PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE options (     id INTEGER PRIMARY KEY AUTOINCREMENT,     question_id TEXT NOT NULL,     option_text TEXT NOT NULL,     is_correct INTEGER NOT NULL CHECK(is_correct IN (0, 1)) DEFAULT 0,     FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE );
CREATE TABLE questions (   id TEXT PRIMARY KEY,   subject TEXT,   category TEXT,   topic TEXT,   level TEXT,   difficulty INTEGER,   question TEXT,   options TEXT,   correct INTEGER,   hint TEXT,   explanation TEXT,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP , topic_id TEXT, subtopic_id TEXT);
CREATE TABLE users (   username TEXT PRIMARY KEY,   security_question TEXT,   security_answer_hash TEXT,   xp INTEGER DEFAULT 0,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP , progress_data TEXT DEFAULT '{}', recovery_key_hash TEXT, password_hash TEXT);
DELETE FROM sqlite_sequence;
