INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0025','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Analyze the statement: ''Zero is both a quantity and a placeholder.'' Is this true?','["Yes, it means ''none'' and holds empty place value columns.","No, it is only a placeholder.","No, it is only a quantity.","No, zero is not a number."]',0,'Think about ''0 apples'' and the number ''10''.','Zero has a dual role in mathematics.','2026-10-30 17:32:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0026','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Critique: ''Bob counted a circle of 12 bananas by starting at one and going around twice, getting a total of 24.''','["Incorrect, each object must be counted exactly once.","Correct, counting twice is safer.","Incorrect, the total should be 0.","Correct, circles are counted twice."]',0,'Don''t count things twice.','One-to-one correspondence means counting each item only once.','2026-10-30 17:32:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0027','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Evaluate the difference between a ''numeral'' and a ''number''.','["A number is the idea of a quantity, a numeral is the written symbol.","They are the exact same thing.","A numeral is always letters.","A number is only used for counting."]',0,'Idea vs. Ink.','Number is the concept; numeral is how we write it.','2026-10-30 17:32:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0028','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Synthesize: If Diana counts 18 pencils from left to right, what will they get if they count from right to left?','["18","17","19","0"]',0,'The total stays the same.','Order irrelevance principle: direction doesn''t change the total.','2026-10-30 17:32:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0029','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Analyze the role of the digits 0-9 in the decimal system.','["They combine to form all possible larger numerals.","They are the only numbers that exist.","They cannot be combined.","They only represent shapes."]',0,'Building blocks of math.','Our base-10 system uses these 10 digits to build all other numbers.','2026-10-30 17:32:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0030','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Evaluate: Why is the number line a useful tool for understanding counting?','["It visually shows the fixed, increasing order and magnitude of numbers.","It shows how to draw numbers.","It makes numbers smaller.","It hides the number zero."]',0,'It puts them in a row.','It maps quantity to physical distance and order.','2026-10-30 17:32:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0031','Maths','Numbers and Number Sense','Subtopic 1: Counting and Number Recognition','Primary',10,'Analyze the statement: ''Zero is both a quantity and a placeholder.'' Is this true?','["Yes, it means ''none'' and holds empty place value columns.","No, it is only a placeholder.","No, it is only a quantity.","No, zero is not a number."]',0,'Think about ''0 apples'' and the number ''10''.','Zero has a dual role in mathematics.','2026-10-30 17:32:23',NULL,NULL);
