INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0057','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',5,'Write the numeral for ''two thousand five hundred''.','["2,500","2050","2,005","25,000"]',0,'Use a comma.','2 in thousands, 5 in hundreds.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0058','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',5,'Which spelling is correct for the number 90?','["Ninety","Ninty","Ninetee","Nine-ty"]',0,'Keep the e.','It keeps the ''e'': ninety.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0059','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',5,'Which spelling is correct for the number 40?','["Forty","Fourty","Fortee","Forte"]',0,'No ''u''.','Drop the ''u'': forty.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0060','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',5,'Convert ''eighty-five'' into digits.','["85","805","58","8005"]',0,'Combine them.','8 tens, 5 ones.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0061','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Analyze the error: Alice wrote ''one thousand and twenty'' as ''120''. What went wrong?','["They forgot the placeholder zero in the hundreds place; it should be 1,020.","They added too many digits.","They forgot a comma.","Nothing is wrong."]',0,'Check the hundreds.','Without the zero, the 1 shifts to the hundreds place.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0062','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Synthesize the conversion of ''twenty-five thousand six hundred'' into a numeral.','["25,600","25,060","2,560","250,600"]',0,'Use the comma separator.','25 in the thousands group, 600 in the units group.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0063','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Evaluate the difference in place value between ''five hundred and four'' (504) and ''fifty-four'' (54).','["504 has a hundreds digit, while 54 is only tens and ones.","They are the exact same value.","54 is larger.","504 has no tens."]',0,'Count the digits.','The word ''hundred'' creates a 3-digit number.','2026-10-30 17:32:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0064','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Critique: ''The number 1,000,000 is read as ten hundred thousand.''','["False, it is read as one million.","True.","False, it is one billion.","False, it is read as ten thousands."]',0,'Think of the commas.','Standard naming conventions call this one million.','2026-10-30 17:32:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0065','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Synthesize: Convert ''four hundred and sixteen'' into standard numeric form.','["416","40016","4016","460"]',0,'Combine carefully.','400 + 16 = 416.','2026-10-30 17:32:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0066','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Analyze the rule for writing large numbers internationally.','["Commas are used to separate groups of three digits (thousands, millions) to make reading easier.","Commas are never used.","Letters are mixed with numbers.","Zeros are hidden."]',0,'Think about 1,000,000.','Grouping by threes.','2026-10-30 17:32:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0067','Maths','Numbers and Number Sense','Subtopic 2: Reading and Writing Numbers','Primary',10,'Analyze the error: George wrote ''one thousand and twenty'' as ''120''. What went wrong?','["They forgot the placeholder zero in the hundreds place; it should be 1,020.","They added too many digits.","They forgot a comma.","Nothing is wrong."]',0,'Check the hundreds.','Without the zero, the 1 shifts to the hundreds place.','2026-10-30 17:32:27',NULL,NULL);
