INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0098','Maths','Numbers and Number Sense','Subtopic 3: Number Names and Number Words','Primary',10,'Synthesize the number name for 12,345.','["Twelve thousand three hundred and forty-five","Twelve three forty-five","One two three four five","Twelve thousand three forty-five"]',0,'Read up to the comma first.','Group by thousands and hundreds.','2026-10-30 17:32:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0099','Maths','Numbers and Number Sense','Subtopic 3: Number Names and Number Words','Primary',10,'Critique the rule for hyphenation in compound numbers.','["Numbers from 21 to 99 (except multiples of 10) require a hyphen.","Hyphens are never used.","Hyphens are used for hundreds.","Hyphens replace ''and''."]',0,'Connect tens and ones.','Twenty-one, ninety-nine, etc., use hyphens.','2026-10-30 17:32:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0100','Maths','Numbers and Number Sense','Subtopic 3: Number Names and Number Words','Primary',10,'Analyze the orthographic difference between 4, 14, and 40.','["Four and fourteen keep the ''u'', forty drops it.","They all keep the ''u''.","They all drop the ''u''.","Fourteen drops it, forty keeps it."]',0,'Watch the u.','Forty is spelled without a u.','2026-10-30 17:32:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0101','Maths','Numbers and Number Sense','Subtopic 3: Number Names and Number Words','Primary',10,'Synthesize the number name for 100,000.','["One hundred thousand","Ten ten thousands","A million","One hundred thousands"]',0,'Read the group before the comma.','Read the 100 before the thousands group.','2026-10-30 17:32:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0102','Maths','Numbers and Number Sense','Subtopic 3: Number Names and Number Words','Primary',10,'Evaluate: Why do 11 and 12 not follow the ''-teen'' naming pattern?','["They come from old English roots for ''one left over'' and ''two left over'' after ten.","They are mistakes.","They are prime numbers.","They are fractions."]',0,'Old words.','Historical linguistic quirks shape these names.','2026-10-30 17:32:30',NULL,NULL);
