INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0133','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Critique: ''Alice says 305 and 35 are identical because zero has no value.''','["False, zero is a crucial placeholder that shifts the 3 to the hundreds place.","True, zero means nothing.","False, 35 is larger.","True for addition."]',0,'It pushes the 3 over.','Zero holds the tens column open.','2026-10-30 17:32:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0134','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Analyze: How does the base-ten system relate adjacent place values?','["Each place to the left is 10 times greater than the place to its right.","Each place is 1 greater.","They are unrelated.","They decrease by 10."]',0,'x10 per step.','Moving left multiplies the value by 10.','2026-10-30 17:32:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0135','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Evaluate the place value shift: If a digit is moved two columns to the left, what happens to its value?','["It is multiplied by 100.","It is multiplied by 20.","It increases by 2.","It stays the same."]',0,'Two jumps of x10.','10 x 10 = 100.','2026-10-30 17:32:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0136','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Synthesize the total value: 4 thousands, 0 hundreds, 7 tens, 2 ones.','["4,072","4,720","4,270","472"]',0,'Don''t skip the hundreds.','Combine them, keeping 0 as a placeholder.','2026-10-30 17:32:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0137','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Analyze: Why is the ''face value'' concept necessary alongside ''place value''?','["Face value identifies the digit itself (1-9), while place value gives it magnitude based on position.","They mean the same thing.","Face value is only for decimals.","Place value is a mistake."]',0,'Symbol vs Location.','You need the symbol AND its location to know the amount.','2026-10-30 17:32:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0138','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Synthesize: What happens to the place value of a number''s digits when you multiply the entire number by 10?','["All digits shift one place to the left.","The digits change face value.","Nothing happens.","They shift right."]',0,'Shift left.','Multiplying by 10 shifts everything to a higher column.','2026-10-30 17:32:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0139','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Critique: ''George says 305 and 35 are identical because zero has no value.''','["False, zero is a crucial placeholder that shifts the 3 to the hundreds place.","True, zero means nothing.","False, 35 is larger.","True for addition."]',0,'It pushes the 3 over.','Zero holds the tens column open.','2026-10-30 17:32:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0140','Maths','Numbers and Number Sense','Subtopic 4: Place Value and Face Value','Primary',10,'Analyze: How does the base-ten system relate adjacent place values?','["Each place to the left is 10 times greater than the place to its right.","Each place is 1 greater.","They are unrelated.","They decrease by 10."]',0,'x10 per step.','Moving left multiplies the value by 10.','2026-10-30 17:32:34',NULL,NULL);
