INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0169','Maths','Numbers and Number Sense','Subtopic 5: Expanded and Standard Forms','Primary',10,'Evaluate the multiplicative expanded form of 3,517.','["(3 x 1,000) + (5 x 100) + (1 x 10) + (7 x 1)","(3 x 100) + (5 x 10) + (1 x 1) + 7","(3 x 1,000) + (5 x 10) + (17 x 1)","3000 x 500 x 10 x 7"]',0,'Digit x Column value.','Shows each digit multiplied by its place value.','2026-10-30 17:32:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0170','Maths','Numbers and Number Sense','Subtopic 5: Expanded and Standard Forms','Primary',10,'Critique the mistake: ''Bob wrote 604 as 600 + 40 + 4''.','["They added a tens value (40) that doesn''t exist; it should be 600 + 4.","It is perfectly correct.","It should be 60 + 4.","It should be 604 + 0."]',0,'Look at the middle digit.','604 has a zero in the tens place.','2026-10-30 17:32:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0171','Maths','Numbers and Number Sense','Subtopic 5: Expanded and Standard Forms','Primary',10,'Synthesize the multiplicative expanded form of 40,250.','["(4 x 10,000) + (2 x 100) + (5 x 10)","(4 x 1,000) + (2 x 10) + (5 x 1)","(4 x 10,000) + (2 x 1,000) + (5 x 10)","(4 x 100,000) + (2 x 100) + (5 x 1)"]',0,'Find the non-zero digits.','Omit zeros, multiply non-zeros by their place.','2026-10-30 17:32:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0172','Maths','Numbers and Number Sense','Subtopic 5: Expanded and Standard Forms','Primary',10,'Analyze why a zero digit is usually omitted in expanded addition form.','["Adding zero to any sum does not change the total value.","Because zero is negative.","Because zero destroys digits.","It represents infinity."]',0,'0 + x = x.','0 contributes nothing to the sum.','2026-10-30 17:32:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0173','Maths','Numbers and Number Sense','Subtopic 5: Expanded and Standard Forms','Primary',10,'Evaluate: Reconstruct the standard form from (8 x 1000) + (3 x 10).','["8,030","8,300","830","8,003"]',0,'Fill the gaps with zeros.','No hundreds, no ones. Put zeros there.','2026-10-30 17:32:39',NULL,NULL);
