INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0205','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Analyze why 1,205 is greater than 999 without comparing individual digits.','["For positive whole numbers, a number with more digits is always greater.","Because 1 > 9.","Because it has a zero.","Because 5 > 9."]',0,'Count the digits.','4 digits vs 3 digits.','2026-10-30 17:32:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0206','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Evaluate the comparison of 4,732 and 4,729.','["4,732 > 4,729 because the tens digit 3 > 2.","4,732 < 4,729","Equal","4,732 > 4,729 because 4 > 2."]',0,'Check the tens.','Compare left to right. Tens place breaks the tie.','2026-10-30 17:32:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0207','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Critique: ''A number with more digits is always greater than a number with fewer digits.''','["True for positive whole numbers, false for negative integers or decimals.","False in all cases.","True for negatives too.","Only true for odds."]',0,'What about -5000 vs -9?','Negative numbers flip the rule.','2026-10-30 17:32:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0208','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Synthesize the descending order for: 3,042; 3,402; 3,240; 3,024.','["3,402; 3,240; 3,042; 3,024","3,024; 3,042; 3,240; 3,402","3,402; 3,042; 3,240; 3,024","3,240; 3,402; 3,042; 3,024"]',0,'Check hundreds carefully.','Compare hundreds then tens.','2026-10-30 17:32:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0209','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Evaluate: How does placing a zero at the end of a whole number affect its relative value in comparisons?','["It multiplies its value by 10, making it vastly larger.","It does nothing.","It makes it smaller.","It turns it into a decimal."]',0,'x10.','Shifts all place values.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0210','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Analyze: Compare 9,999 and 10,000 using place value logic.','["10,000 > 9,999 because it extends into the ten-thousands place.","9,999 is larger because 9 > 1.","They are equal.","Cannot compare."]',0,'Digit count.','More digits = larger positive value.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0211','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Analyze why 1,205 is greater than 999 without comparing individual digits.','["For positive whole numbers, a number with more digits is always greater.","Because 1 > 9.","Because it has a zero.","Because 5 > 9."]',0,'Count the digits.','4 digits vs 3 digits.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0212','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Evaluate the comparison of 4,732 and 4,729.','["4,732 > 4,729 because the tens digit 3 > 2.","4,732 < 4,729","Equal","4,732 > 4,729 because 4 > 2."]',0,'Check the tens.','Compare left to right. Tens place breaks the tie.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0213','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Critique: ''A number with more digits is always greater than a number with fewer digits.''','["True for positive whole numbers, false for negative integers or decimals.","False in all cases.","True for negatives too.","Only true for odds."]',0,'What about -5000 vs -9?','Negative numbers flip the rule.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0214','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Synthesize the descending order for: 3,042; 3,402; 3,240; 3,024.','["3,402; 3,240; 3,042; 3,024","3,024; 3,042; 3,240; 3,402","3,402; 3,042; 3,240; 3,024","3,240; 3,402; 3,042; 3,024"]',0,'Check hundreds carefully.','Compare hundreds then tens.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0215','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Evaluate: How does placing a zero at the end of a whole number affect its relative value in comparisons?','["It multiplies its value by 10, making it vastly larger.","It does nothing.","It makes it smaller.","It turns it into a decimal."]',0,'x10.','Shifts all place values.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0216','Maths','Numbers and Number Sense','Subtopic 6: Comparing and Ordering Numbers','Primary',10,'Analyze: Compare 9,999 and 10,000 using place value logic.','["10,000 > 9,999 because it extends into the ten-thousands place.","9,999 is larger because 9 > 1.","They are equal.","Cannot compare."]',0,'Digit count.','More digits = larger positive value.','2026-10-30 17:32:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0217','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',1,'What is an ''even'' number?','["A whole number that can be divided by 2 exactly, with no remainder.","A number that cannot be divided by 2.","A number that ends in 1, 3, or 5.","A number with letters."]',0,'Split into equal teams.','Even numbers can be paired up perfectly.','2026-10-30 17:32:43',NULL,NULL);
