INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0230','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',5,'What is the quick method to tell if 1,234,567 is odd or even?','["Look at the last digit; if it''s 1,3,5,7,9, it is odd.","Divide by 2.","Add the digits.","Guess."]',0,'Last digit secret.','The last digit decides.','2026-10-30 17:32:45',NULL,NULL);
