INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0241','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Critique: ''Zero is an odd number because it represents nothing.''','["False. Zero is an even number because 0 / 2 = 0 with no remainder.","True.","Zero is neither.","Zero is a fraction."]',0,'0 / 2 = 0.','Zero fits the even definition and sequence perfectly.','2026-10-30 17:32:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0242','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Synthesize the rule for subtracting an Odd number from an Even number.','["Always Odd.","Always Even.","Always Zero.","Changes."]',0,'Try 4 - 1.','Even - Odd = Odd.','2026-10-30 17:32:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0243','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Evaluate the product of multiplying an odd number by an odd number.','["Always odd","Always even","Always zero","Multiple of 10"]',0,'Try 3 x 3.','Odd x Odd = Odd.','2026-10-30 17:32:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0244','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Analyze why any integer multiplied by an even number yields an even product.','["An even number has a factor of 2, guaranteeing the product is divisible by 2.","Even numbers are larger.","Cancels out odds.","Product becomes zero."]',0,'x2 makes it even.','Factor of 2 is preserved.','2026-10-30 17:32:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0245','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Synthesize: If x is odd and y is even, what is x * y + y?','["Even","Odd","Zero","Prime"]',0,'Work step by step.','Odd*Even = Even. Even+Even = Even.','2026-10-30 17:32:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0246','Maths','Numbers and Number Sense','Subtopic 7: Odd and Even Numbers','Primary',10,'Evaluate: Why do even and odd numbers alternate on the number line?','["Because adding 1 to an even number creates a remainder of 1 (odd), and adding 1 to that pairs up the remainder (even).","Coincidence.","Because 0 is odd.","They don''t alternate."]',0,'+1 changes the parity.','Adding 1 shifts the pairing status.','2026-10-30 17:32:46',NULL,NULL);
