INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0323','Maths','Numbers and Number Sense','Subtopic 9: Rounding and Estimating Numbers','Primary',10,'Synthesize: Kevin estimates 44 + 44 by rounding to the nearest 10. What is the estimate vs actual?','["Estimate: 80, Actual: 88. Significant underestimation.","Estimate: 90, Actual 88.","Estimate 100, Actual 88.","Both are 88."]',0,'Round down twice.','40+40=80. Double rounding down creates a gap.','2026-10-30 17:32:54',NULL,NULL);
