INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0349','Maths','Numbers and Number Sense','Subtopic 10: Roman Numerals','Primary',10,'Analyze the ''Subtractive Rule'' using ''IX''.','["Smaller symbol before larger means subtract (10 - 1 = 9).","1 plus 10.","10 times 1.","Means 11."]',0,'Smaller letter in front.','Subtract when smaller comes before larger.','2026-10-30 17:32:57',NULL,NULL);
