INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0351','Maths','Numbers and Number Sense','Subtopic 10: Roman Numerals','Primary',10,'Evaluate why traditional Roman numerals do not include a symbol for zero.','["Purely additive/subtractive tally system for physical counts, not positional place-value requiring a placeholder.","Didn''t know how to count.","Unlucky.","Used ''O''."]',0,'Can''t have a physical stack of zero objects.','Developed as a tally system.','2026-10-30 17:32:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0352','Maths','Numbers and Number Sense','Subtopic 10: Roman Numerals','Primary',10,'Analyze structural rules regarding which symbols can be repeated.','["I, X, C, M repeat up to 3 times; V, L, D never repeat.","V,L,D repeat 5 times.","All repeat infinitely.","None repeat."]',0,'Check the base 5s.','1, 10, 100 repeat. 5, 50, 500 do not.','2026-10-30 17:32:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0353','Maths','Numbers and Number Sense','Subtopic 10: Roman Numerals','Primary',10,'Synthesize: Convert CDXLIV to a number.','["444","666","464","544"]',0,'Break into chunks.','(500-100) + (50-10) + (5-1) = 444.','2026-10-30 17:32:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t1_global_0354','Maths','Numbers and Number Sense','Subtopic 10: Roman Numerals','Primary',10,'Critique: ''Fiona wrote 99 as IC (100 - 1).''','["False, you cannot subtract I from C; you must convert by place value: XC (90) + IX (9) = XCIX.","True.","False, it is LXXXXIX.","False, it is C-I."]',0,'Convert place by place.','Subtractive rule has strict limits (I only subtracts from V and X).','2026-10-30 17:32:57',NULL,NULL);
