INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0017','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'What happens when you add zero to 41?','["It stays 41 (Identity property).","It becomes zero.","It doubles.","It loses 1."]',0,'Zero adds nothing.','Adding zero leaves a number unchanged.','2026-10-30 17:33:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0018','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'Estimate 177 + 72 to the nearest ten.','["250","240","260","260"]',0,'Round first.','Round 177 up and 72 down.','2026-10-30 17:33:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0019','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'Calculate 18 + 15.','["33","32","34","28"]',0,'Bridge the ten.','Add the parts.','2026-10-30 17:33:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0020','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'What is 19 + 19?','["38","37","39","30"]',0,'Add to itself.','Double it.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0021','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'If you have 120 leaves and find 50 more, how many?','["170","160","180","100"]',0,'Look at the tens place.','Add the tens.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0022','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'Calculate 39 + 7.','["46","45","47","41"]',0,'Bridge 10.','Make a ten.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0023','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'Which shows the Associative property?','["(14+2)+3 = 14+(2+3)","14+2 = 2+14","14+0 = 14","14x1 = 14"]',0,'Brackets.','Grouping.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0024','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',5,'Estimate 162 + 98 to nearest ten.','["260","270","250","180"]',0,'Round.','Round 12 down, 18 up.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0025','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Calculate 368 + 257 using column addition with regrouping.','["625","525","635","615"]',0,'Don''t forget the carried digits.','Regroup ones to tens, and tens to hundreds.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0026','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Critique: ''Bob added 45 + 32 by adding 4+3=7 and 5+2=7 to get 77, but when adding 48 + 35 they got 713.''','["They forgot to regroup (carry) the 10 from 8+5=13 into the tens column; it should be 83.","They subtracted.","They did it correctly.","They rounded instead."]',0,'Watch out for double-digit column sums.','When a column totals 10 or more, you must regroup.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0027','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Synthesize the Associative Property for addition using (568 + 457) + 30.','["It equals 568 + (457 + 30).","It equals {a} x {b}.","It means you can only add two numbers.","It means order matters."]',0,'Move the brackets.','Changing the grouping (brackets) does not change the sum.','2026-10-30 17:33:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0028','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Evaluate: Why is estimating sums (e.g., rounding 668 and 557 before adding) a critical mathematical skill?','["It provides a quick, approximate check to see if an exact, complex calculation is reasonable or if a major error occurred.","It replaces exact math permanently.","It makes the numbers negative.","It proves the commutative property."]',0,'Sanity check.','Estimation catches major errors.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0029','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Analyze: If adding three 3-digit numbers, what is the maximum possible value that could be carried over into the next column?','["2","1","3","9"]',0,'Think of 9+9+9.','Max digits are 9+9+9 = 27. The 2 is carried.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0030','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Synthesize a missing addend: 368 + [?] = 850','["482","357","125","725"]',0,'Work backwards.','Subtract {a} from the total.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0031','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Calculate the sum of 1092 and 345.','["1437","1337","1537","1447"]',0,'Column addition.','Regroup carefully.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0032','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Critique: ''Hannah says that addition is always commutative, even for words.''','["True for numbers, but false for words/events (putting on socks then shoes is not the same as shoes then socks).","True for everything.","False, addition is never commutative.","True only for even numbers."]',0,'Real life vs Math.','Math properties apply to numbers, not necessarily actions.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0033','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Evaluate: Is (a + b) + c always equal to a + (b + c) for all whole numbers?','["Yes, this is the associative property.","No.","Only if they are even.","Only if c is zero."]',0,'Associative law.','Grouping doesn''t change the sum.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0034','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Analyze: What happens to the sum if both addends are odd numbers?','["The sum is always even.","The sum is always odd.","The sum is always zero.","Cannot be determined."]',0,'Think of 3 + 5.','Odd + Odd = Even.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0035','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Synthesize: Find the sum of the first four multiples of 2.','["20","16","24","12"]',0,'List them then add.','2 + 4 + 6 + 8.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0036','Maths','Basic Arithmetic Operations','Subtopic 1: Addition of whole numbers','Primary',10,'Evaluate the use of compensation: To add 99 + 47, what is the fastest mental strategy?','["Add 100 to 47, then subtract 1.","Use column addition.","Count on your fingers.","Multiply."]',0,'Adjust by 1.','Make 99 a 100, then adjust.','2026-10-30 17:33:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0037','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'If Alice has 8 apples and gives away 2, what operation finds how many remain?','["Subtraction (-)","Addition (+)","Multiplication (x)","Division (÷)"]',0,'Taking away means minus.','Taking away or finding the difference is subtraction.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0038','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'What is the specific mathematical name for the answer you get in a subtraction problem?','["Difference","Sum","Product","Quotient"]',0,'Check your vocabulary words.','The result of subtraction is the difference.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0039','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'Calculate this mentally: 13 - 6.','["7","8","6","16"]',0,'Count backwards.','13 minus 6 is 7.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0040','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'What does the minus sign (-) mean in a math sentence?','["Take away or find the difference between numbers.","Add the numbers together.","Both sides are completely equal.","Make groups of."]',0,'Look closely at the symbol.','Minus means to subtract.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0041','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'If you start at 14 on a number line and move left 9 steps, where do you end up?','["5","13","4","10"]',0,'Jump backwards on the line.','Moving left on a number line is subtraction.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0042','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'In the equation 9 - 3 = 6, what is the starting number (9) called?','["Minuend","Subtrahend","Difference","Addend"]',0,'Vocabulary word.','The starting number you subtract from is the minuend.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0043','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'Calculate: 7 - 2.','["5","6","4","0"]',0,'Difference.','Take away n.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0044','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'If Hannah has 10 shells and eats 4, how many are left?','["6","5","7","8"]',0,'Take away.','Subtract the eaten ones.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0045','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'What is 14 - 0?','["14","0","13","15"]',0,'Take away nothing.','Subtracting zero leaves it unchanged.','2026-10-30 17:33:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0046','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'Which equation shows subtraction?','["10 - 4 = 6","10 + 4 = 14","10 x 4 = 40","10 = 10"]',0,'-','Look for the minus sign.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0047','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',1,'Calculate 9 - 9.','["0","1","9","18"]',0,'Take it all away.','Taking a number away from itself leaves zero.','2026-10-30 17:33:13',NULL,NULL);
