INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0050','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Subtract using columns: 48 - 33. (No regrouping needed).','["15","25","13","81"]',0,'Line up the digits correctly.','Subtract ones, then tens.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0051','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Calculate this step-by-step: 24 - 5 - 3.','["16","19","21","19"]',0,'Do it one piece at a time.','Subtract from left to right one at a time.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0052','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Is subtraction commutative? Does 15 - 10 equal 10 - 15?','["No, the order matters in subtraction.","Yes, they are equal.","Only for even numbers.","Only if they are positive."]',0,'Try it with 5 - 2.','Changing the order changes the answer completely.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0053','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'How can you check the answer to 16 - 11 = 5?','["Add 5 and 11 to see if it equals 16.","Subtract them again.","Multiply them.","Add 16 and 11."]',0,'Work backwards.','Use inverse operations (addition) to check subtraction.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0054','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Estimate 178 - 71 to the nearest ten.','["110","100","100","170"]',0,'Round first.','Round up the first, round down the second.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0055','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Calculate 78 - 23.','["55","45","65","50"]',0,'Column subtraction.','Subtract ones, then tens.','2026-10-30 17:33:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0056','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Find the difference: 100 - 35.','["65","75","55","0"]',0,'Mental math.','Count up from the subtrahend.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0057','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Evaluate: 65 - 16.','["49","59","51","39"]',0,'Watch the ones.','Subtract.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0058','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Estimate 83 - 91 to the nearest ten.','["-10","0","-20","0"]',0,'80 - 40.','Round both to tens.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0059','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Solve: 40 - 8 - 7.','["25","20","30","15"]',0,'Subtract 8, then 7.','Left to right.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0060','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',5,'Liam has 62 cookies and sells 17. How many are left?','["45","55","35","40"]',0,'42 - 17.','Regrouping needed.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0061','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Calculate 402 - 175 using column subtraction with regrouping (borrowing).','["227","237","127","327"]',0,'Borrow from the next column.','You must regroup across the zeros/smaller digits.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0062','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Analyze the specific process of ''subtracting across zeros'' for 500 - 268.','["You must regroup 1 hundred into 10 tens, and then 1 ten into 10 ones, leaving 4 hundreds, 9 tens, and 10 ones.","You just subtract the bottom numbers from 10 directly.","You ignore the zeros completely.","You add the numbers instead."]',0,'Chain of borrowing.','Regrouping changes how the number is represented to make subtraction possible.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0063','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Critique: ''Charlie calculated 13 - 18 and got a negative number, but said subtraction is associative so they can just swap the numbers to make it positive.''','["False, subtraction is neither commutative nor associative; order strictly matters.","True, you can swap them to make it easier.","False, subtraction is commutative but not associative.","True for whole numbers only."]',0,'Order matters!','You cannot arbitrarily change the order of numbers or brackets in subtraction.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0064','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Synthesize a missing subtrahend equation: 850 - [?] = 523.','["327","573","227","337"]',0,'Subtract the difference from the total.','If a - x = b, then x = a - b.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0065','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Evaluate: Why does regrouping (borrowing) not alter the actual overall value of the top number?','["Because you are simply exchanging place-value units (e.g., 1 ten for 10 ones) within the same total amount.","It actually does change the value.","Because it creates negative numbers temporarily.","Because zero has no value."]',0,'Breaking a 10-dollar bill into ten 1-dollar bills.','1 ten is exactly the same value as 10 ones. The total is just packaged differently.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0066','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Analyze a multi-step problem: Start with 600. Subtract 60. Then subtract 6. What exactly remains?','["534","540","594","660"]',0,'Step by step.','Work sequentially from left to right.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0067','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Critique: ''When checking 42 - 17 = 25, George did 42 + 25.''','["Wrong operation, should be 25 + 17 = 42.","Correct.","Should be 42 x 25.","Should be 17 - 25."]',0,'Add the difference to the subtrahend.','Check subtraction by adding the parts.','2026-10-30 17:33:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0068','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Evaluate: 700 - 456.','["244","344","254","356"]',0,'Borrow from 7.','Regroup across zeros.','2026-10-30 17:33:15',NULL,NULL);
