INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0070','Maths','Basic Arithmetic Operations','Subtopic 2: Subtraction of whole numbers','Primary',10,'Analyze: What is the effect on the difference if you add 10 to both the minuend and the subtrahend?','["The difference stays exactly the same.","The difference increases by 10.","The difference increases by 20.","The difference is 0."]',0,'Constant difference.','(A+10) - (B+10) = A - B.','2026-10-30 17:33:15',NULL,NULL);
