INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0125','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'If you have 57 crayons and group them by 10, how many complete groups and what is the remainder?','["5 groups, Remainder 7","5 groups, Remainder 0","7 groups, Remainder 5","6 groups, Remainder 7"]',0,'Tens and ones.','Divide by 10.','2026-10-30 17:33:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0126','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'What must ALWAYS be true about a remainder in a division problem?','["It must be strictly smaller than the divisor.","It can be larger than the divisor.","It must be zero.","It must be an even number."]',0,'Can you make another group?','If the remainder is equal or larger, you could make another full group.','2026-10-30 17:33:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0127','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Calculate 84 ÷ 4 using long/short division.','["21","22","12","42"]',0,'Column by column.','8/4=2, 4/4=1.','2026-10-30 17:33:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0128','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Calculate 156 ÷ 3.','["52","51","62","42"]',0,'Combine digits.','15/3=5, 6/3=2.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0129','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Calculate 157 ÷ 3.','["52 R 1","52 R 2","51 R 4","50 R 7"]',0,'Look at previous.','156 is exact, 1 is left.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0130','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Estimate 198 ÷ 5.','["40","30","50","10"]',0,'Round first.','Round to 200.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0131','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Calculate 96 ÷ 8.','["12","11","13","14"]',0,'Times tables.','8x12=96.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0132','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',5,'Calculate 14 ÷ 4.','["3 R 2","3 R 1","4 R 2","2 R 3"]',0,'Times tables.','4x3=12, leaves 2.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0133','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Analyze: How can multiplication help you check the answer to 28 ÷ 5 = 5 R 3?','["Multiply 5 x 5, then add 3. It should equal 28.","Multiply 5 x 3.","Multiply 28 x 5.","Add all numbers."]',0,'Work backwards.','Divisor x Quotient + Remainder = Dividend.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0134','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Critique: ''Bob calculated 45 ÷ 6 = 6 R 9.''','["False, the remainder (9) is larger than the divisor (6), meaning another group of 6 can be made. The true answer is 7 R 3.","True, the math works.","False, it should be 8.","False, there are no remainders."]',0,'Check the size of the remainder.','The remainder MUST be smaller than the divisor.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0135','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Evaluate: Why is division by zero mathematically undefined?','["Because there is no number you can multiply by 0 to get a non-zero dividend.","Because 0 is too small to see.","Because it equals infinity.","Because it equals 0."]',0,'Try checking it with multiplication.','If x ÷ 0 = y, then y * 0 must equal x. But y * 0 is always 0.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0136','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Synthesize the solution to: Diana shares 31 items equally among 4 boxes. The question asks ''How many boxes are FULL?''','["7 boxes","8 boxes","4 boxes","3 boxes"]',0,'Read what the question asks carefully.','The quotient answers ''full'' groups. The remainder is discarded.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0137','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Synthesize the solution to: Ethan has 35 items. They can fit 4 per box. The question asks ''How many boxes are NEEDED to hold ALL items?''','["9 boxes","8 boxes","4 boxes","3 boxes"]',0,'Can you leave items behind?','The remainder means you need one extra box to hold the leftovers.','2026-10-30 17:33:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0138','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Analyze the relationship between division and fractions.','["A fraction is literally a division problem (e.g., 3/4 means 3 divided by 4).","They are entirely unrelated.","Fractions are only addition.","Division cannot use fractions."]',0,'Look at the symbol.','The fraction bar means ''divided by''.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0139','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Evaluate: 700 ÷ 4.','["175","150","200","125"]',0,'7/4=1(R3), 30/4=7(R2), 20/4=5.','Long division.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0140','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Synthesize: Check 23 ÷ 5 = 4 R 3.','["5 x 4 + 3 = 23","5 x 4 = 20","23 - 3 = 20","5 + 4 + 3 = 12"]',0,'Formula.','Divisor x quotient + remainder.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0141','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Critique: ''Ian says that 8 ÷ 0 = 0.''','["False, it is undefined.","True.","False, it is 8.","False, it is infinity."]',0,'Undefined.','Cannot divide by zero.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0142','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Analyze: What is the largest possible remainder when dividing by 7?','["6","7","8","0"]',0,'One less.','Remainder must be less than divisor.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0143','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Evaluate: 144 ÷ 12.','["12","14","10","11"]',0,'Times tables.','12 x 12 = 144.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0144','Maths','Basic Arithmetic Operations','Subtopic 4: Division and sharing equally','Primary',10,'Synthesize: A bakery has 50 rolls, packs 6 per bag. How many bags, how many left?','["8 bags, 2 left","7 bags, 8 left","8 bags, 0 left","9 bags"]',0,'Divide.','50 / 6 = 8 R 2.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0145','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'When doing column addition for 25 + 12, which column MUST you add first?','["The ones column (far right).","The tens column.","The hundreds column.","The far left."]',0,'Start small.','Always start from the right (ones place).','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0146','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Calculate 35 + 22 using columns.','["57","67","47","58"]',0,'Line them up.','Add ones, then tens.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0147','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'When doing column subtraction for 45 - 32, which column MUST you subtract first?','["The ones column (far right).","The tens column.","The hundreds column.","The far left."]',0,'Start small.','Always start from the right.','2026-10-30 17:33:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0148','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Calculate 55 - 42 using columns.','["13","23","3","14"]',0,'Line them up.','Subtract ones, then tens.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0149','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Estimate 65 + 12 by rounding to the nearest ten.','["70","80","77","100"]',0,'Round first.','Round both, then add.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0150','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Estimate 25 - 22 by rounding to the nearest ten.','["0","10","3","0"]',0,'Round first.','Round both, then subtract.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0151','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'What does ''line up the digits'' mean?','["Put ones under ones, tens under tens.","Put them in a straight horizontal line.","Draw a line under them.","Make them all zeros."]',0,'Vertical alignment.','Place value alignment.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0152','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Calculate 23 + 14.','["37","27","47","34"]',0,'No carrying.','3+4=7, 2+1=3.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0153','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Calculate 58 - 23.','["35","25","45","30"]',0,'No borrowing.','8-3=5, 5-2=3.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0154','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'If you add 12 + 8 + 15, what is the answer?','["35","30","40","25"]',0,'Step by step.','12+8=20, 20+15=35.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0155','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'What is the sum of 6 + 17 + 4?','["27","21","25","30"]',0,'Make 10 first.','6+4=10, 10+17=27.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0156','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',1,'Calculate 30 - 8 - 7.','["15","14","22","10"]',0,'Left to right.','30-8=22, 22-7=15.','2026-10-30 17:33:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0157','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 368 + 257. Remember to regroup (carry) carefully.','["625","525","635","615"]',0,'Don''t forget carried numbers.','8+7=15, carry 1. 6+5+1=12, carry 1...','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0158','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 468 - 357. Remember to regroup (borrow) carefully.','["111","121","11","211"]',0,'Borrow from the left.','Borrow from the tens if the ones digit is too small.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0159','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Why do we ''carry'' a 1 when 8 + 7 = 15 in the ones column?','["Because 15 ones is equal to 1 ten and 5 ones, so the 1 ten moves to the tens column.","Because 1 is smaller.","It''s a magic trick.","To make the number bigger."]',0,'10 ones = 1 ten.','We are regrouping place values.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0160','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate the sum of three numbers: 668 + 557 + 125.','["1350","1225","1250","1450"]',0,'Add the column.','Line up all three and add carefully.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0161','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Estimate 768 + 257 to the nearest hundred.','["1100","1025","1200","1000"]',0,'Look at tens to round.','Round to hundreds first.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0162','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Check the calculation 368 - 357 = 11 using the inverse operation.','["Add 11 and 357; it equals 368.","Subtract them again.","Multiply 11 by 357.","Add all three."]',0,'Work backwards.','Subtraction is checked by addition.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0163','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 28 + 17.','["45","35","55","41"]',0,'Carry the 1.','8+7=15, carry 1. 2+1+1=4.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0164','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 42 - 17.','["25","35","15","20"]',0,'Borrow.','Borrow 10. 12-7=5. 3-1=2.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0165','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 503 - 268.','["235","335","245","345"]',0,'Watch the zero.','Borrow across zero.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0166','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Calculate 700 - 456.','["244","344","254","356"]',0,'Borrow chain.','Borrow across zeros.','2026-10-30 17:33:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0167','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Check 52 - 28 = 24.','["24 + 28 = 52","52 + 28 = 80","28 - 24 = 4","24 x 2 = 48"]',0,'Inverse.','Add difference to subtrahend.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0168','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',5,'Estimate 83 - 41 to nearest ten.','["40","50","30","42"]',0,'Round.','80 - 40 = 40.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0169','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Analyze the process of subtracting across zeros: 1,000 - 456.','["Regroup 1 thousand into 10 hundreds, then 1 hundred into 10 tens, then 1 ten into 10 ones, leaving 9 hundreds, 9 tens, 10 ones.","Just subtract from 10 directly.","Bring down the zero.","Add them instead."]',0,'Borrow all the way from the thousands.','It creates a chain of regrouping.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0170','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Critique: ''Bob subtracted 327 from 514. In the ones column, they calculated 7 - 4 = 3 instead of regrouping.''','["False, you must always subtract the bottom number from the top number; regrouping was required.","True, you subtract the smaller from the larger.","True, it''s faster.","False, they should add."]',0,'Top minus bottom, always.','You cannot flip the numbers to make it easier.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0171','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Synthesize the calculation: 5,432 + 8,765.','["14,197","13,197","14,187","13,097"]',0,'Column by column.','Carefully carry the thousands.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0172','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Evaluate: Why is it critical to strictly align digits by place value (right-justified) before adding or subtracting?','["To ensure you are combining units of the exact same magnitude (ones with ones, tens with tens).","To make it look neat.","It doesn''t matter.","To save paper."]',0,'Like with like.','You can''t add apples to oranges, and you can''t add tens to ones.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0173','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Synthesize a missing digits problem: 4_2 + _3_ = 800. What are the missing digits?','["472 + 328 (or similar combinations depending on exact setup, e.g. 7, 3, 8).","1, 2, 3","0, 0, 0","9, 9, 9"]',0,'Think about carrying.','Work column by column to find what makes 10.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0174','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Analyze the effect of magnitude when estimating 9,876 - 1,234.','["Rounding to the nearest thousand gives 10,000 - 1,000 = 9,000, a fast and highly effective check.","Estimation doesn''t work here.","Must round to ones.","Must multiply."]',0,'Fast check.','Rounding to the highest place value gives the fastest sanity check.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0175','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Critique: ''George checked 75 - 28 = 57 by doing 57 + 28 = 85. They said it''s correct.''','["False, 85 is not the original 75. The subtraction is wrong.","True, addition checks subtraction.","False, should multiply.","True, 85 is close."]',0,'Does it match?','The check must equal the minuend.','2026-10-30 17:33:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0176','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Evaluate: 450 - 327.','["123","133","223","113"]',0,'Word problem example.','Regroup.','2026-10-30 17:33:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0177','Maths','Basic Arithmetic Operations','Subtopic 5: Long addition and subtraction','Primary',10,'Analyze: What happens if you forget to reduce the digit you borrowed from?','["Your answer will be 10, 100, or 1000 too large.","Nothing.","Answer is too small.","Answer is negative."]',0,'Don''t forget to cross it out.','Borrowing removes value from that column.','2026-10-30 17:33:26',NULL,NULL);
