INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0205','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Analyze the process of 2-digit by 2-digit multiplication (e.g., 24 x 12). Why must you add a placeholder zero on the second line?','["Because you are multiplying by the tens digit, so the product must be shifted one place value to the left.","Because zeros look neat.","Because the number is even.","It is just a rule."]',0,'Place value shift.','Multiplying by a ten means the answer is in tens, not ones.','2026-10-30 17:33:29',NULL,NULL);
