INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0207','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Evaluate the Distributive Property area model for 26 x 14.','["(30 x 10) + (30 x 4) + (6 x 10) + (6 x 4) = 364.","Just multiply the tens and add the ones.","It doesn''t work.","Only works for squares."]',0,'The box method.','Break both numbers into tens and ones, making 4 smaller multiplication problems.','2026-10-30 17:33:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0208','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Critique: ''Diana calculated 23 x 14 by doing 20x10=200 and 3x4=12, total 212.''','["False, they missed the cross-multiplications (20x4 and 3x10). The true answer is 322.","True, that is the fast way.","False, they should subtract.","False, the answer is 214."]',0,'FOIL or box method.','You must multiply every part by every other part.','2026-10-30 17:33:29',NULL,NULL);
