INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0210','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Analyze: What happens if you forget to add the carried digits during multi-digit multiplication?','["The final product will be significantly underestimated because higher place values were ignored.","Nothing.","It will be overestimated.","It turns into division."]',0,'Don''t drop the carries.','Carried digits represent larger place values (tens/hundreds).','2026-10-30 17:33:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0211','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Evaluate: Why does multiplying by 10 shift the digits left?','["Because each place value is a power of 10 in the decimal system.","It doesn''t.","Because 10 is an even number.","Because of the associative property."]',0,'Powers of 10.','Base-10 system.','2026-10-30 17:33:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0212','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Synthesize: Calculate 36 x 12.','["432","422","442","332"]',0,'Split 12.','36x10=360, 36x2=72. 360+72=432.','2026-10-30 17:33:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0213','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Critique: ''Ian says multiplying by 0 leaves the number unchanged.''','["False, multiplying by 0 gives 0. Multiplying by 1 leaves it unchanged.","True.","False, it gives 1.","False, it gives infinity."]',0,'Zero property.','Identity vs Zero property.','2026-10-30 17:33:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0214','Maths','Basic Arithmetic Operations','Subtopic 6: Multiplication of multi-digit numbers','Primary',10,'Analyze: What is the distributive property of multiplication over addition?','["a x (b + c) = (a x b) + (a x c)","a + (b x c) = (a + b) x c","a x b = b x a","(a x b) x c = a x (b x c)"]',0,'Distribute the factor.','Splitting the multiplication.','2026-10-30 17:33:29',NULL,NULL);
