INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0239','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',5,'Split the dividend to calculate 96 ÷ 4.','["(80/4) + (16/4) = 20 + 4 = 24","90/4 + 6/4","96/2 / 2","96 - 4"]',0,'Split into easy chunks.','Distributive property of division.','2026-10-30 17:33:32',NULL,NULL);
