INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0241','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Analyze the process of long division for 400 ÷ 6.','["Divide, Multiply, Subtract, Bring down. Result is 66 R 4.","Just guess.","Add them all up.","Multiply by 10."]',0,'DMSB.','Standard algorithm steps.','2026-10-30 17:33:32',NULL,NULL);
