INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0243','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Evaluate: In long division, what must you do if the number you ''bring down'' creates a value smaller than the divisor?','["Write a 0 in the quotient and bring down the next digit.","Stop dividing.","Add 1.","Write a decimal."]',0,'Placeholder zero in quotient.','The divisor goes in 0 times.','2026-10-30 17:33:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0244','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Critique: ''Diana calculated 512 ÷ 4 and got 128, but didn''t write down any subtraction steps.''','["If they did it mentally using short division correctly, it is valid, but long division requires showing the subtractions of multiples.","It is completely wrong.","They should have added.","They must use a calculator."]',0,'Mental remainders.','Short vs Long division.','2026-10-30 17:33:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0245','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Analyze why estimation is crucial before performing complex long division (e.g. 8,942 ÷ 31).','["Rounding (e.g., 9000 / 30 = 300) gives a target order of magnitude, preventing massive place-value errors in the quotient.","It wastes time.","It gives the exact answer.","It replaces the remainder."]',0,'Sanity check.','Ensures your answer isn''t 10x too big or small.','2026-10-30 17:33:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0246','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Synthesize: What is the largest possible remainder when dividing any number by 7?','["6","7","8","0"]',0,'One less than the divisor.','The remainder must always be strictly less than the divisor.','2026-10-30 17:33:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0247','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Critique: ''Division by zero is just zero.''','["False, it is undefined.","True.","False, it is 1.","False, it is the number itself."]',0,'Undefined.','Cannot divide by 0.','2026-10-30 17:33:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0248','Maths','Basic Arithmetic Operations','Subtopic 7: Short and long division','Primary',10,'Evaluate: Check 23 ÷ 5 = 4 R 3.','["5 x 4 + 3 = 23. Correct.","5 x 4 = 20.","23 - 3 = 20.","5 + 4 = 9."]',0,'Formula.','Divisor x Quotient + Remainder.','2026-10-30 17:33:33',NULL,NULL);
