INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0255','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',1,'If 12 + 5 = 17, how can you use subtraction to check it?','["17 - 5 = 12","12 - 5 = 7","17 - 12 = 4","12 + 17 = 29"]',0,'Work backwards.','Take one part away from the total.','2026-10-30 17:33:33',NULL,NULL);
