INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0269','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',5,'How do you check a division answer that has a remainder (e.g. 23 ÷ 5 = 4 R 3)?','["(5 x 4) + 3 = 23","5 x 4 = 20","23 - 3 = 20","5 + 4 + 3 = 12"]',0,'Multiply then add.','(Divisor x Quotient) + Remainder = Dividend.','2026-10-30 17:33:35',NULL,NULL);
