INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0277','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Analyze the structure of missing number problems: Why does ''X - 15 = 20'' use addition to solve, but ''35 - X = 20'' uses subtraction to solve?','["In the first, you need the starting total (add parts). In the second, you have the total and one part, so you subtract to find the other part.","They both use addition.","Subtraction is commutative.","They are mistakes."]',0,'Total vs Part.','Position of the unknown dictates the inverse step.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0278','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Synthesize the solution to this multi-step equation: (X x 6) + 4 = 40.','["6","36","7","5"]',0,'Work backwards step by step.','40 - 4 = 36. 36 ÷ 6 = 6.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0279','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Evaluate: If a calculation has multiple steps, how must inverse operations be applied to check it?','["In the exact reverse order of the original operations.","In the same order.","Randomly.","Only using addition."]',0,'Reverse order.','Like untying a knot, you must undo the last step first.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0280','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Critique: ''Diana checked 157 ÷ 3 = 52 R 1 by calculating 52 x 3 = 156. They concluded it was wrong because it didn''t equal 157.''','["False, they forgot to add the remainder (1) to the product.","True, it is wrong.","False, they should subtract.","False, they multiplied wrong."]',0,'+ Remainder.','The remainder must be added back in.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0281','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Synthesize the missing number: X ÷ 6 = 9 R 2.','["56","54","60","11"]',0,'Work backwards with remainder.','(6 x 9) + 2 = 56.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0282','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Analyze the relationship: If a x b = c, does c ÷ a always equal b?','["Yes, provided ''a'' is not zero, because division by zero is undefined.","Yes, always.","No.","Only for even numbers."]',0,'Exception for zero.','Zero breaks the inverse relationship.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0283','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Critique the mistake: ''Checking addition by adding the same numbers again instead of using subtraction.''','["It repeats the same logic and might repeat the same arithmetic error, whereas subtraction uses a different pathway to verify.","It is the best way.","It proves commutative property.","It changes the numbers."]',0,'Avoid repeating mistakes.','Use a different operation to catch errors.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0284','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Evaluate: 250 pencils. +75. -90. Check the steps.','["250+75=325 (Check 325-75=250). 325-90=235 (Check 235+90=325).","Just guess.","No checking needed.","Multiply them."]',0,'Step by step checking.','Check each step with its inverse.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0285','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Analyze: How does estimation work alongside inverse operations?','["Inverse operations check internal consistency; estimation checks if the answer is reasonable in magnitude.","They are the same thing.","Estimation is exact.","Inverse is an estimate."]',0,'Consistency vs Magnitude.','Two different types of checks.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0286','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Synthesize: X - 12 = 3 + 12.','["27","15","3","0"]',0,'Simplify then invert.','3+12=15. 15+12=27.','2026-10-30 17:33:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0287','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Evaluate: Why is equation balancing like a scale?','["Whatever operation you perform on one side, you must perform on the other to maintain equality.","It''s heavy.","It only works for addition.","It doesn''t work."]',0,'Balance.','Keep both sides equal.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0288','Maths','Basic Arithmetic Operations','Subtopic 8: Relationship between operations','Primary',10,'Critique: ''Liam says X + 5 = 10 and 10 = X + 5 are different equations.''','["False, equality is symmetric.","True.","False, they are inequalities.","True, left is right."]',0,'Symmetry.','a=b is the same as b=a.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0289','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'In a math problem with mixed operations, what does BODMAS/PEMDAS help you do?','["Remember the correct order to do the calculations so everyone gets the same answer.","Remember how to spell.","Skip difficult numbers.","Only use addition."]',0,'Order of operations.','It is a set of rules for priority.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0290','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'What is the first step in BODMAS/PEMDAS?','["Brackets / Parentheses","Addition","Division","Multiplication"]',0,'The ''B'' or ''P''.','Always do what is inside the brackets first.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0291','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: (5 + 3) x 2.','["16","11","13","10"]',0,'Brackets first.','Brackets first: 5+3=8. Then 8x2=16.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0292','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: 5 + (3 x 2).','["11","16","13","10"]',0,'Brackets first.','Brackets first: 3x2=6. Then 5+6=11.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0293','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'If there are no brackets, which do you do first: Multiplication or Addition?','["Multiplication","Addition","It doesn''t matter","Subtract"]',0,'M comes before A.','Multiplication has higher priority than addition.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0294','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: 4 + 3 x 2.','["10","14","9","24"]',0,'Multiply before add.','Multiply first: 3x2=6. Add 4+6=10.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0295','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'What does the ''D'' stand for in BODMAS?','["Division","Double","Decimal","Difference"]',0,'Opposite of multiply.','Division.','2026-10-30 17:33:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0296','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'What does the ''A'' stand for in BODMAS?','["Addition","Algebra","Answer","Addend"]',0,'Plus.','Addition.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0297','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: 10 - 2 x 3.','["4","24","1","6"]',0,'Multiply before subtract.','Multiply first: 2x3=6. 10-6=4.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0298','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: (10 - 2) x 3.','["24","4","1","6"]',0,'Brackets first.','Brackets first: 10-2=8. 8x3=24.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0299','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Do you add before you multiply if there are NO brackets?','["No, multiply first.","Yes.","It doesn''t matter.","Only on weekends."]',0,'BODMAS.','Multiplication has priority.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0300','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',1,'Calculate: 6 + 4 x 3.','["18","30","13","10"]',0,'Multiply first.','4x3=12. 6+12=18.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0301','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 24 ÷ 6 x 2.','["8","2","4","12"]',0,'Left to right!','Multiplication and Division have EQUAL priority, so work left to right. 24/6=4. 4x2=8.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0302','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 15 - 6 + 2.','["11","7","9","13"]',0,'Left to right!','Addition and Subtraction have EQUAL priority, work left to right. 15-6=9. 9+2=11.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0303','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 20 ÷ 5 + 7.','["11","20","1","12"]',0,'Divide before add.','Divide first: 20/5=4. Add: 4+7=11.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0304','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 18 - 2 x 4.','["10","64","8","2"]',0,'Multiply before subtract.','Multiply first: 2x4=8. Subtract: 18-8=10.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0305','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'What does the ''O'' in BODMAS or ''E'' in PEMDAS stand for?','["Orders or Exponents (like powers and roots)","Only","Operations","Evens"]',0,'Powers.','Things like squared numbers (3^2).','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0306','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 2 + 3^2 (3 squared).','["11","25","8","10"]',0,'Square it first.','Powers first: 3x3=9. Then 2+9=11.','2026-10-30 17:33:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0307','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: (6 + 4) x 3.','["30","18","13","42"]',0,'Brackets first.','Brackets: 6+4=10. 10x3=30.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0308','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 18 ÷ 3 x 2.','["12","3","6","9"]',0,'Left to right.','Left to right: 18/3=6. 6x2=12.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0309','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 20 - 5 - 3.','["12","18","8","15"]',0,'Left to right.','Left to right: 20-5=15. 15-3=12.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0310','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 24 ÷ (2 + 4) + 3 x 2.','["10","14","8","12"]',0,'Follow all steps.','Brackets: 6. 24/6=4. 3x2=6. 4+6=10.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0311','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Why shouldn''t you automatically add before subtracting?','["Because addition and subtraction have equal priority; you just go left to right.","Because subtraction is better.","Because brackets say so.","You should."]',0,'Left to right.','Equal priority.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0312','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',5,'Calculate: 5 + 2 x 4.','["13","28","11","9"]',0,'Multiply first.','2x4=8. 5+8=13.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0313','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Critique the common mistake: ''In BODMAS, you MUST do Multiplication before Division because M comes before D.''','["False, Multiplication and Division have equal priority; you calculate them from left to right as they appear.","True, M is always first.","False, D is always first.","True, except for fractions."]',0,'Left to right tiebreaker.','They share the same step.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0314','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Synthesize the calculation: 24 ÷ (2 + 4) + 3 x 2.','["10","14","8","12"]',0,'Follow all steps strictly.','Brackets: 2+4=6. Div/Mult: 24/6=4, 3x2=6. Add: 4+6=10.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0315','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Analyze the real-world application: ''Charlie buys 3 notebooks at $4 each and a pen for $2.'' Which expression represents the total cost?','["3 x 4 + 2","3 x (4 + 2)","3 + 4 x 2","(3 + 4) x 2"]',0,'No brackets needed.','Multiply cost of notebooks first, then add the pen.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0316','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Evaluate: ''Diana buys 3 matching sets, each containing a $4 notebook and a $2 pen.'' Which expression represents this?','["3 x (4 + 2)","3 x 4 + 2","3 + 4 x 2","3 x 4 x 2"]',0,'Group the set.','The bracket groups the set together before multiplying by 3.','2026-10-30 17:33:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0317','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Synthesize the calculation: 100 - (5^2 + 15) ÷ 2.','["80","60","90","75"]',0,'P-E-M-D-A-S.','5^2=25. Bracket: 25+15=40. Div: 40/2=20. Sub: 100-20=80.','2026-10-30 17:33:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0318','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Analyze the danger of relying purely on left-to-right calculation without order of operations.','["It leads to wildly inconsistent answers because the mathematical relationships and groupings are ignored.","It is actually faster and better.","It only fails for division.","It works perfectly."]',0,'Consistency.','Math requires standardized rules so equations represent reality correctly.','2026-10-30 17:33:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0319','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Evaluate: (5+2) x 4.','["28","13","33","20"]',0,'Brackets.','7x4=28.','2026-10-30 17:33:40',NULL,NULL);
