INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0322','Maths','Basic Arithmetic Operations','Subtopic 9: Order of operations — introductory','Primary',10,'Critique: ''Julia did 15 - 6 + 2 = 15 - 8 = 7.''','["False, they added before subtracting. Left to right: 15-6=9, 9+2=11.","True.","False, they subtracted wrong.","False, they should multiply."]',0,'Left to right.','Addition and subtraction are left to right.','2026-10-30 17:33:40',NULL,NULL);
