INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0342','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'Estimate to check: 19 boxes with 21 pencils each. About how many pencils?','["400","300","200","500"]',0,'Round then multiply.','Round 19->20, 21->20. 20x20=400.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0343','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'A museum welcomes 135 visitors in morning, 218 in afternoon. Total?','["353","343","83","453"]',0,'Add.','135 + 218 = 353.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0344','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'A farmer has 500 oranges and sells 185. How many remain?','["315","685","415","325"]',0,'Subtract.','500 - 185 = 315.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0345','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'16 shelves with 25 books each. How many books?','["400","41","300","500"]',0,'Multiply.','16 x 25 = 400.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0346','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'Coach shares 84 bottles among 7 teams. How many each?','["12","11","13","77"]',0,'Divide.','84 / 7 = 12.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0347','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'A group walks 18 km day 1, 14 km day 2. Route is 50 km. Remaining?','["18 km","32 km","68 km","22 km"]',0,'Multi-step.','18+14=32. 50-32=18.','2026-10-30 17:33:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0348','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',5,'Buy 3 pens at $4 each, notebook at $7. Total?','["$19","$33","$21","$15"]',0,'Multi-step.','(3x4)+7=19.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0349','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Analyze the danger of relying ONLY on keywords (like ''more'' or ''share'') to solve word problems.','["Keywords can be misleading depending on sentence structure; you must comprehend the actual mathematical situation being described.","Keywords are never used in math.","Keywords are foolproof.","They only work for addition."]',0,'Context matters.','Read the whole situation, don''t just hunt for words.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0350','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Synthesize this multi-step problem: A tank holds 60L. 1/4 is used for cleaning, 1/3 for plants. How much is left? (Assume sequential from total, so 15L and 20L).','["25L","35L","10L","30L"]',0,'Fractions of an amount, then subtract.','15 + 20 = 35 used. 60 - 35 = 25 left.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0351','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Critique this reasoning: ''Charlie has 50 items and packs them 6 per bag. 50/6 = 8.33. So they need 8.33 bags.''','["False, you cannot have a fraction of a physical bag in this context; they need 9 bags to hold all items.","True, decimals are always exact.","False, they need 8 bags.","True, cut the bag."]',0,'Can you buy .33 of a bag?','Context dictates how to handle remainders.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0352','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Evaluate the five-step method for word problems: Read, Identify, Choose, Calculate, Check. Why is ''Check'' critical?','["To ensure the numerical answer makes logical sense in the real-world context of the problem.","To make the problem longer.","To practice handwriting.","It isn''t critical."]',0,'Sanity check.','Does a human running 500 mph make sense?','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0353','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Synthesize: Ethan walks 18 km day 1, 14 km day 2. The total route is 50 km. How many km remain?','["18 km","32 km","68 km","12 km"]',0,'Multi-step.','18+14=32. 50-32=18.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0354','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Analyze: If a problem asks ''How many more X than Y are there?'', what concept is being applied?','["Finding the difference between two quantities (Subtraction).","Combining groups.","Finding the total.","Sharing equally."]',0,'Comparison.','Comparing amounts means finding the difference.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0355','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Evaluate: Why do word problems use units (like km, kg, $)?','["To give the numbers real-world meaning and ensure you don''t add incompatible quantities (like apples to km).","To make it confusing.","Because math requires words.","It doesn''t matter."]',0,'Apples vs Oranges.','Units provide context.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0356','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Critique: ''Hannah added 12 km and 9 hours together.''','["False, you cannot add quantities with different units.","True.","False, they should be multiplied.","False, they should be subtracted."]',0,'Incompatible units.','Only add like units.','2026-10-30 17:33:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0357','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Synthesize: Ian has $100. Buys 3 shirts at $15 each. How much change?','["$55","$45","$85","$50"]',0,'Multi-step money.','3x15=45. 100-45=55.','2026-10-30 17:33:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0358','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Analyze: What is the hidden step in ''A dozen eggs cost $2. How much for 3 eggs?''','["Finding the unit cost or recognizing that 3 is 1/4 of a dozen. (2 / 4 = $0.50).","Adding 3 and 2.","Multiplying 12 by 3.","There is no hidden step."]',0,'Dozen = 12.','You have to know a dozen is 12.','2026-10-30 17:33:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0359','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Evaluate: If an estimate says the answer should be around 400, but the calculation gives 3,990, what happened?','["A major place-value error occurred during the exact calculation.","The estimate is wrong.","They are close enough.","Nothing."]',0,'Place value error.','Estimation caught a 10x error.','2026-10-30 17:33:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t2_global_0360','Maths','Basic Arithmetic Operations','Subtopic 10: Word problems involving operations','Primary',10,'Synthesize: A baker makes 5 batches of 12 cookies. Burns 4 cookies. Sells the rest in boxes of 8. How many boxes?','["7","8","6","9"]',0,'Multi-step.','5x12=60. 60-4=56. 56/8=7.','2026-10-30 17:33:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0001','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'What is a factor?','["A whole number that divides another number exactly, leaving no remainder.","A number obtained by multiplying.","The answer to an addition problem.","A number that is left over."]',0,'Think of division without a remainder.','A factor divides into a number exactly.','2026-10-30 17:33:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0002','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'Which of these numbers is a factor of 8?','["2","5","7","9"]',0,'Which number fits perfectly into 8?','8 divided by 2 is an exact whole number.','2026-10-30 17:33:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0003','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'Is 3 a factor of 15?','["Yes","No","Sometimes","Only on Tuesdays"]',0,'Does 3 fit perfectly into 15?','15 divided by 3 is 5 exactly, so 3 is a factor.','2026-10-30 17:33:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0004','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'Which of these is NOT a factor of 10?','["3","1","2","5"]',0,'Which number does NOT divide 10 exactly?','10 divided by 3 leaves a remainder, so it is not a factor.','2026-10-30 17:33:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0005','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'What do we call pairs of numbers that multiply to give a target number?','["Factor pairs","Odd pairs","Even pairs","Multiple pairs"]',0,'They work together in pairs.','Factor pairs are two numbers that multiply to give the target number.','2026-10-30 17:33:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0006','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',1,'Is 1 a factor of every whole number?','["Yes","No","Only even numbers","Only odd numbers"]',0,'1 fits into everything.','Every whole number can be divided by 1 exactly.','2026-10-30 17:33:55',NULL,NULL);
