INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0013','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Find all the factors of 18.','["1, 2, 3, 6, 9, 18","2, 4, 6, 8","18, 36, 54","1, 18"]',0,'Think of all pairs that multiply to 18.','The factor pairs are (1,18), (2,9), and (3,6).','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0014','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'If 5 is a factor of a number, what else must be true?','["The number is a multiple of 5.","The number is less than 5.","The number is prime.","The number is odd."]',0,'Factors and multiples are opposites.','If A is a factor of B, then B is a multiple of A.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0015','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'How many factors does the number 7 have?','["2","1","3","4"]',0,'It''s a prime number.','7 has two factors: 1 and 7.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0016','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'If 12 marbles are arranged in equal rows, which of these is a possible number of rows?','["4","5","7","9"]',0,'Must be a factor of 12.','4 is a factor of 12 (12/4 = 3 rows).','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0017','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Find the factor pairs of 16.','["(1,16), (2,8)...","Just 1 and the number.","Only even numbers.","Multiples of the number."]',0,'Multiply to get the target.','Find pairs that multiply to the number.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0018','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Which of these numbers has exactly 3 factors?','["4 (factors: 1, 2, 4)","6","8","10"]',0,'Think of a perfect square.','Square numbers of primes have 3 factors.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0019','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Find all the factors of 18.','["1, 2, 3, 6, 9, 18","2, 4, 6, 8","18, 36, 54","1, 18"]',0,'Think of all pairs that multiply to 18.','The factor pairs are (1,18), (2,9), and (3,6).','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0020','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'If 5 is a factor of a number, what else must be true?','["The number is a multiple of 5.","The number is less than 5.","The number is prime.","The number is odd."]',0,'Factors and multiples are opposites.','If A is a factor of B, then B is a multiple of A.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0021','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'How many factors does the number 7 have?','["2","1","3","4"]',0,'It''s a prime number.','7 has two factors: 1 and 7.','2026-10-30 17:33:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0022','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'If 12 blocks are arranged in equal rows, which of these is a possible number of rows?','["4","5","7","9"]',0,'Must be a factor of 12.','4 is a factor of 12 (12/4 = 3 rows).','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0023','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Find the factor pairs of 16.','["(1,16), (2,8)...","Just 1 and the number.","Only even numbers.","Multiples of the number."]',0,'Multiply to get the target.','Find pairs that multiply to the number.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0024','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',5,'Which of these numbers has exactly 3 factors?','["4 (factors: 1, 2, 4)","6","8","10"]',0,'Think of a perfect square.','Square numbers of primes have 3 factors.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0025','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Analyze the relationship: If x is a factor of y, and y is a factor of z, what is the relationship between x and z?','["x is a factor of z.","x is a multiple of z.","x equals z.","No relationship."]',0,'Think about Russian nesting dolls.','Factors are transitive. If x divides y, and y divides z, then x divides z.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0026','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Evaluate why the number of factors of a perfect square (like 16) is always an odd number.','["Because one factor pair consists of the same number multiplied by itself, meaning it is only listed once.","Because all perfect squares are odd numbers.","Because perfect squares don''t have factors.","It is a coincidence."]',0,'Look at the square root.','For 16, the pairs are (1,16), (2,8), and (4,4). The ''4'' is only listed once, making the total count odd (1, 2, 4, 8, 16).','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0027','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Analyze: Why does listing factor pairs prevent missing factors?','["Because factors always occur in pairs (a x b = c), finding one guarantees finding its counterpart.","Because it is faster.","Because factors are always even.","It doesn''t help."]',0,'They come in twos.','Every division that yields a factor produces a quotient that is also a factor.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0028','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Critique the statement: ''Every number has an even number of factors.''','["False, perfect squares have an odd number of factors.","True, factors always come in distinct pairs.","False, primes have 3 factors.","True, because math is balanced."]',0,'Think of the number 9.','Perfect squares repeat a factor, making the total count odd.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0029','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Synthesize: If a number N has factors 1, 2, 3, 4, 6, 8, 12, 24, what is N?','["24","48","12","36"]',0,'Look at the largest number in the list.','The largest factor is the number itself.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0030','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Evaluate: Why is 1 considered a factor of every integer?','["Because any integer divided by 1 yields the integer itself with no remainder.","Because 1 is the largest number.","Because 1 is zero.","It isn''t a factor."]',0,'Identity property of division.','1 fits perfectly into every whole number.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0031','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Analyze the relationship: If x is a factor of y, and y is a factor of z, what is the relationship between x and z?','["x is a factor of z.","x is a multiple of z.","x equals z.","No relationship."]',0,'Think about Russian nesting dolls.','Factors are transitive. If x divides y, and y divides z, then x divides z.','2026-10-30 17:33:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0032','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Evaluate why the number of factors of a perfect square (like 16) is always an odd number.','["Because one factor pair consists of the same number multiplied by itself, meaning it is only listed once.","Because all perfect squares are odd numbers.","Because perfect squares don''t have factors.","It is a coincidence."]',0,'Look at the square root.','For 16, the pairs are (1,16), (2,8), and (4,4). The ''4'' is only listed once, making the total count odd (1, 2, 4, 8, 16).','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0033','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Analyze: Why does listing factor pairs prevent missing factors?','["Because factors always occur in pairs (a x b = c), finding one guarantees finding its counterpart.","Because it is faster.","Because factors are always even.","It doesn''t help."]',0,'They come in twos.','Every division that yields a factor produces a quotient that is also a factor.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0034','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Critique the statement: ''Every number has an even number of factors.''','["False, perfect squares have an odd number of factors.","True, factors always come in distinct pairs.","False, primes have 3 factors.","True, because math is balanced."]',0,'Think of the number 9.','Perfect squares repeat a factor, making the total count odd.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0035','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Synthesize: If a number N has factors 1, 2, 3, 4, 6, 8, 12, 24, what is N?','["24","48","12","36"]',0,'Look at the largest number in the list.','The largest factor is the number itself.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0036','Maths','Factors, Multiples and Divisibility','Subtopic 1: Factors and factor pairs','Primary',10,'Evaluate: Why is 1 considered a factor of every integer?','["Because any integer divided by 1 yields the integer itself with no remainder.","Because 1 is the largest number.","Because 1 is zero.","It isn''t a factor."]',0,'Identity property of division.','1 fits perfectly into every whole number.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0037','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'What is a multiple?','["The result of multiplying a number by a whole number.","A number that divides exactly.","A fraction.","A remainder."]',0,'Think of multiplication tables.','A multiple is found by multiplying.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0038','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'Which of these is a multiple of 4?','["12","5","3","13"]',0,'It''s in the 4 times table.','4 x 3 = 12, so 12 is a multiple of 4.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0039','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'Is 20 a multiple of 5?','["Yes","No","Maybe","Only if it ends in 2"]',0,'Can you count by 5s to get to 20?','5 x 4 = 20, so 20 is a multiple of 5.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0040','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'What is the smallest positive multiple of 7?','["7","1","0","14"]',0,'Multiply by 1.','7 x 1 = 7.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0041','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'How do you find multiples of 3?','["Add 3 repeatedly (3, 6, 9...).","Divide by 3.","Subtract 3.","Multiply by 2."]',0,'Count by 3s.','Multiples are found by multiplying or adding repeatedly.','2026-10-30 17:33:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0042','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',1,'Is 16 a multiple of 4?','["Yes","No","Only for primes","Cannot tell"]',0,'Check the times table.','4 x 4 = 16.','2026-10-30 17:33:59',NULL,NULL);
