INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0049','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',5,'What are the first four positive multiples of 6?','["6, 12, 18, 24","1, 2, 3, 6","6, 8, 10, 12","12, 24, 36, 48"]',0,'Count by 6s.','6x1, 6x2, 6x3, 6x4.','2026-10-30 17:33:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0050','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',5,'Which statement is true about factors and multiples?','["Factors divide exactly, multiples are obtained by multiplying.","Factors are infinite, multiples are finite.","Factors are larger than multiples.","They are exactly the same."]',0,'Divide vs Multiply.','Factors divide into a number. Multiples grow by multiplying.','2026-10-30 17:33:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0051','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',5,'Is 36 a multiple of 9?','["Yes, because 9x4=36","No, because 36 is even","Yes, because 9+4=13","No, because 36/4=9"]',0,'Check the 9 times table.','36 is the result of multiplying 9 by 4.','2026-10-30 17:33:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0052','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',5,'Which of these numbers is BOTH a multiple of 2 and a multiple of 5?','["20","12","15","25"]',0,'It must end in 0.','20 is 2x10 and 5x4.','2026-10-30 17:34:00',NULL,NULL);
