INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0061','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Critique the statement: ''Every number is a multiple of itself.''','["True, because any number multiplied by 1 equals itself.","False, because you can''t multiply a number by itself.","False, only prime numbers are.","True, but only for even numbers."]',0,'Multiply by 1.','A number x 1 = the number itself, so it is a multiple of itself.','2026-10-30 17:34:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0062','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Why is 0 a multiple of every whole number (if 0 is included in the definition)?','["Because any whole number multiplied by 0 equals 0.","Because every number divided by 0 is 0.","Because 0 is the identity element.","It is not a multiple."]',0,'Multiply by zero.','A multiple is the result of multiplying by a whole number. n x 0 = 0.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0063','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Evaluate: Can a multiple of a positive number be smaller than the number itself (excluding 0)?','["No, positive multiples start at the number (x1) and grow larger.","Yes, if you divide.","Yes, if the number is even.","No, they start at 0."]',0,'x1 is the smallest.','The smallest positive multiple is the number x 1.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0064','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Synthesize: If X is a multiple of 6, is X always a multiple of 3?','["Yes, because 3 is a factor of 6.","No, not always.","Only if X is odd.","Only if X is negative."]',0,'Think of the factors of 6.','If a number contains 6 (which is 2x3), it must also contain 3.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0065','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Analyze: How many multiples of 4 exist between 10 and 20 (inclusive)?','["3 (12, 16, 20)","2","4","5"]',0,'List them.','4x3=12, 4x4=16, 4x5=20.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0066','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Critique: ''Fiona says the multiples of 5 are 1, 5.''','["False, those are the factors of 5. The multiples are 5, 10, 15...","True.","False, the multiples are 5, 15, 25.","False, it is 10, 20."]',0,'Multiples grow.','Confusing factors with multiples.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0067','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Critique the statement: ''Every number is a multiple of itself.''','["True, because any number multiplied by 1 equals itself.","False, because you can''t multiply a number by itself.","False, only prime numbers are.","True, but only for even numbers."]',0,'Multiply by 1.','A number x 1 = the number itself, so it is a multiple of itself.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0068','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Why is 0 a multiple of every whole number (if 0 is included in the definition)?','["Because any whole number multiplied by 0 equals 0.","Because every number divided by 0 is 0.","Because 0 is the identity element.","It is not a multiple."]',0,'Multiply by zero.','A multiple is the result of multiplying by a whole number. n x 0 = 0.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0069','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Evaluate: Can a multiple of a positive number be smaller than the number itself (excluding 0)?','["No, positive multiples start at the number (x1) and grow larger.","Yes, if you divide.","Yes, if the number is even.","No, they start at 0."]',0,'x1 is the smallest.','The smallest positive multiple is the number x 1.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0070','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Synthesize: If X is a multiple of 6, is X always a multiple of 3?','["Yes, because 3 is a factor of 6.","No, not always.","Only if X is odd.","Only if X is negative."]',0,'Think of the factors of 6.','If a number contains 6 (which is 2x3), it must also contain 3.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0071','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Analyze: How many multiples of 4 exist between 10 and 20 (inclusive)?','["3 (12, 16, 20)","2","4","5"]',0,'List them.','4x3=12, 4x4=16, 4x5=20.','2026-10-30 17:34:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0072','Maths','Factors, Multiples and Divisibility','Subtopic 2: Multiples','Primary',10,'Critique: ''Liam says the multiples of 5 are 1, 5.''','["False, those are the factors of 5. The multiples are 5, 10, 15...","True.","False, the multiples are 5, 15, 25.","False, it is 10, 20."]',0,'Multiples grow.','Confusing factors with multiples.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0073','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is a prime number?','["A whole number greater than 1 with exactly two positive factors: 1 and itself.","A number with many factors.","Any odd number.","A number that ends in 0."]',0,'It can only be divided by 1 and itself.','A prime number has exactly two factors.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0074','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is a composite number?','["A whole number greater than 1 with more than two positive factors.","A number with exactly two factors.","Any even number.","A negative number."]',0,'It can be broken down into smaller factors.','A composite number has more than two factors.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0075','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 7 prime or composite?','["Prime","Composite","Both","Neither"]',0,'Can you divide 7 by anything else?','7 has only two factors: 1 and 7.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0076','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 8 prime or composite?','["Composite","Prime","Both","Neither"]',0,'It can be divided by 2.','8 has factors 1, 2, 4, 8.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0077','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 1 prime or composite?','["Neither","Prime","Composite","Both"]',0,'Primes need EXACTLY two factors.','1 is neither prime nor composite because it has only ONE factor (itself).','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0078','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is the only EVEN prime number?','["2","4","6","8"]',0,'It''s the smallest prime.','2 has exactly two factors (1 and 2). All other even numbers can be divided by 2.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0079','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is a prime number?','["A whole number greater than 1 with exactly two positive factors: 1 and itself.","A number with many factors.","Any odd number.","A number that ends in 0."]',0,'It can only be divided by 1 and itself.','A prime number has exactly two factors.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0080','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is a composite number?','["A whole number greater than 1 with more than two positive factors.","A number with exactly two factors.","Any even number.","A negative number."]',0,'It can be broken down into smaller factors.','A composite number has more than two factors.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0081','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 7 prime or composite?','["Prime","Composite","Both","Neither"]',0,'Can you divide 7 by anything else?','7 has only two factors: 1 and 7.','2026-10-30 17:34:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0082','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 8 prime or composite?','["Composite","Prime","Both","Neither"]',0,'It can be divided by 2.','8 has factors 1, 2, 4, 8.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0083','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'Is the number 1 prime or composite?','["Neither","Prime","Composite","Both"]',0,'Primes need EXACTLY two factors.','1 is neither prime nor composite because it has only ONE factor (itself).','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0084','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',1,'What is the only EVEN prime number?','["2","4","6","8"]',0,'It''s the smallest prime.','2 has exactly two factors (1 and 2). All other even numbers can be divided by 2.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0085','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Are all odd numbers prime?','["No","Yes","Only some of them","Always"]',0,'Think of the number 9 or 15.','No, for example, 9 is odd but composite (factors 1, 3, 9).','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0086','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Classify the number 15.','["Composite","Prime","Neither","Even"]',0,'It ends in 5.','15 has factors 1, 3, 5, 15.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0087','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Why is 9 a composite number?','["It has factors 1, 3, and 9 (more than two).","It is odd.","It has exactly two factors.","It is even."]',0,'3 x 3 = 9.','Having more than two factors makes it composite.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0088','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'List the prime numbers between 1 and 10.','["2, 3, 5, 7","1, 2, 3, 5, 7, 9","2, 4, 6, 8","3, 5, 7, 9"]',0,'Skip 1, 4, 6, 8, 9, 10.','The primes are 2, 3, 5, and 7. (1 is neither, 9 is composite).','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0089','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'What makes an even number greater than 2 composite?','["It has at least three factors: 1, 2, and itself.","It is odd.","It has exactly two factors.","It cannot be divided."]',0,'Divide by 2.','Being divisible by 2 gives it a third factor.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0090','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'If a number ends in 5 (and is greater than 5), is it prime or composite?','["Composite","Prime","Neither","Depends"]',0,'Divisibility by 5.','It will be divisible by 5, giving it more than 2 factors.','2026-10-30 17:34:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0091','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Are all odd numbers prime?','["No","Yes","Only some of them","Always"]',0,'Think of the number 9 or 15.','No, for example, 9 is odd but composite (factors 1, 3, 9).','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0092','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Classify the number 15.','["Composite","Prime","Neither","Even"]',0,'It ends in 5.','15 has factors 1, 3, 5, 15.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0093','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'Why is 9 a composite number?','["It has factors 1, 3, and 9 (more than two).","It is odd.","It has exactly two factors.","It is even."]',0,'3 x 3 = 9.','Having more than two factors makes it composite.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0094','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'List the prime numbers between 1 and 10.','["2, 3, 5, 7","1, 2, 3, 5, 7, 9","2, 4, 6, 8","3, 5, 7, 9"]',0,'Skip 1, 4, 6, 8, 9, 10.','The primes are 2, 3, 5, and 7. (1 is neither, 9 is composite).','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0095','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'What makes an even number greater than 2 composite?','["It has at least three factors: 1, 2, and itself.","It is odd.","It has exactly two factors.","It cannot be divided."]',0,'Divide by 2.','Being divisible by 2 gives it a third factor.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0096','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',5,'If a number ends in 5 (and is greater than 5), is it prime or composite?','["Composite","Prime","Neither","Depends"]',0,'Divisibility by 5.','It will be divisible by 5, giving it more than 2 factors.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0097','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Critique the assertion: ''All prime numbers are odd.''','["False; 2 is an even prime number.","True.","True, because even numbers can be divided by 2.","False, 1 is prime."]',0,'What about the number 2?','2 is the only even prime number. All other primes are odd.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0098','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Analyze why 1 is classified as neither prime nor composite.','["A prime must have exactly two distinct positive factors, and a composite must have more than two. 1 has exactly ONE positive factor (itself).","Because it is the first number.","Because it is odd.","Because it divides everything."]',0,'Count the distinct factors of 1.','1 does not fit the definition of either category based on factor count.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0099','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Synthesize a rule to check if a large number like 97 is prime.','["Test divisibility by prime numbers up to its square root (approx 9). If none divide exactly, it is prime.","Divide it by every number up to 97.","Just look at the last digit.","Add the digits."]',0,'Don''t check past 10.','You only need to check primes up to the square root to find a factor pair.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0100','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Evaluate the classification of the number 51.','["Composite, because 5 + 1 = 6, meaning it is divisible by 3.","Prime, because it is odd and doesn''t end in 5.","Prime, because it has two factors.","Composite, because it is even."]',0,'Use the divisibility rule for 3.','51 is divisible by 3 (3 x 17 = 51).','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0101','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Critique: ''The product of two prime numbers is always composite.''','["True, because it will have factors of 1, the product, and the two original prime numbers (more than 2 factors).","False, it is prime.","False, it is always even.","True, but only if they are the same."]',0,'Count the factors.','e.g., 3 x 5 = 15. Factors: 1, 3, 5, 15.','2026-10-30 17:34:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0102','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Analyze: Can a composite number have only prime numbers as its factors (other than 1 and itself)?','["Yes, e.g., 15 (factors 1, 3, 5, 15; 3 and 5 are prime).","No, it must have a composite factor.","Yes, but only if it''s even.","No."]',0,'Look at 15.','Some composite numbers only have prime factors besides 1 and themselves.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0103','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Critique the assertion: ''All prime numbers are odd.''','["False; 2 is an even prime number.","True.","True, because even numbers can be divided by 2.","False, 1 is prime."]',0,'What about the number 2?','2 is the only even prime number. All other primes are odd.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0104','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Analyze why 1 is classified as neither prime nor composite.','["A prime must have exactly two distinct positive factors, and a composite must have more than two. 1 has exactly ONE positive factor (itself).","Because it is the first number.","Because it is odd.","Because it divides everything."]',0,'Count the distinct factors of 1.','1 does not fit the definition of either category based on factor count.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0105','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Synthesize a rule to check if a large number like 97 is prime.','["Test divisibility by prime numbers up to its square root (approx 9). If none divide exactly, it is prime.","Divide it by every number up to 97.","Just look at the last digit.","Add the digits."]',0,'Don''t check past 10.','You only need to check primes up to the square root to find a factor pair.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0106','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Evaluate the classification of the number 51.','["Composite, because 5 + 1 = 6, meaning it is divisible by 3.","Prime, because it is odd and doesn''t end in 5.","Prime, because it has two factors.","Composite, because it is even."]',0,'Use the divisibility rule for 3.','51 is divisible by 3 (3 x 17 = 51).','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0107','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Critique: ''The product of two prime numbers is always composite.''','["True, because it will have factors of 1, the product, and the two original prime numbers (more than 2 factors).","False, it is prime.","False, it is always even.","True, but only if they are the same."]',0,'Count the factors.','e.g., 3 x 5 = 15. Factors: 1, 3, 5, 15.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0108','Maths','Factors, Multiples and Divisibility','Subtopic 3: Prime and composite numbers','Primary',10,'Analyze: Can a composite number have only prime numbers as its factors (other than 1 and itself)?','["Yes, e.g., 15 (factors 1, 3, 5, 15; 3 and 5 are prime).","No, it must have a composite factor.","Yes, but only if it''s even.","No."]',0,'Look at 15.','Some composite numbers only have prime factors besides 1 and themselves.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0109','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',1,'What is the divisibility rule for 2?','["Last digit is 0, 2, 4, 6, or 8 (even).","Sum of digits is 2.","Last digit is 0 or 5.","Last digit is 0."]',0,'Look at the last digit.','All even numbers are divisible by 2.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0110','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',1,'Is 18 divisible by 2?','["Yes, it ends in 8.","No, 1+8=9.","Yes, it ends in 1.","No."]',0,'Ends in an even number.','Last digit is 8, which is even.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0111','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',1,'What is the divisibility rule for 5?','["Last digit is 0 or 5.","Last digit is even.","Sum of digits is 5.","Last digit is 10."]',0,'Count by 5s.','Numbers ending in 0 or 5 are divisible by 5.','2026-10-30 17:34:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0112','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',1,'Is 35 divisible by 5?','["Yes, ends in 5.","No.","Yes, 3+5=8.","No, ends in 3."]',0,'Check the last digit.','It ends in 5.','2026-10-30 17:34:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0113','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',1,'What is the divisibility rule for 10?','["Last digit is 0.","Last digit is 5.","Sum of digits is 10.","Last digit is even."]',0,'Count by 10s.','Numbers ending in 0 are divisible by 10.','2026-10-30 17:34:06',NULL,NULL);
