INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0122','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 123 divisible by 3?','["Yes, 1+2+3=6, and 6 is divisible by 3.","No, ends in 3.","No, it is odd.","Yes, 1+2=3."]',0,'Apply the rule for 3.','Sum of digits is 6.','2026-10-30 17:34:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0123','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Check if 247 is divisible by 3.','["No, 2+4+7=13, not divisible by 3.","Yes","Yes, ends in 7.","No, it''s even."]',0,'Add the digits.','Sum of digits is 13.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0124','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 450 divisible by BOTH 10 and 5?','["Yes, both, because it ends in 0.","Only 10.","Only 5.","Neither."]',0,'Check the last digit.','Ending in 0 satisfies both rules.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0125','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Which numbers divide 120 exactly based on rules for 2, 3, 5, 10?','["2, 3, 5, and 10.","Only 2 and 5.","Only 10.","Only 3."]',0,'Apply all rules.','Ends in 0 (2,5,10) and 1+2+0=3 (3).','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0126','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 425 divisible by 2?','["No, it ends in 5 (odd).","Yes","Yes, 4+2=6.","No, it ends in 25."]',0,'Check the last digit.','It is an odd number.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0127','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'What is the divisibility rule for 3?','["Sum of the digits is divisible by 3.","Last digit is 3.","Ends in 3, 6, or 9.","Last two digits divide by 3."]',0,'Add them up.','Add the digits and check if the sum divides by 3.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0128','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 123 divisible by 3?','["Yes, 1+2+3=6, and 6 is divisible by 3.","No, ends in 3.","No, it is odd.","Yes, 1+2=3."]',0,'Apply the rule for 3.','Sum of digits is 6.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0129','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Check if 247 is divisible by 3.','["No, 2+4+7=13, not divisible by 3.","Yes","Yes, ends in 7.","No, it''s even."]',0,'Add the digits.','Sum of digits is 13.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0130','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 450 divisible by BOTH 10 and 5?','["Yes, both, because it ends in 0.","Only 10.","Only 5.","Neither."]',0,'Check the last digit.','Ending in 0 satisfies both rules.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0131','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Which numbers divide 120 exactly based on rules for 2, 3, 5, 10?','["2, 3, 5, and 10.","Only 2 and 5.","Only 10.","Only 3."]',0,'Apply all rules.','Ends in 0 (2,5,10) and 1+2+0=3 (3).','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0132','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',5,'Is 425 divisible by 2?','["No, it ends in 5 (odd).","Yes","Yes, 4+2=6.","No, it ends in 25."]',0,'Check the last digit.','It is an odd number.','2026-10-30 17:34:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0133','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Critique the mistake: ''Alice says divisibility by 3 means checking if the last digit is 3, 6, or 9.''','["False; you must check if the SUM of the digits is divisible by 3.","True.","True, but only for even numbers.","False, rule is for 9."]',0,'Don''t just look at the last digit for 3!','The rule for 3 requires summing all digits.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0134','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Analyze: Why does the divisibility rule for 5 work by ONLY looking at the last digit?','["Because in a base-10 system, every place value above ones (tens, hundreds) is a multiple of 10, and 10 is a multiple of 5. So only the ones digit matters.","Because all numbers end in 5.","Because 5 is prime.","It''s a coincidence."]',0,'Think about place value.','10, 100, 1000 are all divisible by 5. The remainder depends solely on the ones digit.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0135','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Evaluate: If a number is divisible by 10, is it always divisible by 2 and 5? Why?','["Yes, because 10 = 2 x 5, so any multiple of 10 must also be a multiple of its prime factors.","No.","Only by 5.","Only by 2."]',0,'Factors of 10.','Multiples of a composite number are multiples of its factors.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0136','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Synthesize: Determine if 8,745 is divisible by 3 and 5.','["Both. Ends in 5, and 8+7+4+5=24 (divisible by 3).","Only 5.","Only 3.","Neither."]',0,'Test both rules.','Passes rule for 5 (ends in 5) and rule for 3 (sum=24).','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0137','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Analyze the divisibility rule for 4: ''Last two digits must be divisible by 4.'' Is 316 divisible by 4?','["Yes, 16 is divisible by 4.","No.","Yes, 3+1+6=10.","No, ends in 6."]',0,'Look at the tens and ones.','Last two digits are 16. 16/4 = 4.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0138','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Synthesize the divisibility rule for 6: A number is divisible by 6 if...','["It is divisible by both 2 AND 3.","It ends in 6.","Sum of digits is 6.","It is even."]',0,'Combine rules.','6 = 2 x 3. Must be even AND sum of digits divisible by 3.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0139','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Critique the mistake: ''George says divisibility by 3 means checking if the last digit is 3, 6, or 9.''','["False; you must check if the SUM of the digits is divisible by 3.","True.","True, but only for even numbers.","False, rule is for 9."]',0,'Don''t just look at the last digit for 3!','The rule for 3 requires summing all digits.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0140','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Analyze: Why does the divisibility rule for 5 work by ONLY looking at the last digit?','["Because in a base-10 system, every place value above ones (tens, hundreds) is a multiple of 10, and 10 is a multiple of 5. So only the ones digit matters.","Because all numbers end in 5.","Because 5 is prime.","It''s a coincidence."]',0,'Think about place value.','10, 100, 1000 are all divisible by 5. The remainder depends solely on the ones digit.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0141','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Evaluate: If a number is divisible by 10, is it always divisible by 2 and 5? Why?','["Yes, because 10 = 2 x 5, so any multiple of 10 must also be a multiple of its prime factors.","No.","Only by 5.","Only by 2."]',0,'Factors of 10.','Multiples of a composite number are multiples of its factors.','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0142','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Synthesize: Determine if 8,745 is divisible by 3 and 5.','["Both. Ends in 5, and 8+7+4+5=24 (divisible by 3).","Only 5.","Only 3.","Neither."]',0,'Test both rules.','Passes rule for 5 (ends in 5) and rule for 3 (sum=24).','2026-10-30 17:34:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0143','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Analyze the divisibility rule for 4: ''Last two digits must be divisible by 4.'' Is 316 divisible by 4?','["Yes, 16 is divisible by 4.","No.","Yes, 3+1+6=10.","No, ends in 6."]',0,'Look at the tens and ones.','Last two digits are 16. 16/4 = 4.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0144','Maths','Factors, Multiples and Divisibility','Subtopic 4: Divisibility rules','Primary',10,'Synthesize the divisibility rule for 6: A number is divisible by 6 if...','["It is divisible by both 2 AND 3.","It ends in 6.","Sum of digits is 6.","It is even."]',0,'Combine rules.','6 = 2 x 3. Must be even AND sum of digits divisible by 3.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0145','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'What are ''common factors''?','["Factors that are shared by two or more numbers.","Factors that are boring.","Factors that are odd.","Factors that are large."]',0,'Shared by both.','Common factors appear in the factor lists of both numbers.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0146','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'If the factors of 12 are 1, 2, 3, 4, 6, 12 and factors of 18 are 1, 2, 3, 6, 9, 18. What are the common factors?','["1, 2, 3, 6","1, 2, 3","1, 12","6, 18"]',0,'Find the matching numbers.','1, 2, 3, and 6 appear in both lists.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0147','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'Is 2 a common factor of 8 and 10?','["Yes, both are even.","No.","Only of 8.","Only of 10."]',0,'Are they both even?','2 divides both 8 and 10 exactly.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0148','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'Is 5 a common factor of 15 and 20?','["Yes, both end in 5 or 0.","No.","Only of 15.","Only of 20."]',0,'Rule for 5.','5 divides both 15 and 20.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0149','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'Is 1 always a common factor of any two whole numbers?','["Yes","No","Only odd numbers","Only even numbers"]',0,'1 fits into everything.','1 divides every whole number.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0150','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'Can a common factor be larger than the numbers themselves?','["No","Yes","Sometimes","Only for primes"]',0,'Divide INTO the number.','Factors are smaller than or equal to the number.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0151','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'What are ''common factors''?','["Factors that are shared by two or more numbers.","Factors that are boring.","Factors that are odd.","Factors that are large."]',0,'Shared by both.','Common factors appear in the factor lists of both numbers.','2026-10-30 17:34:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0152','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',1,'If the factors of 12 are 1, 2, 3, 4, 6, 12 and factors of 18 are 1, 2, 3, 6, 9, 18. What are the common factors?','["1, 2, 3, 6","1, 2, 3","1, 12","6, 18"]',0,'Find the matching numbers.','1, 2, 3, and 6 appear in both lists.','2026-10-30 17:34:09',NULL,NULL);
