INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0157','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Find the common factors of 16 and 24.','["1, 2, 4, 8","1, 2, 3, 4","1, 2, 8","1, 4, 8, 12"]',0,'List both sets.','Factors 16: 1,2,4,8,16. Factors 24: 1,2,3,4,6,8,12,24. Common: 1,2,4,8.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0158','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Find the common factors of 10 and 15.','["1, 5","1, 2, 5","1, 3, 5","5, 10"]',0,'Matches.','Factors 10: 1,2,5,10. Factors 15: 1,3,5,15. Common: 1,5.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0159','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'If two numbers have only 1 as a common factor, what are they called?','["Coprime (or relatively prime)","Prime numbers","Composite numbers","Twins"]',0,'No other shared divisors.','If 1 is the only common factor, they share no other factors.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0160','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Which of these is a common factor of 14 and 21?','["7","2","3","14"]',0,'Check times tables.','Both are in the 7 times table.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0161','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'How many common factors do 9 and 15 have?','["Two (1 and 3)","One","Three","Four"]',0,'List them.','Factors 9: 1,3,9. Factors 15: 1,3,5,15. Common: 1, 3.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0162','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Is 4 a common factor of 12 and 18?','["No, 18 is not divisible by 4.","Yes, both are even.","Only of 18.","Yes, 4x3=12."]',0,'Check 18.','18/4 has a remainder.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0163','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Find the common factors of 16 and 24.','["1, 2, 4, 8","1, 2, 3, 4","1, 2, 8","1, 4, 8, 12"]',0,'List both sets.','Factors 16: 1,2,4,8,16. Factors 24: 1,2,3,4,6,8,12,24. Common: 1,2,4,8.','2026-10-30 17:34:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0164','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Find the common factors of 10 and 15.','["1, 5","1, 2, 5","1, 3, 5","5, 10"]',0,'Matches.','Factors 10: 1,2,5,10. Factors 15: 1,3,5,15. Common: 1,5.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0165','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'If two numbers have only 1 as a common factor, what are they called?','["Coprime (or relatively prime)","Prime numbers","Composite numbers","Twins"]',0,'No other shared divisors.','If 1 is the only common factor, they share no other factors.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0166','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Which of these is a common factor of 14 and 21?','["7","2","3","14"]',0,'Check times tables.','Both are in the 7 times table.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0167','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'How many common factors do 9 and 15 have?','["Two (1 and 3)","One","Three","Four"]',0,'List them.','Factors 9: 1,3,9. Factors 15: 1,3,5,15. Common: 1, 3.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0168','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',5,'Is 4 a common factor of 12 and 18?','["No, 18 is not divisible by 4.","Yes, both are even.","Only of 18.","Yes, 4x3=12."]',0,'Check 18.','18/4 has a remainder.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0169','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Analyze: What are the common factors of three numbers: 12, 18, and 30?','["1, 2, 3, 6","1, 2, 3","6, 12","1, 6"]',0,'Check all lists.','Factors must divide ALL three numbers exactly.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0170','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Critique the mistake: ''Finding common factors of only two numbers when the question gives three.''','["A common factor must divide ALL given numbers exactly; missing one changes the result.","It is correct.","Three numbers don''t have common factors.","You just add them."]',0,'Check all numbers.','A common factor must be common to the entire set.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0171','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Synthesize: If a and b are distinct prime numbers, what are their common factors?','["Only 1","Their product","a and b","0"]',0,'What do primes share?','Primes only share 1 as a factor.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0172','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Evaluate: Can a common factor of two numbers be equal to the difference between the two numbers?','["Yes, e.g., common factor 10 for 20 and 30.","No, never.","Only for primes.","Always."]',0,'Think of 20 and 30.','Yes, common factors can equal the difference.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0173','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Critique: ''The common factors of an even and an odd number are always just 1.''','["False, e.g., 6 and 9 share a common factor of 3.","True.","False, they always share 2.","True, because one is even."]',0,'Think of 6 and 9.','They can share odd factors.','2026-10-30 17:34:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0174','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Synthesize: If two numbers share a common factor of 10, what else must be true about those numbers?','["They both end in 0.","They are both prime.","They both end in 5.","They are equal."]',0,'Divisibility rule for 10.','Multiples of 10 end in 0.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0175','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Analyze: What are the common factors of three numbers: 12, 18, and 30?','["1, 2, 3, 6","1, 2, 3","6, 12","1, 6"]',0,'Check all lists.','Factors must divide ALL three numbers exactly.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0176','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Critique the mistake: ''Finding common factors of only two numbers when the question gives three.''','["A common factor must divide ALL given numbers exactly; missing one changes the result.","It is correct.","Three numbers don''t have common factors.","You just add them."]',0,'Check all numbers.','A common factor must be common to the entire set.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0177','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Synthesize: If a and b are distinct prime numbers, what are their common factors?','["Only 1","Their product","a and b","0"]',0,'What do primes share?','Primes only share 1 as a factor.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0178','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Evaluate: Can a common factor of two numbers be equal to the difference between the two numbers?','["Yes, e.g., common factor 10 for 20 and 30.","No, never.","Only for primes.","Always."]',0,'Think of 20 and 30.','Yes, common factors can equal the difference.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0179','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Critique: ''The common factors of an even and an odd number are always just 1.''','["False, e.g., 6 and 9 share a common factor of 3.","True.","False, they always share 2.","True, because one is even."]',0,'Think of 6 and 9.','They can share odd factors.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0180','Maths','Factors, Multiples and Divisibility','Subtopic 5: Common factors','Primary',10,'Synthesize: If two numbers share a common factor of 10, what else must be true about those numbers?','["They both end in 0.","They are both prime.","They both end in 5.","They are equal."]',0,'Divisibility rule for 10.','Multiples of 10 end in 0.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0181','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'What are ''common multiples''?','["Multiples that are shared by two or more numbers.","Multiples that are boring.","Factors.","Remainders."]',0,'Shared multiples.','Common multiples appear in the multiples lists of two or more numbers.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0182','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'If multiples of 4 are 4, 8, 12, 16, 20, 24... and multiples of 6 are 6, 12, 18, 24... What are some common multiples?','["12, 24","4, 6","8, 18","2, 3"]',0,'Find the matching numbers.','12 and 24 appear in both lists.','2026-10-30 17:34:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0183','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'Is 10 a common multiple of 2 and 5?','["Yes, 2x5=10 and 5x2=10.","No.","Only of 5.","Only of 2."]',0,'Check times tables.','10 is in both multiples lists.','2026-10-30 17:34:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0184','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'Is 15 a common multiple of 3 and 4?','["No, 15 is not a multiple of 4.","Yes","Yes, 3x5=15.","Maybe"]',0,'Check 4 times table.','4x3=12, 4x4=16. 15 is skipped.','2026-10-30 17:34:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0185','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'Is 24 a common multiple of 8 and 12?','["Yes, 8x3=24 and 12x2=24.","No.","Only of 8.","Only of 12."]',0,'Check times tables.','It appears in both lists.','2026-10-30 17:34:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0186','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'Are common multiples infinite?','["Yes, they continue without end (12, 24, 36...).","No","Only for even numbers","Only for primes"]',0,'They go on forever.','Multiples continue indefinitely.','2026-10-30 17:34:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0187','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',1,'What are ''common multiples''?','["Multiples that are shared by two or more numbers.","Multiples that are boring.","Factors.","Remainders."]',0,'Shared multiples.','Common multiples appear in the multiples lists of two or more numbers.','2026-10-30 17:34:13',NULL,NULL);
