INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0193','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'What is the second common multiple of 4 and 6?','["24","12","36","48"]',0,'Multiply the first common multiple by 2.','First is 12 (LCM), second is 12x2 = 24.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0194','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'Which of these is a common multiple of 5 and 10?','["20","15","25","5"]',0,'Ends in 0.','20 is a multiple of both 5 and 10.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0195','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'Find a common multiple of 3, 4, and 6.','["12","6","8","24"]',0,'Must be in all lists.','12 is in all three lists.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0196','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'If a number is a common multiple of 2 and 3, it must also be a multiple of what?','["6","5","12","2"]',0,'Multiply them.','Because 2x3=6, any common multiple of 2 and 3 is a multiple of 6.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0197','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'Is 30 a common multiple of 5 and 6?','["Yes, 5x6=30.","No, only of 5.","No, only of 6.","No."]',0,'Check times tables.','It is in both times tables.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0198','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'How do you find common multiples quickly?','["List the multiples of the larger number and check if the smaller number divides them.","Add the numbers.","Subtract the numbers.","Guess."]',0,'Use the bigger number.','Start with the bigger jumps to save time.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0199','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'What is the second common multiple of 4 and 6?','["24","12","36","48"]',0,'Multiply the first common multiple by 2.','First is 12 (LCM), second is 12x2 = 24.','2026-10-30 17:34:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0200','Maths','Factors, Multiples and Divisibility','Subtopic 6: Common multiples','Primary',5,'Which of these is a common multiple of 5 and 10?','["20","15","25","5"]',0,'Ends in 0.','20 is a multiple of both 5 and 10.','2026-10-30 17:34:14',NULL,NULL);
