INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0225','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',1,'What is the HCF of 12 and 18 based on their common factors (1, 2, 3, 6)?','["6","1","3","12"]',0,'Find the biggest one.','The greatest number in the common factors list is 6.','2026-10-30 17:34:17',NULL,NULL);
