INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0229','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'What is the HCF of 16 and 24?','["8","4","12","16"]',0,'Largest match.','The common factors are 1, 2, 4, 8. The greatest is 8.','2026-10-30 17:34:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0230','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'Find the HCF of 20 and 30.','["10","5","20","30"]',0,'Largest match.','Factors 20: 1,2,4,5,10,20. Factors 30: 1,2,3,5,6,10,15,30. HCF is 10.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0231','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'What is the HCF of 12, 18, and 30?','["6","2","3","12"]',0,'Must divide ALL THREE.','Common to all three: 1, 2, 3, 6. Greatest is 6.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0232','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'Find the HCF of 8 and 12.','["4","2","6","8"]',0,'Largest match.','Factors 8: 1,2,4,8. Factors 12: 1,2,3,4,6,12. HCF is 4.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0233','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'What is the HCF of 9 and 15?','["3","1","5","9"]',0,'Largest match.','Factors 9: 1,3,9. Factors 15: 1,3,5,15. HCF is 3.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0234','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'If a teacher wants to pack 12 apples and 18 oranges into identical packs, she uses the HCF. How many packs?','["6","5","7","1"]',0,'Equal grouping.','HCF is 6.','2026-10-30 17:34:18',NULL,NULL);
