INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0236','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'Find the HCF of 20 and 30.','["10","5","20","30"]',0,'Largest match.','Factors 20: 1,2,4,5,10,20. Factors 30: 1,2,3,5,6,10,15,30. HCF is 10.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0237','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'What is the HCF of 12, 18, and 30?','["6","2","3","12"]',0,'Must divide ALL THREE.','Common to all three: 1, 2, 3, 6. Greatest is 6.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0238','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'Find the HCF of 8 and 12.','["4","2","6","8"]',0,'Largest match.','Factors 8: 1,2,4,8. Factors 12: 1,2,3,4,6,12. HCF is 4.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0239','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'What is the HCF of 9 and 15?','["3","1","5","9"]',0,'Largest match.','Factors 9: 1,3,9. Factors 15: 1,3,5,15. HCF is 3.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0240','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',5,'If a teacher wants to pack 12 apples and 18 oranges into identical packs, she uses the HCF. How many packs?','["6","5","7","1"]',0,'Equal grouping.','HCF is 6.','2026-10-30 17:34:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0241','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Evaluate: Why is HCF useful for ''equal grouping'' word problems?','["It finds the greatest number of identical groups you can make using all items without leftovers.","It finds when events repeat.","It tells you the total number of items.","It multiplies the items."]',0,'Think of packing fruit.','HCF divides all quantities exactly, maximizing the number of groups.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0242','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Analyze the difference between HCF and LCM.','["HCF finds the greatest shared factor (divides into), LCM finds the least positive shared multiple (multiplies up to).","HCF finds the smallest multiple, LCM finds the largest factor.","They are the same.","HCF is for addition."]',0,'Divides vs Multiplies.','Factors go IN, Multiples GROW.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0243','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Synthesize: If the HCF of a and b is b, what is the relationship between a and b?','["b is a factor of a (a is a multiple of b).","b is a multiple of a.","They are equal.","They are prime."]',0,'Think of HCF(12, 6) = 6.','If b divides a exactly, then b is a factor of a, and the greatest factor of b is b itself.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0244','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'A baker has 28 plain rolls and 42 seeded rolls. Greatest number of identical packs?','["14","7","21","28"]',0,'Find HCF(28,42).','Factors 28: 1,2,4,7,14,28. Factors 42: 1,2,3,6,7,14,21,42. HCF = 14.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0245','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Analyze: What is the HCF of two distinct prime numbers?','["1","Their product","0","The larger prime"]',0,'What do primes share?','Primes only share 1 as a factor.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0246','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Synthesize: Find the HCF of 36 and 48 using prime factorisation (36=2^2x3^2, 48=2^4x3).','["12","6","24","144"]',0,'Smallest powers.','Take common primes with smallest powers: 2^2 x 3 = 4 x 3 = 12.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0247','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Evaluate: Why is HCF useful for ''equal grouping'' word problems?','["It finds the greatest number of identical groups you can make using all items without leftovers.","It finds when events repeat.","It tells you the total number of items.","It multiplies the items."]',0,'Think of packing fruit.','HCF divides all quantities exactly, maximizing the number of groups.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0248','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Analyze the difference between HCF and LCM.','["HCF finds the greatest shared factor (divides into), LCM finds the least positive shared multiple (multiplies up to).","HCF finds the smallest multiple, LCM finds the largest factor.","They are the same.","HCF is for addition."]',0,'Divides vs Multiplies.','Factors go IN, Multiples GROW.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0249','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Synthesize: If the HCF of a and b is b, what is the relationship between a and b?','["b is a factor of a (a is a multiple of b).","b is a multiple of a.","They are equal.","They are prime."]',0,'Think of HCF(12, 6) = 6.','If b divides a exactly, then b is a factor of a, and the greatest factor of b is b itself.','2026-10-30 17:34:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0250','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'A baker has 28 plain rolls and 42 seeded rolls. Greatest number of identical packs?','["14","7","21","28"]',0,'Find HCF(28,42).','Factors 28: 1,2,4,7,14,28. Factors 42: 1,2,3,6,7,14,21,42. HCF = 14.','2026-10-30 17:34:19',NULL,NULL);
