INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0252','Maths','Factors, Multiples and Divisibility','Subtopic 7: Highest common factor (HCF)','Primary',10,'Synthesize: Find the HCF of 36 and 48 using prime factorisation (36=2^2x3^2, 48=2^4x3).','["12","6","24","144"]',0,'Smallest powers.','Take common primes with smallest powers: 2^2 x 3 = 4 x 3 = 12.','2026-10-30 17:34:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0253','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',1,'What does LCM stand for?','["Least Common Multiple (smallest positive)","Largest Common Multiple","Last Common Multiple","Long Common Multiple"]',0,'Smallest one.','LCM is Least Common Multiple.','2026-10-30 17:34:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0254','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',1,'What is the LCM of 4 and 6 based on their common multiples (12, 24, 36)?','["12","4","6","24"]',0,'Smallest match.','The smallest positive common multiple is 12.','2026-10-30 17:34:20',NULL,NULL);
