INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0257','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',1,'Is 0 considered a multiple in primary school LCM problems?','["No, we look for the smallest POSITIVE common multiple.","Yes, it is the LCM.","Sometimes.","Always."]',0,'Look for positive numbers.','We list positive multiples to make comparisons easier.','2026-10-30 17:34:20',NULL,NULL);
