INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0272','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',5,'One alarm sounds every 4 mins, another every 6 mins. When will they next sound together?','["12 mins","10 mins","24 mins","2 mins"]',0,'Use LCM for repeating events.','LCM(4,6) = 12.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0273','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',5,'Runner A does a lap in 3 mins, Runner B in 5 mins. When will they complete laps together at the start?','["15 mins","8 mins","30 mins","2 mins"]',0,'Use LCM.','LCM(3,5) = 15.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0274','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',5,'Find the LCM of 4 and 10.','["20","14","40","2"]',0,'Smallest match.','Multiples 4: 4,8,12,16,20. Multiples 10: 10,20. Match is 20.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0275','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',5,'Find the LCM of 5 and 10.','["10","5","15","50"]',0,'10 is a multiple of 5.','Multiples 5: 5,10. Multiples 10: 10. Match is 10.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0276','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',5,'Is the LCM always greater than or equal to the largest of the given numbers?','["Yes","No","Only for primes","Sometimes"]',0,'Can a multiple be smaller?','A multiple must be at least as large as the number itself.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0277','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Evaluate: Why is LCM useful for ''repeating event'' word problems?','["It finds the earliest positive time or number at which repeating intervals coincide.","It finds the maximum size of groups.","It adds the intervals.","It finds the remainder."]',0,'Think of alarms or buses.','Schedules overlapping require finding shared multiples.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0278','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Analyze: What is the LCM of two distinct prime numbers?','["Their product.","Their sum.","1","0"]',0,'Multiply them.','Primes share no factors other than 1, so their LCM is their product (e.g., LCM(3,5)=15).','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0279','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Analyze the relationship: HCF(a,b) x LCM(a,b) = ?','["a x b","a + b","a / b","a - b"]',0,'Multiply them.','The product of HCF and LCM equals the product of the numbers.','2026-10-30 17:34:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0280','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Synthesize: Find the LCM of 6, 8, and 12.','["24","48","72","96"]',0,'Smallest match for all three.','Multiples 6: 24... 8: 24... 12: 24... LCM = 24.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0281','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Critique: ''The LCM of two even numbers is always their product.''','["False, e.g. LCM(4,6) = 12, not 24. They share a factor of 2, reducing the LCM.","True.","False, it is their sum.","True, but only above 10."]',0,'Think of 4 and 6.','Sharing a factor makes the LCM smaller than the product.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0282','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Synthesize: If LCM(x,y) = 20, and x = 4, what are possible values for y?','["5 or 20","5","10","2"]',0,'Test multiples of 5.','If y=5, LCM(4,5)=20. If y=20, LCM(4,20)=20.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0283','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Evaluate: Why is LCM useful for ''repeating event'' word problems?','["It finds the earliest positive time or number at which repeating intervals coincide.","It finds the maximum size of groups.","It adds the intervals.","It finds the remainder."]',0,'Think of alarms or buses.','Schedules overlapping require finding shared multiples.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0284','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Analyze: What is the LCM of two distinct prime numbers?','["Their product.","Their sum.","1","0"]',0,'Multiply them.','Primes share no factors other than 1, so their LCM is their product (e.g., LCM(3,5)=15).','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0285','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Analyze the relationship: HCF(a,b) x LCM(a,b) = ?','["a x b","a + b","a / b","a - b"]',0,'Multiply them.','The product of HCF and LCM equals the product of the numbers.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0286','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Synthesize: Find the LCM of 6, 8, and 12.','["24","48","72","96"]',0,'Smallest match for all three.','Multiples 6: 24... 8: 24... 12: 24... LCM = 24.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0287','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Critique: ''The LCM of two even numbers is always their product.''','["False, e.g. LCM(4,6) = 12, not 24. They share a factor of 2, reducing the LCM.","True.","False, it is their sum.","True, but only above 10."]',0,'Think of 4 and 6.','Sharing a factor makes the LCM smaller than the product.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0288','Maths','Factors, Multiples and Divisibility','Subtopic 8: Lowest common multiple (LCM)','Primary',10,'Synthesize: If LCM(x,y) = 20, and x = 4, what are possible values for y?','["5 or 20","5","10","2"]',0,'Test multiples of 5.','If y=5, LCM(4,5)=20. If y=20, LCM(4,20)=20.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0289','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'What does ''prime factorisation'' mean?','["Expressing a whole number as a product (multiplication) of prime numbers (e.g. 12 = 2x2x3).","Adding prime numbers.","Dividing by 1.","Listing all factors."]',0,'Building blocks.','Breaking a number down entirely into prime numbers.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0290','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'What tool can we use to break a number into prime factors?','["A factor tree","A ruler","A thermometer","A compass"]',0,'It has branches.','A factor tree breaks a number into smaller factors until they are all prime.','2026-10-30 17:34:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0291','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'What is the prime factorisation of 6?','["2 x 3","1 x 6","3 + 3","6 x 0"]',0,'Multiply two primes.','2 and 3 are prime, and 2x3=6.','2026-10-30 17:34:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0292','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'What is the prime factorisation of 4?','["2 x 2","1 x 4","2 + 2","4"]',0,'Multiply two primes.','2 is prime, and 2x2=4.','2026-10-30 17:34:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0293','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'Does the number 1 have a prime factorisation?','["No, because 1 is not a prime number.","Yes","Only on Mondays","Yes, 1x1"]',0,'1 is neither prime nor composite.','1 is not prime, so it has no prime factorisation.','2026-10-30 17:34:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0294','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',1,'How can you check if a prime factorisation is correct?','["Multiply the final prime factors together to see if they equal the original number.","Add the numbers.","Subtract them.","Guess."]',0,'Do the math.','Checking: 2x2x3 = 12.','2026-10-30 17:34:24',NULL,NULL);
