INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0301','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'What is the prime factorisation of 12?','["2 x 2 x 3","2 x 6","3 x 4","1 x 12"]',0,'All numbers must be prime.','6 and 4 are composite, so they must be broken down further into 2x2x3.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0302','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'What is the prime factorisation of 20?','["2 x 2 x 5","4 x 5","2 x 10","1 x 20"]',0,'All numbers must be prime.','4 and 10 are composite. Break down to 2x2x5.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0303','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'How do you write 2 x 2 x 3 using powers (exponents)?','["2^2 x 3","4 x 3","2^3","2 x 3^2"]',0,'Use the small raised number.','2 x 2 is written as 2^2.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0304','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 8.','["2 x 2 x 2 (or 2^3)","2 x 4","1 x 8","4^2"]',0,'All primes.','8 = 2 x 4 = 2 x 2 x 2.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0305','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 28.','["2 x 2 x 7 (or 2^2 x 7)","4 x 7","2 x 14","1 x 28"]',0,'All primes.','28 = 4x7 = 2x2x7.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0306','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 45.','["3 x 3 x 5 (or 3^2 x 5)","5 x 9","3 x 15","9 x 5"]',0,'All primes.','45 = 5x9 = 5x3x3.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0307','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'What is the prime factorisation of 12?','["2 x 2 x 3","2 x 6","3 x 4","1 x 12"]',0,'All numbers must be prime.','6 and 4 are composite, so they must be broken down further into 2x2x3.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0308','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'What is the prime factorisation of 20?','["2 x 2 x 5","4 x 5","2 x 10","1 x 20"]',0,'All numbers must be prime.','4 and 10 are composite. Break down to 2x2x5.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0309','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'How do you write 2 x 2 x 3 using powers (exponents)?','["2^2 x 3","4 x 3","2^3","2 x 3^2"]',0,'Use the small raised number.','2 x 2 is written as 2^2.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0310','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 8.','["2 x 2 x 2 (or 2^3)","2 x 4","1 x 8","4^2"]',0,'All primes.','8 = 2 x 4 = 2 x 2 x 2.','2026-10-30 17:34:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0311','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 28.','["2 x 2 x 7 (or 2^2 x 7)","4 x 7","2 x 14","1 x 28"]',0,'All primes.','28 = 4x7 = 2x2x7.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0312','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',5,'Find the prime factorisation of 45.','["3 x 3 x 5 (or 3^2 x 5)","5 x 9","3 x 15","9 x 5"]',0,'All primes.','45 = 5x9 = 5x3x3.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0313','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Critique the mistake: ''Stopping when a factor is composite instead of breaking it down further.''','["False; prime factorisation requires ALL final factors to be prime numbers (e.g. 12=3x4 is wrong, must be 3x2x2).","It''s correct.","True for even numbers.","True for odd numbers."]',0,'Don''t stop early.','You must keep branching the factor tree until you hit only primes.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0314','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Analyze: Why is prime factorisation unique to every composite number (Fundamental Theorem of Arithmetic)?','["Every composite number has exactly one unique set of prime factors (like a unique fingerprint or barcode).","It isn''t unique.","Because all numbers are prime.","Because 1 is a factor."]',0,'It''s a mathematical fingerprint.','No two numbers have the same prime factorisation.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0315','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Synthesize the prime factorisation of 60.','["2 x 2 x 3 x 5 (or 2^2 x 3 x 5)","6 x 10","2 x 30","3 x 20"]',0,'Break everything down.','60 = 6x10 = (2x3)x(2x5) = 2x2x3x5.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0316','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Evaluate the use of Repeated Division to find prime factors for 24.','["Divide by smallest prime 2 (12), then 2 (6), then 2 (3), then 3 (1). Result: 2x2x2x3.","Divide by 4, then 6.","Divide by 24.","Divide by 8, then 3."]',0,'Ladder method.','Keep dividing by the smallest possible prime until you reach 1.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0317','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Analyze the error: Confusing 2^3 with 2 x 3.','["2^3 means 2x2x2 (8), while 2x3 means 2+2+2 (6). Exponents are repeated multiplication.","They are the same (6).","2^3 is 5.","2^3 is smaller."]',0,'Power vs multiply.','Exponents mean multiply the base by itself.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0318','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Critique the assertion: ''Every number needs at least two prime factors.''','["False; a prime number (like 13) is already prime and has only one prime factor (itself).","True.","True, except 0.","True, except 1."]',0,'Look at 13.','Primes don''t need to be broken down.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0319','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Critique the mistake: ''Stopping when a factor is composite instead of breaking it down further.''','["False; prime factorisation requires ALL final factors to be prime numbers (e.g. 12=3x4 is wrong, must be 3x2x2).","It''s correct.","True for even numbers.","True for odd numbers."]',0,'Don''t stop early.','You must keep branching the factor tree until you hit only primes.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0320','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Analyze: Why is prime factorisation unique to every composite number (Fundamental Theorem of Arithmetic)?','["Every composite number has exactly one unique set of prime factors (like a unique fingerprint or barcode).","It isn''t unique.","Because all numbers are prime.","Because 1 is a factor."]',0,'It''s a mathematical fingerprint.','No two numbers have the same prime factorisation.','2026-10-30 17:34:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0321','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Synthesize the prime factorisation of 60.','["2 x 2 x 3 x 5 (or 2^2 x 3 x 5)","6 x 10","2 x 30","3 x 20"]',0,'Break everything down.','60 = 6x10 = (2x3)x(2x5) = 2x2x3x5.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0322','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Evaluate the use of Repeated Division to find prime factors for 24.','["Divide by smallest prime 2 (12), then 2 (6), then 2 (3), then 3 (1). Result: 2x2x2x3.","Divide by 4, then 6.","Divide by 24.","Divide by 8, then 3."]',0,'Ladder method.','Keep dividing by the smallest possible prime until you reach 1.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0323','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Analyze the error: Confusing 2^3 with 2 x 3.','["2^3 means 2x2x2 (8), while 2x3 means 2+2+2 (6). Exponents are repeated multiplication.","They are the same (6).","2^3 is 5.","2^3 is smaller."]',0,'Power vs multiply.','Exponents mean multiply the base by itself.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0324','Maths','Factors, Multiples and Divisibility','Subtopic 9: Prime factorisation — introductory','Primary',10,'Critique the assertion: ''Every number needs at least two prime factors.''','["False; a prime number (like 13) is already prime and has only one prime factor (itself).","True.","True, except 0.","True, except 1."]',0,'Look at 13.','Primes don''t need to be broken down.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0325','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',1,'If a problem asks ''How many equal groups can be made without leftovers?'', should you use factors or multiples?','["Factors","Multiples","Addition","Fractions"]',0,'Dividing exactly.','Factors divide into equal groups with no leftovers.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0326','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',1,'If a problem asks ''When will repeating events (like alarms) happen together again?'', should you use factors or multiples?','["Multiples","Factors","Subtraction","Decimals"]',0,'Events rolling forward.','Multiples help with repeating schedules.','2026-10-30 17:34:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0327','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',1,'Can you share 30 pencils equally among 5 students with NO leftovers?','["Yes, 6 each","No","Yes, 5 each","No, 2 remain"]',0,'Divisibility by 5.','30 / 5 = 6 exactly.','2026-10-30 17:34:27',NULL,NULL);
