INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0337','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',5,'A school has 24 chairs to arrange in equal rows. Can they make 5 equal rows?','["No, 24 is not divisible by 5.","Yes","Yes, 4 per row.","Yes, 5 per row."]',0,'Check factors of 24.','24 / 5 has a remainder.','2026-10-30 17:34:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0338','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',5,'A warehouse has 468 bottles. Can they be packed in boxes of 6 with no leftovers?','["Yes, divisible by 2 and 3.","No.","Only boxes of 5.","Only boxes of 10."]',0,'Rule for 6.','468 is even (2) and 4+6+8=18 (3). So yes.','2026-10-30 17:34:28',NULL,NULL);
