INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0351','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',10,'Analyze: One bus arrives every 10 mins, another every 15 mins. Next together?','["30 mins","5 mins","15 mins","150 mins"]',0,'Find LCM.','LCM(10,15) = 30.','2026-10-30 17:34:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0352','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',10,'Critique the mistake: ''Choosing LCM when the question asks for the largest number of equal groups.''','["False, HCF is for dividing into groups, LCM is for repeating events.","Correct.","True for odd.","True for even."]',0,'Don''t mix them up.','HCF = Groups. LCM = Events.','2026-10-30 17:34:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t3_global_0353','Maths','Factors, Multiples and Divisibility','Subtopic 10: Real-life applications of factors and multiples','Primary',10,'Evaluate: If a problem says ''using ALL items without leftovers'', what math concept is absolutely required?','["Exact Divisibility (Factors).","Estimation.","Multiplication.","Decimals."]',0,'No remainders.','Leftovers mean a remainder, so exact factors are needed.','2026-10-30 17:34:30',NULL,NULL);
