INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0098','Maths','Fractions','Subtopic 3: Equivalent Fractions','Primary',10,'Analyze: Why does multiplying the numerator and denominator by the same non-zero number create an equivalent fraction?','["Because you are multiplying the fraction by 1 (e.g., 3/3 = 1), which preserves its value.","Because the numbers get bigger.","Because it creates a proper fraction.","It actually changes the value."]',0,'Identity property.','Multiplying by n/n is multiplying by 1.','2026-10-30 17:34:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0099','Maths','Fractions','Subtopic 3: Equivalent Fractions','Primary',10,'Charlie claims that 3/7 is equivalent to 5/9. Is this correct?','["No, adding the same number to both changes the value of the fraction.","Yes, adding maintains equivalence.","Only if they are even.","Only if they are odd."]',0,'Addition breaks equivalence.','You must multiply or divide, not add, to keep equivalence.','2026-10-30 17:34:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0100','Maths','Fractions','Subtopic 3: Equivalent Fractions','Primary',10,'Check if 20/45 is equivalent to 8/18.','["Yes, they both simplify to {n}/{d}.","No.","Yes, but they are improper.","Cannot be checked."]',0,'Simplify both.','Both simplify to the same base fraction.','2026-10-30 17:34:51',NULL,NULL);
