INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0102','Maths','Fractions','Subtopic 3: Equivalent Fractions','Primary',10,'Are 1/4 and 7/29 equivalent?','["No, because the denominator was not multiplied by exactly 7.","Yes, they are close.","Yes, they are the same.","Only in decimals."]',0,'Check the multiplication.','Must be the EXACT same multiplier for both.','2026-10-30 17:34:51',NULL,NULL);
