INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0118','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',1,'Simplify 3/6 by dividing both numbers by 3.','["1/2","1/3","2/3","3/4"]',0,'Divide by 3.','3/3=1, 6/3=2.','2026-10-30 17:34:53',NULL,NULL);
