INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0125','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',5,'Is the fraction 5/15 in lowest terms? (Assume no common factors).','["Yes, if they share no common factors other than 1.","Depends on the numbers","No, it can be divided.","Always no."]',1,'Check for common factors.','A fraction is in lowest terms when numerator and denominator have no common factor > 1.','2026-10-30 17:34:54',NULL,NULL);
