INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0132','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',5,'Simplify 14/49.','["2/7","4/14","1/7","2/1"]',0,'Divide by 7.','Divide both by 7.','2026-10-30 17:34:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0133','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Can the fraction 3/5 be simplified further?','["No, it is already in its lowest terms.","Yes, by dividing by 2.","Yes, by dividing by 3.","Yes, by subtracting 1."]',1,'Look for common factors.','3 and 5 share no common factors other than 1.','2026-10-30 17:34:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0134','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Use the Greatest Common Factor (GCF) to simplify 60/84.','["5/7","10/14","15/21","20/28"]',0,'Find the GCF first.','The GCF is 12. Dividing both by 12 gives the lowest terms.','2026-10-30 17:34:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0135','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Critique: ''Charlie simplified 16/24 to 8/12 and stopped, claiming it is in lowest terms.''','["Incorrect; 8 and 12 still share a common factor of 4, so it simplifies further to 2/3.","Correct.","Incorrect, it simplifies to 4/6 and stops.","Incorrect, it simplifies to 1/2."]',1,'Can 8 and 12 be divided again?','Must divide until NO common factors remain.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0136','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Synthesize the simplest form of 165/195.','["11/13","33/39","55/65","1/13"]',0,'Divide by 15.','Divide both by the GCF, 15.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0137','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Evaluate: Does simplifying a fraction change its mathematical value?','["No, it writes an equivalent fraction using smaller numbers, preserving the exact value.","Yes, it makes it smaller.","Yes, it makes it larger.","Only for improper fractions."]',1,'Does 1/2 pizza equal 2/4 pizza?','Simplifying just changes the description, not the amount.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0138','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Analyze: What is the quickest way to simplify 408/456 in one step?','["Divide the numerator and denominator by their Greatest Common Factor (24).","Divide by 2 repeatedly.","Divide by 3.","Divide by 4."]',1,'Find the GCF.','Using the GCF simplifies it in exactly one step.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0139','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Can the fraction 19/21 be simplified further?','["No, it is already in its lowest terms.","Yes, by dividing by 2.","Yes, by dividing by 3.","Yes, by subtracting 1."]',1,'Look for common factors.','19 and 21 share no common factors other than 1.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0140','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Use the Greatest Common Factor (GCF) to simplify 276/300.','["23/25","46/50","69/75","92/100"]',0,'Find the GCF first.','The GCF is 12. Dividing both by 12 gives the lowest terms.','2026-10-30 17:34:55',NULL,NULL);
