INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0142','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Synthesize the simplest form of 465/495.','["31/33","93/99","155/165","1/33"]',0,'Divide by 15.','Divide both by the GCF, 15.','2026-10-30 17:34:55',NULL,NULL);
