INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0144','Maths','Fractions','Subtopic 4: Simplifying Fractions to Lowest Terms','Primary',10,'Analyze: What is the quickest way to simplify 984/1032 in one step?','["Divide the numerator and denominator by their Greatest Common Factor (24).","Divide by 2 repeatedly.","Divide by 3.","Divide by 4."]',1,'Find the GCF.','Using the GCF simplifies it in exactly one step.','2026-10-30 17:34:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0145','Maths','Fractions','Subtopic 5: Comparing and Ordering Fractions','Primary',1,'Which fraction is greater: 1/20 or 2/20?','["2/20","1/20","They are equal","Cannot compare"]',0,'Look at the top number.','Since the denominators are the same, 2 is greater than 1.','2026-10-30 17:34:56',NULL,NULL);
