INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0189','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',1,'Where is 0 located on a number line for positive fractions?','["At the very beginning (far left).","In the middle.","At the end.","At 1."]',0,'Far left.','Counting for positive fractions starts at 0 on the left.','2026-10-30 17:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0190','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',1,'If a number line has 8 equal parts between 0 and 1, what fraction is at the very last mark (at 1)?','["8/8","7/8","1/8","0"]',0,'Same top and bottom.','All parts are counted, so 8/8, which equals 1.','2026-10-30 17:35:01',NULL,NULL);
