INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0192','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',1,'What fraction does the 3rd mark represent on a line divided into 10 parts?','["3/10","1/10","10/3","2/10"]',0,'Top number is the mark count.','Third mark means numerator is 3.','2026-10-30 17:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0193','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'On a number line from 0 to 1 divided into 3 equal parts, where is 1/3 located?','["At the 1th mark after 0","At the 3th mark","Past the number 1","At 0"]',0,'The top number tells you how many steps.','The numerator 1 tells you to count 1 marks from 0.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0194','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Are 2/5 and 4/10 located at the same point on a number line?','["Yes, because they are equivalent fractions representing the same value.","No, one is farther right.","No, one is past 1.","Cannot tell."]',0,'They are the same amount.','Equivalent fractions share the exact same position.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0195','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Which fraction is farther to the right on a number line: 3/7 or 4/7?','["4/7","3/7","They are at the same place","Cannot tell"]',0,'Greater numbers go right.','Fractions further to the right are greater. 4/7 > 3/7.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0196','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'If Diana places 4/11 and 6/11 on a number line, which is closer to 0?','["4/11","6/11","They are equal distance","Neither"]',0,'Smaller goes left.','Smaller fractions are closer to 0.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0197','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'If the interval 0 to 1 is divided into 14 parts, what mark is exactly halfway?','["7/14","1/14","14/14","6/14"]',0,'Find half of the total parts.','Half of 14 is 7, so it is at 7/14.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0198','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Locate 1 whole on a number line divided into 9 parts.','["At the 9th mark (9/9)","At the 1st mark","At the 4th mark","Past the line"]',0,'Same top and bottom.','1 whole is when all parts are counted.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0199','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'On a number line from 0 to 1 divided into 6 equal parts, where is 2/6 located?','["At the 2th mark after 0","At the 6th mark","Past the number 1","At 0"]',0,'The top number tells you how many steps.','The numerator 2 tells you to count 2 marks from 0.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0200','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Are 3/8 and 6/16 located at the same point on a number line?','["Yes, because they are equivalent fractions representing the same value.","No, one is farther right.","No, one is past 1.","Cannot tell."]',0,'They are the same amount.','Equivalent fractions share the exact same position.','2026-10-30 17:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0201','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Which fraction is farther to the right on a number line: 4/6 or 5/6?','["5/6","4/6","They are at the same place","Cannot tell"]',0,'Greater numbers go right.','Fractions further to the right are greater. 5/6 > 4/6.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0202','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'If Julia places 5/10 and 7/10 on a number line, which is closer to 0?','["5/10","7/10","They are equal distance","Neither"]',0,'Smaller goes left.','Smaller fractions are closer to 0.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0203','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'If the interval 0 to 1 is divided into 10 parts, what mark is exactly halfway?','["5/10","1/10","10/10","4/10"]',0,'Find half of the total parts.','Half of 10 is 5, so it is at 5/10.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0204','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',5,'Locate 1 whole on a number line divided into 12 parts.','["At the 12th mark (12/12)","At the 1st mark","At the 7th mark","Past the line"]',0,'Same top and bottom.','1 whole is when all parts are counted.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0205','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Where would you place the improper fraction 4/3 on a number line?','["Beyond the whole number 1, to the right.","Between 0 and 1","Exactly at 0","Exactly at 1"]',0,'Compare the top and bottom numbers.','Because 4 > 3, the value is greater than 1.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0206','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Synthesize the location of the mixed number 2 2/5 on a number line.','["Between the whole numbers 2 and 3, at the 2th mark out of 5.","Between 1 and 2.","Beyond 3.","At exactly 2."]',0,'Look at the whole number part.','It is 2 wholes PLUS 2/5, so it falls between 2 and 3.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0207','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Analyze: How many 7ths do you need to count from 0 to reach the number 3?','["21","7","3","10"]',0,'Multiply the whole number by the denominator.','Each whole number has 7 parts. 3 wholes x 7 = 21.','2026-10-30 17:35:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0208','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Critique: ''Diana says 9/9 is located farther right than 10/9.''','["False, 10/9 is an improper fraction > 1, so it is farther right.","True, because 9/9 is a whole.","True, 9/9 is larger.","False, they are in the same spot."]',0,'Improper fractions are bigger than 1.','10 > 9, so it goes further right.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0209','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Evaluate the position of 10/14 compared to 5/7 on an extended number line.','["They are located at the exact same point.","10/14 is farther right.","5/7 is farther right.","One is negative."]',0,'Check if they are equivalent.','Equivalent fractions map to the same mathematical point.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0210','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Synthesize: If you start at 1 and move right by 1/4, what improper fraction are you at?','["5/4","1/4","2/4","1/4"]',0,'Convert 1 to a fraction first.','1 is 4/4. 4/4 + 1/4 = 5/4.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0211','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Where would you place the improper fraction 8/6 on a number line?','["Beyond the whole number 1, to the right.","Between 0 and 1","Exactly at 0","Exactly at 1"]',0,'Compare the top and bottom numbers.','Because 8 > 6, the value is greater than 1.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0212','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Synthesize the location of the mixed number 2 3/8 on a number line.','["Between the whole numbers 2 and 3, at the 3th mark out of 8.","Between 1 and 2.","Beyond 3.","At exactly 2."]',0,'Look at the whole number part.','It is 2 wholes PLUS 3/8, so it falls between 2 and 3.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0213','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Analyze: How many 6ths do you need to count from 0 to reach the number 3?','["18","6","3","9"]',0,'Multiply the whole number by the denominator.','Each whole number has 6 parts. 3 wholes x 6 = 18.','2026-10-30 17:35:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0214','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Critique: ''Julia says 8/8 is located farther right than 9/8.''','["False, 9/8 is an improper fraction > 1, so it is farther right.","True, because 8/8 is a whole.","True, 8/8 is larger.","False, they are in the same spot."]',0,'Improper fractions are bigger than 1.','9 > 8, so it goes further right.','2026-10-30 17:35:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0215','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Evaluate the position of 2/10 compared to 1/5 on an extended number line.','["They are located at the exact same point.","2/10 is farther right.","1/5 is farther right.","One is negative."]',0,'Check if they are equivalent.','Equivalent fractions map to the same mathematical point.','2026-10-30 17:35:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0216','Maths','Fractions','Subtopic 6: Fractions on a Number Line','Primary',10,'Synthesize: If you start at 1 and move right by 2/7, what improper fraction are you at?','["9/7","2/7","3/7","1/7"]',0,'Convert 1 to a fraction first.','1 is 7/7. 7/7 + 2/7 = 9/7.','2026-10-30 17:35:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0217','Maths','Fractions','Subtopic 7: Adding Fractions with Like Denominators','Primary',1,'What is 1/30 + 1/30?','["2/30","1/60","2/60","1/30"]',0,'Add the top numbers only.','Add the numerators: 1 + 1 = 2, keep the denominator 30.','2026-10-30 17:35:05',NULL,NULL);
