INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0270','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Find the difference: 3/6 - 1/6. Simplify.','["2/6 simplifies to 1/3","2/0","1/2","1/6"]',0,'Simplify.','3 - 1 = 2. 2/6 = 1/3.','2026-10-30 17:35:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0271','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Calculate 5/10 - 2/10. What is the answer?','["3/10","3/0","1/10","3/20"]',0,'Subtract numerators.','Numerators: 5 - 2 = 3. 3/10.','2026-10-30 17:35:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0272','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Subtract and simplify: 7/8 - 3/8.','["4/8 simplifies to 1/2","4/0","1/4","4/16"]',0,'Simplify the result.','7 - 3 = 4. 4/8 simplifies to 1/2.','2026-10-30 17:35:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0273','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'What happens if you subtract a fraction from itself? (e.g. 4/7 - 4/7)','["0","1","4/0","8/7"]',0,'Nothing remains.','Taking the whole amount away leaves zero.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0274','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Julia has 7/8 of a chocolate bar. They give away 5/8. How much is left?','["2/8","2/0","12/8","0"]',0,'Subtract.','7 - 5 = 2.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0275','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Calculate 7/12 - 1/12 and simplify.','["6/12 simplifies to 1/2","6/0","1/6","1/4"]',0,'Simplify.','7 - 1 = 6. 6/12 = 1/2.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0276','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',5,'Find the difference: 4/6 - 2/6. Simplify.','["2/6 simplifies to 1/3","2/0","1/2","1/6"]',0,'Simplify.','4 - 2 = 2. 2/6 = 1/3.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0277','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Calculate: 1 whole - 1/15','["14/15","1/15","1/15","14/0"]',0,'Change 1 whole into a fraction.','1 whole is 15/15. 15/15 - 1/15 = 14/15.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0278','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'A route is 1 km long. Bob walks 2/5 km. What fraction remains?','["3/5 km","2/5 km","3/1 km","0 km"]',0,'1 whole is d/d.','1 = 5/5. 5/5 - 2/5 = 3/5.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0279','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Critique: ''Charlie calculated 10/12 - 3/12 = 7/0.''','["False, the denominator must stay unchanged (12).","True.","False, it should be 7/24.","False, you add them."]',0,'Denominators stay the same.','Never subtract the denominators.','2026-10-30 17:35:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0280','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Evaluate: 2 wholes - 4/9.','["1 5/9","-2/9","1 4/9","2 4/9"]',0,'Borrow 1 whole.','2 = 1 + 9/9. 1 9/9 - 4/9 = 1 5/9.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0281','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Synthesize: Ethan starts with 12/8 of a pie, eats 5/8, and gives away 2/8. How much is left?','["5/8","7/8","9/8","0"]',0,'Subtract both amounts.','12 - 5 - 2 = 5.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0282','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Analyze: What is the missing number? X/10 - 1/10 = 3/10','["4","2","3","1"]',0,'Work backwards.','X - 1 = 3, so X = 4.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0283','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Calculate: 1 whole - 2/15','["13/15","2/15","1/15","13/0"]',0,'Change 1 whole into a fraction.','1 whole is 15/15. 15/15 - 2/15 = 13/15.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0284','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'A route is 1 km long. Hannah walks 3/8 km. What fraction remains?','["5/8 km","3/8 km","5/1 km","0 km"]',0,'1 whole is d/d.','1 = 8/8. 8/8 - 3/8 = 5/8.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0285','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Critique: ''Ian calculated 10/12 - 4/12 = 6/0.''','["False, the denominator must stay unchanged (12).","True.","False, it should be 6/24.","False, you add them."]',0,'Denominators stay the same.','Never subtract the denominators.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0286','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Evaluate: 2 wholes - 5/8.','["1 3/8","-3/8","1 5/8","2 5/8"]',0,'Borrow 1 whole.','2 = 1 + 8/8. 1 8/8 - 5/8 = 1 3/8.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0287','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Synthesize: Kevin starts with 6/8 of a pie, eats 1/8, and gives away 2/8. How much is left?','["3/8","5/8","7/8","0"]',0,'Subtract both amounts.','6 - 1 - 2 = 3.','2026-10-30 17:35:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0288','Maths','Fractions','Subtopic 8: Subtracting Fractions with Like Denominators','Primary',10,'Analyze: What is the missing number? X/10 - 2/10 = 3/10','["5","1","3","2"]',0,'Work backwards.','X - 2 = 3, so X = 5.','2026-10-30 17:35:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0289','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',1,'To add 1/2 and 1/5, what is the first step?','["Find a common denominator.","Add the numerators immediately.","Add the denominators immediately.","Subtract them."]',0,'Look at the denominators.','Unlike fractions must share a common denominator before adding.','2026-10-30 17:35:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0290','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',1,'Why can''t you just add the numerators of 1/3 and 1/4 directly?','["Because the denominators (the sizes of the parts) are different.","Because they are unit fractions.","Because you can never add fractions.","Because the numbers are too small."]',0,'Unequal parts.','You can only add parts that are the same size.','2026-10-30 17:35:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0291','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',1,'What is a ''common denominator''?','["A multiple shared by both original denominators.","A factor.","The top number.","A fraction."]',0,'Shared multiple.','It''s a common multiple of the bottom numbers.','2026-10-30 17:35:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0292','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',1,'If you need to add 1/2 and 1/5, which number could be a common denominator?','["10","2","5","7"]',0,'Multiply 2 and 5.','10 is a multiple of both 2 and 5.','2026-10-30 17:35:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0293','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',1,'To subtract 1/3 from 1/2, do you need a common denominator?','["Yes","No","Only for addition","Only for multiplying"]',0,'Same rule as addition.','Both addition and subtraction require common denominators.','2026-10-30 17:35:15',NULL,NULL);
