INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0314','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Critique: ''Bob added 1/3 and 1/4 and got 2/7.''','["False, they added numerators and denominators. It should be 7/12.","True.","False, it should be 1/12.","False, it should be 2/12."]',0,'Never add denominators.','1/3 = 4/12, 1/4 = 3/12. 4/12 + 3/12 = 7/12.','2026-10-30 17:35:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0315','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Synthesize: Charlie reads 2/5 of a book on Monday and 1/2 on Tuesday. What fraction is read?','["9/10","3/7","2/10","1/5"]',0,'Common denominator is 10.','2/5 = 4/10. 1/2 = 5/10. 4/10 + 5/10 = 9/10.','2026-10-30 17:35:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0316','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Evaluate: A ribbon is 5/6 m long. 1/3 m is cut off. How much remains?','["1/2 m (or 3/6)","4/3 m","6/9 m","4/6 m"]',0,'Convert 1/3 to sixths.','5/6 - 2/6 = 3/6 = 1/2.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0317','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Analyze: What is the best (Least Common) denominator for adding 1/6 and 1/8?','["24","48","14","2"]',0,'Find the LCM.','LCM of 6 and 8 is 24.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0318','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Synthesize: X - 1/4 = 1/3. What is X?','["7/12","1/12","2/7","1/7"]',0,'Use inverse operation (addition).','X = 1/3 + 1/4 = 4/12 + 3/12 = 7/12.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0319','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Calculate 5/6 - 1/6 by finding a common denominator.','["24/36 (unsimplified)","4/0","6/12","36/36"]',0,'Cross-multiply.','Common denom 6x6. (5x6)/36 - 6/36.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0320','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Critique: ''Hannah added 1/3 and 1/4 and got 2/7.''','["False, they added numerators and denominators. It should be 7/12.","True.","False, it should be 1/12.","False, it should be 2/12."]',0,'Never add denominators.','1/3 = 4/12, 1/4 = 3/12. 4/12 + 3/12 = 7/12.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0321','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Synthesize: Ian reads 2/5 of a book on Monday and 1/2 on Tuesday. What fraction is read?','["9/10","3/7","2/10","1/5"]',0,'Common denominator is 10.','2/5 = 4/10. 1/2 = 5/10. 4/10 + 5/10 = 9/10.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0322','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Evaluate: A ribbon is 5/6 m long. 1/3 m is cut off. How much remains?','["1/2 m (or 3/6)","4/3 m","6/9 m","4/6 m"]',0,'Convert 1/3 to sixths.','5/6 - 2/6 = 3/6 = 1/2.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0323','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Analyze: What is the best (Least Common) denominator for adding 1/6 and 1/8?','["24","48","14","2"]',0,'Find the LCM.','LCM of 6 and 8 is 24.','2026-10-30 17:35:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0324','Maths','Fractions','Subtopic 9: Adding and Subtracting Fractions with Unlike Denominators','Primary',10,'Synthesize: X - 1/4 = 1/3. What is X?','["7/12","1/12","2/7","1/7"]',0,'Use inverse operation (addition).','X = 1/3 + 1/4 = 4/12 + 3/12 = 7/12.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0325','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'What is the rule to calculate 1/3 x 1/2?','["Multiply the numerators and multiply the denominators.","Add the numerators.","Find a common denominator.","Flip the second fraction."]',0,'Straight across.','When multiplying fractions, multiply straight across.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0326','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'To find 1/2 of 1/5, what operation do you use?','["Multiplication","Addition","Subtraction","Division"]',0,'Fraction OF a fraction.','Finding a ''fraction of'' something means multiplying.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0327','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Calculate 1/2 x 1/7.','["1/14","2/9","1/7","7/2"]',0,'Top x Top, Bottom x Bottom.','1x1=1, 2x7=14.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0328','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Calculate 1/3 x 1/9.','["1/27","2/12","1/9","9/3"]',0,'Multiply straight across.','1x1=1, 3x9=27.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0329','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Do you need a common denominator to multiply fractions?','["No","Yes","Only for even numbers","Only for proper fractions"]',0,'Straight across.','Multiplication doesn''t require common denominators.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0330','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'What is the top number of the answer to 1/5 x 2/7?','["2","3","5","7"]',0,'Multiply the tops.','Numerator: 1 x 2 = 2.','2026-10-30 17:35:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0331','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'What is the rule to calculate 2/3 x 1/2?','["Multiply the numerators and multiply the denominators.","Add the numerators.","Find a common denominator.","Flip the second fraction."]',0,'Straight across.','When multiplying fractions, multiply straight across.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0332','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'To find 1/2 of 1/8, what operation do you use?','["Multiplication","Addition","Subtraction","Division"]',0,'Fraction OF a fraction.','Finding a ''fraction of'' something means multiplying.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0333','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Calculate 1/2 x 1/6.','["1/12","2/8","1/6","6/2"]',0,'Top x Top, Bottom x Bottom.','1x1=1, 2x6=12.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0334','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Calculate 1/3 x 1/8.','["1/24","2/11","1/8","8/3"]',0,'Multiply straight across.','1x1=1, 3x8=24.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0335','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'Do you need a common denominator to multiply fractions?','["No","Yes","Only for even numbers","Only for proper fractions"]',0,'Straight across.','Multiplication doesn''t require common denominators.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0336','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',1,'What is the top number of the answer to 2/5 x 2/7?','["4","4","5","7"]',0,'Multiply the tops.','Numerator: 2 x 2 = 4.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0337','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 1/5 x 2/3.','["2/15","2/8","3/15","2/5"]',0,'Multiply top x top, bottom x bottom.','Numerators: 1 x 2 = 2. Denominators: 5 x 3 = 15.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0338','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'How do you multiply the whole number 5 by the fraction 2/5?','["Write 5 as 5/1, then multiply.","Add 5 to the numerator.","Multiply 5 by the denominator.","You cannot multiply them."]',0,'Put it over 1.','Whole numbers can be written over 1.','2026-10-30 17:35:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0339','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 7 x 1/5.','["7/5","1/35","8/5","5/7"]',0,'Multiply the whole number by the numerator.','7/1 x 1/5 = 7/5.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0340','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 2 x 4/7.','["8/7","8/14","2/7","4/14"]',0,'Multiply the whole number by the numerator.','2/1 x 4/7 = 8/7.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0341','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'A recipe uses 3/4 cup of flour. Ethan makes half the recipe. How much flour?','["3/8 cup","3/2 cup","4/8 cup","1/4 cup"]',0,'Multiply by 1/2.','1/2 x 3/4 = 3/8.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0342','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 1/4 x 3/5.','["3/20","3/9","4/20","3/4"]',0,'Top x Top, Bottom x Bottom.','1x3 = 3. 4x5 = 20.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0343','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 2/5 x 2/3.','["4/15","4/8","4/15","4/5"]',0,'Multiply top x top, bottom x bottom.','Numerators: 2 x 2 = 4. Denominators: 5 x 3 = 15.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0344','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'How do you multiply the whole number 8 by the fraction 3/5?','["Write 8 as 8/1, then multiply.","Add 8 to the numerator.","Multiply 8 by the denominator.","You cannot multiply them."]',0,'Put it over 1.','Whole numbers can be written over 1.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0345','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 6 x 1/5.','["6/5","1/30","7/5","5/6"]',0,'Multiply the whole number by the numerator.','6/1 x 1/5 = 6/5.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0346','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 2 x 5/7.','["10/7","10/14","2/7","5/14"]',0,'Multiply the whole number by the numerator.','2/1 x 5/7 = 10/7.','2026-10-30 17:35:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0347','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'A recipe uses 3/4 cup of flour. Kevin makes half the recipe. How much flour?','["3/8 cup","3/2 cup","4/8 cup","1/4 cup"]',0,'Multiply by 1/2.','1/2 x 3/4 = 3/8.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0348','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',5,'Calculate 2/4 x 3/5.','["6/20","6/9","5/20","6/4"]',0,'Top x Top, Bottom x Bottom.','2x3 = 6. 4x5 = 20.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0349','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Calculate the whole number 3 multiplied by 3/4.','["9/4","9/12","3/4","12/3"]',0,'Write the whole number over 1.','Write 3 as 3/1. Then (3 x 3) / (1 x 4) = 9/4.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0350','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Analyze: What is ''cancellation'' when multiplying fractions like 2/3 x 3/4?','["Dividing a numerator and a denominator by a common factor before multiplying.","Crossing out the whole fraction.","Erasing mistakes.","Adding the fractions instead."]',0,'Simplify before you multiply.','Simplifying beforehand makes the numbers smaller and easier to multiply.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0351','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Evaluate: If a garden covers 2/3 of a plot, and flowers are on 1/2 of the garden. Fraction of plot with flowers?','["1/3 (or 2/6)","3/5","4/6","1/6"]',0,'Multiply them.','1/2 x 2/3 = 2/6 = 1/3.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0352','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Critique: ''Diana multiplied 1/2 x 1/3 and got 1/5 by adding the denominators.''','["False, you MUST multiply the denominators to get 1/6.","True.","False, you add the numerators.","False, the answer is 2/5."]',0,'Don''t add!','Multiplication requires multiplying the denominators.','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0353','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Synthesize: Calculate 4/5 x 5/8 and simplify.','["1/2","20/40","9/13","1/4"]',0,'Cancel the 5s.','4x5=20, 5x8=40. 20/40 = 1/2. (Or cancel the 5s and 4/8=1/2).','2026-10-30 17:35:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0354','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Analyze: Why is the product of two proper fractions always smaller than either of the original fractions?','["Because you are taking a part OF a part, making it even smaller.","Because fractions are negative.","It isn''t.","Because denominators get added."]',0,'A part of a part.','Half of a half is a quarter.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0355','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Calculate the whole number 6 multiplied by 3/4.','["18/4","18/24","3/4","24/3"]',0,'Write the whole number over 1.','Write 6 as 6/1. Then (6 x 3) / (1 x 4) = 18/4.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0356','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Analyze: What is ''cancellation'' when multiplying fractions like 2/3 x 3/4?','["Dividing a numerator and a denominator by a common factor before multiplying.","Crossing out the whole fraction.","Erasing mistakes.","Adding the fractions instead."]',0,'Simplify before you multiply.','Simplifying beforehand makes the numbers smaller and easier to multiply.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0357','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Evaluate: If a garden covers 2/3 of a plot, and flowers are on 1/2 of the garden. Fraction of plot with flowers?','["1/3 (or 2/6)","3/5","4/6","1/6"]',0,'Multiply them.','1/2 x 2/3 = 2/6 = 1/3.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0358','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Critique: ''Julia multiplied 1/2 x 1/3 and got 1/5 by adding the denominators.''','["False, you MUST multiply the denominators to get 1/6.","True.","False, you add the numerators.","False, the answer is 2/5."]',0,'Don''t add!','Multiplication requires multiplying the denominators.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0359','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Synthesize: Calculate 4/5 x 5/8 and simplify.','["1/2","20/40","9/13","1/4"]',0,'Cancel the 5s.','4x5=20, 5x8=40. 20/40 = 1/2. (Or cancel the 5s and 4/8=1/2).','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0360','Maths','Fractions','Subtopic 10: Multiplying Fractions','Primary',10,'Analyze: Why is the product of two proper fractions always smaller than either of the original fractions?','["Because you are taking a part OF a part, making it even smaller.","Because fractions are negative.","It isn''t.","Because denominators get added."]',0,'A part of a part.','Half of a half is a quarter.','2026-10-30 17:35:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0361','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'To divide a fraction by a whole number, what is the ''Keep, Change, Flip'' rule step for 1/3 ÷ 2?','["Keep 1/3, change ÷ to x, flip 2/1 to 1/2.","Change 1/3 to 3/1.","Flip both fractions.","Add the fractions."]',0,'Keep, Change, Flip.','Keep the first fraction, change the sign to multiplication, flip the second.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0362','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'What is the reciprocal (flipped version) of 3/4?','["4/3","3/4","1/4","3/1"]',0,'Flip it upside down.','Swap the top and bottom.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0363','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'What is the reciprocal of the whole number 5?','["1/5","5/1","5","0/5"]',0,'Put it under 1.','5 is 5/1, so flipped it is 1/5.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0364','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'When using ''Keep, Change, Flip'', what do you change the division sign (÷) into?','["Multiplication (x)","Addition (+)","Subtraction (-)","Equals (=)"]',0,'Keep, CHANGE, Flip.','Division becomes multiplication.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0365','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'Calculate 1/2 ÷ 2.','["1/4","1","2/2","4"]',0,'Half of a half.','1/2 x 1/2 = 1/4.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0366','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'Calculate 1/3 ÷ 2.','["1/6","2/3","3/2","6"]',0,'Keep, Change, Flip.','1/3 x 1/2 = 1/6.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0367','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'To divide a fraction by a whole number, what is the ''Keep, Change, Flip'' rule step for 1/6 ÷ 2?','["Keep 1/6, change ÷ to x, flip 2/1 to 1/2.","Change 1/6 to 6/1.","Flip both fractions.","Add the fractions."]',0,'Keep, Change, Flip.','Keep the first fraction, change the sign to multiplication, flip the second.','2026-10-30 17:35:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0368','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'What is the reciprocal (flipped version) of 3/4?','["4/3","3/4","1/4","3/1"]',0,'Flip it upside down.','Swap the top and bottom.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0369','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'What is the reciprocal of the whole number 5?','["1/5","5/1","5","0/5"]',0,'Put it under 1.','5 is 5/1, so flipped it is 1/5.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0370','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'When using ''Keep, Change, Flip'', what do you change the division sign (÷) into?','["Multiplication (x)","Addition (+)","Subtraction (-)","Equals (=)"]',0,'Keep, CHANGE, Flip.','Division becomes multiplication.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0371','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'Calculate 1/2 ÷ 2.','["1/4","1","2/2","4"]',0,'Half of a half.','1/2 x 1/2 = 1/4.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0372','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',1,'Calculate 1/3 ÷ 2.','["1/6","2/3","3/2","6"]',0,'Keep, Change, Flip.','1/3 x 1/2 = 1/6.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0373','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Calculate 1/2 ÷ 3.','["1/6","3/2","1/5","3/5"]',0,'Multiply by the reciprocal of 3.','1/2 x 1/3 = 1/6.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0374','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Calculate 3/4 ÷ 3.','["1/4 (or 3/12)","9/4","3/12","4/3"]',0,'Keep, Change, Flip.','3/4 x 1/3 = 3/12 = 1/4.','2026-10-30 17:35:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0375','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Charlie has 1/2 of a pizza and shares it equally between 2 people. What fraction does each get?','["1/4","1","1/2","2"]',0,'Half of a half.','1/2 ÷ 2 = 1/4.','2026-10-30 17:35:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0376','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Calculate 2/5 ÷ 2.','["1/5 (or 2/10)","4/5","5/2","2/10"]',0,'Keep, Change, Flip.','2/5 x 1/2 = 2/10 = 1/5.','2026-10-30 17:35:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0377','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'What is the first step to calculate 2 ÷ 1/3?','["Write 2 as 2/1.","Flip 2 to 1/2.","Add 2 and 3.","Multiply 2 by 1."]',0,'Make it a fraction.','Write the whole number as a fraction first.','2026-10-30 17:35:27',NULL,NULL);
