INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0382','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Calculate 2/5 ÷ 2.','["1/5 (or 2/10)","4/5","5/2","2/10"]',0,'Keep, Change, Flip.','2/5 x 1/2 = 2/10 = 1/5.','2026-10-30 17:35:28',NULL,NULL);
