INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0384','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',5,'Calculate 3 ÷ 1/2.','["6","3/2","1/6","1.5"]',0,'How many halves in 3 wholes?','3/1 x 2/1 = 6.','2026-10-30 17:35:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0385','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Calculate the division of two fractions: 1/3 ÷ 1/4.','["4/3","1/12","3/4","4/3"]',0,'Multiply by the reciprocal of 1/4.','1/3 x 4/1 = 4/3.','2026-10-30 17:35:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0386','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Evaluate: 2/3 ÷ 4/5.','["10/12 (or 5/6)","8/15","6/20","15/8"]',0,'Keep, Change, Flip.','2/3 x 5/4 = 10/12 = 5/6.','2026-10-30 17:35:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0387','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Synthesize: A ribbon is 3/4 m long. Each piece must be 1/4 m long. How many pieces can be cut?','["3","3/16","4/3","12"]',0,'How many 1/4s fit into 3/4?','3/4 ÷ 1/4 = 3/4 x 4/1 = 12/4 = 3.','2026-10-30 17:35:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0388','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Critique: ''Diana calculated 1/2 ÷ 1/4 and got 1/8 by multiplying them.''','["False, division requires flipping the second fraction; the answer is 2.","True.","False, the answer is 1/6.","False, you add them."]',0,'Don''t forget to flip!','1/2 ÷ 1/4 = 1/2 x 4/1 = 4/2 = 2.','2026-10-30 17:35:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0389','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Analyze: Why is division by zero undefined for fractions?','["Because you cannot divide a quantity into zero equal groups.","Because zero is too small to see.","Because it equals 1.","It is defined as zero."]',0,'Can you share pizza with 0 people?','Division by zero breaks the rules of arithmetic.','2026-10-30 17:35:29',NULL,NULL);
