INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0394','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Critique: ''Julia calculated 1/2 ÷ 1/4 and got 1/8 by multiplying them.''','["False, division requires flipping the second fraction; the answer is 2.","True.","False, the answer is 1/6.","False, you add them."]',0,'Don''t forget to flip!','1/2 ÷ 1/4 = 1/2 x 4/1 = 4/2 = 2.','2026-10-30 17:35:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0395','Maths','Fractions','Subtopic 11: Dividing Fractions','Primary',10,'Analyze: Why is division by zero undefined for fractions?','["Because you cannot divide a quantity into zero equal groups.","Because zero is too small to see.","Because it equals 1.","It is defined as zero."]',0,'Can you share pizza with 0 people?','Division by zero breaks the rules of arithmetic.','2026-10-30 17:35:29',NULL,NULL);
