INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0397','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',1,'A recipe needs 1/4 cup of flour and 1/4 cup of sugar. Which operation finds the total amount?','["Addition","Subtraction","Multiplication","Division"]',0,'Altogether or total.','The word ''total'' suggests combining quantities via addition.','2026-10-30 17:35:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0398','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',1,'If a problem asks ''how much remains'' after someone eats a fraction of a cake, which operation is used?','["Subtraction","Addition","Multiplication","Division"]',0,'Taking away.','''Remains'' or ''left over'' suggests subtraction.','2026-10-30 17:35:30',NULL,NULL);
