INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0418','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',5,'A cake is shared. Julia gets 2/5 and a friend gets 1/5. Total fraction eaten?','["3/5","2/25","1/5","5/5"]',0,'Add them.','2/5 + 1/5 = 3/5.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0419','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',5,'A bottle has 7/8 L of water. Kevin drinks 2/8 L. How much is left?','["5/8 L","9/8 L","14/64 L","7/8 L"]',0,'Subtract.','7/8 - 2/8 = 5/8.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0420','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',5,'Liam has 1/2 of a pie and shares it with 2 friends (3 people total). Fraction each?','["1/6","1/2","3/2","1/5"]',0,'Divide by 3.','1/2 ÷ 3 = 1/6.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0421','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'A tank holds 12 litres. 1/3 is used for plants, and 1/4 is used for cleaning. How many litres remain?','["5","4","3","5"]',0,'Find amount used for each, subtract from total.','Used = 4 + 3. Remaining = Total - Used.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0422','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'A book has 120 pages. Bob reads 1/3 on Saturday and 1/4 on Sunday. How many pages remain unread?','["50","70","40","30"]',0,'Calculate pages for each day.','1/3 is 40. 1/4 is 30. 120 - 70 = 50.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0423','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Synthesize: Charlie buys 4 notebooks at 3.50 each, and uses 1/2 of a 20 note to pay. Does Charlie have enough?','["No, 4x3.50=14, but 1/2 of 20 is 10. Not enough.","Yes, 10 is more than 14.","Yes, they cost 10.","No, they cost 20."]',0,'Calculate cost and available money.','Total cost 14. Available money 10. Short by 4.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0424','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Evaluate: A runner completes 2/5 of a 10 km race, takes a break, then runs another 1/2 of the TOTAL race. How far left to run?','["1 km","5 km","4 km","9 km"]',0,'Calculate exact km for each fraction.','2/5 of 10 = 4. 1/2 of 10 = 5. Total run = 9. 10 - 9 = 1 km left.','2026-10-30 17:35:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0425','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Critique: ''Ethan says if you eat 1/2 of a pizza, then 1/2 of what is LEFT, you ate the whole pizza.''','["False, you ate 1/2 + 1/4 = 3/4 of the pizza.","True.","False, you ate 1/2 + 1/2 = 1.","False, you ate nothing."]',0,'Fraction OF what is left.','1/2 of 1/2 is 1/4. 1/2 + 1/4 is 3/4. 1/4 remains.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0426','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Analyze: 3/4 of a class of 32 students go on a trip. 1/3 of the students on the trip are girls. How many girls on the trip?','["8","12","24","4"]',0,'Multi-step multiplication.','Trip = 3/4 of 32 = 24. Girls = 1/3 of 24 = 8.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0427','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'A tank holds 12 litres. 1/3 is used for plants, and 1/4 is used for cleaning. How many litres remain?','["5","4","3","5"]',0,'Find amount used for each, subtract from total.','Used = 4 + 3. Remaining = Total - Used.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0428','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'A book has 120 pages. Hannah reads 1/3 on Saturday and 1/4 on Sunday. How many pages remain unread?','["50","70","40","30"]',0,'Calculate pages for each day.','1/3 is 40. 1/4 is 30. 120 - 70 = 50.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0429','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Synthesize: Ian buys 4 notebooks at 3.50 each, and uses 1/2 of a 20 note to pay. Does Ian have enough?','["No, 4x3.50=14, but 1/2 of 20 is 10. Not enough.","Yes, 10 is more than 14.","Yes, they cost 10.","No, they cost 20."]',0,'Calculate cost and available money.','Total cost 14. Available money 10. Short by 4.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0430','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Evaluate: A runner completes 2/5 of a 10 km race, takes a break, then runs another 1/2 of the TOTAL race. How far left to run?','["1 km","5 km","4 km","9 km"]',0,'Calculate exact km for each fraction.','2/5 of 10 = 4. 1/2 of 10 = 5. Total run = 9. 10 - 9 = 1 km left.','2026-10-30 17:35:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0431','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Critique: ''Kevin says if you eat 1/2 of a pizza, then 1/2 of what is LEFT, you ate the whole pizza.''','["False, you ate 1/2 + 1/4 = 3/4 of the pizza.","True.","False, you ate 1/2 + 1/2 = 1.","False, you ate nothing."]',0,'Fraction OF what is left.','1/2 of 1/2 is 1/4. 1/2 + 1/4 is 3/4. 1/4 remains.','2026-10-30 17:35:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t4_global_0432','Maths','Fractions','Subtopic 12: Fractions in Word Problems','Primary',10,'Analyze: 3/4 of a class of 32 students go on a trip. 1/3 of the students on the trip are girls. How many girls on the trip?','["8","12","24","4"]',0,'Multi-step multiplication.','Trip = 3/4 of 32 = 24. Girls = 1/3 of 24 = 8.','2026-10-30 17:35:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_001','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is Earth?','["A star like the Sun","The planet on which we live","The moon","A large cloud of gas"]',1,'It is where all humans live.','Earth is the planet on which we live. It is our home in space...','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_002','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Earth is the _____ planet from the Sun.','["First","Second","Third","Fourth"]',2,'Count: Mercury, Venus, _____.','It is the third planet from the Sun, after Mercury and Venus.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_003','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'How many planets are there in our Solar System?','["Seven","Eight","Nine","Ten"]',1,'There are eight recognized major planets.','Earth is one of the eight planets that orbit the Sun.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_004','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is the approximate shape of the Earth?','["A flat circle","A perfect cube","Approximately spherical (shaped like a ball)","A triangle"]',2,'It looks round from space.','Earth is approximately spherical, meaning it is shaped like a ball.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_005','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Approximately what percentage of Earth''s surface is covered by water?','["29%","50%","71%","90%"]',2,'Most of the Earth is covered in blue.','Water covers approximately 71% of the surface.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_006','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Approximately what percentage of Earth''s surface is covered by land?','["29%","50%","71%","90%"]',0,'Less than a third of the Earth is land.','Land covers about 29%.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_007','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is the layer of gases surrounding Earth called?','["The crust","The atmosphere","The core","The ocean"]',1,'It contains the air we breathe.','Earth is surrounded by a layer of gases called the atmosphere.','2026-11-01 07:53:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_008','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is a ''globe''?','["A flat piece of paper showing countries","A spherical, three-dimensional model of Earth","A telescope used to look at the stars","A type of cloud"]',1,'It is shaped like the Earth itself.','A globe represents Earth as a small, three-dimensional model.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_009','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is a ''map''?','["A round model of the Earth","A representation of all or part of Earth''s surface on a flat surface","An imaginary line through the Earth","A type of spaceship"]',1,'You can fold it up and put it in your pocket.','Map: A representation of all or part of Earth''s surface on a flat surface.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_010','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is the imaginary line around which Earth rotates called?','["The equator","The axis","The horizon","The orbit"]',1,'It passes through the North and South poles.','Earth rotates, or spins, around an imaginary line called its axis.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_011','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'How long does one complete rotation of Earth take?','["1 hour","12 hours","24 hours","365 days"]',2,'It is the length of one full day.','One complete rotation takes approximately 24 hours.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_012','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What causes the cycle of day and night?','["The Sun moving around the Earth","Earth''s rotation on its axis","The Moon blocking the Sun","Clouds covering the sky"]',1,'As Earth spins, half faces the Sun and half faces away.','This [rotation] creates the cycle of day and night.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_013','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'How long does one complete revolution of Earth around the Sun take?','["1 day","30 days","Approximately 365.25 days","10 years"]',2,'It takes one full year.','One complete revolution takes approximately 365.25 days, which is why a calendar year is about 365 days long.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_014','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Which of these is an example of an icy region on Earth?','["The Amazon rainforest","The Sahara Desert","Antarctica","The Himalayas"]',2,'It is located at the South Pole.','Antarctica has extensive ice sheets and very cold conditions.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_015','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Most of Earth''s water is...','["Freshwater in lakes","Salty ocean water","Frozen in glaciers","Underground"]',1,'You cannot drink most of the water on Earth.','Most of Earth''s water is salty ocean water.','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_016','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'Which of these is a way to help protect our planet?','["Throwing rubbish into rivers","Wasting drinking water","Reducing, reusing, and recycling materials","Destroying forests"]',2,'It helps keep the environment clean.','We can help protect our planet by... Reducing, reusing, and recycling materials...','2026-11-01 07:53:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_017','Geography','Physical Geography','Topic 1: Our Earth','Primary',1,'What is the ''equator''?','["The line connecting the North and South poles","An imaginary line around the middle of Earth, halfway between the poles","A mountain range in Asia","The path Earth takes around the Sun"]',1,'It divides the Earth into the Northern and Southern Hemispheres.','Equator: An imaginary line around the middle of Earth, halfway between the poles.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_018','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why does the Earth look flat when we stand in a field, even though it is spherical?','["Because the Earth is actually a flat disc.","Because the Earth is so massive that the curvature is too gradual to see from the ground.","Because clouds block our view of the curve.","Because human eyes cannot see round shapes."]',1,'You have to go high into space to see the curve!','Earth may look flat when we stand in a field or walk along a road because it is so large.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_019','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'How does watching a ship travel across the sea prove that the Earth is curved?','["The ship bursts into flames.","The ship appears to disappear gradually over the horizon, bottom first, because it is moving along a curve.","The ship suddenly falls off a sharp edge.","The ship shrinks until it is invisible."]',1,'If the Earth were flat, the ship would just get smaller, but you''d always see the bottom.','Ships travelling across the sea can disappear gradually over the horizon.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_020','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why is only a small proportion of Earth''s water available for humans to easily drink?','["Because most of it is hidden in space.","Because the vast majority of Earth''s water is salty ocean water, and much of the remaining freshwater is trapped in glaciers or underground.","Because humans only drink rainwater.","Because the atmosphere absorbs all the water."]',1,'We can only drink fresh, liquid water!','Most of Earth''s water is salty ocean water. Only a small proportion is freshwater, and much of that freshwater is stored in glaciers, ice sheets, or underground.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_021','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'What would happen if the Earth did not have an atmosphere?','["The Earth would become perfectly safe.","Living things would lack oxygen, temperatures would not be regulated, and we would not be protected from the Sun''s harmful ultraviolet radiation.","The oceans would turn into fresh water.","The Earth would stop rotating."]',1,'The atmosphere is like a protective blanket around the planet.','The atmosphere: Provides gases that living things need... Helps regulate Earth''s temperature... Protects life by absorbing much of the Sun''s harmful ultraviolet radiation.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_022','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'If it is daytime where you live, what is happening on the exact opposite side of the Earth?','["It is also daytime.","It is nighttime, because that side of the Earth is facing away from the Sun.","The Sun has disappeared completely.","The Earth has stopped rotating."]',1,'The Sun can only shine on one half of the ball at a time!','The side of Earth facing the Sun experiences daytime. The side facing away from the Sun experiences nighttime. As Earth rotates, different places move into and out of sunlight.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_023','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why are ''leap years'' necessary in our calendar system?','["Because February is too short.","Because one revolution around the Sun actually takes about 365.25 days; we add an extra day every four years to make up for that quarter-day.","Because the Earth sometimes stops moving.","Because the moon changes shape."]',1,'0.25 + 0.25 + 0.25 + 0.25 = 1 full extra day!','One complete revolution takes approximately 365.25 days, which is why a calendar year is about 365 days long. The extra quarter-day is accounted for by leap years.','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_024','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why do mapmakers face a challenge when trying to show the whole Earth on a flat map?','["Because paper is too expensive.","Because the Earth is a curved 3D sphere, and flattening it into a 2D map always causes some distortion of shape, area, distance, or direction.","Because they don''t know where the countries are.","Because the oceans move too fast."]',1,'Try peeling an orange and flattening the skin—it will stretch and tear!','Because Earth is curved, showing the whole planet on a flat map always involves some distortion of shape, area, distance, or direction...','2026-11-01 07:53:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_025','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'How does the atmosphere ''regulate'' Earth''s temperature?','["It blocks all sunlight from reaching the ground.","It acts like a blanket, holding in some of the Sun''s heat so the planet doesn''t freeze at night, while blocking some intense heat during the day.","It pumps cold water from the ocean into the air.","It creates massive storms every day."]',1,'Without it, days would be boiling hot and nights would be freezing cold!','The atmosphere: ... Helps regulate Earth''s temperature.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_026','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why is ''land'' important even though it only covers 29% of the Earth?','["Because water is useless.","It provides the solid foundation where humans and land animals live, grow food, build communities, and establish transport networks.","Because it is the only place with oxygen.","Because land absorbs all the ocean water."]',1,'We are not fish; we need solid ground to survive!','Why is land important? Land provides places for people and other living things to live. People use land to grow food, build homes...','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_027','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'What makes a ''globe'' better than a ''map'' for understanding the true shape of the continents?','["A globe is easier to fold and carry.","A globe is a 3D spherical model, meaning it shows the continents and oceans without the stretching and distortion found on flat 2D maps.","A globe shows every single street in the world.","A globe is always brightly colored."]',1,'It is a mini version of the real planet!','A globe represents Earth as a small, three-dimensional model... A globe is useful for understanding Earth''s shape.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_028','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'How do different environments on Earth prove that our planet is diverse?','["They show that Earth only has one type of weather.","They show that the same planet can support extremely different conditions—from the freezing ice of Antarctica to the hot, dry sands of the Sahara—each with unique plants and animals.","They prove that Earth is exactly the same everywhere.","They show that animals cannot survive anywhere."]',1,'Life adapts to survive in completely different climates!','Our planet has many different environments, including forests, mountains, deserts, oceans, grasslands, and icy regions... These places are different, but they are all parts of the same planet.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_029','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why is it important to protect natural habitats like forests?','["Because forests take up too much space.","Forests provide homes for diverse plants and animals, and protecting them ensures the survival of these species and the health of the planet''s ecosystems.","Because we need to build more concrete cities.","Because trees block the sunlight."]',1,'Cutting down a forest destroys the homes of thousands of animals!','Earth provides the resources that people and other living things need. We can help protect our planet by: ... Protecting forests and natural habitats.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_030','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'What does it mean that Earth is ''slightly flattened at the poles and bulges around the equator''?','["It means Earth is shaped exactly like a perfect cube.","It means Earth is not a mathematically perfect sphere; the spinning motion causes the middle (equator) to stick out slightly and the top and bottom (poles) to be slightly flat.","It means Earth is shaped like a flat pancake.","It means Earth has massive holes at the North and South poles."]',1,'Think of a squishy ball that you press down on slightly from the top and bottom.','Earth is approximately spherical, meaning it is shaped like a ball. More precisely, it is slightly flattened at the poles and bulges around the equator.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_031','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'How can ''reducing, reusing, and recycling'' help care for the Earth?','["It creates more rubbish.","It minimizes the amount of waste sent to landfills, conserves natural resources, and reduces the pollution caused by manufacturing new items.","It destroys natural habitats.","It uses more energy."]',1,'Using things more than once means taking less from the Earth!','We can help protect our planet by: ... Reducing, reusing, and recycling materials where facilities are available.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_032','Geography','Physical Geography','Topic 1: Our Earth','Primary',5,'Why is the Sun considered essential for life on Earth?','["Because it provides darkness for sleeping.","It provides the necessary energy, light, and heat that drive weather systems, plant growth, and keep the planet at a suitable temperature for liquid water to exist.","Because it pulls water out of the ocean.","Because it creates the atmosphere."]',1,'Without the Sun, the Earth would be a frozen, dark rock!','Life depends on several important conditions, including liquid water, suitable temperatures, energy from the Sun...','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_033','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Analyze the relationship between Earth''s axial rotation and human biological/societal organization.','["The rotation has no impact on human society.","Earth''s 24-hour rotation determines the fundamental diurnal (day/night) cycle, which dictates human circadian rhythms, agricultural schedules, global time zones, and the daily structure of almost all human societies.","The rotation forces humans to hibernate for six months.","The rotation causes humans to age backwards."]',1,'Our entire concept of a ''day'' and when we sleep is controlled by the spin of the planet!','One complete rotation takes approximately 24 hours. This creates the cycle of day and night... As Earth rotates, different places move into and out of sunlight.','2026-11-01 07:53:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_034','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Critique the geometric accuracy of the phrase ''Earth is a sphere''.','["It is 100% mathematically correct.","While ''sphere'' is a useful approximation for primary understanding, it is geodetically inaccurate; Earth is an oblate spheroid, meaning centrifugal force from its rotation causes an equatorial bulge and polar flattening.","It is entirely false; Earth is a flat plane.","It means Earth is shaped exactly like an egg."]',1,'Spinning makes the middle stretch out just a tiny bit!','Earth is approximately spherical, meaning it is shaped like a ball. More precisely, it is slightly flattened at the poles and bulges around the equator.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_035','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Synthesize the function of the atmosphere as a dual ''shield and greenhouse'' for Earth''s biosphere.','["The atmosphere only prevents rain from falling.","The atmosphere acts as a shield by absorbing lethal ultraviolet solar radiation, while simultaneously acting as a greenhouse by trapping sufficient thermal energy to maintain the liquid water necessary for biological survival.","The atmosphere creates radiation and freezes the planet.","The atmosphere has no physical effect on the planet''s surface."]',1,'It blocks the bad rays from space but keeps the warm heat in!','The atmosphere: Provides gases that living things need... Helps regulate Earth''s temperature... Protects life by absorbing much of the Sun''s harmful ultraviolet radiation.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_036','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Evaluate the epistemological shift caused by satellite photography regarding our understanding of Earth''s shape.','["Satellite photos proved the Earth was flat.","For centuries, curvature was inferred through indirect mathematical and observational methods (like ship masts). Satellite photography provided absolute, direct visual empirical proof of Earth''s spherical nature, shifting it from deduced theory to undeniable visual fact.","Satellites made it impossible to see the Earth.","Satellite photos proved that the Earth is a perfect cube."]',1,'We used to have to guess with math; now we can just look at a picture from space!','Scientists have learned about Earth''s shape using observations, measurements, satellites, and photographs taken from space. Photographs from space show Earth''s curved shape.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_037','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Analyze the inherent cartographic paradox of attempting to map the global Earth.','["Maps are completely flawless representations of Earth.","It is mathematically impossible to project a 3D oblate spheroid onto a 2D Euclidean plane without introducing distortion. Therefore, every flat map is a compromise, distorting either shape, area, distance, or direction (e.g., the Mercator projection).","Maps are impossible to draw and have never been made.","Maps can only be drawn by satellites."]',1,'You cannot flatten a globe perfectly without ripping or stretching it!','Because Earth is curved, showing the whole planet on a flat map always involves some distortion of shape, area, distance, or direction, depending on the map projection.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_038','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'How does the ''unequal distribution of freshwater'' act as a limiting factor for human civilization?','["Humans do not need freshwater.","Although water covers 71% of Earth, the vast majority is saline (oceanic) or locked in cryospheric ice (glaciers). The minute fraction of accessible liquid freshwater severely limits agricultural capacity and dictates where human settlements can thrive.","Freshwater is equally distributed everywhere on Earth.","All ocean water is safe to drink instantly."]',1,'We live on a blue planet, but we can only drink a tiny drop of it!','Most of Earth''s water is salty ocean water. Only a small proportion is freshwater, and much of that freshwater is stored in glaciers, ice sheets, or underground.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_039','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Synthesize the relationship between Earth''s orbital revolution and the concept of ''leap years''.','["Leap years are random holidays.","Because a single solar revolution takes roughly 365.24 days, a standard 365-day calendar falls out of sync with astronomical seasons. Inserting an intercalary day (February 29th) every four years mathematically corrects this accumulated orbital drift.","Leap years happen when the Earth stops moving.","Leap years are used to change the speed of the Earth."]',1,'Those four missing quarter-days add up to one full day every four years!','One complete revolution takes approximately 365.25 days, which is why a calendar year is about 365 days long. The extra quarter-day is accounted for by leap years.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_040','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Evaluate the global ethical implication of the statement: ''caring for the planet is a shared responsibility''.','["It means only one country is responsible for the Earth.","Because the atmosphere and oceans are continuous, borderless systems, environmental degradation (like pollution or climate change) in one region inherently impacts the entire biosphere, necessitating unified global cooperation for sustainability.","It means humans should not interact with nature.","It proves that pollution cannot cross national borders."]',1,'The air above one country easily blows over to the next; we share one sky!','People and communities in different parts of the world may face different environmental challenges, but caring for the planet is a shared responsibility.','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_041','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Analyze how extreme environmental adaptations demonstrate the resilience of the biosphere (e.g., Sahara vs. Antarctica).','["Life only exists in mild, perfect temperatures.","The existence of flora and fauna in both hyper-arid deserts (Sahara) and freezing cryospheres (Antarctica) proves that biological evolution produces highly specialized physiological adaptations, allowing life to exploit almost every available niche on the planet.","Animals in the Sahara and Antarctica are exactly identical.","No life exists outside of the Amazon rainforest."]',1,'A penguin and a camel both survive by having bodies built perfectly for their extreme homes!','Deserts: Home to specially adapted plants and animals. Polar regions: Home to organisms adapted to cold conditions... Life depends on several important conditions...','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_042','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Critique the historical reliance on ''ships disappearing over the horizon'' as proof of Earth''s curvature.','["It was a completely false observation.","While valid as an indirect, observable phenomenon demonstrating curvature, it is subject to optical illusions (like atmospheric refraction) and localized scale limits, making it a qualitative observation rather than the absolute quantitative proof later provided by modern geodesy.","It proves the Earth is flat and the ship is sinking.","It was the only way humans ever studied the Earth."]',1,'It''s a great clue, but math and satellites gave us the absolute proof!','Ships travelling across the sea can disappear gradually over the horizon... Scientists have [also] learned about Earth''s shape using observations, measurements, satellites...','2026-11-01 07:53:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_043','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'How does the atmosphere''s role in ''supporting weather'' dictate the distribution of terrestrial biomes (like forests and deserts)?','["Weather is random and has no effect on plants.","The atmosphere transports thermal energy and moisture globally. This circulatory system dictates precipitation patterns, which directly control whether a specific geographic region develops into a lush rainforest (high rainfall) or a barren desert (low rainfall).","The atmosphere only creates wind, not rain.","Terrestrial biomes are created by underground oceans."]',1,'If the atmosphere doesn''t drop rain on a piece of land, that land becomes a desert!','The atmosphere: ... Supports weather, clouds, and rainfall... Our planet has many different environments, including forests... deserts...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_044','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Synthesize the difference between Earth''s ''Rotation'' and ''Revolution'' and their respective temporal impacts.','["They are two words for the exact same movement.","Rotation is the Earth spinning on its internal axis, governing the 24-hour diurnal (day/night) cycle. Revolution is the Earth''s orbital transit around the Sun, governing the 365.25-day annual calendar and seasonal shifts.","Rotation takes a year, while revolution takes a day.","Rotation causes gravity, while revolution causes the atmosphere."]',1,'Spinning like a top = one day. Flying around the Sun = one year.','Earth rotates, or spins, around an imaginary line called its axis... One complete rotation takes approximately 24 hours. Earth also travels around the Sun. One complete revolution takes approximately 365.25 days...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_045','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Evaluate the vulnerability of ''freshwater stored in glaciers and ice sheets'' in the context of global climate regulation.','["Glaciers are indestructible and never melt.","Glaciers and ice sheets act as massive, frozen reservoirs of the planet''s limited freshwater. If planetary temperatures destabilize, the accelerated melting of these cryospheric stores directly threatens global sea levels and long-term freshwater availability.","Glaciers are made of salty ocean water.","Melting glaciers have no impact on the rest of the planet."]',1,'If the ice melts, that rare freshwater mixes into the salty ocean!','Only a small proportion is freshwater, and much of that freshwater is stored in glaciers, ice sheets, or underground.','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_046','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'Analyze why a ''Globe'' is fundamentally superior for understanding global flight paths or ocean currents compared to a ''Map''.','["Globes are flat and easy to read.","Because maps project a 3D surface onto 2D, they severely distort spatial relationships at the poles. A globe maintains accurate proportional distances, areas, and angles, which is vital for plotting the true shortest path (great circles) across vast planetary distances.","Globes show the inside of the Earth.","Maps are strictly 3D models."]',1,'If you want to see the true distance between two continents, you have to look at a round globe!','A globe represents Earth as a small, three-dimensional model. Because Earth is curved, showing the whole planet on a flat map always involves some distortion...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_earth_047','Geography','Physical Geography','Topic 1: Our Earth','Primary',10,'How does the categorization of Earth as ''the third planet from the Sun'' influence its capacity to support life?','["Planetary order has no effect on biology.","Its specific orbital placement (the ''Goldilocks Zone'') ensures that Earth receives the exact quotient of solar radiation required to maintain surface temperatures that allow water to exist in a liquid state—the fundamental prerequisite for all known biochemistry.","Being third means it is the coldest planet in the system.","Being third means it is entirely made of gas."]',1,'If we were closer, water would boil; if we were farther, water would freeze!','It is the third planet from the Sun... Life depends on several important conditions, including liquid water, suitable temperatures, energy from the Sun...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_001','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What is a continent?','["A large body of salt water","One of Earth''s major landmasses","A very tall mountain","An imaginary line around the Earth"]',1,'It is a massive piece of land.','A continent is one of Earth''s major landmasses.','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_002','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'How many continents are there in the commonly taught model?','["Five","Six","Seven","Eight"]',2,'There are seven major landmasses in this model.','In the commonly taught seven-continent model, the continents are...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_003','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which continent is the largest by land area and population?','["Africa","North America","Asia","Europe"]',2,'It stretches from the Arctic to the tropics.','Asia is the largest continent by land area and population.','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_004','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which continent contains the Sahara Desert and the Nile River?','["South America","Africa","Australia","Antarctica"]',1,'It is the second-largest continent.','Africa... Features: Sahara Desert, Nile River...','2026-11-01 07:53:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_005','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which two continents form the connected landmass called Eurasia?','["North and South America","Africa and Asia","Europe and Asia","Australia and Antarctica"]',2,'They are attached to each other.','Europe and Asia form one connected landmass called Eurasia...','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_006','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which continent contains the Amazon rainforest and the Andes Mountains?','["Africa","South America","Asia","North America"]',1,'It is located mostly in the Southern Hemisphere.','South America... Features: Amazon River, Amazon rainforest, Andes Mountains...','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_007','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which is the smallest of the seven continents in the common model?','["Europe","Antarctica","Australia","South America"]',2,'It is part of the wider Oceania region.','Australia is the smallest of the seven continents in the common model.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_008','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which continent surrounds the South Pole and is largely covered by ice?','["The Arctic","Europe","Antarctica","North America"]',2,'Penguins live there, but there are no permanent human populations.','Antarctica surrounds the South Pole. It is the coldest continent and is largely covered by ice.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_009','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What is Oceania?','["A region that includes Australia and many Pacific island nations","A deep part of the Atlantic Ocean","A mountain range in Europe","A desert in Africa"]',0,'It covers many islands in the Pacific.','Oceania is a wider geographical region that includes Australia, New Zealand, Papua New Guinea, and many Pacific island nations.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_010','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What does the word ''hemisphere'' mean?','["A type of weather","One half of Earth","A large ocean","A very hot desert"]',1,'Hemi means half, sphere means ball.','Hemisphere: One half of Earth.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_011','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which ocean lies between Asia/Australia and the Americas?','["The Atlantic Ocean","The Indian Ocean","The Pacific Ocean","The Arctic Ocean"]',2,'It is the largest ocean.','Pacific Ocean: Lies between Asia/Australia and the Americas.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_012','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'Which ocean lies between the Americas and Europe/Africa?','["The Pacific Ocean","The Atlantic Ocean","The Indian Ocean","The Southern Ocean"]',1,'Many ships crossed this ocean to reach the Americas from Europe.','Atlantic Ocean: Lies between the Americas and Europe/Africa.','2026-11-01 07:53:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_013','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What is an ''island''?','["A mountain covered in snow","An area of land surrounded by water","A very dry place with no rain","A river that flows into the sea"]',1,'Greenland is the world''s largest one.','Island: An area of land surrounded by water.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_014','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What is the highest mountain above sea level, and on which continent is it located?','["Mount Kilimanjaro, Africa","Mount Everest, Asia","The Rocky Mountains, North America","The Alps, Europe"]',1,'It is on the border of Nepal and China.','Mount Everest, Earth''s highest mountain above sea level, lies in the Himalayas [in Asia].','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_015','Geography','Physical Geography','Topic 2: Continents of the World','Primary',1,'What does ''Eurasia'' mean?','["A country in South America","The connected landmass of Europe and Asia","A type of ocean current","An ancient desert"]',1,'Because Europe and Asia are not separated by water, they form one giant piece of land.','Eurasia: The connected landmass of Europe and Asia.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_016','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why is Antarctica unique regarding its political status compared to all other continents?','["Because it is ruled by a single global king.","Because it has no sovereign countries and is governed through an international treaty system.","Because every country in the world is located there.","Because it is only owned by penguins."]',1,'Countries agreed to share it for peaceful science!','Some continents contain many countries, while Antarctica has no sovereign countries and is governed through an international treaty system.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_017','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why do geographers sometimes use different models to count the continents (like combining Europe and Asia into Eurasia)?','["Because counting to seven is too difficult.","Because there are different ways of grouping Earth''s landmasses since Europe and Asia are physically one connected piece of land.","Because Europe sank into the ocean.","Because the continents move too fast to count."]',1,'Continents are human ideas; physically, Europe and Asia are attached!','There are different ways of grouping Earth''s landmasses. For example, some educational systems combine Europe and Asia as Eurasia...','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_018','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'How does the equator relate to the continents of South America and Africa?','["It forms a physical wall blocking travel between them.","The imaginary line of the equator crosses directly through both South America and Africa, meaning they have land in both the Northern and Southern Hemispheres.","The equator is a river that flows through them.","The equator only crosses Antarctica."]',1,'The middle of the Earth passes right through these landmasses.','Equator: Crosses South America, Africa, and Asia''s island region.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_019','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why is Greenland classified as an island rather than a continent?','["Because it is located in the Pacific Ocean.","Even though it is massive, Greenland is smaller than Australia (the smallest continent) and is classified as the world''s largest island.","Because it is completely made of plastic.","Because it is located at the South Pole."]',1,'Australia is the cutoff point for how small a continent can be.','Greenland is the world''s largest island that is not classified as a continent.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_020','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'If a person claims ''everyone in Africa lives in exactly the same way,'' why is this statement incorrect?','["Because nobody actually lives in Africa.","Because Africa is a massive continent containing a remarkable variety of languages, cultures, environments (cities, deserts, rainforests), and wildlife.","Because Africa only contains one single city.","Because everyone in Africa lives in the Sahara desert."]',1,'A continent is huge; it is impossible for millions of people to be identical!','Important: No continent has just one culture or one way of life. There is great diversity within every continent.','2026-11-01 07:53:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_021','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'How does the geography of a continent affect the daily lives of the people who live there?','["It forces everyone to speak English.","Geography determines the climate (hot deserts vs. freezing ice), which affects what clothes people wear, what food they can grow, and how they build their homes.","Geography has absolutely no effect on people.","It makes everyone live underground."]',1,'You can''t farm the same way in a snowy mountain as you do in a tropical rainforest.','Studying continents helps us... Understand how geography affects transport, trade, and settlement.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_022','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'What is a ''desert'' and which major desert is found in Africa?','["A place covered in thick ice; the Amazon desert.","A region that receives very little precipitation; the Sahara is the world''s largest hot desert, found in Africa.","A place with heavy rainfall; the Gobi desert.","A massive ocean; the Pacific desert."]',1,'A desert is defined by how dry it is!','Desert: A region that receives very little precipitation... Africa... Features: Sahara Desert... The Sahara is the world''s largest hot desert.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_023','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why do scientists and support staff go to Antarctica if it has no permanent native population?','["To farm tropical fruits.","To temporarily stay at research stations to study the extreme climate, ice, wildlife, and Earth''s environment.","To build large shopping centers.","To start new countries."]',1,'It is a massive, frozen laboratory for science!','Antarctica has no permanent native human population, although scientists and support staff stay at research stations... temporary research teams study climate, ice...','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_024','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why is understanding the concept of a ''Hemisphere'' useful when looking at a globe?','["It tells you the exact time of day.","It divides the Earth in half (North/South or East/West), helping you quickly describe the general location of massive landmasses like continents.","It shows you the depth of the ocean.","It proves that the Earth is flat."]',1,'It''s an easy way to slice the Earth in half to find things!','Hemisphere: One half of Earth... Continents can be located in relation to the equator, the poles, and the oceans. Northern Hemisphere: Contains most of Asia...','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_025','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'How does the Amazon River in South America compare to other rivers globally?','["It is the shortest river in the world.","It carries more water than any other river in the world by volume.","It is made entirely of ice.","It is located in the middle of a desert."]',1,'It is massive and supports the huge rainforest around it!','The Amazon River carries more water than any other river in the world by volume.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_026','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'What physical features make North America geographically diverse?','["It only contains hot deserts.","It stretches across multiple climate zones, including Arctic environments, massive forests, grasslands, the Rocky Mountains, and tropical areas.","It is entirely covered in a single glacier.","It has no mountains or rivers."]',1,'From snowy Canada to tropical Mexico!','North America includes Arctic environments, forests, grasslands, mountains, tropical areas, and many islands.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_027','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'What is the ''Great Barrier Reef'' and where is it located?','["A massive mountain range in Europe.","The world''s largest coral reef system, located off the northeast coast of Australia.","A large desert in South America.","A frozen lake in Antarctica."]',1,'It is an underwater wonderland full of sea life!','The Great Barrier Reef, off Australia''s northeast coast, is the world''s largest coral reef system.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_028','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Why might a map projection change how large a continent appears compared to a globe?','["Because maps are always broken.","Because taking a 3D spherical globe and flattening it onto a 2D map requires stretching the image, which distorts the true size of landmasses (especially near the poles).","Because continents change size every day.","Because globes are not accurate."]',1,'Flattening a round object always stretches the picture!','Remember that the map projection can change how large continents appear.','2026-11-01 07:53:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_029','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'Which continent is known for the Alps, the Danube River, and having extensive coastlines?','["Asia","Africa","Europe","South America"]',2,'It has a very jagged coastline with many peninsulas.','Europe... Features: Alps, Danube River, Mediterranean coast, and northern forests.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_030','Geography','Physical Geography','Topic 2: Continents of the World','Primary',5,'How does the continent of Asia compare to other continents in terms of size and population?','["It is the smallest and has no people.","It is the largest continent by both land area and population.","It is the second largest, after Africa.","It is mostly covered by the ocean."]',1,'More people live in Asia than any other continent!','Asia is the largest continent by land area and population.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_031','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Analyze the epistemological problem with the ''seven-continent model'' as a strict geographical fact.','["The model is a flawless representation of geology.","The concept of a ''continent'' is largely a cultural and historical construct rather than a strict geological one; for instance, Europe and Asia form a single continuous tectonic landmass (Eurasia) but are separated culturally.","The model proves that continents do not exist.","The model requires all continents to be exactly the same size."]',1,'Geography is physical, but how we name the map is cultural!','There are different ways of grouping Earth''s landmasses. For example, some educational systems combine Europe and Asia as Eurasia... Europe and Asia form one connected landmass... even though they are commonly taught as separate continents.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_032','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Synthesize how the geographic vastness of the Asian continent inherently dictates its extreme climatic diversity.','["The vastness ensures the climate is perfectly uniform everywhere.","Because Asia spans massively from the high-latitude Arctic circle in the north all the way down to the low-latitude tropical equator in the south, it encompasses nearly every major biome on Earth, from tundra to rainforest.","The vastness prevents any weather from forming.","The vastness means Asia is entirely a desert."]',1,'When a landmass is that big, it covers every type of weather zone!','It stretches from the Arctic region in the north to tropical regions in the south. Features: Himalayas, Gobi Desert, large river systems, forests...','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_033','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Critique the monolithic stereotype of ''Africa'' often presented in popular media using geographical and cultural evidence.','["Africa is a single country with one language and one desert.","The stereotype is factually incorrect; Africa is the second-largest continent, comprising 54 sovereign nations, encompassing radically diverse biomes (from the arid Sahara to the Congo rainforest), and housing thousands of distinct languages and ethnic cultures.","Africa is entirely covered in rainforests and has no deserts.","Africa has no people and is only a wildlife reserve."]',1,'Treating a massive, diverse continent like a single country is a huge mistake!','Africa contains a remarkable variety of languages, cultures, wildlife, and landscapes... No continent has just one culture or one way of life. There is great diversity within every continent.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_034','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Evaluate the geopolitical significance of Antarctica''s ''international treaty system''.','["The treaty allows any country to claim Antarctica for military bases.","The Antarctic Treaty is a unique diplomatic milestone that suspended sovereign territorial claims, permanently dedicating an entire continent exclusively to peaceful scientific research and environmental protection, preventing militarization.","The treaty forced all scientists to leave the continent.","The treaty divided Antarctica equally among all seven continents."]',1,'It is the only continent reserved entirely for peace and science!','Antarctica has no sovereign countries and is governed through an international treaty system... temporary research teams study climate, ice, wildlife...','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_035','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Analyze how the concept of ''Oceania'' solves a cartographic categorization problem.','["It sinks Australia into the ocean.","Traditional continent models focus on massive, continuous landmasses. ''Oceania'' acts as a regional categorization that logically groups the isolated continental landmass of Australia with the thousands of culturally and geographically linked archipelagos (like New Zealand and Fiji) scattered across the vast Pacific Ocean.","It proves that islands cannot exist.","It combines North and South America."]',1,'If you only count big landmasses, you leave out thousands of important islands!','Oceania is a wider geographical region that includes Australia, New Zealand, Papua New Guinea, and many Pacific island nations.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_036','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Synthesize the relationship between the ''Equator'' and the biodiversity found in South America and Africa.','["The equator freezes the continents, destroying biodiversity.","The equator bisects both continents, anchoring massive tropical zones. These low-latitude regions receive direct, intense solar radiation and heavy rainfall year-round, fueling hyper-productive ecosystems like the Amazon and Congo rainforests, which harbor immense global biodiversity.","The equator causes the continents to float away.","The equator has no effect on biology or climate."]',1,'The middle of the Earth gets the most sun and rain, perfect for massive jungles!','Equator: Crosses South America, Africa... South America has tropical rainforests... Amazon River, Amazon rainforest... Africa... Congo Basin...','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_037','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Evaluate the impact of geographic isolation on the biodiversity of Australia.','["Isolation meant Australia had no animals at all.","Millions of years of deep geographic isolation from other major landmasses allowed Australia''s flora and fauna to follow a highly divergent evolutionary path, resulting in high rates of endemism (species found nowhere else on Earth, like marsupials).","Isolation meant Australia shared all its animals with Europe.","Isolation caused the continent to shrink."]',1,'When animals are trapped on an island for millions of years, they evolve very differently!','Studying continents helps us... Learn how plants and animals adapt to different environments.','2026-11-01 07:53:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_038','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'How does the orientation of major mountain ranges (like the Andes in South America vs. the Himalayas in Asia) dictate regional climate and river systems?','["Mountain ranges have no impact on weather or rivers.","Massive mountain chains act as orographic barriers, blocking weather systems (creating rain shadows like the Atacama Desert) and serving as the high-altitude ''water towers'' (source glaciers) for massive continental river systems (like the Amazon or Ganges).","Mountains absorb all the water, preventing rivers from forming.","Mountains only affect the climate in the Northern Hemisphere."]',1,'Mountains block clouds from passing and store snow that melts into rivers!','Features: Himalayas, Gobi Desert, large river systems... South America... Andes Mountains, and Atacama Desert. Amazon River...','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_039','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Critique the historical mapping convention that places Europe at the top-center of world maps.','["It is a naturally occurring law of physics.","Placing Europe at the top-center is a purely arbitrary, Eurocentric cartographic convention established during the era of European global naval dominance; since the Earth is a sphere floating in space, there is no objective ''up'' or ''center''.","It is required because Europe is the largest continent.","It is because the magnetic north pole is located in Paris."]',1,'Maps are drawn by people, and people often put themselves in the center of the picture!','A world map or globe helps us see these relationships. Remember that the map projection can change how large continents appear.','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_040','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Analyze the statement ''Greenland is the world''s largest island that is not classified as a continent'' in terms of geographical definitions.','["It proves Greenland is actually a continent.","The boundary between ''island'' and ''continent'' is scientifically arbitrary. Greenland sits on its own tectonic plate, but geographers conventionally use Australia''s landmass size (~7.7 million km²) as the baseline minimum for continental status; everything smaller surrounded by water is an island.","It means Greenland is a peninsula.","It means Greenland is made of artificial ice."]',1,'If Greenland were a little bit bigger, we might have 8 continents!','Greenland is the world''s largest island that is not classified as a continent... Australia... Smallest [continent].','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_041','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Synthesize how the ''Northern Hemisphere'' dominance of landmasses impacts global human population distribution.','["It means all humans live in the Southern Hemisphere.","Because the vast majority of Earth''s habitable, arable landmasses (Eurasia, North America) are concentrated north of the equator, the overwhelming majority of the global human population, historical empires, and modern economic centers are subsequently located in the Northern Hemisphere.","It means the Northern Hemisphere is entirely ocean.","It forces humans to live only on the equator."]',1,'More land equals more room for people to live and grow food!','Northern Hemisphere: Contains most of Asia, Europe, and North America. Southern Hemisphere: Contains Antarctica, most of Australia...','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_042','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Evaluate the importance of the ''Great Lakes'' and the ''Mississippi River'' to the geographic and economic development of North America.','["They are only used for swimming.","These massive interconnected freshwater systems provide vital, natural interior navigation routes and irrigation, acting as an economic superhighway that facilitated the rapid agricultural and industrial development of the North American interior.","They prevented any human settlement in North America.","They are entirely frozen and cannot be used."]',1,'Rivers are nature''s highways for transporting heavy goods!','North America... Features: Rocky Mountains, Great Lakes, Mississippi River...','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_043','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Analyze the environmental vulnerability of ''Oceania'' in the context of global climate change.','["Oceania is completely immune to climate change.","Because Oceania consists largely of thousands of low-lying Pacific island nations and fragile coral ecosystems (like the Great Barrier Reef), the region faces acute, existential threats from rising global sea levels, ocean acidification, and extreme weather events.","Climate change will cause Oceania to grow into a massive continent.","The islands are protected by massive concrete walls."]',1,'When you live on an island only a few feet above the ocean, rising water is an emergency.','Oceania is a wider geographical region that includes Australia, New Zealand... and many Pacific island nations. Features... coral reefs, and Pacific islands.','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_044','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'How does the ''Sahara Desert'' act as both a barrier and a bridge in the human history of Africa?','["It acts as a permanent wall that no human has ever crossed.","While its extreme hyper-aridity acts as a massive geographic barrier isolating sub-Saharan Africa from the Mediterranean, historically, nomadic cultures utilized specialized knowledge and camel caravans to forge trans-Saharan trade routes, bridging the continent.","It is actually a massive ocean.","It was completely paved over by early humans."]',1,'It is a deadly obstacle, but clever merchants found ways to cross the sand!','Africa... Features: Sahara Desert... The Sahara is the world''s largest hot desert... Studying continents helps us... Understand how geography affects transport, trade, and settlement.','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_continents_045','Geography','Physical Geography','Topic 2: Continents of the World','Primary',10,'Synthesize why understanding ''Hemispheres'' is crucial for understanding global seasons.','["Hemispheres dictate the time of day.","Because Earth is tilted on its axis, as it revolves around the Sun, the Northern and Southern Hemispheres receive opposing angles of solar radiation. Therefore, when the Northern Hemisphere experiences summer, the Southern Hemisphere concurrently experiences winter.","Hemispheres prove that seasons do not exist.","Seasons are identical in all hemispheres simultaneously."]',1,'When it is snowing in New York, it is a hot summer day in Australia!','Hemisphere: One half of Earth... Northern Hemisphere... Southern Hemisphere...','2026-11-01 07:53:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_001','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What is an ocean?','["A small lake","A vast body of salt water","A river in a forest","A mountain made of ice"]',1,'It covers most of our planet.','An ocean is a vast body of salt water.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_002','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Approximately what percentage of Earth''s surface is covered by oceans?','["29%","50%","71%","90%"]',2,'More than two-thirds of the Earth is covered in ocean water.','Oceans cover about 71% of Earth''s surface and contain most of the planet''s water.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_003','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'How many named oceans are there on Earth?','["Three","Four","Five","Seven"]',2,'They are the Pacific, Atlantic, Indian, Arctic, and Southern.','Although we name five oceans, they are connected to form one large global ocean.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_004','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Which ocean is the largest and deepest?','["The Atlantic Ocean","The Indian Ocean","The Arctic Ocean","The Pacific Ocean"]',3,'It covers more area than all the land on Earth combined.','The Pacific Ocean is the largest and deepest of the five oceans.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_005','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Which is the smallest and generally shallowest of the five oceans?','["The Atlantic Ocean","The Indian Ocean","The Arctic Ocean","The Southern Ocean"]',2,'It is located near the North Pole.','The Arctic Ocean... It is the smallest and generally shallowest of the five oceans.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_006','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Which ocean lies between the Americas to the west and Europe and Africa to the east?','["The Pacific Ocean","The Atlantic Ocean","The Indian Ocean","The Southern Ocean"]',1,'Many famous historical ships sailed across this ocean.','The Atlantic Ocean lies between the Americas to the west and Europe and Africa to the east.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_007','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Which ocean surrounds Antarctica?','["The Arctic Ocean","The Indian Ocean","The Southern Ocean","The Pacific Ocean"]',2,'It is at the very bottom of the globe.','The Southern Ocean surrounds Antarctica...','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_008','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What is an ''ocean current''?','["A mountain underwater","A large, continuous movement of ocean water","A type of sea turtle","A boat used for fishing"]',1,'It acts like a river flowing through the ocean.','Current: A large, continuous movement of ocean water.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_009','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What does ''overfishing'' mean?','["Catching fish faster than populations can replace them","Feeding fish in an aquarium","Swimming with dolphins","Protecting coral reefs"]',0,'It happens when we take too many fish from the sea.','Overfishing: Catching fish faster than populations can replace them.','2026-11-01 07:53:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_010','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What is ''pollution''?','["A type of ocean plant","Harmful substances or waste entering the environment","A type of clean energy","A coral reef"]',1,'Plastic rubbish is a common type of pollution.','Pollution: Harmful substances or waste entering the environment.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_011','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Where is the Mariana Trench, the deepest known part of the ocean, located?','["The Atlantic Ocean","The Indian Ocean","The Pacific Ocean","The Arctic Ocean"]',2,'It is deeper than Mount Everest is tall.','The Mariana Trench, the deepest known part of the ocean, is in the western Pacific.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_012','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Which ocean lies mainly between Africa, Asia, and Australia?','["The Pacific Ocean","The Atlantic Ocean","The Indian Ocean","The Arctic Ocean"]',2,'It contains many warm, tropical islands.','The Indian Ocean lies mainly between Africa, Asia, and Australia.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_013','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What is a ''coral reef''?','["A large ship","An underwater ecosystem built mainly by reef-forming corals","A type of plastic pollution","A river that flows into the sea"]',1,'They are very colorful and shelter many fish.','Coral reef: An underwater ecosystem built mainly by reef-forming corals.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_014','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'Where is the Arctic Ocean located?','["Around the South Pole","Around the North Pole","Between Africa and South America","In the middle of the Pacific"]',1,'It is mostly covered by sea ice.','The Arctic Ocean surrounds the region near the North Pole.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_015','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What is one way people can help protect the oceans?','["Throwing rubbish into rivers","Leaving plastic on the beach","Reducing unnecessary plastic and disposing of waste responsibly","Pouring oil into drains"]',2,'Keeping trash out of the water helps sea animals survive.','Use reusable items where practical and reduce unnecessary plastic. Put rubbish in suitable bins...','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_016','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',1,'What are ''waves'' in the ocean?','["Fish jumping out of the water","A movement of energy through water, often caused by wind","Boats moving very fast","Ice melting at the poles"]',1,'You can surf on them when they reach the beach.','Wave: A movement of energy through water, often caused by wind.','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_017','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why is it scientifically accurate to say there is only ''one global ocean''?','["Because all the oceans are the exact same temperature.","Because the five named oceans are not separated by physical land walls; they are fully connected to each other, allowing water to flow freely around the planet.","Because the other four oceans dried up.","Because the government made it a law."]',1,'The names just help us map different areas of the same giant body of water.','Although we name five oceans, they are connected to form one large global ocean. Ocean water moves around the planet through currents...','2026-11-01 07:53:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_018','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How do oceans directly influence the world''s weather and climate?','["They stop the wind from blowing.","Ocean water absorbs heat from the Sun, and evaporation from the oceans supplies most of the water vapour that forms clouds and rain.","They freeze all the clouds in the sky.","They create mountains that block the wind."]',1,'Without the oceans, there would be no rain!','Ocean water stores and moves heat. Evaporation from oceans supplies much of the water vapour that later forms clouds and precipitation.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_019','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why do different parts of the ocean support different kinds of marine life?','["Because all fish only like warm water.","Because factors like temperature, sunlight, water depth, and nutrients vary greatly (e.g., shallow coral reefs vs. the dark, high-pressure deep ocean).","Because the government places animals in specific spots.","Because animals cannot swim."]',1,'A coral reef needs sunlight, but deep-sea creatures survive in total darkness.','Marine life is not distributed equally. Temperature, sunlight, water depth, nutrients, and available food affect which organisms can live in each habitat.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_020','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How does ''ocean acidification'' threaten marine life?','["It makes the water too sweet.","The ocean absorbs carbon dioxide from the atmosphere, which changes the seawater chemistry, making it harder for corals and shellfish to build their skeletons.","It turns the ocean into solid ice.","It forces fish to swim backward."]',1,'The water becomes slightly acidic, which dissolves fragile shells.','Ocean acidification: The ocean absorbs some carbon dioxide from the atmosphere, changing seawater chemistry and making it harder for some organisms to build shells...','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_021','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why does rubbish dropped in a river far inland eventually threaten the ocean?','["Because birds carry the rubbish to the ocean.","Because rivers naturally flow downstream and eventually empty into the sea, carrying plastic pollution and chemicals with them.","Because the ocean reaches out and pulls the rubbish in.","Because rivers are part of the ocean."]',1,'All waterways eventually lead to the ocean!','Rivers and drains can carry rubbish from inland communities to the sea, so keeping local surroundings clean also helps protect oceans.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_022','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How do ''ocean currents'' benefit marine ecosystems globally?','["They freeze the ocean solid.","They act like giant conveyor belts that transport essential heat from the equator and nutrients to different parts of the globe.","They stop fish from swimming.","They empty the ocean of water."]',1,'They help mix the warm and cold water around the Earth.','Ocean water moves around the planet through currents, which transport heat and nutrients.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_023','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'What is a major environmental challenge specifically facing the Arctic Ocean today?','["It is getting too crowded with tropical fish.","The amount of seasonal sea ice is declining over the long term due to rising global temperatures (climate change).","The ocean is turning into fresh water.","It is expanding and covering Europe."]',1,'Less ice means trouble for animals like polar bears.','Interesting fact: The amount of Arctic sea ice changes with the seasons and has declined over the long term... Climate change: Rising ocean temperatures...','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_024','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How does the Antarctic Circumpolar Current in the Southern Ocean affect the rest of the world?','["It blocks all ships from sailing.","It flows continuously around Antarctica, acting as a massive mixer that helps connect the water of the Atlantic, Pacific, and Indian Oceans.","It freezes the entire planet.","It pushes all the water into space."]',1,'It is the only current that flows completely around the globe without hitting land!','Interesting fact: The Antarctic Circumpolar Current flows around Antarctica and helps connect the world''s major ocean systems.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_025','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why is the Atlantic Ocean considered historically significant for human civilization?','["It is the only ocean with fish in it.","It lies exactly between the Americas, Europe, and Africa, making it a critical, historical route for international travel, trade, and exploration.","It is completely frozen and can be walked across.","It is the smallest ocean and easy to avoid."]',1,'Many famous explorers and trade ships crossed this ocean.','Interesting fact: The Atlantic has long been an important route for international travel, fishing, and trade.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_026','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How does ''climate change'' physically threaten coastal communities?','["It makes the beaches larger.","Rising global temperatures cause glaciers to melt and ocean water to expand, leading to rising sea levels that can flood coastal homes and habitats.","It turns the ocean water into solid rocks.","It stops all ocean waves from crashing."]',1,'Higher water means floods for cities built near the beach.','Climate change: Rising ocean temperatures and sea levels affect marine habitats and coastal communities.','2026-11-01 07:53:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_027','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why are ''coral reefs'' sometimes called the rainforests of the sea?','["Because trees grow out of them.","Because, although they are found in shallow waters, they shelter a massive variety of fish and marine organisms, providing a highly diverse habitat.","Because they are green and leafy.","Because it rains a lot there."]',1,'They are packed with different kinds of colorful life!','Coral reefs: Found mainly in warm, shallow waters; they shelter many fish and other organisms.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_028','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'What role do tiny marine organisms like ''plankton'' play in the ocean?','["They eat whales and sharks.","They form the fundamental base (foundation) of many ocean food webs; without them, larger animals would starve.","They create plastic pollution.","They drain the ocean of water."]',1,'Even the biggest whales survive by eating tiny plankton!','Tiny marine organisms also form the foundation of many ocean food webs.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_029','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'How can buying seafood from ''responsibly managed sources'' protect the ocean?','["It makes the fish taste better.","It helps prevent ''overfishing'' by ensuring that fish are caught at a sustainable rate, allowing their populations time to recover and reproduce.","It ensures the fish are cooked properly.","It stops people from eating seafood altogether."]',1,'It means leaving enough fish in the sea to make baby fish for next year!','Choose seafood from responsibly managed sources when possible... Overfishing: Catching fish faster than populations can recover can damage food webs.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_030','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'What is a unique feature of the ''Mid-Atlantic Ridge''?','["It is a massive bridge built by humans.","It is a major underwater mountain chain that runs down the center of the Atlantic Ocean.","It is a deep trench where water drains away.","It is a floating island of plastic."]',1,'There are giant mountains hidden under the ocean waves!','Atlantic Ocean... Features: A major underwater mountain chain called the Mid-Atlantic Ridge.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_031','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',5,'Why do coastal habitats like ''mangroves'' matter to the ocean ecosystem?','["They block ships from entering the port.","They act as crucial nurseries, providing safe shelter and feeding areas for many species of young fish and marine life.","They dry up the ocean water.","They are the only place sharks can sleep."]',1,'Baby fish hide in the mangrove roots to stay safe from predators!','Coastal habitats: Mangroves, salt marshes, and seagrass beds provide shelter and feeding areas for many species.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_032','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Analyze the paradox of the ocean functioning as both a ''carbon sink'' and a victim of ''ocean acidification''.','["The ocean produces all the world''s carbon dioxide.","While the ocean beneficially absorbs massive amounts of atmospheric CO2 (mitigating climate change), this chemical absorption creates carbonic acid, which catastrophically lowers the ocean''s pH and prevents calcifying organisms (like corals) from building their skeletal structures.","The ocean prevents carbon dioxide from entering the atmosphere entirely.","Carbon dioxide turns ocean water into fresh drinking water."]',1,'The ocean helps us by absorbing bad gases, but it poisons the coral reefs in the process!','Ocean acidification: The ocean absorbs some carbon dioxide from the atmosphere, changing seawater chemistry and making it harder for some organisms to build shells or skeletons.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_033','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Critique the geographical convention of dividing the World Ocean into five distinct named bodies.','["It is geologically proven that the oceans are separated by massive underground walls.","The division is purely an arbitrary, human cartographic convention used to simplify regional geography; hydrographically, it is a single, continuous, highly integrated global hydrosphere where water and energy circulate freely.","It proves that water cannot mix between different oceans.","The five oceans were created by five different meteor strikes."]',1,'The borders between oceans only exist on maps, not in the water!','Although we name five oceans, they are connected to form one large global ocean. Ocean water moves around the planet through currents... Their boundaries are geographical divisions used to help us study the global ocean.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_034','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Synthesize how the ''thermohaline circulation'' (ocean currents driven by temperature and salt) impacts global terrestrial climates.','["It freezes the entire planet.","These massive, deep-ocean currents act as a global conveyor belt, transporting immense thermal energy from the equator toward the poles, fundamentally moderating regional terrestrial climates (e.g., keeping Northern Europe warmer than it otherwise would be).","It causes all oceans to boil and evaporate.","It prevents any wind from blowing on land."]',1,'Currents move warm water away from the equator, warming up cold countries!','Ocean water moves around the planet through currents, which transport heat and nutrients... Ocean water stores and moves heat.','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_035','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Evaluate the cascading ecological impact of ''overfishing'' an apex predator (like sharks or tuna) on an open ocean food web.','["It only affects the apex predator and nothing else.","Removing apex predators fundamentally destabilizes the trophic cascade; prey populations explode uncontrollably, which then overconsume foundational resources (like plankton), leading to a systemic collapse of the entire localized ecosystem.","It causes the ocean to immediately run out of water.","It helps the ecosystem by removing dangerous animals."]',1,'In nature, removing the top predator ruins the balance for every animal below it!','Overfishing: Catching fish faster than populations can recover can damage food webs. Open ocean: Home to tuna, dolphins, sharks...','2026-11-01 07:53:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_036','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Analyze the geographic and economic significance of the ''Indian Ocean'' during historical and modern monsoonal trade.','["The Indian Ocean was completely unnavigable.","The cyclical, predictable nature of the monsoon winds allowed merchants to reliably sail massive cargo loads between Africa, Arabia, and Asia, establishing the Indian Ocean as one of the most lucrative and culturally transformative maritime trade networks in human history.","The monsoon winds prevented any ships from leaving port.","The Indian Ocean was only used to transport ice."]',1,'Sailors used these reliable seasonal winds like a free engine to cross the sea!','Indian Ocean... Interesting fact: Seasonal monsoon winds influence weather and rainfall around parts of the Indian Ocean.','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_037','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Evaluate the threat of ''plastic pollution'' not just as a physical hazard, but as a systemic biological threat through microplastics.','["Plastic is a natural food source for marine life.","Beyond physical entanglement, plastics degrade into microscopic particles (microplastics) that are ingested by foundational species (like plankton), bioaccumulating toxic chemicals upward through the food web, eventually threatening human food safety.","Plastic instantly dissolves into harmless water.","Plastic pollution only affects birds, not fish."]',1,'When fish eat tiny pieces of broken plastic, the humans who eat the fish are eating plastic too!','Plastic pollution: Plastic waste can injure marine animals or be mistaken for food.','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_038','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Synthesize the relationship between the ''Arctic Ocean''s'' declining sea ice and the acceleration of global warming (the albedo effect).','["Declining sea ice cools the planet down.","White sea ice effectively reflects solar radiation back into space (high albedo). As the ice melts, it exposes dark ocean water, which absorbs more solar heat, causing temperatures to rise further and accelerating even more ice melt in a dangerous feedback loop.","Sea ice has no effect on solar radiation.","Melting sea ice creates new mountains."]',1,'Ice acts like a giant mirror reflecting the sun''s heat away from Earth!','Arctic Ocean... Interesting fact: The amount of Arctic sea ice changes with the seasons and has declined over the long term... Climate change: Rising ocean temperatures...','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_039','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Critique the anthropocentric perspective that oceans are primarily valuable as ''routes for ships carrying people and goods''.','["This is the only correct way to view the ocean.","While economically vital to humans, this utilitarian perspective dangerously ignores the ocean''s intrinsic ecological value as Earth''s primary life-support system, holding immense biodiversity and functioning as the primary driver of global climate regulation.","Oceans should only be used as giant trash dumps.","Oceans have no ecological value whatsoever."]',1,'The ocean is the lungs of the planet, not just a road for cargo ships!','They support life: Oceans provide habitats... They influence weather and climate... They connect people: Ships transport food... (Synthesis: The ocean is a living system, not just a highway).','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_040','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Analyze how the extreme environmental conditions of the ''deep ocean'' drive unique biological adaptations.','["Deep ocean animals are exactly identical to shallow water fish.","The complete absence of sunlight, freezing temperatures, and crushing hydrostatic pressure forces deep-sea organisms to evolve radical adaptations, such as bioluminescence or relying on chemosynthesis from hydrothermal vents instead of photosynthesis.","The deep ocean is actually very warm and brightly lit.","No living organisms can survive in the deep ocean."]',1,'To survive miles underwater in the dark, animals have to evolve bizarre and amazing features!','Deep ocean: Contains organisms adapted to darkness, cold, and high pressure.','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_041','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Evaluate the geopolitical vulnerability of ''coastal habitats'' (like mangroves and salt marshes) in the face of modern urban development.','["Coastal habitats are completely immune to human development.","These vital ecosystems are frequently perceived as ''wastelands'' and are systematically dredged or paved over for lucrative coastal real estate, destroying crucial marine nurseries and removing natural storm-surge barriers that protect inland cities.","Urban development naturally creates new mangrove forests.","Coastal habitats are only destroyed by sharks."]',1,'Paving over a swamp to build a hotel destroys the ocean''s natural defense system against floods!','Coastal habitats: Mangroves, salt marshes... provide shelter... Habitat damage: Coastal development... can harm reefs, mangroves, and other habitats.','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_042','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Synthesize how the ''Mariana Trench'' challenges our understanding of the limits of Earth''s biosphere.','["It proves that life cannot exist below 100 meters.","Despite being the deepest, most highly pressurized, and inaccessible point in the ocean, extreme-adapted microbial and scavenging life still exists there, proving that the parameters for biological survival on Earth are vastly wider than surface conditions suggest.","It is completely devoid of any water.","It proves that the ocean floor is flat."]',1,'Even in the deepest, darkest, most crushing part of the planet, life finds a way!','Pacific Ocean... The Mariana Trench, the deepest known part of the ocean, is in the western Pacific. Deep ocean: Contains organisms adapted to darkness, cold, and high pressure.','2026-11-01 07:53:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_043','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Analyze the statement: ''Rivers and drains can carry rubbish from inland communities to the sea''. How does this reframe the responsibility for ocean conservation?','["It proves that only coastal cities are responsible for the ocean.","It demonstrates that ocean conservation is not a localized, coastal issue; because watersheds are interconnected, inland populations hundreds of miles from the sea are equally culpable for marine pollution and must engage in systemic waste management.","It means the ocean pushes rubbish into the rivers.","It proves that rivers are not connected to the ocean."]',1,'Littering in a city far away from the beach can still kill a sea turtle!','Rivers and drains can carry rubbish from inland communities to the sea, so keeping local surroundings clean also helps protect oceans.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_044','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Evaluate the distinction between a ''Sea'' and an ''Ocean'' in geographical taxonomy.','["A sea is made of fresh water; an ocean is made of salt water.","An ocean is a vast, continuous body of open salt water. A sea is generally a smaller, localized subdivision of an ocean that is partially enclosed or bounded by adjacent landmasses (like the Mediterranean Sea).","They are two words for the exact same thing.","A sea is entirely frozen; an ocean is liquid."]',1,'The Mediterranean Sea is mostly surrounded by land, but the Pacific Ocean is wide open!','Ocean: A vast body of salt water. Sea: A smaller part of the ocean, often partly enclosed by land.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_045','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Synthesize how the ''evaporation'' of ocean water is the foundational mechanism for terrestrial agriculture.','["Evaporation removes all the water from the planet forever.","Oceanic evaporation desalinates seawater, lifting massive volumes of fresh water vapor into the atmosphere, which is then transported by wind currents to precipitate as rain over landmasses, providing the vital freshwater required for all terrestrial farming.","Evaporation causes the oceans to freeze.","Evaporation has no connection to agriculture."]',1,'Without the salty ocean evaporating, farmers would have no fresh rain for their crops!','They influence weather and climate: ...Evaporation from oceans supplies much of the water vapour that later forms clouds and precipitation.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_oceans_global_046','Geography','Physical Geography','Topic 3: Oceans of the World','Primary',10,'Critique the effectiveness of solving ''plastic pollution'' solely through individual actions (like using reusable bags).','["Individual actions immediately eliminate 100% of global plastic.","While individual actions raise awareness, they are insufficient to solve the crisis without systemic, top-down industrial reform; the vast majority of marine plastic originates from unregulated commercial fishing gear (ghost nets) and poor municipal waste infrastructure in developing nations.","Plastic pollution is actually beneficial for the ocean.","Individual actions have absolutely no impact and should be stopped."]',1,'Using a paper straw helps, but stopping giant factories from dumping waste is the real solution!','Everyone can contribute to ocean protection... Use reusable items where practical and reduce unnecessary plastic. Put rubbish in suitable bins... (Synthesis: Individual action is necessary but part of a larger industrial challenge).','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_001','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What are landforms?','["Only things built by humans","Natural shapes and features of the Earth''s surface","Only rivers and oceans","Types of weather"]',1,'They include mountains, valleys, and plains.','Landforms are the natural shapes and features of the Earth''s surface.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_002','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a mountain?','["A flat area of land","A high area of land that rises steeply above the surrounding landscape","A deep hole in the ground","A body of water"]',1,'They are the tallest landforms.','Mountains are high areas of land that rise steeply above the surrounding landscape.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_003','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'Which of these is a famous mountain range in Asia?','["The Andes","The Himalayas","The Alps","The Rocky Mountains"]',1,'Mount Everest is located here.','Examples: The Himalayas in Asia...','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_004','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a hill?','["A raised area of land, usually lower and more gently sloping than a mountain","A deep, narrow river","A flat desert","A large piece of ice"]',0,'They are like small, gentle mountains.','Hills are raised areas of land, usually lower and more gently sloping than mountains.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_005','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a plain?','["A deep canyon","A broad area of relatively flat or gently rolling land","A steep mountain peak","An underwater volcano"]',1,'They are often used for farming because they are flat.','Plains are broad areas of relatively flat or gently rolling land.','2026-11-01 07:53:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_006','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a plateau?','["A low area between two mountains","A large area of high land with a relatively flat top","A sandy beach","An island made of ice"]',1,'It looks like a giant table.','A plateau is a large area of high land with a relatively flat or gently rolling top.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_007','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is another common name for a plateau?','["Tableland","Canyon","Peak","Desert"]',0,'It is flat on top, like a table.','A plateau... is sometimes called a tableland.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_008','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a valley?','["A high, flat mountain top","A low area of land between hills or mountains","An ocean trench","A flat plain covered in sand"]',1,'Rivers often flow through the bottom of them.','A valley is a low area of land between hills or mountains, or between higher areas of land.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_009','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What defines a desert?','["It is always extremely hot.","It is a region that receives very little precipitation (rain or snow).","It has no sand.","It is always located near the ocean."]',1,'A desert is defined by how dry it is, not how hot it is.','A desert is a region that receives very little precipitation (rain or snow).','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_010','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is an island?','["Land surrounded by water on most sides","An area of land surrounded by water on all sides","A tall mountain","A deep river valley"]',1,'You need a boat to get there.','An island is an area of land surrounded by water on all sides.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_011','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a peninsula?','["Land surrounded by water on all sides","An area of land surrounded by water on most sides but connected to a larger land area","A dry desert","A type of volcano"]',1,'It sticks out into the water like a finger.','A peninsula is an area of land surrounded by water on most sides but connected to a larger land area.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_012','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a canyon or gorge?','["A flat grassy plain","A deep, narrow valley with steep sides, often carved by a river","A flat plateau","A small, gentle hill"]',1,'The Grand Canyon is a famous example.','A canyon or gorge: A deep, narrow valley with steep sides, often carved by a river over a long time.','2026-11-01 07:53:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_013','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a volcano?','["A completely flat plain","An opening in the Earth''s crust through which molten rock, gases, and ash may escape","A frozen glacier","A river that flows underground"]',1,'It can erupt with lava.','Volcano: An opening in the Earth''s crust through which molten rock, gases, and ash may escape.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_014','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What does ''erosion'' mean?','["Building new mountains","The wearing away and movement of soil or rock","Planting new trees","When water turns into ice"]',1,'Wind and water slowly break rocks down over time.','Erosion: The wearing away and movement of soil or rock.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_015','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',1,'What is a ''peak''?','["The bottom of a valley","The highest point of a mountain","A type of flat plain","A deep canyon"]',1,'It is the very top.','Peak: The highest point of a mountain.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_016','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why is the climate on top of a mountain often different from the land at the bottom?','["Because the top of the mountain is closer to the sun, making it hotter.","Because higher places are often colder than nearby lowlands due to altitude.","Because mountains block all the weather.","There is no difference in climate."]',1,'The higher you go, the thinner and colder the air gets!','Climate: Higher places are often colder than nearby lowlands.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_017','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why are ''plains'' considered highly suitable for human settlements and farming?','["Because they have steep slopes that prevent floods.","Because they offer flat land, making it easier to build roads and towns, and often have deep, fertile soil for growing crops.","Because they receive no rainfall.","Because they are always covered in ice."]',1,'It is much easier to drive a tractor on flat ground!','Many plains have deep, fertile soil suitable for farming. Flat land often makes it easier to build roads, railways, towns, and cities.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_018','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How are ''valleys'' and ''rivers'' often connected in geography?','["Rivers always avoid flowing into valleys.","Many valleys are actually formed or carved out over thousands of years by the flowing water of rivers.","Valleys are caused by rivers drying up completely.","Rivers only flow on top of mountains, not in valleys."]',1,'Water flows downhill, cutting into the dirt and rock to make a valley!','Many valleys are formed or shaped by rivers and glaciers.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_019','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why is it incorrect to assume that all deserts are hot and sandy?','["Because deserts are actually giant oceans.","Because a desert is defined by receiving very little precipitation; cold deserts (like the Antarctic Desert) can have freezing temperatures and ice.","Because deserts only exist in Europe.","Because sand doesn''t exist in a true desert."]',1,'Antarctica is the largest desert on Earth because it rarely snows or rains there!','Deserts are not always hot: some are cold for much of the year... Cold deserts may have freezing temperatures and little rainfall.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_020','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How can ''volcanic activity'' act as a creative force in geography, rather than just a destructive one?','["It destroys all land permanently.","When molten rock (lava) escapes and cools, it piles up over time and can build massive new mountains and entirely new islands.","It creates massive deep canyons.","It turns mountains into flat plains."]',1,'The Hawaiian islands were built by volcanoes rising from the ocean floor!','Volcanic activity can build mountains and islands.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_021','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why are coastal landforms (like beaches and cliffs) constantly changing shape?','["Because humans rebuild them every day.","Because they are continuously worn away and reshaped by the powerful forces of waves, wind, and ocean currents.","Because they are made of solid steel.","Because they only change shape during earthquakes."]',1,'The ocean never stops pounding against the coast!','Coastal landforms: Features along the edge of the sea... Waves, wind, and currents help shape them.','2026-11-01 07:53:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_022','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How do mountains play a vital role in providing water to lower areas?','["They absorb all the water like a sponge.","Mountains collect large amounts of snow and rain; when the snow melts, it feeds the rivers and streams that flow down into the valleys.","They push water up into the clouds.","They turn fresh water into salt water."]',1,'The snow on the peak melts and flows down to the farms below!','Water: Many rivers begin in mountain regions where snow and rain supply water.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_023','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'What is a major challenge for humans attempting to build transport networks (like railways) in mountainous regions?','["The ground is too flat.","The steep slopes and rough terrain make it physically difficult, dangerous, and expensive to construct and travel on roads.","Mountains are always too hot to work in.","There is no challenge at all."]',1,'Building a train track up a steep, rocky cliff is very hard!','...but steep slopes can make travel difficult.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_024','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How does the ''wearing away of rocks'' (erosion) over long periods contribute to landform development?','["It makes mountains grow taller.","It slowly breaks down solid rock and moves the dirt, carving out deep canyons and flattening rough landscapes over millions of years.","It turns rock into solid metal.","It completely eliminates all landforms."]',1,'A tiny river can carve a massive canyon if it flows for a million years!','Landforms develop over long periods through processes such as... flowing water, wind, and the wearing away of rocks.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_025','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How does a ''plateau'' differ visually from a ''plain''?','["A plateau is underwater.","While both may feature relatively flat land, a plateau stands significantly higher and elevated above the surrounding land, like a table.","A plain is always covered in snow, a plateau is not.","They are exactly identical."]',1,'A plain is flat on the ground; a plateau is flat up high!','A plateau is a large area of high land with a relatively flat or gently rolling top... A plateau stands higher than much of the land around it.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_026','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why do river valleys often support large human settlements?','["Because they have steep cliffs to hide in.","Because they provide flat land, fertile soil deposited by the river, and a reliable, constant supply of fresh water.","Because they are always dry and desert-like.","Because they are too dangerous for animals."]',1,'People need water to drink and good dirt to farm!','River valleys may have fertile soil and a reliable water supply. Roads, farms, and settlements are often found in suitable valleys.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_027','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'Why is the Arabian Peninsula considered a ''peninsula'' and not an ''island''?','["Because it has no water around it.","Because while it is surrounded by water on most sides, it is still physically connected to the larger landmass of Asia.","Because it is completely surrounded by water.","Because it is located in the sky."]',1,'You can walk to a peninsula without getting your feet wet!','A peninsula is an area of land surrounded by water on most sides but connected to a larger land area.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_028','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How do desert plants and animals survive the harsh geographic conditions of a desert landform?','["They drink from giant lakes.","They rely on special biological adaptations that allow them to survive with extremely limited water and extreme temperatures.","They migrate to the ocean every day.","They do not need water to survive."]',1,'A cactus stores water inside its thick skin!','Desert plants and animals have special adaptations that help them survive with limited water.','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_029','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'What causes natural hazards like landslides in mountainous regions?','["The extreme flatness of the land.","The steep slopes of mountains can become unstable due to heavy rain or earthquakes, causing soil and rocks to crash downwards.","The complete lack of gravity.","Volcanic eruptions only."]',1,'Gravity pulls the loose dirt down the steep sides of the mountain!','Natural hazards: Steep slopes may experience landslides...','2026-11-01 07:54:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_030','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',5,'How do humans actively change or reshape landforms?','["By staring at them.","Through large-scale activities such as farming, mining for minerals, cutting through hills for road construction, and building cities.","By pulling mountains down with ropes.","Humans cannot change landforms."]',1,'We blow up parts of mountains to build tunnels!','People also change landscapes through farming, mining, construction, and road building.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_031','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Analyze the geomorphological relationship between ''rivers'' and ''canyons/gorges''.','["Rivers instantly destroy canyons.","Over immense geological timescales, the continuous kinetic energy and abrasive sediment of flowing river water aggressively erode the bedrock, incising deep, steep-sided gorges into the landscape.","Canyons naturally push rivers out of their paths.","Rivers have no effect on solid rock."]',1,'Water is soft, but over a million years, it can slice through solid stone!','A deep, narrow valley with steep sides, often carved by a river over a long time.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_032','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Synthesize how the topographic characteristics of a ''plain'' facilitate both agricultural and industrial development.','["Plains are entirely composed of infertile rock.","The expansive, low-relief topography prevents soil erosion, allowing deep, fertile topsoil to accumulate for high-yield agriculture, while the lack of geographic barriers drastically reduces the engineering costs of industrial infrastructure (railways/cities).","Plains are too steep for machines to operate.","Plains prevent any water from settling."]',1,'Flat ground means rich dirt stays put, and you don''t have to blast through mountains to lay a train track.','Many plains have deep, fertile soil suitable for farming. Flat land often makes it easier to build roads, railways, towns, and cities.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_033','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Evaluate the dualistic nature of living near a ''volcano'' in terms of human settlement.','["Volcanoes offer no benefits and instantly kill everyone.","While representing a catastrophic existential hazard (eruptions, ash, pyroclastic flows), volcanic activity also deposits highly mineral-rich ash that creates incredibly fertile agricultural soils, incentivizing dense human settlement despite the risks.","Volcanoes only produce cold water, which is completely safe.","Volcanoes are entirely safe and have no hazards."]',1,'The dirt around a volcano is so good for growing crops that people risk living next to a ticking bomb!','Volcanic activity can build mountains and islands... Natural hazards: ...volcanic areas may face eruptions. People choose places based on water, land, climate, work, and safety.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_034','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Critique the classification of ''hills'' versus ''mountains''.','["Hills and mountains are the exact same thing.","The distinction is inherently subjective and geologically arbitrary; while mountains are generally higher with steeper gradients, there is no standardized, universal elevation metric that definitively separates a ''tall hill'' from a ''small mountain''.","Mountains must be exactly 10,000 feet tall.","Hills are always man-made, while mountains are natural."]',1,'Geography doesn''t have a ruler that says ''this is exactly where a hill becomes a mountain.''','Mountains are generally higher than hills, although there is no single height that separates all mountains from hills.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_035','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Analyze how the physical isolation of an ''island'' impacts its ecological and evolutionary development.','["Islands share all their animals with the mainland instantly.","Being completely surrounded by water acts as an absolute geographic barrier, isolating gene pools and forcing endemic flora and fauna to undergo divergent evolution, uniquely adapting to the specific, isolated micro-environment.","Islands prevent any plants from growing.","Islands are always physically connected to the mainland."]',1,'Animals trapped on an island for a million years evolve into completely new species!','An island is an area of land surrounded by water on all sides... Wildlife: Different landforms provide different habitats for plants and animals.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_036','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Synthesize the interaction between ''plateaus'' and ''rivers'' to explain the formation of dramatic landscapes.','["Plateaus completely absorb rivers.","As regional tectonic uplift elevates a massive, flat landmass into a plateau, pre-existing rivers drastically increase their erosive power due to the higher gradient, incising deep gorges and canyons through the rising tableland.","Rivers cannot flow on a plateau.","Rivers build plateaus by depositing sand."]',1,'When the flat land pushes up, the river acts like a saw cutting a deep crack into the earth!','A plateau stands higher than much of the land around it. Rivers may cut deep valleys and gorges into plateaus.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_037','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Evaluate the socio-economic implications of mountain topography on regional integration.','["Mountains make it incredibly easy for cultures to blend.","The extreme relief, steep gradients, and harsh climates of mountains act as severe geographic barriers. This historically isolates communities, impedes the construction of transport networks, and severely limits trade and cultural integration with lowland states.","Mountains have no effect on trade or travel.","Mountains act as giant, smooth highways for trade."]',1,'A giant wall of rock makes it very hard to trade with your neighbors!','People: ... steep slopes can make travel difficult... Transport: Flat areas are often easier for building roads and railways than steep mountains.','2026-11-01 07:54:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_038','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'How does human ''careful land use'' mitigate the destructive effects of geomorphological processes like erosion?','["Humans can turn off gravity.","By implementing practices like terracing steep slopes or planting stabilizing vegetation, humans can artificially reduce the kinetic energy of water runoff, physically anchoring the topsoil and preventing catastrophic erosion or landslides.","Humans can make rocks indestructible.","Careful land use actually speeds up erosion."]',1,'If you plant trees on a hill, the roots hold the dirt together so it doesn''t wash away in the rain!','People also change landscapes... Careful land use helps reduce erosion and protect habitats.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_039','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Critique the meteorological definition of a ''desert''.','["A desert is defined exclusively by having hot sand.","The defining metric of a desert is not high temperature or sand, but rather extreme aridity (a severe precipitation deficit). Therefore, freezing, ice-covered regions like Antarctica are classified as deserts because they receive negligible annual moisture.","Deserts are defined by having high humidity and dense forests.","Deserts are only found near the equator."]',1,'If it doesn''t rain or snow, it''s a desert, even if it''s freezing cold!','A desert is a region that receives very little precipitation (rain or snow). Deserts are not always hot: some are cold for much of the year.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_040','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Analyze how the ''wearing away of rocks'' (weathering and erosion) acts in direct opposition to ''movements inside the Earth'' (tectonic uplift).','["They are exactly the same process.","Tectonic forces (internal movements and volcanism) are constructive, actively pushing the Earth''s crust upwards to build high-relief landforms (mountains). Conversely, erosion by wind and water is destructive, continuously grinding these landforms back down to a flat plain.","Erosion builds mountains, while tectonic plates destroy them.","Neither process has any effect on the Earth''s surface."]',1,'The Earth pushes the mountains up, and the rain slowly grinds them back down!','Landforms develop over long periods through processes such as movements inside the Earth, volcanic activity, flowing water, wind, and the wearing away of rocks.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_041','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Evaluate why the ''Great Plains of North America'' are vital to global food security based on their landform characteristics.','["Because they are covered in dense jungles.","The massive, unbroken expanse of low-relief topography, combined with deep, fertile soils accumulated over millennia, allows for highly mechanized, ultra-efficient, large-scale monoculture farming that produces massive agricultural surpluses.","Because they are located on a steep, rocky mountain.","Because the land is too uneven to farm."]',1,'Flat, rich dirt stretching for miles is perfect for giant tractors and massive farms!','Plains are broad areas of relatively flat or gently rolling land. Many plains have deep, fertile soil suitable for farming... Example: The Great Plains of North America.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_042','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Synthesize how a ''peninsula'' provides strategic geopolitical and economic advantages to a settlement.','["It traps the settlement with no way out.","By being surrounded by water on most sides but retaining a contiguous land bridge, a peninsula offers the immense naval defense and maritime trade advantages of an island, without severing vital overland trade and supply routes to the continental interior.","It means the settlement has no access to the ocean.","It forces the settlement to be completely underground."]',1,'You get the benefit of having ports for ships, but you can still march an army down the road!','A peninsula is an area of land surrounded by water on most sides but connected to a larger land area.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_043','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Analyze how the ''climate'' of a mountain biome changes strictly due to topography, independent of latitude.','["Mountains at the equator are covered in boiling lava.","Due to the environmental lapse rate, atmospheric pressure and temperature decrease proportionally with altitude. Thus, a high-altitude mountain peak can sustain a freezing, glaciated cryosphere even if it is located in a hot, tropical latitude at its base.","Mountains have the exact same temperature from bottom to top.","Altitude makes the air thicker and hotter."]',1,'Even in the hot jungle, if you climb high enough up a mountain, you will find snow!','Climate: Higher places are often colder than nearby lowlands.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_044','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Evaluate the ecological impact of ''river valleys'' as biodiversity hotspots.','["River valleys kill all plant life.","River valleys concentrate essential resources (fresh water, nutrient-dense alluvial soils deposited by floods, and varied microclimates), creating highly productive riparian ecosystems that support significantly denser and more diverse flora and fauna than surrounding, drier landforms.","River valleys only support a single type of insect.","River valleys are completely sterile environments."]',1,'Water and rich dirt mean lots of plants, which means lots of animals!','River valleys may have fertile soil and a reliable water supply... Wildlife: Different landforms provide different habitats for plants and animals.','2026-11-01 07:54:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_landforms_global_045','Geography','Physical Geography','Topic 4: Landforms of the Earth','Primary',10,'Critique the human perception of landforms as ''permanent'' features of the Earth.','["Landforms literally never change.","Human perception is skewed by our short lifespans; on a geological timescale, landforms are highly dynamic. Continents collide to build mountains, rivers relentlessly carve canyons, and coastal erosion erases peninsulas, meaning the Earth''s surface is in a constant state of flux.","Landforms change completely every single day.","Landforms are only changed by human technology."]',1,'A mountain looks permanent to us, but to the Earth, it''s just a temporary bump slowly washing away!','Landforms develop over long periods through processes such as movements inside the Earth, volcanic activity, flowing water, wind, and the wearing away of rocks.','2026-11-01 07:54:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_001','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''water body''?','["A type of cloud","A natural or human-made place where water collects or flows","A large mountain of ice","An underground cave"]',1,'Oceans, lakes, and rivers are examples.','Water bodies are natural or human-made places where water collects or flows.','2026-11-01 07:54:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_002','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'Which type of water has a low concentration of dissolved salts?','["Freshwater","Saltwater","Ocean water","Sea water"]',0,'It is the type of water humans need to drink.','Some water bodies contain freshwater, which has a low concentration of dissolved salts.','2026-11-01 07:54:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_003','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What are the largest bodies of saltwater on Earth?','["Lakes","Rivers","Oceans","Ponds"]',2,'They cover about 71% of the planet.','Oceans are the largest bodies of saltwater on Earth.','2026-11-01 07:54:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_004','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''sea''?','["A small flow of fresh water","A large body of saltwater that is often partly surrounded by land","A frozen piece of ice","A small pond"]',1,'The Mediterranean and Caribbean are examples.','A sea is a large body of saltwater that is often partly surrounded by land or connected to an ocean.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_005','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''river''?','["A body of water completely surrounded by land","A natural stream of water that flows through a channel towards another water body","A large mass of slow-moving ice","Water stored underground"]',1,'The Amazon and the Nile are famous examples.','A river is a natural stream of water that flows through a channel towards another water body...','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_006','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is the ''source'' of a river?','["Where the river ends","Where the river begins","A smaller river joining a larger one","The path the river takes"]',1,'It is often high up in the mountains.','Source: The place where the river begins.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_007','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''tributary''?','["A small river or stream that flows into a larger river","The end of a river","A frozen river","A large ocean"]',0,'It adds its water to the main river.','Tributary: A smaller river or stream that flows into a larger river.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_008','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''lake''?','["A body of water surrounded by land","A flowing stream of water","A frozen ocean","A body of saltwater covering the whole Earth"]',0,'You can walk all the way around it.','A lake is a body of water surrounded by land.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_009','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''pond''?','["The largest body of saltwater","A relatively small body of still or slowly moving water","A fast-moving river","A giant block of ice"]',1,'Frogs and water lilies often live here.','A pond is a relatively small body of still or slowly moving water.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_010','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''waterfall''?','["A flat river","A place where flowing water drops steeply from a higher level to a lower level","A frozen lake","Water stored underground"]',1,'Victoria Falls and Niagara Falls are examples.','A waterfall forms where flowing water drops steeply from a higher level to a lower level.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_011','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What are ''glaciers''?','["Warm ocean currents","Large masses of ice that form on land and move slowly","Small ponds","Rivers of hot water"]',1,'They are like slow-moving rivers of ice.','Glaciers are large masses of ice that form on land... They move slowly under their own weight.','2026-11-01 07:54:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_012','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is ''groundwater''?','["Water stored in clouds","Water stored beneath Earth''s surface in soil and rocks","Water flowing in a river","Water frozen in a glacier"]',1,'People dig wells to reach it.','Groundwater is water stored beneath Earth''s surface in soil and cracks or spaces within rocks.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_013','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is ''evaporation'' in the water cycle?','["Water falling from clouds","The Sun heating water and changing it into water vapour","Water turning into solid ice","Water flowing into a river"]',1,'It is how water moves from the ocean into the air.','Evaporation: The Sun heats water, changing some liquid water into water vapour.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_014','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is ''precipitation''?','["Water turning into a gas","Water gathering in a lake","Water falling from clouds as rain, snow, sleet, or hail","Water soaking into the ground"]',2,'It is how water returns to the ground.','Precipitation: Water falls from clouds as rain, snow, sleet, or hail.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_015','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What does ''water pollution'' mean?','["Cleaning the ocean","Contamination of water by harmful substances or waste","Boiling water to drink it","Freezing water into ice"]',1,'Throwing plastic or chemicals in a river causes this.','Water pollution occurs when harmful substances or waste contaminate water bodies.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_016','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',1,'What is a ''spring''?','["A type of cloud","A place where groundwater naturally emerges onto the land surface","A dry desert area","The bottom of the ocean"]',1,'It is water coming naturally out of the ground.','A spring forms where groundwater naturally emerges onto the land surface.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_017','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why is only a tiny fraction of Earth''s water available for humans to drink?','["Because most of it is hidden in space.","Because the vast majority is saltwater in the oceans, and much of the remaining freshwater is frozen in glaciers or trapped underground.","Because humans only drink rainwater directly from clouds.","Because the atmosphere absorbs all the water."]',1,'You can''t drink the ocean, and you can''t easily melt a glacier!','Most of Earth''s water is saltwater in the oceans. Only a small proportion is freshwater, and much of that freshwater is stored in glaciers... and underground.','2026-11-01 07:54:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_018','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How do oceans help regulate the Earth''s climate?','["They block the wind from blowing.","Ocean water absorbs, stores, and moves massive amounts of heat around the planet, and evaporation supplies the water vapor for rain.","They freeze the entire planet.","They create mountains that block the sun."]',1,'They act like a giant global heater and air conditioner!','They influence weather and climate: Ocean water stores and moves heat. Evaporation from oceans supplies much of the water vapour...','2026-11-01 07:54:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_019','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'What is the main geographic difference between a ''sea'' and an ''ocean''?','["A sea is freshwater; an ocean is saltwater.","While both are saltwater, an ocean is vastly larger and open, whereas a sea is generally a smaller part of the ocean that is partly enclosed by land.","A sea is entirely frozen; an ocean is not.","They are exactly the same size."]',1,'The Mediterranean Sea is mostly surrounded by Europe and Africa, but the Atlantic Ocean is wide open.','A sea is a large body of saltwater that is often partly surrounded by land or connected to an ocean... oceans are generally much larger.','2026-11-01 07:54:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_020','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How does a river change as it moves from its ''source'' to its ''mouth''?','["It turns into solid ice.","It generally starts as a small stream in high areas (the source), collects more water from tributaries, and ends by emptying into a larger body of water (the mouth).","It flows backward up the mountain.","It turns from saltwater into freshwater."]',1,'It grows wider and deeper as it travels downhill.','Source: The place where the river begins... Tributary: A smaller river or stream that flows into a larger river. Mouth: The place where the river enters a sea, ocean, lake...','2026-11-01 07:54:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_021','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why are ''ponds'' considered important ecosystems even though they are small?','["Because they contain large whales.","Even though they are small and still, they support rich, concentrated habitats for frogs, insects, fish, and aquatic plants.","Because they are the only source of saltwater on land.","Because they have no living things in them."]',1,'A small pond is a whole world for a frog!','Ponds can support frogs, insects, fish, water lilies, and other plants and animals. They are important small habitats...','2026-11-01 07:54:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_022','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How does a ''glacier'' form differently than the ice found on the ocean surface (sea ice)?','["Glaciers are made of frozen saltwater.","Sea ice forms when the ocean freezes, but a glacier forms entirely on land when layers of snow accumulate over years, compress into ice, and slowly move.","Glaciers form instantly in one day.","Glaciers are made of frozen air."]',1,'Glaciers are basically giant, heavy piles of old, crushed snow!','Important distinction: Sea ice forms when ocean water freezes. Glaciers form on land from accumulated snow.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_023','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why is ''groundwater'' crucial for many human populations around the world?','["Because it is the only water that is salty.","In areas where surface water (lakes/rivers) is scarce, people rely on digging wells into aquifers to bring clean groundwater to the surface for drinking and farming.","Because it forces people to build boats.","Because it creates massive ocean waves."]',1,'If there is no river nearby, you have to dig down to find water!','Groundwater supplies drinking water and supports farming and ecosystems in many parts of the world... Wells can bring groundwater to the surface for human use.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_024','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why is it dangerous to assume that all clear-looking water is safe to drink?','["Because clear water is always freezing cold.","Even if water looks perfectly clear, it may still contain invisible, harmful microscopic organisms (microorganisms) or toxic chemicals that cause disease.","Because clear water is actually solid glass.","Because all clear water is saltwater."]',1,'You can''t see bacteria with your bare eyes!','Not all water that looks clear is safe to drink. Water may contain harmful microorganisms or chemicals that cannot be seen.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_025','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How does ''condensation'' act as a bridge between evaporation and precipitation in the water cycle?','["It turns rain into solid rock.","After water evaporates into a gas, condensation cools that water vapor back into tiny liquid droplets or ice crystals, forming the clouds that eventually release precipitation.","It absorbs water directly from the ground.","It makes the sun shine brighter."]',1,'Without condensation, the evaporated water would never turn into rain clouds!','Condensation: Water vapour cools and forms tiny droplets or ice crystals in clouds.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_026','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How can human agricultural practices accidentally cause ''water pollution''?','["By planting too many trees.","If farmers use too many agricultural chemicals (like fertilizers or pesticides), rain can wash those chemicals into nearby streams, rivers, and groundwater, contaminating them.","By watering their crops with pure rain.","By harvesting their crops too early."]',1,'Chemicals on a farm can easily wash down a hill into a river!','Sources include untreated sewage, plastic litter, industrial waste, and agricultural chemicals.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_027','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why might a river be used to generate ''hydroelectric power''?','["Because rivers have no energy.","The physical force and movement of flowing water (especially where it drops quickly) can be harnessed by machines to generate clean electricity.","Because rivers are always made of oil.","Because rivers never move."]',1,'The power of rushing water can spin a turbine to make electricity!','Energy: Moving water can generate hydroelectric power... Waterfalls... can be used to generate hydroelectricity where suitable facilities are built.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_028','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How does long-term melting of land-based glaciers impact coastal cities?','["It makes the cities freeze.","When massive land-based glaciers melt due to a warming climate, that extra water flows into the oceans, contributing to rising sea levels that can flood coastal cities.","It turns the coastal cities into deserts.","It has absolutely no effect on the ocean."]',1,'If the ice on land melts, the oceans get fuller!','Long-term ice loss contributes to rising sea levels. Glaciers and ice sheets are sensitive to changes in climate.','2026-11-01 07:54:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_029','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'Why are ''wetlands, riverbanks, and coastal habitats'' important to protect?','["They prevent all rain from falling.","They act as critical natural habitats for countless species of wildlife, providing food and shelter that support the broader ecosystem.","They are the only places humans can live.","They are full of plastic pollution."]',1,'These muddy, wet areas are nurseries for baby fish and birds!','Nature: Wetlands, rivers, lakes, and oceans provide habitats for countless species... Protect wetlands, riverbanks, and coastal habitats.','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_030','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'What is a ''reservoir'' and how is it used?','["A type of natural ocean.","A reservoir is a human-made lake or storage area used to collect and supply drinking water or irrigation for human communities.","A mountain made of solid ice.","An underground cave with no water."]',1,'It''s like a giant, artificial bucket holding water for a city!','Drinking water: Rivers, lakes, reservoirs, and groundwater can supply water after suitable treatment.','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_031','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',5,'How can keeping local, inland surroundings clean help protect the vast oceans?','["Because the ocean is actually inland.","Because rubbish and chemicals dropped inland are often washed into local drains or streams, which flow into larger rivers, and eventually carry that pollution straight into the ocean.","It doesn''t; local rubbish disappears instantly.","Because oceans push rubbish onto the land."]',1,'A plastic bottle dropped in the street can end up in the sea miles away!','Rivers and drains can carry rubbish from inland communities to the sea, so keeping local surroundings clean also helps protect oceans.','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_032','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Analyze the paradox of the ''Water Cycle'' regarding the distribution of global freshwater.','["The water cycle ensures every single country gets the exact same amount of rain.","While the water cycle is a continuous, closed global system, the physical distribution of precipitation is highly unequal due to atmospheric circulation and geography, leading to severe droughts in some regions and floods in others.","The water cycle removes water from the Earth permanently.","The water cycle only happens over the oceans."]',1,'The Earth has the same amount of water it always had, but it doesn''t always fall where we need it!','The cycle repeats continuously, although the time water spends in each place can vary greatly... (Synthesis: Global cycle, but local distribution varies drastically).','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_033','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Critique the biological implications of defining a ''lake'' merely as ''a body of water surrounded by land''.','["It implies lakes can only exist in outer space.","This simple geographic definition obscures deep biological complexities; lakes can range from hyper-saline (like the Dead Sea) to freshwater, each harboring completely distinct, specialized ecosystems and requiring different conservation approaches.","It implies that lakes are actually mountains.","It implies all lakes are exactly the same depth."]',1,'A freshwater lake and a saltwater lake are completely different worlds biologically!','A lake is a body of water surrounded by land. Lakes can be freshwater or saltwater, natural or human-made... Lakes provide habitats...','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_034','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Synthesize how the topographic gradient (steepness) of a river''s ''channel'' dictates its geomorphological function.','["A steep river completely stops moving.","A steep gradient near the source generates high kinetic energy, aggressively eroding bedrock and carving deep valleys. A low, flat gradient near the mouth causes the river to lose energy and deposit those eroded sediments, building fertile floodplains and deltas.","The steepness has absolutely no effect on the river.","A flat river flows upward into the mountains."]',1,'Fast water cuts rocks; slow water drops dirt!','A river is a natural stream... Source: The place where the river begins... Mouth: The place where the river enters... They provide water, support farming, carry sediments...','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_035','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Evaluate the socio-economic vulnerability of societies that rely exclusively on ''glacial meltwater'' for their river systems.','["They are completely immune to any economic problems.","These societies are highly vulnerable to climate change; as global warming accelerates glacier retreat, they may face initial flooding, followed by severe, permanent long-term water shortages and agricultural collapse once the glacial ''reservoir'' is depleted.","They have unlimited water forever.","Glaciers never melt, so they are completely safe."]',1,'If your river comes from a glacier, what happens when the glacier melts away completely?','Melting glacier ice can contribute to river flow... Glaciers and ice sheets are sensitive to changes in climate.','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_036','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Analyze the systemic threat posed by the over-extraction of ''groundwater'' from deep aquifers.','["It causes the groundwater to become fresher.","Because deep aquifers often take centuries to naturally recharge via the water cycle, extracting groundwater for mass agriculture faster than it replenishes leads to permanent depletion, land subsidence (sinking), and severe future water insecurity.","It causes the oceans to instantly dry up.","It creates new mountains above ground."]',1,'If you pump water out faster than the rain can soak back in, the well goes dry!','Some groundwater collects in permeable rock layers called aquifers... Groundwater supplies drinking water and supports farming... (Synthesis: It is not an infinite resource if overused).','2026-11-01 07:54:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_037','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Critique the concept of treating ''rivers, lakes, and oceans'' as infinite waste disposal systems during early industrialization.','["It was a perfectly sustainable and healthy practice.","This perspective dangerously ignored the finite dilution capacity of aquatic ecosystems. Persistent bioaccumulative toxins (heavy metals, non-biodegradable plastics) do not simply ''disappear'' in water; they systematically poison the entire food web, eventually threatening human survival.","It proved that water destroys all chemicals instantly.","It was the only way to create clean drinking water."]',1,'Throwing toxic waste in the river just moves the poison somewhere else; it doesn''t destroy it.','Water pollution occurs when harmful substances or waste contaminate water bodies. Sources include untreated sewage, plastic litter, industrial waste... (Synthesis: The water doesn''t make the waste disappear).','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_038','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Synthesize how the ''high specific heat capacity'' of ocean water regulates the Earth''s terrestrial climate.','["It causes the oceans to boil away.","Water absorbs and releases thermal energy much slower than land. The massive oceans act as a global thermal buffer, absorbing intense summer solar radiation and slowly releasing it during winter, preventing extreme, lethal temperature swings on adjacent landmasses.","It forces the Earth to stop rotating.","It has absolutely no effect on terrestrial temperatures."]',1,'The ocean acts like a giant, global thermostat!','They absorb and store heat, helping distribute energy around Earth... Climate: Water absorbs, stores, and transfers heat around the planet.','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_039','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Evaluate the geopolitical and economic significance of ''river mouths'' (deltas and estuaries) in human history.','["They were useless because they were always frozen.","River mouths serve as critical geographical interfaces where inland river transport meets oceanic maritime trade. Historically, this logistical advantage catalyzed the rapid growth of massive, wealthy port cities and diverse cultural hubs at these specific junctures.","They prevented any humans from ever settling near them.","They were only used as giant garbage dumps."]',1,'A city at the mouth of a river controls all the trade going in and out of the country!','Mouth: The place where the river enters a sea, ocean, lake... Transport: Rivers, seas, and oceans carry people and goods.','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_040','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Analyze how the physical structure of an ''aquifer'' challenges the concept of water ownership.','["Aquifers prove that water only belongs to one person.","Because aquifers are vast, contiguous underground geological formations that ignore human-drawn political borders on the surface, over-extraction or pollution by one country or farmer can directly deplete or poison the water supply of a neighboring region.","Aquifers are strictly confined to single backyards.","Aquifers only exist in the ocean."]',1,'You can''t build a fence underground; if your neighbor pumps all the water, your well goes dry too!','Groundwater is water stored beneath Earth''s surface in soil and cracks or spaces within rocks... Some groundwater collects in permeable rock layers called aquifers.','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_041','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Synthesize the relationship between ''waterfalls'', topographic resistance, and industrial development.','["Waterfalls stopped all industrial development.","Waterfalls occur where rivers cross highly erosion-resistant bedrock. Historically, the concentrated kinetic energy at these abrupt drops provided massive, reliable mechanical power (and later hydroelectricity), triggering the establishment of major manufacturing and industrial cities precisely at these geographic ''fall lines''.","Waterfalls only occur in flat, sandy deserts.","Waterfalls were only used for tourism, never industry."]',1,'Early factories didn''t have electricity; they used the crashing water of a waterfall to power their machines!','A waterfall forms where flowing water drops steeply... over resistant rock... can be used to generate hydroelectricity where suitable facilities are built.','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_042','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Evaluate the statement: ''Clear-looking water is not necessarily safe.'' What does this imply about modern water treatment infrastructure?','["It implies we should only drink muddy water.","It highlights the existential biological threat of invisible pathogens and dissolved chemical toxins. This necessitates advanced, highly engineered municipal water treatment infrastructure (filtration, chlorination, testing) to guarantee public health, a system often lacking in developing regions.","It implies that all clear water is perfectly safe.","It implies that water treatment is a waste of time."]',1,'Just because you can''t see the poison doesn''t mean it isn''t there!','Treat drinking water appropriately; clear-looking water is not necessarily safe. Water may contain harmful microorganisms or chemicals that cannot be seen.','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_043','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Critique the ecological impact of constructing massive artificial ''reservoirs'' (dams) on river ecosystems.','["Dams only provide benefits and have no ecological impact.","While reservoirs provide vital hydroelectricity and irrigation, they critically disrupt the natural riverine ecosystem. They block seasonal fish migrations, trap nutrient-rich sediments behind the dam, and drastically alter downstream flow, devastating the natural habitats below.","Dams are completely natural and build themselves.","Dams increase the natural flow of rivers exponentially."]',1,'Stopping a river to make a lake solves one problem but creates a dozen new ones for the fish and plants downstream.','Drinking water: Rivers, lakes, reservoirs... (Synthesis: However, disrupting a natural flow has ecological consequences).','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_044','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Analyze how the ''evaporation'' phase of the water cycle functions as a massive, natural desalination plant.','["Evaporation turns fresh water into salty ice.","When solar energy evaporates ocean water, only the pure H2O molecules transition into vapor, leaving the heavy salts and minerals behind in the ocean. This natural physical process is the sole mechanism that supplies the Earth''s continents with essential freshwater precipitation.","Evaporation takes all the salt into the clouds, making salty rain.","Evaporation has no effect on salt levels."]',1,'When the ocean evaporates, it leaves the salt behind; that''s why rain isn''t salty!','Evaporation: The Sun heats water, changing some liquid water into water vapour... Oceans and seas are mainly saltwater... (Synthesis: The rain that falls back down is fresh).','2026-11-01 07:54:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_045','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Synthesize why the ''Southern Ocean'' is critically unique compared to the other four global oceans.','["It is the only ocean that is boiling hot.","Unlike the other oceans which are bounded by multiple major landmasses, the Southern Ocean is bounded solely by Antarctica and the Antarctic Circumpolar Current. This massive, unobstructed current physically mixes and connects the Atlantic, Pacific, and Indian oceans, regulating global ocean circulation.","It is entirely enclosed by land with no currents.","It is the only ocean with no fish."]',1,'It is the massive roundabout that connects the world''s oceans!','The Southern Ocean surrounds Antarctica and connects with the southern parts of the Atlantic, Pacific, and Indian Oceans. Features: ...powerful currents... The Antarctic Circumpolar Current... helps connect the world''s major ocean systems.','2026-11-01 07:54:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_water_global_046','Geography','Physical Geography','Topic 5: Water Bodies of the Earth','Primary',10,'Evaluate the long-term geopolitical consequences of a permanent decline in ''Arctic sea ice''.','["It will cause the Arctic to become a massive continent of rock.","While devastating to endemic polar ecosystems (like polar bears), the permanent melting of Arctic sea ice opens previously unnavigable trans-polar maritime trade routes and exposes untapped underwater natural resources, inevitably sparking intense geopolitical competition and territorial disputes among northern nations.","It will cause all ships to instantly sink.","It will have absolutely no geopolitical or economic consequences."]',1,'Melting ice is bad for bears, but shipping companies want to use the open water as a shortcut!','The Arctic Ocean... Features: Sea ice... The amount of Arctic sea ice... has declined over the long term... Climate change: Rising ocean temperatures... affect marine habitats...','2026-11-01 07:54:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_001','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What are the four main cardinal directions?','["Up, down, left, right","North, south, east, and west","North-east, south-east, south-west, north-west","Top, bottom, side, edge"]',1,'Remember the phrase: Never Eat Soggy Waffles.','The four cardinal directions are north, south, east, and west.','2026-11-01 07:54:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_002','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'Which direction is exactly opposite to North?','["East","West","South","North-east"]',2,'It is usually at the bottom of a map.','South (S): Opposite to north.','2026-11-01 07:54:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_003','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'If you are facing North, which direction is to your right?','["South","West","North-east","East"]',3,'Never (N) Eat (E) Soggy (S) Waffles (W).','East (E): To the right when facing north.','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_004','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is a ''compass''?','["A tool used to measure temperature","A tool that helps people find directions using a magnetized needle","A map of the whole world","A type of sailing ship"]',1,'It always points North.','A compass is a tool that helps people find directions. A traditional magnetic compass contains a magnetized needle...','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_005','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'On a standard map, which direction is usually at the top?','["South","East","North","West"]',2,'Look for the compass rose on the map.','North (N): Usually shown at the top of a standard map.','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_006','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is the abbreviation for the direction ''South-east''?','["SW","SE","NE","NW"]',1,'It uses the first letter of each word.','South-east: SE.','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_007','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'Which intermediate direction is located exactly between South and West?','["South-west","North-west","South-east","North-east"]',0,'It combines the names of the two cardinal directions.','South-west: SW. Position: Between south and west.','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_008','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What does the ''N'' on a compass dial stand for?','["Never","Now","North","Near"]',2,'N is the direction the needle points to.','The compass dial shows directions such as N, E, S, and W.','2026-11-01 07:54:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_009','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is a ''landmark''?','["A secret underground tunnel","A recognizable feature that helps people find a place","An invisible line on a map","A tool used to measure distance"]',1,'A tall mountain or a famous building can be one.','Landmark: A recognizable feature that helps people find a place.','2026-11-01 07:54:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_010','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'In which general direction does the Sun appear to rise?','["North","South","East","West"]',2,'The Sun comes up in the morning on this side.','In many regions, the Sun appears to rise roughly in the east and set roughly in the west.','2026-11-01 07:54:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_011','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'In which general direction does the Sun appear to set?','["North","South","East","West"]',3,'The Sun goes down in the evening on this side.','In many regions, the Sun appears to rise roughly in the east and set roughly in the west.','2026-11-01 07:54:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_012','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is ''navigation''?','["Building a new road","The process of finding and following a route","Reading a storybook","Measuring the depth of the ocean"]',1,'A compass and a map help you do this.','Navigation: The process of finding and following a route.','2026-11-01 07:54:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_013','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is a ''compass rose''?','["A type of flower that grows in the north","A map symbol showing directions","The glass cover on a compass tool","A path leading east"]',1,'You always check this symbol on a map first.','Compass rose: A map symbol showing directions.','2026-11-01 07:54:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_014','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What does GPS use to estimate a person''s location?','["The wind","Magnetic north","Satellite signals","The stars"]',2,'Your phone uses this technology to give you directions.','GPS: Uses satellite signals to estimate a receiver''s location.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_015','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'If a library is East of a school, and a shop is East of the library, what is the order of buildings from West to East?','["Shop, Library, School","School, Shop, Library","School, Library, Shop","Library, School, Shop"]',2,'Think about reading from left to right on a standard map.','The school is furthest west, then the library is east of that, and the shop is east of the library.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_016','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is giving directions using ''North, South, East, West'' often better than using ''Left, Right, Straight''?','["Because ''Left'' and ''Right'' are illegal on maps.","Compass directions are absolute and do not change, whereas ''Left'' and ''Right'' change depending entirely on which way a person is facing.","Because compasses are too heavy to carry.","Because people forget their left and right hands."]',1,'If two people are facing opposite ways, their ''left'' is different, but ''North'' is the same for both!','Left and right depend on which way you are facing. Compass directions are more useful for describing a location because they do not change when you turn around.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_017','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'If you are facing East, and you turn around to face the exact opposite direction, which way are you facing?','["North","South","West","East"]',2,'If the Sun rises in front of you, where does it set?','East is to the right when facing north, West is to the left. They are opposite directions.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_018','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why should you keep a magnetic compass away from strong magnets and mobile phones?','["Because the compass will delete the phone''s memory.","The magnetic field from electronics or magnets can interfere with the compass needle, causing it to point in the wrong direction.","Because the compass will catch on fire.","Because the compass only works in complete darkness."]',1,'The compass needle is just a tiny magnet; a bigger magnet will confuse it!','Keep a magnetic compass away from strong magnets and some electronic devices, as these can affect its reading.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_019','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'If town A is South of town B, where is town B in relation to town A?','["Town B is West of town A.","Town B is North of town A.","Town B is East of town A.","Town B is also South of town A."]',1,'Directions work in opposites!','If A is below B (south), then B must be above A (north).','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_020','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is the phrase ''Never Eat Soggy Waffles'' useful for navigation?','["It teaches you what to eat in the forest.","It provides a memory aid for the clockwise order of the cardinal directions: North, East, South, West.","It tells you the names of the oceans.","It proves that compasses don''t work in the rain."]',1,'N, E, S, W in a circle!','A useful memory aid is Never Eat Soggy Waffles. The first letters give the clockwise order: North, East, South, West.','2026-11-01 07:54:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_021','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'When looking at a map, why is it critical to check the ''compass rose'' before deciding which way is North?','["Because maps change shape every day.","While most maps are drawn with North at the top, some maps use different orientations; the compass rose proves exactly which way is North.","Because the compass rose tells you the temperature.","Because maps cannot be read without a compass rose."]',1,'Never assume UP is North without checking the symbol first!','Most maps are drawn with north at the top... However, always check the map''s compass rose or north arrow.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_022','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'What is the difference between ''magnetic north'' and ''true north''?','["There is no difference; they are exactly the same.","Magnetic north is the direction a compass needle points due to Earth''s magnetic field, while true north is the exact geographic North Pole.","Magnetic north is located at the South Pole.","True north is only used by airplanes."]',1,'The Earth''s magnetic field is a little bit tilted compared to the map!','Important: Magnetic north is not exactly the same as geographic (true) north. The difference between them is called magnetic declination.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_023','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'If you are walking North-west, what two cardinal directions are you walking between?','["North and East","South and West","North and West","South and East"]',2,'It''s exactly halfway between straight forward and straight left (if facing north).','North-west: NW. Position: Between north and west.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_024','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is it dangerous to rely *only* on the Sun to find exact directions?','["The Sun is too bright to look at.","The Sun''s exact apparent position in the sky changes depending on the season, the latitude, and local weather conditions.","The Sun actually rises in the West sometimes.","The Sun does not exist in the winter."]',1,'The Sun rises *roughly* in the east, but not exactly perfectly east every single day!','Do not rely on the Sun alone for precise navigation. Its apparent position varies, and weather or local conditions may make it difficult to use.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_025','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'What three things must a set of ''clear directions'' usually include?','["A map, a compass, and a ruler.","A starting point, a direction to travel, and a final destination.","The time of day, the weather, and a landmark.","A left turn, a right turn, and a U-turn."]',1,'You can''t tell someone how to get somewhere if you don''t know where they are starting from!','Clear directions usually include a starting point, a direction, and a destination.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_026','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'How does a GPS system differ from a traditional magnetic compass?','["A GPS uses paper maps, while a compass uses satellites.","A GPS uses electronic signals from satellites in space to calculate your exact location, while a compass uses the Earth''s natural magnetic field to show direction.","A GPS only works underwater.","A compass is powered by batteries."]',1,'Your phone uses GPS; an explorer 100 years ago used a compass!','Compass: ...contains a magnetized needle... GPS: Uses satellite signals to estimate a receiver''s location.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_027','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'If a river runs from the North-east to the South-west, what path is it taking?','["It is flowing from the top right to the bottom left of a standard map.","It is flowing straight up.","It is flowing from the bottom left to the top right.","It is flowing straight across from left to right."]',0,'Draw a diagonal line across the map!','North-east is top right; South-west is bottom left.','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_028','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is a ''landmark'' helpful when using a compass to navigate in the wilderness?','["It tells you the exact time.","Once you use the compass to find the correct direction, you can aim for a visible landmark (like a tall tree) in that direction and walk toward it without constantly staring at the compass.","It gives you shelter from the rain.","It magically moves the compass needle."]',1,'It''s easier to walk toward a big mountain than to stare at a tiny needle while walking!','Look towards the required direction and identify a landmark. Walk safely towards the landmark...','2026-11-01 07:54:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_029','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'When giving directions, why is it better to say ''The shop is North of the park'' instead of just ''The shop is North''?','["Because ''North'' is a bad word.","Directions are relative; you must provide a reference location (the park) so the person knows what the shop is North *of*.","Because the shop might move.","Because the park is always in the center of the map."]',1,'North of what? You have to give them a starting point!','When describing a place, always name the reference location... ''The library is south of the school'' is clearer than simply saying ''The library is south.''','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_030','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'What should you do before reading the needle on a traditional magnetic compass?','["Shake it violently.","Hold it perfectly flat in your hand and wait for the needle to completely stop moving.","Hold it upside down.","Point it directly at the sun."]',1,'If the compass is tilted, the needle might get stuck!','Hold the compass flat in your hand. Wait for the needle to stop moving.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_031','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Analyze the geodetic concept of ''Magnetic Declination'' and why it complicates precision navigation.','["It proves that the Earth has no magnetic field.","Magnetic declination is the angular variance between True North (geographic pole) and Magnetic North (where the compass points); this variance changes depending on your global location, requiring navigators to mathematically adjust their compass bearings to match a map.","It means compasses point South in the Southern Hemisphere.","It means that magnets destroy paper maps."]',1,'The needle points to a magnetic field, which is slightly off-center from the actual top of the globe!','Important: Magnetic north is not exactly the same as geographic (true) north. The difference between them is called magnetic declination.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_032','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Critique the reliability of utilizing the Sun for absolute navigational bearings without supplementary tools.','["The Sun is the only perfect navigational tool.","While the Sun rises *generally* in the east, its precise azimuth of sunrise shifts significantly across the horizon throughout the year due to Earth''s axial tilt and the observer''s latitude, making it a highly imprecise tool for absolute directional bearing without a compass or astrolabe.","The Sun always rises at exactly 90 degrees East every single day everywhere on Earth.","The Sun actually rises in the West during the winter."]',1,'In the summer, the sun rises much further north than it does in the winter!','Do not rely on the Sun alone for precise navigation. Its apparent position varies... The exact position changes with season and latitude.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_033','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Synthesize the relationship between ''relative location'' and the necessity of a standardized ''cardinal direction'' framework.','["Relative location means you don''t need any directions.","Relative location relies on landmarks (''next to the tree''), which is useless if the user is unfamiliar with the area. Cardinal directions provide a universal, objective geometric framework that remains true regardless of the user''s starting point or local knowledge.","Cardinal directions change depending on what city you are in.","Relative location uses satellites, while cardinal directions use the sun."]',1,'If I don''t know where the ''big tree'' is, telling me to go ''left of the tree'' is useless. Telling me to go North always works!','Left and right depend on which way you are facing. Compass directions are more useful for describing a location because they do not change when you turn around.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_034','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Evaluate the technological transition from traditional ''magnetic compasses'' to satellite-based ''GPS'' for global navigation.','["GPS completely eliminated the need to ever know directions.","While GPS provides precise, instantaneous coordinates via satellite triangulation, it introduces a critical dependency on electronic infrastructure (batteries/signals); a traditional compass remains an essential, fail-safe analog tool because it relies solely on Earth''s inherent geomagnetic field.","Magnetic compasses are actually more accurate than military GPS.","GPS works by reading the magnetic field of the Earth."]',1,'If your phone battery dies in the woods, you better have a real compass!','A traditional magnetic compass... aligns approximately with Earth''s magnetic field... GPS: Uses satellite signals to estimate a receiver''s location... each has limitations.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_035','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Analyze how the arbitrary convention of ''North-up'' mapping shapes human psychological perceptions of global geography.','["North-up maps prove that gravity pulls things South.","Because maps traditionally place North at the top, it creates a subtle psychological hierarchy that subconsciously equates ''North'' with ''up'' or ''superior'', despite the Earth being a sphere in space with no objective top or bottom.","North-up maps are required by the laws of physics.","South-up maps are literally impossible to draw or read."]',1,'If you look at the Earth from space, there is no ''up''!','Most maps are drawn with north at the top... However, always check the map''s compass rose... (Synthesis: It is just a drawing convention, not a physical law of the planet).','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_036','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'How does a ''compass rose'' function as the epistemological key to interpreting any two-dimensional map?','["It tells you the exact distance between two cities.","Without a compass rose establishing the absolute orientation of the cardinal directions on the specific projection, a map is merely a floating diagram; the rose grounds the 2D image into the absolute reality of Earth''s geography.","It proves that the map is drawn perfectly to scale.","It shows the elevation of mountains."]',1,'Without the symbol, you have no idea if the map is drawn upside-down or sideways!','Compass rose: A map symbol showing directions... always check the map''s compass rose or north arrow.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_037','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Critique the effectiveness of ''left/right'' instructions in a complex, multi-stage navigation route.','["Left/right instructions are universally understood by all animals.","Left/right directives are entirely egocentric (dependent on the user''s current orientation). In a complex route, a single mistaken turn invalidates all subsequent left/right instructions, whereas cardinal directions (North/South) remain objectively true and allow for immediate self-correction.","Left and right are objective magnetic directions.","Cardinal directions are impossible to use in a city."]',1,'If you get turned around, your ''left'' is now ''right'', but North is always North!','Left and right depend on which way you are facing. Compass directions are more useful for describing a location because they do not change when you turn around.','2026-11-01 07:54:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_038','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Evaluate the safety protocol: ''Never cross a road or enter an unsafe area just to follow a compass bearing.''','["A compass bearing will magically protect you from cars.","A compass provides a straight-line geometric bearing, ignoring physical geography and hazards (cliffs, highways). Navigation requires synthesizing the objective compass bearing with subjective environmental awareness and safety assessments to plot a viable, safe route.","You must always walk in a perfectly straight line no matter what is in the way.","Compasses purposely point you toward dangerous areas."]',1,'The compass says go straight, but if there''s a cliff in the way, you have to walk around it!','Never cross a road or enter an unsafe area just to follow a compass bearing. Always pay attention to your surroundings. Real journeys may require... safe crossing points.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_039','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Synthesize how the concept of ''Intermediate Directions'' (e.g., NE, SW) increases navigational resolution.','["Intermediate directions make navigation impossible.","By bisecting the 90-degree angles between the four cardinal points, intermediate directions double the precision of a navigational bearing, allowing travelers to describe a much more specific vector rather than relying on broad quadrants.","Intermediate directions only work in the Southern Hemisphere.","Intermediate directions are only used on digital GPS screens."]',1,'It gives you 8 choices instead of just 4, making your aim much more accurate!','Between the four cardinal directions are four intermediate directions... If a hospital is north-east of a school, it lies generally above and to the right...','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_040','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Analyze the statement: ''A map''s direction is not always the same as the direction a road travels.''','["Roads are always built in perfectly straight lines facing North.","Maps display absolute geometric directions, but human infrastructure (roads) must contour to local topography, property lines, and obstacles; thus, a road traveling generally ''North'' will often curve East or West along its actual physical path.","Maps are completely useless for finding roads.","Roads naturally align perfectly with the Earth''s magnetic field."]',1,'The town you want is straight North, but the road might curve around a mountain first!','A map''s direction is not always the same as the direction a road travels. Real journeys may require road names, distances, landmarks...','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_041','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'How does the reliance on ''landmarks'' interact with cardinal directions in practical human wayfinding?','["Landmarks completely replace the need for directions.","Wayfinding is a hybrid process; cardinal directions provide the absolute vector (the ''which way''), while landmarks provide the relative, visual confirmation of progress (the ''how far''), combining objective geometry with subjective visual recognition.","Landmarks are only used by people who cannot read maps.","Cardinal directions prevent people from seeing landmarks."]',1,'Use the compass to aim, and use the giant tree to walk straight!','Look towards the required direction and identify a landmark. Walk safely towards the landmark... Landmarks: ...help people recognize locations.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_042','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Critique the assumption that the magnetic needle of a compass points to the geographic North Pole.','["The needle points to the exact geographic center of the North Pole.","The magnetic needle aligns with Earth''s magnetic field, pointing to the Magnetic North Pole, a geological phenomenon that is physically distinct from the geographic North Pole and actually slowly drifts over time due to Earth''s molten core.","The needle points to the closest large metal building.","The needle actually points to the Sun."]',1,'The magnetic pole is actually located hundreds of miles away from the true North Pole, and it moves!','A traditional magnetic compass contains a magnetized needle that aligns approximately with Earth''s magnetic field... Magnetic north is not exactly the same as geographic (true) north.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_043','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What does the abbreviation ''NW'' stand for on a compass?','["North-west","Nowhere","North-wind","Near-west"]',0,'It combines the letters of North and West.','North-west: NW. Position: Between north and west.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_044','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'If the library is North of the park, where is the park?','["South of the library","East of the library","West of the library","North of the library"]',0,'Directions work in exact opposites.','If A is north of B, then B is south of A.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_045','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What does ''straight ahead'' mean when giving directions?','["Turn left","Turn right","Continue forward without turning","Face the opposite direction"]',2,'Keep walking the way you are facing.','Straight ahead: Continue forward without turning.','2026-11-01 07:54:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_046','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What does ''turn around'' mean when following directions?','["Walk in a circle","Face the exact opposite direction","Look up at the sky","Stop moving completely"]',1,'If you were facing North, you are now facing South.','Turn around: Face the opposite direction.','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_047','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',1,'What is a compass rose used for on a map?','["To make the map look pretty","To show which way is North, South, East, and West","To show where the oceans are","To show the names of cities"]',1,'It is the little star or cross with N, E, S, W on it.','Compass rose: A map symbol showing directions.','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_048','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is ''True North'' different from ''Magnetic North''?','["True North is a fake direction.","True North is the actual geographic North Pole at the top of the Earth, while Magnetic North is where the Earth''s magnetic field pulls a compass needle.","True North only works in the winter.","Magnetic North is located at the equator."]',1,'The Earth is like a giant magnet, but the magnet is slightly tilted!','Important: Magnetic north is not exactly the same as geographic (true) north. The difference between them is called magnetic declination.','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_049','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'If you are walking South and you take a 90-degree turn to your right, which direction are you now walking?','["North","East","West","South-east"]',2,'Draw a compass cross. Face the bottom (S), then turn to your right arm.','If you are facing South (down), turning to your right will point you West (left).','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_050','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why is it important to have a ''starting point'' when giving directions?','["Because you need to know what time it is.","Because directions are relative; telling someone to ''go East'' only works if they know exactly where they are supposed to start going East from.","Because maps don''t have starting points.","Because starting points are always in the North."]',1,'You can''t give directions to the shop if you don''t know where the person is standing right now!','Clear directions usually include a starting point, a direction, and a destination.','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_051','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'How do maps use symbols like a compass rose to prevent confusion?','["By hiding the symbols.","By explicitly marking which edge of the paper represents North, so the reader doesn''t accidentally hold the map upside down and walk the wrong way.","By making the symbols change color.","By drawing a compass rose on every single street."]',1,'If you hold the map upside down without checking the compass rose, you will walk South instead of North!','Most maps are drawn with north at the top... However, always check the map''s compass rose or north arrow.','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_052','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',5,'Why are intermediate directions (like South-East) helpful?','["They make the compass heavier.","They allow you to describe a location that is not in a perfectly straight line with the four main cardinal directions, making navigation much more precise.","They are only used by airplanes.","They replace the need for cardinal directions."]',1,'If a town isn''t straight North or straight East, it must be North-East!','Between the four cardinal directions are four intermediate directions... The eight directions are...','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_053','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Critique the geometric limitation of using a 2D map compass rose for long-distance global navigation.','["A 2D compass rose is perfect for all space travel.","A 2D map compass rose assumes a flat Euclidean plane; however, over vast intercontinental distances on the spherical Earth, following a constant compass bearing (a rhumb line) creates a curved, inefficient path rather than the true shortest distance (a great circle).","A 2D compass rose only works underwater.","A 2D compass rose proves the Earth is flat."]',1,'Walking a straight line on a flat map is actually a curved line on a round globe!','Most maps are drawn with north at the top... A compass can help hikers... find their way. (Synthesis: However, long-distance navigation on a sphere requires advanced geometry beyond a flat map).','2026-11-01 07:54:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_054','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Analyze the cognitive difference between ''egocentric'' navigation (Left/Right) and ''allocentric'' navigation (North/South).','["They are exactly the same thing.","Egocentric navigation relies on the subject''s shifting physical orientation (Left/Right), whereas allocentric navigation relies on a fixed, objective external framework (North/South), requiring a higher level of spatial cognitive mapping.","Egocentric navigation uses satellites.","Allocentric navigation only works at the North Pole."]',1,'Left/Right is about *you*. North/South is about the *world*.','Left and right depend on which way you are facing. Compass directions are more useful for describing a location because they do not change when you turn around.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_055','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Synthesize how the concept of ''Magnetic Declination'' forces navigators to integrate multiple forms of data.','["It means compasses are completely useless.","Because the Magnetic North Pole wanders geographically, a navigator cannot rely solely on a compass; they must actively synthesize the objective compass bearing with updated cartographic data (declination charts) to calculate their true geographic heading.","It forces navigators to rely entirely on the Sun.","It means maps must be redrawn every single day."]',1,'You have to do a little math to match the magnetic needle to the paper map!','Important: Magnetic north is not exactly the same as geographic (true) north. The difference between them is called magnetic declination.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_056','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'Evaluate the evolutionary advantage of human societies developing standardized ''cardinal directions''.','["It made societies completely isolated.","Standardized cardinal directions provided a universal, objective spatial language. This allowed disparate cultures to accurately share geographic knowledge, coordinate complex trade routes, and navigate vast, featureless environments like oceans or deserts where localized landmarks were absent.","It forced everyone to speak the exact same language.","It prevented people from exploring new lands."]',1,'Without North, South, East, and West, crossing an ocean is impossible because there are no trees or mountains to use as landmarks!','Directions help us describe where places are and how to travel from one place to another... A compass can help hikers, explorers, sailors, and travellers find their way.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_compass_global_057','Geography','Physical Geography','Topic 6: Directions and Compass Skills','Primary',10,'How does the ''apparent motion of the Sun'' complicate rudimentary navigation without technological instruments?','["The Sun stays in the exact same spot all day.","While providing a rough East/West axis, the Sun''s precise azimuth varies daily based on latitude and axial tilt (seasons). Without a compass or astrolabe, relying on the Sun requires complex astronomical knowledge to avoid significant navigational drift over long distances.","The Sun always rises exactly at True North.","The Sun actually moves backward in the winter."]',1,'If you follow the sunrise in the summer, you''ll end up in a slightly different place than if you followed it in the winter!','Sun: In many regions, the Sun appears to rise roughly in the east and set roughly in the west. The exact position changes with season and latitude. Do not rely on the Sun alone for precise navigation.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_001','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is a ''map''?','["A round model of the Earth","A drawing or representation of all or part of Earth''s surface, usually from above","A tool used to measure temperature","An imaginary line in the sky"]',1,'It is usually flat and can be printed on paper.','A map is a drawing or representation of all or part of Earth''s surface.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_002','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is a ''globe''?','["A flat piece of paper","A round, three-dimensional model of Earth","A type of compass","A drawing of a single city"]',1,'It represents Earth''s overall shape more naturally.','A globe is a round, three-dimensional model of Earth.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_003','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'Which map part explains what the symbols, lines, and colors mean?','["The title","The legend or key","The scale","The compass rose"]',1,'It acts like a dictionary for the map.','Legend or key: Explains the symbols, lines, and colours used on a map.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_004','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What does a map ''scale'' do?','["Shows the weather","Shows the relationship between a distance on the map and the actual distance on Earth","Explains the symbols","Points to the North"]',1,'It helps you measure how far apart things really are.','Scale: Shows the relationship between a distance on the map and the actual distance on Earth.','2026-11-01 07:54:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_005','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'Which type of map shows country borders, states, cities, and capitals?','["Physical map","Thematic map","Political map","Road map"]',2,'It shows the boundaries created by humans.','Political map: Shows countries, borders, states, cities, and capitals.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_006','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'Which type of map shows natural features like mountains, rivers, and lakes?','["Political map","Physical map","Thematic map","Road map"]',1,'It shows what the actual ground looks like.','Physical map: Shows natural features such as mountains, plains, rivers, and lakes.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_007','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is ''latitude''?','["An imaginary line that measures how far North or South a place is from the Equator","A line that measures distance from the Prime Meridian","A type of physical map","A tool for measuring wind"]',0,'These lines run side-to-side across the globe.','Latitude measures how far north or south a place is from the Equator.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_008','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is the latitude of the Equator?','["90 degrees North","180 degrees East","0 degrees","90 degrees South"]',2,'It is exactly in the middle of the North and South poles.','The Equator is at 0 degrees latitude.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_009','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is ''longitude''?','["An imaginary line that measures how far East or West a place is from the Prime Meridian","A line that measures distance from the Equator","A type of weather map","A symbol in the map key"]',0,'These lines run up and down from the North Pole to the South Pole.','Longitude measures how far east or west a place is from the Prime Meridian.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_010','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is the longitude of the Prime Meridian?','["90 degrees","0 degrees","180 degrees","360 degrees"]',1,'It is the starting line for measuring East and West.','The Prime Meridian is at 0 degrees longitude.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_011','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is a ''hemisphere''?','["A full circle","One half of a sphere","A type of mountain","A deep ocean trench"]',1,'The Equator divides the Earth into the Northern and Southern Hemispheres.','Hemisphere: One half of a sphere.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_012','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What do ''coordinates'' do?','["They are values used to identify a specific location on Earth","They print the map","They predict the weather","They build roads"]',0,'They act like an exact address for a spot on the globe.','Coordinates: Values used to identify a location.','2026-11-01 07:54:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_013','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'Which type of map would you use if you want to see just the rainfall patterns in an area?','["Political map","Physical map","Thematic map","Road map"]',2,'It focuses on one specific ''theme''.','Thematic map: Shows one particular subject, such as climate, rainfall, population...','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_014','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What is the highest degree of latitude you can reach (at the North or South Pole)?','["0 degrees","90 degrees","180 degrees","360 degrees"]',1,'You can''t go further north than the North Pole!','Latitude ranges from 0 degrees to 90 degrees north or south. The North Pole is at 90 degrees N...','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_015','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',1,'What does the ''title'' of a map do?','["Tells you exactly how far to walk","Tells you what the map represents or is about","Shows you the compass directions","Shows the borders of countries"]',1,'It is the name of the map.','Title: The title tells what the map represents.','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_016','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why is a globe often considered more ''accurate'' than a flat map for looking at the whole world?','["Because globes are heavier.","A globe represents Earth''s true 3D shape, avoiding the distortion of size and shape that always happens when you try to flatten a sphere into a 2D map.","Because flat maps cannot show oceans.","Because globes show the future."]',1,'You can''t peel an orange and lay the skin perfectly flat without stretching it!','A globe represents Earth''s overall shape more naturally than a flat map... Because Earth is curved, showing the whole planet on a flat map always involves some distortion...','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_017','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'If a map scale states ''1 centimetre = 10 kilometres'', and two cities are 4 centimetres apart on the map, what is the actual distance between them?','["14 kilometres","4 kilometres","40 kilometres","400 kilometres"]',2,'Multiply the map distance by the scale factor.','If 1 cm = 10 km, then 4 cm = 4 x 10 = 40 kilometres.','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_018','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why must you check the map''s legend (key) before assuming what a blue line means?','["Because blue lines always mean roads.","Because while blue often represents rivers, map conventions can vary; the legend explicitly explains what each specific symbol and color actually means on that particular map.","Because the legend will change the blue line to red.","Because blue lines mean nothing."]',1,'Never guess what a symbol means; read the key!','These conventions can vary. Always check the map''s legend rather than assuming that every map uses the same colours and symbols.','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_019','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'How do latitude and longitude work together to pinpoint a location?','["They only work if you are on a boat.","They form a global grid system; by providing an exact measurement of how far North/South (latitude) and how far East/West (longitude) a place is, you find the single exact point where those two lines cross.","They force you to guess where you are.","They only measure the height of mountains."]',1,'It''s like finding a point on a graph; you need the X and the Y axis!','Together, latitude and longitude can identify a location on Earth.','2026-11-01 07:54:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_020','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why is it important to remember that a map scale only measures distance, not travel time?','["Because time doesn''t exist on a map.","Because the actual time it takes to travel that distance depends heavily on the route, the type of transport, traffic, and physical conditions like mountains.","Because maps are always wrong about distance.","Because a scale actually only measures weight."]',1,'10 kilometres on a flat highway takes less time than 10 kilometres climbing a steep mountain!','Important: A map''s scale measures distance, not the time needed to travel. Travel time depends on the route, transport, and conditions.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_021','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'How does the Equator physically divide the Earth?','["It cuts the Earth into East and West.","It divides the Earth horizontally into the Northern Hemisphere and the Southern Hemisphere.","It divides the Earth into land and water.","It cuts the Earth into four quarters."]',1,'It is the belt around the middle of the planet.','The Equator divides Earth into the Northern Hemisphere and Southern Hemisphere.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_022','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'If a coordinate is written as ''30° N, 50° W'', what does it mean?','["30 degrees West, 50 degrees North.","30 degrees North of the Equator, and 50 degrees West of the Prime Meridian.","30 degrees South, 50 degrees East.","It is 30 miles from the North Pole."]',1,'Always read the Latitude (North/South) first!','This means 20 degrees north of the Equator and 30 degrees east of the Prime Meridian... coordinates are commonly written as latitude followed by longitude.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_023','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why are all lines of longitude not parallel to each other?','["Because they are drawn randomly.","Unlike latitude lines, lines of longitude are drawn from pole to pole, meaning they are widest apart at the Equator and converge (meet together) at the North and South Poles.","Because they are actually circles.","Because they follow river paths."]',1,'Think of the lines on a pumpkin; they all meet at the top and bottom!','Lines of longitude meet at the poles.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_024','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'If you want to understand the layout of a country''s mountains and rivers, which type of map is most useful?','["A Political Map","A Thematic Map about population","A Physical Map","A Road Map"]',2,'This map shows the physical ground, not invisible borders.','Physical map: Shows natural features such as mountains, plains, rivers, and lakes.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_025','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why is a flat map sometimes more practical to use than a globe, even though it has distortions?','["Globes are always wrong.","A globe is bulky and usually only shows large global features, whereas a flat map can be easily carried, folded, or zoomed in digitally to show incredibly fine details like specific streets and buildings.","Globes cannot show oceans.","Maps are strictly 3D."]',1,'You can''t fit a globe in your pocket or zoom in to see your house!','A globe is small and cannot show every street or building in detail... A map is often more convenient when we need to find a particular place or study a specific area in detail.','2026-11-01 07:54:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_026','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'How does the Prime Meridian divide the Earth?','["It divides it into North and South.","It (along with the 180° meridian) divides the Earth vertically into the Eastern Hemisphere and the Western Hemisphere.","It divides the Earth into the Arctic and Antarctic.","It doesn''t divide the Earth."]',1,'It slices the Earth like an apple from top to bottom.','The Prime Meridian divides Earth into the Eastern and Western Hemispheres when used with the meridian at 180°.','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_027','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why is it important to state the ''reference location'' when giving directions (e.g., ''The shop is East of the library'')?','["Because East changes depending on the time of day.","Because saying ''The shop is East'' is incomplete; you must clarify what it is East *of* so the person has a starting point to navigate from.","Because ''East'' means different things in different countries.","It is not important."]',1,'East of what? You need an anchor point!','When describing a place, always name the reference location... ''The library is south of the school'' is clearer than simply saying ''The library is south.''','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_028','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'What is a ''grid'' on a simple classroom map used for?','["To make the map look colorful.","It uses crossing lines (usually letters and numbers) to create small squares, making it much faster to locate a specific point, like ''B3''.","To measure the exact temperature.","To stop people from reading the map."]',1,'It is a simpler version of latitude and longitude for finding things in a small area.','Grid coordinates are useful for finding a place on a map quickly.','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_029','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'If a country lies exactly on the Equator, which hemispheres is it in?','["Only the Northern Hemisphere.","Only the Southern Hemisphere.","It has land in both the Northern Hemisphere and the Southern Hemisphere.","It is in the Eastern Hemisphere only."]',2,'The line cuts right through the middle of the country!','The Equator divides Earth into the Northern Hemisphere and Southern Hemisphere. (If it crosses the line, it is in both).','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_030','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',5,'Why might a map use ''icons'' or small pictures?','["To hide secret messages.","To represent specific features clearly and quickly, such as a small airplane picture to indicate the exact location of an airport without writing long words.","To make the map heavier.","Because maps cannot use words."]',1,'A picture is fast and easy to understand!','Small pictures or icons: May represent airports, schools, hospitals, or tourist attractions.','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_031','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Critique the geometric inevitability of ''distortion'' in all two-dimensional world maps.','["Distortion only happens because cartographers are bad at drawing.","It is a mathematical impossibility to project the surface of a three-dimensional sphere (or oblate spheroid) onto a flat Euclidean plane without tearing or stretching. Therefore, every flat world map inherently distorts either shape, relative area, distance, or direction to achieve the projection.","Distortion proves that the Earth is actually flat.","Distortion only affects the color of the oceans."]',1,'You cannot flatten a globe perfectly without stretching it out of shape!','Because Earth is curved, showing the whole planet on a flat map always involves some distortion of shape, area, distance, or direction, depending on the map projection.','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_032','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Analyze the geopolitical implications of the ''Prime Meridian'' being established at Greenwich, London (0° Longitude).','["It was placed there because London is exactly in the center of the Earth.","Unlike the Equator, which is a mathematically objective line based on Earth''s rotation, the Prime Meridian is entirely arbitrary. Its placement at 0° reflects the historical geopolitical and naval dominance of the British Empire during the 19th century when international time and longitude standards were established.","It was placed there because the magnetic pole is in London.","It has absolutely no geopolitical significance."]',1,'They could have put the 0 line anywhere on Earth, but the most powerful empire at the time got to choose!','The Prime Meridian is at 0° longitude... (Synthesis: The Equator is physical; the Prime Meridian is an agreed-upon human construct).','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_033','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Synthesize how the combination of ''Political Maps'' and ''Physical Maps'' provides a complete understanding of a nation''s borders.','["Political maps are entirely useless.","Political maps show the arbitrary human-drawn boundaries (borders), while physical maps show the natural topography (mountains/rivers). Synthesizing them reveals *why* borders exist where they do, as many political borders are naturally defined by impassable physical features like mountain ranges or wide rivers.","Physical maps show borders better than political maps.","Combining them causes the map to erase itself."]',1,'A country''s border is often drawn exactly where a giant mountain range or river is!','Political map: Shows countries, borders... Physical map: Shows natural features such as mountains, plains, rivers... (Synthesis: The physical world often dictates the political lines).','2026-11-01 07:54:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_034','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Evaluate the abstraction required to understand and utilize ''Thematic Maps''.','["Thematic maps are the simplest maps and require no thought.","Unlike physical/political maps that represent tangible geographic reality, thematic maps represent abstract, invisible data (like population density or climate zones) spatially over a geographic area, requiring the user to synthesize statistical data with geographic location.","Thematic maps only show physical roads.","Thematic maps cannot be understood by humans."]',1,'You can''t physically *see* ''population density'' on the ground; the map visualizes invisible data!','Thematic map: Shows one particular subject, such as climate, rainfall, population, or natural resources.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_035','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Analyze the mathematical relationship between lines of latitude and lines of longitude regarding ''parallelism''.','["They are both completely parallel to each other.","Lines of latitude (parallels) remain equidistant and perfectly parallel to each other from the Equator to the poles. Lines of longitude (meridians) are not parallel; they are furthest apart at the Equator and physically converge to a single point at the North and South Poles.","Latitude lines cross each other at the equator.","Longitude lines are perfectly parallel."]',1,'Latitude lines are like belts; longitude lines are like the wedges of an orange!','Latitude... (parallels). Longitude... Lines of longitude meet at the poles.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_036','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Critique the assertion that coordinates (e.g., 20° N, 30° E) are merely ''geographical descriptions'' and not cultural boundaries.','["Coordinates strictly divide the world into cultural zones.","Coordinates are an absolute, objective mathematical grid system overlaying the planet. While they pinpoint exact physical locations, they are entirely blind to the complex, shifting cultural, linguistic, and political identities of the human beings occupying those locations.","Coordinates are subjective and change based on opinion.","Coordinates determine what language people speak."]',1,'A coordinate is just math; it tells you nothing about the people living there!','These are geographic descriptions of locations, not boundaries between cultures or countries.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_037','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Synthesize the cognitive difference between using a ''relative grid'' (A1, B2) on a local map versus ''absolute geographic coordinates'' (Latitude/Longitude).','["They are exactly the same system.","A relative alphanumeric grid is an arbitrary overlay useful only for navigating that specific, isolated local map. Latitude and longitude form a universal, absolute global framework that defines a location''s exact position in relation to the entire planet.","A relative grid is used for the whole planet.","Latitude and longitude can only be used in classrooms."]',1,'A ''B3'' on a tourist map of Paris means nothing on a map of Tokyo, but a Latitude/Longitude coordinate means the same thing everywhere!','On a simple classroom grid, coordinates can also use letters and numbers... Grid coordinates are useful for finding a place on a map quickly. Real-world latitude and longitude use a different coordinate system.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_038','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'How does a map''s ''Scale'' dictate its level of ''Detail'' (Large scale vs. Small scale)?','["Scale has no effect on the detail of a map.","Because map size is physically limited, a ''small scale'' map showing a vast area (like a world map) must heavily generalize or omit small features. A ''large scale'' map showing a small area (like a city block) can include minute details like individual buildings and trees.","A world map shows every single building perfectly.","Scale only affects the colors used on a map."]',1,'If you draw the whole world on a piece of paper, a city is just a tiny dot!','A map is usually much smaller than the real area it represents. A scale explains the relationship... Maps are useful for detailed information [when showing a small area].','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_039','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Evaluate the phrase: ''Always check the map''s legend rather than assuming that every map uses the same colours and symbols.''','["All maps are legally required to use identical symbols.","Cartography is not universally standardized; while conventions exist (blue for water), mapmakers have creative freedom. A red line might mean a major highway on one map, but a disputed political border on another, making the legend the only definitive key to interpretation.","It means legends are usually lying.","Assuming colors is always the safest way to read a map."]',1,'A green area might mean a forest, or it might just mean a country with low elevation!','These conventions can vary. Always check the map''s legend rather than assuming that every map uses the same colours and symbols.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_040','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Analyze the impact of ''Digital Maps'' (like GPS on smartphones) on traditional human spatial cognition.','["Digital maps improve our ability to memorize routes perfectly.","While highly convenient, dynamic digital maps that constantly center the user and rotate automatically relieve the brain of building its own ''cognitive map'' (allocentric spatial awareness), potentially degrading human navigational skills and reliance on fixed cardinal directions.","Digital maps are completely useless and nobody uses them.","Digital maps force users to rely on physical globes."]',1,'If your phone always tells you when to turn, your brain stops paying attention to the actual environment!','Maps can be printed on paper or displayed on phones, computers, and other digital devices... (Synthesis: Digital maps do the navigation for you).','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_041','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Synthesize how the concept of ''Hemispheres'' influences global climate seasonality.','["Hemispheres dictate that the entire planet shares the exact same season.","Because Earth is tilted on its axis, the Northern and Southern Hemispheres are exposed to differing angles of solar radiation at different times in Earth''s orbit. Thus, when it is summer in the Northern Hemisphere, it is conversely winter in the Southern Hemisphere.","Hemispheres have absolutely no connection to climate or seasons.","The equator causes the hemispheres to freeze."]',1,'When New York (North) is having a snowy winter, Australia (South) is having a hot summer!','The Equator divides Earth into the Northern Hemisphere and Southern Hemisphere... (Synthesis: The division results in opposite seasons due to axial tilt).','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_042','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Critique the representation of ''Antarctica'' on a standard rectangular world map (like a Mercator projection).','["It is drawn perfectly to scale.","Due to extreme high-latitude distortion necessary to flatten the globe into a rectangle, Antarctica is typically stretched across the entire bottom of the map, appearing massively larger and wider than its actual physical proportion to other continents.","Antarctica is completely omitted from all rectangular maps.","It appears as a tiny dot in the center of the map."]',1,'Look at a flat map and see how huge Antarctica looks; then look at a globe and see its true size!','Because Earth is curved, showing the whole planet on a flat map always involves some distortion of shape, area... depending on the map projection.','2026-11-01 07:54:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_043','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Evaluate the necessity of the ''Prime Meridian'' acting as the baseline for global time zones.','["Time zones are based on the Equator, not the Prime Meridian.","Since Earth rotates 360 degrees of longitude every 24 hours (15 degrees per hour), the Prime Meridian (0°) serves as the objective, agreed-upon mathematical baseline (Greenwich Mean Time/UTC) from which all other global time zones are calculated sequentially East and West.","The Prime Meridian has no connection to time.","Time zones are completely random."]',1,'When it is noon at 0 degrees, it is midnight on the other side of the planet at 180 degrees!','The Prime Meridian is at 0° longitude... Longitude is measured east or west up to 180°... (Synthesis: Earth rotates 360 degrees, so longitude correlates to time).','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_044','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Analyze how ''Thematic Maps'' can be weaponized for political propaganda.','["Thematic maps are objective and can never be biased.","Because thematic maps visualize abstract data (like demographics or resources), cartographers can intentionally manipulate variables, colors, or data scaling to visually exaggerate threats, minimize specific populations, or push a specific political narrative under the guise of objective geography.","Thematic maps only show natural rivers.","Propaganda cannot be drawn on paper."]',1,'If you color a small problem bright, alarming red on a map, people will think it''s a massive crisis!','Thematic map: Shows one particular subject, such as climate, rainfall, population... (Synthesis: Whoever controls the data visualization controls the narrative).','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_maps_global_045','Geography','Physical Geography','Topic 7: Maps, Globes, and Location','Primary',10,'Synthesize the geographical logic behind lines of ''Latitude'' capping at 90 degrees.','["Latitude lines can actually go up to 360 degrees.","Latitude measures angular distance from the Equator (0°) to the poles. Since a pole is a single point at the absolute top or bottom of the sphere, the maximum angular distance achievable from the center plane (Equator) is exactly a right angle, or 90 degrees.","Latitude lines stop at 90 degrees because they run out of paper.","Latitude lines stop at 90 degrees because of ocean currents."]',1,'From the middle (0) to the very top is a 90-degree angle!','Latitude ranges from 0° to 90° north or south. The North Pole is at 90° N, and the South Pole is at 90° S.','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_001','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What does ''weather'' describe?','["The shape of mountains","The condition of the atmosphere at a particular place and time","Typical weather patterns over many years","The depth of the ocean"]',1,'It changes from hour to hour and day to day.','Weather is the condition of the atmosphere at a particular place and time.','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_002','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What does ''climate'' describe?','["What is happening outside right now","Typical weather patterns over many years","The speed of the wind","The amount of rain in one day"]',1,'It is what you expect the weather to be like in a season.','Climate describes longer-term patterns... typical weather patterns over many years.','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_003','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What is ''temperature''?','["How fast the wind blows","How hot or cold the air is","How much rain falls","How many clouds are in the sky"]',1,'It is usually measured in degrees Celsius or Fahrenheit.','Temperature tells us how hot or cold the air is.','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_004','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What is ''precipitation''?','["Wind blowing across the ocean","Water that falls from clouds as rain, snow, sleet, or hail","The sun shining brightly","Fog close to the ground"]',1,'It is water falling from the sky.','Precipitation is water that falls from clouds as rain, snow, sleet, or hail.','2026-11-01 07:54:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_005','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What is ''wind''?','["Water falling from the sky","Moving air","A type of cloud","The heat from the sun"]',1,'You can feel it blowing against your face.','Wind is moving air. It has both speed and direction.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_006','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What is ''humidity''?','["The temperature of the air","The amount of water vapour in the air","The speed of the wind","The weight of the atmosphere"]',1,'High humidity makes hot days feel sticky.','Humidity describes the amount of water vapour in the air.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_007','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What are clouds made of?','["Solid rock","Tiny water droplets, ice crystals, or both","Smoke from fires","Dust from deserts"]',1,'They float high in the sky.','Clouds are made of tiny water droplets, ice crystals, or both.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_008','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument measures air temperature?','["A barometer","A rain gauge","A thermometer","An anemometer"]',2,'It usually has numbers showing degrees.','Thermometer: Air temperature.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_009','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument measures the amount of rainfall?','["A thermometer","A rain gauge","A wind vane","A hygrometer"]',1,'It collects rain in a tube.','Rain gauge: Amount of rainfall.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_010','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument measures wind speed?','["An anemometer","A barometer","A thermometer","A wind vane"]',0,'It often has little cups that spin in the wind.','Anemometer: Wind speed.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_011','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument shows wind direction?','["A rain gauge","A wind vane","An anemometer","A barometer"]',1,'It points to where the wind is coming from.','Wind vane: Wind direction.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_012','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument measures air pressure?','["A barometer","A thermometer","A hygrometer","A rain gauge"]',0,'It helps predict if a storm is coming.','Barometer: Air pressure.','2026-11-01 07:54:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_013','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What instrument measures humidity?','["A wind vane","A thermometer","A hygrometer","An anemometer"]',2,'It measures how much moisture is in the air.','Hygrometer: Humidity.','2026-11-01 07:54:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_014','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What is a ''weather forecast''?','["A history book about old storms","An estimate of future weather based on observations and scientific models","A machine that controls the weather","A type of thermometer"]',1,'You watch this on TV to know what to wear tomorrow.','A weather forecast is an estimate of future weather based on observations and scientific models.','2026-11-01 07:54:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_015','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What kind of clouds can produce lightning, thunder, and heavy rain?','["Cirrus clouds","Stratus clouds","Cumulonimbus clouds","Cumulus clouds"]',2,'They are big, dark storm clouds.','Cumulonimbus clouds: Large, towering clouds that can produce heavy rain, lightning, thunder...','2026-11-01 07:54:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_016','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',1,'What are ''cirrus'' clouds?','["Low, grey clouds","Large storm clouds","Thin, wispy clouds high in the sky made mostly of ice crystals","Puffy, white clouds"]',2,'They look like horse tails.','Cirrus clouds: Thin, wispy clouds high in the sky. They are made mostly of ice crystals.','2026-11-01 07:54:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_017','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why is ''climate'' different from ''weather''?','["Climate is hot and weather is cold.","Weather describes short-term atmospheric conditions (like a rainy afternoon), while climate describes typical long-term patterns (like a rainy season over many years).","Weather is measured by satellites, climate is measured by thermometers.","They are exactly the same thing."]',1,'Weather is today; climate is what you expect every year!','Weather tells us what the atmosphere is doing now or over a short period. Climate describes what is typical over many years.','2026-11-01 07:54:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_018','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why can high ''humidity'' make warm weather feel much more uncomfortable?','["Because humidity makes the sun shine brighter.","Because high humidity means the air is already full of water vapor, making it harder for human sweat to evaporate and cool the body.","Because humidity makes the wind blow faster.","Because humidity creates snow."]',1,'If the air is wet, your sweat can''t dry off to cool you down!','Humidity describes the amount of water vapour in the air. High humidity can make warm weather feel more uncomfortable.','2026-11-01 07:54:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_019','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'How does a ''meteorologist'' use air pressure (measured by a barometer)?','["To measure how much rain fell yesterday.","Changes in air pressure provide vital clues to help them understand developing weather systems and forecast if a storm is approaching.","To make the clouds disappear.","To stop the wind from blowing."]',1,'Falling pressure usually means bad weather is coming!','Air pressure is the force exerted by the weight of the atmosphere. Changes in pressure help meteorologists understand developing weather systems.','2026-11-01 07:54:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_020','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why should you keep a thermometer in a ''shaded, well-ventilated place'' to measure air temperature reliably?','["Because thermometers will break if they get wet.","If placed in direct sunlight or near hot surfaces, the thermometer will absorb radiant heat and measure the temperature of the sun/surface, not the actual air temperature.","Because the wind will blow the thermometer away.","Because thermometers cannot read temperatures over 20 degrees."]',1,'You want to measure the air, not how hot the sun is making the glass!','For more reliable temperature measurements, keep a thermometer in a shaded, well-ventilated place away from direct sunlight and hot surfaces.','2026-11-01 07:54:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_021','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'If a forecast predicts a ''70% chance of rain'', what does that actually mean?','["It will definitely rain for 70% of the entire day.","It suggests a significant likelihood of rain occurring at some point in the area, but the precise meaning depends on the specific forecasting service''s models.","It means 70% of the country will flood.","It means it will absolutely not rain."]',1,'It''s a probability, not a guarantee!','A 70% chance of rain does not mean it will rain for 70% of the day; the precise meaning depends on the forecasting service.','2026-11-01 07:54:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_022','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'How does the weather affect the daily activities of ''farmers''?','["Farmers ignore the weather completely.","Farmers critically depend on accurate weather forecasts to plan exactly when to plant seeds, schedule irrigation, and harvest crops before storms.","Farmers use weather forecasts to build houses.","Farmers only work when it is snowing."]',1,'If you plant seeds right before a massive flood, you lose your whole crop!','Farming: Farmers use forecasts to plan planting, irrigation, and harvesting.','2026-11-01 07:54:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_023','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why is it dangerous to stand under an ''isolated tree'' during a thunderstorm?','["Because the tree will block the rain.","Lightning typically strikes the tallest object in an area; standing under an isolated tree makes you a prime target for a lightning strike.","Because the tree will catch on fire and burn forever.","It is perfectly safe to stand under a tree."]',1,'Lightning looks for the quickest path to the ground, usually the tallest thing around!','Thunderstorms: Go indoors when thunder is heard. Stay away from isolated trees, open fields, water, and metal objects outdoors.','2026-11-01 07:54:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_024','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why should you never walk or drive through floodwater, even if it looks shallow?','["Because you might get your shoes dirty.","Floodwater can be deceptively deep and fast-moving; it can easily sweep away vehicles or hide dangerous underwater obstacles.","Because floodwater is always boiling hot.","Because floodwater turns into ice instantly."]',1,'Just a few inches of fast water can knock a person down!','Floods: Follow official instructions and avoid walking or driving through floodwater. It may be deeper or faster-moving than it appears.','2026-11-01 07:54:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_025','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'What should a person do during a ''heatwave'' to stay safe?','["Wear thick winter clothing.","Drink plenty of water, seek shade or cool indoor places, and reduce strenuous physical activity during the hottest hours.","Run a marathon in the middle of the day.","Stop drinking water entirely."]',1,'Your body needs water and rest to survive extreme heat!','Heatwaves: Drink water, seek shade or a cool indoor place, and reduce strenuous activity during the hottest hours.','2026-11-01 07:54:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_026','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why do ''stratus clouds'' often look different than ''cumulus clouds''?','["Stratus clouds are invisible.","Stratus clouds form low, grey, flat layers that spread across the whole sky (often bringing drizzle), while cumulus clouds are puffy, rounded, and separated.","Stratus clouds are made of green smoke.","Stratus clouds only appear at night."]',1,'Stratus clouds look like a giant grey blanket over the sky!','Cumulus clouds: Puffy clouds with rounded tops and relatively flat bases... Stratus clouds: Low, grey clouds that spread across much of the sky.','2026-11-01 07:54:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_027','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'How do weather stations make modern forecasts more accurate than just looking at the sky?','["They just guess based on the day of the week.","Weather stations combine precise ground instruments (thermometers, barometers) with advanced data from satellites, radar, and weather balloons to track massive global atmospheric models.","They use ancient magic.","They force the clouds to rain on command."]',1,'They can see storms forming hundreds of miles away using radar!','Weather stations combine observations from instruments with information from satellites, radar, weather balloons... Meteorologists use this information to understand current conditions and forecast future weather.','2026-11-01 07:54:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_028','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why is ''cloud cover'' an important element of weather to observe?','["Clouds block the wind entirely.","Clouds are made of condensed water; observing their type and amount provides crucial clues about moisture in the atmosphere and approaching weather systems.","Clouds are made of solid ice that falls on cities.","Clouds prove that the atmosphere is disappearing."]',1,'Dark, towering clouds usually mean a storm is coming!','Cloud cover: Clouds are made of tiny water droplets, ice crystals, or both. The amount and type of cloud cover help describe the sky... Clouds provide clues about the atmosphere...','2026-11-01 07:54:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_029','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'Why are ''forecasts not guarantees''?','["Because meteorologists always lie.","Because the atmosphere is a highly complex, chaotic system; while scientific models estimate future conditions accurately, sudden changes in pressure or wind can alter the actual weather outcome.","Because satellites don''t work in space.","Because weather never changes."]',1,'Nature is unpredictable; a storm might change direction at the last minute!','Forecasts are not guarantees. Conditions may change, so check updated forecasts and official warnings.','2026-11-01 07:54:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_030','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'How can keeping a simple ''daily weather record'' help you understand your local environment?','["It stops the rain from falling.","By recording daily temperatures, winds, and clouds over time, you can begin to recognize local weather patterns and understand how your specific climate behaves.","It makes the weather exactly the same every day.","It proves that weather instruments are broken."]',1,'If you write it down every day, you might notice it always rains on cloudy Tuesday afternoons!','A simple daily weather record can include: Date and time. Temperature... Cloud cover... Daily observations help us recognize weather patterns.','2026-11-01 07:54:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_031','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',5,'What should you do if you are outdoors and you hear thunder?','["Climb to the top of a hill.","Immediately seek safe indoor shelter and wait at least 30 minutes after the last clap of thunder before resuming outdoor activities.","Hide under a metal umbrella.","Run into an open field."]',1,'If you can hear thunder, lightning is close enough to strike you!','Thunderstorms: Go indoors when thunder is heard... Wait at least 30 minutes after the last thunder before resuming outdoor activities.','2026-11-01 07:54:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_032','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Critique the assertion that ''weather and climate'' are functionally identical concepts.','["The assertion is perfectly scientifically accurate.","The assertion conflates temporal scales; ''weather'' is the chaotic, short-term atmospheric state (e.g., a cold day), whereas ''climate'' is the statistical aggregation of weather patterns over decades (e.g., a tropical zone), meaning a cold day does not disprove global climate trends.","The assertion proves that climate change doesn''t exist.","Weather and climate are just two different words for rain."]',1,'A cold winter day (weather) doesn''t mean the planet isn''t slowly getting warmer (climate).','Weather and climate are related, but they do not mean the same thing. Weather: Conditions over a short period. Climate: Typical weather patterns over many years.','2026-11-01 07:54:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_033','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Synthesize how the measurement of ''Air Pressure'' (using a barometer) functions as a predictive tool for meteorologists.','["Air pressure directly controls the temperature of the sun.","Changes in barometric pressure indicate shifting air masses. A rapid drop in air pressure typically signifies an approaching low-pressure system, which allows air to rise, cool, and condense, often resulting in severe storms and precipitation.","Barometers only measure how fast the wind is blowing.","Air pressure has no predictive value for weather."]',1,'When the invisible weight of the air drops, bad weather is usually rushing in to fill the gap!','Air pressure is the force exerted by the weight of the atmosphere. Changes in pressure help meteorologists understand developing weather systems.','2026-11-01 07:54:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_034','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Analyze the physical mechanics behind the formation of ''Cumulonimbus'' clouds and their association with severe weather.','["They form when the sun sets and the sky turns dark.","Cumulonimbus clouds form through intense atmospheric instability and powerful vertical updrafts. As warm, moist air rises rapidly and cools at high altitudes, it creates massive, towering structures capable of producing hail, lightning, and torrential rain.","They are created purely by strong horizontal winds pushing fog.","They form when the atmosphere runs out of water vapor."]',1,'They are giant towers of turbulent, rising air!','Cumulonimbus clouds: Large, towering clouds that can produce heavy rain, lightning, thunder, hail, and strong winds.','2026-11-01 07:54:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_035','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Evaluate the epidemiological and physiological risks associated with extreme ''Heatwaves'' combined with high ''Humidity''.','["High humidity cools the body down perfectly during a heatwave.","High humidity severely impairs the human body''s primary cooling mechanism (the evaporation of sweat). When combined with extreme ambient temperatures, it can quickly lead to lethal hyperthermia (heatstroke) because the body cannot shed thermal energy.","Heatwaves are only dangerous if you are wearing winter clothes.","Humidity prevents the sun from shining, making heatwaves safer."]',1,'If the air is already full of water, your sweat can''t evaporate, and you overheat dangerously fast.','Humidity describes the amount of water vapour in the air. High humidity can make warm weather feel more uncomfortable. Heatwaves: Drink water, seek shade... reduce strenuous activity...','2026-11-01 07:54:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_036','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Synthesize the socio-economic reliance of the ''transport sector'' on accurate meteorological forecasting.','["The transport sector completely ignores meteorology.","Global logistics (aviation, shipping, trucking) rely entirely on precise weather models to avoid catastrophic hazards (hurricanes, blizzards, fog), optimize fuel efficiency via wind currents, and maintain the integrity of global supply chains.","Transport only relies on reading the stars, not weather.","Weather forecasts only affect farmers, not transport."]',1,'An airplane flying into a severe thunderstorm without warning could crash!','Transport: Heavy rain, fog, snow, and strong winds can affect roads, ships, and aircraft... Weather affects daily activities, travel...','2026-11-01 07:54:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_037','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Analyze why ''cloud appearance alone cannot guarantee what the weather will do next.''','["Because clouds are optical illusions.","While clouds visually indicate current atmospheric moisture and instability, complex atmospheric dynamics (like shifting wind shear, sudden pressure changes, or temperature inversions) can rapidly dissipate a threatening cloud or trigger unexpected precipitation.","Because clouds never produce rain.","Because all clouds are made of smoke, not water."]',1,'A dark cloud might just blow away if the wind suddenly shifts!','Clouds provide clues about the atmosphere, but cloud appearance alone cannot guarantee what the weather will do next... Forecasts are not guarantees. Conditions may change...','2026-11-01 07:54:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_038','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Critique the practice of observing weather ''without special equipment'' (e.g., estimating wind or temperature by feel) in a scientific context.','["It is the most accurate way to do science.","While useful for basic qualitative pattern recognition (e.g., ''it feels colder today''), sensory observation is highly subjective and vulnerable to physical biases (like wind chill). True meteorological science requires objective, standardized, and calibrated instruments (like anemometers) for verifiable data.","It proves that expensive instruments are a scam.","You cannot observe the weather without a computer."]',1,'Your skin might feel cold because of the wind, but a thermometer tells you the exact, objective temperature!','Scientists use instruments to measure weather accurately... You can observe the weather without special equipment. A simple daily weather record can include... (Synthesis: Simple observation is good for learning, but instruments provide the necessary scientific accuracy).','2026-11-01 07:54:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_039','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Evaluate the safety protocol of ''waiting at least 30 minutes after the last thunder'' before resuming outdoor activities.','["It is a waste of time because lightning only strikes once.","Lightning can strike unpredictably from the anvil cloud of a departing storm, even if the sky directly overhead appears clear. The 30-minute rule ensures the electrified cumulonimbus system has safely moved out of striking range.","You only need to wait 30 seconds after thunder.","Thunder is completely harmless and does not relate to lightning."]',1,'Lightning can strike up to 10 miles away from the rain; if you hear thunder, you are in danger!','Thunderstorms: Go indoors when thunder is heard... Wait at least 30 minutes after the last thunder before resuming outdoor activities.','2026-11-01 07:54:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_040','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Synthesize the function of a ''Hygrometer'' with the concept of ''Precipitation''.','["A hygrometer stops precipitation from falling.","A hygrometer measures humidity (atmospheric water vapor). Because precipitation requires the condensation of atmospheric moisture, tracking rising humidity with a hygrometer helps meteorologists predict when the air will reach saturation and produce rain or snow.","A hygrometer directly weighs the rain that has already fallen.","A hygrometer is only used to measure the temperature of snow."]',1,'You can''t have rain without water vapor in the air first!','Hygrometer: Humidity... Humidity describes the amount of water vapour in the air... Precipitation is water that falls from clouds...','2026-11-01 07:54:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_041','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Analyze the specific danger of ''walking or driving through floodwater'' in the context of fluid dynamics.','["Floodwater is always perfectly clean and safe to drink.","Fluid dynamics dictate that even shallow, fast-moving water exerts immense lateral force. Just a few inches of moving floodwater can easily overcome the friction holding a person or a heavy vehicle to the road, sweeping them away instantly.","Floodwater is completely static and never moves.","Vehicles are too heavy to ever be moved by water."]',1,'Water is incredibly heavy and powerful when it moves; it can float a car easily!','Floods: Follow official instructions and avoid walking or driving through floodwater. It may be deeper or faster-moving than it appears.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_042','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Critique the concept of a ''70% chance of rain'' in public weather forecasting.','["It means 70% of the city will be completely underwater.","The percentage (Probability of Precipitation) is frequently misunderstood by the public; it is a statistical model combining the confidence that precipitation will occur in the area with the percentage of the area expected to receive measurable rain, not a guarantee of duration.","It means it will absolutely rain for exactly 70% of the hours in a day.","It means the rain will be 70% water and 30% air."]',1,'It''s a mathematical probability involving area and confidence, not a timer!','A 70% chance of rain does not mean it will rain for 70% of the day; the precise meaning depends on the forecasting service.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_043','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Evaluate the global impact of ''weather stations'' combining ground instruments with ''satellites and radar''.','["It made ground instruments completely obsolete.","The integration of localized, ground-truth data (thermometers/barometers) with macro-level remote sensing (satellites/radar) allows meteorologists to build highly complex, predictive 3D atmospheric models, revolutionizing global disaster preparedness and weather accuracy.","It forces satellites to measure the temperature of the ground only.","It completely stopped all severe storms from forming."]',1,'You need to see the big picture from space AND the exact temperature on the ground to make a good forecast!','Weather stations combine observations from instruments with information from satellites, radar, weather balloons... Meteorologists use this information to understand current conditions and forecast future weather.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_044','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Synthesize how the physical composition of ''Cirrus clouds'' dictates their high altitude.','["They are made of heavy liquid water, so they float higher.","Cirrus clouds form in the upper troposphere where temperatures are perpetually below freezing. Because they are composed entirely of microscopic ice crystals rather than liquid water droplets, they remain thin, wispy, and suspended at extreme altitudes.","They are made of smoke from volcanoes.","They are formed by airplanes, not nature."]',1,'It is so cold up there that the water vapor freezes instantly into ice needles!','Cirrus clouds: Thin, wispy clouds high in the sky. They are made mostly of ice crystals.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_045','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Analyze the role of ''Disaster preparedness'' in mitigating the societal impact of extreme weather.','["Preparedness stops hurricanes from hitting land.","While humans cannot alter the trajectory of extreme weather (like cyclones), early warning systems powered by accurate forecasting allow for mass evacuations and infrastructural fortification, drastically reducing catastrophic loss of human life and economic devastation.","Preparedness is only useful for sunny days.","Warnings are completely ignored by governments."]',1,'You can''t stop the storm, but you can get out of its way if you know it''s coming!','Disaster preparedness: Early warnings can help communities prepare for dangerous conditions.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_weather_global_046','Geography','Physical Geography','Topic 8: Weather and Weather Observation','Primary',10,'Evaluate the physiological imperative of ''keeping exposed skin covered in extreme cold''.','["It prevents you from getting a sunburn.","Extreme cold rapidly leaches thermal energy from the body. Exposed skin is highly susceptible to frostbite (cellular freezing and tissue death) and accelerates systemic hypothermia; insulating layers are required to trap the body''s radiant heat and prevent lethal core temperature drops.","It is only a fashion choice.","Exposed skin actually generates more heat in the cold."]',1,'If skin is exposed to freezing wind, the water inside your cells can literally turn to ice!','Snow and extreme cold: Wear suitable warm clothing, keep exposed skin covered in extreme cold, and follow local travel and weather warnings.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_001','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What are ''seasons''?','["Types of clouds in the sky","Periods of the year that often have different patterns of temperature, daylight, and rainfall","The speed at which the Earth spins","Different names for the ocean"]',1,'Spring, summer, autumn, and winter are examples.','Seasons are periods of the year that often have different patterns of temperature, daylight, rainfall, snow or plant growth.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_002','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is the main cause of Earth''s seasons?','["The Moon''s gravity","Earth''s tilted axis as it revolves around the Sun","Earth moving closer to and farther from the Sun","Changes in the ocean''s temperature"]',1,'The Earth leans to one side as it goes around the Sun.','Seasons happen mainly because Earth''s axis is tilted as Earth travels around the Sun.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_003','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is ''climate''?','["The weather outside your window right now","The usual pattern of weather in a place over a long period","A sudden, heavy rainstorm","The temperature on a single day"]',1,'It is what you expect the weather to be like every year.','Climate is the usual pattern of weather in a place over a long period, often studied using 30-year averages.','2026-11-01 07:54:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_004','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What does ''weather'' describe?','["Long-term patterns over many years","Conditions over a short period, like an hour or a day","The rotation of the Earth","The tilt of the Earth''s axis"]',1,'It is what is happening right now, like rain or sunshine.','Weather: Conditions over a short period. Can change within minutes or hours.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_005','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is a ''Tropical climate''?','["A climate that is very cold for much of the year","A climate that is often warm throughout the year","A climate that always has snow","A climate found only at the North Pole"]',1,'These places are usually located near the Equator.','Tropical climate: Often warm throughout the year.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_006','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is a ''Polar climate''?','["A climate that is very hot and dry","A climate that is very cold for much of the year, with ice or tundra","A climate with moderate temperatures","A climate with distinct wet and dry seasons"]',1,'Antarctica is an example.','Polar climate: Very cold for much of the year, with extensive ice or tundra in many areas.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_007','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What defines a ''dry or desert climate''?','["It always has heavy snow.","Rainfall is very low.","It rains every day.","It is located only on islands."]',1,'Deserts are defined by being very dry, not just hot.','Dry or desert climate: Rainfall is very low in many desert regions.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_008','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What happens during ''Spring'' in many regions?','["Leaves change colour and fall off trees.","Temperatures become warmer, flowers bloom, and trees grow new leaves.","It is the coldest season with snow.","The days become the shortest of the year."]',1,'Nature seems to ''wake up'' in this season.','Spring: In many regions, temperatures become warmer after winter. Flowers bloom, trees grow new leaves...','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_009','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What happens during ''Autumn'' (Fall) in many temperate regions?','["It is the warmest season.","Leaves change colour and fall from some trees, and temperatures become cooler.","Flowers bloom and animals become more active.","It has a distinct wet season with heavy monsoon rains."]',1,'The leaves turn orange and brown before dropping.','Autumn (Fall): In many temperate regions, leaves change colour and fall from some trees. Temperatures often become cooler.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_010','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is the ''Equator''?','["The line connecting the North and South Poles","An imaginary line around the middle of Earth","The path Earth takes around the Sun","A line of longitude"]',1,'It divides the Earth into the Northern and Southern Hemispheres.','Equator: An imaginary line around the middle of Earth.','2026-11-01 07:54:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_011','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What does the word ''Hemisphere'' mean?','["A full circle","One half of Earth","A type of weather","The tilt of the Earth"]',1,'The Northern and Southern Hemispheres are examples.','Hemisphere: One half of Earth.','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_012','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What is ''revolution'' in geography?','["The spinning of Earth on its axis","Earth''s movement around the Sun","A sudden change in government","A type of strong wind"]',1,'It takes about one year to complete.','Revolution: Earth''s movement around the Sun.','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_013','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What does ''Climate change'' mean?','["The weather changing from morning to afternoon","Long-term changes in Earth''s climate patterns","A sudden rainstorm","Moving from one country to another"]',1,'It involves changes over many years, like global warming.','Climate change: Long-term changes in Earth''s climate patterns.','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_014','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'What happens during a ''wet season'' in tropical regions?','["There is no rainfall.","Rainfall is frequent or heavy, and rivers may rise.","It snows every day.","All the trees lose their leaves."]',1,'It is a time of heavy rain instead of a cold winter.','Wet season: Rainfall is frequent or heavy. Rivers may rise...','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_015','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',1,'Do all places on Earth have four distinct seasons (Spring, Summer, Autumn, Winter)?','["Yes, everywhere is exactly the same.","No, tropical regions may have wet and dry seasons, and polar regions have long periods of daylight or darkness.","Yes, but they happen on different days.","No, some places only have winter all year."]',1,'Near the equator, it is usually just wet or dry!','Important: Not every place has four clearly defined seasons. Tropical regions may have wet and dry seasons...','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_016','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'Why do the Northern and Southern Hemispheres experience opposite seasons at the same time?','["Because they are on different planets.","Because as Earth revolves around the Sun, its tilted axis causes one hemisphere to lean toward the Sun (summer) while the other leans away (winter).","Because the Sun moves up and down.","Because the equator blocks the sunlight."]',1,'If you lean your head toward a fire, your face gets hot while the back of your head is cold!','When a hemisphere tilts towards the Sun, it receives more direct sunlight... producing summer. When it tilts away... producing winter. The two hemispheres have opposite seasons.','2026-11-01 07:54:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_017','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'If it is Winter in Canada (Northern Hemisphere), what season is it in New Zealand (Southern Hemisphere)?','["Winter","Spring","Summer","Autumn"]',2,'The hemispheres are always exactly opposite!','Its seasons are generally opposite to those in the Northern Hemisphere... December is usually winter in Canada but summer in New Zealand.','2026-11-01 07:54:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_018','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'Why is the statement ''Seasons are caused by Earth moving closer to and farther from the Sun'' incorrect?','["Because the Earth never moves.","Because seasons are mainly caused by the tilt of Earth''s axis, which changes the angle and duration of sunlight, not the overall distance from the Sun.","Because the Sun is always the exact same distance away.","Because seasons are caused by the Moon."]',1,'It''s all about the tilt, not the distance!','Remember these three facts: ... Seasons are not mainly caused by Earth being closer to or farther from the Sun.','2026-11-01 07:54:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_019','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'How does a region''s climate affect the way people build their homes?','["People build the exact same houses everywhere.","People use thick insulation in cold climates to retain heat, while in hot climates they use shade and ventilation to stay cool.","Homes are only affected by the local government, not the weather.","Climate only affects clothing, not homes."]',1,'You wouldn''t build an igloo in the desert!','Homes and clothing: People use insulation and warm clothing in cold climates. In hot climates, shade, ventilation and suitable clothing help people stay comfortable.','2026-11-01 07:54:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_020','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'Why are ''wet and dry seasons'' more noticeable than temperature changes in many tropical regions?','["Because tropical regions are freezing cold.","Because tropical regions near the equator receive direct sunlight year-round, keeping temperatures warm and constant, making rainfall the main seasonal change.","Because the sun never shines in tropical regions.","Because tropical regions do not have seasons."]',1,'Near the middle of the Earth, it is always warm, so the big change is how much it rains!','In many tropical regions, changes in rainfall are more noticeable than changes in temperature.','2026-11-01 07:54:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_021','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'How does climate directly influence the work of a farmer?','["Farmers can grow any plant anywhere they want.","Farmers must choose specific crops and planting times based entirely on the local climate''s rainfall, temperature, and soil conditions.","Farmers ignore the climate and only check the daily weather.","Climate only affects what animals the farmer can keep."]',1,'You can''t grow tropical bananas in freezing snow!','Farming: Farmers choose crops and planting times according to rainfall, temperature, soil and available water.','2026-11-01 07:54:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_022','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'What does it mean for an animal to ''hibernate'' or ''migrate'' due to seasonal changes?','["They build a new house.","They adapt to the harsh winter by either sleeping through the cold months (hibernate) or traveling to a warmer climate (migrate).","They change their fur color permanently.","They learn to swim in the ocean."]',1,'Birds flying south for the winter is migration; a bear sleeping through winter is hibernation.','Plants and animals: Some animals migrate, hibernate or change their behaviour as seasons change.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_023','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'How are ''Highland or mountain climates'' different from the land surrounding them?','["They are always much hotter.","Temperatures in mountains often become much colder as elevation increases, meaning conditions can change greatly between a valley and a nearby mountain top.","They have exactly the same climate as the valley.","They never receive any rain or snow."]',1,'The higher you climb, the colder it gets!','Highland or mountain climate: Temperatures often become colder as elevation increases. Conditions can change greatly between valleys and mountain tops.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_024','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'Why is ''global warming'' a serious concern for modern society?','["Because it makes winters slightly longer.","Human activities, like burning fossil fuels, are causing rapid climate change, leading to melting glaciers, rising sea levels, and extreme heatwaves.","Because it stops all plants from growing.","Because it proves that the climate never changes."]',1,'The planet is heating up much faster than it ever has naturally.','Today, human activities... are causing global warming... Possible effects include: Higher average temperatures... Melting glaciers and rising sea levels.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_025','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'How does understanding the difference between weather and climate help us understand climate change?','["It shows that weather is fake.","It helps us realize that a single cold day (weather) does not disprove the long-term trend that the planet''s overall temperature is rising (climate).","It proves that the climate changes every single day.","It shows that they are the exact same thing."]',1,'A cold Tuesday doesn''t mean the whole year wasn''t the hottest on record!','Weather and climate are related, but they are not the same... Weather: Conditions over a short period... Climate: Patterns over many years.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_026','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'What is a ''Temperate climate''?','["A climate that is completely covered in ice.","A climate that often has moderate temperatures and noticeable seasonal changes (like distinct spring, summer, autumn, winter).","A climate with no rain at all.","A climate that is always hot and humid."]',1,'It isn''t too hot or too cold, and the seasons change clearly.','Temperate climate: Often has moderate temperatures and noticeable seasonal changes.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_027','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'How can people help reduce the impacts of rapid climate change?','["By leaving all lights on.","By saving energy, protecting forests, reducing waste, and using cleaner energy sources.","By cutting down more trees.","By burning more coal and oil."]',1,'Small actions like saving electricity help reduce the amount of fossil fuels burned!','People can help by saving energy, protecting forests, reducing waste, using cleaner energy where possible...','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_028','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'Why do some trees lose their leaves during Autumn in temperate climates?','["Because the leaves get too heavy.","As temperatures become cooler and sunlight decreases, the trees drop their leaves to conserve water and energy for the coming winter.","Because animals eat all the leaves.","Because it rains too much."]',1,'The tree is preparing to sleep through the freezing winter!','Autumn (Fall): In many temperate regions, leaves change colour and fall from some trees. Temperatures often become cooler.','2026-11-01 07:54:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_029','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'If a location is on the Equator, what happens to its seasons?','["It has extreme, freezing winters.","Because it does not tilt away from the Sun, it generally experiences warm temperatures year-round, often characterized by wet and dry seasons rather than summer and winter.","It is always covered in snow.","It is always completely dark."]',1,'The middle of the Earth always gets direct sunlight!','Tropical regions may have wet and dry seasons... Tropical climate: Often warm throughout the year.','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_030','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',5,'What does it mean for a plant to become ''dormant''?','["It grows very fast.","It temporarily stops growing and rests, usually during a cold winter or dry season, to survive harsh conditions.","It turns into an animal.","It catches on fire."]',1,'It is like hibernation for plants!','Plants may flower, produce seeds or become dormant.','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_031','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Critique the common misconception that Earth''s seasons are caused by its elliptical orbit (distance from the Sun).','["The elliptical orbit is the only cause of seasons.","If distance were the primary cause, the entire planet would experience summer simultaneously at its closest point. However, because the hemispheres experience opposite seasons concurrently, the primary cause must be the 23.5-degree axial tilt altering solar incidence angles.","Distance from the Sun proves that seasons do not exist.","The Earth''s orbit is a perfect circle, so distance doesn''t matter."]',1,'If closeness caused summer, Australia and Canada would have summer at the exact same time!','When a hemisphere tilts towards the Sun... it generally has longer daylight hours. This usually produces summer... Seasons are not mainly caused by Earth being closer to or farther from the Sun.','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_032','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Analyze how the ''angle of sunlight'' caused by Earth''s tilt affects the concentration of thermal energy.','["The angle of sunlight has no effect on heat.","When a hemisphere tilts toward the Sun, solar radiation strikes it at a direct, perpendicular angle, concentrating thermal energy into a smaller area (summer). When tilted away, the radiation strikes at an oblique angle, scattering the same energy over a larger area (winter).","The tilt causes the Sun to turn off during winter.","The angle of sunlight only affects ocean currents."]',1,'Direct sunlight is like a focused flashlight beam; angled sunlight is like a spread-out, weaker beam!','When a hemisphere tilts towards the Sun, it receives more direct sunlight... producing summer. When it tilts away from the Sun, it receives less direct sunlight...','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_033','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Synthesize why the concept of ''four distinct seasons'' is highly Eurocentric/temperate-centric when applied globally.','["Every single country on Earth has exactly four seasons.","The rigid four-season model (Spring, Summer, Autumn, Winter) accurately describes temperate zones (like Europe or North America), but fundamentally fails to describe tropical zones (defined by monsoonal wet/dry shifts) or polar zones (defined by extreme light/dark shifts).","The four seasons only exist in the Southern Hemisphere.","Tropical regions actually have eight seasons."]',1,'A farmer in the tropics doesn''t care about ''Autumn''; they care about the monsoon rains!','Important: Not every place has four clearly defined seasons. Tropical regions may have wet and dry seasons, while polar regions have very long periods of daylight or darkness...','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_034','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Evaluate the profound socio-economic implications of an unpredictable ''Monsoon'' season on agricultural societies.','["An unpredictable monsoon has no effect on society.","In agrarian societies heavily reliant on monsoons (like India), the precise timing and volume of rainfall dictate the entire agricultural yield. An unpredictable monsoon (drought or flooding) can trigger catastrophic crop failure, economic collapse, and severe famine.","Monsoons only affect cities, not farms.","An unpredictable monsoon makes farming much easier."]',1,'If the rains come a month late, all the newly planted seeds will die in the dry dirt!','For example, parts of India experience seasonal rainfall linked to the monsoon... Farming: Farmers choose crops and planting times according to rainfall...','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_035','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Analyze the specific feedback loop regarding ''melting glaciers'' and rapid climate change.','["Melting glaciers cool the Earth down.","As global warming melts highly reflective white glaciers, it exposes dark land or ocean water, which absorbs significantly more solar radiation (decreased albedo), thereby accelerating the warming process and causing even faster glacial melt in a compounding feedback loop.","Melting glaciers freeze the oceans solid.","Glaciers have no relation to climate change."]',1,'Ice reflects the sun''s heat like a mirror; when it melts, the Earth absorbs that heat!','Today, human activities... are causing global warming... Possible effects include: ... Melting glaciers and rising sea levels.','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_036','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Synthesize how extreme climate change fundamentally disrupts traditional animal ''migration'' patterns.','["Animals will simply stop migrating and stay in one place forever.","Animals migrate based on deeply ingrained seasonal cues (temperature shifts, daylight). As climate change alters the timing of these seasons, animals may migrate too early or too late, arriving at destinations when crucial food sources (like blooming plants or insects) are unavailable.","Migration is completely unaffected by climate.","Climate change causes animals to migrate to the Moon."]',1,'If a bird flies north in spring, but spring comes a month early, the bird might miss all the food!','Plants and animals: Some animals migrate, hibernate or change their behaviour as seasons change... Climate change: Changes to habitats and the lives of plants and animals.','2026-11-01 07:54:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_037','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Evaluate the distinction between a ''Polar climate'' and a ''Dry or desert climate'' in terms of precipitation.','["Polar climates have heavy rain, deserts have no rain.","While deserts are stereotypically hot, the primary defining metric for both is an extreme lack of precipitation. Therefore, most of Antarctica (a Polar climate) is technically classified as a cold desert because its atmospheric conditions are too cold to hold moisture for snowfall.","There is no distinction; they are the exact same climate.","Deserts only exist on the equator."]',1,'A desert is defined by how dry it is, not how hot it is! Antarctica is the largest desert on Earth.','Dry or desert climate: Rainfall is very low in many desert regions. Some deserts have extremely hot days and cool or cold nights... Example: ...the Antarctic Desert.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_038','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Critique the phrase: ''Climate change is natural, so modern global warming isn''t a problem.''','["The phrase is perfectly correct and we should ignore global warming.","While Earth''s climate has historically fluctuated, modern global warming is unique because its primary catalyst is anthropogenic (human-caused greenhouse gas emissions), and the rate of temperature increase is catastrophically rapid, outpacing the ability of ecosystems to adapt naturally.","The phrase is wrong because the climate has never changed before today.","Modern global warming is actually cooling the planet."]',1,'The Earth has warmed before, but never this fast! Humans are speeding it up dangerously.','Earth''s climate has changed naturally throughout its history. Today, human activities—especially burning coal, oil and gas, and clearing forests—are causing global warming and contributing to rapid climate change.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_039','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Analyze how geographical features like ''elevation'' override latitudinal expectations in a ''Highland climate''.','["Elevation makes the climate identical to the equator.","According to latitude, a region near the equator should be tropical. However, because temperature drops rapidly with elevation (the environmental lapse rate), a high mountain peak at the equator will maintain a freezing, alpine climate, completely overriding the latitudinal baseline.","Elevation causes the temperature to increase rapidly.","Elevation only affects the climate in Europe."]',1,'Even in the hot jungle, a tall mountain will have snow on top!','Highland or mountain climate: Temperatures often become colder as elevation increases. Conditions can change greatly between valleys and mountain tops.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_040','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Synthesize how humans in ''hot climates'' traditionally utilize architectural design (homes) as an adaptive response to their environment.','["They build homes entirely out of ice.","Prior to modern air conditioning, humans in hot climates engineered homes utilizing passive cooling techniques—such as maximizing shade, aligning windows to capture cross-ventilation, and using thick thermal-mass materials (like mud-brick) to block intense solar radiation.","They build homes with no windows or doors.","They do not build homes in hot climates."]',1,'Without AC, you have to build your house so the wind blows through it and the sun stays out!','Homes and clothing: ... In hot climates, shade, ventilation and suitable clothing help people stay comfortable.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_041','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Evaluate the physiological impact of ''long periods of daylight or darkness'' on humans living in polar regions.','["It has absolutely no effect on human physiology.","Extreme photoperiod variations in polar regions severely disrupt the human circadian rhythm (the biological clock), which relies on a standard 24-hour light/dark cycle to regulate sleep hormones like melatonin, often leading to seasonal affective disorders.","It causes humans to hibernate for six months.","It forces humans to sleep permanently."]',1,'Imagine trying to go to sleep when the sun is shining brightly at midnight!','Important: Not every place has four clearly defined seasons... polar regions have very long periods of daylight or darkness at certain times of the year.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_042','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Synthesize why the burning of ''coal, oil, and gas'' is specifically isolated as the primary driver of modern climate change.','["Because they produce water vapor that cools the Earth.","These fossil fuels contain massive amounts of ancient, sequestered carbon. Combusting them rapidly releases this carbon into the atmosphere as carbon dioxide, artificially thickening the atmospheric greenhouse layer and trapping excess thermal energy globally.","Because they destroy the ozone layer instantly.","Because they are perfectly clean and harmless."]',1,'Burning fossil fuels is like putting a thicker blanket around the Earth!','Today, human activities—especially burning coal, oil and gas, and clearing forests—are causing global warming and contributing to rapid climate change.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_043','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Analyze the geopolitical threat posed by ''rising sea levels'' caused by climate change.','["Rising sea levels only affect fish.","As thermal expansion and glacial melt increase ocean volume, rising sea levels pose an existential threat to low-lying island nations and heavily populated coastal megacities, threatening to create millions of climate refugees and massive economic devastation.","Rising sea levels will create new continents.","Rising sea levels will cause the oceans to dry up."]',1,'If the ocean rises even a few feet, entire cities and island countries will be permanently underwater!','Possible effects include: ... Melting glaciers and rising sea levels.','2026-11-01 07:54:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_044','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Critique the assumption that a ''wet season'' implies constant, unending rainfall.','["A wet season means it rains 24 hours a day without stopping.","The term ''wet season'' is a macroeconomic and meteorological generalization indicating a period where the statistical majority of a region''s annual precipitation occurs. It does not preclude periods of intense sunshine or dry days within that season.","A wet season actually means the air is dry.","A wet season only happens in the desert."]',1,'It''s the rainiest part of the year, but the sun still comes out!','A wet season does not mean that it rains every day, and a dry season does not mean that no rain falls at all.','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_seasons_global_045','Geography','Physical Geography','Topic 9: Seasons and Climate','Primary',10,'Evaluate how ''clearing forests'' (deforestation) serves as a double-edged catalyst for global warming.','["It stops global warming by removing trees.","Forests act as crucial ''carbon sinks,'' absorbing atmospheric CO2. Clearing them not only releases their stored carbon (often via burning), but it permanently removes the biological infrastructure necessary to filter future greenhouse gas emissions from the atmosphere.","It creates more shade for the Earth.","It has no effect on the climate."]',1,'Cutting down a forest is like destroying the Earth''s natural air filter!','Today, human activities—especially burning coal, oil and gas, and clearing forests—are causing global warming... People can help by... protecting forests...','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_001','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What is a ''natural resource''?','["Something made in a factory","Something found in nature that is useful to living things","A type of artificial plastic","A computer program"]',1,'It comes from the Earth, not from human hands.','Natural resources are materials, substances and sources of energy that occur in nature and are useful to living things.','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_002','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which of these is an example of a natural resource?','["A television","A plastic toy","Water","A mobile phone"]',2,'Water is found in nature and is essential for life.','People depend on natural resources for food, water, shelter, clothing, energy and transport.','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_003','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What does it mean if a resource is ''renewable''?','["It can never be used by humans.","It is replenished (replaced) naturally over time.","It is made of plastic.","It takes millions of years to form."]',1,'Nature makes more of it, like sunlight or wind.','Renewable resources are replenished naturally over time.','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_004','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What does it mean if a resource is ''non-renewable''?','["It can be replaced quickly in a few days.","It grows on trees.","It exists in limited quantities and takes millions of years to form.","It is a type of solar power."]',2,'Once we use it all, it is gone for a very long time.','Non-renewable resources exist in limited quantities or take extremely long periods—often millions of years—to form. They cannot be replaced quickly...','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_005','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which of these is a ''renewable'' resource?','["Coal","Sunlight","Natural gas","Petroleum (oil)"]',1,'The Sun shines every day, so we won''t run out of sunlight.','Examples include: Sunlight... Wind... Flowing water... Forests...','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_006','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which of these is a ''non-renewable'' resource?','["Wind","Sunlight","Coal","Fish"]',2,'Coal took millions of years to form underground.','Examples include: Coal... Petroleum (oil)... Natural gas... Minerals...','2026-11-01 07:54:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_007','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What are ''fossil fuels''?','["Fuels made from modern plants in a laboratory","Fuels formed from ancient organic matter, such as coal, oil, or natural gas","Energy from the sun","Energy from wind turbines"]',1,'They are dug up from deep underground.','Fossil fuel: Fuel formed from ancient organic matter, such as coal, oil or natural gas.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_008','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What does ''conservation'' mean?','["Using up all resources as quickly as possible","Protecting resources and using them wisely","Throwing rubbish into rivers","Cutting down all forests"]',1,'It means saving things for the future.','Conservation means protecting resources and using them wisely so that they remain available and healthy.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_009','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What is ''deforestation''?','["Planting new trees","Cleaning the ocean","Clearing or removing forests","Building a new city"]',2,'It happens when too many trees are cut down.','Deforestation: Clearing or removing forests.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_010','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What does ''recycling'' mean?','["Throwing waste into the ocean","Processing used materials to make new products","Burning rubbish","Burying rubbish in the ground"]',1,'Turning an old plastic bottle into a new bench is recycling.','Recycling: Processing used materials to make new products.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_011','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Where do humans get the materials (like wood, stone, and metal) to build shelters?','["They fall from the sky.","They are extracted from natural resources like forests and mines.","They are made entirely of water.","They are generated by wind turbines."]',1,'Houses are built from pieces of the Earth.','Shelter: Wood, stone, clay, sand and metal ores are used to make homes and buildings.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_012','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which natural resource do plants need to undergo photosynthesis?','["Petroleum","Sunlight","Coal","Gold"]',1,'Plants use the sun''s energy to make their food.','Sunlight provides warmth and light, helps plants grow... Air contains gases... plants use carbon dioxide during photosynthesis.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_013','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which natural resource is primarily used to make clothing like cotton shirts?','["Rocks","Petroleum","Plants","Metals"]',2,'Cotton grows in a field!','Clothing: Cotton comes from plants, wool from sheep...','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_014','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'What is ''pollution''?','["Planting new trees","Harmful substances or waste entering the environment","Using solar energy","Recycling old paper"]',1,'Smoke in the air or chemicals in the river are examples.','Pollution: Harmful substances or forms of energy entering the environment.','2026-11-01 07:54:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_015','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',1,'Which activity provides humans with rocks, minerals, and metal ores?','["Fishing","Farming","Mining","Forestry"]',2,'Miners dig these resources out of the ground.','Mining: Rocks, minerals and ores (e.g., Iron ore, copper, limestone).','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_016','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'Why is it important to remember that ''renewable'' does not mean ''unlimited''?','["Because renewable resources do not actually exist.","Because even renewable resources, like forests or fish, can be permanently destroyed if humans use them faster than nature can replace them.","Because renewable resources turn into non-renewable resources every year.","Because renewable resources are only found in space."]',1,'If you catch all the fish today, there won''t be any baby fish tomorrow!','Remember: Renewable does not mean unlimited. Forests can disappear through excessive logging, and fish populations can collapse through overfishing.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_017','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does ''sustainable use'' protect natural resources for the future?','["It means humans should completely stop using all resources.","It means meeting people''s needs today while carefully managing resources so future generations will still have what they need to survive.","It means only using non-renewable resources.","It means throwing away old resources to make room for new ones."]',1,'It means taking only what you need, and leaving enough for tomorrow.','Sustainable use means meeting people''s needs today without damaging the ability of future generations to meet their own needs.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_018','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'Why are coal, petroleum, and natural gas considered ''non-renewable'' even though they are made by nature?','["Because they are actually made in factories.","Because they take millions of years to form from ancient organic matter; once we burn them, they cannot be replaced on a human timescale.","Because they evaporate instantly when touched.","Because they are constantly falling from space."]',1,'The Earth makes more oil, but it takes millions of years; we burn it in minutes!','Non-renewable resources exist in limited quantities or take extremely long periods—often millions of years—to form. They cannot be replaced quickly on a human timescale.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_019','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does ''deforestation'' negatively affect the environment beyond just the loss of wood?','["It creates more oceans.","Removing too many trees destroys critical wildlife habitats, increases soil erosion, and reduces the forest''s ability to store carbon.","It actually helps the environment by creating flat land.","It causes volcanoes to erupt."]',1,'Trees hold the dirt together and clean the air!','Deforestation: removing too many trees can destroy habitats and increase soil erosion... Forests also store carbon and help protect soil.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_020','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does ''recycling'' metals help conserve non-renewable resources?','["It magically creates new metal from the air.","By processing used metals into new products, it reduces the need to mine for new, limited metal ores, thereby saving the non-renewable resource.","It makes the old metals disappear.","It turns metal into renewable wood."]',1,'Melting down old aluminum cans means we don''t have to dig a new hole in the ground!','Recycling metals so fewer new minerals need to be extracted.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_021','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'Why is ''soil'' considered a complex, essential natural resource?','["Because it is completely empty and sterile.","Healthy soil is essential for agriculture and contains a complex mix of mineral particles, organic matter, air, water, and living organisms.","Because it is entirely made of plastic.","Because it is only found in the ocean."]',1,'Good dirt is full of life and nutrients needed to grow our food!','Soil supports plant growth and provides a habitat for many organisms. Healthy soil contains mineral particles, organic matter, air, water and living organisms.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_022','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does the ''pollution'' of air affect both plants and animals?','["Polluted air makes plants grow faster.","Air pollution from vehicles and factories releases harmful chemicals that can cause respiratory illness in humans/animals and damage the health of plants.","Air pollution only affects airplanes.","Polluted air actually cleans the environment."]',1,'Dirty air is bad for lungs and bad for leaves!','Air pollution from vehicles, factories, burning waste and other sources can harm people, animals and plants.','2026-11-01 07:54:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_023','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'What is a major environmental risk associated with ''mining'' for non-renewable resources?','["Mining always creates new, beautiful forests.","If not managed carefully, mining can severely damage local habitats, disturb the soil, and cause serious water pollution from extracted chemicals.","Mining has absolutely no effect on the environment.","Mining only happens on other planets."]',1,'Digging a giant hole in the ground destroys the homes of the animals that lived there.','Mining provides useful materials, but it can damage habitats, disturb soil and pollute water if it is not managed carefully.','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_024','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'Why is ''water scarcity'' a growing problem even though 71% of the Earth is covered in water?','["Because all the oceans are drying up.","Because the vast majority of Earth''s water is salty ocean water; only a tiny fraction is accessible freshwater needed for drinking and farming, and it is easily overused or polluted.","Because humans only drink saltwater.","Because water is a non-renewable resource."]',1,'We live on a blue planet, but we can''t drink the ocean!','Although Earth has abundant water, most is salty ocean water, and only a small proportion is readily available freshwater. Water supplies can be threatened by pollution, overuse...','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_025','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does generating electricity with ''solar panels'' or ''wind turbines'' benefit the environment compared to burning coal?','["Solar panels and wind turbines produce heavy smoke.","They utilize renewable energy sources (sunlight and wind) that do not deplete over time and do not release greenhouse gases or air pollution while generating electricity.","They completely stop the wind from blowing.","They use up all the sunlight so plants cannot grow."]',1,'The wind and sun are free, and they don''t make dirty smoke!','Energy: Electricity can be generated using sunlight, wind... Renewable energy generation: Energy from natural flows (Solar, wind...).','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_026','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'What is the consequence of ''resource depletion''?','["Resources multiply rapidly.","Excessive extraction reduces the available supplies of vital materials (like minerals and fossil fuels) until they are completely exhausted, leaving future generations without them.","The resources turn into water.","It proves that resources are unlimited."]',1,'If you take all the cookies from the jar today, the jar is empty tomorrow!','Resource depletion: excessive extraction can reduce available supplies of minerals and fossil fuels.','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_027','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How do everyday objects like ''synthetic clothing'' rely on non-renewable resources?','["They are woven from spider webs.","Many modern synthetic fibres (like polyester or nylon) are manufactured in factories using complex chemicals derived directly from petroleum (oil).","They are grown in fields like cotton.","They are made entirely of recycled glass."]',1,'Your nylon jacket is actually made from oil pumped from the ground!','Clothing: ...many synthetic fibres are manufactured using chemicals derived from petroleum.','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_028','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'Why is ''saving water'' at home (like turning off taps) an important conservation practice?','["Because the water company will run out of pipes.","Even though water is renewable, localized clean freshwater supplies are limited; wasting water strains local reservoirs and the energy used to treat and pump the water.","Because water is non-renewable and will disappear forever.","Because running taps causes earthquakes."]',1,'Clean drinking water takes effort to produce; don''t let it run down the drain!','Save water: Turn off taps when not needed, repair leaks... Water scarcity: using more water than is replenished can reduce supplies for homes...','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_029','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'How does the ''harvesting of timber'' fit into the concept of sustainable use?','["Timber should never be harvested under any circumstances.","Timber can be harvested sustainably if the rate of logging is carefully controlled to match the rate at which new trees can be planted and naturally regrow, ensuring the forest recovers.","All timber should be harvested immediately before it goes bad.","Timber can only be harvested from non-renewable forests."]',1,'If you cut down one tree, you must plant a new one and wait for it to grow!','Sustainable use means... Harvesting timber at a rate that allows forests to recover.','2026-11-01 07:54:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_030','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',5,'What does it mean to say that conservation ''does not mean that people can never use natural resources''?','["It means people should destroy resources for fun.","It means humans must use resources to survive and build society, but conservation requires us to use them responsibly, efficiently, and with minimal environmental harm.","It means conservation is entirely fake.","It means only machines can use resources."]',1,'We need wood to build houses, but we don''t need to cut down the entire forest to do it!','Conservation does not mean that people can never use natural resources. It means using them responsibly and reducing avoidable harm.','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_031','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Critique the rigid binary classification of resources into strictly ''renewable'' or ''non-renewable''.','["The binary classification is a perfect, flawless scientific law.","The binary is overly simplistic. ''Renewable'' resources like freshwater aquifers or fertile topsoil regenerate at such slow geological rates that, under intense modern anthropogenic extraction, they functionally act as finite, non-renewable resources on a human timescale.","The binary classification proves that all resources are renewable.","Non-renewable resources actually regenerate in a few days."]',1,'If it takes 1,000 years for an aquifer to refill, and we drain it in 10 years, it isn''t practically ''renewable'' for us!','Important distinction: Some resources, such as freshwater and soil, need careful management. They may be naturally replenished, but not always fast enough to meet human needs.','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_032','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Analyze the systemic environmental paradox inherent in transitioning to ''Renewable Energy'' technologies (like solar panels and wind turbines).','["Renewable energy technologies require no physical materials to build.","While the energy sources (sun/wind) are infinitely renewable and zero-emission, the physical infrastructure (panels/turbines/batteries) requires massive global mining operations for rare earth metals and minerals (non-renewable resources), causing localized ecological damage.","Renewable energy technologies actually produce more fossil fuels.","Solar panels are grown organically from seeds."]',1,'You need to mine non-renewable copper and lithium out of the ground to build a ''green'' wind turbine!','Mining: Rocks, minerals and ores... used to make steel, aluminium, copper and electronic components. Mining provides useful materials, but it can damage habitats...','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_033','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Synthesize how ''Overfishing'' disrupts marine trophic cascades and threatens global food security.','["Overfishing only removes older fish, making the ocean healthier.","By systematically extracting apex predators or foundational species faster than they reproduce, overfishing causes a structural collapse of marine food webs. This ecological failure directly threatens the primary protein source and economic livelihood of billions of coastal humans.","Overfishing proves that fish reproduce instantly.","Overfishing has absolutely no impact on human food supplies."]',1,'If you take all the adult fish, they can''t make baby fish, and the entire ocean starves—including the fishermen!','Fish and other living resources: can reproduce if... harvesting is controlled... Resource depletion... Overfishing... Catching fish in ways that allow populations to reproduce.','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_034','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Evaluate the socio-economic implications of ''Resource Depletion'' for nations heavily dependent on fossil fuel extraction.','["Resource depletion will make those nations permanently invincible.","As finite fossil fuel reserves are inevitably exhausted, nations economically anchored solely to extraction will face catastrophic economic collapse and severe geopolitical vulnerability unless they systematically transition their economies toward sustainable or diversified industries.","Resource depletion proves that fossil fuels are unlimited.","Depleted resources will magically refill themselves."]',1,'If your entire country''s economy relies on selling oil, what happens when the oil well runs dry?','Resource depletion: excessive extraction can reduce available supplies of minerals and fossil fuels... Resources are important not only for people living today but also for future generations.','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_035','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Analyze how ''Deforestation'' acts as a dual catalyst for both localized ecological collapse and global climate change.','["Deforestation only affects the specific trees that are cut.","Locally, deforestation destroys biodiversity and causes severe soil erosion. Globally, it acts as a catastrophic climate feedback loop: removing trees eliminates a critical carbon sink, and burning/clearing the timber releases massive amounts of sequestered CO2 into the atmosphere.","Deforestation actually cools the global climate.","Deforestation prevents soil erosion completely."]',1,'Cutting down a forest destroys the local animals'' homes AND stops the Earth from cleaning its air!','Deforestation: removing too many trees can destroy habitats and increase soil erosion... Forests also store carbon... burning coal, oil and gas, and clearing forests—are causing global warming...','2026-11-01 07:54:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_036','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Synthesize the concept of ''Sustainability'' in terms of intergenerational equity.','["Sustainability means current generations should consume everything immediately.","Sustainability is fundamentally an ethical framework regarding temporal fairness; it dictates that the economic and consumptive privileges of the present generation must not systemically degrade the environmental capital required for the survival and prosperity of future generations.","Sustainability proves that future generations do not matter.","Sustainability is only concerned with the past, not the future."]',1,'You shouldn''t throw a party today if it means your children have to starve tomorrow!','Sustainable use means meeting people''s needs today without damaging the ability of future generations to meet their own needs... Sustainability: Meeting current needs while protecting future generations'' ability to meet theirs.','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_037','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Critique the assumption that ''Recycling'' is the ultimate solution to the global waste crisis.','["Recycling completely eliminates the need for any raw materials.","While vital for conserving extracted minerals, recycling is highly energy-intensive, often degrades material quality (downcycling), and cannot process all waste streams. It must be subordinate to systemic ''Reduction'' and ''Reuse'' to genuinely mitigate overconsumption and industrial pollution.","Recycling actually creates more raw materials than it uses.","Recycling is a complete myth and does not exist."]',1,'It takes a lot of energy to melt down a plastic bottle; it is much better to just use a reusable bottle!','Reduce, reuse and recycle: Buy only what you need, reuse suitable items and recycle materials... (Synthesis: ''Reduce'' is listed first because preventing waste is better than processing it).','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_038','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Evaluate the geopolitical tension caused by the uneven global distribution of ''Non-renewable resources'' (like petroleum and rare minerals).','["Uneven distribution ensures perfect global peace and equality.","Because vital non-renewable resources are geographically concentrated within specific national borders, they create severe geopolitical imbalances, often triggering international conflicts, economic monopolies, and the exploitation of resource-rich developing nations by powerful industrial states.","Uneven distribution proves that all countries have the exact same resources.","Non-renewable resources have no value in geopolitics."]',1,'If a country needs oil to survive but doesn''t have any, they have to buy it from—or fight—a country that does!','Non-renewable resources exist in limited quantities... (Synthesis: The limitation and location of these resources drive global economics and politics).','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_039','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Analyze how the ''Water Cycle'' technically makes water a renewable resource, yet localized ''Water Scarcity'' remains a critical crisis.','["Water scarcity is an illusion because the ocean is huge.","While the global volume of water remains constant via the water cycle, human populations often aggressively over-extract localized freshwater aquifers and rivers faster than localized precipitation can recharge them, creating severe, localized desiccation and humanitarian crises.","The water cycle removes water from Earth entirely.","Water scarcity proves that the water cycle does not exist."]',1,'The Earth has plenty of water, but if a city pumps its local lake dry faster than it rains, that city is in trouble!','Water scarcity: using more water than is replenished can reduce supplies for homes, farms and wildlife... Some resources, such as freshwater... may be naturally replenished, but not always fast enough to meet human needs.','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_040','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Synthesize how the industrial reliance on ''Fossil Fuels'' creates a negative externality (Climate Change) that threatens ''Renewable Resources'' (like forests and agriculture).','["Fossil fuels protect forests by providing artificial sunlight.","The combustion of fossil fuels drives rapid anthropogenic climate change, altering global precipitation and temperature baselines. This extreme climatic shift directly destabilizes ''renewable'' agricultural cycles and forest ecosystems, rendering them increasingly vulnerable to drought, fires, and collapse.","Fossil fuels have absolutely no connection to climate change or agriculture.","Climate change actually causes forests to grow exponentially."]',1,'Burning coal causes droughts, and droughts kill the ''renewable'' crops that farmers rely on!','Climate change: burning fossil fuels releases greenhouse gases that contribute to global warming... Changes in rainfall patterns... Changes to habitats and the lives of plants and animals.','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_041','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Evaluate the profound ecological significance of ''Soil'' as a dynamic, living system rather than just inert dirt.','["Soil is completely sterile and contains no living organisms.","Soil is a highly complex, biological matrix (containing microbes, fungi, organic matter, and minerals) that forms the foundational base of terrestrial food webs and acts as a massive global carbon sink. Its degradation via industrial farming poses a catastrophic threat to global food security.","Soil is entirely composed of crushed plastic.","Soil has no role in supporting plant growth."]',1,'Dirt isn''t dead! It is packed with billions of tiny living things that help plants grow.','Healthy soil contains mineral particles, organic matter, air, water and living organisms. Soil can be damaged by erosion, pollution, excessive chemical use...','2026-11-01 07:54:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_042','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Critique the concept of ''economic growth'' when it relies strictly on the linear extraction of non-renewable resources.','["Continuous economic growth based on non-renewables is mathematically infinite.","A macroeconomic model predicated on the perpetual extraction of finite, non-renewable resources is fundamentally unsustainable; it guarantees eventual resource exhaustion, necessitating a structural transition to a circular economy (focusing on recycling and renewables) to avoid systemic collapse.","Economic growth actually creates more non-renewable resources.","Extracting non-renewables has no impact on economic growth."]',1,'You can''t base a forever-growing economy on a pile of coal that is slowly shrinking!','Non-renewable resources exist in limited quantities... excessive extraction can reduce available supplies... Sustainable use means meeting people''s needs today without damaging the ability of future generations...','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_043','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Analyze how the ''Pollution'' of air directly impacts the economic viability of the ''Farming'' and ''Forestry'' sectors.','["Air pollution acts as a powerful fertilizer, doubling crop yields.","Atmospheric pollutants (like sulfur dioxide or ground-level ozone) can cause acid rain and inhibit photosynthesis, directly stunting crop yields, damaging commercial timber forests, and causing massive, cascading economic losses in agricultural sectors.","Air pollution is completely ignored by plants.","Air pollution only affects the ocean, not land-based farming."]',1,'If the air is toxic, the plants get sick, and the farmers lose money!','Air pollution... can harm people, animals and plants. Soil can be damaged by... pollution... Farming: Crops and livestock...','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_044','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Synthesize the ethical argument for ''Conservation'' as a moral responsibility to non-human species.','["Conservation is only about ensuring humans have enough wood to build houses.","Beyond utilitarian human resource management, conservation carries the profound ethical imperative to preserve Earth''s biodiversity. By mitigating habitat loss and pollution, humans acknowledge the intrinsic right of diverse species to exist within stable, healthy ecosystems.","Conservation dictates that all non-human species should be eradicated.","Animals do not require natural habitats to survive."]',1,'We share this planet; protecting the forest isn''t just for timber, it''s to save the animals that live there!','Plants provide... habitats for animals. Habitat loss: mining, construction and poorly managed farming can harm wildlife. Conservation means protecting resources and using them wisely so that they remain available and healthy.','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_resources_global_045','Geography','Physical Geography','Topic 10: Natural Resources of the Earth','Primary',10,'Evaluate how ''Technological Innovation'' acts as a double-edged sword regarding Natural Resources.','["Technology completely eliminates the need for any natural resources.","While technology increases efficiency (e.g., better solar panels) and enables deeper resource extraction, it simultaneously invents new demands for rare materials (e.g., lithium for batteries) and drastically accelerates global consumption rates, requiring stringent sustainability protocols to offset the increased extraction.","Technology always destroys all renewable resources instantly.","Technology has completely frozen resource extraction at 19th-century levels."]',1,'We invent better machines to save energy, but those new machines require us to dig up new, rare minerals!','Rocks and minerals are used in buildings, roads, tools, electronics... Resource depletion: excessive extraction can reduce available supplies... Sustainable use means meeting people''s needs today...','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_001','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What is a ''habitat''?','["A type of animal","The natural place where an organism lives and finds the conditions it needs to survive","A tool used for farming","A weather pattern"]',1,'It provides food, water, and shelter for living things.','A habitat is the natural place where an organism lives and finds the conditions it needs to survive.','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_002','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'How do most plants make their own food?','["By eating insects","By using sunlight, water, and carbon dioxide through photosynthesis","By drinking milk","By absorbing it from rocks"]',1,'Plants use the sun''s energy to feed themselves.','Most plants make their own food using sunlight, water and carbon dioxide through a process called photosynthesis.','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_003','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What is an ''adaptation''?','["A type of disease","A feature or behaviour that helps an organism survive in its environment","A type of weather","A machine used in farming"]',1,'A polar bear''s thick fur is an example of an adaptation.','Plants have features that help them survive in their environments. These features are called adaptations.','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_004','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What does a ''food chain'' show?','["How to cook food","How energy passes from one organism to another when one is eaten","How fast animals can run","Where animals sleep"]',1,'It shows who eats what in nature.','A food chain shows how energy passes from one organism to another when one is eaten by another.','2026-11-01 07:54:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_005','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'In a food chain, what is a ''producer''?','["An animal that eats meat","An organism that makes its own food, usually a plant","A mushroom that breaks down dead things","An animal that eats insects"]',1,'Grass is a producer.','Producers make their own food, usually using sunlight.','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_006','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'In a food chain, what is a ''consumer''?','["A plant that makes its own food","An organism that obtains energy by eating plants or other organisms","The sun","The dirt on the ground"]',1,'A lion is a consumer because it eats other animals.','Consumers obtain energy by eating plants or other organisms.','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_007','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What is the job of a ''decomposer'' (like fungi or bacteria)?','["To make sunlight","To hunt large animals","To break down dead organisms and waste, returning nutrients to the environment","To grow new leaves"]',2,'They act as nature''s recyclers.','Decomposers, including many fungi and bacteria, break down dead organisms and waste, returning nutrients to the environment.','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_008','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What does ''biodiversity'' mean?','["The number of rocks in an area","The variety of living things in an area or on Earth","The amount of rain that falls","A type of large animal"]',1,'It means having many different types of plants and animals.','Biodiversity means the variety of living things in an area or on Earth...','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_009','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What does ''extinction'' mean?','["An animal moving to a new home","A plant growing very tall","The disappearance of a species from Earth so it no longer exists anywhere","An animal going to sleep for the winter"]',2,'Dinosaurs are an example of an extinct group of animals.','Extinction means that a species no longer exists anywhere on Earth.','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_010','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'Which of these is an example of a ''Marine habitat''?','["A desert","A coral reef or ocean","A tall mountain","A grassy plain"]',1,'These habitats are full of saltwater.','Marine habitats: Include oceans, coral reefs, rocky shores and open water.','2026-11-01 07:54:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_011','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'Which of these is an example of a ''Freshwater habitat''?','["An ocean","A river or lake","A coral reef","A dry desert"]',1,'Fish and frogs live in these waters.','Freshwater habitats: Include rivers, lakes, ponds and wetlands.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_012','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What type of habitat is known for being warm, wet, and having dense vegetation with tall trees?','["Polar region","Desert","Tropical rainforest","Grassland"]',2,'Monkeys and parrots live here.','Tropical rainforests: Often warm and wet, with dense vegetation and many different species.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_013','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What type of habitat is dominated by grasses and grazing animals, with very few trees?','["Grassland","Marine habitat","Tropical rainforest","Tundra"]',0,'Zebras and elephants often live here.','Grasslands: Areas dominated by grasses, often with scattered trees or shrubs.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_014','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What do camels store in their humps to help them survive in the desert?','["Water","Air","Fat","Sand"]',2,'The fat gives them energy when there is no food.','Camels can conserve water... Their humps store fat, not water.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_015','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',1,'What is one way to protect biodiversity?','["Throwing plastic into the river","Protecting natural habitats like forests and wetlands","Cutting down all the trees","Hunting all the animals"]',1,'Keeping their homes safe keeps the animals safe.','Everyone can help protect living things... Protect forests, wetlands, rivers and coastal habitats.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_016','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why is ''habitat destruction'' considered one of the biggest threats to wildlife?','["Because it makes the animals bored.","If organisms lose the specific places they need to feed, shelter, and reproduce, they cannot survive and their populations will decline.","Because animals do not need habitats.","Because it makes the weather too cold."]',1,'If you destroy an animal''s home and food source, the animal will die.','Habitat destruction: Organisms lose places to feed, shelter and reproduce... Protecting habitats is often more effective than trying to protect one species while leaving its environment damaged.','2026-11-01 07:54:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_017','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How do ''decomposers'' (like mushrooms) help a forest ecosystem stay healthy?','["They eat all the living trees.","They break down dead leaves and fallen trees, which recycles important nutrients back into the soil so new plants can grow.","They block the sunlight from reaching the ground.","They scare away dangerous predators."]',1,'Without them, the forest would be buried in dead leaves and the soil would have no food for new plants!','Decomposers, including many fungi and bacteria, break down dead organisms and waste, returning nutrients to the environment.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_018','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why is it important to understand that a ''food chain'' usually connects to form a ''food web'' in nature?','["Because animals only ever eat one type of food.","Because in reality, most animals eat (and are eaten by) several different things, creating a complex network of connections rather than just a single straight line.","Because spiders build webs in the forest.","Because food chains are actually illegal."]',1,'A frog might eat a grasshopper, a fly, and a worm, not just one thing!','In nature, food chains connect to form food webs. Most organisms have several feeding relationships rather than just one.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_019','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How does a polar bear''s physical adaptation help it survive in the Arctic?','["It breathes fire to melt the ice.","It has thick fur and a layer of body fat to retain heat in freezing temperatures, and large paws to help it swim and walk on ice.","It grows wings to fly south for the winter.","It turns green to hide in the grass."]',1,'Every part of the bear''s body is built to survive the freezing cold!','Polar bears: Thick fur and a layer of body fat help them retain heat in the Arctic. Their large paws help them move across ice and swim.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_020','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How do mangrove trees adapt to survive in coastal habitats where most plants would die?','["They grow completely underwater.","They have specialized root systems that allow them to live in muddy, salty water environments.","They produce fruit made of pure salt.","They absorb salt directly into their leaves and explode."]',1,'Most trees die if you pour salt water on them, but mangroves are adapted to it!','Mangrove trees: Many mangroves have specialised roots that help them live in muddy, salty coastal environments.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_021','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why do some animals choose to ''migrate'' instead of staying in one habitat all year?','["They like to go on vacation.","When the seasons change and weather becomes too harsh or food becomes scarce, they travel long distances to find a habitat with better conditions for survival and breeding.","Because they get lost easily.","Because the sun forces them to move."]',1,'Birds fly south in the winter because the bugs they eat freeze in the north!','Animals can also survive through behaviour. Some migrate to find food or suitable breeding places... Migration: Movement from one area to another, often seasonally.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_022','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'If a toxic chemical pollutes a river, how does the concept of a ''food chain'' explain how a bird could get sick?','["The bird might drink the air above the river.","The chemical gets absorbed by river plants, which are eaten by small fish, which are then eaten by the bird, passing the poison up the food chain.","The bird is completely immune to river pollution.","Food chains only pass good energy, not chemicals."]',1,'The bird doesn''t have to touch the toxic water; it just has to eat a fish that did!','A food chain shows how energy passes from one organism to another when one is eaten by another... Pollution: Water, soil and air can become harmful to living things.','2026-11-01 07:54:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_023','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why are ''invasive species'' considered a major threat to biodiversity?','["Because they clean up the environment too quickly.","Because these introduced species are not native to the area; they can rapidly multiply, eat all the food, and harm or outcompete the native species that belong there.","Because they are always much smaller than native species.","Because they plant new trees."]',1,'If you bring a new predator to an island, it might eat all the native birds that don''t know how to hide from it!','Invasive species: Introduced organisms can harm native species and ecosystems.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_024','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How does high ''biodiversity'' actually help human beings?','["It makes the air harder to breathe.","A biodiverse planet provides humans with a variety of food crops, raw materials like fibres, and many important medicines derived from different plants and fungi.","It prevents humans from building houses.","It has absolutely no benefit to human beings."]',1,'Many medicines you buy at the pharmacy originally came from a rare plant in the rainforest!','Biodiversity is important because living things: Provide food, fibres and some medicines. Help pollinate flowers and crops.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_025','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'What do the arrows in a drawn ''food chain'' specifically represent?','["Which animal is the biggest.","They show the direction in which energy passes from the organism that is eaten to the organism that eats it.","They show which way the wind is blowing.","They show how fast the animals can run."]',1,'The arrow points FROM the grass TO the grasshopper!','The arrows show the direction in which energy passes: from the food to the organism eating it.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_026','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why is ''overhunting and overfishing'' dangerous for an ecosystem?','["It makes the animals lazy.","If humans remove animals from a population faster than those animals can reproduce and replace themselves, the population will crash and could eventually face extinction.","It causes the animals to grow much larger.","It forces the animals to migrate to the moon."]',1,'You can''t take 100 fish out of a lake if the fish only make 10 babies a year!','Overhunting and overfishing: Populations may decline faster than they can recover... When habitats are damaged or populations decline... some species may become endangered or extinct.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_027','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How do some desert plants, like cacti, survive with almost no rainfall?','["They secretly import water from the ocean.","They have adaptations like thick stems that store water like a sponge, and sharp spines instead of wide leaves to reduce water loss.","They only grow during the winter when it snows.","They drink blood from animals."]',1,'A cactus is built to hold onto every single drop of water it gets!','Desert plants: Some cacti store water in thick stems. Their spines help reduce water loss and protect them from some animals.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_028','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'Why might a tropical rainforest have more ''biodiversity'' than a polar tundra?','["Because it is closer to the moon.","The warm, wet climate and dense vegetation of a rainforest provide a massive variety of food sources and micro-habitats, supporting many more different species than a freezing, harsh tundra.","Because animals do not like the snow.","Because the tundra is entirely underwater."]',1,'A warm jungle with thousands of fruit trees can feed many more types of animals than a frozen wasteland!','Tropical rainforests: Often warm and wet, with dense vegetation and many different species... Polar regions and tundra: Very cold conditions and short growing seasons limit plant growth in many areas.','2026-11-01 07:54:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_029','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'What does it mean when animals ''interact with the non-living parts of their environment''?','["They fight with rocks.","It means animals rely on things that aren''t alive to survive, such as drinking water, breathing air, and using sunlight for warmth.","They pretend that rocks are other animals.","It means they ignore everything except food."]',1,'A fish needs water to swim in, and a lizard needs a warm rock to sit on—both water and rocks are non-living!','Non-living parts of an environment include sunlight, water, air, rocks, soil and temperature. Living things depend on these factors in different ways.','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_030','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',5,'How does ''climate change'' threaten habitats worldwide?','["It makes every habitat exactly the same.","By shifting long-term temperatures and rainfall patterns, it alters the specific conditions (like ice melting or droughts) that local plants and animals have specifically adapted to survive in.","It causes animals to instantly turn into plants.","It prevents the sun from shining on the habitats."]',1,'If a polar bear''s ice melts because the Earth gets warmer, the bear loses its home!','Climate change: Temperatures and rainfall patterns change, affecting habitats... When habitats are damaged... food webs can change and some species may become endangered...','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_031','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Critique the anthropocentric strategy of ''protecting one specific endangered species'' versus ''protecting the entire habitat''.','["Protecting one species is always 100% effective and much cheaper.","Protecting a single species (like a panda) in isolation often fails if the underlying ecosystem is collapsing. Habitat conservation is a superior holistic strategy because it simultaneously protects the target species, its food web, and the countless undiscovered microorganisms that sustain the biome.","Protecting the habitat actually harms the endangered species.","It is impossible to protect a habitat without destroying a city."]',1,'You can''t save the fish if you don''t save the river!','Protecting habitats is often more effective than trying to protect one species while leaving its environment damaged... Ecosystem: Living organisms interacting with each other and their non-living environment.','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_032','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Analyze how the ''extinction'' of a primary consumer (e.g., a specific grasshopper) can trigger a systemic trophic cascade in a food web.','["The extinction will only affect the grasshopper itself.","The loss of a primary consumer disrupts energy flow upward (predators like frogs starve due to prey loss) and downward (producers like grass overgrow due to lack of grazing), potentially destabilizing and collapsing the entire localized ecosystem.","The predators will simply eat grass instead.","The extinction will cause the grass to instantly die."]',1,'In a web, if you cut one string, the whole net sags!','When habitats are damaged or populations decline, food webs can change and some species may become endangered or extinct... A food web: A network of connected food chains.','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_033','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Synthesize the evolutionary purpose of the ''spines'' on a cactus in a desert biome.','["They act as solar panels to absorb more sunlight.","Spines serve a dual adaptive function: their minimal surface area drastically reduces transpirational water loss in hyper-arid conditions, and they physically deter thirsty desert herbivores from consuming the plant''s stored internal water reserves.","They are used to attack other plants.","They catch rain droplets and funnel them to the roots."]',1,'A spine is just a modified leaf that doesn''t lose water and keeps hungry animals away!','Desert plants: Some cacti store water in thick stems. Their spines help reduce water loss and protect them from some animals.','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_034','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Evaluate the profound ecological significance of ''pollinators'' (like bees) to both natural biodiversity and human agriculture.','["Pollinators only exist to make honey for humans.","Pollinators are keystone species; by facilitating the sexual reproduction of flowering plants, they sustain the genetic diversity of natural botanical ecosystems and are mechanically responsible for producing a massive percentage of the global human food supply.","Pollinators actually destroy crops by eating the flowers.","Pollinators only help plants grow taller, not reproduce."]',1,'Without bees moving pollen from flower to flower, we wouldn''t have apples, almonds, or coffee!','Biodiversity is important because living things: ...Help pollinate flowers and crops... For example, bees and other pollinators help many flowering plants reproduce.','2026-11-01 07:54:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_035','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Analyze how ''invasive species'' exploit the vulnerability of isolated ecosystems (like islands).','["Invasive species always peacefully share resources with native species.","Isolated ecosystems often lack natural predators or evolutionary defenses. When an invasive species is introduced, it exploits this ecological naivete, aggressively outcompeting, predating upon, or spreading novel diseases to native species, often driving them to rapid extinction.","Invasive species cannot survive on islands.","Native species always instantly evolve to defeat invasive species."]',1,'If a snake is accidentally brought to an island where birds nest on the ground because they''ve never had predators, the snake will eat all the birds!','Invasive species: Introduced organisms can harm native species and ecosystems.','2026-11-01 07:54:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_036','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Synthesize the relationship between ''photosynthesis'' and the atmospheric carrying capacity for animal life.','["Photosynthesis consumes all the oxygen, making it harder for animals to breathe.","Photosynthesis is the foundational biochemical process of the biosphere. Producers use solar energy to sequester carbon dioxide and release oxygen as a byproduct, simultaneously generating the base caloric energy (food) and the breathable atmosphere required by all aerobic animal life.","Photosynthesis only produces water, not energy or oxygen.","Animals do not rely on photosynthesis in any way."]',1,'Plants are the engine of life; they make the food and the oxygen!','Plants: Most plants make their own food using sunlight, water and carbon dioxide through a process called photosynthesis... Animals obtain energy by eating plants...','2026-11-01 07:54:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_037','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Critique the assertion that ''fungi and bacteria are pests that should be eliminated from a healthy forest''.','["Fungi and bacteria are indeed pests that destroy the forest.","This assertion represents a fundamental ecological misunderstanding. Fungi and bacteria act as vital decomposers; without their biochemical ability to break down complex dead organic matter, the forest would choke on detritus and soil nutrient cycling would permanently cease, killing all plants.","Fungi and bacteria only eat living animals.","Fungi and bacteria are actually a type of rock."]',1,'Without mushrooms and bacteria, the forest would run out of food in the dirt!','Decomposers, including many fungi and bacteria, break down dead organisms and waste, returning nutrients to the environment... Decomposers break down dead material, allowing nutrients to be reused.','2026-11-01 07:54:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_038','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Evaluate how ''climate change'' acts as a threat multiplier for ''habitat destruction''.','["Climate change reverses habitat destruction by growing new forests.","While human development physically destroys habitats, rapid climate change alters the fundamental temperature and precipitation baselines of remaining habitats. This forces species to migrate out of protected reserves to survive, leaving them vulnerable to extinction if escape routes are blocked by human infrastructure.","Climate change only affects the ocean, not land habitats.","Habitat destruction prevents climate change from happening."]',1,'If a nature reserve gets too hot, the animals have to leave the safe zone to survive!','Climate change: Temperatures and rainfall patterns change, affecting habitats... When habitats are damaged... some species may become endangered or extinct.','2026-11-01 07:54:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_039','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Synthesize how the concept of ''genetic differences within species'' strengthens overall Biodiversity.','["Genetic differences mean the species will instantly go extinct.","Intraspecific genetic diversity provides a crucial evolutionary buffer. If an entire species is genetically identical, a single novel pathogen or environmental shift could eradicate the entire population; genetic variance ensures that at least some individuals may possess the traits required to survive and reproduce.","Genetic differences only affect the color of the animal.","Genetic diversity makes animals weaker against diseases."]',1,'If every plant is exactly the same, one disease can kill them all; difference is a survival strategy!','Biodiversity means the variety of living things... including different species, genetic differences within species and ecosystems.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_040','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Analyze the physical mechanics of ''camouflage'' (like a chameleon''s color-changing skin) as an evolutionary adaptation.','["Camouflage is only used to look pretty to humans.","Camouflage provides a dual survival advantage in the predator-prey arms race: it allows predators to remain visually undetectable to ambush prey, while simultaneously allowing prey species to visually blend into the ambient environment to evade detection by predators.","Camouflage makes an animal highly visible and easy to catch.","Camouflage is a trick animals use to control the weather."]',1,'Blending in means you don''t get eaten, or you get to eat!','Chameleons: Many chameleons have colour-changing skin. Colour changes can help with... camouflage in some situations... Adaptation: A feature or behaviour that helps an organism survive and reproduce.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_041','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'How does the ''Illegal wildlife trade'' directly undermine international conservation efforts?','["It helps conservation by moving animals to safer countries.","By creating a lucrative black market for endangered animal parts (e.g., ivory, rhino horn), the illegal trade incentivizes aggressive poaching, which systematically decimates vulnerable populations and completely bypasses the legal frameworks established to manage and protect biodiversity.","It is a legal way to fund conservation projects.","It only trades in very common, non-endangered animals."]',1,'When an animal''s horn is worth more than gold on the black market, hunters will kill the very last one!','Illegal wildlife trade: Some animal and plant populations become threatened... Populations may decline faster than they can recover.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_042','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Critique the conceptual difference between a ''Food Chain'' and a ''Food Web'' in modeling ecological reality.','["A food chain is highly accurate, while a food web is fictional.","A food chain is a linear, heavily simplified pedagogical model (A eats B eats C). A food web is a far more accurate representation of ecological reality, mapping the chaotic, highly interconnected, and multi-directional feeding relationships that actually sustain an ecosystem.","A food web only applies to spiders.","They are two exact words for the exact same model."]',1,'In real life, a snake doesn''t just eat frogs; it eats mice, birds, and lizards too!','A food chain shows how energy passes... In nature, food chains connect to form food webs. Most organisms have several feeding relationships rather than just one.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_043','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Synthesize how the specific adaptations of ''Aquatic plants'' (like water lilies) solve the physical challenges of their marine or freshwater habitat.','["They grow heavy rocks to sink to the bottom.","To survive in a fluid medium where light penetration is limited, aquatic plants evolve buoyant, floating leaves (to maximize solar absorption for photosynthesis) and internal aerenchyma (air spaces) to maintain structural buoyancy and facilitate gas exchange underwater.","They evolve to survive entirely without sunlight or water.","They adapt by growing long legs to walk out of the water."]',1,'They have built-in floaties so their leaves can reach the sun at the top of the pond!','Aquatic plants: Some water plants have floating leaves and air spaces that help them live in water.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_044','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Analyze the systemic environmental impact of ''pollution'' on the non-living (abiotic) components of an ecosystem.','["Pollution only affects living animals, not the non-living parts.","Pollution fundamentally degrades the abiotic foundation of a habitat (e.g., acidifying soil, contaminating groundwater, altering atmospheric gas ratios). Because all biotic organisms rely entirely on these non-living factors for survival, poisoning the abiotic environment inevitably causes systemic biological collapse.","Pollution makes soil richer and water cleaner.","Pollution only affects the ocean, not land."]',1,'If you poison the dirt and the water, everything that lives there will eventually die.','Pollution: Water, soil and air can become harmful to living things... Non-living parts of an environment include sunlight, water, air, rocks, soil... Living things depend on these factors...','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_habitats_global_045','Geography','Physical Geography','Topic 11: Plants, Animals, and Habitats','Primary',10,'Evaluate why ''Tropical rainforests'' harbor significantly more biodiversity than ''Polar regions and tundra''.','["Because scientists purposely placed all the animals in the rainforest.","The extreme, freezing conditions and negligible growing seasons of the tundra severely limit primary production (plant growth), whereas the perpetual warmth, intense solar radiation, and high precipitation of the rainforest catalyze explosive primary production, capable of sustaining vastly more complex, multi-tiered food webs.","Because animals in the tundra are all completely invisible.","Because the tundra is actually much hotter than the rainforest."]',1,'More sun and rain equals more plants, which equals more food for thousands of different animals!','Tropical rainforests: Often warm and wet, with dense vegetation and many different species... Polar regions and tundra: Very cold conditions and short growing seasons limit plant growth in many areas.','2026-11-01 07:54:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_001','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''settlement''?','["A type of wild animal","A place where people live","A natural forest","A type of ocean"]',1,'It is the word for any place where human homes are built.','A settlement is a place where people live. Settlements range from small groups of homes to large cities...','2026-11-01 07:54:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_002','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What are ''rural'' settlements?','["Huge cities with skyscrapers","Settlements in the countryside and less densely built-up areas","Settlements located only underwater","Places where nobody lives"]',1,'Think of farms and open spaces.','Rural settlements are settlements in the countryside and less densely built-up areas. Many are villages or small communities...','2026-11-01 07:54:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_003','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What are ''urban'' settlements?','["Small farming villages","Built-up places with relatively high population density and many homes, businesses and services","Isolated mountain cabins","Uninhabited deserts"]',1,'Think of busy cities like Tokyo or Nairobi.','Urban settlements are built-up places with relatively high population density... Towns and cities are examples...','2026-11-01 07:54:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_004','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''suburb''?','["A deep part of the ocean","A residential or mixed-use area located within or around a city or urban area","A massive farm","A high mountain peak"]',1,'People often live here and travel into the city for work.','Suburbs are residential or mixed-use areas located within or around a city or urban area.','2026-11-01 07:54:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_005','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''hamlet''?','["A massive city","A very small settlement, often consisting of a few homes","A type of bird","A large factory"]',1,'It is smaller than a village.','Hamlet: A very small settlement, often consisting of a few homes and few or no major services.','2026-11-01 07:54:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_006','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What does ''urbanisation'' mean?','["When people move away from cities","The growth of urban populations and urban areas","When a city turns into a forest","Planting new trees"]',1,'It happens when many people move into cities.','Urbanisation: The growth of urban populations and urban areas.','2026-11-01 07:54:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_007','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is ''residential'' land used for?','["Farming crops","Factories and warehouses","Houses and apartment buildings","Parks and playgrounds"]',2,'It is the land used for people''s homes.','Residential: Houses and apartment buildings.','2026-11-01 07:54:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_008','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is ''commercial'' land used for?','["Growing food","Shops, markets, restaurants and offices","Building houses","Protecting wildlife"]',1,'It is the land used for businesses and buying things.','Commercial: Shops, markets, restaurants and offices.','2026-11-01 07:54:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_009','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''linear settlement'' pattern?','["Homes spread far apart","Homes grouped in a circle","Homes and buildings arranged along a road, river, railway or coastline","Homes built in the sky"]',2,'The houses form a long line.','Linear settlement: Homes and buildings are arranged along a road, river, railway or coastline.','2026-11-01 07:54:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_010','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''clustered settlement'' pattern?','["Homes built far away from each other","Homes grouped close together, often around a village centre or water source","Homes built only in a straight line","Homes built on top of each other"]',1,'The houses are bunched together in one spot.','Clustered settlement: Homes are grouped close together, often around a village centre, water source or crossroads.','2026-11-01 07:54:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_011','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'Why do people build settlements near rivers?','["Because they want to be cold","For access to water for drinking, farming, and transport","Because rivers have no floods","Because rivers produce oil"]',1,'Water is the most important resource for survival!','Settlements can develop near rivers... Rivers can provide water, transport routes and fertile land.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_012','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''dispersed settlement'' pattern?','["Homes arranged in a perfect line","Homes spread over a wide area, often near individual farms","Homes packed tightly into a city","Homes that move every day"]',1,'Neighbors live far apart from each other.','Dispersed settlement: Homes are spread over a wide area, often near individual farms or separate plots of land.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_013','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'Which of these is an example of a ''public service'' in a settlement?','["A private farm","A factory","A school or hospital","A family''s living room"]',2,'These are places that help the whole community.','Public services: Schools, hospitals, libraries and government buildings.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_014','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What does ''infrastructure'' mean?','["The animals living in a forest","Essential systems such as roads, water supply, electricity and drainage","A type of weather","The roofs of houses"]',1,'It is the physical network that keeps a settlement running.','Infrastructure: Essential systems such as roads, water supply, electricity and drainage.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_015','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',1,'What is a ''city''?','["A few homes in the countryside","A small farming village","A large urban settlement with many residents, varied jobs, transport networks and public services","A tent in the desert"]',2,'It is the largest type of settlement.','City: A large urban settlement with many residents, varied jobs, transport networks and public services.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_016','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why is ''flat, fertile land'' (plains) a common place for large settlements to grow?','["Because flat land causes massive floods.","Plains are useful for farming to feed the population, and the flat ground makes it much easier and cheaper to construct buildings, roads, and railways.","Because plains always have gold in the dirt.","Because flat land is too hard to walk on."]',1,'It''s much harder to build a city on a steep, rocky mountain!','Flat, fertile land: Plains can be useful for farming, building and transport because they often make construction easier.','2026-11-01 07:54:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_017','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why do growing cities often face ''traffic congestion''?','["Because nobody in the city travels.","As urbanisation brings more residents and jobs, the existing roads cannot handle the massive increase in vehicles, requiring improvements in public transport to solve the problem.","Because the roads are too wide.","Because everyone only walks in the city."]',1,'More people means more cars on the same old roads!','When many people move into cities, the process is called urbanisation... it also creates demands for housing, water, transport... Traffic congestion: Improve public transport...','2026-11-01 07:54:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_018','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'How does ''industrial land use'' usually fit into a well-planned city?','["Factories are always built right next to schools.","Heavy industries are usually separated and placed away from residential areas and schools to protect people from noise, traffic, and pollution.","Factories are built in the exact center of the city.","Industrial land is completely banned in all cities."]',1,'You don''t want a loud, smoky factory right next to your bedroom window!','Some activities need to be separated for safety or comfort. For example, a noisy industrial site may be placed away from homes and schools.','2026-11-01 07:54:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_019','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why might a settlement develop in a ''linear pattern''?','["Because the people hate their neighbors.","The homes naturally follow a specific geographic or infrastructure feature, such as being built along a single road, a railway track, or the coastline of a river/ocean.","Because it is illegal to build in a circle.","Because mountains force them to build in a square."]',1,'If the only way to travel is down a river, everyone will build their house facing the water!','Linear settlement: Homes and buildings are arranged along a road, river, railway or coastline.','2026-11-01 07:54:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_020','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why are coastal harbours historically excellent locations for large cities to develop?','["Because they have no access to water.","Harbours provide protected deep water for ships, which directly supports lucrative industries like fishing, international shipping, tourism, and global trade.","Because harbours prevent all natural disasters.","Because the salt water is good for farming."]',1,'A good harbour means ships can bring goods from all over the world!','Coasts and harbours: Coastal locations may support fishing, shipping, tourism and trade.','2026-11-01 07:54:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_021','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'What is a major environmental risk of building a settlement on a coastline?','["The town will definitely sink into the ocean.","While great for trade, coastal settlements are highly vulnerable to natural hazards like severe sea storms, coastal erosion, and rising sea levels due to climate change.","The coast provides absolutely no food.","Coastal settlements are completely immune to weather."]',1,'Being right next to the ocean is dangerous when a big storm hits!','Coasts and harbours... They can also face storms, coastal erosion and rising sea levels.','2026-11-01 07:54:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_022','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why are ''suburbs'' sometimes referred to as ''mixed-use'' areas?','["Because they have no houses.","Because while they are primarily residential (homes), they also contain necessary commercial areas (shops) and public services (schools) so residents don''t have to travel to the city center for everything.","Because they are a mix of oceans and deserts.","Because they mix farming and mining."]',1,'You live there, but you can also buy your groceries there!','Suburbs are residential or mixed-use areas... They often contain: Houses... Schools, parks and local shops... A mixture of residential and commercial land uses.','2026-11-01 07:54:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_023','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'How does the growth of a university or hospital affect a settlement?','["It forces everyone to leave the town.","These major services act as ''magnets'' that attract students, doctors, and workers, which increases the population and encourages the local economy to grow.","It makes the town smaller and quieter.","It destroys all the local houses."]',1,'A big hospital brings hundreds of new jobs to a town!','Why do settlements grow? ... Education: Schools, colleges and universities attract students and workers. Healthcare: Hospitals and medical services support a growing population.','2026-11-01 07:54:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_024','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'What does it mean for a settlement to be ''sustainable''?','["It means the settlement never changes or grows.","It means the community is planned to meet the needs of the people today (housing, jobs) while managing waste and protecting green spaces so the environment isn''t ruined for the future.","It means the settlement only uses plastic.","It means the city has no parks or trees."]',1,'It means building a city that won''t destroy itself with pollution!','A well-planned settlement tries to provide homes, jobs, services and open spaces while managing traffic, pollution and environmental risks... Sustainable settlements need safe housing, clean water, good transport... and protected green spaces.','2026-11-01 07:54:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_025','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why might a farming village naturally develop a ''dispersed settlement'' pattern?','["Because farmers do not like living in houses.","Because agricultural work requires massive amounts of open land for crops or grazing, forcing individual farmhouses to be spread far apart from each other.","Because farmers have to hide from the sun.","Because it is required by law."]',1,'If everyone owns 100 acres of farmland, their houses will be very far apart!','Dispersed settlement: Homes are spread over a wide area, often near individual farms or separate plots of land.','2026-11-01 07:54:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_026','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'How do ''dry regions'' limit the growth of settlements?','["They make the land too flat.","Settlements in deserts can only develop near a reliable water source (like an oasis or river); the strict limit on available water restricts how large the population can safely grow.","Dry regions actually encourage the largest cities on Earth.","They force people to live underwater."]',1,'You can''t build a city for a million people if you only have enough drinking water for a hundred!','Dry regions: Settlements may develop near reliable water sources, wells, rivers or oases. Water availability can limit how large they grow.','2026-11-01 07:54:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_027','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'What is ''housing shortage'' and how can city planners solve it?','["It means houses are too short; they build taller houses.","It occurs when a city''s population grows faster than homes can be built. Planners solve this by designing affordable housing and using land efficiently (like building apartment towers instead of single houses).","It means there are too many houses; they destroy them.","It means houses are invisible."]',1,'When a million people move to a city, you have to build apartments upwards to fit them all!','Challenge: Housing shortages. Possible solution: Plan affordable housing and use land efficiently.','2026-11-01 07:54:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_028','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why is ''loss of green spaces'' a problem in growing urban areas?','["Because green spaces are ugly.","As cities expand, parks and natural habitats are often paved over for buildings, which removes areas for recreation, harms local wildlife, and can make the city hotter and more polluted.","Because green spaces cause traffic jams.","Because green spaces generate electricity."]',1,'People and animals need nature, even in the middle of a concrete city!','Challenge: Loss of green spaces. Possible solution: Preserve parks, trees and natural habitats.','2026-11-01 07:54:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_029','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'Why is it incorrect to assume everyone in a ''rural'' area is a farmer?','["Because farming doesn''t exist anymore.","While rural areas have farms, modern rural communities also rely on diverse professions like healthcare, education, construction, and technology to function.","Because everyone in a rural area works in a factory.","Because rural areas are completely empty."]',1,'A village still needs doctors, teachers, and builders!','Not everyone living in a rural area is a farmer. People in rural communities work in many professions, including education, healthcare, construction and technology.','2026-11-01 07:54:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_030','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',5,'How do ''mountains'' physically influence how a settlement is built?','["People always build cities on the very highest peak.","The steep slopes make construction and transport difficult, so mountain communities often build in the lower, flatter valleys or carve flat terraces into the hillsides for homes and farming.","Mountains are completely impossible to live in.","People build their houses floating above the mountains."]',1,'You have to find the flattest spot possible when you live on a mountain!','Mountains: Mountain communities may use valleys and terraces for homes and farming. Steep slopes can make construction and transport difficult.','2026-11-01 07:54:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_031','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Critique the conceptual boundary between ''Urban'' and ''Rural'' in the context of modern globalization.','["The boundary is universally identical in every single country.","The binary is increasingly blurred and subjective; exact statistical definitions vary wildly by country, and modern infrastructure (internet, telecommuting) allows historically ''rural'' areas to participate directly in globalized ''urban'' economies.","The boundary proves that rural areas no longer exist.","Rural and urban areas are separated by physical walls."]',1,'A person living in a remote cabin might work online for a tech company in a massive city!','Exact definitions differ between countries... Not everyone living in a rural area is a farmer. People in rural communities work in many professions... technology.','2026-11-01 07:54:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_032','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Analyze the paradox of ''rivers'' as settlement locations regarding human security.','["Rivers are entirely safe and have never harmed a settlement.","Rivers present a critical paradox: they are essential for establishing early settlements (providing drinking water, irrigation, and trade routes), but this proximity simultaneously exposes the settlement to devastating existential threats from seasonal flooding.","Rivers provide no resources but are completely safe.","Rivers only flow during the winter."]',1,'The water that gives you life can also wash your house away!','Rivers and freshwater: Rivers can provide water, transport routes and fertile land. However, building too close to a river can create flood risks.','2026-11-01 07:55:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_033','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Synthesize how rapid ''urbanisation'' strains municipal ''infrastructure'' in developing nations.','["Urbanisation automatically builds new infrastructure instantly.","As massive rural-to-urban migration causes explosive population growth, the influx drastically outpaces the city''s existing infrastructure (water grids, sanitation, public transit), resulting in systemic failures, traffic gridlock, and the rise of informal, underserviced settlements (slums).","Urbanisation reduces the need for any infrastructure.","Urbanisation only affects rural farms."]',1,'If a million people move to a city meant for 100,000, the pipes and roads will break!','When many people move into cities, the process is called urbanisation. Urbanisation can bring opportunities, but it also creates demands for housing, water, transport and public services... Traffic congestion... Water shortages...','2026-11-01 07:55:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_034','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Evaluate the socio-economic implications of separating ''Industrial'' and ''Residential'' land use (zoning).','["Zoning forces everyone to live inside factories.","While separating toxic or noisy heavy industry from homes protects public health and safety (residential quality of life), aggressive strict zoning can enforce socio-economic segregation and increase urban sprawl by forcing workers into long, car-dependent commutes.","Zoning allows factories to be built inside schools.","Zoning has absolutely no effect on how a city functions."]',1,'You don''t want to live next to a chemical plant, but you also don''t want to drive two hours to get to work!','Some activities need to be separated for safety or comfort. For example, a noisy industrial site may be placed away from homes and schools... (Synthesis: Separation is good for health, but increases travel distance).','2026-11-01 07:55:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_035','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Analyze how the physical geography of a ''Clustered settlement'' traditionally provided a defensive advantage.','["Clustered settlements made it easier for enemies to attack.","Historically, grouping homes tightly together around a central node (like a hill or well) maximized the collective defensibility of the population against raiders or predators, while keeping communal agricultural lands on the exposed periphery.","Clustered settlements were built underwater to hide.","Defensive advantages were only found in dispersed settlements."]',1,'There is safety in numbers; a tight group of houses is easier to defend than houses spread miles apart!','Clustered settlement: Homes are grouped close together, often around a village centre, water source or crossroads. (Synthesis: Grouping provides mutual protection).','2026-11-01 07:55:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_036','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Synthesize the relationship between ''Suburban'' development and modern transport networks.','["Suburbs existed long before any transport was invented.","The explosive growth of suburbs is directly predicated on the advent of mass transit and personal automobiles. Without these transport networks bridging the spatial gap, the functional separation of the suburban ''residence'' from the urban ''workplace'' would be logistically impossible.","Suburbs rely entirely on people walking to work in the city.","Suburbs caused the destruction of all roads."]',1,'You can only live far away from your job in the city if you have a car or a train to get you there!','Suburbs... They often contain: ...Roads connecting people to workplaces and city centres... Some suburbs have frequent public transport, while others are designed mainly around road travel.','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_037','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Evaluate the vulnerability of ''Coastal and harbour'' settlements in the era of anthropogenic climate change.','["Coastal cities are completely immune to climate change.","Historically dominant due to maritime trade, coastal megacities now face an existential geographical crisis: thermal oceanic expansion and glacial melt (rising sea levels) threaten to permanently inundate trillions of dollars of vital port infrastructure and displace millions of urban residents.","Coastal cities will simply float on top of the rising water.","Climate change will cause coastal cities to move inland naturally."]',1,'The ocean that made the port city rich is now threatening to swallow it!','Coasts and harbours: Coastal locations may support fishing, shipping, tourism and trade. They can also face storms, coastal erosion and rising sea levels.','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_038','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Critique the concept of a ''City'' as a purely physical construct of buildings and roads.','["A city is nothing more than concrete and asphalt.","A city is fundamentally a socio-economic organism, not just a physical space. Its true defining characteristics are its dense, complex networks of human interaction, cultural exchange, economic trade, and the specialized division of labor that buildings merely facilitate.","A city is defined exclusively by having exactly one million trees.","Cities are purely natural formations caused by earthquakes."]',1,'A city is the people and the economy; empty buildings don''t make a city!','A city: A large urban settlement with many residents, varied jobs, transport networks and public services... settlements grow when they attract more residents and economic activity.','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_039','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Analyze how a ''Linear settlement'' pattern reflects human adaptation to specific geographical constraints.','["Linear settlements prove that humans hate curves.","The linear pattern is an optimal geometric adaptation to narrow, elongated geographical corridors of utility (like a habitable river valley flanked by steep mountains) or essential transport arteries (like a railway line), maximizing access to the resource while avoiding hostile terrain.","Linear settlements are only built in perfect, open plains.","Linear settlements are built randomly with no logic."]',1,'If you live in a deep, narrow mountain valley, the only way to build is in a straight line along the river!','Linear settlement: Homes and buildings are arranged along a road, river, railway or coastline.','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_040','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Synthesize the concept of ''Unequal access to services'' with the rapid, unplanned growth of urban areas.','["Unplanned growth guarantees perfect equality for all residents.","When urbanisation is rapid and informal, marginalized populations are often pushed to the urban periphery (slums). Because municipal infrastructure (schools, hospitals, clean water) cannot scale fast enough, these peripheral zones suffer severe systemic deprivation, entrenching social inequality.","Unequal access means some people get too many hospitals.","Rapid growth automatically builds new schools for everyone."]',1,'If a city grows too fast, the poorest neighborhoods usually get left without running water or schools.','Challenge: Unequal access to services. Possible solution: Improve access to schools, healthcare and essential facilities... Urbanisation can bring opportunities, but it also creates demands...','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_041','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Evaluate the statement: ''Natural features influence settlements, but they do not determine everything.''','["It means humans have no control over where they live.","This reflects environmental possibilism. While geography limits options (e.g., you need water), advanced human technology (aqueducts, air conditioning), government policies, and global economic forces can allow massive settlements to thrive in historically inhospitable biomes (like modern desert cities).","It proves that geography has absolutely zero effect on humans.","It means settlements are entirely built by natural forces."]',1,'Nature dictates the rules, but human technology can sometimes rewrite them (like building a massive city in the hot desert)!','Natural features influence settlements, but they do not determine everything. Technology, culture, government decisions and economic opportunities also matter.','2026-11-01 07:55:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_042','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Synthesize how the transition from ''Rural'' to ''Urban'' economies alters the primary sector of human labor.','["The transition forces everyone to become a farmer.","Rural settlements are historically anchored in primary sector extraction (agriculture, forestry, mining). Urbanization signifies a structural economic shift toward secondary (manufacturing) and tertiary (services, education, technology) sectors, concentrating wealth and diverse labor in dense nodes.","Urban economies rely entirely on hunting and gathering.","The transition has no effect on what jobs people do."]',1,'In a village, most people pull resources from the earth; in a city, people provide services to each other.','Rural settlements... Jobs linked to agriculture, forestry, fishing... Urban settlements... A wide range of jobs and services... factories, markets, cultural centres...','2026-11-01 07:55:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_043','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Analyze the ecological concept of ''Loss of green spaces'' as a public health issue in urban planning.','["Green spaces are only for making cities look pretty.","Beyond aesthetics, the paving of green spaces exacerbates the ''urban heat island'' effect (trapping lethal thermal energy) and removes natural air-filtration systems. Preserving green infrastructure is a critical public health mandate to mitigate respiratory disease and heatstroke in dense cities.","Losing green spaces actually cools the city down.","Green spaces cause severe pollution in urban areas."]',1,'Trees in a city aren''t just for looking at; they literally clean the air and lower the temperature!','Challenge: Loss of green spaces. Possible solution: Preserve parks, trees and natural habitats... A well-planned settlement tries to provide... open spaces while managing... environmental risks.','2026-11-01 07:55:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_044','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Critique the historical reliance on ''migration'' as the sole engine for settlement growth.','["Migration is a myth and never happens.","While in-migration (people moving for jobs/safety) rapidly expands cities, natural increase (birth rates exceeding death rates due to improved urban healthcare and sanitation) is an equally critical, internally generated demographic engine that drives exponential urban population growth.","Migration only makes cities shrink.","Settlements only grow when people stop having children."]',1,'A city grows when new people move in, AND when the people already there live longer and have families!','Why do settlements grow? ... Migration: People may move to a settlement for work, education... Healthcare: Hospitals and medical services support a growing population. (Synthesis: Better hospitals mean more babies survive, growing the city from within).','2026-11-01 07:55:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_settlements_global_045','Geography','Human Geography','Topic 12: People, Places, and Settlements','Primary',10,'Evaluate how ''transport'' infrastructure acts as the circulatory system of a modern settlement.','["Transport only moves water, not people.","Without robust, scalable transport infrastructure (roads, rail, ports), the specialized zones of a city (residential, industrial, commercial) cannot interact. If transport fails (congestion), the economic efficiency and social cohesion of the entire urban organism collapse.","Transport infrastructure is entirely optional for a city.","Transport prevents people from reaching their jobs."]',1,'If the roads are completely jammed, workers can''t reach the factories, and the city''s economy stops breathing!','Transport: Roads, ports, railways and airports connect communities... Traffic congestion: Improve public transport... Some activities need to be separated... (Synthesis: Transport is the only way to connect the separated zones).','2026-11-01 07:55:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_001','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is ''transport''?','["Growing food on a farm","The movement of people, animals or goods from one place to another","Sending a text message","Building a new house"]',1,'It means moving things around.','Transport is the movement of people, animals or goods from one place to another.','2026-11-01 07:55:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_002','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What are the four broad categories of transport?','["Walking, running, jumping, swimming","Road, rail, water and air","Cars, buses, trains, bikes","Phones, letters, emails, radios"]',1,'These cover land, sea, and sky.','There are four broad categories of transport: road, rail, water and air.','2026-11-01 07:55:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_003','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'Which type of transport includes cars, buses, bicycles, and trucks?','["Rail transport","Water transport","Road transport","Air transport"]',2,'These travel on paved streets.','Road transport: Includes cars, buses, bicycles, motorcycles and trucks.','2026-11-01 07:55:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_004','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'Which type of transport is best for carrying large quantities of goods between different continents?','["Bicycles","Cargo ships (Water transport)","Passenger aeroplanes","Local buses"]',1,'They are huge boats that cross the ocean.','Water transport: ... Ships carry large quantities of goods between countries.','2026-11-01 07:55:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_005','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'Which type of transport includes passenger trains, metros, and trams?','["Air transport","Road transport","Rail transport","Water transport"]',2,'They travel on metal tracks.','Rail transport: Includes passenger trains, freight trains, metros and trams.','2026-11-01 07:55:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_006','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What are ''pipelines'' used for?','["To carry passengers underwater","To move liquids and gases, including water, oil and natural gas","To fly airplanes","To send emails"]',1,'They are long tubes that carry liquids.','Pipelines: Move liquids and gases, including water, oil and natural gas.','2026-11-01 07:55:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_007','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is a ''transport network''?','["A single parked car","A system of connected routes and facilities that enables people and goods to move","A type of internet connection","A weather map"]',1,'It includes roads, tracks, and ports.','A transport network is a system of connected routes and facilities that enables people and goods to move.','2026-11-01 07:55:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_008','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is ''communication''?','["Building a bridge","The process of sharing information, ideas, feelings or messages with other people","Driving a truck","Trading goods for money"]',1,'Talking, writing, and emailing are examples.','Communication is the process of sharing information, ideas, feelings or messages with other people.','2026-11-01 07:55:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_009','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is an example of ''face-to-face communication''?','["Sending an email","Writing a letter","Speaking and listening to someone directly while observing their gestures","Watching television"]',2,'It happens when you are in the same room as the person.','Face-to-face communication: People speak, listen, use gestures and observe facial expressions.','2026-11-01 07:55:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_010','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is an example of ''digital communication''?','["Reading a printed book","Speaking face-to-face","Sending an email or making a video call","Listening to the radio"]',2,'It uses computers and the internet.','Digital communication: Phones, email, messaging applications and video calls...','2026-11-01 07:55:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_011','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What is ''trade''?','["Sharing a secret message","Buying, selling or exchanging goods and services","Building a new road","Riding a train"]',1,'It is how countries get things they don''t make themselves.','Trade: Buying, selling or exchanging goods and services.','2026-11-01 07:55:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_012','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'Which action is a safe way to use communication technology?','["Sharing your password with a stranger","Checking information before forwarding it to others","Sending threatening messages","Giving out your home address online"]',1,'You should make sure something is true before you share it.','Check information before forwarding it.','2026-11-01 07:55:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_013','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What does ''infrastructure'' mean in terms of transport?','["The passengers on a bus","Essential physical systems and facilities like roads, bridges, and airports","A type of digital message","The weather on a travel day"]',1,'It is the stuff built to make travel possible.','Infrastructure: Essential physical systems and facilities.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_014','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'Which of these is a way to reduce transport pollution?','["Leaving a car engine running all day","Walking or cycling for short journeys","Flying in an airplane for every trip","Driving alone in a large car"]',1,'Bikes don''t make smoke!','People and communities can reduce some impacts by: Walking or cycling for suitable short journeys.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_015','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',1,'What does ''Globalisation'' mean?','["Isolating a country from the world","Increasing connections and interdependence between places and countries","Stopping all international trade","Building walls around a city"]',1,'It means the world is becoming more connected.','Globalisation: Increasing connections and interdependence between places and countries.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_016','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why is ''road transport'' better suited for local, door-to-door deliveries than rail transport?','["Because trucks are faster than trains.","Because road networks connect directly to almost every individual home and shop, whereas trains are restricted to specific, fixed railway tracks and stations.","Because roads do not cause any pollution.","Because trains cannot carry heavy objects."]',1,'A train can''t pull up to your front door!','Road transport: ... Useful for local journeys and door-to-door deliveries. Roads connect homes, towns, farms and cities.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_017','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'If you need to send urgent, life-saving medical supplies to a distant continent, which transport mode is most suitable and why?','["Water transport, because ships can carry large quantities.","Air transport, because it connects distant places extremely quickly, which is crucial for urgent deliveries.","Rail transport, because trains never crash.","Road transport, because trucks are the cheapest."]',1,'Planes are the fastest way to cross the world!','Air transport: ... Useful for long-distance journeys and urgent deliveries. Can connect distant places quickly.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_018','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How does international ''trade'' depend on transport networks?','["Trade stops when transport is used.","Countries need ships, aircraft, trains, and trucks to physically deliver the food, machinery, and clothing they exchange across borders.","Trade only happens digitally, so physical transport is unnecessary.","Trade only happens if countries share a land border."]',1,'You can''t buy a computer from another country if a ship or plane can''t bring it to you!','Trade: Countries exchange products such as food... Ships, aircraft, trains and trucks help deliver these goods.','2026-11-01 07:55:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_019','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How does much of the world''s international internet traffic actually travel?','["It floats through the air in clouds.","It travels physically through massive undersea fibre-optic cables laid across the ocean floor.","It is only sent through paper letters.","It only travels through space satellites."]',1,'The ''wireless'' internet actually relies on giant wires under the sea!','Important: ... much international internet traffic travels through undersea fibre-optic cables.','2026-11-01 07:55:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_020','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why is it important to have diverse modes of communication (written, digital, broadcast, face-to-face)?','["Because one method will eventually break.","Because different methods are useful for different situations (e.g., broadcasting for emergency warnings to millions, face-to-face for personal nuance, and written to preserve information).","Because everyone in the world has a smartphone.","Because digital communication is the only legal way to talk."]',1,'You wouldn''t send a personal letter to warn a whole city about a flood!','Different methods are useful for different people and situations... Broadcast communication: Radio and television can share news... with large audiences.','2026-11-01 07:55:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_021','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How do modern transport and communication help with ''healthcare and emergency response''?','["They prevent emergencies from happening.","Transport quickly moves medical equipment and patients, while digital communication allows emergency services to share immediate warnings and coordinate rescue efforts.","They only help doctors talk to each other for fun.","They slow down ambulances with traffic."]',1,'If there''s an earthquake, the radio warns you, and a helicopter brings the medicine.','Healthcare and emergency response: Transport moves medicines and medical equipment. Communication helps emergency services share warnings and coordinate assistance.','2026-11-01 07:55:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_022','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'What is a significant ''disadvantage'' of global connections and digital communication?','["It makes travel completely free.","While it shares knowledge, it also exposes users to online scams, privacy risks, and the rapid spread of misinformation (fake news).","It stops people from ever seeing their families.","It guarantees that everyone will become wealthy."]',1,'The internet can spread a lie just as fast as it spreads the truth!','Challenges: ... Online scams, privacy risks and misinformation.','2026-11-01 07:55:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_023','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How does the construction of transport infrastructure (like a new highway) negatively impact the natural environment?','["It provides new homes for animals.","Building roads and railways can change landscapes, fragment (break apart) wildlife habitats, and create noise and air pollution.","It stops climate change completely.","It has absolutely no impact on nature."]',1,'A highway cuts a forest in half, making it hard for animals to cross!','However, building transport infrastructure can change landscapes, fragment wildlife habitats and affect communities.','2026-11-01 07:55:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_024','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why are ''electric vehicles'' not considered a perfect, 100% pollution-free solution for transport?','["Because they still run on petrol.","While they reduce exhaust pollution at the tailpipe, their overall environmental impact still depends on how the electricity is generated (e.g., burning coal) and the mining required for their batteries.","Because they cause more air pollution than trucks.","Because they are too slow to be useful."]',1,'If the electricity comes from a dirty coal plant, the car isn''t perfectly clean!','Electric vehicles can reduce exhaust pollution at the point of use, but their overall environmental impact also depends on electricity generation, vehicle production and battery materials.','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_025','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why is it crucial to ''keep passwords private'' and not share personal details online?','["Because it wastes internet data.","Digital communication connects you to the whole world, including strangers who might misuse your personal information for scams or harm (privacy risks).","Because your computer will turn off.","Because it makes the internet too crowded."]',1,'You wouldn''t give your house key to a stranger; don''t give them your digital keys either!','Safe and responsible communication: Keep passwords private... Do not share personal details with strangers online.','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_026','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How does ''tourism'' rely on global transport connections?','["Tourists only ever walk to their destinations.","People must use international transport networks (like aeroplanes and cruise ships) to visit different regions and experience new landscapes, food, and traditions.","Tourism prevents global connections.","Tourists only travel using underground pipelines."]',1,'You can''t visit another continent without a plane or a ship!','Tourism and cultural exchange: People visit different regions to experience landscapes... (Transport makes this possible).','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_027','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'What is ''misinformation'' in the context of digital communication?','["A message that is perfectly true and helpful.","Information that is false, inaccurate, or misleading, which can spread very quickly across global digital networks if people don''t check the facts before forwarding it.","A type of secure password.","A broken undersea cable."]',1,'It is a lie that spreads fast on the internet.','Challenges: ... misinformation... Check information before forwarding it.','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_028','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why is using ''shared public transport'' (like a bus or train) better for the environment than everyone driving their own car?','["Because buses are always electric.","A single bus or train can carry dozens or hundreds of people, which significantly reduces the total amount of fuel burned and greenhouse gases released per person compared to individual cars.","Because buses do not use roads.","Because trains are free."]',1,'One engine moving 50 people is much cleaner than 50 engines moving 50 people!','People and communities can reduce some impacts by: ... Using buses, trains and other shared transport when practical.','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_029','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'How can ''unequal access'' to transport and digital networks be a challenge?','["It guarantees everyone gets the same education.","It creates an unfair divide; people without reliable internet or transport may struggle to access online education, apply for jobs, or reach hospitals, leaving them at a disadvantage.","It means everyone has too many phones.","It solves traffic congestion."]',1,'If school is online, but you don''t have Wi-Fi, you get left behind!','Challenges: ... Unequal access to transport and digital networks... Remember that not everyone has reliable internet access or the same communication tools.','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_030','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',5,'Why are ''satellites'' especially useful for communication?','["They are the cheapest way to send a letter.","They beam signals from space, making them vital for providing communication, broadcasting, and GPS navigation to remote areas that lack ground infrastructure like cables.","They physically transport people to space.","They block the sun from causing global warming."]',1,'If you are in the middle of a desert with no wires, a satellite in space can still connect your phone!','Important: Satellites are useful for communications in remote areas, navigation and broadcasting...','2026-11-01 07:55:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_031','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Critique the assertion that ''Globalisation'' is an exclusively beneficial process for all communities.','["Globalisation provides only benefits and has eradicated all global poverty.","While globalisation expands trade, education, and knowledge sharing, it also creates severe negative externalities, such as massive greenhouse gas emissions from international shipping, the loss of unique local cultural traditions, and economic dependency on distant suppliers.","Globalisation has absolutely no economic impact on communities.","Globalisation completely stops all international trade."]',1,'Buying cheap goods from across the world is great, but it might put local workers out of a job!','Global connections can create jobs... They can also spread misinformation, increase environmental pressures and make some communities dependent on distant suppliers.','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_032','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Analyze the paradox of modern ''Road Transport'' regarding urban development.','["Roads naturally clean the air in cities.","Road transport is essential for logistical ''last-mile'' connectivity and urban economic growth, yet its expansion inherently induces demand, leading to chronic traffic congestion, localized air pollution, and the physical fracturing of urban communities.","Road transport prevents anyone from moving into cities.","Roads only benefit rural farms, not cities."]',1,'Building more roads often just leads to more traffic jams!','Road transport: ... Useful for local journeys... Heavy traffic can cause delays and air pollution... building transport infrastructure can change landscapes, fragment wildlife habitats and affect communities.','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_033','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Synthesize how the vulnerability of ''undersea fibre-optic cables'' threatens global economic stability.','["Undersea cables are indestructible and never break.","Because the vast majority of international digital communication (including global financial transactions, logistics, and data routing) relies on physical undersea cables, a localized disruption (e.g., an earthquake or sabotage) can trigger a cascading, instantaneous collapse of transnational economic and communication networks.","Undersea cables only carry television signals.","Economic stability relies entirely on satellites, not cables."]',1,'If a shark or a submarine cuts the right wire at the bottom of the ocean, the stock market could crash!','Important: ... much international internet traffic travels through undersea fibre-optic cables. (Synthesis: The global economy relies on the internet, which relies on fragile physical wires).','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_034','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Evaluate the ecological trade-offs associated with transitioning global shipping from ''Water transport'' to ''Air transport'' for speed.','["Air transport is ecologically identical to water transport.","While air transport offers exponential speed advantages for logistics, it is highly energy-intensive per metric ton of cargo, generating drastically higher carbon emissions and exacerbating climate change compared to the slower, but more fuel-efficient, bulk maritime shipping.","Water transport is actually much faster than air transport.","Air transport produces zero emissions."]',1,'Planes are fast, but they burn massive amounts of fuel compared to a slow cargo ship!','Air transport: ... Useful for long-distance journeys and urgent deliveries... Often uses more energy per passenger [or cargo] than well-used public transport... Cargo ship [is] useful for moving large amounts of goods...','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_035','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Analyze the socio-political implications of ''unequal access to digital networks'' (the digital divide).','["Unequal access ensures perfect political equality.","In a globalized society where civic participation, education, and economic opportunity are increasingly digitized, populations lacking reliable internet access suffer systemic disenfranchisement, widening the socio-economic gap between developed and developing regions.","Digital access has no bearing on education or jobs.","Unequal access forces everyone to read books."]',1,'If the whole world is talking online, and you don''t have internet, your voice isn''t heard.','Challenges: ... Unequal access to transport and digital networks... Remember that not everyone has reliable internet access... (Synthesis: If you aren''t connected, you are locked out of the modern economy).','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_036','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Synthesize how ''Digital Communication'' fundamentally alters the spatial dynamics of ''Education'' and ''Work''.','["It forces everyone to physically commute to the same building.","Digital communication (video calls, cloud networks) effectively decouples physical location from collaborative participation, allowing synchronous remote education and globalized telecommuting, thereby rendering geographic proximity irrelevant for many information-sector activities.","It makes education completely impossible.","It only allows people to communicate via written letters."]',1,'You can live in a village in Africa and take a live university class in Europe!','Education: Students can learn from online lessons, digital libraries and teachers in other locations... Digital communication: ...allow people to exchange information over long distances.','2026-11-01 07:55:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_037','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Critique the environmental sustainability of relying exclusively on ''Electric Vehicles'' (EVs) to solve transport emissions.','["EVs will instantly and permanently solve all climate change problems.","While EVs eliminate tailpipe emissions, labeling them purely ''sustainable'' ignores the massive upstream environmental costs: the carbon-intensive generation of the electrical grid powering them, and the destructive mining required for their lithium-ion batteries.","EVs actually produce more tailpipe emissions than petrol cars.","EVs run on water and require no batteries."]',1,'A clean car powered by a dirty coal plant is still dirty!','Electric vehicles can reduce exhaust pollution at the point of use, but their overall environmental impact also depends on electricity generation, vehicle production and battery materials.','2026-11-01 07:55:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_038','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Analyze the statement ''Communication can also use sign languages, symbols, pictures, maps and visual signals'' in the context of global inclusivity.','["It proves that spoken language is the only valid communication.","This acknowledges that human communication transcends spoken/written linguistics. Visual and symbolic systems provide crucial accessibility for the deaf community and create a universal, cross-cultural medium that bypasses language barriers in a globalized world (e.g., airport symbols).","It means pictures are superior to digital communication.","It means everyone must learn to draw maps."]',1,'A picture of a bathroom or an exit sign is understood in any country, no matter what language they speak!','Communication can also use sign languages, symbols, pictures, maps and visual signals. Different methods are useful for different people and situations.','2026-11-01 07:55:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_039','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Evaluate the role of ''Broadcast communication'' (Radio/TV) during a widespread natural disaster compared to ''Digital communication'' (Internet).','["Broadcast communication is useless because nobody owns a radio.","During a disaster, fragile digital networks (internet/cellular) often fail due to power loss or infrastructure damage. Broadcast communication is far more resilient and unilateral, capable of transmitting vital emergency warnings to massive, isolated populations simultaneously using basic receivers.","Digital communication never fails during a storm.","Broadcast communication can only send text messages."]',1,'When the internet towers blow down in a hurricane, the radio still works!','Broadcast communication: Radio and television can share news, educational programmes and emergency announcements with large audiences.','2026-11-01 07:55:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_040','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Synthesize how the concept of ''Globalisation'' forces a localized community to balance economic opportunity with cultural preservation.','["Globalisation forces communities to completely abandon all traditions immediately.","Globalisation integrates a local community into lucrative international trade and digital networks, offering economic uplift. However, the influx of globalized media, foreign products, and standardized corporate culture threatens to erode and homogenize unique, indigenous traditions and languages.","Globalisation completely isolates a community from the rest of the world.","Globalisation ensures that local traditions become the only global culture."]',1,'You get to sell your local goods to the whole world, but the whole world''s culture floods into your town!','Global connections can create jobs, spread knowledge and make products available... They can also... [cause] Loss of some local traditions or unfair economic effects.','2026-11-01 07:55:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_041','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Analyze the specific vulnerabilities introduced by ''Online scams, privacy risks and misinformation'' in a highly connected society.','["They make the internet completely safe for everyone.","As societal infrastructure digitizes, malicious actors can exploit the speed and anonymity of global networks. This threatens personal financial ruin (scams), systemic identity theft (privacy), and the rapid destabilization of democratic institutions via weaponized, algorithmic misinformation.","They only affect people who do not own computers.","They prevent people from ever sending emails."]',1,'A lie can travel halfway around the world online before the truth even wakes up!','Challenges: ... Online scams, privacy risks and misinformation... Check information before forwarding it. Respect other people''s privacy...','2026-11-01 07:55:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_042','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Critique the reliance on ''Pipelines'' for transport from an environmental risk perspective.','["Pipelines are completely risk-free and never break.","While highly efficient for continuous bulk transport of fluids (oil/gas), pipelines traverse vast, often remote ecological zones. A structural failure or rupture results in localized, catastrophic environmental contamination (spills) that are notoriously difficult to contain and remediate.","Pipelines only transport fresh, clean drinking water.","Pipelines are the primary cause of traffic congestion in cities."]',1,'An oil pipeline is efficient, but if it leaks in a forest, it creates an ecological disaster!','Pipelines: Move liquids and gases, including water, oil and natural gas... (Synthesis: Moving oil across land involves the risk of spills).','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_043','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Synthesize the relationship between ''Transport networks'' and ''Urbanisation''.','["Transport networks prevent urbanisation entirely.","Robust transport networks (railways, highways) act as the physical conduits that funnel rural populations into urban centers. Once urbanized, the high population density necessitates complex intra-city public transit (metros), creating a reciprocal loop where transport fuels urban growth, and urban growth demands more transport.","Urbanisation happens without any transport networks.","Transport networks only exist in the countryside."]',1,'Trains and roads bring people to the city, and then the city needs more trains and roads to handle all the new people!','Transport networks connect rural communities to towns and cities... Urbanisation can bring opportunities, but it also creates demands for housing, water, transport...','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_044','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Analyze the statement: ''No single mode is best for every situation.'' How does this dictate intermodal logistics?','["It means humans should only ever walk.","It necessitates ''intermodal'' systems (using multiple transport types). A cargo container might cross an ocean efficiently on a slow ship, travel inland rapidly on a train, and complete the ''last mile'' delivery flexibly on a truck, maximizing the specific economic and geographic advantages of each mode.","It implies that airplanes are the only valid form of transport.","It forces companies to only use bicycles for global trade."]',1,'To get a package from China to your front door in America, you need a ship, a train, and a truck!','No single mode is best for every situation. For example, a cargo ship is useful for moving large amounts of goods, while an aeroplane is more suitable when speed is especially important.','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_transport_global_045','Geography','Human Geography','Topic 13: Transport, Communication, and Global Connections','Primary',10,'Evaluate the ethical responsibility of a digital citizen when engaging with ''misinformation''.','["Citizens should forward all information immediately to increase web traffic.","Because digital algorithms rapidly amplify shared content, citizens bear the ethical burden of verifying the veracity and source of information *before* dissemination. Failing to do so makes the user complicit in the global proliferation of harmful, destabilizing falsehoods.","Citizens have no responsibility for what they share online.","Misinformation is actually beneficial for education."]',1,'You are responsible for making sure you aren''t helping to spread a lie!','Safe and responsible communication: ... Check information before forwarding it. Respect other people''s privacy and opinions.','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_001','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is the ''environment''?','["Only the weather outside","Everything around us that affects living things, including natural and human-made features","Only the animals in a forest","Only the oceans and rivers"]',1,'It is everything in the world around you.','The environment is everything around us that affects living things. It includes natural features... as well as human-made features...','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_002','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'Which of these is a ''natural environment'' feature?','["A road","A factory","A mountain","A bridge"]',2,'It was made by nature, not by people.','Natural environment: Includes air, water, land, rocks, mountains, rivers, oceans, forests...','2026-11-01 07:55:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_003','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'Which of these is a ''human-made environment'' feature?','["A river","A building","A forest","A rock"]',1,'It was built by people.','Human-made environment: Includes buildings, roads, dams, farms, bridges, factories and parks...','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_004','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What does ''biotic'' mean?','["Non-living things like rocks","Living things like plants and animals","Things made of plastic","Things that fly"]',1,'Bio- means life.','Biotic components are living things, such as plants, animals, fungi and microorganisms.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_005','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What does ''abiotic'' mean?','["Living things","Non-living parts of the environment like sunlight, water, and soil","Animals that eat meat","Plants that grow in the ocean"]',1,'A-biotic means not living.','Abiotic components are non-living parts of the environment, such as sunlight, air, water, soil, rocks and temperature.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_006','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is an ''ecosystem''?','["A large city","Living organisms interacting with one another and with their non-living surroundings","A type of weather","A machine that cleans water"]',1,'A forest or a pond is an ecosystem.','An ecosystem consists of living organisms interacting with one another and with their non-living surroundings.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_007','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'In a food chain, what is a ''producer''?','["An animal that eats other animals","A green plant that makes its own food using sunlight","A mushroom that eats dead things","A human being"]',1,'Grass is a producer.','Producers: Usually green plants and algae that make their own food using sunlight.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_008','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What does a ''decomposer'' do?','["Hunts large animals","Breaks down dead material and recycles nutrients","Makes its own food using sunlight","Pollutes the water"]',1,'They are nature''s garbage collectors.','Decomposers: Organisms such as fungi and bacteria that break down dead material and recycle nutrients.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_009','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is ''air pollution''?','["Planting new trees","Harmful substances like vehicle exhaust and smoke entering the air","Rain falling from clouds","Birds flying in the sky"]',1,'It makes the air dirty and hard to breathe.','Air pollution: Sources include vehicle exhaust, industrial emissions, burning fuels and fires.','2026-11-01 07:55:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_010','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is ''noise pollution''?','["Loud music that makes people happy","Excessive noise from traffic or machinery that disturbs sleep and wildlife","The sound of rain falling","The sound of birds singing"]',1,'Too much loud noise is actually a type of pollution!','Noise pollution: Excessive noise from traffic, machinery, construction or loudspeakers can disturb sleep...','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_011','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is the first ''R'' in the 5 Rs of waste management?','["Recycle","Refuse (say no to unnecessary items)","Repair","Reuse"]',1,'The easiest way to stop waste is to not buy it in the first place!','The 5 Rs... 1. Refuse: Say no to unnecessary items...','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_012','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What does ''recycle'' mean?','["Throwing waste in the river","Separating materials like paper and glass to be processed into new products","Burying rubbish underground","Burning plastic"]',1,'Turning an old bottle into a new bottle is recycling.','Recycle: Separate materials such as paper, glass, metals... for processing into new products...','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_013','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is ''composting''?','["Burning food waste","Breaking down organic waste like food scraps and leaves into a material that improves soil","Throwing batteries in the bin","Freezing food so it doesn''t go bad"]',1,'It turns old apple cores into healthy dirt!','Composting organic waste: Food scraps, fallen leaves... Microorganisms break them down into a material that can improve soil.','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_014','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What causes ''global warming''?','["Planting too many trees","Human activities increasing greenhouse gases, which trap heat in the atmosphere","The Earth moving closer to the sun","Using too much solar power"]',1,'Burning fossil fuels acts like a giant blanket trapping heat.','Human activities are increasing the amount of certain greenhouse gases... This strengthens the greenhouse effect and causes global warming.','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_015','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',1,'What is ''sustainability''?','["Using up all natural resources immediately","Meeting people''s needs today while protecting the ability of future generations to meet theirs","Never using any natural resources","Throwing all waste into the ocean"]',1,'It means leaving enough for tomorrow!','Sustainable development aims to meet people''s needs today while protecting the ability of future generations to meet their own needs.','2026-11-01 07:55:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_016','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is ''soil'' considered both an abiotic and a biotic environment?','["Because it is made entirely of water.","Soil contains abiotic (non-living) minerals, air, and water, but healthy soil is also packed with biotic (living) organisms and decomposing matter.","Because soil only exists on other planets.","Because soil is made of plastic."]',1,'Dirt isn''t just ground-up rocks; it''s full of tiny living things!','Healthy soil contains mineral particles, organic matter, air, water (abiotic) and living organisms (biotic).','2026-11-01 07:55:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_017','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How does a polluted pond affect the entire ecosystem, not just the fish?','["It only makes the water look a different color.","If the fish die, birds lose their food source, the water becomes unsafe for animals to drink, and humans lose a resource, showing how all parts are connected.","Pollution only affects the specific fish that touch it.","Pollution actually makes the pond healthier."]',1,'In a food web, poisoning one link poisons the whole chain!','When one part of an ecosystem changes, other parts can be affected. For example, if a pond becomes polluted, fish may die, birds may lose a food source and people may lose access to safe water.','2026-11-01 07:55:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_018','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is ''light pollution'' harmful to the environment?','["Because it makes it too easy to see at night.","Excessive artificial light at night disrupts the natural sleep patterns of humans, confuses nocturnal wildlife, and makes it impossible to see the stars.","Because it creates freezing temperatures.","Because light pollution is actually a type of water pollution."]',1,'Baby sea turtles can get confused by streetlights and walk away from the ocean!','Light pollution: Excessive artificial light at night can disturb wildlife, affect sleep and make stars harder to see.','2026-11-01 07:55:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_019','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How does the principle of ''Reduce'' prevent waste more effectively than ''Recycle''?','["Reducing uses more energy than recycling.","Recycling still requires energy and factories to process old materials; ''reducing'' means buying less packaging in the first place, preventing the waste from ever existing.","Reducing means throwing things in the river.","Recycling magically makes waste disappear with no energy."]',1,'The best garbage is the garbage you never create!','Remember: Reducing and reusing waste often prevents waste from being created in the first place. Recycling is valuable, but it still requires energy and suitable facilities.','2026-11-01 07:55:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_020','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is it important to know that ''not every material belongs in a compost bin''?','["Because compost bins are only for plastic.","Organic materials like food scraps break down safely, but items like plastics, batteries, or chemicals will poison the soil and must be disposed of properly.","Because compost bins are too small.","Because organic waste never breaks down."]',1,'You can''t turn a battery into healthy dirt!','However, not every material belongs in a compost bin. Plastics, batteries, electronic waste and hazardous chemicals need appropriate collection and disposal.','2026-11-01 07:55:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_021','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How does ''deforestation'' directly contribute to global warming?','["Cutting down trees releases ice into the air.","Trees naturally absorb and store carbon dioxide. Cutting them down reduces this carbon storage, and burning the wood releases massive amounts of greenhouse gases back into the air.","Cutting down trees cools the planet by creating shade.","Trees produce greenhouse gases, so cutting them stops global warming."]',1,'Forests act like the Earth''s lungs; removing them leaves more carbon dioxide in the air!','Major sources [of greenhouse gases] include: ... Cutting down forests, which reduces the amount of carbon stored in trees and soils.','2026-11-01 07:55:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_022','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'What is the difference between climate ''mitigation'' and ''adaptation''?','["They are the exact same thing.","Mitigation means stopping the cause (like reducing emissions to stop the planet from warming). Adaptation means preparing for the effects (like building a higher sea wall to block floods).","Mitigation only applies to animals, adaptation applies to humans.","Mitigation means moving to a new planet."]',1,'Mitigation is turning off the leaking tap; adaptation is buying a mop!','Mitigation means reducing the causes of climate change... Adaptation means preparing for its effects...','2026-11-01 07:55:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_023','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why are ''greenhouse gases'' like a blanket around the Earth?','["They are made of wool and cotton.","They allow sunlight to enter the atmosphere but trap the returning heat inside, keeping the planet warm; too many gases trap too much heat, causing global warming.","They block all sunlight, freezing the Earth.","They pull the Earth closer to the sun."]',1,'A thin blanket keeps you comfortable, but 10 thick blankets make you sweat!','The Earth''s atmosphere contains gases that help keep the planet warm enough for life. This natural process is called the greenhouse effect. Human activities are increasing... [these] gases... [causing] global warming.','2026-11-01 07:55:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_024','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How does ''overexploitation'' (like overfishing) threaten biodiversity?','["It makes the fish grow bigger.","Harvesting plants or animals much faster than their populations can naturally reproduce leads to population collapse and potential extinction.","It prevents animals from swimming.","It increases the number of species in the area."]',1,'If you take 100 fish but only 10 babies are born, soon there will be zero fish!','Overexploitation: Plants and animals are harvested faster than populations can recover.','2026-11-01 07:55:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_025','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is ''Sustainability'' described as balancing Environmental, Social, and Economic well-being?','["Because protecting the environment means everyone must be poor.","True sustainability requires protecting nature (environmental) while still ensuring people have jobs (economic) and access to health, education, and fairness (social).","Because only the economy matters.","Because social well-being requires destroying forests."]',1,'You can''t save the forest by forcing the people living next to it to starve; you have to find a balance!','It involves balancing three connected areas: Environmental protection... Social well-being... Economic well-being...','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_026','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How can ''walking or cycling for short journeys'' help the environment?','["It creates more noise pollution.","It replaces the need to drive a car, which directly reduces the burning of fossil fuels, lowering both localized air pollution and global greenhouse gas emissions.","It destroys the roads.","It uses more water."]',1,'Bicycles don''t have exhaust pipes!','People and communities can reduce some impacts by: Walking or cycling for suitable short journeys.','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_027','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is protecting a whole ''habitat'' usually better than trying to save just one specific animal species?','["Because habitats are easier to move.","A habitat supports an entire interconnected web of life. Protecting the habitat saves the target animal, its food sources, and countless other species simultaneously.","Because animals do not need habitats.","Because single species are impossible to find."]',1,'You can''t save the monkeys if you cut down the jungle they live in!','Protecting habitats is often more effective than trying to protect one species while leaving its environment damaged.','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_028','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'How can ''changing rainfall patterns'' caused by climate change affect communities?','["It guarantees that every place will have perfect weather.","It causes severe, unpredictable extremes: some places suffer devastating droughts and water shortages, while others face catastrophic flooding from unusually heavy rain.","It stops all rain from falling ever again.","It makes the ocean turn into fresh water."]',1,'Global warming doesn''t just mean heat; it means the weather gets extreme and unpredictable!','Changes in rainfall and water supply: Some places face more severe drought, while others experience heavier rainfall and flooding.','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_029','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is ''repairing'' an item considered better for the environment than throwing it away and buying a new one?','["Because repaired items are always brand new.","Repairing keeps the item out of the landfill (reducing waste) and prevents the need to extract new natural resources to manufacture a replacement product.","Because buying new things is illegal.","Because throwing things away creates clean energy."]',1,'Fixing a hole in a shirt saves the water and energy needed to make a brand new shirt!','The 5 Rs... 4. Repair: Fix suitable broken items instead of immediately replacing them.','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_030','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',5,'Why is ''saving energy'' at home (like turning off lights) linked to protecting the environment?','["Because lights scare away animals.","Most electricity is still generated by burning fossil fuels (coal, gas). Using less electricity means less fuel is burned, reducing air pollution and greenhouse gas emissions.","Because lights create water pollution.","Because the sun will run out of energy."]',1,'Unless you have solar panels, leaving the TV on means burning more coal!','Use energy efficiently: Switch off unused lights and devices... Major sources [of greenhouse gases] include: Burning coal, oil and natural gas for electricity...','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_031','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Critique the assertion that ''human-made environments'' are completely separate from ''natural environments''.','["Human-made environments exist in a separate dimension.","The assertion represents a false dichotomy. Human-made environments (cities) are entirely constructed from natural resources (stone, wood, metal) and are fundamentally dependent on natural ecosystem services (clean air, watershed supply) to function.","Human-made environments do not use any natural resources.","Natural environments are completely immune to human actions."]',1,'A concrete city is just processed rock; it is still part of the Earth''s environment!','Human-made environment... Human-made places often contain natural features too... People also change the environment by building... These activities can improve lives, but they can also damage ecosystems...','2026-11-01 07:55:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_032','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Analyze the systemic ecological consequences of introducing an ''Invasive Species'' to a localized habitat.','["Invasive species always peacefully coexist with native plants.","Lacking natural predators in the new environment, an invasive species can rapidly multiply, violently outcompeting native species for finite resources, disrupting evolutionary food webs, and potentially driving localized native populations to extinction.","Invasive species instantly die in new environments.","Invasive species only affect human cities, not nature."]',1,'If you bring a fast-breeding snake to an island of ground-nesting birds, the birds will be wiped out!','Invasive species: Species introduced to a new area can sometimes spread and harm native species.','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_033','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Synthesize how ''Climate Change'' acts as a threat multiplier for ''Food Security''.','["Climate change ensures crops will grow faster everywhere.","By altering foundational abiotic factors (temperature spikes, erratic rainfall, severe droughts), climate change directly degrades global agricultural yields and destabilizes marine fisheries, threatening the baseline food supply for human populations.","Climate change only affects wild animals, not human farms.","Climate change prevents floods from destroying crops."]',1,'Farmers rely on predictable weather; if the rain stops or floods the fields, there is no harvest!','Changes in rainfall... Some places face more severe drought... Risks to communities: Heat, floods, fires... can affect homes, crops... (Synthesis: If the weather changes, the crops fail).','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_034','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Evaluate the complex sustainability trade-offs involved in transitioning to ''Electric Vehicles'' (EVs).','["EVs have absolutely zero environmental impact from creation to destruction.","While EVs critically mitigate localized urban air pollution and tailpipe greenhouse emissions (mitigation), manufacturing their high-capacity batteries requires intensive, often ecologically destructive mining of non-renewable rare earth metals, highlighting a complex sustainability trade-off.","EVs actually produce more tailpipe smoke than diesel trucks.","EVs run entirely on water and require no batteries."]',1,'A ''green'' car still requires digging giant mines for lithium and copper!','Electric vehicles can reduce exhaust pollution at the point of use, but their overall environmental impact also depends on electricity generation, vehicle production and battery materials.','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_035','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Analyze the distinction between ''Ozone-layer depletion'' and ''Climate change / Global warming''.','["They are two names for the exact same scientific process.","They are distinct phenomena; ozone depletion is caused by specific chemicals (CFCs) destroying the stratospheric UV shield, while global warming is caused by greenhouse gases (CO2, methane) trapping infrared thermal radiation in the lower atmosphere.","Ozone depletion causes the Earth to freeze.","Climate change creates the ozone layer."]',1,'The ozone hole lets in burning UV rays, but global warming acts like a blanket trapping heat!','Climate change is different from ozone-layer depletion. They are separate environmental problems with different causes, although some human activities can contribute to both.','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_036','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Synthesize how the principle of ''Economic well-being'' must integrate with ''Environmental protection'' to achieve true Sustainability.','["Economic well-being requires the total destruction of the environment.","A macroeconomic model that perpetually extracts resources faster than they regenerate guarantees eventual economic collapse. True sustainability requires a ''circular economy'' where economic growth is decoupled from environmental degradation through efficiency, renewables, and recycling.","Environmental protection forbids humans from having jobs or money.","Sustainability means only focusing on saving trees, ignoring humans."]',1,'You can''t have a healthy economy if you run out of all the resources needed to build things!','Sustainable development aims to meet people''s needs today while protecting the ability of future generations... It involves balancing three connected areas: Environmental protection... Social well-being... Economic well-being...','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_037','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Critique the effectiveness of ''Recycling'' as the primary strategy for managing municipal solid waste.','["Recycling perfectly eliminates all global waste without energy.","While recycling prevents raw material extraction, it is the least efficient of the ''Rs''. It requires immense logistical energy (collection, melting, remanufacturing) and suffers from material degradation (downcycling). The primary, most effective strategy must be source ''Reduction'' (refusing to create waste initially).","Recycling actually creates more raw waste than it destroys.","Recycling is completely illegal in most countries."]',1,'It is much better to just use a washable cup than to recycle a thousand plastic ones!','Remember: Reducing and reusing waste often prevents waste from being created in the first place. Recycling is valuable, but it still requires energy and suitable facilities.','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_038','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Evaluate the cascading effects of ''Agricultural runoff'' (fertilizers) acting as ''Water Pollution'' in a marine ecosystem.','["Fertilizers make the ocean water perfectly clean.","Excess agricultural fertilizers wash into rivers and oceans, causing massive, unnatural algal blooms (eutrophication). When this algae dies, decomposers consume the water''s oxygen to break it down, creating hypoxic ''dead zones'' that suffocate marine life.","Fertilizers turn the ocean into fresh drinking water.","Fertilizers have absolutely no effect on water or algae."]',1,'Too much plant food in the water makes the algae grow out of control and steal all the oxygen from the fish!','Water pollution: Sewage, chemicals... can contaminate rivers, lakes and oceans. Pollution can harm aquatic organisms... (Synthesis: Farm chemicals are a major unseen pollutant).','2026-11-01 07:55:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_039','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Synthesize how ''Biodiversity'' acts as an ecological insurance policy against environmental shocks.','["Biodiversity makes ecosystems weaker and easier to destroy.","High biodiversity provides functional redundancy within an ecosystem. If a disease or climate shift eradicates one species, a highly diverse ecosystem will likely contain other species capable of fulfilling that ecological niche (e.g., another pollinator), preventing total systemic collapse.","Biodiversity means every animal is exactly identical.","Biodiversity forces ecosystems to collapse instantly."]',1,'If you only have one type of bee, and a disease kills it, you have no food. If you have 50 types of bees, some will survive!','Biodiversity is important because it helps ecosystems function... and diverse ecosystems can be more resilient to some disturbances.','2026-11-01 07:55:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_040','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Analyze the socio-economic dimension of ''Climate Change Adaptation'' regarding global inequality.','["Adaptation is equally easy and cheap for every country.","Adaptation requires massive capital investment (e.g., building seawalls, relocating cities, engineering drought-resistant crops). Consequently, wealthy nations can adapt effectively, while developing nations—who historically contributed the least to emissions—suffer the most devastating, unmitigated impacts.","Adaptation means ignoring climate change completely.","Only wealthy countries will be affected by climate change."]',1,'A rich city can afford a billion-dollar flood wall; a poor farming village cannot!','Social well-being: Support health, education, safety, fairness... Adaptation means preparing for its effects, such as improving flood protection... (Synthesis: Not everyone can afford to adapt).','2026-11-01 07:55:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_041','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Evaluate the ethical implications of ''Overexploitation'' (like overfishing or excessive logging) in the context of intergenerational equity.','["Overexploitation is ethically required to maximize current profits.","Overexploitation prioritizes immediate, short-term economic extraction at the direct expense of the resource''s regenerative capacity, functionally stealing the natural capital and future economic livelihood from subsequent generations.","Overexploitation actually helps resources regenerate faster.","Overexploitation proves that future generations will not need resources."]',1,'Taking all the fish today means your grandchildren will have no fish to eat or sell!','Overexploitation: Plants and animals are harvested faster than populations can recover... Sustainable development aims to meet people''s needs today while protecting the ability of future generations to meet their own needs.','2026-11-01 07:55:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_042','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Synthesize how ''Soil Pollution'' poses a direct threat to human systemic health.','["Soil pollution only affects worms and insects.","Contaminants (heavy metals, pesticides) in the soil bioaccumulate in agricultural crops. When humans consume these crops, the concentrated toxins enter the human food chain, causing severe, systemic, long-term health crises.","Soil pollution instantly purifies water.","Polluted soil magically cleans itself overnight."]',1,'If the dirt is toxic, the carrot is toxic, and the person who eats the carrot gets sick!','Land and soil pollution: ...hazardous waste and excessive use of some chemicals can contaminate soil and harm plants, animals and people.','2026-11-01 07:55:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_043','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Critique the reliance on ''individual actions'' (like turning off lights) as the sole solution to global climate change.','["Individual actions are mathematically sufficient to stop climate change instantly.","While individual actions build a culture of conservation, the vast majority of global emissions originate from systemic industrial, agricultural, and energy sectors. Solving the crisis requires massive, top-down governmental policy shifts and corporate regulation, not just personal footprint reduction.","Individual actions actually cause more pollution.","Climate change cannot be solved by humans at all."]',1,'Turning off your bedroom light is good, but shutting down a coal power plant is what actually fixes the problem!','Protecting the environment is a shared responsibility. Small actions become more effective when supported by good public services, responsible businesses and sound environmental policies... Governments, industries... need to make larger changes...','2026-11-01 07:55:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_044','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Analyze the relationship between ''Deforestation'' and ''Zoonotic Diseases'' (diseases jumping from animals to humans).','["Deforestation prevents all diseases from spreading.","As humans aggressively clear forests for agriculture or urban expansion, they destroy the buffer zones between wild habitats and human settlements. This forces stressed, displaced wildlife into close contact with humans and livestock, drastically increasing the transmission of novel zoonotic viruses.","Deforestation makes humans completely immune to diseases.","Animals never carry diseases."]',1,'When you cut down the bat''s forest, the bat moves into the barn with the pigs, and new diseases spread!','Habitat loss: Forests... are cleared or fragmented... Human activities can improve lives, but they can also damage ecosystems... (Synthesis: Destroying habitats brings wild nature dangerously close to human cities).','2026-11-01 07:55:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_environment_global_045','Geography','Physical Geography','Topic 14: Our Environment and Sustainability','Primary',10,'Evaluate the importance of ''Decomposers'' in maintaining the thermodynamic efficiency of an ecosystem.','["Decomposers trap all energy forever, killing the ecosystem.","Decomposers (fungi/bacteria) are the vital recycling engine of the biosphere. They dismantle complex organic compounds from dead matter, releasing trapped, essential elemental nutrients (nitrogen, phosphorus) back into the soil to be reabsorbed by producers, closing the biochemical loop.","Decomposers only create sunlight for plants.","Decomposers are actually producers that make their own food."]',1,'Without decomposers, the world would be buried miles deep in dead trees and nothing new could grow!','Decomposers: Organisms such as fungi and bacteria that break down dead material and recycle nutrients... returning nutrients to the soil.','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_001','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is a ''place'' in geography?','["A type of weather","A particular location on Earth","An imaginary line","A moving vehicle"]',1,'It can be a natural feature, a building, a neighborhood, or a city.','A place is a particular location on Earth.','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_002','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'Which of these is an example of a ''physical feature''?','["A mountain","A road","A school","A bridge"]',0,'It is made by nature.','Physical features: Features of the natural environment, such as mountains, rivers, lakes...','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_003','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'Which of these is an example of a ''human feature''?','["A river","A forest","A house","A desert"]',2,'It is built by people.','Human features: Features created or changed by people, such as houses, roads, farms...','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_004','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is a ''country''?','["A small neighborhood","A territory with a defined geographical area and a system of government","A type of mountain range","An area that has no borders"]',1,'Japan, Kenya, and Canada are examples.','A country is a territory with a defined geographical area and a system of government.','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_005','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is a ''region''?','["An area grouped together because it shares one or more characteristics","A single building","A moving body of water","A type of map"]',0,'For example, the Sahara is a physical region.','A region is an area grouped together because it shares one or more characteristics.','2026-11-01 07:55:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_006','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is a ''boundary''?','["A line or limit that separates one area from another","A deep hole in the ground","A tall building","A type of weather pattern"]',0,'It can be a natural river or an invisible political line.','A boundary is a line or limit that separates one area from another.','2026-11-01 07:55:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_007','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'Which of these is a ''natural boundary''?','["A straight line drawn on a map","A brick wall","A river or mountain ridge","A highway"]',2,'Nature created the dividing line.','Natural boundaries: A river, mountain ridge or coastline may separate areas.','2026-11-01 07:55:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_008','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What does ''fieldwork'' mean in geography?','["Reading a fictional story","Gathering geographical information through direct observations and other methods","Guessing where a place is","Drawing imaginary maps"]',1,'It means going outside to study the real world.','Fieldwork: Gathering geographical information through observations and other methods.','2026-11-01 07:55:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_009','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What does a ''political map'' show?','["Only mountains and rivers","Countries, administrative boundaries, and cities","Only rainfall and temperature","Only satellite photographs"]',1,'It shows the borders created by humans.','Political maps show countries and administrative boundaries.','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_010','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What does a ''physical map'' show?','["Only roads and highways","Natural features such as mountains, rivers, and plains","Population numbers","Administrative districts"]',1,'It shows what the natural ground looks like.','Physical maps show features such as mountains, rivers and plains.','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_011','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What can a ''satellite image'' help geographers see?','["The history of a country","Patterns of land cover and development from high above the Earth","The exact population number","The names of every person in a town"]',1,'It is a picture taken from space.','Satellite images show patterns of land cover and development from above.','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_012','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is an ''administrative division''?','["A natural forest","An area used for governing or organising public services (like a state or province)","A type of mountain","A deep ocean"]',1,'It helps the government manage a large area.','Administrative region: An area used for governing or organising public services, such as a province, state, district...','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_013','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What does ''population'' mean?','["The number of trees in an area","The people living in a particular area","The number of roads in a city","The types of animals in a forest"]',1,'It refers to humans.','Population: The people living in a particular area.','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_014','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'Why should you check the ''legend'' on a map?','["It tells you the exact time.","It is a guide explaining the symbols and colours used on the map.","It shows you the weather forecast.","It proves the map is correct."]',1,'It helps you read the map.','Map legend: A guide explaining the symbols and colours used on a map.','2026-11-01 07:55:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_015','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',1,'What is a ''cultural region''?','["An area with the exact same weather every day","An area where people may share languages, traditions, or cultural practices","An area with no people","An area that only has factories"]',1,'It is grouped by how the people live.','Cultural region: An area where people may share some languages, traditions, historical experiences...','2026-11-01 07:55:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_016','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why do geographers say a place often contains BOTH physical and human features?','["Because people cannot build things in nature.","Because almost all locations include natural elements (like the ground or a river) alongside things built by people (like houses or bridges).","Because all places are exactly the same.","Because nature quickly destroys all human buildings."]',1,'Even a busy city sits on natural dirt and rocks!','A place often contains both types of features. A coastal town, for example, may have a natural beach and harbour alongside houses, shops and roads.','2026-11-01 07:55:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_017','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How does a ''region'' differ from a ''country''?','["A region is always bigger than a country.","A country has a defined government and recognized borders, whereas a region is just an area grouped by shared characteristics (like a desert or a farming zone) and does not need its own government.","A region only has animals, a country only has humans.","They are exactly the same thing."]',1,'The Sahara desert is a region that crosses the borders of many different countries!','A country is a territory with... a system of government... A region is an area grouped together because it shares one or more characteristics... A region does not always have its own government...','2026-11-01 07:55:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_018','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why is it incorrect to assume that everyone in a single country lives the exact same way?','["Because countries only last for one year.","Because countries can be very large and contain wildly different landscapes, climates, and communities, meaning life varies greatly from one region to another.","Because people never leave their houses.","Because every country has exactly one type of landscape."]',1,'People living in the snowy mountains of Canada live very differently than people in a busy Canadian city!','Countries differ in their languages, cultures, landscapes... However, no country has only one kind of landscape or one way of life. Conditions can vary greatly from one region to another...','2026-11-01 07:55:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_019','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How do ''administrative divisions'' (like states, provinces, or districts) help a country function?','["They prevent people from traveling.","They break a large country into smaller, manageable pieces to help organize schools, healthcare, road maintenance, and local government services efficiently.","They force everyone to speak different languages.","They erase the borders of the country."]',1,'It is much easier for a local mayor to fix a pothole than for the national president to do it!','These divisions help organise schools, healthcare, transport, waste collection, roads, emergency services and other public responsibilities.','2026-11-01 07:55:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_020','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why might a political boundary NOT follow a natural feature like a river?','["Because rivers change direction every day.","Because some political boundaries were drawn as straight lines across a map by governments or treaties, rather than following the physical geography of the land.","Because boundaries are only drawn underwater.","Because it is illegal to use a river as a boundary."]',1,'Sometimes politicians just drew a straight line on a piece of paper with a ruler!','A political boundary does not always follow a natural feature. Some boundaries are straight lines drawn across land, while others follow rivers or mountain ranges.','2026-11-01 07:55:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_021','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How does the ''climate'' of a place directly influence how people build their homes?','["It forces everyone to build identical homes.","People must adapt to the climate; in cold regions, they build homes with thick insulation, while in hot regions, they design homes for shade and ventilation.","Climate only affects what color the house is painted.","People do not care about the weather when building."]',1,'You wouldn''t build a house with giant, drafty windows in freezing snow!','Climate affects... what homes are designed for... People in cold regions may need well-insulated homes, while communities in hot regions may use shade, ventilation...','2026-11-01 07:55:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_022','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why is ''Step 3: Record information'' critical when conducting a local area investigation?','["Because you will forget if you don''t write it down.","It ensures you have accurate, written observations (or a sketch map) to review later, and helps you distinguish between confirmed facts and your own personal guesses (inferences).","Because it is the only way to get paid.","Because you must mail the notes to the government."]',1,'A good geographer relies on written facts, not just memory!','Record information: Write down observations, draw a sketch map... distinguish what you observed from what you inferred.','2026-11-01 07:55:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_023','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why is it important to check the ''date'' on a map or dataset before using it?','["To see if the map is older than you are.","Because places, populations, and borders change over time; an old map might not show a newly built highway or a recently changed country border.","Because maps expire and disappear after 10 years.","Because the date changes the color of the map."]',1,'A map from 1950 won''t show the new hospital built in 2020!','When using information, ask: When was it created or updated? ... Remember that maps simplify the real world. They may not show every building, path, boundary or recent change. Check the date...','2026-11-01 07:55:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_024','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How can an ''economic region'' cross the borders of multiple towns?','["It cannot; economies only exist in one town at a time.","If multiple towns are all connected by the same type of industry (like a string of coastal towns all relying on fishing and tourism), they form a single economic region regardless of town borders.","It only happens if all the towns merge into one massive city.","It happens when the towns stop trading with each other."]',1,'If three towns all mine coal, they are part of the same coal-mining region!','Economic region: An area connected by similar economic activities, such as farming, manufacturing, mining, fishing or tourism.','2026-11-01 07:55:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_025','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'If you want to understand how many people live in an area, which type of map or data should you use?','["A physical map","A population map and official statistics","A road map","A satellite image of a cloud"]',1,'Physical maps show mountains, but population maps show where the people are!','Population maps and statistics help explain where people live.','2026-11-01 07:55:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_026','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why do geographers prefer to compare places using ''several characteristics'' rather than just one?','["Because checking one characteristic is illegal.","Because places are complex; looking at just one feature (like temperature) won''t explain the whole picture of how people live, work, and build their communities there.","Because geographers have a lot of free time.","Because comparing one characteristic always gives the wrong answer."]',1,'To understand a place, you have to look at its weather, its land, AND its people!','A useful comparison considers several characteristics rather than relying on one feature.','2026-11-01 07:55:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_027','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How can ''transport and technology'' change the challenges a place faces?','["They create mountains where there were none.","Good transport and digital networks can connect an isolated place to jobs, hospitals, and markets, overcoming difficult physical geography.","They force everyone to move away from the place.","They prevent any new buildings from being built."]',1,'A fast train can make living in a distant mountain village much easier!','Transport and technology: Roads, railways, ports, airports and digital networks connect places to jobs, education, healthcare and markets. Places with limited transport... may face different challenges...','2026-11-01 07:55:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_028','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'Why should you ask ''Does it show facts, estimates or opinions?'' when looking at a geographic source?','["Because all maps are opinions.","Because some information (like a blog post) might be a personal opinion, while a government census is a recorded fact; geographers must rely on verifiable facts to draw accurate conclusions.","Because facts are usually wrong.","Because opinions are better than facts in science."]',1,'You need proof, not just someone''s guess!','When using information, ask: ... Does it show facts, estimates or opinions? Is it suitable for the question being investigated? ... Geographers compare locations using evidence rather than assumptions.','2026-11-01 07:55:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_029','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'If you observe litter in a public park during fieldwork, what is the ''geographical'' next step?','["Ignore it and go home.","Identify it as an environmental issue and suggest a realistic, practical improvement (like adding more bins or scheduling waste collection).","Burn the litter immediately.","Blame the park ranger."]',1,'Geographers don''t just study problems; they look for logical solutions!','Step 5: Suggest improvements. Identify a local issue, such as litter... Suggest realistic improvements and consider who could help.','2026-11-01 07:55:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_030','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',5,'How do ''natural resources'' influence local employment?','["They force everyone to work in an office.","If a place has abundant forests, fertile soil, or minerals, the local jobs will often revolve around forestry, farming, or mining to extract those specific resources.","They prevent people from having jobs.","Natural resources have no connection to jobs."]',1,'If you live next to a gold mine, many people in town will work as miners!','Natural resources: The availability of forests, minerals, fertile soil, sunlight and wind can influence local industries and employment.','2026-11-01 07:55:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_031','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Critique the assertion that a ''Country'' is a permanent, static geographical entity.','["Countries are physically carved into the Earth''s crust and cannot change.","Countries are dynamic geopolitical constructs, not permanent geographical features. Their political boundaries, administrative divisions, and systems of government are subject to frequent change through historical events, treaties, conflicts, and shifting geopolitical power.","Countries only change their names, never their borders.","Countries disappear and reappear randomly every decade."]',1,'Look at a map of Europe from 1910 versus today; the physical land is the same, but the countries completely changed!','A country is a territory with a defined geographical area and a system of government. Countries have boundaries, although some boundaries are disputed or not universally recognised... History and culture: Migration, trade, historical events... shape [places].','2026-11-01 07:55:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_032','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Synthesize how the concept of a ''Region'' functions as an analytical tool rather than a physical reality.','["Regions are physical walls built between cities.","A region is an epistemological construct used by geographers to simplify and analyze complex spatial data. By grouping disparate areas based on a chosen variable (e.g., economics or culture), researchers can identify macro-trends that transcend rigid political borders.","Regions are useless for geographical analysis.","Regions are strictly defined by ocean boundaries."]',1,'A ''region'' is just a way for humans to categorize the world to make it easier to study.','A region is an area grouped together because it shares one or more characteristics. Regions can be small or large, and their boundaries depend on the reason for grouping places... A region does not always have its own government...','2026-11-01 07:55:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_033','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Analyze the inherent vulnerability of ''Administrative Divisions'' (like districts) when dealing with transnational environmental issues (like river pollution).','["Administrative divisions instantly stop all pollution at the border.","Administrative borders are human constructs that natural systems ignore. A river flowing through multiple districts requires complex inter-jurisdictional cooperation to manage pollution, as one district''s waste will inevitably flow into another''s territory, exposing the limits of localized authority.","Administrative divisions are completely immune to water pollution.","River pollution always flows backward against administrative borders."]',1,'A line on a map won''t stop a polluted river from flowing into the next town!','However, people, wildlife, water and environmental systems may cross boundaries, so cooperation between neighbouring areas can be important.','2026-11-01 07:55:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_034','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Evaluate the historiographical significance of ''Fieldwork'' compared to ''Satellite Imagery'' in understanding a local place.','["Fieldwork is outdated and completely useless.","While satellite imagery provides excellent macro-level spatial and topographical data, it cannot capture granular, qualitative human elements. Fieldwork grounds the data, capturing local culture, economic conditions, and human interactions that are invisible from space.","Satellite imagery captures human emotions perfectly.","They both provide the exact same type of data."]',1,'A satellite can show a building, but only walking past it (fieldwork) tells you if it''s an abandoned warehouse or a busy school.','Satellite images show patterns of land cover and development from above... Field observations provide information gathered directly in a place. (Synthesis: Satellites show the ''where'', fieldwork shows the ''how'' and ''why'').','2026-11-01 07:55:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_035','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Synthesize how ''Historical Events'' and ''Migration'' permanently alter the ''Human Features'' of a geographic location.','["They cause the physical mountains to change shape.","Migration and historical events introduce novel architectural styles, agricultural techniques, and urban planning philosophies. Over time, these introduced cultural artifacts physically manifest in the landscape, fundamentally altering the built environment (human features) of that place.","They have no effect on the built environment.","They cause all buildings to instantly turn into natural features."]',1,'If a new culture moves into a town, they will build new types of houses and temples, changing how the town looks!','History and culture: Migration, trade, historical events and cultural exchange shape the languages, food, architecture, celebrations and traditions found in different places.','2026-11-01 07:55:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_036','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Critique the assumption that possessing abundant ''Natural Resources'' automatically guarantees a place will be prosperous.','["Natural resources are the only factor in determining wealth.","This reflects the ''resource curse'' paradox. While resources provide potential economic capital, true prosperity is dictated by human factors: robust infrastructure, equitable governance, education, and stable economic institutions. Without these, resource abundance often leads to exploitation and inequality.","Natural resources always make a place extremely poor.","Natural resources evaporate if they are not used immediately."]',1,'Having a gold mine doesn''t make a town rich if corrupt leaders steal all the gold!','The availability of forests, minerals... can influence local industries... Resources alone do not determine whether a place is prosperous; education, infrastructure, governance and many other factors matter too.','2026-11-01 07:55:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_037','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Analyze how the physical geography of ''Andean mountain communities'' necessitates specific agricultural adaptations (like terracing).','["They farm on flat plains because mountains don''t exist.","The extreme relief and steep gradients of the Andes preclude traditional flatland agriculture and increase erosion risk. Communities must engineer the landscape by carving horizontal terraces into the slopes to create arable land, manage water runoff, and stabilize the soil.","They grow crops underwater in the mountain lakes.","They only hunt animals and never grow crops."]',1,'If you try to plant a normal farm on a steep cliff, the rain will wash all your dirt and seeds away!','Andean mountain communities: High elevations and steep slopes influence travel, farming and settlement patterns. People adapt to local conditions...','2026-11-01 07:55:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_038','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Synthesize the relationship between ''low-lying topography'' and ''human engineering'' in the Netherlands.','["The Netherlands requires no engineering because it is on a mountain.","Because much of the Netherlands is geographically below sea level, its continued existence as a habitable place relies on massive, continuous human engineering—a complex system of dikes, canals, and drainage pumps designed to actively manage water and prevent catastrophic marine flooding.","The Netherlands uses engineering to build taller mountains.","The Netherlands relies entirely on natural coral reefs for protection."]',1,'They literally built walls to hold back the ocean so they could build cities on the dry land!','Low-lying parts of the Netherlands: Much of the landscape is low and relatively flat. Water management, drainage, dikes and flood protection are important in many areas.','2026-11-01 07:55:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_039','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Evaluate the epistemological necessity of distinguishing between ''what you observed'' and ''what you inferred'' during geographic fieldwork.','["Inferences are always facts, so there is no need to distinguish them.","Observations are verifiable, objective empirical data (e.g., ''there is litter''). Inferences are subjective interpretations of that data (e.g., ''people here are lazy''). Conflating the two compromises the scientific integrity of the geographic study and leads to biased conclusions.","Observations are always false, while inferences are true.","Distinguishing them makes the fieldwork completely invalid."]',1,'You saw trash on the ground (observation). You guessed the trash can was full (inference). You must keep these separate!','Step 3: Record information... record the date and distinguish what you observed from what you inferred.','2026-11-01 07:55:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_040','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Analyze how ''Transport infrastructure'' serves as the primary catalyst for the integration of ''Economic Regions''.','["Transport infrastructure isolates towns from each other.","An economic region (like a manufacturing hub) requires the fluid movement of raw materials, labor, and finished goods. Robust transport infrastructure (highways, rail networks) drastically lowers friction of distance, physically integrating disparate towns into a single, cohesive macroeconomic engine.","Transport infrastructure is only used for holidays.","Economic regions form naturally without any human roads."]',1,'Three farming towns can only act as one big ''farming region'' if they have roads connecting them to the same market!','Economic region: An area connected by similar economic activities... Transport and technology: Roads, railways, ports... connect places to jobs... and markets. (Synthesis: The transport network is what connects the region).','2026-11-01 07:55:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_041','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Critique the idea that maps represent objective, unquestionable reality.','["Maps are magical and can never contain errors.","Maps are inherently subjective models that simplify reality. The cartographer makes subjective choices regarding scale, what features to omit, what data to emphasize, and what projection to use. Therefore, a map is an interpretation of reality, not an absolute truth.","Maps are entirely fictional and should never be used.","Maps are drawn by satellites with no human input."]',1,'A map is just a drawing made by a person; they couldn''t draw every single tree, so they made choices about what was important!','Remember that maps simplify the real world. They may not show every building, path, boundary or recent change. Check the date, scale, legend and source before drawing conclusions.','2026-11-01 07:55:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_042','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Synthesize how the concept of a ''Place'' is shaped simultaneously by its absolute location and its relative spatial connections.','["A place is only defined by its exact GPS coordinates.","A ''place'' is defined both by its static, absolute site (its physical landforms and climate) and its dynamic, relative situation (its transport links, trade connections, and cultural exchange with surrounding places), making its identity fluid and interconnected.","A place has no connections to anywhere else.","A place is defined exclusively by its political name."]',1,'A port city isn''t just about the water; it''s about all the ships coming in from other countries!','Every place has characteristics... Physical features... Human features... Transport and technology... connect places to jobs... History and culture... (Synthesis: It''s what is there, plus what connects to it).','2026-11-01 07:55:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_043','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Analyze the inherent conflict between ''Political Boundaries'' and ''Cultural Regions'' in post-colonial geography.','["Political boundaries always perfectly match cultural regions.","In many post-colonial areas, political boundaries were drawn arbitrarily by foreign powers using geometric lines, intentionally ignoring complex, pre-existing indigenous cultural and linguistic regions. This misalignment frequently causes severe, long-term geopolitical instability and ethnic conflict.","Cultural regions naturally form perfect square borders.","Political boundaries completely erase culture instantly."]',1,'If you draw a straight line through a map, you might accidentally cut a single cultural group in half!','Cultural region: An area where people may share some languages... Cultures are diverse and can overlap... A political boundary does not always follow a natural feature. Some boundaries are straight lines drawn across land...','2026-11-01 07:55:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_044','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Evaluate the necessity of establishing ''Administrative Divisions'' (like provinces or municipalities) in a highly populous nation.','["They are unnecessary and only slow down government.","Centralized administration of a massive population is logistically impossible. Administrative divisions decentralize governance, allowing for localized resource allocation, tailored public services (schools, emergency response), and localized infrastructure maintenance that addresses specific regional needs.","They force everyone to move to the capital city.","They are only used to change the weather in different areas."]',1,'A country with a billion people needs local mayors to manage the day-to-day problems in small towns!','These divisions help organise schools, healthcare, transport, waste collection, roads, emergency services and other public responsibilities.','2026-11-01 07:55:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('geo_places_global_045','Geography','Human Geography','Topic 15: Exploring Countries, Regions, and Local Places','Primary',10,'Synthesize the process of identifying a ''Local Issue'' and ''Suggesting Improvements'' during geographic fieldwork as civic action.','["It is just a theoretical exercise for school.","This process moves geography from passive observation to active civic engagement. By empirically documenting an infrastructural or environmental failure (like dangerous walking routes) and proposing evidence-based, actionable solutions, geographers actively participate in urban planning and community advocacy.","It means you should fix the problem yourself instantly.","It forces the government to ban all fieldwork."]',1,'You don''t just notice a broken sidewalk; you figure out why it''s broken and suggest a way the city can fix it!','Step 5: Suggest improvements. Identify a local issue... Suggest realistic improvements and consider who could help. (Synthesis: Geography is a tool for fixing communities).','2026-11-01 07:55:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_001','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is physics?','["The study of history and old maps","A branch of science that studies matter, energy, motion, forces, light, sound, heat, and electricity","The study of how plants grow","The study of animals and their habitats"]',1,'It helps us understand how the physical world works.','Physics is a branch of science that studies matter, energy, motion, forces, light, sound, heat and electricity.','2026-11-01 07:56:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_002','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'Which of these is an everyday example of physics involving ''motion''?','["Reading a book silently","A ball rolling across the floor","Painting a picture","Sleeping in a bed"]',1,'Rolling is a type of motion.','Motion: Physics explains how objects move and what makes them speed up, slow down or change direction.','2026-11-01 07:56:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_003','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'When you push the pedals of a bicycle to make it move, which branch of science explains this action?','["Geography","Physics","Literature","History"]',1,'Physics explains forces and movement.','Riding a bicycle: Pushing the pedals makes the bicycle move... Physics helps explain how and why these everyday events happen.','2026-11-01 07:56:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_004','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is a ''prediction'' in science?','["A random guess about the past","A statement about what we think will happen in an experiment","The final answer to a test","A tool used to measure distance"]',1,'It is what you guess will happen before you test it.','Prediction: A statement about what we think will happen.','2026-11-01 07:56:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_005','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is an ''observation''?','["Information collected by noticing something with our senses or measuring it","A rule that cannot be broken","A story about a scientist","A guess about the future"]',0,'You observe that the sky is blue or the car rolled 5 meters.','Observation: Information collected by noticing or measuring something.','2026-11-01 07:56:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_006','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What does ''quantitative'' mean when making an observation?','["Using feelings and emotions","Using numbers and measurements","Using colors only","Using sounds only"]',1,'Quantity means an amount you can count or measure.','Quantitative observations: Use numbers and measurements.','2026-11-01 07:56:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_007','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'Which of these is a ''quantitative'' observation?','["The toy car is shiny.","The car travelled 80 centimetres.","The floor feels smooth.","The bell sounds loud."]',1,'It includes a specific number.','Quantitative observations... Examples: The car travelled 80 centimetres.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_008','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'Which of these is a ''qualitative'' observation?','["The experiment lasted 5 seconds.","The water temperature was 30°C.","The surface feels rough.","The ramp is 10 centimetres high."]',2,'It describes a quality, like how it feels or looks.','Qualitative observations: Describe qualities without using numbers. Examples: The surface feels rough.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_009','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is an ''experiment''?','["A planned test used to investigate a scientific question","A list of numbers","A type of measuring tool","A guess that cannot be tested"]',0,'It is how scientists find answers.','Experiment: A planned test used to investigate a question.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_010','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What does it mean to conduct a ''fair test''?','["To test every single factor at the exact same time","To change one main factor at a time while keeping all other important factors the same","To cheat during a test","To test without measuring anything"]',1,'You only change one thing so you know exactly what caused the result.','Fair test: A test that changes one main factor while controlling other important factors.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_011','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is a ''result'' in a science experiment?','["The question asked before the experiment","What happens or what is found during the investigation","The equipment used to build a ramp","A guess about tomorrow"]',1,'It is the data or outcome you get at the end.','Result: What happens or what is found during an investigation.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_012','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What is a ''conclusion''?','["An explanation of what the results tell us","The starting question","The materials needed for a test","A wild guess"]',0,'It is the final answer you figure out after looking at the results.','Conclusion: An explanation of what the results tell us.','2026-11-01 07:56:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_013','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'When studying light and heat, physics explains how energy from the _____ warms the Earth.','["Moon","Stars","Sun","Ocean"]',2,'The Sun provides light and heat to our planet.','Light and heat: Physics helps explain how light travels and how energy from the Sun warms Earth.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_014','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'How does physics explain sound?','["It explains how vibrating objects produce sounds that travel to our ears.","It explains how silence is created in space.","It explains why light is faster than sound.","It explains how to paint a picture."]',0,'When you hit a drum, it vibrates and makes a sound.','Sound: Physics explains how vibrating objects produce sounds that travel to our ears.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_015','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',1,'What does magnetism explain in physics?','["Why water boils","Why magnets attract certain materials, such as iron","How fast a car can drive","Why plants grow towards the sun"]',1,'Magnets stick to some metals because of physics!','Magnetism: Physics explains why magnets attract some materials, such as iron.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_016','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'If you want to test whether a heavier car rolls further than a lighter car, what must you keep exactly the same to make it a ''fair test''?','["The weight of the cars.","The height of the ramp and the floor surface.","The color of the cars.","You should change the ramp and the floor at the same time."]',1,'If you change the ramp AND the car, you won''t know which one caused the car to go further!','A fair test changes one main factor at a time. If you are testing weight, you must keep the ramp height and floor the same.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_017','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'Why is it important to repeat a test (like rolling a car down a ramp) three times instead of just once?','["To make the experiment take longer.","To check whether the pattern is consistent and reliable, in case there was a mistake on the first try.","Because you are required to use three different cars.","Because three is a lucky number."]',1,'Maybe the car bumped into a speck of dust on the first try; doing it three times makes sure the result is true!','Repeating the experiment can help us check whether the pattern is consistent... What should you do to check whether an experimental result is reliable? Repeat the test.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_018','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'If your experiment proves that your prediction was incorrect, what should you do?','["Erase the data and change your prediction so you look smart.","Record the result honestly; an incorrect prediction still leads to useful scientific learning.","Throw the experiment away and never tell anyone.","Stop asking scientific questions."]',1,'Finding out you were wrong is still finding the right answer!','An incorrect prediction can still lead to useful scientific learning... Record the result honestly.','2026-11-01 07:56:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_019','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'In the toy car experiment, why must you release the car from the ramp *without* pushing it?','["Because pushing it breaks the car.","Because pushing it adds an uncontrolled force, which makes the test unfair and the results unreliable.","Because pushing it makes it go backward.","Because you are only testing how fast your hands can move."]',1,'If you push it hard one time and soft the next time, the test is not fair!','Release the car from the same starting point without pushing it... A fair test is an experiment in which we change one main factor at a time while keeping other important factors the same.','2026-11-01 07:56:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_020','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'How is ''electrical energy'' converted when you use a simple lamp in your bedroom?','["It is converted entirely into sound.","It is converted mainly into light and some heat.","It is converted into magnetic energy.","It is destroyed completely."]',1,'The bulb lights up the room, but it also gets warm to the touch!','Using a lamp: Electrical energy is converted mainly into light and some heat.','2026-11-01 07:56:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_021','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'What physical forces are at work when a child plays on a swing?','["Only electricity.","The swing moves back and forth under the influence of gravity and motion.","Only magnetism.","There are no forces at work."]',1,'Gravity pulls you down, and motion swings you back up!','Playing on a swing: The swing moves back and forth under the influence of gravity and motion.','2026-11-01 07:56:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_022','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'Why is the statement ''The ball rolled far'' a weak scientific observation compared to ''The ball rolled 150 centimeters''?','["Because ''far'' is a bad word.","Because ''far'' is a qualitative observation that is vague and subjective, while ''150 centimeters'' is a precise, quantitative measurement that can be verified.","Because scientists are not allowed to use letters.","Because 150 centimeters is actually very short."]',1,'My idea of ''far'' might be different from your idea of ''far''; numbers make it exact!','Quantitative observations: Use numbers and measurements. Examples: The car travelled 80 centimetres. (Qualitative describes qualities without numbers, which is less precise).','2026-11-01 07:56:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_023','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'What is a ''variable'' in a science experiment?','["The person doing the experiment.","A factor that can change in an experiment, such as the height of the ramp.","A rule that says you cannot change anything.","The final answer."]',1,'It is the thing that ''varies'' (changes)!','Variable: A factor that can change in an experiment.','2026-11-01 07:56:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_024','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'If you want to investigate how surface friction affects a toy car, what should be your single changing variable?','["The weight of the toy car.","The height of the ramp.","The surface on which the car rolls (e.g., smooth floor vs. rough carpet).","The person dropping the car."]',2,'To test the floor, you have to change the floor!','For example, you may notice that a toy car rolls farther on a smooth floor than on a rough carpet. Does the surface affect how far a toy car travels? (To test this, the surface must be the variable).','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_025','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'What step immediately follows an ''observation'' in a standard scientific investigation?','["Writing the final conclusion.","Asking a scientific question based on that observation.","Throwing the materials away.","Ignoring what you saw."]',1,'You see something interesting, and then you ask ''why did that happen?''','A scientific investigation often begins with an observation... This observation can lead to a scientific question.','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_026','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'Why is it important to use a measuring tape or ruler in a physics experiment instead of just guessing the distance?','["Because rulers are heavy and hold the ramp down.","Because scientific experiments require exact, quantitative measurements to produce reliable and comparable results.","Because guessing is always more accurate than measuring.","Because rulers create friction."]',1,'You can''t prove a car rolled further without exact numbers!','Measurement: Finding the size, amount or value of something... Scientists record what happens rather than relying only on memory... Quantitative observations: Use numbers and measurements.','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_027','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'When riding a bicycle, how does physics explain the function of the brakes?','["Brakes make the bicycle go faster.","Brakes apply friction to the wheels to slow the bicycle down.","Brakes use magnetism to pull the bike backward.","Brakes turn the bike invisible."]',1,'Squeezing the brakes rubs against the wheel to stop it!','Riding a bicycle: Pushing the pedals makes the bicycle move. Brakes help slow it down, while friction between the tyres and road helps the bicycle grip...','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_028','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'Which of the following is a good ''scientific question'' that can be tested?','["What is the best color in the world?","Does a longer ramp make a toy car travel farther?","Do aliens like playing with cars?","Is a smooth floor happier than a rough floor?"]',1,'A scientific question must be something you can physically measure and test!','Scientists ask questions that can be investigated through observations or experiments. Examples: Does a longer ramp make a toy car travel farther?','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_029','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'What conclusion can you draw if a car travels 40cm on a 5cm ramp, and 85cm on a 15cm ramp?','["Ramp height has no effect on distance.","The car travels farther as the ramp height increases.","The car travels shorter as the ramp height increases.","The car travels exactly 100cm every time."]',1,'The higher the ramp, the further the car goes!','Ramp height 5 cm = 40 cm. Ramp height 15 cm = 85 cm. In this example, the car travelled farther as the ramp height increased.','2026-11-01 07:56:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_030','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',5,'Why is understanding ''friction'' important when riding a bicycle?','["Because friction makes the pedals fall off.","Friction between the tyres and the road helps the bicycle grip the surface so it doesn''t slide out of control.","Friction makes the bicycle float in the air.","Friction provides the light for the bicycle."]',1,'Without friction, riding a bike on a road would be like riding on ice!','Riding a bicycle: ...friction between the tyres and road helps the bicycle grip the surface.','2026-11-01 07:56:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_031','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Analyze the epistemological value of a ''failed'' prediction in the scientific method.','["A failed prediction proves that science is a waste of time.","A prediction that is not supported by empirical results is highly valuable; it falsifies a hypothesis, forcing the scientist to revise their understanding and generating new, more accurate scientific knowledge.","A failed prediction means the scientist must falsify the data to match.","It proves that experiments are entirely random and meaningless."]',1,'Discovering that something *doesn''t* work is just as important as discovering that it *does*!','An incorrect prediction can still lead to useful scientific learning... Record the result honestly.','2026-11-01 07:56:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_032','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Critique the validity of an experiment where a student changes both the ramp height AND the floor surface at the same time.','["The experiment is highly efficient and perfectly valid.","The experiment is invalid because it lacks variable isolation (it is not a ''fair test''). If the car rolls further, the student cannot determine if the increased distance was caused by the steeper ramp or the smoother floor.","The experiment is valid as long as the student writes down the answer.","It is invalid because changing two things causes an explosion."]',1,'If you change two things at once, you never know which one actually made the difference!','If you also change the car and the floor surface, you cannot easily tell which change caused the result. Fair test: A test that changes one main factor while controlling other important factors.','2026-11-01 07:56:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_033','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Synthesize how ''quantitative'' data provides a superior foundation for a ''conclusion'' compared to ''qualitative'' data in physics.','["Qualitative data uses numbers, making it superior.","Quantitative data provides objective, standardized numerical metrics (e.g., ''85 cm'') that can be statistically analyzed and universally replicated, whereas qualitative data (e.g., ''it went far'') is subjective and prone to observer bias.","Quantitative data is completely useless for physics.","Qualitative data is the only way to measure gravity."]',1,'You can argue about what ''far'' means, but you can''t argue with ''85 centimeters''!','Quantitative observations: Use numbers and measurements... Conclusion: An explanation of what the results tell us. (Synthesis: Numbers provide objective proof for the explanation).','2026-11-01 07:56:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_034','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Evaluate the transition of energy when ''ringing a bell''.','["The bell creates energy out of nothing.","The kinetic (mechanical) energy from the hand movement causes the physical metal of the bell to vibrate. These vibrations transfer energy into the surrounding air molecules, propagating as acoustic (sound) energy to the ear.","The bell converts light energy directly into sound.","The bell absorbs sound and converts it into heat."]',1,'Your moving hand creates vibrations, and those vibrations hit your eardrum as sound!','Ringing a bell: The bell vibrates and produces sound. Sound: Physics explains how vibrating objects produce sounds that travel to our ears.','2026-11-01 07:56:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_035','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Analyze the physical mechanics of ''friction'' as both an impeding and enabling force in the context of a bicycle.','["Friction only speeds up the bicycle.","Friction acts as an impeding force when the brakes are applied (converting kinetic energy to heat to slow the bike), but it acts as an essential enabling force between the tires and the asphalt, providing the traction necessary for forward propulsion without slipping.","Friction makes the bicycle completely invisible.","Friction is entirely absent from bicycle mechanics."]',1,'Friction stops you when you brake, but it also lets your tires grip the road so you can move forward!','Riding a bicycle: ... Brakes help slow it down, while friction between the tyres and road helps the bicycle grip the surface.','2026-11-01 07:56:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_036','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Synthesize the relationship between an ''Observation'' and a ''Scientific Question''.','["They are identical and mean the exact same thing.","An observation is the empirical detection of a phenomenon (e.g., noticing a car rolls faster on tile). This anomalies or patterns prompt intellectual curiosity, serving as the foundational catalyst for formulating a specific, testable Scientific Question (e.g., ''Does surface texture determine speed?'').","A scientific question always comes before an observation is ever made.","Observations prevent scientific questions from being asked."]',1,'You have to see something weird (observation) before you can ask ''why did that happen?'' (question).','A scientific investigation often begins with an observation. An observation is something we notice... This observation can lead to a scientific question.','2026-11-01 07:56:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_037','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Evaluate the structural necessity of identifying a ''Variable'' before designing an experiment.','["Variables are only identified after the experiment is completely finished.","Identifying variables is the absolute prerequisite for experimental design. A scientist must explicitly define the independent variable (what to change), the dependent variable (what to measure), and the controlled variables (what to keep constant) to ensure a valid ''fair test''.","Identifying variables ensures the experiment will always fail.","Variables are only used in history, not physics."]',1,'If you don''t know what you are changing and what you are keeping the same, your test is useless!','Variable: A factor that can change in an experiment. Fair test: A test that changes one main factor while controlling other important factors.','2026-11-01 07:56:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_038','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'How does the ''conversion of electrical energy'' in a lamp demonstrate the limitations of energy efficiency?','["It demonstrates that 100% of electricity is converted into light.","A lamp converts electrical energy into desired luminous energy (light), but inherently loses a significant portion of that energy as undesired thermal energy (heat), demonstrating that energy conversions are rarely 100% efficient to their primary purpose.","It shows that electricity can only be converted into sound.","It proves that lamps do not actually use energy."]',1,'A lightbulb''s job is to make light, but the heat it makes is actually wasted energy!','Using a lamp: Electrical energy is converted mainly into light and some heat.','2026-11-01 07:56:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_039','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Critique the assertion that ''Physics is limited to laboratories''.','["The assertion is completely accurate; physics only happens in labs.","This assertion is fundamentally flawed. Physics is the foundational science describing the universal mechanics of reality; every macroscopic and microscopic interaction in everyday life (from swinging on a playground to walking) is governed by physical laws, regardless of location.","Physics only occurs when scientists are actively watching.","Physics is limited to outer space, not Earth."]',1,'Gravity doesn''t turn off just because you leave the science classroom!','Physics in Everyday Life: Physics is not limited to laboratories. It is present in homes, schools, playgrounds and nature.','2026-11-01 07:56:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_040','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Analyze the specific function of ''gravity'' in the mechanics of playing on a swing.','["Gravity only pushes the swing higher into the air.","Gravity provides the continuous, downward restoring force. When the swing is pushed upward to its apex, gravity decelerates it to a stop, then pulls it back down, converting potential energy back into kinetic energy to maintain the oscillating motion.","Gravity prevents the swing from moving at all.","Gravity causes the swing to float away."]',1,'Gravity is the invisible rope pulling you back down to the center!','Playing on a swing: The swing moves back and forth under the influence of gravity and motion.','2026-11-01 07:56:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_041','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Synthesize how the concept of ''Reproducibility'' (repeating a test) establishes scientific truth.','["Repeating a test proves that the first test was a complete lie.","A single result could be an anomaly caused by an uncontrolled variable or human error. Repeating an experiment multiple times and achieving consistent quantitative results mathematically proves that the observed phenomenon is an objective, reliable physical law rather than a random fluke.","Repeating a test makes the results entirely random.","Science relies entirely on guessing without ever repeating tests."]',1,'If you drop a ball once and it falls, it''s a clue. If you drop it 100 times and it falls, it''s a scientific law!','Repeating the experiment can help us check whether the pattern is consistent. What should you do to check whether an experimental result is reliable? Repeat the test.','2026-11-01 07:56:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_042','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Evaluate the necessity of controlling ''the starting position of the car'' in a ramp experiment.','["The starting position changes the color of the car.","If the starting position varies, the distance the car travels on the ramp varies, altering its initial kinetic energy upon hitting the floor. This introduces a second, unmeasured variable, instantly invalidating the ''fair test'' parameters.","The starting position has absolutely no effect on the car''s speed.","The starting position prevents the car from moving."]',1,'If you drop the car from the top of the ramp one time, and the middle of the ramp the next time, the test is completely ruined!','Keep these factors the same: ... The starting position of the car. If you also change the car and the floor surface, you cannot easily tell which change caused the result.','2026-11-01 07:56:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_043','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Analyze the statement: ''Not every question can be answered by a simple experiment.''','["It means science is useless and cannot answer anything.","It acknowledges the epistemological limits of empirical science. While physics excels at testing objective mechanical variables (e.g., ''how fast does it fall?''), it cannot use simple experiments to answer subjective, metaphysical, or highly complex multi-variable questions (e.g., ''is the color red beautiful?'').","It proves that experiments are always the wrong way to learn.","It means we should only use magic to answer questions."]',1,'Science can tell you how a rainbow forms, but an experiment can''t tell you if a rainbow is pretty!','Not every question can be answered by a simple experiment, but good scientific questions can often be investigated systematically.','2026-11-01 07:56:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_044','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Critique the practice of relying ''only on memory'' when recording experimental results.','["Human memory is perfectly infallible and superior to written data.","Human memory is highly fallible, subject to psychological bias, and degrades rapidly over time. True scientific rigor demands immediate, written documentation of quantitative data to ensure accuracy, transparency, and the ability for peer review.","Memory is the only legally accepted form of scientific data.","Writing down results actually destroys the data."]',1,'You might think you remember the car rolled 80cm, but a week later you might swear it was 90cm! Write it down!','Observations, Measurements and Results: Scientists record what happens rather than relying only on memory.','2026-11-01 07:56:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_intro_global_045','Physics','Introduction to Physics','Topic 1: Introduction to Physics','Primary',10,'Synthesize how the discipline of ''Physics'' bridges the macro (Sunlight warming Earth) and the micro (Magnetism).','["Physics only studies massive objects in space.","Physics provides a unified mathematical and conceptual framework that explains all universal phenomena. The same fundamental laws of energy transfer and fundamental forces govern both massive celestial mechanics (solar radiation) and atomic-level interactions (magnetic fields).","Physics proves that the Sun is actually a giant magnet.","Physics only studies things that can be seen with the naked eye."]',1,'Physics is the rulebook for everything in the universe, big or small!','Physics is a branch of science that studies matter, energy, motion, forces, light, sound, heat and electricity... from sunlight warming our planet... [to] why magnets attract certain materials...','2026-11-01 07:56:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_001','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What does a complete measurement usually include?','["Only a number","A number and a unit","Only a unit","A color and a shape"]',1,'If you just write ''15'', no one knows if you mean 15 centimetres or 15 elephants!','A measurement usually includes two parts: Number: how much of something there is. Unit: the standard used to express the amount.','2026-11-01 07:56:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_002','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What does ''length'' tell us?','["How heavy an object is","How long, tall or wide an object is","How hot an object is","How much water a cup holds"]',1,'You use a ruler to find this out.','Length tells us how long, tall or wide an object is.','2026-11-01 07:56:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_003','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What is the abbreviation for ''centimetre''?','["cm","m","kg","s"]',0,'It is a common unit for measuring small lengths.','Centimetre: cm. Length of a pencil.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_004','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'How many centimetres are in 1 metre?','["10","100","1,000","50"]',1,'A metre stick is exactly 100 centimetres long.','Important conversions: 100 centimetres = 1 metre.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_005','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'How many millimetres are in 1 centimetre?','["10","100","1,000","1"]',0,'Look at the tiny lines between the numbers on a ruler.','Important conversions: 10 millimetres = 1 centimetre.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_006','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What does a ''thermometer'' measure?','["Weight","Length","Temperature","Time"]',2,'It tells you how hot or cold something is.','Thermometer: Measures temperature.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_007','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What unit is commonly used to measure the mass of a bag of rice?','["Litres","Kilograms (kg)","Centimetres","Seconds"]',1,'Kilograms measure how much matter is in the bag.','Mass is commonly measured in: Grams (g), Kilograms (kg)... A bag of rice might have a mass of 5 kg.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_008','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'How many grams are in 1 kilogram?','["10","100","1,000","10,000"]',2,'Kilo- means one thousand.','Useful conversions: 1,000 grams = 1 kilogram.','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_009','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What unit is used to measure time?','["Kilograms","Seconds, minutes, and hours","Degrees Celsius","Litres"]',1,'You use a clock or stopwatch for this.','Units of time: Second (s), Minute (min), Hour (h).','2026-11-01 07:56:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_010','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'How many seconds are in 1 minute?','["24","30","60","100"]',2,'Watch the second hand on a clock go all the way around.','Minute (min) = 60 seconds.','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_011','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What instrument is used to measure the volume of a liquid in a science experiment?','["A ruler","A thermometer","A measuring cylinder","A stopwatch"]',2,'It is a tall glass or plastic tube with numbers on the side.','Measuring cylinder: Measures the volume of a liquid.','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_012','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What unit is used to measure the capacity of a water bottle?','["Centimetres","Kilograms","Litres (L) or millilitres (mL)","Degrees"]',2,'Look at the label on a bottle of water.','Capacity of a container: Millilitres (mL), litres (L).','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_013','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'How many millilitres are in 1 litre?','["10","100","1,000","60"]',2,'Milli- means one thousandth.','Useful conversions: 1,000 millilitres = 1 litre.','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_014','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What is a ''standard unit''?','["Using your foot to measure a room","An agreed unit that people can use consistently anywhere in the world","A guess of how heavy something is","A broken ruler"]',1,'A centimetre is exactly the same size in every country.','A standard unit is an agreed unit that people can use consistently.','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_015','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',1,'What does it mean to measure ''capacity''?','["How far apart two places are","How much a container can hold","How hot the air is","How much an object weighs"]',1,'A bucket has a larger capacity than a teacup.','Capacity is how much a container can hold.','2026-11-01 07:56:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_016','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'Why is writing ''15'' without a unit a meaningless measurement in science?','["Because 15 is an unlucky number.","Without a unit, the number provides no context; ''15'' could mean 15 seconds, 15 kilograms, or 15 meters, making the data useless.","Because all measurements must be written in letters, not numbers.","Because 15 is too large of a number to measure."]',1,'If a doctor says ''take 5 of medicine'', you need to know if they mean 5 drops or 5 entire bottles!','Writing only “15” does not tell us whether we mean 15 centimetres, 15 seconds or something else. The unit makes the measurement meaningful.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_017','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'If you place a pencil on a ruler, and the eraser is at the 2 cm mark and the tip is at the 9 cm mark, how long is the pencil?','["9 cm","2 cm","11 cm","7 cm"]',3,'You have to subtract the starting point from the ending point!','If an object starts at the 2 cm mark and ends at the 9 cm mark, its length is: 9 - 2 = 7 cm.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_018','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'What is the crucial difference between ''mass'' and ''weight'' in physics?','["Mass is measured in seconds, weight is measured in minutes.","Mass is the amount of matter in an object, while weight is the actual force of gravity pulling down on that object.","Mass is for liquids, weight is for solids.","There is no difference; they are identical concepts."]',1,'Your mass stays the same in space, but your weight changes because there is less gravity!','Mass is a measure of how much matter an object contains. Weight is the force with which gravity pulls an object.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_019','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'If an astronaut travels to the Moon, what happens to their mass and their weight?','["Their mass decreases and their weight increases.","Their mass remains the same, but their weight is lower because the Moon has a weaker gravitational pull.","Their mass and weight both become zero.","Their mass increases and their weight stays the same."]',1,'You are still made of the same amount of ''stuff'' (mass), but the moon doesn''t pull you down as hard (weight)!','An object has approximately the same mass on Earth and the Moon, but its weight is lower on the Moon because the Moon''s gravitational pull is weaker.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_020','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'What unit is used to properly measure ''weight'' (the force of gravity) in physics?','["Kilograms","Newtons (N)","Centimetres","Degrees Celsius"]',1,'Even though your bathroom scale says ''kilograms'', physics uses Newtons for the force of weight!','Weight is a force caused by gravity. It is measured in newtons (N).','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_021','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'If a bottle has a capacity of 750 mL, how much of a litre does it hold?','["Half of a litre","Three-quarters of a litre","One full litre","Two litres"]',1,'Since 1 litre is 1000 mL, 750 mL is 3/4 of a litre.','For example, a bottle with a capacity of 750 mL holds three-quarters of a litre.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_022','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'Why is measuring a desk using ''hand spans'' considered a non-standard measurement?','["Because hand spans are too accurate.","Because the size of a hand span is informal and varies from person to person, meaning two people will get different results for the same desk.","Because hands are not allowed in science.","Because you can only use your feet to measure."]',1,'A child''s hand is much smaller than an adult''s hand, so the measurement would change!','A non-standard unit is an informal measure, such as hand spans... Another person''s hand spans may give a different result.','2026-11-01 07:56:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_023','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'What does it mean for a measurement to be ''accurate''?','["It means the measurement has many decimal places.","It means the measurement is a random guess.","It describes how close the measurement is to the true or accepted value of the object.","It means the measurement was taken very quickly."]',2,'If the real length is 10 cm, measuring it as 10.1 cm is very accurate!','Accuracy describes how close a measurement is to the true or accepted value.','2026-11-01 07:56:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_024','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'Why is it important to keep your eyes level with the marking when reading a measuring cylinder?','["To stop the water from boiling.","Looking from above or below the line creates an optical illusion (parallax error) that makes you read the wrong measurement.","Because looking down breaks the glass.","To make the water change color."]',1,'If you look from above, the water level looks higher than it really is!','To improve measurement quality: ... Keep your eyes level with the marking.','2026-11-01 07:56:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_025','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'At what approximate temperature does pure water boil under normal atmospheric pressure (in Celsius)?','["0°C","50°C","100°C","200°C"]',2,'100 degrees Celsius is very hot!','Water boils at approximately 100°C under normal atmospheric pressure.','2026-11-01 07:56:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_026','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'At what approximate temperature does ice melt under normal atmospheric pressure (in Celsius)?','["0°C","32°C","100°C","10°C"]',0,'0 degrees Celsius is the freezing/melting point of water.','Ice melts at approximately 0°C under normal atmospheric pressure.','2026-11-01 07:56:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_027','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'If an object has a volume of 1 cubic centimetre (1 cm³), how much liquid capacity is that equal to?','["10 Litres","100 millilitres","1 millilitre (1 mL)","1,000 Litres"]',2,'A tiny cube that is 1cm on all sides holds exactly 1 millilitre of water!','Useful conversions: ... 1 cm³ = 1 mL.','2026-11-01 07:56:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_028','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'Why should you NOT automatically start counting from the physical edge of a ruler when measuring an object?','["Because rulers are usually broken on the edge.","Many rulers have a small blank gap before the actual ''zero'' mark; aligning the object with the physical edge instead of the zero mark will cause an inaccurate measurement.","Because the edge of the ruler is poisonous.","Because starting at the edge makes the object shrink."]',1,'Always line up the object with the printed ''0'' line, not the end of the plastic!','Common mistake: Do not automatically count from the ruler''s physical edge. Some rulers have a small gap before the zero mark.','2026-11-01 07:56:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_029','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'If you want to measure how long a school lesson lasts, which tool and unit should you use?','["A thermometer in degrees Celsius","A balance scale in kilograms","A clock or stopwatch in minutes or hours","A measuring cylinder in millilitres"]',2,'You are measuring the duration of time.','Time: How long an event lasts... Measuring time: Clock... Stopwatch... Units: Minute (min)... Hour (h)... Example: A school lesson may last 45 minutes.','2026-11-01 07:56:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_030','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',5,'Why do scientists use the International System of Units (SI), like Kelvins or Metres?','["To confuse people who don''t study science.","To provide an internationally agreed-upon standard so that scientists in different countries can reliably compare their measurements without confusion.","To make measurements completely secret.","Because SI units are the only ones that work in space."]',1,'If a scientist in Japan uses metres and a scientist in Brazil uses metres, they perfectly understand each other''s work!','Standard units are useful because they allow people in different places to compare measurements reliably. The International System of Units (SI) provides internationally agreed measurement units.','2026-11-01 07:56:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_031','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Critique the common societal conflation of the terms ''Mass'' and ''Weight''.','["They are scientifically identical, so conflating them is correct.","Society colloquially uses ''weight'' (measured in kg) to describe ''mass''. Scientifically, mass (kg) is the invariant scalar quantity of matter, while weight (Newtons) is the variable vector force exerted by gravity on that mass, making the everyday usage technically incorrect.","Society uses Newtons to measure mass, which is wrong.","Mass only exists on Earth, while weight only exists in space."]',1,'Your bathroom scale actually measures the force of gravity (weight) but displays the answer in mass (kg)! That''s a physics mistake!','Everyday language often uses “weight” when referring to kilograms on a bathroom scale. In physics, mass and weight are distinguished carefully. Mass: measured in grams or kilograms. Weight: a gravitational force, measured in newtons.','2026-11-01 07:56:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_032','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Analyze the mathematical logic behind the metric system''s use of prefixes (like milli- and kilo-).','["The prefixes are random words with no mathematical meaning.","The metric system uses a base-10 logarithmic scale. Prefixes systematically denote powers of 10 applied to a base unit (e.g., ''milli-'' is \\\\(10^{-3}\\\\) or 1/1000th, ''kilo-'' is \\\\(10^3\\\\) or 1000 times), allowing for seamless decimal conversions without complex fractions.","The prefixes only apply to measuring temperature.","The prefixes were invented to make math harder."]',1,'Milli always means divide by a thousand; Kilo always means multiply by a thousand!','Important conversions: 10 millimetres = 1 centimetre. 100 centimetres = 1 metre. 1,000 metres = 1 kilometre. 1,000 grams = 1 kilogram.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_033','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Synthesize how the concept of ''Accuracy'' differs from the concept of ''Precision'' (decimal places) in physical measurement.','["Accuracy and precision are exactly the same thing.","A measurement can be highly precise (e.g., 10.999 cm) but completely inaccurate if the true value is 5 cm. Accuracy is proximity to the true value, while precision (decimal places) only indicates the resolution of the measuring instrument.","Accuracy is about decimal places, precision is about the true value.","If a measurement has 5 decimal places, it is guaranteed to be 100% accurate."]',1,'A broken ruler can give you a very precise number (like 12.34 cm), but that number is completely inaccurate because the ruler is broken!','Accuracy describes how close a measurement is to the true or accepted value... Remember that a measurement can never be assumed perfectly accurate just because it has many decimal places.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_034','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Evaluate the physiological and physical reasons why ''non-standard units'' (like a hand span) were abandoned for global trade and science.','["Non-standard units were abandoned because humans stopped having hands.","Because human biology is inherently variable, non-standard units provided no objective baseline. This subjectivity caused critical errors in scientific replication and commercial disputes in trade, necessitating the creation of immutable, universal standard units.","Non-standard units were perfectly accurate but too expensive to use.","Standard units were actually abandoned in favor of hand spans."]',1,'If you buy ''10 hand spans of rope'', a seller with small hands will cheat you!','A non-standard unit is an informal measure, such as hand spans or footsteps... Another person''s hand spans may give a different result. Standard units are useful because they allow people in different places to compare measurements reliably.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_035','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Analyze the relationship between ''Volume'' (\\(cm^3\\)) and ''Capacity'' (mL) as expressions of three-dimensional space.','["Volume measures time, capacity measures length.","They are functionally equivalent expressions of the same physical property (3D spatial occupation). Volume (\\\\(cm^3\\\\)) is typically derived geometrically for solids, while capacity (mL) is typically used for fluid displacement, unified by the direct conversion \\\\(1 cm^3 = 1 mL\\\\).","Volume and capacity are completely unrelated concepts.","Volume only applies to gases, capacity only applies to solids."]',1,'A solid cube that is 1x1x1 cm takes up the exact same amount of space as 1 milliliter of water!','Volume is the amount of three-dimensional space an object or substance occupies. Capacity is how much a container can hold... Useful conversions: 1 cm³ = 1 mL.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_036','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Critique the necessity of the ''Kelvin (K)'' scale in advanced physics compared to Celsius.','["Kelvin is completely useless and only Celsius is used in science.","While Celsius is practical because it is calibrated to the phase changes of water (0° and 100°), Kelvin is an absolute thermodynamic scale starting at Absolute Zero (where molecular motion theoretically stops). This makes Kelvin mathematically essential for complex thermodynamic equations.","Celsius starts at Absolute Zero, making Kelvin redundant.","Kelvin is only used to measure the temperature of the sun."]',1,'Scientists need a temperature scale where ''zero'' actually means ''zero heat energy left''!','Kelvin (K): the standard temperature unit in the International System of Units (SI), especially in scientific work. Degrees Celsius (°C): widely used in daily life...','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_037','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Synthesize the procedure required to accurately measure an object''s length using a ruler that has a broken or unreadable ''zero'' mark.','["It is impossible; the ruler must be thrown away.","You can align the object''s starting edge with any clearly marked whole integer (e.g., the 2 cm mark). You then read the endpoint and subtract the starting integer from the ending integer to calculate the absolute length.","You just align it with the broken edge and guess the length.","You must multiply the ending number by two."]',1,'If your ruler is broken at the end, just start measuring from the ''5 cm'' line and subtract 5 at the end!','If an object starts at the 2 cm mark and ends at the 9 cm mark, its length is: 9 - 2 = 7 cm.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_038','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Evaluate the importance of the instruction: ''Repeat measurements when practical.''','["Repeating measurements is a waste of time because the first try is always perfect.","Repeating measurements is a fundamental safeguard against random human error (like misreading a scale) or instrument anomaly. Averaging multiple trials increases the statistical reliability and accuracy of the final recorded data.","Repeating measurements actually makes the data less accurate.","You should only repeat a measurement if you don''t like the first answer."]',1,'Even a good scientist can accidentally look at a ruler sideways once; checking three times proves you are right!','To improve measurement quality: ... Repeat measurements when practical.','2026-11-01 07:56:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_039','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Analyze why defining a ''Unit'' is mathematically critical to the definition of ''Measurement''.','["Units are just optional decorations for numbers.","A mathematical integer is purely abstract. In physics, a measurement represents a physical reality; the ''Unit'' acts as the essential scalar multiplier that translates an abstract number into a concrete, quantifiable physical dimension.","Units prove that numbers do not exist.","Measurement only requires a color, not a unit."]',1,'The number 10 means nothing in physics unless you tell me if it is 10 kilograms or 10 seconds!','Measurement is the process of finding the size, amount or value of something by comparing it with a unit... Writing only ''15'' does not tell us whether we mean 15 centimetres, 15 seconds... The unit makes the measurement meaningful.','2026-11-01 07:56:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_040','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Synthesize how the concept of ''Gravity'' bridges the definitions of Mass and Weight.','["Gravity has no effect on weight, only on mass.","Mass is the intrinsic property of matter resisting acceleration. Gravity is an external acceleration field. Weight is the mathematical product of an object''s intrinsic Mass interacting with the localized field of Gravity (\\\\(W = mg\\\\)).","Gravity destroys mass completely.","Gravity is a type of measuring instrument."]',1,'Your mass is the ''stuff'' you are made of; gravity is the invisible hand pulling that ''stuff'' down. Together, they create your weight!','Mass is a measure of how much matter an object contains. Weight is the force with which gravity pulls an object... Weight is a force caused by gravity.','2026-11-01 07:56:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_041','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Critique the use of a ''Stopwatch'' versus a standard ''Clock'' in a physics experiment calculating speed.','["A clock is always superior for measuring high-speed physics.","A standard clock measures absolute time of day with low resolution (minutes/seconds). A stopwatch measures relative elapsed time (duration) with high resolution (milliseconds), which is strictly necessary for calculating accurate velocities over short experimental intervals.","A stopwatch measures the time of day, a clock measures duration.","There is no difference; both are equally accurate for speed."]',1,'You can''t use a wall clock to measure a race that takes 2.5 seconds!','Clock: shows the time of day. Stopwatch: measures the duration of an activity. To measure how long it takes a toy car to travel... start a stopwatch when the car is released...','2026-11-01 07:56:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_042','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Evaluate the physical mechanics of why water boils at 100°C under *normal atmospheric pressure*, implying a change at different pressures.','["Water always boils at 100°C regardless of pressure.","Boiling occurs when a liquid''s vapor pressure equals the surrounding atmospheric pressure. Therefore, if atmospheric pressure drops (e.g., at high altitudes), water requires less thermal energy to boil, meaning it will boil at a temperature significantly lower than 100°C.","Pressure forces water to freeze at 100°C.","Water boiling has nothing to do with temperature."]',1,'If you climb to the top of Mount Everest, water boils faster because the air is thinner!','Water boils at approximately 100°C under normal atmospheric pressure. (Synthesis: The qualifier ''under normal pressure'' indicates that pressure affects the boiling point).','2026-11-01 07:56:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_043','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Analyze the error potential of not allowing an instrument (like a balance scale) to ''start at zero'' (tare).','["It has no effect on the measurement.","Failing to zero or ''tare'' an instrument introduces a systematic zero error. The instrument will continuously add its uncalibrated baseline offset to every subsequent reading, guaranteeing that every single measurement recorded is mathematically inaccurate.","It makes the measurement perfectly precise.","It only affects the measurement of liquids, not solids."]',1,'If your scale says you weigh 5kg before you even step on it, your final weight will be 5kg too high!','To improve measurement quality: ... Check that the instrument starts at zero when appropriate.','2026-11-01 07:56:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_044','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Synthesize how the concept of ''Temperature'' relates to microscopic kinetic energy.','["Temperature is a measure of how loud molecules are.","Temperature is not a measure of ''heat'' as a substance, but rather a macroscopic metric quantifying the average microscopic kinetic energy (speed and vibration) of the particles within a substance.","Temperature measures how heavy particles are.","Temperature proves that particles do not move."]',1,'When you measure temperature, you are actually measuring how fast the tiny invisible pieces of matter are vibrating!','Temperature tells us how hot or cold something is. It is related to the average motion of the particles in a substance.','2026-11-01 07:56:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_measure_global_045','Physics','Measurement','Topic 2: Measurement and Physical Quantities','Primary',10,'Critique the historical evolution from local, arbitrary units (like a foot) to the International System of Units (SI).','["Local units were superior because everyone liked them better.","Local units were biologically or culturally derived (e.g., a king''s foot length), causing localized inconsistencies. The SI system represents an epistemological shift toward defining units using immutable, universal physical constants (e.g., the speed of light) to ensure absolute global standardization.","The SI system was invented to make trade impossible.","Local units were perfectly consistent across every country."]',1,'A ''foot'' used to be the size of the actual king''s foot. When the king died, the measurement changed! The SI system fixed this.','Standard units are useful because they allow people in different places to compare measurements reliably. The International System of Units (SI) provides internationally agreed measurement units.','2026-11-01 07:56:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_001','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is ''matter''?','["Only things that are heavy","Anything that has mass and occupies space","Only living things","Only things that you can see"]',1,'Everything around you, including the air, is matter.','Matter is anything that has mass and occupies space.','2026-11-01 07:56:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_002','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'Which of these is NOT an example of matter?','["Water","Air","Light","A stone"]',2,'You cannot weigh a beam of light.','Light and sound are not matter. They transfer energy rather than being substances that have mass and occupy space...','2026-11-01 07:56:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_003','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is a ''solid''?','["A state of matter that takes the shape of its container","A state of matter with a fixed shape and a fixed volume","A state of matter that spreads out to fill a room","A state of matter with no mass"]',1,'A rock is a solid because its shape does not change easily.','Solids usually have a fixed shape and a fixed volume.','2026-11-01 07:56:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_004','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is a ''liquid''?','["A state of matter with a fixed shape","A state of matter with no volume","A state of matter with a fixed volume that takes the shape of its container","A state of matter that is always frozen"]',2,'Water is a liquid; it changes shape when you pour it into a cup.','Liquids have a fixed volume but take the shape of their container.','2026-11-01 07:56:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_005','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is a ''gas''?','["A state of matter that does not have a fixed shape or fixed volume","A state of matter that is always heavy","A state of matter that is frozen","A state of matter that only exists in space"]',0,'Air is a gas.','Gases do not have a fixed shape or a fixed volume. They spread out to fill the available space in a container.','2026-11-01 07:56:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_006','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What property describes how easily a material bends without breaking?','["Hardness","Strength","Flexibility","Absorbency"]',2,'A rubber band is flexible.','Flexibility: how easily a material bends without breaking.','2026-11-01 07:56:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_007','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What property describes how well a material resists scratching or being dented?','["Strength","Hardness","Transparency","Flexibility"]',1,'A diamond is very hard.','Hardness: how well a material resists scratching or being dented.','2026-11-01 07:56:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_008','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What does ''transparent'' mean?','["Allows some light through, making things look blurry","Blocks all light from passing through","Allows most light to pass through so objects can be seen clearly","Absorbs all water"]',2,'Clean window glass is transparent.','Transparent: Allows most light to pass through so objects can be seen clearly.','2026-11-01 07:56:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_009','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What does ''opaque'' mean?','["Allows most light to pass through","Blocks visible light from passing through","Allows only a little bit of light to pass through","Is completely invisible"]',1,'A wooden door is opaque.','Opaque: Does not allow light to pass through in the ordinary visible-light sense.','2026-11-01 07:56:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_010','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What does ''translucent'' mean?','["Blocks all light from passing through","Allows some light through, but objects on the other side cannot be seen clearly","Allows all light to pass through perfectly","Reflects all light"]',1,'Frosted glass is translucent.','Translucent: Allows some light through, but objects on the other side cannot be seen clearly.','2026-11-01 07:56:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_011','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is ''melting''?','["A liquid changing into a solid","A gas changing into a liquid","A solid changing into a liquid","A liquid changing into a gas"]',2,'Ice turning into water is melting.','Melting occurs when a solid changes into a liquid.','2026-11-01 07:56:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_012','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is ''freezing''?','["A solid changing into a gas","A gas changing into a liquid","A liquid changing into a solid","A liquid changing into a gas"]',2,'Water turning into ice is freezing.','Freezing occurs when a liquid changes into a solid.','2026-11-01 07:56:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_013','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is ''evaporation''?','["A solid changing into a liquid","A liquid changing into a gas at its surface","A gas changing into a solid","A gas changing into a liquid"]',1,'A puddle drying up in the sun is evaporation.','Evaporation occurs when particles at the surface of a liquid escape into the gas state.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_014','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What is ''condensation''?','["A liquid changing into a solid","A solid changing into a gas","A gas changing into a liquid","A liquid changing into a gas"]',2,'Water droplets forming on a cold glass is condensation.','Condensation occurs when a gas changes into a liquid.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_015','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',1,'What property describes how readily a material takes in liquid?','["Absorbency","Conductivity","Flexibility","Hardness"]',0,'A sponge has high absorbency.','Absorbency: how readily a material takes in liquid.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_016','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'How does the balloon experiment prove that ''air'' is matter?','["It shows that air is invisible.","When air is blown into a balloon, the balloon expands, proving that the air occupies physical space (volume) inside the balloon.","It proves that air has no mass.","It shows that air is actually a liquid."]',1,'Matter is anything that takes up space; the balloon gets bigger because space is being filled!','When air enters a balloon, the balloon expands because the air occupies space... Air may be difficult to see, but it is matter.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_017','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why is an empty plastic bottle hard to squeeze when the cap is screwed on tight?','["Because plastic gets harder over time.","Because the bottle is not actually empty; it is full of air (a gas) which occupies space and pushes back when compressed.","Because closing the cap turns the air into a solid.","Because squeezing a bottle creates a vacuum."]',1,'The air inside pushes against your hands!','You may find that squeezing the closed bottle is more difficult because the air inside cannot escape easily. This helps demonstrate that air occupies space.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_018','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'How do the particles in a ''solid'' behave compared to a ''gas''?','["Particles in a solid fly around the room, while gas particles stay perfectly still.","Particles in a solid are closely packed and only vibrate in place, while gas particles spread out freely to fill the available space.","Particles in a solid are completely invisible.","Both solids and gases have particles that move at the exact same speed."]',1,'Solid particles are locked together; gas particles are wild and free!','Solids... Their particles are closely packed and vibrate around their positions. Gases... They spread out to fill the available space...','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_019','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why does a solid iron nail usually sink in water while a massive steel ship floats?','["Because the ship is lighter than the nail.","While steel is denser than water, the ship is shaped with a hollow hull full of air, making the *average* density of the entire ship lower than water.","Because the ship has no mass.","Because the iron nail is actually a liquid."]',1,'A solid block of steel sinks, but a steel bowl floats because of the air inside it!','The ship''s hollow hull contains a large amount of air, making the average density of the entire ship low enough for it to float.','2026-11-01 07:56:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_020','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'What causes water droplets to form on the outside of a cold glass on a warm day?','["The glass is melting.","Water vapor (a gas) in the warm air cools down when it touches the cold glass, condensing into liquid water droplets.","The water inside the glass leaks through the solid walls.","The ice inside the glass jumps out."]',1,'The water comes from the air, not from inside the glass!','Condensation occurs when a gas changes into a liquid. Example: Water droplets form on the outside of a cold glass when water vapour in the surrounding air cools.','2026-11-01 07:56:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_021','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'How is ''Hardness'' physically different from ''Strength'' when describing a material like glass?','["There is no difference; they mean the same thing.","Glass is very hard (it resists being scratched by a knife), but it is not strong (it breaks easily if dropped or hit with a hammer).","Glass is very strong but not hard.","Hardness means a material bends, strength means it absorbs water."]',1,'You can''t easily scratch a window, but you can easily smash it!','Hardness is not the same as strength: a hard material can still be brittle... Hardness: how well a material resists scratching... Strength: how well a material withstands forces without breaking.','2026-11-01 07:56:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_022','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why is ''rubber'' an excellent material for making a bicycle tyre?','["Because rubber is completely rigid.","Because rubber is flexible (it bends to grip the road) and elastic (it returns to its shape after bumping over a rock).","Because rubber absorbs water perfectly.","Because rubber is harder than steel."]',1,'A tyre needs to bend when it hits a bump, and then bounce back!','Rubber: Flexible and elastic... Common use: Rubber bands and tyres.','2026-11-01 07:56:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_023','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'If you want to create a ''fair test'' to see which paper towel absorbs the most water, what must you do?','["Test each paper towel with a different liquid.","Use pieces of paper towel that are the exact same size and test them with the exact same amount of water.","Change the size of the paper towel and the amount of water at the same time.","Pour all the water on the floor first."]',1,'If one towel is huge and the other is tiny, the test isn''t fair!','Make it a fair test: Keep the material sizes, water amounts, soaking time and testing method as similar as possible.','2026-11-01 07:56:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_024','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'What does it mean for a material to be a ''good electrical conductor'', like copper?','["It blocks electricity completely.","It allows electricity to pass through it very easily, making it perfect for the wiring inside homes and electronics.","It turns electricity into water.","It is highly absorbent."]',1,'Electricity travels through copper like water through a pipe!','Conductivity: how well a material allows heat or electricity to pass through it. Copper: Good electrical conductor. Common use: Electrical wiring.','2026-11-01 07:56:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_025','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why is ice placed at exactly 0°C considered a ''change of state'' point?','["Because it catches on fire.","At 0°C under normal pressure, water can exist as both a solid and a liquid; it is the exact temperature where ice melts into water, and water freezes into ice.","Because it instantly turns into a gas.","Because water has no temperature."]',1,'0°C is the magic number where water switches between solid and liquid!','Ice melts at approximately 0°C... Water freezes at approximately 0°C... During melting or freezing, the temperature of a pure substance can remain at its change-of-state temperature...','2026-11-01 07:56:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_026','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why does a puddle of water dry up on a sunny day even though the water is not boiling (not at 100°C)?','["Because the sun drinks the water.","Because evaporation occurs at the *surface* of the liquid, allowing some water particles to escape into the air as a gas even below the boiling point.","Because the water sinks into the center of the Earth.","Because the puddle freezes."]',1,'The sun slowly pulls the top layer of water molecules into the air!','Evaporation occurs when particles at the surface of a liquid escape into the gas state... Water can evaporate even when it is below its boiling point.','2026-11-01 07:56:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_027','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'If a material is ''elastic'', what happens after you pull on it?','["It shatters into tiny pieces.","It returns towards its original shape after the stretching force is removed.","It stays stretched out forever.","It turns into a liquid."]',1,'Think of a rubber band snapping back!','Elasticity: how well a material returns to its original shape after being stretched or compressed.','2026-11-01 07:56:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_028','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'Why are bathroom windows often made of ''translucent'' glass instead of ''transparent'' glass?','["Because transparent glass breaks too easily.","Translucent glass lets some light in to brighten the room, but scatters the light so people outside cannot see a clear image, protecting privacy.","Because translucent glass is completely black.","Because transparent glass absorbs water."]',1,'You want sunlight in the bathroom, but you don''t want the neighbors looking in!','Translucent: Allows some light through, but objects on the other side cannot be seen clearly. Examples: frosted glass...','2026-11-01 07:56:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_029','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'How does ''density'' determine whether a solid object will float or sink in water?','["By the object''s color.","If the object''s average density is lower than the water''s density, it floats. If its density is higher, it sinks.","By how loud the object is.","By the time of day."]',1,'A rock sinks because it is denser than water; wood floats because it is less dense!','Objects with an average density lower than water generally float. Objects with an average density greater than water generally sink.','2026-11-01 07:56:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_030','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',5,'If you freeze a cup of liquid water, what is changing?','["The amount of mass in the cup.","The state of the matter (from liquid to solid) due to the loss of thermal energy.","The water turns into air.","The water turns into light."]',1,'The ''stuff'' is exactly the same, it is just arranged differently because it is cold!','Matter can change from one state to another when it gains or loses thermal energy. Freezing occurs when a liquid changes into a solid... when it loses enough thermal energy...','2026-11-01 07:56:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_031','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Critique the assertion that ''gases have no mass'' based on the definition of matter.','["The assertion is true; gases are weightless.","The assertion is fundamentally false. Because gases are defined as a state of matter (like air in a balloon), and matter by definition possesses mass and occupies space, gases inherently have mass, even though it is difficult to perceive without precision instruments.","The assertion is true; gases do not occupy space.","Gases only have mass when they are frozen."]',1,'A balloon full of air weighs slightly more than a completely empty balloon!','Matter is anything that has mass and occupies space... Gases... Examples: air... (Synthesis: Since air is a gas, and gas is matter, gas must have mass).','2026-11-01 07:56:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_032','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Analyze the kinetic particle theory: How does the addition of thermal energy (heat) transition a substance from a solid to a liquid?','["Heat makes the particles stop moving entirely.","Thermal energy increases the kinetic energy (vibration) of the closely packed particles in a solid. When the energy overcomes the intermolecular forces holding them in a rigid lattice, the particles break free to slide past one another, transitioning into a liquid (melting).","Heat causes the particles to multiply and create new matter.","Heat turns the solid directly into light energy."]',1,'Heat is just energy that makes the tiny particles shake so fast they break apart!','Solids... particles are closely packed and vibrate... Liquids... particles can move past one another. Matter can change from one state to another when it gains or loses thermal energy.','2026-11-01 07:56:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_033','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Synthesize how the concept of ''average density'' (mass per unit volume) resolves the paradox of a heavy steel ship floating.','["The ship floats because steel is actually less dense than water.","While the raw material (steel) has a higher density than water, shaping it into a hollow hull traps a massive volume of air (which has very low density). The combined mass of the steel and air divided by the vast displaced volume results in an *average* density lower than water.","The ship floats because gravity stops working on the ocean.","The ship floats because the ocean water is turned into solid ice."]',1,'Density = Mass / Volume. A ship has a lot of mass, but a HUGE amount of volume, making the overall fraction very small!','A ship is made from materials such as steel, which is denser than water. However, the ship''s hollow hull contains a large amount of air, making the average density of the entire ship low enough for it to float.','2026-11-01 07:56:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_034','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Evaluate the physical difference between ''Evaporation'' and ''Boiling'' in a liquid.','["They are exactly the same physical process.","Evaporation is a surface-level phenomenon that can occur at any temperature below the boiling point as individual particles gain enough kinetic energy to escape. Boiling is a bulk phenomenon occurring uniformly throughout the liquid only when its vapor pressure equals atmospheric pressure.","Evaporation only happens to solids.","Boiling only happens at the surface of a liquid."]',1,'A puddle dries up (evaporates) on a warm day without ever bubbling (boiling)!','Evaporation occurs when particles at the surface of a liquid escape into the gas state... Water can evaporate even when it is below its boiling point.','2026-11-01 07:56:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_035','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Analyze why the ''temperature of a pure substance can remain at its change-of-state temperature'' during melting (e.g., staying at 0°C).','["Because the thermometer breaks.","During a phase change (like melting), the thermal energy being added does not increase the kinetic energy (temperature) of the particles. Instead, the energy is entirely consumed as ''latent heat'' to break the intermolecular bonds holding the solid lattice together.","Because the ice absorbs all the heat and destroys it.","Because water cannot go above 0°C."]',1,'While the ice is melting, all the heat goes into breaking the ice apart, not making the water warmer!','During melting or freezing, the temperature of a pure substance can remain at its change-of-state temperature while the change is taking place.','2026-11-01 07:56:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_036','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Synthesize the relationship between ''Condensation'' and the formation of the global ''Water Cycle'' (clouds).','["Condensation prevents clouds from forming.","As solar radiation evaporates water into vapor, the vapor rises into the atmosphere where temperatures drop. This loss of thermal energy forces the gaseous vapor to undergo condensation, transitioning back into liquid micro-droplets that aggregate to form visible clouds.","Condensation causes clouds to fall instantly as solid ice.","The water cycle relies only on evaporation, not condensation."]',1,'Clouds are literally just floating lakes of condensed water droplets!','Condensation occurs when a gas changes into a liquid... Water vapour rises and cools, and condensation forms tiny droplets in clouds.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_037','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Critique the classification of materials strictly as ''Solids, Liquids, or Gases''.','["The classification is a flawless law of nature.","While useful for basic physics, the strict tripartite classification is an oversimplification. Many complex materials (like non-Newtonian fluids, gels, foams, or plasma) exhibit hybrid properties that defy strict categorization into a single classical state.","Materials are only classified by their color, not state.","Solids and liquids are the exact same state of matter."]',1,'Toothpaste doesn''t flow like a liquid, but it isn''t hard like a solid!','Note: These are the typical properties of solids, liquids and gases at everyday conditions. Some materials, such as gels and foams, behave in more complex ways.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_038','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Evaluate the necessity of ''Variable Control'' in the material Absorbency Test.','["Variable control makes the test completely unfair.","To empirically prove which material is intrinsically most absorbent, the scientist must isolate the material type as the sole independent variable. If material size or water volume fluctuates (uncontrolled variables), the resulting data cannot mathematically isolate the cause of the absorbency.","Variable control means using a different liquid for every test.","You only need to control variables if you use a microscope."]',1,'If the sponge is 10 times bigger than the paper towel, it will obviously hold more water, ruining the test!','Make it a fair test: Keep the material sizes, water amounts, soaking time and testing method as similar as possible.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_039','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Analyze the mechanical property of ''Elasticity'' versus ''Flexibility'' using a rubber band and a piece of wire.','["They are the exact same property.","Both materials possess Flexibility (they bend without breaking). However, only the rubber band possesses high Elasticity—the mechanical ability to store potential energy when deformed and subsequently exert a restorative force to return to its original geometric shape.","The wire is elastic, the rubber band is not.","Neither material is flexible."]',1,'You can bend a wire (flexible), but it stays bent. A rubber band bounces back (elastic)!','Flexibility: how easily a material bends without breaking... Elasticity: how well a material returns to its original shape after being stretched or compressed.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_040','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Synthesize why ''Hardness'' and ''Strength'' are often inversely correlated in materials like Glass and Steel.','["Hardness and strength always increase together.","Glass is extremely hard (resistant to surface scratching) but possesses low tensile strength and high brittleness (shatters under impact). Conversely, structural steel is softer (can be scratched) but possesses immense tensile strength and malleability, allowing it to absorb massive impact forces without catastrophic failure.","Glass is stronger than steel.","Hardness prevents any material from breaking."]',1,'A diamond is the hardest natural material, but you can smash it with a steel hammer!','Hardness is not the same as strength: a hard material can still be brittle... Hardness: how well a material resists scratching... Strength: how well a material withstands forces without breaking.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_041','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Critique the everyday use of the term ''empty'' when describing a container (like a bottle) in the context of physics.','["The term is perfectly accurate in all contexts.","In physics, a container on Earth is never truly ''empty'' unless a vacuum is artificially created. An ''empty'' bottle is actually completely filled with atmospheric gases (air), which possess mass and volume and will exert fluid resistance if compressed.","An empty bottle contains liquid water.","An empty bottle is full of solid rocks."]',1,'You aren''t squeezing an empty bottle; you are squeezing a bottle full of air!','Push an empty plastic bottle gently... Then close the opening and try again. You may find that squeezing the closed bottle is more difficult because the air inside cannot escape... air occupies space.','2026-11-01 07:56:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_042','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Analyze how ''Density'' differs from ''Mass'' when determining buoyancy (floating).','["They are the exact same concept.","Mass is the absolute amount of matter in an object. Density is a ratio of that mass divided by the object''s spatial volume. Buoyancy is dictated strictly by the comparative density of the object versus the fluid, meaning a massive object can float if its volume is sufficiently large.","Mass determines floating; density determines sinking.","Density only applies to gases."]',1,'A 10,000-ton steel ship floats, but a 10-gram steel marble sinks! It''s about how much space the mass takes up.','Density describes how much mass is contained in a given volume... Objects with an average density lower than water generally float.','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_043','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Synthesize how the concept of ''Displacement'' interacts with the shape of a ship''s hull to allow it to float.','["Displacement means the ship destroys the water.","According to Archimedes'' principle, a ship will float if the weight of the water it pushes out of the way (displaces) equals the total weight of the ship. A wide, hollow hull maximizes the volume of water displaced, generating a sufficient upward buoyant force to counteract gravity.","Displacement causes the ship to sink faster.","A ship''s hull is shaped to minimize displacement."]',1,'The ship pushes down, and the displaced water pushes back up!','The shape of the hull also allows the ship to displace enough water to support its weight.','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_044','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Evaluate the physical mechanics of ''Freezing'' at the molecular level.','["Freezing causes molecules to move faster.","As a liquid loses thermal energy to the environment, the kinetic energy of its constituent particles decreases. When the energy falls below a critical threshold (the freezing point), intermolecular attractive forces overpower the kinetic motion, locking the particles into a rigid, fixed geometric lattice (a solid).","Freezing turns the molecules into a gas.","Freezing is caused by adding thermal energy."]',1,'Taking away heat slows the molecules down until they get stuck together!','Matter can change from one state to another when it gains or loses thermal energy... Freezing occurs when a liquid changes into a solid... when it loses enough thermal energy...','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_matter_global_045','Physics','Matter and Materials','Topic 3: Matter and Materials','Primary',10,'Analyze the electromagnetic property of ''Transparency'' versus ''Opacity''.','["Transparency means the material reflects all light.","Transparency occurs when a material''s atomic structure does not absorb or scatter photons of visible light, allowing the electromagnetic waves to transmit through the material unimpeded. Opacity occurs when the atomic structure entirely absorbs or reflects the visible photons, blocking transmission.","Opacity means the material allows all light to pass through.","Transparency is only possible in liquids."]',1,'Glass lets the light waves pass straight through, but a wooden door absorbs them!','Transparent: Allows most light to pass through so objects can be seen clearly... Opaque: Does not allow light to pass through in the ordinary visible-light sense.','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_001','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What does it mean if an object is in ''motion''?','["It is changing color","Its position changes relative to a reference point over time","It is getting heavier","It is staying perfectly still"]',1,'It means the object is moving from one place to another.','An object is in motion when its position changes relative to a reference point over time.','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_002','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What is a ''force'' in physics?','["A type of speed","A push or a pull acting on an object","A measurement of time","A type of light"]',1,'Kicking a ball or opening a drawer are examples.','A force is a push or a pull acting on an object.','2026-11-01 07:56:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_003','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'Which of the following is an example of a ''push'' force?','["Pulling a suitcase toward you","Pushing a swing away from you","Opening a drawer","Dropping a ball"]',1,'You are moving the object away from your body.','Pushing a swing can make it move away from you.','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_004','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'Which of the following is an example of a ''pull'' force?','["Kicking a football","Pressing a button","Pulling a drawer to open it","Pushing a toy car"]',2,'You are moving the object toward your body.','Pulling a drawer opens it.','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_005','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What does ''distance'' measure?','["How heavy an object is","How far an object travels along its path","How fast an object is moving","The amount of matter in an object"]',1,'You measure it in meters or kilometers.','Distance describes how far an object travels along its path.','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_006','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What does ''speed'' tell us?','["The direction a car is turning","How much distance an object travels in a given amount of time","How heavy a bicycle is","How strong gravity is"]',1,'It is calculated by dividing distance by time.','Speed tells us how much distance an object travels in a given amount of time.','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_007','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What is ''gravity''?','["A force that pushes things up into the sky","An attractive force between objects with mass that pulls things towards Earth''s centre","A force that stops things from moving","A type of weather"]',1,'It is why things fall down when you drop them.','Gravity is an attractive force between objects that have mass. Earth''s gravity pulls objects towards Earth''s centre...','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_008','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What is ''friction''?','["A force that pulls objects toward the center of the Earth","A force that resists sliding or movement between surfaces that are touching","A force that makes things float","A force that pushes objects away from each other"]',1,'It makes it hard to drag a heavy box across a rough carpet.','Friction is a force that resists sliding or movement between surfaces that are touching.','2026-11-01 07:56:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_009','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What is ''air resistance''?','["A force that makes you breathe faster","A force that opposes an object''s movement through the air","A force that pulls you to the ground","A force that creates wind"]',1,'It is why a feather falls slower than a rock.','Air resistance: A force that opposes an object''s movement through air.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_010','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'If a child walks 5 metres forward, what distance have they travelled?','["0 metres","5 metres","10 metres","1 metre"]',1,'Distance is just how far they walked.','Total distance travelled: 5 m.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_011','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What unit is used to measure speed in the example given in the lesson?','["Kilograms (kg)","Metres per second (m/s)","Centimetres (cm)","Seconds (s)"]',1,'It tells you how many meters the object moved in one second.','The unit m/s means metres per second.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_012','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What happens when ''balanced forces'' act on an object?','["The object flies into the air.","They cancel one another out, so the overall force is zero and the motion does not change.","The object spins very fast.","The object breaks into pieces."]',1,'It is like a tied game of tug-of-war where nobody moves.','Balanced forces cancel one another out, so the overall force (the resultant force) is zero. They do not change the object''s motion.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_013','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What happens when ''unbalanced forces'' act on an object?','["The object turns invisible.","They produce a non-zero resultant force and can change the object''s motion.","The object stops moving forever.","The object loses all its mass."]',1,'One side pulls harder, making the object move.','Unbalanced forces produce a non-zero resultant force and can change an object''s motion.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_014','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'How do you calculate speed?','["Add distance and time together","Multiply distance by time","Divide distance by time","Subtract time from distance"]',2,'If you travel 10 meters in 2 seconds, your speed is 5 m/s.','Speed = Distance / Time.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_015','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',1,'What is ''position'' in physics?','["The speed of a moving car","The location of an object relative to a reference point","The total distance travelled","The force of a push"]',1,'It describes exactly where something is.','Position: The location of an object relative to a reference point.','2026-11-01 07:56:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_016','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'If a child walks 5 metres forward and then 3 metres backward, why is their ''distance travelled'' 8 metres, but their ''position'' is only 2 metres from the start?','["Because the child shrank while walking.","Because distance measures the total path walked (5+3=8), but position only measures where they ended up compared to where they started (5-3=2).","Because distance and position are the exact same thing.","Because the 3 metres backward don''t count."]',1,'Distance is every step you took; position is just where you are right now!','If the child walks 5 metres forward and then 3 metres back... the total distance is still 8 metres, but the final position is only 2 metres from the starting point.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_017','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'If a toy car travels 12 metres in 3 seconds, what is its average speed?','["4 m/s","15 m/s","36 m/s","9 m/s"]',0,'Divide the distance (12) by the time (3).','Speed = Distance / Time. 12 / 3 = 4 m/s.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_018','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'If Car A travels 10 metres in 5 seconds, and Car B travels 10 metres in 2 seconds, which car has the greater average speed?','["Car A","Car B","They have the same speed","Neither car is moving"]',1,'The car that finishes the race in less time is the faster car!','Car A speed: 10/5 = 2 m/s. Car B speed: 10/2 = 5 m/s. If two toy cars travel the same distance, the car that takes less time has the greater average speed.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_019','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'How does ''friction'' act as a helpful force when you ride a bicycle?','["It makes the bicycle completely weightless.","Friction between the tyres and the road helps the bicycle grip the surface so it doesn''t slide, and friction in the brakes allows you to stop safely.","It pushes the bicycle forward without pedaling.","It turns the wheels into squares."]',1,'Without friction, riding a bike would be like riding on smooth, slippery ice!','Helpful friction: It helps our shoes grip the ground... It allows bicycle brakes to slow the wheels.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_020','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'Why might a toy car roll farther on a smooth wooden floor than on a rough carpet?','["Because the carpet is afraid of the car.","Because the rough carpet creates more friction, which resists the sliding motion and slows the car down much faster than the smooth floor.","Because the smooth floor has no gravity.","Because the toy car is too heavy for the carpet."]',1,'Rough surfaces grab onto the wheels and slow them down!','A toy car generally rolls farther on a smooth, firm surface than on a rough carpet because the carpet usually creates more resistance to rolling.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_021','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'What does it mean when a scientist says an object is in ''circular motion''?','["It is moving in a perfectly straight line.","It is rotating or moving around a central point or axle, like a turning wheel.","It is moving back and forth like a swing.","It is standing perfectly still."]',1,'Think of a merry-go-round or a bicycle wheel spinning.','Circular motion: a wheel rotating around its axle.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_022','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'If two people are playing tug-of-war and pulling the rope with the exact same amount of force in opposite directions, what happens?','["The rope breaks instantly.","The forces are balanced, the resultant force is zero, and the rope does not move in either direction.","The rope flies up into the air.","One person falls over immediately."]',1,'If both sides pull equally, it''s a tie and nobody moves!','Balanced forces: Two people pull a box [or rope] in opposite directions with equal forces. If the forces balance, the resultant force is zero. They do not change the object''s motion.','2026-11-01 07:56:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_023','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'If a football is rolling across the grass, how could an ''unbalanced force'' change its motion?','["By making the grass grow faster.","A player kicking it from the side (applying a force) would change its direction, or friction from the grass would slow its speed.","By freezing the ball into solid ice.","An unbalanced force cannot change the ball''s motion."]',1,'A kick adds a new force that changes where the ball is going!','Forces can cause several effects: Start a stationary object moving... Increase or decrease speed. Change the direction of motion.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_024','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'Why is ''gravity'' essential for the Earth''s position in space?','["Because gravity makes the Earth flat.","Gravity is the attractive force that keeps the Earth in its orbit revolving around the Sun, and keeps the Moon in orbit around the Earth.","Because gravity pushes the Sun away.","Gravity is not important in space."]',1,'Without the Sun''s gravity, the Earth would float away into deep space!','Gravity also keeps the Moon in orbit around Earth and Earth in orbit around the Sun.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_025','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'In a science experiment testing ramp height, why MUST you release the toy car without pushing it?','["Because pushing the car makes a loud noise.","Because pushing it adds an extra, uncontrolled force (an extra variable) that ruins the ''fair test'' by changing the car''s starting speed.","Because pushing the car will break the ramp.","Because you are only allowed to push the car on Tuesdays."]',1,'If you push it hard on the low ramp, it might go further than on the high ramp, ruining your test!','Release it without pushing... Make it a fair test: Keep the car, ramp surface, starting point and floor surface the same. Change only the ramp height.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_026','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'How can a force change an object''s ''shape'' instead of its motion?','["By making the object invisible.","If you apply a force to a soft or elastic object, like squeezing a sponge, the push or pull will temporarily or permanently alter its physical shape.","Forces can never change an object''s shape.","By painting the object a different color."]',1,'Think about squishing a piece of clay in your hand!','Forces can cause several effects: ... Change an object''s shape. For example, squeezing a soft sponge changes its shape.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_027','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'Why do we need a ''reference point'' to determine if an object is in motion?','["Because a reference point gives you the temperature.","Because motion is relative; you can only tell a bicycle is moving if you compare its changing position to something stationary, like a tree.","Because a reference point stops the object from moving.","Because reference points are the only things that move."]',1,'If you are in a train with no windows, you can''t tell you are moving because you have no outside reference point to look at!','An object is in motion when its position changes relative to a reference point over time. For example, a bicycle moving past a tree is in motion because its position changes relative to the tree.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_028','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'What happens if you apply a strong force in the exact opposite direction that an object is moving?','["The object will speed up.","The opposing force will cause the object to slow down and eventually stop.","The object will turn into a gas.","The force will have no effect."]',1,'If a ball is rolling toward you, and you push back against it, it stops!','Applying a force opposite to motion can slow an object.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_029','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'How does ''air resistance'' affect a falling feather compared to a falling stone?','["It makes the feather fall faster than the stone.","Air resistance pushes up against falling objects; because the feather is wide and light, the air catches it and slows it down much more than the heavy, compact stone.","It turns the feather into a stone.","Air resistance only affects objects moving upward."]',1,'The feather floats on the air, while the stone cuts right through it!','In everyday situations, air resistance can make a feather fall more slowly than a stone.','2026-11-01 07:56:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_030','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',5,'Why does a rolling football eventually slow down and stop even if no player touches it?','["Because it runs out of battery power.","Because invisible forces, specifically friction from the grass and air resistance, constantly apply an opposing pull against the ball''s motion until it stops.","Because gravity pulls it into the center of the Earth.","Because the ball decides it is tired."]',1,'The grass rubs against the ball, slowing it down a little bit every second!','Friction and air resistance gradually slow it down.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_031','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Analyze the statement: ''Balanced forces do not necessarily mean an object is stationary.''','["The statement is false; balanced forces always mean the object is completely still.","According to Newton''s First Law, if the resultant force is zero (balanced), an object''s motion does not change. Therefore, an object already moving at a constant velocity in a straight line will continue moving indefinitely under balanced forces.","The statement means balanced forces cause an object to accelerate rapidly.","Balanced forces only apply to liquids."]',1,'If you are sliding on perfectly smooth ice and nothing pushes or pulls you, you will slide forward forever!','An important point: balanced forces do not necessarily mean an object is stationary. A moving object can continue at a constant velocity when the resultant force is zero.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_032','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Critique the conceptual difference between ''Distance'' (a scalar quantity) and ''Displacement'' (change in position).','["They are mathematically identical in all situations.","Distance measures the total length of the path traveled (scalar), regardless of direction. Displacement (position change) is a vector measuring the shortest straight line from the start to the end point; thus, walking in a complete circle results in high distance but zero displacement.","Distance is measured in kilograms, displacement is measured in seconds.","Distance only applies to cars, displacement only applies to airplanes."]',1,'If you run around a track and end exactly where you started, your distance is 400m, but your change in position is zero!','Position describes where an object is relative to a reference point. Distance describes how far an object travels along its path... total distance is still 8 metres, but the final position is only 2 metres from the starting point.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_033','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Synthesize how ''Friction'' acts as the mechanical prerequisite for ''Straight-line motion'' in wheeled vehicles.','["Friction prevents wheels from turning, stopping all motion.","While friction opposes motion (drag), static friction between the tire and the road surface is an absolute mechanical prerequisite for forward propulsion; without this frictional grip, the wheels would spin in place endlessly without transferring kinetic energy into forward straight-line motion.","Friction only causes the tires to melt.","Wheeled vehicles rely entirely on gravity, not friction."]',1,'If you try to drive a car on perfectly smooth ice (no friction), the tires just spin and you go nowhere!','Helpful friction: It helps our shoes grip the ground when we walk... friction between the tyres and road helps the bicycle grip the surface.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_034','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Evaluate the physical phenomenon described: ''Without air resistance, objects released from the same height fall with the same acceleration regardless of their mass.''','["This means heavy objects always fall faster than light objects.","This is Galilean equivalence. Gravity accelerates all mass equally (\\\\(9.8 m/s^2\\\\) on Earth). In a vacuum (no air resistance), a heavy hammer and a light feather dropped simultaneously will hit the ground at the exact same millisecond.","This proves that gravity only affects heavy objects.","This means that light objects actually float upwards in a vacuum."]',1,'On the Moon (where there is no air), an astronaut dropped a hammer and a feather, and they hit the dirt at the exact same time!','Without air resistance, objects released from the same height fall with the same acceleration regardless of their mass.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_035','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Analyze how applying a force ''sideways'' alters the vector of a moving object.','["A sideways force causes the object to stop instantly.","Velocity is a vector comprising both speed and direction. Applying a perpendicular (sideways) unbalanced force to a moving object alters its directional vector without necessarily altering its forward speed, forcing it into a curved or new straight-line trajectory.","A sideways force only makes the object heavier.","A sideways force reverses the object''s direction completely."]',1,'If a ball is rolling forward, and you tap it lightly from the side, it doesn''t stop, it just curves!','Forces can cause several effects: ... Change the direction of motion... Applying a force sideways can change direction.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_036','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Synthesize the concept of ''Resultant Force'' in a scenario where three unequal forces act simultaneously on an object.','["The resultant force is always zero when three forces act.","The resultant force is the single mathematical net vector derived from adding all directional forces. If the sum of these vectors is non-zero, it constitutes an unbalanced force, and the object will accelerate in the direction of that final net resultant vector.","The object splits into three pieces.","The resultant force is calculated by multiplying the forces together."]',1,'If two people pull left, and one pulls right, you subtract the right pull from the left pull to find the ''Resultant'' leftover force!','Resultant force: The overall force after combining the forces acting on an object... When the forces are unequal, the resultant force acts towards the stronger force. The object''s motion can change.','2026-11-01 07:56:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_037','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Critique the experimental design of the ''Toy Car Ramp Test'' if the student uses a heavy metal car for the low ramp and a light plastic car for the high ramp.','["The design is brilliant because it tests two things at once.","The design is fundamentally invalid. By failing to control the mass of the car (an independent variable), the student has conflated two variables (mass and ramp height). Any difference in distance cannot be scientifically attributed solely to the change in ramp height.","The design is valid as long as both cars are red.","The design proves that plastic is faster than metal."]',1,'In science, you can only change ONE thing at a time to prove what caused the result!','Make it a fair test: Keep the car, ramp surface, starting point and floor surface the same. Change only the ramp height... If you also change the car... you cannot easily tell which change caused the result.','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_038','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Evaluate the dualistic nature of ''Friction'' as both an engineering hazard and a mechanical necessity.','["Friction is always a hazard and should be eliminated completely.","In mechanical engineering, friction is a destructive hazard causing thermal energy loss and physical wear on moving parts (requiring lubrication). Simultaneously, it is a strict mechanical necessity for components like brakes, clutches, and tires to function via grip.","Friction is only a necessity and never causes any problems.","Friction only affects objects that are completely stationary."]',1,'Friction destroys your car''s engine (bad), but it''s the only thing that makes the brakes work (good)!','Friction can be helpful or unhelpful... Helpful: allows bicycle brakes to slow the wheels... Unhelpful: It can wear down moving machine parts. It can produce unwanted heat.','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_039','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Analyze how the formula ''Speed = Distance / Time'' demonstrates an inverse relationship between speed and time.','["It demonstrates that speed and time are not related.","Mathematically, time is in the denominator. Assuming a constant distance, as the time taken to complete the journey decreases, the calculated average speed must proportionally increase, proving that a shorter duration equals a higher velocity.","It proves that distance is calculated by subtracting time.","It shows that if time increases, speed also increases."]',1,'In a 100-meter race, the person with the smallest time has the biggest speed!','Speed = Distance / Time... If two toy cars travel the same distance, the car that takes less time has the greater average speed.','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_040','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Synthesize how a ''rolling bicycle wheel'' combines multiple types of basic motion.','["It only uses straight-line motion.","The tire is undergoing ''rotational motion'' by spinning 360 degrees around its central axle. Simultaneously, the entire bicycle apparatus is undergoing ''straight-line motion'' as it translates across the ground relative to a reference point, creating a complex combined trajectory.","It only uses back-and-forth motion like a swing.","It proves that a wheel cannot move in a straight line."]',1,'The wheel spins in a circle, but the bike moves in a straight line!','An object may combine more than one type of motion. A rolling bicycle wheel, for example, rotates while moving forward.','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_041','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Evaluate the physical implications of an object moving ''relative to a reference point''. What if the reference point is also moving?','["It means motion is an absolute, fixed property of the universe.","This introduces Galilean relativity. Motion is not absolute; it is strictly defined by the observer''s frame of reference. If you run forward on a forward-moving train, your speed relative to the train is low, but your speed relative to a stationary tree outside is the sum of both speeds.","It proves that nothing in the universe is actually moving.","It means the object will instantly stop."]',1,'If you sit in a moving car, you are stationary relative to the seat, but you are moving 60mph relative to the road outside!','An object is in motion when its position changes relative to a reference point over time... We compare an object''s position at different times.','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_042','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Critique the everyday assumption that ''gravity only pulls things down''.','["The assumption is perfectly accurate for all physics.","Gravity is an omnidirectional attractive force between any two masses. We perceive it as ''down'' because Earth is the most massive local object, pulling us toward its center. However, the Moon''s gravity also pulls ''up'' on Earth''s oceans, creating tides.","Gravity actually pushes things away from the Earth.","Gravity only exists when objects are falling."]',1,'Gravity doesn''t mean ''down''; it means ''pulled toward the heaviest object''!','Gravity is an attractive force between objects that have mass. Earth''s gravity pulls objects towards Earth''s centre... Gravity also keeps the Moon in orbit around Earth...','2026-11-01 07:56:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_043','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Synthesize how ''Air Resistance'' acts as a specialized form of friction.','["Air resistance is a form of gravity, not friction.","Friction is the resistance between interacting surfaces. Air resistance (drag) occurs because a moving solid object must physically collide with and displace atmospheric gas molecules. Thus, air resistance is simply fluid friction acting opposite to the vector of motion.","Air resistance only occurs in a vacuum.","Air resistance makes objects accelerate faster."]',1,'Running through air is like running through very thin water; the air rubs against you and slows you down!','Friction is a force that resists sliding or movement between surfaces that are touching... Air resistance: A force that opposes an object''s movement through air.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_044','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Analyze the mathematical calculation of ''Average Speed'' versus instantaneous speed.','["Average speed tells you exactly how fast the car was moving at every single second.","The formula ''Total Distance / Total Time'' calculates the mean (average) velocity over the entire journey. It inherently obscures instantaneous speed variations; a car could stop at a red light, speed up, and slow down, but the formula only calculates the smoothed, aggregate rate of travel.","Average speed can only be calculated for objects that never stop.","Average speed is calculated by adding distance and time."]',1,'If you drive 60 miles in one hour, your average speed is 60mph, even if you stopped for gas for 10 minutes!','Speed tells us how much distance an object travels in a given amount of time... An object''s speed can change during a journey.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_motion_global_045','Physics','Motion and Forces','Topic 4: Motion and Forces','Primary',10,'Evaluate why an ''Unbalanced Force'' is the strict mechanical requirement for ''Acceleration''.','["Unbalanced forces actually prevent acceleration.","According to Newton''s Second Law, an object''s inertia will maintain its current velocity (even if zero) indefinitely. Only the introduction of a non-zero net force (an unbalanced force) can overcome that inertia and induce a change in velocity (acceleration, deceleration, or directional shift).","Acceleration can happen even if all forces are perfectly balanced.","Unbalanced forces only change the color of the object, not the speed."]',1,'If nobody pushes the ball, it will never move; you need an uneven push to force it to start!','Balanced forces... do not change the object''s motion. Unbalanced forces produce a non-zero resultant force and can change an object''s motion.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_001','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is a ''simple machine''?','["A robot that runs on electricity","A basic mechanical device that helps us apply a force to perform a task","A computer program","A type of vehicle engine"]',1,'It is a basic tool that makes work easier without using electricity.','A simple machine is a basic mechanical device that helps us apply a force to perform a task.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_002','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'How many traditional simple machines are there?','["Two","Four","Six","Ten"]',2,'There are exactly six.','The six traditional simple machines are: Lever, Pulley, Wheel and axle, Inclined plane, Wedge, Screw.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_003','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is a ''lever''?','["A wheel with a rope","A rigid bar that turns around a fixed point","A flat, sloping surface","A tool used for cutting"]',1,'A seesaw is a classic example.','A lever is a rigid bar that turns around a fixed point called a fulcrum.','2026-11-01 07:56:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_004','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is the fixed point that a lever turns around called?','["The effort","The load","The fulcrum","The axle"]',2,'It is the pivot point holding the lever up.','Fulcrum: the point around which the lever turns.','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_005','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is a ''pulley''?','["A grooved wheel used with a rope or cord","A flat piece of wood","A sharp knife","A spinning top"]',0,'You use this to pull a flag up a flagpole.','A pulley is a wheel with a groove around its edge. A rope or cord runs through the groove...','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_006','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is an ''inclined plane''?','["A wheel and an axle","A flat surface set at an angle, like a ramp","A lever used to lift things","A rope hanging from the ceiling"]',1,'It is a slope used to push things upward.','An inclined plane is a flat surface set at an angle to the horizontal. A ramp is a common example.','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_007','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'Which of these is an example of an inclined plane?','["A seesaw","A door knob","A wheelchair ramp","A pair of scissors"]',2,'It is a slanted surface.','Examples include: Wheelchair access ramps. Loading ramps.','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_008','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is a ''wedge''?','["A wheel with a rope","A machine made of two sloping surfaces that meet at a sharp edge to split materials","A flat board used for walking","A long rope used for pulling"]',1,'An axe blade is a wedge.','A wedge is a simple machine made of two sloping surfaces that meet at a sharp edge or point. It helps split, cut or separate materials.','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_009','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'Which of these tools is an example of a wedge?','["A wheelbarrow","A pulley","An axe","A steering wheel"]',2,'It is sharp and used to split wood.','Examples of wedges include: Knives. Axes. Chisels.','2026-11-01 07:56:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_010','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What is a ''screw''?','["An inclined plane wrapped around a central cylinder","A flat ramp","A wheel attached to a pole","A heavy weight on a rope"]',0,'It has a spiral thread winding around it.','A screw is an inclined plane wrapped around a central cylinder. The sloping surface forms a spiral called a thread.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_011','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'Which of these is an example of a ''wheel and axle''?','["A knife","A door knob","A ramp","A flagpole rope"]',1,'The round knob is the wheel, the metal stick inside is the axle.','Examples include: Bicycle wheels. Door knobs. Steering wheels.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_012','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What does ''effort'' mean when using a simple machine?','["The object being moved","The force applied to the machine by a person or motor","The fixed point of a lever","The friction on the ground"]',1,'It is the push or pull that you provide.','Effort: the force applied to the lever [or machine].','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_013','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'What does ''load'' mean when using a simple machine?','["The force applied by a person","The object or resistance being moved","The center of a wheel","The sharp edge of an axe"]',1,'It is the heavy box or the rock you are trying to lift.','Load: the object or resistance being moved.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_014','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'Which simple machine is often used on construction cranes to lift heavy objects?','["A wedge","A screw","A pulley","An inclined plane"]',2,'It uses ropes and wheels to lift steel beams.','Where are pulleys used? ... Cranes used on construction sites.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_015','Physics','Simple Machines','Topic 5: Simple Machines','Primary',1,'Do simple machines create new energy out of nothing?','["Yes, they create endless energy.","No, they do not create energy, but they make a task more convenient.","Yes, they turn air into electricity.","No, they actually destroy energy."]',1,'They only change how you apply force; they don''t do the work for you completely!','Simple machines... do not create energy, but they can make work easier to perform.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_016','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why is pushing a heavy box up a ramp (an inclined plane) often easier than lifting it straight up?','["Because gravity stops working on a ramp.","It reduces the amount of force needed to move the load upward, even though you have to push it over a longer distance.","Because ramps are coated in oil to eliminate friction.","Because the box loses mass on a ramp."]',1,'It trades force for distance: less pushing, but a longer walk!','Using a ramp allows the box to be moved up more gradually, usually with less force, but over a longer distance.','2026-11-01 07:56:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_017','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'How does a ''fixed pulley'' (like on a flagpole) make work more convenient, even though it doesn''t reduce the weight of the load?','["It turns the flag into a gas so it floats.","It changes the direction of the force; pulling *down* on a rope is often easier for a human than lifting *up* directly.","It makes the rope completely invisible.","It eliminates gravity completely."]',1,'It''s easier to use your body weight to pull down than to use your arm muscles to pull up!','A fixed pulley is often used to change the direction of a force. For example, pulling down on a rope can raise a bucket.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_018','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'When using a claw hammer to pull a nail out of wood, which part acts as the ''fulcrum''?','["The person''s hand.","The nail itself.","The curved head of the hammer resting against the wood.","The handle of the hammer."]',2,'The metal head is the pivot point that the handle rotates around!','Claw hammer: When pulling out a nail, the hammer''s head rests against the wood and acts as the fulcrum.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_019','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'How do the handles of a pair of scissors act as a lever?','["The handles are completely decorative.","You apply the ''effort'' force to the handles, which pivot around the screw in the middle (the fulcrum) to cut the paper (the load).","The handles are actually an inclined plane.","The handles are wedges that split the paper directly."]',1,'The screw in the middle is the fulcrum!','Scissors: The handles and blades act as levers, and the cutting edges act as wedges.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_020','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why is a door knob considered a ''wheel and axle'' instead of just a handle?','["Because it is completely round like a ball.","The large outer knob acts as the ''wheel'' which turns a much smaller rod (the ''axle'') inside the door, multiplying the twisting force.","Because it falls off if you turn it too fast.","Because it is made of metal."]',1,'Turning the big knob makes it easy to turn the stiff metal stick inside the door!','A door knob also uses the wheel-and-axle principle: turning the larger knob rotates the smaller spindle inside the door mechanism.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_021','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'How is a ''screw'' physically related to an ''inclined plane''?','["They are completely unrelated.","A screw is simply a long inclined plane (a ramp) that has been wrapped around a central cylinder to create a spiral thread.","A screw is just an inclined plane that has been flattened with a hammer.","An inclined plane is a screw that lost its threads."]',1,'If you unwrapped the thread of a screw, it would just be a long triangle (a ramp)!','A screw is an inclined plane wrapped around a central cylinder. The sloping surface forms a spiral called a thread.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_022','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'In a lever, what happens if you apply your ''effort'' (push) much further away from the fulcrum?','["The lever breaks instantly.","It generally reduces the amount of force you need to lift the load, providing a better mechanical advantage.","It makes the load ten times heavier.","It turns the lever into a pulley."]',1,'Think of a seesaw: sitting further back makes it easier to lift the person on the other side!','Applying effort farther from the fulcrum can reduce the force needed, although the effort point must move through a greater distance.','2026-11-01 07:56:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_023','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why is it much easier to move a heavy suitcase with wheels than to drag it across the floor?','["Because wheels make the suitcase lighter by removing mass.","Wheels allow the suitcase to roll, which drastically reduces the friction compared to sliding the flat bottom of the suitcase on the floor.","Because wheels contain magnets that pull the suitcase.","Because sliding creates no friction at all."]',1,'Rolling means you don''t have to fight the rough floor!','Wheels allow objects to roll instead of sliding along a surface. Rolling often reduces resistance compared with sliding, making it easier to move loads.','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_024','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'How does a ''wedge'' help you split a piece of wood?','["It freezes the wood so it shatters.","When you drive the wedge into the wood, its sloping sides change the downward pushing force into an outward sideways force, splitting the wood apart.","It absorbs all the water in the wood until it snaps.","It uses electricity to burn through the wood."]',1,'You hit it straight down, and it pushes the wood left and right!','When a wedge is pushed into a material, its sloping surfaces direct the applied force sideways, helping separate the material.','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_025','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why does a ''movable pulley'' provide a mechanical advantage compared to a ''fixed pulley''?','["Because it is painted a different color.","The movable pulley moves with the load and is supported by two segments of rope, cutting the effort force needed to lift the load roughly in half.","Because it ignores gravity completely.","Because it turns into a lever when you pull it."]',1,'Because two ropes are holding the weight, your arm only has to do half the work!','Movable pulley: The pulley moves with the load. In an ideal arrangement, it can reduce the effort force needed...','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_026','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'In a simple machine experiment, why should you use a ''spring scale'' to pull a box up a ramp?','["To make the box heavier.","To accurately measure the exact amount of pulling force (in Newtons) required, allowing you to prove that the ramp reduced the effort compared to lifting.","To measure the temperature of the box.","To measure how long the box is."]',1,'A spring scale measures force (Newtons), so you can prove the ramp made the job easier!','With adult supervision, use a spring scale to pull the box slowly across the surface and record the force.','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_027','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'What trade-off do you make when using an inclined plane (ramp) to reduce the lifting force?','["You have to use electricity.","You use less force, but you have to push the object over a much longer distance to reach the same height.","You use less force, but the object gets heavier at the top.","You use more force, but the distance is shorter."]',1,'It''s an easier push, but a longer walk!','Using a ramp allows the box to be moved up more gradually, usually with less force, but over a longer distance.','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_028','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'How does a ''bottle opener'' function as a lever?','["It smashes the bottle.","The edge of the opener catches under the cap (the load), rests on the top of the cap (the fulcrum), and your hand pulls up on the handle (the effort) to pry it off.","It spins the bottle very fast.","It acts as a wedge that cuts the glass."]',1,'It uses a pivot point to pop the tight metal cap off easily.','Bottle opener: A bottle opener uses leverage to help lift a bottle cap.','2026-11-01 07:56:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_029','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why is a ''wheelbarrow'' considered a compound machine (combining two simple machines)?','["Because it is painted two colors.","It uses a wheel and axle to roll on the ground, and the long handles act as a lever (pivoting on the wheel) to lift the heavy load inside the bucket.","Because it has two wheels.","Because it uses a pulley and a screw."]',1,'The wheel makes it roll, the long handles make it easy to lift!','Wheelbarrow: It combines a wheel and axle with a lever to help transport a load.','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_030','Physics','Simple Machines','Topic 5: Simple Machines','Primary',5,'Why do real-world pulleys require slightly more effort force than the ''ideal'' math suggests?','["Because gravity gets stronger when you use a rope.","Because the math ignores friction; in the real world, the rope rubbing against the grooved wheel creates friction, which requires extra force to overcome.","Because the pulley creates extra mass.","Because the rope stretches forever."]',1,'Nothing in the real world is perfectly smooth; friction steals a little bit of your effort!','Remember: Real pulleys have friction, so the force needed is usually greater than the ideal value.','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_031','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Critique the fundamental misconception that simple machines ''save work'' in classical mechanics.','["They do save work because they create free energy.","In physics, ''Work'' equals Force multiplied by Distance (\\\\(W = F \times d\\\\)). A simple machine (like a ramp) decreases the required Force, but proportionally increases the Distance. Therefore, the total Work done remains identical; it is only the application of effort that changes.","They save work because they make the object weigh less.","They save work by eliminating the distance completely."]',1,'You do the exact same amount of ''Work'' (Energy), you just spread it out over a longer path so it feels easier!','Simple machines... do not create energy... reducing the effort force usually involves moving through a greater distance or accepting other trade-offs.','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_032','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Analyze the mechanical transition of force vectoring in a ''Wedge''.','["A wedge amplifies the downward force without changing its direction.","A wedge operates by vector resolution. When a unilateral linear force is applied to the blunt end (e.g., striking an axe), the inclined planes of the wedge physically redirect the single downward vector into bilateral (outward) lateral forces, resulting in material cleavage.","A wedge converts downward force into upward force.","A wedge prevents any force from transferring."]',1,'You hit it straight down, but the shape turns that force 90 degrees to the left and right!','When a wedge is pushed into a material, its sloping surfaces direct the applied force sideways, helping separate the material.','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_033','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Synthesize how the concept of ''Mechanical Advantage'' dictates the design of a ''Wheel and Axle''.','["A larger axle always provides a better advantage.","Mechanical advantage in a wheel and axle is a ratio of the wheel''s radius to the axle''s radius. Applying a small force to the outer edge of a large wheel (like a large steering wheel) generates a massive torque on the small axle, enabling human effort to turn heavy machinery.","The size of the wheel has no effect on the axle.","Mechanical advantage means the wheel turns on its own."]',1,'A giant steering wheel makes it easy to turn a heavy truck because the wheel is so much wider than the steering column!','The wheel and axle can help reduce effort or make movement easier, depending on how it is designed... turning the larger knob rotates the smaller spindle...','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_034','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Evaluate the physical relationship between the ''pitch'' (distance between threads) of a screw and its required effort force.','["Pitch has no effect on effort force.","A screw is a wrapped inclined plane. A fine pitch (threads close together) creates a gentle slope, requiring minimal rotational effort but many turns to advance. A coarse pitch (threads far apart) creates a steep slope, requiring fewer turns but significantly more rotational force.","A fine pitch requires immense force to turn.","Threads actually act as pulleys, not inclined planes."]',1,'If the threads are packed tightly, it''s like walking up a very gentle, very long winding staircase!','A screw is an inclined plane wrapped around a central cylinder... The threads can provide a mechanical advantage, but friction and the screw''s design affect how much effort is needed.','2026-11-01 07:56:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_035','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Analyze the specific class of lever demonstrated by a ''seesaw'' versus a ''wheelbarrow''.','["They are exactly the same class of lever.","A seesaw is a Class 1 lever (the fulcrum is between the effort and the load). A wheelbarrow is a Class 2 lever (the load is between the fulcrum/wheel and the effort/handles), which is mechanically optimized to always provide a mechanical advantage > 1.","A wheelbarrow has no fulcrum.","A seesaw is a Class 3 lever."]',1,'On a seesaw, the pivot is in the middle. On a wheelbarrow, the pivot is the front wheel!','Seesaw: The central support is the fulcrum... Wheelbarrow: It combines a wheel and axle with a lever... (Synthesis: The position of the fulcrum changes the mechanics).','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_036','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Synthesize how a ''block and tackle'' (a system of multiple pulleys) theoretically scales mechanical advantage.','["Adding pulleys makes the load infinitely heavy.","Each additional supporting rope segment in a movable pulley system proportionally divides the load''s weight. Therefore, theoretically, an infinite number of pulleys requires zero effort, but requires the user to pull an infinite length of rope to move the load a single centimeter.","Adding pulleys increases the force required to lift the load.","Adding pulleys turns the rope into a solid bar."]',1,'If you use 4 ropes to lift the box, you only pull with 1/4 the strength, but you have to pull 4 times as much rope!','Movable pulley... In an ideal arrangement, it can reduce the effort force needed, although more rope must be pulled.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_037','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Evaluate the role of ''Friction'' in the functionality of a ''Screw'' versus an ''Inclined Plane'' (ramp).','["Friction is equally useless in both machines.","On a simple ramp, friction is an unwanted inefficiency opposing the upward push. However, on a screw, friction is the essential mechanical property that holds the inclined plane in place; without high static friction between the threads and the material, the screw would unwind and fall out.","Friction prevents the screw from turning at all.","Friction is entirely absent from screws."]',1,'Friction makes a screw hard to drive in, but it''s also the only thing keeping the screw from sliding right back out!','Turning a screw... helps it hold materials together... The threads can provide a mechanical advantage, but friction and the screw''s design affect how much effort is needed.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_038','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Critique the validity of a ''Fair Test'' experiment comparing ramp effort, if the student uses a spring scale but pulls at wildly fluctuating speeds.','["The test is completely valid because speed doesn''t matter.","The test is invalid. Pulling at fluctuating speeds introduces kinetic acceleration (\\\\(F=ma\\\\)). The spring scale will register spikes in force due to accelerating the mass, conflating the force required to overcome gravity/friction with the force required to accelerate, destroying the baseline measurement.","The test is valid as long as the ramp is blue.","Fluctuating speed is required to make the scale work."]',1,'If you yank the box quickly, the scale spikes because of the sudden acceleration, not because the ramp is steep!','Make it a fair test: Use the same box and similar movement speeds... avoid changing several factors at once.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_039','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Analyze how the ''Archimedes Screw'' (an ancient water pump) utilizes the simple machine concept to defeat gravity.','["It acts as a giant lever that throws water into the air.","The Archimedes Screw is a vast inclined plane wrapped around a central cylinder. By rotating the cylinder, the inclined plane continuously scoops and pushes discrete pockets of fluid up the spiral gradient, effectively rolling a liquid uphill against gravity.","It uses a massive pulley system to lift buckets of water.","It freezes the water into a solid block to slide it up."]',1,'It''s like a spiral staircase for water; turning the screw forces the water to ''walk'' up the stairs!','A screw is an inclined plane wrapped around a central cylinder. The sloping surface forms a spiral called a thread.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_040','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Synthesize the mechanical interaction within a pair of ''Scissors'' to classify it as a compound machine.','["Scissors are just two wedges glued together.","Scissors utilize two intersecting Class 1 levers (the handles pivot on the central screw/fulcrum to multiply hand force), which terminate in dual wedges (the sharpened blades) that concentrate the multiplied force onto a microscopic surface area to achieve shear cleavage.","Scissors are a combination of a pulley and a wheel.","Scissors are a single, unchangeable simple machine."]',1,'Your hand uses the lever to multiply your strength, and the wedge blade uses that strength to cut!','Scissors: The handles and blades act as levers, and the cutting edges act as wedges.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_041','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Evaluate the physical consequence of placing the ''fulcrum'' extremely close to the ''load'' in a Class 1 lever.','["It makes the load infinitely heavy.","Placing the fulcrum immediately adjacent to the load maximizes the length of the effort arm relative to the load arm. This creates an extreme mechanical advantage, allowing a minuscule effort force to lift a massive load, albeit requiring a massive effort distance.","It makes the lever snap in half instantly.","It forces the user to apply maximum effort to lift a small load."]',1,'If you want to lift a car with a long steel bar, you put the rock (fulcrum) right next to the car, and push down on the very far end of the bar!','Applying effort farther from the fulcrum can reduce the force needed, although the effort point must move through a greater distance.','2026-11-01 07:56:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_042','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Critique the assertion that a ''Wheel and Axle'' is completely mechanically distinct from a ''Lever''.','["The assertion is completely true; they share no physics.","A wheel and axle is mechanically identical to a continuously rotating lever. The central axis acts as a permanent fulcrum, while the radii of the axle and the wheel act as the opposing lever arms, providing continuous, 360-degree leverage without needing to reset.","A wheel and axle is actually a type of pulley.","A wheel and axle is just a flattened wedge."]',1,'A wheel is just a lever that spins in a perfect circle so it never hits the ground!','A wheel and axle consists of a larger wheel connected to a smaller rod called an axle... (Synthesis: The center is the fulcrum, the spokes are the lever arms).','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_043','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Analyze how the ''slope angle'' of an Inclined Plane determines its Mechanical Advantage.','["A steeper slope provides a higher mechanical advantage.","The mechanical advantage of an inclined plane is inversely proportional to its slope angle (or height relative to length). A shallow, gentle angle provides a massive mechanical advantage (requires very little force), while a steep, near-vertical angle approaches a mechanical advantage of 1 (lifting straight up).","The angle has no effect on the mechanical advantage.","A flat horizontal line provides a mechanical advantage of zero."]',1,'A steep ramp is hard to climb; a gentle ramp is easy to climb, but you have to walk much further!','A longer, gentler ramp generally requires less force to move the same load upward at a steady speed, but the load must travel a longer distance.','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_044','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Synthesize the biomechanics of the human body: How does the human arm act as a simple machine?','["The human arm is a wheel and axle.","The human arm is a biological lever system. The elbow joint acts as the fulcrum, the bicep muscle provides the effort force (inserting just past the fulcrum), and the object held in the hand acts as the load, operating primarily as a Class 3 lever.","The human arm is a biological pulley system.","The human arm uses no simple machine physics."]',1,'Your elbow is the pivot, your muscle is the pull, and the weight in your hand is the load!','A lever has three important parts: Fulcrum... Effort... Load... (Synthesis: The body uses these exact parts).','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_machines_global_045','Physics','Simple Machines','Topic 5: Simple Machines','Primary',10,'Evaluate the physical limitations of using a ''Single Fixed Pulley''.','["It makes the object weigh twice as much.","A single fixed pulley provides a mechanical advantage of exactly 1. It does not reduce the required effort force at all; it solely alters the directional vector of the force (e.g., allowing a user to pull down to lift a load up, utilizing body weight rather than muscular strength).","It cuts the required effort force exactly in half.","It allows you to lift an object without pulling the rope."]',1,'A fixed pulley doesn''t make the box lighter, it just makes it easier for you to use your body weight to pull!','A fixed pulley is often used to change the direction of a force. For example, pulling down on a rope can raise a bucket. (Contrasted with movable pulleys which reduce effort).','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_001','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What is ''energy''?','["A type of invisible liquid","The capacity to cause change or make things happen","A type of heavy rock","A loud noise"]',1,'It makes movement, light, and heat possible.','Energy is the capacity to cause change or make things happen.','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_002','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'Can you hold energy in your hands like a material object?','["Yes, energy is a solid object.","No, energy is not a material; we only observe its effects.","Yes, but only in the winter.","Yes, energy is a type of liquid."]',1,'You can hold a battery, but you can''t hold the electricity inside it!','Energy is not a material that we can hold in our hands. Instead, we observe its effects.','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_003','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'Which of these is a ''natural'' source of light energy?','["A flashlight (torch)","The Sun","A television","A glowing lightbulb"]',1,'It exists in nature without humans building it.','Natural sources: the Sun, stars and lightning.','2026-11-01 07:56:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_004','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'Which of these is an ''artificial'' source of light energy?','["The stars","Lightning","A lamp","The Sun"]',2,'Humans made this light source.','Artificial sources: lamps, torches and light-emitting diodes (LEDs).','2026-11-01 07:56:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_005','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'How is ''sound energy'' produced?','["By freezing water","By objects vibrating","By mixing chemicals","By painting a picture"]',1,'When you hit a drum, the skin shakes (vibrates) to make the noise!','Sound is produced when objects vibrate.','2026-11-01 07:56:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_006','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What does ''thermal energy'' refer to?','["The sound a machine makes","Heat and the motion of particles within matter","The light from a computer","The speed of a bicycle"]',1,'Thermal means heat!','Thermal energy is associated with the motion and interactions of particles within matter. Heat is energy transferred...','2026-11-01 07:56:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_007','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What is ''electrical energy''?','["Energy from the sun","Energy associated with electric charges and electric currents","Energy stored in food","Energy from the wind"]',1,'It powers your TV and refrigerator.','Electrical energy is associated with electric charges and electric currents.','2026-11-01 07:56:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_008','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What is ''kinetic energy''?','["Energy stored in a battery","Energy an object has because it is moving","Energy from the moon","Energy stored in food"]',1,'A rolling ball has this type of energy.','Kinetic energy is the energy an object has because it is moving.','2026-11-01 07:56:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_009','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What type of stored energy does a battery contain?','["Kinetic energy","Chemical energy","Sound energy","Light energy"]',1,'The chemicals inside the battery react to create electricity.','Chemical energy: energy associated with substances such as food, fuels and batteries.','2026-11-01 07:56:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_010','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What is ''gravitational potential energy''?','["Energy stored in a spring","Energy associated with an object''s position in a gravitational field, like a book on a high shelf","Energy from a running animal","Energy from a hot stove"]',1,'It is the energy of being high up, ready to fall!','Gravitational potential energy: energy associated with an object''s position in a gravitational field, such as a book on a high shelf.','2026-11-01 07:56:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_011','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What does an ''energy transformation'' mean?','["Energy disappearing completely","Energy changing from one form to another","Energy turning into a solid rock","Energy stopping forever"]',1,'Like electricity turning into light in a bulb.','Energy often changes from one form to another. This is called an energy transformation.','2026-11-01 07:56:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_012','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'Which of the following transforms electrical energy into sound energy?','["A flashlight","A solar panel","A speaker","A bicycle"]',2,'You plug it in (electricity) and music comes out (sound).','Speaker: Electrical energy → sound energy...','2026-11-01 07:56:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_013','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What is a simple way to ''save energy'' at home?','["Leave the refrigerator door open","Switch off lights when they are not needed","Leave the television on all night","Use hot water for everything"]',1,'Don''t waste electricity if no one is in the room!','Useful habits include: Switch off lights when they are not needed.','2026-11-01 07:56:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_014','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'Where do humans and animals get their energy from?','["From the wind","From batteries","From the food they eat","From rocks"]',2,'Eating gives you the chemical energy you need to run and play!','Animals and humans obtain energy from food.','2026-11-01 07:56:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_015','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',1,'What type of energy does a solar panel produce from sunlight?','["Sound energy","Kinetic energy","Electrical energy","Chemical energy"]',2,'It turns sunshine into electricity for your house!','Solar panel: Light energy → electrical energy.','2026-11-01 07:56:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_016','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'Why does the Moon appear bright in the night sky even though it does not produce its own light?','["Because it is covered in electric lamps.","Because it reflects light energy from the Sun into our eyes.","Because the Moon is actually a giant star.","Because the Earth shines light onto the Moon."]',1,'The Moon is like a giant mirror reflecting the Sun''s light!','Important: The Moon appears bright because it reflects sunlight; it does not produce its own visible light like the Sun.','2026-11-01 07:56:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_017','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'Why can sound NOT travel through a perfect vacuum (like outer space)?','["Because it is too cold in space.","Because sound requires a medium (like air or water particles) to vibrate and travel through, and a vacuum has no particles.","Because there is no gravity in space.","Because space is too bright."]',1,'In space, no one can hear you scream because there is no air to carry the sound waves!','Sound needs a medium to travel through. It cannot travel through a perfect vacuum because there are no particles there to carry the sound vibrations.','2026-11-01 07:56:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_018','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'How does a metal spoon sitting in a bowl of hot soup become warm?','["Through radiation from the sun.","Through conduction, because the thermal energy transfers directly from the hot soup to the metal spoon it is touching.","Through convection in the air.","Through electrical energy from the bowl."]',1,'Heat moves straight from the hot liquid into the solid spoon!','Conduction: energy transfer through direct contact, especially in solids... A metal spoon left in hot soup may become warm by conduction.','2026-11-01 07:56:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_019','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'How does thermal energy from a heater warm a whole room, even if you aren''t touching the heater?','["Through conduction along the floor.","Through convection, where the warm air rises and moves around the room as a fluid.","Through sound waves.","Through chemical energy."]',1,'The heater warms the air, and the air floats around the room to warm you!','Convection: energy transfer by the movement of fluids, such as air or water... Warm air rising above a heater is an example of convection.','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_020','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'If two cars are exactly the same mass, but Car A is driving 50 km/h and Car B is driving 100 km/h, which one has more kinetic energy?','["Car A","Car B","They have the exact same kinetic energy.","Neither car has kinetic energy."]',1,'Speed increases kinetic energy!','For objects of the same mass, a faster-moving object has more kinetic energy than a slower-moving object.','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_021','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'If you drop a book from a high shelf, what energy transformation is happening as it falls?','["Chemical energy turns into light energy.","Gravitational potential energy transforms into kinetic (movement) energy.","Electrical energy turns into sound energy.","Heat energy turns into potential energy."]',1,'It loses height (potential) but gains speed (kinetic)!','A ball [or book] held above the ground has gravitational potential energy. When it falls, some of that energy becomes kinetic energy.','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_022','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'Why is it important to know that an electric lamp produces both light AND thermal (heat) energy?','["Because the heat makes the lamp float.","Because it shows that energy transformations are not always perfectly efficient; the heat produced by a lightbulb is often wasted energy.","Because lamps need heat to produce sound.","Because light is actually just frozen heat."]',1,'A bulb''s job is to make light; the heat it makes is usually wasted energy!','An electric lamp produces light and also transfers some energy as heat. Electric lamp: Electrical energy → light energy + thermal energy.','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_023','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'How do our bodies use ''chemical energy'' when riding a bicycle?','["Our bodies absorb chemical energy directly from the bicycle.","Our bodies transform the chemical energy stored in the food we ate into kinetic energy to push the pedals, and also produce some thermal energy (sweat).","Our bodies turn chemical energy into electrical batteries.","Our bodies reject chemical energy completely."]',1,'You burn the ''fuel'' (food) to make your legs move!','Riding a bicycle: Chemical energy from food → movement, with some energy transferred as heat and sound.','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_024','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'What happens to the kinetic energy of a moving ball when it hits a wall and stops?','["The energy is completely destroyed and disappears forever.","The energy is transferred to the wall or transformed into other forms, such as sound (a ''thud'') and thermal energy (friction).","The energy turns into a solid rock.","The energy turns into electrical energy and shocks the wall."]',1,'Energy never dies; it just changes form or moves to a new object!','When a moving ball hits another object, some of its energy may be transferred to that object, while some may become sound and thermal energy. Energy does not simply disappear...','2026-11-01 07:57:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_025','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'How does energy travel from the Sun to the Earth through the empty vacuum of space?','["Through conduction.","Through convection.","Through radiation, travelling as waves that do not need a physical medium.","Through electrical wires."]',2,'Radiation is the only way heat can travel through the empty nothingness of space!','Radiation: energy transfer by waves, including sunlight travelling through space. Energy from the Sun reaches Earth by radiation.','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_026','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'Why is ''food'' technically not energy itself?','["Because food is just a hologram.","Food is a physical material that *contains* stored chemical energy; our bodies must digest it through chemical processes to release and transfer that energy.","Because food only contains kinetic energy.","Because food destroys energy."]',1,'Food is the battery; the energy is locked inside it!','Food is not energy itself; it contains chemical energy that the body can transfer and transform through chemical processes.','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_027','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'What type of stored energy is found in a stretched rubber band?','["Gravitational potential energy","Chemical energy","Elastic potential energy","Electrical energy"]',2,'When you stretch it, it wants to snap back!','Elastic potential energy: energy stored when an elastic object is stretched or compressed, such as a spring [or rubber band].','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_028','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'Why do we say energy is ''wasted'' if a machine makes a loud noise while it works?','["Because noise makes the machine run faster.","Because the machine is designed to do a specific job (like moving), so any electrical energy transformed into sound instead of movement is useless for that job.","Because noise destroys the machine.","Because noise is a type of chemical energy."]',1,'If a fan''s job is to blow air (kinetic), any energy used to make a loud humming noise (sound) is wasted electricity!','Energy efficiency: Using less energy to provide the same useful service... Energy does not simply disappear... spreading into the surroundings as thermal energy or sound.','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_029','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'How does using ''daylight when practical'' help save energy?','["It stops the sun from burning out.","It replaces the need to turn on electric lamps, thereby saving the electrical energy (and money) that would have been used.","It makes the house colder.","It turns the windows into solar panels."]',1,'Open the curtains instead of flipping the light switch!','Saving energy means reducing unnecessary energy use... Useful habits include: Use daylight when it is practical.','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_030','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',5,'What is the difference between ''saving energy'' at home and the physics ''law of conservation of energy''?','["They are the exact same concept.","Saving energy at home means not wasting electricity (a behavioral choice); the law of conservation of physics is a universal rule that energy cannot be created or destroyed, only transformed.","Saving energy is a physics law, conservation is a choice.","Neither concept actually exists."]',1,'You can ''waste'' electricity by leaving a light on, but the energy itself wasn''t destroyed, it just turned into useless heat and light!','Energy conservation in everyday life: using energy wisely... The law of conservation of energy in physics: energy cannot be created or destroyed... These are related ideas, but they do not mean the same thing.','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_031','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Critique the everyday statement: ''My phone battery ran out of energy and the energy is gone.''','["The statement is perfectly accurate according to physics.","The statement is colloquially understood but scientifically false. According to the law of conservation of energy, the chemical energy in the battery didn''t ''disappear''; it was transformed into light (screen), sound (speakers), and thermal energy (heat) which dissipated into the environment.","The statement is false because batteries create infinite energy.","The statement proves that batteries do not use energy."]',1,'The energy didn''t die; it just escaped into the room as light and heat!','Energy does not simply disappear when a device stops working... It is transferred or transformed, often spreading into the surroundings as thermal energy or sound... The law of conservation of energy... energy cannot be created or destroyed...','2026-11-01 07:57:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_032','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Analyze the energy transformations required for a human to ride a bicycle, starting from the Sun.','["The Sun directly pushes the bicycle pedals with light.","Nuclear energy in the Sun transforms into radiant (light) energy. Plants absorb this and transform it into chemical energy (food). A human eats the food, transforming chemical energy into kinetic energy (pedaling) and thermal energy (sweat).","The Sun turns into a battery that powers the bicycle.","The process involves zero energy transformations."]',1,'Every ounce of energy you use to pedal a bike originally came from a star!','Sunlight provides energy... Plants use energy from sunlight to make food. Animals and humans obtain energy from food... Riding a bicycle: Chemical energy from food → movement...','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_033','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Synthesize how the concept of ''Energy Efficiency'' dictates modern engineering of lightbulbs (LEDs vs. Incandescent).','["Engineers try to make bulbs that produce as much heat as possible.","An incandescent bulb is highly inefficient because it transforms a massive percentage of electrical energy into wasted thermal energy (heat). Engineers design LEDs to maximize efficiency by transforming a much higher percentage of electricity directly into luminous energy (light) with minimal thermal waste.","LEDs are inefficient because they produce too much sound.","Energy efficiency has no impact on engineering."]',1,'A good lightbulb makes light, not heat! LEDs save electricity because they don''t waste it on heat.','Energy efficiency: Using less energy to provide the same useful service. Electric lamp: Electrical energy → light energy + thermal energy.','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_034','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Evaluate the physical distinction between ''Thermal Energy'' and ''Heat''.','["They are identical and can be used interchangeably in physics.","Thermal energy is the internal kinetic energy of particles within a specific system. Heat is the active, directional transfer of that energy across a boundary solely due to a temperature gradient (flowing from high to low).","Thermal energy is cold, heat is hot.","Heat is a material, thermal energy is a gas."]',1,'A cup of coffee has thermal energy; ''heat'' is what happens when that energy flows from the coffee into your cold hands!','Thermal energy is associated with the motion and interactions of particles within matter. Heat is energy transferred because of a temperature difference: it flows naturally from a warmer object or region to a cooler one.','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_035','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Analyze the mechanical transition from ''Gravitational Potential Energy'' to ''Kinetic Energy'' using a pendulum.','["The pendulum creates new energy at the bottom of its swing.","At its highest point, the pendulum possesses maximum gravitational potential energy and zero kinetic energy. As it falls, gravity converts this potential energy into kinetic energy, reaching maximum kinetic velocity at the absolute bottom of the arc before converting back as it swings up.","The pendulum has zero energy at all times.","The pendulum only uses chemical energy."]',1,'It trades height for speed, and then trades speed back for height!','Gravitational potential energy: energy associated with an object''s position in a gravitational field... When it falls, some of that energy becomes kinetic energy.','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_036','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Synthesize how ''Convection'' currents rely on the relationship between thermal energy and density.','["Convection works because hot fluids become heavier and sink.","As a fluid (air/water) absorbs thermal energy, its particles gain kinetic energy, spread apart, and its density decreases. This less dense, warmer fluid rises, while denser, cooler fluid sinks to replace it, creating a continuous convective circulatory loop.","Convection only works in solid metals.","Convection proves that temperature has no effect on density."]',1,'Hot air balloons fly because hot air is less dense and floats above cold air!','Convection: energy transfer by the movement of fluids, such as air or water. Warm air rising above a heater is an example of convection.','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_037','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Critique the assertion that a ''solar panel creates electricity out of nothing.''','["This assertion correctly describes how solar panels violate the laws of physics.","The assertion violates the First Law of Thermodynamics. A solar panel does not ''create'' energy; it is a photovoltaic transducer that absorbs existing electromagnetic radiation (light energy) from the Sun and transforms it into electrical current.","Solar panels actually extract electricity from the dirt.","Solar panels create energy by burning oxygen in the air."]',1,'You can''t make energy from nothing! The panel just catches the sun''s energy and changes its form.','Solar panel: Light energy → electrical energy. The law of conservation of energy in physics: energy cannot be created or destroyed; it can be transferred or transformed...','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_038','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Evaluate the role of ''Friction'' as an agent of energy transformation.','["Friction destroys energy completely.","Friction is a non-conservative force that constantly opposes kinetic motion. It acts as a primary agent of energy dissipation, inevitably transforming the useful kinetic energy of a moving object into disorganized, often unusable thermal energy (heat) and acoustic energy (sound).","Friction transforms heat energy into kinetic energy, speeding objects up.","Friction only transforms energy into light."]',1,'When you hit the brakes on a bike, the kinetic energy doesn''t die; friction turns it into heat on the brake pads!','Rubbing your hands together can warm them through friction... When a moving ball hits another object... some may become sound and thermal energy. Energy does not simply disappear...','2026-11-01 07:57:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_039','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Analyze why sound energy cannot travel through a ''perfect vacuum''.','["Because a vacuum is too loud.","Sound is a mechanical, longitudinal wave defined by the compression and rarefaction of physical matter. A perfect vacuum is devoid of all particulate matter, meaning there is no physical medium to transmit the kinetic vibrations.","Because sound is an electromagnetic wave that requires gravity.","Because sound travels too fast for a vacuum to hold it."]',1,'Sound is just particles bumping into each other; if there are no particles, there is no sound!','Sound needs a medium to travel through. It cannot travel through a perfect vacuum because there are no particles there to carry the sound vibrations.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_040','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Synthesize the concept of ''Chemical Energy'' as a form of potential energy.','["Chemical energy is actually a form of kinetic motion.","Chemical energy is microscopic potential energy stored within the electromagnetic bonds of molecules (like glucose in food or hydrocarbons in fuel). This energy remains ''stored'' until a chemical reaction (like digestion or combustion) breaks the bonds, releasing the energy as heat, light, or kinetic force.","Chemical energy only exists in batteries, not in nature.","Chemical energy is the energy of gravity."]',1,'The energy is locked inside the molecular structure, waiting to be unleashed!','Stored energy... Chemical energy: energy associated with substances such as food, fuels and batteries... Food is not energy itself; it contains chemical energy that the body can transfer and transform through chemical processes.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_041','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Evaluate the physics of ''Regenerative Braking'' in modern electric vehicles in the context of energy transformation.','["It creates endless energy from nothing.","Traditional brakes waste kinetic energy as thermal energy (friction). Regenerative braking captures the vehicle''s kinetic energy and transforms it back into electrical energy via a generator, storing it in the battery and significantly increasing the vehicle''s overall systemic efficiency.","It uses electricity to make the brakes hotter.","It turns light energy directly into kinetic energy."]',1,'Instead of losing the speed as wasted heat, the car turns the speed back into electricity for the battery!','Energy efficiency: Using less energy to provide the same useful service... (Synthesis: Capturing wasted kinetic energy and turning it back into electrical energy is highly efficient).','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_042','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Critique the phrase: ''Close the refrigerator door so the cold energy doesn''t escape.''','["The phrase is perfectly accurate in thermodynamics.","In physics, there is no such thing as ''cold energy''; cold is merely the absence of thermal energy. The scientifically accurate phrasing is that closing the door prevents the external, ambient thermal energy (heat) from entering the refrigerator and warming the interior.","The cold energy will escape and freeze the room.","The phrase is wrong because refrigerators do not use energy."]',1,'Heat moves into the fridge; ''cold'' does not move out!','Heat is energy transferred because of a temperature difference: it flows naturally from a warmer object or region to a cooler one.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_043','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Analyze how the ''Mass'' and ''Velocity'' of an object independently dictate its Kinetic Energy.','["Mass and velocity have no effect on kinetic energy.","Kinetic energy is directly proportional to mass, but exponentially proportional to velocity (\\\\(KE = \frac{1}{2}mv^2\\\\)). Therefore, while doubling a car''s mass doubles its kinetic energy, doubling its speed quadruples its kinetic energy, making high-speed collisions exponentially more destructive.","Mass is the only thing that matters for kinetic energy.","Kinetic energy only applies to objects at rest."]',1,'A heavy truck has a lot of energy, but a fast truck has an extreme amount of energy!','For objects of the same mass, a faster-moving object has more kinetic energy... For objects moving at the same speed, a greater mass means more kinetic energy.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_044','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Synthesize how a ''microphone and speaker system'' represents a closed loop of energy transformations.','["It only uses sound energy.","The microphone acts as a transducer, converting incoming acoustic (sound) energy into an electrical signal. This electrical energy travels through wires to the speaker, which acts as a reverse transducer, converting the electrical energy back into kinetic vibrations and resulting sound energy.","It converts light into sound directly.","It destroys electrical energy to make silence."]',1,'Your voice vibrates a magnet (making electricity), the electricity travels a wire, and vibrates another magnet (making sound)!','Speaker: Electrical energy → sound energy... Sound is produced when objects vibrate.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energy_global_045','Physics','Energy and Its Forms','Topic 6: Energy and Its Forms','Primary',10,'Evaluate the role of ''Radiation'' as the primary mechanism for Earth''s biosphere survival.','["Radiation instantly kills all life on Earth.","Because the vast expanse between the Sun and Earth is a near-perfect vacuum, conduction and convection are impossible. Electromagnetic radiation is the singular mechanism by which life-sustaining solar energy can cross the vacuum of space to drive Earth''s climate and photosynthetic food webs.","Radiation is only used by human-made machines like microwaves.","Earth survives solely on geothermal conduction from its core."]',1,'Without radiation, the Earth would freeze instantly because the Sun''s heat couldn''t cross empty space!','Sound... cannot travel through a perfect vacuum... Radiation: energy transfer by waves, including sunlight travelling through space... Plants use energy from sunlight to make food.','2026-11-01 07:57:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_001','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What is a ''source of light''?','["Something that blocks all light","Something that produces its own visible light","An object that is completely black","A shadow on the ground"]',1,'The Sun and a lightbulb are examples.','A source of light is something that produces its own visible light.','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_002','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'Which of these is a ''natural'' source of light?','["An electric lamp","A torch (flashlight)","The Sun","A television screen"]',2,'It exists without humans making it.','Natural sources occur in nature. Examples include: The Sun...','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_003','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'Which of these is an ''artificial'' source of light?','["A star","Lightning","A firefly","An electric lamp"]',3,'Humans built this light source.','Artificial sources are made by humans. Examples include: Electric lamps...','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_004','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'How does light travel through a clear material?','["In zig-zag patterns","In straight lines","In circles","It curves around objects"]',1,'It goes straight until it hits something.','Light travels in straight lines through a uniform transparent material.','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_005','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What does it mean if a material is ''transparent''?','["It blocks all light.","It allows most light to pass through so objects can be seen clearly.","It makes things look blurry.","It reflects all light."]',1,'Clear window glass is transparent.','Transparent: Allows most light to pass through so objects can be seen clearly.','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_006','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What does it mean if a material is ''opaque''?','["It does not allow visible light to pass through.","It lets you see clearly through it.","It creates a rainbow.","It is made of glass."]',0,'A wooden door is opaque.','Opaque: Does not allow visible light to pass through.','2026-11-01 07:57:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_007','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What does it mean if a material is ''translucent''?','["It blocks all light like a wall.","It allows some light through but scatters it, so objects appear blurred.","It acts perfectly like a mirror.","It is a source of light."]',1,'Frosted glass is translucent.','Translucent: Allows some light through but scatters it, so objects appear blurred.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_008','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'How is a ''shadow'' formed?','["When light turns into darkness","When an opaque object blocks light from reaching a surface behind it","When a mirror reflects light","When a transparent object lets light through"]',1,'When you stand in the sun, your body blocks the light from hitting the ground!','A shadow forms when an opaque object blocks light from reaching a surface or region behind it.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_009','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What happens when light ''reflects'' off a surface?','["The light disappears.","The light bounces off the surface.","The light bends in half.","The light turns into heat."]',1,'A mirror is very good at doing this.','Reflection occurs when light bounces off a surface.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_010','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What is ''refraction''?','["Light bouncing off a mirror","The change in direction of light as it passes from one material into another","Light turning into a shadow","Light traveling in a perfectly straight line forever"]',1,'It makes a pencil look bent in a glass of water.','Refraction is the change in direction of light as it passes from one material into another, such as from air into water.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_011','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'Which two things interact to produce a rainbow?','["Sunlight and water droplets","A mirror and a flashlight","A shadow and a wall","Lightning and snow"]',0,'You see it in the sky after it rains while the sun is shining.','White light, such as sunlight... water droplets can refract, reflect and separate the colours of sunlight to produce a rainbow.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_012','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What is the ''pupil'' of the human eye?','["The part that senses light at the back of the eye","The colored part of the eye","The opening through which light enters","The nerve that sends signals to the brain"]',2,'It is the black circle in the middle of your eye.','Pupil: the opening through which light enters.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_013','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What is the ''retina'' of the human eye?','["The clear front surface","A light-sensitive layer at the back that converts light into nerve signals","The colored part","The opening for light"]',1,'It acts like the film in a camera.','Retina: a light-sensitive layer that converts light into nerve signals.','2026-11-01 07:57:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_014','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'What does the ''optic nerve'' do?','["It changes the color of the eye.","It carries signals from the eye to the brain.","It stops light from entering the eye.","It creates tears."]',1,'It tells your brain what you are looking at.','Optic nerve: carries signals from the eye to the brain.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_015','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',1,'Which of these is a safe way to care for your eyes?','["Looking directly at the Sun","Reading in the dark","Looking directly at a bright laser","Taking regular breaks from prolonged close-up work"]',3,'Give your eyes a rest when reading or using a screen!','Caring for our eyes... Take regular breaks from prolonged close-up work. Avoid looking directly at the Sun or bright lasers.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_016','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why is the Moon NOT considered a source of light?','["Because it is only visible during the day.","Because it does not produce its own visible light; it only reflects the light produced by the Sun.","Because it is actually a star.","Because the Moon is transparent."]',1,'It acts like a giant, rocky mirror in space!','The Moon also reflects sunlight rather than producing its own visible light.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_017','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'How does light allow us to see an object like a book?','["Our eyes shoot light out to hit the book.","The book produces its own light and sends it to our eyes.","Light from a source hits the book, reflects off it, and travels into our eyes.","The book turns light into sound."]',2,'Light bounces off the object and into your eye!','How do we see an object? Light comes from a source... The light reaches an object. Some light reflects off the object. Reflected light enters our eyes.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_018','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why can light travel through the empty vacuum of space, but sound cannot?','["Because space is too bright for sound.","Because light does not require a material medium (like air or water) to travel, whereas sound relies on vibrating particles.","Because light is much heavier than sound.","Because sound gets frozen in space."]',1,'Light is a type of radiation that doesn''t need particles to move!','Light can travel through empty space... Unlike sound, light does not require air or another material medium to travel.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_019','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'If you want to create a larger shadow on a wall using a flashlight and a toy, what should you do?','["Move the toy further away from the flashlight.","Move the toy closer to the flashlight.","Turn the flashlight off.","Paint the toy a different color."]',1,'If the object is close to the light, it blocks a wider angle of the light beam!','What changes the size of a shadow? When an object moves closer to a nearby light source, its shadow often becomes larger.','2026-11-01 07:57:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_020','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why do shadows outside look very long in the early morning and late evening, but short at midday?','["Because the Sun''s light is weaker in the morning.","Because as the Sun appears to move across the sky, a low Sun hits objects from the side (making long shadows), and a high Sun at midday hits them from above (making short shadows).","Because objects grow taller in the morning.","Because the Earth stops spinning at midday."]',1,'When the sun is right above you, your shadow is hidden right under your feet!','Why do shadows change during the day? ... In many situations, shadows are long when the Sun is low in the sky and shorter when the Sun is high overhead.','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_021','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'How is a mirror different from a rough piece of wood when light hits it?','["A mirror absorbs all the light, wood reflects it.","A smooth mirror reflects light in an organized way to form a clear image, while wood reflects light in many scattered directions, so no clear image forms.","A mirror bends light using refraction, wood uses reflection.","There is no difference; they both form clear images."]',1,'The light bounces perfectly off the smooth mirror, but bounces crazily off the bumpy wood!','A smooth mirror reflects light in an organised way, allowing a clear image to form. Rough surfaces also reflect light, but they scatter it in many directions...','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_022','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why does a pencil look bent or broken when you place it halfway into a glass of water?','["Because the water melts the pencil.","Because of refraction; light travels at different speeds in water than in air, causing the light rays to change direction as they leave the water.","Because the glass acts as a mirror.","Because the pencil creates a shadow underwater."]',1,'The light from the pencil bends before it hits your eye, tricking your brain!','For example, a pencil partly submerged in water may appear bent at the surface... light from the submerged part changes direction as it travels from water into air (Refraction).','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_023','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'How does a ''lens'' (like in eyeglasses or a magnifying glass) work?','["It creates its own light source.","It uses refraction to bend light rays in a specific way, helping to focus the light and form clear or larger images.","It blocks all light to create a shadow.","It acts as a solid, opaque wall."]',1,'A lens bends the light so it hits your eye perfectly!','Lenses use refraction to change the paths of light rays and help form images. Refraction is important in: Eyeglasses, Magnifying glasses...','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_024','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why do we see a rainbow as many different colors?','["Because rain is dyed with different food colors.","Because white sunlight actually contains a range of colors; water droplets act like tiny prisms that refract and separate the white light into its visible colors.","Because the sun changes color during a storm.","Because shadows mix together to make colors."]',1,'White light is actually a mix of every color; the water separates them!','White light, such as sunlight, contains a range of visible colours. Under suitable conditions, water droplets can refract, reflect and separate the colours of sunlight to produce a rainbow.','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_025','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'What is the function of the ''lens'' inside the human eye?','["It changes the color of the eye.","It helps focus the incoming light onto the retina at the back of the eye.","It carries signals to the brain.","It stops dust from entering the pupil."]',1,'It acts just like the lens in a camera to make the picture sharp!','Lens: helps focus light onto the retina.','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_026','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why is ''tracing paper'' considered translucent rather than transparent?','["Because you can see perfectly clearly through it.","Because it allows some light to pass through, but the light is scattered, so you can''t see a sharp, clear image on the other side.","Because it blocks 100% of all light.","Because it is an artificial source of light."]',1,'You can see light shining behind it, but you can''t read a book through it!','Translucent: Allows some light through but scatters it, so objects appear blurred. Examples: ...tracing paper...','2026-11-01 07:57:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_027','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'If you want to sleep in a dark room during the day, what kind of material should your curtains be made of?','["Transparent","Translucent","Opaque","Reflective"]',2,'Opaque curtains will block the sunlight completely!','Opaque: Does not allow visible light to pass through.','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_028','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'What happens to the pupil of an eye when a bright light is shined on it?','["The iris controls it, causing the pupil to get smaller to protect the eye from too much light.","The pupil disappears completely.","The pupil gets massively larger.","The pupil turns into a retina."]',0,'Your eye reacts to protect itself from bright light!','Iris: the coloured part that controls the size of the pupil.','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_029','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'Why is it important to NEVER look directly at the Sun or a bright laser?','["Because it will make you fall asleep.","Because the intense light energy can severely and permanently damage the sensitive retina at the back of your eye.","Because it causes shadows to disappear.","Because it will make your eyes change color."]',1,'The sun''s light is so powerful it can burn the inside of your eye!','Caring for our eyes... Avoid looking directly at the Sun or bright lasers. (The retina is a light-sensitive layer).','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_030','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',5,'How does a prism work similarly to a raindrop?','["They both make things wet.","Both can refract (bend) white light and separate it into the different colors of the rainbow sequence.","They both block light completely to make shadows.","They both act as a perfect mirror."]',1,'A prism is a special piece of glass that splits light just like a raindrop does!','Prisms can also separate white light into different colours. (Similar to water droplets producing a rainbow).','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_031','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Critique the linguistic accuracy of the phrase ''The Moon is shining bright tonight.''','["The phrase is perfectly accurate scientifically.","The phrase implies the Moon is an active source emitting photons. Scientifically, the Moon is a passive, opaque celestial body; it only appears bright because it acts as a massive reflector, redirecting incident solar radiation (sunlight) toward Earth.","The phrase is wrong because the Moon is actually transparent.","The phrase is wrong because the Moon only shines during the day."]',1,'The Moon doesn''t shine; it just bounces the Sun''s shine!','The Moon appears bright because it reflects sunlight; it does not produce its own visible light like the Sun.','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_032','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Analyze the electromagnetic property of ''White Light''.','["White light is a single, pure color that has no other parts.","White light is not a singular color, but a composite optical phenomenon. It is the visible result of all constituent wavelengths of the visible electromagnetic spectrum (red through violet) combining and striking the human retina simultaneously.","White light is actually just very bright blue light.","White light is created when shadows mix together."]',1,'White isn''t one color; it is EVERY color mixed together!','White light, such as sunlight, contains a range of visible colours... Prisms can also separate white light into different colours.','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_033','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Synthesize how the concept of ''Specular vs. Diffuse Reflection'' explains why we can see our face in a mirror but not in a white wall.','["A wall absorbs all light, a mirror does not.","A mirror has a microscopically smooth surface, creating specular reflection (parallel light rays remain parallel, preserving an image). A wall has a microscopically rough surface, causing diffuse reflection (light scatters randomly, destroying the image while still illuminating the wall).","A mirror uses refraction to create an image, a wall uses reflection.","A wall is transparent, while a mirror is translucent."]',1,'The wall bounces light into your eye so you can see the wall, but it scatters the light so much you can''t see your reflection in it!','A smooth mirror reflects light in an organised way, allowing a clear image to form. Rough surfaces also reflect light, but they scatter it in many directions, so they usually do not form a clear mirror-like image.','2026-11-01 07:57:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_034','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Evaluate the physical mechanics of ''Refraction'' based on optical density.','["Refraction happens because water absorbs light and destroys it.","Refraction occurs when a light wave crosses an interface between two transparent media with different optical densities (e.g., air to water). The change in density forces the light wave to alter its velocity, which geometrically bends the path of the light ray.","Refraction proves that light travels in circles, not straight lines.","Refraction only happens when light hits an opaque object."]',1,'When a car drives from a fast paved road into thick mud, it slows down and swerves; light does the same thing when entering water!','Refraction is the change in direction of light as it passes from one material into another... This happens because light travels at different speeds in different materials.','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_035','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Analyze how the ''Retina'' functions as an analog to a digital camera sensor.','["The retina is a piece of glass that bends the light.","The retina acts as the biological transducer at the focal plane of the eye. Like a camera sensor, it receives focused incoming photons and converts that electromagnetic light energy into electrochemical nerve signals, which are transmitted to the brain for image processing.","The retina is the hole that lets light into the eye.","The retina controls the color of the eye."]',1,'The retina turns the actual light into an electrical code your brain can read!','Retina: a light-sensitive layer that converts light into nerve signals. Optic nerve: carries signals from the eye to the brain.','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_036','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Synthesize the geometrical relationship between an object, a light source, and the resulting ''Umbra'' (shadow).','["The shadow is always exactly the same size as the object.","Because light travels in straight linear paths (rectilinear propagation), moving an opaque object closer to a point light source geometrically increases the angle of intercepted rays, casting a proportionally larger shadow on a fixed background screen.","The shadow gets smaller as the object gets closer to the light.","Light bends around the object to completely eliminate the shadow."]',1,'Draw a straight line from the lightbulb, past the edge of the object, to the wall; moving the object closer to the bulb makes that line hit the wall higher up!','Light travels in straight lines... When an object moves closer to a nearby light source, its shadow often becomes larger.','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_037','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Critique the assertion that ''Empty space is completely dark because there is no light in it.''','["The assertion is true; light cannot exist in space.","The assertion conflates the presence of light with the visibility of light. Space is saturated with solar radiation (light), but it appears dark because it is a vacuum; there is no particulate matter (like dust or air) to scatter or reflect the light into an observer''s eye.","The assertion is true because the Sun turns off in space.","Space is dark because it is completely filled with opaque rocks."]',1,'You can only see a flashlight beam in a dark room if there is dust or smoke in the air to reflect it!','Light can travel through empty space, which is how sunlight reaches Earth... We see most objects when light reflects from them into our eyes. (Synthesis: If there is nothing in space to reflect the light into your eye, it looks dark).','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_038','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Evaluate how ''Lenses'' manipulate refraction for technological advancement.','["Lenses block light to create detailed shadows.","Lenses are engineered transparent materials with precisely curved surfaces designed to manipulate the refraction angle of incident light. By converging or diverging light rays, lenses correct biological vision defects (eyeglasses) or magnify microscopic/distant objects (microscopes/telescopes).","Lenses are perfect mirrors that reflect images.","Lenses only change the color of light."]',1,'A lens forces the light rays to bend in exactly the right way so they meet at a perfect focus point!','Lenses use refraction to change the paths of light rays and help form images. Refraction is important in: Eyeglasses... Microscopes, Telescopes.','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_039','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Analyze the specific atmospheric and geometric conditions required to view a ''Rainbow''.','["A rainbow occurs whenever it rains, regardless of the Sun.","A rainbow requires precise geometry: the observer must be positioned between a low-angle Sun (behind them) and a field of suspended water droplets (in front of them). The droplets act as individual prisms, refracting, internally reflecting, and dispersing the white sunlight back toward the observer.","The Sun must be directly in front of the observer.","A rainbow only forms at midnight."]',1,'The sun has to shine over your shoulder and hit the rain in front of you!','Under suitable conditions, water droplets can refract, reflect and separate the colours of sunlight... A rainbow is usually seen when the Sun is behind the observer and water droplets are in the part of the sky ahead.','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_040','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Synthesize how ''Opaque'', ''Translucent'', and ''Transparent'' materials affect the absorption and transmission of photons.','["They all transmit 100% of photons perfectly.","Transparent materials transmit photons with minimal scattering. Translucent materials transmit photons but severely scatter their vectors, destroying image coherence. Opaque materials have atomic structures that entirely absorb or reflect incident photons, reducing transmission to zero.","Opaque materials transmit photons, transparent materials absorb them.","Translucent materials only transmit sound waves, not light."]',1,'It''s about whether the light passes through straight, gets scrambled, or gets blocked completely!','Transparent: Allows most light to pass... Translucent: Allows some light through but scatters it... Opaque: Does not allow visible light to pass...','2026-11-01 07:57:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_041','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Evaluate the evolutionary purpose of the ''Iris'' and ''Pupil'' in the human eye under varying light conditions.','["The iris is purely decorative and serves no function.","The iris is a dynamic muscular diaphragm that regulates the aperture (pupil) size to maintain optimal retinal exposure. It constricts in high-intensity light to prevent phototoxic retinal damage, and dilates in low-light to maximize photon capture for night vision.","The pupil produces light so humans can see in the dark.","The iris stops the eye from falling out."]',1,'It acts just like the aperture ring on a camera, opening wide in the dark and closing tight in the bright sun!','Iris: the coloured part that controls the size of the pupil. Pupil: the opening through which light enters.','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_042','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Critique the common belief that a shadow is a physical ''thing'' or substance.','["A shadow is made of dark matter particles.","A shadow is not a physical entity or substance; it is an optical absence. It is simply a two-dimensional geometric region on a surface where ambient illumination is occluded (blocked) by an intervening opaque object.","A shadow is a type of gas.","A shadow is a reflection of the object."]',1,'A shadow isn''t a ''thing'' that exists; it is just a spot where the light didn''t hit!','A shadow forms when an opaque object blocks light from reaching a surface or region behind it... A shadow: A dark region formed when an object blocks light.','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_043','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Analyze how the ''Optic Nerve'' completes the process of vision.','["The optic nerve shines light back out of the eye.","Vision does not occur in the eye; it occurs in the visual cortex. The optic nerve acts as the biological data cable, transmitting the electrochemical action potentials generated by the retina to the brain, where the raw data is inverted and interpreted into a conscious image.","The optic nerve is the part of the eye that bends the light.","The optic nerve is completely unnecessary for seeing."]',1,'The eye is just the camera; the brain is the computer that actually ''sees'' the picture!','Optic nerve: carries signals from the eye to the brain. Our eyes detect light and send signals to the brain, which interprets them so that we can see.','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_044','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Synthesize the relationship between the ''speed of light'' and the phenomenon of ''refraction''.','["Refraction proves that light travels at the exact same speed in every material.","Refraction is a direct consequence of light altering its velocity based on the optical density of the medium. When a light wavefront enters a denser medium (like glass) at an angle, one side of the wave slows down before the other, causing the entire wave''s path to pivot or bend.","Refraction makes light travel faster than normal.","The speed of light only affects shadows, not refraction."]',1,'Imagine pushing a shopping cart from a smooth floor onto thick carpet at an angle; the cart pulls to one side because one wheel slows down first!','Refraction is the change in direction of light... This happens because light travels at different speeds in different materials.','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_045','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Evaluate the physical impossibility of a ''transparent shadow''.','["Transparent shadows happen every day.","Because a shadow is defined as the region where light is blocked, a perfectly transparent object (which transmits almost all light) cannot cast a distinct, dark shadow. Only opaque or highly translucent objects possess the requisite light-blocking properties to form a true umbra.","Transparent objects actually cast the darkest shadows.","A transparent shadow is created by a mirror."]',1,'If the light goes straight through the object, there is no dark spot behind it!','A shadow forms when an opaque object blocks light... Transparent: Allows most light to pass through...','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_light_global_046','Physics','Light and Shadows','Topic 7: Light and Shadows','Primary',10,'Analyze why the color ''black'' is essentially the optical opposite of ''white light''.','["Black is exactly the same as white light.","While white light is the additive synthesis of all visible electromagnetic wavelengths striking the eye, black is the absence of light. An object appears black because it acts as a perfect absorber, soaking up all incident visible wavelengths and reflecting zero photons to the observer''s eye.","Black light is a specific wavelength that destroys white light.","Black is created by a prism mixing all colors together."]',1,'White means bouncing all the colors to your eye; black means swallowing all the colors so your eye sees nothing!','White light, such as sunlight, contains a range of visible colours... We see most objects when light reflects from them into our eyes. (Synthesis: If an object does not reflect any colors, it appears black).','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_001','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What produces sound?','["Light shining on an object","Vibrating objects moving back and forth","A shadow hitting a wall","Electricity stopping"]',1,'When you hit a drum, it shakes to make the noise.','Sound is a form of energy produced by vibrating objects.','2026-11-01 07:57:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_002','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What is a ''vibration''?','["A loud noise","A repeated back-and-forth movement","A color changing","A type of light"]',1,'Think of a guitar string shaking when you pluck it.','A vibration is a repeated back-and-forth movement.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_003','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What does sound travel through?','["Only empty space","A medium such as a gas, liquid, or solid","Only through metal","Only through light"]',1,'It can travel through the air, water, or even a wooden door.','Sound travels through a medium—a material such as a gas, liquid or solid.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_004','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What does ''pitch'' tell us?','["How loud a sound is","How high or low a sound seems","How fast the sound travels","How bright the sound is"]',1,'A bird chirp is high; a lion roar is low.','Pitch tells us whether a sound seems high or low.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_005','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What type of vibration produces a ''high-pitched'' sound?','["Slower vibrations","Faster vibrations","No vibrations","Only heavy vibrations"]',1,'The faster the shaking, the higher the squeak!','A high-pitched sound is produced by faster vibrations.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_006','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What type of vibration produces a ''low-pitched'' sound?','["Slower vibrations","Faster vibrations","Invisible vibrations","Silent vibrations"]',0,'A big, slow bass drum makes a low boom.','A low-pitched sound is produced by slower vibrations.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_007','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What unit is used to measure ''frequency'' (how fast something vibrates)?','["Kilograms","Metres","Hertz (Hz)","Degrees"]',2,'It means how many times it vibrates every second.','Frequency is measured in hertz (Hz).','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_008','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What does ''loudness'' describe?','["How high or low a sound is","How loud or quiet a sound seems","The color of the sound","The speed of the sound wave"]',1,'A whisper is quiet; a shout is loud.','Loudness describes how loud or quiet a sound seems.','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_009','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What unit is commonly used to measure sound level (loudness)?','["Hertz","Decibels (dB)","Litres","Kilometres"]',1,'A higher decibel number means a louder sound.','Sound level is commonly measured in decibels (dB).','2026-11-01 07:57:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_010','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What is an ''echo''?','["A sound that disappears instantly","A reflected sound heard again after bouncing off a surface","A sound made by a musical instrument","A completely silent room"]',1,'You hear it when you shout into a large, empty cave.','An echo is a reflected sound heard again after the original sound.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_011','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What part of the human ear vibrates when sound waves reach it?','["The pupil","The retina","The eardrum","The nose"]',2,'It acts just like the skin of a drum!','Eardrum: vibrates when sound waves reach it.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_012','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What does the ''auditory nerve'' do?','["It vibrates to make sound.","It carries electrical nerve signals to the brain so we can hear.","It catches the sound waves from the air.","It protects the ear from water."]',1,'It is the wire that connects your ear to your brain.','Auditory nerve: carries these signals to the brain, which interprets them as sound.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_013','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'What is ''noise pollution''?','["A pleasant song on the radio","Unwanted or excessive sound that disturbs people, animals, or the environment","A completely silent forest","A type of water pollution"]',1,'Loud traffic outside your window is an example.','Noise pollution is unwanted or excessive sound that disturbs people, animals or the environment.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_014','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'Which of these is a way to protect your hearing?','["Listening to headphones at maximum volume","Standing next to a loud machine","Keeping headphones at a moderate volume and taking listening breaks","Shouting into someone''s ear"]',2,'Loud noises can damage your ears forever!','How can we protect our hearing? Keep headphones and speakers at a moderate volume. Take listening breaks.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_015','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',1,'How does a string instrument (like a guitar) make a sound?','["By vibrating the air directly","The strings vibrate when plucked or bowed","By hitting a drum skin","By turning on a light"]',1,'You pull the string, it shakes, and makes a sound.','String instruments: Guitar and violin strings vibrate when plucked or bowed.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_016','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why is ''pitch'' not the same thing as ''loudness''?','["Because pitch is for animals and loudness is for humans.","A sound can have a high pitch but be very quiet (like a small whistle), or have a low pitch but be very loud (like a massive drum).","Because pitch is measured in meters and loudness is measured in seconds.","Because they are exactly the same thing."]',1,'Pitch is the ''note'' (high/low); loudness is the ''volume'' (loud/quiet).','Pitch is not the same as loudness. A high-pitched sound can be quiet or loud. A low-pitched sound can also be quiet or loud.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_017','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why is it impossible to hear an explosion in the empty vacuum of outer space?','["Because space is too loud already.","Because sound travels by disturbing particles in a medium (like air or water); since a vacuum has no particles, the vibrations cannot travel.","Because gravity pulls the sound back to Earth.","Because sound waves freeze in space."]',1,'Without air to shake, the sound can''t travel!','Sound needs a medium to travel through. It cannot travel through a perfect vacuum because there are no particles there to carry the sound vibrations.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_018','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'How does a sound wave travel from a ringing bell to your ear?','["The bell shoots a laser beam to your ear.","The vibrating bell physically moves the air particles next to it, which bump into the next particles, creating a wave of pressure changes that travels to your ear.","The bell creates a vacuum that pulls your ear.","The bell turns the air into a solid."]',1,'It''s like dominoes falling; the vibrating bell knocks the air particles into each other all the way to your ear!','When an object vibrates... These movements disturb nearby particles, creating sound waves that travel through the surrounding material... It moves as a wave of pressure changes caused by vibrating particles.','2026-11-01 07:57:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_019','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why does a room with soft carpets and curtains usually sound less ''echoing'' than an empty room with hard floors?','["Because soft materials absorb some of the sound energy, reducing the amount of sound that bounces (reflects) back.","Because hard floors absorb all the sound instantly.","Because carpets create their own sound waves.","Because soft materials make the room completely silent."]',1,'Hard walls bounce the sound back perfectly; soft carpets soak it up!','Soft materials, such as curtains and carpets, absorb some sound energy and can reduce reflections. This is one reason furnished rooms often sound less echoing than empty rooms.','2026-11-01 07:57:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_020','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'If a sound has a frequency of 500 Hz, what does that mean?','["The sound is 500 decibels loud.","The object making the sound is completing 500 vibration cycles every single second.","The sound takes 500 seconds to reach your ear.","The sound weighs 500 kilograms."]',1,'Hz is just a way of counting how many times the object shakes in one second.','Frequency is measured in hertz (Hz). One hertz means one vibration cycle per second. A sound with a frequency of 500 Hz has 500 vibration cycles per second.','2026-11-01 07:57:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_021','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'How does a musician playing a guitar change the ''pitch'' of the sound they are making?','["By hitting the guitar with a hammer.","By pressing the string against different frets, which changes the vibrating length of the string (and therefore its frequency).","By turning off the lights in the room.","By making the guitar louder."]',1,'A shorter string shakes faster, making a higher-pitched sound!','Musicians change pitch by changing the frequency of vibration. For example, a guitarist changes the vibrating length of a string by pressing it against different frets.','2026-11-01 07:57:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_022','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'How does ''sonar'' technology on a submarine use the physics of sound?','["It uses light to see underwater.","It sends out a sound wave and listens for the ''echo'' (reflected sound) bouncing off objects to figure out where things are underwater.","It uses a giant vacuum to pull things closer.","It freezes the water to make it transparent."]',1,'It''s like shouting in a cave to hear if there is a wall in front of you!','Where are echoes useful? Sonar systems use reflected sound to detect objects underwater.','2026-11-01 07:57:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_023','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why does a sound usually become quieter as you move farther away from the source?','["Because the sound waves turn into light.","As the sound wave travels, the energy spreads out over a larger area, so the strength of the vibration reaching your ear is weaker.","Because the sound waves actually get faster.","Because your ears stop working."]',1,'The energy gets spread out in a giant circle, so less of it hits your ear!','Distance from the source also matters: a sound usually becomes quieter as you move farther away.','2026-11-01 07:57:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_024','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'What is the job of the ''cochlea'' in the human ear?','["To block loud sounds from entering.","It is a fluid-filled structure that converts the physical vibrations into electrical nerve signals.","It is the fleshy outside part that catches the sound.","It is the bone that connects to the brain."]',1,'It translates the shaking air into an electrical code your brain can understand!','Cochlea: a fluid-filled structure in the inner ear that converts vibrations into electrical nerve signals.','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_025','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why is ''noise pollution'' considered a problem for wildlife?','["It makes the animals dance.","Excessive noise can interfere with wildlife communication, making it hard for animals to find mates, hunt, or hear predators approaching.","It causes the animals to go to sleep.","It actually helps animals communicate better."]',1,'If a bird can''t hear another bird singing because of a loud highway, they can''t communicate!','Noise pollution... Excessive noise from traffic... can disturb sleep, affect health and interfere with wildlife communication.','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_026','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'What happens when you pluck a stretched rubber band around a box?','["The rubber band melts.","The band vibrates back and forth, disturbing the air and producing a sound.","The rubber band turns into a liquid.","The rubber band creates a bright light."]',1,'You can actually see the blur of the vibration while you hear the sound!','Pluck a rubber band stretched around an empty box: the band vibrates and produces sound.','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_027','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'In general, does sound travel faster through water or through the air?','["It travels exactly the same speed in both.","Sound generally travels faster through water (and solids) than through air.","It travels much faster through air.","Sound cannot travel through water at all."]',1,'The particles in water are closer together, so they can bump into each other faster!','Sound generally travels faster through water and many solids than through air...','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_028','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'What does it mean when the lesson says the ''instrument''s design affects the quality or tone of its sound''?','["It means all instruments sound exactly the same.","It means that even if a flute and a guitar play the exact same pitch (note), they sound completely different because of their physical shape and material.","It means you can''t hear the instrument if it is painted red.","It means the instrument doesn''t make any sound."]',1,'A wooden box sounds different than a metal tube, even if they vibrate at the same speed!','The instrument''s design also affects the quality or tone of its sound, helping us distinguish a flute from a guitar even when they play the same note.','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_029','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'Why should you NEVER use high-volume sound to test your hearing?','["Because it will waste electricity.","Very loud sounds can cause permanent damage to the delicate structures inside your inner ear (like the cochlea), leading to hearing loss.","Because it will make the room too hot.","Because loud sounds actually fix your hearing."]',1,'Once those tiny parts inside your ear break, they don''t heal!','Safety: ... never use high-volume sound to test hearing. Very loud sounds can damage delicate structures in the inner ear. Hearing damage can be permanent...','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_030','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',5,'What is the function of the ''middle-ear bones''?','["They create the sound waves.","They transmit and amplify (make stronger) the vibrations from the eardrum before sending them to the cochlea.","They connect the eye to the brain.","They clean the ear canal."]',1,'They act like tiny levers to boost the shaking so you can hear clearly!','Middle-ear bones: transmit and amplify the vibrations.','2026-11-01 07:57:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_031','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Critique the sci-fi movie trope of hearing a massive spaceship explosion in deep space.','["The trope is scientifically accurate because explosions create their own air.","The trope violates the physics of acoustics. Sound requires a particulate medium (matter) to propagate mechanical pressure waves. Deep space is a near-perfect vacuum; without particles to transmit the vibration, the explosion would be completely silent to an outside observer.","The trope is wrong because explosions in space only create high-pitched sounds.","The trope is correct, but only if the spaceship is made of metal."]',1,'You can see the flash of light in space, but you would never hear the ''boom''!','Sound cannot travel through a perfect vacuum because there are no particles to carry the vibrations. Space is mostly a vacuum... a sound-producing event in space would not be heard directly by a nearby observer...','2026-11-01 07:57:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_032','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Analyze the mechanical relationship between ''Frequency (Hz)'' and ''Pitch''.','["Frequency determines how loud the sound is, not the pitch.","Frequency is the objective, physical measurement of vibration cycles per second (Hz). Pitch is the subjective, psychoacoustic perception of that frequency by the human brain. A higher objective frequency is processed as a ''higher'' perceived pitch.","Frequency and pitch are unrelated concepts.","Pitch is measured in Hz, while frequency is how loud it is."]',1,'Hz is the math; Pitch is what your brain actually hears!','Pitch tells us whether a sound seems high or low. It depends mainly on the frequency of vibration... Frequency is measured in hertz (Hz).','2026-11-01 07:57:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_033','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Synthesize how the concept of ''acoustic impedance'' explains why sound travels faster in solids than in gases.','["Sound travels faster in gases because gases are lighter.","In a solid, the atoms are densely packed and chemically bonded in a rigid lattice. When one particle vibrates, it immediately and efficiently transfers the kinetic energy to adjacent particles. In a gas, particles are sparse, meaning it takes longer for the pressure wave to propagate between collisions.","Sound travels faster in solids because solids create vacuums.","Sound actually travels at the exact same speed in all materials."]',1,'Imagine pushing a line of tightly packed dominoes (solid) versus a line of dominoes spaced far apart (gas); the packed ones fall much faster!','Sound generally travels faster through water and many solids than through air...','2026-11-01 07:57:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_034','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Evaluate the physiological mechanics of the ''Cochlea'' as a biological transducer.','["The cochlea simply acts as a drum that echoes the sound louder.","The cochlea functions as a biological transducer. It receives the mechanical, kinetic energy (vibrations) transmitted through the fluid inside it and converts that physical motion into electrochemical energy (nerve impulses) that the brain can decode.","The cochlea converts electrical signals into sound waves.","The cochlea prevents any sound from reaching the brain."]',1,'It translates the physical ''shaking'' of the world into an electrical code for the brain!','Cochlea: a fluid-filled structure in the inner ear that converts vibrations into electrical nerve signals.','2026-11-01 07:57:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_035','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Analyze the phenomenon of ''Medical Ultrasound'' based on the physics of sound reflection.','["Ultrasound uses dangerous radiation to burn images into film.","Ultrasound machines emit extremely high-frequency sound waves (above human hearing) into the body. These waves encounter different tissue densities and reflect (echo) back at different rates. The machine synthesizes these echoes to map a real-time visual image of internal structures.","Ultrasound uses vacuums to pull the sound out of the body.","Ultrasound is just a very loud noise that doctors listen to with their ears."]',1,'It''s literally using sonar to ''see'' inside a person!','Where are echoes useful? ... Medical ultrasound uses high-frequency sound waves and their echoes to produce images inside the body.','2026-11-01 07:57:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_036','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Synthesize how altering the ''length'' of a guitar string demonstrates the inverse relationship between length and frequency.','["A longer string vibrates faster, creating a higher pitch.","When a string is shortened (e.g., pressing a fret), the mass and length of the vibrating segment decrease. With the same tension, a shorter string completes a vibration cycle more rapidly (higher frequency), resulting in a higher perceived pitch, proving an inverse relationship.","A shorter string vibrates slower, creating a lower pitch.","Changing the length of the string only changes the loudness."]',1,'Shorten the string = faster shaking = higher note!','Musicians change pitch by changing the frequency of vibration. For example, a guitarist changes the vibrating length of a string by pressing it against different frets.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_037','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Critique the use of ''Decibels (dB)'' to measure perceived loudness.','["Decibels are a perfect measurement of how humans perceive sound.","Decibels provide an objective logarithmic measurement of sound intensity (pressure). However, perceived loudness is subjective and frequency-dependent; the human ear is highly sensitive to mid-range frequencies (like speech) but poorly perceives very low or high frequencies, even if they have the exact same dB level.","Decibels only measure the pitch of a sound.","Decibels measure the speed of the sound wave in water."]',1,'A dog whistle might be 100 dB, but you wouldn''t perceive it as ''loud'' because you can''t hear that frequency at all!','Sound level is commonly measured in decibels (dB). A decibel reading is a physical measurement; perceived loudness also depends on frequency and the listener.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_038','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Analyze why a ''furnishing a room'' drastically alters its acoustic profile.','["Furniture creates a vacuum that destroys sound.","Empty rooms feature hard, planar surfaces (walls/floors) that cause specular reflection, resulting in overlapping echoes (reverberation). Furnishing a room introduces soft, porous materials (carpets/sofas) that act as acoustic dampeners, absorbing the kinetic energy of the sound waves and preventing reflection.","Furniture generates its own sound waves that cancel out echoes.","Furniture actually increases the amount of echoing in a room."]',1,'A soft couch acts like a sponge for sound waves!','Soft materials, such as curtains and carpets, absorb some sound energy and can reduce reflections. This is one reason furnished rooms often sound less echoing than empty rooms.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_039','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Synthesize how the concept of ''Noise Pollution'' affects human cardiovascular and psychological health.','["Noise pollution is purely an aesthetic annoyance with no health effects.","Chronic exposure to excessive decibel levels (traffic, industry) triggers a persistent physiological stress response. The body constantly releases adrenaline and cortisol, leading to documented increases in hypertension (high blood pressure), sleep deprivation, and severe psychological distress.","Noise pollution actually improves cardiovascular health by keeping people awake.","Noise pollution only affects animals, not humans."]',1,'Living next to a loud highway doesn''t just annoy you; the constant stress actually damages your heart and health over time!','Noise pollution is unwanted or excessive sound that disturbs people... Excessive noise can interrupt sleep, make communication difficult, affect concentration and harm hearing.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_040','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Evaluate the mechanics of ''Wind Instruments'' compared to ''String Instruments''.','["Wind instruments use strings made of air.","While string instruments rely on the transverse vibration of a physical cord under tension, wind instruments (like flutes) rely on the longitudinal vibration of a column of air inside a resonant cavity. Changing the length of that air column (by pressing keys) changes the frequency and pitch.","Wind instruments do not vibrate at all.","Both instruments rely entirely on striking a drum skin."]',1,'In a flute, you aren''t shaking a string; you are shaking a tube of air!','String instruments: Guitar and violin strings vibrate... Wind instruments: Vibrating air columns produce sound in instruments such as flutes and recorders.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_041','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Analyze the statement: ''A high-pitched sound can be quiet or loud.'' What does this prove about the physics of a wave?','["It proves that pitch and loudness are the exact same thing.","It proves that frequency (pitch) and amplitude (loudness) are independent variables of a wave. Frequency is how *fast* the wave oscillates, while amplitude (loudness) is how *much energy* (or pressure) is in each oscillation.","It proves that high-pitched sounds are always loud.","It proves that wave physics is entirely random."]',1,'You can gently tap a tiny bell (high pitch, quiet) or smash it with a hammer (high pitch, loud)!','Pitch is not the same as loudness. A high-pitched sound can be quiet or loud... A stronger vibration often produces a louder sound...','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_042','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Critique the biological design of the ''Outer Ear'' (Pinna) in humans.','["The outer ear is completely useless and only holds glasses.","The pinna acts as an asymmetrical acoustic funnel. Its specific biological ridges and folds are engineered to capture, reflect, and direct sound waves into the ear canal. Furthermore, the way sound bounces off these folds helps the brain calculate the vertical elevation and direction of the sound source.","The outer ear creates sound waves and sends them into the world.","The outer ear is a fluid-filled sac that decodes electricity."]',1,'It acts like a fleshy satellite dish, catching the sound and pouring it into your head!','Outer ear: collects sound waves and directs them into the ear canal.','2026-11-01 07:57:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_043','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Synthesize how a ''Sonic Boom'' relates to the speed of sound propagation.','["A sonic boom occurs when sound waves completely stop moving.","A sonic boom is a shock wave created when an object (like a jet) travels faster than the speed of sound through a fluid medium (air). The object outpaces its own sound waves, causing them to compress into a massive, overlapping pressure cone that hits the ground as a continuous ''boom''.","A sonic boom is just a very loud drum.","A sonic boom only happens in the vacuum of space."]',1,'When a jet flies faster than sound, it piles all the sound waves up in front of it like a wall of pressure!','Sound travels through a medium... It moves as a wave of pressure changes caused by vibrating particles. (Synthesis: If you move faster than the wave you are creating, the pressure builds up).','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_044','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Evaluate the statement: ''Hearing damage can be permanent.'' What physiological reality does this highlight?','["It means the eardrum will just grow back stronger.","It highlights the fragility of the stereocilia (tiny hair cells) inside the cochlea. These specialized biological cells translate vibrations into nerve signals, but they do not regenerate in mammals. Once sheared or destroyed by excessive decibel levels, the resulting sensorineural hearing loss is irreversible.","It means you can just replace your ear with a new one.","It is a myth; hearing damage always heals overnight."]',1,'The tiny hairs inside your ear are like blades of grass; if a loud noise tramples them flat, they never stand back up!','Very loud sounds can damage delicate structures in the inner ear. Hearing damage can be permanent, so prevention is important.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_sound_global_045','Physics','Sound and Hearing','Topic 8: Sound and Hearing','Primary',10,'Analyze how the ''Eardrum'' functions as a biomechanical interface.','["The eardrum blocks all sound from entering the brain.","The eardrum (tympanic membrane) is the critical interface where acoustic energy (air pressure waves) is converted into mechanical kinetic energy. The pressure waves physically push and pull the membrane, initiating the chain reaction of bone movement in the middle ear.","The eardrum turns sound directly into light energy.","The eardrum creates the sound waves that leave the ear."]',1,'It catches the invisible air waves and turns them into a physical, mechanical shaking motion!','Eardrum: vibrates when sound waves reach it. Middle-ear bones: transmit and amplify the vibrations.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_001','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What does ''temperature'' tell us?','["How heavy an object is","How hot or cold something is","How fast something is moving","How bright a light is"]',1,'You use a thermometer to check it.','Temperature tells us how hot or cold something is.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_002','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What is ''heat'' in physics?','["A type of light wave","Energy transferred from a warmer object to a cooler one","The amount of space an object takes up","The color of an object"]',1,'It is energy on the move.','Heat is energy transferred from a warmer object or region to a cooler one because of a temperature difference.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_003','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'Which instrument is used to measure temperature?','["A barometer","A stopwatch","A thermometer","A ruler"]',2,'It usually has numbers showing degrees.','We often use a thermometer to measure temperature.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_004','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What unit is commonly used to measure temperature in daily life?','["Degrees Celsius (°C)","Litres (L)","Kilograms (kg)","Seconds (s)"]',0,'Water freezes at 0°C.','Degrees Celsius (°C): widely used for weather, cooking and everyday measurements.','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_005','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'At what temperature (in Celsius) does water freeze at normal atmospheric pressure?','["100°C","50°C","0°C","10°C"]',2,'Zero is the freezing point of water.','On the Celsius scale, water freezes at about 0°C...','2026-11-01 07:57:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_006','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What is a ''thermal conductor''?','["A material that stops heat from moving","A material that transfers thermal energy relatively easily","A material that creates its own heat","A material that turns heat into light"]',1,'Metals are good conductors.','Thermal conductors: Materials that transfer thermal energy relatively easily.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_007','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'Which of these materials is a good ''thermal conductor''?','["Wood","Foam","Copper","Plastic"]',2,'Metals let heat pass through them easily.','Examples: copper, aluminium and iron.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_008','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What is a ''thermal insulator''?','["A material that transfers heat very quickly","A material that slows the transfer of thermal energy","A material that creates electricity","A material that glows in the dark"]',1,'A winter coat is a good insulator.','Thermal insulators: Materials that slow the transfer of thermal energy.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_009','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'Which of these materials is a good ''thermal insulator''?','["Iron","Aluminium","Copper","Wool"]',3,'Wool slows down the heat escaping from your body.','Examples: wood, wool, foam and many plastics.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_010','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What does ''conduction'' mean?','["Heat travelling through empty space","Heat transfer through direct contact, especially in solids","Heat rising in a liquid","Heat turning into sound"]',1,'It happens when two things are touching.','Conduction: Energy transfers through neighbouring particles and interactions within a material... Example: A metal spoon warms up in hot water.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_011','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What does ''convection'' mean?','["Heat bouncing off a mirror","Energy transferred by the movement of a fluid, such as a liquid or gas","Heat traveling through empty space","Heat causing a solid to freeze"]',1,'Warm air rising is convection.','Convection: Energy is transferred by the movement of a fluid, such as a liquid or gas.','2026-11-01 07:57:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_012','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What is ''radiation''?','["Energy transferred through direct contact","Energy travelling by electromagnetic waves that does not need a material medium","Heat moving through liquid water","Heat turning into solid ice"]',1,'The Sun warms the Earth through radiation.','Radiation: Energy travels by electromagnetic waves. It does not need a material medium.','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_013','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What happens to many materials when they are heated?','["They expand (get slightly larger)","They disappear completely","They freeze solid","They contract (get smaller)"]',0,'The heat makes the particles move faster and push apart.','Many materials expand when heated...','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_014','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What is a basic safety rule around hot objects?','["Always touch steam to see how hot it is","Use suitable oven mitts or heat-resistant tools","Play near open flames","Put glass thermometers in the oven"]',1,'Protect your hands from burns!','Follow these rules: ... Use suitable oven mitts or heat-resistant tools.','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_015','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',1,'What should you do if you get a minor thermal burn?','["Put butter on it","Cool the area under cool running water for 20 minutes","Put toothpaste on it","Wrap it in a thick blanket"]',1,'Cool water helps stop the burn from getting worse.','For a minor thermal burn, cool the area under cool running water for 20 minutes; do not apply ice, butter or toothpaste.','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_016','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why is it scientifically incorrect to say ''close the door, you are letting the cold in''?','["Because cold air actually moves faster than hot air.","Heat is the energy that moves; it flows naturally from a warmer area to a cooler one. You are actually letting the *heat out*.","Because doors do not stop air from moving.","Because cold is a type of solid matter."]',1,'The warm air inside your house is escaping to the cold outside!','Heat is energy transferred from a warmer object or region to a cooler one because of a temperature difference.','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_017','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'If you put a cool metal spoon into a cup of hot water, what happens to the energy?','["The spoon gives its cold energy to the water.","Energy transfers from the warmer water into the cooler spoon until they approach the same temperature.","The water freezes instantly.","The spoon creates its own heat."]',1,'The heat moves from the hot liquid into the cold metal.','Energy transfers from the warmer water to the cooler spoon... Energy continues to transfer until they approach the same temperature...','2026-11-01 07:57:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_018','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why does a metal spoon feel colder than a wooden spoon, even if they are in the exact same room at the same temperature?','["Because metal actually absorbs cold from the air.","Because metal is a good thermal conductor; it transfers the heat *away* from your warm hand much faster than wood (an insulator) does.","Because metal has a naturally lower temperature than wood.","Because wood creates its own heat."]',1,'Your hand feels cold because it is losing heat quickly to the metal!','Metal often feels colder than wood at the same room temperature because metal transfers energy away from your hand more quickly. This does not necessarily mean the metal has a lower temperature.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_019','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'How does a winter coat (made of wool or down) keep you warm?','["It has batteries inside that create heat.","The material acts as a thermal insulator, trapping your body heat and slowing down the transfer of that energy to the cold air outside.","It acts as a thermal conductor, pulling heat from the sun.","It stops gravity from affecting your body."]',1,'The coat doesn''t make you warm; it just stops your own body heat from escaping!','Thermal insulators: Materials that slow the transfer of thermal energy... Insulating materials are also used in... Warm clothing.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_020','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why are cooking pots usually made of metal, but their handles are made of plastic or wood?','["Because metal is cheap and wood is expensive.","Metal is a good conductor to transfer heat from the stove to the food quickly, while the handle is an insulator to prevent the heat from burning your hand.","Because metal handles would break the pot.","Because wood is a better conductor than metal."]',1,'You want the food to get hot, but not your hand!','Metals generally transfer heat efficiently from a stove to the food. Handles may be made from materials that conduct heat less easily, helping reduce heat transfer to the user''s hand.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_021','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'How does ''convection'' work when you heat a pot of water on the stove?','["The heat travels directly through the metal into the water without moving the water.","The water at the bottom gets warm, becomes less dense, and rises to the top, while the cooler water sinks to the bottom, creating a circulating current.","The heat turns into radiation and shoots out of the pot.","The water freezes at the bottom and boils at the top."]',1,'Hot water floats up, cold water sinks down!','Convection: Energy is transferred by the movement of a fluid... Example: In a heated pot, warmer water rises while cooler water tends to sink, creating circulation.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_022','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why do engineers leave small gaps between the metal sections of railway tracks or bridges?','["To let water drain through the cracks.","Because metal expands (gets larger) when heated by the summer sun; without gaps, the expanding metal would push against itself and buckle or break.","To save money on using less metal.","To make a clicking sound when trains drive over them."]',1,'If the metal gets hot and grows, it needs room to stretch!','Many materials expand when heated... Examples include: Railway tracks and bridges designed with room for thermal expansion.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_023','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why might a tight metal jar lid become easier to open if you run it under warm water?','["The warm water washes away the glue.","The heat causes the metal lid to expand (get slightly larger) faster than the glass jar, loosening its grip.","The warm water makes the metal contract (shrink).","The warm water makes the glass expand instantly."]',1,'The heat makes the metal stretch out a tiny bit, breaking the tight seal!','Examples include: ... A metal jar lid becoming easier to loosen after being warmed gently.','2026-11-01 07:57:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_024','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'How does thermal energy from the Sun reach the Earth across the empty vacuum of space?','["Through conduction, because space is full of metal.","Through radiation, which travels as electromagnetic waves and does not require a material medium (like air) to travel through.","Through convection currents in outer space.","Through sound waves."]',1,'Radiation can travel through absolute nothingness!','Radiation: Energy travels by electromagnetic waves. It does not need a material medium. Example: Energy from the Sun warms Earth''s surface.','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_025','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'What is the difference between an ''infrared thermometer'' and a ''laboratory thermometer''?','["An infrared thermometer only works on ice.","A laboratory thermometer usually touches a liquid to measure it, while an infrared thermometer estimates temperature by detecting radiation from a distance without touching the object.","A laboratory thermometer measures time, not temperature.","An infrared thermometer measures how heavy an object is."]',1,'You can point an infrared thermometer at a hot pan from across the kitchen!','Laboratory thermometer: measures temperatures during scientific experiments. Infrared thermometer: estimates temperature by detecting infrared radiation, often without touching the object.','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_026','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why should you never use your sense of touch (like your hand) to measure temperature precisely?','["Because your hands are always freezing cold.","Your sense of touch is subjective and affected by thermal conductivity (e.g., metal feels colder than wood at the same temperature), making it unreliable for precise scientific measurement.","Because hands cannot feel heat at all.","Because touching things destroys thermal energy."]',1,'Your hand tells you how fast heat is leaving your skin, not the exact temperature of the object!','Our sense of touch is not a reliable way to measure temperature precisely. Use a suitable thermometer instead.','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_027','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'What does it mean that ''no ordinary material is a perfect insulator''?','["It means all insulators are actually conductors.","It means that while insulators significantly slow down the transfer of thermal energy, they cannot stop it 100% completely; eventually, the heat will pass through.","It means you should never use insulation in a house.","It means insulators are actually made of metal."]',1,'Even in the best winter coat, you will eventually get cold if you stay outside long enough!','No ordinary material is a perfect insulator. Insulators slow heat transfer rather than stopping it completely.','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_028','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'What is a ''Kelvin'' (K)?','["A type of thermometer made of wood.","The standard scientific temperature unit used in the International System of Units (SI).","A unit used to measure the weight of an object.","A type of thermal conductor."]',1,'Scientists use Kelvin because it starts at absolute zero!','Kelvin (K): the standard scientific temperature unit.','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_029','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why is ''cooling'' described as lowering the temperature rather than ''adding cold''?','["Because cold is actually a type of gas.","In physics, there is no such thing as ''cold energy''; cooling is simply the process of removing or transferring thermal energy (heat) away from an object.","Because adding cold makes things explode.","Because cooling is impossible in nature."]',1,'You can''t add ''cold''; you can only take away heat!','Cooling does not always mean removing all thermal energy. It means lowering the temperature of an object or system... Heat is energy transferred...','2026-11-01 07:57:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_030','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',5,'Why should you never touch steam to test how hot it is?','["Because steam is actually freezing cold.","Steam contains an immense amount of thermal energy and can cause severe, instant burns to your skin, even faster than boiling water.","Because steam turns your hand invisible.","Because touching steam turns it into solid ice."]',1,'Steam is water that has been heated past boiling; it is incredibly dangerous!','Follow these rules: ... Never touch steam to test its temperature... Hot objects, steam and heated liquids can cause burns.','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_031','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Critique the phrase: ''This oven contains a lot of heat.''','["The phrase is scientifically accurate because ovens generate heat.","The phrase is technically incorrect in thermodynamics. An object contains ''internal energy'' (thermal energy). ''Heat'' strictly defines the dynamic *transfer* of energy across a boundary due to a temperature gradient, not a static property contained within an object.","The phrase is wrong because ovens contain cold, not heat.","The phrase is wrong because heat is a solid object."]',1,'You don''t ''have'' heat; heat is the action of energy moving from you to something colder!','Remember: An object does not “contain heat” in the same sense that it has a temperature. It contains internal energy; heat refers to energy being transferred because of a temperature difference.','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_032','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Analyze the kinetic relationship between ''Temperature'' and ''Thermal Energy'' in a macroscopic object.','["Temperature and thermal energy are exactly the same thing.","Temperature is a statistical measure of the *average* kinetic energy of the particles. Thermal energy is the *total* kinetic and potential energy of all particles combined. Thus, a massive glacier has more total thermal energy than a cup of boiling water, even though the water has a higher temperature.","Temperature measures mass, while thermal energy measures speed.","Thermal energy stops existing when temperature increases."]',1,'A tiny drop of boiling water has a high temperature, but a giant ocean has way more total thermal energy!','Temperature... At a microscopic level, it is related to the average kinetic energy of the particles in a substance. Thermal energy: Energy associated with the particles and interactions within matter.','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_033','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Synthesize how the concept of ''Specific Heat Capacity'' (though not named, implied by material differences) affects the subjective ''feel'' of materials.','["Specific heat capacity means all materials feel exactly the same.","Materials have different rates of thermal conductivity and heat capacity. Metal conducts energy rapidly away from human skin, creating a sharp temperature gradient and triggering cold receptors. Wood conducts energy slowly, maintaining a smaller gradient, thus feeling warmer despite being at thermal equilibrium with the metal.","Specific heat capacity means wood is always colder than metal.","It proves that human hands actually generate electricity."]',1,'Your brain doesn''t feel temperature; it feels how fast heat is leaving your skin!','Metal often feels colder than wood at the same room temperature because metal transfers energy away from your hand more quickly. This does not necessarily mean the metal has a lower temperature.','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_034','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Evaluate the physical mechanics of ''Convection'' in the context of atmospheric weather patterns.','["Convection only occurs inside cooking pots, not in the atmosphere.","Convection is the primary engine of global weather. Solar radiation warms the Earth''s surface (conduction), which warms the air above it. This air expands, loses density, and rises (convection), creating low-pressure zones that draw in cooler air (wind), forming complex meteorological circulatory systems.","Convection prevents any wind from blowing.","Convection causes all clouds to freeze solid."]',1,'Wind is just the Earth''s way of stirring the giant pot of air to balance the heat!','Convection: Energy is transferred by the movement of a fluid, such as a liquid or gas. (Synthesis: The atmosphere is a massive fluid).','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_035','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Analyze the statement: ''Water behaves unusually near its freezing point.'' What is this anomaly and its ecological significance?','["Water contracts infinitely as it freezes, crushing all marine life.","Unlike most materials that contract continuously as they cool, water reaches its maximum density at 4°C, then *expands* as it freezes into a solid crystal lattice (ice). This anomaly causes ice to float, insulating the liquid water below and allowing aquatic ecosystems to survive winter.","Water boils when it reaches its freezing point.","Water turns into a metal when it freezes."]',1,'If ice sank, the oceans would freeze solid from the bottom up, killing all fish!','Some materials expand very little, and water behaves unusually near its freezing point. (Synthesis: This refers to water expanding instead of contracting when it freezes).','2026-11-01 07:57:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_036','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Synthesize how ''Radiation'', ''Conduction'', and ''Convection'' all operate simultaneously when boiling a pot of water on a campfire.','["Only radiation is happening because it is a fire.","The fire transfers thermal energy to the metal pot via electromagnetic waves (Radiation). The metal pot transfers the energy through its solid structure to the water touching it (Conduction). The heated water at the bottom expands and rises, distributing the energy throughout the liquid (Convection).","Conduction, convection, and radiation cannot happen at the same time.","Only convection is happening because water is a liquid."]',1,'Physics doesn''t happen one step at a time; it happens all at once!','In real situations, more than one method may occur at the same time. A cooking pot, for example, may receive energy from a flame by radiation and convection, then transfer energy to food through conduction.','2026-11-01 07:57:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_037','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Critique the use of ''Degrees Fahrenheit'' versus ''Kelvin'' in the context of scientific standardization.','["Fahrenheit is the absolute scientific standard everywhere on Earth.","Fahrenheit is an arbitrary, localized scale based on historical human references (e.g., body temperature). Kelvin is an absolute thermodynamic scale starting at absolute zero (no kinetic energy). Kelvin is scientifically essential because its proportional ratios directly correlate to kinetic energy equations (e.g., the Ideal Gas Law), whereas Fahrenheit does not.","Kelvin is only used for measuring the temperature of the ocean.","Fahrenheit is mathematically perfect and based on absolute zero."]',1,'You can''t do advanced physics math with a temperature scale that goes negative; Kelvin solves this by starting at the absolute bottom!','Kelvin (K): the standard scientific temperature unit. Degrees Fahrenheit (°F): used in some countries for everyday temperatures.','2026-11-01 07:57:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_038','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Evaluate the physical danger of ''Thermal Expansion'' in infrastructural engineering if not properly accounted for.','["Thermal expansion makes bridges stronger and safer.","If engineers do not integrate expansion joints, the kinetic energy added by summer heat causes the molecular structure of steel/concrete to expand. This uncontrollable dimensional increase generates immense internal stress, leading to catastrophic buckling, cracking, and structural failure of bridges and railways.","Thermal expansion only affects plastic, not metal or concrete.","Thermal expansion causes bridges to shrink and fall apart."]',1,'If the metal has nowhere to stretch, it will bend and snap the bridge in half!','Railway tracks and bridges designed with room for thermal expansion... Many materials expand when heated...','2026-11-01 07:57:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_039','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Analyze the physiological reason why applying ''ice'' to a severe thermal burn is contraindicated (bad advice) in first aid.','["Ice instantly cures the burn and heals the skin.","A thermal burn causes extreme cellular damage. Applying ice causes rapid, extreme vasoconstriction (shrinking blood vessels), which completely cuts off blood flow and oxygen to the damaged tissue, exacerbating cellular death and potentially causing frostbite on top of the burn.","Ice makes the burn hotter through a chemical reaction.","Ice is too wet and will wash away the skin."]',1,'You want to gently remove the heat with cool water; shocking the skin with freezing ice causes more damage!','For a minor thermal burn, cool the area under cool running water for 20 minutes; do not apply ice, butter or toothpaste.','2026-11-01 07:57:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_040','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Synthesize how the concept of ''Thermal Equilibrium'' governs the direction of heat flow in the universe.','["Thermal equilibrium means heat always flows from cold to hot.","The Second Law of Thermodynamics dictates that thermal energy spontaneously and irreversibly flows from regions of higher temperature to regions of lower temperature until both reach thermal equilibrium (the exact same temperature), maximizing the entropy of the system.","Thermal equilibrium prevents any heat from moving at all.","Thermal equilibrium means all objects in the universe are at 100°C."]',1,'Nature always tries to balance things out; the hot coffee will always cool down to match the room!','Heat is energy transferred from a warmer object or region to a cooler one because of a temperature difference... Energy continues to transfer until they approach the same temperature...','2026-11-01 07:57:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_041','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Critique the colloquial term ''sweating'' when referring to a cold glass of water on a hot day.','["The glass is actually sweating water from inside itself to cool down.","The term is scientifically inaccurate. The water droplets do not originate from inside the glass (like biological sweat); they are formed via condensation, as the ambient atmospheric water vapor loses thermal energy upon contacting the cold surface of the glass and undergoes a phase change into liquid.","The glass is melting, and the sweat is liquid glass.","The glass is absorbing water from the air and storing it inside."]',1,'The water on the outside of the glass came from the invisible air, not from inside the cup!','Condensation occurs when a gas changes into a liquid. Example: Water droplets form on the outside of a cold glass when water vapour in the surrounding air cools. (from previous knowledge linked to this topic).','2026-11-01 07:57:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_042','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Analyze the role of a ''Vacuum'' in the design of a ''Thermal flask'' (Thermos).','["A vacuum creates infinite heat.","A vacuum is a region devoid of matter. Because Conduction and Convection require a physical medium (particles/fluid) to transfer kinetic energy, a vacuum jacket between the walls of a flask almost entirely halts these two methods of heat transfer, vastly improving insulation.","A vacuum speeds up convection currents.","A vacuum only stops radiation, not conduction."]',1,'If there is no air between the walls of the bottle, the heat has no ''bridge'' to cross!','Thermal insulators: Materials that slow the transfer of thermal energy... Insulating materials are also used in: ... Thermal flasks. Conduction: Energy transfers through neighbouring particles... (Synthesis: No particles means no conduction).','2026-11-01 07:57:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_043','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Synthesize how ''Infrared Radiation'' allows an infrared thermometer to measure temperature without physical contact.','["It sends out a physical probe to touch the object invisibly.","All objects with a temperature above absolute zero emit electromagnetic radiation in the infrared spectrum. The intensity and wavelength of this radiation correlate directly with the object''s kinetic temperature. The thermometer''s sensor detects this radiation across empty space, requiring no conductive contact.","It freezes the object and measures how long it takes to melt.","It measures the sound the object makes."]',1,'Everything that is warm glows with invisible light; the thermometer ''sees'' that invisible glow!','Infrared thermometer: estimates temperature by detecting infrared radiation, often without touching the object.','2026-11-01 07:57:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_044','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Evaluate the physical limitations of ''Convection'' in a zero-gravity environment (like the International Space Station).','["Convection works perfectly in zero gravity because air is lighter.","Natural convection is driven entirely by density differentials interacting with a gravitational field (less dense, warm fluid is forced upward by the heavier, cold fluid sinking). In microgravity, there is no ''up'' or ''down'' for density to exploit, meaning natural convection entirely ceases, requiring mechanical fans for ventilation.","Convection is actually much stronger in zero gravity.","Convection only relies on radiation, which ignores gravity."]',1,'Without gravity, hot air doesn''t rise! It just sits there, which is why astronauts need fans to circulate their air.','Convection: Energy is transferred by the movement of a fluid... warmer water rises while cooler water tends to sink... (Synthesis: ''Rising'' and ''sinking'' require gravity).','2026-11-01 07:57:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_heat_global_045','Physics','Heat and Temperature','Topic 9: Heat and Temperature','Primary',10,'Critique the assertion that a thick wool sweater ''generates heat'' for the wearer.','["The sweater generates heat through a chemical reaction with air.","The sweater generates zero thermal energy. It functions purely as a highly efficient thermal insulator. The complex matrix of wool fibers traps pockets of stagnant air, which is a poor thermal conductor, drastically reducing the rate of convective and conductive heat loss from the wearer''s own biological metabolism.","The sweater uses friction to generate immense heat.","The sweater absorbs radiation from the moon."]',1,'Your body is the heater; the sweater is just the thick wall keeping the heat inside!','Insulators slow heat transfer rather than stopping it completely... Warm clothing. (Synthesis: The clothing is an insulator, not a heat source).','2026-11-01 07:57:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_001','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is ''electricity''?','["A type of water","Phenomena associated with electric charge","A type of rock","A loud noise"]',1,'It powers our lights and TVs.','Electricity involves electric charges and their effects.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_002','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What does an ''electric cell'' do?','["It measures how hot something is","It converts chemical energy into electrical energy","It stores water","It creates light without energy"]',1,'It is the small power source inside a watch or remote.','An electric cell converts chemical energy into electrical energy.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_003','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is a ''battery''?','["A broken wire","One or more electric cells connected together","A machine that cleans water","A type of lightbulb"]',1,'You put these in a toy to make it work.','A battery consists of one or more electric cells connected together.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_004','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is an ''electric circuit''?','["A type of road for cars","A complete path through which electric current can flow","A spinning wheel","A box that holds batteries"]',1,'It is the loop that electricity travels around.','An electric circuit is a complete path through which electric current can flow.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_005','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What happens in a ''closed circuit''?','["The path is broken, and no electricity flows","The path is complete, so current can flow","The battery explodes","The lightbulb turns into a battery"]',1,'The circle is closed, so the electricity can run around it.','Closed circuit: The path is complete, so current can flow... Result: The bulb can light up.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_006','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What happens in an ''open circuit''?','["The path has a break, so current cannot flow","The lightbulb shines brighter","The electricity flows twice as fast","The switch turns into a conductor"]',0,'The circle is broken, so the electricity stops.','Open circuit: The path has a break, so current cannot flow around the circuit. Result: The bulb stays off.','2026-11-01 07:57:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_007','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is an ''electrical conductor''?','["A material that stops electricity","A material that allows electric charge to move relatively easily","A person who drives a train","A type of battery"]',1,'Metal wires are conductors.','Electrical conductors: Materials that allow electric charge to move relatively easily.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_008','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'Which of these is a good ''electrical conductor''?','["Rubber","Wood","Copper","Plastic"]',2,'Electricity flows easily through metal.','Examples: copper, aluminium and many other metals.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_009','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is an ''electrical insulator''?','["A material that strongly resists the movement of electric charge","A machine that creates electricity","A metal wire","A type of lightbulb"]',0,'It stops electricity from flowing.','Electrical insulators: Materials that strongly resist the movement of electric charge.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_010','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'Which of these is a good ''electrical insulator''?','["Copper","Aluminium","Rubber","Iron"]',2,'This is why wires are wrapped in rubber!','Examples: rubber, glass and many plastics under ordinary conditions.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_011','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is the job of a ''switch'' in a circuit?','["It creates electricity.","It opens or closes the circuit.","It turns the electricity into sound.","It makes the battery bigger."]',1,'It works like a bridge that you can lift up or put down.','Switch: opens or closes the circuit.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_012','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is a ''series circuit''?','["A circuit with separate branches","A circuit with components connected along one main path","A circuit that has no battery","A circuit that only uses rubber wires"]',1,'The electricity has only one road to travel on.','Series circuit: Components are connected along one main path.','2026-11-01 07:57:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_013','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is a ''parallel circuit''?','["A circuit with components connected in separate branches","A circuit that only has one lightbulb","A circuit that does not work","A circuit made of only batteries"]',0,'The electricity has multiple different roads it can take.','Parallel circuit: Components are connected in separate branches.','2026-11-01 07:57:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_014','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'What is ''static electricity''?','["Electricity that flows continuously in a circle","A build-up of electric charge on the surface of an object","Electricity that only works in the dark","A type of battery"]',1,'It happens when you rub a balloon on your hair!','Static electricity: A build-up of electric charge on an object.','2026-11-01 07:57:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_015','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',1,'Which of these is a very important electrical safety rule?','["Touch exposed wires to see if they are hot","Keep electrical appliances away from water and wet hands","Put metal objects into electrical sockets","Pull a plug out by its cord"]',1,'Water and electricity are a dangerous combination!','Follow these rules: ... Keep electrical appliances away from water and wet hands.','2026-11-01 07:57:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_016','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why is the metal wire in a circuit always coated in plastic or rubber?','["Because plastic helps the electricity move faster.","The rubber acts as an insulator, protecting people from touching the live metal conductor and preventing the wires from touching each other and short-circuiting.","Because bare metal is illegal.","Because rubber actually creates the electricity."]',1,'The metal moves the power, and the rubber keeps the power safely inside!','The metal inside a wire carries current. The insulating outer covering helps prevent people from touching the conducting metal and reduces the risk of accidental contact between conductors.','2026-11-01 07:57:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_017','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'If you open the switch in a simple series circuit with a battery and a bulb, what exactly happens?','["The battery stops working permanently.","The physical path for the electric current is broken, stopping the flow of electricity, and the bulb turns off.","The bulb gets twice as bright.","The switch creates a new path for the electricity."]',1,'Opening the switch is like lifting a bridge; the electricity can''t cross!','Open circuit: The path has a break, so current cannot flow around the circuit. Result: The bulb stays off... A switch does not create electricity. It controls whether the circuit provides a complete conducting path.','2026-11-01 07:57:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_018','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'If a lightbulb in a circuit stops glowing, is it always because the switch was opened?','["Yes, the switch is the only thing that can turn a bulb off.","No, it could also mean the battery is exhausted, the bulb is broken, or a wire is disconnected.","Yes, switches automatically open if the bulb gets tired.","No, it just means the electricity is invisible."]',1,'If the battery dies, the path is still closed, but there is no power!','A bulb may also fail to light if the battery is exhausted, the bulb is faulty or the connections are unsuitable. So a dark bulb does not always mean the switch is open.','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_019','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why do the lights in your house NOT all go out if one single lightbulb burns out?','["Because house lights do not use electricity.","Because houses are wired using parallel circuits; if one branch (bulb) breaks, the electricity can still flow through the other separate branches to keep the other lights on.","Because houses use series circuits.","Because burned-out bulbs create their own electricity."]',1,'Parallel means there is a detour road for the electricity to take!','Parallel circuit: Components are connected in separate branches. If one bulb breaks, another branch may still provide a complete path... Household lighting circuits are generally arranged in parallel branches...','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_020','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'What happens if one bulb breaks in a ''series circuit'' containing three bulbs?','["Only the broken bulb goes out, the other two stay on.","The entire circuit path is broken, so all three bulbs will go out immediately.","The other two bulbs get brighter.","The broken bulb fixes itself."]',1,'If the only bridge on the road breaks, nobody can cross!','Series circuit: Components are connected along one main path... If one bulb breaks and opens the path, all the bulbs in that path go out.','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_021','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'How does a battery eventually ''die''?','["The electricity leaks out of the bottom.","The stored chemical energy inside the battery is fully transformed into electrical energy; when the chemical reactions stop, it can no longer drive a current.","It absorbs too much light from the room.","The wires get too tired to carry the current."]',1,'The battery is a chemical factory; when it runs out of chemicals, it stops working!','A battery does not provide unlimited energy. When its stored chemical energy can no longer sustain the required current, it must be replaced or recharged...','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_022','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why is ''static electricity'' different from the electricity powering a television?','["Static electricity only happens in the summer.","Static electricity is a stationary build-up of charge on a surface (like a balloon), while the TV uses a continuous flow of electric current through a closed circuit.","Static electricity is much more powerful than a TV.","Static electricity comes from water."]',1,'Static is stuck in one place; current is flowing in a circle!','Sometimes electric charge builds up on the surface of an object instead of flowing continuously through a circuit. This is called static electricity.','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_023','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why is it incredibly dangerous to touch a damaged electrical wire with wet hands?','["Because the water will put out the electricity.","Water containing dissolved substances is a conductor; the wet hands create a path for the electrical current to flow out of the wire and directly into your body, causing a severe shock.","Because wet hands make the wire slippery.","Because the wire will rust instantly."]',1,'Water turns your skin into a bridge for the electricity to cross!','Water containing dissolved substances can conduct electricity. Wet hands and damp surroundings can increase electrical danger... unsafe contact can cause electric shock...','2026-11-01 07:57:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_024','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'What energy transformation happens inside an electric motor?','["It turns movement into light.","It converts electrical energy into movement (kinetic energy).","It converts light into sound.","It converts chemical energy into a battery."]',1,'You plug the motor in (electricity), and it spins (movement)!','Motor: converts electrical energy into movement.','2026-11-01 07:57:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_025','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'What energy transformation happens inside a standard lightbulb?','["It converts light energy into electricity.","It converts electrical energy into light energy and thermal (heat) energy.","It converts sound into light.","It converts chemical energy into movement."]',1,'It makes light, but it also gets hot!','Bulb: converts electrical energy into light and thermal energy.','2026-11-01 07:57:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_026','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'If you rub a balloon on your hair and then stick it to a wall, what scientific phenomenon are you demonstrating?','["A series circuit","Static electricity","An open circuit","A chemical battery"]',1,'The rubbing builds up an electrical charge on the rubber!','For example, when you rub a balloon against dry hair or wool, electric charges can be redistributed... This is called static electricity.','2026-11-01 07:57:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_027','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'How does a ''buzzer'' function in an electric circuit?','["It creates electricity.","It acts as a switch to open the circuit.","It converts electrical energy into sound energy.","It turns sound into light."]',2,'You push the button, the electricity flows, and it makes a loud noise!','Buzzer: converts electrical energy into sound.','2026-11-01 07:57:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_028','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why should you never pull a plug out of the wall by yanking its cord?','["Because it might pull the wall down.","Pulling the cord can damage the internal metal wires or strip the insulating rubber, creating a severe shock or fire hazard.","Because it uses too much electricity.","Because the cord likes being in the wall."]',1,'Yanking the cord can break the protective rubber layer!','Follow these rules: ... Do not pull a plug out by its cord. Never touch damaged wires or exposed conductors.','2026-11-01 07:57:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_029','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'What is a ''terminal'' on a battery?','["The part of the battery that makes light.","One of the two connection points, usually marked positive (+) or negative (-), where wires must be attached to create a flow of current.","The plastic wrapper around the battery.","The switch that turns the battery off."]',1,'The electricity flows out of one terminal and into the other!','A cell has two terminals, commonly marked positive (+) and negative (−). When connected correctly in a suitable circuit, the cell can drive electric current.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_030','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',5,'Why is lightning considered a form of electricity?','["Because it is plugged into the clouds.","It is a massive discharge of built-up static electricity in the atmosphere.","It is actually a giant series circuit.","It is a chemical battery exploding in space."]',1,'Lightning is just a giant version of the spark you get when you touch a doorknob in the winter!','Other examples [of static electricity] include: ... Lightning, which involves large electrical discharges in the atmosphere.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_031','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Critique the common phrase: ''The switch creates the electricity to turn on the light.''','["The phrase is perfectly accurate.","The phrase is fundamentally incorrect. The battery (or generator) is the source converting energy into electrical potential. The switch is merely a mechanical bridge; closing it completes the conducting path, allowing the pre-existing potential to drive the current.","The switch creates electricity, but only when it is open.","The lightbulb actually creates the electricity."]',1,'The electricity is waiting in the battery; the switch just opens the gate!','A switch does not create electricity. It controls whether the circuit provides a complete conducting path.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_032','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Analyze the systemic vulnerability of a ''Series Circuit'' in the context of holiday string lights.','["Series circuits are impossible to break.","If holiday lights are wired in a pure series circuit, the electrical current must pass through every single filament sequentially. If one bulb burns out (the filament breaks), it physically opens the circuit, halting current flow and disabling every light on the string.","Series circuits ensure that if one light breaks, the rest get brighter.","Series circuits only work if they are plugged into a parallel battery."]',1,'They are all on the same road; if the road is blocked, nobody gets through!','Series circuit: Components are connected along one main path... If one bulb breaks and opens the path, all the bulbs in that path go out.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_033','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Synthesize how the concept of ''Resistance'' explains the function of both Conductors and Insulators.','["Resistance only exists in water.","All materials possess electrical resistance (opposition to current flow). Conductors (metals) have extremely low resistance, allowing free electron flow. Insulators (rubber) have extraordinarily high resistance, effectively halting electron flow under normal voltage conditions.","Conductors have high resistance, insulators have low resistance.","Resistance proves that electricity does not exist."]',1,'It''s all about how hard the material fights back against the electricity!','Electrical conductors: Materials that allow electric charge to move relatively easily. Electrical insulators: Materials that strongly resist the movement of electric charge.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_034','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Evaluate the physical danger of ''overloading sockets or extension leads''.','["It causes the electricity to move too slowly.","Drawing too much current through a single socket or extension lead exceeds the physical capacity of the internal wires. The excessive current generates massive thermal energy (heat) due to resistance, which can melt the insulating plastic and ignite a catastrophic electrical fire.","It causes the house to lose all its gravity.","Overloading sockets actually makes them safer and colder."]',1,'Too much electricity forced through a small wire makes it dangerously hot!','Follow these rules: ... Never overload sockets or extension leads... unsafe contact can cause electric shock, burns and fires.','2026-11-01 07:57:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_035','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Analyze the statement: ''A dark bulb does not always mean the switch is open.'' What troubleshooting logic does this require?','["It means the switch must be pressed twice.","It requires systemic deductive reasoning. A dark bulb signifies an incomplete or unpowered circuit, which has multiple potential points of failure: a depleted chemical cell (battery), a severed conducting path (broken wire), a blown filament (faulty bulb), or the open switch.","It means the lightbulb is actually shining invisible light.","It means electricity is a myth."]',1,'If your car doesn''t start, it might not be the key; it could be out of gas or have a broken engine!','A bulb may also fail to light if the battery is exhausted, the bulb is faulty or the connections are unsuitable. So a dark bulb does not always mean the switch is open.','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_036','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Synthesize the energy pathway: How does a battery power a bulb, starting from chemical potential?','["The battery shoots light directly at the bulb.","The battery undergoes an internal chemical reaction that generates electrical potential energy. This potential drives an electric current (moving charges) through the closed conducting wire circuit to the bulb''s filament, where resistance transforms the electrical energy into radiant (light) and thermal (heat) energy.","The battery spins in a circle to create gravity, which turns on the bulb.","The chemical energy turns into a solid that travels down the wire."]',1,'Chemicals make electricity, electricity travels the wire, and the bulb turns it into light and heat!','An electric cell converts chemical energy into electrical energy... When the circuit is complete, current flows. The bulb transfers electrical energy into light and thermal energy.','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_037','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Critique the action of directly touching a person who is actively receiving a severe electric shock.','["You should grab them immediately to pull them away.","This is a fatal error. Because the human body (composed mostly of water and dissolved salts) is an electrical conductor, touching the victim directly will incorporate your body into the live circuit, electrocuting you as well. The power must be isolated or a non-conductive object must be used.","Touching them will safely ground the electricity.","You should touch them only if you are wearing metal gloves."]',1,'If they are touching the electricity, and you touch them, you are now touching the electricity too!','If someone may be receiving an electric shock, do not touch them directly while they may still be in contact with the electricity. Get emergency help and have the power isolated...','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_038','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Evaluate why pure water is a poor conductor, but ''water containing dissolved substances'' is highly dangerous around electricity.','["Dissolved substances turn the water into solid metal.","Pure \\\\(H_2O\\\\) lacks free ions, making it an insulator. However, everyday water (tap water, sweat, puddles) is saturated with dissolved salts and minerals (electrolytes) that disassociate into mobile ions, providing a highly efficient conducting path for deadly electrical currents.","Dissolved substances make the water freeze, stopping the electricity.","Pure water actually conducts electricity perfectly."]',1,'It''s the invisible minerals floating in the water that actually carry the shock to your hand!','Water containing dissolved substances can conduct electricity. Wet hands and damp surroundings can increase electrical danger...','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_039','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Analyze the mechanical transition required to turn ''Static Electricity'' into an ''Electric Current''.','["Static electricity can never become a current.","Static electricity is a localized imbalance of surface charge (potential). To become a current, a continuous, closed conductive pathway must be introduced between the charged areas, allowing the accumulated electrons to flow steadily rather than remaining static or discharging in a single instantaneous spark.","Static electricity must be frozen to become a current.","Currents must be converted into light to become static."]',1,'Static is stuck; current is flowing. You need a wire bridge (circuit) to make the static flow!','Sometimes electric charge builds up on the surface of an object instead of flowing continuously through a circuit. This is called static electricity.','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_040','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Synthesize how the architecture of a ''Parallel Circuit'' ensures redundancy in household wiring.','["Parallel circuits ensure all lights are the exact same color.","Unlike series circuits, parallel architecture splits the main current into multiple independent branches. If a component in one branch fails (e.g., a broken TV), it only opens that specific localized path; the current continues to flow unimpeded through the other intact branches, maintaining power to the rest of the house.","Parallel circuits force every machine in the house to turn off if one breaks.","Parallel circuits do not use wires, only batteries."]',1,'It''s like a highway with multiple detours; if one road is blocked, the cars just take the other roads!','Parallel circuit: Components are connected in separate branches. If one bulb breaks, another branch may still provide a complete path, so the other bulb can remain lit. Household lighting circuits are generally arranged in parallel branches...','2026-11-01 07:57:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_041','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Critique the use of ''Mains Electricity'' (wall sockets) for primary school science experiments.','["Mains electricity is the safest way to learn physics.","Mains electricity operates at extremely high voltages designed to power heavy appliances. Introducing it to uninsulated, experimental school circuits poses a catastrophic, lethal risk of electrocution or fire. Therefore, experiments must strictly utilize low-voltage DC batteries.","Mains electricity is too weak to power small school bulbs.","Mains electricity should only be used if the students wear rubber shoes."]',1,'The power in the wall is deadly; the power in an AA battery is safe for learning!','Important: Electricity can be dangerous. For learning activities, use only approved, low-voltage battery-powered equipment. Never experiment with wall sockets, exposed mains wires or household electrical supplies.','2026-11-01 07:57:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_042','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Synthesize the relationship between a ''Battery'' and an ''Electric Cell''.','["They are entirely different and unrelated devices.","An electric cell is the singular, foundational unit containing the chemical reaction that generates electrical potential. A ''battery'' is technically a compound device consisting of two or more of these electric cells wired together (usually in series) to produce a higher total voltage.","An electric cell is a biological organism, while a battery is metal.","A battery is just an empty box that holds electric cells."]',1,'One unit is a cell; a group of them working together is a battery!','An electric cell converts chemical energy into electrical energy. A battery consists of one or more electric cells connected together.','2026-11-01 07:57:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_043','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Analyze how ''Lightning'' exemplifies the extreme limits of electrical insulators.','["Lightning proves that air is a perfect conductor.","Under normal conditions, atmospheric air is an excellent electrical insulator. However, during a thunderstorm, the static charge buildup in the clouds becomes so massive (millions of volts) that it overcomes the air''s electrical resistance, physically ionizing the gas into a conductive plasma channel to discharge to the ground.","Lightning proves that clouds are made of solid metal.","Lightning is actually a chemical reaction, not electricity."]',1,'Air normally stops electricity, but if the storm is powerful enough, it forces the electricity right through the air!','Electrical insulators: Materials that strongly resist the movement of electric charge. Examples: ... air (implied by typical circuit conditions, overcome by lightning). Lightning, which involves large electrical discharges in the atmosphere.','2026-11-01 07:57:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_044','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Evaluate the physical necessity of having exactly ''two terminals'' on an electric cell.','["Two terminals are only needed to make the battery look symmetrical.","Electrical current requires a potential difference and a closed loop to flow. The two terminals (positive and negative) provide the origin and destination points for the charge; without two distinct terminals, a continuous, circular conducting path (a circuit) cannot be physically established.","A battery only actually needs one terminal to work perfectly.","The two terminals prevent the battery from exploding."]',1,'Electricity needs a door to leave the battery, and a different door to come back in!','A cell has two terminals, commonly marked positive (+) and negative (−). When connected correctly in a suitable circuit, the cell can drive electric current... Imagine a loop: from one battery terminal, through a wire... and back to the other terminal.','2026-11-01 07:57:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_electric_global_045','Physics','Electricity and Circuits','Topic 10: Electricity and Circuits','Primary',10,'Synthesize the concept of a ''Short Circuit'' (an unintended path) using the principles of conductors and resistance.','["A short circuit makes the battery last ten times longer.","Electricity follows the path of least resistance. If damaged insulation allows a highly conductive wire to cross itself, bypassing the intended load (the bulb/resistance), the current spikes massively along this new ''short'' path. This unrestricted flow generates extreme thermal energy, rapidly exhausting the battery and risking a fire.","A short circuit means the wire is physically too short to reach the bulb.","A short circuit proves that insulators actually conduct electricity."]',1,'If the electricity can take a shortcut past the lightbulb, it will go so fast it causes a fire!','The insulating outer covering helps prevent... accidental contact between conductors... (Synthesis: If conductors touch without a load, it creates a dangerous, unrestricted path).','2026-11-01 07:57:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_001','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What is a ''magnet''?','["An object that produces a magnetic field and can attract certain materials","An object that attracts every single material on Earth","A source of bright light","A type of chemical battery"]',0,'It can pull things like iron clips toward itself.','A magnet is an object that produces a magnetic field. This field can exert a force on certain materials and on other magnets.','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_002','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'Which of these materials is typically attracted to an ordinary magnet?','["Wood","Plastic","Iron","Glass"]',2,'Metals like iron and steel stick to magnets.','Magnetic materials include iron, many types of steel, nickel and cobalt.','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_003','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'Which of these materials is ''non-magnetic''?','["Iron","Steel","Copper","Nickel"]',2,'Copper is a metal, but ordinary magnets do not attract it.','Non-magnetic materials in everyday magnet tests include wood, plastic, paper, glass, copper and aluminium.','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_004','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'How many poles does an ordinary bar magnet have?','["One","Two (a North pole and a South pole)","Three","Four"]',1,'Every magnet has a pair of poles.','Every ordinary bar magnet has two poles: North pole (N) and South pole (S).','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_005','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What happens when two ''like'' poles (such as two North poles) face each other?','["They attract each other","They repel (push away) each other","They stick together permanently","They turn into non-magnetic wood"]',1,'Same poles push each other away.','Like poles repel. North and north repel; south and south repel.','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_006','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What happens when two ''unlike'' poles (a North pole and a South pole) face each other?','["They repel each other","They attract (pull toward) each other","They disappear into thin air","Nothing happens"]',1,'Opposite poles pull together.','Unlike poles attract. North and south poles pull toward each other.','2026-11-01 07:57:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_007','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What is a ''magnetic field''?','["A fence built around a magnet","The region around a magnet where magnetic forces can act","A wire inside a battery","A type of electric current"]',1,'It is the invisible zone where the magnetic force works.','A magnetic field is the region around a magnet where magnetic forces can act.','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_008','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What is the main purpose of a ''compass''?','["To measure temperature","To help with navigation by aligning its magnetized needle with a magnetic field","To cut through metal","To lift heavy cars"]',1,'It points roughly toward geographic north.','A compass contains a small magnetised needle that can rotate freely. The needle aligns with the magnetic field around it... help people navigate.','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_009','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What is an ''electromagnet''?','["A magnet made of solid wood","A magnet produced by electric current flowing through a coil of wire","A natural rock found in the ground","A battery made of iron"]',1,'You turn it on and off using electricity.','An electromagnet is a magnet produced by electric current flowing through a coil of wire.','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_010','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'Which of these everyday items commonly uses magnets?','["A paper notebook","A wooden pencil","A loudspeaker","A glass cup"]',2,'Inside the speaker, a magnet helps create sound waves.','Examples include: ... Speakers use magnets and electric currents to help turn electrical signals into sound.','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_011','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What are the two poles of a bar magnet usually labelled as?','["Top and Bottom","North (N) and South (S)","Left and Right","Positive and Negative"]',1,'N and S stand for the two ends.','Every ordinary bar magnet has two poles: North pole (N) and South pole (S).','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_012','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'Can an ordinary magnet attract an aluminium can?','["Yes, all metals are magnetic.","No, aluminium is a non-magnetic material in ordinary magnet tests.","Yes, but only underwater.","Yes, if the can is painted red."]',1,'Not all metals are magnetic; aluminium doesn''t stick.','An aluminium can is generally not attracted to an ordinary magnet.','2026-11-01 07:57:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_013','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What happens if you break a bar magnet in half?','["One half becomes all North and the other becomes all South.","Each piece forms its own brand-new North and South poles.","Both pieces lose their magnetism instantly.","The magnet turns into liquid."]',1,'You can never isolate just a single pole!','If an ordinary bar magnet is broken into smaller pieces, each piece forms its own north and south poles...','2026-11-01 07:57:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_014','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'Why should you keep small, powerful magnets away from young children?','["Because children like the pretty colors","Because swallowing magnets can cause life-threatening internal injuries","Because children will break the magnets","Because magnets make children tired"]',1,'Magnets can pinch tissue inside the body if swallowed.','Keep small, powerful magnets away from young children. Swallowing magnets can cause life-threatening internal injuries...','2026-11-01 07:57:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_015','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',1,'What is the iron core inside a simple electromagnet used for?','["To make the wire heavier","To make the magnetic effect stronger","To stop electricity from flowing","To cool down the battery"]',1,'It boosts the power of the coil.','Wrapping the wire around an iron core can make the magnetic effect stronger.','2026-11-01 07:57:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_016','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why is ''repulsion'' considered the only true test to confirm if an unknown metal bar is actually a permanent magnet?','["Because attraction can happen with unmagnetized iron, but only two like poles will actively repel each other.","Because permanent magnets never attract anything.","Because unmagnetized iron always repels bar magnets.","Because attraction requires electricity, while repulsion requires water."]',0,'An unmagnetized paperclip will stick to *either* end of a magnet, but another magnet will push away if the poles match!','Repulsion is especially useful for identifying magnets because two ordinary magnetic materials may attract a magnet, but repulsion occurs when like poles of two magnets face one another.','2026-11-01 07:57:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_017','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'How does an electromagnet differ from a permanent bar magnet in terms of control?','["An electromagnet is weaker and cannot pick up paperclips.","An electromagnet''s magnetic field can be turned completely on and off by controlling the electric current, whereas a permanent magnet is always on.","An electromagnet does not have North or South poles.","A bar magnet uses electricity, while an electromagnet does not."]',1,'You can flip a switch to make an electromagnet drop a heavy load of scrap metal!','Electromagnets are useful because their magnetic effect can be controlled. When the current is switched off, most of the magnetic effect disappears...','2026-11-01 07:57:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_018','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why do iron filings form curved lines stretching from the North pole to the South pole around a bar magnet?','["Because the filings are being blown by the wind.","The filings align themselves along the invisible magnetic field lines that loop outside the magnet from its North pole to its South pole.","Because iron filings are liquid.","Because the paper is vibrating."]',1,'The filings map out the invisible force field.','If you sprinkle iron filings around a bar magnet... the filings show a pattern concentrated around its ends... Outside a bar magnet, the conventional field-line direction is from north to south.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_019','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'If you bring a compass near a strong, active electromagnet connected to a battery, what happens to the compass needle?','["The needle spins wildly or points toward the electromagnet because its electric current creates a strong interfering magnetic field.","The compass needle turns into ice.","The compass needle points straight down.","Nothing happens because compasses ignore electricity."]',0,'Electricity creates magnetism, which will mess up the compass needle!','Keep a compass away from strong magnets and magnetic objects while taking a reading, because they can disturb the needle... Electromagnet produces a magnetic field.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_020','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why are horseshoe magnets shaped like a ''U'' instead of being straight bars?','["To make them easier to hang on a wall.","By bending the bar into a U-shape, the North and South poles are brought close together, concentrating the magnetic field between them for a stronger pull.","To make the magnet lighter.","To prevent the poles from touching each other."]',1,'Having both poles side-by-side makes the magnetic grip much stronger at the opening.','Horseshoe magnets: U-shaped magnets that bring their poles close together.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_021','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why won''t an ordinary magnet pick up a copper penny or a gold ring?','["Because gold and copper are magnetic materials.","Because gold and copper are non-magnetic materials that are not noticeably attracted by ordinary classroom magnets.","Because copper is heavier than a bar magnet.","Because coins are coated in plastic."]',1,'Only certain metals like iron and steel are magnetic; precious metals like gold are not.','Non-magnetic materials in everyday magnet tests include wood, plastic, paper, glass, copper and aluminium.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_022','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'How do electric motors use magnets to create movement?','["Motors use magnets to freeze water into ice.","Magnetic forces (attraction and repulsion between permanent magnets and electromagnets inside the motor) help turn electrical energy into rotational movement.","Motors use magnets to make a loud sound like a speaker.","Motors use magnets to create gravity."]',1,'Pushing and pulling magnets make the inside part of the motor spin around!','Electric motors: Magnetic forces help motors turn electrical energy into movement in fans, toys and many machines.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_023','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why should you keep strong magnets away from credit cards, hotel room keys, and computer hard drives?','["Because the magnets will scratch the plastic screen.","Because the strong magnetic field can erase or scramble the magnetically stored data encoded on those cards and devices.","Because the magnets will drain the battery of the computer.","Because the cards are made of iron."]',1,'Many cards store data on a tiny magnetic stripe; a strong magnet wipes that data clean!','Keep strong magnets away from magnetic cards, electronic devices and equipment that may be affected.','2026-11-01 07:57:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_024','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'What happens to the strength of an electromagnet if you increase the number of wire coils wrapped around the iron core?','["The strength decreases to zero.","The magnetic effect generally becomes stronger.","The magnet turns into a bar magnet.","The battery explodes immediately."]',1,'More loops of wire mean a stronger magnetic field!','Wrapping the wire around an iron core can make the magnetic effect stronger. (And more turns of wire increase this effect).','2026-11-01 07:57:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_025','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why does a compass needle point roughly toward the Earth''s geographic North?','["Because the Earth has a giant magnet inside it, creating a planetary magnetic field that aligns the free-spinning compass needle.","Because the Sun pulls the needle north.","Because gravity pulls compass needles north.","Because the North Pole is made of solid copper."]',0,'Our whole planet acts like a giant bar magnet floating in space!','Earth behaves approximately like a giant magnet, so a compass needle usually points roughly toward geographic north.','2026-11-01 07:57:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_026','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'If you wrap an insulated wire around an iron nail and connect the ends to a low-voltage battery, what have you built?','["A simple electric motor","A simple electromagnet","A series circuit","A permanent bar magnet"]',1,'You made a homemade magnet using electricity!','An electromagnet is a magnet produced by electric current flowing through a coil of wire. Wrapping the wire around an iron core... A simple electromagnet has three main parts: A coil... An iron core... A low-voltage battery...','2026-11-01 07:57:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_027','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why is it important to disconnect the battery if your homemade electromagnet wire starts to feel warm?','["Because warmth means the battery is charging.","Because a warm wire means too much current is flowing (a short circuit), which can drain the battery quickly and cause burns or a fire hazard.","Because warm wires turn into permanent magnets.","Because warmth makes the wire invisible."]',1,'Too much current makes the wire dangerously hot.','Disconnect the battery if the wire or battery becomes warm.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_028','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'How do recycling plants use powerful electromagnets?','["To melt down glass bottles.","To lift and separate heavy iron and steel scrap metal from other non-magnetic waste materials easily.","To crush wooden boxes into pulp.","To sort plastic bags by color."]',1,'A giant crane with an electromagnet can pick up a pile of old cars instantly!','Industry and recycling: Powerful electromagnets can lift and sort certain iron and steel objects.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_029','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'Why can a magnet attract a paperclip through a thin wooden table or a piece of paper?','["Because paper and wood are magnetic materials.","Because magnetic fields can pass through non-magnetic materials like paper, wood, and glass without losing all their force.","Because the paperclip has its own battery.","Because the table is made of iron."]',1,'The invisible magnetic field goes right through the table to grab the clip underneath.','This field can exert a force on certain materials... (The magnetic field passes right through thin barriers).','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_030','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',5,'What is a major safety hazard when handling two very strong rare-earth magnets?','["They might turn into water.","They can snap together with immense force and severely pinch your fingers or shatter into sharp pieces.","They might float away into the ceiling.","They cause instant hearing loss."]',1,'They pull toward each other so fast they can catch your skin in between!','Handle strong magnets carefully because they can pinch fingers or break if they snap together.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_031','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Critique the common misconception that ''all metals are magnetic.''','["The misconception is actually a scientific law because every metal contains free electrons.","This is a widespread false belief. While metals like iron, steel, nickel, and cobalt are strongly magnetic, the vast majority of common industrial and precious metals—such as copper, aluminum, gold, silver, lead, and brass—are entirely non-magnetic in everyday conditions.","All metals are magnetic, but some require electricity to activate.","Only non-metals can be magnetic."]',1,'People think ''metal = magnet'', but aluminum cans and copper pennies don''t stick at all!','Not all metals are magnetic. A steel paper clip is usually attracted to a magnet. An aluminium can is generally not attracted to an ordinary magnet.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_032','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Analyze the physical impossibility of isolating a ''Magnetic Monopole'' using ordinary bar magnets.','["You can easily make a North-only magnet by cutting a bar magnet in half.","According to Maxwell''s equations and atomic physics, magnetic field lines must always form continuous closed loops. Breaking a bar magnet merely creates two smaller dipoles, each possessing both a North and South pole, because magnetic fields originate from electron spin/current loops, not isolated point charges.","Cutting a magnet in half destroys the magnetic field completely.","A magnetic monopole can be created by freezing the magnet."]',1,'Every ''piece'' of a magnet must have two sides; you can''t have a coin with only one face!','If an ordinary bar magnet is broken into smaller pieces, each piece forms its own north and south poles; breaking it does not normally produce a separate north-only or south-only magnet.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_033','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Synthesize how the microscopic alignment of ''domains'' explains why an unmagnetized piece of iron can be magnetized.','["Iron contains tiny pre-made magnets that shoot out of the metal.","In an unmagnetized iron bar, microscopic regions called ''magnetic domains'' point in random, conflicting directions, canceling out their net magnetic fields. Stroking the iron with a strong permanent magnet forces these domains to align in a unified direction, turning the bar into a magnet.","Magnetizing iron requires melting it into a liquid state.","Domains are imaginary lines drawn by scientists on paper."]',1,'The tiny magnetic ''neighborhoods'' inside the iron all get pointed the exact same way!','Some materials, such as iron, can also become magnetised under suitable conditions.','2026-11-01 07:57:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_034','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Evaluate the geopolitical and navigational significance of ''Magnetic Declination'' regarding compass usage.','["Magnetic declination means a compass points directly to the true South Pole.","True geographic North (the rotational axis) and Magnetic North (the geomagnetic pole) do not occupy the same spatial coordinate. This angular variance (declination) shifts depending on your exact global location, requiring navigators to mathematically correct their compass bearings to avoid severe navigational errors.","Declination is a fictional concept used only in video games.","Magnetic north and geographic north are identical everywhere on Earth."]',1,'The compass doesn''t point to the exact top of the world; you have to adjust for the difference!','Earth behaves approximately like a giant magnet, so a compass needle usually points roughly toward geographic north. However, magnetic north and geographic north are not exactly the same location, and the difference varies from place to place.','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_035','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Analyze the electromechanical feedback loop inside an audio ''Loudspeaker''.','["A loudspeaker uses light waves to push air molecules.","A loudspeaker combines a permanent magnet and an electromagnet (voice coil). An alternating electrical audio signal flows through the coil, creating a fluctuating magnetic field. This field interacts with the permanent magnet, forcing the coil and attached speaker cone to vibrate rapidly, compressing the air into sound waves.","A loudspeaker uses a motor to spin a disc that cuts the air.","A loudspeaker relies entirely on static electricity."]',1,'Electricity makes the coil push and pull against the permanent magnet, shaking the cone to make music!','Speakers use magnets and electric currents to help turn electrical signals into sound.','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_036','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Synthesize the thermodynamic consequence of applying excessive heat (the Curie Point) to a permanent magnet.','["Heating a magnet makes its magnetic field infinitely stronger.","Thermal energy increases the kinetic vibrational energy of the atoms within a permanent magnet. If heated past a specific threshold (the Curie Point), this thermal agitation violently disrupts and randomizes the microscopic domain alignment, permanently destroying the permanent magnetism.","Heating a magnet turns it into solid gold.","Heat has no effect on magnetic domains."]',1,'If you bake a magnet until it''s red hot, the atoms shake so violently that the magnet completely loses its power!','Some materials, such as iron, can also become magnetised... (Implicit: Extreme thermal energy disrupts atomic alignment).','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_037','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Critique the conceptual symmetry between ''Electric Charges'' and ''Magnetic Poles''.','["Electric charges and magnetic poles are mathematically and physically identical.","While both exhibit dipole characteristics, they are fundamentally distinct. Electric charges can exist as isolated monopoles (a single positive proton or negative electron). Magnetic poles, however, cannot exist in isolation; they must always exist in dipole pairs (North and South).","Magnetic poles can exist as isolated monopoles, while electric charges cannot.","Electric charges must always exist in pairs like magnets."]',1,'You can have a single positive electric charge, but you can never have a single ''North'' magnetic charge!','Every ordinary bar magnet has two poles... breaking it does not normally produce a separate north-only... (Contrasted with electric charges which can be isolated).','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_038','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Evaluate the functional role of the Earth''s molten outer core in generating its planetary magnetic field (the Geodynamo).','["The Earth''s magnetic field is caused by solid iron mountains on the surface.","The Earth''s geodynamo is driven by convection currents of molten iron and nickel in the outer core. Because these liquid metals are electrically conductive and circulating due to planetary rotation, they act as a massive, self-sustaining planetary electromagnet.","The core is made of plastic and creates static electricity.","The Earth''s magnetic field comes from the Moon''s gravity."]',1,'Swirling rivers of liquid metal deep inside the Earth act like a giant natural generator!','Earth behaves approximately like a giant magnet...','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_039','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Analyze why a compass needle will behave erratically or fail near high-voltage power lines or heavy machinery.','["Power lines are made of wood, which blocks magnetism.","High-voltage alternating current (AC) electricity flowing through power lines generates powerful, fluctuating localized electromagnetic fields. These external fields overpower the weak geomagnetic field of the Earth, forcing the compass needle to align with the electrical interference rather than North.","Power lines freeze the compass needle in place.","High-voltage lines attract the compass casing physically."]',1,'Electricity creates its own magnetic field, which tricks the compass into pointing the wrong way!','Keep a compass away from strong magnets and magnetic objects while taking a reading, because they can disturb the needle.','2026-11-01 07:57:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_040','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Synthesize how ''Magnetic Levitation'' (Maglev) trains utilize the fundamental rules of magnetism to eliminate friction.','["Maglev trains use wheels coated in special grease to eliminate friction.","Maglev trains use powerful electromagnets on the train and the track. By configuring the like poles to face each other (North-North or South-South), the train is magnetically repelled upward and levitated above the track, completely eliminating mechanical wheel-on-rail friction and allowing extreme velocities.","Maglev trains use gravity to pull themselves forward.","Maglev trains use anchors to drag themselves along the ground."]',1,'By making the train float on a cushion of magnetic repulsion, there is zero friction slowing it down!','Like poles repel. North and north repel... (Applied to advanced transport technology like repulsion levitation).','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_041','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Evaluate the physical safety hazard of children swallowing multiple small ''rare-earth'' (neodymium) magnets.','["Swallowing magnets is completely safe because they pass through the body naturally.","Rare-earth magnets are extraordinarily powerful. If a child swallows multiple magnets at different times, the magnets can attract each other *through* the folds of different intestinal walls. This continuous magnetic clamping cuts off blood supply, causing rapid tissue necrosis, perforations, and life-threatening internal injuries.","Swallowing magnets gives the child superpowers.","Magnets dissolve safely in stomach acid instantly."]',1,'If two strong magnets inside a child''s belly pull toward each other through the intestines, they trap the tissue and cause severe damage!','Keep small, powerful magnets away from young children. Swallowing magnets can cause life-threatening internal injuries, especially if more than one is swallowed.','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_042','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Analyze the mechanical transition in an ''Electromagnetic Relay'' used in heavy industry.','["A relay uses a manual hand crank to turn heavy machinery on and off.","A relay is an electrically operated switch. A small, safe low-voltage current passes through an electromagnet coil. The resulting magnetic field pulls a metal switch closed, completing a secondary, high-voltage circuit to power heavy machinery safely without human contact with high voltage.","A relay converts electrical energy into sound waves.","A relay uses water pressure to push a metal switch."]',1,'A tiny electric whisper uses a magnet to flip a giant, heavy-duty power switch safely!','Electromagnets are useful because their magnetic effect can be controlled. They are used in electric motors, relays, some lifting equipment...','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_043','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Synthesize why magnetic field lines ''never cross one another'' in physics diagrams.','["Field lines cross each other constantly in complex loops.","Magnetic field lines are a graphical representation of the net direction of magnetic force at any given point. If two lines crossed, it would imply that a single point in space has two simultaneous, conflicting net magnetic force vectors, which is physically impossible.","Crossing field lines causes the magnet to explode.","Field lines cross each other to create North poles."]',1,'A compass needle can only point in one direction at a time; therefore, field lines can never intersect!','Field lines do not cross one another.','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_044','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Critique the design of a compass when used near a massive iron ore deposit in the wilderness.','["An iron deposit makes the compass 100% accurate.","Iron ore is a strongly magnetic material. A massive deposit underground generates an anomalous local magnetic field (a magnetic anomaly). This local field distorts the Earth''s ambient field, causing a compass needle to point toward the ore body rather than Magnetic North, leading travelers astray.","Iron ore turns the compass into an electromagnet.","Iron ore completely destroys the compass needle so it won''t move."]',1,'A mountain made of iron will act like a giant fake North Pole and trick your compass!','Keep a compass away from strong magnets and magnetic objects while taking a reading, because they can disturb the needle.','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_magnet_global_045','Physics','Magnets and Magnetism','Topic 11: Magnets and Magnetism','Primary',10,'Evaluate the role of ''Magnetic Hysteresis'' in the temporary versus permanent magnetism of materials.','["All materials retain 100% of their magnetism forever once touched by a magnet.","Materials differ in their retentivity. Soft iron (used in electromagnets) has low retentivity, meaning it magnetizes easily but loses its magnetism instantly when current stops. Hard steel has high retentivity, retaining its magnetic alignment to form a permanent magnet.","Soft iron makes the best permanent bar magnets.","Retentivity only applies to electrical resistance, not magnetism."]',1,'Some metals love to hold onto magnetism (permanent), while others let it go the second you turn off the power (temporary)!','When the current is switched off, most of the magnetic effect disappears, although the core may retain some magnetism. (Contrasted with permanent magnets).','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_001','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What are the two states of matter that are called ''fluids''?','["Solids and liquids","Liquids and gases","Solids and gases","Ice and water"]',1,'Fluids are things that can easily change their shape to fit a container.','Liquids and gases are called fluids because they can flow.','2026-11-01 07:57:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_002','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'Why are liquids and gases called fluids?','["Because they are invisible","Because they can flow","Because they are heavy","Because they are always cold"]',1,'It means they can pour or spread out.','Liquids and gases are called fluids because they can flow.','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_003','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'Does air take up space?','["No, air is completely empty.","Yes, air is matter and occupies space.","Only when it is cold.","Only when it is windy."]',1,'Think about what happens when you blow up a balloon!','Air is matter: it has mass and occupies space.','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_004','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What produces ''air pressure''?','["The sun heating the ground","Air particles moving and colliding with surfaces","Clouds rubbing together","Gravity pulling on water"]',1,'It''s millions of tiny invisible particles bumping into you.','Air particles move in different directions and collide with surfaces. These collisions produce air pressure.','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_005','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What happens to water pressure as you go deeper underwater in a swimming pool?','["It decreases","It stays exactly the same","It increases","It turns into air pressure"]',2,'There is more heavy water pressing down on you from above!','Deeper underwater, water pressure is greater. In a still body of water, pressure increases with depth...','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_006','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What is ''density''?','["How fast an object moves in water","The amount of mass in a given volume","How wide a boat is","The temperature of a fluid"]',1,'It tells you how tightly packed the ''stuff'' inside an object is.','Density is the amount of mass in a given volume.','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_007','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What is another name for ''buoyancy''?','["Gravity","Upthrust","Friction","Air resistance"]',1,'It is the water pushing up!','Buoyancy, also called upthrust, is the upward force a fluid exerts on an object immersed in it.','2026-11-01 07:57:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_008','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What does ''buoyancy'' or ''upthrust'' do to an object in water?','["It pushes the object downward.","It pushes the object upward.","It makes the object spin.","It freezes the object."]',1,'It fights against gravity to help things float.','Buoyancy, also called upthrust, is the upward force a fluid exerts on an object immersed in it.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_009','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What is ''drag''?','["A force that pulls things down","A force that opposes (fights against) movement through a fluid","A force that makes things speed up","A force that creates light"]',1,'It slows you down when you try to run in a swimming pool.','When an object moves through a fluid, the fluid can oppose its movement. This opposing force is called fluid resistance or drag.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_010','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What is ''air resistance''?','["A type of gravity","Drag caused by moving through air","A way to make cars go faster","The weight of the clouds"]',1,'It is the air pushing back against you when you ride a bike fast.','Air resistance acts on objects moving through air.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_011','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What is ''water resistance''?','["Water turning into ice","Drag caused by moving through water","Water falling from a waterfall","Water moving through a pipe"]',1,'It is what makes swimming hard work!','Water resistance acts on objects moving through water.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_012','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'Why does a parachute help a person fall slower?','["It makes gravity disappear.","It increases air resistance because of its large surface area.","It pushes the air downwards.","It is filled with helium."]',1,'The big canopy catches a lot of air, which pushes back up!','A parachute has a large surface area, so air resistance increases and helps slow the descent.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_013','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'What does it mean if an object is ''streamlined''?','["It is shaped like a perfect square.","It is shaped to reduce resistance (drag) while moving through a fluid.","It is made of heavy metal.","It is filled with air."]',1,'Fish and airplanes are shaped this way so they can move smoothly.','Streamlined: Shaped to reduce resistance while moving through a fluid.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_014','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'If an object has a *lower* average density than water, what will it usually do?','["Sink","Explode","Float","Melt"]',2,'Wood floats because it is less dense than water.','An object with a lower average density than water will generally float in water.','2026-11-01 07:57:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_015','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',1,'If an object has a *greater* average density than water, what will it usually do?','["Float","Sink","Fly","Evaporate"]',1,'A solid rock sinks because it is denser than water.','an object with a greater average density generally sinks...','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_016','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'If you push an empty, open plastic bottle straight down into a bucket of water, why doesn''t the water fill the bottle completely?','["Because the water is too cold.","Because the bottle is already full of air (a gas), and since air takes up space, the water cannot enter unless the air is allowed to escape.","Because the bottle creates a magnetic field that repels water.","Because plastic dissolves in water."]',1,'You can''t put water into a space that is already full of air!','When the bottle is held upright and submerged, the air trapped inside prevents water from filling the space completely... Air occupies space.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_017','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'How does ''air pressure'' help you drink juice through a straw?','["The straw pushes the juice down.","When you suck on the straw, you lower the air pressure inside it; the higher atmospheric pressure pushing down on the juice in the cup forces the liquid up into the straw.","The juice is magnetic and sticks to the straw.","The straw creates gravity."]',1,'You aren''t really pulling the liquid up; the outside air is pushing it up!','Drinking through a straw: When pressure inside the straw is reduced, atmospheric pressure on the drink''s surface helps push liquid up the straw.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_018','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why is air pressure generally lower on top of a high mountain than at sea level?','["Because it is colder on a mountain.","Because there is less atmosphere (less heavy air) resting above you pushing down.","Because mountains are closer to the sun.","Because mountains block the wind."]',1,'Think of the atmosphere like a giant pile of blankets; at the top of the mountain, you have fewer blankets on top of you!','Air pressure changes with altitude. It is generally lower on high mountains than near sea level because there is less atmosphere above.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_019','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why must deep-sea divers be careful about how deep they swim?','["Because water loses its density in the deep ocean.","Because water pressure increases with depth; the deeper they go, the more heavy water is pressing down and crushing inward on their bodies and equipment.","Because the water gets too bright.","Because there is no gravity deep underwater."]',1,'The weight of the ocean above you is incredibly heavy!','Deeper underwater, water pressure is greater... This is why divers must follow safe depth limits and why underwater equipment needs to be designed to withstand pressure.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_020','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'How do the forces of ''weight'' and ''upthrust'' work together when an object is floating perfectly still on a lake?','["Weight pushes up, upthrust pushes down.","The downward force of gravity (weight) is exactly balanced by the upward buoyant force (upthrust) from the water.","The upthrust is much stronger than the weight.","The weight is much stronger than the upthrust."]',1,'It''s a perfect tie between gravity pulling down and water pushing up!','If these forces balance, an object can float at rest.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_021','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why does a solid steel block sink, but a massive steel cargo ship floats?','["Because cargo ships are painted with special floating paint.","The ship is hollow and filled mostly with air. This makes the *average* density of the entire ship lower than water, allowing it to displace enough water to create a balancing upthrust.","Because the cargo ship uses engines to push itself out of the water.","Because the ocean is denser than solid steel."]',1,'It''s not about what it is made of; it is about how much space it takes up compared to its weight!','A ship is made from materials such as steel, which is denser than water. However, the ship''s hollow hull contains a large amount of air, making the average density of the entire ship low enough for it to float.','2026-11-01 07:57:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_022','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'What does it mean when a ship ''displaces'' water?','["It turns the water into a gas.","As the ship enters the ocean, its hull physically pushes water out of the way to make room for itself.","It drinks the water to become heavier.","It makes the water freeze."]',1,'If you sit in a full bathtub, the water you push out of the way spills over the edge; that is displacement!','The ship pushes water aside as it enters the water. This displaced water produces the upward buoyant force...','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_023','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why is a fish shaped like a torpedo (streamlined)?','["To scare away predators.","This shape helps the fish easily cut through the water, drastically reducing ''water resistance'' (drag) and saving the fish energy when swimming.","So it can hold more air inside its body.","To increase the water pressure on its head."]',1,'A flat box is hard to push through water, but a pointed shape glides easily!','Fish and many boats have streamlined shapes that reduce resistance as they move through water.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_024','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why is it harder to ride a bicycle really fast than it is to ride it slowly, even on a flat road?','["Because gravity gets stronger when you move fast.","As you pedal faster, you hit the air particles harder and faster, massively increasing the ''air resistance'' (drag) pushing backward against you.","Because the tires melt at high speeds.","Because the bicycle loses mass when moving fast."]',1,'The faster you go, the harder the wind pushes back!','Air resistance opposes a cyclist''s movement. At higher speeds, overcoming it usually requires more effort.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_025','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'How does a hot-air balloon use buoyancy to fly?','["It uses a massive propeller to push the air down.","Heating the air inside the balloon makes it spread out and become less dense than the cooler air outside; the denser outside air provides enough upthrust to lift the lighter balloon.","It uses magnets to repel the Earth.","The fire burns gravity away."]',1,'Hot air floats on top of cold air, carrying the balloon up with it!','Heating the air inside a balloon makes it less dense than the surrounding air. Buoyancy can lift the balloon when the upward force is sufficient.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_026','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'If you press a plastic suction cup against a window, why does it stick so tightly?','["Because the plastic melts into the glass.","Pressing it pushes the air out from underneath; the higher air pressure of the room on the outside pushes the cup tightly against the glass.","Because it creates a magnetic field.","Because the glass is sticky."]',1,'The heavy air in the room is literally pressing the cup against the wall!','Pressing a suction cup against a smooth surface removes some air from underneath. The greater outside air pressure helps hold it in place.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_027','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'What happens if a floating cargo ship is loaded with too many heavy shipping containers?','["It will float higher in the water.","Its total weight increases, forcing it to sink deeper to displace more water for upthrust; if overloaded, it won''t be able to displace enough water and will sink completely.","The ship will turn into an airplane.","The upthrust will disappear instantly."]',1,'If it gets too heavy, the water can''t push back hard enough!','Adding too much cargo increases the ship''s weight. The ship then sinks deeper into the water to displace more water and obtain more upthrust. If it is overloaded, it may become unsafe.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_028','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'Why do airplanes need powerful engines just to move forward through the sky?','["Because clouds are very heavy.","They have to overcome ''air resistance'' (drag) which constantly pushes backward against the airplane as it flies through the atmosphere.","Because gravity pulls them backward.","Because space tries to suck them upwards."]',1,'Even though air feels thin, pushing a giant metal plane through it at 500 mph takes a lot of force!','Aircraft: ... Air resistance, or drag, acts against its motion.','2026-11-01 07:57:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_029','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'How does water pressure help deliver water to the taps in your house?','["The taps pull the water using magnets.","Water is often stored in high tanks (like water towers); gravity pulls the water down, creating high pressure in the pipes that pushes the water forcefully out of your tap.","The pipes are squeezed by giant machines.","The water boils and turns into steam."]',1,'The heavy water in the tall tower is pushing down, forcing the water in your pipes to squirt out!','Water supply: Water pressure helps move water through pipes and out of taps... The height of the water above the outlet helps create the pressure that drives the flow.','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_030','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',5,'If you drop a flat piece of paper and a crumpled ball of paper from the same height, why does the ball hit the ground first?','["Because crumpling the paper makes it heavier.","The flat paper has a much larger surface area, which catches more air particles and creates much more air resistance (drag) than the compact ball.","Because gravity pulls harder on round objects.","Because the flat paper floats like a balloon."]',1,'The flat paper has to push a lot more air out of its way to fall!','A parachute [or flat paper] has a large surface area, so air resistance increases and helps slow the descent.','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_031','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Critique the everyday assertion that ''Air has no weight.''','["The assertion is perfectly true; gas has no mass.","The assertion is scientifically false. Air is a mixture of physical gas molecules (nitrogen, oxygen, etc.). Because it is matter, it has mass, and therefore the Earth''s gravity pulls on it, giving it weight and creating atmospheric pressure.","Air only has weight when it is raining.","Air has weight, but it is pushed upward by gravity."]',1,'The air above your head weighs as much as a school bus, but you don''t feel it because the pressure is balanced inside and outside your body!','Air is a mixture of gases... air is matter: it has mass and occupies space... At Earth''s surface, the atmosphere exerts pressure on us...','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_032','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Analyze Archimedes'' Principle regarding the exact mathematical relationship between buoyancy and displacement.','["Buoyancy is unrelated to how much water is displaced.","Archimedes'' Principle states that the upward buoyant force exerted on a submerged object is exactly equal to the weight of the fluid that the object displaces. If a ship displaces 10,000 tons of water, the ocean pushes up with 10,000 tons of buoyant force.","The buoyant force is always exactly half the weight of the water displaced.","Displacement only applies to gases, not liquids."]',1,'The water wants to flow back into the hole the ship made; that ''pushing back'' is the buoyant force!','The ship pushes water aside as it enters the water. This displaced water produces the upward buoyant force that supports the ship. (Synthesis: The force equals the displaced weight).','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_033','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Synthesize how the concept of ''Density'' explains why a helium balloon floats in the air, but a balloon filled with human breath sinks.','["Human breath is magnetic and pulls the balloon to the floor.","Helium is an element with a lower density than the surrounding mixture of atmospheric nitrogen and oxygen. Therefore, the buoyant force of the heavier surrounding air lifts the lighter helium balloon. Human breath contains heavier \\\\(CO_2\\\\), making it denser than the surrounding air.","Helium has zero mass, while human breath is solid.","Human breath destroys the balloon''s rubber, causing it to sink."]',1,'The heavy air in the room sinks to the floor, pushing the lighter helium balloon up to the ceiling!','Air also produces buoyancy. A helium-filled balloon can rise because the buoyant force from the surrounding air is greater than the combined weight of the balloon and its contents.','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_034','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Evaluate the physical mechanics of why water pressure is ''approximately equal in all horizontal directions'' at a specific depth.','["Water pressure only pushes straight down like a rock.","Because water is a fluid, its particles are mobile and constantly colliding. At a specific depth, the hydrostatic pressure created by the weight of the water above is transmitted equally in all directions (Pascal''s Principle), meaning it crushes inward on a diver from the sides and bottom just as hard as from the top.","Water pressure only pushes upward.","Horizontal pressure is caused by the Earth''s rotation."]',1,'If you are underwater, the water doesn''t just press on your head; it squeezes your whole body equally from every side!','At the same depth in the same still water, pressure is approximately equal in all horizontal directions.','2026-11-01 07:57:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_035','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Analyze how the design of a ''Parachute'' manipulates fluid dynamics to achieve a safe landing velocity (terminal velocity).','["A parachute removes gravity from the skydiver.","A parachute artificially maximizes the skydiver''s surface area. As velocity increases, the air resistance (drag) acting on this massive canopy increases exponentially until it exactly balances the downward force of gravity, resulting in a slow, constant, survivable terminal velocity.","A parachute uses helium to float the skydiver safely.","A parachute creates a vacuum that pulls the skydiver upwards."]',1,'The parachute creates so much drag that it forces a ''tie'' with gravity, so you stop speeding up and just drift down!','A parachute has a large surface area, so air resistance increases and helps slow the descent... Balanced forces cancel one another out...','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_036','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Synthesize the interaction between ''Air Pressure'' and ''Fluid Flow'' in the mechanics of a drinking straw.','["The straw has a tiny motor inside that pumps the liquid.","Drinking through a straw does not ''pull'' the liquid up. By expanding the lungs, a person creates a localized low-pressure vacuum inside their mouth and the straw. The higher, ambient atmospheric pressure resting on the surface of the drink then physically forces the liquid up the straw to equalize the pressure.","The liquid climbs the straw using surface tension.","The straw is magnetic and attracts the liquid."]',1,'You are just removing the air in the straw so the heavy air in the room can push the juice up into your mouth!','When pressure inside the straw is reduced, atmospheric pressure on the drink''s surface helps push liquid up the straw.','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_037','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Critique the statement: ''If an object is heavy, it will sink.''','["This statement is an absolute law of physics.","This statement is fundamentally flawed because it conflates ''weight'' (mass) with ''density''. An object''s sinking or floating is determined by its density relative to the fluid, not its absolute weight. A 100,000-ton aircraft carrier (heavy) floats, while a 10-gram solid gold coin (light) sinks.","This statement is only true for objects made of wood.","Heavy objects actually float better than light objects."]',1,'A tiny pebble sinks, but a massive iceberg floats; it''s all about density!','Whether an object floats or sinks depends on several factors, especially its average density... A solid piece of steel usually sinks... But a ship [which is very heavy]... can be low enough [density] for it to float.','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_038','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Evaluate the engineering trade-off of a ''Streamlined'' design in automotive or aerospace manufacturing.','["Streamlined designs have no drawbacks and are perfect for everything.","While streamlining a vehicle drastically reduces aerodynamic drag (saving fuel and allowing higher top speeds), the teardrop or tapered shape severely restricts internal volumetric capacity, forcing engineers to compromise between maximum aerodynamic efficiency and practical cargo/passenger space.","Streamlining increases drag to make the vehicle safer.","Streamlined designs are only used in boats, not cars."]',1,'A sports car cuts through the wind easily, but you can''t fit a sofa in the back!','Streamlined shapes: Fish and many boats have streamlined shapes that reduce resistance as they move through water. Air flowing around an aircraft''s wings... Air resistance, or drag, acts against its motion.','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_039','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Analyze how the ''Altitude'' affects the boiling point of water due to Atmospheric Pressure.','["Altitude makes water boil instantly at room temperature.","As altitude increases (e.g., climbing a mountain), the column of atmosphere above decreases, leading to lower atmospheric pressure. Because boiling requires liquid vapor pressure to overcome atmospheric pressure, water boils at a significantly lower temperature at high altitudes.","Altitude has no effect on water or pressure.","Higher altitude means higher pressure, so water never boils."]',1,'On top of Mount Everest, water boils before it even gets hot enough to cook pasta properly!','Air pressure changes with altitude. It is generally lower on high mountains than near sea level because there is less atmosphere above.','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_040','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Synthesize the concept of a ''Submarine'' diving and surfacing using the principles of density and buoyancy.','["A submarine uses giant underwater wings to fly to the surface.","A submarine controls its depth by manipulating its overall average density. To dive, it floods its ballast tanks with seawater, increasing its mass and density until weight exceeds upthrust. To surface, it pumps compressed air into the tanks, expelling the water, lowering its density until upthrust exceeds weight.","A submarine changes the density of the ocean around it.","A submarine uses magnets to repel the ocean floor."]',1,'To sink, the sub drinks water to get heavy. To float, it blows the water out to get light!','An object generally floats when the fluid can provide enough upward force to balance its weight... An object sinks when its weight exceeds the maximum upward buoyant force... Density is the amount of mass in a given volume.','2026-11-01 07:57:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_041','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Critique the safety hazard of ''Suction Cups'' failing at extremely high altitudes (like in a high-altitude airplane or space).','["Suction cups become permanently glued to the window at high altitudes.","Suction cups function because the ambient external air pressure is significantly stronger than the low pressure trapped underneath the cup. At high altitudes (or in a vacuum), the external atmospheric pressure is drastically reduced or eliminated, meaning there is no external force to hold the cup to the surface, and it will fail.","Suction cups actually work better in space because there is no gravity.","Suction cups rely on sticky glue, not air pressure."]',1,'Without heavy air in the room to push on the back of the cup, it just falls off!','Suction cups: Pressing a suction cup against a smooth surface removes some air from underneath. The greater outside air pressure helps hold it in place. Air pressure... is generally lower on high mountains...','2026-11-01 07:57:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_042','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Analyze how ''Drag'' (fluid resistance) differs from solid mechanical ''Friction''.','["They are exactly identical in every mathematical aspect.","Solid friction is generally independent of velocity. However, fluid drag (air/water resistance) is highly velocity-dependent; the drag force increases exponentially (often squared) as the object''s speed through the fluid increases, making high-speed travel massively energy-intensive.","Drag actually pushes objects forward, while friction pulls them back.","Drag only happens in space, friction only happens on Earth."]',1,'Walking through waist-deep water is easy, but trying to sprint through it is almost impossible!','When an object moves through a fluid, the fluid can oppose its movement. This opposing force is called fluid resistance or drag... At higher speeds, overcoming it usually requires more effort.','2026-11-01 07:57:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_043','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Synthesize why human bodies do not collapse under the immense ''Air Pressure'' at sea level.','["Human bodies are made of solid steel that cannot be crushed.","At sea level, atmospheric pressure exerts tremendous force (about 14.7 psi) on the human body. However, the human body is largely composed of incompressible fluids (water/blood) and pressurized gases (in the lungs) that exert an equal and opposite outward pressure, maintaining structural equilibrium.","Gravity pulls the air pressure away from our bodies.","Humans actually do collapse, but we don''t notice it."]',1,'The air inside you is pushing out just as hard as the atmosphere is pushing in!','At Earth''s surface, the atmosphere exerts pressure on us, but we do not usually feel crushed because the fluids inside our bodies exert pressure too.','2026-11-01 07:57:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_044','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Evaluate the physical mechanics of why a ''Hot-air balloon'' must eventually land if the burner is turned off.','["The balloon gets too tired to fly.","The balloon''s buoyancy depends on the air inside being significantly hotter (and thus less dense) than the ambient air. If the burner is turned off, the trapped air slowly cools and contracts via thermal transfer. Its density increases until it matches the outside air, eliminating the buoyant upthrust.","The balloon becomes heavier because it absorbs clouds.","Gravity only works when the burner is turned off."]',1,'When the air inside cools down, it shrinks and gets heavy again, bringing the balloon back to Earth!','Heating the air inside a balloon makes it less dense than the surrounding air. Buoyancy can lift the balloon... (Synthesis: If it cools, it becomes dense again and sinks).','2026-11-01 07:57:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_fluids_global_045','Physics','Forces in Liquids and Gases','Topic 12: Forces in Liquids and Gases','Primary',10,'Critique the idea that ''Water has no shape.''','["The idea is true; water is completely invisible and shapeless.","While it is true that water is a fluid and lacks a *fixed* macroscopic shape (it conforms to its container), at the molecular level, water droplets form distinct spherical shapes due to surface tension and cohesion, proving that fluid mechanics dictate form even without a container.","Water actually has a fixed shape like a diamond.","Water is a solid, so it always has a shape."]',1,'If you pour water into a square cup, it becomes a square. But a single raindrop naturally forms a sphere!','Liquids have a fixed volume but take the shape of their container. (Synthesis: But surface tension in freefall or small drops creates a spherical shape).','2026-11-01 07:57:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_001','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is the Sun?','["A large planet","A star at the centre of our Solar System","A giant moon","A human-made satellite"]',1,'It is a huge ball of very hot gas.','The Sun is a star at the centre of our Solar System.','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_002','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What does the Sun provide for the Earth?','["Most of its natural light and energy (heat)","Water and rocks","Oxygen to breathe","Gravity to pull the moon"]',0,'Without it, the Earth would be freezing dark.','The Sun provides Earth with most of its natural light and energy.','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_003','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is Earth''s ''rotation''?','["The Earth spinning around its own imaginary axis","The Earth travelling around the Sun","The Earth moving closer to the Moon","The Earth stopping completely"]',0,'It is like a spinning top.','Earth spins around an imaginary line called its axis. This movement is called rotation.','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_004','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'How long does it take the Earth to complete one rotation?','["One year","About 24 hours","One month","One week"]',1,'This creates one full day and night cycle.','Earth takes about 24 hours to complete one rotation...','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_005','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What causes day and night on Earth?','["The Sun turning off and on","The Moon blocking the Sun","The Earth''s rotation (spinning on its axis)","The Earth moving closer to the Sun"]',2,'When your side of the Earth faces the Sun, it is day!','Earth takes about 24 hours to complete one rotation... As Earth rotates, different places face toward or away from the Sun (Day and Night).','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_006','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is Earth''s ''revolution''?','["The Earth spinning on its axis","The Earth travelling around the Sun","The Moon travelling around the Earth","The Sun travelling around the Earth"]',1,'It is the long journey around the star.','Earth also moves around the Sun. This motion is called revolution.','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_007','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'How long does it take the Earth to complete one revolution (orbit) around the Sun?','["24 hours","Approximately 365.25 days (one year)","One month","Ten years"]',1,'This is why we have a calendar year.','Earth takes approximately 365.25 days to complete one orbit around the Sun. This period is one year.','2026-11-01 07:57:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_008','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'Does the Moon produce its own light?','["Yes, it is a small star.","No, it reflects sunlight.","Yes, it is made of fire.","No, it absorbs all light."]',1,'It acts like a giant, rocky mirror in the sky.','The Moon... reflects sunlight; it does not produce its own visible light like a star.','2026-11-01 07:57:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_009','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What are the ''phases of the Moon''?','["The changing shapes of the Moon as pieces break off","The changing appearances of the Moon''s sunlit half as it orbits Earth","The colors of the Moon changing","The Moon moving closer to Earth"]',1,'Sometimes it looks like a crescent, sometimes it looks full.','As the Moon orbits Earth, we see different portions of its sunlit half. These changing appearances are called phases of the Moon.','2026-11-01 07:57:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_010','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is a ''Full Moon''?','["When the Moon is completely invisible","When the Moon''s Earth-facing side is almost fully illuminated (lit up)","When the Moon is shaped like a crescent","When the Moon is red"]',1,'It looks like a big bright circle.','Full Moon: The Moon''s Earth-facing side is almost fully illuminated.','2026-11-01 07:57:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_011','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What force keeps the planets in orbit around the Sun?','["Magnetism","Air resistance","Gravity","Friction"]',2,'The Sun pulls on the planets so they don''t float away.','The Sun''s gravity keeps the planets in orbit around it.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_012','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'How many recognized planets are in our Solar System?','["Four","Eight","Ten","Nine"]',1,'Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.','There are eight recognised planets.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_013','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'Which planet is the largest in the Solar System?','["Earth","Saturn","Jupiter","Mars"]',2,'It is a massive gas giant.','Jupiter: The largest planet in the Solar System.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_014','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is an ''artificial satellite''?','["A moon that orbits a planet","A human-made machine placed in orbit around Earth or another body","A type of star","A shooting star (meteor)"]',1,'Humans launch these into space on rockets.','Artificial satellite: A human-made machine placed in orbit, often around Earth.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_015','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',1,'What is the main reason Earth has different seasons (Summer, Winter)?','["The Earth moving closer to the Sun","The Earth''s axial tilt (it is leaning to one side)","The Sun changing temperature","The Moon blocking the Sun"]',1,'Because it tilts, one side gets more direct sunlight than the other!','Earth''s axial tilt is the main reason for the seasons.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_016','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why is the Sun critical for life on Earth, beyond just providing light to see?','["Because it provides gravity that creates oxygen.","Its energy warms the Earth to keep water liquid, drives the weather, and allows plants to make food (photosynthesis).","Because it absorbs harmful radiation from space.","Because it creates magnetic fields that protect animals."]',1,'Without the Sun, the Earth would be a frozen, lifeless rock!','The Sun... Warms Earth''s surface... Helps plants make food through photosynthesis. Drives much of Earth''s weather... Supports life by keeping Earth within a temperature range where liquid water can exist.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_017','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why does the Sun appear to move across the sky from east to west every day?','["Because the Sun orbits around the Earth.","Because the Earth is rotating (spinning) on its axis from west to east.","Because the Earth is revolving around the Sun.","Because the clouds are moving east to west."]',1,'You are the one spinning; the Sun is sitting still!','The Sun appears to move across the sky from east to west during the day, but this apparent movement is mainly caused by Earth rotating from west to east.','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_018','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why do we have a ''leap year'' with an extra day in February every four years?','["Because the Earth slows down every four years.","Because a single Earth revolution takes about 365.25 days; the extra quarter-days add up to one full day every four years.","Because the Moon''s orbit changes every four years.","Because the Sun grows larger every four years."]',1,'0.25 + 0.25 + 0.25 + 0.25 = 1 extra day!','Earth takes approximately 365.25 days to complete one orbit... The extra quarter-day accumulates, which is why leap years usually include an additional day in February every four years...','2026-11-01 07:57:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_019','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'What is the difference between the ''New Moon'' phase and the ''Full Moon'' phase?','["A New Moon is when the Moon explodes; a Full Moon is when it grows back.","During a New Moon, the sunlit side faces away from Earth (making it hard to see). During a Full Moon, the sunlit side fully faces the Earth.","A New Moon happens in summer; a Full Moon happens in winter.","A New Moon is blue; a Full Moon is yellow."]',1,'It depends on which side of the Moon the Sun is shining on!','New Moon: The side illuminated by the Sun mostly faces away from Earth... Full Moon: The Moon''s Earth-facing side is almost fully illuminated.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_020','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Is a ''lunar eclipse'' the same thing as the regular phases of the Moon?','["Yes, they are the exact same thing.","No, phases are caused by our viewing angle of the sunlit half, while an eclipse happens when the Earth''s shadow physically blocks the Sun''s light from hitting the Moon.","Yes, an eclipse just means a very bright full moon.","No, an eclipse only happens during the day."]',1,'Phases happen every month; eclipses are rare events!','Important: The phases do not happen because Earth''s shadow normally covers the Moon. Earth''s shadow causes a lunar eclipse, which is a different event.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_021','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why do astronauts on the International Space Station appear to float if there is still gravity in space?','["Because space is a perfect vacuum that destroys gravity.","They are in continuous ''free-fall'' moving around the Earth at the exact same speed as the space station, which creates the feeling of weightlessness.","Because they wear special anti-gravity boots.","Because they are too far away for Earth''s gravity to reach them."]',1,'Gravity is still pulling them down, but they are moving sideways so fast that they keep ''missing'' the Earth!','Gravity acts throughout space... The spacecraft and the astronauts are both falling around Earth together. This continuous free-fall creates the feeling of weightlessness.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_022','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Which planet in the Solar System is known as the ''Red Planet'' and why?','["Venus, because it is the hottest planet.","Mars, because its surface is covered in iron-rich dust (rust).","Jupiter, because of its giant red spot.","Mercury, because it is closest to the Sun."]',1,'It literally looks like a rusty ball in space!','Mars: Known as the Red Planet because of iron-rich dust on its surface.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_023','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why is Venus hotter than Mercury, even though Mercury is closer to the Sun?','["Because Venus has a fire burning on its surface.","Venus has a very dense atmosphere that creates a massive greenhouse effect, trapping the Sun''s heat.","Because Venus is much larger than Mercury.","Because Venus generates its own heat from the core."]',1,'Venus acts like a giant, super-heated blanket trapping all the warmth!','Venus: The hottest planet on average because of its dense atmosphere and strong greenhouse effect.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_024','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'What are the four ''inner planets'' (Mercury, Venus, Earth, Mars) made of compared to the ''outer planets''?','["They are all made of gas.","The inner planets are rocky, solid worlds, while the outer planets are giant balls of gas or ice.","The inner planets are made of ice, the outer planets are rocky.","They are all exactly the same composition."]',1,'You can land a spaceship on Mars, but you can''t land on Jupiter because it has no solid surface!','The four inner planets are rocky worlds, while Jupiter and Saturn are gas giants and Uranus and Neptune are ice giants.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_025','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'How do ''artificial satellites'' help us in our everyday lives?','["They create the gravity that keeps us on Earth.","They transmit television and internet signals (communication), help us navigate using GPS, and monitor the weather.","They block the Sun to keep the Earth cool.","They provide light during the night."]',1,'When you use a maps app on a phone, a satellite in space is telling the phone where it is!','Artificial satellites have many useful purposes: Communication... Weather forecasting... Navigation...','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_026','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'How does Earth''s ''axial tilt'' cause Summer in the Northern Hemisphere?','["The Earth moves much closer to the Sun during the Summer.","The Northern half of the Earth is tilted *toward* the Sun, receiving more direct sunlight and longer days.","The Sun burns much hotter during the Summer.","The Earth stops spinning during the Summer."]',1,'When you tilt toward the campfire, your face gets hotter!','Summer: A hemisphere tilts toward the Sun. Days are generally longer, and sunlight is more direct... Earth''s axial tilt is the main reason for the seasons.','2026-11-01 07:57:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_027','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'When it is Summer in the Northern Hemisphere, what season is it in the Southern Hemisphere?','["Also Summer","Winter","Spring","Autumn"]',1,'Because one half is tilted toward the Sun, the other half must be tilted away!','When the Northern Hemisphere experiences summer, the Southern Hemisphere generally experiences winter, and vice versa.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_028','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Why do drawings of the Solar System in books often look unrealistic compared to real space?','["Because books use the wrong colors.","Books often exaggerate the sizes of the planets and draw them much closer together so they fit on the page; in reality, space is enormous and mostly empty.","Because books include fake planets.","Because planets constantly change size."]',1,'If a book drew the Solar System to scale, the planets would be microscopic dots separated by huge blank pages!','The drawings of the Solar System often exaggerate planet sizes and bring the planets closer together so they can fit on a page. In reality, space between the planets is enormous.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_029','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'What does a ''telescope'' or ''robotic rover'' allow space scientists to do?','["It allows them to physically travel to other galaxies in seconds.","It allows them to observe and study distant planets and stars that are too far, dangerous, or difficult for humans to visit in person.","It allows them to change the weather on Earth.","It creates new stars in the sky."]',1,'A rover is like a remote-control scientist driving around on Mars!','Space exploration also uses telescopes, robotic spacecraft, landers, rovers... These tools allow scientists to study places that would otherwise be difficult or impossible to visit.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_030','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',5,'Does the Moon''s gravity affect the Earth?','["No, the Moon is too small to have gravity.","Yes, the Moon''s gravity pulls on the Earth, contributing significantly to the ocean tides.","No, gravity only goes from Earth to the Moon.","Yes, it pulls all the air off the Earth."]',1,'The Moon''s pull literally lifts the water in the oceans up and down every day!','The Moon''s gravity contributes to Earth''s ocean tides, together with the Sun''s influence.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_031','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Critique the common misconception that ''Summer occurs because the Earth is closer to the Sun in its orbit.''','["The misconception is entirely true and mathematically verified.","This is a widespread fallacy. Earth''s orbit is elliptical, but the distance change is negligible regarding seasons (in fact, Earth is closest to the Sun in January). Seasons are driven strictly by the 23.5-degree axial tilt altering the angle of incidence of solar radiation.","Summer occurs because the Sun expands in size.","Summer occurs because the Earth rotates faster."]',1,'If closeness caused Summer, the whole planet would have Summer at the exact same time!','A common misconception: Seasons are not mainly caused by Earth moving closer to or farther from the Sun. Earth''s axial tilt is the main reason for the seasons.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_032','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Analyze the specific thermonuclear reaction that allows the Sun to generate energy.','["The Sun generates energy by burning fossil fuels like coal.","The Sun generates energy via nuclear fusion. Deep in its core, extreme gravitational pressure and heat force hydrogen atomic nuclei to fuse into heavier helium nuclei. This fusion process releases a massive amount of radiant and thermal energy.","The Sun generates energy by reflecting light from other stars.","The Sun generates energy through a massive electrical short circuit."]',1,'It isn''t a ''fire''; it is a continuous nuclear reaction smashing atoms together!','The Sun is a star... a huge ball of very hot gas, mainly hydrogen and helium, that releases energy through nuclear fusion.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_033','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Synthesize how the concept of ''Mass'' versus ''Weight'' applies to an astronaut travelling from Earth to the Moon.','["Both mass and weight decrease to zero in space.","Mass is the invariant scalar quantity of matter in the astronaut''s body, which remains identical on Earth and the Moon. Weight is the variable vector force of gravity acting on that mass (\\\\(W=mg\\\\)); because the Moon has 1/6th of Earth''s gravity, the astronaut''s weight drops drastically, but their mass is unchanged.","Mass drops drastically, but weight remains the same.","Both mass and weight increase on the Moon."]',1,'You are still made of the exact same amount of ''stuff'' (mass), but the Moon pulls on that ''stuff'' much less (weight)!','An object''s weight depends on the gravitational force acting on it. Its mass—the amount of matter it contains—does not change simply because it travels to another planet.','2026-11-01 07:57:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_034','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Evaluate the physical mechanics of ''Free-fall'' that creates the illusion of ''zero gravity'' on the International Space Station.','["The ISS uses anti-gravity machines to repel Earth.","Gravity at the altitude of the ISS is about 90% as strong as on Earth''s surface. However, the ISS has immense forward (tangential) velocity. As gravity pulls it down, its forward speed causes it to constantly ''miss'' the Earth, resulting in a perpetual state of free-fall for the station and the astronauts inside.","The ISS is too far away for gravity to reach it.","The ISS is filled with water to make the astronauts float."]',1,'If you drop an elevator, you feel weightless inside it; the ISS is basically an elevator falling forever around the curve of the Earth!','Gravity acts throughout space... The spacecraft and the astronauts are both falling around Earth together. This continuous free-fall creates the feeling of weightlessness.','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_035','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Analyze why the ''New Moon'' phase is essentially invisible from Earth.','["The Moon physically shrinks until it disappears.","During the New Moon phase, the Moon is positioned between the Earth and the Sun. Consequently, the hemisphere of the Moon illuminated by solar radiation faces entirely away from Earth, while the unilluminated (dark) hemisphere faces us, rendering it visually indistinguishable against the dark sky.","The Earth''s shadow completely blocks the Sun.","The Moon travels behind the Sun."]',1,'You are looking at the dark back-side of the Moon!','New Moon: The side illuminated by the Sun mostly faces away from Earth, so the Moon is difficult to see.','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_036','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Synthesize the climatic difference between the ''Equator'' and the ''Poles'' based on Earth''s spherical geometry and axial tilt.','["The equator is hotter because it is physically thousands of miles closer to the Sun.","Because Earth is a sphere, solar radiation strikes the equator directly (high angle of incidence), concentrating the thermal energy into a small area. At the poles, the curvature of the Earth forces the same amount of solar radiation to spread out over a much larger surface area, drastically reducing its heating efficiency.","The poles are colder because they are made of solid ice that reflects heat.","The equator is hotter because it spins faster."]',1,'Direct sunlight is like a focused magnifying glass; angled sunlight at the poles is weak and spread out!','Summer [or Direct Sunlight]... Days are generally longer, and sunlight is more direct... Season names and their timing depend on location. Places near the equator may have wet and dry seasons rather than four distinct temperature-based seasons.','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_037','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Evaluate the significance of ''Greenhouse Gases'' on Venus compared to Earth.','["Venus has no greenhouse gases, making it cold.","Venus possesses a hyper-dense atmosphere composed primarily of \\\\(CO_2\\\\). This triggers a runaway greenhouse effect; high-frequency solar radiation penetrates the atmosphere, but the re-radiated low-frequency infrared thermal energy is trapped, escalating the surface temperature beyond that of Mercury, despite Venus being further from the Sun.","Earth has a stronger greenhouse effect than Venus.","Greenhouse gases on Venus actually cool the planet down."]',1,'Venus is a cautionary tale of what happens when an atmosphere traps too much heat!','Venus: The hottest planet on average because of its dense atmosphere and strong greenhouse effect.','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_038','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Critique the use of ''Artificial Satellites'' in low Earth orbit from a long-term sustainability perspective (Space Debris).','["Satellites instantly dissolve when they stop working, causing no issues.","While satellites provide critical communication and meteorological data, the unchecked proliferation of these devices creates a severe orbital hazard. Defunct satellites and debris create a high-velocity debris field (Kessler Syndrome) that threatens the integrity of future space exploration and current operational satellites.","Satellites provide no useful data and are a waste of money.","Satellites actually clean up the atmosphere by absorbing pollution."]',1,'Space is big, but the specific orbits around Earth are getting crowded with broken robot trash!','Artificial satellites have many useful purposes... (Synthesis: However, launching thousands of metal machines into orbit creates a massive traffic/trash problem when they break).','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_039','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Analyze the distinction between ''Gas Giants'' (Jupiter/Saturn) and ''Ice Giants'' (Uranus/Neptune).','["They are exactly identical in every physical aspect.","While both lack a solid rocky surface, Gas Giants are composed almost entirely of hydrogen and helium gas/liquid. Ice Giants contain a much higher percentage of heavier elements (like oxygen, carbon, nitrogen) compacted into supercritical ''ices'' (water, ammonia, methane) beneath their gaseous envelopes.","Gas giants are hot, Ice giants are frozen solid rock.","Ice giants are made entirely of frozen \\\\(H_2O\\\\) water."]',1,'They are both huge planets without a solid surface to stand on, but they are made of different chemical recipes!','Jupiter and Saturn are gas giants and Uranus and Neptune are ice giants.','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_040','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Synthesize how the ''Orbital Period'' (length of a year) changes for planets further from the Sun.','["All planets take exactly 365 days to orbit the Sun.","According to Kepler''s Laws of Planetary Motion, as the orbital radius (distance from the Sun) increases, the circumference of the orbit increases and the gravitational pull weakens, resulting in a slower orbital velocity. Therefore, planets further from the Sun have exponentially longer ''years'' than Earth.","Planets further away orbit much faster.","Orbital period is determined solely by the size of the planet."]',1,'Neptune is so far away that one ''Neptune Year'' takes 165 Earth years to finish!','Earth takes approximately 365.25 days to complete one orbit... (Synthesis: A larger orbit takes longer to complete).','2026-11-01 07:57:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_041','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Evaluate the physical mechanics of a ''Lunar Eclipse''.','["The Moon passes in front of the Sun, blocking its light from Earth.","A lunar eclipse occurs during a Full Moon phase when the Earth perfectly aligns between the Sun and the Moon. The Earth''s physical mass blocks the solar radiation, casting a massive, opaque shadow (umbra) across the lunar surface.","The Moon simply turns off its light for a few hours.","The Sun travels behind the Moon."]',1,'The Earth gets in the way and casts a shadow on the Moon!','Earth''s shadow causes a lunar eclipse, which is a different event [from normal phases].','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_042','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Critique the assertion that the Sun is ''burning'' in space.','["The Sun is burning oxygen just like a campfire on Earth.","The assertion is a chemical fallacy. ''Burning'' is a chemical combustion reaction requiring oxygen. Space is a vacuum devoid of oxygen. The Sun generates energy through nuclear fusion (combining atomic nuclei), a process entirely distinct from and infinitely more powerful than chemical combustion.","The Sun is burning because it is made of coal.","The Sun doesn''t actually produce heat; it just reflects heat from other galaxies."]',1,'Fire needs oxygen; the Sun doesn''t use oxygen, it smashes atoms together!','The Sun is a star... a huge ball of very hot gas, mainly hydrogen and helium, that releases energy through nuclear fusion.','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_043','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Analyze how the ''Tides'' demonstrate the gravitational interplay between the Earth, Moon, and Sun.','["Tides are caused by whales pushing the water.","The gravitational fields of the Moon (primarily) and the Sun exert a differential pulling force on the Earth. This force physically stretches the Earth''s oceans into an ellipsoid shape, creating ''bulges'' of water. As Earth rotates through these stationary bulges, coastlines experience alternating high and low tides.","Tides are caused by the wind blowing the ocean.","Tides only happen when the Moon falls into the ocean."]',1,'The Moon''s gravity is literally pulling the water of the ocean toward itself!','The Moon''s gravity contributes to Earth''s ocean tides, together with the Sun''s influence.','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_044','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Synthesize why the Moon is ''tidally locked'' to the Earth, meaning we only ever see one side of it.','["The Moon does not rotate on its axis at all.","Over billions of years, Earth''s massive gravitational pull has created tidal friction on the Moon''s crust, slowing its rotation. It is now in synchronous rotation, meaning the Moon takes the exact same amount of time to rotate on its axis as it does to revolve around the Earth, keeping one face permanently pointed at us.","The back side of the Moon is too dark to see.","The Earth''s shadow permanently covers the back side of the Moon."]',1,'It spins exactly once every time it circles the Earth, so the same side is always facing us!','The Moon... travels around Earth... (Synthesis: We only see the ''Earth-facing side'' because its rotation matches its orbit).','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_space_global_045','Physics','Earth, Moon and Space','Topic 13: Earth, Moon and Space Physics','Primary',10,'Evaluate the importance of ''Photosynthesis'' as a biological energy transducer connecting the Sun to Earth''s ecosystems.','["Photosynthesis creates new energy out of dirt.","Photosynthesis is the foundational biochemical bridge for life. Biological organisms (plants) act as transducers, capturing incoming electromagnetic radiation (solar energy) and converting it into stored, usable chemical energy (glucose). This process forms the base of the entire planetary food web.","Photosynthesis uses moonlight to create water.","Photosynthesis proves that plants do not need the Sun."]',1,'Plants are organic solar panels that turn sunlight into food for the rest of the planet!','This energy: ... Helps plants make food through photosynthesis.','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_001','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What is an ''energy resource''?','["A type of battery","A source from which people obtain useful energy","A light switch","A machine that uses electricity"]',1,'It is where we get the power to run our homes and cities.','An energy resource is a source from which people obtain useful energy.','2026-11-01 07:57:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_002','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What does it mean if an energy resource is ''renewable''?','["It can only be used once and then it is gone forever.","It is naturally replenished (replaced) on a human timescale.","It is always dangerous to use.","It produces the most pollution."]',1,'Nature keeps making more of it, so we don''t run out!','Renewable resources are naturally replenished on a human timescale. Examples include sunlight, wind...','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_003','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these is an example of a ''renewable'' energy resource?','["Coal","Natural Gas","Wind","Oil"]',2,'The wind never stops blowing forever.','Renewable resources are naturally replenished... Examples include sunlight, wind, flowing water...','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_004','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What does it mean if an energy resource is ''non-renewable''?','["It is finite or replenished far too slowly to replace what people use.","It can be used over and over again forever.","It is entirely free to use.","It comes from the sun."]',0,'Once we use it all up, it is gone!','Non-renewable resources are finite or are replenished far too slowly to replace what people use.','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_005','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these is an example of a ''non-renewable'' energy resource (a fossil fuel)?','["Sunlight","Coal","Flowing water","Geothermal heat"]',1,'It takes millions of years for the Earth to make more coal.','Non-renewable energy... Examples include coal, oil, natural gas...','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_006','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What does a ''solar photovoltaic (PV) panel'' do?','["It burns coal to make electricity.","It converts sunlight directly into electricity.","It uses wind to spin a turbine.","It turns water into ice."]',1,'You see these flat panels on the roofs of houses.','Solar photovoltaic (PV) panels: Convert light directly into electricity.','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_007','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What turns the blades of a ''wind turbine''?','["A giant motor","Moving air (wind)","Flowing water","Electricity"]',1,'It works like a giant pinwheel.','A wind turbine''s blades rotate when wind flows over them.','2026-11-01 07:57:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_008','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What is used to generate electricity in a ''hydroelectric'' power station?','["Burning oil","Moving or falling water","Sunlight","Wind"]',1,'These are often built inside giant dams on rivers.','Hydroelectric power generates electricity using moving or falling water.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_009','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What is a major disadvantage of burning fossil fuels (like coal and oil)?','["They release carbon dioxide, a greenhouse gas that contributes to global warming.","They produce too much oxygen.","They stop the wind from blowing.","They make the sun shine too brightly."]',0,'The smoke and gases act like a blanket, trapping heat on Earth.','Burning fossil fuels releases carbon dioxide, a greenhouse gas that contributes to global warming.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_010','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What is the job of a ''generator'' in a power station?','["To burn the coal","To convert mechanical energy (spinning) into electrical energy","To hold the water in a dam","To clean the solar panels"]',1,'It turns the physical spinning motion into electricity that can go into wires.','The generator converts mechanical energy into electrical energy.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_011','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What is the job of a ''turbine'' in a power station?','["To catch the electricity","A rotating machine driven by a moving fluid (like air, water, or steam) that spins the generator","To store the coal","To measure the temperature"]',1,'It is the giant fan blade that gets pushed to spin.','Turbine: A rotating machine driven by a moving fluid, such as air, water or steam.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_012','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What does ''energy conservation'' mean?','["Using as much energy as possible","Reducing unnecessary energy use and avoiding waste","Building more power stations","Throwing away old batteries"]',1,'It means turning off the lights when you leave a room!','Energy conservation means reducing unnecessary energy use.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_013','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What does ''energy efficiency'' mean?','["Using more energy to do a worse job","Getting a useful result (doing the same task) while using less energy","Never turning on the TV","Using only coal for power"]',1,'An efficient lightbulb makes the same amount of light, but uses half the electricity.','Energy efficiency means getting a useful result while using less energy.','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_014','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these is a good way to save energy at home?','["Leave the refrigerator door open while you eat.","Leave the TV on when you go to school.","Switch off lights when a room is empty.","Turn the heater to maximum and open the windows."]',2,'Don''t waste electricity if no one is using it!','Practical actions include: Switch off lights when a room is empty. Turn off televisions...','2026-11-01 07:57:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_015','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',1,'What are fossil fuels (like coal and oil) made from?','["Rocks that melted in the sun","The remains of ancient organisms (plants and animals) over millions of years","Water that froze underground","Clouds that fell to Earth"]',1,'They are literally made from ancient, squished dinosaurs and plants!','Fossil fuels formed from the remains of ancient organisms over millions of years.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_016','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why are fossil fuels (coal, oil, natural gas) considered ''non-renewable'' even though the Earth technically still makes them?','["Because they are illegal to dig up.","Because they take millions of years to form, meaning they are replenished far too slowly to replace the massive amounts people consume every day.","Because they are actually made of plastic.","Because they instantly evaporate when they touch the air."]',1,'We are burning them a million times faster than the Earth can make new ones!','Non-renewable resources are finite or are replenished far too slowly to replace what people use... Fossil fuels contain stored chemical energy, but they take millions of years to form.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_017','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'How does a typical coal power station generate electricity?','["The coal is squeezed until electricity drops out.","Burning the coal creates heat, which boils water to produce high-pressure steam. The steam spins a turbine, which turns a generator to create electricity.","The coal absorbs sunlight and turns it into electricity.","The coal is thrown into a river to make water flow faster."]',1,'You burn the rock to make steam, and the steam spins the giant fan!','In many power stations, this heat produces steam that turns a turbine connected to a generator... Fossil-fuel power: Burning fuel heats water to produce steam, which turns the turbine.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_018','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why is ''wind energy'' sometimes unreliable as a sole source of electricity for a city?','["Because wind turbines are invisible.","Because wind speed varies unpredictably; if the wind stops blowing, the turbines stop spinning and electricity output drops.","Because the wind always blows in the wrong direction.","Because wind energy is a non-renewable resource."]',1,'If it is a calm, still day, the windmills won''t turn!','Limitations [of wind energy]: Wind speed varies, so electricity output changes... Batteries or other electricity sources may be needed...','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_019','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'How does a ''hydroelectric'' dam generate electricity?','["It burns water to create heat.","Water stored at a higher level flows down through pipes, and the force of the moving water physically spins a turbine connected to a generator.","It uses solar panels floating on the lake.","It catches lightning strikes over the water."]',1,'The heavy water falls through the dam and pushes the giant fan blades!','Water is stored at a higher level. Water flows through channels or pipes. Moving water turns a turbine. The turbine drives a generator.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_020','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'What is a major ''limitation'' or environmental disadvantage of building a large hydroelectric dam?','["They release massive amounts of carbon dioxide smoke.","Reservoirs can flood large areas of land, displace human communities, and alter natural river ecosystems and fish migration.","They rely on fossil fuels to operate.","They can only operate at night."]',1,'To build a dam, you have to flood a whole valley, which destroys the habitats there.','Limitations: Dams may alter river ecosystems and fish migration. Reservoirs can flood land and displace communities.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_021','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why do solar panels have a limitation regarding ''when'' they can provide electricity?','["They only work when it is raining.","Solar panels require sunlight, meaning they generate significantly less or no electricity at night or during heavy cloud cover.","They only work during the winter.","They only work when the wind is blowing."]',1,'No sun, no power (unless you have a battery to store it)!','Limitations: Solar panels generate less electricity at night. Clouds and shading can reduce their output.','2026-11-01 07:57:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_022','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'What is the difference between a ''Solar PV (Photovoltaic) panel'' and a ''Solar thermal system''?','["There is no difference; they are two names for the same thing.","A PV panel converts sunlight directly into electricity, while a thermal system uses the sunlight''s heat to warm up water or another material.","A PV panel is used at night, while a thermal system is used during the day.","A PV panel creates wind, while a thermal system creates gravity."]',1,'One makes electricity for your TV; the other makes hot water for your shower!','Solar photovoltaic (PV) panels: Convert light directly into electricity. Solar thermal systems: Use sunlight to heat water or another material.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_023','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'How does switching from old incandescent lightbulbs to ''LED bulbs'' demonstrate ''energy efficiency''?','["LED bulbs are much heavier than old bulbs.","LED bulbs provide the same amount of useful light but use significantly less electrical energy to do it, because they waste less energy as heat.","LED bulbs use more energy but change colors.","LED bulbs are powered by tiny lumps of coal."]',1,'It''s the same brightness, but a much cheaper electricity bill!','Energy efficiency means getting a useful result while using less energy. For example, an efficient light bulb produces the required light using less electrical energy than an inefficient bulb.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_024','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why is ''electricity'' described as an ''energy carrier'' rather than a ''primary energy resource''?','["Because electricity is actually a solid object you can carry in a box.","Because electricity does not exist naturally in a form we can mine or harvest; we must always use a primary resource (like coal, wind, or solar) to generate the electricity first.","Because electricity can only travel through water.","Because electricity is lighter than air."]',1,'You can''t dig a hole and find a puddle of electricity; you have to burn coal or catch wind to make it!','Electricity is an energy carrier, not a primary energy resource. It must be generated using another energy source or by converting stored energy.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_025','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why does the lesson state that ''Renewable does not automatically mean impact-free''?','["Because renewable energy is actually fake.","Even renewable sources require building infrastructure (like giant dams or mining materials for solar panels), which can still disrupt local wildlife, alter landscapes, and create manufacturing waste.","Because renewable energy creates massive amounts of greenhouse gases.","Because renewable energy always runs out quickly."]',1,'Windmills are clean, but you still have to dig up metal to build the giant metal towers!','Renewable does not automatically mean impact-free. For example, dams can affect rivers and wildlife, and manufacturing solar panels and wind turbines requires materials and energy.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_026','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'If you want to perform a ''classroom energy audit'', what should you be looking for?','["Looking for gold hidden in the walls.","Looking for instances of wasted energy, such as empty rooms with the lights left on, or devices running when nobody is using them, so you can suggest improvements.","Looking for the largest window in the school.","Looking to see how loud the students are."]',1,'An audit is an inspection to find where you are wasting power!','A simple classroom energy audit: Learners can work in groups to record: How many lights are on in an empty room. Which devices are running unnecessarily.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_027','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'How do ''greenhouse gases'' released by fossil fuels affect the Earth''s climate?','["They freeze the oceans solid.","They act like a blanket in the atmosphere, trapping additional thermal energy (heat) in Earth''s climate system and causing global warming.","They destroy the Sun.","They turn the sky green."]',1,'The gases let the sun''s heat in, but won''t let it escape back into space!','Greenhouse gases from fossil fuels trap additional heat in Earth''s climate system.','2026-11-01 07:57:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_028','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'Why might a city need large battery storage systems if they rely entirely on solar and wind power?','["To make the city look futuristic.","Because solar and wind are intermittent (sun doesn''t shine at night, wind doesn''t always blow); batteries store the excess energy generated during good conditions to be used when conditions are poor.","To make the wind blow harder.","To burn the batteries for heat."]',1,'You have to save the daytime sunshine in a battery so you can turn on your lights at night!','Limitations [of solar]: ... Batteries or other electricity sources may be needed when sunlight is unavailable. A sustainable energy system combines... energy storage where needed...','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_029','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'How does using ''daylight when it is practical'' relate to energy conservation?','["It stops the sun from shining too brightly.","By opening curtains to use natural sunlight to illuminate a room, you eliminate the need to turn on electric lamps, thus conserving electrical energy.","It turns the windows into solar panels.","It creates wind inside the classroom."]',1,'If the sun is bright enough, you don''t need to waste electricity turning on the ceiling lights!','Practical actions include: ... Use daylight when it is sufficient... Energy conservation means reducing unnecessary energy use.','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_030','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',5,'What is a ''transformer'' used for in the context of an electrical power station (based on the diagram)?','["To turn the generator into a car.","To alter the voltage of the electricity so it can travel efficiently through long power lines to homes and businesses.","To burn the coal.","To create the wind."]',1,'It steps up the power so it can travel miles down the highway wires!','Electricity travels through power lines to homes, schools and businesses. (Implied by the diagram showing the transformer connecting the generator to the power lines).','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_031','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the assertion that transitioning to 100% renewable energy immediately eliminates all environmental degradation.','["The assertion is perfectly true; renewable energy has zero physical footprint.","The assertion is a fallacy. While renewables drastically reduce greenhouse gas emissions, manufacturing solar PV arrays and neodymium magnets for wind turbines requires intensive, destructive mining of rare-earth metals. Furthermore, end-of-life recycling for massive fiberglass turbine blades poses severe landfill challenges.","The assertion is false because renewable energy produces more carbon dioxide than coal.","The assertion is true because renewable energy is imaginary."]',1,'You still have to dig giant strip mines to get the lithium and silver needed to build ''green'' technology!','Renewable does not automatically mean impact-free... manufacturing solar panels and wind turbines requires materials and energy... Resource use: Building power stations... requires land, minerals, water... Waste: Some energy technologies produce waste that must be safely managed.','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_032','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the thermodynamic inefficiency inherent in a ''Fossil-Fuel Power Station''.','["Fossil fuel stations are 100% perfectly efficient.","A massive percentage of the stored chemical energy in coal/oil is lost as waste heat to the environment during combustion, and further mechanical energy is lost to friction in the turbine and generator. Only a fraction of the original chemical potential is actually converted into usable electrical current.","Fossil fuel stations actually create more energy than they consume.","Fossil fuel stations only lose energy through sound waves."]',1,'Most of the energy in the coal just escapes up the smokestack as useless heat!','Energy efficiency: Obtaining a useful result while using less energy... (Synthesis: Burning fuel to boil water to spin a turbine is a multi-step process with massive thermal and friction losses at every step).','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_033','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize how ''Pumped-Storage Hydroelectricity'' acts as a massive mechanical battery for the electrical grid.','["It stores electricity by freezing water into solid ice blocks.","During periods of low electricity demand (and cheap power), excess grid electricity is used to pump water uphill into a reservoir. During peak demand, that water is released to flow downhill through turbines, converting the stored gravitational potential energy back into electricity.","It uses water to cool down nuclear reactors.","It stores electricity by mixing it with chemicals in the water."]',1,'It uses extra electricity to push water up a mountain, so it can fall back down and make electricity when you need it later!','Some hydroelectric systems use flowing rivers... while pumped-storage systems move water between different elevations to store energy.','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_034','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the geopolitical and economic implications of ''Non-renewable resource depletion''.','["Depletion will have no effect because humans don''t need energy.","Because fossil fuels are geographically concentrated and finite, their depletion will cause severe scarcity, escalating global energy costs and triggering geopolitical conflict over remaining reserves, forcing a mandatory, rapid transition to alternative localized energy infrastructure.","Depletion means countries will simply start burning rocks instead.","Depletion proves that non-renewable resources are actually renewable."]',1,'If the whole world runs on oil, and the oil runs out, the countries that control the last drops hold all the power!','Non-renewable energy... These resources can become depleted as they are consumed... Choosing energy sources involves considering reliability, cost, land use... and the needs of local communities.','2026-11-01 07:57:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_035','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the mechanical transition in a ''Wind Turbine'' from fluid dynamics to electromagnetism.','["The wind blows the electricity directly into the wires.","The kinetic energy of the fluid (wind) applies aerodynamic lift and drag to the turbine blades, converting fluid motion into rotational mechanical energy. This spins the rotor of the generator, where electromagnetic induction converts the mechanical rotation into an electrical current.","The wind turbine uses a giant battery to spin the blades, creating wind.","The wind turbine burns the air to create heat energy."]',1,'Wind pushes the blade (kinetic), the blade spins a magnet inside a coil of wire (mechanical), which pushes electrons (electrical)!','Wind energy uses moving air to produce useful energy. A wind turbine''s blades rotate when wind flows over them. The rotating system drives a generator that produces electricity.','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_036','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the concept of ''Intermittency'' as the primary engineering hurdle for Solar and Wind power grids.','["Intermittency means solar panels get too hot and melt.","Solar (diurnal cycle/clouds) and wind (weather patterns) are intermittent, meaning their energy production does not reliably match human energy consumption curves. This necessitates the development of massive grid-scale energy storage (batteries/pumped hydro) or ''baseload'' backups (nuclear/fossil) to prevent grid blackouts.","Intermittency proves that wind and solar are completely useless.","Intermittency means that solar panels only work in the rain."]',1,'People want to turn their lights on at 8 PM, but the sun is already down! You have to bridge that gap.','Limitations [of renewables]: Solar panels generate less electricity at night. Clouds and shading can reduce their output. Wind speed varies, so electricity output changes... Batteries or other electricity sources may be needed...','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_037','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the use of ''Biomass'' (burning wood/plants) as a perfectly ''Carbon Neutral'' renewable energy source.','["Biomass is perfectly carbon neutral and has no emissions.","While biomass is technically renewable (plants regrow and absorb \\\\(CO_2\\\\)), burning it releases massive amounts of \\\\(CO_2\\\\) and particulate pollution instantaneously. If the replanting and regrowth cycle takes decades (e.g., harvesting old-growth forests), it acts as a net-carbon emitter in the critical short term, exacerbating climate change.","Biomass actually absorbs carbon dioxide while it is burning.","Biomass is a non-renewable fossil fuel."]',1,'Burning a 100-year-old tree releases a century of stored carbon in one hour; planting a sapling won''t recapture that carbon for another 100 years!','Common energy resources include: ... Biomass, such as wood and plant material... Renewable resources are naturally replenished on a human timescale... Renewable does not automatically mean impact-free.','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_038','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the physical difference in energy generation between ''Nuclear Power'' and ''Fossil Fuels''.','["Nuclear power burns radioactive coal to make smoke.","Fossil fuels release energy through chemical combustion (breaking molecular bonds). Nuclear power releases energy through nuclear fission (splitting the heavy atomic nuclei of uranium). Fission produces millions of times more thermal energy per unit of mass than combustion, without releasing greenhouse gases, though it creates radioactive waste.","Nuclear power uses wind to spin the uranium.","There is no difference; they both burn liquids."]',1,'You don''t set uranium on fire; you split its atoms apart to create massive amounts of heat!','Fossil fuels... When fossil fuels burn, they release energy as heat... Nuclear power: Energy released from nuclear reactions heats water in many conventional nuclear stations. (Synthesis: Nuclear uses atomic reactions, not chemical burning).','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_039','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze how the ''Greenhouse Effect'' is a physical disruption of Earth''s thermal equilibrium.','["The greenhouse effect freezes the Earth by blocking all sunlight.","Earth maintains equilibrium by radiating infrared thermal energy back into space. Greenhouse gases (like \\\\(CO_2\\\\) from fossil fuels) are transparent to incoming high-energy solar radiation but opaque to outgoing low-energy infrared radiation. By trapping this outgoing heat, they disrupt the equilibrium, forcing the global average temperature to rise.","The greenhouse effect destroys the ozone layer.","The greenhouse effect means plants grow too fast and cover the Earth."]',1,'The gases act like a one-way mirror: sunlight gets in easily, but the resulting heat can''t get back out!','Climate change: Greenhouse gases from fossil fuels trap additional heat in Earth''s climate system.','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_040','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the concept of a ''Sustainable Energy System'' as described in the text.','["A sustainable system relies entirely on burning coal as fast as possible.","A truly sustainable system is multifaceted. It cannot rely on a single technology; it requires a diversified grid of renewable resources (solar/wind/hydro), advanced energy storage to handle intermittency, hyper-efficient end-user appliances to reduce total demand, and responsible lifecycle management of materials and waste.","A sustainable system means humans must stop using all electricity immediately.","A sustainable system only uses nuclear power."]',1,'There is no ''silver bullet'' to fix the energy crisis; we have to use a smart combination of everything!','A sustainable energy system combines suitable energy resources, efficient equipment, energy storage where needed, reliable electricity networks and reduced waste.','2026-11-01 07:58:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_041','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the Jevons Paradox in the context of ''Energy Efficiency''.','["Energy efficiency always results in 100% less energy being used.","The Jevons Paradox observes that as technological efficiency increases (e.g., cheaper, more efficient LED lights), the relative cost of using that resource drops, which can paradoxically induce higher overall consumption (e.g., people leaving the efficient lights on all night), negating the intended conservation gains.","Energy efficiency physically destroys the power grid.","Energy efficiency means appliances break faster."]',1,'If a car gets double the gas mileage, people often choose to drive twice as far, so they don''t actually save any gas!','Energy efficiency means getting a useful result while using less energy... Energy conservation means reducing unnecessary energy use. (Synthesis: Efficiency lowers cost, which can discourage behavioral conservation).','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_042','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the viability of ''Geothermal Heat'' as a globally scalable baseline energy resource.','["Geothermal heat can easily be used in every single city on Earth.","While geothermal is a highly reliable, continuous renewable resource (unlike intermittent solar/wind), it is geographically highly restricted. Economically viable geothermal gradients (magma near the crust) are generally only found along active tectonic plate boundaries or volcanic hotspots, limiting its global scalability.","Geothermal heat comes from the sun, so it is available everywhere.","Geothermal heat is actually a non-renewable fossil fuel."]',1,'You can only build a geothermal plant where the Earth''s crust is thin and hot; you can''t just build one anywhere!','Common energy resources include: ... Geothermal heat from inside Earth... Choosing energy sources involves considering reliability, cost, land use... and local conditions.','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_043','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the statement: ''Electricity is an energy carrier, not a primary energy resource.''','["This means electricity is carried in buckets.","Primary resources (coal, wind, uranium) possess raw potential energy inherent in nature. Electricity is a synthesized, intermediate vector—a highly organized flow of electrons generated by converting a primary resource. It exists solely to transport that energy efficiently across vast distances to an end-user device.","This means electricity is a primary resource found in mines.","This means electricity is actually a fossil fuel."]',1,'You don''t ''mine'' electricity; you use a primary fuel to ''make'' it so you can send it down a wire!','Electricity is an energy carrier, not a primary energy resource. It must be generated using another energy source or by converting stored energy.','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_044','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the ecological impact of ''Hydroelectric Reservoirs'' on downstream sediment transport.','["Reservoirs make the downstream rivers much healthier and cleaner.","A dam physically halts the natural hydrological flow. While it generates clean power, the reservoir traps nutrient-rich silt and sediment behind the dam wall. This starves the downstream river deltas of critical structural material and agricultural nutrients, leading to severe coastal erosion and ecosystem collapse.","Reservoirs actually push more dirt into the downstream rivers.","Reservoirs have absolutely no effect on river ecosystems."]',1,'The dam stops the water from carrying natural dirt and nutrients downstream, starving the lands below the dam!','Limitations: Dams may alter river ecosystems and fish migration. Reservoirs can flood land and displace communities... Renewable does not automatically mean impact-free.','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_energyres_global_045','Physics','Energy Resources','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the physical challenge of ''Energy Storage'' when replacing fossil fuels with renewables.','["Renewable energy can easily be stored in cardboard boxes.","Fossil fuels are inherently stable, high-density chemical storage mediums that can be stockpiled and burned on demand (dispatchable). Renewable electricity must be consumed the instant it is generated unless stored. Current battery technology is expensive and lacks the massive energy density required to stockpile months of municipal power.","Fossil fuels cannot be stored, while wind energy is easily stored.","Energy storage is completely unnecessary for any power grid."]',1,'A pile of coal is nature''s battery; replacing that with giant chemical batteries for a whole city is incredibly difficult and expensive!','Fossil fuels... can provide energy when sunlight or wind is unavailable. Fuels can often be stored and transported... A sustainable energy system combines... energy storage where needed...','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_001','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What does ''physics'' help explain in our everyday lives?','["Only things in outer space","How bicycles move, why balls bounce, and how phones work","Only how to read books","Only how plants grow"]',1,'It explains how the world around you works.','Physics is not only something we study in textbooks. It explains how bicycles move, why balls bounce, how phones produce sound...','2026-11-01 07:58:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_002','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What is ''engineering''?','["Applying scientific knowledge and creativity to solve practical problems","Writing a fictional story","Painting a picture of a bridge","Guessing how things work without testing them"]',1,'Engineers design and build things to help people.','Engineering uses scientific knowledge, creativity and testing to solve practical problems.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_003','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What energy transformation happens in an electric fan?','["It turns light into heat.","An electric motor converts electrical energy into movement (kinetic energy).","It turns movement into a battery.","It turns sound into electricity."]',1,'You plug it in, and the blades spin!','Electric fans: An electric motor converts electrical energy into movement.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_004','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'How do bicycle brakes work?','["They use magnetism to stop the bike.","They use friction to rub against the wheel and slow it down.","They use gravity to pull the bike backward.","They use wind to blow the bike away."]',1,'The brake pads rub against the metal wheel to stop it.','Bicycles... brakes use friction to slow it down.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_005','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What physics force pulls a basketball downward after you throw it?','["Magnetism","Air resistance","Gravity","Friction"]',2,'Gravity is what makes the ball fall through the hoop!','Basketball: The ball follows a curved path as gravity pulls it downward.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_006','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What does a ''microphone'' do?','["It converts sound vibrations into electrical signals.","It converts electrical signals into sound.","It creates light waves.","It makes the room completely silent."]',0,'It catches your voice and turns it into an electrical code.','Microphones: Convert sound vibrations into electrical signals.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_007','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What does a ''speaker'' or ''headphone'' do?','["It turns light into sound.","It uses electrical signals to create vibrations that produce sound.","It turns sound into electricity.","It blocks all noise from entering."]',1,'It is the exact opposite of a microphone!','Speakers and headphones: Use electrical signals and magnetic forces to create vibrations that produce sound.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_008','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What is a ''prototype'' in engineering?','["The final, perfect product that is sold in stores","An early, simple version of a design built for testing","A type of battery","A type of bridge"]',1,'It''s like a rough draft of a machine!','Prototype: An early version of a design built for testing.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_009','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What does ''stability'' mean when building a structure like a tower?','["How heavy the tower is","How well the structure resists tipping over or collapsing","What color the tower is painted","How fast the tower can move"]',1,'A stable tower won''t fall down in the wind.','Stability: How well a structure resists tipping or collapsing.','2026-11-01 07:58:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_010','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'Who is famous for achieving a pioneering controlled, powered aeroplane flight in 1903?','["Thomas Edison","The Wright brothers","Alexander Graham Bell","Johannes Gutenberg"]',1,'They flew the first real airplane at Kitty Hawk.','The aeroplane: Orville and Wilbur Wright achieved a pioneering controlled, powered flight in 1903.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_011','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What does a ''thermos flask'' do?','["It makes cold drinks hot.","It reduces heat transfer to help keep drinks hot or cold.","It creates electricity.","It breaks down food."]',1,'It stops the heat from getting in or getting out!','Thermos flasks: Reduce heat transfer to help keep drinks hot or cold.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_012','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'Which shape is often used by engineers to make frameworks (like bridges) strong and rigid?','["A circle","A triangle","A thin flat line","A soft square"]',1,'Triangles are very strong shapes for building.','Shape: Triangles can help make frameworks rigid...','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_013','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'What is the first step in a useful engineering process?','["Build the final product immediately","Identify the problem that needs to be solved","Test the product","Sell the product"]',1,'You have to know what is broken before you can fix it!','A useful engineering process has six steps: 1. Identify the problem. Decide what needs to be improved or created.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_014','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'Why do scientists and engineers ''test'' their designs?','["Because testing is a fun game to play.","To reveal what works, what fails, and what needs to be improved.","Because they want to break everything they build.","Because testing creates electricity."]',1,'Testing shows you how to make the next version better!','A prototype does not need to be perfect. Testing helps reveal what works, what fails and what should be improved.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_015','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',1,'In a science experiment, what are ''variables''?','["The final written conclusion","Factors that can change and affect the result of the experiment","The safety goggles you wear","The table you work on"]',1,'If you are testing ramp height, the height is your changing variable!','Variables: Factors that can change and affect the result of an experiment.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_016','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How does physics explain why it is hard to ride a bicycle on a muddy, slippery road?','["Because mud is a liquid.","Because the mud drastically reduces the necessary ''friction'' between the tyres and the road, making the tyres spin without gripping the surface.","Because mud creates too much gravity.","Because mud turns off the bicycle''s engine."]',1,'You need friction (grip) to push the bike forward; mud makes it too slippery!','Tyre friction helps the bicycle grip the road... Friction: A force that opposes sliding...','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_017','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'Why is ''folding'' a piece of paper into an accordion shape an engineering trick for building a strong paper bridge?','["Folding makes the paper lighter.","Folding the flat paper changes its structural geometry, greatly increasing its rigidity and resistance to bending under a load compared to a flat sheet.","Folding turns the paper into solid wood.","Folding creates a magnetic field that repels the coins."]',1,'A flat piece of paper sags instantly; an accordion fold gives it structural strength!','What might you discover? Folding changes the paper''s shape and can make it resist bending more effectively.','2026-11-01 07:58:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_018','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How do fibre-optic cables use physics to send internet and communication signals?','["They send tiny paper messages through a tube.","They send information as rapid pulses of light through thin glass or plastic fibres using the principle of total internal reflection.","They use water pressure to push the internet through the cables.","They use sound waves shouting through the wires."]',1,'Your internet is literally traveling as laser beams of light bouncing down a glass tube!','Fibre-optic communication: Sends information as pulses of light through thin fibres. Light is guided along the fibre by the principles of total internal reflection.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_019','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'If you are testing which paper airplane design flies the furthest, what is a crucial ''variable'' you must keep exactly the same to ensure a ''fair test''?','["You should change the type of paper every time.","You must use the exact same starting point and launch force for every throw.","You should use a completely different airplane for every throw.","You must throw one outside in the wind and one inside."]',1,'If you throw one plane really hard, and throw the other plane softly, the test is ruined!','Project B: Which paper airplane travels farther? Compare two designs using the same paper. Use the same starting point and launch method...','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_020','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How does an aircraft use the physics of fluids (gases) to take off and fly?','["The airplane''s wings flap like a bird.","The engines provide forward thrust, and the specific shape of the wings forces the moving air to produce an upward force called ''lift''.","The airplane is filled with helium like a balloon.","The airplane turns off gravity."]',1,'The wings push the air down, so the air pushes the plane up!','Aircraft: Engines provide thrust, while the shape and movement of the wings help produce lift. Air resistance opposes forward movement.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_021','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'Why is it stated that ''Inventions rarely appear from nowhere''?','["Because all inventions were given to us by aliens.","Because inventors almost always build upon the earlier scientific discoveries, shared knowledge, and previous experiments of many other people across history.","Because inventions are only created by one single person working alone in a dark room.","Because inventions are just accidents that happen instantly."]',1,'Thomas Edison didn''t invent the lightbulb from scratch; he improved on the work of dozens of scientists before him!','Inventions rarely appear from nowhere. They often build on earlier discoveries, shared knowledge, repeated experiments and improvements made by many people...','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_022','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'In an engineering design process, what is the purpose of step 6: ''Improve the design''?','["To throw the project away and start over from step 1.","To use the empirical evidence gathered during testing to identify weaknesses and make changes to the prototype to make it work better.","To paint the project a nice color so it looks pretty.","To pretend the design was perfect the first time."]',1,'Engineering is about constant improvement, fixing what failed in the test!','6. Improve the design. Use the evidence from testing to make changes and test again... A prototype does not need to be perfect. Testing helps reveal... what should be improved.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_023','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How does the sport of swimming demonstrate Newton''s Third Law (Action and Reaction) even if the law isn''t explicitly named?','["Swimmers just float and let the water carry them.","Swimmers apply a mechanical force by pushing the water backward with their arms and legs; the water pushes back, propelling the swimmer forward.","Swimmers drink the water to become heavier and sink.","Swimmers use magnets to pull themselves forward."]',1,'You push the water back, the water pushes you forward!','Swimming: Swimmers push water backward to move forward, while water resistance opposes their motion.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_024','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'If your hypothesis (prediction) in a physics project turns out to be completely wrong, what should you write in your final report?','["Erase your original prediction and pretend you guessed correctly.","Report the results honestly; explain that the evidence did not support your prediction and discuss what the results actually mean.","Throw the report away because the experiment failed.","Blame the equipment for giving the wrong answer."]',1,'In science, proving your guess wrong is still a successful discovery!','How to write a project report: ... Repeat measurements... report the results honestly—even when they do not match your prediction.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_025','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How do seat belts in a car use physics to keep you safe?','["They use magnetism to hold you to the seat.","When a car slows down suddenly, your body''s inertia wants to keep moving forward; the seat belt provides the restraining force to stop your forward motion safely.","They make the car weigh less.","They turn off gravity inside the car."]',1,'Your body wants to keep flying forward when the car stops; the belt applies the stopping force!','Cars and buses: ... Seat belts help restrain passengers when a vehicle slows suddenly.','2026-11-01 07:58:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_026','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'Why must engineers consider ''environmental effects'' when designing a new transport system (like a train or airplane)?','["Because environmental effects make the transport system faster.","Because building and operating machines use natural resources, create emissions (like carbon dioxide), and can disrupt habitats; engineers must balance usefulness with environmental harm.","Because the environment is not important to engineering.","Because engineers only care about making money."]',1,'A fast airplane is great, but not if it creates so much pollution that people get sick!','Engineers also consider cost, accessibility, safety, environmental effects and the needs of the people who will use the design.','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_027','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'What is a ''load'' in the context of structural engineering?','["The amount of time it takes to build a bridge.","A force or weight (like cars, people, or wind) that a structure (like a bridge or tower) must physically support without collapsing.","The color of the materials used.","The amount of money the structure costs."]',1,'If a bridge is built to hold a load of 10 cars, putting 20 cars on it will cause it to collapse!','Load: A force or weight that a structure must support.','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_028','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'What role did Alexander Graham Bell play in communication engineering?','["He invented the first electric lightbulb.","He is closely associated with the development and patenting of an early practical telephone, transforming how people communicate over distances.","He invented the first airplane.","He invented the first printing press."]',1,'He helped create the technology that lets you talk to someone miles away!','The telephone: Alexander Graham Bell is closely associated with the development and patenting of an early practical telephone...','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_029','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'Why is it important to use ''several trials'' (repeating the test) when doing the toy car ramp experiment?','["Because doing it once is too fast.","A single test might have an accidental error (like bumping the car). Repeating the test and getting similar results proves the data is reliable and not a fluke.","Because you need to use a different car every time.","Because the ramp gets steeper every time you use it."]',1,'If the car hits a speck of dust on the first try, your answer will be wrong! Doing it three times guarantees accuracy.','Project A: Does ramp height affect distance? ... Repeat three times and record the distances. How to write a project report: ... Repeat measurements when possible.','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_030','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',5,'How does a refrigerator use physics to keep food cold?','["It uses a giant block of ice.","It uses a mechanical refrigeration system to actively transfer thermal energy (heat) from the inside of the fridge to the surrounding environment outside.","It creates magic ''cold energy'' out of nothing.","It turns the food into a solid block of ice."]',1,'It doesn''t ''make cold''; it pumps the heat out into your kitchen!','Refrigerators: Transfer heat from the inside to the surrounding environment using a refrigeration system.','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_031','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Critique the assertion that ''Engineering is just applied physics.''','["Engineering is exactly the same thing as physics.","The assertion is reductive. While engineering relies heavily on the laws of physics, it is a distinct discipline that synthesizes physical laws with economic constraints, material science, safety regulations, creativity, and human-centric design to solve practical, real-world problems.","Engineering has absolutely no connection to physics.","Engineering is only used for building bridges, not electronics."]',1,'Physics tells you how gravity works; Engineering uses that rule to build a safe, cheap bridge that people actually want to use!','Engineering uses scientific knowledge, creativity and testing to solve practical problems... Engineers also consider cost, accessibility, safety, environmental effects and the needs of the people...','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_032','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Analyze the complex physical interactions occurring when a tennis racket strikes a ball.','["The racket simply deletes the ball''s kinetic energy and gives it new energy.","The collision involves severe kinetic energy transfer and material deformation. The racket strings (elastic potential energy) and the ball compress. As they rapidly return to their original shape (elasticity), they exert an immense, unbalanced force that instantaneously reverses the ball''s velocity vector.","The tennis racket uses magnetic fields to repel the ball.","The ball passes straight through the strings due to quantum tunneling."]',1,'The ball squishes flat against the strings, and the strings bounce back like a trampoline to shoot it away!','Tennis: The racket applies a force to the ball and changes its speed and direction. What affects a moving ball? ... How hard it is kicked or thrown... Whether it collides with another object...','2026-11-01 07:58:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_033','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Synthesize how the principle of ''Total Internal Reflection'' enables modern global internet (Fibre-optics).','["It uses mirrors to bounce sound waves across the ocean.","Fibre-optic cables use lasers to encode digital data into light pulses. Because the glass fibre''s optical density is engineered precisely, the light hits the boundary of the cable at a shallow angle, reflecting 100% of the light internally without escaping, allowing massive data transmission at the speed of light across oceans.","It allows electricity to travel through rubber wires perfectly.","It relies on shadows to transmit Morse code."]',1,'The light bounces off the inside walls of the glass tube so perfectly that none of the light leaks out, even if the tube bends!','Fibre-optic communication: Sends information as pulses of light through thin fibres. Light is guided along the fibre by the principles of total internal reflection.','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_034','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Evaluate the biomechanical and physical trade-offs in bicycle ''Gearing''.','["Gears make the bicycle pedal itself without human effort.","Gears exploit the mechanical advantage of the wheel and axle. A low gear (small front ring, large rear cog) sacrifices speed for high torque, making uphill climbing easier (less effort, more pedaling). A high gear sacrifices torque for speed, ideal for flat roads (more effort, less pedaling).","Gears only change the color of the bicycle chain.","Gears use air resistance to push the bike forward."]',1,'You can''t get ''free'' energy; you have to choose between pedaling really fast but easily (low gear), or pedaling slowly but with hard pushes (high gear)!','Cycling: Gears change how easily the rider can turn the wheels. (Synthesis: This applies the principles of simple machines/mechanical advantage to human output).','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_035','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Analyze the systemic failure mode of a paper bridge that ''bends too much'' under a load.','["The paper bridge fails because gravity turns off.","When loaded in the center, the top surface of the flat paper is subjected to compression, while the bottom surface is subjected to extreme tension. Because flat paper lacks structural depth (a low moment of inertia), it cannot resist these opposing forces, causing catastrophic structural buckling.","The paper bridge fails because paper is highly magnetic.","The paper bridge fails because the coins melt the paper."]',1,'A flat piece of paper has no thickness to fight against the bending force!','What might you discover? Folding changes the paper''s shape and can make it resist bending more effectively... Strength: How well a structure withstands forces without breaking.','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_036','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Synthesize the role of a ''Transducer'' in the context of both a Microphone and a Speaker.','["A transducer only exists in nuclear power plants.","Both devices are electro-acoustic transducers operating in reverse. A microphone transduces mechanical acoustic energy (sound waves) into fluctuating electrical current. A speaker receives that electrical current and transduces it back into mechanical acoustic energy via electromagnetic vibration.","A transducer turns solid objects into liquid.","A transducer is a type of bridge that connects two cities."]',1,'One turns sound into electricity, the other turns electricity back into sound!','Microphones: Convert sound vibrations into electrical signals. Speakers and headphones: Use electrical signals and magnetic forces to create vibrations that produce sound.','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_037','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Critique the historical narrative of the ''Lone Genius Inventor'' (e.g., Thomas Edison inventing the lightbulb alone).','["The narrative is 100% accurate; Edison did everything himself in one day.","This narrative is a historical fallacy that ignores the collaborative nature of science and engineering. Edison''s practical lightbulb relied on decades of prior research in vacuum pumps, carbon filaments, and electricity by scientists like Joseph Swan and others, highlighting that innovation is an iterative, collective process.","The narrative is false because lightbulbs were actually invented by aliens.","The narrative proves that you don''t need science to invent things."]',1,'Science is a team sport played across generations; nobody invents a complex machine completely by themselves from scratch!','The electric light: Many inventors contributed to the development of practical electric lighting. Thomas Edison and Joseph Swan are among those associated... Inventions rarely appear from nowhere. They often build on earlier discoveries...','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_038','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Evaluate the role of ''Aerodynamics'' (Air Resistance) in the engineering of high-speed passenger trains (like the bullet train).','["Aerodynamics are ignored in trains because trains are heavy.","At high velocities, aerodynamic drag (air resistance) becomes the dominant opposing force, increasing exponentially with speed. Engineers must design aggressively streamlined, tapered nose cones for trains to pierce the fluid atmosphere efficiently, drastically reducing energy consumption and preventing sonic boom effects in tunnels.","Aerodynamics are used to make the train fly into the sky.","Aerodynamics only matter for bicycles, not trains."]',1,'If a train going 200 mph had a flat, square front, it would waste massive amounts of electricity just fighting the wind!','Air resistance opposes forward movement... Different transport designs balance speed, safety, energy use... (Synthesis: High speed requires overcoming massive drag via streamlined engineering).','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_039','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Analyze how the ''Scientific Method'' overlaps with the ''Engineering Design Process''.','["They are entirely different and share no common steps.","Both rely on empirical observation and systematic testing. However, the Scientific Method tests a hypothesis to generate new universal knowledge (Why does it happen?), while the Engineering Process tests a prototype to solve a specific human problem (How can we fix it?). Both heavily rely on analyzing resulting data to refine their models.","The engineering process never uses testing, only guessing.","The scientific method is only used for building bridges."]',1,'Science asks ''What is this?''; Engineering asks ''How can I use this to build a better tool?''','A physics project starts with a question that can be investigated safely. Learners make predictions, test ideas, record evidence... A useful engineering process has six steps... Identify the problem... Build a prototype... Test and record...','2026-11-01 07:58:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_040','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Synthesize the integration of multiple simple machines required to operate a modern ''Door'' safely.','["A door is only a single piece of wood.","A door is a compound machine. The hinges act as a fixed axis of rotation (lever/wheel and axle concept), the door itself acts as a massive lever arm multiplying the user''s force, and the doorknob uses a wheel and axle to retract the latch (a wedge), demonstrating complex mechanical integration.","A door uses pulleys to lift itself into the ceiling.","A door is held together purely by static electricity."]',1,'You use a wheel (the knob) to pull back a wedge (the latch) so you can swing a giant lever (the door)!','Doors and hinges: Hinges allow a door to rotate around a fixed axis... A door knob also uses the wheel-and-axle principle... (from previous knowledge context).','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_041','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Critique the safety of conducting a physics experiment testing ''how much weight a structure can hold'' if the load involves human beings.','["It is the best way to test a structure because it is realistic.","Testing prototype structures with human loads violates paramount safety ethics in physics education. Prototypes are designed to fail to find their limits. Using humans as the load introduces a severe, unacceptable risk of catastrophic injury upon structural collapse. Static, inanimate weights must be used.","It is safe as long as the humans wear helmets.","It is safe if the structure is made of paper."]',1,'You build a tiny bridge and break it with coins so you know how to build a giant bridge that WON''T break with people!','Safety: Use small, light weights, keep the bridge low, and do not use the experiment to test structures that people will stand on.','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_042','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Analyze the mechanical principle behind ''Arch'' structures in engineering.','["Arches are purely decorative and offer no structural support.","An arch is a curved structure designed to resolve vertical gravitational loads (weight) into compressive forces. By forcing the load to travel outward and downward along the curve of the arch into solid abutments (supports), it eliminates tensile stress, making it incredibly strong using materials like stone.","Arches work by floating above the ground using magnetism.","Arches use elasticity to bounce the weight away."]',1,'The curve of the arch forces all the heavy blocks to squeeze tightly together, making the bridge incredibly strong!','Shape: Triangles can help make frameworks rigid, while arches can transfer loads toward their supports.','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_043','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Synthesize how a ''Thermos flask'' utilizes the physics of heat transfer to function.','["It uses an electric motor to blow cold air on the liquid.","A thermos uses a double-walled vacuum design. The vacuum layer prevents conduction and convection (which require a material medium), while a reflective inner coating minimizes radiation. By impeding all three methods of heat transfer, it maintains the internal temperature (hot or cold) in near-thermal isolation.","It uses chemical reactions to freeze the liquid instantly.","It uses magnets to repel the heat away from the bottle."]',1,'It''s basically a bottle inside a bottle, with absolutely nothing (a vacuum) in between them!','Thermos flasks: Reduce heat transfer to help keep drinks hot or cold. (Synthesis with previous heat transfer concepts).','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_044','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Evaluate the necessity of ''Failure'' in the prototype testing phase of engineering.','["Failure means the engineer is incompetent and should quit.","Controlled failure is the most critical diagnostic tool in engineering. A prototype that never fails provides no data on its ultimate safety limits or structural tolerances. Analyzing exactly how and why a prototype breaks provides the empirical data necessary to over-engineer the final product for safety.","Failure proves that physics is entirely random.","Failure is avoided by never testing the prototype at all."]',1,'You have to break the first model to learn how to make the final model unbreakable!','Test the prototype safely, measure results and identify weaknesses... A prototype does not need to be perfect. Testing helps reveal what works, what fails and what should be improved.','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('phys_everyday_global_045','Physics','Everyday Physics','Topic 15: Everyday Physics and Engineering','Primary',10,'Critique the assertion that ''Newton''s laws of motion are irrelevant to modern digital sports (like esports).''','["The assertion is completely accurate.","While esports occur digitally, the human interface relies entirely on physics. Actuating a keyboard or mouse requires overcoming mechanical spring resistance (Hooke''s Law) via muscle force, and the tactile feedback and actuation speed (latency) are governed by the friction and mass of the physical switches.","The assertion is false because esports are played on the moon.","Esports rely entirely on quantum physics, not classical motion."]',1,'Even clicking a mouse requires your finger to apply force to overcome the mechanical resistance of a tiny spring!','Physics is not only something we study in textbooks. It explains how... phones produce sound... (Synthesis: Every physical interaction, even with a digital device, involves forces and motion).','2026-11-01 07:58:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_001','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is ''chemistry''?','["The study of stars and planets","The branch of science that studies matter, its properties, what it is made of, and how it changes","The study of ancient history","The study of how animals behave"]',1,'It helps us understand the materials that make up the world around us.','Chemistry is the branch of science that studies matter, its properties, what it is made of, and how it changes.','2026-11-01 08:30:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_002','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is ''matter''?','["Only things that are liquids","Anything that has mass and occupies space","Only things you can see","Only living things"]',1,'Everything around you, including air and water, is matter.','Matter is anything that has mass and occupies space.','2026-11-01 08:30:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_003','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'Which of these is NOT an example of matter?','["Water","Wood","Light","Air"]',2,'You cannot weigh a beam of light on a scale.','Water, air, wood, metal, and the food we eat are all examples of matter. (Light does not have mass).','2026-11-01 08:30:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_004','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What does it mean to study the ''properties'' of a material?','["To study how much it costs","To study characteristics like its color, hardness, or solubility","To study where it was made","To study its history"]',1,'A property describes what the material is like.','Chemists investigate properties such as colour, hardness, solubility and how materials respond to heat.','2026-11-01 08:30:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_005','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What are the three common states of matter studied by chemists?','["Wood, metal, and glass","Solids, liquids, and gases","Fire, water, and earth","Atoms, molecules, and cells"]',1,'Ice, water, and steam are examples of these three states.','Chemists study the materials that make up the world, including solids, liquids and gases.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_006','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is a ''physical change''?','["A change where a material is completely destroyed","A change in form, size, or state where no new substance is formed","A change where a completely new substance is formed","A change that only happens to metal"]',1,'Melting ice is an example because it is still just water.','Physical change: A change in form, size or state where no new substance is formed.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_007','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'Which of these is an example of a ''physical change''?','["Iron rusting","Wood burning","Ice melting","Baking a cake"]',2,'The material stays the same; it just changes shape or state.','Examples [of physical change]: Ice melting. Paper being cut. Water freezing.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_008','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is a ''chemical change''?','["A change where a material is cut in half","A change in which one or more new substances form","A change where water turns into ice","A change that only happens in space"]',1,'Burning wood is an example because it turns into ash and smoke.','Chemical change: A change in which one or more new substances form.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_009','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'Which of these is an example of a ''chemical change''?','["Cutting paper","Iron rusting","Freezing water","Melting butter"]',1,'The iron turns into a new substance called rust.','Examples [of chemical change]: Iron rusting. Wood burning. An egg cooking.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_010','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What are the tiny building blocks of all matter called?','["Cells","Atoms","Drops","Grains"]',1,'They are too small to see with your eyes.','Atoms are tiny building blocks of matter.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_011','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is a ''molecule''?','["A type of liquid","A single, isolated atom","Two or more atoms joined together","A tool used in the laboratory"]',2,'Water is a molecule made of hydrogen and oxygen atoms joined together.','Molecules are groups of two or more atoms joined together.','2026-11-01 08:30:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_012','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is the most important safety rule in a chemistry laboratory?','["Always taste the chemicals to see what they are","Follow the teacher''s instructions and wear appropriate safety equipment","Mix all the chemicals together","Never wash your hands"]',1,'Safety always comes first in a lab!','Follow the teacher''s instructions and wear appropriate safety equipment, such as goggles when required.','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_013','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'Should you ever taste or directly smell unknown substances in a laboratory?','["Yes, to find out what they are","No, never taste laboratory substances or directly smell chemicals","Only if they look like water","Only if the teacher is not looking"]',1,'Chemicals can be very dangerous if they get in your mouth or nose.','Never taste laboratory substances or directly smell chemicals.','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_014','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'What is an ''observation'' in a science experiment?','["A guess about what will happen","Information gathered using our senses or instruments","The final answer","The equipment used to clean up"]',1,'It is what you see, hear, or measure during a test.','Observation: Information gathered using our senses or instruments.','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_015','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',1,'If you put sugar in water and stir it, what happens?','["It turns into sand.","It dissolves in the water.","It explodes.","It sinks to the bottom and stays solid forever."]',1,'The sugar seems to disappear, but it is actually mixed into the water.','Expected observations: Sugar dissolves in water under ordinary conditions.','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_016','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why is chemistry considered important for ''everyday life'', not just laboratories?','["Because chemistry is only used to make explosions.","Chemistry helps us understand and create things we use daily, like cooking food, making soap to clean dirt, and developing medicines.","Because chemists need to go to the grocery store.","Chemistry is actually completely separated from everyday life."]',1,'When you bake bread or wash your hands, you are doing chemistry!','Chemistry is not limited to laboratories. It is part of our daily activities... Everyday example: Cooking food... Washing with soap... Chemistry is useful in medicine, agriculture...','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_017','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'How does the ''fair test'' rule apply when testing if sugar dissolves faster in warm or cold water?','["You should use a lot of sugar in the cold water and a little in the warm water.","You must use the exact same amount of sugar and water, and change ONLY the water temperature.","You should stir the warm water, but not the cold water.","You should use salt instead of sugar."]',1,'If you change two things at once, you won''t know which one caused the result!','Plan a fair test. Use the same amount of sugar and water, changing only the water temperature.','2026-11-01 08:30:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_018','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why is ''cutting a piece of paper'' considered a physical change rather than a chemical change?','["Because paper is not made of matter.","Because the paper changes its shape and size, but the actual material is still paper; no new substance was formed.","Because cutting paper releases heat and light.","Because cutting paper makes it turn into a liquid."]',1,'It looks different, but it is still just paper!','Physical change: A change in form, size or state where no new substance is formed. Examples: ... Paper being cut.','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_019','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why is ''cooking an egg'' considered a chemical change?','["Because the egg becomes cold.","Because the heat causes the proteins in the egg to react and form new substances with different properties (color, texture) that cannot easily be turned back into a raw egg.","Because cooking an egg only changes its shape.","Because the egg evaporates completely."]',1,'Once you fry an egg, you can never un-fry it; it has permanently changed into something new!','Chemical change: A change in which one or more new substances form. Examples: ... An egg cooking.','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_020','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'What is the difference between an ''element'' and a ''compound''?','["Elements are liquids, compounds are solids.","An element contains only one type of atom, while a compound contains atoms of different elements chemically joined together (like H2O).","An element is made of molecules, a compound is made of light.","There is no difference; they are the same thing."]',1,'Gold is an element (only gold atoms); Water is a compound (hydrogen + oxygen)!','Elements contain one type of atom. Compounds contain atoms of different elements chemically joined together. For example, water is a compound made from hydrogen and oxygen atoms.','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_021','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'If you see a bicycle chain turning orange over time, what chemical process is happening?','["The iron in the chain is melting.","The iron is reacting with oxygen and moisture in the air to form a new substance called rust (a chemical change).","The chain is undergoing a physical change.","The chain is turning into pure gold."]',1,'The shiny metal is reacting with the air to create the orange crust!','Everyday example... Iron rusting: Iron reacts with oxygen and moisture to form rust... (This is a chemical change).','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_022','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why is ''glass'' a good material for a window, but a bad material for a hammer?','["Because glass is a liquid.","Glass has the property of being ''transparent'' (letting light through for windows), but it is also ''brittle'' and breaks easily upon impact, making it useless for hitting things.","Because glass cannot be shaped.","Because glass is too heavy to lift."]',1,'You have to choose the right properties for the job!','Glass: Usually transparent and hard, making it useful for windows... It can break if dropped. A material''s property is a characteristic that helps describe it... so they are suitable for different purposes.','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_023','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'In the scientific method, what should a scientist do if their experiment''s results do not match their prediction?','["Change the results so they match the prediction.","Record the results honestly and be willing to change their initial prediction based on the new evidence.","Throw the experiment away and never tell anyone.","Stop being a scientist."]',1,'Being wrong is how scientists learn the truth!','Draw a conclusion... Do not claim more than the evidence supports. Scientists should be willing to change their predictions when the evidence does not support them.','2026-11-01 08:30:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_024','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why are ''atoms'' and ''molecules'' important to chemistry?','["Because they are easily visible to the naked eye.","Because all matter in the entire universe is built out of these tiny, invisible particles.","Because they are only found in science labs.","Because they are a type of chemical change."]',1,'They are like the microscopic Lego bricks that build everything in the world!','All matter is made of tiny particles... Atoms are tiny building blocks of matter. Molecules are groups of two or more atoms joined together.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_025','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'What happens to ''sand'' when you mix it with water in a cup?','["It dissolves completely and becomes invisible.","It does not dissolve; the particles remain solid and eventually settle at the bottom of the cup.","It turns into a gas and floats away.","It turns the water into solid ice."]',1,'Unlike sugar, sand will just sit at the bottom of the glass!','Expected observations: ... Sand does not dissolve; its particles may settle.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_026','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why is ''reversibility'' not the only way to tell if a change is physical or chemical?','["Because all physical changes are permanent.","Because some physical changes (like cutting paper) are very difficult to reverse, but the key rule is whether a *new substance* was actually formed.","Because chemical changes can easily be reversed by freezing.","Because reversibility only applies to liquids."]',1,'You can''t uncut a piece of paper, but it is still just paper!','Some changes are difficult to reverse, but reversibility alone does not tell us whether a change is physical or chemical. The key question is whether a new substance forms.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_027','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'Why must you NEVER mix unknown household cleaners together?','["Because it will make them smell nice.","Because they might undergo a dangerous chemical change, releasing toxic gases or harmful heat.","Because they will turn into solid rocks.","Because they will become useless water."]',1,'Mixing bleach and ammonia creates a deadly, poisonous gas!','Laboratory safety: ... Never mix unknown substances or household cleaners.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_028','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'How does soap help clean your hands? (Based on the everyday chemistry examples)','["It uses a physical change to freeze the dirt.","It uses chemical properties to loosen and remove grease and dirt from the skin.","It burns the dirt off with heat.","It turns the dirt into pure water."]',1,'Soap grabs onto the oil and dirt so the water can wash it away!','Everyday example... Washing with soap: Soap helps loosen and remove grease and dirt.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_029','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'What chemical change happens when you bake bread?','["The bread freezes solid.","Yeast in the dough produces carbon dioxide gas (helping it rise), and the heat causes chemical changes that create the crust and flavor.","The bread turns into a liquid.","The bread undergoes a physical change only."]',1,'The soft, sticky dough chemically changes into fluffy, hard-crusted bread!','Everyday example... Baking bread: Yeast produces carbon dioxide, helping dough rise; baking also causes chemical changes.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_030','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',5,'What are you doing when you ''draw a conclusion'' in an experiment?','["You are drawing a picture of the laboratory.","You are explaining what your observations and measurements show, based only on the evidence you collected.","You are making a random guess about what might happen next.","You are writing down the safety rules."]',1,'It is the final step where you explain the ''answer'' to your experiment!','Draw a conclusion. Explain what the observations show. Do not claim more than the evidence supports.','2026-11-01 08:30:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_031','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Critique the assertion that ''Chemistry only occurs inside a laboratory.''','["The assertion is true; chemistry requires glass beakers to function.","The assertion is a fallacy. Chemistry is the fundamental study of matter and its interactions. Biological processes (digestion), geological processes (rusting iron), and everyday actions (cooking) are continuous, natural chemical reactions occurring outside of any lab.","The assertion is true because chemicals must be purchased from a store.","Chemistry only occurs in space, not on Earth."]',1,'Every time you breathe or eat, you are a walking chemistry lab!','Chemistry is not limited to laboratories. It is part of our daily activities... Everyday example: Cooking food... Iron rusting... Plants growing...','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_032','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Analyze the epistemological role of a ''Fair Test'' in establishing scientific causality.','["A fair test proves that science is always right.","By strictly isolating a single independent variable (e.g., water temperature) and holding all other variables constant (sugar amount, stirring rate), a fair test eliminates confounding factors. This allows the chemist to mathematically attribute any observed effect directly to the manipulated variable.","A fair test means everyone gets a turn to do the experiment.","A fair test uses random variables to ensure unpredictable results."]',1,'If you change two things, you can never prove which one caused the final result!','Plan a fair test. Use the same amount of sugar and water, changing only the water temperature. (Synthesis: This ensures causality).','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_033','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Synthesize the difference between a ''Physical Change'' and a ''Chemical Change'' at the atomic/molecular level.','["Physical changes destroy atoms, chemical changes create new atoms.","In a physical change (melting ice), the molecules (\\\\(H_2O\\\\)) remain structurally intact; only their spacing and kinetic energy change. In a chemical change (rusting iron), the molecular bonds are broken and reformed, creating entirely novel chemical structures with new properties.","Physical changes alter molecules, chemical changes only alter the shape of the object.","There is no atomic difference; it is purely a visual difference."]',1,'Melting ice just makes the water molecules move faster; rusting physically attaches oxygen atoms to iron atoms to make a new molecule!','Physical change: A change in form, size or state where no new substance is formed. Chemical change: A change in which one or more new substances form. Molecules are groups of two or more atoms joined together.','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_034','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Evaluate the limitation of using ''Reversibility'' as the sole diagnostic criteria for physical vs. chemical changes.','["Reversibility is a flawless rule; all physical changes are reversible.","While state changes (melting/freezing) are easily reversible physical changes, altering form (e.g., cutting paper or grinding wood) is practically irreversible, yet remains a physical change because no new molecular substance is synthesized. Thus, the formation of a ''new substance'' is the only definitive criteria.","Reversibility is completely unrelated to chemistry.","All chemical changes are easily reversible."]',1,'You can''t put a shredded piece of paper back together, but it''s still just paper, not a new chemical!','Some changes are difficult to reverse, but reversibility alone does not tell us whether a change is physical or chemical. The key question is whether a new substance forms.','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_035','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Analyze how the chemical formula ''H₂O'' defines water as a ''Compound''.','["It shows that water is made of a single type of atom.","The formula explicitly denotes that a single molecule of water is constructed from two distinct elements: Hydrogen (H) and Oxygen (O), chemically bonded together in a 2:1 ratio. Because it contains atoms of *different* elements, it is by definition a compound.","It shows that water is a physical mixture of ice and steam.","It proves that water is an element, not a compound."]',1,'The ''H'' and the ''O'' mean it''s a combination of two different ingredients!','Elements contain one type of atom. Compounds contain atoms of different elements chemically joined together. For example, water is a compound made from hydrogen and oxygen atoms. Its chemical formula is H₂O.','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_036','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Synthesize why ''Photosynthesis'' in plants is classified as a Chemical Change.','["Because the plant grows taller, which is a change in size.","During photosynthesis, plants absorb ambient \\\\(CO_2\\\\) and \\\\(H_2O\\\\) and use solar energy to forcibly break and rearrange those molecular bonds, synthesizing entirely new chemical substances (glucose sugars and oxygen). This synthesis of new matter defines it as a chemical reaction.","Because the plant changes color in the fall.","Because plants only undergo physical changes."]',1,'The plant literally builds a new chemical ''sugar'' out of the air and water!','Everyday example... Plants growing: Chemical reactions help plants make sugars during photosynthesis. Chemical change: A change in which one or more new substances form.','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_037','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Critique the safety instruction: ''Never taste laboratory substances or directly smell chemicals.'' What physiological risk does this mitigate?','["It prevents you from eating all the teacher''s supplies.","Chemical reagents can be highly caustic, toxic, or volatile. Direct ingestion or inhalation of concentrated vapors can cause immediate, severe tissue necrosis in the respiratory tract or systemic poisoning. Odors must be ''wafted'', and ingestion is strictly prohibited.","It prevents the chemicals from losing their flavor.","It is just a rule to keep the lab quiet."]',1,'Breathing in strong chemical fumes can instantly burn the inside of your lungs!','Laboratory safety... Never taste laboratory substances or directly smell chemicals. Keep chemicals away from your eyes and mouth...','2026-11-01 08:30:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_038','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Evaluate the relationship between a material''s ''Properties'' and its ''Application'' using rubber as an example.','["Properties have no impact on application; any material works for any job.","Engineering applications are dictated by material properties. Rubber possesses high elasticity (returns to shape), flexibility, and water resistance. These specific properties make it uniquely suited for applications requiring durable, airtight seals and shock absorption, such as vehicle tyres.","Rubber is used for tyres because it is hard and brittle like glass.","Rubber is used for tyres because it is highly conductive."]',1,'You wouldn''t make a car tire out of glass, because glass shatters instead of bouncing!','We choose materials according to their properties. Rubber: Flexible and elastic... Common use: Rubber bands and tyres.','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_039','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Analyze the statement: ''Do not claim more than the evidence supports.'' Why is this foundational to the scientific method?','["Because scientists should only make things up if they sound cool.","It guards against confirmation bias and unverified extrapolation. Scientific conclusions must be strictly bounded by the empirical data actually collected during the specific parameters of the experiment; overstating results leads to false theories and invalidates the research.","Because evidence is less important than a scientist''s personal opinion.","It means you should never write down any results at all."]',1,'If you test that sugar dissolves in water, you can''t claim that sugar dissolves in oil, because you didn''t test the oil!','Draw a conclusion. Explain what the observations show. Do not claim more than the evidence supports.','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_040','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Synthesize how the concept of ''Matter'' differentiates a wooden block from the light illuminating it.','["The wooden block and the light are both solid matter.","The wooden block possesses mass (atomic structure) and occupies physical volume (space), thus it is matter. The light illuminating it consists of massless photons transferring electromagnetic energy; because it lacks mass and volume, it is not matter.","The light is matter because you can see it, but the wood is not.","There is no difference; they are both forms of energy."]',1,'You can put wood on a scale and weigh it; you can''t weigh a beam of light!','Matter is anything that has mass and occupies space. Water, air, wood... are all examples... Light and sound are not matter. They transfer energy rather than being substances that have mass and occupy space...','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_041','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Critique the observation that ''sugar disappears'' when stirred into water.','["The observation is scientifically perfect; the sugar ceases to exist.","The observation is a semantic fallacy. The solid sugar does not disappear or cease to exist; it undergoes a physical process (dissolution) where its molecules separate and disperse evenly throughout the water solvent, remaining present in the solution despite being invisible to the naked eye.","The sugar turns into a gas and floats away.","The sugar turns into pure water."]',1,'If you taste the water, it is sweet! The sugar is still there, just broken into invisible pieces.','Chemistry helps answer questions such as: ... Why does sugar dissolve in water? ... Expected observations: Sugar dissolves in water... (Synthesis: It doesn''t disappear, it becomes a solution).','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_042','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Analyze the role of ''Yeast'' in baking bread as an example of everyday chemistry.','["Yeast acts as a physical wedge to push the bread apart.","Yeast is a biological organism that facilitates a chemical reaction (fermentation). It metabolizes sugars in the dough, producing carbon dioxide gas as a byproduct. This gas becomes trapped in the gluten matrix, physically expanding (leavening) the bread, demonstrating a biochemical change.","Yeast freezes the bread to make it solid.","Yeast turns the bread into a pure element."]',1,'The yeast ''eats'' the sugar and ''breathes out'' gas bubbles, which makes the bread fluffy!','Everyday example... Baking bread: Yeast produces carbon dioxide, helping dough rise; baking also causes chemical changes.','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_043','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Evaluate why ''Ice, liquid water, and water vapour'' are considered the same chemical substance.','["They are actually three completely different chemical compounds.","Despite existing in drastically different physical states (solid, liquid, gas) with different kinetic energies and densities, the molecular composition of all three remains identical: \\\\(H_2O\\\\). The transitions between them are purely physical changes of state, not chemical reactions.","Ice is made of oxygen, water is hydrogen, and vapor is nitrogen.","They are the same because they all dissolve in sand."]',1,'Whether it''s an ice cube or a steam cloud, it is still just H2O molecules!','Chemists study the materials that make up the world, including solids, liquids and gases. Example: Ice, liquid water and water vapour are three forms of water.','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_044','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Synthesize how the chemical property of ''Rusting'' dictates the engineering application of Iron.','["Because iron rusts, it is always the best metal to use underwater.","Iron readily undergoes an oxidation reaction (rusting) when exposed to moisture and ambient oxygen, compromising its structural integrity. Therefore, engineers must either utilize protective coatings (paint/galvanization) or alloy it with other elements (creating stainless steel) for applications exposed to the elements.","Rusting makes iron stronger and more flexible.","Rusting proves that iron is actually a gas."]',1,'Because iron turns into crumbly rust when it gets wet, you can''t build a bare-iron boat without painting it first!','Chemical change... Iron rusting... Everyday example: Iron reacts with oxygen and moisture to form rust.','2026-11-01 08:30:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_intro_global_045','Chemistry','Introduction to Chemistry','Topic 1: Introduction to Chemistry','Primary',10,'Critique the statement: ''Scientists only do experiments to prove they are right.''','["The statement is the core definition of the scientific method.","This reflects a fundamental misunderstanding of scientific inquiry. The goal of an experiment is to test a hypothesis against empirical reality. Falsification (proving a prediction wrong) is vital; it eliminates incorrect models and drives the refinement of theories toward objective truth.","Scientists only do experiments to make explosions.","The statement is true because being wrong is not allowed in science."]',1,'A good scientist is happy to be proven wrong, because finding the truth is more important than being right!','Draw a conclusion... Do not claim more than the evidence supports. Scientists should be willing to change their predictions when the evidence does not support them.','2026-11-01 08:30:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_001','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What are the three common states of matter?','["Wood, metal, and glass","Solids, liquids, and gases","Earth, wind, and fire","Hot, cold, and warm"]',1,'Think about ice, water, and steam.','Matter commonly exists in three states: solid, liquid and gas.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_002','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What does it mean for something to be a ''solid''?','["It flows and changes shape easily.","It has no shape at all.","It has a definite shape and a definite volume.","It is always completely invisible."]',2,'A wooden block or a rock is a solid.','A solid has a definite shape and a definite volume. It usually keeps its shape unless a force changes it.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_003','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'Which of these is an example of a solid?','["Air","Water","Milk","Ice"]',3,'It keeps its shape when you put it in a bowl.','Examples [of solids] include rocks, books, ice cubes...','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_004','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What does it mean for something to be a ''liquid''?','["It has a definite volume but does not have a fixed shape; it flows.","It has a fixed shape and cannot flow.","It spreads out to fill any room.","It is always frozen hard."]',0,'Water and juice are liquids.','A liquid has a definite volume but does not have a fixed shape. It flows and takes the shape of the part of its container that it fills.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_005','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'Which of these is an example of a liquid?','["A rock","Cooking oil","A wooden block","Oxygen gas"]',1,'You can pour it into a glass.','Examples [of liquids] include water, milk, cooking oil and juice.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_006','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What does it mean for something to be a ''gas''?','["It has a definite shape like a box.","It has a fixed volume that never changes.","It has no fixed shape and no fixed volume; it spreads out to fill the space.","It is always heavy and falls to the ground."]',2,'The air inside a balloon is a gas.','A gas has no fixed shape and no fixed volume. It spreads out to fill the available space in its container.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_007','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'Which of these is an example of a gas?','["Helium inside a balloon","Water in a cup","A piece of wood","A metal spoon"]',0,'It floats and fills up space.','Examples [of gases] include the oxygen and nitrogen in air, helium in balloons and water vapour.','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_008','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What are all solids, liquids, and gases made of?','["Tiny particles that are too small to see","Empty space","Liquid water","Light waves"]',0,'Everything is built out of these invisible pieces.','Matter is made of tiny particles. These particles are too small to see individually with our eyes...','2026-11-01 08:34:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_009','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What is ''melting''?','["A liquid turning into a solid","A gas turning into a liquid","A solid changing into a liquid","A liquid turning into a gas"]',2,'It happens when you leave an ice cube in the sun.','Melting: Solid → liquid. Ice melts into water when it gains enough energy.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_010','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What is ''freezing''?','["A solid changing into a liquid","A liquid changing into a gas","A gas changing into a solid","A liquid changing into a solid"]',3,'It happens when you put water in the freezer.','Freezing: Liquid → solid. Water freezes into ice when it loses enough energy.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_011','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What is ''evaporation''?','["A solid turning into a gas","A liquid changing into a gas at its surface","A gas turning into a liquid","A liquid freezing into a solid"]',1,'It is how wet clothes dry in the sun.','Evaporation: Change from liquid to gas at the surface.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_012','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What is ''condensation''?','["A liquid turning into a solid","A solid turning into a liquid","A gas changing into a liquid","A liquid turning into a gas"]',2,'It makes water droplets on the outside of a cold glass.','Condensation: Change from gas to liquid.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_013','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What is ''sublimation''?','["A solid changing directly into a gas without becoming a liquid","A gas changing into a liquid","A liquid changing into a solid","A solid melting into a liquid"]',0,'It skips the liquid step completely!','Sublimation: Change from solid directly to gas. Some solid substances, such as dry ice, do this...','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_014','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'What causes matter to change from one state to another (like solid to liquid)?','["Painting it a different color","Gaining or losing thermal energy (heating or cooling)","Moving it to a different room","Breaking it into smaller pieces"]',1,'You have to heat up ice to make it melt!','Matter can change state when it gains or loses thermal energy.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_015','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',1,'Which state of matter can be easily compressed (squished)?','["Solid","Liquid","Gas","Metal"]',2,'You can squeeze a balloon, but you can''t squeeze a rock!','Gases can be compressed: When pressure is applied, gas particles can be pushed closer together.','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_016','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Why does a liquid, like water, change shape when you pour it from a tall bottle into a wide bowl?','["Because the water particles are destroyed.","Because liquids have no fixed shape; their particles can move past each other to take the shape of their new container.","Because liquids have no volume.","Because the bowl is magnetic."]',1,'The water spreads out to fit the bowl, but it''s still the exact same amount of water!','A liquid has a definite volume but does not have a fixed shape. It flows and takes the shape of the part of its container... The particles remain close but can move past each other. This allows the liquid to flow...','2026-11-01 08:34:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_017','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Why is it very difficult to compress (squish) a solid rock?','["Because rocks are made of gas.","Because the particles in a solid are already tightly packed close together and vibrate in fixed positions.","Because the rock is completely empty inside.","Because rocks are too hot to touch."]',1,'There is no empty space between the particles to squeeze them into!','Solid: tightly packed particles. The particles stay close together and vibrate around fixed positions. This helps the solid keep its shape... Easily compressed? Usually no.','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_018','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'How do the particles in a gas behave compared to the particles in a liquid?','["Gas particles are frozen solid and cannot move.","Gas particles move freely in all directions and are spread far apart, while liquid particles stay close together.","Gas particles are much heavier than liquid particles.","Gas particles are exactly the same as liquid particles."]',1,'Gas particles fly around the whole room, liquid particles stay clustered in the cup!','Gas: widely spaced particles. The particles move freely in different directions and spread throughout the available space. (Unlike liquids where particles remain close).','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_019','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'If you pump air into a bicycle tyre, why does the tyre get hard?','["Because the air turns into a solid metal.","Because air is a gas (matter), meaning it takes up space and pushes against the inside of the tyre as it is compressed.","Because the air freezes inside the tyre.","Because the air escapes through the rubber."]',1,'You are stuffing more and more invisible matter into a small space!','When air is pumped into a bicycle tyre, the air occupies space inside the tyre. Air is matter even though we cannot usually see it. Gases can be compressed...','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_020','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Why does wet clothing eventually dry when hung outside on a sunny day?','["The water on the clothes freezes into invisible ice.","The thermal energy from the sun causes the liquid water to evaporate, changing into water vapor (gas) and floating away.","The water on the clothes sinks into the ground.","The fabric absorbs the water permanently."]',1,'The sun heats the water until it turns into a gas and leaves the clothes!','Drying clothes: Liquid water evaporates from the fabric... Evaporation: Liquid → gas from the liquid''s surface.','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_021','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'What causes water droplets to form on the outside of a glass of cold iced tea?','["The glass is melting.","The cold tea leaks through the solid glass.","Invisible water vapor (gas) in the warm air cools down when it hits the cold glass and condenses into liquid water droplets.","The ice inside the glass jumps out."]',2,'The water comes from the air in the room, not from inside the cup!','Droplets on a cold glass: Water vapour in the surrounding air cools against the glass and condenses into liquid droplets. The water does not usually leak through the glass.','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_022','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'If you put a dry tissue at the bottom of a cup and push the cup upside down into a bowl of water, why does the tissue stay dry?','["Because the tissue is waterproof.","Because the cup is filled with air (matter), which occupies the space and prevents the liquid water from entering.","Because the water is too heavy to go inside.","Because the cup creates a magnetic force."]',1,'The water can''t get in because the air is in the way!','Air trapped inside the cup occupies space and prevents most of the water from entering... Air occupies space.','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_023','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Is the white cloud you see coming out of a boiling kettle actually ''steam'' (water vapor)?','["Yes, it is pure, invisible gas.","No, true water vapor is invisible; the white cloud is actually tiny liquid water droplets formed when the hot gas cools and condenses in the air.","Yes, steam is always white and cloudy.","No, it is smoke from burning water."]',1,'If you can see it, it is a liquid mist, not a gas!','Is steam the same as the white cloud above a kettle? Not exactly. Water vapour is a colourless gas. The white cloud often seen above a boiling kettle is made mainly of tiny liquid water droplets...','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_024','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Even though a sponge is soft and can be squished, why is it still classified as a ''solid''?','["Because it is actually a liquid that flows.","Because the material itself has a fixed shape and volume; it can only be squished because it is full of empty air spaces.","Because it is made of gas.","Because it absorbs water."]',1,'The sponge material is solid; you are just squeezing the empty air out of the holes!','Many solids are hard, but not all are. A sponge, for example, is a solid that can be compressed because it contains many small spaces.','2026-11-01 08:34:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_025','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'At what temperature does pure liquid water turn into a solid (ice) under normal pressure?','["100°C","50°C","0°C","10°C"]',2,'0°C is the freezing point!','For pure water at standard atmospheric pressure, ice melts at about 0°C (and water freezes at 0°C).','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_026','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'At what temperature does pure liquid water actively boil into a gas under normal pressure?','["0°C","50°C","100°C","200°C"]',2,'100°C is very hot!','For pure water at standard atmospheric pressure... water boils at about 100°C.','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_027','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'What happens to the ''volume'' of a liquid if you pour it from a tall, thin glass into a short, wide bowl?','["The volume increases because the bowl is wider.","The volume decreases because the bowl is shorter.","The volume stays exactly the same, even though the shape changes.","The volume disappears completely."]',2,'100 mL of water is always 100 mL, no matter what shape the cup is!','Properties of liquids: No fixed shape... Fixed volume: A given amount of liquid occupies approximately the same volume under the same conditions. Example: Pour water... the amount of water remains the same...','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_028','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'What does it mean that a gas has ''no fixed volume''?','["It means gas is very heavy.","It means gas will expand or spread out to completely fill any container you put it in, regardless of the container''s size.","It means gas shrinks until it disappears.","It means gas stays exactly the same size forever."]',1,'If you release a tiny bit of gas in a large room, it spreads out to fill the entire room!','Gases: No fixed volume: It spreads out to fill the available space.','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_029','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'How does the ''Particle Model'' explain why solids hold their shape?','["Because the particles are glued together with liquid.","The particles in a solid are tightly packed in an orderly arrangement and only vibrate in place, so they cannot move past each other to change shape.","Because the particles are frozen in ice.","Because the particles move freely in all directions."]',1,'The pieces are locked together like tightly packed puzzle pieces!','Solid: tightly packed particles. The particles stay close together and vibrate around fixed positions. This helps the solid keep its shape and volume.','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_030','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',5,'Why is ''sublimation'' different from normal melting and boiling?','["It only happens to liquids.","Sublimation skips the liquid phase entirely; a solid turns directly into a gas without ever melting into a liquid first.","It means a gas turns into a liquid instantly.","It only happens when something is frozen."]',1,'Dry ice doesn''t melt into a puddle; it just turns straight into fog!','Sublimation: Change from solid directly to gas without passing through the liquid state. Some solid substances, such as dry ice, do this...','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_031','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Critique the assertion that ''Gases are weightless because they float in the air.''','["The assertion is scientifically accurate; gases lack mass.","The assertion is a fallacy. Gases are defined as a state of matter (e.g., oxygen, helium). Because matter by definition possesses mass and occupies space, all gases possess mass and therefore exert weight under gravity, even if they are less dense than the surrounding atmosphere.","The assertion is true because gases are invisible.","Gases only have weight when they are frozen."]',1,'A balloon full of air weighs slightly more than a completely empty, flat balloon!','Matter is anything that has mass and occupies space... Gases... Examples include the oxygen and nitrogen in air... (Synthesis: Since gases are matter, they must have mass).','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_032','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Analyze the kinetic particle theory: How does adding thermal energy cause ''Melting''?','["Thermal energy makes the particles stop moving completely.","Thermal energy increases the kinetic energy (vibration) of the closely packed particles in a solid. When the vibration becomes forceful enough to overcome the intermolecular bonds holding the rigid lattice together, the particles break free to slide past one another, forming a liquid.","Thermal energy creates new particles that push the solid apart.","Thermal energy turns the solid directly into light."]',1,'Heat makes the particles shake so violently that they break their rigid structure!','Melting: Solid → liquid. Ice melts into water when it gains enough energy... Solid: The particles stay close together and vibrate... Liquid: The particles remain close but can move past each other.','2026-11-01 08:35:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_033','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Synthesize why ''Compressibility'' is a defining characteristic of gases but not solids or liquids.','["Solids and liquids are already made of gas.","In gases, the intermolecular distance between particles is vast, leaving massive amounts of empty void space. Applied pressure easily forces these particles closer together (compression). In solids and liquids, particles are already closely packed with negligible void space, rendering them virtually incompressible.","Gases are made of softer materials than solids.","Solids and liquids can actually be compressed easily."]',1,'You can squish a gas because it''s mostly empty space! You can''t squish a liquid because the particles are already touching.','Solid... Particles close together... Liquid... Particles close together... Gas... Particles far apart: Gas particles are generally much farther apart... Gases can be compressed: When pressure is applied, gas particles can be pushed closer together.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_034','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Evaluate the physical distinction between ''Evaporation'' and ''Boiling''.','["They are two names for the exact same physical process.","Evaporation is a surface-level phenomenon where high-energy particles escape a liquid at any temperature below the boiling point. Boiling is a bulk phenomenon occurring uniformly throughout the entire liquid volume only when its vapor pressure equals the surrounding atmospheric pressure.","Evaporation only happens to solids.","Boiling only happens at the surface of a liquid."]',1,'A puddle evaporates slowly from the top down; a pot boils rapidly from the bottom up!','Evaporation: Change from liquid to gas at the surface. Boiling: Liquid changes to gas throughout the liquid when it reaches its boiling point under the given pressure.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_035','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Analyze the specific anomaly of ''Water'' when transitioning from a liquid to a solid (freezing).','["Water shrinks continuously until it disappears when it freezes.","Unlike almost all other substances that increase in density as they freeze (particles packing tighter), water reaches maximum density at 4°C and then expands as it forms a crystalline lattice structure (ice). This unique physical property makes solid ice less dense than liquid water, causing it to float.","Water turns into a heavy metal when it freezes.","Water boils when it reaches its freezing point."]',1,'If ice didn''t expand and become lighter than water, it would sink and freeze the oceans solid!','This relies on synthesis of physics knowledge (often taught alongside states of matter). The text mentions: ''For pure water at standard atmospheric pressure, ice melts at about 0°C.'' The anomaly of ice floating is a foundational chemistry concept.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_036','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Synthesize the interaction between ''Temperature'' and ''Condensation'' in the formation of visible mist.','["Mist forms when the air gets too hot.","Hot, invisible water vapor (gas) holds high kinetic energy. When this gas contacts a cooler environment (like cool air above a kettle or a cold glass), it rapidly loses thermal energy. This forces the particles to slow down and bond together (condensation), forming microscopic, visible liquid droplets suspended in the air.","Mist forms when water turns into a solid.","Mist is actually smoke from burning water."]',1,'The hot gas hits the cold air, instantly turning back into floating liquid water!','Is steam the same as the white cloud above a kettle? Not exactly. Water vapour is a colourless gas. The white cloud... is made mainly of tiny liquid water droplets formed when hot water vapour cools and condenses in the air.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_037','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Critique the everyday use of the word ''Steam'' to describe the white cloud above a kettle.','["The white cloud is scientifically defined as pure steam.","Scientifically, ''steam'' (water vapor) is a high-energy, transparent, invisible gas. The visible white cloud is not a gas; it is an aerosol consisting of condensed, microscopic droplets of liquid water. Therefore, calling the visible cloud ''steam'' is a colloquial misnomer for condensed liquid.","The white cloud is actually a solid.","The white cloud is made of smoke, not water."]',1,'True steam is completely invisible; the white cloud you see is already liquid water!','Is steam the same as the white cloud above a kettle? Not exactly. Water vapour is a colourless gas. The white cloud often seen above a boiling kettle is made mainly of tiny liquid water droplets...','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_038','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Evaluate the experimental design: Inverting an ''empty'' cup into water to prove air occupies space.','["The experiment fails because cups are not transparent.","The experiment relies on fluid displacement and the impermeability of matter. The cup is not empty; it contains a volume of atmospheric gas (air). Because two distinct masses of matter (water and air) cannot occupy the same volume simultaneously, the trapped gas physically prevents the liquid from entering the rigid container.","The experiment works because the cup is magnetic.","The experiment works because the tissue paper absorbs all the water instantly."]',1,'The water wants to go in, but the air refuses to get out of the way!','Air trapped inside the cup occupies space and prevents most of the water from entering... Air occupies space. The bottle was not truly empty; it contained invisible air.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_039','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Analyze how ''Sublimation'' bypasses the liquid state entirely.','["Sublimation occurs when a solid is frozen twice.","Sublimation occurs in specific substances (like dry ice/solid \\\\(CO_2\\\\)) where the atmospheric pressure is below the substance''s triple point. When thermal energy is added, the intermolecular bonds shatter completely, allowing the molecules to transition directly from a rigid lattice (solid) to a free-moving state (gas) without an intermediate fluid phase.","Sublimation means a gas turns into a solid.","Sublimation only happens when liquids are boiled."]',1,'Dry ice never leaves a wet puddle; it just turns straight into fog!','Sublimation: Change from solid directly to gas without passing through the liquid state. Some solid substances, such as dry ice, do this under suitable conditions.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_040','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Synthesize why a ''Sponge'' is classified as a solid despite being highly compressible.','["A sponge is actually a highly viscous liquid.","A sponge''s compressibility does not stem from its fundamental atomic structure (like a gas). The physical material (cellulose/polyurethane) is a rigid solid holding a fixed shape. However, it is a porous matrix filled with atmospheric gas. Compression merely forces the trapped gas out of the macroscopic voids, leaving the solid material intact.","A sponge is classified as a gas because it holds air.","A sponge is a solid only when it is wet."]',1,'You aren''t squishing the solid sponge material; you are just squishing the empty air pockets inside it!','Many solids are hard, but not all are. A sponge, for example, is a solid that can be compressed because it contains many small spaces.','2026-11-01 08:35:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_041','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Critique the assertion that ''Gases have no fixed shape and therefore have no volume.''','["The assertion is completely accurate in physics.","The assertion conflates shape and volume. While gases have no fixed shape (conforming to their container), they inherently possess volume (occupying 3D space). Their volume is simply variable, expanding to fill whatever container they occupy, unlike liquids which have a fixed volume regardless of container shape.","Gases actually have a fixed shape like a box.","Gases have a fixed volume but no shape."]',1,'A gas will fill a small jar or a massive room; its volume changes to match the space!','Gas: State with no fixed shape or volume... It spreads out to fill the available space in its container.','2026-11-01 08:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_042','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Analyze the role of ''Thermal Energy'' in overcoming intermolecular forces during a state change.','["Thermal energy makes the intermolecular forces stronger.","Intermolecular forces act as a binding agent between particles. Thermal energy provides kinetic energy to the particles. A state change (e.g., liquid to gas) occurs precisely when the thermal kinetic energy surpasses the attractive potential energy of the intermolecular forces, allowing the particles to break free and separate.","Thermal energy creates new atoms during a state change.","Thermal energy only affects the color of the material."]',1,'Heat is just movement; if the particles move fast enough, they break their invisible chains and fly apart!','Matter can change state when it gains or loses thermal energy... (Synthesis: The energy breaks the bonds holding the particles together).','2026-11-01 08:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_043','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Synthesize how the ''Particle Model'' explains the high density of solids compared to gases.','["Solids are dense because their particles are made of heavy metal.","Density is mass per unit volume. In the particle model for solids, particles are tightly packed in a dense, orderly lattice with minimal void space, maximizing mass within a given volume. In gases, particles are widely dispersed with massive void space between them, resulting in minimal mass per unit volume (low density).","Gases are highly dense because their particles move fast.","The particle model proves that solids and gases have identical density."]',1,'A box full of solid particles is packed tight; a box full of gas particles is mostly just empty space!','Solid: tightly packed particles... Gas: widely spaced particles. Gas particles are generally much farther apart than particles in solids and liquids.','2026-11-01 08:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_044','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Evaluate the physical mechanism of ''Freezing'' at the microscopic level.','["Freezing causes particles to move faster and fly apart.","As a liquid loses thermal energy to its environment, the kinetic velocity of its particles decreases. Eventually, they lack the energy to overcome intermolecular attractive forces, causing them to lock into fixed, vibrating positions within a rigid crystalline structure, transitioning from a fluid to a solid state.","Freezing causes the particles to turn into a gas.","Freezing only happens when pressure is applied."]',1,'Taking away heat slows the particles down until they get stuck together like glue!','Freezing: Liquid → solid... when it loses enough energy. Solid: The particles stay close together and vibrate around fixed positions.','2026-11-01 08:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_states_global_045','Chemistry','Solids, Liquids and Gases','Topic 2: Solids, Liquids and Gases','Primary',10,'Analyze the statement: ''A liquid takes the shape of the part of its container that it fills.'' Why doesn''t it fill the entire container like a gas?','["Because liquids are repelled by the top of the container.","Unlike gases, liquids possess a definite, fixed volume due to stronger intermolecular forces keeping the particles in close proximity. While these forces are weak enough to allow the particles to flow and assume the container''s shape, they are strong enough to prevent the particles from dispersing endlessly into the available void space.","Because liquids are actually solids in disguise.","Because gravity does not affect liquids."]',1,'The liquid flows to the bottom of the cup, but it won''t expand to fill the top half because the particles want to stay close together!','Liquid: A liquid has a definite volume but does not have a fixed shape. It flows and takes the shape of the part of its container that it fills... The particles remain close but can move past each other.','2026-11-01 08:35:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_001','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What happens during a ''change of state''?','["A material changes from one physical state (like solid, liquid, or gas) to another.","A material changes color permanently.","A completely new substance is formed.","A material disappears forever."]',1,'Ice turning into water is an example.','A change of state happens when a substance changes from one of these states to another.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_002','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What is ''melting''?','["A liquid changing into a gas","A liquid changing into a solid","A solid changing into a liquid","A solid changing into a gas"]',2,'It is what happens to ice cream on a hot day.','Melting occurs when a solid gains thermal energy and changes into a liquid.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_003','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'Which of these is an example of melting?','["Water turning into ice","Wet clothes drying","Chocolate softening and turning liquid when warmed","A puddle disappearing"]',2,'The solid chocolate becomes gooey and liquid.','Examples [of melting]: ... Chocolate softening and melting when warmed.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_004','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What is ''freezing''?','["A gas changing into a liquid","A liquid changing into a solid","A solid changing into a gas","A liquid changing into a gas"]',1,'It is what happens when you put water in the freezer.','Freezing occurs when a liquid loses thermal energy and becomes a solid.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_005','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'Which of these is an example of freezing?','["Ice turning into water","Liquid wax becoming solid as it cools","Water boiling on a stove","A puddle drying up"]',1,'The hot, runny wax turns hard.','Examples [of freezing]: ... Liquid wax becoming solid after a candle is extinguished, as it cools.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_006','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What is ''evaporation''?','["A gas turning into a solid","A liquid changing into a gas at its surface","A solid changing into a liquid","A liquid changing into a solid"]',1,'It is why a puddle slowly disappears.','Evaporation is the change from liquid to gas that happens at the surface of a liquid.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_007','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What is ''condensation''?','["A liquid changing into a gas","A solid changing into a gas","A solid changing into a liquid","A gas changing into a liquid"]',3,'It creates the water drops on a cold glass.','Condensation occurs when a gas changes into a liquid, usually as it cools.','2026-11-01 08:35:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_008','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'Which of these is an example of condensation?','["Ice melting in a bowl","Tiny droplets forming on a bathroom mirror after a hot shower","Wet clothes drying on a line","Butter melting in a pan"]',1,'The steam hits the cold mirror and turns back into liquid drops.','Examples [of condensation]: ... Tiny droplets forming on a bathroom mirror after a hot shower.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_009','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What is ''sublimation''?','["A liquid turning into a solid","A solid changing directly into a gas without becoming a liquid","A gas changing into a liquid","A solid turning into a liquid"]',1,'It skips the liquid step completely!','Sublimation is the change from a solid directly into a gas without first becoming a liquid.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_010','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'Which substance is commonly known to ''sublime'' (undergo sublimation) under ordinary conditions?','["Pure water","Solid carbon dioxide (dry ice)","Liquid wax","Chocolate"]',1,'Dry ice never leaves a wet puddle.','An example is dry ice, which is solid carbon dioxide. Under ordinary atmospheric conditions, it changes directly into carbon dioxide gas.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_011','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'Are changes of state (like melting or freezing) considered physical or chemical changes?','["Chemical changes, because a new substance is formed.","Physical changes, because the substance remains chemically the same.","Neither, they are a magical change.","Both at the same time."]',1,'Ice, water, and steam are all just H2O!','Changes of state are physical changes because the substance remains chemically the same.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_012','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'What causes a change of state to happen?','["Painting the object","Gaining or losing thermal energy (heating or cooling)","Moving the object to a dark room","Breaking the object with a hammer"]',1,'You have to add heat or take heat away!','Matter commonly exists as a solid, liquid or gas. A change of state happens... usually because it gains or loses thermal energy.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_013','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'In the water cycle, what happens during ''evaporation''?','["Water falls from the clouds as rain.","Water vapour cools and forms clouds.","The Sun warms water in oceans and rivers, turning it into water vapour.","Water freezes into a glacier."]',2,'The sun pulls the liquid water up into the air as a gas.','Evaporation: The Sun warms water in oceans, lakes and rivers. Some liquid water becomes water vapour.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_014','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'In the water cycle, what happens during ''condensation''?','["Water freezes solid on a mountain.","Water falls from the clouds as rain.","Water vapour cools and forms tiny droplets, helping clouds develop.","The Sun warms the ocean."]',2,'The invisible gas turns back into liquid drops to make clouds.','Condensation: Water vapour cools and forms tiny droplets or ice crystals, helping clouds develop.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_015','Chemistry','Changes of State','Topic 3: Changes of State','Primary',1,'At what temperature does pure water freeze at standard atmospheric pressure?','["100°C","0°C","50°C","200°C"]',1,'Zero is the freezing point!','For pure water at standard atmospheric pressure, the freezing point is approximately 0°C.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_016','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Why is ''melting'' considered a physical change rather than a chemical change?','["Because the ice disappears completely.","Because the substance (water) only changes its state (from solid to liquid) and does not form a new chemical substance.","Because melting is completely irreversible.","Because melting creates carbon dioxide gas."]',1,'Ice is just frozen water; it''s exactly the same ''stuff''!','Changes of state are physical changes because the substance remains chemically the same. Example: Ice melting... Why? Solid water becomes liquid water.','2026-11-01 08:35:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_017','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'How does adding thermal energy (heat) cause a solid to melt into a liquid?','["The heat creates new particles.","The heat gives the particles more energy to vibrate strongly until they can move past one another and flow.","The heat freezes the particles in place.","The heat makes the particles shrink."]',1,'Heating makes the tightly packed pieces shake until they break loose!','As a solid is heated, its particles vibrate more strongly. At the melting point, the particles can move past one another, so the solid becomes a liquid.','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_018','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'How does removing thermal energy (cooling) cause a liquid to freeze into a solid?','["The cooling makes the particles move faster.","The cooling causes the particles to lose energy, move less energetically, and settle into fixed, vibrating positions.","The cooling turns the particles into a gas.","The cooling destroys the particles completely."]',1,'Taking away heat slows the pieces down until they get stuck together!','As a liquid cools, its particles move less energetically. When freezing occurs, they settle into positions where they can mainly vibrate rather than move freely...','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_019','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'What is a key difference between ''evaporation'' and ''boiling''?','["Evaporation happens to solids; boiling happens to liquids.","Evaporation only happens at the surface and can occur at any temperature; boiling happens throughout the entire liquid and forms bubbles at a specific temperature.","Evaporation is a chemical change; boiling is a physical change.","Evaporation forms bubbles; boiling only happens at the surface."]',1,'A puddle evaporates slowly, but a pot of water on a stove boils rapidly with bubbles!','Evaporation... Happens at the liquid''s surface. Can occur at many temperatures... Boiling... Happens throughout the liquid. Occurs at the boiling point... Produces bubbles...','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_020','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'If you want wet clothes to dry (evaporate) faster on a clothesline, what conditions would help?','["Freezing temperatures, still air, and high humidity.","Warm temperatures, moving air (wind), and low humidity.","Keeping the clothes bunched up in a tight ball.","Drying them in the dark."]',1,'Warm, windy, dry days are the best for drying laundry!','Evaporation usually happens faster when: The temperature is higher. More of the liquid''s surface is exposed. Air moves across the surface. The surrounding air is less humid.','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_021','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Why do water droplets form on the outside of a cold glass of water on a warm day?','["Because the glass is leaking.","Because invisible water vapor (gas) in the warm room air hits the cold glass, cools down, and condenses into liquid droplets.","Because the ice inside the glass melts and jumps out.","Because the glass absorbs water from the table."]',1,'The water comes from the air in the room, not from inside the cup!','Why does a cold glass become wet? Air around the glass contains invisible water vapour. The glass cools the nearby air. Some water vapour condenses into liquid droplets...','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_022','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Why does sweating help cool down the human body?','["Because sweat is made of ice.","Because as the sweat evaporates (liquid to gas), it removes energy (heat) from the skin, leaving the body cooler.","Because sweat creates a chemical reaction that freezes the blood.","Because sweat reflects sunlight."]',1,'The heat from your skin goes into the water to turn it into a gas, taking the heat away with it!','Evaporation removes some of the faster-moving particles from the liquid. This can cool the remaining liquid, which is one reason sweat helps cool our bodies.','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_023','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'If you see a white cloud above a boiling kettle, why is it scientifically inaccurate to call it pure ''steam''?','["Because steam is always black.","True steam (water vapor) is an invisible gas; the white cloud you see is actually tiny droplets of liquid water that have already condensed in the cooler air.","Because the cloud is made of smoke from the kettle burning.","Because true steam is a solid block of ice."]',1,'If you can see it, it has already turned back into a liquid mist!','Is steam the same as the white cloud above a kettle? Not exactly. Water vapour is a colourless gas. The white cloud... is made mainly of tiny liquid water droplets formed when hot water vapour cools and condenses...','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_024','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'What happens to the temperature of a pure substance exactly while it is melting or freezing (e.g., a cup of ice water)?','["The temperature goes up very quickly.","The temperature remains approximately constant until the change of state is completely finished.","The temperature drops to absolute zero.","The temperature changes wildly every second."]',1,'While ice is melting in water, the whole glass stays at exactly 0°C until all the ice is gone!','During a change of state, the energy transferred changes the arrangement... For a pure substance changing state at constant pressure, the temperature remains approximately constant until that change is complete.','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_025','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'How does ''sublimation'' differ from normal melting?','["Sublimation makes things colder, melting makes things hotter.","In sublimation, a solid turns directly into a gas, completely skipping the liquid phase.","Sublimation is a chemical change, melting is a physical change.","Sublimation only happens to water."]',1,'Dry ice doesn''t melt into a puddle; it just disappears into a gas!','Sublimation is the change from a solid directly into a gas without first becoming a liquid.','2026-11-01 08:35:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_026','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Why should you never touch dry ice (solid carbon dioxide) with your bare hands?','["Because it is extremely hot and will burn you.","Because it is extremely cold and can cause severe damage (frostbite) to your skin.","Because it will instantly turn your hands into a gas.","Because it is covered in poisonous liquid."]',1,'It is much, much colder than regular ice!','Safety: Dry ice is extremely cold and can injure skin. Never touch it with bare hands or handle it without trained adult supervision.','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_027','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'In the water cycle, what role does ''precipitation'' play after condensation?','["It turns the water back into a gas.","It is the process where the condensed water in the clouds falls back to Earth as rain, snow, or hail.","It is the process of the sun warming the oceans.","It is the process of water soaking into the ground."]',1,'After the clouds get heavy with condensed water, they drop it back to the ground!','Precipitation: Water falls from clouds as rain, snow or other forms of precipitation.','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_028','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Why does chocolate become soft and messy if you leave it in your pocket on a warm day?','["Because chocolate is a liquid.","Because your body heat transfers thermal energy to the solid chocolate, causing it to reach its melting point and change into a liquid state.","Because the chocolate is undergoing a chemical change.","Because chocolate evaporates easily."]',1,'Your body heat is high enough to melt the cocoa butter in the chocolate!','Melting... Examples: Chocolate softening and melting when warmed.','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_029','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'If you put liquid water in a freezer, why does it eventually become solid ice?','["The freezer adds ''cold energy'' to the water.","The freezer removes thermal energy from the liquid water, slowing the particles down until they lock into a solid structure (freezing).","The freezer adds air pressure to crush the water.","The freezer turns the water into a gas first."]',1,'You can''t add ''cold''; you can only take away heat!','Freezing occurs when a liquid loses thermal energy and becomes a solid... When freezing occurs, they settle into positions where they can mainly vibrate...','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_030','Chemistry','Changes of State','Topic 3: Changes of State','Primary',5,'Is burning a piece of wood a physical change like melting ice? Why or why not?','["Yes, because the wood just gets hot.","No, burning wood is a chemical change because the wood reacts with oxygen to form entirely new substances (like ash and smoke).","Yes, because you can easily turn the smoke back into wood.","No, because burning wood is a change of state."]',1,'You can melt ice and freeze it back into water, but you can''t un-burn a pile of ash!','Wood burning: Chemical. New substances form... A physical change may be reversible... reversibility alone does not determine...','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_031','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Critique the assertion that ''Evaporation and Boiling are identical because they both turn liquid into gas.''','["The assertion is completely accurate in physical chemistry.","The assertion conflates the end result with the physical mechanism. Evaporation is a surface-level phenomenon occurring at any temperature, driven by high-energy particles escaping. Boiling is a bulk, systemic phenomenon occurring only when vapor pressure equals atmospheric pressure, forming gas bubbles throughout the liquid volume.","They are different because evaporation only happens in the dark.","They are different because boiling creates a chemical change, while evaporation is a physical change."]',1,'A puddle dries up without ever bubbling; a pot of water on the stove bubbles vigorously!','Evaporation and boiling: what is the difference? Evaporation: Happens at the liquid''s surface. Can occur at many temperatures... Boiling: Happens throughout the liquid. Occurs at the boiling point...','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_032','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Analyze the kinetic relationship between ''Latent Heat'' and the temperature plateau during a phase change.','["Latent heat causes the temperature to spike randomly.","During a phase change (e.g., melting), added thermal energy (latent heat) does not increase the kinetic energy (temperature) of the particles. Instead, the energy is entirely consumed to break the intermolecular bonds holding the solid lattice together, maintaining a constant temperature until the phase change is complete.","Latent heat causes the object to freeze while being heated.","Latent heat proves that thermometers do not work during melting."]',1,'While ice is melting in a glass, all the heat goes into breaking the ice, not warming the water, so the glass stays exactly at 0°C!','During a change of state, the energy transferred changes the arrangement and interactions of particles. For a pure substance changing state at constant pressure, the temperature remains approximately constant until that change is complete.','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_033','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Synthesize how the concept of ''Sublimation'' relates to the atmospheric pressure at a substance''s Triple Point.','["Sublimation occurs when pressure is extremely high.","Sublimation occurs when the ambient atmospheric pressure is below the substance''s ''triple point'' pressure. Under these low-pressure conditions, the liquid phase cannot thermodynamically exist; thus, adding thermal energy forces the solid lattice to shatter directly into a gaseous state, bypassing liquefaction.","Sublimation only occurs in a perfect vacuum.","Sublimation proves that atmospheric pressure has no effect on phase changes."]',1,'Dry ice skips the liquid phase because normal Earth pressure isn''t high enough to hold liquid carbon dioxide together!','Sublimation is the change from a solid directly into a gas without first becoming a liquid. An example is dry ice... Under ordinary atmospheric conditions, it changes directly...','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_034','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Evaluate the physical mechanics of why ''moving air'' (wind) accelerates the rate of Evaporation.','["Wind creates friction that boils the water.","Evaporation creates a localized boundary layer of high-humidity air (vapor) directly above the liquid surface, which suppresses further evaporation. Wind continuously strips away this saturated boundary layer, replacing it with dry air and maintaining a steep vapor pressure gradient that maximizes the evaporation rate.","Wind freezes the water, forcing it to turn into a gas.","Wind increases the mass of the water particles."]',1,'Blowing on a wet shirt sweeps away the damp air sitting right on top of the fabric, letting more water escape!','Evaporation usually happens faster when: ... Air moves across the surface. The surrounding air is less humid.','2026-11-01 08:35:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_035','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Analyze the source of the ''white cloud'' often observed when using Dry Ice.','["The cloud is purely carbon dioxide gas.","The white cloud is a secondary condensation effect. Dry ice sublimes into extremely cold, invisible \\\\(CO_2\\\\) gas. This freezing gas rapidly cools the ambient air, forcing the invisible atmospheric water vapor to condense into an aerosol of visible, microscopic liquid water droplets (a mist).","The cloud is actually smoke from the dry ice burning.","The cloud is a chemical reaction between plastic and ice."]',1,'You aren''t seeing the carbon dioxide; you are seeing the water in the air freezing into fog because the carbon dioxide is so cold!','The white cloud often seen near dry ice is mainly tiny water droplets formed from moisture in the surrounding air; carbon dioxide gas itself is invisible.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_036','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Synthesize the thermodynamic principle of ''Evaporative Cooling'' as a biological survival mechanism (sweating).','["Sweating works by covering the skin in cold ice.","Evaporation is an endothermic process; the highest-kinetic-energy molecules escape into the gas phase, lowering the *average* kinetic energy (temperature) of the remaining liquid. By secreting sweat, the human body uses this latent heat of vaporization to actively extract massive amounts of thermal energy from the skin, preventing hyperthermia.","Sweating works by absorbing heat from the sun.","Sweating proves that human bodies generate a vacuum."]',1,'The hottest water molecules fly away into the air, leaving only the cooler ones behind on your skin!','Evaporation removes some of the faster-moving particles from the liquid. This can cool the remaining liquid, which is one reason sweat helps cool our bodies.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_037','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Critique the assertion that ''Boiling Point is an absolute, unchanging temperature for any liquid.''','["The assertion is perfectly true; water always boils at 100°C.","The assertion is false because boiling point is highly dependent on ambient atmospheric pressure. Boiling occurs when vapor pressure equals atmospheric pressure. At high altitudes (lower atmospheric pressure), the vapor pressure required is lower, meaning liquids will boil at a significantly lower temperature than at sea level.","The assertion is false because boiling point depends on the color of the pot.","The assertion is true because pressure only affects solids."]',1,'On top of Mount Everest, water boils before it even gets hot enough to cook pasta properly!','Pure water boils at approximately 100°C at standard atmospheric pressure. The boiling point changes when the pressure changes, such as at high altitudes.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_038','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Evaluate why ''Reversibility'' is an insufficient metric for definitively classifying a Physical Change.','["Because physical changes are completely irreversible.","While many physical changes (melting/freezing) are easily reversible, some physical changes (like shattering glass or grinding a log into sawdust) are practically irreversible. The definitive classification rests not on reversibility, but strictly on whether the molecular structure was altered to synthesize a novel chemical substance.","Because chemical changes are the only changes that can be reversed.","Because reversibility only applies to gases."]',1,'You can''t un-smash a window, but the broken pieces are still glass, not a new chemical!','A physical change may be reversible... However, reversibility alone does not determine whether a change is physical or chemical.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_039','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Analyze the specific interaction between ''Humidity'' and ''Condensation'' on a cold surface.','["High humidity prevents condensation from occurring.","Humidity is a measure of ambient atmospheric water vapor. A cold surface extracts thermal energy from adjacent air, lowering its temperature below the ''dew point'' where the air can no longer hold the vapor. High humidity provides an abundant source of vapor, rapidly accelerating the rate of condensation on the cold surface.","Humidity causes the glass to melt, not condense.","Humidity turns the cold glass into a gas."]',1,'On a very dry day, a cold glass won''t sweat much because there isn''t enough water in the air to grab onto it!','Air around the glass contains invisible water vapour. The glass cools the nearby air. Some water vapour condenses into liquid droplets on the outside.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_040','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Synthesize how the ''Water Cycle'' acts as a massive, solar-powered distillation and redistribution engine.','["The water cycle relies on underground fires to boil the ocean.","The Sun provides the thermal energy to evaporate (distill) surface water, leaving impurities behind as the vapor rises. Atmospheric cooling forces condensation into clouds, which are then transported by wind currents before precipitating, effectively redistributing purified freshwater across global terrestrial ecosystems.","The water cycle uses magnets to pull water into the sky.","The water cycle proves that oceans never lose any water."]',1,'The sun acts like a giant pump, lifting fresh water out of the salty ocean and dropping it on the land as rain!','Evaporation: The Sun warms water in oceans... Condensation: Water vapour cools and forms tiny droplets... Precipitation: Water falls from clouds... The water cycle moves water around Earth and helps supply freshwater...','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_041','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Critique the everyday observation that a ''cloud'' is a gas.','["The observation is scientifically perfect.","The observation is an optical fallacy. A true gas (like water vapor) is typically transparent and invisible at the macroscopic level. A cloud is actually a dense colloidal suspension (an aerosol) of liquid water droplets or solid ice crystals that are large enough to scatter visible light, making them opaque/white.","A cloud is actually a solid block of ice.","A cloud is a chemical reaction between air and sunlight."]',1,'If you can see it, it is not water vapor; it has already condensed back into liquid or solid form!','Condensation: Water vapour cools and forms tiny droplets or ice crystals, helping clouds develop... (Synthesis: Clouds are droplets/crystals, not gas).','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_042','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Analyze how the ''Particle Model'' explains why liquids are largely incompressible compared to gases.','["Liquids are incompressible because their particles are made of steel.","In a liquid, the particles have enough kinetic energy to break rigid lattice bonds and flow, but the intermolecular attractive forces still keep the particles in close, virtually touching proximity. Because there is negligible void space between the particles, applying pressure cannot force them significantly closer together.","Liquids are incompressible because they are completely frozen.","Liquids actually are highly compressible."]',1,'You can''t squeeze the liquid in a syringe because the particles are already shoulder-to-shoulder!','Liquid... Particles close together: The particles remain close to one another... Easily compressed? Usually very little. (Contrasted with gases which are widely spaced).','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_043','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Synthesize the thermodynamic transition required for ''Freezing'' to occur in a pure liquid.','["Freezing requires adding cold energy to the liquid.","Freezing is an exothermic phase transition. The liquid must continuously transfer its internal thermal energy (latent heat) to a cooler external environment. As kinetic energy drops, intermolecular attractive forces dominate, forcing the chaotic fluid particles to lock into a structured, low-energy rigid lattice.","Freezing requires boiling the liquid first.","Freezing occurs instantly when a liquid touches glass."]',1,'The liquid has to give away its heat to the freezer until the particles slow down enough to get stuck together!','Freezing occurs when a liquid loses thermal energy and becomes a solid... When freezing occurs, they settle into positions where they can mainly vibrate rather than move freely past one another.','2026-11-01 08:35:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_044','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Evaluate the assertion that ''A physical change never breaks chemical bonds.''','["The assertion is entirely false; melting breaks all chemical bonds.","The assertion is accurate regarding intramolecular bonds (the bonds holding a molecule together, like the H-O bonds in water). A physical change only overcomes the weaker intermolecular forces (bonds between separate molecules), altering the physical state or shape without destroying the fundamental molecular identity of the substance.","The assertion is false because physical changes destroy the atoms.","The assertion is true because chemical bonds do not exist."]',1,'Melting ice just pulls the H2O molecules away from each other; it doesn''t rip the H away from the O!','Changes of state are physical changes because the substance remains chemically the same. Example: Ice melting... Solid water becomes liquid water.','2026-11-01 08:35:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes_global_045','Chemistry','Changes of State','Topic 3: Changes of State','Primary',10,'Analyze the role of ''Surface Area'' in the rate of evaporation.','["Surface area has no effect on evaporation.","Evaporation is exclusively a surface phenomenon where high-energy particles escape the liquid phase. Increasing the surface area directly increases the number of molecules exposed to the atmosphere interface, proportionally increasing the statistical probability of particles escaping, thus accelerating the overall evaporation rate.","Increasing surface area stops evaporation completely.","Evaporation only happens at the bottom of a liquid."]',1,'A cup of water takes days to dry up, but if you spill that same cup across the floor, it dries in an hour!','Evaporation usually happens faster when: ... More of the liquid''s surface is exposed.','2026-11-01 08:35:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_001','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What is a ''material''?','["A type of animal","A type of matter used to make an object","A kind of energy","A type of weather"]',1,'Wood, metal, and plastic are examples.','A material is a type of matter used to make an object.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_002','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What is a ''property'' in chemistry?','["Who owns the object","A characteristic that helps describe a material","How much an object costs","Where an object was made"]',1,'Color, hardness, and flexibility are examples.','A property is a characteristic that helps describe a material.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_003','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What property describes a material that allows you to see clearly through it?','["Opaque","Transparent","Hardness","Flexibility"]',1,'Clear window glass has this property.','Transparent: Lets most light pass through so objects can be seen clearly.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_004','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What property describes a material that does NOT let light pass through it?','["Opaque","Translucent","Transparent","Elastic"]',0,'A solid wooden door is opaque.','Opaque: Does not let light pass through in the ordinary way.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_005','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What property describes how easily a material can bend without breaking?','["Strength","Hardness","Flexibility","Absorbency"]',2,'A rubber strip is flexible.','Flexibility: The ability to bend without breaking.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_006','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What property describes a material''s ability to return to its original shape after being stretched?','["Hardness","Elasticity","Opacity","Solubility"]',1,'A rubber band is elastic.','Elasticity: The ability to return towards its original shape after a force is removed.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_007','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What does it mean if a material is ''absorbent''?','["It reflects all light.","It takes in (soaks up) liquid.","It blocks electricity.","It repels water completely."]',1,'A paper towel or a sponge is highly absorbent.','Absorbency describes how readily a material takes in liquid.','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_008','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What does it mean if a material is ''waterproof''?','["It acts like a sponge.","It resists water passing through it.","It dissolves in water.","It turns water into ice."]',1,'A raincoat is waterproof.','A waterproof material resists water passing through it...','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_009','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What does it mean if a material is ''soluble'' in water?','["It sinks to the bottom.","It floats on the top.","It dissolves in the water.","It turns the water into a solid."]',2,'Salt and sugar are soluble in water.','Solubility describes how well a substance dissolves in a particular liquid. Soluble: Sugar dissolves in water...','2026-11-01 08:47:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_010','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What is a ''thermal conductor''?','["A material that stops heat from moving.","A material that allows heat to pass through it relatively easily.","A material that turns heat into cold.","A material that changes color."]',1,'Metal cooking pots are good thermal conductors.','Conductors and insulators... Metals usually conduct heat well...','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_011','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'What is an ''electrical insulator''?','["A material that creates electricity.","A material that strongly resists the flow of electricity.","A material that conducts electricity perfectly.","A material that acts like a battery."]',1,'Rubber and plastic are insulators used to cover wires.','Electrical insulators: Materials that strongly resist the movement of electric charge.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_012','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'Which of these materials is typically attracted to a magnet?','["Wood","Plastic","Iron","Glass"]',2,'Metals like iron are magnetic.','Magnetic materials: Iron and many types of steel are attracted to magnets.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_013','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'Why are windows usually made of glass?','["Because glass is soft.","Because glass has the property of being transparent.","Because glass is highly absorbent.","Because glass conducts electricity."]',1,'You want to be able to see through a window!','Window: Common material - Glass. Useful property - Transparent.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_014','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'Why are cooking pots usually made of metal?','["Because metal is transparent.","Because metal is a good conductor of heat.","Because metal is a good insulator.","Because metal melts easily."]',1,'You want the heat to travel from the stove to your food quickly.','Cooking pot: Common material - Metal. Useful property - Conducts heat well.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_015','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',1,'Which of these is an example of an ''insoluble'' material (it does not dissolve in water)?','["Sugar","Salt","Sand","Honey"]',2,'The sand will just sit at the bottom of the glass.','Insoluble: Sand does not dissolve appreciably in water under ordinary conditions.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_016','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why is ''hardness'' not the same thing as ''strength'' in materials?','["Because hardness is for liquids and strength is for solids.","Hardness means a material resists scratching (like glass), but it might lack strength and be brittle (like glass shattering when dropped).","Hardness and strength are exactly the same thing.","Hardness means a material can bend easily."]',1,'A diamond is the hardest natural material, but you can still smash it with a hammer (low strength)!','Hardness and strength are not the same. A material can be hard but brittle. Glass, for example, resists many scratches but can shatter when struck.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_017','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why is a rubber band considered ''elastic'', but a piece of aluminum foil is only ''flexible''?','["Because aluminum foil is heavier than rubber.","Because aluminum foil bends easily (flexible) but stays bent, while a rubber band bends and then snaps back to its original shape (elastic).","Because aluminum foil is completely rigid.","Because rubber is actually a metal."]',1,'Flexibility is bending; elasticity is bouncing back!','A material can be flexible without being highly elastic. A thin sheet of metal may bend and remain bent, while an elastic band tends to return to its previous shape.','2026-11-01 08:47:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_018','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why are electrical wires made with a copper core but covered in a plastic or rubber coating?','["To make the wires look pretty.","Copper is a conductor that allows electricity to flow, while the plastic is an insulator that protects people from electric shocks and prevents short circuits.","Copper is an insulator and plastic is a conductor.","Both copper and plastic are excellent conductors."]',1,'The electricity travels through the inside metal, and the outside rubber keeps it trapped safely!','Electrical wires use a metal conductor surrounded by insulation to reduce the risk of electric shock... Wire covering: Plastic or rubber - Electrical insulation.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_019','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why is ''frosted glass'' considered translucent instead of transparent?','["Because frosted glass is completely black.","Frosted glass lets some light through, but it scatters the light so you cannot see a clear, sharp image through it.","Because frosted glass reflects all light like a mirror.","Because frosted glass blocks 100% of the light."]',1,'You can tell if a light is on behind frosted glass, but you can''t read a book through it!','Translucent: Lets some light through, but objects cannot be seen clearly. Example: Frosted glass.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_020','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'If you are designing a raincoat, which two properties are the most important to consider?','["Heavy weight and high absorbency","Water resistance (waterproof) and flexibility","Transparency and brittleness","High electrical conductivity and magnetism"]',1,'You want a raincoat to keep you dry (waterproof) and allow you to walk (flexible)!','Raincoat: Waterproof-coated fabric - Resists water. (It must also be flexible so you can move while wearing it).','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_021','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'How can a strong magnet be used in a recycling plant?','["To melt down plastic bottles.","To use magnetism to easily separate iron and steel objects from a mixture of non-magnetic waste like plastic and glass.","To freeze water inside cans.","To crush wooden boxes."]',1,'A giant magnet can pull all the steel cans out of a pile of garbage instantly!','Magnetism can help separate iron or steel objects from mixtures of other materials.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_022','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'What is the key difference between a ''physical property'' and a ''chemical property''?','["Physical properties are for solids, chemical properties are for liquids.","A physical property can be observed without changing the substance (like color), while a chemical property describes how a substance reacts to form entirely new substances (like rusting).","Physical properties are invisible, chemical properties are visible.","There is no difference; they mean the same thing."]',1,'Color is a physical property; flammability (burning) is a chemical property!','A physical property can be observed or measured without changing a substance into a different substance... A chemical property describes how a substance can react to form new substances.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_023','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'If you want to test which type of paper towel is the most absorbent, why must you use the ''same size piece'' of each towel?','["Because different sizes have different colors.","To make it a ''fair test''; if one piece is much larger, it will naturally hold more water, ruining your ability to compare the materials fairly.","Because you can only use small amounts of water.","Because large pieces of paper explode."]',1,'If you change the size of the towel AND the brand of the towel, you don''t know which factor caused the result!','For a fair comparison, use similar-sized samples, the same amount of water and the same waiting time.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_024','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why is it important to know that solubility ''depends on the substance and the liquid''?','["Because all liquids are exactly the same.","Because a substance (like salt) might dissolve perfectly in water, but completely fail to dissolve in cooking oil.","Because solubility only works in the dark.","Because all solids dissolve in all liquids."]',1,'Water and oil act very differently as solvents!','Solubility depends on the substance and the liquid. A substance that dissolves in water may not dissolve in oil.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_025','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why do the handles of cooking pots often have plastic or wood coatings on them?','["To make the pot heavier.","Because wood and plastic are thermal insulators; they conduct heat poorly, preventing the heat of the stove from burning your hand.","Because plastic is a better thermal conductor than metal.","To make the pot magnetic."]',1,'The metal pot gets incredibly hot; the plastic handle protects you!','Handles may be made from materials that conduct heat less easily, helping reduce heat transfer to the user''s hand.','2026-11-01 08:47:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_026','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'If an object is described as ''opaque'', what will happen if you shine a flashlight at it?','["The light will pass straight through clearly.","The light will pass through but look blurry.","The object will not let the visible light pass through; it will block it or reflect it.","The object will turn completely invisible."]',2,'An opaque object will cast a shadow because it blocks the light!','Opaque: Does not let light pass through in the ordinary way.','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_027','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'What property is essential for a material used to make a reusable water bottle?','["High absorbency","Water resistance (waterproof) and durability","High electrical conductivity","High magnetism"]',1,'If the bottle absorbs water, it will become a soggy mess!','Reusable water bottle: Stainless steel, glass or suitable plastic - Durability and suitability for holding water.','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_028','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Why is copper a poor choice for building a boat, even if it is strong?','["Because copper is too flexible.","Because copper is a heavy metal and expensive, and other materials (like fiberglass or steel) offer better properties for large boat hulls.","Because copper dissolves instantly in water.","Because copper is a gas."]',1,'You have to balance all the properties, including how much it costs!','The best material depends on the object''s purpose, safety, cost, durability and environmental impact.','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_029','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'Is the ''colour'' of a metal spoon a physical property or a chemical property?','["A chemical property, because color can never change.","A physical property, because you can observe it without changing the spoon into a new chemical substance.","A chemical property, because color requires a chemical reaction to see.","Neither; color is an illusion."]',1,'Just looking at it doesn''t change what it is made of!','A physical property can be observed or measured without changing a substance into a different substance. Examples include colour, density, hardness...','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_030','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',5,'If iron develops rust over time, what kind of property does this demonstrate?','["A physical property.","A chemical property, because the iron is reacting with oxygen to form a new substance (rust).","An electrical property.","A magnetic property."]',1,'Rusting permanently changes the iron into something new!','A chemical property describes how a substance can react to form new substances. For example... Iron''s ability to react with oxygen and moisture to form rust is a chemical property.','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_031','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Critique the assertion that ''Glass is a completely rigid material with no elasticity.''','["The assertion is true; glass can never bend or bounce.","The assertion is scientifically false. While macroscopic glass appears highly rigid and brittle, at microscopic levels or in specific geometries (like optical fibers or thin glass sheets), glass exhibits measurable flexibility and perfect elasticity until it reaches its breaking point.","Glass is actually a highly viscous liquid, not a solid.","Glass is only rigid when it is painted black."]',1,'A giant window pane won''t bend, but a tiny thread of glass (fiber optic) can bend into a circle without snapping!','Hardness and strength are not the same. A material can be hard but brittle. Glass, for example, resists many scratches but can shatter when struck. (Synthesis: However, thin glass like fiber optics can bend, showing flexibility).','2026-11-01 08:47:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_032','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Analyze how the concept of ''Alloying'' (mixing metals) addresses the limitations of pure materials.','["Alloying makes metals invisible.","Pure metals often have severe limitations (e.g., pure iron rusts easily and is relatively soft). By alloying (mixing) iron with carbon and chromium, metallurgists synthesize ''stainless steel'', combining the strength of iron with extreme chemical resistance to oxidation (rust).","Alloying turns solid metals into permanent gases.","Alloying prevents metals from ever conducting electricity."]',1,'Pure gold is so soft you can bend it with your hands; they mix it with silver or copper to make hard jewelry!','The best material depends on the object''s purpose, safety, cost, durability... (Synthesis: If pure iron has a bad chemical property (rusting), scientists mix it to change that property).','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_033','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Synthesize the relationship between ''Electrical Conductivity'' and ''Thermal Conductivity'' in metals.','["Metals conduct electricity well, but block heat perfectly.","In metals, the same physical mechanism—a ''sea of delocalized electrons'' that are free to move throughout the atomic lattice—facilitates both electrical and thermal conductivity. Therefore, excellent electrical conductors (like copper or silver) are almost universally excellent thermal conductors.","Metals conduct heat well, but block electricity perfectly.","There is no relationship between heat and electricity in metals."]',1,'The same tiny particles that carry the electric shock also carry the heat from the stove!','Metal: Often strong and able to conduct heat and electricity... Conductors and insulators: Metals such as copper are good electrical conductors. Metals usually conduct heat well...','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_034','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Evaluate the environmental trade-off of engineering plastics with extremely high ''Durability'' and ''Water Resistance''.','["These properties make plastics instantly biodegradable.","The very properties that make plastics highly desirable for packaging and containers (extreme durability, chemical inertness, and water resistance) make them an ecological disaster. Because they resist natural chemical and biological degradation, they persist in the environment for centuries as pollution.","These properties cause plastics to turn into water.","These properties make plastics highly magnetic."]',1,'A plastic bottle is great because it never leaks, but that also means it sits in a landfill for 500 years without breaking down!','The best material depends on the object''s purpose, safety, cost, durability and environmental impact. (Synthesis: High durability means it never rots or goes away).','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_035','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Analyze the mechanical distinction between ''Elasticity'' and ''Plasticity'' (deformation) when bending a metal paperclip.','["They are exactly the same concept.","When you bend a paperclip slightly, it springs back (elasticity). However, if you bend it past its ''yield point'', the atomic structure permanently deforms and stays bent. This permanent, non-reversible deformation without breaking is called plasticity or malleability.","Elasticity means it stays bent; plasticity means it snaps back.","Metals only have elasticity and never stay bent."]',1,'Rubber bands bounce back; paperclips stay bent. That permanent bend is ''plasticity''!','A material can be flexible without being highly elastic. A thin sheet of metal may bend and remain bent, while an elastic band tends to return to its previous shape.','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_036','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Synthesize how ''Translucent'' materials manipulate light compared to ''Transparent'' materials at the microscopic level.','["Translucent materials absorb all the light, making it dark.","Transparent materials have a uniform atomic structure that transmits light rays in a straight, parallel line, preserving the image. Translucent materials have microscopic structural irregularities (like frosting or internal boundaries) that randomly scatter the light rays in multiple directions, diffusing the light and destroying the image coherence.","Transparent materials scatter light, while translucent materials keep it straight.","Translucent materials only allow red light to pass through."]',1,'Imagine throwing a handful of bouncy balls at a flat wall (they bounce straight back) versus a rocky cliff (they bounce crazily everywhere)!','Transparent: Lets most light pass through so objects can be seen clearly. Translucent: Lets some light through, but objects cannot be seen clearly... (Synthesis: This happens because the light is scattered).','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_037','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Critique the use of ''Solubility'' testing as a definitive method for identifying an unknown white powder.','["Solubility in water immediately proves exactly what the chemical is.","While solubility is a useful physical property, it is not definitive. Many distinct chemical compounds (e.g., sugar, salt, baking soda) are all highly soluble in water and produce clear solutions. Definitive identification requires synthesizing multiple physical and chemical property tests (like melting point or reactivity).","Solubility only works on liquids, not powders.","Solubility testing destroys the chemical permanently."]',1,'If you stir white powder into water and it dissolves, it could be sugar (safe) or salt (safe) or a deadly poison! You need more tests.','Solubility describes how well a substance dissolves in a particular liquid... A physical property can be observed... Understanding both types of properties helps scientists identify materials...','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_038','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Evaluate the physical mechanics of a ''Waterproof'' fabric (like Gore-Tex) that is also ''Breathable''.','["It uses magic to only let water move in one direction.","Breathable waterproof fabrics utilize a microporous membrane. The microscopic pores are specifically sized to be physically smaller than a droplet of liquid water (preventing rain from entering), but significantly larger than an individual molecule of water vapor (allowing evaporated sweat gas to escape).","It has giant holes that let everything through.","It uses electricity to shock the water away."]',1,'The holes in the jacket are too small for a rain drop, but big enough for invisible steam to sneak out!','Water-resistant materials: Waterproof-coated fabrics and some plastics help keep water out. (Synthesis: How can a raincoat keep rain out but let sweat escape? Pore size!).','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_039','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Analyze how the ''Absorbency'' of a sponge relies on capillary action and physical structure.','["A sponge absorbs water because it is chemically identical to water.","A sponge''s absorbency is a physical phenomenon, not a chemical one. The sponge''s structure features a vast network of interconnected, microscopic voids (pores). Water is drawn into these voids via capillary action (adhesion to the sponge walls and cohesion to itself), displacing the air and holding the liquid.","A sponge uses magnetism to pull water inside.","A sponge turns water into a solid block of ice."]',1,'The water climbs into all the tiny empty air holes inside the sponge!','Absorbent materials: Paper towels, cotton towels and sponges can absorb water... A sponge, for example, is a solid that can be compressed because it contains many small spaces.','2026-11-01 08:47:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_040','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Synthesize why understanding ''Chemical Properties'' is vital for safe materials engineering (e.g., choosing pipes for drinking water).','["Chemical properties only matter if you want the pipes to change color.","Engineers must know the chemical properties (reactivity) of materials to ensure safety. For example, lead was historically used for water pipes because of its excellent physical properties (malleability), but its chemical property (toxicity and reactivity when corroding into drinking water) caused severe neurological poisoning.","Chemical properties are completely irrelevant to engineering.","Understanding chemical properties prevents the pipes from turning into gas."]',1,'A pipe might be physically strong, but if it chemically poisons the water flowing through it, it''s a terrible choice!','A chemical property describes how a substance can react to form new substances... The best material depends on the object''s purpose, safety, cost... and environmental impact.','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_041','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Critique the assertion that ''A material cannot be both an insulator and a conductor.''','["The assertion is a perfect law of physics.","The assertion is false because conductivity is a spectrum, and it depends on the context (thermal vs. electrical). While true that a material cannot simultaneously be a good electrical conductor and a good electrical insulator, semiconductors (like silicon) can act as insulators or conductors depending on applied voltage or temperature.","The assertion is false because all materials conduct electricity perfectly.","The assertion is true, but only in outer space."]',1,'Silicon (used in computer chips) is famous exactly because it can switch back and forth between being a conductor and an insulator!','Conductors and insulators: Some materials allow heat or electrical current to pass through them more easily than others... (Synthesis: Conductivity is not binary; it exists on a spectrum, and advanced materials manipulate this).','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_042','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Analyze how ''Density'' affects the structural engineering of aerospace vehicles (airplanes) compared to marine vehicles (ships).','["Density doesn''t matter because both vehicles use engines.","Aerospace engineering strictly requires materials with an extremely high ''strength-to-weight ratio'' (like titanium or carbon fiber) because high density (heavy) materials require too much energy to generate aerodynamic lift. Marine engineering can tolerate higher density materials (like solid steel) because oceanic buoyancy can support massive weights.","Airplanes require the heaviest materials to prevent floating away.","Ships require the lightest materials because water has no gravity."]',1,'You can build a boat out of heavy steel, but a steel airplane would need impossibly huge engines to fly!','Strength: Ability to withstand forces... The best material depends on the object''s purpose... (Synthesis: Heavy steel is fine for boats because water holds it up; airplanes need light, strong materials to fly).','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_043','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Synthesize the concept of ''Composite Materials'' (like fiberglass or reinforced concrete).','["Composite materials are just pure metals painted different colors.","Composites are engineered by physically combining two or more distinct materials to synthesize a new material that exhibits the best properties of both. For example, concrete provides extreme compressive strength (hardness), while embedded steel rebar provides tensile strength (flexibility/strength), preventing catastrophic shattering.","Composite materials combine two gases to make a solid.","Composite materials are perfectly pure elements found in nature."]',1,'Concrete is great at holding heavy weight, but terrible at bending. Steel is great at bending. Put them together, and you get a bridge that can do both!','An object can contain more than one material... (Synthesis: When engineers combine materials microscopically, like steel wires inside concrete, they create a ''Composite'').','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_044','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Evaluate the physical consequence of confusing a ''Chemical Property'' (flammability) with a ''Physical Property'' (state of matter) when handling compressed hydrogen gas.','["There are no consequences; hydrogen is completely inert.","Confusing them is lethal. While hydrogen is physically a colorless, odorless gas (a physical property making it seem harmless like air), its chemical property is extreme flammability and explosive reactivity with oxygen. Failing to account for its chemical properties in storage leads to catastrophic combustion.","It only matters because hydrogen turns into water instantly.","Hydrogen is a solid metal, so it cannot explode."]',1,'It might look and feel like normal air (physical), but if you light a match near it, it explodes (chemical)!','A physical property can be observed... without changing a substance... A chemical property describes how a substance can react to form new substances. Understanding both types of properties helps scientists identify materials and predict how they may behave.','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_materials_global_045','Chemistry','Materials and Their Properties','Topic 4: Materials and Their Properties','Primary',10,'Critique the design of a ''Thermal Flask'' using your knowledge of material properties.','["A thermal flask uses magnets to repel heat.","A thermal flask must combine multiple opposing material properties. It requires an inner layer with extremely low thermal conductivity (a vacuum or glass insulator) to prevent heat transfer, coupled with a durable, high-strength outer layer (like stainless steel or hard plastic) to protect the fragile internal vacuum chamber from mechanical shock.","A thermal flask uses pure copper to keep water hot.","A thermal flask relies entirely on chemical reactions to create heat."]',1,'You need something fragile (like glass or a vacuum) to stop the heat, but you need something strong (like metal) on the outside so it doesn''t break when you drop it!','An object can contain more than one material... Insulator: A material that resists the flow of electricity or heat... Strength: Ability to withstand forces... (Synthesis: The flask needs an insulator inside, and a strong material outside).','2026-11-01 08:47:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_001','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What is a ''substance''?','["A kind of matter with its own characteristic properties","A type of animal","A completely invisible gas","A type of energy"]',0,'It is a specific type of matter, like salt or sugar.','A substance is a kind of matter with its own characteristic properties. For example, water, oxygen, salt and sugar are different substances.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_002','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What is a ''pure substance''?','["A combination of many different things","Matter that contains only one kind of substance","A material that is very dirty","Any liquid you can drink"]',1,'It is 100% just one thing, like pure oxygen.','A pure substance contains only one kind of substance, rather than a combination of different substances.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_003','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Which of these is an example of a pure substance?','["Soil","Fruit salad","Pure oxygen gas","Saltwater"]',2,'It only has one ingredient.','In science, pure substances include elements such as oxygen and compounds such as pure water or pure sodium chloride.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_004','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What is a ''mixture''?','["A material that contains only one substance","Two or more substances combined without forming a new substance","A liquid that has frozen solid","A substance that has disappeared"]',1,'It''s like making a salad; the ingredients are together, but still themselves.','A mixture is made when two or more substances are combined without forming a new substance through a chemical reaction.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_005','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Which of these is an example of a mixture?','["Pure water","Pure sugar","Fruit salad","Pure salt"]',2,'You can see all the different fruits mixed together.','Fruit salad: Different fruits are mixed together. You can usually identify the individual pieces.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_006','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What is a ''uniform mixture'' (homogeneous)?','["A mixture where you can easily see all the different parts","A mixture that appears the same throughout, like salt water","A mixture that only contains solids","A mixture that is completely dry"]',1,'It looks like one single thing, like a glass of salty water.','A uniform mixture has the same appearance and composition throughout at the scale you can observe. The different substances may not be visible separately.','2026-11-01 08:48:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_007','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What is a ''non-uniform mixture'' (heterogeneous)?','["A mixture that looks exactly the same everywhere","A mixture where different parts or ingredients are visible, like soil","A mixture that contains only one pure substance","A mixture that is completely invisible"]',1,'You can pick out the different pieces, like pebbles in soil.','A non-uniform mixture does not have the same composition everywhere. Different parts may be visible...','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_008','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Which of these is a ''uniform'' mixture?','["Sand mixed with water","A bowl of mixed nuts","Salt dissolved in water","A salad"]',2,'The salt blends in perfectly so it looks like plain water.','Examples [of uniform mixtures]: Salt water after the salt has dissolved.','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_009','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Which of these is a ''non-uniform'' mixture?','["Air","Sugar dissolved in water","Soil containing stones and leaves","Pure oxygen"]',2,'You can easily see the stones mixed in the dirt.','Examples [of non-uniform mixtures]: ... Soil containing stones and leaves.','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_010','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What method can be used to separate large, visible objects from a mixture, like picking stones out of rice?','["Evaporation","Handpicking","Filtration","Melting"]',1,'You just use your fingers!','Handpicking: Large, visible pieces are removed by hand. Example: Removing small stones from rice.','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_011','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What method uses a tool with holes to separate larger particles from smaller ones, like stones from sand?','["Evaporation","Handpicking","Sieving","Boiling"]',2,'The sand falls through the holes, but the stones get caught.','Sieving: A sieve separates particles of different sizes. Example: Separating larger stones from finer sand.','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_012','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What method separates a solid that has NOT dissolved (like sand) from a liquid?','["Filtration","Evaporation","Melting","Freezing"]',0,'You pour it through a paper filter that catches the sand.','Filtration: A filter holds back certain solid particles while liquid passes through. Example: Separating sand from water.','2026-11-01 08:48:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_013','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'What method separates a dissolved solid (like salt) from a liquid?','["Handpicking","Sieving","Evaporation","Filtration"]',2,'You boil the water away, and the salt is left behind.','Evaporation: A liquid changes into a gas, leaving a dissolved solid behind. Example: Recovering salt from salt water.','2026-11-01 08:48:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_014','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Can you always tell if water is a pure substance just by looking at it?','["Yes, if it is clear, it is perfectly pure.","No, clear water can still contain dissolved invisible substances, like salt or minerals.","Yes, pure water is always bright blue.","No, pure water is always cloudy."]',1,'Saltwater looks exactly like pure water!','A material can look clean but still contain other substances... tap water usually contains small amounts of dissolved minerals... even when it looks completely clear.','2026-11-01 08:48:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_015','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',1,'Is air a pure substance or a mixture?','["A pure substance","A mixture of different gases","A solid","A liquid"]',1,'Air is made of oxygen, nitrogen, and other gases mixed together.','Air, which is a mixture of gases. (It is a uniform mixture).','2026-11-01 08:48:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_016','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is ''tap water'' usually considered a mixture rather than a pure substance?','["Because it is cloudy and dirty.","Because it comes from a tap.","Even though it looks clear, it usually contains small amounts of dissolved minerals and chemicals.","Because it contains solid rocks."]',2,'It''s mostly water, but there are invisible mineral particles mixed into it!','A material can look clean but still contain other substances. For example, tap water usually contains small amounts of dissolved minerals... even when it looks completely clear.','2026-11-01 08:48:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_017','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why does a fruit salad represent a ''non-uniform'' (heterogeneous) mixture?','["Because all the fruits melt together into a single liquid.","Because you can visibly distinguish the different types of fruit, and a spoonful from one side might have more grapes than a spoonful from the other side.","Because it is a pure substance.","Because fruit salad is invisible."]',1,'It looks different depending on which part of the bowl you look at!','Fruit salad: Different fruits are mixed together. You can usually identify the individual pieces. (A non-uniform mixture does not have the same composition everywhere).','2026-11-01 08:48:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_018','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'If you stir salt into water until it disappears, what kind of mixture have you created?','["A non-uniform mixture.","A pure substance.","A uniform (homogeneous) mixture, because the salt is evenly distributed and the liquid appears the same throughout.","A dry mixture."]',2,'It looks like one perfectly clear liquid, even though it''s actually two things mixed together!','Salt water: Uniform. The dissolved salt is spread throughout the water.','2026-11-01 08:48:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_019','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is it mathematically inaccurate to say a mixture ''forms a new substance''?','["Because mixtures actually destroy substances.","When substances are mixed (like sand and iron), they undergo a physical change but do not react chemically; each ingredient retains its original chemical properties.","Because mixtures always explode.","Because mixtures are only made of one substance."]',1,'Mixing salt and water just makes salty water; it doesn''t create a brand-new chemical!','A mixture is made when two or more substances are combined without forming a new substance through a chemical reaction.','2026-11-01 08:48:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_020','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is ''filtration'' completely useless for separating salt from saltwater?','["Because the filter paper is made of salt.","Because filtration only catches undissolved solid particles (like sand). Dissolved salt particles are small enough to pass right through the microscopic holes in the filter paper along with the water.","Because the salt will burn the filter paper.","Because water cannot pass through a filter."]',1,'The salt breaks down into pieces so small they slide right through the paper!','Important: Filtering ordinary salt water will not remove dissolved salt because the dissolved particles pass through most ordinary filters.','2026-11-01 08:48:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_021','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'How does ''evaporation'' successfully separate salt from saltwater?','["It turns the salt into a gas.","It applies heat to turn the liquid water into a gas (water vapor) which escapes, leaving the solid salt crystals behind in the container.","It uses a magnet to pull the salt out of the water.","It freezes the water so the salt falls to the bottom."]',1,'The water flies away as steam, but the salt is too heavy and gets left behind!','Evaporation: A liquid changes into a gas, leaving a dissolved solid behind. Example: Recovering salt from salt water.','2026-11-01 08:48:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_022','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'If you have a mixture of iron filings (tiny magnetic pieces) and sand, how could you easily separate them?','["By dissolving them in water.","By using a magnet; the magnet will attract and pull out the iron filings, leaving the non-magnetic sand behind.","By boiling the mixture.","By using a paper filter."]',1,'Use the magnetic property of the iron!','This applies previous knowledge to the current topic (implied by the curriculum). While not explicitly named in the text, ''magnetism'' was covered in Topic 4. The text hints: ''Many mixtures can be separated using physical methods. This works because their ingredients have different physical properties...''','2026-11-01 08:48:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_023','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'What physical property allows a ''sieve'' to separate sand from small stones?','["Color","Solubility","Particle size; the smaller sand particles fall through the holes, while the larger stones are blocked.","Magnetism"]',2,'The holes act like a size-checker; only small things get through!','Sieving: A sieve separates particles of different sizes. Example: Separating larger stones from finer sand.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_024','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is ''air'' considered a mixture rather than a pure substance?','["Because you can''t see it.","Because it is a combination of several different gases (like oxygen, nitrogen, and carbon dioxide) that are physically mixed together, not chemically bonded.","Because it contains clouds.","Because it only contains oxygen."]',1,'It is a blend of several different invisible ingredients!','Air: the mixture of gases around us supplies oxygen for breathing and carbon dioxide for plant growth.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_025','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'If you mix concrete using cement, sand, gravel, and water, why do the specific proportions (amounts) of the ingredients matter?','["Because the color of the concrete will change.","Changing the amounts of the ingredients changes the physical properties (like strength and durability) of the final mixture.","The proportions do not matter at all.","Because the concrete will turn into a gas if you use too much water."]',1,'If you use too much water and not enough cement, the bridge will collapse!','The proportions of ingredients often matter. For example, changing the amounts of water, cement and aggregates changes the properties of concrete.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_026','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is ''soil'' considered a highly complex, non-uniform mixture?','["Because it is perfectly clear.","Because it contains a huge variety of unevenly distributed ingredients, including solid minerals, organic plant matter, liquid water, and trapped air pockets.","Because it is a pure chemical compound.","Because it can be separated using evaporation."]',1,'If you look at dirt, you can see tiny rocks, dead leaves, and wet mud all mixed together!','Soil: Soil can contain mineral particles, organic matter, water and air... (It is a Non-uniform mixture).','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_027','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'What happens when you mix oil and water together in a glass?','["They dissolve perfectly to form a uniform mixture.","They form a non-uniform mixture where the two liquids remain separated into distinct layers, because they do not mix (dissolve) into each other.","They explode.","They turn into a solid rock."]',1,'They hate each other and will quickly separate into two stripes in the glass!','A non-uniform mixture does not have the same composition everywhere. Different parts may be visible... Examples: ... Oil and water.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_028','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'What does it mean for a mixture to have a composition that ''can vary''?','["It means the mixture is always the same.","It means you can change the recipe; for example, you can make saltwater slightly salty or extremely salty, and it is still considered a saltwater mixture.","It means the mixture will evaporate.","It means the mixture is pure."]',1,'You can add 1 spoon of sugar to tea, or 10 spoons; it''s still sweet tea!','Pure substances and mixtures compared... Composition: Mixture - Can vary. Pure substance - Fixed for a given pure substance.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_029','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'Why is it important to know that separating a mixture does NOT guarantee safety (e.g., filtering dirty water)?','["Because filtering makes water poisonous.","Filtration only removes visible solid particles (like dirt). It does NOT remove dissolved toxic chemicals, invisible bacteria, or microscopic viruses, so the water is still unsafe to drink.","Because filtering makes the water too hot.","Because filtering removes all the oxygen."]',1,'Just because it looks clean doesn''t mean the invisible germs are gone!','Important: ... separating a mixture does not necessarily mean making every ingredient safe to use. Never drink water from a classroom separation experiment.','2026-11-01 08:48:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_030','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',5,'If you want to quickly separate iron nails from a pile of sawdust, which method is fastest?','["Filtration","Evaporation","Using a magnet","Handpicking each nail"]',2,'The magnet grabs the metal instantly, leaving the wood dust behind!','Many mixtures can be separated using physical methods. This works because their ingredients have different physical properties... (Like magnetism).','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_031','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Critique the everyday use of the word ''pure'' (e.g., ''100% pure orange juice'') versus its strict chemical definition.','["The everyday and chemical definitions are completely identical.","Colloquially, ''pure'' means natural or unadulterated. Chemically, this is a fallacy; orange juice is a highly complex, heterogeneous mixture of water, citric acid, sugars, and organic compounds. A strict chemical ''pure substance'' contains only one discrete element or compound.","Orange juice is actually a pure element.","Chemistry defines ''pure'' as anything that is safe to drink."]',1,'To a chemist, ''pure orange juice'' is a mixture of a hundred different chemicals! Only something like pure 100% H2O is a ''pure substance''.','In science, pure substances include elements... and compounds... At this level, remember that the word pure describes what a material contains, not simply how clean it looks.','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_032','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Analyze the physical principle that allows ''Evaporation'' to successfully separate a solute from a solvent.','["Evaporation relies on the solute and solvent having different magnetic properties.","Separation via evaporation exploits a massive differential in boiling points. The liquid solvent (water) has a relatively low boiling point and transitions to a gas, while the dissolved solid solute (salt) has an extraordinarily high boiling point, remaining behind as a solid precipitate.","Evaporation relies on the salt dissolving the water.","Evaporation proves that water and salt are the same chemical."]',1,'The water boils away at 100°C, but the salt won''t boil until it reaches 1400°C, so the salt is left behind!','Many mixtures can be separated using physical methods. This works because their ingredients have different physical properties, such as... boiling point... Evaporation: A liquid changes into a gas, leaving a dissolved solid behind.','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_033','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Synthesize how the concept of ''Homogeneity'' applies to a metallic alloy like steel.','["Steel is a pure element, not a mixture.","Steel is a homogeneous mixture (an alloy). While it is composed of different elements (iron and carbon), these elements are mixed at the atomic level, creating a material with a uniform composition and physical appearance throughout, making it indistinguishable from a pure substance to the naked eye.","Steel is a heterogeneous mixture where you can see the carbon flakes.","Steel is a mixture of liquid and gas."]',1,'You can''t see the different metals in a steel sword; it is blended perfectly!','A uniform mixture has the same appearance and composition throughout at the scale you can observe. The different substances may not be visible separately. (Synthesis: Alloys are uniform solid mixtures).','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_034','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Evaluate the limitations of ''Filtration'' as a mechanical separation technique.','["Filtration can separate any mixture instantly.","Filtration is strictly a mechanical sieving process dependent on particle size. It is entirely ineffective at separating miscible liquids (like alcohol and water) or solutions where the solute is dissolved into particles smaller than the filter matrix''s pore size (like saltwater).","Filtration only works on gases.","Filtration destroys the chemicals being separated."]',1,'A coffee filter catches the coffee grounds, but the flavor and color molecules are small enough to pass right through into your cup!','Filtration: A filter holds back certain solid particles while liquid passes through... Important: Filtering ordinary salt water will not remove dissolved salt because the dissolved particles pass through most ordinary filters.','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_035','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Analyze why ''Air'' is classified as a uniform mixture despite containing varying trace amounts of pollutants depending on location.','["Because air is actually a pure substance.","While the macro-composition of air (Nitrogen/Oxygen) is globally consistent and thoroughly mixed (homogeneous) on a visual scale, the exact chemical recipe fluctuates locally due to environmental factors. It remains a mixture because the gases do not chemically bond, despite the slight localized variations.","Because air is a liquid.","Because air can be separated using a paper filter."]',1,'The air in a city has more pollution than the air in a forest, so the ''recipe'' changes, but it is still a blended mixture of gases!','A uniform mixture has the same appearance and composition throughout at the scale you can observe... Air, which is a mixture of gases. Pure substances and mixtures compared: Composition... Mixture - Can vary.','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_036','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Synthesize the sequential separation techniques required to isolate pure salt and pure sand from a mixture of salt, sand, and water.','["You can separate them all at once using a magnet.","First, apply Filtration: the mechanical filter traps the insoluble sand, allowing the liquid saltwater solution (filtrate) to pass through. Second, apply Evaporation to the filtrate: thermal energy vaporizes the water solvent, leaving the crystallized solid salt as a precipitate.","You must freeze the mixture to separate them.","You just use a sieve to separate all three."]',1,'Filter the muddy water to catch the sand, then boil the clear water to catch the salt!','Filtration... Example: Separating sand from water. Evaporation... Example: Recovering salt from salt water. (Synthesis: Combining both methods sequentially).','2026-11-01 08:48:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_037','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Critique the statement: ''If a material looks perfectly clear, it is a pure substance.''','["The statement is an absolute scientific law.","The statement relies on a dangerous sensory fallacy. Visual homogeneity does not equal chemical purity. A perfectly clear liquid could be pure \\\\(H_2O\\\\), a homogeneous mixture (saltwater), or a deadly, clear liquid poison. Chemical analysis, not visual inspection, is required to verify purity.","The statement is true because all mixtures are cloudy.","The statement is true because clear things have no mass."]',1,'A glass of saltwater and a glass of pure water look exactly the same!','A material can look clean but still contain other substances... Water that appears clear may still contain dissolved substances, so appearance alone cannot prove purity.','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_038','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Evaluate the physical mechanics of ''Sieving'' versus ''Filtration''.','["They are exactly the same process with different names.","Both are mechanical separation methods based on physical particle size, but they operate at drastically different scales. Sieving is a macroscopic process using a coarse mesh to separate large solids from smaller solids. Filtration is a microscopic process using a fine porous medium to separate suspended solids from a fluid.","Sieving uses heat, filtration uses cold.","Filtration separates liquids from gases, sieving separates solids."]',1,'A sieve is like a big net for catching rocks; a filter is like a microscopic net for catching dirt in water!','Sieving: A sieve separates particles of different sizes. Example: Separating larger stones from finer sand. Filtration: A filter holds back certain solid particles while liquid passes through.','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_039','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Analyze the chemical difference between ''Pure Water'' (H2O) and ''Tap Water''.','["Tap water is a completely different chemical compound.","Pure water is a compound consisting exclusively of \\\\(H_2O\\\\) molecules (a pure substance). Tap water is a homogeneous mixture (a solution); it consists primarily of \\\\(H_2O\\\\) acting as a solvent, but contains various dissolved mineral solutes (fluoride, calcium, chlorine) introduced during environmental transit and municipal treatment.","Pure water has no mass, while tap water is heavy.","There is zero difference; they are scientifically identical."]',1,'Pure water is made in a lab; tap water picks up tiny pieces of rock and chemicals as it travels through pipes!','Pure water prepared for a science experiment [is a pure substance]... tap water usually contains small amounts of dissolved minerals and other substances [it is a mixture]...','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_040','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Synthesize how the concept of ''Solubility'' dictates whether a liquid mixture will be Homogeneous or Heterogeneous.','["Solubility forces all mixtures to explode.","If the solute has high solubility in the solvent (e.g., salt in water), it dissolves at the molecular level, creating a single-phase, uniform (homogeneous) solution. If the solute is insoluble (e.g., sand or oil in water), it remains in a distinct physical phase, creating a multi-phase, non-uniform (heterogeneous) mixture.","Solubility means the mixture will always be a solid.","Solubility has no effect on the mixture type."]',1,'If it dissolves, it blends in perfectly. If it doesn''t dissolve, it sits there like a lump!','Soluble: Sugar dissolves in water... forming a solution. (Uniform). Insoluble: Sand does not dissolve... (Non-uniform).','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_041','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Critique the safety of recovering salt from seawater via evaporation for human consumption.','["It is perfectly safe and ready to eat immediately.","While evaporation successfully separates \\\\(H_2O\\\\) from the dissolved solids, seawater is a highly complex mixture containing not just sodium chloride, but toxic heavy metals, microplastics, and biological waste. Evaporating raw seawater concentrates ALL non-volatile solutes, rendering the raw precipitate potentially hazardous without further chemical refinement.","It is unsafe because evaporation turns the salt into a poison gas.","It is unsafe because seawater contains no salt."]',1,'Boiling ocean water leaves behind salt, but it also leaves behind fish poop and pollution!','Important: ... separating a mixture does not necessarily mean making every ingredient safe to use. Never drink water from a classroom separation experiment.','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_042','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Analyze how ''Decantation'' (implied as a separation method for non-uniform liquids/solids) relies on gravity and density.','["Decantation relies on boiling the mixture.","Decantation exploits density differentials in a heterogeneous mixture. By allowing the denser, insoluble solid (or heavier immiscible liquid) to settle to the bottom via gravity (sedimentation), the less dense, supernatant liquid layer on top can be carefully poured off, achieving a crude physical separation.","Decantation uses a paper filter to catch the solid.","Decantation relies on magnetic fields to pull the water away."]',1,'If you let the sand sink to the bottom, you can carefully pour the clear water off the top!','This synthesizes standard separation techniques. The text mentions ''particles may settle at the bottom''. Pouring off the liquid is decantation.','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_043','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Synthesize why a ''Solution'' is considered the ultimate form of a uniform mixture.','["Because a solution is actually a solid block of ice.","In a true solution (like saltwater), the solute dissolves and disperses at the atomic or molecular level within the solvent. This microscopic integration means the components will never settle out over time via gravity, and they cannot be separated by mechanical filtration, representing perfect physical homogeneity.","Because a solution can be easily separated with a sieve.","Because a solution is actually a pure substance, not a mixture."]',1,'The salt breaks down into individual molecules; you can''t get any more mixed than that!','Salt water: Uniform. The dissolved salt is spread throughout the water... filtering ordinary salt water will not remove dissolved salt...','2026-11-01 08:48:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_044','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Evaluate the chemical implication of the statement: ''The composition of a mixture can vary.''','["It means mixtures are unstable and explode often.","Unlike a pure compound (which requires an exact, immutable stoichiometric ratio, e.g., exactly two Hydrogens for every Oxygen in water), a mixture is a physical blend. You can mix 1 gram of salt or 100 grams of salt into a liter of water; both are valid ''saltwater'' mixtures, demonstrating that their physical composition is infinitely variable.","It means you can change water into gold by mixing it.","It means mixtures must always contain exactly 50% of each ingredient."]',1,'There is no strict ''recipe'' for a mixture; you can add as much or as little as you want!','Pure substances and mixtures compared... Composition: Mixture - Can vary. Pure substance - Fixed for a given pure substance.','2026-11-01 08:48:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_mixtures_global_045','Chemistry','Pure Substances and Mixtures','Topic 5: Pure Substances and Mixtures','Primary',10,'Critique the use of ''Handpicking'' in modern industrial separation processes.','["Handpicking is the most efficient and widely used industrial method.","Handpicking relies on visual identification and manual human dexterity. While useful for crude, macroscopic separations (like removing bad fruit), it is hopelessly inefficient, slow, and expensive for industrial scale. Modern industry relies on automated physical properties (magnetism, density centrifuges, automated optical sorting) for high-throughput separation.","Handpicking is impossible because humans cannot see mixtures.","Handpicking uses giant robotic hands to smash the mixture."]',1,'You can pick rocks out of your rice bowl, but a factory processing a million tons of rice needs a machine to do it!','Handpicking: Large, visible pieces are removed by hand... (Synthesis: This is slow and manual).','2026-11-01 08:48:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_001','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What does it mean if a material is ''soluble''?','["It can dissolve in a particular solvent.","It floats on top of water.","It turns into a gas when heated.","It sinks and forms a solid rock."]',0,'Sugar and salt have this property in water.','A material is soluble in a particular solvent if it can dissolve in that solvent.','2026-11-01 08:49:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_002','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What does it mean if a material is ''insoluble''?','["It dissolves very quickly.","It does not dissolve appreciably in a particular solvent.","It is a liquid.","It turns water into ice."]',1,'Sand and small stones have this property in water.','A material is insoluble in a particular solvent if it does not dissolve appreciably in that solvent under the conditions used.','2026-11-01 08:49:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_003','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'In a mixture of sugar and water, what is the ''solute''?','["The glass cup","The water","The sugar","The spoon"]',2,'It is the solid that seems to disappear.','The substance that dissolves is called a solute. For example: Sugar = solute.','2026-11-01 08:49:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_004','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'In a mixture of sugar and water, what is the ''solvent''?','["The sugar","The water","The air","The spoon"]',1,'It is the liquid that does the dissolving.','A liquid that dissolves a substance is called a solvent. For example: Water = solvent.','2026-11-01 08:49:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_005','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What is a ''solution''?','["A solid rock","A mixture formed when a solute dissolves in a solvent.","A liquid that cannot dissolve anything.","A mixture of two dry solids."]',1,'Sugar water is an example of this.','A liquid that dissolves a substance is called a solvent. The substance that dissolves is called a solute. Together, they form a solution.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_006','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'Which of these materials is ''soluble'' in water?','["Sand","Small stones","Cooking oil","Table salt"]',3,'It disappears when you stir it into water.','Common examples of materials that dissolve in water include: Sugar... Table salt...','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_007','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'Which of these materials is ''insoluble'' in water?','["Table sugar","Sand","Table salt","Coffee compounds"]',1,'It will just sit at the bottom of the glass.','Examples in water include: Sand. Sand does not dissolve appreciably in water.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_008','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What happens to sugar particles when they dissolve in water?','["They are completely destroyed and vanish.","They turn into water particles.","They spread throughout the water and become too small to see individually.","They turn into a hard, solid lump."]',2,'The sugar is still there, you just can''t see it!','The sugar has not vanished. Its particles spread throughout the water and become too small to see individually.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_009','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What does ''stirring'' do to a solid in a liquid?','["It makes it freeze.","It usually helps the solid dissolve faster.","It prevents the solid from dissolving.","It turns the liquid into a solid."]',1,'You use a spoon to do this when making sweet tea.','Stirring usually helps a solid dissolve faster because fresh water is brought into contact with the solid.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_010','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'How does ''temperature'' affect how fast sugar dissolves in water?','["Sugar dissolves faster in cold water.","Sugar dissolves faster in warmer water.","Temperature has no effect on dissolving.","Warm water stops sugar from dissolving."]',1,'Hot tea dissolves sugar much faster than iced tea!','Many solids, including sugar, dissolve faster in warmer water than in colder water.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_011','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What is a ''saturated solution''?','["A solution that is completely dry.","A solution that is frozen solid.","A solution that cannot dissolve more of a substance under the existing conditions.","A solution that has no solute in it."]',2,'It''s completely full and can''t hold any more dissolved powder!','When no more of a solid can dissolve under the conditions, the solution is saturated.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_012','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'Is ''melting'' the same thing as ''dissolving''?','["Yes, they are the exact same thing.","No, melting is a solid changing to a liquid due to heating, while dissolving is a substance mixing into a solvent.","Yes, both require a liquid solvent.","No, melting only happens to water."]',1,'Ice melts; sugar dissolves.','These processes can look similar, but they are different. Dissolving: A substance mixes into a solvent. Melting: A solid changes into a liquid due to heating.','2026-11-01 08:49:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_013','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What happens when you mix cooking oil and water?','["The oil dissolves completely.","The oil forms separate droplets or a layer because it is insoluble.","The water turns into oil.","The oil freezes into a solid."]',1,'Oil and water do not mix!','Cooking oil: Oil does not mix uniformly with water and usually forms a separate layer.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_014','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'Does changing the ''particle size'' (like crushing a sugar cube into powder) affect dissolving?','["Yes, smaller particles generally dissolve faster.","No, particle size does not matter.","Yes, larger particles dissolve much faster.","Only if the water is freezing cold."]',0,'Powder dissolves much faster than a big solid block!','Granulated sugar generally dissolves faster than a sugar cube of the same mass because smaller particles expose more surface area...','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_015','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',1,'What is a ''fair test'' in science?','["A test where you change every single factor at the same time.","A test where you change only one factor at a time and keep everything else the same.","A test where you guess the answer without doing an experiment.","A test that only uses warm water."]',1,'To test temperature fairly, you must keep the amount of water and sugar exactly the same!','A fair test changes only one factor at a time.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_016','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Why doesn''t a glass of sugar water taste like plain water, even though it looks exactly the same?','["Because the glass itself changes the flavor.","Because the sugar has not vanished; its particles have simply spread throughout the water and become too small to see, forming a solution.","Because the water has melted.","Because the sugar turned into a gas and floated away."]',1,'The sugar is invisible, but it is still physically in the cup!','The sugar has not vanished. Its particles spread throughout the water and become too small to see individually. A solution may look clear, but it still contains the dissolved substance.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_017','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'If you want a solid cube of sugar to dissolve as quickly as possible in a glass of water, what three things should you do?','["Use cold water, don''t stir it, and leave the cube whole.","Use warm water, stir the mixture vigorously, and crush the cube into smaller particles first.","Use warm water, add sand to the mixture, and don''t stir.","Freeze the water, stir it, and add more sugar cubes."]',1,'Combine all three tricks to make it dissolve instantly!','Three important factors can affect how quickly many solid materials dissolve in water: 1. Stirring... 2. Temperature (warmer water)... 3. Particle size (smaller particles expose more surface area).','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_018','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Why does crushing a solid (decreasing particle size) make it dissolve faster?','["Because crushing it makes the material hotter.","Because smaller particles expose more surface area to the solvent, allowing more water to interact with the solid at once.","Because crushing it changes it into a completely new chemical.","Because smaller particles are heavier than large blocks."]',1,'If you crush it, the water can touch the inside parts of the cube right away!','Granulated sugar generally dissolves faster than a sugar cube of the same mass because smaller particles expose more surface area to the water.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_019','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Why is leaving a chocolate bar in the hot sun an example of ''melting'' rather than ''dissolving''?','["Because the sun acts as a liquid solvent.","Because the solid chocolate changes directly into a liquid due to heating, without mixing into a separate liquid solvent.","Because chocolate is insoluble in the sun.","Because the chocolate completely disappears."]',1,'Melting only needs heat; dissolving needs a liquid to mix into!','Dissolving is not the same as melting... Melting: A solid changes into a liquid due to heating. Example: ice melting... Sugar dissolving in water does not mean the sugar has melted.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_020','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'What will you observe if you create a ''saturated'' solution of salt in water?','["The salt will suddenly turn into a gas and evaporate.","The water will freeze into solid ice.","Some salt will remain undissolved at the bottom of the glass, no matter how much you stir.","The water will turn bright red."]',2,'The water is completely ''full'' and simply cannot hold any more salt!','When no more of a solid can dissolve under the conditions, the solution is saturated. For example, if you keep adding sugar... eventually some sugar may remain undissolved at the bottom.','2026-11-01 08:49:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_021','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'If a material is ''insoluble'' in water, does that mean it can never dissolve in any liquid on Earth?','["Yes, insoluble materials are completely immune to all liquids.","No, solubility depends on the solvent. A substance that does not dissolve in water might dissolve perfectly in oil or another liquid.","Yes, insoluble materials are actually made of pure water.","No, but it can only dissolve in water if the water is boiling."]',1,'A permanent marker won''t wash off with water (insoluble), but it will wipe away easily with rubbing alcohol (soluble)!','Remember: Insoluble does not mean that a material can never dissolve in any liquid. It means it does not dissolve appreciably in the particular solvent being considered.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_022','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'In an experiment testing if sugar dissolves faster than salt, a student puts sugar in hot water and salt in cold water. Why is this NOT a fair test?','["Because salt can only dissolve in boiling water.","Because they changed two factors at the same time (substance and temperature); they should have used the same temperature for both cups.","Because sugar and salt are exactly the same thing.","Because they didn''t use a large enough cup."]',1,'If the sugar dissolves faster, you won''t know if it''s because it was sugar, or just because the water was hot!','A fair test changes only one factor at a time. To investigate the effect of temperature, for example, use equal amounts of the same material and equal amounts of water... changing only temperature.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_023','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'According to the particle model, what exactly happens during the ''dissolving'' process (Step 2)?','["The solid particles explode into energy.","The water particles interact with the solid particles, pulling them away and allowing them to separate from the main crystal structure.","The water particles turn into solid sugar.","The solid particles group tightly together to form a bigger crystal."]',1,'The water molecules act like tiny magnets, grabbing the sugar pieces and pulling them apart!','Step 2: During dissolving. Water particles interact with sugar particles, allowing them to separate from the crystals.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_024','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'If you add a spoonful of flour to a glass of water and stir, it makes the water cloudy and eventually settles at the bottom. What does this tell you?','["Flour is highly soluble in water.","Flour is insoluble (or only forms a suspension) because it does not dissolve completely to form a clear solution.","Flour is a liquid.","Flour turns water into a gas."]',1,'If it doesn''t form a clear, uniform mixture, it didn''t truly dissolve!','Flour: Flour does not dissolve like sugar. It may make water cloudy or form a suspension.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_025','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Why does stirring a drink help the sugar dissolve faster?','["Stirring acts like a heater and boils the water.","Stirring crushes the sugar into microscopic invisible pieces instantly.","Stirring continually brings fresh, unsaturated water into direct contact with the undissolved solid, speeding up the process.","Stirring slows down the particles in the water."]',2,'If you don''t stir, the water right next to the sugar gets ''full'' quickly, and the dissolving slows down!','Stirring usually helps a solid dissolve faster because fresh water is brought into contact with the solid.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_026','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'What happens to the amount (mass) of sugar after it is fully dissolved in water?','["It increases because it mixes with water.","It decreases because part of it vanishes.","It remains exactly the same; the matter has not vanished, it is just spread out.","It turns into zero because it is invisible."]',2,'Invisible does not mean gone; the matter is conserved!','The sugar has not vanished. Its particles spread throughout the water and become too small to see individually.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_027','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Can you dissolve an unlimited amount of salt into a single cup of water?','["Yes, water can hold an infinite amount of salt.","No, at a given temperature, a specific amount of solvent can only dissolve a specific amount of solute before becoming saturated.","Yes, but only if you use a wooden spoon.","No, water can only dissolve sugar, not salt."]',1,'Eventually, the water hits its limit!','Can water dissolve unlimited amounts? No. At a given temperature, a certain amount of a substance can dissolve in a given amount of solvent.','2026-11-01 08:49:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_028','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'Why is ''solution'' an appropriate term for saltwater?','["Because the salt and water have formed a completely new chemical compound.","Because the solute (salt) has spread uniformly throughout the solvent (water), creating a clear, homogeneous mixture.","Because the salt has melted into a liquid.","Because the salt has sunk to the bottom of the glass."]',1,'The ingredients are perfectly blended together at an invisible level!','A liquid that dissolves a substance is called a solvent. The substance that dissolves is called a solute. Together, they form a solution. A solution may look clear, but it still contains the dissolved substance.','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_029','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'If you heat up a saturated solution of sugar and water, what is likely to happen to any undissolved sugar at the bottom?','["It will turn into solid ice.","More of it will likely dissolve, because warmer water can generally dissolve a greater amount of solid solute.","It will instantly evaporate into a gas.","Nothing; temperature does not affect saturated solutions."]',1,'Hot water has more ''room'' to hold dissolved solids!','The amount that can dissolve depends on the substance, the amount of solvent and the temperature. For many solids, warmer water can dissolve more...','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_030','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',5,'If you mix sand, salt, and water, what will happen?','["Both the sand and the salt will dissolve.","The sand will dissolve, but the salt will sink.","The salt will dissolve (soluble), but the sand will remain visible and settle at the bottom (insoluble).","Both the sand and salt will float to the top."]',2,'You will get a clear, salty solution with a pile of sand at the bottom!','Table salt: Salt dissolves in water... Sand: Sand does not dissolve appreciably in water. It may settle at the bottom.','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_031','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Critique the common colloquial statement: ''The sugar melted in my tea.''','["The statement is scientifically accurate and describes the process perfectly.","The statement is a physical fallacy. Melting is a phase transition from solid to liquid driven strictly by thermal energy (heat). Sugar in tea is undergoing dissolution, where a solute disperses into a liquid solvent to form a mixture.","The statement is wrong because sugar turns into a gas in tea.","The statement is wrong because tea is not a solvent."]',1,'Melting needs heat, dissolving needs a liquid! The hot tea is acting as a solvent, not just a heater.','Dissolving is not the same as melting. These processes can look similar, but they are different... Sugar dissolving in water does not mean the sugar has melted.','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_032','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Analyze the kinetic mechanism behind why increased ''Temperature'' generally increases both the rate and capacity of solubility for solid solutes.','["Higher temperatures freeze the solvent, trapping the solute.","Increased thermal energy increases the kinetic velocity of the solvent molecules. These faster-moving solvent molecules collide more forcefully and frequently with the solid lattice, breaking it apart faster (rate), and the increased intermolecular space can often accommodate more solute particles (capacity).","Higher temperatures cause the solute to repel the solvent magnetically.","Higher temperatures turn the solid solute directly into a liquid."]',1,'Fast, hot water molecules act like tiny wrecking balls, smashing into the sugar crystal and pulling it apart rapidly!','Many solids, including sugar, dissolve faster in warmer water... The amount that can dissolve depends on the substance... For many solids, warmer water can dissolve more... (Synthesis with particle theory).','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_033','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Synthesize how the concept of ''Surface Area to Volume Ratio'' dictates the effect of particle size on the rate of dissolution.','["A smaller ratio means the solvent cannot touch the solute at all.","A single large crystal has a low surface-area-to-volume ratio, meaning the solvent can only interact with the outermost layer of molecules. Crushing the crystal exponentially increases the exposed surface area, allowing the solvent to attack and pull away many more solute molecules simultaneously.","A large crystal dissolves faster because it is heavier and sinks.","Particle size only matters if the solvent is boiling."]',1,'If you break a block in half, you suddenly expose the ''inside'' of the block to the water, speeding up the process!','Granulated sugar generally dissolves faster than a sugar cube of the same mass because smaller particles expose more surface area to the water.','2026-11-01 08:49:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_034','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Evaluate the experimental design: A student tests solubility by putting 10g of sugar in 100mL of water at 20°C, and 10g of salt in 50mL of water at 20°C. Why is this invalid?','["The experiment is perfectly valid because the temperatures are the same.","The experiment fails the criteria for a ''fair test'' by manipulating a confounding variable. The volume of the solvent (100mL vs 50mL) was altered. Because solubility capacity depends heavily on the volume of the solvent, the differing amounts render the comparison mathematically invalid.","The experiment is invalid because sugar and salt cannot be compared.","The experiment is invalid because 20°C is too cold to dissolve anything."]',1,'You gave the sugar twice as much water to dissolve into; that''s cheating!','Make it a fair test: A fair test changes only one factor at a time... use equal amounts of the same material and equal amounts of water... The amount that can dissolve depends on... the amount of solvent...','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_035','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Analyze the physical state of a ''Solution'' at the molecular level.','["A solution is a heterogeneous mixture of distinct solid and liquid phases.","In a true solution, the solute undergoes perfect homogeneous dispersion at the atomic or molecular level within the solvent phase. The solute particles are so thoroughly integrated and microscopic that they do not scatter light (remaining clear) and will not separate out via gravity (sedimentation).","A solution is actually a newly synthesized chemical compound.","A solution only exists when two liquids are mixed, not solids."]',1,'The sugar breaks down into individual invisible molecules that hide perfectly between the water molecules!','A liquid that dissolves a substance is called a solvent. The substance that dissolves is called a solute... A solution may look clear, but it still contains the dissolved substance. The sugar has not vanished. Its particles spread throughout...','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_036','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Synthesize the concept of a ''Dynamic Equilibrium'' using the definition of a ''Saturated Solution''.','["A saturated solution means the liquid has turned into a solid.","While not explicitly named, saturation implies equilibrium. In a saturated solution, the solvent has reached its maximum thermodynamic capacity for holding the solute at that temperature. Any additional solid added will simply accumulate at the bottom, as the rate of dissolving equals the rate of precipitation.","A saturated solution is a liquid that has no solute in it at all.","A saturated solution means the liquid will instantly evaporate."]',1,'The water is completely full; for every new piece of sugar that dissolves, an old piece of sugar has to turn back into a solid at the bottom!','When no more of a solid can dissolve under the conditions, the solution is saturated... eventually some sugar may remain undissolved at the bottom.','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_037','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Critique the assertion that ''Oil is an insoluble substance.''','["The assertion is perfectly true; oil can never be dissolved.","The assertion lacks necessary context. Solubility is a relative property dependent on the specific solvent-solute interaction. While cooking oil is highly insoluble in a polar solvent like water (forming immiscible layers), it is highly soluble in non-polar organic solvents. Thus, ''insoluble'' must always be qualified with the solvent.","The assertion is false because oil dissolves instantly in water.","The assertion is true because oil is a liquid, not a solid."]',1,'Oil hates water, but it loves mixing with other oils or specific chemicals!','Remember: Insoluble does not mean that a material can never dissolve in any liquid. It means it does not dissolve appreciably in the particular solvent being considered.','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_038','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Evaluate the physical consequence of creating a ''Suspension'' (like flour and water) versus a ''Solution''.','["They are exactly the same thing, both resulting in a clear liquid.","A solution involves molecular-level dispersion, creating a stable, clear, homogeneous mixture. A suspension (flour in water) involves macroscopic, insoluble particles temporarily suspended in the fluid. Because they do not dissolve, these larger particles scatter light (cloudiness) and will eventually separate and settle at the bottom via gravity.","A suspension only occurs when mixing two gases together.","A solution involves gravity pulling the particles to the bottom instantly."]',1,'Flour just floats around in the water making it murky; if you wait long enough, it will all sink to the bottom like mud!','Flour does not dissolve like sugar. It may make water cloudy or form a suspension... A non-uniform mixture does not have the same composition everywhere. Different parts may be visible...','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_039','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Analyze why ''Stirring'' accelerates dissolution without changing the maximum solubility limit (saturation point).','["Stirring creates thermal energy that boils the water.","Stirring provides mechanical agitation that rapidly disperses the localized, highly concentrated solute boundary layer surrounding the solid crystal. This continuously exposes the undissolved solid to fresh, unsaturated solvent, maximizing the kinetic rate of dissolving. However, it does not alter the thermodynamic capacity of the solvent to hold solute.","Stirring actually forces the water to hold twice as much solute.","Stirring prevents the solute from ever dissolving."]',1,'Stirring just moves the ''full'' water out of the way so ''empty'' water can touch the sugar crystal!','Stirring usually helps a solid dissolve faster because fresh water is brought into contact with the solid... These factors mainly affect the rate of dissolving—how fast it happens. They do not make every insoluble material soluble (or change the absolute limit).','2026-11-01 08:49:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_040','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Synthesize how adding excessive heat to a saturated saltwater solution, and then letting it cool, would affect the solute.','["The salt would turn into a gas and evaporate.","Heating increases the solvent''s capacity, allowing any remaining solid salt to dissolve. However, as the solution cools back to room temperature, the solvent''s capacity drops. The excess dissolved salt can no longer be held in solution and will precipitate out, reforming visible solid crystals at the bottom.","The salt would permanently disappear.","The water would freeze into solid ice instantly."]',1,'Hot water holds more salt; if the water cools down, it has to ''spit out'' the extra salt it can no longer hold!','The amount that can dissolve depends on the substance, the amount of solvent and the temperature. For many solids, warmer water can dissolve more...','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_041','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Critique the student hypothesis: ''Crushing an insoluble rock into fine dust will make it soluble in water.''','["The hypothesis is correct because dust is a liquid.","The hypothesis is fundamentally flawed. Crushing alters a physical property (particle size/surface area) to increase the *rate* of dissolving for soluble substances. It does not alter the chemical nature of the substance or its thermodynamic compatibility with the solvent. An insoluble rock remains insoluble regardless of its macroscopic size.","The hypothesis is correct because smaller particles always dissolve.","The hypothesis is false because crushing a rock creates a magnetic field."]',1,'You can grind a rock into microscopic dust, but it will just make muddy water, not a clear solution!','These factors [like particle size] mainly affect the rate of dissolving—how fast it happens. They do not make every insoluble material soluble.','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_042','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Analyze the chemical implications of the phrase: ''Dissolving does not usually create a new substance.''','["It implies that dissolving is an irreversible chemical reaction.","It defines dissolution as a physical, rather than chemical, change. When sugar dissolves in water, the covalent bonds within the sucrose molecule remain entirely intact. The only change is the breaking of weaker intermolecular forces between separate sugar molecules as they become surrounded by water molecules.","It implies that dissolving destroys the original atoms of the substance.","It implies that the solute and solvent fuse into a new element."]',1,'If you boil the water away, you get the exact same sugar back because it never chemically changed!','Dissolving does not usually create a new substance. The sugar remains sugar, and the water remains water.','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_043','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Synthesize the interaction between the ''Solvent'' and the ''Solute'' during Step 2 of the dissolving process.','["The solvent chemically burns the solute into a gas.","The process is driven by intermolecular attraction. The solvent particles (water molecules) are attracted to the surface molecules of the solute crystal (sugar). They surround the solute molecules, overcome the attractive forces holding the crystal lattice together, and physically pull them into the bulk liquid phase.","The solute acts as a magnet that repels the solvent.","The solvent and solute ignore each other completely."]',1,'The water molecules swarm the sugar crystal, grab the outside pieces, and carry them away into the liquid!','Step 2: During dissolving. Water particles interact with sugar particles, allowing them to separate from the crystals.','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_044','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Evaluate the physical characteristics of a mixture of ''Cooking Oil and Water''.','["They form a perfect, uniform homogeneous solution.","Because oil is non-polar and water is polar, they are highly immiscible (insoluble in each other). Instead of dissolving, they form a heterogeneous mixture. Due to differing densities, they will spontaneously separate into distinct macroscopic phases, with the less dense oil forming a layer on top of the water.","The water dissolves the oil instantly, making it clear.","They react chemically to form a solid rock."]',1,'They are chemically incompatible, so they refuse to mix and just stack on top of each other!','Cooking oil: Oil does not mix uniformly with water and usually forms a separate layer... Forms separate droplets or a layer. Soluble in water? No.','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_soluble_global_045','Chemistry','Soluble and Insoluble Materials','Topic 6: Soluble and Insoluble Materials','Primary',10,'Critique the use of ''Appearance alone'' to judge the purity of a liquid.','["Appearance is the only scientifically valid way to test purity.","Appearance is highly deceptive. A visually clear, transparent liquid could be a pure substance (distilled water) or a homogeneous mixture (a solution of salt, sugar, or toxic chemicals in water). Because dissolved solutes are dispersed at the molecular level, they do not scatter light, making solutions visually indistinguishable from pure solvents.","Clear liquids are always guaranteed to be pure substances.","Cloudy liquids are the only true pure substances."]',1,'A glass of saltwater and a glass of pure water look exactly the same to your eyes!','A solution may look clear, but it still contains the dissolved substance... Water that appears clear may still contain dissolved substances, so appearance alone cannot prove purity. (From previous topic context, highly relevant here).','2026-11-01 08:49:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_001','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'Why do we often need to separate mixtures?','["To make them look pretty.","To remove unwanted materials or to recover a useful ingredient.","To turn them into a gas.","To make them heavier."]',1,'Like picking bad berries out of a fruit salad, or getting clean water from dirty water.','Sometimes we want to remove unwanted materials or recover a useful ingredient.','2026-11-01 08:49:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_002','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What separation method involves removing large, visible, unwanted pieces with your fingers?','["Evaporation","Handpicking","Filtration","Melting"]',1,'You do this when picking stones out of rice.','Handpicking means removing unwanted pieces by hand. It works best when the different materials are easy to see and large enough...','2026-11-01 08:49:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_003','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What separation method uses a mesh tool to separate larger solid particles from smaller ones?','["Sieving","Boiling","Freezing","Handpicking"]',0,'Like separating big rocks from fine sand.','Sieving separates solid particles of different sizes using a mesh or sieve.','2026-11-01 08:49:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_004','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What is ''sedimentation''?','["Solid particles settling at the bottom of a liquid when left undisturbed.","Water turning into solid ice.","A liquid turning into a gas.","Mixing sugar and water perfectly."]',0,'It''s when the dirt in muddy water sinks to the bottom.','Sedimentation: The heavier insoluble particles settle at the bottom when the mixture is left undisturbed.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_005','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What is ''decantation''?','["Carefully pouring off a liquid from settled solid material.","Using a paper filter to catch sand.","Boiling water until it evaporates.","Using a magnet to pick up metal."]',0,'You pour the clean water off the top, leaving the mud at the bottom.','Decantation: The liquid is carefully poured off without disturbing the settled solid.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_006','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What separation method passes a mixture through a paper barrier to catch solid particles?','["Filtration","Evaporation","Handpicking","Magnetism"]',0,'Like making coffee!','Filtration separates certain insoluble solid particles from a liquid by passing the mixture through a filter.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_007','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'In filtration, what is the ''residue''?','["The clean liquid that falls through the filter.","The solid dirt or material left trapped on the filter paper.","The glass cup holding the liquid.","The funnel itself."]',1,'It''s the stuff that gets caught!','The residue is the solid left on the filter.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_008','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'In filtration, what is the ''filtrate''?','["The solid dirt trapped on the filter.","The liquid that successfully passes through the filter.","The air above the mixture.","The paper filter itself."]',1,'It''s the clean liquid that drips into the cup below.','The filtrate is the liquid that passes through the filter.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_009','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What separation method uses heat to turn a liquid into a gas, leaving a dissolved solid behind?','["Filtration","Sieving","Evaporation","Decantation"]',2,'You boil the water away to get the salt back.','Evaporation can be used to recover a dissolved solid from a solution... the water becomes water vapour and salt may remain behind...','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_010','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What method can separate iron or steel objects from a pile of plastic and glass?','["Evaporation","Magnetic separation","Filtration","Sieving"]',1,'Magnets only pull on certain metals, like iron.','Magnetic separation uses a magnet to remove magnetic materials from a mixture.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_011','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'Which method is best for separating sand from water?','["Handpicking every grain of sand","Evaporation","Filtration","Magnetic separation"]',2,'The paper catches the sand but lets the water through.','Sand and water: Filtration - Sand particles are held back by a suitable filter.','2026-11-01 08:49:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_012','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'Which method is best for separating dissolved salt from water?','["Sieving","Filtration","Evaporation","Handpicking"]',2,'The salt is too small for a filter, so you have to boil the water away.','Salt dissolved in water: Evaporation - Water evaporates, leaving salt behind.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_013','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'If you want to separate tea leaves from brewed liquid tea, what method should you use?','["Evaporation","Straining or filtration","Magnetic separation","Freezing"]',1,'A tea strainer acts just like a filter.','Tea leaves and brewed tea: Straining or filtration - The leaves are retained while the liquid passes through.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_014','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'Can one single separation method perfectly separate every kind of mixture?','["Yes, filtration works for everything.","No, the best method depends on the properties of the materials in the mixture.","Yes, evaporation works for everything.","No, mixtures can never be separated."]',1,'You can''t use a magnet to separate salt and water!','No single method works for every mixture. Sometimes two or more methods are needed. The best method depends on the properties...','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_015','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why do separation methods like sieving or magnetic separation actually work?','["Because mixtures are magical.","Because they rely on the different physical properties of the ingredients (like size or magnetism) to pull them apart.","Because all mixtures will naturally separate themselves if you wait 5 minutes.","Because they use chemical reactions to destroy the unwanted parts."]',1,'You use the differences between the pieces (one is big, one is small) to pull them apart!','Many mixtures can be separated using physical methods. This works because their ingredients have different physical properties, such as particle size... magnetism.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_016','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why might sieving fail to separate two different materials?','["If the two materials are exactly the same color.","If both materials have particles that are the exact same size, they will both fall through the holes together.","If one material is magnetic.","If the sieve is made of metal."]',1,'If you try to sieve salt and sugar, they will both just fall through the holes!','A sieve works because its holes have a particular size. If both materials have similar-sized particles, sieving may not separate them effectively.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_017','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why is ''decantation'' usually done right after ''sedimentation''?','["Because boiling water takes a long time.","Sedimentation lets the heavy dirt sink to the bottom; decantation is the gentle pouring process used to remove the clear liquid off the top without stirring the dirt back up.","Because decantation requires a paper filter.","Because sedimentation uses magnets."]',1,'First you wait for the mud to sink, then you carefully pour the clean water away!','Sedimentation: The heavier insoluble particles settle at the bottom... Decantation: The liquid is carefully poured off without disturbing the settled solid.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_018','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why is pouring muddy water through a filter paper better than just using sedimentation and decantation?','["Filtration is actually worse than decantation.","Sedimentation might leave tiny floating dirt particles behind. Filtration forces the liquid through microscopic holes in the paper, catching even the tiny insoluble particles that wouldn''t sink.","Filtration boils the water instantly.","Filtration uses a magnet to pull the mud out."]',1,'The filter paper is like a microscopic net that catches almost all the solid dirt!','Sedimentation and decantation may remove visible particles, but they do not necessarily remove... (Filtration is more thorough). Filtration separates certain insoluble solid particles... by passing the mixture through a filter.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_019','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why does ordinary filtration completely fail to separate salt from saltwater?','["Because the salt burns a hole in the filter paper.","Because the dissolved salt particles are so microscopically small that they pass right through the holes in the filter paper along with the water.","Because the salt is magnetic and sticks to the funnel.","Because the water turns into a solid."]',1,'Dissolved salt is basically invisible; it slips right through the tiny holes in the paper!','Important: Filtering ordinary salt water will not remove dissolved salt because the dissolved particles pass through most ordinary filters.','2026-11-01 08:49:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_020','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'If you evaporate a bowl of saltwater to get the salt back, what happens to the water?','["It turns into solid ice.","It turns into an invisible gas (water vapor) and escapes into the air, meaning you cannot easily recover the liquid water.","It turns into a new chemical.","It stays in the bowl as a heavy liquid."]',1,'The water boils away into the sky!','Evaporation removes the solvent as vapour. The dissolved solid may be left behind. Evaporation alone is not the best way to collect the water as a liquid...','2026-11-01 08:49:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_021','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'If you spill a box of iron nails into a sandbox, what is the most efficient way to separate them?','["Handpick them one by one.","Pour water on them and filter it.","Sweep a strong magnet over the sand; the iron nails are magnetic and will stick to it, while the sand will not.","Evaporate the sand."]',2,'The magnet does all the hard work instantly!','Magnetic separation uses a magnet to remove magnetic materials from a mixture. Example: A magnet can attract iron filings from sand.','2026-11-01 08:49:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_022','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why wouldn''t a magnet work to separate aluminum cans from a pile of plastic bottles?','["Because plastic is too heavy.","Because neither aluminum nor plastic is attracted to an ordinary magnet; they share the same physical property of being non-magnetic.","Because the magnet would melt the plastic.","Because aluminum cans are actually liquids."]',1,'Magnets only pull on specific metals like iron or steel!','This method only works when one of the materials is attracted to the magnet and the other material is not... Not all metals are magnetic. For example, aluminium... are not attracted...','2026-11-01 08:49:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_023','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'If you have a mixture of sand and salt, what is the very first step you must take to separate them?','["Use a magnet on them.","Add water and stir, so the salt dissolves (becomes a liquid solution) while the sand remains solid (insoluble).","Evaporate them in an oven.","Pour them through a dry sieve."]',1,'You have to turn the salt into a liquid first, so you can separate it from the solid sand!','Separating mixtures by dissolving... Add water to the mixture. The salt dissolves in the water. (Then you filter the sand, then evaporate the water).','2026-11-01 08:49:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_024','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'After adding water to a sand and salt mixture, you pour it through a filter. What is the ''residue'' and what is the ''filtrate''?','["Residue = Saltwater; Filtrate = Sand","Residue = Sand; Filtrate = Pure Water","Residue = Sand; Filtrate = Saltwater solution","Residue = Salt; Filtrate = Sandwater"]',2,'The sand gets caught in the paper (residue), and the salty water drips through (filtrate)!','Filter the mixture to remove the insoluble sand [Residue]. Evaporate the water from the salt solution [Filtrate]...','2026-11-01 08:49:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_025','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Is it safe to drink the clear water you get after filtering muddy water in a classroom experiment?','["Yes, if it looks clear, it is safe.","No, filtration only removes dirt; it does not remove invisible dissolved chemicals or harmful microscopic bacteria, so it is not automatically safe to drink.","Yes, filtering boils the water and kills germs.","No, because the water will taste like paper."]',1,'Clear water can still have invisible germs hiding in it!','However, ordinary filters do not remove dissolved salt, and not all filters remove microorganisms. Filtered water is not automatically safe to drink... Never drink water from a classroom separation experiment.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_026','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Critique the assertion that ''Evaporation is the perfect method for separating any solution.''','["The assertion is perfectly true for all solutions.","The assertion is false. Evaporation is only effective for solid-liquid solutions where you only wish to recover the non-volatile solid solute. If you need to recover the liquid solvent, or if you are separating two miscible liquids (like water and alcohol), you must use distillation instead.","Evaporation only works on magnetic solutions.","Evaporation only works if the liquid is frozen first."]',1,'If you want to keep the water to drink, boiling it away into the sky doesn''t help you!','Evaporation alone is not the best way to collect the water as a liquid; distillation is used when both the solvent and the dissolved solid need to be recovered.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_027','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Analyze the physical mechanics of ''Sedimentation'' using the concept of Density.','["Sedimentation relies on the solid being lighter than the liquid.","Sedimentation is driven by gravity acting on density differentials. Insoluble particles with a higher density than the surrounding fluid (like sand in water) will experience a net downward gravitational force, eventually settling at the bottom. Less dense particles (like sawdust) would float instead.","Sedimentation works because the water turns into a solid block.","Sedimentation is driven by magnetic fields in the Earth."]',1,'Gravity pulls the heavy (dense) dirt down through the lighter water!','The heavier insoluble particles settle at the bottom when the mixture is left undisturbed.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_028','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Synthesize a multi-step procedure to isolate pure iron, pure sand, and pure salt from a single dry mixture containing all three.','["1. Add water. 2. Evaporate. 3. Use a magnet.","1. Magnetic Separation (extracts the iron). 2. Add water to the remaining mixture to dissolve the salt. 3. Filtration (extracts the insoluble sand as residue). 4. Evaporation of the filtrate (recovers the solid salt).","1. Filter the dry mixture. 2. Melt the iron. 3. Freeze the water.","1. Handpick the salt. 2. Sieve the sand. 3. Evaporate the iron."]',1,'Use the magnet first while it''s dry, then use water to separate the salt and sand!','This requires synthesizing multiple sections: Magnetic separation (removes iron)... Separating mixtures by dissolving... Add water... Filter to remove sand... Evaporate to recover salt.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_029','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Evaluate the limitation of ''Sieving'' when attempting to separate a mixture of granulated sugar and fine table salt.','["Sieving will perfectly separate them based on color.","Sieving relies exclusively on a distinct differential in macroscopic particle size. Because granulated sugar and table salt often have overlapping or highly similar crystalline particle sizes, a sieve mesh cannot reliably discriminate between them; both will either pass through or be retained together.","Sieving will cause the salt and sugar to dissolve instantly.","Sieving only works on liquids."]',1,'The holes in the net can''t tell the difference between a grain of salt and a grain of sugar!','A sieve works because its holes have a particular size. If both materials have similar-sized particles, sieving may not separate them effectively.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_030','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Analyze why ''Filtration'' is classified as a physical separation rather than a chemical reaction.','["Because filtration creates a small explosion.","Filtration mechanically segregates matter based on physical size (particles larger than the pore size are trapped). It does not alter the molecular structure, break chemical bonds, or synthesize new compounds. The residue and filtrate retain their original chemical identities.","Because filtration permanently destroys the water molecules.","Because filtration only works if you add dangerous chemicals."]',1,'The filter paper is just a physical wall with tiny doors; it doesn''t change the chemistry of the water or the dirt!','Many mixtures can be separated using physical methods. This works because their ingredients have different physical properties... (Filtration separates without changing the substances chemically).','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_031','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Synthesize how ''Decantation'' could be used in an industrial setting to separate two immiscible liquids (like oil and water).','["Decantation cannot be used for liquids, only solids.","Because oil and water are immiscible (insoluble) and have different densities, they naturally stratify into two distinct liquid layers (sedimentation/settling). The less dense top layer (oil) can then be carefully poured off (decanted) from the denser bottom layer (water), achieving a physical separation.","Decantation involves boiling both liquids until they turn into gas.","Decantation uses a giant magnet to pull the oil out of the water."]',1,'If the oil floats on top of the water, you can just carefully pour the oil off into a different cup!','Sedimentation and decantation... The heavier... settle at the bottom... The liquid is carefully poured off... (Synthesis: This works for layered liquids too, based on density).','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_032','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Critique the assertion that ''A clear filtrate proves the mixture is now a pure substance.''','["The assertion is absolutely true; clear liquids are always pure.","The assertion is a dangerous fallacy. A clear filtrate only proves that all macroscopic, insoluble suspended solids have been removed. The filtrate may still be a highly complex homogeneous solution containing multiple dissolved, invisible solutes (salts, toxins, sugars) that passed through the filter.","The assertion is true because filters magically clean all toxins.","The assertion is false because clear liquids are always solid ice."]',1,'A coffee filter catches the grounds, but the liquid that comes out is definitely a mixture (coffee), not pure water!','A material can look clean but still contain other substances... ordinary filters do not remove dissolved salt... Filtered water is not automatically safe to drink.','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_033','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Evaluate the environmental and economic necessity of ''Magnetic Separation'' in modern waste management.','["It is only used to make garbage look prettier.","Municipal waste is a massive, complex heterogeneous mixture. Manually handpicking metals is economically unviable and hazardous. Automated magnetic separation rapidly and cheaply isolates valuable, recyclable ferrous metals (iron/steel) from the waste stream, reducing landfill volume and minimizing the ecological impact of mining new ore.","It is used to magically turn plastic into gold.","It is a useless process that costs too much money."]',1,'Without giant magnets, recycling factories would have to pay humans to dig through dangerous garbage by hand to find the metal cans!','Magnetic equipment helps separate iron and steel from some recycling materials... The best method depends on the properties of the materials...','2026-11-01 08:49:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_034','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Analyze the specific function of the ''Filter Paper'' in a laboratory filtration setup.','["The filter paper chemically reacts with the water to clean it.","The filter paper acts as a semi-permeable microscopic mesh. Its engineered pore size establishes a physical threshold: solvent molecules and dissolved solute ions (which are smaller than the pores) pass through as filtrate, while larger, insoluble suspended aggregate particles are mechanically blocked and retained as residue.","The filter paper absorbs all the water so only dry dirt is left.","The filter paper uses magnetism to pull the dirt out."]',1,'It''s like a chain-link fence: a mosquito (water) can fly right through, but a baseball (sand) gets stuck!','Filtration separates certain insoluble solid particles from a liquid by passing the mixture through a filter. During filtration: The residue is the solid left on the filter. The filtrate is the liquid that passes through...','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_035','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'If you want to separate a mixture of dry beans and flour, what is the best method?','["Evaporation","Sieving; the fine flour falls through the mesh, and the large beans are caught.","Magnetic separation","Filtration with water"]',1,'The flour is tiny dust, the beans are big chunks!','Sieving separates solid particles of different sizes using a mesh or sieve. Smaller particles pass through the holes...','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_036','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why is ''Handpicking'' not a good method for separating salt from sand?','["Because salt is magnetic.","Because both particles are far too small and numerous for a human to realistically pick them apart by hand; it would take years.","Because handpicking causes explosions.","Because sand is invisible."]',1,'Imagine trying to pick out a million grains of salt with tweezers!','Handpicking means removing unwanted pieces by hand. It works best when the different materials are easy to see and large enough to pick out.','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_037','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Synthesize why attempting to filter a ''Homogeneous Mixture'' (like saltwater) is an exercise in futility.','["Because homogeneous mixtures instantly destroy filter paper.","A homogeneous mixture is defined by molecular-level dispersion (a true solution). The dissolved solute particles (ions/molecules) are infinitesimally smaller than the physical pores of any standard mechanical filter media. Thus, both the solvent and solute easily pass through the barrier together, achieving zero separation.","Because homogeneous mixtures are too thick and viscous to pour.","Because homogeneous mixtures instantly freeze when they touch paper."]',1,'The salt is broken down into invisible pieces that just ride the water straight through the holes!','A uniform mixture has the same appearance and composition throughout... ordinary filters do not remove dissolved salt because the dissolved particles pass through...','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_038','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Evaluate the physical limitations of ''Decantation'' as a quantitative separation method.','["Decantation is the most perfectly precise method in chemistry.","Decantation is an inherently imprecise, qualitative technique. While it rapidly removes the bulk of a supernatant liquid, surface tension and fluid dynamics make it physically impossible to pour off 100% of the liquid without inadvertently disturbing and pouring off some of the underlying sediment (residue).","Decantation only works in zero gravity.","Decantation turns the liquid into a permanent solid."]',1,'You can pour off most of the water, but if you try to get every last drop, the mud will slosh out too!','Decantation: The liquid is carefully poured off without disturbing the settled solid... (Synthesis: ''Carefully pouring'' implies a manual, imprecise process compared to absolute filtration).','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_039','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Critique the design of an experiment that attempts to use ''Evaporation'' to separate a mixture of two different liquids (e.g., water and rubbing alcohol).','["The experiment will work perfectly and easily.","The experimental design is flawed if simple evaporation is used. Both liquids are volatile and will transition to the gas phase, though at different rates depending on their boiling points. Simple evaporation into the open air will result in the loss of both substances, failing to isolate or recover either liquid component effectively.","The experiment will cause the liquids to freeze solid.","The experiment will turn the liquids into a magnetic metal."]',1,'If you just boil it in an open bowl, both liquids will eventually just fly away into the sky!','Evaporation removes the solvent as vapour... Evaporation alone is not the best way to collect the water as a liquid; distillation is used when both the solvent and the dissolved solid need to be recovered.','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_040','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',1,'What separation method would you use if you want to keep BOTH the dissolved solid (like salt) AND the liquid (like water)?','["Evaporation","Filtration","Distillation","Handpicking"]',2,'Evaporation loses the water to the sky; this other method traps the steam and turns it back into water!','Evaporation alone is not the best way to collect the water as a liquid; distillation is used when both the solvent and the dissolved solid need to be recovered.','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_041','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why is ''evaporation'' not the best method if your goal is to get pure drinking water out of saltwater?','["Because evaporation leaves the salt behind, but turns the water into a gas (steam) that escapes into the room; you lose the water you wanted to drink.","Because evaporation destroys the water completely.","Because evaporation makes the water toxic.","Because evaporation only works on frozen water."]',0,'If you boil a pot dry, you have salt, but nothing to drink!','Evaporation removes the solvent as vapour... Evaporation alone is not the best way to collect the water as a liquid; distillation is used...','2026-11-01 08:49:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_042','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',5,'Why is it usually necessary to use ''multiple'' separation methods (like dissolving, then filtering, then evaporating) for complex mixtures?','["Because using only one method is illegal.","Because different ingredients have different properties; no single physical method (like just a filter or just a magnet) can separate everything at once.","Because multiple methods make the experiment look cooler.","Because mixtures are completely impossible to separate."]',1,'A magnet can pull out the iron, but it won''t pull the salt out of the sand!','No single method works for every mixture. Sometimes two or more methods are needed... This process uses more than one method because the two solids have different properties.','2026-11-01 08:49:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_043','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Critique the use of ''Filtration'' to purify heavily polluted river water for a municipal drinking supply.','["Filtration alone is perfectly sufficient to make river water potable.","Filtration is a necessary primary step to mechanically remove macroscopic debris (sediment/silt). However, it is fundamentally insufficient for purification, as it cannot remove dissolved heavy metals, microscopic pathogens, or agricultural chemical runoff, necessitating advanced chemical/biological treatment phases.","Filtration is entirely useless and shouldn''t be used at all.","Filtration actually adds more pollution to the water."]',1,'You can filter out the mud, but the invisible bacteria will still make you sick!','Important: ... separating a mixture does not necessarily mean making every ingredient safe to use... not all filters remove microorganisms. Filtered water is not automatically safe to drink.','2026-11-01 08:49:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_044','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Analyze the thermodynamic requirements for recovering a solid solute via ''Evaporation''.','["Evaporation requires freezing the mixture to absolute zero.","Evaporation requires a continuous input of thermal energy (endothermic process) to overcome the latent heat of vaporization of the solvent. As the solvent molecules gain kinetic energy and enter the gas phase, the concentration of the solute in the remaining liquid increases until precipitation occurs.","Evaporation requires the mixture to be kept in total darkness.","Evaporation is a completely passive process requiring zero energy."]',1,'You have to add a lot of heat to boil away an entire pot of water!','Evaporation: A liquid changes into a gas, leaving a dissolved solid behind... (Synthesis: Changing from liquid to gas requires thermal energy transfer).','2026-11-01 08:49:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_separating_global_045','Chemistry','Separating Mixtures','Topic 7: Separating Mixtures','Primary',10,'Synthesize the concept of ''Differential Solubility'' in separating a mixture of sugar and sand.','["Sugar and sand have the exact same solubility in all liquids.","Differential solubility exploits the fact that solutes behave differently in a specific solvent. By introducing water, a physical divergence is created: the sugar dissolves (high solubility) forming a mobile liquid phase, while the sand remains a rigid solid lattice (insoluble), allowing mechanical separation via filtration.","Adding water makes both the sugar and sand explode.","Differential solubility means both materials dissolve instantly."]',1,'You use water as a tool: it ''grabs'' the sugar, but ignores the sand!','Sometimes one solid dissolves in a liquid while another does not. This difference can help separate the solids... The salt [or sugar] dissolves... Filter... to remove the insoluble sand.','2026-11-01 08:49:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_001','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What are the tiny building blocks of all matter called?','["Cells","Atoms","Dust","Seeds"]',1,'Everything is built out of these microscopic pieces.','Matter is made of extremely tiny building blocks called atoms.','2026-11-01 08:49:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_002','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'Can you see a single atom with your naked eye?','["Yes, if you look very closely.","No, atoms are so small that we cannot see individual atoms with our eyes or an ordinary classroom microscope.","Yes, but only in the dark.","No, because atoms are invisible gases."]',1,'They are much smaller than a grain of sand.','Atoms are so small that we cannot see individual atoms with our eyes or an ordinary classroom microscope.','2026-11-01 08:49:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_003','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What is a ''molecule''?','["A single, lonely atom","A group of two or more atoms chemically bonded together","A type of chemical symbol","A piece of lab equipment"]',1,'It''s what you get when atoms link up!','A molecule is a group of two or more atoms chemically bonded together.','2026-11-01 08:49:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_004','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What subatomic particle has a positive electric charge?','["Electron","Neutron","Proton","Molecule"]',2,'P is for Positive!','Protons: Positively charged particles found in the nucleus.','2026-11-01 08:49:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_005','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What subatomic particle has a negative electric charge?','["Proton","Electron","Neutron","Atom"]',1,'They buzz around the outside of the atom.','Electrons: Negatively charged particles found in regions around the nucleus.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_006','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What subatomic particle has NO electric charge (neutral)?','["Proton","Electron","Neutron","Molecule"]',2,'N is for Neutral!','Neutrons: Particles with no electric charge, found in the nucleus.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_007','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'Where is the ''nucleus'' located in an atom?','["Floating outside the atom","In the tiny central region of the atom","In the electron ring","It makes up the entire atom"]',1,'It is the core of the atom.','The nucleus is the tiny central region of an atom. It contains protons and, in most atoms, neutrons.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_008','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What is the chemical symbol for Oxygen?','["Ox","O","Oxg","Xy"]',1,'It is a single capital letter.','Oxygen - O - Oxygen gas is present in air.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_009','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What is the chemical symbol for Hydrogen?','["Hy","H","Hd","He"]',1,'It is a single capital letter.','Hydrogen - H - Water contains hydrogen atoms.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_010','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What is the chemical symbol for Carbon?','["Ca","Co","C","Cr"]',2,'It is a single capital letter.','Carbon - C - Present in living things and pencil graphite.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_011','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What is the chemical formula for water?','["H₂O","CO₂","O₂","N₂"]',0,'You drink it every day!','Water molecule — H₂O - Two hydrogen atoms are bonded to one oxygen atom.','2026-11-01 08:49:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_012','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What does the formula O₂ represent?','["Water","Two oxygen atoms bonded in an oxygen molecule","One oxygen atom and one hydrogen atom","Carbon dioxide"]',1,'The small ''2'' means there are two of them.','Oxygen molecule — O₂ - Two oxygen atoms are bonded together.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_013','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'What does the formula CO₂ represent?','["Water","Oxygen gas","Carbon dioxide","Carbon gas"]',2,'You breathe this gas out!','Carbon dioxide molecule — CO₂ - One carbon atom is bonded to two oxygen atoms.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_014','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'In a chemical formula, what does a small number written below the line (a subscript) mean?','["The temperature of the atom","How many atoms of the preceding element are in the molecule","The size of the atom","How heavy the atom is"]',1,'Like the ''2'' in H₂O!','A small number written below the line is called a subscript. It tells you how many atoms of the preceding element are represented.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_015','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',1,'If there is no small number (subscript) after a chemical symbol in a formula, what does it mean?','["There are zero atoms of that element.","There is one atom of that element.","There are ten atoms of that element.","The atom is broken."]',1,'No number just means ''one''.','If no subscript appears after an element symbol, it means one atom of that element in the formula unit...','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_016','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Why is an atom considered the smallest unit of a chemical element?','["Because atoms cannot be divided into smaller subatomic particles.","Because an atom is the smallest piece of an element that retains that specific element''s chemical identity and properties.","Because atoms are the only things that have mass.","Because all atoms are the exact same size."]',1,'If you break an oxygen atom apart, it is no longer oxygen; it''s just protons and electrons!','An atom is the smallest unit of a chemical element that retains that element''s chemical identity.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_017','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'If a chemical symbol has two letters, like ''Fe'' for iron, how must it be written?','["Both letters must be capitalised (FE).","Both letters must be lowercase (fe).","The first letter is capitalised, and the second is lowercase (Fe).","The first letter is lowercase, and the second is capitalised (fE)."]',2,'Fe stands for iron (from the Latin ''ferrum'')!','The first letter is always capitalised; the second, when present, is lowercase.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_018','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'How many total atoms are in one molecule of water (H₂O)?','["Two","Three","Four","One"]',1,'2 Hydrogens + 1 Oxygen = 3 total atoms!','Two hydrogen atoms + one oxygen atom → one water molecule... H₂O... The small ₂ means there are two hydrogen atoms. There is no number after O, so there is one oxygen atom.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_019','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'How many total atoms are in one molecule of carbon dioxide (CO₂)?','["Two","Three","Four","One"]',1,'1 Carbon + 2 Oxygens = 3 total atoms!','For example, CO₂ has one carbon atom and two oxygen atoms, making three atoms in total per molecule.','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_020','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'What is the difference between an ''element'' and a ''compound'' based on their atoms?','["Elements are made of molecules; compounds are made of isolated atoms.","An element contains only one kind of atom (like O₂), while a compound is made from two or more different elements chemically combined (like H₂O).","Elements are always solids; compounds are always liquids.","There is no difference."]',1,'If it has different capital letters in the formula (like C and O), it''s a compound!','Element: A substance containing only one kind of atom... Compound: A substance made from two or more different elements chemically combined...','2026-11-01 08:49:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_021','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Why is an O₂ molecule considered an element and not a compound?','["Because oxygen is a gas.","Because even though it contains two atoms bonded together, they are both the exact same kind of atom (oxygen).","Because oxygen is invisible.","Because it only contains one single atom."]',1,'A compound must have DIFFERENT elements mixed together!','An oxygen molecule (O₂) contains two atoms, but both are oxygen atoms. (An element contains only one kind of atom).','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_022','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Why is H₂O considered a compound?','["Because it is a liquid.","Because it contains atoms from two different elements (Hydrogen and Oxygen) chemically combined together.","Because it contains three atoms.","Because it is a pure substance."]',1,'It combines two different chemical symbols!','A water molecule (H₂O) contains atoms of two different elements. A compound contains different elements chemically combined...','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_023','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'What holds the atoms together inside a molecule?','["Gravity","Chemical bonds","Magnetic fields","Static electricity"]',1,'It''s like the strong glue that connects the building blocks.','Atoms can join through chemical bonds. These bonds hold the atoms together.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_024','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Why do textbooks use simplified ''solar system'' models to draw atoms, and why is this slightly inaccurate?','["The models are perfectly accurate pictures taken by microscopes.","The models help us visualize the parts (nucleus and electrons), but in reality, electrons do not follow neat, flat planetary paths like planets orbiting the sun.","The models are inaccurate because atoms don''t actually have electrons.","The models are inaccurate because the nucleus is actually on the outside of the atom."]',1,'Electrons actually form a blurry ''cloud'' around the nucleus, not neat circles!','Important: Atom diagrams in textbooks are simplified models. Atoms are not little solar systems with electrons following neat planetary paths.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_025','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'What does the chemical formula ''CH₄'' (Methane) tell you about its molecule?','["It is made of Carbon and Helium.","It contains 1 Carbon atom and 4 Hydrogen atoms.","It contains 4 Carbon atoms and 1 Hydrogen atom.","It contains 1 Carbon atom and 1 Hydrogen atom."]',1,'C has no subscript (so 1), H has a subscript of 4!','Formula: CH₄. Name: Methane. Atoms represented: 1 carbon, 4 hydrogen.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_026','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'If you build a model of a water molecule using colored balls, why should you use two different colors?','["To make it look pretty.","Because water is made of two different elements (Hydrogen and Oxygen), and different colors represent different elements.","Because the Hydrogen atoms are different sizes.","Because one atom is hot and the other is cold."]',1,'You need to show that the atoms aren''t all the same!','Use different colours for different elements, and make a key showing what each colour represents.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_027','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Do all substances exist as molecules?','["Yes, every substance in the universe is made of molecules.","No, some elements, like helium, normally exist as individual, unbonded atoms rather than molecules.","Yes, but some molecules are invisible.","No, some substances are made of pure energy."]',1,'Helium atoms are ''loners'' and don''t like to bond together!','Some elements, such as helium, normally exist as individual atoms rather than molecules under ordinary conditions. So not every substance is made of molecules.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_028','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Where are protons and neutrons located inside an atom?','["Floating in the electron cloud.","In the tiny central region called the nucleus.","They are located outside the atom.","Protons are in the center, neutrons are on the outside."]',1,'They are packed tightly together in the very center!','The nucleus is the tiny central region of an atom. It contains protons and, in most atoms, neutrons.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_029','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'How does understanding atoms help us understand everyday things, like cooking?','["It proves that food isn''t made of matter.","It helps us understand that heating food can cause the molecules to chemically react, break their bonds, and form new substances.","It shows that atoms disappear when they get hot.","It proves that cooking doesn''t change food at all."]',1,'Cooking an egg changes its chemical molecules permanently!','Why are atoms and molecules important? ... Cooking: Heating can cause molecules in food to change or react.','2026-11-01 08:49:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_030','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',5,'Why is ''matter'' described as ''building blocks'' in chemistry?','["Because all matter is made of wood.","Just as different arrangements of building blocks can make different structures (like a house or a car), different arrangements of atoms can form millions of different chemical substances.","Because matter only comes in square shapes.","Because atoms are as large as toy blocks."]',1,'With only about 100 different ''blocks'' (elements), you can build the whole universe!','Think of atoms as tiny building blocks. Just as different arrangements of building blocks can make different structures, atoms can form many different substances.','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_031','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Critique the classical ''Bohr Model'' (planetary model) of the atom presented in basic diagrams.','["The Bohr model is the most currently accurate quantum mechanical representation of an atom.","While the Bohr model is pedagogically useful for showing energy levels and subatomic particle locations (nucleus vs. electrons), it is physically inaccurate. Quantum mechanics dictates that electrons do not orbit in flat, defined planetary paths, but rather exist in probabilistic 3D clouds (orbitals).","The Bohr model is inaccurate because it places electrons in the nucleus.","The Bohr model is inaccurate because it proves atoms do not exist."]',1,'Electrons don''t fly in perfect circles like planets; they swarm in blurry clouds!','Important: Atom diagrams in textbooks are simplified models. Atoms are not little solar systems with electrons following neat planetary paths. (Synthesis: This introduces the concept that the visual model is a flawed analogy).','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_032','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Analyze the relationship between a molecule''s ''chemical bonds'' and its ''chemical properties''.','["Chemical bonds have no effect on properties; properties are determined by color.","Chemical bonds dictate a molecule''s properties. The specific spatial arrangement of atoms and the strength/type of the attractive interactions (bonds) between them completely define how the molecule will react with other substances, its state of matter, and its thermodynamic stability.","Chemical bonds only determine if the molecule is heavy or light.","Chemical bonds are physical strings that tie atoms together."]',1,'Water (\\(H_2O\\)) puts out fires, but Hydrogen (\\(H_2\\)) and Oxygen (\\(O_2\\)) alone will explode! The bonds change everything.','Materials: Different arrangements of atoms and different chemical bonds help give materials their properties. The properties of a substance depend on the kinds of atoms it contains and how those atoms are arranged and bonded.','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_033','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Synthesize how the concept of ''Subatomic Particles'' defines the overall electrical charge of a neutral atom.','["A neutral atom has no subatomic particles at all.","An atom''s nucleus contains positively charged protons, while negatively charged electrons occupy the surrounding space (neutrons are neutral). In a neutrally charged atom, the number of positive protons exactly equals the number of negative electrons, resulting in a net electrical charge of zero.","A neutral atom has more protons than electrons.","A neutral atom has only neutrons."]',1,'If you have +5 and -5, they cancel out to equal zero!','Protons: Positively charged... Electrons: Negatively charged... (Synthesis: Neutrality requires these opposite charges to balance).','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_034','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Evaluate the significance of ''Chemical Symbols'' in global scientific communication.','["Chemical symbols are only used in English-speaking countries.","Chemical symbols (like ''Fe'' for iron or ''Au'' for gold) provide a standardized, universal nomenclature. Regardless of linguistic differences in the spoken name of an element (e.g., ''Iron'' in English vs. ''Fer'' in French), the symbol remains constant, ensuring unambiguous global scientific data sharing.","Chemical symbols change depending on which country you are in.","Chemical symbols are just secret codes used to hide information."]',1,'A scientist in Japan and a scientist in Brazil both know exactly what ''H₂O'' means!','Chemical symbols help scientists around the world communicate clearly, regardless of the language they speak.','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_035','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Analyze the structural difference between the element ''Oxygen'' (\\(O_2\\)) and the element ''Helium'' (He) as they naturally occur.','["They are structurally identical; both exist as molecules.","Oxygen naturally exists as a diatomic molecule (\\\\(O_2\\\\)), meaning two oxygen atoms chemically bond together to form a stable unit. Helium is a noble gas and naturally exists as a monatomic gas, meaning individual, unbonded helium atoms move freely without forming molecules.","Oxygen is a single atom, while Helium is a molecule.","Oxygen is a solid, while Helium is a liquid."]',1,'Oxygen atoms like to hold hands in pairs; Helium atoms like to be completely alone!','Oxygen molecule — O₂... Two oxygen atoms are bonded together... Some elements, such as helium, normally exist as individual atoms rather than molecules under ordinary conditions.','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_036','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Synthesize the meaning of the chemical formula ''H₂SO₄'' (Sulfuric Acid), assuming ''S'' is Sulfur.','["It contains 2 Hydrogen, 1 Sulfur, and 4 Oxygen atoms.","The formula represents a complex compound molecule. The subscript ''2'' indicates two Hydrogen (H) atoms. The lack of a subscript after ''S'' indicates one Sulfur atom. The subscript ''4'' indicates four Oxygen (O) atoms, totaling seven atoms chemically bonded into a single molecular unit.","It contains 2 Hydrogen, 4 Sulfur, and 1 Oxygen atom.","It contains 1 Hydrogen, 1 Sulfur, and 1 Oxygen atom."]',1,'Read it piece by piece: H(2) + S(1) + O(4)!','A chemical formula uses symbols and numbers to represent the elements... A small number... tells you how many atoms of the preceding element... If no subscript appears... it means one atom...','2026-11-01 08:49:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_037','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Critique the statement: ''Every molecule is a compound.''','["The statement is an absolute scientific law.","The statement is false. While every compound is a molecule (because it requires two or more atoms bonded together), not every molecule is a compound. A molecule like \\\\(O_2\\\\) (oxygen gas) or \\\\(N_2\\\\) (nitrogen gas) consists of multiple atoms bonded together, but because they are of the *same* element, they are classified as elements, not compounds.","The statement is true because molecules always have different atoms.","The statement is true because all compounds are gases."]',1,'O2 is a molecule, but it only has one type of ingredient, so it''s not a compound!','Molecules can contain atoms of the same element or atoms of different elements... An oxygen molecule (O₂) contains two atoms, but both are oxygen atoms... A compound contains different elements chemically combined...','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_038','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Evaluate the physical limitations of ''Atomic Models'' (like plastic balls and sticks) used in classrooms.','["The models are exact, perfect replicas of real atoms.","Physical models are pedagogical tools that drastically misrepresent scale, motion, and quantum reality. The ''sticks'' represent chemical bonds, which are actually invisible electromagnetic forces, not physical rods. Furthermore, the ''balls'' suggest atoms have hard boundaries, whereas atoms are mostly empty space with diffuse electron clouds.","The models are completely useless and teach nothing.","The models prove that atoms are actually made of plastic."]',1,'The sticks just show you *where* the magnetic attraction connects the atoms; there isn''t a real stick there!','Remember that models are not exact pictures of atoms. They help us visualise how atoms are grouped and bonded. (Synthesis: Bonds aren''t sticks, and atoms aren''t hard plastic spheres).','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_039','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Analyze how the ''Mass'' of an atom is distributed among its subatomic particles.','["Electrons make up 99% of an atom''s mass.","While not explicitly detailed with mass values in the text, synthesizing the particle locations implies the structure. The nucleus (containing protons and neutrons) is incredibly dense and contains almost 100% of the atom''s mass. The electrons, which occupy the vast surrounding space, have negligible mass in comparison.","Protons, neutrons, and electrons all weigh exactly the same.","The mass is evenly spread throughout the entire atom."]',1,'The center of the atom is incredibly heavy, while the outside cloud is incredibly light!','This relies on synthesizing general physics knowledge tied to the curriculum''s introduction of the nucleus. The text states: ''The nucleus is the tiny central region... It contains protons and... neutrons.''','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_040','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Synthesize why the distinction between a ''Mixture'' (from Topic 5) and a ''Compound'' (from Topic 8) is defined by chemical bonds.','["Mixtures and compounds are the exact same thing.","In a mixture (like salt and sand), the substances are physically co-located but retain their individual chemical identities and can be mechanically separated because no chemical bonds form between them. In a compound (like \\\\(H_2O\\\\)), the atoms are permanently joined by electromagnetic chemical bonds, synthesizing an entirely new substance with novel properties.","Compounds can be easily separated by handpicking, mixtures cannot.","Mixtures involve chemical bonds, compounds do not."]',1,'You can easily pick the fruit out of a fruit salad (mixture), but you can''t easily pick the Hydrogen out of a glass of Water (compound)!','A molecule is a group of two or more atoms chemically bonded together... A compound contains different elements chemically combined... (Contrasting with Topic 5 where mixtures are ''combined without forming a new substance'').','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_041','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Critique the use of ''Subscripts'' in a chemical formula. What happens if you change a subscript (e.g., changing \\(H_2O\\) to \\(H_2O_2\\))?','["It just makes the water taste slightly different.","Changing a subscript does not simply alter the amount of the substance; it entirely redefines the molecular identity. \\\\(H_2O\\\\) is water (essential for life). Changing the oxygen subscript to 2 creates \\\\(H_2O_2\\\\) (hydrogen peroxide, a toxic bleach). The specific stoichiometric ratio is the fundamental identity of the compound.","It turns the liquid into a solid.","It has no effect on the chemical at all."]',1,'If you change the numbers, you completely change the chemical! Water is safe, Hydrogen Peroxide will make you sick!','The formula H₂O records the kinds and numbers of atoms in one water molecule... A compound contains different elements chemically combined in a fixed proportion.','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_042','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Analyze the etymology and logic behind chemical symbols that do not match their English names (e.g., ''Fe'' for Iron or ''Au'' for Gold).','["The symbols were chosen randomly by a computer.","These symbols are derived from the historical Latin or Greek names for the elements, established long before modern English nomenclature. For example, ''Fe'' derives from the Latin ''ferrum'' (iron), and ''Au'' from ''aurum'' (gold). This maintains historical consistency in the universal scientific language.","The symbols are just typos that scientists never fixed.","The symbols represent the country where the element was found."]',1,'Scientists used Latin hundreds of years ago, so the old Latin names stuck!','Iron: Fe... Gold: Au... Chemical symbols help scientists around the world communicate clearly, regardless of the language they speak. (Synthesis: The non-matching symbols are rooted in historical universal languages like Latin).','2026-11-01 08:49:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_043','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Synthesize the role of ''Electrons'' in the formation of ''Chemical Bonds''.','["Electrons prevent atoms from bonding by pushing them apart.","While the nucleus contains the heavy protons and neutrons, it is the negatively charged electrons occupying the outermost regions of the atom that directly interact with other atoms. Chemical bonds are formed through the sharing, gaining, or losing of these outermost electrons to achieve thermodynamic stability.","Electrons act as physical glue that holds the nuclei together.","Electrons have no role in chemical bonding."]',1,'The outside edges of the atoms (the electrons) are what touch and connect when atoms lock together!','Electrons: Negatively charged particles found in regions around the nucleus... Atoms can join through chemical bonds. (Synthesis: Since electrons are on the outside, they are the particles that interact to form bonds).','2026-11-01 08:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_044','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Evaluate the conceptual leap from observing macroscopic ''Matter'' to understanding microscopic ''Atoms''.','["It requires no conceptual leap; atoms are easily visible.","It requires abstract, inferential reasoning. Because atoms are sub-microscopic and cannot be directly observed by human senses, their existence and properties must be deduced through empirical experiments, mathematical models, and macro-level chemical behaviors (like constant proportion reactions), rather than direct observation.","It proves that matter is just an illusion.","It requires a magnifying glass to see the atoms clearly."]',1,'We can''t see them, so we have to use clues and models to figure out how they work!','Matter is made of extremely tiny building blocks called atoms. Atoms are so small that we cannot see individual atoms with our eyes or an ordinary classroom microscope... Models help us understand atoms...','2026-11-01 08:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_atoms_global_045','Chemistry','Atoms and Molecules','Topic 8: Atoms and Molecules','Primary',10,'Critique the classification of ''Air'' using the concepts of elements, molecules, and compounds.','["Air is a single pure element.","Air is not a single chemical entity, but a homogeneous mixture. It is composed of diatomic elemental molecules (like Nitrogen \\\\(N_2\\\\) and Oxygen \\\\(O_2\\\\)), compound molecules (like Carbon Dioxide \\\\(CO_2\\\\)), and monatomic elements (like Argon). Because these distinct molecules are not chemically bonded to *each other*, it remains a mixture.","Air is a single giant compound molecule.","Air is made entirely of unbonded individual atoms."]',1,'Air is a soup made of many different types of floating molecules!','Oxygen gas is present in air... Nitrogen gas makes up most of Earth''s atmosphere... (Synthesis with Topic 5: Air is a mixture of these different molecules).','2026-11-01 08:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_001','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What is an ''element''?','["A mixture of many different things","A pure substance made of only one kind of atom","A liquid that dissolves things","A type of gas found only in space"]',1,'It is the simplest form of a substance.','An element is a pure substance made of only one kind of atom.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_002','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What is a ''compound''?','["A pure substance made when two or more different elements are chemically combined","A mixture of sand and water","A single atom floating by itself","A type of metal"]',0,'Water is an example of a compound.','A compound is a pure substance made when two or more different elements are chemically combined in fixed proportions.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_003','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What is a ''mixture''?','["Two or more substances chemically bonded into a new substance","Two or more substances physically combined without forming a single new substance","Only one kind of atom","A pure substance that cannot be separated"]',1,'Fruit salad is an example.','A mixture contains two or more substances physically combined rather than chemically combined into a single new substance.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_004','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'Which of these is an example of an ''element''?','["Pure water","Salt water","Copper wire","Air"]',2,'It is made of only one thing: copper atoms.','Copper wire: Element - Copper atoms make up the element copper.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_005','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'Which of these is an example of a ''compound''?','["Oxygen gas (O₂)","Pure water (H₂O)","Air","Soil"]',1,'It contains two different elements bonded together.','Pure water (H₂O): Compound - Hydrogen and oxygen are chemically combined.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_006','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'Which of these is an example of a ''mixture''?','["Pure sodium chloride (salt)","Pure oxygen","Copper","Air"]',3,'It is a blend of oxygen, nitrogen, and other gases.','Air: Mixture - Contains several gases.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_007','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What does the chemical symbol ''Fe'' stand for?','["Fluorine","Iron","Gold","Helium"]',1,'Fe comes from the Latin word for iron, ''ferrum''.','Iron (Fe) - A metal used in tools, buildings and many machines.','2026-11-01 08:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_008','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What does the chemical symbol ''Au'' stand for?','["Silver","Aluminum","Gold","Argon"]',2,'Au comes from the Latin word ''aurum''.','Gold: Au - Used in jewellery and electronics.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_009','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What is the chemical formula for water?','["CO₂","H₂O","O₂","NaCl"]',1,'You drink it every day!','Water (H₂O) - Each water molecule contains two hydrogen atoms bonded to one oxygen atom.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_010','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What is the chemical formula for carbon dioxide?','["CO₂","H₂O","O₂","NaCl"]',0,'You breathe this out.','Carbon dioxide (CO₂) - Each molecule contains one carbon atom bonded to two oxygen atoms.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_011','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What does the formula ''NaCl'' represent?','["Water","Oxygen gas","Sodium chloride (table salt)","Carbon dioxide"]',2,'You put this on your food!','Sodium chloride (NaCl) - Common table salt is a compound made of sodium and chlorine.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_012','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'Is ''Oxygen gas'' (O₂) an element or a compound?','["An element","A compound","A mixture","A liquid"]',0,'Even though it has two atoms, they are both the same kind!','Oxygen gas (O₂): Element - Contains only oxygen atoms.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_013','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What happens when you mix salt and water?','["They form a brand new chemical compound.","They form a physical mixture (salt water).","The salt turns into a gas.","They explode."]',1,'You can still separate them by evaporating the water.','Salt water: Mixture - Salt and water are combined without forming a single new substance.','2026-11-01 08:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_014','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'What do we call the short letters used by scientists to represent elements (like ''C'' for Carbon)?','["Chemical symbols","Secret codes","Mathematical formulas","Number signs"]',0,'It''s a universal shortcut.','Each element has its own chemical symbol, which is used around the world.','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_015','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',1,'How many elements have scientists identified?','["Exactly 10","About 50","More than 100","Only 4 (Earth, Air, Fire, Water)"]',2,'Look at a Periodic Table!','Scientists have identified more than 100 elements.','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_016','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why is an O₂ molecule considered an ''element'' and not a ''compound''?','["Because it is a gas, and compounds are only solids.","Because it only contains one kind of atom (oxygen), even though there are two atoms bonded together.","Because it contains two different types of atoms.","Because it is invisible."]',1,'A compound MUST have different kinds of atoms mixed together!','An O₂ molecule has two atoms but is still part of an element because both atoms are oxygen. An element is defined by the type of atom it contains, not by whether its atoms occur individually or in pairs.','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_017','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why is pure water (H₂O) classified as a ''compound''?','["Because it is a liquid.","Because it is made of two different elements (Hydrogen and Oxygen) that are chemically combined together.","Because it contains three total atoms.","Because you can separate it with a paper filter."]',1,'It is a chemical combination of different ingredients!','H₂O is a compound because it contains hydrogen and oxygen chemically combined.','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_018','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'If you see the chemical symbol ''Na'', why is the ''a'' lowercase?','["Because ''a'' is a vowel.","Because ''N'' is more important.","In a two-letter chemical symbol, the first letter is always capitalized and the second is always lowercase.","Because the ''a'' is silent."]',2,'It''s the standard rule for all scientific symbols around the world.','The first letter is always capitalised; the second, when present, is lowercase: for example, Na for sodium and Cl for chlorine.','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_019','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'What is ''brass'' classified as, and why?','["It is an element, because it is a pure metal.","It is a mixture (an alloy), because it contains copper and zinc mixed together physically, not bonded into a new pure compound.","It is a compound, because it has a chemical formula.","It is a liquid."]',1,'Alloys are just metals melted and mixed together like a smoothie!','Brass: Mixture - An alloy made mainly of copper and zinc. Brass is an example of an alloy, which is a mixture containing a metal and one or more other elements. Its components are mixed at the material level...','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_020','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why do the properties of a compound often look completely different from the elements that make it up?','["Because the elements are destroyed.","Because when elements chemically combine, they form an entirely new substance with its own unique properties.","Because compounds are always liquids.","Because you can still see the original elements floating inside."]',1,'Poison gas + explosive metal = safe table salt!','When elements form a compound, the resulting substance can have properties very different from those of the original elements. For example, sodium is a highly reactive metal and chlorine is a poisonous gas... they form sodium chloride (table salt).','2026-11-01 08:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_021','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Can you separate the hydrogen and oxygen in water (H₂O) using a physical method like evaporation or filtration?','["Yes, evaporation will leave the hydrogen behind.","Yes, a paper filter will catch the oxygen.","No, compounds must be broken down by chemical reactions (like electrolysis), not physical methods.","No, water can never be separated."]',2,'You can''t boil or filter a chemical bond apart!','Compounds can sometimes be broken down into simpler substances by chemical reactions. This is different from physically separating a mixture. For example, water can be decomposed into hydrogen and oxygen using electrolysis...','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_022','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'How is separating salt water different from separating pure water?','["Salt water is a compound, so you need electricity to separate it.","Salt water is a physical mixture, so you can use physical methods (like evaporation) to separate the water from the salt.","Pure water is a mixture, so you can use evaporation to separate the hydrogen.","There is no difference."]',1,'Mixtures = physical separation. Compounds = chemical separation.','By contrast, salt water can be separated by evaporation: the water leaves as vapour, while salt may remain behind. The salt and water were a mixture, not a new compound...','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_023','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'What does the formula ''CO₂'' tell you about the atoms inside?','["There is one Carbon atom and one Oxygen atom.","There is one Carbon atom and two Oxygen atoms chemically bonded together.","There are two Carbon atoms and one Oxygen atom.","There is a mixture of Carbon and Oxygen floating around."]',1,'Read the letters and the small numbers (subscripts)!','Carbon dioxide (CO₂) - Each molecule contains one carbon atom bonded to two oxygen atoms.','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_024','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why is ''Air'' classified as a mixture?','["Because it contains several different gases (like oxygen, nitrogen, and carbon dioxide) that are physically mixed together in the same space, but not chemically bonded.","Because it only contains oxygen.","Because it is a pure compound made of oxygen and nitrogen bonded together.","Because it is completely empty."]',1,'It''s a soup of different, independent gas molecules!','Air: Mixture - Contains several gases.','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_025','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'If you mix sugar and water, have you created a new chemical compound?','["Yes, because the sugar disappears.","No, you have created a physical mixture; the sugar and water have not chemically bonded into a new substance.","Yes, because the water tastes different.","No, because sugar is not an element."]',1,'If you boil the water away, you get the exact same sugar back!','A mixture contains two or more substances physically combined rather than chemically combined into a single new substance. Examples include... Salt water...','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_026','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'What is a ''fixed proportion'' in a compound?','["It means the compound is glued to the table.","It means the recipe is always exactly the same; for example, water (H₂O) always has exactly 2 hydrogen atoms for every 1 oxygen atom.","It means you can mix any amount of elements together to get the same compound.","It means the compound never changes its state of matter."]',1,'If you change the recipe (like H₂O₂), you get a completely different chemical!','Compound: A pure substance made when two or more different elements are chemically combined in fixed proportions.','2026-11-01 08:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_027','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why is pure sodium chloride (table salt) considered a compound?','["Because it is a mixture of salt and water.","Because it is made of two different elements (sodium and chlorine) chemically combined together.","Because it is found in the ocean.","Because it only contains sodium atoms."]',1,'NaCl means two different elements are locked together!','Sodium chloride (NaCl) - Common table salt is a compound made of sodium and chlorine... Pure sodium chloride: Compound - Sodium and chlorine are chemically combined.','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_028','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'What is ''electrolysis'' used for?','["To separate a physical mixture like sand and water.","To use electrical energy to drive a chemical reaction, such as breaking down the compound water into hydrogen and oxygen gases.","To evaporate salt water.","To mix metals together to make brass."]',1,'You have to shock the water to break the strong chemical bonds!','For example, water can be decomposed into hydrogen and oxygen using electrolysis, a process that uses electrical energy and appropriate equipment. Key terms: Electrolysis - Using electrical energy to drive a chemical reaction.','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_029','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Why do scientists use chemical symbols like ''C'' for Carbon and ''O'' for Oxygen?','["To make chemistry look harder than it is.","So scientists around the entire world can communicate clearly and understand exactly what elements are in a substance, no matter what language they speak.","Because words take too much ink to write.","Because the elements asked them to."]',1,'It''s a universal language for chemistry!','Chemical symbols help scientists around the world communicate clearly, regardless of the language they speak.','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_030','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',5,'Is ''soil'' an element, compound, or mixture?','["Element","Compound","Mixture","None of these"]',2,'Soil has rocks, dirt, dead leaves, water, and air all mixed up!','Soil: Mixture - Contains different materials.','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_031','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Critique the assertion that ''A molecule must always be a compound.''','["The assertion is scientifically accurate.","The assertion is false. While all compounds exist as molecules (or crystal lattices), not all molecules are compounds. A molecule is simply two or more atoms bonded together. If those atoms are of the *same* element (like \\\\(O_2\\\\) or \\\\(N_2\\\\)), it is an elemental molecule, not a compound.","The assertion is false because molecules are only found in liquids.","The assertion is true because all atoms are compounds."]',1,'Oxygen gas is a molecule (O2), but it is NOT a compound!','An O₂ molecule has two atoms but is still part of an element because both atoms are oxygen... A compound contains different elements chemically combined...','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_032','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Analyze the chemical transformation: Sodium (a reactive metal) + Chlorine (a toxic gas) = Sodium Chloride (safe table salt). What does this demonstrate?','["It demonstrates that mixtures are safe to eat.","It demonstrates a fundamental principle of chemistry: when elements undergo a chemical reaction to synthesize a compound, the original chemical properties of the constituent elements are destroyed, resulting in an entirely novel substance with distinct, unrelated properties.","It demonstrates that metals and gases cannot combine.","It demonstrates that table salt is actually toxic and explosive."]',1,'The explosive metal and the poison gas combine to make something you put on french fries!','When elements form a compound, the resulting substance can have properties very different from those of the original elements. For example, sodium is a highly reactive metal and chlorine is a poisonous gas... they form sodium chloride...','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_033','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Synthesize the difference in ''Proportions'' between a Mixture and a Compound.','["Mixtures have fixed proportions, compounds have variable proportions.","Compounds are defined by immutable stoichiometric ''fixed proportions'' (e.g., Water is always exactly \\\\(H_2O\\\\)). If the ratio changes, the chemical identity changes. Mixtures, however, are physical blends with highly variable proportions (e.g., saltwater can be slightly salty or extremely salty and is still considered a saltwater mixture).","Both mixtures and compounds have strictly fixed proportions.","Proportions have no effect on either mixtures or compounds."]',1,'You can''t add an extra ''O'' to water (it becomes hydrogen peroxide!), but you can add an extra spoonful of salt to a cup of saltwater!','Compound: ... chemically combined in fixed proportions... Mixture: Two or more substances combined without forming a single new substance. (Referencing Topic 5 integration: mixtures can vary).','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_034','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Evaluate the physical characteristics of ''Brass'' to determine its classification.','["Brass is a pure elemental metal.","Brass is an alloy, classifying it as a homogeneous mixture. It is created by physically melting and blending copper and zinc. Because the copper and zinc atoms do not undergo a chemical reaction to form a new molecular bond, they simply co-exist in a solid matrix, retaining their individual metallic characteristics.","Brass is a pure chemical compound.","Brass is a non-metal liquid."]',1,'Alloys are just metal smoothies; the metals are mixed, not chemically bonded!','Brass: Mixture - An alloy made mainly of copper and zinc. Brass is an example of an alloy, which is a mixture containing a metal and one or more other elements. Its components are mixed at the material level rather than forming one pure compound.','2026-11-01 08:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_035','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Analyze why separating the components of a ''Compound'' requires significantly more energy (like Electrolysis) than separating a ''Mixture''.','["Because mixtures are heavier than compounds.","Mixtures are held together only by weak physical intermolecular forces, which can be overcome by simple mechanical means (filtration) or mild thermal energy (evaporation). Compounds are held together by strong intramolecular chemical bonds (covalent/ionic), requiring massive energy input (like high-voltage electricity) to physically break the atomic connections.","Because compounds are magnetic and mixtures are not.","Because compounds are always frozen solid."]',1,'You can boil water to separate it from salt (mixture), but boiling won''t split the water itself into Hydrogen and Oxygen! You have to shock it.','Mixtures can often be separated by physical methods, such as filtration or evaporation. Compounds can sometimes be broken down into simpler substances by chemical reactions. This is different from physically separating a mixture. For example, water can be decomposed... using electrolysis, a process that uses electrical energy...','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_036','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Synthesize the nomenclature rules for a chemical symbol like ''Co'' versus ''CO''.','["They both represent the exact same chemical substance.","Capitalization is mathematically critical in chemical nomenclature. ''Co'' (Capital, lowercase) represents a single atom of the element Cobalt. ''CO'' (Capital, Capital) represents a compound molecule composed of one Carbon atom and one Oxygen atom (Carbon Monoxide).","They both represent a mixture of Carbon and Oxygen.","Neither are valid chemical symbols."]',1,'A second capital letter means a second, completely different element has started!','The first letter is always capitalised; the second, when present, is lowercase: for example, Na for sodium... CO₂... One carbon atom and two oxygen atoms...','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_037','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Critique the assertion that ''Air is a compound because it contains Oxygen and Nitrogen together.''','["The assertion is completely scientifically accurate.","The assertion represents a fundamental misunderstanding of chemical bonding. While Air contains multiple elements, those elements (like \\\\(O_2\\\\) and \\\\(N_2\\\\)) exist as independent, non-bonded molecules moving freely in the same space. Because they are not chemically bonded to each other, Air is a mixture, not a compound.","Air is actually a single pure element.","Air is a compound because it contains water vapor."]',1,'The oxygen and nitrogen in the air are floating next to each other, but they aren''t holding hands!','Air: Mixture - Contains several gases. A mixture contains two or more substances physically combined rather than chemically combined...','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_038','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Evaluate the structural representation of ''Sodium Chloride'' (NaCl) in a solid state.','["It exists as distinct, free-floating NaCl molecules.","Unlike water (\\\\(H_2O\\\\)) which forms discrete, independent molecules, solid sodium chloride forms a massive, continuous ionic crystal lattice. The formula NaCl simply represents the 1:1 empirical ratio of sodium ions to chloride ions within that infinite repeating structure, rather than a single isolated ''molecule''.","It exists as a liquid metal.","It exists as a pure element."]',1,'Salt isn''t made of tiny independent pairs of atoms; it''s a giant, perfectly organized 3D grid of alternating atoms!','Sodium chloride (NaCl) - Common table salt is a compound made of sodium and chlorine. It forms a repeating crystal structure rather than separate NaCl molecules.','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_039','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Analyze how the concept of ''Elements'' defines the absolute limit of chemical decomposition.','["Elements can be chemically broken down into smaller elements infinitely.","By definition, an element is the simplest form of chemical matter. While compounds can be decomposed into their constituent elements via chemical reactions, an element cannot be broken down into simpler chemical substances by any ordinary chemical means, because it consists of only one unique atomic identity.","Elements can be physically filtered into smaller pieces.","Elements are actually just mixtures of compounds."]',1,'You can break water down into Hydrogen and Oxygen, but you can''t break Oxygen down into anything else using normal chemistry!','An element is a pure substance made of only one kind of atom... Can it be broken down chemically into simpler substances? Element: Not by ordinary chemical methods. Compound: Often, by suitable chemical reactions.','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_040','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Synthesize why the chemical formula for water is written as \\(H_2O\\) instead of \\(HO_2\\).','["Because ''H'' comes first in the alphabet.","The subscripts dictate the fixed stoichiometric proportions required for thermodynamic stability. Water requires exactly two Hydrogen atoms to bond with one Oxygen atom to complete their valence electron shells. Writing \\\\(HO_2\\\\) represents a completely different, highly unstable ratio (one hydrogen, two oxygens) that is not water.","Because \\\\(HO_2\\\\) is the formula for ice.","There is no reason; scientists just guessed."]',1,'The numbers are the exact recipe! H2O is water; HO2 is something completely different.','Water (H₂O) - Each water molecule contains two hydrogen atoms bonded to one oxygen atom... A compound is a pure substance made when two or more different elements are chemically combined in fixed proportions.','2026-11-01 08:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_041','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Critique the common phrase: ''I am breathing in pure Oxygen.''','["The phrase is perfectly accurate for anyone on Earth.","The phrase is factually incorrect under normal atmospheric conditions. Earth''s atmosphere is a mixture composed of approximately 78% Nitrogen (\\\\(N_2\\\\)) and only 21% Oxygen (\\\\(O_2\\\\)), alongside trace gases. Unless breathing from a specialized medical tank, humans breathe a complex gas mixture, not a pure elemental substance.","The phrase is true because Nitrogen is invisible.","The phrase is false because humans only breathe Carbon Dioxide."]',1,'You are breathing in mostly Nitrogen! Pure Oxygen is only found in metal tanks at the hospital.','Air: Mixture - Contains several gases... Oxygen (O) - An element found in the air as oxygen gas...','2026-11-01 08:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_042','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Analyze the etymology of the chemical symbol ''Na'' for Sodium.','["It stands for ''Natural Air''.","Many chemical symbols are derived from their historical Latin nomenclature, ensuring universal standardisation. The symbol ''Na'' derives from ''Natrium'', the Latin word for sodium, which is why it does not match the English spelling.","It was a typo that was never corrected.","It stands for ''North America''."]',1,'Scientists used Latin as a universal language centuries ago, so the old Latin names stuck!','A chemical symbol begins with a capital letter. If it has a second letter, that letter is lowercase: for example, Na for sodium... Chemical symbols help scientists around the world communicate clearly...','2026-11-01 08:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_043','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Synthesize how ''Electrolysis'' proves that Water is a compound and not an element.','["Electrolysis freezes the water into a solid, proving it is a pure element.","Electrolysis utilizes electrical energy to overcome the covalent bonds within the water molecule. By successfully driving a chemical reaction that decomposes the water into two distinct elemental gases (Hydrogen and Oxygen), it empirically proves that water is a compound synthesized from multiple elements.","Electrolysis evaporates the water, proving it is a mixture.","Electrolysis proves that water is a magnetic metal."]',1,'If water was an element, you couldn''t break it apart into Hydrogen and Oxygen!','Compounds can sometimes be broken down into simpler substances by chemical reactions... water can be decomposed into hydrogen and oxygen using electrolysis, a process that uses electrical energy... (Synthesis: If you can break it into two different elements, it must be a compound).','2026-11-01 08:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_044','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Evaluate the physical and chemical state of ''Graphite'' (pencil lead).','["Graphite is a compound made of lead and wood.","Graphite is an elemental substance. It is composed entirely of Carbon (C) atoms arranged in a specific crystalline lattice (sheets). Despite its physical appearance differing vastly from a diamond (which is also pure carbon), chemically, graphite is a pure element containing only one kind of atom.","Graphite is a mixture of black paint and sand.","Graphite is a liquid metal."]',1,'Pencil ''lead'' isn''t lead at all; it''s pure Carbon!','Carbon (C) - An element found in living things and in materials such as graphite.','2026-11-01 08:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_elements_global_045','Chemistry','Elements and Compounds','Topic 9: Elements and Compounds','Primary',10,'Critique the classification of a ''Solution'' (like saltwater) using the definitions of Elements, Compounds, and Mixtures.','["A solution is a pure compound because it is clear.","A solution is a homogeneous mixture. While it may appear visually uniform like a pure compound, it is fundamentally a physical blend of a solvent (water, a compound) and a solute (salt, a compound). Because the water and salt do not chemically bond to form a new molecule, it remains a mixture and can be physically separated via evaporation.","A solution is a pure element because water is an element.","A solution is a solid."]',1,'It looks like one pure thing, but if you boil it, you''ll find the salt hiding inside!','Salt water: Mixture - Salt and water are combined without forming a single new substance. A mixture does not always look like a mixture. Salt water looks uniform because the salt dissolves...','2026-11-01 08:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_001','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'How do many familiar acidic foods, like lemons, typically taste?','["Sweet","Salty","Sour","Bitter"]',2,'Think of how a lemon makes your mouth pucker!','At primary-school level, you can begin by recognising that many familiar acidic solutions have a sour character.','2026-11-01 08:50:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_002','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'Which of these is a common example of an acid found in the kitchen?','["Baking soda","Vinegar","Soap","Pure water"]',1,'It is a sour liquid often used in salad dressing.','Examples [of acids] include: ... Vinegar — contains acetic acid.','2026-11-01 08:50:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_003','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What kind of acid is naturally found in lemons and oranges?','["Citric acid","Lactic acid","Acetic acid","Sulfuric acid"]',0,'It''s named after citrus fruits!','Examples include: Lemon juice — contains citric acid. Orange juice — contains citric acid...','2026-11-01 08:50:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_004','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What is a ''base''?','["A substance that produces hydrogen ions.","A substance that can react with an acid.","A type of sour food.","A type of pure water."]',1,'It is the chemical opposite of an acid.','A base is a substance that can react with an acid.','2026-11-01 08:50:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_005','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'Which of these is a common example of a mildly basic substance?','["Lemon juice","Baking soda","Vinegar","Orange juice"]',1,'It is a white powder used in baking.','Examples include: Baking soda — a mildly basic substance in water.','2026-11-01 08:50:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_006','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What do we call a base that can dissolve in water?','["An acid","An alkali","An indicator","A neutral"]',1,'It''s a special name for a wet, dissolved base.','A base that dissolves in water is called an alkali.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_007','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What is an ''indicator'' used for in chemistry?','["To make food taste better","To change colour depending on whether a solution is acidic or basic","To measure how hot a liquid is","To weigh chemicals"]',1,'It acts like a chemical traffic light!','An indicator is a substance that changes colour depending on whether a solution is acidic or basic.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_008','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What happens to Blue Litmus paper when you put it in an ACID?','["It turns red.","It stays blue.","It turns yellow.","It turns green."]',0,'Blue turns to Red in Acid!','Blue litmus paper: Turns red in an acidic solution.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_009','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What happens to Red Litmus paper when you put it in a BASE?','["It turns yellow.","It stays red.","It turns blue.","It turns black."]',2,'Red turns to Blue in Base!','Red litmus paper: Turns blue in a basic solution.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_010','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What does it mean if a solution is ''neutral''?','["It is highly acidic.","It is highly basic.","It is neither acidic nor basic overall.","It is frozen solid."]',2,'It is perfectly balanced right in the middle.','Neutral: Neither acidic nor basic overall.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_011','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'What is the pH scale used for?','["To measure how heavy a chemical is.","To measure how hot or cold a chemical is.","To describe how acidic or basic an aqueous solution is.","To measure how fast a chemical moves."]',2,'It uses numbers from 0 to 14.','The pH scale describes how acidic or basic an aqueous solution is.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_012','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'On the pH scale (0-14), what number is considered ''neutral''?','["0","14","10","7"]',3,'It is exactly in the middle of the scale.','pH of 7: neutral, under standard school-level conditions.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_013','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'On the pH scale, what do numbers below 7 (like 2 or 4) mean?','["The solution is acidic.","The solution is neutral.","The solution is basic (alkaline).","The solution is pure water."]',0,'The lower the number, the stronger the acid!','pH below 7: acidic.','2026-11-01 08:50:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_014','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'On the pH scale, what do numbers above 7 (like 10 or 12) mean?','["The solution is acidic.","The solution is basic (alkaline).","The solution is neutral.","The solution is a gas."]',1,'The higher the number, the stronger the base!','pH above 7: basic (alkaline).','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_015','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',1,'Should you ever taste a mystery liquid in a science lab to see if it is an acid?','["Yes, if it smells like lemon.","Yes, tasting is the best way to do science.","No, never taste an unknown substance because it could be dangerous or corrosive.","Yes, but only a tiny drop."]',2,'Use an indicator paper instead of your tongue!','Safety rule: Never taste an unknown substance to find out whether it is acidic. Some acids are corrosive and can cause serious injuries.','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_016','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'Why is ''red cabbage extract'' considered a natural indicator?','["Because cabbage is a red vegetable.","Because it contains natural chemicals that change color when mixed with an acid or a base.","Because cabbage is an acid.","Because cabbage smells bad."]',1,'The juice actually changes from purple to pink or green depending on the chemical!','Red cabbage indicator: a natural indicator that changes colour in acidic and basic solutions.','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_017','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'If you test pure water with both red and blue litmus paper, what will happen?','["Both papers will turn green.","The red paper will turn blue, and the blue paper will turn red.","Neither paper will change colour because pure water is neutral.","Both papers will turn white."]',2,'Because it''s neutral (pH 7), it doesn''t trigger the acid or the base color change!','Neutral: Pure water... A neutral solution generally does not change red or blue litmus paper to the opposite colour.','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_018','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'What does the word ''alkaline'' mean when talking about liquids?','["It means the liquid is an acid.","It means the liquid is pure water.","It is another word for a basic solution (a base that is dissolved in water).","It means the liquid is poisonous."]',2,'Alkaline and Basic mean the exact same thing on the pH scale!','pH above 7: basic (alkaline)... A base that dissolves in water is called an alkali.','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_019','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'If a solution has a pH of 3, how would you classify it, and what would it do to blue litmus paper?','["It is a base, and it will turn the paper red.","It is an acid, and it will turn the paper red.","It is a base, and it will keep the paper blue.","It is neutral, and it will turn the paper green."]',1,'pH 3 is below 7, so it''s an acid. Acids turn blue paper red!','pH below 7: acidic... Blue litmus paper: Turns red in an acidic solution.','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_020','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'If you mix an acid and a base together, what type of reaction usually happens?','["A combustion reaction.","A neutralisation reaction, which commonly produces salt and water.","An evaporation reaction.","A freezing reaction."]',1,'They fight each other and cancel each other out!','A neutralisation reaction occurs when an acid reacts with a base. It commonly produces a salt and water...','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_021','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'How does an ''antacid'' medicine help if you have a stomach ache caused by too much stomach acid?','["It adds more acid to digest the food faster.","It freezes the stomach acid into a solid block.","It contains a base that reacts with the excess stomach acid to neutralise it.","It creates a protective plastic coating in your stomach."]',2,'The base in the medicine cancels out the burning acid!','Everyday applications include: Antacids: certain antacid ingredients react with excess stomach acid [neutralisation].','2026-11-01 08:50:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_022','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'Why might farmers add a basic substance (like lime) to their soil?','["To make the soil bright white.","To neutralise the soil if it has become too acidic for plants to grow well.","To make the soil more acidic.","To turn the dirt into pure salt."]',1,'They are using a massive neutralisation reaction on the whole farm!','Everyday applications include: ... Agriculture: farmers may add suitable lime materials to reduce excessive soil acidity.','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_023','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'What is a ''Universal Indicator''?','["A thermometer that works in space.","An indicator that produces a range of different colours, helping you estimate the exact number on the pH scale.","An indicator that only turns blue or red.","A machine that cleans dirty water."]',1,'Instead of just two colors, it gives you a whole rainbow to tell you exactly how strong the acid or base is!','Universal indicator: produces a range of colours that can help estimate pH.','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_024','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'If you test soap with pH paper and get a pH of 9, what does this tell you about the soap?','["The soap is an acid.","The soap is neutral.","The soap is basic (alkaline).","The soap is broken."]',2,'pH 9 is higher than 7, so it is a base!','pH above 7: basic (alkaline)... Some soaps — often basic...','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_025','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'Why is ''Sodium Hydroxide'' dangerous to use in a primary school classroom?','["Because it is a strong acid.","Because it is a strong alkali (base) that is corrosive and can severely damage skin and eyes.","Because it is highly explosive.","Because it is radioactive."]',1,'Just like strong acids, strong bases can burn you badly!','Sodium hydroxide solution — a strong alkali used in some industrial processes; it is dangerous and not suitable for a school experiment. Do not touch or taste an unknown base. Strong bases can damage skin...','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_026','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'If a neutralisation reaction happens, does the final mixture ALWAYS have a perfect pH of 7?','["Yes, it always perfectly balances to exactly 7.","No, the final pH depends on exactly how much acid and base were mixed and how strong they were.","Yes, unless you stir it too fast.","No, it always ends up at exactly pH 0."]',1,'If you mix a bucket of acid with only one drop of base, it will still be very acidic!','Neutralisation does not mean that every mixture becomes exactly pH 7. The final pH depends on the quantities and strengths of the substances...','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_027','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'What kind of acid is commonly found in yoghurt?','["Citric acid","Sulfuric acid","Lactic acid","Acetic acid"]',2,'It''s what gives yoghurt that slightly sour tang!','Yoghurt — commonly contains lactic acid.','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_028','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'Why is it important to use ''indicators'' instead of touching chemicals to find out what they are?','["Because indicators are cheaper than gloves.","Because strong acids and strong bases are corrosive and can cause serious injuries if they touch your skin.","Because indicators make the chemicals smell better.","Because touching them will turn them into water."]',1,'Never touch a mystery chemical with your bare hands!','Indicators help us test substances without tasting or touching them... Some acids are corrosive and can cause serious injuries. ... Strong bases can damage skin and eyes.','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_029','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'What happens if you put a drop of vinegar (acetic acid) onto a piece of red litmus paper?','["It turns bright blue.","Nothing; the red litmus paper stays red because vinegar is an acid, not a base.","It turns black.","The paper dissolves instantly."]',1,'Red paper only changes color for bases! Because vinegar is an acid, the red paper does nothing.','Red litmus paper: Turns blue in a basic solution. Vinegar — contains acetic acid.','2026-11-01 08:50:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_030','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',5,'What is ''Turmeric'' used for in chemistry?','["To make curries spicy.","As a natural indicator that changes from yellow to reddish-brown when mixed with a base.","As a strong acid.","To measure the temperature of water."]',1,'It''s a spice in your kitchen that can actually do chemistry tricks!','Turmeric: a natural indicator that changes from yellow towards reddish-brown in the presence of many basic substances.','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_031','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Critique the chemical definition of an Acid provided in the text.','["The text defines an acid as any liquid that is sour.","The text provides the Arrhenius definition: ''An acid is a substance that produces hydrogen ions in water.'' This correctly identifies that acidity is a chemical property defined by the dissociation of molecules to yield \\\\(H^+\\\\) ions in an aqueous solution, rather than just a sensory trait like ''sourness''.","The text defines an acid as a substance that produces oxygen.","The text states that acids are solid metals."]',1,'Sourness is just how our tongue detects it; the actual chemistry is all about Hydrogen ions!','An acid is a substance that produces hydrogen ions in water.','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_032','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Analyze the mathematical nature of the pH scale. What does ''a tenfold change in hydrogen-ion activity'' mean if the pH drops from 6 to 5?','["It means the solution got 10 times colder.","The pH scale is logarithmic, not linear. A decrease of exactly 1 pH unit (from 6 to 5) means the concentration (activity) of hydrogen ions actually increased by a factor of 10. Thus, pH 5 is ten times more acidic than pH 6.","It means the solution is 10 times less acidic.","It means the solution is completely neutral."]',1,'Moving just one number on the scale is a massive jump in chemical strength!','A change of one pH unit represents a tenfold change in hydrogen-ion activity. (Synthesis: Logarithmic scale logic).','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_033','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Synthesize the chemical equation for a classic Neutralisation reaction.','["Acid + Base → Explosion + Fire","When an Arrhenius Acid (producing \\\\(H^+\\\\)) reacts with an Arrhenius Base (producing \\\\(OH^-\\\\)), the \\\\(H^+\\\\) and \\\\(OH^-\\\\) ions combine to synthesize \\\\(H_2O\\\\) (Water). The remaining constituent ions from the acid and base bond to form an ionic compound generically classified as a ''Salt''. Therefore: Acid + Base → Salt + Water.","Acid + Base → Acidic Base + Air","Acid + Water → Base + Salt"]',1,'The dangerous parts of the acid and base combine to make harmless water!','A neutralisation reaction occurs when an acid reacts with a base. It commonly produces a salt and water... Acid + Base → Salt + Water','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_034','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Evaluate the distinction between a ''Base'' and an ''Alkali''.','["They are two completely different, unrelated chemicals.","All alkalis are bases, but not all bases are alkalis. A ''base'' is the broad chemical classification for a substance that reacts with an acid. An ''alkali'' is a highly specific sub-classification: it is a base that is physically soluble in an aqueous solvent (water).","An alkali is an acid, while a base is neutral.","An alkali is a solid, while a base is a gas."]',1,'If the base can''t dissolve in water, it''s just a base. If it CAN dissolve, it gets the special name ''alkali''!','A base is a substance that can react with an acid... A base that dissolves in water is called an alkali.','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_035','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Analyze the function of ''Red Cabbage Extract'' as a pH indicator.','["It only changes color when boiled.","Red cabbage contains water-soluble anthocyanin pigment molecules. The molecular structure of these pigments physically alters when exposed to varying concentrations of hydrogen ions (\\\\(H^+\\\\)). This structural change shifts the wavelength of light they absorb/reflect, creating a visible color spectrum (red in acid, purple in neutral, green/yellow in base).","It uses magic to guess the pH of the water.","It only works on other vegetables."]',1,'The chemical molecules in the cabbage juice literally change shape when they touch an acid!','Red cabbage indicator: a natural indicator that changes colour in acidic and basic solutions... Indicator: A substance that changes colour to help identify acidity...','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_036','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Critique the assertion that ''Adding any amount of base to an acid makes the solution perfectly safe and neutral.''','["The assertion is true; any base will instantly neutralize any acid perfectly.","The assertion is dangerous. Neutralization is a strict stoichiometric process. If you add a weak base to a highly concentrated strong acid, or if you do not add a sufficient molar quantity of the base, the resulting solution will remain highly acidic and corrosive. Furthermore, the reaction itself can be violently exothermic (producing extreme heat).","The assertion is true only if you stir it very slowly.","The assertion is false because bases actually make acids stronger."]',1,'It''s a math equation; if you have 100 acid molecules and only 10 base molecules, you still have 90 acid molecules left over!','Neutralisation does not mean that every mixture becomes exactly pH 7. The final pH depends on the quantities and strengths of the substances and other conditions.','2026-11-01 08:50:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_037','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Synthesize how ''Indicators'' relate to the concept of ''Chemical Changes'' from the previous topic.','["Indicators cause physical changes by melting the liquid.","The color shift of an indicator is empirical evidence of a temporary, reversible chemical reaction. The indicator molecule chemically reacts with the \\\\(H^+\\\\) ions in the solution, forming a new, slightly different molecular structure that reflects a different color of light. This is a classic visual clue of a chemical change.","Indicators do not undergo any changes at all.","Indicators undergo a change of state from solid to gas."]',1,'The indicator itself is doing a tiny chemical reaction in the cup to change its color!','An indicator is a substance that changes colour... (Synthesis with Topic 10: ''A lasting colour change'' is a clue of a chemical change).','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_038','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Evaluate the physical characteristics of ''Pure Water'' regarding its pH.','["Pure water has a pH of 0 because it has no chemicals.","Chemically pure water (\\\\(H_2O\\\\)) at standard temperature has a perfect equilibrium of hydrogen ions (\\\\(H^+\\\\)) and hydroxide ions (\\\\(OH^-\\\\)). Because these acidic and basic ions are perfectly balanced, the solution exerts no net acidic or basic properties, resulting in a perfectly neutral pH of exactly 7.0.","Pure water has a pH of 14 because it is totally safe.","Pure water has a fluctuating pH that changes every day."]',1,'Pure water is the definition of a perfect tie on the pH scale!','Neutral: Neither acidic nor basic overall - Pure water under ordinary conditions. pH of 7: neutral...','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_039','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Analyze the environmental chemistry of ''Wastewater Treatment'' utilizing neutralisation.','["Wastewater is boiled until it turns into pure acid.","Industrial and municipal wastewater is often highly acidic or basic due to chemical runoff. Releasing this into the ecosystem causes severe environmental degradation. Treatment plants utilize bulk neutralisation (injecting strong acids or bases) to artificially force the wastewater''s pH back to a neutral ~7.0 before discharging it safely into rivers.","Wastewater is frozen to separate the acids and bases.","Wastewater treatment uses magnets to pull the acid out of the water."]',1,'Factories have to fix the pH of their dirty water so they don''t dump burning acid into a natural river!','Everyday applications include: ... Wastewater treatment: controlled chemical treatment can adjust pH.','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_040','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Synthesize why ''Tap Water'' is rarely a perfect pH 7.','["Because tap water is actually a weak acid.","As established in previous topics, tap water is a homogeneous mixture (a solution), not pure \\\\(H_2O\\\\). It contains dissolved atmospheric gases (like \\\\(CO_2\\\\), which forms weak carbonic acid) and dissolved ground minerals (which can act as bases). This complex mixture of solutes shifts the pH slightly away from a perfect neutral 7.","Because tap water is artificially dyed to trick indicators.","Because tap water is highly alkaline and corrosive."]',1,'The tiny invisible minerals mixed into the tap water push the pH scale slightly off center!','The classification depends on the substance and its concentration. For example, tap water may have a pH slightly above or below 7 because of dissolved minerals and gases.','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_041','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Critique the experimental design: A student tests a clear liquid with Blue Litmus paper. The paper stays blue. The student concludes the liquid is a Base. Is this accurate?','["Yes, if it stays blue, it is 100% a base.","The conclusion is logically flawed. Blue litmus paper only changes to red in the presence of an acid. If it stays blue, the liquid could be a base, OR it could be perfectly neutral (like pure water). To confirm it is a base, the student MUST test it with Red Litmus paper to see if it turns blue.","No, because litmus paper only works on colored liquids.","Yes, because blue litmus paper turns red in a base."]',1,'Water (neutral) won''t change the blue paper either! You have to use both colors of paper to be sure.','Blue litmus paper: Turns red in an acidic solution... A neutral solution generally does not change red or blue litmus paper to the opposite colour. (Synthesis: Staying blue doesn''t prove it''s a base, it just proves it''s NOT an acid).','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_042','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Analyze the term ''Corrosive'' in the context of strong acids and bases.','["Corrosive means it smells bad.","A corrosive substance causes catastrophic, irreversible chemical degradation of materials it contacts. In biological tissue, highly concentrated \\\\(H^+\\\\) (acids) or \\\\(OH^-\\\\) (bases) ions violently react with and destroy lipids and proteins (cell membranes), causing severe chemical burns that are fundamentally different from thermal burns.","Corrosive means the substance is radioactive.","Corrosive means the substance freezes water instantly."]',1,'Corrosive chemicals literally eat away and destroy your skin through a violent chemical reaction!','Some acids are corrosive and can cause serious injuries. ... Strong bases can damage skin and eyes.','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_043','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Synthesize the interaction between ''Baking Soda'' and an acidic ingredient in baking (like lemon juice or buttermilk).','["They freeze the bread dough.","Baking soda is a base (Sodium Bicarbonate). When mixed with an acid in a wet dough, a rapid neutralisation reaction occurs. This chemical change produces a salt, water, and crucially, Carbon Dioxide (\\\\(CO_2\\\\)) gas. The \\\\(CO_2\\\\) gas bubbles become trapped in the dough, physically expanding it (leavening) to create fluffy baked goods.","They turn the dough into pure sugar.","They cause the bread to shrink and become hard."]',1,'The acid and base fight in the dough, and the gas they create puffs the bread up!','Baking soda — a mildly basic substance... A neutralisation reaction occurs when an acid reacts with a base. (Synthesis with Topic 10: Baking a cake: ingredients react... gas bubbles forming).','2026-11-01 08:50:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_044','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Evaluate the physiological mechanism of ''Antacids'' using chemical principles.','["Antacids coat the stomach in a thick layer of plastic.","The human stomach utilizes strong Hydrochloric Acid (HCl) for digestion. Overproduction causes discomfort. Antacids are formulated with weak, safe bases (like Calcium Carbonate or Magnesium Hydroxide). Ingesting them triggers a neutralizing chemical reaction directly inside the stomach, reducing the free \\\\(H^+\\\\) ion concentration and raising the pH back to a comfortable level.","Antacids use electricity to destroy the stomach acid.","Antacids are strong acids that out-compete the stomach acid."]',1,'You are swallowing a safe base to chemically cancel out the painful acid in your belly!','Antacids: certain antacid ingredients react with excess stomach acid [neutralisation reaction].','2026-11-01 08:50:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_acids_global_045','Chemistry','Acids, Bases and Indicators','Topic 11: Acids, Bases and Indicators','Primary',10,'Critique the use of ''Taste'' as a historical scientific method for identifying acids and bases.','["Taste is the most accurate and safe way to measure pH.","Historically, chemists defined acids as ''sour'' and bases as ''bitter''. While true for weak, edible compounds, relying on the human gustatory system (taste) as a diagnostic tool is lethally flawed. Strong acids and bases will instantly cause severe corrosive necrosis of the tongue and esophageal tissues before a taste can be registered.","Taste only works if the liquid is boiling hot.","Taste is completely accurate but only for bases, not acids."]',1,'A lemon is sour (weak acid), but battery acid is so strong it would destroy your tongue before you could taste it!','At primary-school level, you can begin by recognising that many familiar acidic solutions have a sour character... Safety rule: Never taste an unknown substance... Some acids are corrosive and can cause serious injuries.','2026-11-01 08:50:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_001','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is the chemical formula for water?','["CO₂","O₂","H₂O","NaCl"]',2,'It has two hydrogen atoms and one oxygen atom.','Its chemical formula is H₂O.','2026-11-01 08:51:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_002','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What two elements make up water?','["Carbon and Oxygen","Hydrogen and Oxygen","Helium and Hydrogen","Nitrogen and Oxygen"]',1,'Think of the letters in H₂O.','Water is a chemical substance made of hydrogen and oxygen.','2026-11-01 08:51:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_003','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is the solid state of water called?','["Water vapour","Rain","Steam","Ice"]',3,'It is cold and hard.','Solid: Ice. Example: Ice cubes, snow.','2026-11-01 08:51:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_004','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is the gas state of water called?','["Water vapour","Ice","Liquid water","Rain"]',0,'It is invisible in the air.','Gas: Water vapour. Example: Invisible water gas in the air.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_005','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'Where is most of Earth''s water found?','["Rivers","Glaciers","Oceans and seas","Underground"]',2,'Think of the largest bodies of water.','Oceans and seas: Very large bodies of salty water. Most of Earth''s water is saltwater.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_006','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'Is ocean water mostly freshwater or saltwater?','["Freshwater","Saltwater","Pure water","Drinking water"]',1,'It tastes very salty.','Most of Earth''s water is saltwater.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_007','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'In the water cycle, what is it called when the Sun warms water into a gas?','["Condensation","Evaporation","Precipitation","Infiltration"]',1,'Liquid turning to gas.','Evaporation: The Sun warms liquid water, causing some of it to become water vapour and enter the air.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_008','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'In the water cycle, what is it called when water vapour cools to form clouds?','["Evaporation","Precipitation","Condensation","Collection"]',2,'Gas turning to liquid.','Condensation: Water vapour cools and changes into tiny liquid droplets or ice crystals, helping clouds form.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_009','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is water falling from clouds as rain or snow called?','["Evaporation","Condensation","Precipitation","Collection"]',2,'Weather falling from the sky.','Precipitation: Water falls from clouds as rain, snow, sleet, or hail.','2026-11-01 08:51:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_010','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is a ''solvent''?','["A substance that freezes","A substance that dissolves another substance","A substance that pollutes","A substance that is dissolved"]',1,'Water is a common solvent.','A solvent is a substance that dissolves another substance.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_011','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'When you mix salt and water, what is the salt?','["The solvent","The solution","The mixture","The solute"]',3,'It is the solid that seems to disappear.','Solute: salt, the substance being dissolved.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_012','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'If water from a stream looks clear, is it always safe to drink?','["Yes, clear water is safe.","No, it may contain invisible germs or chemicals.","Yes, if it is moving.","No, it must be green."]',1,'You cannot see microscopic germs.','No. Water may look clear and still contain bacteria, viruses, parasites, or dissolved chemicals that cannot be seen.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_013','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is ''water conservation''?','["Wasting water.","Using water carefully and protecting resources.","Making water salty.","Leaving taps running."]',1,'Saving water.','Water conservation means using water carefully while ensuring that people and ecosystems have the water they need.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_014','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'What is water stored beneath Earth''s surface called?','["Rain","Glaciers","Oceans","Groundwater"]',3,'It is hidden underground.','Groundwater: Water stored beneath Earth''s surface.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_015','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',1,'Why do plants need water?','["To stay warm.","For photosynthesis and transporting minerals.","To change leaf color.","They do not need water."]',1,'They drink it from the soil.','Plants use water in photosynthesis. Water carries dissolved minerals from roots to other parts of a plant.','2026-11-01 08:51:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_016','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Why is water known as a ''universal solvent''?','["It exists throughout the universe.","It can dissolve many different substances.","It never dissolves anything.","It dissolves all metals instantly."]',1,'It''s excellent at dissolving things like salt and sugar.','Water is often called a universal solvent because it dissolves many different substances, although it does not dissolve everything.','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_017','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'What provides the energy that drives the water cycle?','["Earth''s core","The Moon","The Sun","Wind"]',2,'The heat makes water evaporate.','The Sun provides energy that drives much of this cycle.','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_018','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'What stage of the water cycle is responsible for forming clouds?','["Evaporation","Precipitation","Infiltration","Condensation"]',3,'Invisible vapour turning into visible droplets.','Condensation: Water vapour cools and changes into tiny liquid droplets or ice crystals, helping clouds form.','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_019','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Boiling water kills disease-causing microorganisms, but what does it fail to do?','["It fails to heat the water.","It fails to remove dissolved chemical contaminants.","It fails to kill bacteria.","It fails to turn water into vapour."]',1,'Boiling doesn''t remove poisons or heavy metals.','Boiling can kill many disease-causing microorganisms, but it does not remove most dissolved chemical contaminants and may concentrate some of them.','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_020','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Why is accessible freshwater limited despite Earth having so much water?','["Freshwater evaporates instantly.","Humans drink it all every day.","Most water is saltwater in oceans, and much freshwater is trapped in glaciers or underground.","Freshwater is only found in clouds."]',2,'We cannot drink ocean water, and glaciers are frozen.','Most of Earth''s water is saltwater. Only a small fraction is freshwater that is readily accessible for human use. Much freshwater is stored in glaciers, ice sheets, and underground.','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_021','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'What happens to salt particles when they dissolve in water?','["They are destroyed completely.","They turn into water molecules.","They spread through the water as tiny charged particles called ions.","They float to the surface."]',2,'They break into invisible pieces but are still there.','When salt dissolves, it spreads through the water as tiny charged particles called ions. The salt has not simply vanished...','2026-11-01 08:51:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_022','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Why should old paints and medicines not be poured down the drain?','["They will clean the pipes.","They cause water pollution that harms aquatic ecosystems.","They evaporate and cause rain.","They turn into pure water."]',1,'What goes down the drain reaches nature.','Avoid pouring oils, paints, medicines, or chemicals into drains... Water pollution happens when harmful substances or organisms enter water and make it unsafe or damage ecosystems.','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_023','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'How does drinking water help the human body?','["It stops the heart from beating.","It prevents digestion.","It helps maintain water balance and regulate body temperature.","It turns blood into a solid."]',2,'Sweating helps cool you down.','For people: Drinking helps the body maintain its water balance. Water helps regulate body temperature.','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_024','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'How can chemical fertilizers from a farm pollute a nearby lake?','["The fertilizers evaporate.","Runoff from rain washes the fertilizers off the farmland into the lake.","The fertilizers walk to the lake.","The lake absorbs them through the air."]',1,'Rain washes the dirt away.','Common sources [of pollution] include: ... Fertilisers and pesticides washed from farmland. Runoff carrying soil and other pollutants.','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_025','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'What happens in the ''infiltration'' stage of the water cycle?','["Water falls from the sky.","Water turns into a gas.","Water soaks into the ground and replenishes groundwater.","Water turns into ice."]',2,'Water acting like it''s soaking into a sponge.','Collection and infiltration: Water gathers in rivers, lakes, and oceans. Some soaks into the ground and replenishes groundwater.','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_026','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Is the freezing of water into ice a physical or chemical change?','["Chemical, because ice is a new substance.","Physical, because it changes state but remains H₂O.","Chemical, because it gets cold.","Neither, it is an illusion."]',1,'Ice is just frozen water.','Water changes state when it gains or loses thermal energy... (Since it remains H₂O, it is a physical change, linking to Topic 10).','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_027','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'What happens if you mix cooking oil and water?','["They form a uniform solution.","They do not mix evenly and form separate layers.","They explode.","The oil dissolves the water."]',1,'Oil and water don''t mix.','Cooking oil does not mix evenly with water.','2026-11-01 08:51:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_028','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Why is water conservation necessary?','["Because water is turning into solid rock.","Because humans don''t need water.","Because accessible freshwater is limited and in high demand.","Because the oceans are drying up."]',2,'We only have a tiny amount of fresh drinking water.','Freshwater is limited in many places, and demand can put pressure on rivers, lakes, and groundwater.','2026-11-01 08:51:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_029','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'Why are wetlands important?','["They are dry deserts.","They provide habitats and food sources for aquatic plants and animals.","They boil water naturally.","They are a source of saltwater."]',1,'They are homes for wildlife.','Rivers, lakes, wetlands, and oceans provide habitats and food sources.','2026-11-01 08:51:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_030','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',5,'How can you recover solid salt from a saltwater solution?','["Filtration","Handpicking","Evaporation","Freezing"]',2,'Boiling the water away leaves the salt.','If the water is removed by suitable evaporation, salt can be recovered.','2026-11-01 08:51:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_031','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Critique the claim that ''Boiling water makes it 100% safe to drink from any polluted source.''','["It is true; boiling destroys all contaminants.","It is false. Boiling denatures biological pathogens (killing germs), but it does not remove dissolved chemical contaminants. Evaporating the solvent can actually concentrate the remaining toxic chemical solutes.","It is true, but only if boiled for two hours.","It is false because boiling creates new bacteria."]',1,'Boiling kills germs, but makes poisons more concentrated!','Boiling can kill many disease-causing microorganisms, but it does not remove most dissolved chemical contaminants and may concentrate some of them.','2026-11-01 08:51:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_032','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Analyze the thermodynamic process of ''Evaporation'' in the water cycle.','["It is driven by lunar gravity.","It is an endothermic process driven by solar radiation. Thermal energy increases the kinetic energy of liquid water molecules until they overcome intermolecular cohesive forces (hydrogen bonds) and escape as a gas.","It is driven by the cooling of the Earth.","It is a chemical reaction that breaks H₂O into H₂ and O₂."]',1,'Heat makes the molecules vibrate fast enough to break free!','The Sun provides energy that drives much of this cycle... Evaporation: The Sun warms liquid water, causing some of it to become water vapour...','2026-11-01 08:51:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_033','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Synthesize the ecological impact of agricultural ''Runoff'' containing fertilizers.','["It cleans rivers by removing algae.","Nitrogen-rich fertilizers cause eutrophication. This hyper-stimulates algal growth (blooms). When the algae die, decomposing bacteria consume the dissolved oxygen, creating hypoxic ''dead zones'' that suffocate aquatic life.","It creates pure water for fish.","It freezes the lakes."]',1,'Too much fertilizer makes pond scum grow out of control, killing the fish.','Common sources include: ... Fertilisers and pesticides washed from farmland... Polluted water can harm people, aquatic animals, and plants.','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_034','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Evaluate the physical characteristics of ''Groundwater'' versus ''Surface Water''.','["Groundwater is saltwater; surface water is freshwater.","Surface water is highly exposed to rapid contamination and evaporation. Groundwater in aquifers is generally filtered by soil layers, making it often cleaner, but it recharges very slowly and is vulnerable to persistent, long-term chemical leaching.","Groundwater is frozen solid.","They are perfectly identical."]',1,'Groundwater takes a very long time to fill up from rain.','Groundwater: Water stored beneath Earth''s surface... Some soaks into the ground and replenishes groundwater. Freshwater is limited...','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_035','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Analyze why water is highly effective at dissolving ionic compounds like NaCl.','["Water is a non-polar solvent.","Water is a highly polar molecule with partial positive and negative charges. These charged poles exert strong electrostatic attraction on the positive sodium ions and negative chloride ions, pulling the crystal lattice apart and hydrating the ions.","Water chemically destroys the sodium.","Water repels the salt magnetically."]',1,'Water molecules act like tiny magnets pulling the salt apart.','When salt dissolves, it spreads through the water as tiny charged particles called ions. (Synthesis of water''s polarity).','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_036','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Synthesize how ''Conservation of Mass'' applies to the global Water Cycle.','["The cycle creates new water every day.","The global water cycle is a closed thermodynamic system regarding mass. Water continuously changes state and location, but the total mass of H₂O on Earth remains constant. It is neither created nor destroyed, merely cycled.","The cycle destroys water through evaporation.","The cycle relies on meteors bringing new water."]',1,'The water you drink is the exact same water the dinosaurs drank!','The water cycle is the continuous movement of water between Earth''s surface and the atmosphere... The cycle repeats continuously.','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_037','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Critique the assumption that ''Rainwater is always the purest, safest form of water to consume.''','["The assumption is scientifically flawless.","The assumption is flawed. As water vapor condenses and falls as rain, it acts as an atmospheric solvent. It readily absorbs atmospheric pollutants (causing acid rain) and particulate matter (smog), meaning raw rainwater often requires filtration.","The assumption is true because rain falls from clean clouds.","The assumption is false because rain is saltwater."]',1,'Rain falls through polluted city air and absorbs the smog.','Rain: ... low in dissolved salts, but its quality varies... Water may look clear and still contain... dissolved chemicals...','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_038','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Evaluate the environmental impact of ''Thermal Pollution'' (releasing hot, chemically clean water into a river).','["It keeps fish warm in winter.","Releasing hot water drastically alters the local ecosystem. Increased temperature significantly decreases the solubility of dissolved oxygen in the water (leading to hypoxia) and triggers thermal shock, disrupting the reproductive cycles of native aquatic species.","It has zero impact if the water is clean.","It freezes the river solid."]',1,'Hot water holds less oxygen, causing fish to suffocate.','Water pollution happens when harmful substances or organisms enter water and make it unsafe or damage ecosystems. Industrial waste released without proper treatment. (Thermal energy is a pollutant).','2026-11-01 08:51:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_039','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Analyze the chemical composition of ''Ice'' versus ''Liquid Water''.','["Ice contains more hydrogen.","Chemically, they are absolutely identical; both consist exclusively of H₂O molecules. The difference is purely physical (kinetic). In liquid water, molecules have enough thermal energy to flow. In ice, lower thermal energy forces molecules into a rigid crystalline lattice.","Ice is a compound, liquid water is a mixture.","Ice contains no oxygen."]',1,'Freezing locks the exact same molecules in place.','Water is a chemical substance made of hydrogen and oxygen. Its chemical formula is H₂O... Water changes state when it gains or loses thermal energy.','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_040','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Synthesize why ''Desalination'' (removing salt from ocean water) is not the primary source of global drinking water.','["Ocean water has no water in it.","While oceans are abundant, desalination (reverse osmosis/distillation) is extraordinarily energy-intensive and economically expensive. It also produces a highly concentrated toxic brine byproduct that is difficult to dispose of without harming marine ecosystems.","Humans are allergic to sea water.","Desalination makes water radioactive."]',1,'It takes massive amounts of electricity to squeeze the salt out of ocean water.','Most of Earth''s water is saltwater. Only a small fraction is freshwater that is readily accessible for human use. (Synthesis: Why don''t we use the ocean? Because separating the mixture is hard and costly).','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_041','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Evaluate the physical property of ''Density'' as water transitions from a liquid to a solid.','["Water becomes incredibly dense when it freezes.","Water exhibits a rare physical anomaly: it expands as it freezes into a solid crystalline lattice. This expansion causes solid ice to have a lower density than liquid water, causing it to float. If ice were denser, oceans would freeze solid from the bottom up.","Water''s density does not change.","Ice becomes a gas with zero density."]',1,'Ice cubes float because the water expanded and got lighter when it froze.','State: Solid. Name: Ice. Example: Ice cubes... (Synthesis: Ice floats, an essential property of water).','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_042','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Critique the effectiveness of ''Filtration'' for making seawater safe to drink.','["Filtration works perfectly.","Filtration is entirely ineffective for desalination. Sodium and chloride ions are dissolved at the molecular level, meaning they easily pass through the microscopic pores of standard mechanical filters along with the water molecules. Separation requires phase-change methods.","Filtration works if the paper is thick enough.","Filtration turns the saltwater into a poisonous gas."]',1,'The salt pieces are too tiny; they swim right through the holes in the filter paper.','When salt dissolves, it spreads through the water as tiny charged particles called ions. (Synthesis with Topic 7: Dissolved particles pass through ordinary filters).','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_043','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Analyze how ''Transpiration'' in plants contributes to the global Water Cycle.','["Plants absorb water vapor from the air to make rain.","Transpiration is the biological equivalent of evaporation. Plants absorb liquid groundwater through roots, transport it through their vascular system, and release it as water vapor through microscopic pores (stomata) in their leaves, actively moving massive volumes of water back into the atmosphere.","Plants turn water into solid rocks.","Transpiration is how plants drink rain directly from clouds."]',1,'Plants sweat invisible water vapor into the air.','For plants: ... Water carries dissolved minerals from roots to other parts... The water cycle... Water may follow different routes... be taken up by plants, or return to the atmosphere.','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_044','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Synthesize the concept of a ''Watershed'' in relation to water pollution.','["A watershed is a building where water is stored.","A watershed is a topographical land area where all precipitation drains to a common central outlet (a specific river/lake). This means pollution (like oil/agricultural runoff) dropped anywhere within that vast area will eventually flow into and contaminate that single, shared body of water.","A watershed is a type of boat that cleans pollution.","A watershed is a mathematical formula."]',1,'If you dump oil on a hill miles away, the rain will eventually wash it down into the river at the bottom of the valley.','Common sources [of pollution] include: ... Runoff carrying soil and other pollutants. (Synthesis: Geography dictates how runoff travels).','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_water_global_045','Chemistry','Water and Its Importance','Topic 12: Water and Its Importance','Primary',10,'Evaluate the role of ''Wetlands'' (swamps/marshes) as natural water treatment ecosystems.','["Wetlands create pollution.","Wetlands act as massive, natural bio-filters. As slow-moving runoff water passes through, the dense network of plant roots and specialized soil bacteria trap sediments, absorb excess agricultural nutrients, and break down toxic pollutants, significantly purifying the water.","Wetlands boil the water to kill germs.","Wetlands freeze the water to trap pollution."]',1,'The plants and mud in a swamp act like a giant sponge that filters and cleans dirty water.','Protect wetlands, rivers, lakes... Wetlands provide habitats... Water conservation means... ensuring that people and ecosystems have the water they need. (Synthesis: Ecosystems provide purification services).','2026-11-01 08:51:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_001','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What is ''air''?','["A single pure gas","A mixture of several different gases","A type of invisible liquid","Only oxygen"]',1,'It is not just one thing!','Air is a mixture of gases that surrounds Earth.','2026-11-01 08:51:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_002','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What do we call the layer of gases that surrounds our planet?','["The ocean","The crust","The atmosphere","Outer space"]',2,'It acts like a blanket around Earth.','The layer of gases around our planet is called the atmosphere.','2026-11-01 08:51:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_003','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'Which gas makes up the largest part (about 78%) of dry air?','["Oxygen","Carbon dioxide","Helium","Nitrogen"]',3,'It starts with an N.','Nitrogen makes up about 78% of dry air.','2026-11-01 08:51:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_004','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'Approximately what percentage of dry air is Oxygen?','["1%","21%","50%","78%"]',1,'It is the second most common gas in the air.','Oxygen makes up about 21% of dry air.','2026-11-01 08:51:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_005','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What gas do humans and many other animals need to breathe in to survive?','["Nitrogen","Carbon dioxide","Oxygen","Helium"]',2,'You take a deep breath of this!','Humans and many other organisms use oxygen during cellular respiration... Most animals need oxygen to survive.','2026-11-01 08:51:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_006','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What gas do humans and animals breathe OUT (release) as a waste product?','["Oxygen","Nitrogen","Carbon dioxide","Argon"]',2,'Plants need the gas that we breathe out!','Humans and animals release carbon dioxide during respiration.','2026-11-01 08:51:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_007','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What gas do plants need to take in to make their own food (photosynthesis)?','["Oxygen","Nitrogen","Helium","Carbon dioxide"]',3,'They use the gas that we breathe out!','Plants use carbon dioxide during photosynthesis to make sugars.','2026-11-01 08:51:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_008','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'When you blow up a balloon, it gets bigger. What property of gas does this show?','["Gases are heavy.","Gases occupy space.","Gases are always hot.","Gases turn into solids."]',1,'The invisible air takes up room inside the rubber.','Gases occupy space. When air enters a balloon, the balloon expands. The air takes up space inside it.','2026-11-01 08:51:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_009','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What is it called when a gas spreads out to fill a room (like smelling perfume)?','["Freezing","Melting","Diffusion","Combustion"]',2,'The smell spreads through the air.','Gases spread out: Gas particles move around and mix with other gases. This spreading is called diffusion.','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_010','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What is the scientific word for ''burning''?','["Diffusion","Combustion","Condensation","Respiration"]',1,'It involves fire and heat.','Burning is a chemical reaction called combustion.','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_011','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'Which gas is required to keep a normal fire burning?','["Carbon dioxide","Nitrogen","Oxygen","Argon"]',2,'Fires need to ''breathe'' this gas too!','Many familiar fires need oxygen to continue... Oxygen: supports the combustion reaction.','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_012','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What are the three things a fire needs to burn (the ''fire triangle'')?','["Water, dirt, and air","Fuel, oxygen, and heat","Wood, match, and smoke","Light, sound, and gas"]',1,'You need something to burn, a gas, and a spark!','A simple way to remember the three essentials of a typical fire is the fire triangle: Fuel... Oxygen... Heat...','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_013','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'Which of these is a common cause of air pollution?','["Planting trees","Riding a bicycle","Exhaust from cars and vehicles","Drinking water"]',2,'The smoke coming out of cars makes the air dirty.','Common sources include: Exhaust from vehicles. Smoke from burning fuels...','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_014','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What can air pollution do to humans?','["Make them run faster.","Irritate their eyes and lungs, and worsen breathing problems.","Give them better eyesight.","Nothing, it is harmless."]',1,'Dirty air makes it hard to breathe.','Air pollution can irritate the eyes and lungs, worsen breathing problems...','2026-11-01 08:51:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_015','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',1,'What is one way you can help reduce air pollution?','["Leave all the lights on in your house.","Burn your rubbish in the garden.","Walk or ride a bike instead of taking a car.","Cut down trees."]',2,'Using your own energy instead of an engine helps the air!','How can we help reduce air pollution? Walk, cycle, or use public transport when practical...','2026-11-01 08:51:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_016','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'If you can''t see air, how can you prove it is actually there (that it is matter)?','["Because it has a color.","Because you can observe its physical effects, like wind moving tree branches, or feel resistance when moving fast.","Because it tastes sweet.","You cannot prove it is there."]',1,'You can feel the wind push against your hand!','Air is usually invisible, but we can observe its effects: Wind moves leaves and branches... Air resistance slows a moving object.','2026-11-01 08:51:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_017','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Why do scientists usually describe the percentages of gases in ''dry air'' instead of normal air?','["Because water vapor in normal air is invisible.","Because the amount of water vapor (humidity) constantly changes depending on the weather and location, making it impossible to give one fixed percentage for normal air.","Because normal air doesn''t have any oxygen in it.","Because dry air is easier to breathe."]',1,'A jungle has very wet air, but a desert has very dry air!','These percentages are approximate. Water vapour is not included in the standard dry-air percentages because its amount changes from place to place and over time.','2026-11-01 08:51:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_018','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Even though Nitrogen makes up 78% of the air, why can''t most plants just pull it straight from the air to grow?','["Because Nitrogen is a solid.","Because plants can only breathe Oxygen.","Most plants cannot use nitrogen gas directly from the air; they rely on specific microorganisms in the soil to convert it into a usable form.","Because Nitrogen is poisonous to all plants."]',2,'The plants need helpful bacteria in the dirt to ''digest'' the nitrogen for them first!','Most plants cannot use nitrogen gas directly from the air. Certain microorganisms convert nitrogen into forms plants can use.','2026-11-01 08:51:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_019','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Why is Carbon Dioxide (CO₂) considered important for Earth, even though there is very little of it in the air?','["Because it is the only gas humans breathe.","Because plants need it to make food (photosynthesis), and it helps trap heat in the atmosphere to keep the Earth warm.","Because it makes the sky blue.","Because it turns into pure gold when it rains."]',1,'Without it, plants would starve and the Earth would freeze!','Plants use carbon dioxide during photosynthesis to make sugars... Carbon dioxide helps trap heat in Earth''s atmosphere.','2026-11-01 08:51:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_020','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'How does a bicycle pump prove that gases can be compressed?','["The pump makes the air disappear.","The pump turns the air into a liquid.","The pump pushes a large amount of air into the small space of the tyre, forcing the air particles closer together and increasing the pressure.","The pump takes air out of the tyre."]',2,'You are squishing more and more air into a tiny rubber tube!','Gases can be compressed: Pushing air into a smaller space increases its pressure. This is how pumps help inflate tyres.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_021','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'If you spray perfume in one corner of a room, why can someone in the opposite corner eventually smell it?','["Because the perfume is magnetic.","Because of diffusion; the gas particles of the perfume constantly move around and naturally spread out to mix with the air throughout the whole room.","Because the air conditioner blows it directly at them.","Because the perfume turns into a liquid on the floor."]',1,'The tiny smell particles bounce around until they fill the whole space!','Gases spread out: Gas particles move around and mix with other gases. This spreading is called diffusion.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_022','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'If a fire needs fuel, oxygen, and heat (the fire triangle), how does throwing a thick blanket over a small fire put it out?','["The blanket makes the fire too hot.","The blanket removes the ''oxygen'' from the fire triangle by blocking fresh air from reaching the flames.","The blanket acts as extra fuel.","The blanket turns the fire into a liquid."]',1,'Without fresh air (oxygen), the fire suffocates!','A simple way to remember the three essentials of a typical fire is the fire triangle... Removing one of these essentials can help stop a fire.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_023','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'How do fish survive underwater if they need oxygen?','["Fish don''t need oxygen; they only need water.","Fish come to the surface to take a deep breath every five minutes.","Fish obtain dissolved oxygen from the water using their gills.","Fish drink the water and turn it into oxygen in their stomachs."]',2,'The water actually has tiny invisible oxygen gas particles mixed into it!','Fish: Obtain dissolved oxygen from water using their gills.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_024','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Do plants ONLY take in carbon dioxide and NEVER use oxygen?','["Yes, plants are perfectly opposite to humans.","No, plants also carry out cellular respiration, which means they use oxygen and release carbon dioxide, just like animals do.","Yes, oxygen is poisonous to plants.","No, plants only use nitrogen."]',1,'Plants breathe oxygen too, especially at night!','Plants do not simply take in carbon dioxide and release oxygen all the time. They also respire, using oxygen and releasing carbon dioxide.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_025','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'If you push an empty, upside-down glass straight down into a bowl of water, why doesn''t the water fill the glass completely?','["Because the glass is waterproof.","Because the trapped air inside the glass occupies space (it is matter) and physically prevents the water from coming in.","Because the water is too heavy.","Because the glass pushes the water away magnetically."]',1,'The invisible air is already taking up the room inside the cup!','The tissue should remain mostly dry because trapped air occupies the space inside the glass and prevents water from filling it.','2026-11-01 08:51:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_026','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'In the upside-down glass experiment, how can you let the water inside the glass?','["By adding salt to the water.","By tilting the glass slightly so the trapped air can escape as bubbles, making room for the water.","By freezing the water.","By pushing the glass down harder."]',1,'The air has to leave before the water can come in!','If you tilt the glass underwater, air can escape as bubbles and water can enter.','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_027','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Why is ''planting trees'' helpful, but NOT the only solution to air pollution?','["Because trees cause air pollution.","Because trees grow too slowly.","Because while trees help clean the air, they cannot absorb all pollution; we must also stop reducing the pollution directly at its source (like car exhaust).","Because trees only absorb oxygen."]',2,'You can''t just plant a tree and then keep polluting forever; you have to stop the smoke!','Planting trees is valuable, but it cannot replace reducing pollution at its source.','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_028','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Why does a balloon pop if you keep blowing too much air into it?','["Because the air turns into a solid.","Because you are forcing too many gas particles into a confined space, increasing the air pressure until the rubber cannot stretch any further and breaks.","Because the air inside the balloon gets too cold.","Because the air inside the balloon escapes."]',1,'The squished air pushes back so hard it rips the balloon!','Gases can be compressed: Pushing air into a smaller space increases its pressure.','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_029','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'How does ''diffusion'' relate to air pollution?','["Diffusion prevents air pollution from happening.","Diffusion causes harmful gases from a factory to spread out and mix with the clean air, carrying the pollution over a wide area.","Diffusion turns pollution into safe water.","Diffusion traps the pollution inside the factory."]',1,'This is why smoke from a fire can make a whole city smell bad!','Gases spread out: Gas particles move around and mix with other gases. This spreading is called diffusion.','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_030','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',5,'Is air a compound or a mixture? Why?','["It is a compound because it is made of oxygen and nitrogen chemically bonded together.","It is a mixture because it contains several different gases (like oxygen and nitrogen) that are just physically mixed together in the same space, not chemically bonded.","It is a pure element.","It is a liquid."]',1,'The oxygen and nitrogen molecules float right past each other without getting stuck together!','Air is not a single chemical substance. It contains several gases mixed together...','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_031','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Critique the common misconception that ''Plants only produce oxygen and animals only produce carbon dioxide.''','["The misconception is completely true biologically.","The misconception ignores plant respiration. While plants perform photosynthesis (consuming CO₂, producing O₂) during the day, all their living cells continuously perform cellular respiration (consuming O₂, producing CO₂) to generate metabolic energy, day and night.","The misconception is false because animals actually produce oxygen.","The misconception is false because plants do not use gases."]',1,'Plants have to ''breathe'' oxygen to stay alive, just like we do! They just happen to make MORE oxygen than they use during the day.','Plants do not simply take in carbon dioxide and release oxygen all the time. They also respire, using oxygen and releasing carbon dioxide.','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_032','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Analyze the thermodynamic mechanism of ''Air Pressure'' in a sealed container (like a bicycle tyre).','["Air pressure is caused by gravity pulling the air down.","Air pressure is the macroscopic result of billions of microscopic collisions. Gas particles are in constant, random, rapid motion. Pressure is the cumulative force of these particles constantly striking the interior walls of the container. Compressing the gas increases the collision frequency, thus increasing the pressure.","Air pressure is caused by the air freezing into a solid.","Air pressure is caused by the rubber tyre shrinking."]',1,'The tiny invisible air molecules are constantly punching the inside of the tyre! Squish them closer, and they punch it more often.','Gases can be compressed: Pushing air into a smaller space increases its pressure... (Synthesis of kinetic particle theory).','2026-11-01 08:51:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_033','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Synthesize how the concept of ''Diffusion'' is driven by the Kinetic Theory of Matter.','["Diffusion happens because the wind blows the gas away.","In a gas, particles possess high kinetic energy and move freely and randomly in all directions. Diffusion is the statistical result of this random thermal motion, causing particles to naturally disperse from an area of high localized concentration (where they collide often) to areas of low concentration until uniform equilibrium is reached.","Diffusion happens because gases are heavier than air.","Diffusion happens because magnets pull the gas across the room."]',1,'Because the particles are flying around at random, they naturally bump into each other and spread out into empty spaces!','Gases spread out: Gas particles move around and mix with other gases. This spreading is called diffusion. (Synthesis with particle movement).','2026-11-01 08:51:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_034','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Evaluate the chemical role of ''Oxygen'' in the process of Combustion (burning).','["Oxygen acts as the fuel that burns.","Combustion is a rapid exothermic oxidation reaction. The fuel (e.g., wood, hydrocarbons) acts as the reducing agent, and Oxygen acts as the oxidizing agent. The oxygen chemically bonds with the carbon and hydrogen in the fuel, breaking the old bonds and releasing massive thermal energy while synthesizing new products like CO₂ and H₂O.","Oxygen acts to cool the fire down so it doesn''t explode.","Oxygen is destroyed completely by the fire."]',1,'Oxygen isn''t the thing burning; it''s the chemical that RIPS the fuel apart to release the heat!','Oxygen supports combustion, which is the chemical process involved in burning. Oxygen does not normally burn by itself; it helps other substances burn.','2026-11-01 08:51:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_035','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Analyze why ''Carbon Dioxide'' (CO₂), despite being a trace gas (approx. 0.04%), is the primary driver of anthropogenic climate change.','["Because CO₂ is highly toxic to humans.","While its concentration is low compared to Nitrogen, CO₂ is a potent ''greenhouse gas''. Its specific molecular structure allows it to absorb and re-emit infrared radiation (heat) reflecting off the Earth''s surface. A seemingly tiny absolute increase in this trace gas exponentially increases the amount of thermal energy trapped in the troposphere.","Because CO₂ blocks sunlight from reaching the Earth.","Because CO₂ freezes the oceans."]',1,'It acts like a thick glass roof on a greenhouse; even a little bit traps a LOT of heat!','Carbon dioxide, or CO₂, is present in a much smaller proportion... Carbon dioxide helps trap heat in Earth''s atmosphere. Increasing atmospheric carbon dioxide from human activities contributes to global warming.','2026-11-01 08:51:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_036','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Synthesize the atmospheric cycle of ''Nitrogen'' considering its inert nature as a diatomic gas (N₂).','["Nitrogen is breathed in by animals to build muscles directly.","The triple-covalent bond in atmospheric N₂ makes it highly inert and biologically inaccessible to most life. The nitrogen cycle requires ''nitrogen fixation''—specialized soil bacteria (or high-energy events like lightning) must chemically break the N₂ bond and synthesize reactive compounds (like ammonia or nitrates) before plants can absorb it for DNA/protein synthesis.","Nitrogen is absorbed through the skin of animals.","Nitrogen reacts instantly with oxygen to make fire."]',1,'The nitrogen in the air is locked up tight; plants need bacteria to ''unlock'' it for them!','Nitrogen makes up about 78%... It is an important element in proteins and DNA... Most plants cannot use nitrogen gas directly... Certain microorganisms convert nitrogen into forms plants can use.','2026-11-01 08:51:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_037','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Critique the assertion that ''Empty space in a room contains literally nothing.''','["The assertion is scientifically flawless.","The assertion is a macroscopic illusion. What appears as ''empty space'' is actually a dense fluid mixture of atmospheric gases (Nitrogen, Oxygen, Argon) exerting roughly 14.7 psi of pressure. A true vacuum (nothingness) does not naturally exist on the Earth''s surface; the space is entirely occupied by gaseous matter.","The assertion is true because gases have zero mass.","The assertion is true if the room is completely dark."]',1,'The room is completely full of invisible air molecules!','Air is usually invisible, but we can observe its effects... Air occupies space, even when we cannot see it. (Synthesis: Invisible does not equal empty).','2026-11-01 08:51:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_038','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Evaluate the consequences of ''Particulate Matter'' (dust/smoke) as a component of Air Pollution.','["Particulate matter is harmless because it is just dirt.","While gases like CO₂ affect climate, fine particulate matter (PM2.5/PM10 from combustion or dust) poses severe acute biological risks. Because these solid microscopic particles are small enough to bypass the respiratory system''s natural filtration (cilia/mucus), they lodge deep in the alveolar tissue of the lungs, causing severe inflammation, asthma, and systemic cardiovascular damage.","Particulate matter only affects the color of buildings.","Particulate matter makes the air smell like flowers."]',1,'Tiny bits of floating soot and dust can get trapped deep inside your lungs and make you very sick!','Air pollution occurs when harmful gases or particles enter the air... Common sources include: ... Smoke... Dust... Air pollution can irritate the eyes and lungs, worsen breathing problems...','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_039','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Analyze the physical principle demonstrated by placing a dry tissue in an inverted glass and submerging it in water.','["It proves that glass is impermeable to water.","The experiment empirically demonstrates that air is physical matter (occupies volume). Because two distinct masses of matter cannot occupy the same volume simultaneously, the trapped atmospheric gas exerts pressure against the liquid water, preventing the fluid from displacing the gas and entering the rigid container.","It proves that tissues absorb oxygen.","It proves that water is heavier than glass."]',1,'The water can''t go in because the air refuses to get out of the way!','Observation: The tissue should remain mostly dry because trapped air occupies the space inside the glass and prevents water from filling it... Conclusion: Air is invisible, but it occupies space.','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_040','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Synthesize how the ''Fire Triangle'' dictates the function of a Carbon Dioxide (CO₂) fire extinguisher.','["The extinguisher adds more fuel to burn the fire out faster.","A CO₂ extinguisher attacks two legs of the fire triangle. First, CO₂ is a dense, non-combustible gas; it rapidly blankets the fuel source, displacing the lighter atmospheric Oxygen (suffocation). Second, the rapid expansion of the compressed CO₂ gas from the nozzle is highly endothermic, absorbing massive amounts of Heat (cooling).","The extinguisher turns the fire into a liquid.","The extinguisher creates a vacuum that sucks the fire away."]',1,'The heavy CO2 gas pushes the Oxygen away so the fire suffocates!','A simple way to remember the three essentials of a typical fire is the fire triangle: Fuel... Oxygen... Heat... Removing one of these essentials can help stop a fire.','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_041','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Critique the idea that ''Air resistance is a nuisance that only slows things down.''','["Air resistance is entirely useless and should be eliminated.","While air resistance (aerodynamic drag) opposes kinetic motion (reducing vehicle efficiency), it is biologically and physically essential. It is the fluid friction that allows parachutes to function, birds and airplanes to generate aerodynamic lift for flight, and it provides the friction necessary to incinerate meteors before they strike the Earth''s surface.","Air resistance is actually what makes cars move forward.","Air resistance only exists in outer space."]',1,'Without air resistance, airplanes couldn''t fly, and parachutes wouldn''t work!','Air is usually invisible, but we can observe its effects: ... Air resistance slows a moving object. (Synthesis: applying the concept to broader physics).','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_042','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Analyze the chemical relationship between ''Decomposers'' and the atmospheric gas cycle.','["Decomposers destroy all gases, removing them from the cycle.","Decomposers (bacteria/fungi) are critical recycling agents. Through cellular respiration and specific decay pathways, they metabolize the complex organic compounds in dead organisms, chemically breaking them down and releasing the locked Carbon and Nitrogen back into the atmosphere as CO₂ and N₂, closing the biogeochemical loops.","Decomposers only create solid rocks.","Decomposers turn atmospheric oxygen into solid ice."]',1,'Bacteria eat dead leaves and breathe out Carbon Dioxide, putting the carbon back into the air for new plants to use!','Decomposers: Many microorganisms use oxygen or other chemical pathways to obtain energy and break down organic matter.','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_043','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Synthesize why ''Argon'', despite being the third most abundant gas in the atmosphere (approx. 1%), is rarely discussed in biological cycles.','["Argon is highly toxic and kills all biological life instantly.","Argon is a Noble Gas. Its outermost electron valence shell is completely full, rendering it chemically inert. Because it possesses maximum thermodynamic stability, it does not naturally form chemical bonds or react with other elements, meaning it passes through biological systems (like human lungs) completely unchanged and unutilized.","Argon is a solid metal at room temperature.","Argon is the primary food source for plants."]',1,'Argon is so stable it refuses to react with anything, so our bodies just ignore it!','Argon and other gases: About 1%. Includes argon... (Synthesis with general chemistry: Argon is inert, hence its absence in the biology section).','2026-11-01 08:51:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_044','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Evaluate the systemic impact of reducing ''Emissions from industries'' on global Air Pollution.','["It would immediately stop all pollution worldwide instantly.","Industrial emissions represent massive point-sources of concentrated pollutants (SO₂, NOₓ, particulate matter). Reducing these source emissions directly prevents the atmospheric formation of secondary pollutants (like acid rain and photochemical smog), yielding exponential improvements in regional air quality and downwind ecosystem health.","It would have no effect because industries don''t produce pollution.","It would increase pollution because industries clean the air."]',1,'Stopping the smoke at the factory chimney is much better than trying to clean it out of the sky later!','Common sources include: ... Emissions from some industries... How can we help reduce air pollution? ... Planting trees is valuable, but it cannot replace reducing pollution at its source.','2026-11-01 08:51:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_air_global_045','Chemistry','Air and Gases Around Us','Topic 13: Air and Gases Around Us','Primary',10,'Critique the logic: ''If I can''t smell it, the air must be perfectly clean and free of pollution.''','["The logic is perfect; all dangerous chemicals have a strong smell.","The logic is dangerously flawed. The human olfactory system can only detect a specific range of volatile compounds. Many of the most lethal atmospheric pollutants—such as Carbon Monoxide (CO), Radon gas, and microscopic PM2.5 particulate matter—are completely colorless and odorless, making sensory detection impossible without scientific instrumentation.","The logic is flawed because clean air actually smells like strawberries.","The logic is perfect because pollution is always visible as black smoke."]',1,'Some of the most dangerous gases in the world have absolutely no smell at all!','Air pollution occurs when harmful gases or particles enter the air... (Synthesis: Many harmful gases, like CO2 or CO, are invisible and odorless).','2026-11-01 08:51:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_001','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What is ''environmental chemistry''?','["The study of stars and space.","The study of chemical substances and processes in air, water, soil, and living environments.","The study of only plants.","The study of how to build houses."]',1,'It is the chemistry of the natural world around us!','Environmental chemistry is the study of chemical substances and processes in air, water, soil, and living environments.','2026-11-01 08:51:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_002','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What is ''pollution''?','["Harmful contamination of the environment.","Cleaning the environment.","Planting new trees.","Saving water."]',0,'It makes the air, water, or dirt dirty and unsafe.','Pollution: Harmful contamination of the environment.','2026-11-01 08:51:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_003','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these is a common cause of air pollution?','["Riding a bicycle.","Planting trees.","Exhaust from cars (vehicles).","Drinking water."]',2,'Cars burn fuel and create smoke.','Common sources [of air pollution]: Vehicle exhaust.','2026-11-01 08:51:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_004','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these is a common cause of water pollution?','["Untreated sewage.","Collecting rainwater.","Fish swimming.","Filtering water."]',0,'It is dirty water that hasn''t been cleaned yet.','Common sources [of water pollution]: Untreated sewage.','2026-11-01 08:51:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_005','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What does it mean to ''reduce'' waste?','["To use an item again.","To use fewer unnecessary materials in the first place.","To process old materials into new ones.","To throw everything in the bin."]',1,'It means making less trash from the start!','Reduce: Use fewer unnecessary materials.','2026-11-01 08:51:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_006','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What does it mean to ''reuse'' an item?','["To throw it away after one use.","To process it in a factory.","To use an item again when it is safe and suitable.","To burn it."]',2,'Don''t throw it away if you can still use it!','Reuse: Use an item again when it is safe and suitable. A clean glass jar can become a storage container.','2026-11-01 08:51:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_007','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What does it mean to ''recycle''?','["To process suitable waste materials into materials that can be used again.","To throw plastic in the river.","To use a plastic bottle one time.","To bury waste in the ground."]',0,'Like turning old plastic bottles into new plastic items.','Recycle: Process suitable waste materials into materials that can be used again.','2026-11-01 08:51:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_008','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What does ''biodegradable'' mean?','["A material that lasts forever.","A material that can be broken down by living organisms (like bacteria) under suitable conditions.","A material made of pure metal.","A material that cannot be broken down."]',1,'It rots away naturally, like an apple core.','Biodegradable materials can be broken down by living organisms, such as certain bacteria and fungi...','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_009','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these materials is usually ''biodegradable''?','["A plastic bottle","A glass jar","Fruit and vegetable scraps","A metal can"]',2,'Food rots away in the dirt.','Material: Fruit and vegetable scraps - General behaviour: Usually biodegradable.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_010','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Which of these materials is usually ''non-biodegradable'' (does not break down easily)?','["Fallen leaves","Untreated paper","Many conventional plastics","Food scraps"]',2,'Plastic can stay in the environment for hundreds of years.','Material: Many conventional plastics - General behaviour: Usually not readily biodegradable.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_011','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What is ''composting''?','["Burning plastic waste.","Breaking down suitable organic materials into a stable, soil-like product.","Turning water into ice.","Dumping chemicals in the soil."]',1,'It turns old food and leaves into great dirt for gardens!','Composting is a process in which microorganisms break down suitable organic materials into a stable, soil-like product called compost.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_012','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What is a ''greenhouse gas''?','["A gas that makes plants turn green.","A gas that is only found in greenhouses.","A gas that absorbs and emits heat, contributing to the greenhouse effect.","A gas that makes the Earth freezing cold."]',2,'It acts like a warm blanket around the Earth.','Greenhouse gas: A gas that absorbs and emits infrared radiation, contributing to the greenhouse effect.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_013','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Which gas is a major contributor to human-caused global warming?','["Oxygen","Nitrogen","Helium","Carbon dioxide"]',3,'It is the gas released when we burn coal and oil.','For example, burning many fossil fuels releases carbon dioxide, which contributes to global warming.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_014','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'Can pollution harm people and animals?','["No, pollution is perfectly safe.","Yes, pollution can make water unsafe, harm lungs, and damage habitats.","Only plants are harmed by pollution.","Only fish are harmed by pollution."]',1,'Dirty air and water are bad for all living things!','Air pollution can harm the lungs... Polluted water can harm people, aquatic animals, and plants.','2026-11-01 08:51:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_015','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',1,'What is ''sustainability''?','["Using up all our resources as fast as possible.","Meeting our needs while protecting resources and environmental systems for the future.","Never using any natural resources.","Creating as much waste as possible."]',1,'It means leaving enough clean nature for the people of tomorrow!','Sustainability: Meeting needs while protecting resources and environmental systems for the future.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_016','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'How does ''environmental chemistry'' help solve real-world problems?','["It only tells us what color the sky is.","It allows scientists to test water and air to identify specific pollutants, and then develop cleaner technologies or water treatment processes to remove them.","It helps scientists build faster cars.","It teaches us how to cut down trees faster."]',1,'Chemists use science to find the pollution and invent ways to clean it up!','Chemistry can help identify environmental problems and develop ways to prevent or reduce them... Scientists can test water for substances... Water treatment processes can remove... pollutants.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_017','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why is burning waste (like plastic) in an open fire a bad idea for the environment?','["Because it is too expensive.","Because the combustion process releases harmful pollutants and smoke into the air, worsening air quality and harming health.","Because it creates too much water.","Because it makes the waste invisible and safe."]',1,'Burning plastic releases toxic smoke into the air we breathe!','Air pollution occurs when... substances contaminate the air at harmful levels. Common sources: ... Smoke from burning fuels or waste.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_018','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'If a farm uses too much chemical fertiliser, how does it harm the local river?','["The fertiliser evaporates and blocks the sun.","Rain washes the excess fertiliser into the river, providing excess nutrients that cause rapid, harmful algae growth.","The fertiliser turns the river water into solid salt.","The fertiliser makes the river flow backward."]',1,'The fertiliser feeds the river slime instead of the farm crops!','Excess nutrients from fertilisers can encourage rapid algae growth; when the algae die and decompose, oxygen levels in the water may fall.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_019','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why is ''reducing'' waste generally considered better than ''recycling'' waste?','["Because recycling is illegal.","Because reducing avoids the energy, transport, and pollution costs needed to manufacture AND recycle products in the first place.","Because recycling makes more waste.","Because reducing means throwing things in the river."]',1,'If you don''t buy the plastic bottle, you don''t even have to use energy to recycle it!','Reducing waste is often especially helpful because it avoids the need to make, transport, and dispose of some products in the first place.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_020','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Even if a material is labeled ''biodegradable'', why isn''t it always harmless to throw it into nature?','["Because biodegradable things instantly turn into poison.","Because large amounts of rotting organic waste can produce unpleasant smells and release greenhouse gases if managed poorly.","Because biodegradable things actually last forever.","Because biodegradable things are made of glass."]',1,'A massive pile of rotting food still creates bad gases and attracts pests!','Biodegradable does not mean harmless in every situation. Large amounts of organic waste can produce unpleasant smells and greenhouse gases if managed poorly.','2026-11-01 08:51:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_021','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why are conventional plastics considered an environmental problem?','["Because they melt too easily in the sun.","Because they are mostly non-biodegradable; they do not break down readily through biological processes and persist as litter in the environment for a very long time.","Because they are highly magnetic.","Because they turn into pure oxygen."]',1,'A plastic bottle will sit in the ocean for hundreds of years because nature can''t easily ''digest'' it!','Non-biodegradable materials do not break down readily through ordinary biological processes. Some plastics may persist for a long time...','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_022','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'How does composting help the environment?','["It turns plastic into metal.","It safely reduces the amount of organic waste going to landfills and creates a nutrient-rich product (compost) that can be returned to the soil.","It burns food waste to make electricity.","It freezes waste so it never rots."]',1,'It''s nature''s way of recycling food scraps back into healthy dirt!','Composting can reduce the amount of organic waste sent to landfills and return nutrients to soil.','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_023','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why shouldn''t you put old batteries in a garden compost bin?','["Because batteries are biodegradable.","Because batteries contain harmful chemicals and metals that will cause soil pollution and ruin the compost.","Because batteries will make the plants grow too fast.","Because batteries will turn into water."]',1,'The toxic acid in the battery will poison the dirt!','Soil pollution occurs when harmful substances accumulate... Possible sources include: Improper disposal of batteries... Avoid adding batteries, plastics, chemical waste... [to compost].','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_024','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'How does the ''greenhouse effect'' work on Earth?','["It blocks all sunlight from reaching the Earth.","Gases in the atmosphere absorb and emit heat, acting like a blanket that keeps the planet warm enough for life to exist.","It freezes the Earth by trapping cold air.","It turns the atmosphere into solid glass."]',1,'It''s a natural process that keeps us from freezing!','Earth''s atmosphere contains gases that absorb and emit heat. This natural greenhouse effect helps keep the planet warm enough for life.','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_025','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'If the greenhouse effect is natural, why is ''global warming'' currently a problem?','["Because the greenhouse effect has stopped working completely.","Human activities (like burning fossil fuels) have increased the concentration of greenhouse gases (like carbon dioxide), strengthening the effect and making the Earth too warm.","Because the sun is getting closer to the Earth.","Because humans are planting too many trees."]',1,'We are making the ''blanket'' around the Earth too thick!','However, human activities have increased the concentration of greenhouse gases... This strengthens the greenhouse effect and causes global warming.','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_026','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'How can using a reusable metal water bottle help reduce the impacts of climate change?','["The metal bottle absorbs carbon dioxide from the air.","By ''reducing'' the need to manufacture, transport, and dispose of hundreds of disposable plastic bottles, which requires burning fossil fuels at every step.","The metal bottle cools down the air around it.","It doesn''t help at all."]',1,'Making plastic bottles in a factory uses a lot of energy and creates a lot of smoke!','Reduce: Use fewer unnecessary materials. For example, choose a durable refillable bottle instead of repeatedly buying disposable bottles... Reducing waste is often especially helpful because it avoids the need to make, transport, and dispose... (Synthesis with climate change).','2026-11-01 08:51:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_027','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why does pouring motor oil on the ground cause ''soil pollution''?','["Because the oil makes the soil too slippery.","The harmful oil accumulates in the soil, which can harm soil organisms, damage plant roots, and eventually leak down into the groundwater.","Because the oil turns into fertilizer.","Because the oil instantly evaporates."]',1,'The oil poisons the bugs in the dirt and ruins the drinking water below!','Soil pollution occurs when harmful substances accumulate in it. Possible sources include: ... Oil and fuel leaks. Polluted soil may harm soil organisms, affect plant growth, or allow contaminants to enter crops and groundwater.','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_028','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'What happens to the oxygen levels in a river when a massive algae bloom dies and rots?','["The oxygen levels increase significantly.","Decomposing organisms (bacteria) break down the dead algae, and this decomposition process consumes the dissolved oxygen in the water, starving the fish.","The oxygen turns into solid ice.","The oxygen levels remain perfectly stable."]',1,'The bacteria use up all the oxygen while they ''eat'' the dead algae, leaving none for the fish!','...when the algae die and decompose, oxygen levels in the water may fall.','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_029','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'Why must industrial waste be ''treated'' before being released into a river?','["To make the water colorful.","Treatment processes use chemistry to neutralize or remove harmful chemical pollutants so they do not contaminate the natural water supply and damage the ecosystem.","To make the water boil.","To add more salt to the ocean."]',1,'Factories have to clean their dirty water before dumping it outside!','Industrial waste released without proper treatment [causes pollution]... Water treatment processes can remove or reduce specific pollutants, depending on the technology and the contamination involved.','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_030','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',5,'How does taking public transport (like a bus or train) reduce air pollution compared to everyone driving their own car?','["Buses run on pure water.","It moves many people using only one engine''s worth of fuel, vastly reducing the total amount of exhaust and greenhouse gases released per person.","Buses do not have exhaust pipes.","It makes people breathe less oxygen."]',1,'One bus makes much less smoke than 40 individual cars!','How can we help reduce air pollution? Walk, cycle, or use public transport when practical and safe... (Synthesis: Efficiency reduces total emissions).','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_031','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the assertion that ''Biodegradable plastics are the ultimate solution to plastic pollution and can be thrown anywhere.''','["The assertion is true; biodegradable plastics instantly vanish when dropped.","The assertion is dangerously flawed. Many ''biodegradable'' plastics require highly specific, high-temperature industrial composting facilities to break down. If littered in the ocean or a cold natural environment, they persist similarly to conventional plastics and still pose severe ecological threats.","The assertion is true because animals can safely eat them.","The assertion is false because biodegradable plastics are made of metal."]',1,'If you drop a ''biodegradable'' cup in a cold ocean, it will just float there like regular plastic; it needs a hot compost pile to melt away!','Biodegradable does not mean harmless in every situation... Some products labelled biodegradable require specific industrial composting conditions.','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_032','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the chemical mechanism of ''Acid Deposition'' (Acid Rain) caused by air pollution.','["Acid rain is caused by clouds freezing into solid acid.","Combustion of fossil fuels releases Sulfur Dioxide (SO₂) and Nitrogen Oxides (NOₓ) into the atmosphere. These pollutant gases chemically react with atmospheric water vapor and oxygen to synthesize Sulfuric and Nitric acids. These acids then precipitate, drastically lowering the pH of terrestrial and aquatic ecosystems.","Acid rain is caused by trees releasing too much oxygen.","Acid rain is just normal rain that feels cold."]',1,'The smoke from the factory mixes with the clouds to literally create rain made of weak acid!','Air pollution can... contribute to environmental problems such as acid deposition... Burning coal, oil, gas... (Synthesis with Topic 11 Acids: The pollution gases react with water to make acids).','2026-11-01 08:51:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_033','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize how the concept of ''Eutrophication'' demonstrates a chain reaction of chemical and biological imbalances.','["Eutrophication is a simple physical change where water freezes.","Eutrophication begins with chemical pollution (excess nitrogen/phosphorus from fertilizer). This triggers biological hyper-growth (algal bloom). The subsequent biological death of the algae triggers massive aerobic bacterial decomposition, causing a severe chemical deficit (hypoxia/low dissolved oxygen), ultimately leading to the biological collapse of higher trophic levels (fish kills).","Eutrophication is when fish eat too much plastic.","Eutrophication only happens in the desert."]',1,'It''s a deadly chain reaction: chemicals feed algae, algae die, bacteria eat algae, bacteria use all the oxygen, fish suffocate!','Excess nutrients from fertilisers can encourage rapid algae growth; when the algae die and decompose, oxygen levels in the water may fall. (Polluted water can harm... aquatic animals).','2026-11-01 08:51:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_034','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the thermodynamic role of ''Carbon Dioxide'' as a Greenhouse Gas.','["Carbon dioxide acts as a physical magnifying glass to intensify sunlight.","Earth absorbs high-energy shortwave solar radiation and re-emits it as lower-energy, longwave infrared radiation (heat). The molecular structure of CO₂ allows it to be transparent to incoming shortwave radiation but highly opaque to outgoing longwave infrared, absorbing the kinetic energy and radiating it back to the surface, shifting the global thermal equilibrium.","Carbon dioxide blocks all sunlight, freezing the Earth.","Carbon dioxide destroys the ozone layer."]',1,'The gas lets the sunlight in, but it won''t let the heat escape back out into space!','Earth''s atmosphere contains gases that absorb and emit heat. This natural greenhouse effect helps keep the planet warm... increasing atmospheric carbon dioxide... strengthens the greenhouse effect...','2026-11-01 08:51:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_035','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the limitations of ''Recycling'' within the framework of Thermodynamics (entropy).','["Recycling creates infinite energy, breaking the laws of physics.","While beneficial, recycling is not a perfectly closed loop. Every mechanical and chemical recycling process requires significant energy input (often from fossil fuels) and results in material degradation (increased entropy). Many materials (like paper/plastic) ''downcycle'' and can only be processed a finite number of times before structural failure, making ''Reduction'' fundamentally superior.","Recycling works perfectly forever with zero energy loss.","Recycling turns plastics directly back into crude oil."]',1,'You can''t recycle a piece of paper infinitely; eventually, the fibers break down. It''s better to just use less paper!','Reducing waste is often especially helpful because it avoids the need to make, transport, and dispose... (Synthesis: Recycling still takes energy and effort, it isn''t perfect).','2026-11-01 08:51:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_036','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the impact of ''Soil Contamination'' on human food security through Bioaccumulation.','["Soil pollution makes crops grow 10 times larger.","Heavy metals or persistent organic pollutants dumped into soil do not vanish. They are absorbed by the root systems of agricultural crops. These stable chemical contaminants accumulate in the plant tissues. When humans consume these crops (or animals that ate the crops), the toxins bioaccumulate in human tissues, posing severe long-term toxicological threats.","Soil pollution instantly turns all dirt into sand.","Soil pollution only affects the color of the vegetables."]',1,'The poison in the dirt gets sucked up by the carrot, and then you eat the carrot!','Polluted soil may harm soil organisms, affect plant growth, or allow contaminants to enter crops and groundwater.','2026-11-01 08:51:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_037','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the assertion that ''Water Treatment Plants simply filter out the dirt, so the water is pure.''','["The assertion is true; filtration removes 100% of all chemicals.","The assertion is a gross oversimplification. While mechanical filtration removes suspended solids (turbidity), it cannot remove dissolved chemical solutes (like pharmaceuticals or heavy metals) or microscopic pathogens. Advanced treatment requires complex chemical engineering, such as biological aeration, chemical coagulation, and chemical disinfection (chlorination/ozonation) to ensure potability.","The assertion is false because treatment plants actually add dirt.","The assertion is true because water cannot dissolve chemicals."]',1,'A paper filter won''t catch dissolved lead or invisible viruses! They have to use complex chemistry to kill the germs and remove the poisons.','Water treatment processes can remove or reduce specific pollutants, depending on the technology and the contamination involved. (Synthesis with Topic 7: ordinary filters do not remove dissolved substances).','2026-11-01 08:51:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_038','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the ecological necessity of ''Decomposers'' (bacteria/fungi) in the context of Biodegradable waste.','["Decomposers are harmful because they create pollution.","Decomposers are the foundational chemical recyclers of the biosphere. Without their specific metabolic pathways (which break complex organic polymers back into simple inorganic nutrients like nitrogen and carbon), biodegradable waste would accumulate infinitely, and the biogeochemical cycles required to sustain primary producers (plants) would completely halt.","Decomposers turn waste into solid rocks.","Decomposers only exist in ocean environments."]',1,'Without bacteria to eat the dead leaves and turn them into compost, the world would be buried miles deep in dead plants!','Composting is a process in which microorganisms break down suitable organic materials into a stable, soil-like product... return nutrients to soil. (Synthesis with Topic 13: Decomposers).','2026-11-01 08:52:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_039','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze how the concept of ''Sustainability'' integrates chemistry, economics, and environmental science.','["Sustainability means banning all chemistry and factories permanently.","Sustainability requires a multidisciplinary balance. It acknowledges that human society requires chemical engineering and manufacturing (economics/needs), but demands that these processes be redesigned (e.g., using renewable energy, closed-loop recycling, and non-toxic synthesis) to prevent the irreversible degradation of the Earth''s ecological systems for future generations.","Sustainability means making as much money as possible today.","Sustainability only applies to planting trees in parks."]',1,'We still need to make things, but we have to invent ways to make them without destroying the planet!','Sustainability: Meeting needs while protecting resources and environmental systems for the future. Chemistry helps... develop cleaner ways to make useful products.','2026-11-01 08:52:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_040','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the chemical and environmental differences between an ''Oil Spill'' in water versus a ''Fertilizer Spill''.','["Both spills sink instantly and form solid rocks.","An oil spill introduces a highly concentrated, toxic, immiscible non-polar hydrocarbon that physically coats the water surface and wildlife, causing immediate mechanical and chemical toxicity. A fertilizer spill introduces highly soluble, polar inorganic nutrients (nitrates/phosphates) that dissolve invisibly, causing delayed, systemic ecological collapse via eutrophication and hypoxia.","Both spills evaporate instantly and cause air pollution.","Oil spills are helpful to fish, fertilizers are not."]',1,'Oil floats on top and suffocates birds instantly; fertilizer dissolves and silently destroys the oxygen in the lake over time!','Common sources [of water pollution]... Fertilisers... Oil spills... (Synthesis of Topic 6 solubility and Topic 14 pollution effects).','2026-11-01 08:52:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_041','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the practice of using ''Open waste burning'' to manage municipal garbage.','["It is the most advanced, clean method of waste disposal.","Open burning is environmentally catastrophic. Unlike highly controlled municipal incinerators (which use extreme heat and chemical scrubbers), low-temperature open burning results in incomplete combustion. This synthesizes and releases massive quantities of highly toxic chemical byproducts (like dioxins, particulate matter, and CO₂) directly into the local atmosphere.","It is safe as long as you do it at night.","It only produces pure water vapor and harmless ash."]',1,'Burning trash in your backyard doesn''t get hot enough to destroy the toxins; it just spews poisonous smoke into the neighborhood!','Smoke from burning fuels or waste... Avoiding open waste burning can reduce many sources of air pollution.','2026-11-01 08:52:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_042','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Analyze the phrase ''Energy Efficiency'' as a chemical engineering solution to Climate Change.','["Energy efficiency means using the hottest fire possible.","Most global energy is generated via the combustion of fossil fuels (a chemical reaction producing CO₂). Energy efficiency means engineering systems (like LED lights or better engines) that perform the same amount of useful work while requiring less electrical or mechanical input, directly reducing the total stoichiometric mass of fuel burned and CO₂ emitted.","Energy efficiency means only using electricity, not chemicals.","Energy efficiency means stopping all human movement."]',1,'If a car engine is more efficient, it burns less gas to drive the same distance, so it makes less pollution!','Ways to reduce greenhouse-gas emissions include: Improving energy efficiency... Reducing unnecessary fuel use. (Synthesis: less fuel burned = less CO2).','2026-11-01 08:52:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_043','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Synthesize the role of ''Carbon Sinks'' (like forests) in mitigating Global Warming.','["Forests act as physical fans to blow the heat away.","Forests act as massive biological carbon sinks. Through the chemical process of photosynthesis, trees continuously extract atmospheric CO₂, cleaving the carbon atom to synthesize organic biomass (wood/leaves) while releasing O₂. Deforestation not only halts this extraction but, if the wood is burned/decayed, violently releases the stored carbon back into the atmosphere.","Forests absorb all the sunlight, making the Earth dark.","Forests turn carbon dioxide into solid gold."]',1,'Trees literally pull the global warming gas out of the air and turn it into solid wood!','Protecting forests and other ecosystems that store carbon... (Synthesis with Topic 13: Plants use carbon dioxide during photosynthesis).','2026-11-01 08:52:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_044','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Evaluate the chemical difficulty of ''Recycling'' complex modern electronic waste (e-waste).','["E-waste is easily recycled because it is made of pure water.","E-waste is notoriously difficult to recycle because it is a highly complex, heterogeneous mixture of dozens of chemically distinct materials (plastics, rare earth metals, toxic heavy metals like lead/mercury) tightly integrated at a microscopic level. Separating these requires dangerous, energy-intensive chemical smelting and acidic extraction processes.","E-waste is recycled simply by washing it in a dishwasher.","E-waste cannot be recycled at all and must be burned."]',1,'A smartphone has glass, plastic, gold, lithium, and toxic lead all glued together; pulling them apart cleanly is a chemical nightmare!','Improper disposal of batteries and electronic waste [causes soil pollution]... Recycling: Process suitable waste materials... (Synthesis: The complexity of the mixture makes physical separation incredibly hard).','2026-11-01 08:52:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_environ_global_045','Chemistry','Chemistry and the Environment','Topic 14: Energy Resources and the Environment','Primary',10,'Critique the idea that ''Because Earth has survived climate changes in the past, anthropogenic global warming is not a threat.''','["The idea is true; humans cannot affect the global climate.","The idea conflates geological time with biological adaptability. While Earth''s climate has historically shifted due to natural orbital or volcanic cycles, anthropogenic (human-caused) global warming is injecting massive quantities of greenhouse gases into the atmosphere at a highly accelerated kinetic rate. This unprecedented speed outpaces the evolutionary capacity of ecosystems and human agricultural infrastructure to adapt, leading to catastrophic systemic failure.","The idea is true because greenhouse gases are a myth.","The idea is false because Earth has never had a climate change before."]',1,'Nature used to change the temperature over millions of years; we are doing it in decades, which is too fast for animals and farms to survive!','However, human activities have increased the concentration of greenhouse gases... This strengthens the greenhouse effect and causes global warming... (Synthesis of the speed and scale of human impact vs natural cycles).','2026-11-01 08:52:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_001','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What happens to the structure of an egg when it is cooked?','["It turns into water.","Heat changes the structure of its proteins, making it firmer.","It turns into a gas.","Nothing happens to the egg."]',1,'Heat causes a permanent change inside the egg!','Cooking: When an egg is cooked, heat changes the structure of its proteins. The egg becomes firmer...','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_002','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What does yeast produce that helps bread dough rise?','["Carbon dioxide gas","Solid salt","Liquid water","Oxygen gas"]',0,'The yeast burps out gas bubbles!','Baking: When bread dough is prepared with yeast, the yeast produces carbon dioxide gas as it uses sugars. The gas forms bubbles that help the dough rise.','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_003','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What process uses microorganisms like bacteria to turn milk into yoghurt?','["Evaporation","Filtration","Fermentation","Melting"]',2,'Helpful germs change the milk''s chemistry!','Fermentation: Microorganisms convert certain substances into others... bacteria help turn milk into yoghurt.','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_004','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'How does refrigeration help preserve food?','["It cooks the food slowly.","It slows the growth of many microorganisms (germs).","It turns the food into solid ice permanently.","It removes all the water from the food."]',1,'Cold temperatures make the bad bacteria sleepy so they grow slower.','Food preservation: Refrigeration slows the growth of many microorganisms.','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_005','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What is the special substance in soap that helps it lift grease and dirt?','["Acid","Sugar","Surfactant","Salt"]',2,'It grabs the oil and the water at the same time!','They contain substances called surfactants. A surfactant has one part that interacts well with water and another part that interacts with oils...','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_006','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What is the ''active ingredient'' in a medicine?','["The part that makes it taste like candy.","The component responsible for its intended effect (making you better).","The plastic bottle it comes in.","The water mixed inside it."]',1,'It''s the chemical that actually does the important work in your body!','Medicines contain active ingredients that produce intended effects in the body... Active ingredient: The component in a product responsible for its intended effect','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_007','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'Why is cotton a good material for making towels?','["Because it is heavy.","Because it absorbs water.","Because it conducts electricity.","Because it is completely waterproof."]',1,'You want a towel to soak up the water after a bath!','Material: Cotton. Example: T-shirts, towels. Useful property: Absorbs water.','2026-11-01 08:58:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_008','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'Why are metals used to make cooking pans?','["Because they melt easily.","Because they conduct heat well.","Because they are transparent.","Because they are very soft."]',1,'You want the heat to travel from the stove to your food.','Material: Metals. Example: Cooking pans... Useful property: Many conduct heat and electricity.','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_009','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What should you ALWAYS do before using a household cleaning product?','["Mix it with another product.","Taste it.","Read and follow the product label.","Put it in an old water bottle."]',2,'The label tells you exactly how to use it safely!','Follow these safety rules: Read and follow the product label.','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_010','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'Is it safe to mix bleach with other household cleaners?','["Yes, it makes them work better.","No, never mix cleaning products because dangerous gases can form.","Yes, but only if you mix it with water first.","Yes, as long as you wear gloves."]',1,'Mixing chemicals can create a poisonous gas cloud!','Never mix cleaning products. In particular, never mix bleach with acids or ammonia-containing products, because dangerous gases can form.','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_011','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'How does a battery work to power a flashlight?','["It catches light from the sun.","It stores sound energy.","It converts stored chemical energy into electrical energy.","It burns a tiny fire inside."]',2,'Chemicals inside react to make electricity!','A battery stores energy in chemical substances. When a battery powers a device, chemical reactions help produce an electric current.','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_012','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What gas is released into the air when fossil fuels (like petrol or coal) are burned?','["Oxygen","Nitrogen","Carbon dioxide","Helium"]',2,'This gas contributes to global warming!','However, burning fossil fuels releases carbon dioxide...','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_013','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What is the purpose of adding ''fluoride'' to toothpaste?','["To make it turn blue.","To help prevent tooth decay (cavities).","To make it taste like mint.","To make the toothpaste foam up."]',1,'It makes your teeth strong!','Toothpaste contains ingredients designed to clean teeth; many toothpastes include fluoride to help prevent tooth decay.','2026-11-01 08:58:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_014','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What does ''sunscreen'' protect your skin from?','["Rainwater","Ultraviolet radiation (UV light) from the sun","Cold wind","Bugs"]',1,'It stops the sun from burning you!','Sunscreen uses ingredients that help protect skin from ultraviolet radiation when used correctly.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_015','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',1,'What do ''fertilisers'' do for plants?','["They stop the plants from growing.","They supply nutrients that plants need for growth.","They turn the plants into plastic.","They cut the plants down."]',1,'It is like vitamins for the farm!','Fertilisers supply nutrients that plants need for growth.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_016','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why is ''drying fruit'' an effective method of food preservation?','["Because it cooks the fruit completely.","Drying removes the water that microorganisms (bacteria and fungi) need to grow, preventing the fruit from spoiling quickly.","Because dry fruit is poisonous to humans.","Because it freezes the fruit."]',1,'Germs need water to live; if you take the water away, they can''t grow!','Drying removes water that microorganisms need to grow... Food process: Drying fruit. What happens? Water is removed, slowing spoilage.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_017','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'How does a ''surfactant'' in soap help wash away greasy dirt?','["It burns the oil away.","It has one part that sticks to oil and one part that sticks to water, allowing the oil to break into droplets and mix into the water so it can be rinsed away.","It turns the oil into solid rock.","It makes the water disappear."]',1,'It acts like a bridge connecting the water and the oil!','A surfactant has one part that interacts well with water and another part that interacts with oils or grease. This helps oily dirt disperse in water so it can be rinsed away.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_018','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why shouldn''t you store cleaning chemicals in empty drink bottles?','["Because it will make the bottle melt.","Because someone (especially a child) might accidentally mistake it for a drink and swallow dangerous chemicals.","Because the bottle will explode.","Because the chemicals need air to breathe."]',1,'Always keep chemicals clearly marked so no one drinks them by accident!','Keep chemicals in their original, labelled containers. Store them away from children and pets.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_019','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'If a car battery is dead, why shouldn''t you just throw it in the regular rubbish bin?','["Because it is too heavy for the bin.","Because batteries contain harmful chemicals and materials that need careful handling and special recycling to prevent environmental pollution.","Because the rubbish bin will catch fire instantly.","Because you can just wash it and use it again."]',1,'The battery acid and heavy metals will poison the soil at the landfill!','Batteries should not be burned, opened, or placed in ordinary waste where local rules require special collection. Rechargeable and other batteries can contain materials that need careful handling...','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_020','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'What dangerous gas can be produced by ''incomplete combustion'' (when a fire doesn''t have enough oxygen)?','["Carbon dioxide","Oxygen gas","Carbon monoxide","Nitrogen gas"]',2,'Unlike carbon dioxide, carbon monoxide is incredibly toxic and completely invisible!','...incomplete combustion can produce dangerous carbon monoxide.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_021','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why is ''ceramic'' a good material choice for a coffee mug?','["Because it is highly flexible.","Because it is transparent like glass.","Because ceramics are often hard and heat-resistant, keeping the liquid hot without melting the mug.","Because it conducts electricity."]',2,'You need something that won''t melt or burn your hands when you pour hot coffee in!','Material: Ceramics. Example: Cups, tiles. Useful property: Often hard and heat-resistant.','2026-11-01 08:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_022','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why does bread dough rise when you bake it?','["The yeast produces carbon dioxide gas bubbles, and the heat of baking causes chemical changes that lock the dough into a solid, fluffy bread.","The heat turns the flour into water.","The yeast creates oxygen that makes the bread float.","The dough expands because it absorbs air from the room."]',0,'The gas bubbles get trapped in the dough and puff it up like a balloon!','When bread dough is prepared with yeast, the yeast produces carbon dioxide gas as it uses sugars. The gas forms bubbles that help the dough rise. Baking then changes the dough into bread.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_023','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'If a person is severely dehydrated, why might a doctor give them an ''oral rehydration solution'' instead of just plain water?','["Because plain water is poisonous.","Because the solution contains specific active ingredients (water and important salts) that the body lost and urgently needs to replace.","Because the solution is a painkiller.","Because the solution is a strong acid."]',1,'When you sweat or get sick, you lose water AND salts; you have to replace both!','Oral rehydration solutions that replace water and important salts lost during dehydration.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_024','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'What should you do immediately if a household cleaning chemical splashes into your eyes?','["Rub your eyes strongly.","Follow the emergency instructions on the product label and contact poison-control or emergency services promptly.","Go to sleep.","Put vinegar in your eyes."]',1,'The label will tell you exactly how to safely wash it out!','If a chemical gets into the eyes or is swallowed, follow the label''s emergency instructions and contact local poison-control or emergency services promptly.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_025','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why are ''plastics'' used to make so many everyday food containers?','["Because they are heavy and break easily.","Because they are extremely expensive.","Because many plastics are lightweight, durable, and can be easily moulded into different shapes.","Because plastics are natural elements."]',2,'They won''t shatter if you drop your lunchbox!','Material: Plastics. Example: Food containers, equipment. Useful property: Many are lightweight and can be moulded.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_026','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'What is the difference between an ''antacid'' and a ''disinfectant''?','["An antacid cleans floors, a disinfectant cures headaches.","An antacid neutralizes stomach acid inside the body; a disinfectant reduces microorganisms on hard surfaces outside the body.","They are exactly the same thing.","An antacid is an acid, a disinfectant is a base."]',1,'One is medicine for your belly, the other is a cleaner for the kitchen counter!','Antacids that help relieve some types of indigestion... Disinfectants formulated to reduce microorganisms on suitable surfaces.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_027','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why is ''polyester'' often used to make sports clothing?','["Because it absorbs all water like a sponge.","Because it is a strong, lightweight fibre that handles sweat and movement well.","Because it is made of solid metal.","Because it shatters like glass."]',1,'You want clothes that are light and tough when you run!','Material: Polyester. Example: Sports clothing. Useful property: Strong, lightweight fibre.','2026-11-01 08:58:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_028','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'If you pour oil and water into a cup, they separate. What happens if you add a drop of dishwashing liquid and stir?','["The oil turns into solid ice.","The dishwashing liquid acts as a surfactant, breaking the oil into smaller droplets that disperse evenly through the water.","The water explodes.","The oil completely vanishes from existence."]',1,'The soap forces the oil and water to mix!','What do you observe? The oil in the cup containing detergent may break into smaller droplets and disperse more easily. The oil has not simply dissolved... the surfactant helps disperse it.','2026-11-01 08:58:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_029','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'Why is it important to use agricultural chemicals (like pesticides and fertilisers) exactly according to their labels?','["Because using more will automatically make the plants grow forever.","Incorrect use can cause severe environmental pollution, harming people, wildlife, soil, or local water sources.","Because the labels are just suggestions.","Because they will turn into pure oxygen if used wrongly."]',1,'If you spray too much, it washes into the river and kills the fish!','Agricultural products can help protect crops, but incorrect use can harm people, wildlife, soil, or water.','2026-11-01 08:58:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_030','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',5,'What chemical process happens inside a battery to create electricity?','["A physical change like melting.","A nuclear explosion.","Chemical reactions between the stored substances produce a flow of electrons (an electric current).","Photosynthesis."]',2,'The chemicals inside trade pieces with each other, which pushes electricity through the wires!','A battery stores energy in chemical substances. When a battery powers a device, chemical reactions help produce an electric current.','2026-11-01 08:58:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_031','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Critique the assertion that ''Cooking is purely a physical process because you still eat the same food.''','["The assertion is true; cooking only changes the temperature of the food.","The assertion is a chemical fallacy. Cooking involves intense thermal energy that acts as activation energy for numerous complex chemical reactions. It causes protein denaturation, Maillard browning, and the breakdown of complex carbohydrates, synthesizing entirely novel chemical compounds that alter nutritional availability, texture, and flavor.","The assertion is true because food cannot undergo chemical changes.","The assertion is false because cooking turns food into a gas."]',1,'When you fry an egg, the heat permanently changes the chemical shape of the proteins; you can never ''uncook'' it!','Food undergoes many chemical changes during preparation... Cooking: When an egg is cooked, heat changes the structure of its proteins... the change cannot easily be reversed.','2026-11-01 08:58:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_032','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Analyze the chemical mechanism of a ''Surfactant'' (like soap) at the molecular level.','["A surfactant physically burns the oil away.","A surfactant is an amphiphilic molecule. It possesses a hydrophilic (water-loving, polar) ''head'' and a lipophilic (oil-loving, non-polar) ''tail''. The tails embed themselves into the non-polar grease, while the heads interact with the polar water, forming a spherical structure called a micelle that lifts and suspends the oil in the aqueous solution.","A surfactant turns water into a non-polar solvent.","A surfactant is a strong acid that dissolves the grease."]',1,'The soap molecule acts like a microscopic grappling hook, grabbing the oil with one end and the water with the other!','A surfactant has one part that interacts well with water and another part that interacts with oils or grease. This helps oily dirt disperse in water so it can be rinsed away. (Synthesis of polarity concepts).','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_033','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Synthesize the danger of mixing household bleach (sodium hypochlorite) with an acid (like vinegar or toilet bowl cleaner).','["It creates a very powerful, safe cleaning foam.","Mixing bleach with an acid rapidly lowers the pH of the solution. This triggers a violent, unintended chemical reaction that liberates diatomic Chlorine gas (\\\\(Cl_2\\\\)) or Chloramine gases. These volatile gases are highly toxic, corrosive to the respiratory tract, and potentially lethal if inhaled in an enclosed space.","It neutralizes the bleach, making it pure water.","It freezes the chemicals into a solid block."]',1,'The two safe liquids react instantly to create a deadly, invisible poison gas cloud in your bathroom!','Never mix cleaning products. In particular, never mix bleach with acids or ammonia-containing products, because dangerous gases can form.','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_034','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Evaluate the biochemical role of ''Yeast'' in baking bread as an application of fermentation.','["Yeast acts as a physical sponge to hold water.","Yeast is a living single-celled fungus. In the dough, it undergoes anaerobic respiration (fermentation), metabolizing the complex carbohydrates (starches/sugars) present in the flour. The metabolic byproducts of this biochemical reaction are ethanol and Carbon Dioxide (\\\\(CO_2\\\\)) gas. The \\\\(CO_2\\\\) inflates the gluten matrix, leavening the bread.","Yeast is a chemical acid that burns the dough.","Yeast turns the flour into pure protein."]',1,'The living yeast ''eats'' the sugar and ''breathes out'' gas bubbles that make the bread fluffy!','Baking: When bread dough is prepared with yeast, the yeast produces carbon dioxide gas as it uses sugars. The gas forms bubbles that help the dough rise... Fermentation: Microorganisms convert certain substances... yeast can convert sugars into alcohol and carbon dioxide...','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_035','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Analyze the energy transformation occurring within a ''Battery'' (Galvanic cell).','["A battery creates new energy out of empty space.","A battery is a closed thermodynamic system containing a specific electrochemical gradient. It does not ''create'' energy; it stores potential energy in the chemical bonds of its reactants. Upon completing a circuit, a spontaneous redox (reduction-oxidation) chemical reaction occurs, forcing electrons to flow from the anode to the cathode, transducing chemical potential energy into kinetic electrical energy.","A battery traps lightning and releases it slowly.","A battery uses miniature nuclear fusion."]',1,'The chemicals inside ''want'' to react, but they can only do it by pushing electricity through your flashlight!','A battery stores energy in chemical substances. When a battery powers a device, chemical reactions help produce an electric current... converts stored chemical energy into electrical energy.','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_036','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Synthesize how the concept of ''Incomplete Combustion'' poses a severe biological threat in everyday life.','["Incomplete combustion only produces harmless water vapor.","Standard combustion (sufficient \\\\(O_2\\\\)) produces \\\\(CO_2\\\\). Incomplete combustion (insufficient \\\\(O_2\\\\)) synthesizes Carbon Monoxide (CO). CO is highly toxic because it binds to hemoglobin in human blood with 200x the affinity of oxygen, blocking cellular respiration and causing silent, lethal asphyxiation without any warning odor or smoke.","Incomplete combustion creates a massive explosion of light.","Incomplete combustion freezes the air in the room."]',1,'If a heater is broken and doesn''t get enough air, it makes a deadly gas you can''t see or smell!','Burning many fuels is a form of combustion, which usually requires oxygen... incomplete combustion can produce dangerous carbon monoxide. (Synthesis: Carbon monoxide is a toxic gas).','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_037','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Critique the use of ''Plastics'' in everyday life, balancing material properties against environmental impact.','["Plastics are perfectly safe and should be used for everything.","Plastics possess unparalleled material properties: they are cheap, chemically inert, lightweight, moldable, and incredibly durable. However, this extreme chemical durability is exactly what causes their environmental catastrophe; because they are highly resistant to biological degradation (non-biodegradable), their widespread use results in persistent, accumulating microplastic pollution across all global ecosystems.","Plastics are useless because they shatter like glass.","Plastics are made of wood and dissolve instantly in water."]',1,'The fact that plastic lasts forever makes it a great container, but a terrible piece of garbage!','Plastics: ... Many are lightweight and can be moulded... Many materials have advantages as well as environmental costs... (Synthesis with Topic 14: Plastics are non-biodegradable).','2026-11-01 08:58:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_038','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Evaluate the pharmacological precision of an ''Active Ingredient'' in a medication.','["The active ingredient is just food coloring.","A pharmaceutical tablet is a complex mixture. Most of the mass consists of inert ''excipients'' (binders/fillers). The ''active ingredient'' is the specific, highly purified chemical compound engineered to interact with precise biological receptors or enzymes to trigger the therapeutic physiological response. The dosage of this specific chemical is mathematically critical.","The active ingredient is the water used to swallow the pill.","All parts of a medicine pill do the exact same thing."]',1,'A tiny speck of chemical in the pill does all the curing; the rest of the pill is just chalk to make it big enough to swallow!','Medicines contain active ingredients that produce intended effects in the body... Active ingredient: The component in a product responsible for its intended effect.','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_039','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Analyze the chemical rationale behind using an ''Antacid'' to treat indigestion.','["Antacids coat the stomach in a thick layer of physical plastic.","Indigestion is often caused by an excess of Hydrochloric Acid (HCl) in the gastric lumen. Antacids are formulated with weak, basic compounds (like Calcium Carbonate or Magnesium Hydroxide). Ingesting them initiates a targeted neutralisation reaction in vivo, reacting with the \\\\(H^+\\\\) ions to produce salt, water, and \\\\(CO_2\\\\), safely buffering the gastric pH.","Antacids are strong acids that burn the stomach.","Antacids use electricity to shock the stomach."]',1,'You are drinking a safe chemical base to cancel out the painful acid in your stomach!','Antacids that help relieve some types of indigestion... (Synthesis with Topic 11: Antacids contain substances that help neutralise excess stomach acid).','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_040','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Synthesize how ''Food Preservation'' techniques rely on manipulating chemical or biological kinetics.','["Food preservation uses magic to freeze time.","Food spoilage is driven by the kinetic rate of bacterial growth and enzymatic decay. Preservation methods artificially alter the environment to halt these kinetics: Refrigeration lowers thermal energy (slowing metabolic reaction rates); Drying removes the aqueous solvent required for bacterial life; Pickling lowers the pH (acidification), denaturing bacterial proteins.","Food preservation works by adding more bacteria to the food.","Food preservation relies entirely on painting the food."]',1,'Bacteria need warmth, water, and neutral pH to live; if you make the food cold, dry, or sour, they can''t survive!','Food preservation: Refrigeration slows the growth of many microorganisms. Drying removes water that microorganisms need to grow. Pickling... (Synthesis: Changing the environment to stop biological chemistry).','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_041','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Critique the assertion that ''Natural chemicals are always safe, and synthetic chemicals are always dangerous.''','["The assertion is perfectly true; anything from nature is safe.","The assertion is a widespread chemical fallacy. Toxicity is determined strictly by the molecular structure and dosage of a substance, not its origin. Many synthetic chemicals (like lab-made aspirin) are life-saving, while many entirely natural chemicals (like botulinum toxin, cyanide in apple seeds, or snake venom) are lethally toxic.","The assertion is true because synthetic chemicals are made of plastic.","The assertion is false because natural chemicals do not exist."]',1,'Poison ivy is 100% natural, but you definitely don''t want to rub it on your skin! Safety depends on the specific chemical.','This applies critical thinking to the entire chemistry curriculum. The text notes: ''Agricultural products can help protect crops, but incorrect use can harm...'' and ''Never taste unknown chemicals...''. (Synthesis: Chemical properties dictate safety, not origin).','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_042','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Analyze the role of ''Fluoride'' as an active ingredient in toothpaste.','["Fluoride turns the teeth blue.","Dental enamel is primarily composed of hydroxyapatite. In the acidic environment of the mouth (caused by bacterial fermentation of sugars), this mineral demineralizes (decays). Fluoride ions chemically react with the enamel, substituting into the crystal lattice to form fluorapatite, a novel compound that is significantly harder and far more resistant to acidic dissolution.","Fluoride is a surfactant that washes grease off teeth.","Fluoride is a sugar that makes toothpaste taste better."]',1,'Fluoride actually bonds with your teeth to make a harder, acid-proof shield on the outside!','Toothpaste contains ingredients designed to clean teeth; many toothpastes include fluoride to help prevent tooth decay... Active ingredient: The component... responsible for its intended effect.','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_043','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Synthesize how understanding ''Chemical Properties'' dictates material selection for engineering a saucepan.','["Engineers pick materials based only on their color.","A saucepan requires opposing, highly specific properties. The base must be engineered from a metal (like copper or steel) due to its high ''thermal conductivity'' (allowing rapid heat transfer to the food) and high ''melting point'' (resisting the stove''s heat). Conversely, the handle must be engineered from an insulator (like plastic or ceramic) with low thermal conductivity to protect the user.","A saucepan is entirely made of plastic because it is lightweight.","A saucepan is made of glass because it is transparent."]',1,'You need metal to cook the food, but you need plastic on the handle so you don''t burn your hand!','Metals: Cooking pans... Many conduct heat... Ceramics: Cups... hard and heat-resistant... No single material is best for every purpose. A window needs... a saucepan needs material suited to heating food.','2026-11-01 08:58:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_044','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Evaluate the necessity of standard ''Chemical Labelling'' and storage protocols in a household environment.','["Labels are only for scientists in laboratories.","Household chemicals are often highly concentrated, reactive compounds (strong acids, bases, oxidizers). Storing them in unlabelled or inappropriate containers (like food bottles) drastically increases the statistical probability of accidental ingestion or inadvertent mixing, leading to severe toxicological or catastrophic exothermic reactions. Standardized labeling provides immediate, critical toxicological data and neutralization protocols for emergency services.","Labels make the chemicals work faster.","Storage protocols require all chemicals to be frozen."]',1,'If you put bleach in a water bottle, someone might drink it! The label is there to save lives in an emergency.','Keep chemicals in their original, labelled containers. Store them away from children and pets. Never mix cleaning products... If a chemical gets into the eyes... follow the label''s emergency instructions...','2026-11-01 08:58:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_everyday_global_045','Chemistry','Chemistry in Everyday Life','Topic 15: Chemistry in Everyday Life','Primary',10,'Analyze the concept of an ''Alloy'' using everyday brass items (like keys or doorknobs).','["Brass is a pure element found in mines.","Brass is an engineered alloy—a solid homogeneous mixture (solid solution) of Copper and Zinc. By physically mixing the atoms of a soft, highly conductive metal (Copper) with another element, metallurgists synthesize a material with enhanced physical properties, specifically increased tensile strength, hardness, and corrosion resistance, without altering the fundamental chemical identity of the constituent metals.","Brass is a chemical compound formed by an explosion.","Brass is a type of plastic painted to look like metal."]',1,'Copper is too soft to make a good key; if you mix it with zinc to make brass, it becomes hard enough to turn a lock without bending!','This synthesizes knowledge from Topic 9 (Brass is an alloy) with Topic 15 (Materials around us). Alloys combine elements to create useful properties.','2026-11-01 08:58:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_001','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'What is a ''physical change''?','["A change that permanently destroys a material.","A change in size, shape, state, or appearance without forming a new substance.","A change where a completely new substance is formed.","A change that only happens when things get cold."]',1,'It looks different, but it''s still made of the exact same stuff.','A physical change occurs when a material changes its size, shape, state, or appearance without forming a new substance.','2026-11-01 09:12:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_002','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'What is a ''chemical change''?','["A change where a material is just cut in half.","A change where a liquid turns into solid ice.","A change when one or more substances change into new substances with different chemical properties.","A change that only happens to water."]',2,'You create a completely brand-new material!','A chemical change occurs when one or more substances change into new substances with different chemical properties.','2026-11-01 09:12:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_003','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''melting ice'' a physical or chemical change?','["Physical change","Chemical change","Both","Neither"]',0,'It''s still just water!','Examples [of physical changes] include: Melting ice: solid water becomes liquid water.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_004','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''cutting paper'' a physical or chemical change?','["Chemical change","Physical change","Both","Neither"]',1,'Even tiny pieces of paper are still paper.','Examples [of physical changes] include: ... Cutting paper: one sheet becomes smaller pieces of the same paper.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_005','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''iron rusting'' a physical or chemical change?','["Physical change","Chemical change","Both","Neither"]',1,'The iron turns into a flaky, orange new substance!','Examples [of chemical changes] include: Rusting iron: iron reacts with oxygen and moisture to form rust.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_006','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''cooking an egg'' a physical or chemical change?','["Chemical change","Physical change","Both","Neither"]',0,'You can never un-cook an egg back to raw!','Examples [of chemical changes] include: ... Cooking an egg: heating causes chemical changes in the egg''s proteins.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_007','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''dissolving sugar in water'' a physical or chemical change?','["Chemical change","Physical change","Both","Neither"]',1,'If you boil the water away, the sugar is still there.','Examples [of physical changes] include: ... Dissolving sugar in water: the sugar spreads through the water; it has not become a different substance.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_008','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Is ''burning wood'' a physical or chemical change?','["Physical change","Chemical change","Both","Neither"]',1,'The wood turns into smoke and ash; it is gone forever.','Examples [of chemical changes] include: ... Burning wood: wood reacts with oxygen, producing substances such as gases, smoke, and ash.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_009','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'What is a common clue that a chemical change might have happened?','["The object was cut in half.","The object melted into a liquid.","A lasting colour change or gas bubbles forming (when not boiling).","The object was moved to a new room."]',2,'If it suddenly changes color or fizzes, it might be a chemical reaction!','How can we recognise a chemical change? Possible clues include: A lasting colour change. Gas bubbles forming.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_010','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'If a change is ''reversible'', what does that mean?','["It can never be undone.","It can be changed back to its original state under suitable conditions.","It exploded.","It turned into a gas."]',1,'Like melting ice, and then freezing the water back into ice!','Reversible: Able to be changed back under suitable conditions.','2026-11-01 09:12:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_011','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Are physical changes *always* easily reversible?','["Yes, you can always easily reverse any physical change.","No, some physical changes (like breaking glass) are very difficult to reverse.","Yes, but only if you use heat.","No, physical changes can never be reversed."]',1,'You can''t easily tape a shattered window back together, even though it''s a physical change!','Are physical changes always reversible? No. Some are easily reversible, while others are not... Glass breaking: Not easily...','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_012','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'What is a ''reactant'' in a chemical reaction?','["The new substance that is formed.","The container the reaction happens in.","A substance present at the start of a chemical reaction.","The heat produced by the reaction."]',2,'It is the starting ingredient!','Reactant: A substance present at the start of a chemical reaction.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_013','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'What is a ''product'' in a chemical reaction?','["A substance formed by a chemical reaction.","The substance present at the start.","The tool used to stir the mixture.","The smell of the reaction."]',0,'It is the final result you get at the end!','Product: A substance formed by a chemical reaction.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_014','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'Does heating something *always* cause a chemical change?','["Yes, heat always destroys materials.","No, heating can cause either a physical change (like melting) or a chemical change (like cooking).","Yes, heat always causes fire.","No, heating only ever causes physical changes."]',1,'Heating ice just makes water (physical), but heating bread makes toast (chemical)!','Why heating can cause different types of change: Heating does not always cause a chemical change. Boiling water — physical change... Toasting bread — chemical changes.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_015','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',1,'If you see bubbles in boiling water, is that a chemical change?','["Yes, bubbles always mean a chemical change.","No, boiling water is just liquid turning to gas; it is a physical change.","Yes, because the water is being destroyed.","No, because water doesn''t actually boil."]',1,'The bubbles are just made of water vapor, not a new gas!','However, no single clue proves that a chemical change has occurred. For example, bubbles can form when water boils, which is a physical change.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_016','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why is ''breaking a piece of chalk'' classified as a physical change rather than a chemical change?','["Because chalk is not made of atoms.","Because the chalk only changed its size and shape; the dust and pieces are still chemically identical to the original chalk.","Because breaking chalk creates a lot of heat.","Because you can easily glue the chalk perfectly back together."]',1,'It looks different, but it''s still exactly the same material!','A physical change occurs when a material changes its size, shape, state, or appearance without forming a new substance. Examples include: ... Breaking chalk: a large piece becomes small pieces of chalk.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_017','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why is ''souring milk'' classified as a chemical change?','["Because sour milk is just cold milk.","Because chemical and biological processes produce entirely new substances (acids) that permanently change the milk''s taste and smell.","Because the milk only changed its color slightly.","Because souring is easily reversed by adding sugar."]',1,'The bacteria in the milk made new, sour-tasting chemicals!','Examples [of chemical changes] include: ... Souring milk: chemical and biological processes produce substances that change its taste and smell.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_018','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'If you mix baking soda and vinegar together and it instantly fizzes and bubbles, what type of change has occurred?','["A physical change, because mixing things is always physical.","A chemical change, because the fizzing indicates that a new gas substance was formed through a reaction.","A physical change, because the liquid is boiling.","No change occurred."]',1,'Those bubbles aren''t boiling water; they are a brand new gas being created!','How can we recognise a chemical change? Possible clues include: ... Gas bubbles forming... Scientists consider the whole process and whether new substances form.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_019','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why is ''reversibility'' a bad rule to use when deciding if a change is physical or chemical?','["Because chemical changes are actually very easy to reverse.","Because some physical changes (like cutting paper or breaking glass) are almost impossible to reverse, even though no new substance was formed.","Because physical changes are only reversible if you freeze them.","Because reversibility only applies to liquids."]',1,'You can''t easily turn sawdust back into a log, but cutting wood is still just a physical change!','Are physical changes always reversible? No. Some are easily reversible, while others are not... Paper being cut: Not easily... Remember: Reversibility is useful evidence, but it does not by itself determine whether a change is physical or chemical.','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_020','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'What is the defining, most important question to ask when deciding if a change is chemical or physical?','["Did it change color?","Has a new substance formed?","Did it get hot?","Can I reverse it?"]',1,'This is the ONLY rule that is 100% true every time!','Scientists classify them by asking an important question: Has a new substance formed?','2026-11-01 09:12:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_021','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'How does ''toasting bread'' demonstrate a chemical change caused by heat?','["The heat melts the bread into a liquid.","The heat causes a reaction in the bread''s molecules that creates new, dark, crusty substances, permanently changing its smell and taste.","The heat just makes the bread dry, which is a physical change.","The heat turns the bread into pure carbon gas."]',1,'You can''t un-toast bread because the chemicals in the bread have permanently reacted to the heat!','Toasting bread — chemical changes: Heating causes reactions that create new substances, changing the bread''s colour, smell, and taste.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_022','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'When an iron nail rusts, what are the ''reactants'' and what is the ''product''?','["Reactant = Rust; Product = Iron and Oxygen","Reactants = Iron, Oxygen, and Moisture; Product = Rust","Reactant = Water; Product = Iron","Reactants = Rust and Water; Product = Oxygen"]',1,'The things you mix together are reactants; the thing you get at the end is the product!','Rusting iron: iron reacts with oxygen and moisture to form rust... Reactant: A substance present at the start... Product: A substance formed...','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_023','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'If you see bubbles rising in a pot of water on a hot stove, why is this a physical change and not a chemical change?','["Because stove heat cannot cause chemical changes.","Because the bubbles are just liquid water turning into water vapor gas (a change of state); no new chemical substance is being formed.","Because the bubbles are filled with oxygen gas.","Because boiling destroys the water completely."]',1,'The bubbles are just H2O in gas form, not a new chemical!','For example, bubbles can form when water boils, which is a physical change... Boiling water — physical change: Liquid water becomes water vapour. The substance remains H₂O.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_024','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why is dissolving salt in water considered a physical change?','["Because the salt turns into a gas.","Because no new substance is formed; if you evaporate the water, you can recover the exact same salt.","Because dissolving is a chemical reaction.","Because salt water is a pure compound."]',1,'The salt is just hiding between the water molecules; it hasn''t changed into anything else!','Conclusion: Dissolving salt in water is generally a physical change because no new substance is formed.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_025','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'If a clear liquid suddenly forms a solid powder that falls to the bottom after two chemicals are mixed, what is this a clue of?','["A physical change.","A chemical change, as ''a new solid forming from liquids'' is a strong indicator that new substances were created.","A change of state.","Nothing happened."]',1,'When two clear liquids suddenly make a solid rock, you know they reacted chemically!','How can we recognise a chemical change? Possible clues include: ... A new solid forming from liquids.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_026','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why must you keep rusty iron objects away from food and drink?','["Because rust makes food taste too sweet.","Because rust is a new chemical substance formed from environmental reactions and may carry harmful bacteria or be unsafe for consumption.","Because rust will turn the food into iron.","Because rust is extremely cold."]',1,'Rust isn''t just dirty iron; it''s a completely different chemical crust!','Conclusion: Rusting is a chemical change... Do not use rusty objects for food or drink.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_027','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'If you fold a piece of paper into an origami crane, what kind of change have you made?','["A chemical change.","A physical change, because the paper only changed its shape, not its chemical identity.","A change of state.","No change was made."]',1,'It looks like a bird, but it''s still made of paper!','Folding paper: Physical. The paper changes shape, but no new substance forms.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_028','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Why does a piece of apple turning brown after being cut suggest a chemical change?','["Because the apple is melting.","The ''lasting colour change'' indicates that the flesh of the apple is reacting with oxygen in the air to form a new brown substance.","Because the apple is freezing.","Because the apple is evaporating."]',1,'The apple is reacting with the air, just like iron rusting!','How can we recognise a chemical change? Possible clues include: A lasting colour change.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_029','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'Can you easily reverse the process of burning wood (a chemical change)?','["Yes, just put the ash in the freezer.","Yes, by adding water to the smoke.","No, chemical changes are often difficult or impossible to reverse by simple methods, because the original substances have been destroyed to make new ones.","Yes, by squeezing the ash very hard."]',2,'You can never put the smoke and ash back together to make a log!','Physical changes vs chemical changes... Chemical change... Reversibility: Often difficult to reverse by simple methods.','2026-11-01 09:12:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_030','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',5,'If a change produces a sudden burst of heat and bright light (like a firework), what type of change is almost certainly occurring?','["A physical change.","A chemical change, because the release of heat and light is a major clue that chemical bonds are reacting and forming new substances.","A change of state.","Evaporation."]',1,'Explosions and fire are always chemical reactions!','How can we recognise a chemical change? Possible clues include: ... Heat or light being released.','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_031','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Critique the assertion that ''Any process that creates bubbles is a chemical reaction.''','["The assertion is perfectly true; bubbles are always new gases.","The assertion is a logical fallacy. While gas evolution (bubbles) *can* indicate a chemical reaction (e.g., baking soda and vinegar), it can also merely indicate a physical phase transition (boiling water) where the substance changes state from liquid to gas without altering its chemical identity.","The assertion is false because bubbles are solids.","The assertion is false because bubbles only happen in space."]',1,'If you boil water, the bubbles are just steam (water), not a new chemical!','However, no single clue proves that a chemical change has occurred. For example, bubbles can form when water boils, which is a physical change.','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_032','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Analyze the thermodynamic and chemical distinction between ''Melting Sugar'' and ''Caramelizing (Burning) Sugar''.','["They are identical physical processes.","Melting sugar is a physical change (solid to liquid) requiring thermal energy but maintaining the sucrose molecule. Caramelizing sugar requires excessive thermal energy that breaks the chemical bonds of the sucrose, synthesizing new flavor compounds (a chemical change) and permanently altering its identity.","Caramelizing sugar is a physical change, melting is a chemical change.","Melting sugar freezes it, caramelizing evaporates it."]',1,'If the sugar turns brown and smells different, you''ve burned it and created new chemicals!','This applies the concepts of ''heating can cause different types of change'' to a complex scenario. Melting is explicitly a physical change (solid to liquid). The text notes ''heating causes reactions that create new substances... changing the... colour, smell, and taste'' (like toasting bread or caramelizing).','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_033','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Synthesize the concept of ''Conservation of Mass'' within the context of a Chemical Change like burning wood.','["Burning wood destroys the mass of the wood completely, leaving nothing.","While the solid wood appears to ''vanish'', mass is strictly conserved. The chemical reaction converts the solid wood and atmospheric oxygen (reactants) into ash, smoke, and invisible gases like \\\\(CO_2\\\\) and water vapor (products). The total mass of the products exactly equals the mass of the reactants.","Burning wood creates new mass out of nothing.","Burning wood turns all the mass into pure light."]',1,'If you trapped all the smoke and gas in a giant bubble, it would weigh the same as the original log and oxygen!','Burning wood: wood reacts with oxygen, producing substances such as gases, smoke, and ash. (Synthesis: The matter isn''t destroyed; it just changes form into unseen gases).','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_034','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Evaluate the limitation of using ''Reversibility'' to teach the difference between physical and chemical changes.','["Reversibility is a flawless rule with no exceptions.","Using reversibility creates severe pedagogical confusion. While chemical changes are generally irreversible by simple means, many physical changes (like shattering glass, grinding meat, or cutting paper) are equally irreversible. The *only* definitive metric is whether a novel molecular substance was synthesized.","Reversibility is completely irrelevant to science.","Chemical changes are actually the only changes that are easily reversible."]',1,'You can''t un-smash a window, but the broken pieces are still glass, not a new chemical!','Are physical changes always reversible? No. Some are easily reversible, while others are not... Glass breaking: Not easily... Remember: Reversibility is useful evidence, but it does not by itself determine...','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_035','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Analyze the chemical process of ''Rusting'' as an oxidation reaction.','["Rusting is just the iron melting in the sun.","Rusting is a specific chemical change (oxidation) where elemental Iron (\\\\(Fe\\\\)) chemically bonds with atmospheric Oxygen (\\\\(O_2\\\\)) in the presence of an aqueous catalyst (moisture) to synthesize Iron Oxide (rust). The physical properties of the tough metal are permanently lost to the brittle product.","Rusting is when water physically washes away the iron.","Rusting is a physical change caused by the wind."]',1,'The iron is literally eating the oxygen out of the air and locking it into a new, crumbly rock!','Rusting iron: iron reacts with oxygen and moisture to form rust... Iron rusting: Chemical... New substances form through reactions.','2026-11-01 09:12:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_036','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Synthesize why ''Dissolving Salt'' is classified as a physical change despite the salt becoming invisible and intimately mixed with the water.','["Dissolving salt destroys the salt atoms completely.","During dissolution, the ionic bonds of the salt are overcome by the polar water molecules, separating the ions. However, no new chemical compound is synthesized. The sodium and chloride ions merely exist in an aqueous state. The process is completely physically reversible via simple thermal evaporation.","Dissolving salt creates a new chemical called liquid-salt.","Dissolving salt is actually a chemical reaction that creates gas."]',1,'If you boil the water away, you get the exact same salt back!','Dissolving sugar [or salt] in water: the sugar spreads through the water; it has not become a different substance... Conclusion: Dissolving salt in water is generally a physical change because no new substance is formed.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_037','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Critique the student statement: ''When I mixed two clear liquids, they turned bright pink. This is a physical change because liquids just mixed.''','["The statement is correct; liquids cannot undergo chemical changes.","The statement is incorrect. A spontaneous, ''lasting colour change'' upon mixing two distinct substances is a primary empirical indicator of a chemical reaction. The interaction synthesized a novel chemical product whose molecular structure reflects pink light, unlike the clear reactants.","The statement is correct because color is an illusion.","The statement is incorrect only if the liquid also exploded."]',1,'Clear + Clear = Pink is not normal mixing; it means a new chemical was born in the glass!','How can we recognise a chemical change? Possible clues include: A lasting colour change... Scientists consider the whole process and whether new substances form.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_038','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Evaluate the biochemical complexity of ''Cooking an Egg'' as a chemical change.','["Cooking an egg simply melts the solid egg into a liquid.","Cooking an egg involves the thermal denaturation of complex folded protein molecules (like albumin). The added thermal energy violently breaks the weak bonds holding the protein''s 3D structure, causing them to unfold and tangle together into a permanent, solid, cross-linked network, altering the chemical composition fundamentally.","Cooking an egg is a physical change because it just gets hot.","Cooking an egg adds new atoms to the egg from the frying pan."]',1,'The heat permanently changes the shape and connections of the molecules inside the egg!','Cooking an egg: heating causes chemical changes in the egg''s proteins... creates a result that cannot be changed back to a raw egg by cooling.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_039','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Analyze how the ''State of Matter'' changes during the chemical reaction of burning wood.','["The wood simply melts into a liquid.","Burning (combustion) is a chemical reaction that forces a radical phase transformation. The solid reactants (wood) and gaseous reactants (oxygen) undergo a violent chemical breakdown, synthesizing entirely new products that are primarily gaseous (\\\\(CO_2\\\\), \\\\(H_2O\\\\) vapor) and minor solids (ash), releasing massive thermal energy.","The wood turns into a heavier solid block.","The state of matter does not change during burning."]',1,'A massive, heavy log turns into a tiny pile of ash because the rest of the mass floated away as invisible gas!','Burning wood: wood reacts with oxygen, producing substances such as gases, smoke, and ash. (Synthesis: Solid wood becomes mostly invisible gases).','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_040','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Synthesize the difference between a ''Reactant'' and a ''Product'' using the rusting of a nail.','["The rust is the reactant, and the nail is the product.","In the chemical reaction of rusting, the elemental Iron (the nail) and atmospheric Oxygen/Moisture are the ''Reactants''—the initial substances consumed by the reaction. The resulting Iron Oxide (the rust) is the ''Product''—the novel chemical substance synthesized as a direct result of the chemical change.","Both the nail and the rust are reactants.","Both the nail and the rust are products."]',1,'Reactants are the starting ingredients; Products are the final result!','Rusting iron: iron reacts with oxygen and moisture to form rust... Reactant: A substance present at the start... Product: A substance formed by a chemical reaction.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_041','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Critique the assertion that ''Digesting food is just a physical change of crushing it into smaller pieces.''','["The assertion is completely true; digestion is just chewing.","The assertion is false. While mechanical digestion (chewing) is a physical change, chemical digestion is a highly complex series of chemical changes. Enzymes and stomach acids chemically break down large macromolecular compounds (like starches and proteins) into entirely new, simpler molecular substances (like glucose and amino acids) that the body can absorb.","Digesting food is actually nuclear fusion.","Digesting food turns the food into pure water."]',1,'Chewing is physical, but your stomach acid actually rips the molecules apart into new chemicals!','This synthesizes the definition of chemical change (new substances) with everyday biological processes implied by the curriculum. Souring milk (a biological/chemical process) is a chemical change.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_042','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Analyze the physical mechanics of ''Sublimation'' (solid to gas) versus a chemical change that produces a gas.','["They are the exact same process.","Sublimation (e.g., dry ice turning into \\\\(CO_2\\\\) gas) is a physical phase transition; the molecular identity remains identical, only the kinetic energy and state change. A chemical change producing a gas (e.g., baking soda and vinegar) synthesizes an entirely novel gaseous molecule that did not exist in the initial reactants.","Sublimation creates a new gas, while chemical changes do not.","Sublimation only happens in liquids."]',1,'Dry ice is solid carbon dioxide turning into gas carbon dioxide (physical). Vinegar and baking soda make a brand new gas that wasn''t there before (chemical)!','A physical change occurs when a material changes its size, shape, state... without forming a new substance... A chemical change occurs when one or more substances change into new substances... Gas bubbles forming [can be a clue].','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_043','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Synthesize how the concept of ''Energy Transfer'' dictates whether heating causes a physical or chemical change.','["Heating always causes a chemical change.","Low levels of thermal energy transfer typically only increase particle kinetic energy, leading to physical state changes (melting/boiling) as intermolecular forces are overcome. However, intense thermal energy transfer can exceed the ''activation energy'' required to break the stronger *intramolecular* chemical bonds, triggering a chemical reaction (burning/cooking).","Heating always causes a physical change.","Energy transfer is not related to heat."]',1,'A little heat melts the butter (physical); a LOT of heat burns the butter black (chemical)!','Why heating can cause different types of change: Heating does not always cause a chemical change. Boiling water — physical change... Toasting bread — chemical changes. (Synthesis: Depends on how much heat and what the substance is).','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_044','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Evaluate the chemical implication of a ''Precipitate'' forming when two clear liquids are mixed.','["It means the liquids were frozen solid by the room temperature.","The sudden formation of an insoluble solid (a precipitate) from two homogeneous liquid solutions is a definitive empirical indicator of a chemical change. It proves that the constituent ions in the two liquid reactants underwent a double-displacement chemical reaction to synthesize a completely novel, insoluble chemical compound.","It means the liquids were physically mixed without reacting.","It means the liquids evaporated instantly."]',1,'If two clear liquids suddenly make a powdery rock that sinks to the bottom, they definitely reacted to make a new chemical!','How can we recognise a chemical change? Possible clues include: ... A new solid forming from liquids.','2026-11-01 09:12:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('chem_changes1_global_045','Chemistry','Physical and Chemical Changes','Topic 10: Physical and Chemical Changes','Primary',10,'Critique the classification of ''Alloying'' (mixing metals like copper and zinc to make brass) as a Physical Change.','["Alloying is a chemical change because the metal changes color.","Alloying is correctly classified as a physical change. Despite the macroscopic changes in properties (hardness, color), the constituent metals do not undergo a chemical reaction to form a new molecular compound. They remain a physical, homogeneous solid mixture (a solid solution) where the atomic structures are blended, not bonded.","Alloying is a chemical change because it requires heat.","Alloying is a physical change because metals cannot be mixed."]',1,'Melting metals together is just making a ''metal smoothie''; they mix, but they don''t chemically react!','A physical change occurs when a material changes its... appearance without forming a new substance. (Synthesized with Topic 9 where Brass is defined as a mixture).','2026-11-01 09:12:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_001','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is Biology?','["The study of rocks and space.","The scientific study of living things and their environments.","The study of numbers and math.","The study of how to build machines."]',1,'Bio means life!','Biology is the scientific study of living things and their interactions with the environment.','2026-11-01 09:14:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_002','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What does the word ''bio'' mean in Greek?','["Star","Rock","Life","Water"]',2,'It is the first half of the word ''biology''.','The word biology comes from Greek word roots: bio means life...','2026-11-01 09:14:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_003','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'Which of these is considered a ''living thing''?','["A plastic toy","A growing tree","A glass window","A cloud in the sky"]',1,'It is alive and grows.','A growing tree: Living - It grows, uses energy, and carries out life processes.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_004','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'Which of these is considered a ''non-living thing''?','["A mushroom","A dog","A rock","A bacteria"]',2,'It has never been alive.','A rock: Non-living - It does not carry out life processes.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_005','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'How do most plants get their food?','["By eating bugs.","By drinking milk.","They make their own food using light energy (sunlight).","They buy it from the soil."]',2,'They use the sun to cook their own food.','Most plants make their own food using light energy.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_006','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is a ''habitat''?','["A type of plant.","A tool used to look at tiny things.","The natural place where an organism lives.","A type of animal."]',2,'It is an animal or plant''s home, like a forest or ocean.','Habitat: The natural place where an organism lives.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_007','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is a ''cell''?','["A type of rock.","The basic structural and functional unit of living organisms.","A type of energy.","A tool used by scientists."]',1,'It is the tiny building block of all life.','A cell is the basic structural and functional unit of living organisms.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_008','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What tool do scientists use to look at tiny things like cells or bacteria?','["Telescope","Thermometer","Microscope","Ruler"]',2,'It makes tiny things look much bigger!','Cells are generally too small to see clearly with the naked eye, so scientists often use microscopes to study them.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_009','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is a ''microorganism''?','["An organism that is very large, like a whale.","A type of non-living rock.","An organism too small to see clearly without magnification (like a microscope).","A plant that grows in the dark."]',2,'The prefix ''micro'' means extremely small.','Microorganism: An organism that is generally too small to see clearly without magnification.','2026-11-01 09:14:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_010','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What does ''reproduction'' mean?','["When an organism sleeps for a long time.","When an organism eats food.","The process by which organisms produce new organisms of their own kind.","When an organism removes waste."]',2,'It means making babies or new seeds!','Reproduction: The process by which organisms produce new organisms of their own kind.','2026-11-01 09:14:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_011','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is ''respiration''?','["Drinking water.","Growing taller.","Cellular chemical processes that release usable energy from nutrients.","Sleeping at night."]',2,'It is how living things get energy out of their food.','Respiration: Cellular chemical processes that release usable energy from nutrients.','2026-11-01 09:14:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_012','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'Which group of living things includes mushrooms, moulds, and yeasts?','["Plants","Animals","Fungi","Bacteria"]',2,'They are not plants, and they don''t make their own food.','Fungi: Mushrooms, moulds, and yeasts.','2026-11-01 09:14:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_013','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'If a toy robot moves and talks, why is it considered ''non-living''?','["Because it doesn''t have fur.","Because its movements are controlled by a machine, not biological life processes like a real animal.","Because it doesn''t like water.","Because it is too small."]',1,'It doesn''t grow, breathe, or need real food!','A toy robot: Non-living - Its movements are controlled by a machine, not biological life processes... Movement alone does not prove that something is alive.','2026-11-01 09:14:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_014','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What is the first step in a simple scientific investigation?','["Draw a conclusion","Observe (notice something about a living organism)","Record results","Eat a snack"]',1,'You have to look at something before you can ask a question about it!','A simple scientific investigation follows these steps: Step 1: Observe - Notice something about a living organism...','2026-11-01 09:14:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_015','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',1,'What should a scientist do if their experiment''s results don''t match their original guess?','["Erase the results and make up fake ones.","Cry and give up.","Revise their explanation based on the honest evidence.","Hide the evidence from other scientists."]',2,'Science is about finding the truth, not just being right!','Scientists must record results honestly. If the evidence does not support their original idea, they revise their explanation rather than changing the results.','2026-11-01 09:14:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_016','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'Why is a wooden table classified as ''non-living'' even though it is made from a tree?','["Because trees are not alive.","Because the wood is painted.","It is made from material that once came from a living tree, but the table itself no longer carries out life processes (it cannot grow or reproduce).","Because it does not have leaves anymore."]',2,'Once-living things are dead and can''t do things like grow or breathe anymore.','A wooden table: Non-living - It is made from material that once came from a living tree, but the table itself is not alive.','2026-11-01 09:14:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_017','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'Why is a dry, unplanted seed considered a ''living thing''?','["Because it can walk around.","Because it is green.","It is viable and currently dormant; it can begin to grow (carry out life processes) when given suitable conditions like water and warmth.","Because it tastes good."]',2,'It is basically ''sleeping'' until you plant and water it!','A dry seed: Living, if viable - It may remain dormant and grow when suitable conditions are available... A viable seed can be alive even when it appears inactive.','2026-11-01 09:14:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_018','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'Why is ''movement'' not a good enough characteristic to prove something is alive?','["Because some animals never move.","Because non-living things like cars, rivers, and wind can move, but they do not carry out biological life processes like growth or reproduction.","Because plants move faster than animals.","Because movement is an illusion."]',1,'A rolling rock moves, but it is definitely not alive!','Important: Movement alone does not prove that something is alive. A car moves, and a river flows, but neither is a living organism.','2026-11-01 09:14:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_019','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'How do fungi (like mushrooms) obtain their food, since they cannot photosynthesize like plants?','["They eat sunlight.","They hunt bugs like animals.","They obtain nutrients from organic materials or other organisms (often dead or decaying matter).","They drink pure water only."]',2,'They absorb their food from the dirt or dead trees they grow on!','Fungi: Mushrooms, moulds, and yeasts. Fungi obtain nutrients from organic materials or other organisms.','2026-11-01 09:14:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_020','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'What do plant cells typically have that animal cells do NOT have?','["A nucleus and cytoplasm.","A cell wall and chloroplasts (which help carry out photosynthesis).","A cell membrane and DNA.","Animals and plants have exactly the same cells."]',1,'The cell wall makes plants stiff, and chloroplasts make them green!','Plant and animal cells share some structures... Plant cells also typically have a cell wall, and many have chloroplasts that help carry out photosynthesis.','2026-11-01 09:14:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_021','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'How do animals and plants differ in how they obtain energy (nutrition)?','["Animals drink water, plants eat dirt.","Plants usually make their own food (sugars) using sunlight, while animals must obtain energy by eating food or other organisms.","Plants eat animals, animals eat sunlight.","There is no difference."]',1,'Plants are ''producers'', animals are ''consumers''.','Animals obtain energy by eating food or other organisms... green plants usually make sugars using sunlight, water, and carbon dioxide.','2026-11-01 09:14:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_022','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'What does it mean for an organism to ''respond to its surroundings''?','["It ignores everything around it.","It reacts to changes in its environment, like a plant growing toward the light or an animal running from danger.","It turns into a different animal.","It stays completely still forever."]',1,'If you poke a living thing, it reacts!','Response to surroundings: Living things respond to changes in their environment. A plant shoot may grow towards light, and an animal may move away from danger.','2026-11-01 09:14:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_023','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'Are all living things made of millions of cells?','["Yes, everything alive is huge.","No, some organisms, like many bacteria, consist of just one single cell.","Yes, cells are always found in groups of a million.","No, some living things have zero cells."]',1,'Bacteria are so tiny they are just one single cell!','A cell is the basic structural and functional unit... Some organisms, such as many bacteria, consist of just one cell. Plants and animals are made of many cells.','2026-11-01 09:14:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_024','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'How does biology help us in the field of ''Agriculture''?','["By helping us build better bridges.","By helping us understand how to grow crops better, choose suitable conditions for them, and protect them from pests and diseases.","By helping us build computers.","By helping us fly planes."]',1,'Farming is basically applied biology!','Agriculture: Growing crops and protecting plants from pests and diseases... Knowledge of plant growth helps farmers choose suitable conditions for crops.','2026-11-01 09:14:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_025','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'If you want to test if a seed needs water to grow, what is the best way to design a ''fair test''?','["Give one seed water and another seed milk.","Put one seed in the dark with water, and one seed in the light with no water.","Place one seed on a damp towel and an identical seed on a dry towel, keeping them in the exact same location and light conditions.","Only test one seed with water."]',2,'A fair test changes only ONE thing (water) and keeps everything else exactly the same!','Place seeds on damp paper towels in one container. Place similar seeds on dry paper towels in another... Keep both containers in a suitable, warm location with appropriate light conditions.','2026-11-01 09:14:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_026','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'What is ''biodiversity''?','["The study of rocks.","The variety of living organisms in a specific area or across the entire Earth.","The process of a plant growing.","The speed at which an animal runs."]',1,'It means having lots of different kinds of plants and animals!','Biodiversity: The variety of living organisms in an area or across Earth.','2026-11-01 09:14:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_027','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'Why must living things manage ''waste removal''?','["Because waste makes them heavier.","Because life processes (like respiration and digestion) naturally produce toxic byproducts that must be removed so they don''t poison the organism.","Because waste is used to build houses.","Living things do not produce waste."]',1,'Just like humans need to go to the bathroom, all living cells make trash they need to get rid of!','Waste removal: Living things produce waste as part of their life processes and must remove or manage it.','2026-11-01 09:14:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_028','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'What does it mean when a seed is ''dormant''?','["It is dead and will never grow.","It is fully grown.","It is in a period of reduced activity, waiting for suitable conditions (like water and warmth) before it begins to grow.","It is currently growing very fast."]',2,'It''s like the seed is hibernating!','Dormancy: A period of reduced activity that helps an organism or seed survive unfavourable conditions.','2026-11-01 09:14:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_029','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'What is ''cytoplasm''?','["The hard shell of a turtle.","The jelly-like substance inside a cell where the organelles float.","The green part of a leaf.","The bone of a mammal."]',1,'It''s the ''jelly'' that fills up the inside of the cell!','This applies general biology knowledge based on the cell diagram provided. The diagram shows the cell membrane surrounding the cytoplasm.','2026-11-01 09:14:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_030','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',5,'How does biology help in the field of ''Medicine''?','["It helps doctors build hospitals out of brick.","It helps doctors understand how the human body works, how diseases spread, and how treatments and medicines affect our cells.","It helps doctors drive ambulances faster.","It teaches doctors how to paint."]',1,'You can''t fix a human body if you don''t understand the biology of how it works!','Medicine: Understanding the human body, diseases, and how treatments work.','2026-11-01 09:14:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_031','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Critique the assertion that ''Since fire consumes oxygen, grows in size, and responds to water by shrinking, it must be a living organism.''','["The assertion is true; fire is a living plasma.","The assertion highlights the danger of using single characteristics to define life. While fire ''grows'' and uses oxygen (combustion, not respiration), it lacks cellular structure, genetic material (DNA), and the ability to reproduce biological offspring. Therefore, the overall pattern of life is absent.","The assertion is true because fire moves on its own.","The assertion is false because fire doesn''t drink water."]',1,'Fire might act alive in some ways, but it doesn''t have cells or DNA!','No single characteristic, considered by itself, is always enough to identify life; scientists consider the overall pattern of life processes.','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_032','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Analyze the biological necessity of ''Chloroplasts'' in plant cells compared to animal cells.','["Animal cells have chloroplasts, plant cells do not.","Plant cells are autotrophic; they require chloroplasts (containing chlorophyll) to capture solar energy and synthesize glucose via photosynthesis. Animal cells are heterotrophic; they obtain pre-synthesized glucose by consuming other organisms, rendering chloroplasts biologically unnecessary for their energy acquisition strategy.","Chloroplasts help animals see in the dark.","Chloroplasts are only used to make plants green, not for energy."]',1,'Plants have to make their own food using the sun, so they need special ''solar panels'' (chloroplasts) that animals don''t need!','Plant cells also typically have a cell wall, and many have chloroplasts that help carry out photosynthesis... Animals obtain energy by eating food...','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_033','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Synthesize why a virus is often considered to be on the border between living and non-living.','["Viruses are plants that can walk.","While not explicitly detailed in the text, synthesizing the ''characteristics of life'' implies this. Viruses lack cellular structure, cannot metabolize nutrients (no respiration), and cannot reproduce independently. However, they possess genetic material and can evolve, confusing the strict binary classification of ''living'' vs ''non-living''.","Viruses are just small animals.","Viruses are made of pure rock."]',1,'A virus is like a USB drive; it has code, but it can''t do anything at all until you plug it into a living cell (computer)!','This requires synthesizing the ''characteristics of life'' list (cells, growth, reproduction, respiration). Viruses fail most of these without a host.','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_034','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Evaluate the ecological relationship between ''Respiration'' in animals and ''Photosynthesis'' in plants.','["They are completely unrelated processes.","They form a complementary, symbiotic biochemical cycle. Plants utilize solar energy, water, and CO₂ (often produced by animal respiration) to synthesize glucose and release O₂. Animals then consume the glucose and use the O₂ for cellular respiration, releasing CO₂ back to the plants, creating a closed metabolic loop.","Plants do both processes to kill animals.","Animals use photosynthesis to create oxygen for plants."]',1,'Plants make the oxygen and food we need; we breathe out the carbon dioxide the plants need!','Animals obtain energy by eating food... green plants usually make sugars using sunlight, water, and carbon dioxide. Respiration: Cells release usable energy... this process uses oxygen...','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_035','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Analyze the function of ''Dormancy'' as an evolutionary survival strategy for seeds.','["Dormancy kills the seed so a new one can grow.","Dormancy allows an organism to suspend its metabolic life processes during periods of severe environmental stress (e.g., winter freezing, severe drought). By waiting until ambient conditions (moisture, temperature) are optimal for germination, the seed drastically increases the biological probability of offspring survival.","Dormancy allows the seed to turn into a rock.","Dormancy makes the seed grow twice as fast."]',1,'If a seed sprouts in the middle of a freezing winter, it will die. Dormancy lets it wait for spring!','A viable seed can remain dormant until conditions are suitable for germination... Dormancy: A period of reduced activity that helps an organism or seed survive unfavourable conditions.','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_036','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Synthesize how the concept of ''Biodiversity'' contributes to the stability of an ecosystem (like a forest).','["Biodiversity makes the forest weaker and easier to destroy.","High biodiversity means a complex web of interdependent species. If a specific disease eradicates one species of plant, a highly diverse forest has alternative food sources for herbivores, preventing systemic ecological collapse. Low biodiversity (monocultures) are highly vulnerable to single catastrophic events.","Biodiversity means there is only one type of animal in the forest.","Biodiversity has no effect on the forest."]',1,'Don''t put all your eggs in one basket! A forest with 100 different types of trees will survive a disease much better than a forest with only 1 type of tree.','Biodiversity: The variety of living organisms in an area or across Earth. (Synthesis: Why is ''variety'' important? It creates resilience).','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_037','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Critique the student statement: ''Since plants don''t move, they don''t respond to their surroundings.''','["The statement is biologically accurate.","The statement represents a macroscopic fallacy. While plants lack muscular locomotion, they exhibit profound biochemical and physical responses to stimuli (tropisms). They can alter their growth vectors toward light (phototropism), grow roots toward gravity/water, and even release defensive chemicals when attacked by herbivores.","The statement is true because plants are non-living.","The statement is true because plants only respond to sound."]',1,'Plants might not run away, but they slowly bend toward the sun and reach their roots toward water!','Living things respond to changes in their environment. A plant shoot may grow towards light...','2026-11-01 09:14:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_038','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Evaluate the importance of ''Fungi'' as decomposers within a habitat.','["Fungi are useless because they don''t hunt animals.","Fungi are critical biogeochemical recyclers. By secreting extracellular enzymes to digest dead organic matter (like fallen trees), they break down complex polymers (lignin/cellulose) into simple inorganic nutrients. This process returns essential elements (carbon, nitrogen) to the soil, sustaining the autotrophic plant life of the habitat.","Fungi act as the main predators in the ocean.","Fungi produce all the oxygen on Earth."]',1,'Without fungi to rot dead trees, the forest would eventually be buried in dead wood and run out of dirt!','Fungi obtain nutrients from organic materials or other organisms. (Synthesis: What happens to the organic material? It gets recycled).','2026-11-01 09:14:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_039','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Analyze the structural and functional difference between the ''Cell Wall'' and the ''Cell Membrane'' in a plant cell.','["They are two names for the exact same structure.","The cell membrane is a semi-permeable lipid bilayer present in all cells that selectively regulates the transport of molecules in and out of the cytoplasm. The cell wall is a rigid, outer structural layer (composed of cellulose in plants) that provides mechanical support and protection against osmotic pressure, but is not selectively permeable.","The cell wall is only found in animals.","The cell membrane is made of solid wood."]',1,'The membrane is like the security guard checking who comes in; the wall is like a brick wall holding the building up!','Plant and animal cells share some structures, including a cell membrane... Plant cells also typically have a cell wall...','2026-11-01 09:14:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_040','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Synthesize why ''Biotechnology'' relies heavily on a deep understanding of Microorganisms.','["Because microorganisms are easy to see with the naked eye.","Microorganisms (like bacteria and yeast) possess rapid reproduction cycles, simple genetics, and unique metabolic pathways (like fermentation). Biotechnology leverages these biological mechanisms, using the microbes as microscopic ''factories'' to synthesize specific, useful products like insulin, antibiotics, biofuels, or fermented foods.","Because microorganisms are non-living machines.","Because microorganisms are made of plastic."]',1,'Bacteria multiply incredibly fast, so scientists can use them to manufacture medicines very quickly!','Biotechnology: Using living cells or organisms to produce useful products. Microorganisms... yeast can convert sugars into alcohol...','2026-11-01 09:14:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_041','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Critique the necessity of ''Step 5: Draw a conclusion'' in the scientific method if the results do not support the hypothesis.','["If the results are wrong, you should skip Step 5 and try again.","Step 5 is arguably the most critical step precisely *when* the hypothesis fails. A negative result is valid empirical data. The conclusion must synthesize *why* the initial assumption failed based on the new evidence, leading to a revised hypothesis and deeper understanding, which is the fundamental mechanism of scientific progress.","Step 5 is only used when the scientist is right.","Step 5 requires the scientist to change the data to match the hypothesis."]',1,'In science, being proven ''wrong'' is actually a good thing because it means you learned something new!','Step 5: Draw a conclusion... Scientists must record results honestly. If the evidence does not support their original idea, they revise their explanation rather than changing the results.','2026-11-01 09:14:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_042','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Analyze the physiological purpose of ''Cellular Respiration'' across both plant and animal kingdoms.','["It is a process used exclusively to create body heat.","Cellular respiration is the universal metabolic mechanism for generating biological work. Regardless of whether the organism is a plant or an animal, cells must oxidize organic molecules (like glucose) to synthesize ATP (adenosine triphosphate). This ATP acts as the universal energy currency required to power all other cellular life processes.","It is the process of breathing air in and out of lungs.","It is a process only used by plants in the dark."]',1,'Your lungs breathe air, but your microscopic CELLS use that oxygen to burn sugar and make energy!','Respiration: Cells release usable energy from nutrients through chemical processes. In many organisms, this process uses oxygen... (Synthesis: It''s about energy release, not just breathing).','2026-11-01 09:14:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_043','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Synthesize how the environment of a ''Desert'' habitat forces severe evolutionary adaptations in its organisms.','["Deserts have no effect on organisms because animals can just drink sand.","Deserts are characterized by extreme abiotic stressors: severe water scarcity and high thermal variance. Organisms must evolve radical biological adaptations to survive. Plants may evolve deep taproots or waxy cuticles to prevent transpiration (cacti), while animals may become nocturnal or evolve highly efficient renal systems to minimize water waste.","Deserts cause all animals to grow thick fur for warmth.","Deserts force animals to learn how to photosynthesize."]',1,'You can''t survive in a desert unless your body changes to save every single drop of water!','Desert: Organisms adapted to limited water and often extreme temperatures. An organism''s survival depends on suitable conditions...','2026-11-01 09:14:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_044','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Evaluate the biological classification of a ''Virus'' compared to ''Bacteria''.','["They are exactly the same thing, both being single-celled animals.","Bacteria are classified as living organisms because they are complete, single-celled entities capable of independent metabolism, growth, and reproduction. Viruses are sub-microscopic infectious agents composed only of genetic material in a protein coat. They lack cellular structure and cannot metabolize or reproduce outside of a living host cell, placing them on the edge of biological life.","Viruses are plants, while bacteria are animals.","Viruses are visible to the naked eye, bacteria are not."]',1,'A bacteria is a living, breathing, eating cell. A virus is just a tiny piece of rogue code that hijacks other cells!','This applies the definition of a cell. ''A cell is the basic structural and functional unit... bacteria, consist of just one cell.'' Viruses lack this structure.','2026-11-01 09:14:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_intro_global_045','Biology','Introduction to Living Things','Topic 1: Introduction to Biology','Primary',10,'Critique the idea that ''All life on Earth requires Oxygen to survive.''','["The idea is an absolute law of biology with no exceptions.","The idea is a terrestrial, macroscopic bias. While humans, animals, and plants rely on aerobic respiration, an immense diversity of life consists of anaerobic microorganisms (like certain archaea and bacteria). These organisms inhabit extreme anoxic environments (deep sea vents, mud, intestinal tracts) and utilize alternative chemical pathways (like fermentation or sulfate reduction) to generate metabolic energy.","The idea is true because oxygen is the only gas in the atmosphere.","The idea is true because water is made of oxygen."]',1,'Many bacteria live deep in the mud or at the bottom of the ocean where there is zero oxygen, and they survive perfectly fine!','Respiration: ... In many organisms, this process uses oxygen, but some organisms can release energy without oxygen.','2026-11-01 09:14:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_001','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is the main job of a plant''s roots?','["To catch sunlight.","To make seeds.","To absorb water and minerals and anchor the plant in the soil.","To attract bees."]',2,'They hold the plant in the ground like an anchor.','Roots — absorb water and minerals and often anchor the plant in the soil.','2026-11-01 09:14:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_002','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'Which part of the plant is responsible for supporting the leaves and flowers?','["The roots","The stem","The fruit","The seeds"]',1,'It acts like the plant''s backbone.','Stem — supports the plant and transports water, minerals, and sugars.','2026-11-01 09:14:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_003','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'In which part of the plant does most of the food-making (photosynthesis) happen?','["The roots","The flowers","The leaves","The stem"]',2,'They are usually flat and green to catch sunlight.','Leaves — carry out most photosynthesis in many plants.','2026-11-01 09:14:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_004','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is the beautiful, colourful part of a plant that helps it reproduce?','["The root","The flower","The stem","The leaf"]',1,'Bees love to visit this part!','Flowers — help the plant reproduce. They often have colourful petals...','2026-11-01 09:14:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_005','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What part of a flowering plant protects the seeds and can often be eaten by animals?','["The stem","The roots","The fruit","The pollen"]',2,'Apples and tomatoes are examples.','Fruits — develop from the flower''s ovary in flowering plants and often protect seeds.','2026-11-01 09:14:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_006','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is inside a seed?','["A tiny, young plant (embryo) and stored food.","Pure water.","A fully grown tree.","Dirt."]',0,'It is a baby plant waiting to grow!','Seeds — contain a young plant (embryo) and stored food or structures that help provide nourishment...','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_007','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What does a plant need from the air to make its own food?','["Oxygen","Nitrogen","Carbon dioxide","Helium"]',2,'They use the gas that humans breathe out.','Plants use the sugars they make from water and carbon dioxide.','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_008','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What provides the energy a plant needs for photosynthesis?','["Wind","Soil","Light energy (usually from the Sun)","Water"]',2,'Plants need this to grow big and strong during the day.','Light provides energy for photosynthesis.','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_009','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is the green pigment in leaves called?','["Melanin","Chlorophyll","Haemoglobin","Paint"]',1,'It is what makes leaves look green.','They contain chlorophyll, a green pigment that absorbs light energy.','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_010','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is it called when a seed starts to grow into a new plant?','["Photosynthesis","Pollination","Germination","Evaporation"]',2,'It happens when you plant a seed and water it.','Germination is the beginning of a seed''s growth into a seedling.','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_011','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'How do some light seeds travel away from the parent plant (seed dispersal)?','["They walk.","They swim.","They are carried through the air by the wind.","They dig underground."]',2,'Think of a dandelion blowing in the breeze.','Wind: light seeds may be carried through the air.','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_012','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'Do all plants have flowers?','["Yes, every plant has a flower.","No, some plants like mosses do not produce flowers.","Yes, but they are invisible.","No, only trees have flowers."]',1,'Ferns and mosses are different!','Not all plants have every part in the same form. For example, mosses do not produce flowers or seeds...','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_013','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'Why do animals visit flowers?','["To eat the leaves.","They are attracted by colourful petals or scents.","To hide from rain.","To sleep inside the stem."]',1,'Bees and butterflies love the bright colors and sweet smells.','They often have colourful petals or scents that attract pollinators...','2026-11-01 09:14:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_014','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'What is ''pollination''?','["When a plant dies.","When pollen reaches a flower''s stigma.","When a seed starts to grow.","When a leaf falls off a tree."]',1,'It''s how plants get ready to make seeds.','Pollination occurs when pollen reaches a flower''s stigma.','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_015','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',1,'How do roots help the soil?','["They make the soil wet.","They turn the soil into rocks.","They can help hold soil in place and reduce erosion.","They make the soil disappear."]',2,'They act like a net keeping the dirt from washing away.','Soil protection: Roots can help hold soil in place and reduce erosion.','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_016','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Why is the ''stem'' of a plant like a highway system?','["Because it is paved with concrete.","Because it transports water and minerals up from the roots, and sugars down from the leaves to the rest of the plant.","Because insects drive cars on it.","Because it is completely hollow inside."]',1,'It moves the ''food'' and ''water'' traffic up and down the plant.','Stem... transports water, minerals, and sugars. Water and minerals move from roots towards the leaves... Sugars made during photosynthesis are transported to parts of the plant that need or store them.','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_017','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'What is the difference between a ''taproot'' and ''fibrous roots''?','["Taproots are green, fibrous roots are brown.","A taproot has one thick main root (like a carrot), while fibrous roots are a spreading network of many thin roots (like grass).","Taproots grow above ground, fibrous roots grow underwater.","There is no difference."]',1,'Think of a single long carrot vs a messy clump of grass roots.','Taproot: One main root with smaller side roots (Example: Carrot). Fibrous roots: Many thin roots spreading from the base (Example: Grass).','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_018','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'How do plants ''breathe'' in the carbon dioxide they need?','["Through their roots in the soil.","Through their flowers.","Through tiny openings in their leaves usually called ''stomata''.","Through the bark on their stem."]',2,'They are like microscopic mouths on the bottom of the leaf.','Leaves also have tiny openings, usually called stomata, that allow gases to move in and out.','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_019','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'What happens during ''transpiration''?','["The plant eats a bug.","Water vapour escapes from the plant, mainly through the stomata in its leaves.","The plant makes a flower.","The roots absorb rocks."]',1,'It''s like the plant is ''sweating'' invisible water vapor.','Water vapour can escape through these openings in a process called transpiration.','2026-11-01 09:14:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_020','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Botanically speaking, why is a tomato actually a fruit and not a vegetable?','["Because it is sweet and red.","Because it grows on a vine.","Because it develops from a flower''s ovary and contains seeds.","Because it is used in salads."]',2,'If it holds the seeds, science calls it a fruit!','Fruits — develop from the flower''s ovary in flowering plants and often protect seeds. Examples include apples, tomatoes...','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_021','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'What is the difference between ''pollination'' and ''fertilisation''?','["They are exactly the same thing.","Pollination is when a seed grows; fertilisation is when a flower opens.","Pollination is the physical transfer of pollen to the stigma; fertilisation is the actual joining of the reproductive cells inside the ovary.","Pollination is done by wind, fertilisation is done by bees."]',2,'Pollination is the delivery; fertilisation is what happens after the package arrives!','Pollination and fertilisation are not the same: pollination is the transfer of pollen to the stigma; fertilisation involves the joining of reproductive cells.','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_022','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'If you want to test if a seed needs water to germinate (a fair test), what must you do?','["Give one seed water and another seed fertilizer.","Give one seed water and keep another identical seed dry, while keeping the temperature and light exactly the same for both.","Put one seed in the dark and one in the light.","Test only one seed with a lot of water."]',1,'You must only change ONE thing at a time to know what caused the result.','Fair-test rule: Keep seed type, number of seeds, container, temperature, and location as similar as possible. Change only the water condition.','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_023','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Do all seeds need bright sunlight to begin germinating?','["Yes, seeds will never grow without light.","No, most seeds do not require light to BEGIN germinating, but they will need it later to grow into healthy seedlings.","Yes, sunlight is the only thing a seed needs.","No, light actually kills all seeds."]',1,'They usually sprout while buried in the dark dirt!','Most do not require light to begin germinating, although light becomes important for the growth of many seedlings once they emerge.','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_024','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Why is oxygen an important product of photosynthesis for humans and animals?','["Because we use oxygen to build houses.","Because photosynthesis releases oxygen into the environment, which humans and animals must breathe to survive.","Because oxygen makes water taste better.","Oxygen is not important."]',1,'Plants ''breathe out'' the exact gas that we need to ''breathe in''!','Oxygen: Photosynthesis releases oxygen into the environment... Humans and many other organisms use oxygen...','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_025','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'In a flower, what is the ''stamen''?','["The colorful petal.","The part that produces pollen (usually including an anther and a filament).","The female reproductive structure.","The root of the flower."]',1,'It''s the part that makes the yellow pollen dust!','Stamens: the parts that produce pollen; each usually includes an anther and a filament.','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_026','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'In a flower, what does the ''ovary'' do?','["It produces pollen.","It attracts bees.","It contains ovules, which can develop into seeds after fertilisation.","It holds the plant up."]',2,'It''s the part that swells up to become the fruit!','Ovary: contains ovules, which can develop into seeds after fertilisation.','2026-11-01 09:14:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_027','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'How do some plants use animals for ''seed dispersal''?','["The animals eat the seeds and destroy them completely.","Seeds may stick to an animal''s fur and fall off later, or pass through an animal''s digestive system and be left in a new location.","Animals plant the seeds using tools.","Animals guard the seeds so they don''t move."]',1,'A bird might eat a berry and drop the seed far away!','Animals: seeds may stick to fur or pass through an animal''s digestive system.','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_028','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Do plants ONLY carry out photosynthesis?','["Yes, they only make food.","No, plants also respire (breathe) day and night to use the energy they made, just like animals do.","Yes, they never use energy.","No, they only respire at night."]',1,'They make the food during the day, but they burn that food for energy 24/7!','Plants also respire, day and night. Photosynthesis and respiration are different processes.','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_029','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Can a plant grow without soil?','["No, soil is absolutely essential for every single plant.","Yes, plants can grow in water-based systems (like hydroponics) as long as the water provides the necessary mineral nutrients and conditions.","No, plants will instantly die without dirt.","Yes, but they will never grow roots."]',1,'As long as they get the vitamins they normally find in dirt, they don''t actually need the dirt!','Soil often supplies water and minerals and supports roots, but soil itself is not essential for every plant. Plants can also grow in water-based systems when the necessary nutrients and conditions are provided.','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_030','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',5,'Why is ''chlorophyll'' essential for a plant''s survival?','["It makes the plant smell good to bees.","It is the specific green pigment that is able to absorb the light energy needed to power photosynthesis.","It acts as a poison to stop bugs from eating the leaves.","It is the only part of the plant that absorbs water."]',1,'Without this green chemical, the plant couldn''t capture the sun''s power!','They contain chlorophyll, a green pigment that absorbs light energy... the process by which plants use light energy to make sugars...','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_031','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Critique the assertion that ''Plants obtain their food by absorbing it from the soil through their roots.''','["The assertion is scientifically accurate.","The assertion is a fundamental misconception. Roots absorb inorganic ''mineral nutrients'' and water, not ''food'' (energy-yielding organic compounds). Plants are autotrophs; they manufacture their own organic food (glucose) via photosynthesis in their leaves, utilizing solar energy to combine CO₂ and H₂O.","The assertion is true because roots have mouths.","The assertion is true, but only for trees."]',1,'Fertilizer in the soil isn''t ''food''—it''s more like vitamins. The plant cooks its own food using the sun!','Roots do not absorb food from the soil in the same way animals eat food; most plants manufacture sugars in their green parts through photosynthesis.','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_032','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Analyze the biochemical equation for Photosynthesis: Carbon dioxide + water + light energy → sugar + oxygen. What thermodynamic process is occurring?','["The plant is destroying energy.","Photosynthesis is an endothermic (energy-absorbing) anabolic reaction. The plant transduces radiant solar energy into stable chemical potential energy, storing it within the covalent bonds of the newly synthesized glucose (sugar) molecules.","The plant is creating a nuclear explosion.","The plant is turning solid sugar into light."]',1,'The plant is taking sunlight and trapping it inside a sugar molecule!','Photosynthesis, the process by which plants use light energy to make sugars from water and carbon dioxide. (Synthesis: It converts light energy into stored chemical energy).','2026-11-01 09:14:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_033','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Synthesize the physiological relationship between ''Stomata'' and ''Transpiration''.','["Stomata physically pump water out of the plant.","Stomata are pores necessary for gas exchange (absorbing CO₂ for photosynthesis). However, opening these pores exposes the saturated interior of the leaf to the drier atmosphere. This inevitably results in Transpiration—the passive, evaporative loss of water vapor driven by the concentration gradient.","Stomata are designed exclusively to waste water.","Stomata block all water from escaping the plant."]',1,'The plant HAS to open its ''mouths'' to breathe in CO2, but when it does, it accidentally loses water to the air!','Leaves also have tiny openings, usually called stomata, that allow gases to move in and out. Water vapour can escape through these openings in a process called transpiration.','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_034','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Evaluate the evolutionary advantage of a ''Fleshy Fruit'' (like an apple) in angiosperms.','["The fruit provides a food source for the growing seed.","The fleshy, nutritious fruit is an evolutionary adaptation for zoocory (animal-mediated seed dispersal). By investing energy into creating a palatable food source, the plant ensures an animal will consume the fruit and subsequently excrete the indigestible seeds in a new, distant location, often with a ''starter'' of fertilizer.","The fruit is designed to poison animals that eat it.","The fruit makes the plant too heavy, causing it to fall over and plant itself."]',1,'The plant makes a tasty treat on purpose so an animal will carry its babies (seeds) far away!','Fruits... often protect seeds and often assist seed dispersal... seeds may stick to fur or pass through an animal''s digestive system.','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_035','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Analyze the structural classification of a ''Potato Tuber'' compared to a ''Sweet Potato''.','["They are identical root structures.","Despite both growing underground and storing starch, they are anatomically distinct. A sweet potato is an enlarged storage *root*. A potato tuber is a modified, swollen underground *stem* (possessing nodes or ''eyes'' which roots lack), adapted for energy storage and vegetative reproduction.","A potato is a leaf, a sweet potato is a flower.","A potato grows on branches, a sweet potato grows in dirt."]',1,'Even though it''s buried in the dirt, a normal potato is actually a swollen stem, not a root!','Storage roots: Roots enlarged to store food... Example: Sweet potato. Examples of modified stems include potato tubers... These structures can store food...','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_036','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Synthesize the dual ecological role of plants regarding the Atmospheric Carbon Cycle.','["Plants only produce carbon dioxide, harming the environment.","Plants act as both a massive carbon ''sink'' and a carbon ''source''. During daylight, high-rate photosynthesis heavily sequesters atmospheric CO₂, locking the carbon into organic biomass. However, continuously through cellular respiration (and eventually upon decomposition), they also release CO₂ back into the atmosphere.","Plants only absorb carbon and never release it.","Plants have no effect on carbon levels."]',1,'They take Carbon Dioxide out of the air to build their bodies, but they also breathe a little bit back out to stay alive!','Plants use carbon dioxide during photosynthesis... Plants also respire, day and night. Photosynthesis and respiration are different processes. (Synthesis: They absorb CO2 to make food, but release it when burning that food for energy).','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_037','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Critique the experimental design: To test if light is needed for germination, a student places wet seeds in a dark cupboard and dry seeds on a sunny windowsill.','["The experiment is perfectly designed.","The experimental design is critically flawed because it violates the principle of controlling variables (a fair test). The student altered two independent variables simultaneously (Light/Dark AND Wet/Dry). If neither seed germinates, it is impossible to empirically determine whether the failure was due to the lack of light, the lack of water, or both.","The experiment is flawed because seeds must be planted in soil.","The experiment is perfect because it tests two things at once to save time."]',1,'You can''t change the water AND the light at the same time; if the seed dies, you won''t know whose fault it was!','Fair-test rule: Keep seed type, number of seeds, container, temperature, and location as similar as possible. Change only the water condition. (Synthesis: Applying the fair test rule to a new scenario).','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_038','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Evaluate the biological purpose of ''Dormancy'' in a seed.','["Dormancy means the seed is permanently dead.","Dormancy is a complex physiological state of arrested development and severely depressed metabolic activity. It prevents premature germination during transiently favorable conditions (like a brief warm spell in autumn), ensuring the embryo only resumes growth when sustained environmental conditions (temperature, moisture, light) are optimal for seedling survival.","Dormancy makes the seed grow incredibly fast.","Dormancy turns the seed into a flower instantly."]',1,'It''s an evolutionary trick to make sure the baby plant doesn''t wake up in the middle of winter and freeze to death!','A viable seed can remain dormant until conditions are suitable for germination.','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_039','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Analyze the function of the ''Pistil'' (or Carpel) in angiosperm reproduction.','["It is the structure that produces pollen.","The pistil is the complete female reproductive organ of the flower. It consists of the stigma (a sticky receptive surface to capture pollen), the style (a conduit tube), and the basal ovary. Following pollination, a pollen tube grows down the style to deliver sperm cells to the ovules within the ovary, achieving fertilisation.","It is the colourful petal that attracts bees.","It is the root system of the flower."]',1,'It''s the central part of the flower that acts as a landing pad for pollen and houses the ''eggs'' (ovules)!','Pistil or carpel: the female reproductive structure, which includes the stigma, style, and ovary in many flowers. Ovary: contains ovules, which can develop into seeds after fertilisation.','2026-11-01 09:14:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_040','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Synthesize how the concept of ''Vascular Tissue'' (Xylem and Phloem, implied by stem transport) solves the physical limitations of large plants.','["Vascular tissue makes the plant invisible.","Unlike non-vascular mosses which must remain small and in damp environments to absorb water via osmosis, large plants possess specialized vascular ''plumbing''. The stem''s transport tissues defy gravity, moving water/minerals unilaterally from roots to the canopy, and bidirectionally distributing photosynthetic sugars, enabling massive vertical growth (trees).","Vascular tissue prevents the plant from growing tall.","Vascular tissue turns the roots into leaves."]',1,'A giant redwood tree can only survive because its stem has microscopic ''pipes'' pumping water hundreds of feet into the air!','Stem — ... transports water, minerals, and sugars. Water and minerals move from roots towards the leaves through specialised tissues. Sugars made during photosynthesis are transported to parts of the plant... (Synthesis: How do trees get so big? A plumbing system).','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_041','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Critique the use of the word ''Vegetable'' in a strict botanical context versus a culinary context.','["Botanically, all plants are vegetables.","The term ''vegetable'' has no strict botanical definition; it is a culinary term referring to edible plant parts (roots, stems, leaves). Botanically, if an edible plant structure developed from a flower''s mature ovary and contains seeds (e.g., a tomato, cucumber, or pumpkin), it is definitively classified as a ''fruit'', regardless of its savory culinary use.","Botanically, vegetables are only the roots.","Culinary vegetables are always poisonous."]',1,'A chef calls a tomato a vegetable because it goes in a salad, but a scientist calls it a fruit because it has seeds inside!','Fruits — develop from the flower''s ovary in flowering plants and often protect seeds. Examples include apples, tomatoes... In everyday language, some foods are called vegetables even though botanically they are fruits.','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_042','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Analyze the environmental consequence if a plant''s ''Stomata'' remained permanently closed.','["The plant would grow exponentially faster.","If stomata remained permanently closed, the plant would completely halt transpiration, saving water. However, it would also completely sever gas exchange. Without the ability to absorb atmospheric \\\\(CO_2\\\\), the biochemical reactions of photosynthesis would cease, ultimately starving the plant and halting oxygen production.","The plant would turn into an animal.","The plant would absorb too much sunlight and explode."]',1,'The plant has to open its pores to ''breathe'' in the ingredients for its food; if it seals them shut to save water, it starves!','Leaves also have tiny openings, usually called stomata, that allow gases to move in and out. Water vapour can escape... (Synthesis: closing them stops water loss, but also stops CO2 intake).','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_043','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Synthesize the difference between ''Pollination'' and ''Fertilisation''.','["They are identical biological terms.","Pollination is strictly a mechanical vector process: the physical transfer of pollen grains from an anther to a receptive stigma (via wind or insects). Fertilisation is the subsequent cellular process: the biochemical fusion of the male gamete (from the pollen) with the female gamete (ovule) deep inside the ovary to form a viable zygote.","Pollination creates the fruit; fertilisation creates the flower.","Pollination happens in animals; fertilisation happens in plants."]',1,'Pollination is the mailman delivering the letter to the mailbox; fertilisation is reading the letter inside the house!','Pollination and fertilisation are not the same: pollination is the transfer of pollen to the stigma; fertilisation involves the joining of reproductive cells.','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_044','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Evaluate the biological necessity of a ''Fibrous Root'' system for a grass plant compared to a taproot.','["Fibrous roots are useless and cause the grass to die.","Grass inhabits environments where topsoil moisture is often transient. A fibrous root system creates a massive, dense, shallow subterranean surface area. This architecture allows the plant to rapidly maximize the absorption of light rainfall before it evaporates, while simultaneously providing superior soil stabilization (preventing erosion) compared to a single deep taproot.","Fibrous roots allow the grass to walk away from danger.","Fibrous roots dig straight down to find magma."]',1,'Instead of digging one deep hole like a carrot, grass spreads a giant shallow net to catch every drop of rain before it dries up!','Fibrous roots: Many thin roots spreading from the base. Example: Grass... Roots can help hold soil in place and reduce erosion. (Synthesis: form fits function).','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_plants_global_045','Biology','Plants and Their Parts','Topic 2: Plants and Their Parts','Primary',10,'Critique the assertion that ''Plants only rely on their roots to get everything they need to survive.''','["The assertion is completely accurate.","The assertion ignores the fundamental requirements of autotrophic life. While roots are essential for absorbing \\\\(H_2O\\\\) and inorganic mineral ions, they cannot absorb energy or carbon. A plant absolutely relies on its aerial structures (leaves) to capture photons (light energy) and absorb atmospheric \\\\(CO_2\\\\) to synthesize the actual organic molecules required for survival.","The assertion is true because roots also absorb sunlight.","The assertion is false because roots are only used for anchoring."]',1,'Roots are only half the equation! They get the water and vitamins, but the leaves have to get the carbon and the sunlight to actually cook the food!','Roots... absorb water and minerals... However, roots do not absorb food from the soil... most plants manufacture sugars in their green parts... Leaves... capture sunlight... Carbon dioxide, taken from the air.','2026-11-01 09:14:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_001','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What is the main difference between an animal and a green plant?','["Animals are always bigger than plants.","Animals do not make their own food through photosynthesis; they must eat or absorb it.","Animals only live in water.","Animals do not need energy."]',1,'Plants use the sun to cook; animals have to go grocery shopping in nature!','Unlike green plants, animals do not make their own food through photosynthesis... Animals are living organisms that obtain nutrients by eating or absorbing food...','2026-11-01 09:14:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_002','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What is a ''vertebrate''?','["An animal that eats only plants.","An animal with a backbone.","An animal that lives in the ocean.","An animal with a hard shell."]',1,'It has a spine inside its body.','Vertebrates: Animals with a backbone, such as fish, frogs, birds, lizards, and mammals.','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_003','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What is an ''invertebrate''?','["An animal without a backbone.","An animal that flies.","An animal with feathers.","An animal that only eats meat."]',0,'It does NOT have a spine.','Invertebrates: Animals without a backbone, such as insects, worms, snails...','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_004','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'Which of these is a ''mammal''?','["Frog","Shark","Eagle","Dog"]',3,'It has fur and drinks milk when it''s a baby.','Mammals... Examples: humans, elephants, bats, dogs, and dolphins.','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_005','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'Which of these is a ''reptile''?','["Snake","Salmon","Penguin","Earthworm"]',0,'It has scaly skin and usually lays eggs on land.','Reptiles... Examples: snakes, lizards, turtles, and crocodilians.','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_006','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'Which of these is an ''amphibian''?','["Spider","Frog","Dolphin","Ostrich"]',1,'It starts life in the water as a tadpole, then moves to land!','Amphibians... Examples: frogs, toads, and salamanders.','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_007','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'How many legs does an adult insect have?','["Four","Six","Eight","Ten"]',1,'Think of an ant or a butterfly.','Insects: Have six legs and three main body regions...','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_008','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What do ''herbivores'' eat?','["Only other animals.","Plants or plant parts.","Both plants and animals.","Dirt."]',1,'They are vegetarians, like rabbits or giraffes.','Herbivores: Animals that eat plants or plant parts.','2026-11-01 09:14:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_009','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What do ''carnivores'' eat?','["Only other animals (meat).","Only plants.","Both plants and animals.","Fungi."]',0,'They are meat-eaters, like lions.','Carnivores: Animals that eat other animals.','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_010','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What do ''omnivores'' eat?','["Only plants.","Only rocks.","Both plant and animal matter.","Only dead animals."]',2,'They eat a mix of everything, like humans and bears.','Omnivores: Animals that eat both plant and animal matter.','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_011','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What is an animal''s ''habitat''?','["The food it eats.","The place where an animal lives and finds the resources it needs.","The fur on its body.","The eggs it lays."]',1,'It''s the animal''s home in nature!','A habitat is the place where an animal lives and finds the resources it needs...','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_012','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What kind of body covering do birds have?','["Fur","Scales","Shell","Feathers"]',3,'It helps them fly and stay warm.','Birds: Have feathers and beaks.','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_013','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What kind of body covering do most fish and reptiles have?','["Moist skin","Scales","Hair","Feathers"]',1,'It looks like tiny, hard overlapping plates.','Fish... Most have... scales for protection. Reptiles: Have dry skin covered with scales...','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_014','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'What does a camel store in its hump?','["Water","Air","Fat","Sand"]',2,'It''s a storage tank for energy, not a water bottle!','Camels... Their humps store fat, not water.','2026-11-01 09:14:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_015','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',1,'Should you touch or feed wild animals when observing them?','["Yes, if they look hungry.","Yes, to see how they feel.","No, never handle unfamiliar animals or feed them unless specifically allowed.","Yes, but only if they are birds."]',2,'Keep wild animals wild and safe!','Safety: Never handle unfamiliar animals, nests, eggs, or wildlife. Do not feed wild animals...','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_016','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Why is an octopus considered an ''invertebrate'' even though it is very large and strong?','["Because it lives in the water.","Because it does not have an internal backbone or skeleton.","Because it has eight arms.","Because it lays eggs."]',1,'You don''t need a spine to be strong or smart!','Invertebrates: Animals without a backbone, such as insects, worms, snails, jellyfish, and octopuses.','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_017','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'What is a unique characteristic of mammals regarding how they feed their babies?','["They feed their young with nectar from flowers.","Females feed their young with milk produced by mammary glands.","They feed their young by throwing up fish.","Mammals do not feed their young."]',1,'This is where the word ''mammal'' comes from!','Mammals: ... Feed their young with milk produced by mammary glands.','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_018','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Do all mammals give birth to live babies?','["Yes, 100% of mammals have live births.","No, a few special mammals actually lay eggs.","Yes, except for dolphins.","No, mammals never have live births."]',1,'The platypus is a famous mammal that lays eggs!','Mammals: ... Most give birth to live young, but a few mammals lay eggs.','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_019','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'How do the life cycles of most amphibians (like frogs) differ from reptiles?','["Amphibians only live on land.","Many amphibians begin life as aquatic larvae (like tadpoles in water) before moving to land, while reptiles hatch from eggs on land.","Amphibians fly, reptiles swim.","Amphibians have hard shells, reptiles have moist skin."]',1,'Frogs start in the pond, turtles start on the beach!','Amphibians: Many live part of their lives in water and part on land... Many begin life as aquatic larvae, such as tadpoles. Reptiles... Many lay eggs on land...','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_020','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'If you find a creature with eight legs and no antennae, what is it?','["An insect","An arachnid (like a spider)","A crustacean","An amphibian"]',1,'Spiders have 8 legs, insects have 6!','Arachnids: Have eight legs as adults and do not have antennae.','2026-11-01 09:14:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_021','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Why do animals like crabs and lobsters need a hard ''exoskeleton'' (shell)?','["To help them fly.","To protect their soft invertebrate bodies and provide support, since they lack an internal backbone.","To keep them warm in winter.","To help them slither on land."]',1,'It''s like wearing armor on the outside instead of having bones on the inside!','Crustaceans: Many have hard external skeletons... Invertebrates may have soft bodies, shells, or external skeletons.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_022','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'What is an ''adaptation'' in biology?','["A disease an animal catches.","An inherited feature or behaviour that helps an organism survive and reproduce in its specific environment.","When an animal gets lost.","When an animal changes its diet for one day."]',1,'It''s a special trick or body part that makes the animal perfect for its home!','An adaptation is a feature or behaviour that helps an organism survive and reproduce in its environment over generations.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_023','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'How does a polar bear''s body covering (fur and fat) act as an adaptation?','["It makes them invisible to fish.","It insulates them, keeping their body heat trapped inside the freezing Arctic environment.","It helps them fly over the ice.","It stores water for them to drink."]',1,'It''s like wearing a heavy winter coat all the time!','Polar bears: have thick fur and a layer of body fat that help insulate them in cold environments.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_024','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Can an animal with an amazing adaptation survive anywhere in the world?','["Yes, adaptations make animals invincible.","No, adaptations are specific to a certain habitat; a polar bear''s thick fur would cause it to overheat and die in a desert.","Yes, as long as it has water.","Yes, if it is a vertebrate."]',1,'A superpower in the snow is a curse in the desert!','Adaptations do not mean an animal can survive everywhere. Each species has limits, and changes to its habitat can threaten its survival.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_025','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'How do fish obtain the oxygen they need to respire?','["They come to the surface to breathe air with lungs.","They absorb oxygen through their skin.","They usually breathe through gills, which extract dissolved oxygen from the water.","They don''t need oxygen."]',2,'Gills act like underwater lungs!','Fish: Live in water. Usually breathe through gills.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_026','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Why is ''moist skin'' an important body covering for some amphibians and worms?','["It makes them taste bad to predators.","It helps them with gas exchange (breathing) directly through their skin.","It reflects sunlight to keep them cool.","It helps them swim faster."]',1,'They can literally ''breathe'' through their wet skin!','Moist skin: Function - Helps gas exchange in some animals. Example: Frog, earthworm.','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_027','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Are all birds capable of flying?','["Yes, if it has wings, it can fly.","No, some birds (like penguins and ostriches) have feathers and wings but cannot fly.","Yes, but some choose not to.","No, only insects can fly."]',1,'A penguin''s wings are used for swimming, not flying!','Birds: ... Have wings, although not every bird can fly. Examples: penguins... ostriches...','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_028','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'What does it mean when a scientist says human activities are causing ''habitat destruction''?','["Humans are building houses for animals.","Humans are destroying the natural homes (forests, wetlands) where animals live, making it impossible for them to find food or shelter.","Humans are moving animals to better places.","Humans are cleaning the rivers."]',1,'If you cut down the forest, the monkeys have nowhere to live!','Human activities such as habitat destruction, pollution... can harm animal populations. (Synthesis: destroying the habitat destroys the resources needed to live).','2026-11-01 09:14:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_029','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'What defines a ''mollusc''?','["They all have 8 legs.","Many have soft invertebrate bodies, and some grow protective hard shells (like snails or clams).","They are all mammals that swim.","They only live in the desert."]',1,'Think of a squishy snail hiding in a hard shell.','Molluscs: Many have soft bodies, and some have protective shells. Examples: snails, clams...','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_030','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',5,'Is it possible for an animal''s feeding habits to change?','["No, they eat the exact same thing their whole life.","Yes, feeding categories can vary depending on the specific species or the stage of the animal''s life.","Yes, they change every single day randomly.","No, all animals are herbivores."]',1,'A baby frog (tadpole) might eat plants, but an adult frog eats bugs!','Some animals also feed on dead organisms... Feeding categories can vary with species and life stage.','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_031','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Critique the biological classification: ''A bat flies and has wings, therefore it must be a bird.''','["This is biologically accurate based on locomotion.","This represents convergent evolution, not shared taxonomy. Despite having wings for flight (like birds), bats are classified as mammals because they possess hair/fur and nourish their live-born young with milk from mammary glands—defining mammalian traits that birds lack.","This is true because bats lay eggs.","This is false because bats are actually insects."]',1,'Don''t be fooled by the wings! If it has fur and drinks milk, it''s a mammal.','Mammals: Have hair or fur... Feed their young with milk... Examples: ... bats... Birds: ... Have feathers and beaks.','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_032','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Analyze the physiological purpose of ''Respiration'' in animals.','["Respiration is solely the mechanical act of inhaling air.","Respiration is the universal cellular metabolic process. Animals inhale oxygen, which is transported to cells to chemically oxidize organic nutrients (glucose) acquired from food. This exothermic reaction releases ATP (usable energy) required for all biological functions, while producing CO₂ as a waste product.","Respiration is how animals absorb sunlight for energy.","Respiration is the process of digesting solid food in the stomach."]',1,'Breathing is just step one; respiration is the cells burning the food for energy!','Respiration: Cells release usable energy from nutrients through chemical processes. In many organisms, this process uses oxygen... (Topic 1 synthesis). Animals generally: Respire to release usable energy from food.','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_033','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Synthesize why the terms ''Vertebrate'' and ''Invertebrate'' do not represent equal halves of the animal kingdom.','["There are exactly the same number of vertebrates and invertebrates.","The binary classification is highly disproportionate. Vertebrates (possessing a spinal column) represent only a tiny fraction (approx. 5%) of animal life. Invertebrates are vastly more diverse and numerous, making up the great majority of all known animal species on Earth across almost every ecosystem.","Vertebrates make up 95% of all animals.","Invertebrates only exist in the ocean."]',1,'Bugs, worms, and sea creatures outnumber humans and dogs by a massive amount!','Invertebrates make up the great majority of known animal species. They live in almost every habitat...','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_034','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Evaluate the evolutionary significance of the ''Amniotic Egg'' (hard/leathery shell) in Reptiles and Birds compared to Amphibians.','["It makes the egg taste better to predators.","Amphibians lay jelly-like, anamniotic eggs that must remain in water to prevent desiccation (drying out). The evolutionary development of a shelled, amniotic egg in reptiles and birds provided a self-contained, aqueous environment, freeing these vertebrates to reproduce entirely on dry land without returning to water.","It prevents the egg from floating away in the ocean.","It allows the egg to perform photosynthesis."]',1,'A frog has to go back to the pond to lay eggs; a bird can lay an egg in a dry tree!','Amphibians: ... Lay jelly-like eggs in water (graphic). Reptiles: ... Lay leathery eggs on land... Birds: ... Lay hard eggs on land (graphic). (Synthesis: The shell allows land reproduction).','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_035','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Analyze the ecological role of ''Omnivores'' in a food web.','["Omnivores only eat dead leaves.","Omnivores exhibit high trophic flexibility, meaning they can consume both autotrophs (producers/plants) and heterotrophs (consumers/animals). This adaptability allows them to survive in fluctuating environments by switching food sources, and they act as critical energy conduits between multiple trophic levels in an ecosystem.","Omnivores strictly consume apex predators.","Omnivores create their own food using sunlight."]',1,'Because they can eat salads AND steak, they can survive even if one type of food runs out!','Omnivores: Animals that eat both plant and animal matter. (Synthesis of adaptation and survival).','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_036','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Synthesize how the physical ''Adaptations'' of a Desert animal (like a camel) directly respond to abiotic environmental stressors.','["The camel evolved to drink sand.","Deserts present severe abiotic stressors: extreme heat and severe water scarcity. The camel''s adaptations (fat storage in the hump for metabolic water/energy, specialized kidneys to concentrate urine, and thermoregulatory behaviors) are direct evolutionary responses to mitigate dehydration and heat stroke, ensuring survival.","The camel evolved to breathe carbon dioxide.","The camel evolved thick blubber to stay warm in the sand."]',1,'The camel''s body is a biological machine perfectly engineered to survive with almost zero water!','Camels: can conserve water and tolerate hot, dry conditions. Their humps store fat, not water. Adaptation: An inherited feature... that helps an organism survive...','2026-11-01 09:14:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_037','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Critique the statement: ''Animals are independent organisms that do not rely on their habitat once they are fully grown.''','["The statement is true; adult animals can live anywhere.","The statement is ecologically false. An animal''s survival is perpetually tethered to its habitat. A habitat provides the continuous, non-negotiable inputs required for life: specific food sources, water, optimal temperature ranges, and shelter. If the habitat is degraded, even adult populations will rapidly collapse.","The statement is true because animals can perform photosynthesis.","The statement is false because animals only need water, not food."]',1,'An adult monkey is strong, but if you cut down the jungle, it will still starve!','A habitat is the place where an animal lives and finds the resources it needs... Each species has limits, and changes to its habitat can threaten its survival.','2026-11-01 09:14:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_038','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Evaluate the biological limitations of an ''Exoskeleton'' in Arthropods (Insects/Crustaceans).','["An exoskeleton makes the animal immortal.","While an exoskeleton provides excellent defense and structural support, it is composed of rigid chitin and does not grow with the animal. Therefore, the animal must periodically undergo ''ecdysis'' (moulting), shedding the old skeleton. During this moulting period, the animal is extremely soft, vulnerable to predation, and physically unsupported.","An exoskeleton melts in the rain.","An exoskeleton prevents the animal from breathing."]',1,'Imagine wearing a suit of armor; if you grow bigger, you have to take it off to get a new one. While it''s off, you are squishy and defenseless!','Crustaceans: Many have hard external skeletons... (Synthesis of general biological principles of exoskeletons).','2026-11-01 09:14:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_039','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Analyze the classification of a ''Whale'' in the animal kingdom.','["It is a fish because it swims and has fins.","Despite morphological similarities to fish (fins, aquatic habitat) due to convergent evolution, whales are Mammals. They are endothermic (warm-blooded), breathe atmospheric oxygen via lungs (blowholes), have vestigial hair, and most importantly, viviparously birth live young which they nurse with milk from mammary glands.","It is an amphibian because it breathes air.","It is an invertebrate because it has blubber."]',1,'It looks like a giant fish, but it is actually a mammal just like a dog or a human!','Mammals: ... feed their young with milk... breathe using lungs. Examples: ... dolphins [and whales].','2026-11-01 09:14:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_040','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Synthesize the impact of ''Habitat Destruction'' on global Biodiversity.','["Habitat destruction increases biodiversity by forcing animals to evolve faster.","Habitat destruction (deforestation, urbanization) eradicates the specific ecological niches species have adapted to over millennia. Because adaptations limit species to specific conditions, removing the habitat leads to rapid population decline, species extinction, and a catastrophic reduction in global biodiversity and ecosystem stability.","Habitat destruction only affects plants, not animals.","Habitat destruction creates more ocean habitats."]',1,'If you bulldoze a forest, the specialized animals that live there don''t adapt; they just die out.','Human activities such as habitat destruction... can harm animal populations... Protecting habitats helps conserve animal populations and biodiversity.','2026-11-01 09:14:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_animals_global_041','Biology','Animals and Their Habitats','Topic 3: Animals and Their Characteristics','Primary',10,'Critique the observation: ''I saw a worm moving in the dirt, so it must be an insect.''','["This is correct; all small crawling things are insects.","This is taxonomically incorrect. While both are invertebrates, they belong to entirely different phyla. Insects (Arthropods) are defined by having a segmented body (head, thorax, abdomen), an exoskeleton, and exactly six jointed legs. An earthworm (Annelid) has a soft, long, unjointed body with no exoskeleton and zero legs.","This is correct because worms have six legs.","This is incorrect because worms are actually baby snakes."]',1,'A worm has no legs and no hard shell; it is definitely not an insect!','Insects: Have six legs and three main body regions... Worms: Many have long, soft bodies... (Zero legs mentioned).','2026-11-01 09:14:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_001','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is a ''life cycle''?','["Only the time an animal is a baby.","The stages an organism passes through during its life, from beginning to reproduction.","The path an animal walks every day.","How long an animal sleeps."]',1,'It''s the story of a living thing from birth to adult!','Life cycle: the stages an organism passes through, from the beginning of its life until it produces offspring or reaches later stages of life.','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_002','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What does the word ''growth'' mean in biology?','["When an animal changes color.","An increase in size, mass, or the number of cells.","When an animal learns a new trick.","When a plant dies."]',1,'It means getting bigger and taller!','Growth: an increase in size, mass, or the number of cells.','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_003','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What does ''development'' mean in biology?','["Changes in an organism''s form, structure, or abilities as it matures.","Just getting heavier.","Eating a lot of food.","Moving to a new home."]',0,'It means changing shape or learning to do new things (like a baby learning to walk).','Development: changes in an organism''s form, structure, or abilities as it matures.','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_004','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is the first stage in the life cycle of many flowering plants?','["A leaf","A flower","A seed","A mature tree"]',2,'It starts as a tiny package planted in the dirt.','Many flowering plants pass through these stages: Stage 1: Seed','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_005','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is ''germination''?','["When a flower dies.","When a seed begins to grow, usually pushing out a root first.","When a plant makes a fruit.","When a leaf falls off."]',1,'It''s when the seed ''wakes up'' and starts growing!','Germination: With suitable water, oxygen, and temperature, the embryo begins to grow. A root usually emerges first...','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_006','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is the first stage of a butterfly''s life cycle?','["A pupa","A caterpillar","An adult butterfly","An egg"]',3,'It starts as a tiny dot on a leaf.','Stage 1: Egg. An adult butterfly lays eggs...','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_007','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What do we call the larva stage of a butterfly?','["A tadpole","A pupa","A caterpillar","A froglet"]',2,'It looks like a little worm that eats leaves!','Stage 2: Larva (caterpillar).','2026-11-01 09:15:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_008','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What does a frog start its life as?','["A tadpole","An egg","A froglet","A caterpillar"]',1,'Just like birds and butterflies, frogs start here too!','Many frogs lay eggs in water... Eggs: embryos develop inside eggs.','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_009','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is the young, aquatic (water-living) stage of a frog called?','["A pupa","A chick","A tadpole","A juvenile"]',2,'They look like little fish with big heads!','Tadpoles: the young frogs usually live in water and have tails.','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_010','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What hatches out of a bird''s egg?','["A tadpole","A pupa","A chick","A larva"]',2,'It''s a baby bird!','Hatching: the young bird breaks out of the eggshell. Chick: many young birds depend on parents...','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_011','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What is ''offspring''?','["The food an animal eats.","The young produced by living organisms (like babies or seeds).","The home an animal lives in.","The shell of an egg."]',1,'It''s the scientific word for babies!','Offspring: Young produced by living organisms','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_012','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'Which of these is a stage in the human life cycle?','["Pupa","Tadpole","Childhood","Larva"]',2,'You are in this stage right now!','Stage: Childhood. The body grows, and movement, language, and thinking skills develop','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_013','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'Do all humans grow at exactly the same speed (rate)?','["Yes, everyone grows exactly the same.","No, people do not all grow or develop at exactly the same rate.","Yes, unless they are tired.","Yes, until they are teenagers."]',1,'Some people are taller or shorter than others at the same age!','People do not all grow or develop at exactly the same rate.','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_014','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'If a plant does not get enough water, what might happen to its growth?','["It will grow twice as fast.","It will turn into an animal.","It may wilt and not grow normally.","It will grow faster in the dark."]',2,'Water is necessary for a plant to stay healthy!','For example, a plant without enough water may wilt...','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_015','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',1,'What happens during the ''pupa'' (chrysalis) stage of a butterfly?','["The insect flies around eating flowers.","The insect undergoes major changes inside a protective shell to become an adult.","The insect lays eggs.","The insect turns into a tadpole."]',1,'It''s the resting stage where the magic transformation happens!','Stage 3: Pupa (chrysalis). The insect undergoes major changes inside the protective pupal stage as adult structures develop.','2026-11-01 09:15:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_016','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Why is the life cycle of a butterfly considered a ''complete metamorphosis''?','["Because it takes a very long time.","Because its body form changes dramatically and completely as it develops from larva to pupa to adult.","Because it never dies.","Because it looks exactly the same from birth to adulthood."]',1,'A caterpillar looks nothing like a butterfly; it''s a complete change!','Butterflies undergo complete metamorphosis, meaning their body form changes dramatically as they develop.','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_017','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'What three conditions are usually required for a viable seed to begin germinating?','["Light, soil, and fertilizer.","Water, oxygen, and a suitable temperature.","Darkness, cold, and carbon dioxide.","Wind, rain, and rocks."]',1,'A seed needs these three things to ''wake up''!','Germination: With suitable water, oxygen, and temperature, the embryo begins to grow.','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_018','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Why is a tadpole fundamentally different from an adult frog in how it breathes?','["Tadpoles breathe fire, frogs breathe air.","Tadpoles usually live entirely in water and breathe with gills, while adult frogs develop lungs to breathe air.","Tadpoles breathe air, frogs breathe water.","There is no difference; they both breathe the same way."]',1,'Tadpoles are like fish; frogs are land animals!','Tadpoles: the young frogs usually live in water and have tails... Lungs develop as the animal changes. Adult frogs...','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_019','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'In a bird''s life cycle, what is the ''juvenile'' stage?','["When the bird is still inside the egg.","When the bird is a helpless, featherless chick.","When the young bird grows feathers, becomes stronger, and practices adult skills (like flying).","When the bird is old and ready to die."]',2,'It''s like the ''teenager'' phase for a bird!','Juvenile: the young bird grows feathers, becomes stronger, and develops the skills needed for its species.','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_020','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'How does the ''adolescence'' stage differ from ''childhood'' in the human life cycle?','["Adolescence is when a person shrinks.","Adolescence is when puberty brings major physical and hormonal changes, preparing the body for adulthood.","Adolescence only happens to boys.","There is no difference."]',1,'It''s the stage where a child''s body transforms into an adult''s body.','Adolescence: Puberty brings physical and hormonal changes; development continues.','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_021','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Why is the pupa stage of a butterfly so vulnerable (in danger)?','["Because it is very loud and attracts predators.","Because it is inside a protective casing but cannot move or fly away to escape predators.","Because it is highly poisonous.","Because it needs to drink constantly."]',1,'It''s stuck in one spot while it transforms, so it has to hide well!','Stage 3: Pupa (chrysalis). The insect undergoes major changes inside the protective pupal stage... (It is stationary).','2026-11-01 09:15:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_022','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'What happens to a tadpole''s tail as it develops into a froglet?','["The tail grows much longer.","The tail falls off completely.","The tail becomes smaller as it is absorbed into the body to provide energy.","The tail turns into legs."]',2,'The frog basically ''eats'' its own tail for energy while growing legs!','Froglets: the young frogs begin to resemble adults, and the tail becomes smaller as it is absorbed.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_023','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'How does a ''seedling'' obtain energy to grow once it has leaves?','["It continues to use only the stored food from the seed.","It eats bugs from the soil.","Its new leaves begin making sugars through photosynthesis using sunlight.","It drinks sugar water from the rain."]',2,'Once it has leaves, it can cook its own food using the sun!','Stage 3: Seedling... Its leaves begin making sugars through photosynthesis as they develop.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_024','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Do all bird chicks hatch helpless and require extensive care?','["Yes, all baby birds are blind and helpless.","No, some chicks hatch covered in feathers and can move and feed themselves very soon after hatching (like ducks or chickens).","Yes, but they learn to fly in one hour.","No, bird chicks never need their parents."]',1,'Think of a baby duck swimming right away, compared to a baby robin stuck in a nest!','Not all birds care for their young in the same way. Some chicks hatch helpless and require extensive care, while others can move and feed themselves soon after hatching.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_025','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'If two identical seeds are planted, why might one grow into a large plant and the other into a small, weak plant?','["Because plants grow randomly.","Because environmental conditions (like water, light, temperature, or nutrients) might be different for each seed.","Because one seed decided it didn''t want to grow.","Because one seed was older."]',1,'Even if they are twins, the one that gets more water and sunlight will grow better!','Growth and development depend on both inherited characteristics and environmental conditions. Nutrition... Water... Temperature... Light...','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_026','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'In the simple seed germination experiment, what is the ''variable'' (the one thing being changed)?','["The type of seed.","The temperature of the room.","The amount of water (one damp towel, one dry towel).","The size of the container."]',2,'A fair test only changes ONE thing so you know exactly what caused the result!','Keep one paper towel damp... Keep the other paper towel dry. Fair-test rule: Keep seed type, number of seeds, container, temperature, and location as similar as possible. Change only the water condition.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_027','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'How does ''genetics'' (inherited characteristics) affect a human''s growth?','["It decides what color shirt they will wear.","Genetics from parents influence factors like how tall a person might grow or how their body develops, regardless of perfect nutrition.","Genetics has no effect on human growth.","Genetics means humans only grow if they eat vegetables."]',1,'If your parents are very tall, genetics means you will probably be tall too!','People do not all grow or develop at exactly the same rate. Genetics, nutrition, health, environment, and other factors can influence development.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_028','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'What defines the ''mature plant'' stage in a flowering plant''s life cycle?','["The plant dies.","The plant begins to germinate.","The plant is fully grown and capable of producing flowers, which can then be pollinated to form new seeds.","The plant loses all its leaves."]',2,'It is the ''adult'' stage where it is ready to make babies (seeds)!','Stage 4: Mature plant. The plant grows and may produce flowers. After pollination and fertilisation, seeds can form.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_029','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Why is ''dormancy'' a helpful feature for a seed?','["It allows the seed to explode.","It allows the seed to survive unfavorable conditions (like winter freezing or drought) by pausing its life processes until it is safe to grow.","It makes the seed taste bad to birds.","It allows the seed to grow without any water."]',1,'It''s an evolutionary trick to make sure the baby plant doesn''t wake up in the middle of winter!','Dormancy: A period of reduced activity that helps an organism or seed survive unfavourable conditions.','2026-11-01 09:15:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_030','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',5,'Is a ''caterpillar'' a different animal than a ''butterfly''?','["Yes, they are two completely different species.","No, they are the exact same animal, just at different stages of its life cycle (development).","Yes, caterpillars turn into moths, not butterflies.","No, butterflies lay caterpillars, not eggs."]',1,'It''s the same bug; it just changed its clothes and shape!','The caterpillar and adult butterfly look very different... This transformation is called metamorphosis. (It is the same organism).','2026-11-01 09:15:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_031','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Critique the assertion that ''Development is simply a rapid phase of Growth.''','["The assertion is scientifically accurate.","The assertion conflates two distinct biological concepts. ''Growth'' is strictly quantitative (an increase in mass or cell division). ''Development'' is qualitative; it involves cellular differentiation, morphogenesis, and the acquisition of new physiological functions (like a tadpole growing legs or a human entering puberty), which can occur independently of size increases.","The assertion is true because growing always means changing shape.","The assertion is false because development means shrinking."]',1,'You can grow a giant pile of bricks (growth), but building them into a house requires organization and change (development)!','Growth: an increase in size, mass, or the number of cells. Development: changes in an organism''s form, structure, or abilities as it matures. (Synthesis: Growth is size, Development is complexity).','2026-11-01 09:15:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_032','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Analyze the ecological advantage of ''Complete Metamorphosis'' in butterflies regarding resource competition.','["It ensures the butterfly and caterpillar fight for the exact same food.","Complete metamorphosis drastically reduces intraspecific competition. Because the larva (caterpillar) and the adult (butterfly) possess radically different anatomies, they exploit entirely different ecological niches and food sources (leaves vs. nectar). This ensures the adults and offspring do not compete for the same limited resources.","It makes the butterfly more visible to predators.","It allows the butterfly to live underwater."]',1,'If the babies ate the exact same food as the parents, they might starve each other! Metamorphosis prevents this.','The caterpillar and adult butterfly look very different and often eat different foods. (Synthesis: Different foods mean they don''t compete with each other).','2026-11-01 09:15:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_033','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Synthesize how ''Environmental Triggers'' end Seed Dormancy.','["Seeds just decide to wake up randomly.","Dormancy is a physiological block. Seeds require specific, sustained abiotic triggers—such as a prolonged period of cold (stratification) followed by warming, or the abrasive action of water/digestion (scarification)—to chemically degrade growth inhibitors (like abscisic acid) and activate growth hormones (like gibberellins), initiating germination.","Seeds require a loud noise to wake up.","Seeds must be planted by a human to break dormancy."]',1,'The seed has a chemical ''lock'' on it; it takes the perfect combination of water and temperature to ''pick'' the lock and start growing!','A viable seed can remain dormant until conditions are suitable for germination. With suitable water, oxygen, and temperature, the embryo begins to grow. (Synthesis of what breaks dormancy).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_034','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Evaluate the physiological transformation required as a tadpole transitions into an adult frog.','["The tadpole simply grows larger.","The metamorphosis requires a total systemic overhaul. The organism must switch from aquatic respiration (gills) to terrestrial respiration (lungs/skin). It must absorb its tail via apoptosis for energy, develop a completely new appendicular skeleton (legs), and physically reconstruct its digestive tract to transition from a herbivorous/omnivorous diet to an obligate carnivorous diet.","The tadpole only changes its skin color.","The tadpole must learn how to fly."]',1,'It''s not just growing legs; it''s completely rebuilding its lungs and stomach while it''s still alive!','Tadpoles with legs: hind legs develop... Lungs develop as the animal changes. Froglets: ... the tail becomes smaller as it is absorbed. (Synthesis of the massive internal changes required).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_035','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Analyze the significance of the ''Egg'' stage across various animal life cycles (butterflies, frogs, birds).','["Eggs are only used for food.","The egg is the critical stage of embryonic development. Regardless of the species, the egg provides a localized, protected micro-environment (whether a hard shell for birds, jelly for amphibians, or tiny casings for insects) containing the genetic blueprint (zygote) and the initial nutritional reserves (yolk) required to sustain cellular division before the organism can feed itself.","Eggs prevent the animal from growing.","Eggs are only laid by plants, not animals."]',1,'Every egg, whether from a bird or a bug, is a tiny self-contained life-support pod for the baby!','Eggs: embryos develop inside eggs. (Applies to frogs, birds, and butterflies). (Synthesis: The egg is a protective nutrient capsule for the embryo).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_036','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Synthesize how ''Nutrition'' directly impacts the ''Development'' phase of the human life cycle.','["Nutrition only affects humans when they are adults.","Nutrition provides the essential biochemical building blocks for development. Severe protein or caloric deficiency during critical developmental windows (like childhood or adolescence) doesn''t just halt growth (stunting); it can permanently impair neurological development, delay puberty, and cause irreversible structural deficits in bone and organ formation.","Nutrition turns human DNA into plant DNA.","Nutrition has no effect if the genetics are good."]',1,'If a growing body doesn''t get the right building materials (vitamins and proteins), it can''t build the brain and bones properly!','Growth and development depend on both inherited characteristics and environmental conditions. Nutrition: organisms need suitable nutrients or food... a young animal without adequate nutrition may not grow normally.','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_037','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Critique the biological accuracy of using the term ''Adult'' across different species.','["The term ''Adult'' means the exact same thing for a plant, a frog, and a human.","While ''adult'' generally implies biological maturity, the criteria vary wildly. In biology, ''adulthood'' is strictly defined by reproductive viability (the ability to produce gametes and offspring). A ''mature'' plant producing flowers, a butterfly emerging from a pupa, and a human post-puberty are all ''adults'' because they have reached this reproductive threshold, despite vastly different lifespans and anatomies.","The term ''Adult'' only applies to animals that can walk on two legs.","The term ''Adult'' means the organism is about to die."]',1,'To a biologist, ''adult'' just means ''ready to make babies'', whether you are a tree, a bug, or a bird!','Adult stage: Reproduction, producing offspring... Mature plant: The plant grows and may produce flowers... Adult butterfly: ...may reproduce... Adult: the bird reaches reproductive maturity... (Synthesis: Adulthood equals reproductive ability).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_038','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Evaluate the experimental design: A student plants a seed in dry soil, places it in a dark closet, and places it in a freezer. The seed does not grow. What is the conclusion?','["The seed was definitely dead.","The experimental design is disastrously flawed. The student applied three severe abiotic stressors (no water, no light, freezing temperature) simultaneously. It is impossible to isolate the independent variable. The seed failed to germinate, but the data cannot determine which specific condition (or combination) inhibited the biological processes.","The experiment proves that seeds don''t need water.","The experiment proves that seeds only grow in space."]',1,'If you change three rules at the same time and the seed dies, you have no idea which rule actually killed it!','Fair-test rule: Keep seed type, number of seeds, container, temperature, and location as similar as possible. Change only the water condition. (Synthesis: Changing multiple variables ruins the experiment).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_039','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Analyze the role of ''Cell Division'' in the process of Growth.','["Cell division makes the cells smaller so the organism shrinks.","Growth in multicellular organisms is not primarily achieved by individual cells inflating like balloons. Instead, it is driven by mitosis—a continuous cycle of cell division where one parent cell replicates its DNA and divides into two identical daughter cells. This exponential increase in the *number* of cells is the fundamental biological mechanism of physical growth.","Cell division turns plant cells into animal cells.","Cell division only happens in dead organisms."]',1,'You don''t grow because your cells get giant; you grow because your body makes millions of brand new cells!','Growth: an increase in size, mass, or the number of cells. (Synthesis: linking growth directly to cell division).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_040','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Synthesize why some bird species have precocial chicks (ready to run/swim) while others have altricial chicks (helpless and blind).','["Because some birds are lazier than others.","This represents divergent evolutionary strategies. Ground-nesting birds (like ducks) often have precocial chicks; they must be developed enough at hatching to immediately flee predators. Tree-nesting birds (like robins) have altricial chicks; they are born underdeveloped but are protected in an inaccessible nest, allowing the parents to invest energy into rapid postnatal feeding and development.","Because precocial chicks are actually mammals.","Because altricial chicks hatch from square eggs."]',1,'If your nest is on the ground, your babies better be able to run immediately! If your nest is high in a tree, they can afford to be helpless for a while.','Not all birds care for their young in the same way. Some chicks hatch helpless and require extensive care, while others can move and feed themselves soon after hatching. (Synthesis: Form fits habitat).','2026-11-01 09:15:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_life_global_041','Biology','Life Cycles and Growth','Topic 4: Life Cycles and Growth','Primary',10,'Critique the idea that ''All plants follow the Seed -> Seedling -> Plant -> Flower cycle.''','["The idea is an absolute law of biology.","The idea is a massive overgeneralization limited only to Angiosperms (flowering plants) and Gymnosperms. A vast portion of the plant kingdom consists of non-seed-bearing plants (like Bryophytes/mosses and Pteridophytes/ferns). These primitive plants do not produce flowers or seeds; their life cycles rely on alternating generations and the dispersal of microscopic, single-celled spores.","The idea is true because all plants have colorful flowers.","The idea is true because spores are just tiny seeds."]',1,'Moss on a rock doesn''t have flowers or seeds; it uses a completely different, ancient way to reproduce!','Not all plants follow the same pattern... Remember: Not all plants produce flowers and seeds. Mosses and ferns, for example, reproduce using spores.','2026-11-01 09:15:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_001','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What is a ''habitat''?','["The food an animal eats.","The natural place where an organism lives and obtains the resources it needs.","A type of animal.","The weather outside."]',1,'It is the animal''s home in nature!','A habitat is the natural place where an organism lives and obtains the resources it needs.','2026-11-01 09:15:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_002','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'Which of these is a major type of habitat?','["A car","A house","A forest","A school"]',2,'It''s a large natural area filled with trees and wildlife.','Habitats include forests, grasslands, deserts, freshwater environments, oceans, and polar regions.','2026-11-01 09:15:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_003','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What does a habitat provide for an animal?','["Only water.","Food, water, shelter, and space to live.","Only shelter.","Nothing."]',1,'It gives the animal everything it needs to survive.','Habitats provide living things with different combinations of: Food... Water... Shelter... Space...','2026-11-01 09:15:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_004','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What kind of habitat has very little rain and extreme temperatures?','["A rainforest","An ocean","A desert","A wetland"]',2,'Think of sand and cacti!','Deserts receive very little precipitation compared with many other habitats. Some are hot, while others are cold.','2026-11-01 09:15:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_005','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What kind of habitat is filled with salty water?','["A lake","A river","A marine habitat (ocean or sea)","A forest"]',2,'Whales and sharks live here!','Marine habitats: Oceans and seas contain saltwater habitats...','2026-11-01 09:15:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_006','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What is an ''adaptation'' in biology?','["When an animal gets lost.","A disease an animal catches.","An inherited feature or behaviour that helps an organism survive in its environment.","When an animal sleeps."]',2,'It''s a special trick or body part that helps the animal stay alive!','An adaptation is an inherited characteristic that helps an organism survive and reproduce in a particular environment...','2026-11-01 09:15:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_007','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What adaptation helps a polar bear survive in a freezing polar habitat?','["Gills for breathing underwater.","Thick fur and a layer of body fat to stay warm.","Big ears to cool down.","Webbed feet for flying."]',1,'It''s like wearing a heavy winter coat all year!','Polar bears: have thick fur and a layer of body fat that help insulate them in cold environments.','2026-11-01 09:15:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_008','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What adaptation helps a duck swim in the water?','["Thick fur","Sharp claws","Webbed feet","Long ears"]',2,'Their feet act like flippers!','Ducks: have webbed feet that help them paddle.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_009','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What does a camel store in its hump to help it survive in the desert?','["Water","Sand","Air","Fat"]',3,'It''s a storage tank for energy!','A camel can conserve water and tolerate periods with limited drinking water. Its hump stores fat, not water.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_010','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What is ''camouflage''?','["When an animal moves to a new home.","When an organism blends into its surroundings, making it harder to see.","When an animal goes to sleep for the winter.","When an animal runs very fast."]',1,'It''s like wearing an invisibility cloak made of nature!','Camouflage helps an organism blend into its surroundings, making it harder for predators or prey to notice it.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_011','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What is it called when birds fly to a warmer place for the winter?','["Hibernation","Camouflage","Migration","Pollination"]',2,'They travel a long way to find a better home for the season!','Migration: The regular movement of animals from one region to another, often linked to food availability, breeding, or seasonal conditions.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_012','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What is ''hibernation''?','["When an animal travels to a new country.","When an animal eats rocks.","A long period of deep sleep or reduced activity during cold winter months to save energy.","When an animal changes color."]',2,'Like a bear sleeping through the winter!','Hibernation: A prolonged period of reduced activity and metabolism in some animals, helping them survive periods when conditions are unfavourable.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_013','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'Do all animals hibernate in the winter?','["Yes, every single animal sleeps through winter.","No, different species have different behaviors; some migrate, and some stay active.","Yes, but only in the desert.","Yes, but they wake up every day to eat."]',1,'Some animals, like wolves, stay awake and hunt all winter!','Different species follow different seasonal patterns. Not every animal in a cold region hibernates or migrates.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_014','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'What can happen to animals if humans destroy their habitat?','["They will easily find a new home in a city.","They may not be able to find food or shelter, causing their populations to decline.","They will instantly adapt to live in the sky.","Nothing, animals don''t need habitats."]',1,'If you cut down the forest, the animals have nowhere to live!','Human activities such as habitat destruction... can harm animal populations...','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_015','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',1,'How can humans help protect animal habitats?','["By cutting down all the trees.","By polluting rivers with rubbish.","By protecting natural areas, reducing pollution, and not disturbing wild animals.","By paving over wetlands to build parking lots."]',2,'We must keep their homes safe and clean!','People can help by protecting natural areas, reducing pollution, following wildlife-protection rules, and avoiding disturbance of wild animals.','2026-11-01 09:15:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_016','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'Why is ''migration'' considered a ''behavioural'' adaptation?','["Because it is a physical body part.","Because it is an action the animal takes to survive (moving to find food or warmth), rather than a physical part of its body.","Because it happens inside the animal''s stomach.","Because it only happens to birds."]',1,'It''s something the animal DOES, not a body part it HAS!','Behavioural adaptations: Actions that help an organism survive or reproduce. Examples: seasonal migration...','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_017','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'How does a tiger''s striped fur act as a ''structural adaptation''?','["It helps the tiger fly.","It keeps the tiger cool in the sun.","It is a physical feature that provides camouflage, helping the tiger blend into tall grass and shadows so it can sneak up on prey.","It makes the tiger look friendly."]',2,'The stripes make it hard to see the tiger in the jungle!','Structural adaptations: Physical features of an organism''s body... A tiger''s stripes can help break up its outline among vegetation and shadows (camouflage).','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_018','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'Why do some animals, like the Fennec fox, have incredibly large ears?','["So they can hear fish underwater.","As a physiological/structural adaptation to help release excess body heat in a hot desert environment.","So they can fly like a bird.","So they can store water in them."]',1,'Big ears act like radiators, letting the heat escape from their body into the cool night air!','A fennec fox has large ears that help release body heat.','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_019','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'What is ''mimicry'' and how does it help an animal survive?','["It is when an animal goes to sleep.","It is when an animal changes its diet.","It occurs when a harmless organism looks exactly like a dangerous or poisonous organism, tricking predators into leaving it alone.","It is when an animal builds a nest."]',2,'If you look exactly like a poisonous wasp, birds will be too scared to eat you!','Mimicry occurs when an organism resembles another organism in a way that can provide an advantage. For example, some harmless insects resemble stinging insects...','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_020','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'How is ''hibernation'' different from normal sleeping?','["Hibernation only lasts for one hour.","Hibernation involves a prolonged, massive drop in metabolism and body temperature to survive months without food, unlike normal daily sleep.","Hibernation only happens in the summer.","There is no difference."]',1,'It''s not just a nap; their heart rate slows down to almost nothing to save energy!','Hibernation: A prolonged period of reduced activity and metabolism in some animals, helping them survive periods when conditions are unfavourable.','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_021','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'If a desert animal is ''nocturnal'' (active at night), what type of adaptation is this?','["Structural","Physiological","Behavioural","Metabolic"]',2,'It''s a choice they make (a behavior) to avoid the hot daytime sun!','Some desert animals are active at night, when temperatures are cooler... Behavioural adaptations: Actions that help an organism survive...','2026-11-01 09:15:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_022','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'Why is an animal''s survival threatened if its habitat suddenly changes?','["Because animals can instantly change their adaptations to fit any new habitat.","Because adaptations develop over many generations; an individual animal cannot just instantly ''adapt'' a new body part to survive a sudden change like a flood or deforestation.","Because animals do not need habitats.","Because animals are immune to climate change."]',1,'If a polar bear''s ice melts, it can''t just instantly grow gills and become a fish! It will struggle to survive.','Adaptations develop in populations over generations... changes to its habitat can threaten its survival.','2026-11-01 09:15:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_023','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'In a forest habitat, what ''living'' components does a bird depend on?','["Only sunlight and air.","Only water and rocks.","Trees for shelter (nesting) and insects or seeds for food.","Only dirt."]',2,'Living components are the other biological organisms in the habitat!','Component: Living. Examples: Plants, animals, fungi... Importance: Provide food, shelter... (A bird may eat insects...)','2026-11-01 09:15:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_024','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'How do fish breathe in a freshwater or marine habitat?','["They hold their breath underwater.","They come to the surface to breathe air with lungs.","They use gills to extract dissolved oxygen directly from the water.","They don''t need oxygen."]',2,'Gills act like underwater lungs!','Gills allow many aquatic animals to obtain oxygen dissolved in water.','2026-11-01 09:15:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_025','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'Why are dolphins and whales classified differently than fish, even though they share the same marine habitat?','["Because they have scales.","Because dolphins and whales are mammals; they must swim to the surface to breathe air through lungs, unlike fish which use gills.","Because dolphins are birds.","Because fish are mammals."]',1,'They may look like fish, but they breathe air just like we do!','Dolphins and whales are mammals, not fish. They breathe air through lungs and must surface to breathe.','2026-11-01 09:15:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_026','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'What is ''aestivation''?','["When an animal travels to the North Pole.","A period of reduced activity (similar to hibernation) used by some animals to survive extremely hot or dry conditions.","When an animal learns to swim.","When an animal changes its color to white."]',1,'It''s like hibernation, but for surviving the summer heat instead of the winter cold!','Some animals use aestivation, a period of reduced activity during hot or dry conditions.','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_027','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'Why is the phrase ''a habitat is a forest or ocean'' slightly inaccurate?','["Because forests are not habitats.","Because a habitat doesn''t have to be massive; it is simply the specific place an organism lives, so a single rotting log or a small puddle can be a complete habitat for insects or frogs.","Because oceans are too big to be habitats.","Because habitats are only found in space."]',1,'For a tiny bug, a single leaf might be its entire world (habitat)!','A habitat is not necessarily a whole forest or ocean. A rotting log, a patch of soil, or a small pool of water can also be a habitat for certain organisms.','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_028','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'How does the ''interdependence'' of a bee and a flower work in a habitat?','["The bee destroys the flower.","The flower provides food (nectar) for the bee, and the bee spreads pollen for the flower, helping the plant reproduce; they rely on each other.","The flower eats the bee.","The bee turns the flower into a leaf."]',1,'It''s a biological team-up! The bee gets lunch, and the flower gets to make seeds.','Organisms also depend on one another. For example, a flowering plant may provide nectar for a bee. The bee may transfer pollen between flowers, helping the plant reproduce.','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_029','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'What might happen to a population of animals if a highway is built directly through the middle of their forest habitat?','["The animals will learn to drive.","The population might suffer because the highway physically separates them, restricting access to food, water, and making it hard to find mates.","The population will instantly double.","Nothing will happen."]',1,'If the animals can''t safely cross the road, half the forest is basically lost to them!','Habitat changes may: ... Separate populations so that animals cannot easily find mates.','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_030','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',5,'How is ''camouflage'' different from ''mimicry''?','["They are exactly the same thing.","Camouflage is blending into the background (like a green frog on a green leaf); Mimicry is looking like a completely different, specific organism (like a harmless bug looking like a dangerous wasp).","Camouflage only works at night.","Mimicry means the animal is invisible."]',1,'Camouflage makes you ''disappear'' into the background. Mimicry makes you look like a scary monster!','Camouflage helps an organism blend into its surroundings... Mimicry occurs when an organism resembles another organism... Camouflage and mimicry are different strategies...','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_031','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Critique the assertion that ''An individual animal can develop a structural adaptation if its environment suddenly changes.''','["The assertion is true; animals can instantly change their bodies to survive.","The assertion is a Lamarckian fallacy. Structural adaptations are inherited genetic traits that arise through random mutation and natural selection over many generations within a population. An individual organism cannot deliberately alter its genetic morphology.","The assertion is true if the animal tries very hard.","The assertion is false because adaptations only happen to plants."]',1,'If you move to Antarctica, you can''t just ''grow'' polar bear fur; adaptations take thousands of years!','Adaptations develop in populations over generations; an individual animal does not develop a new inherited adaptation simply because it needs one.','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_032','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Analyze the specific ''Physiological Adaptations'' required for a marine mammal (like a whale) to survive in the ocean.','["They must grow gills to breathe underwater.","Marine mammals face severe osmotic and thermal challenges. Physiologically, they require a thick layer of blubber for thermal insulation, specialized renal systems to excrete excess salt, and highly efficient myoglobin to store oxygen during prolonged dives.","They must learn how to photosynthesize.","They must turn their lungs into solid rocks."]',1,'They have to hold their breath for a long time and stay warm in freezing water, all while surrounded by salt!','Physiological adaptations: Internal body processes that help an organism function... A layer of body fat helps insulate some marine mammals...','2026-11-01 09:15:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_033','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Synthesize the concept of ''Interdependence'' within a complex ecosystem facing Habitat Destruction.','["If one species dies, the other species will just eat rocks instead.","Ecosystems are webs of interdependent relationships. If habitat destruction eradicates a primary producer or a keystone pollinator, the impact cascades across trophic levels. Herbivores starve, subsequent predators decline, and the entire ecological structure can collapse.","Interdependence means animals don''t need each other.","Habitat destruction only affects the specific animal that loses its home."]',1,'If the bees die, the flowers die. If the flowers die, the deer starve. If the deer starve, the wolves starve!','Organisms also depend on one another... These relationships help ecosystems function. Habitat changes may... Reduce biodiversity.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_034','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Evaluate the evolutionary trade-off of a highly specialized adaptation, such as a diet restricted to a single plant species.','["It guarantees the animal will never go extinct.","Hyper-specialization maximizes an organism''s efficiency in a stable environment. However, it creates severe evolutionary vulnerability. If environmental changes eliminate that single plant species, the highly adapted organism lacks the plasticity to switch food sources, leading to extinction.","It means the animal can easily eat anything else if it wants to.","It makes the animal immune to all diseases."]',1,'If a koala ONLY eats eucalyptus, and all the eucalyptus burns, the koala is doomed!','Adaptations do not mean an animal can survive everywhere. Each species has limits, and changes to its habitat can threaten its survival.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_035','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Analyze the thermodynamic challenges of a ''Desert'' habitat and the resulting behavioral adaptations of its fauna.','["Desert animals survive by drinking massive amounts of water every day.","Deserts present extreme diurnal thermal fluctuations and severe water scarcity. To mitigate hyperthermia and dehydration, many desert animals exhibit the behavioral adaptation of nocturnality—remaining in insulated burrows during peak insolation and foraging only when temperatures drop.","Desert animals survive by photosynthesizing.","Desert animals survive by permanently freezing themselves."]',1,'Why walk in the scorching sun when you can hide in a cool hole and come out to eat at night?','Desert animals face challenges such as limited water, intense sunlight... Some desert animals are active at night, when temperatures are cooler.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_036','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Synthesize how the ''Camouflage'' of a predator differs functionally from the camouflage of prey.','["They are functionally identical; both use it to avoid being eaten.","While structurally similar, their ecological functions are opposite. The prey utilizes defensive camouflage to avoid visual detection by predators, increasing survival. The predator utilizes offensive camouflage to disrupt its silhouette, allowing it to ambush prey with minimal detection.","The tiger uses camouflage to stay warm, the insect uses it to stay cool.","Predators do not use camouflage."]',1,'The bug hides so it doesn''t get eaten; the tiger hides so it can sneak up and EAT you!','Camouflage helps an organism blend into its surroundings, making it harder for predators or prey to notice it.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_037','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Critique the classification of ''Hibernation'' simply as ''a long sleep''.','["The classification is perfectly accurate biologically.","The classification is a severe physiological understatement. Hibernation is a complex, regulated state of torpor. The animal actively suppresses its metabolic rate to a fraction of normal, drastically lowering its core body temperature, heart rate, and respiration to conserve energy.","The classification is wrong because the animal is actually dead.","The classification is wrong because the animal is actually running."]',1,'If you just ''sleep'' for three months without eating, you die. A hibernating animal actually slows its internal engine down!','Hibernation: A prolonged period of reduced activity and metabolism in some animals, helping them survive periods when conditions are unfavourable.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_038','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Evaluate the biological impact of introducing an ''Invasive Species'' into an established habitat.','["Invasive species always improve the habitat by adding new biodiversity.","Invasive species act as severe biological pollutants. Lacking natural predators in the new habitat, they reproduce exponentially. They outcompete native species for limited resources, disrupt established food webs, and can drive endemic species to rapid extinction.","Invasive species only affect plants, never animals.","Invasive species instantly die in a new habitat."]',1,'If you put a fast-breeding, hungry animal in a new forest with no natural enemies, it will eat all the food!','Human activities can also change them through... the introduction of invasive species. Habitat changes may: Reduce access to food... Reduce biodiversity.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_039','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Analyze the structural adaptations required for ''Flight'' in birds.','["Birds only need feathers to fly; weight does not matter.","Avian flight requires radical structural adaptations to maximize the power-to-weight ratio. This includes specialized asymmetric contour feathers for aerodynamic lift, massively enlarged pectoral muscles, and a pneumatized (hollow) skeletal system to drastically reduce overall body mass.","Birds fly using magic, not structural adaptations.","Birds fly by holding their breath."]',1,'You can''t just strap wings on a heavy animal; a bird''s entire body is engineered to be as light and strong as a kite!','Flying: Birds, bats, and many insects fly using different wing structures.','2026-11-01 09:16:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_040','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Synthesize the environmental drivers behind ''Migration''.','["Animals migrate purely for exercise.","Migration is an energy-intensive behavioral adaptation driven by cyclical environmental instability. As seasonal changes degrade local resources (temperature drop, food scarcity), animals must navigate to geographically distinct habitats that temporarily offer optimal conditions for foraging or breeding.","Animals migrate because they get bored of their habitat.","Animals only migrate to escape human cities."]',1,'Why stay and freeze to death when you have wings to fly to a warm beach with plenty of food?','Migration: The regular movement of animals from one region to another, often linked to food availability, breeding, or seasonal conditions.','2026-11-01 09:16:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_041','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Critique the student statement: ''Because a dolphin lives in the ocean, its closest relatives are sharks and tuna.''','["The statement is correct; all ocean animals are closely related.","The statement represents a profound misunderstanding of taxonomy versus convergent evolution. Dolphins and sharks share structural similarities (streamlined bodies, fins) due to adapting to the same fluid dynamic pressures of the marine habitat. However, taxonomically, dolphins are mammals.","The statement is true because dolphins lay eggs like fish.","The statement is true because dolphins breathe through gills."]',1,'Just because a submarine and a shark are both in the water doesn''t mean they are related! A dolphin is a mammal.','Dolphins and whales are mammals, not fish. They breathe air through lungs and must surface to breathe.','2026-11-01 09:16:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_042','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Analyze the adaptation of ''Aestivation'' compared to ''Hibernation''.','["They are the exact same thing.","Both are states of dormancy characterized by depressed metabolism to survive extreme conditions. However, hibernation is an adaptation to survive extreme cold and winter food scarcity, while aestivation is an adaptation to survive extreme heat and drought (desiccation) during summer months.","Aestivation is for plants, hibernation is for animals.","Aestivation means migrating to the desert."]',1,'Hibernation is for freezing winters; aestivation is for boiling summers!','Hibernation: A prolonged period of reduced activity... Aestivation: Reduced activity during hot or dry conditions in some organisms.','2026-11-01 09:16:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_043','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Evaluate the role of ''Microorganisms'' as a living component in a forest habitat.','["They serve absolutely no purpose.","Microorganisms (bacteria and fungi) are foundational to the habitat''s biogeochemical cycles. As decomposers, they break down dead organic matter, recycling essential nutrients (like nitrogen and carbon) back into the soil, which autotrophs (plants) require for survival.","They only exist to make animals sick.","They block out the sun from reaching the forest floor."]',1,'Without invisible bacteria eating dead leaves, the forest would run out of nutrients and choke on its own waste!','Component: Living. Examples: Plants, animals, fungi, microorganisms. Importance: Provide food, shelter, decomposition, and other ecological functions.','2026-11-01 09:16:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_044','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Synthesize how ''Camouflage'' in a snowshoe hare (changing coat color seasonally) is triggered.','["The hare paints itself.","The seasonal molting and color change (brown in summer, white in winter) is a physiological adaptation triggered by environmental cues, specifically photoperiod (day length) and temperature. As days shorten, hormonal shifts cause the animal to shed brown fur and grow white, unpigmented fur.","The hare rolls in the snow until it turns white.","The hare is born white and stays white forever."]',1,'The animal''s body automatically reacts to the changing seasons to grow a new, perfectly colored coat!','A snowshoe hare can have a pale winter coat in snowy regions.','2026-11-01 09:16:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_habitats_global_045','Biology','Habitats and Adaptations','Topic 5: Habitats and Adaptations','Primary',10,'Critique the concept of a ''Habitat'' being solely defined by geographical location.','["Geography is the only thing that matters for a habitat.","Defining a habitat purely by geography is ecologically insufficient. A habitat is defined by the specific combination of biotic and abiotic factors (temperature, humidity, food availability, shelter) that a specific organism requires. A single geographical location (like a tree) can contain dozens of distinct microhabitats.","Habitats are defined solely by the animals that live there.","Habitats are only defined by the weather."]',1,'A bird''s habitat is the top of the tree, but a worm''s habitat is the dirt under the exact same tree!','A habitat is the natural place where an organism lives and obtains the resources it needs. A habitat is not necessarily a whole forest or ocean. A rotting log... can also be a habitat...','2026-11-01 09:16:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_001','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What is the basic unit of life in the human body?','["An organ","A cell","A bone","A tissue"]',1,'It is the tiny building block that makes up everything else!','Cell: The basic unit of life. For example, a muscle cell helps a muscle work.','2026-11-01 09:16:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_002','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'When a group of similar cells work together, what do they form?','["A skeleton","A brain","A tissue","A stomach"]',2,'Cells join together to make this.','Tissue: A group of similar cells working together to perform a function.','2026-11-01 09:16:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_003','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What system in your body is made mostly of bones?','["The nervous system","The skeletal system","The digestive system","The circulatory system"]',1,'It is your body''s hard framework.','The skeletal system is made mainly of bones, together with cartilage and joints.','2026-11-01 09:16:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_004','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'Which bones protect your brain?','["The rib cage","The pelvis","The skull","The spine"]',2,'It is the hard bone inside your head!','The skull protects the brain.','2026-11-01 09:16:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_005','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What do your muscles do?','["They help the body move by pulling on bones.","They digest food in your mouth.","They make blood cells.","They store memories."]',0,'You use them to run, jump, and smile!','Muscles help the body move. Many muscles attach to bones and pull on them when they contract.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_006','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What does the digestive system do?','["It pumps blood around the body.","It helps you breathe in oxygen.","It breaks food into smaller substances the body can absorb and use.","It helps you think."]',2,'It''s what happens to your lunch after you swallow it!','The digestive system breaks food into smaller substances that the body can absorb and use for energy, growth, and repair.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_007','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'Where does food go right after you swallow it?','["Into the lungs","Down a tube called the oesophagus towards the stomach","Into the heart","Into the brain"]',1,'It is the food pipe in your throat.','Oesophagus: A muscular tube carries swallowed food towards the stomach.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_008','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What does your respiratory system help you do?','["Exchange gases (breathe in oxygen and breathe out carbon dioxide).","Digest your food.","Pump blood to your toes.","Move your arms."]',0,'You use it every time you take a breath!','The respiratory system helps the body exchange gases with the environment.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_009','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What is the main organ of the circulatory system that pumps blood?','["The liver","The brain","The heart","The lungs"]',2,'It beats inside your chest all day and night!','Heart: A muscular pump that keeps blood moving.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_010','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What part of your nervous system processes information and supports thinking?','["The brain","The stomach","The kidneys","The liver"]',0,'It''s the boss of your body!','Brain: Processes information, supports thinking and memory, and coordinates many activities.','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_011','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'Which organ filters your blood and produces urine (pee)?','["The lungs","The heart","The stomach","The kidneys"]',3,'You have two of these bean-shaped organs in your lower back.','Kidneys: Filter the blood and produce urine','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_012','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What is the body''s largest organ, which protects you and helps regulate temperature?','["The heart","The skin","The brain","The large intestine"]',1,'It covers your entire body outside!','The skin is the body''s largest organ. It forms a protective barrier, helps regulate body temperature...','2026-11-01 09:16:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_013','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'Which sense uses your ears to gather information?','["Sight","Taste","Hearing","Smell"]',2,'You use this sense to listen to music.','Sense: Hearing. Organ mainly involved: Ears. Information detected: Sound','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_014','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'What happens to your heart when you run or exercise?','["It stops beating.","It usually beats faster to transport more oxygen and nutrients to working muscles.","It moves to a different part of your body.","It beats much slower."]',1,'You can feel it thumping in your chest when you run fast!','The heart usually beats faster to transport more oxygen and nutrients to working muscles.','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_015','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',1,'Which of these is a healthy habit?','["Eating only candy.","Sleeping for only 2 hours a night.","Brushing your teeth with fluoride toothpaste and washing your hands with soap.","Never drinking water."]',2,'It keeps the germs away!','Practise hygiene: Wash hands with soap, brush teeth with fluoride toothpaste...','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_016','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'How is an ''organ'' different from a ''tissue''?','["They are the exact same thing.","A tissue is made of organs.","An organ is a larger structure made of several different tissues working together (like the heart).","An organ is only found in plants."]',2,'Tissues are the materials; organs are the finished product (like the heart or lungs).','Organ: A structure made of different tissues working together, such as the heart.','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_017','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'Besides supporting the body, what is an important function of the bone marrow inside certain bones?','["It digests food.","It makes blood cells.","It stores oxygen.","It sends electrical signals to the brain."]',1,'Your bones actually help make the blood that flows in your veins!','Make blood cells inside bone marrow in certain bones.','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_018','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'How do muscles and bones work together to move your arm?','["The bones pull on the muscles.","The muscle actively pushes the bone away.","The muscle contracts (shortens) and pulls on the bone it is attached to.","The muscles and bones do not touch."]',2,'Muscles can only pull, like pulling a rope; they can''t push!','Many muscles attach to bones and pull on them when they contract... Remember: Muscles pull when they contract; they do not actively push bones.','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_019','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'Where are most of the nutrients from your food actually absorbed into your blood?','["In the mouth","In the stomach","In the small intestine","In the large intestine"]',2,'Your stomach just mashes the food; the long, winding tube after it does the absorbing!','Small intestine: Digestion continues, and most nutrients are absorbed into the blood through the intestinal wall.','2026-11-01 09:16:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_020','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What role does the ''liver'' play in the digestive system?','["It stores solid waste.","It makes bile, which helps the body digest fats.","It chews the food.","It pumps blood."]',1,'It creates a special juice to help break down greasy foods!','The liver makes bile... Bile helps the body digest fats.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_021','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What happens in the ''alveoli'' inside your lungs?','["Food is digested.","Oxygen passes into the blood, and carbon dioxide passes out of the blood to be breathed out.","Blood is pumped to the brain.","Urine is produced."]',1,'They are tiny, microscopic balloons where the actual gas swap happens!','Smaller airways carry air to tiny air sacs called alveoli. Oxygen passes from the alveoli into the blood, while carbon dioxide passes from the blood into the alveoli to be breathed out.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_022','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What is the difference between ''arteries'' and ''veins''?','["Arteries are in the brain, veins are in the legs.","Arteries carry blood away from the heart, while veins carry blood towards the heart.","Arteries only carry water, veins carry blood.","There is no difference."]',1,'Arteries go AWAY, Veins go IN.','Arteries: Carry blood away from the heart. Veins: Carry blood towards the heart.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_023','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What is a ''reflex''?','["When you slowly decide to pick up a book.","A slow movement of the stomach.","A quick, automatic protective response (like pulling your hand away from a hot surface) that happens before you consciously process the pain.","A type of muscle in the heart."]',2,'Your body reacts automatically to protect you before your brain even has time to think ''Ouch!''','A quick protective reflex can travel through the spinal cord, helping your hand move away before you consciously process the pain... This quick response is called a reflex.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_024','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'How does sweat help your body?','["It makes you smell bad so predators stay away.","It mainly helps regulate body temperature (cooling you down).","It removes all the solid waste from your body.","It helps you see better."]',1,'When the sweat evaporates off your skin, it takes the heat with it!','The skin releases sweat, which mainly helps regulate body temperature.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_025','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'Why is ''urine'' (pee) produced?','["To help digest food.","Because the kidneys are filtering waste products and excess water out of your blood.","To make your bones stronger.","To pump blood."]',1,'It''s how your body cleans the trash out of your bloodstream!','The urinary system filters the blood and helps regulate water and salts... The kidneys remove certain wastes and excess water in urine.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_026','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'How do the respiratory and circulatory systems work together when you run?','["They stop working so you can run faster.","The lungs (respiratory) bring in more oxygen, and the heart (circulatory) pumps faster to deliver that oxygen-rich blood to your working leg muscles.","The lungs pump the blood and the heart breathes the air.","They work completely independently."]',1,'Your lungs grab the oxygen, and your heart acts as the delivery truck to get it to your legs!','Respiratory system: Breathing becomes faster to help meet the body''s increased gas-exchange needs. Circulatory system: The heart usually beats faster to transport more oxygen and nutrients to working muscles.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_027','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What are ''capillaries''?','["Bones in your ear.","The large tubes that carry food to your stomach.","Tiny blood vessels where oxygen and nutrients are actually exchanged with the surrounding tissues.","Muscles in your eye."]',2,'They are so small that blood cells have to travel through them in a single-file line!','Capillaries: Tiny blood vessels where substances are exchanged with surrounding tissues.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_028','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'Why is sleep considered a healthy habit for your body?','["It is the only time your heart beats.","Sleep supports learning, growth, and recovery of the body.","It is the only time your body digests food.","It stops you from breathing."]',1,'Your brain and body use sleep time to repair themselves and file away your memories!','Get enough sleep: Sleep supports learning, growth, and recovery.','2026-11-01 09:16:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_029','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What is the difference between ''breathing'' and ''cellular respiration''?','["They are the exact same thing.","Breathing is moving air in and out of the lungs; cellular respiration is the chemical process cells use to release energy from nutrients using oxygen.","Breathing only happens at night.","Cellular respiration is how you digest food in your stomach."]',1,'Your lungs breathe, but your microscopic cells respire to make energy!','Breathing and respiration are not the same: Breathing is moving air into and out of the lungs. Cellular respiration is the process cells use to release energy from nutrients...','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_030','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',5,'What role does the ''diaphragm'' play in the body?','["It digests food in the stomach.","It is a large muscle beneath the lungs that helps with breathing by changing the size of the chest cavity.","It pumps blood to the legs.","It connects the brain to the spine."]',1,'When it pulls down, it acts like a vacuum to suck air into your lungs!','The diaphragm, a large muscle beneath the lungs, helps breathing by changing the size of the chest cavity.','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_031','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Critique the assertion that ''The stomach is the most important organ for digestion because that is where food is absorbed.''','["The assertion is scientifically accurate.","The assertion is biologically flawed. While the stomach mechanically churns food and begins protein breakdown using acid and enzymes, it absorbs very little. The vast majority of chemical digestion and nutrient absorption actually occurs in the highly folded walls of the small intestine.","The assertion is true because the stomach is the largest organ.","The assertion is false because the large intestine does all the digestion."]',1,'The stomach is just a blender; the small intestine is the actual sponge that absorbs the nutrients!','Small intestine: Digestion continues, and most nutrients are absorbed into the blood through the intestinal wall. (Synthesis: correcting a common misconception about the stomach).','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_032','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Analyze the physiological purpose of ''Cellular Respiration'' in relation to the Respiratory and Circulatory systems.','["Cellular respiration is just breathing very deeply.","Cellular respiration is the metabolic process where cells oxidize glucose to synthesize ATP (energy). The Respiratory system is required to intake the necessary \\\\(O_2\\\\) and expel the toxic \\\\(CO_2\\\\) byproduct, while the Circulatory system is the obligate transport network (via hemoglobin) that delivers these gases between the lungs and the cellular mitochondria.","Cellular respiration is how the heart pumps blood.","Cellular respiration only happens in plant cells."]',1,'Your lungs and heart are just the delivery guys; the CELLS are the ones actually using the oxygen to burn the food for energy!','The respiratory system supplies oxygen for cellular respiration and removes much of the carbon dioxide produced... The circulatory system transports substances... (Synthesis of three systems).','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_033','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Synthesize the exception to the rule regarding arteries and veins in the ''Pulmonary'' circulation.','["There is no exception; all arteries always carry oxygen-rich blood.","Generally, arteries carry oxygenated blood away from the heart. However, the pulmonary arteries carry deoxygenated (oxygen-poor) blood *away* from the heart to the lungs. Conversely, the pulmonary veins return newly oxygenated blood *towards* the heart, reversing the standard oxygenation pattern of systemic blood vessels.","Pulmonary arteries only carry water.","Pulmonary veins carry blood to the brain."]',1,'The ''Artery = Away'' rule is always true, but because blood is going AWAY to the lungs to GET oxygen, it''s empty (oxygen-poor) when it leaves the heart!','Most arteries carry oxygen-rich blood... The pulmonary vessels are an important exception: the pulmonary arteries carry oxygen-poor blood to the lungs, and the pulmonary veins return oxygen-rich blood to the heart.','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_034','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Evaluate the neurological mechanism of a ''Reflex Arc'' compared to a conscious action.','["Reflexes are processed slowly by the brain to ensure safety.","A conscious action requires sensory input to travel to the brain for cognitive processing before a motor response is generated. A reflex arc bypasses the brain; the sensory signal travels only to the spinal cord, which immediately triggers a motor response. This vastly reduces reaction time, minimizing tissue damage from acute threats (like fire).","Reflexes do not use nerves at all.","A conscious action is faster than a reflex."]',1,'If you touch a hot stove, your spine pulls your hand away before your brain even realizes it hurts!','A quick protective reflex can travel through the spinal cord, helping your hand move away before you consciously process the pain. The brain then helps you understand what happened.','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_035','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Analyze the functional difference between ''Skeletal'', ''Smooth'', and ''Cardiac'' muscle tissues.','["They are all identical and controlled consciously.","Skeletal muscle is striated and under voluntary control (moving bones). Smooth muscle is non-striated and under involuntary autonomic control (peristalsis in the digestive tract). Cardiac muscle is striated but involuntary, possessing specialized intercalated discs for synchronized rhythmic contractions independent of conscious thought.","Skeletal muscle is in the heart, smooth muscle is on the bones.","Cardiac muscle is the only muscle that can get tired."]',1,'You can choose to flex your bicep (skeletal), but you can''t choose to stop your stomach from digesting (smooth) or your heart from beating (cardiac)!','Skeletal muscle: usually moves bones under conscious control. Smooth muscle: moves materials through organs... Cardiac muscle: forms the heart and contracts... (Synthesis of the three types).','2026-11-01 09:16:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_036','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Synthesize the role of the ''Kidneys'' in maintaining systemic homeostasis.','["Kidneys only produce solid waste.","Kidneys are critical osmoregulatory organs. They filter metabolic waste (like urea) from the blood, but also constantly adjust the reabsorption of water and vital electrolytes (salts) back into the bloodstream. By regulating urine concentration, they maintain the precise blood volume, blood pressure, and chemical balance required for survival.","Kidneys pump blood when the heart is tired.","Kidneys absorb nutrients from food."]',1,'They aren''t just trash cans; they are highly advanced chemical balancers for your blood!','The urinary system filters the blood and helps regulate water and salts. Kidneys: Filter the blood and produce urine... The body also carefully controls how much water and salt it keeps.','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_037','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Critique the statement: ''The skeletal system is a dead, rigid frame of calcium inside the body.''','["The statement is completely true; bones are dead rocks.","The statement is biologically false. The skeletal system is highly active, living tissue. Bones possess a vascular supply, nerves, and active cells (osteoblasts/osteoclasts) that continuously remodel the calcium matrix. Furthermore, the bone marrow is the dynamic site of hematopoiesis (the constant biological synthesis of red and white blood cells).","The statement is true because bones cannot heal when broken.","The statement is false because bones are made of cartilage, not calcium."]',1,'Bones bleed if you break them, they heal themselves, and they are constantly manufacturing your blood!','Make blood cells inside bone marrow in certain bones. Store minerals, such as calcium. (Synthesis: Bones are active, living organs, not dead rocks).','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_038','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Evaluate the interaction between the ''Digestive'' and ''Circulatory'' systems at the site of the Small Intestine.','["The digestive system turns into the circulatory system.","The small intestine features microscopic, finger-like projections (villi) that maximize surface area. Each villus contains a dense capillary network. Once the digestive system chemically breaks complex polymers into simple monomers (like glucose or amino acids), these nutrients diffuse across the intestinal epithelium directly into the circulatory capillaries for systemic distribution.","The circulatory system pumps blood into the stomach to digest food.","The small intestine uses the lungs to absorb food."]',1,'The small intestine is lined with microscopic blood vessels waiting to catch the tiny food particles and carry them away!','Small intestine: ...most nutrients are absorbed into the blood through the intestinal wall. Capillaries: Tiny blood vessels where substances are exchanged... (Synthesis of absorption mechanics).','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_039','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Analyze the physiological integration required for the action of ''Running''.','["Running only uses the muscular system.","Running requires massive, synchronized multi-system integration. The Nervous system sends motor impulses. Skeletal muscles contract against the Skeletal system for locomotion. This massively increases cellular demand for ATP, forcing the Respiratory system to hyperventilate (increase \\\\(O_2\\\\) intake/\\\\(CO_2\\\\) expulsion) and the Circulatory system to increase cardiac output (heart rate) to deliver these gases and nutrients.","Running uses the digestive system to pump blood.","Running requires the urinary system to absorb oxygen."]',1,'Every system in your body goes into overdrive to support your muscles when you sprint!','No body system works completely alone... Nervous system: Coordinates movement... Skeletal and muscular... Respiratory... Breathing becomes faster... Circulatory... heart usually beats faster... (Synthesis of integration).','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_040','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Synthesize the biological purpose of ''Sweating'' as an excretory and thermoregulatory function.','["Sweating is solely to release solid waste from the bones.","Sweating is an autonomic physiological response primarily for thermoregulation. When core temperature rises, sweat glands excrete an aqueous solution onto the skin. Because water has a high latent heat of vaporization, its evaporation absorbs massive amounts of thermal energy from the skin, cooling the blood. Secondarily, it excretes trace metabolic wastes (like urea and salts).","Sweating warms the body up in cold weather.","Sweating is how the body absorbs oxygen through the skin."]',1,'It''s your body''s built-in air conditioning system! The water takes the heat away when it evaporates into the air.','The skin releases sweat, which mainly helps regulate body temperature. (Synthesis of thermodynamics and skin function).','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_human_global_041','Biology','Human Body and Its Systems','Topic 6: The Human Body','Primary',10,'Critique the classification of the ''Liver'' and ''Pancreas'' as accessory organs to the digestive system.','["They are not part of the digestive system because food doesn''t enter them.","While food (chyme) never physically passes through the liver or pancreas, they are obligate components of chemical digestion. The liver synthesizes bile (for lipid emulsification), and the pancreas secretes a highly alkaline juice containing critical digestive enzymes (lipases, proteases, amylases) into the small intestine to complete the breakdown of macronutrients.","They are the main organs where food is chewed.","They only exist to filter blood, not digest food."]',1,'Food never goes inside them, but they squirt the vital chemicals into the intestine that actually dissolve your food!','Other organs help digestion too. The liver makes bile... and the pancreas produces digestive enzymes. Bile helps the body digest fats. (Synthesis: They are chemical factories for digestion).','2026-11-01 09:16:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_001','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Why does our body need food?','["Only to make us sleepy.","Food supplies energy, helps us grow, repairs tissues, and keeps our body working.","Only to change our eye color.","Only when we are exercising."]',1,'Food is the fuel that keeps your body''s engine running!','Our bodies need food for several important reasons... Energy... Growth... Repair... Staying healthy...','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_002','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'What are ''nutrients''?','["The plates and bowls we eat from.","Substances in food that the body needs for energy, growth, repair, and normal functioning.","The parts of food that we cannot digest.","The flavorings added to candy."]',1,'They are the ''good stuff'' hidden inside the food!','Nutrients are substances in food that the body needs for energy, growth, repair, and normal functioning.','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_003','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which nutrient is the body''s main source of energy?','["Water","Vitamins","Carbohydrates","Minerals"]',2,'Think of foods like bread and pasta!','Carbohydrates: An important source of energy','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_004','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which of these foods is a good source of carbohydrates?','["Cooking oil","Chicken","Rice and bread","Water"]',2,'These are ''starchy'' foods that give you energy.','Common sources [of carbohydrates] include: Rice, bread, oats, and other grains.','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_005','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which nutrient does the body use to build muscles and repair tissues?','["Protein","Sugar","Water","Vitamin C"]',0,'You need this to grow strong muscles!','Proteins: Growth, tissue repair, and making important body substances','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_006','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which of these foods is a good source of protein?','["An apple","Eggs and meat","A glass of water","A piece of candy"]',1,'These foods help build your body.','Common sources [of protein] include... Eggs, fish, poultry, and meat.','2026-11-01 09:16:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_007','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Why does the body need some ''fat''?','["It makes you thirsty.","Fats provide concentrated energy, protect organs, and keep the body warm (insulation).","It stops you from growing.","Fats turn into bones."]',1,'A little bit of fat is important for your health!','Fats provide concentrated energy. They also help form cell membranes, protect organs, insulate the body...','2026-11-01 09:16:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_008','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which mineral is very important for building strong bones and teeth?','["Iron","Calcium","Iodine","Potassium"]',1,'You can find this in milk and yogurt!','Calcium: Builds and maintains bones and teeth...','2026-11-01 09:16:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_009','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Why do we need to drink water?','["Because it tastes like candy.","Water carries nutrients around the body, regulates temperature (sweat), and helps remove waste.","Water turns into protein.","Water makes us breathe faster."]',1,'Your body is mostly made of water!','Water is essential because it: Carries nutrients... Helps regulate body temperature... Helps the kidneys remove certain wastes.','2026-11-01 09:16:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_010','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'What is a ''balanced diet''?','["Eating exactly one type of food every day.","An eating pattern that provides the energy and a suitable variety of nutrients a person needs.","Eating only vegetables and never drinking water.","Eating as much sugar as possible."]',1,'It means eating a good mix of everything!','A balanced diet provides the energy and nutrients a person needs in suitable amounts.','2026-11-01 09:16:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_011','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Why should you wash your hands before preparing or eating food?','["To make your hands smell like flowers.","To reduce the risk of illness by washing away harmful microbes (germs).","To make the food taste better.","To keep your hands dry."]',1,'Soap and water wash the invisible germs away!','Follow these basic practices: Wash hands with soap before preparing or eating food... Food safety reduces the risk of illness caused by harmful microbes...','2026-11-01 09:16:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_012','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which vitamin helps the body absorb iron from plants and is found in citrus fruits like oranges?','["Vitamin D","Vitamin C","Vitamin K","Vitamin A"]',1,'Oranges are packed with this vitamin!','Vitamin C: Supports collagen formation and helps the body absorb iron... Example food sources: Citrus fruits...','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_013','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'Which vitamin helps support your vision (eyesight) and is found in carrots?','["Vitamin A","Vitamin B","Vitamin C","Vitamin D"]',0,'Eating carrots is good for your eyes!','Vitamin A: Supports vision and healthy tissues. Example food sources: Carrots...','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_014','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'What is a good way to stay healthy?','["Drinking sugary drinks all day.","Eating a varied diet, drinking water, moving your body, and getting enough sleep.","Skipping meals.","Never washing your hands."]',1,'It takes many good choices to stay healthy!','Healthy habits support the normal functioning of the body: Eat a varied diet... Drink water regularly... Move your body... Get enough sleep...','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_015','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',1,'What happens if you only eat one type of food all the time?','["You will grow twice as fast.","You might miss out on important nutrients, because no single food provides everything the body needs.","You will never get thirsty.","Your body will stop needing sleep."]',1,'You need a rainbow of foods to get all the vitamins!','No single food provides everything the body needs in the right amounts. A varied diet helps supply a broad range of nutrients.','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_016','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'How do carbohydrates actually provide the body with energy?','["They create tiny explosions in the stomach.","Carbohydrates are broken down into simple sugars (like glucose) that cells can then use for energy during cellular respiration.","They turn directly into solid muscle.","They absorb water and become heat."]',1,'Your body breaks complex carbs down into simple sugar fuel!','Carbohydrates are broken down into simple sugars, such as glucose, that cells can use for energy.','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_017','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why is ''dietary fibre'' important even though the body doesn''t digest much of it?','["It turns into fat.","Fibre helps food move smoothly through the digestive system and supports bowel health.","It makes the heart beat faster.","It provides all the body''s vitamins."]',1,'It acts like a broom to sweep your digestive system clean!','Dietary fibre is found mainly in plant foods. Much of it is not digested... Fibre helps food move through the digestive system and can help prevent constipation.','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_018','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'If you wanted to add more ''fibre'' to your diet, which food should you choose?','["A glass of milk","A piece of chicken","Whole grains (like oats) and beans","A spoonful of oil"]',2,'Fibre is only found in plant foods!','Good sources [of fibre] include: Whole grains, such as oats... Beans, lentils... Fruits and vegetables.','2026-11-01 09:16:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_019','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'What are ''amino acids''?','["Types of sugar found in fruit.","The smaller building blocks that make up proteins.","A type of dangerous bacteria.","The liquid inside a battery."]',1,'Think of them like the Lego bricks that build protein!','Proteins are made from smaller building blocks called amino acids.','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_020','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why are some fats (like saturated and trans fats) considered less healthy than others?','["Because they taste bad.","Because while the body needs *some* fat, large amounts of saturated and trans fats can lead to health problems; unsaturated fats (like from nuts) are generally preferred.","Because they instantly turn into sugar.","Because they contain too much water."]',1,'Plant oils and fish fats are usually better for your heart than heavy animal fats!','Unsaturated fats... are generally preferred over large amounts of saturated fat. Trans fats should be limited as much as possible.','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_021','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why does the body need ''Vitamin D''?','["To help the blood clot when you get a cut.","To help the body absorb calcium and support strong bones.","To give you energy to run.","To improve your eyesight."]',1,'You need this vitamin so your body can actually use the calcium you drink in milk!','Vitamin D: Helps the body absorb calcium and supports bones.','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_022','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'What is a unique way the human body can get Vitamin D, besides eating food?','["By breathing in oxygen.","Sunlight helps the body make its own Vitamin D.","By drinking a lot of water.","By sleeping in the dark."]',1,'Your skin can act like a solar panel to make this vitamin!','Vitamin D... sunlight helps the body make vitamin D','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_023','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why is the mineral ''Iron'' important for your body?','["It builds strong teeth.","It helps make haemoglobin, which carries oxygen in your blood.","It helps you see in the dark.","It digests your food."]',1,'Without iron, your blood couldn''t carry oxygen to your muscles!','Iron: Helps make haemoglobin, which carries oxygen in the blood.','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_024','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why do many countries put the mineral ''Iodine'' into everyday table salt?','["To make the salt taste better.","Because iodine helps the thyroid gland make important hormones, and fortified salt is an easy way to ensure people get enough.","To stop the salt from melting.","Because iodine turns into calcium."]',1,'Your neck has a special gland that needs iodine to control how you grow!','Iodine: Helps the thyroid gland make hormones. Common food sources: Iodised salt...','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_025','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'If you sweat a lot on a hot day, why do you need to drink more water?','["To wash the sweat off your skin.","Because sweating removes water from the body to cool it down, and you must drink to replace the lost water (stay hydrated).","Because water stops you from sweating entirely.","Because water turns into ice in your stomach."]',1,'You are leaking water to stay cool; you have to refill the tank!','Water is essential because it... Replaces water lost through urine, sweat, and breathing... Hot weather and exercise often increase the amount needed.','2026-11-01 09:16:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_026','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why is it important to keep raw meat separate from ready-to-eat foods (like a salad)?','["Because raw meat smells bad.","To prevent cross-contamination, where harmful microbes from the raw meat transfer onto the salad, which won''t be cooked to kill them.","Because the salad will turn into meat.","Because they must be eaten at different times of day."]',1,'You don''t want raw chicken juice on your lettuce!','Keep raw meat and seafood separate from ready-to-eat foods... Food safety reduces the risk of illness caused by harmful microbes and contamination.','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_027','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'In the iodine starch test, what happens if you put a drop of iodine on a piece of bread?','["The bread explodes.","The iodine usually changes from brown-orange to a blue-black color, proving that starch (a carbohydrate) is present.","The bread turns bright red.","Nothing happens to the color."]',1,'This is a cool chemistry trick to find hidden carbohydrates!','Iodine usually changes from brown-orange to blue-black when starch is present... Bread: Blue-black colour','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_028','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Is it true that you should NEVER eat fats?','["Yes, fats are completely poisonous.","No, fats are essential for energy storage, building cell membranes, and helping the body absorb certain vitamins.","Yes, fats stop you from growing.","No, you should only eat fats and nothing else."]',1,'Your body actually needs good fats to survive!','Fats provide concentrated energy. They also help form cell membranes, protect organs, insulate the body, and allow the body to absorb vitamins A, D, E, and K.','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_029','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'What happens to food in the ''small intestine''?','["It is chewed up.","Digestion continues, and most of the nutrients are absorbed into the blood through the intestinal wall.","It is turned into solid waste.","It is mixed with stomach acid."]',1,'This is where the food finally crosses over into your body!','This requires recalling knowledge from Topic 6, linked to nutrition. The text says nutrients are absorbed. Small intestine: Digestion continues, and most nutrients are absorbed into the blood...','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_030','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',5,'Why is ''variety'' the most important part of a balanced diet?','["Because eating the same thing is boring.","Because different foods contain different combinations of nutrients; choosing a wide range ensures the body gets all the different vitamins and minerals it needs.","Because variety makes the food cook faster.","Because your stomach can only hold one type of food at a time."]',1,'You can''t get everything you need from just eating apples!','Why variety matters: Different foods contain different combinations of nutrients. Choosing a range of foods over time makes it easier to meet the body''s needs.','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_031','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Critique the assertion that ''You should avoid all carbohydrates because they only make you gain weight.''','["The assertion is true; carbohydrates have no nutritional value.","The assertion is a dangerous dietary fallacy. Carbohydrates are the body''s primary and most efficient source of metabolic energy (glucose) required for cellular respiration. While excessive caloric intake causes weight gain, complex carbohydrates (like whole grains) are essential for sustained energy and also provide crucial dietary fibre.","The assertion is true because carbohydrates are toxic.","The assertion is false because carbohydrates are actually proteins."]',1,'Your brain runs almost entirely on the glucose from carbohydrates! Complex carbs are great fuel.','Carbohydrates: An important source of energy... Carbohydrates are not automatically unhealthy. The type of food and the overall eating pattern matter.','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_032','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Analyze the specific physiological role of ''Vitamin K'' and its necessity in the body.','["Vitamin K gives the blood its red color.","Vitamin K is an essential fat-soluble micronutrient required for the synthesis of specific proteins (clotting factors) in the liver. Without adequate Vitamin K (found in leafy greens), the body loses its ability to perform normal blood clotting (coagulation), leading to severe and uncontrolled hemorrhagic bleeding from minor injuries.","Vitamin K helps the body digest sugars.","Vitamin K is used to build strong bones."]',1,'If you get a papercut, Vitamin K is what helps the blood turn into a scab to stop the bleeding!','Vitamin K: Helps normal blood clotting. Example food sources: Leafy green vegetables.','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_033','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Synthesize the relationship between ''Protein'' consumption and the ''Repair'' of body tissues after injury.','["Protein turns into a bandage inside the body.","When tissue is damaged, the body initiates a healing cascade requiring cellular mitosis and the synthesis of new structural proteins (like collagen and muscle fibers). Dietary proteins are enzymatically digested into amino acids, which are then absorbed and reassembled by ribosomes at the injury site to physically rebuild the damaged cellular architecture.","Protein provides the energy needed to walk to the hospital.","Protein stops the heart from beating too fast."]',1,'You have to eat the building blocks (amino acids) so your body can rebuild the torn muscle!','Proteins are made from smaller building blocks called amino acids. The body uses them to build and repair tissues... (Synthesis of digestion and repair).','2026-11-01 09:16:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_034','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Evaluate the biological requirement of ''Fats'' (Lipids) for the absorption of specific vitamins.','["Fats destroy vitamins so they can''t be absorbed.","Vitamins A, D, E, and K are biochemically ''fat-soluble'', meaning they are non-polar molecules that cannot dissolve in the aqueous environment of the digestive tract alone. Dietary lipids (fats) form micelles that dissolve these vitamins, allowing them to be transported across the intestinal epithelium and absorbed into the lymphatic system.","Fats turn into vitamins inside the stomach.","Fats are only needed to absorb Vitamin C."]',1,'If you eat a carrot (Vitamin A) with absolutely zero fat, your body will struggle to absorb the vitamin!','Fats... allow the body to absorb vitamins A, D, E, and K. (Synthesis: Without fat, these specific vitamins pass right through you).','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_035','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Analyze the function of ''Dietary Fibre'' (Cellulose) in maintaining gastrointestinal health.','["Fibre provides massive amounts of energy.","Human digestive enzymes cannot break the complex beta-glycosidic bonds of dietary fibre (cellulose). As it passes undigested through the gastrointestinal tract, insoluble fibre adds bulk to the stool and mechanically stimulates peristalsis, preventing constipation. Soluble fibre acts as a prebiotic, fermenting in the large intestine to feed a healthy microbiome.","Fibre dissolves completely in the mouth.","Fibre prevents the body from absorbing any water."]',1,'Even though you can''t digest it, the physical bulk of the fibre acts like a scrub brush for your intestines!','Dietary fibre... Much of it is not digested... Fibre helps food move through the digestive system and can help prevent constipation. Some types also feed helpful microbes...','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_036','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Synthesize the physiological consequences of severe ''Iron'' deficiency (Anemia).','["The person will grow extra bones.","Iron is the central coordinate atom in the heme group of a haemoglobin molecule. Severe iron deficiency halts the synthesis of functional haemoglobin in red blood cells. Consequently, the circulatory system''s capacity to transport oxygen from the alveoli to peripheral tissues plummets, resulting in systemic hypoxia, severe fatigue, and impaired cellular respiration.","The person will become highly energetic.","The person will lose the ability to sweat."]',1,'Without iron, your blood can''t hold onto the oxygen you breathe, so your muscles suffocate!','Iron: Helps make haemoglobin, which carries oxygen in the blood. (Synthesis: No iron = no haemoglobin = no oxygen transport = no energy).','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_037','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Critique the concept of a ''Superfood'' that provides every nutrient a human needs.','["Superfoods are scientifically proven to replace all other foods.","The concept of a singular ''superfood'' is a marketing fallacy, not a biological reality. Human biochemistry requires a complex, highly diverse matrix of macronutrients (carbs, proteins, lipids) and dozens of specific micronutrients (vitamins, trace minerals). No single organism synthesizes or stores this exact stoichiometric balance, necessitating a varied, multi-source diet.","Superfoods only work if you eat them with water.","Superfoods are toxic and should always be avoided."]',1,'There is no magic pill or magic fruit; you have to eat a variety of things to get the whole chemical puzzle!','No single food provides everything the body needs in the right amounts. A varied diet helps supply a broad range... No single fruit or vegetable contains every vitamin... Eating a variety of foods is more helpful than relying on one so-called “superfood.”','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_038','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Evaluate the critical importance of ''Hydration'' (Water) for cellular chemical reactions.','["Water stops chemical reactions from happening too fast.","Water is the universal biological solvent. Virtually all intracellular and extracellular metabolic reactions (including hydrolysis during digestion and cellular respiration) require an aqueous medium to occur. Water''s polarity allows it to dissolve and facilitate the collision of reactants, transport solutes, and stabilize enzymes; without it, cellular biochemistry instantly ceases.","Water is only used to wash the outside of the body.","Water provides all the calories the body needs."]',1,'Your cells are basically tiny bags of water; if they dry out, the chemical reactions that keep you alive stop immediately!','Water is essential because it... Supports digestion and many chemical reactions. (Synthesis: Life''s chemistry happens in water).','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_039','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Analyze the specific danger of ''Cross-contamination'' in food safety regarding raw poultry.','["Raw poultry will make vegetables taste like chicken.","Raw poultry often harbors pathogenic bacteria like Salmonella or Campylobacter. If utensils, cutting boards, or hands touch the raw meat and subsequently touch ready-to-eat foods (like salad), the live pathogens are mechanically transferred. Because the salad is not subjected to thermal lethality (cooking) before consumption, it acts as a vector for severe foodborne illness.","Raw poultry removes the vitamins from the vegetables.","Cross-contamination only happens if the food is frozen."]',1,'If you use the same knife for the raw chicken and the salad, you are spreading dangerous, live germs straight into your mouth!','Keep raw meat and seafood separate from ready-to-eat foods... Food safety reduces the risk of illness caused by harmful microbes and contamination.','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_040','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Synthesize how a ''Balanced Diet'' must shift based on the specific physiological stage or activity level of an individual.','["A balanced diet is a strict mathematical formula that never changes.","Dietary requirements are highly dynamic. A growing adolescent requires a higher proportion of proteins and calcium for structural biosynthesis. An endurance athlete requires a massive caloric surplus heavily weighted toward complex carbohydrates for rapid ATP generation. A ''balanced'' diet is not static; it must continually adapt to maintain homeostasis against specific biological demands.","A balanced diet means eating only vegetables when you are old.","A balanced diet means never drinking water when exercising."]',1,'A construction worker running a marathon needs a totally different ''balance'' of fuel than someone sitting at a desk all day!','A balanced diet provides the energy and nutrients a person needs in suitable amounts. The best balance varies with age, activity, health, culture, and food availability.','2026-11-01 09:16:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_041','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Critique the chemical limitation of the ''Iodine Starch Test''.','["The test proves exactly how many calories are in the food.","While the Iodine test is highly effective at qualitatively confirming the presence of starch (amylose) via the formation of a blue-black polyiodide complex, it is biochemically limited. It only tests for complex polysaccharides (starch); it will yield a negative (no color change) result for simple monosaccharides (like glucose) or disaccharides (like sucrose), even though they are also carbohydrates.","The test only works on foods that are already blue.","The test proves if a food has protein in it."]',1,'If you put iodine on pure sugar, it won''t turn black, even though sugar is a carbohydrate! It only works on the complex chains of starch.','Iodine usually changes from brown-orange to blue-black when starch is present. (Synthesis: It only tests for starch, not ALL carbohydrates).','2026-11-01 09:16:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_042','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Evaluate the physiological impact of excessive sodium (salt) consumption.','["It makes the blood turn blue.","Excessive sodium intake disrupts the body''s osmotic balance. The kidneys must retain more water to dilute the high sodium concentration in the blood, which increases overall blood volume. This elevated volume exerts higher hydrostatic pressure against arterial walls (hypertension), forcing the heart to work harder and significantly increasing the risk of cardiovascular disease.","It causes the bones to shrink.","It immediately stops the lungs from working."]',1,'Too much salt forces your body to hold onto extra water, which pushes hard against your blood vessels like over-inflating a balloon!','Limiting foods with very high amounts of salt or added sugar... The body also carefully controls how much water and salt it keeps. (Synthesis of Topic 6 and 7).','2026-11-01 09:16:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_043','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Analyze the role of B Vitamins in energy metabolism.','["They provide energy directly like carbohydrates.","B vitamins (like B12, B6, riboflavin) do not provide caloric energy themselves. Instead, they act as essential coenzymes in cellular respiration pathways (like the Krebs cycle). They physically bind to enzymes to catalyze the biochemical reactions that strip electrons from carbohydrates, proteins, and fats to synthesize ATP.","They turn water into sugar.","They build muscle tissue directly."]',1,'B vitamins are not the fuel; they are the spark plugs that let your body burn the fuel!','B vitamins: Help release energy from food and support other processes.','2026-11-01 09:16:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_044','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Synthesize the biological consequence of a diet lacking in Calcium during childhood.','["The child will grow twice as fast.","Calcium is a primary structural component of hydroxyapatite, the mineral matrix of bone tissue. During childhood, the skeletal system undergoes rapid ossification and growth. A severe calcium deficit prevents the adequate mineralization of newly formed bone matrix, leading to osteomalacia or rickets (soft, deformed bones) and permanently stunted skeletal development.","The child''s hair will fall out.","The child will not be able to digest proteins."]',1,'Without calcium, your body is trying to build a house without any bricks!','Calcium: Builds and maintains bones and teeth... Children need adequate food to grow.','2026-11-01 09:16:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_food_global_045','Biology','Nutrition and Healthy Eating','Topic 7: Food and Nutrition','Primary',10,'Critique the practice of ''skipping meals'' to maintain a healthy weight.','["It is the only way to stay healthy.","Skipping meals is biologically counterproductive. It triggers a starvation response (lowering basal metabolic rate to conserve energy) and causes severe fluctuations in blood glucose levels. This typically leads to acute hypoglycemia (causing fatigue and cognitive impairment) followed by compensatory overeating (bingeing) of high-caloric foods later, disrupting overall metabolic homeostasis.","It makes the digestive system stronger.","It helps the body store extra water."]',1,'If you skip a meal, your body panics and slows down your engine, and then you just end up starving and eating junk food later!','Children need adequate food to grow. Restrictive diets or skipping meals are not appropriate ways to learn about healthy eating.','2026-11-01 09:16:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_001','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What does it mean to be ''healthy''?','["Only that you don''t have a disease.","A state of physical, mental, and social well-being.","That you are very strong.","That you never sleep."]',1,'Health is about feeling good in your body AND your mind!','Health means a state of physical, mental and social well-being, not simply the absence of disease.','2026-11-01 09:16:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_002','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What does ''hygiene'' mean?','["Eating a lot of food.","Practices that help maintain cleanliness and protect health.","Sleeping all day.","Running very fast."]',1,'It means keeping yourself and your surroundings clean!','Hygiene means practices that help maintain cleanliness and protect health.','2026-11-01 09:16:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_003','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What is a very simple and important way to prevent diseases from spreading?','["Washing your hands with soap and water.","Leaving food out on the counter.","Sharing your toothbrush.","Never opening the windows."]',0,'It washes the invisible germs down the drain!','Good personal hygiene includes: Washing hands with soap and clean water... Handwashing: A simple way to prevent disease','2026-11-01 09:16:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_004','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'When is it especially important to wash your hands?','["Before you go to sleep.","While you are eating.","Before preparing or eating food, and after using the toilet.","Only when they look dirty."]',2,'You don''t want germs getting on your food!','Wash hands particularly: Before preparing or eating food. After using the toilet.','2026-11-01 09:16:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_005','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'How long should you scrub your hands with soap to get them clean?','["2 seconds","5 seconds","At least 20 seconds","2 minutes"]',2,'You can sing the ''Happy Birthday'' song twice!','Aim to wash for at least 20 seconds using soap and water.','2026-11-01 09:16:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_006','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'How often should you brush your teeth?','["Once a week","Only when they hurt","Twice a day with fluoride toothpaste","Once a month"]',2,'It keeps the cavities away!','Good personal hygiene includes: ... Brushing teeth twice daily with fluoride toothpaste.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_007','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What does a ''balanced diet'' do for your body?','["It makes you thirsty.","It helps the body grow, repair tissues, and function properly.","It stops you from sleeping.","It causes diseases."]',1,'It gives your body all the building blocks it needs!','Eating a variety of foods helps the body grow, repair tissues and function properly.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_008','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'Why is ''safe drinking water'' important?','["Because it tastes better than milk.","Drinking water should be safe from harmful microorganisms (germs) and dangerous contaminants.","Because water is a non-communicable disease.","Because water gives you energy."]',1,'Dirty water can make you very sick!','Drinking water should be safe from harmful microorganisms and dangerous contaminants.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_009','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What is a ''disease''?','["A type of plant.","A healthy habit.","A condition that interferes with the normal functioning of the body or mind.","A type of exercise."]',2,'It means you are sick or unwell.','A disease is a condition that interferes with the normal functioning of the body or mind.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_010','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What is a ''communicable'' disease?','["A disease that you are born with.","A disease that can spread from one person or animal to another (like catching a cold).","A disease that only affects older people.","A broken bone."]',1,'It means you can ''catch'' it from someone else!','Communicable diseases: These are diseases that can spread from one person, animal or source to another, directly or indirectly.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_011','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'Which of these is a communicable disease?','["A broken arm","Asthma","Chickenpox or the flu","A headache"]',2,'You can catch the flu from a friend who sneezes!','Communicable diseases... Examples include: Influenza (flu)... Chickenpox.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_012','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What does a ''vaccine'' (vaccination) do?','["It cures a broken bone.","It trains the immune system to recognize and fight off specific diseases.","It makes you taller.","It cleans your teeth."]',1,'It acts like a practice target for your body''s defenders!','Vaccines train the immune system to recognise particular infectious agents and help protect against specific diseases.','2026-11-01 09:16:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_013','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What insect is famous for spreading diseases like malaria and dengue when it bites people?','["A honeybee","A spider","A mosquito","A butterfly"]',2,'They leave an itchy bump!','Mosquitoes are insects, and some species transmit disease-causing organisms when they bite people.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_014','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'How can you help stop mosquitoes from breeding near your home?','["By planting more flowers.","By emptying water from containers where they might lay eggs.","By turning on the lights.","By leaving food outside."]',1,'Mosquitoes lay their eggs in still, standing water!','Ways to reduce mosquito breeding and bites include: Emptying water from containers where mosquitoes may breed.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_015','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',1,'What should you do if you feel seriously ill?','["Take someone else''s medicine.","Ignore it and hope it goes away.","Seek help from a trusted adult or healthcare professional (doctor).","Stop drinking water."]',2,'Always ask for help when you are sick!','Seek appropriate healthcare: Follow medical advice... Tell a trusted adult if you feel unwell or are injured.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_016','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why is ''mental health'' just as important as ''physical health''?','["Because it helps your muscles grow.","Mental health means a person can manage everyday feelings and challenges, and seek help when upset; without it, overall well-being is incomplete.","Mental health prevents all communicable diseases.","Mental health means never getting angry."]',1,'Being healthy isn''t just about a strong body; it''s about a happy and balanced mind, too!','Health means a state of physical, mental and social well-being... Mental health: A person can manage everyday feelings and challenges and seek help when needed.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_017','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'If you take perfect care of your hygiene and eat perfectly, will you never get sick?','["Yes, perfect hygiene guarantees you will never be ill.","No, healthy habits support well-being and reduce risks, but illness can still occur even when someone takes good care of themselves.","Yes, as long as you also exercise.","No, hygiene actually causes illness."]',1,'You can lower your chances of getting sick, but nobody is invincible!','Healthy habits support well-being, but illness can still occur even when someone takes good care of themselves.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_018','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why is it important to clean between your teeth and not just brush the front?','["Because food and plaque get trapped between teeth; cleaning all surfaces helps prevent tooth decay and gum disease.","Because it makes your teeth fall out faster.","Because teeth need oxygen to breathe.","Because brushing the front does not work at all."]',0,'A toothbrush can''t always reach into the tight spaces between teeth where germs hide!','Clean all tooth surfaces gently. Clean between teeth using an appropriate method... helps prevent tooth decay, gum disease...','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_019','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why are ''baby teeth'' important, even though they eventually fall out?','["They are the only teeth that can chew food.","They help children chew, speak properly, and act as placeholders to maintain space for permanent teeth.","They are actually made of plastic.","Baby teeth are not important at all."]',1,'They hold the spot open so your adult teeth grow in straight!','Baby teeth are important too because they help children chew, speak and maintain space for permanent teeth.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_020','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'How does proper ''sanitation'' (like flushing toilets and good drainage) protect public health?','["It makes the air smell nice.","It safely manages human waste, preventing harmful microbes from contaminating the drinking water, soil, and food supply.","It gives animals a place to live.","It creates new types of food."]',1,'If waste isn''t disposed of properly, germs get into the water we drink and the food we eat!','Sanitation includes safely managing human waste, wastewater and rubbish. Proper toilets, drainage and waste disposal help reduce contamination of water, soil and food.','2026-11-01 09:16:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_021','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why is sleep considered an active and important part of maintaining health?','["Because you don''t use any energy when you sleep.","Because adequate sleep actively supports learning, memory consolidation, physical growth, and emotional well-being.","Because it stops your heart from beating.","Because sleep cures all communicable diseases."]',1,'Your brain is actually very busy while you sleep, organizing memories and repairing your body!','Sleep and rest: Adequate sleep supports learning, memory, growth and emotional well-being.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_022','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'What is a ''non-communicable'' disease?','["A disease that spreads very quickly by coughing.","A disease caused by mosquitoes.","A disease that does not spread from person to person like an infection (e.g., asthma, diabetes).","A disease that can be cured instantly."]',2,'You cannot ''catch'' asthma from sitting next to someone who has it.','Non-communicable diseases: These do not spread from person to person like communicable infections. Examples include: Asthma. Diabetes.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_023','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'How do diseases like the cold or flu commonly spread through ''respiratory particles''?','["By drinking dirty water.","When an infected person breathes, talks, coughs, or sneezes, they release tiny droplets containing the virus into the air, which others can breathe in.","By sharing a toothbrush.","By eating spoiled food."]',1,'This is why covering your mouth when you cough is so important!','Respiratory particles: Some infections spread when an infected person breathes, talks, coughs or sneezes.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_024','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'If you have a viral illness like the common cold, why shouldn''t you demand antibiotics from a doctor?','["Because antibiotics taste bad.","Because antibiotics are designed to work against certain *bacterial* infections, not viral illnesses; they will not cure a cold.","Because antibiotics will make the cold worse.","Because antibiotics are only for animals."]',1,'Antibiotics kill bacteria, but a cold is caused by a virus. It''s like using the wrong tool for the job!','Important: Antibiotics work against certain bacterial infections, not viral illnesses such as the common cold. They should be used only when appropriately prescribed.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_025','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why is ''ventilation'' (letting fresh air inside) important for preventing disease?','["It makes the room colder so germs freeze.","Good indoor ventilation dilutes and removes airborne respiratory particles, reducing the spread of some respiratory infections.","It blows the germs into the neighbor''s house.","It dries out the skin."]',1,'Opening a window lets the fresh air push the germ-filled air out!','Improve indoor air: Ventilation and appropriate respiratory hygiene can reduce the spread of some respiratory infections.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_026','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'How does a mosquito transmit (spread) a disease like malaria?','["By landing on your food.","By coughing on you.","The mosquito acts as a vector; when an infected mosquito bites a person, it transmits the disease-causing organism directly into their blood.","By stinging you with its tail."]',2,'The mosquito is basically a dirty flying needle that moves the parasite from one person to another!','Insect or animal vectors: Mosquitoes can transmit diseases such as malaria... Caused by parasites transmitted by infected female Anopheles mosquitoes.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_027','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Are all mosquitoes dangerous disease carriers?','["Yes, every single mosquito carries malaria.","No, mosquitoes do not transmit all diseases, and not every mosquito carries a disease-causing organism.","Yes, but they only bite animals.","No, mosquitoes only carry non-communicable diseases."]',1,'Most mosquito bites are just annoying and itchy, but some specific types in certain areas are dangerous.','Mosquitoes do not transmit all diseases, and not every mosquito carries a disease-causing organism.','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_028','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'In the glitter activity, what does the glitter represent?','["A healthy vitamin.","How invisible contamination (like germs on your hands) can easily transfer to other people or objects you touch.","A type of insect.","Clean water."]',1,'If you touch something dirty and then shake someone''s hand, you just passed the ''glitter'' (germs) to them!','Conclusion: Contamination can spread through contact, even when it is not visible. (Glitter is only a model of transfer; it is not a microorganism).','2026-11-01 09:16:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_029','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'What does it mean to have ''immunity'' to a disease?','["It means you are completely invisible to mosquitoes.","It means you have the disease right now.","It refers to the body''s ability to resist or respond effectively to a particular infection, often gained through vaccination or previous exposure.","It means you never have to wash your hands."]',2,'If you are immune, your body already has the weapons ready to fight off that specific germ before it can make you sick!','Immunity: The body''s ability to resist or respond to particular infections.','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_030','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',5,'Why should you never share prescription medicines with others?','["Because medicine is too expensive.","Because prescription medicines are specifically prescribed for a certain person, dosage, and condition; taking someone else''s can be very dangerous.","Because they will lose their color.","Because medicines are communicable."]',1,'What cures one person might be poison to another!','They should be used only when appropriately prescribed. Never share prescription medicines with others.','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_031','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Critique the assertion that ''Health is strictly defined as the absence of physical illness.''','["The assertion is scientifically accurate.","The assertion is biologically and socially incomplete. The modern definition of health encompasses a holistic state of complete physical, mental, and social well-being. A person could have no physical infections (disease) but suffer from severe anxiety or social isolation, meaning they are not truly ''healthy''.","The assertion is true because mental health is an illusion.","The assertion is false because health only refers to diet."]',1,'If your body is fine but your mind is suffering, you aren''t completely healthy. True health includes your mind and your relationships!','Health means a state of physical, mental and social well-being, not simply the absence of disease.','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_032','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Analyze the epidemiological difference between a ''Vector-borne'' communicable disease and a ''Respiratory'' communicable disease.','["They are identical in how they spread.","A respiratory disease (like Influenza) spreads primarily through direct aerosol transmission (inhaling droplets from an infected host''s cough). A vector-borne disease (like Malaria) requires a biological intermediate (an arthropod like a mosquito) to physically transfer the pathogen between hosts via blood-feeding.","Vector-borne diseases are only found in plants.","Respiratory diseases are spread by eating spoiled food."]',1,'You can catch the flu from a sneeze, but you can only catch malaria if a specific bug bites you!','Respiratory particles: Some infections spread when an infected person breathes... Insect or animal vectors: Mosquitoes can transmit diseases such as malaria... (Synthesis of transmission routes).','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_033','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Synthesize the mechanism by which a ''Vaccination'' confers acquired immunity.','["Vaccinations act as a physical shield on the skin.","A vaccination introduces a harmless, deactivated, or partial antigen of a specific pathogen into the body. This safely triggers the adaptive immune system to produce highly specific antibodies and memory cells. If the actual, live pathogen enters the body later, the immune system rapidly recognizes and neutralizes it before the disease can develop.","Vaccinations kill all germs currently inside the stomach.","Vaccinations permanently alter the DNA of the host."]',1,'A vaccine is like giving your body a ''wanted poster'' of the germ so it knows exactly how to fight it if it ever shows up for real!','Vaccines train the immune system to recognise particular infectious agents and help protect against specific diseases. (Synthesis: how it ''trains'' the system).','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_034','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Evaluate the public health impact of widespread ''Sanitation'' infrastructure (like sewage systems) compared to individual hygiene.','["Sanitation is irrelevant if individuals wash their hands.","While individual hygiene (handwashing) is critical for personal defense, public sanitation infrastructure (sewage treatment, clean municipal water) is the primary defense against systemic, waterborne epidemics (like Cholera). Without sanitation, the environmental contamination load is too high for individual hygiene to mitigate population-level outbreaks.","Sanitation only protects plants, not humans.","Sanitation makes handwashing completely unnecessary."]',1,'You can wash your hands all day, but if the city''s drinking water is contaminated with sewage, everyone will still get sick!','Sanitation includes safely managing human waste... Proper toilets, drainage and waste disposal help reduce contamination of water, soil and food. (Synthesis of public vs personal health).','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_035','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Analyze why ''Non-communicable diseases'' (NCDs) cannot be prevented using vaccines or quarantine.','["Because NCDs are caused by alien viruses.","Because NCDs (like diabetes or cancer) are not caused by transmissible exogenous pathogens (viruses/bacteria). They result from complex interactions of genetics, prolonged lifestyle factors (diet, physical inactivity), and environmental exposures. Therefore, immunological training (vaccines) or physical isolation (quarantine) are irrelevant to their pathogenesis.","Because NCDs move too fast to be quarantined.","Because vaccines only work on diseases that are harmless."]',1,'You can''t quarantine someone for asthma, and you can''t get a vaccine for a broken leg!','These do not spread from person to person like communicable infections... Non-communicable diseases can have genetic, environmental or other causes. (Synthesis: The cause dictates the prevention).','2026-11-01 09:16:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_036','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Synthesize the danger of ''Cross-contamination'' in food safety regarding raw and cooked foods.','["Cooking food makes it permanently immune to germs.","Raw foods (like poultry) naturally harbor pathogenic bacteria. Cooking provides thermal lethality, destroying the pathogens. However, if cooked, ready-to-eat food is subsequently placed on a surface (like a cutting board) previously used for raw meat, the live pathogens mechanically transfer back to the safe food, causing foodborne illness upon consumption.","Cross-contamination only happens if food is frozen.","Raw and cooked foods naturally repel each other."]',1,'If you cut raw chicken and then use the same dirty knife to cut your salad, you just put live germs straight into your safe food!','Keep raw and cooked foods separate... Food safety reduces the risk of illness caused by harmful microbes and contamination. (Synthesis of why separation is required).','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_037','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Critique the practice of prescribing ''Antibiotics'' for a patient suffering from Influenza (the flu).','["It is the best and only cure for the flu.","The practice is clinically useless and epidemiologically dangerous. Influenza is a viral infection. Antibiotics function by disrupting specific bacterial mechanisms (like cell wall synthesis) that viruses lack entirely. Using them for a virus provides zero therapeutic benefit and actively accelerates the evolution of antibiotic-resistant bacteria in the patient''s microbiome.","It works because the flu is caused by a giant bacterium.","It is only helpful if the patient is a child."]',1,'Antibiotics are designed to kill bacteria. Using them on a virus is like trying to turn off a lightbulb with a glass of water!','Important: Antibiotics work against certain bacterial infections, not viral illnesses such as the common cold. They should be used only when appropriately prescribed.','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_038','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Evaluate the physiological impact of ''Sleep Deprivation'' on a child''s overall health.','["Sleep deprivation only makes a child slightly tired.","Chronic sleep deprivation causes systemic physiological and cognitive degradation. During sleep, the brain consolidates memory and learning, while the body secretes growth hormones and repairs tissues. A lack of sleep directly impairs cognitive function (focus/memory), stunts physical development, and weakens immunological resistance to communicable diseases.","Sleep deprivation increases intelligence over time.","Sleep deprivation proves the child is very strong."]',1,'Sleep isn''t just resting; it''s the time when your body is actively building your brain and fixing your muscles!','Adequate sleep supports learning, memory, growth and emotional well-being. Children need more sleep than adults. (Synthesis: What happens when this is missing?).','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_039','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Analyze the biological mechanism by which ''Fluoride'' in toothpaste improves oral hygiene.','["Fluoride physically scrubs the dirt off the teeth.","The enamel of teeth is susceptible to demineralization by acids produced by oral bacteria. Fluoride ions chemically react with the tooth enamel (hydroxyapatite) to form fluorapatite. This new mineral structure is significantly harder and more resistant to acidic dissolution, physically preventing the progression of dental caries (tooth decay).","Fluoride kills all bacteria in the mouth instantly.","Fluoride makes the teeth turn bright white."]',1,'Fluoride actually bonds with your teeth to build an acid-proof shield on the outside!','Brushing teeth twice daily with fluoride toothpaste... Good oral hygiene helps prevent tooth decay... (Synthesis with Topic 15 chemistry).','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_040','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Synthesize how breaking the ''Chain of Infection'' applies to Mosquito-borne diseases.','["You must trap all mosquitoes in a giant net.","To prevent diseases like Dengue, public health must disrupt the transmission cycle. Since the mosquito is the obligate vector, eliminating standing water (where larvae develop) breaks the reproductive cycle, reducing the vector population. Using nets prevents the physical transfer of the pathogen to the host, effectively halting the spread of the disease.","You must teach mosquitoes to eat plants instead of blood.","You must freeze the ocean to stop them from breeding."]',1,'If you dump out the puddles, the mosquitoes can''t lay eggs. No mosquitoes = no disease!','Ways to reduce mosquito breeding and bites include: Emptying water from containers where mosquitoes may breed. Covering water-storage containers. Using window screens... (Synthesis: How these actions stop the disease).','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_health_global_041','Biology','Health, Hygiene and Disease Prevention','Topic 8: Health, Hygiene and Disease Prevention','Primary',10,'Critique the concept that ''Cleanliness guarantees you will never contract a disease.''','["The concept is absolutely true.","The concept is a dangerous fallacy. While rigorous hygiene significantly lowers statistical risk by reducing pathogen load, it cannot guarantee absolute prevention. Pathogens can be transmitted asymptomatically via aerosolized particles, through unavoidable environmental exposures, or via highly contagious vectors. Furthermore, cleanliness offers zero protection against non-communicable diseases (like cancer).","The concept is true as long as you use hot water.","The concept is false because cleanliness actually attracts germs."]',1,'Washing your hands is your best defense, but you can''t control every germ in the air you breathe!','Healthy habits support well-being, but illness can still occur even when someone takes good care of themselves... Hygiene helps reduce the spread of harmful germs, although it cannot prevent every illness.','2026-11-01 09:16:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_001','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What is a ''cell'' in biology?','["A small room.","A type of battery.","The basic building block or unit of all living things.","A type of disease."]',2,'It''s like a single Lego brick used to build a body!','A cell is the basic unit of life. All living things are made of one or more cells.','2026-11-01 09:17:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_002','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What is the ''cell membrane''?','["The jelly inside the cell.","The thin outer layer that controls what goes in and out of the cell.","The brain of the cell.","The hard shell of an egg."]',1,'It acts like a security guard for the cell.','Cell membrane: The thin covering that controls what enters and leaves the cell.','2026-11-01 09:17:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_003','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What does the ''nucleus'' do in a cell?','["It makes the cell green.","It stores water.","It contains genetic material and helps control the cell''s activities.","It makes the cell move."]',2,'It is the boss or the brain of the cell!','Nucleus: Contains genetic material and helps control the cell''s activities.','2026-11-01 09:17:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_004','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What is the ''cytoplasm''?','["The hard outer wall of a plant cell.","A jelly-like material filling the inside of the cell where activities happen.","The part that catches sunlight.","A type of microscope."]',1,'It''s the squishy stuff that fills up the cell.','Cytoplasm: A jelly-like material where many chemical activities take place.','2026-11-01 09:17:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_005','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What is a ''microorganism''?','["An animal that lives in the ocean.","A very small living thing that usually requires a microscope to be seen.","A large plant.","A part of the human brain."]',1,'The prefix ''micro'' means tiny!','A microorganism is a living organism so small that it generally requires a microscope to be seen clearly.','2026-11-01 09:17:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_006','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What tool do scientists use to look at cells and microorganisms?','["A telescope","A stethoscope","A microscope","A thermometer"]',2,'It makes invisible things look much bigger.','A microscope is an instrument that makes tiny objects appear larger so we can examine their details.','2026-11-01 09:17:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_007','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'How many cells are humans made of?','["Just one cell.","About ten cells.","Trillions of cells (multicellular).","Zero cells."]',2,'You are made of billions and billions of them!','Examples: Humans are made of trillions of cells... Multicellular organisms: Made of many cells...','2026-11-01 09:17:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_008','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What kind of organism is a bacteria?','["A large animal.","A single-celled organism (made of just one cell).","A plant.","A multicellular fungus."]',1,'The entire creature is just one single cell!','Bacteria are usually made of just one cell... Single-celled organisms: Made of just one cell.','2026-11-01 09:17:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_009','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'Are all microorganisms harmful (bad) for us?','["Yes, every single one causes diseases.","No, many are helpful, like the ones that help make bread or digest our food.","Yes, but only in the winter.","No, they only affect plants."]',1,'Some germs are actually your friends!','Microorganisms are not all harmful. Many are essential to people and the environment... Yeast helps bread dough rise. Some bacteria help make yoghurt...','2026-11-01 09:17:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_010','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'Which of these is a helpful microorganism?','["The virus that causes the flu.","Yeast, which helps bread dough rise.","Bacteria that cause a sore throat.","A mosquito."]',1,'Bakers use it to make bread fluffy!','Helpful microorganisms: Yeast helps bread dough rise.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_011','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What does a ''red blood cell'' do in the human body?','["It thinks and remembers.","It digests food.","It carries oxygen around the body.","It helps plants grow."]',2,'It acts like a little delivery truck for oxygen!','Red blood cell: Carries oxygen around the human body.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_012','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What does a ''root hair cell'' do for a plant?','["It catches sunlight.","It absorbs water and minerals from the soil.","It makes the plant green.","It creates seeds."]',1,'It acts like a tiny sponge underground.','Root hair cell: Absorbs water and minerals from the soil.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_013','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'What is a ''virus''?','["A type of plant cell.","A large animal.","A microscopic infectious agent that causes diseases like the flu.","A helpful bacteria in yogurt."]',2,'It''s the tiny germ that gives you a cold!','Harmful microorganisms... Viruses cause diseases such as influenza and measles...','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_014','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'How can you help reduce the spread of harmful microorganisms?','["By sharing dirty cups.","By leaving food out all night.","By washing your hands with soap and clean water.","By never brushing your teeth."]',2,'Soap destroys the bad germs!','How can we reduce the spread of harmful microorganisms? Wash hands with soap and clean water.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_015','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',1,'Why do plant and animal cells look different?','["Because plants are animals.","Because they perform different jobs and have different parts (like cell walls in plants).","They don''t look different; they are exactly the same.","Because animal cells are made of wood."]',1,'A leaf needs to do different things than a muscle!','Cells have different shapes and sizes because they perform different jobs... Plant and animal cells have some parts in common, but they also have important differences.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_016','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What two main parts does a plant cell have that an animal cell does NOT have?','["A nucleus and a cell membrane.","A cell wall and chloroplasts.","Cytoplasm and vacuoles.","A brain and muscles."]',1,'Plants need these to stand up straight and catch sunlight!','Plant cell... Has a rigid cell wall... Many green plant cells have chloroplasts. Animal cell... Does not have a cell wall. Does not have chloroplasts.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_017','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What is the function of the ''cell wall'' in a plant cell?','["To catch bugs.","To provide a rigid outer layer that supports and strengthens the plant cell.","To store water.","To control what goes in and out of the cell."]',1,'It acts like a brick wall holding the plant up, since plants don''t have bones!','Cell wall: Provides support and helps maintain the cell''s shape.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_018','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'Why do plant cells need ''chloroplasts''?','["To digest their food.","To absorb water from the ground.","They contain chlorophyll, which absorbs light to make food (photosynthesis).","To help the plant walk."]',2,'They are the green ''solar panels'' of the plant!','Chloroplasts: Contain chlorophyll, which absorbs light for photosynthesis.','2026-11-01 09:17:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_019','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'How does a single-celled organism (like an amoeba) survive?','["It lives inside a human.","It doesn''t; it dies immediately.","That one single cell performs all the necessary life functions (eating, responding, reproducing) by itself.","It joins with other cells to form a brain."]',2,'It''s a one-man band!','Single-celled organisms: Made of just one cell. That cell performs all the necessary life functions... without needing other cells...','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_020','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What is a ''vacuole'' in a cell?','["The part that controls the cell.","A storage space that holds cell sap and helps maintain firmness, usually much larger in plant cells.","The part that catches sunlight.","The hard outer shell of the cell."]',1,'It''s like a water balloon inside the cell!','Vacuole: Stores cell sap and helps maintain firmness in many plant cells. (Animal cells usually have smaller vacuoles, if present).','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_021','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'If a microscope has a 10x eyepiece and a 4x objective lens, what is the total magnification?','["14x","40x","6x","400x"]',1,'You multiply the two numbers together (10 x 4)!','The eyepiece and objective lenses work together to magnify an object. For example, a 10x eyepiece and a 4x objective provide 40x total magnification.','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_022','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What does a ''nerve cell'' look like and why?','["It is perfectly round like a ball to roll easily.","It has long, branching extensions to carry messages across long distances in the body.","It is green to catch sunlight.","It has a hard shell to protect it."]',1,'It looks like a long wire because its job is to send signals!','Nerve cell: Carries messages between different parts of the body. (The diagram shows long extensions). Cells can look different because they are adapted to perform different functions.','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_023','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'Why are ''decomposer'' microorganisms so important to the environment?','["They cause all human diseases.","They break down dead plants and animals, cleaning up the environment and returning nutrients to the soil.","They make the air colder.","They turn water into ice."]',1,'Without them, the world would be covered in dead trees and leaves!','Helpful microorganisms... Decomposer microorganisms break down dead plants and animals.','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_024','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'How do some bacteria help the human body?','["They give us a fever.","Helpful ''gut microorganisms'' (bacteria) live in our intestines and help with digestion and other body functions.","They make our bones break.","They stop our heart from beating."]',1,'You actually have millions of good bacteria inside your stomach helping you right now!','Helpful microorganisms... Gut microorganisms help with digestion and other body functions.','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_025','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What is an ''amoeba''?','["A type of plant.","A single-celled organism that can change shape and move using extensions called pseudopodia.","A part of the human brain.","A virus that causes the flu."]',1,'It looks like a tiny, moving blob of jelly!','Amoebas: Single-celled organisms that can change shape and move using extensions called pseudopodia.','2026-11-01 09:17:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_026','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'Why are viruses usually NOT considered living organisms?','["Because they are too big.","Because they do not have a nucleus.","Because they cannot reproduce on their own; they must infect a living host cell to multiply.","Because they are helpful."]',2,'A virus is basically just a rogue piece of code; it needs to hijack a real cell to work!','Not every microscopic thing is a microorganism. For example, viruses... are generally not considered living organisms because they cannot reproduce independently.','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_027','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What is a ''paramecium''?','["A giant fish.","A plant cell.","A single-celled organism that moves using tiny hair-like structures called cilia.","A type of rock."]',2,'It looks a bit like a hairy slipper under the microscope!','Paramecia: Single-celled organisms that move using tiny hair-like structures called cilia.','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_028','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'How does yeast help in baking?','["It turns the bread green.","It is a helpful microscopic fungus that produces gas bubbles, making the bread dough rise.","It makes the bread hard like a rock.","It makes the bread taste like meat."]',1,'It''s the secret ingredient that makes bread fluffy!','Yeasts: Microscopic fungi, some of which are used in baking... Helpful microorganisms: Yeast helps bread dough rise.','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_029','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'What happens in the ''cytoplasm'' of a cell?','["It controls the cell.","It acts as a hard wall.","Many of the cell''s important chemical activities and reactions take place in this jelly-like substance.","It stores memories."]',2,'It''s the busy ''factory floor'' of the cell.','Cytoplasm: A jelly-like material where many chemical activities take place.','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_030','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',5,'Can an animal cell make its own food using sunlight?','["Yes, all cells can do this.","No, because animal cells do not have chloroplasts (chlorophyll) to perform photosynthesis.","Yes, but only at night.","No, because they don''t have a nucleus."]',1,'Animals have to EAT food; they can''t make it like plants do!','Animal cell... Does not have chloroplasts... Chloroplasts: Contain chlorophyll, which absorbs light for photosynthesis.','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_031','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Critique the assertion that ''All cells have a nucleus to control their functions.''','["The assertion is scientifically absolute.","The assertion is functionally inaccurate. While the nucleus is the control center for most eukaryotic cells, some highly specialized cells, notably mature mammalian red blood cells, intentionally expel their nucleus during development to maximize internal volume for hemoglobin and oxygen transport.","The assertion is true because without a nucleus a cell instantly explodes.","The assertion is true, but only for plant cells."]',1,'A red blood cell throws its ''brain'' away so it has more room to carry oxygen!','Nucleus: Contains genetic material... Some cells, such as mature mammalian red blood cells, do not have a nucleus. (Synthesis of adaptation).','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_032','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Analyze the physiological relationship between the ''Cell Wall'' and the ''Vacuole'' in a plant cell.','["They fight against each other to destroy the cell.","They work in tandem to create turgor pressure. The large central vacuole fills with water (cell sap), expanding and exerting outward hydrostatic pressure against the rigid cell wall. This opposing force provides structural integrity, keeping the non-woody plant upright and preventing wilting.","The cell wall absorbs the vacuole.","The vacuole creates the cell wall from scratch."]',1,'The vacuole acts like an inflated balloon pushing against the rigid cardboard box of the cell wall!','Cell wall: Provides support and helps maintain the cell''s shape... Vacuole: Stores cell sap and helps maintain firmness in many plant cells. (Synthesis: How they create ''firmness'').','2026-11-01 09:17:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_033','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Synthesize why the ''Cell Membrane'' is described as ''semi-permeable'' or ''selectively permeable''.','["It means the membrane is completely solid like a brick wall.","The cell membrane does not allow all substances to pass freely. It acts as a highly regulated biological gatekeeper. It allows essential small molecules (like oxygen and water) to enter via diffusion, while actively blocking toxins or using transport proteins to carefully manage the intake of larger nutrients (like glucose) and the expulsion of waste.","It means the membrane only lets water out, never in.","It means the membrane is completely invisible."]',1,'If the membrane let everything in, the cell would be poisoned! It has to ''select'' what gets through.','Cell membrane: The thin covering that controls what enters and leaves the cell. (Synthesis of the word ''controls'').','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_034','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Evaluate the biological classification of a ''Virus'' compared to ''Bacteria'' based on Cell Theory.','["They are classified identically as single-celled animals.","According to Cell Theory, all living organisms are composed of cells capable of independent metabolism and reproduction. Bacteria fulfill this as independent prokaryotic cells. Viruses fail this classification entirely; they lack cellular structures (no cytoplasm, no ribosomes) and cannot metabolize or replicate without hijacking the molecular machinery of a living host cell.","Viruses are plants, bacteria are animals.","Viruses are much larger and more complex than bacteria."]',1,'A virus isn''t a cell; it''s just a tiny piece of rogue code wrapped in protein!','Bacteria: Single-celled organisms... Viruses... are generally not considered living organisms because they cannot reproduce independently. (Synthesis: applying cell theory).','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_035','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Analyze how the structure of a ''Sperm Cell'' is a direct reflection of its biological function.','["It is shaped like a perfect sphere to roll easily.","The sperm cell''s morphology is highly specialized for delivering genetic payload. It possesses a streamlined head containing the nucleus (genetic material), a midpiece packed with mitochondria for massive ATP energy generation, and a long flagellum (tail) to provide the necessary mechanical propulsion to swim toward the egg.","It is shaped like a leaf to absorb sunlight.","It has a thick cell wall to prevent movement."]',1,'It''s built like a tiny, self-propelled torpedo carrying half of a baby''s DNA!','Sperm cell: Helps in reproduction by carrying male genetic material. (Diagram shows a tail for swimming). Cells can look different because they are adapted to perform different functions.','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_036','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Synthesize the ecological impact if all ''Decomposer'' microorganisms were eradicated.','["The environment would become perfectly clean and smell nice.","Eradicating decomposers (like soil bacteria and fungi) would halt the global biogeochemical cycles. Dead organic matter (biomass) would accumulate infinitely without breaking down. More critically, the essential inorganic nutrients (nitrogen, phosphorus) locked within that dead matter would never be returned to the soil, ultimately starving all autotrophic plants and collapsing the entire food web.","Animals would instantly evolve to eat rocks instead.","Only the ocean would be affected, not the land."]',1,'Without these invisible recyclers, the world would be buried miles deep in dead trees, and nothing new could ever grow!','Decomposer microorganisms break down dead plants and animals. (Synthesis: What happens if this stops? The recycling system fails).','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_037','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Critique the student statement: ''An amoeba is less evolved and simpler than a human skin cell.''','["The statement is true; humans are always more evolved.","The statement represents a profound biological misunderstanding. While a human is a complex multicellular organism, a single human skin cell is highly specialized and relies entirely on the rest of the body to survive. An amoeba, however, is an incredibly versatile, self-sufficient organism; its single cell must independently perform *every* function necessary for life (hunting, digestion, respiration, reproduction).","The statement is true because amoebas have no nucleus.","The statement is false because an amoeba is actually a plant."]',1,'A skin cell is just a single brick in a house; an amoeba is the entire house packed into one cell!','Single-celled organisms... That cell performs all the necessary life functions. Multicellular organisms: Made of many cells that often specialise in different jobs.','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_038','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Evaluate the necessity of ''Chloroplasts'' in plant root cells.','["Root cells have the highest concentration of chloroplasts.","Root cells (like root hair cells) reside deep underground in complete darkness. Since chloroplasts utilize chlorophyll to capture photons for photosynthesis, they are biologically useless in an environment devoid of light. Therefore, root cells do not develop chloroplasts, relying instead on sugars transported downward from the photosynthetic leaves via the phloem.","Root cells use chloroplasts to absorb water.","Root cells use chloroplasts to scare away worms."]',1,'Why would you put a solar panel in a dark basement?','Root hair cell: Absorbs water and minerals... (No chloroplasts shown). Chloroplasts: Contain chlorophyll, which absorbs light for photosynthesis. (Synthesis: No light underground = no chloroplasts needed).','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_039','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Analyze the mathematical limitation of a single cell growing to the size of an elephant.','["Cells can easily grow that large if they eat enough.","A single cell cannot grow infinitely due to the Surface Area to Volume Ratio. As a cell grows, its internal volume increases exponentially faster than its surface area (membrane). Eventually, the cell membrane cannot absorb enough oxygen/nutrients or expel enough waste fast enough to sustain the massive internal volume, causing the cell to suffocate or poison itself.","The cell''s nucleus would get too heavy and sink.","The cell would float away into the sky."]',1,'If a cell gets too big, the ''doors'' (membrane) aren''t large enough to feed the giant ''room'' (volume) inside!','The basic unit of life... Cells are usually too small to see clearly... Multicellular organisms: Made of many cells... (Synthesis of *why* large organisms are multi-cellular rather than one giant cell).','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_040','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Synthesize how the concept of ''Gut Microorganisms'' (the microbiome) challenges the idea that a human is a single organism.','["Gut microorganisms prove that humans are actually plants.","The human body is an ecological symbiotic super-organism. We harbor trillions of non-human bacterial cells in our gastrointestinal tract. These microorganisms are not invaders; they are obligate mutualists that break down indigestible complex carbohydrates, synthesize essential vitamins (like Vitamin K), and regulate our immune system. Biologically, we rely on their alien DNA to survive.","Gut microorganisms mean humans are mostly made of viruses.","Gut microorganisms only exist when we are sick."]',1,'You aren''t just ''you''; you are a walking ecosystem containing billions of helpful bacteria that do jobs your own body can''t do!','Helpful microorganisms... Gut microorganisms help with digestion and other body functions. (Synthesis: They are separate organisms but essential to our life).','2026-11-01 09:17:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_041','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Critique the use of ''Antibiotics'' to cure a cold caused by a Virus.','["It is the best way to cure a cold quickly.","The use of antibiotics for a viral infection is a severe clinical error. Antibiotics are biochemical agents designed to disrupt specific metabolic pathways or structures unique to *Bacteria* (like bacterial cell walls or ribosomes). Because viruses are acellular and hijack human host cells to replicate, antibiotics have zero mechanism of action against them and only serve to promote dangerous antibiotic resistance in the body''s natural microbiome.","It works because viruses are just large bacteria.","It is dangerous because it causes the virus to grow faster."]',1,'Antibiotics destroy bacterial walls. A virus doesn''t have a wall; it hides inside your own cells!','Harmful microorganisms... Some bacteria cause diseases... Viruses cause diseases... generally not considered living organisms... (Synthesis linking to Topic 8: Antibiotics only work on bacteria).','2026-11-01 09:17:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_042','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Analyze the specific function of ''Cilia'' in a paramecium.','["They are used exclusively to sting predators.","Cilia are microscopic, hair-like projections that cover the cell membrane of a paramecium. Functionally, they act like hundreds of tiny oars, beating in a coordinated, wave-like motion. This not only provides rapid locomotion through the aquatic environment but also creates water currents to sweep food particles (like bacteria) directly into the organism''s oral groove.","They are used to absorb sunlight for photosynthesis.","They are used to attach the paramecium permanently to a rock."]',1,'Imagine hundreds of tiny oars rowing on a boat!','Paramecia: Single-celled organisms that move using tiny hair-like structures called cilia. (Synthesis: How they actually work for movement and feeding).','2026-11-01 09:17:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_043','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Evaluate the biological necessity of ''Yeast'' reproducing asexually via budding in a resource-rich environment (like bread dough).','["Budding is the only way yeast can survive freezing temperatures.","In a resource-rich, stable environment (like warm dough with abundant sugar), rapid population growth is the optimal evolutionary strategy. Asexual reproduction (budding) requires no mate and allows a single yeast cell to rapidly clone itself. This exponential proliferation maximizes the consumption of sugar and the production of carbon dioxide (fermentation), which is exactly what causes bread to rise.","Budding prevents the yeast from making the bread rise.","Budding turns the yeast into a multicellular organism."]',1,'When there''s plenty of food, the fastest way to multiply is just to clone yourself!','Yeasts: Microscopic fungi, some of which are used in baking... Helpful microorganisms: Yeast helps bread dough rise. (Synthesis of rapid reproduction and function).','2026-11-01 09:17:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_044','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Synthesize the impact of a chemical that destroys the ''Cell Membrane'' on both plant and animal cells.','["Only animal cells would die because plant cells have a cell wall.","While the plant cell possesses an external, rigid cell wall for structural support, destroying the cell membrane would be universally fatal to both plant and animal cells. The cell membrane is the obligate semi-permeable barrier controlling osmoregulation and nutrient intake. Without it, the cytoplasm would leak out, and toxic extracellular fluids would rush in, instantly terminating homeostasis.","Both cells would survive normally.","Only plant cells would die because animal cells are stronger."]',1,'The wall is just the physical structure; the membrane is the actual door that keeps the cell alive!','Cell membrane: The thin covering that controls what enters and leaves the cell. (Synthesis: It is universally essential, even if a wall is present).','2026-11-01 09:17:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_cells_global_045','Biology','Cells and Microscopic Life','Topic 9: Cells and Microscopic Life','Primary',10,'Critique the idea that ''Because bacteria are single-celled, they cannot communicate or work together.''','["The idea is an absolute biological fact.","This represents a misunderstanding of microbial ecology. While bacteria are single-celled, many species engage in highly sophisticated intercellular communication known as ''quorum sensing''. By secreting and detecting chemical signal molecules, bacterial populations can coordinate their behavior, allowing them to act collectively (e.g., forming biofilms or launching coordinated attacks on a host) much like a multicellular organism.","The idea is true because bacteria don''t have brains.","The idea is true because bacteria only live alone."]',1,'They don''t talk with words, but they use chemical signals to ''talk'' and coordinate with each other!','Bacteria: Single-celled organisms found in many environments. (Synthesis of advanced microbiological concepts).','2026-11-01 09:17:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_001','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What does ''reproduction'' mean in biology?','["When an animal goes to sleep.","The process by which living things produce babies or young (offspring).","When a plant makes food.","When an animal moves to a new home."]',1,'It means making a new generation!','Reproduction is the biological process by which living things produce offspring of their own kind.','2026-11-01 09:17:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_002','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What is ''offspring''?','["The food a plant makes.","The young or new organisms produced by parents (like babies, kittens, or seeds).","The leaves on a tree.","The shell of an egg."]',1,'It is the scientific word for babies!','Offspring are the young or new organisms produced by parents.','2026-11-01 09:17:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_003','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'Why do living things need to reproduce?','["So they can grow taller.","So they can run faster.","To ensure that their species continues to exist over generations, even after older individuals die.","To help them sleep better."]',2,'If animals didn''t have babies, their kind would disappear forever!','Reproduction helps ensure that a species continues to exist over generations. Important: Individual living things do not live forever.','2026-11-01 09:17:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_004','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What part of a flowering plant is usually responsible for reproduction?','["The roots","The stem","The flower","The leaves"]',2,'It is the beautiful, colorful part!','Many flowering plants reproduce through flowers, which contain their reproductive structures.','2026-11-01 09:17:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_005','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What do the colorful ''petals'' on a flower do?','["They absorb water.","They make the plant heavy.","They are often brightly coloured and help attract pollinators (like bees and butterflies).","They turn into roots."]',2,'They act like a bright sign saying ''Free Food Here'' to insects!','Petals: Often brightly coloured and help attract pollinators.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_006','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What is ''pollen''?','["Water inside the plant.","A yellow dust that contains the male reproductive cells of flowering plants.","The green part of the leaf.","The hard shell of a seed."]',1,'It''s the yellow dust you often see on flowers.','Pollen: Contains the male reproductive cells of flowering plants','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_007','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What is ''pollination''?','["When a seed starts to grow.","When pollen is transferred from the anther to the stigma of a flower.","When a fruit falls off a tree.","When a plant dies."]',1,'It happens when a bee moves the yellow dust from one part to another!','Pollination is the transfer of pollen from an anther to a stigma.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_008','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'How does wind help some plants reproduce?','["It breaks the stems.","It carries pollen from one flower to another.","It gives the plant energy to make food.","It freezes the plant."]',1,'Some plants don''t need bees; they just let the breeze blow their pollen away!','Wind pollination: Wind carries pollen from one flower to another.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_009','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'After a flower is pollinated and fertilised, what does the ovule turn into?','["A root","A petal","A seed","A leaf"]',2,'It turns into the tiny package that can grow into a new plant.','After fertilisation: The fertilised ovule develops into a seed.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_010','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What happens to the ''ovary'' of a flower after fertilisation?','["It disappears completely.","It turns into a root.","It often develops into a fruit (like a tomato or apple) to protect the seeds.","It turns into a leaf."]',2,'The fruit you eat used to be the bottom part of a flower!','After fertilisation: ... The ovary often develops into a fruit.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_011','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What is ''seed dispersal''?','["When a seed is eaten and destroyed.","When seeds are spread away from the parent plant to grow in new places.","When a seed turns into a rock.","When a plant stops growing."]',1,'It''s how plants ''travel'' to find a new home!','Seed dispersal is the spreading of seeds away from the parent plant.','2026-11-01 09:17:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_012','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'How do dandelions disperse (spread) their seeds?','["They float on water.","They burst open like a pea pod.","Their light, fluffy seeds are carried through the air by the wind.","They wait for animals to eat them."]',2,'You can blow on them to help them fly!','By wind: Light seeds or seeds with wings or fluffy hairs can travel through the air. Example: Dandelion.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_013','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What is ''germination''?','["When a flower opens.","When an animal lays an egg.","The process by which a seed begins to grow into a new plant (sprouting).","When a plant dies in the winter."]',2,'It''s when the seed ''wakes up''!','Germination is the process by which a seed begins to grow into a new plant.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_014','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'What three things do most seeds need to begin germinating?','["Soil, fertilizer, and rocks.","Water, oxygen, and a suitable temperature.","Darkness, cold, and snow.","Juice, dirt, and wind."]',1,'They need a drink, some air, and to be warm enough!','What does a seed need to germinate? Most seeds need: Water... Oxygen... A suitable temperature...','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_015','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',1,'How does a frog reproduce?','["It gives birth to live babies.","It lays eggs in water or moist places.","It splits in half.","It grows from a seed."]',1,'They lay squishy eggs in the pond!','Frog life cycle... Eggs are laid in water by many frog species.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_016','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is the difference between the ''stamen'' and the ''pistil'' in a flower?','["They are the exact same thing.","The stamen is the male part that produces pollen; the pistil is the female part that receives pollen and contains the eggs.","The stamen is a leaf, the pistil is a root.","The stamen makes fruit, the pistil makes seeds."]',1,'One makes the ''boy'' cells, the other holds the ''girl'' cells!','Stamen: The male reproductive part of a flower... Pistil (carpel): The female reproductive part.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_017','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'Why is ''pollination'' NOT the same thing as ''fertilisation''?','["They are exactly the same.","Pollination is just the delivery of pollen; fertilisation is the actual joining of the male and female cells inside the flower.","Pollination happens in animals, fertilisation happens in plants.","Pollination is done by wind, fertilisation is done by bees."]',1,'Pollination is the mailman dropping off the letter; fertilisation is reading it!','Pollination is an important step in reproduction, but it is not the same as fertilisation. Fertilisation is the joining of a male reproductive cell with a female egg cell.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_018','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'Why is ''seed dispersal'' (spreading seeds far away) so important for a plant''s survival?','["Because seeds look ugly near the parent.","Because it reduces competition for light, water, and nutrients between the baby plants and the parent plant.","Because seeds need to travel to the ocean to grow.","Because seeds will explode if they stay close."]',1,'If 100 seeds grow right under the mother tree, they will all fight for the same sunlight and water!','Dispersal helps plants grow in new places and reduces competition for light, water, nutrients and space.','2026-11-01 09:17:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_019','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'How do some animals help plants with seed dispersal WITHOUT meaning to?','["They water the plants.","They sing to the plants.","Seeds with little hooks can attach to an animal''s fur as it walks by, falling off later in a new location.","They cut the plants down."]',2,'Have you ever found prickly burrs stuck to your socks after walking in tall grass? That''s seed dispersal!','By animals: ... Some seeds also attach to animal fur.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_020','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'Does a seed ALWAYS need sunlight to START germinating?','["Yes, seeds will never grow without light.","No, most seeds do not need light to begin germinating (they start underground), but the young plant will need light soon after it emerges.","Yes, sunlight is the only thing they need.","No, light kills all seeds instantly."]',1,'They wake up in the dark dirt, but they need the sun once they reach the surface!','Most seeds do not need light to begin germinating, although the young plant usually needs light after it starts growing.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_021','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is ''asexual reproduction'' in plants?','["When a plant reproduces using pollen and seeds.","When a plant produces new plants from parts of the parent (like a stem or root) without needing pollen or eggs.","When a plant dies.","When a plant turns into an animal."]',1,'It''s like cutting a piece off a plant and growing a whole new clone from it!','Some can reproduce asexually, producing new plants from parts of the parent plant... This is called asexual reproduction because it does not require the joining of male and female reproductive cells.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_022','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is a ''runner'' (like on a strawberry plant)?','["An insect that runs very fast.","A horizontal stem that grows along the ground and can produce a new plant.","A type of root that digs deep.","A flower that falls off."]',1,'It''s like the plant reaches its ''arm'' out to start a new plant nearby!','Runners: Strawberry plants can produce new plants from horizontal stems.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_023','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is ''metamorphosis'' in the life cycle of a frog or butterfly?','["When they go to sleep for the winter.","A major, dramatic change in body form as the animal develops from a young stage (like a tadpole or caterpillar) into an adult.","When they change color to hide.","When they learn to fly."]',1,'A caterpillar turning into a butterfly is an incredible transformation!','Metamorphosis: A major change in body form during development.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_024','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'In a butterfly''s life cycle, what happens during the ''pupa'' (chrysalis) stage?','["The insect flies around eating.","The insect lays eggs.","The insect undergoes major changes inside a protective shell to become an adult.","The insect swims in the water."]',2,'It looks like it''s resting, but inside, its whole body is changing shape!','Pupa (chrysalis): The insect changes form... The insect undergoes major changes inside the protective pupal stage as adult structures develop.','2026-11-01 09:17:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_025','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is the difference between ''internal'' and ''external'' fertilisation in animals?','["Internal means inside the body (like mammals); external means outside the body (like many fish laying eggs in the water).","Internal means outside the body, external means inside.","Internal is for plants, external is for animals.","There is no difference."]',0,'Fish often just spray their eggs and cells into the water to mix!','Fertilisation can be internal, inside the body, or external, outside the body. Many fish and amphibians use external fertilisation...','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_026','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'Do all animals take care of their babies?','["Yes, every animal protects its babies for years.","No, some animals (like birds and mammals) provide extensive care, while others (like sea turtles) leave their eggs and provide no care.","Yes, but only for one day.","No, animals never care for their young."]',1,'A mother bear will fight to protect her cubs, but a sea turtle mother swims away forever after laying her eggs.','Parental care in animals: Some animals protect, feed or care for their young. Others provide little or no care after laying eggs... Sea turtles usually leave their eggs buried in sand...','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_027','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What does an ''embryo'' mean in both plants and animals?','["An old, dying organism.","The hard shell on the outside.","An early developing organism (the tiny baby plant inside a seed, or the baby animal inside an egg/mother).","The food stored inside."]',2,'It''s the very earliest stage of a new life!','Embryo: An early developing organism. (The seed contains an embryo, which is a young developing plant... An embryo develops inside a fertilised egg).','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_028','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'How do ferns and mosses reproduce since they don''t have flowers or seeds?','["They lay eggs.","They use microscopic structures called ''spores''.","They split in half.","They don''t reproduce at all."]',1,'They use a much older, simpler way to make new plants!','Ferns and mosses reproduce using spores rather than seeds.','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_029','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'In the bean seed experiment, what usually emerges (comes out) from the seed FIRST?','["The leaves","The flower","The root, which grows downwards.","The stem"]',2,'The plant needs an anchor and water first, before it tries to reach for the sun!','Stages of germination... 3. The root emerges and grows downwards. 4. The shoot grows upwards.','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_030','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',5,'What is a ''tuber'' (like a potato)?','["A fruit that grows on a tree.","An underground plant part that can grow a new plant from buds called ''eyes''.","A type of seed.","A flower petal."]',1,'If you leave a potato in the cupboard too long, you''ll see it start to grow new stems!','Tubers: A potato can grow from buds called eyes on its tuber.','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_031','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Critique the assertion that ''Plants only reproduce sexually through flowers and pollination.''','["The assertion is scientifically accurate.","The assertion is false. While many angiosperms use sexual reproduction (flowers/seeds), many plants also utilize powerful methods of *asexual* vegetative reproduction (runners, tubers, bulbs, cuttings). These methods allow plants to clone themselves rapidly without the need for pollination or fertilisation.","The assertion is true because asexual reproduction only happens in animals.","The assertion is true because non-flowering plants cannot reproduce."]',1,'Plants have a backup plan! If there are no bees to pollinate their flowers, many can just clone themselves from a root or a stem.','Not all plants reproduce using seeds. Some can reproduce asexually, producing new plants from parts of the parent plant... This is called asexual reproduction...','2026-11-01 09:17:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_032','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Analyze the specific physiological function of the ''Pollen Tube'' during plant fertilisation.','["It acts as a straw to drink water.","Once compatible pollen lands on the stigma, it must physically reach the ovule hidden deep inside the ovary. The pollen grain germinates and grows a microscopic conduit (the pollen tube) all the way down the style. This tube provides a protected pathway for the male gamete to travel and successfully fuse with the egg cell.","It shoots the pollen into the air.","It protects the petals from falling off."]',1,'The pollen can''t just fall into the egg; it has to drill a microscopic tunnel all the way down to deliver its payload!','After compatible pollen lands on the stigma, it can grow a pollen tube down through the style towards an ovule. A male reproductive cell travels through this tube and joins with the egg cell.','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_033','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Synthesize the evolutionary advantage of ''Fruit'' development in Angiosperms (flowering plants).','["Fruit makes the plant heavier so it won''t blow away.","The fleshy ovary (fruit) is an evolutionary adaptation for endozoochory (animal-mediated seed dispersal). By investing energy into sweet, nutritious flesh, the plant incentivizes animals to consume the fruit. The indigestible seeds safely pass through the animal''s digestive tract and are deposited far away, often with a starter packet of fertilizer.","Fruit is designed to kill the seeds.","Fruit acts as a shield against the sun."]',1,'The plant makes a tasty treat on purpose so animals will do the hard work of carrying its babies (seeds) to a new home!','The ovary often develops into a fruit. By animals: Animals may eat fruits and later release seeds in their droppings.','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_034','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Evaluate the biological requirement of ''Oxygen'' during Seed Germination.','["Seeds do not need oxygen until they have leaves.","Before a seedling emerges and can photosynthesize, it must rely entirely on the metabolic breakdown of its stored endosperm (food). This cellular respiration requires oxygen to oxidize the stored carbohydrates and synthesize the ATP (energy) needed to fuel the massive cellular division of early growth.","Oxygen prevents the seed from growing too fast.","Oxygen turns the seed coat into sugar."]',1,'Just like you need oxygen to burn calories for energy, the seed needs oxygen to ''burn'' its stored food to get the energy to sprout!','What does a seed need to germinate? ... Oxygen: Needed for respiration to release energy.','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_035','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Analyze the ecological strategy of ''External Fertilisation'' used by many amphibians and fish.','["It ensures every single egg survives to adulthood.","External fertilisation involves releasing thousands or millions of gametes simultaneously into an aquatic environment (spawning). While the mortality rate of the unprotected zygotes is astronomical (due to predation and environmental hazards), the sheer volume of eggs ensures that at least a few will statistically survive to adulthood without requiring energy-intensive parental care.","It is a strategy used by mammals in the desert.","It requires the parents to protect the eggs inside their bodies."]',1,'They don''t protect their babies, so they just make thousands of them and hope a few survive the hungry fish!','Fertilisation can be internal... or external, outside the body. Many fish and amphibians use external fertilisation... Parental care: ... Others provide little or no care after laying eggs.','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_036','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Synthesize the difference in genetic diversity between sexual reproduction (seeds) and asexual reproduction (runners).','["Asexual reproduction creates more genetic diversity.","Sexual reproduction (pollination/fertilisation) combines genetic material from two distinct parents, creating unique offspring with high genetic diversity (crucial for adapting to diseases or changing environments). Asexual reproduction (runners/tubers) is essentially cloning; it produces offspring genetically identical to the single parent, offering zero new genetic diversity.","There is no difference in genetic diversity.","Sexual reproduction produces exact clones."]',1,'If a disease can kill the parent plant, it will also kill all of its identical clones. Mixing DNA makes stronger, more adaptable offspring!','Asexual reproduction... The new plants are usually genetically very similar to the parent. Sexual reproduction, involving male and female reproductive cells... (Synthesis: mixing two parents creates variety; cloning does not).','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_037','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Critique the student statement: ''A caterpillar and a butterfly are two completely different species that live together.''','["The statement is ecologically accurate.","The statement represents a profound misunderstanding of complete metamorphosis. A caterpillar (larva) and a butterfly (adult) are the exact same organism (same species, same DNA) at different stages of its ontogenetic development. The radical morphological shift allows the single organism to exploit different ecological niches across its lifespan.","The statement is true because caterpillars lay eggs.","The statement is true because butterflies are birds."]',1,'It''s not two different bugs; it''s the exact same bug that completely rebuilt its own body inside a shell!','This process is called complete metamorphosis. (It is a life cycle of ONE organism, not two species).','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_038','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Evaluate the physiological transition an Amphibian (like a frog) must undergo during Metamorphosis.','["The frog simply grows larger in size.","Metamorphosis requires a total systemic overhaul to transition from an aquatic to a terrestrial lifestyle. The organism must resorb its tail via apoptosis, develop an appendicular skeleton (legs) for land locomotion, and most critically, transition its respiratory system from extracting dissolved oxygen via gills to extracting atmospheric oxygen via newly formed lungs.","The frog turns into a fish.","The frog grows a hard shell."]',1,'It has to completely rebuild its breathing system and grow legs while it is still alive and swimming!','Tadpoles: ... live in water and have tails. Tadpoles with legs: ... Lungs develop as the animal changes. Froglets: ... the tail becomes smaller as it is absorbed.','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_039','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Analyze the function of the ''Cotyledon'' (seed leaves) during the early growth of a bean plant.','["They are the true leaves that perform photosynthesis instantly.","The cotyledons are the embryonic first leaves. In dicots like beans, they primarily serve as massive storage organs for endosperm (nutrients). When the seed germinates in the dark soil, the cotyledons provide all the metabolic fuel required for the shoot to breach the surface. They wither and fall off once the ''true leaves'' develop and begin photosynthesis.","They are the roots that absorb water.","They form the hard outer shell of the plant."]',1,'Before the plant reaches the sun to make its own food, it has to pack a ''lunchbox'' (the cotyledons) to give it the energy to dig its way out of the dirt!','A seed contains stored food that supports early growth... (Synthesis with the provided diagram showing ''seed leaves'' (lower) vs ''true leaves'').','2026-11-01 09:17:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_040','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Synthesize why ''Parental Care'' is an evolutionary trade-off in animal reproduction.','["Parental care is always the best strategy for every animal.","Parental care represents a massive energetic and survival cost to the parent, leading them to produce very few offspring (K-selection). The trade-off is that these few offspring have a drastically higher survival rate due to protection and nourishment (e.g., mammals/milk). Conversely, species with zero parental care (r-selection) must produce millions of offspring to ensure statistical survival.","Parental care means the parents eat their young.","Parental care requires animals to lay millions of eggs."]',1,'You can either spend all your energy raising one baby perfectly, or spend that energy making 10,000 babies and just leaving them on the beach!','Parental care can improve the chances that offspring survive, but different animals have different reproductive strategies. (Synthesis: Few babies + high care vs. Many babies + zero care).','2026-11-01 09:17:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_repro_global_041','Biology','Reproduction in Plants and Animals','Topic 10: Reproduction in Plants and Animals','Primary',10,'Critique the classification of a ''Spore'' as simply a tiny seed.','["Spores and seeds are biologically identical.","While both function as reproductive dispersal units, they are biologically distinct. A seed is a complex, multicellular structure resulting from sexual reproduction, containing a diploid embryo and a protective food supply. A spore is typically a microscopic, single-celled, haploid unit capable of developing into a new organism without fusion, representing a much older, simpler evolutionary strategy.","Spores only grow into animals, not plants.","Spores are much larger than seeds."]',1,'A seed is a highly advanced survival pod with a baby plant and a packed lunch inside. A spore is just a single, tough cell.','Ferns and mosses reproduce using spores rather than seeds. (Synthesis: Seeds are complex with embryos and stored food; spores are simple).','2026-11-01 09:17:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_001','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What does a ''food chain'' show?','["How animals build their homes.","A sequence showing how energy and nutrients pass from one organism to another when they eat each other.","How plants drink water.","How long an animal lives."]',1,'It shows who eats who!','A food chain is a sequence showing how energy and nutrients pass from one organism to another when organisms eat one another.','2026-11-01 09:17:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_002','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What is a ''producer''?','["An animal that hunts other animals.","An organism that makes its own food, usually using sunlight.","An animal that only eats meat.","A mushroom."]',1,'Plants are producers because they produce their own food.','A producer is an organism that makes its own food, usually through photosynthesis.','2026-11-01 09:17:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_003','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'Which of these is an example of a producer?','["A snake","Grass or a tree","A lion","A rabbit"]',1,'It has to be something that makes its own food using the sun!','Producers: Examples include: Green grasses. Trees and flowering plants.','2026-11-01 09:17:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_004','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What is a ''consumer'' in a food chain?','["A plant that makes its own food.","An organism that obtains energy by eating plants, animals, or other organisms.","The sun.","Dirt."]',1,'Animals are consumers because they must consume (eat) their food.','A consumer is an organism that obtains energy by eating plants, animals or other organisms.','2026-11-01 09:17:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_005','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What do we call an animal that only eats plants?','["Carnivore","Herbivore","Omnivore","Decomposer"]',1,'Rabbits and cows are examples.','Herbivores: Animals that eat plants or other plant material.','2026-11-01 09:17:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_006','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What do we call an animal that only eats other animals (meat)?','["Omnivore","Herbivore","Producer","Carnivore"]',3,'Lions and snakes are examples.','Carnivores: Animals that eat other animals.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_007','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What do we call an animal that eats BOTH plants and animals?','["Omnivore","Herbivore","Carnivore","Producer"]',0,'Humans and bears are examples.','Omnivores: Animals that eat both plant and animal material.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_008','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'In a food chain, what do the arrows show?','["Which way the wind is blowing.","The direction that energy is moving (from the organism being eaten to the organism that eats it).","How fast the animal runs.","Who is the strongest."]',1,'The arrow points to the mouth of the eater!','The arrows point from the organism being eaten to the organism that eats it. They show the direction in which energy is transferred.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_009','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'If the food chain is: Grass → Grasshopper → Frog, who gets energy from the grass?','["The frog","The grasshopper","The sun","No one"]',1,'The grasshopper eats the grass, so the energy goes to the grasshopper.','The arrows point from the organism being eaten to the organism that eats it... The grasshopper eats the grass.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_010','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What is a ''predator''?','["An animal that is hunted and eaten.","A plant that catches bugs.","An animal that hunts and eats other animals.","An animal that only eats grass."]',2,'A hawk hunting a mouse is a predator.','A predator is an animal that hunts and eats another animal.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_011','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What is ''prey''?','["An animal that hunts.","An animal that is hunted and eaten by a predator.","A type of plant.","An animal that eats both plants and animals."]',1,'The mouse being chased by the hawk is the prey.','Prey is an animal that is hunted and eaten by a predator.','2026-11-01 09:17:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_012','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What does a ''food web'' show?','["Just one single line of animals eating each other.","A network of many connected food chains in an ecosystem.","How spiders build webs to catch food.","Only what plants eat."]',1,'It''s like a messy spider web of many different food chains mixed together!','A food web is a network of interconnected food chains in an ecosystem.','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_013','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'Where does almost all the energy in a food chain originally come from?','["The dirt","The ocean","The Sun","The moon"]',2,'The plants use it to make the first food!','Most food chains begin with energy from the Sun.','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_014','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'What is a ''decomposer''?','["An animal that runs very fast.","An organism (like fungi or bacteria) that breaks down dead organisms and waste to recycle nutrients.","An animal that hunts other animals.","A plant that makes food."]',1,'They are nature''s recyclers and garbage collectors!','Decomposers break down dead organisms and organic waste, returning nutrients to the environment.','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_015','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',1,'Which of these is an example of a decomposer?','["A lion","A grasshopper","Fungi (mushrooms) and bacteria","A rabbit"]',2,'They break down dead logs and leaves in the forest.','Examples [of decomposers] include: Fungi... Bacteria...','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_016','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'Why is a food web a more realistic picture of nature than a single food chain?','["Because food chains are too long to draw.","Because in nature, most organisms eat more than one type of food, and are eaten by several different predators, creating a complex network.","Because food webs only include plants.","Because food chains don''t use arrows."]',1,'Animals don''t eat just one thing; a frog might eat a fly, a grasshopper, or a worm!','Most organisms eat more than one type of food, and many are eaten by several different predators. A food web shows these relationships more realistically than a single food chain.','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_017','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'In the food chain (Grass → Grasshopper → Frog → Snake), what role does the frog play?','["Producer","Primary consumer","Secondary consumer","Decomposer"]',2,'It is the second animal in the line of eaters.','Grass (Producer) -> Grasshopper (Primary consumer) -> Frog (Secondary consumer).','2026-11-01 09:17:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_018','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'What would likely happen to the population of frogs if all the snakes were removed from the ecosystem?','["The frog population would likely decrease.","The frog population would likely increase because they have no predators eating them.","The frog population would instantly turn into snakes.","Nothing would happen."]',1,'Without snakes to eat them, the frogs would multiply quickly!','Changes to one population may affect other populations... (Synthesis: If the predator is gone, the prey numbers go up).','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_019','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'Why are decomposers absolutely essential for a healthy ecosystem?','["They provide sunlight to the plants.","They hunt the apex predators.","They break down dead organic matter, releasing trapped nutrients back into the soil so producers (plants) can use them again to grow.","They turn rocks into soil."]',2,'If they didn''t do their job, the world would be buried in dead trees and the dirt would run out of nutrients!','Why are decomposers important? ... Nutrients are released into the soil or water. Plants absorb available nutrients... Without decomposition, dead organic material would accumulate...','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_020','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'What is ''phytoplankton'' in an ocean food web?','["A large predatory fish.","A type of microscopic aquatic producer that makes its own food using sunlight.","A decomposer that lives on the ocean floor.","A mammal that breathes air."]',1,'They are the tiny, floating ''plants'' that form the base of the ocean food chain!','Producers: Examples include... Phytoplankton in aquatic environments.','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_021','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'Why do food chains usually only have a few feeding levels (e.g., usually stopping after 4 or 5 organisms)?','["Because animals get too big to eat.","Because less energy is available at each higher level, since organisms use up or lose energy as heat before they are eaten.","Because there are not enough plants in the world.","Because predators don''t like the taste of other predators."]',1,'By the time the energy gets to the top predator, there is very little left!','At each feeding level, organisms use much of the energy... Some energy is released as heat... Therefore, less energy is generally available to organisms at higher feeding levels. This is one reason food chains usually contain only a limited number of feeding levels.','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_022','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'Can an animal be both a predator AND prey?','["No, animals are strictly one or the other.","Yes, a frog can be a predator when it eats a grasshopper, but it is prey when a snake eats it.","Yes, but only if it is a producer.","No, being prey means it can never eat."]',1,'In the middle of the food chain, you have to hunt while watching your own back!','A frog may be a predator of an insect. A frog may also be prey for a snake.','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_023','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'What is a ''primary consumer''?','["The top predator in the food chain.","The sun.","The first animal in the food chain that eats the producer (a herbivore).","An animal that eats dead things."]',2,'It''s the first ''eater'' in the chain, which means it has to eat plants!','Grasshopper - Primary consumer... Primary consumers eat producers.','2026-11-01 09:17:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_024','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'In a forest food web, if a disease kills all the rabbits, how might this affect the hawks?','["The hawks would start eating grass.","The hawks would have less food and their population might decrease, or they might be forced to hunt more mice.","The hawks would turn into rabbits.","The hawks would not be affected at all."]',1,'If a predator loses its favorite food, it will struggle to survive unless it finds something else to eat!','The connections mean that a change in one population can affect several other populations... (Synthesis: Hawks eat rabbits, so less food = harder to survive).','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_025','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'What is a ''detritivore''?','["A type of plant.","An animal (like an earthworm) that eats dead organic material and helps break it into smaller pieces for decomposers.","A top predator like a lion.","A microscopic bacteria."]',1,'They are the garbage-eating animals that help the bacteria and fungi do their job!','Detritivores: Animals such as earthworms eat dead organic material and help break it into smaller pieces.','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_026','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'How does energy enter a deep-sea ecosystem where there is absolutely no sunlight?','["Through the wind.","Through ''chemosynthesis'', where producers use chemical processes instead of sunlight to make food.","The animals don''t need energy down there.","They eat rocks."]',1,'In the pitch-black deep ocean, special bacteria use chemicals from underwater volcanoes to make food!','Not all ecosystems depend on sunlight in the same way. Some deep-sea ecosystems receive energy from chemical processes such as chemosynthesis.','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_027','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'What does the arrow represent in this food chain: Algae → Small fish?','["The fish is turning into algae.","The algae is eating the fish.","Energy is transferring from the algae into the small fish when the fish eats it.","The algae and fish are friends."]',2,'The arrow shows the path the energy travels!','The arrows point from the organism being eaten to the organism that eats it. They show the direction in which energy is transferred.','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_028','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'If a human eats a salad with chicken in it, what two feeding positions are they occupying?','["Producer and Decomposer","Primary consumer (eating plants) and Secondary consumer (eating the chicken that ate plants).","Predator and Prey","Only Primary consumer"]',1,'Because humans are omnivores, they play multiple roles in the food web at the same time!','Primary consumers eat producers. Secondary consumers eat primary consumers. (Synthesis: Humans are omnivores eating a producer (salad) and a primary consumer (chicken)).','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_029','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'How can applying a chemical pesticide to kill insects accidentally harm birds?','["It makes the birds grow too fast.","If the birds rely on those insects for food, killing the insects takes away the birds'' food source.","The birds will start eating plants.","The birds will become producers."]',1,'Everything is connected; poisoning the bottom of the food chain starves the top!','Similarly, if a pesticide kills many insects, insect-eating animals may lose an important food source.','2026-11-01 09:17:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_030','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',5,'Why is ''biodiversity'' important for a food web?','["It means there is only one type of plant.","Having many different connected species makes the web stronger; if one food source dies, a predator has other options to eat.","It makes the food web weaker and easier to break.","It turns consumers into producers."]',1,'Don''t put all your eggs in one basket! A predator with five types of prey won''t starve if one type of prey disappears.','Healthy habitats support food webs and biodiversity... The connections mean that a change in one population can affect several other populations. (Synthesis: more connections = more stability).','2026-11-01 09:17:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_031','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Critique the assertion that ''Decomposers are consumers that simply eat dead things instead of living things.''','["The assertion is scientifically perfect.","The assertion conflates two distinct ecological roles. While both are heterotrophs, consumers ingest organic matter internally. Decomposers (saprotrophs like fungi) secrete extracellular enzymes into the environment to digest organic matter externally, then absorb the resulting simple inorganic nutrients, crucially recycling elements (N, P) back into the soil matrix.","The assertion is true because fungi have mouths.","The assertion is false because decomposers are actually producers."]',1,'A vulture (consumer) eats dead meat, but a fungus (decomposer) chemically dissolves a dead tree to turn it back into basic dirt!','Decomposers break down dead organisms and organic waste, returning nutrients to the environment... Plants absorb available nutrients through their roots. (Synthesis of their specific biochemical recycling role).','2026-11-01 09:17:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_032','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Analyze the thermodynamic principle underlying the fact that ''less energy is generally available to organisms at higher feeding levels.''','["Energy is destroyed at each level.","This illustrates the 10% Rule based on the Second Law of Thermodynamics. When a consumer ingests prey, the vast majority of the caloric energy (approx. 90%) was already utilized by the prey for metabolic processes (respiration, movement) or is lost as dissipated heat (entropy). Only the tiny fraction converted into the prey''s actual biomass is transferred upward.","Energy magically disappears in the stomach.","Predators do not need as much energy to survive."]',1,'The grasshopper burns most of the energy it gets from the grass just hopping around! The frog only gets what''s left over in the grasshopper''s body.','At each feeding level, organisms use much of the energy they obtain for movement, growth, respiration... Some energy is released as heat... Therefore, less energy is generally available... (Synthesis with thermodynamics).','2026-11-01 09:17:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_033','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Synthesize the potential ecological impact of removing an Apex Predator (like a wolf) from a forest food web.','["The forest will instantly burst into flames.","Removing an apex predator causes a ''trophic cascade.'' Without predatory regulation, primary consumer populations (e.g., deer) will explode. This overpopulation leads to severe overgrazing, destroying the producer base (plants/forest understory), which ultimately leads to mass starvation for the herbivores and the total collapse of the ecosystem''s biodiversity.","The herbivores will turn into carnivores to replace the wolves.","The ecosystem will become much healthier and more stable."]',1,'Without wolves, the deer eat all the grass. Without grass, the deer starve, and the forest dies!','Predators can help regulate prey populations... Changes to one species can affect several other species in an ecosystem... (Synthesis: removing the regulator collapses the system).','2026-11-01 09:17:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_034','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Evaluate the ecological classification of an organism that performs ''Chemosynthesis''.','["It is a primary consumer because it eats chemicals.","An organism performing chemosynthesis is classified as an autotrophic Producer. Rather than transducing solar photon energy (photosynthesis), it extracts energy from the oxidation of inorganic molecules (like hydrogen sulfide at deep-sea hydrothermal vents) to synthesize organic carbon compounds, forming the foundational energy base for entirely aphotic (lightless) food webs.","It is a decomposer because it lives in the dark.","It is a predator that hunts using poison."]',1,'Down where the sun doesn''t shine, these special bacteria are the ''plants'' of the deep ocean!','Not all ecosystems depend on sunlight in the same way. Some deep-sea ecosystems receive energy from chemical processes such as chemosynthesis. (Synthesis: They are the producers of the deep).','2026-11-01 09:17:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_035','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Analyze the directional flow of ''Nutrients'' versus ''Energy'' in an ecosystem.','["They both flow in a straight line and eventually disappear.","While Energy flows linearly (unidirectionally) through the trophic levels and is continuously lost from the system as dissipated heat, Nutrients (matter) are cyclical. Nutrients are absorbed by producers, passed to consumers, and continuously recycled back into the abiotic environment by decomposers, creating a closed biogeochemical loop.","They both flow backward from predator to producer.","Nutrients are lost as heat, while energy is recycled."]',1,'Energy gets ''used up'' and lost as heat, but the physical atoms of carbon and nitrogen are recycled over and over again forever!','Energy flow: The transfer of energy... Nutrient recycling: The return of nutrients to the environment for reuse. (Synthesis: Energy flows, Nutrients cycle).','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_036','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Synthesize the biological consequence of ''Bioaccumulation'' in a food chain.','["Toxins are completely destroyed by apex predators.","Because biomass drastically decreases at higher trophic levels (the 10% rule), stable environmental toxins (like heavy metals or certain pesticides) become concentrated. A primary consumer eats contaminated plants, and a secondary consumer must eat hundreds of those primary consumers to survive, exponentially magnifying the toxin concentration in the apex predator''s tissues.","Toxins only affect the producers.","Toxins make the predators grow much faster."]',1,'Because a hawk has to eat 100 mice to survive, it also eats 100 times the amount of poison that was inside those mice!','If a pesticide kills many insects... (Synthesis connecting energy loss to toxin concentration).','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_037','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Critique the statement: ''Omnivores always occupy the secondary consumer level in a food web.''','["The statement is ecologically accurate.","The statement is rigid and false. Because food webs are dynamic networks, an omnivore occupies multiple trophic levels simultaneously depending on its immediate diet. When a bear eats berries, it functions as a primary consumer; when it eats a salmon (which ate smaller fish), it functions as a tertiary consumer in the exact same ecosystem.","The statement is true because omnivores only eat plants.","The statement is true because omnivores are apex predators."]',1,'A bear''s ''job title'' in the food web changes depending on whether it''s eating a salad or a fish!','Omnivores: Animals that eat both plant and animal material... Consumers may occupy different positions... These terms describe feeding positions, not fixed types of animals. An animal may occupy different positions depending on what it eats.','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_038','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Evaluate the ecological vulnerability of an ecosystem with extremely low biodiversity (a simple food chain) versus a complex food web.','["Low biodiversity makes the ecosystem stronger and faster.","Ecosystems with low biodiversity lack ecological redundancy. In a simple linear food chain, if one species is extirpated by disease or environmental change, the entire chain collapses. High biodiversity (a complex web) provides resilience; if one prey species declines, predators can shift their foraging pressure to alternative, interconnected nodes, stabilizing the ecosystem.","Low biodiversity means there are too many predators.","There is no difference in vulnerability."]',1,'If your only food source dies, you die. If you have ten different food sources, you just eat something else!','Most organisms eat more than one type of food... The connections mean that a change in one population can affect several other populations... Healthy habitats support food webs and biodiversity. (Synthesis: Complexity = Stability).','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_039','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Analyze the role of ''Phytoplankton'' in the global carbon cycle.','["They only produce carbon dioxide, harming the ocean.","Phytoplankton are massive aquatic autotrophs (producers). Through high-rate photosynthesis, they act as one of the Earth''s primary carbon sinks. They sequester dissolved atmospheric \\\\(CO_2\\\\) into organic biomass, forming the base of the marine food web, and release immense quantities of oxygen (\\\\(O_2\\\\)) as a metabolic byproduct, critically regulating the global climate.","They only consume other fish, ignoring carbon entirely.","They sink to the bottom and turn into rocks instantly."]',1,'These microscopic floating plants produce a massive amount of the oxygen you breathe every day!','Producers: ... Phytoplankton in aquatic environments. During photosynthesis, plants use... carbon dioxide to produce sugars and release oxygen. (Synthesis applied to ocean scale).','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_040','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Synthesize how the concept of ''Carrying Capacity'' is driven by the base of the food web.','["Carrying capacity is driven solely by how many predators exist.","Carrying capacity is the maximum population an ecosystem can sustain. Because of the thermodynamic loss of energy between trophic levels, the total biomass of apex predators is strictly limited by the total energy captured by the Producers (plants/algae) at the base. If the producer base shrinks (e.g., due to drought), the carrying capacity of all subsequent consumer levels crashes.","Carrying capacity has nothing to do with food webs.","Carrying capacity is determined by the size of the animals."]',1,'You can''t support 100 lions on a tiny patch of grass, because there won''t be enough grass to feed the zebras the lions need to eat!','Producers provide the energy-rich food that supports many other organisms... less energy is generally available to organisms at higher feeding levels. (Synthesis: The bottom limits the top).','2026-11-01 09:18:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_foodweb_global_041','Biology','Food Chains and Food Webs','Topic 11: Food Chains and Food Webs','Primary',10,'Critique the classification of a ''Venus Flytrap'' within a food web.','["It is strictly a consumer because it eats meat.","The Venus Flytrap is mixotrophic. It is a true autotrophic Producer that synthesizes its own carbohydrates via photosynthesis. However, because it often inhabits nutrient-poor bogs (lacking bioavailable nitrogen), it has evolved the structural adaptation to trap and digest insects (acting as a consumer) specifically to harvest essential inorganic minerals, not for caloric energy.","It is strictly a decomposer because it rots bugs.","It is not part of the food web at all."]',1,'It makes its own food using the sun like a normal plant, but it eats bugs just to get ''vitamins'' that are missing from the dirt!','Producer: An organism that makes its own food, usually through photosynthesis... Consumer: An organism that obtains energy by eating... (Synthesis of a plant that breaks the rules).','2026-11-01 09:18:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_001','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is an ''ecosystem''?','["Just a group of animals.","A community of living organisms interacting with each other AND their non-living environment (like water and sunlight).","Only the plants in a forest.","A type of weather."]',1,'It includes the living things AND the non-living things they need to survive!','An ecosystem is a community of living organisms interacting with one another and with the non-living parts of their environment.','2026-11-01 09:18:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_002','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'Which of these is a ''living'' (biotic) part of an ecosystem?','["A rock","Sunlight","A frog","Water"]',2,'It has to be something that is alive!','Living components (biotic): These are the living organisms in an ecosystem. Examples: plants, animals, fungi...','2026-11-01 09:18:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_003','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'Which of these is a ''non-living'' (abiotic) part of an ecosystem?','["A bird","A tree","A mushroom","Sunlight"]',3,'It is something that was never alive, but plants and animals need it to survive.','Non-living components (abiotic): These are the physical and chemical parts of the environment. Examples: sunlight, water, air, soil, rocks...','2026-11-01 09:18:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_004','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is a ''habitat''?','["The food an animal eats.","The weather in a forest.","The place where an organism naturally lives (its home).","The time of day an animal sleeps."]',2,'It''s the animal''s address in nature!','A habitat is the place where an organism lives.','2026-11-01 09:18:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_005','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'Why do animals depend on plants?','["Because plants provide shade.","Because animals obtain food and energy by eating plants (or by eating other animals that ate plants).","Because plants make water.","Because plants protect them from the rain."]',1,'Without plants making food from the sun, animals would have nothing to eat!','A simple ecosystem: ... Plants: Use sunlight, water and carbon dioxide to make food. Animals: Obtain food and energy from plants...','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_006','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What does ''interdependence'' mean in an ecosystem?','["That animals don''t need each other.","That living things rely on and are connected to each other for survival (like bees needing flowers, and flowers needing bees).","That plants can walk around.","That all animals live in the ocean."]',1,'It means ''we all need each other to survive''!','Organisms depend on one another... This dependence is called interdependence.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_007','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is a ''population'' in biology?','["All the different animals in a forest.","Members of the *same species* living together in one area (like all the frogs in a pond).","Only the plants in an area.","Only the non-living things in an area."]',1,'It''s a group of exactly the same type of animal!','Population: Members of the same species living in an area.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_008','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is a ''community'' in biology?','["Just one single animal.","Different populations of plants and animals living and interacting together in one area.","A city built by humans.","Only the rocks and water in a pond."]',1,'It''s all the different living neighbors sharing the same habitat!','Community: Different populations living and interacting in an area.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_009','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What happens during ''competition'' in nature?','["Animals help each other find food.","Organisms compete or fight when they both need the same limited resource, like food, water, or space.","Animals go to sleep.","Plants share their water with rocks."]',1,'It''s like two dogs trying to get the same bone!','Competition: Organisms compete when they need the same limited resource, such as food, water, light or space.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_010','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is a ''predator''?','["An animal that eats plants.","An animal that hunts and eats other animals (prey).","A type of tree.","A dead animal."]',1,'A hawk hunting a mouse is a predator!','Predation: A predator hunts and eats prey. For example, a lion may hunt a zebra.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_011','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is ''parasitism''?','["When two animals are best friends.","When a parasite benefits while harming its host (like a tick feeding on a dog).","When plants grow tall.","When animals share their food."]',1,'It''s a relationship where one organism steals from another, making it sick!','Parasitism: A parasite benefits while its host is harmed. A tick feeding on a mammal is one example.','2026-11-01 09:18:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_012','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What is an ''adaptation''?','["A mistake an animal makes.","A special feature or behavior that helps an organism survive in its environment (like a polar bear''s thick fur).","When a plant dies.","When an animal gets lost."]',1,'It''s a biological superpower that helps them live in a specific place!','An adaptation is a feature or behaviour that helps an organism survive and reproduce in its environment.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_013','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'How are ''marine'' ecosystems different from ''freshwater'' ecosystems?','["Marine ecosystems are completely dry.","Marine ecosystems (like oceans) contain salt water, while freshwater ecosystems (like ponds and rivers) do not.","Marine ecosystems only have plants.","There is no difference."]',1,'Oceans are salty, ponds are not!','Marine ecosystem: Oceans, coral reefs and rocky shores contain organisms adapted to salt water... Freshwater ecosystem: Ponds, lakes, rivers...','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_014','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'What might happen to an ecosystem if humans pollute the water?','["The animals will drink more water.","Pollution can harm the aquatic organisms (fish, frogs) and reduce water quality, hurting the whole food web.","The plants will grow much faster.","Nothing will happen."]',1,'Poisoning the water hurts everything that relies on that water to live!','Pollution can harm aquatic organisms and reduce water quality... Changes can have effects that spread through a food web.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_015','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',1,'Why are ''decomposers'' (like mushrooms) important to an ecosystem?','["They make the air colder.","They break down dead material and return the nutrients to the soil so plants can use them again.","They hunt large animals.","They turn dirt into water."]',1,'They are the cleanup crew of nature!','Decomposers: Break down dead material and return nutrients to the environment.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_016','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'How does a ''community'' differ from an ''ecosystem''?','["They are the exact same thing.","A community only includes the *living* organisms (biotic); an ecosystem includes the community PLUS the *non-living* surroundings (abiotic) they interact with.","A community is non-living, an ecosystem is living.","A community is in the ocean, an ecosystem is on land."]',1,'The community is the people; the ecosystem is the people PLUS the houses, weather, and water!','Community: Different populations living... Ecosystem: The community plus non-living environmental components. A community includes living things; an ecosystem includes both living things and their non-living surroundings.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_017','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What does it mean for an organism to have a specific ''niche''?','["It means it has a small house.","It describes the organism''s specific ''job'' or role in the ecosystem, including how it gets food, uses resources, and interacts with others.","It means the organism is a predator.","It means the organism only eats one type of food."]',1,'A habitat is an animal''s address; a niche is the animal''s profession or job!','An organism''s ecological niche describes its role in an ecosystem, including how it obtains food, uses resources and interacts with other organisms.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_018','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What is ''mutualism''?','["When two organisms fight over food.","An interaction where BOTH organisms benefit from the relationship (like a bee getting nectar while pollinating a flower).","When one organism harms another.","When an animal hunts prey."]',1,'It''s a win-win situation for both living things!','Mutualism: Two organisms benefit from an interaction. For example, a bee gets nectar from a flower while helping pollinate it.','2026-11-01 09:18:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_019','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'Why is ''competition'' between plants common in a dense forest?','["Because plants like to fight.","Because they must compete with each other for limited abiotic resources like sunlight, water, and space to grow.","Because they share all their food.","Because animals force them to compete."]',1,'If a big tree blocks the sun, the little plants underneath have to fight to survive in the shade!','Competition: Organisms compete when they need the same limited resource, such as food, water, light or space.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_020','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'How is a cactus structurally adapted to its desert ecosystem?','["It has large, flat leaves to catch rain.","It has a thick stem to store water, and sharp spines to reduce water loss and protect it from thirsty herbivores.","It has deep roots to find salt.","It has fur to stay warm at night."]',1,'It''s a giant water tank covered in needles to keep animals away!','Cactus: A thick stem stores water, and spines help reduce water loss and protect the plant.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_021','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'If an adaptation is helpful in one habitat, will it always be helpful in another?','["Yes, good adaptations work everywhere.","No, adaptations are specific to particular environments; a polar bear''s thick fur would cause it to overheat and die in a desert.","Yes, animals can instantly change their adaptations.","No, adaptations are only helpful for plants."]',1,'A superpower in the snow is a curse in the desert!','Adaptations work in particular environments. A feature that is helpful in one habitat may not be helpful in another.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_022','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What happens to the ''abiotic'' components of a forest if a severe drought occurs?','["The sunlight increases.","The amount of available water (an abiotic factor) drastically decreases, which then harms the biotic components (plants and animals).","The rocks turn into soil.","The temperature drops below freezing."]',1,'If it doesn''t rain, the non-living part (water) disappears, and the living things suffer!','A drought reduces the water available to plants and animals... Non-living components (abiotic)... Examples: sunlight, water...','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_023','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'How does the removal of a top predator affect the rest of the ecosystem?','["The ecosystem instantly dies.","The population of their prey will increase rapidly (overpopulation), which can then lead to overgrazing and the destruction of the plant life.","The prey will turn into predators.","Nothing happens to the ecosystem."]',1,'Without wolves to eat them, the deer will multiply until they eat all the grass and starve!','Removing a predator may cause the population of some prey species to increase. Changes can have effects that spread through a food web.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_024','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What makes an introduced species ''invasive''?','["It is very friendly.","It is a non-native species that disrupts the ecosystem, often by outcompeting native organisms for resources or preying on them.","It is a plant that grows very slowly.","It is an animal that migrates in the winter."]',1,'It''s an alien species that moves in and takes over because nothing hunts it!','Introducing a non-native species can affect native organisms, particularly if it becomes invasive.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_025','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'Why do some trees in a mangrove ecosystem have specialized, exposed roots?','["To walk around the swamp.","To help them survive and breathe in waterlogged, salty coastal environments where normal roots would drown.","To catch fish.","To scare away predators."]',1,'They act like snorkels so the tree can breathe in the muddy water!','Mangrove tree: Some species have specialised roots that help them survive in waterlogged, salty coastal environments.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_026','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'How do ''decomposers'' connect the end of a food chain back to the beginning?','["They eat the sun.","They break down dead animals and waste, releasing the trapped nutrients back into the soil so ''producers'' (plants) can absorb them and start the cycle again.","They turn rocks into animals.","They stop plants from growing."]',1,'They are the bridge that turns dead things back into food for plants!','Decomposers: Break down dead material and return nutrients to the environment... Interdependence helps ecosystems function... Decomposers recycle nutrients...','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_027','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What is a ''coral reef''?','["A type of forest.","A highly diverse marine ecosystem built by living coral organisms in the ocean.","A freshwater pond.","A type of desert."]',1,'It''s like a bustling underwater city built out of calcium!','Marine ecosystem: Oceans, coral reefs and rocky shores contain organisms adapted to salt water.','2026-11-01 09:18:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_028','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'Why is ''biodiversity'' (having many different types of living things) important for an ecosystem?','["It makes the ecosystem look pretty.","High biodiversity makes the ecosystem stronger and more resilient; if one species is affected by a disease, the ecosystem has other connections to rely on.","It makes the ecosystem weaker.","It means all the animals are exactly the same."]',1,'A web with many strings won''t break if you cut just one string!','Protecting habitats... and conserving biodiversity can help ecosystems remain healthy.','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_029','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'In a grassland ecosystem, what abiotic factors primarily determine which plant species can survive there?','["The number of lions.","The specific amount of rainfall and the temperature range.","The color of the grass.","The types of birds."]',1,'Grasslands exist because it''s too dry for a forest, but too wet for a desert!','Grassland... Rainfall and temperature influence which species can live there.','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_030','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',5,'What is ''seed dispersal'' an example of in an ecosystem?','["Parasitism","Interdependence between plants and animals; the plant relies on the animal to carry its seeds to new habitats.","Competition","A non-living component."]',1,'The plant makes a tasty fruit to trick the animal into carrying its seeds away!','Organisms depend on one another... Seed dispersal: Animals may carry seeds to new places. This dependence is called interdependence.','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_031','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Critique the assertion that ''An ecosystem is just a collection of animals living in the same forest.''','["The assertion is scientifically perfect.","The assertion is fundamentally flawed as it ignores two critical components. First, it ignores the primary producers (plants) and decomposers that make up the rest of the biological ''community''. Second, it completely ignores the ''abiotic'' (non-living) factors—like soil chemistry, hydrology, and solar radiation—that actively govern the entire system.","The assertion is true because plants are not part of an ecosystem.","The assertion is true because abiotic factors do not affect animals."]',1,'You can''t have an ecosystem with just animals; they need plants to eat, and plants need sun and dirt to grow!','An ecosystem is a community of living organisms interacting with one another and with the non-living parts of their environment. (Synthesis: Animals are only a small fraction of an ecosystem).','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_032','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Analyze the ecological concept of a ''Niche'' compared to a ''Habitat''.','["A niche is just a smaller habitat.","A habitat is simply the physical spatial location (the ''address'') where an organism resides. A niche is a highly complex ecological concept defining the organism''s functional role (its ''profession'')—encompassing its trophic level, its resource utilization, its symbiotic relationships, and its temporal activity patterns within that habitat.","A niche is for plants, a habitat is for animals.","A habitat is living, a niche is non-living."]',1,'The jungle is the monkey''s address (habitat), but eating fruit in the high canopy during the day is its job (niche)!','A habitat is the place where an organism lives... An organism''s ecological niche describes its role in an ecosystem, including how it obtains food, uses resources and interacts... (Synthesis: Location vs. Role).','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_033','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Synthesize the impact of removing an Apex Predator (disrupting predation) on the abiotic components of a freshwater ecosystem.','["Removing a predator only affects the prey, not the abiotic environment.","Removing an apex predator causes a trophic cascade that alters abiotic factors. Without predators, primary consumer populations explode, overgrazing the riparian (riverbank) vegetation. The loss of plant root systems causes severe soil erosion (abiotic), increasing water turbidity and altering the physical hydrology and temperature of the river itself.","Removing a predator makes the water cleaner.","Removing a predator turns the freshwater into saltwater."]',1,'If the wolves disappear, the deer eat all the bushes on the riverbank. Without the bushes holding the dirt together, the riverbank collapses into the water!','Removing a predator may cause the population of some prey species to increase. Changes can have effects that spread through a food web... Living and non-living components affect each other. (Synthesis of trophic cascade affecting abiotic environment).','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_034','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Evaluate the biological classification of ''Parasitism'' versus ''Predation''.','["They are identical because one animal always dies instantly.","While both are (+/-) interactions benefiting one organism at the expense of another, they differ functionally. Predation involves the immediate killing and consumption of the prey. Parasitism involves a symbiotic relationship where the parasite derives continuous nourishment from a living host; killing the host rapidly is evolutionarily counterproductive for a parasite.","Parasitism only happens in plants, predation only in animals.","Predation is a type of mutualism."]',1,'A lion kills its food immediately; a tick wants its food to stay alive as long as possible so it can keep drinking!','Predation: A predator hunts and eats prey... Parasitism: A parasite benefits while its host is harmed. A tick feeding on a mammal is one example. (Synthesis: A tick doesn''t kill the dog instantly; it feeds slowly).','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_035','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Analyze the specific ''Abiotic'' limitations that define a Marine (ocean) ecosystem.','["Marine ecosystems are only limited by the number of fish.","Marine ecosystems are strictly governed by complex abiotic gradients. Beyond just salinity (salt concentration), life distribution is dictated by hydrostatic pressure, cold temperatures, and the rapid attenuation of solar radiation (light penetration). Because light cannot penetrate the deep ocean, the photosynthetic producer base is restricted entirely to the shallow Photic Zone.","Marine ecosystems have no abiotic limitations.","Marine ecosystems are limited by the lack of water."]',1,'The ocean isn''t just a big bathtub; it''s a layered system where the deep parts are freezing, crushing, and pitch black!','Marine ecosystem... Temperature, depth, currents and available light influence marine life. (Synthesis of abiotic limits in the ocean).','2026-11-01 09:18:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_036','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Synthesize how the concept of ''Interdependence'' relates to the Carbon and Oxygen cycles between plants and animals.','["Plants and animals do not share carbon or oxygen.","Interdependence is chemically literal. Through photosynthesis, autotrophic plants absorb abiotic \\\\(CO_2\\\\) and release \\\\(O_2\\\\). Heterotrophic animals obligately inhale this \\\\(O_2\\\\) for cellular respiration and exhale \\\\(CO_2\\\\) as metabolic waste. Therefore, the survival of the animal community is chemically bound to the waste products of the plant community, and vice versa.","Animals produce oxygen for plants to breathe.","Plants absorb oxygen and release carbon dioxide during photosynthesis."]',1,'Animals breathe out the exact gas that plants need to ''breathe'' in, and plants breathe out the exact gas animals need!','A simple ecosystem: Plants: Use sunlight, water and carbon dioxide to make food. Interdependence: ...Water and oxygen: Organisms depend on environmental resources... (Synthesis connecting Topic 6 and 12).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_037','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Critique the evolutionary logic of ''Mutualism'' (like a bee and a flower).','["Mutualism proves that animals want to be nice to each other.","Mutualism is not altruism; it is reciprocal exploitation driven by evolutionary survival. The flower expends biological energy to synthesize nectar strictly to bribe the bee into acting as a mechanical vector for its pollen. The bee expends energy visiting the flower strictly to harvest caloric resources. Both organisms selfishly optimize their own reproductive fitness, which happens to benefit the other.","Mutualism is a mistake of nature.","Mutualism only benefits the flower, not the bee."]',1,'The bee isn''t trying to help the flower; it just wants a free lunch! The flower uses that greed to spread its pollen.','Mutualism: Two organisms benefit from an interaction. For example, a bee gets nectar from a flower while helping pollinate it. (Synthesis: It is a biological transaction, not friendship).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_038','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Evaluate the physiological adaptation of a Mangrove tree in a coastal ecosystem.','["Mangroves adapted to grow in the desert.","Mangroves inhabit intertidal estuarine ecosystems characterized by anoxic (oxygen-poor), waterlogged mud and extreme salinity. To survive this hostile abiotic environment, they have evolved structural adaptations: pneumatophores (aerial roots) that protrude above the mud to passively absorb atmospheric oxygen, and physiological mechanisms to actively exclude or excrete toxic salt levels.","Mangroves adapted to survive without sunlight.","Mangroves have no special adaptations."]',1,'If you plant a normal tree in salty mud, it will suffocate and die of thirst. Mangroves have built-in snorkels and salt-filters!','Mangrove tree: Some species have specialised roots that help them survive in waterlogged, salty coastal environments. (Synthesis of why these specific roots are needed).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_039','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Analyze the ecological concept of ''Competition'' in a stable ecosystem.','["Competition only occurs between animals, never plants.","Competition is a pervasive ecological pressure that occurs whenever sympatric organisms require a resource whose supply is less than the biological demand (e.g., water, light, nesting sites). Intraspecific competition (between the same species) drives natural selection. Interspecific competition (between different species) forces species to specialize their ecological niches to avoid competitive exclusion.","Competition means organisms share everything equally.","Competition always results in the immediate death of an ecosystem."]',1,'If there is only one piece of pizza left and ten hungry people, they are going to compete for it! Animals and plants do the same thing for water and space.','Competition: Organisms compete when they need the same limited resource, such as food, water, light or space. (Synthesis of resource limitation).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_040','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Synthesize the biological impact of an ''Invasive Species'' on the carrying capacity of an ecosystem.','["Invasive species increase the carrying capacity for all animals.","An invasive species bypasses the ecosystem''s established biological checks and balances (lacking native predators or diseases). It reproduces exponentially and monopolizes limited abiotic and biotic resources. This aggressively lowers the carrying capacity for endemic native species, leading to competitive exclusion, massive population declines, and a catastrophic loss of localized biodiversity.","Invasive species have no impact on carrying capacity.","Invasive species only affect the abiotic environment."]',1,'If you drop a thousand hungry, fast-breeding rabbits on an island with no wolves, they will eat all the food and starve the native animals!','Introducing a non-native species can affect native organisms, particularly if it becomes invasive... Changes can have effects that spread through a food web. (Synthesis: They steal resources, crashing the system).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_ecosystem_global_041','Biology','Ecosystems and Interdependence','Topic 12: Ecosystems and Interdependence','Primary',10,'Critique the student statement: ''Decomposers are only important because they get rid of bad smells.''','["The statement is ecologically accurate.","The statement represents a profound misunderstanding of biogeochemical cycling. While decomposers do eliminate necrotic tissue, their critical ecological function is metabolic. They secrete enzymes to chemically break down complex organic polymers in dead biomass, converting them into simple, bioavailable inorganic ions (like nitrates and phosphates) that autotrophic plants absolutely require to synthesize new organic matter.","The statement is true because decomposers are actually plants.","The statement is true because decomposers only eat garbage."]',1,'They aren''t just nature''s janitors; they are nature''s recycling plant! Without them, plants would run out of ''vitamins'' to grow.','Decomposers: Break down dead material and return nutrients to the environment. Decomposers recycle nutrients... Without decomposition... nutrient recycling would be disrupted. (Synthesis of their chemical importance).','2026-11-01 09:18:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_001','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What does ''biodiversity'' mean?','["The number of rocks in a place.","The variety of living things (plants, animals, fungi) in a place or across the Earth.","The weather in a forest.","How fast an animal runs."]',1,'It means having lots of different kinds of life!','Biodiversity means the variety of living things in a place or across the Earth.','2026-11-01 09:18:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_002','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Which garden has more biodiversity?','["A garden with only one type of grass.","A garden with many different kinds of flowers, insects, and birds.","A garden with no plants.","A garden with only rocks."]',1,'More variety equals more biodiversity!','A garden with many kinds of plants, insects and birds has more variety of life than a garden containing only one kind of plant.','2026-11-01 09:18:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_003','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Why is biodiversity important for humans?','["It makes the Earth flat.","It provides us with food, medicine, and clean water.","It makes the days longer.","It stops the wind from blowing."]',1,'We rely on nature for everything we need to live!','Biodiversity supports healthy ecosystems and benefits people in many ways. Food... Medicine... Clean water...','2026-11-01 09:18:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_004','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What is a ''species''?','["A type of rock.","A group of organisms classified as the same kind of organism (like all lions or all oak trees).","A building.","A drop of water."]',1,'Lions, tigers, and bears are all different species.','Species: A group of organisms classified as the same kind of organism','2026-11-01 09:18:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_005','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What does it mean if an animal is ''endangered''?','["It means the animal is very safe.","It means the animal is facing a high risk of going extinct (dying out) in the wild.","It means the animal lives in a zoo.","It means the animal is a predator."]',1,'It means there are very few of them left, and they need our help!','Endangered species: A species facing a high risk of extinction in the wild.','2026-11-01 09:18:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_006','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What does it mean if an animal is ''extinct''?','["It is sleeping.","It is hiding in the forest.","There are no living individuals of that species left anywhere on Earth.","It means the animal moved to a new country."]',2,'The dinosaurs and the Dodo bird are extinct.','Extinct species: A species for which no living individuals remain anywhere on Earth.','2026-11-01 09:18:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_007','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What is ''habitat loss''?','["When an animal forgets where it lives.","When natural homes (like forests or wetlands) are destroyed to build roads or farms.","When a plant grows too tall.","When a bird builds a new nest."]',1,'It''s like someone bulldozing an animal''s house!','Habitat loss: Forests, wetlands and grasslands may be cleared for buildings, roads or farming.','2026-11-01 09:18:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_008','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'How does pollution harm biodiversity?','["It makes the water taste better.","Plastic waste and harmful chemicals can injure animals and poison their habitats.","It makes plants grow faster.","It gives animals more energy."]',1,'Trash and chemicals make the earth sick.','Pollution: Plastic waste, harmful chemicals and other pollutants can injure organisms, contaminate habitats...','2026-11-01 09:18:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_009','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What is ''conservation''?','["Cutting down all the trees.","Protecting and carefully managing nature, species, and habitats.","Putting all animals in cages.","Throwing trash in the river."]',1,'It means being a superhero for the Earth!','Conservation means protecting and carefully managing nature, including species, habitats and natural resources.','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_010','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Which of these is a good way YOU can help protect biodiversity?','["Throwing rubbish in the river.","Planting native flowers for bees and picking up trash.","Keeping wild animals as pets.","Leaving the water running all day."]',1,'Small actions like planting a flower can help nature!','How can people help... Plant suitable native plants that provide food and shelter for local wildlife... Dispose of waste safely...','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_011','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What happens if humans hunt too many fish from the ocean (overfishing)?','["The ocean gets deeper.","The fish numbers fall sharply and they might not be able to recover.","The fish get bigger.","The ocean turns into a forest."]',1,'If you take too many, there won''t be enough left to make babies!','Overhunting and overfishing: If organisms are removed faster than their populations can recover, their numbers may fall sharply.','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_012','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Where can you find biodiversity?','["Only in the deep ocean.","Only in tropical rainforests.","Everywhere! In forests, deserts, rivers, oceans, and even in the soil and your garden.","Only in outer space."]',2,'It''s all around you, even in the dirt!','Biodiversity can be found in forests, deserts, grasslands, rivers, oceans, coral reefs and even in soil.','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_013','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'What is ''climate change''?','["When the sun goes down at night.","Long-term changes in temperature, rainfall, and weather that can make habitats unsuitable for some animals.","When it rains for one day.","When a bird flies south."]',1,'If a place gets too hot or too dry, the animals there might not survive.','Climate change: Changes in temperature, rainfall, sea level and extreme weather can make habitats unsuitable for some species.','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_014','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Why are bees and other insects important for biodiversity?','["They help pollinate flowers so plants can reproduce.","They make the air colder.","They eat all the bad plants.","They clean the water."]',0,'Without bugs, we wouldn''t have many of the fruits and vegetables we eat!','Pollination: Insects, birds and other animals help many flowering plants reproduce.','2026-11-01 09:18:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_015','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',1,'Should you release a pet fish or turtle into a wild pond?','["Yes, they will be happier.","No, it might become an invasive species and harm the natural animals living there.","Yes, it will clean the pond.","Yes, but only in the winter."]',1,'A pet doesn''t belong in the wild, and it could eat all the native wildlife!','Important: Do not release pets, aquarium animals or non-native plants into the wild. An organism that is harmless in one setting can become invasive in another.','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_016','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What are the three different levels of biodiversity?','["Animals, plants, and fungi.","Species diversity, genetic diversity, and ecosystem diversity.","Oceans, forests, and deserts.","Producers, consumers, and decomposers."]',1,'Biodiversity is about variety in species, genetics, AND whole habitats!','Different levels of biodiversity: Species diversity... Genetic diversity... Ecosystem diversity...','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_017','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is ''genetic diversity''?','["The number of different animals in a zoo.","Differences among individuals of the same species (like different colors or sizes of the same crop).","The number of different forests on Earth.","When an animal changes its species."]',1,'Even though all humans are the same species, we all look different because of genetic diversity!','Genetic diversity: Differences among individuals of the same species. For example, members of one crop species may have different colours...','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_018','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'Why is ''genetic diversity'' important for a population''s survival?','["It makes them all look exactly the same.","If everyone has the same genes, a single disease could wipe out the whole population; genetic differences help populations survive environmental changes and diseases.","It makes them grow faster.","It stops them from reproducing."]',1,'If a disease attacks a farm, you want some plants to naturally resist it so they don''t all die!','These levels are connected. Genetic differences can help populations respond to environmental changes...','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_019','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is ''ecosystem diversity''?','["The variety of different habitats (like wetlands, deserts, and coral reefs) across the planet.","The number of genes in a single animal.","The number of animals that live in one tree.","When a forest turns into a desert."]',0,'It means the Earth isn''t just one giant forest; it has many different types of homes for animals!','Ecosystem diversity: The variety of habitats and ecosystems, such as forests, wetlands, grasslands, deserts and coral reefs.','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_020','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is an ''invasive species''?','["A species that stays in its natural home.","A non-native organism that is introduced to a new area, spreads rapidly, and harms native species or habitats.","An animal that builds a very large nest.","An endangered animal."]',1,'It''s like an alien invader that takes over and destroys the local neighborhood!','Invasive species: Some organisms introduced outside their natural range spread rapidly and harm native species or change habitats.','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_021','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is the difference between ''in-situ'' and ''ex-situ'' conservation?','["In-situ is for plants, ex-situ is for animals.","In-situ means protecting organisms in their natural wild habitats; ex-situ means protecting them outside their natural habitat (like in a zoo or seed bank).","In-situ is illegal, ex-situ is legal.","There is no difference."]',1,'In-situ = IN nature. Ex-situ = OUT of nature (like a zoo).','In-situ conservation: Protecting organisms in their natural habitats... Ex-situ conservation: Protecting organisms outside their natural habitats.','2026-11-01 09:18:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_022','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'How do healthy wetlands contribute to human survival?','["They produce salt.","They can trap pollutants and help maintain clean water quality.","They turn into deserts.","They stop earthquakes."]',1,'Wetlands act like giant natural water filters!','Clean water: Wetlands and other natural systems can trap some pollutants and help maintain water quality.','2026-11-01 09:18:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_023','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'How does ''habitat loss'' directly threaten a species?','["It forces them to learn new languages.","By clearing forests or draining wetlands, animals lose the specific food, shelter, and breeding grounds they need to survive.","It makes them grow larger.","It turns them into invasive species."]',1,'If you bulldoze an animal''s house and grocery store, it can''t survive!','Habitat loss: ... Animals and plants can lose their food, shelter and breeding places.','2026-11-01 09:18:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_024','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is a ''Seed Bank''?','["A place where animals bury their food.","A type of ex-situ conservation facility that stores seeds to protect plant species for the future.","A bank that lends money to farmers.","A machine that plants trees."]',1,'It''s like a backup hard drive for nature, storing seeds in case a plant goes extinct in the wild!','Ex-situ conservation: ... Examples: Seed banks that store seeds','2026-11-01 09:18:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_025','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'Why is protecting the habitat (in-situ conservation) often better than just putting an animal in a zoo?','["Because zoos are too expensive.","Because protecting the habitat also protects the complex interactions and ecological processes (food webs) that the species and many others depend on.","Because animals in zoos forget how to walk.","Because habitats never change."]',1,'You can''t just save the tiger; you have to save the forest and the deer it eats, too!','Protecting natural habitats is especially important because it also protects the interactions and ecological processes that many species depend on.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_026','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What does ''resilience'' mean in biology?','["When an animal is very weak.","The ability of an ecosystem to recover and continue functioning when conditions change (helped by having high biodiversity).","When an ecosystem is completely destroyed.","When an animal runs fast."]',1,'A strong, diverse ecosystem can bounce back from a fire or a drought!','Resilience: A variety of species can help ecosystems continue functioning when conditions change.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_027','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'How can ''climate change'' act together with ''habitat loss'' to threaten a species?','["They cancel each other out.","If a species'' habitat is destroyed, it may not have a safe place to migrate to when the climate forces it to move, making survival much harder.","Climate change stops habitat loss.","Habitat loss fixes climate change."]',1,'It''s a double-threat: their home is destroyed, and the weather is getting too hot!','These threats may act together. For example, a species already affected by habitat loss may find it harder to survive when the climate also changes.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_028','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What is a ''native'' species?','["An invasive species.","A species that occurs naturally in a particular region.","An extinct species.","A species kept as a pet."]',1,'It belongs there and has lived there for thousands of years.','Native species: A species that occurs naturally in a particular region.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_029','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'Why are earthworms and soil bacteria important for biodiversity?','["They eat all the plants.","They act as decomposers, helping break down organic matter and recycle nutrients to keep the soil healthy.","They make the soil radioactive.","They stop plants from growing."]',1,'Without them, the dirt would be dead and nothing could grow!','Healthy soil: Earthworms, fungi and bacteria help break down organic matter and recycle nutrients.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_030','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',5,'What does it mean that biodiversity has ''intrinsic value''?','["It means living things are only valuable if you can sell them.","It means living things have value and matter simply because they exist, regardless of whether they provide direct benefits to humans.","It means all animals cost money.","It means biodiversity is worthless."]',1,'Nature is valuable just for being nature, not just because humans can use it!','Biodiversity also has cultural, educational, recreational and intrinsic value: living things matter beyond the direct benefits people receive from them.','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_031','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Critique the assertion that ''A monoculture farm (growing only one type of crop) is healthy as long as it produces a lot of food.''','["The assertion is scientifically accurate.","The assertion is ecologically flawed. A monoculture has near-zero species and genetic diversity. This lack of biodiversity makes the entire ecosystem highly vulnerable; a single specialized pathogen could eradicate the entire crop because there are no genetic variations to offer resistance.","The assertion is true because monocultures attract more diverse wildlife.","The assertion is false because monocultures don''t need water."]',1,'If you plant a million identical corn plants, one corn disease can wipe out your entire farm overnight!','Genetic diversity... For example, members of one crop species may have different colours, sizes or resistance to disease... Resilience: A variety of species can help ecosystems continue functioning... (Synthesis: Monocultures lack resilience).','2026-11-01 09:18:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_032','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Analyze the cascading ecological effect of introducing an ''Invasive Species'' (like a predatory snake) to an isolated island.','["The island will become a paradise with more biodiversity.","Because endemic island species evolved without this specific predator, they lack defensive adaptations. The invasive predator will consume native prey at an unsustainable rate, causing rapid extinctions. This disrupts the native food web, potentially causing the collapse of native plant species.","The invasive species will instantly die.","The native species will instantly evolve to fight the snake."]',1,'Island animals are often defenseless against new predators. The invader eats everything, crashing the entire ecosystem!','Invasive species: Some organisms introduced outside their natural range spread rapidly and harm native species or change habitats. (Synthesis with Topic 12 concepts of food webs).','2026-11-01 09:18:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_033','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Synthesize how ''Ecosystem Diversity'' buffers against the impacts of global ''Climate Change''.','["It stops the climate from changing.","Different ecosystems provide varying microclimates and habitats. High ecosystem diversity ensures that as the macro-climate shifts, there are varied topographical and ecological niches (refugia) available. Species can migrate to slightly cooler, wetter, or higher-altitude ecosystems nearby, preventing absolute extinction.","Ecosystem diversity makes climate change worse.","It causes all animals to hibernate permanently."]',1,'If the plains get too hot, animals can survive if there is a diverse mountain ecosystem nearby to migrate into!','Ecosystem diversity: The variety of habitats and ecosystems... Resilience: A variety of species can help ecosystems continue functioning when conditions change. (Synthesis of resilience on a macro scale).','2026-11-01 09:18:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_034','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Evaluate the biological limitations of ''Ex-situ Conservation'' (like zoos or seed banks) for saving a species.','["Ex-situ conservation is a perfect permanent solution.","While vital for preventing immediate extinction, ex-situ conservation removes the organism from its natural evolutionary pressures. It severely restricts genetic diversity (bottleneck effect) and fails to protect the symbiotic relationships and habitat necessary for the species to eventually be reintroduced and survive independently in the wild.","Ex-situ conservation only works for plants, not animals.","Ex-situ conservation actually causes extinction."]',1,'You can keep a tiger alive in a cage, but if the forest is gone, the tiger can never go back to being a real wild tiger!','Both approaches can be useful. Protecting natural habitats is especially important because it also protects the interactions and ecological processes that many species depend on. (Synthesis of why in-situ is preferred).','2026-11-01 09:18:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_035','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Analyze the role of ''Habitat Fragmentation'' (breaking a large habitat into small, isolated patches) in driving species toward extinction.','["Fragmentation helps animals by giving them their own private areas.","Fragmentation restricts territorial ranges and isolates populations. This prevents migration, limits access to diverse food sources, and most critically, prevents genetic mixing between populations. This forces inbreeding, drastically reducing genetic diversity and increasing the population''s vulnerability to disease and environmental stress.","Fragmentation only affects microscopic organisms.","Fragmentation increases biodiversity by creating new species instantly."]',1,'If you build a highway through a forest, the animals on the left side can no longer mate with the animals on the right side, leading to weak, inbred offspring!','Habitat loss: Forests, wetlands and grasslands may be cleared for buildings, roads or farming... (Synthesis with Genetic Diversity: isolation prevents genetic mixing).','2026-11-01 09:18:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_036','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Synthesize the connection between ''Biodiversity'' and ''Medicine''.','["Medicine is only made in laboratories from plastic.","Biodiversity is the foundational source of pharmacology. A vast majority of human medicines (like antibiotics from fungi, or analgesics from tree bark) are derived from complex biochemical compounds synthesized by diverse plants, animals, and microbes to defend themselves. Loss of biodiversity means losing undiscovered, irreplaceable chemical blueprints for future medical treatments.","Medicines actually destroy biodiversity.","Biodiversity only provides food, not medicine."]',1,'Every time a plant goes extinct, we might be losing the cure to a terrible disease!','Medicine: Plants, fungi and other organisms provide substances used in medicines and scientific research. (Synthesis of the intrinsic chemical value of nature).','2026-11-01 09:18:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_037','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Critique the statement: ''Climate regulation is entirely controlled by the atmosphere, not by biodiversity.''','["The statement is ecologically accurate.","The statement ignores the massive role of the biosphere in biogeochemical cycles. High-biodiversity ecosystems (like old-growth forests and marine phytoplankton) act as massive carbon sinks, sequestering atmospheric CO2 into organic biomass. Destroying these diverse ecosystems directly accelerates climate change by halting sequestration and releasing stored carbon.","The statement is true because plants only produce oxygen, not carbon.","The statement is true because the ocean does not affect the climate."]',1,'Trees and ocean algae are basically giant sponges that suck carbon out of the air; without them, the Earth overheats!','Climate regulation: Forests, oceans and other ecosystems store and cycle carbon. (Synthesis of biology''s physical impact on the atmosphere).','2026-11-01 09:18:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_038','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Evaluate the concept of ''Overexploitation'' (like overfishing) from a population dynamics perspective.','["Overexploitation helps the population grow faster.","Populations have a natural rate of reproduction and carrying capacity. Overexploitation occurs when the mortality rate (harvesting by humans) significantly exceeds the natural reproductive rate (births/recruitment). This causes a rapid demographic collapse, preventing the population from ever recovering its numbers, leading directly to endangerment or extinction.","Overexploitation only happens to endangered species.","Overexploitation means feeding the animals too much."]',1,'If you take 100 fish out of a lake every year, but the fish only have 50 babies a year, eventually the lake will be empty!','Overhunting and overfishing: If organisms are removed faster than their populations can recover, their numbers may fall sharply. (Synthesis of population dynamics).','2026-11-01 09:18:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_039','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Analyze how maintaining high ''Genetic Diversity'' within a species acts as a defense mechanism.','["It gives the animals laser vision.","Genetic diversity provides a vast pool of phenotypic variations. If a novel pathogen or extreme environmental shift occurs, a genetically uniform population will likely perish entirely. In a highly diverse population, statistical probability dictates that some individuals will possess a genetic mutation providing resistance or tolerance, allowing the species to survive and adapt.","Genetic diversity ensures that all animals get sick at the same time.","Genetic diversity makes the animals weaker."]',1,'If a virus attacks, and everyone has the exact same DNA, everyone dies. If everyone has different DNA, some people will naturally survive!','Genetic diversity... Genetic differences can help populations respond to environmental changes... Resilience: A variety of species can help ecosystems continue functioning... (Synthesis of evolutionary advantage).','2026-11-01 09:18:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_040','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Synthesize the danger of chemical ''Pollution'' (like agricultural runoff) on an aquatic ecosystem''s biodiversity.','["Pollution makes the water cleaner over time.","Chemical runoff (like excess nitrogen/phosphorus fertilizers) causes eutrophication. This triggers explosive, unnatural algae blooms that block sunlight. When the massive amount of algae dies, decomposers consume all the dissolved oxygen in the water to break it down, creating a hypoxic ''dead zone'' that suffocates all other aquatic biodiversity.","Pollution only affects the plants on the shore.","Pollution causes the fish to grow legs."]',1,'Fertilizer is meant for crops, but when it washes into a river, it causes a chain reaction that steals all the oxygen out of the water!','Pollution: Plastic waste, harmful chemicals and other pollutants can injure organisms, contaminate habitats and disrupt food webs. (Synthesis with Topic 12 concepts of interdependence).','2026-11-01 09:18:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_biodiversity_global_041','Biology','Biodiversity and Conservation','Topic 13: Biodiversity and Conservation','Primary',10,'Critique the assertion that ''Endangered species are natural and we shouldn''t intervene.''','["The assertion is a core principle of modern conservation.","While baseline extinction is a natural evolutionary process, the current anthropogenic (human-caused) extinction rate is hundreds of times faster than the natural background rate. This rapid loss is entirely due to artificial pressures (habitat destruction, pollution, invasive species) that we created, necessitating human intervention (conservation) to prevent total ecosystem collapse.","The assertion is true because conservation is illegal.","The assertion is true because animals want to go extinct."]',1,'Dinosaurs went extinct naturally; we are currently bulldozing forests and causing animals to go extinct on purpose. We have to fix what we broke!','A species may become endangered for many reasons, including habitat destruction, hunting, pollution... Conservation work aims to reduce these risks. (Synthesis: The current crisis is human-made, requiring a human solution).','2026-11-01 09:18:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_001','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'Why do living things need water?','["Only to keep cool.","To carry out important life processes like digestion, circulation, and making food.","Only to clean themselves.","They don''t actually need water."]',1,'It is the most important liquid for life on Earth!','Water is essential for nearly all known forms of life. Plants, animals and microorganisms need it to carry out important life processes.','2026-11-01 09:18:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_002','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'Where is most of the water on Earth found?','["In the clouds","In lakes and rivers","In the oceans and seas (as salt water)","Underground"]',2,'The oceans cover most of the planet!','Where is Earth''s water found? Oceans and seas: contain most of Earth''s water, mainly as salt water.','2026-11-01 09:18:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_003','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What happens when liquid water is heated by the sun and turns into invisible gas (water vapor)?','["Precipitation","Condensation","Evaporation","Infiltration"]',2,'It''s how puddles disappear on a sunny day!','Evaporation and transpiration: Liquid water evaporates... Sunlight provides energy: It warms water on Earth''s surface.','2026-11-01 09:18:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_004','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What do we call water that falls from the clouds as rain, snow, or hail?','["Evaporation","Precipitation","Condensation","Runoff"]',1,'It means water is ''precipitating'' or falling down from the sky.','Precipitation: Water falls as rain, snow, sleet or hail.','2026-11-01 09:18:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_005','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''condensation'' in the water cycle?','["When rain falls.","When water vapor cools and forms tiny droplets to make clouds.","When water turns into vapor.","When plants drink water."]',1,'It''s what makes the outside of a cold glass wet on a hot day!','Condensation: Water vapour cools and forms tiny droplets or ice crystals in clouds.','2026-11-01 09:18:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_006','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''groundwater''?','["Water in the ocean.","Water that is stored beneath the ground in soil and rock.","Water that falls as rain.","Water frozen in glaciers."]',1,'It''s the water hiding under your feet!','Groundwater: water stored beneath the ground in soil and rock.','2026-11-01 09:18:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_007','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is soil made of?','["Only broken rocks.","Only dead leaves.","A mix of mineral particles, organic matter, water, air, and living organisms.","Only water and air."]',2,'It''s a complex mix of many different things!','What is soil made of? The main components of soil are: Mineral particles... Organic matter... Water... Air... Living organisms...','2026-11-01 09:18:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_008','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'Why is soil important for plants?','["It gives them a place to sleep.","It supports their roots and stores the water and nutrients they need to grow.","It keeps them warm.","It gives them sunlight."]',1,'It''s the anchor and the grocery store for the plant!','Soil is important because it: Supports plant roots. Stores water and nutrients.','2026-11-01 09:18:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_009','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''weathering''?','["Checking the temperature.","The process where wind, water, and ice slowly break rocks down into smaller particles to help make soil.","When plants grow tall.","When rain falls."]',1,'It''s how big mountains slowly turn into sand and dirt over millions of years!','Rocks break down: Wind, water, temperature changes, ice and living organisms gradually break rocks into smaller particles. This is called weathering.','2026-11-01 09:18:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_010','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''soil erosion''?','["When soil turns into rock.","The removal or washing away of soil by water, wind, or other forces.","When plants grow too fast.","When people plant trees."]',1,'It''s when the good dirt gets blown or washed away!','Soil erosion is the removal of soil by water, wind or other forces.','2026-11-01 09:18:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_011','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'How can we help prevent soil erosion?','["By cutting down all the trees.","By pouring water on it constantly.","By planting trees or ground-cover plants so their roots hold the soil in place.","By paving over it with concrete."]',2,'Plant roots act like fingers holding the dirt together!','Ways to protect soil: Maintain vegetation cover and plant suitable trees or ground-cover plants.','2026-11-01 09:18:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_012','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''water pollution''?','["When water freezes.","When harmful substances or trash contaminate water, making it unsafe for people and wildlife.","When water evaporates into the sky.","When plants drink too much water."]',1,'It''s when water gets dirty and toxic!','Water pollution occurs when harmful substances or organisms contaminate water and make it less suitable for people, wildlife or ecosystems.','2026-11-01 09:18:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_013','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'Which of these is a good way to save water at home?','["Leaving the tap running while you brush your teeth.","Fixing leaking taps and turning off the water when you don''t need it.","Taking 2-hour showers.","Washing the car every day."]',1,'Every little drop counts!','How can we save water at home and school? Turn off taps when water is not needed. Fix leaking taps and pipes.','2026-11-01 09:18:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_014','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'What is ''runoff''?','["An animal running fast.","Water that flows over the surface of the land into streams and rivers after it rains.","Water that stays underground forever.","Water that turns into clouds."]',1,'It''s the water you see rushing down the street when it rains hard!','Runoff: water flows over the land into streams, rivers and lakes.','2026-11-01 09:18:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_015','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',1,'Why are earthworms and bugs in the soil a good thing?','["They make the soil dirty.","They bite people.","They help break down dead material, recycle nutrients, and make channels for air and water.","They turn the soil into rocks."]',2,'They are nature''s little plow machines!','Soil organisms contribute: Earthworms and microorganisms help break down organic material and mix or transform soil components.','2026-11-01 09:18:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_016','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Even though Earth is covered in water, why is water conservation still so important?','["Because all the water is evaporating into space.","Because only a very small fraction of Earth''s water is readily available freshwater; most of it is salt water or frozen.","Because plants are drinking it all.","Because water is turning into soil."]',1,'We can''t drink ocean water, so the small amount of freshwater we have is precious!','Although Earth has abundant water, only a small fraction is readily available freshwater. Protecting water quality and using water responsibly are therefore important.','2026-11-01 09:18:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_017','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What is ''transpiration'' in the water cycle?','["When water freezes into snow.","When liquid water evaporates from lakes.","The process where plants release water vapor through their leaves into the atmosphere.","When water seeps into the ground."]',2,'It''s like plants are sweating invisible water vapor into the air!','Evaporation and transpiration: Liquid water evaporates; plants release water vapour through transpiration.','2026-11-01 09:18:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_018','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What is the difference between ''infiltration'' and ''percolation''?','["Infiltration happens in the ocean, percolation happens on land.","Infiltration is when water first enters the soil surface; percolation is when water moves deeper down through the soil and rock layers.","They are the exact same thing.","Infiltration is evaporation, percolation is condensation."]',1,'Infiltration is entering the door; percolation is going down the stairs into the basement!','Infiltration: water enters the soil. Percolation: water moves deeper through soil and rock.','2026-11-01 09:18:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_019','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'How does a hard surface like concrete affect the water cycle in a city?','["It makes the rain stop.","It reduces infiltration (water soaking in) and increases runoff, which can lead to flooding and carry pollutants into rivers.","It increases infiltration and prevents all flooding.","It makes the water evaporate instantly."]',1,'Water can''t soak through a parking lot, so it rushes away and causes floods!','Hard surfaces such as concrete can reduce infiltration and increase runoff. Too much runoff may contribute to flooding and carry soil and pollutants into waterways.','2026-11-01 09:18:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_020','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What role does ''organic matter'' play in the formation of healthy soil?','["It turns the soil into solid rock.","Dead leaves and roots decompose to add essential organic matter, making the soil rich in nutrients for new plants.","It removes all the water from the soil.","It prevents earthworms from living in the soil."]',1,'Dead plants turn into the food that feeds the next generation of plants!','Organic matter accumulates: Dead leaves, roots and other remains decompose and add organic matter to the soil... helps recycle nutrients when dead organisms decompose.','2026-11-01 09:18:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_021','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What is ''humus'' in the context of soil?','["A type of food made from chickpeas.","A type of rock.","Dark, stable organic material formed from decomposing remains that helps soil hold water and nutrients.","The very bottom layer of solid rock."]',2,'It''s the rich, dark, squishy part of the dirt that makes plants grow well!','Humus is dark, relatively stable organic material formed as remains decompose. It can hold water and nutrients.','2026-11-01 09:18:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_022','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Why is ''sandy soil'' often poor at supporting many types of plants?','["Because it is too cold.","It has relatively large particles, so it drains water very quickly and holds fewer nutrients than finer soils.","Because it contains too much clay.","Because it is too sticky."]',1,'Water runs right through sand like a sieve, so plants get thirsty quickly!','Sandy soil: Has relatively large particles and usually drains water quickly. It often holds less water and fewer nutrients...','2026-11-01 09:18:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_023','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What are the characteristics of ''clay-rich soil''?','["It is very dry and drains water instantly.","It contains very small particles, holds a lot of water and nutrients, but can drain very slowly and become sticky when wet.","It is made entirely of dead leaves.","It is exactly the same as sandy soil."]',1,'If you''ve ever played with squishy, sticky mud that takes forever to dry, that''s clay!','Clay-rich soil: Contains very small mineral particles. It can hold substantial water and nutrients, but may drain slowly and become sticky when wet.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_024','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Why is ''loamy soil'' usually considered excellent for gardening?','["Because it is made of pure rock.","Because it is a balanced mixture of sand, silt, and clay, providing good drainage, aeration, and water retention.","Because it never needs to be watered.","Because it contains no organic matter."]',1,'It''s the ''Goldilocks'' soil: not too sandy, not too sticky, just right!','Loamy soil: A mixture of sand, silt and clay with suitable structure and often organic matter. Many loamy soils provide a good balance...','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_025','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'How does soil act as a habitat?','["Only birds live in it.","It provides shelter, feeding, and reproduction areas for insects, fungi, bacteria, and earthworms.","Nothing can live in soil because there is no air.","Only fish live in soil."]',1,'There is an entire bustling city of bugs and microbes living right under your feet!','Soil is important because it... Provides habitats for earthworms, insects, fungi and bacteria.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_026','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Why is ''soil erosion'' considered a serious environmental problem?','["Because it makes the landscape look too neat.","It causes the loss of fertile topsoil, reduces crop production, and damages aquatic habitats with muddy sediment.","Because it brings too many nutrients to the plants.","Because it causes earthquakes."]',1,'If the good dirt washes away, farmers can''t grow food, and fish choke on the mud in the rivers!','Possible effects [of erosion] include: Loss of fertile topsoil. Reduced plant growth and crop production. Muddy water and sediment... Damage to aquatic habitats.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_027','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'How does planting trees on a steep hill help protect the soil?','["The trees make the hill steeper.","The tree roots anchor the soil in place, and the leaves act like an umbrella to reduce the impact of heavy rain, preventing erosion.","The trees turn the soil into sand.","The trees absorb all the soil."]',1,'The roots act like a giant net holding the hill together!','Ways to protect soil: Maintain vegetation cover and plant suitable trees or ground-cover plants... Plant across slopes...','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_028','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Is boiling water enough to remove all types of water pollution?','["Yes, boiling removes everything.","No, boiling kills many disease-causing microorganisms, but it does not remove chemical pollutants.","Yes, boiling turns chemicals into pure water.","No, boiling only makes the water colder."]',1,'Boiling kills the germs, but it won''t take out toxic chemicals or heavy metals!','Boiling can kill many disease-causing microorganisms, but it does not remove many chemical pollutants.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_029','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'Why should you never pour household chemicals or medicines down the drain?','["Because they will clog the pipes.","Because they can contaminate waterways, harm aquatic wildlife, and make water less suitable for people.","Because they will turn into fresh water.","Because they make the water smell good."]',1,'What goes down the drain eventually ends up in the rivers and oceans!','Ways to protect water include: Dispose of chemicals, medicines and household waste safely rather than pouring them into drains or waterways.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_030','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',5,'What is a ''glacier'' in the context of Earth''s water?','["A hot spring.","A massive sheet of moving ice that stores large amounts of Earth''s frozen freshwater.","A deep underground lake.","A type of salty cloud."]',1,'They are like giant, slow-moving rivers of solid ice!','Where is Earth''s water found? ... Glaciers and ice sheets: store large amounts of frozen freshwater.','2026-11-01 09:18:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_031','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Critique the assertion that ''The water cycle has a distinct beginning and end.''','["The assertion is scientifically accurate; it always starts in the ocean.","The assertion is false. The water cycle is a continuous, dynamic, and closed-loop system of biogeochemical pathways. There is no single starting or ending point; water molecules constantly transition between states (liquid, vapor, solid) and reservoirs (atmosphere, oceans, groundwater) indefinitely.","The assertion is true; it ends when water reaches the clouds.","The assertion is true; it starts when rain falls."]',1,'It''s a circle; you can''t point to the ''start'' of a circle!','The water cycle has no single starting point. Water can move through different pathways, and some water remains underground or frozen for long periods.','2026-11-01 09:18:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_032','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Analyze the specific physiological role of water in maintaining thermal homeostasis in an animal.','["Water makes the animal colder by freezing inside the stomach.","Water has a high specific heat capacity and high latent heat of vaporization. Animals utilize these properties for temperature regulation (homeostasis). By evaporating water from their respiratory surfaces (panting) or skin (sweating), they expel massive amounts of excess thermal energy, preventing lethal hyperthermia.","Water acts as a thick coat to keep the animal warm.","Water prevents the animal from moving, saving energy."]',1,'Sweating works because it takes a lot of body heat to turn liquid water into vapor!','Animals drink water to... support digestion, circulation and temperature regulation.','2026-11-01 09:18:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_033','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Synthesize the impact of widespread ''Deforestation'' on both the Water Cycle and Soil Erosion.','["Deforestation improves both cycles by letting more sun hit the ground.","Deforestation severely disrupts both systems. Without tree roots to anchor the soil and canopy cover to intercept kinetic raindrop energy, soil erosion accelerates massively. Furthermore, removing trees halts transpiration, significantly reducing atmospheric water vapor, which can lead to severe local droughts and altered precipitation patterns.","Deforestation only affects animals, not water or soil.","Deforestation stops the water cycle entirely."]',1,'Trees are the glue that holds the dirt together and the pumps that put water back into the sky. Cutting them down ruins both!','Ways to protect soil: Maintain vegetation cover... Evaporation and transpiration: ...plants release water vapour through transpiration. (Synthesis: Removing trees increases erosion and stops transpiration).','2026-11-01 09:18:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_034','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Evaluate the physical and chemical interactions that cause ''Weathering'' to form soil.','["Weathering is only caused by animals stepping on rocks.","Weathering is a complex integration of mechanical and chemical forces over geological time. Mechanical forces (like ice wedging and thermal expansion/contraction) physically fracture the bedrock. Concurrently, chemical weathering (like slightly acidic rain dissolving minerals or lichens secreting organic acids) alters the rock''s chemical structure, gradually reducing solid rock to fine mineral particulates.","Weathering is when rain washes dirt away.","Weathering is the process of building a mountain."]',1,'It takes freezing ice, flowing water, and thousands of years to grind a mountain down into dirt!','Rocks break down: Wind, water, temperature changes, ice and living organisms gradually break rocks into smaller particles. This is called weathering.','2026-11-01 09:18:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_035','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Analyze the paradoxical nature of ''Clay'' soil regarding water availability for plants.','["Clay soil is perfect because it gives all its water to plants instantly.","Clay soil presents a physical paradox. Its microscopic particle size gives it a massive surface area, allowing it to hold a substantial volume of water. However, these particles pack so tightly together that they create powerful capillary forces that bind the water tightly. Consequently, even though the soil is wet, the water may be physically unavailable for plant roots to extract, and the lack of aeration (oxygen) can suffocate the roots.","Clay soil never holds any water because it drains too fast.","Clay soil only holds saltwater."]',1,'Clay holds water like a locked safe; the water is in there, but the plant struggles to get it out, and it can drown the roots!','Clay-rich soil: Contains very small mineral particles. It can hold substantial water and nutrients, but may drain slowly and become sticky when wet. Air: ...supplies oxygen to roots... (Synthesis: Too much water means no air for roots).','2026-11-01 09:18:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_036','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Synthesize how ''Eutrophication'' (caused by agricultural runoff) damages aquatic ecosystems.','["It makes the fish grow stronger.","Agricultural runoff carrying excess inorganic fertilizers (nitrogen/phosphorus) causes nutrient pollution in waterways. This triggers a massive, unnatural bloom of surface algae that blocks sunlight. When the algae dies, aerobic decomposer bacteria consume massive amounts of dissolved oxygen to break the biomass down, creating a hypoxic (low-oxygen) ''dead zone'' that suffocates fish and other aquatic life.","It cleans the water completely.","It causes the water to evaporate faster."]',1,'Too much fertilizer in a lake causes an explosion of algae that eventually sucks all the oxygen out of the water, killing the fish!','Water pollution... Sources can include... agricultural runoff... Pollution can harm aquatic organisms and reduce water quality. (Synthesis with Topic 12/13).','2026-11-01 09:18:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_037','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Critique the statement: ''Groundwater is completely safe from pollution because it is filtered by the dirt.''','["The statement is ecologically accurate.","The statement is dangerously flawed. While percolation through soil and porous rock does provide mechanical filtration of large particulates and some microbes, it does not filter dissolved chemical pollutants (like heavy metals, nitrates from fertilizers, or industrial solvents). These soluble toxins easily leach deep into aquifers, severely contaminating groundwater reserves for decades or centuries.","The statement is true because dirt destroys all chemicals.","The statement is true because groundwater moves too fast to get polluted."]',1,'Dirt can filter out mud and leaves, but it can''t filter out toxic chemicals dissolved in the water. The poison goes right through to the underground aquifer!','Groundwater recharge: some water reaches underground layers... Water pollution occurs when harmful substances... contaminate water... (Synthesis: Soluble chemicals travel with water).','2026-11-01 09:18:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_038','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Evaluate the importance of ''Air'' as a component of healthy soil.','["Soil does not contain air.","Air (specifically oxygen and nitrogen) is a critical abiotic component occupying the interstitial pore spaces in healthy soil. Oxygen is obligately required for cellular respiration by plant roots and aerobic soil organisms (like earthworms and beneficial bacteria). Without adequate soil aeration (as in compacted or waterlogged soils), these organisms suffocate, halting nutrient cycling and plant growth.","Air only exists above the soil.","Air makes the soil too dry for plants."]',1,'If dirt is packed too tightly or flooded with water, the roots and worms literally drown because they can''t breathe!','Air: fills spaces between particles and supplies oxygen to roots and many soil organisms.','2026-11-01 09:18:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_039','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Analyze the impact of ''Paving over natural landscapes with concrete'' on the local hydrology.','["It improves the water cycle by stopping evaporation.","Urbanization (paving) drastically alters local hydrology by sealing the soil with impermeable surfaces. This stops infiltration and groundwater recharge entirely. The kinetic energy of precipitation is immediately converted into high-velocity surface runoff, which overwhelms drainage systems, causes severe flash flooding, and flushes concentrated urban pollutants directly into adjacent aquatic ecosystems.","It causes the rain to stop falling in the city.","It helps plants grow through the concrete."]',1,'When you pave a parking lot, the rain has nowhere to soak in, so it acts like a giant slide, dumping dirty water straight into the river!','Hard surfaces such as concrete can reduce infiltration and increase runoff. Too much runoff may contribute to flooding and carry soil and pollutants into waterways.','2026-11-01 09:18:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_040','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Synthesize the biological relationship between ''Humus'' and soil fertility.','["Humus is a type of rock that plants eat.","Humus is the dark, highly stable organic fraction of soil resulting from the advanced decomposition of biomass. Biochemically, it acts as a massive reservoir for essential plant macronutrients (like nitrogen) which are slowly mineralized by microbes. Physically, its complex colloidal structure acts like a sponge, significantly increasing the soil''s cation exchange capacity (nutrient retention) and water-holding capacity, making the soil highly fertile.","Humus is a chemical pollutant that kills plants.","Humus is pure sand."]',1,'It''s the dark, rich ''superfood'' of the soil that holds water like a sponge and slowly feeds the plants!','Humus is dark, relatively stable organic material formed as remains decompose. It can help soil hold water and nutrients.','2026-11-01 09:18:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_water_global_041','Biology','Water, Soil and Life','Topic 14: Water, Soil and Life','Primary',10,'Critique the idea that ''All freshwater on Earth is readily available for human use.''','["The idea is completely true.","The idea demonstrates a massive misunderstanding of global water distribution. While freshwater exists, the vast majority (nearly 70%) is locked in inaccessible cryosphere reservoirs (glaciers and polar ice caps). Most of the remainder is deep groundwater. Only a tiny fraction of a percent (found in surface lakes and rivers) is actually physically and economically accessible for human consumption and agriculture.","The idea is true because humans can drink ocean water.","The idea is false because there is no freshwater left."]',1,'Most of the freshwater on Earth is locked up in giant ice cubes at the North and South Poles!','Although Earth has abundant water, only a small fraction is readily available freshwater. Glaciers and ice sheets: store large amounts of frozen freshwater.','2026-11-01 09:18:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_001','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What does the ''environment'' include?','["Only the weather.","Only wild animals.","Living things, non-living things, and human-made surroundings.","Only cities and roads."]',2,'It includes nature AND the things humans build!','The environment includes the living and non-living things around us and the conditions in which we live... human-made surroundings...','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_002','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'How do humans depend on nature for ''materials''?','["We use materials to make the sky blue.","We use wood, cotton, and minerals to make buildings, clothing, and tools.","We use materials to sleep longer.","We don''t need materials from nature."]',1,'Your cotton shirt and wooden desk both come from nature!','Materials: Wood, cotton, bamboo, minerals and other resources are used to make buildings, clothing, tools and everyday products.','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_003','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What is ''pollution''?','["Cleaning the oceans.","Planting new trees in a forest.","The introduction of harmful substances or energy into the environment that causes unwanted changes.","Building safe homes for animals."]',2,'It means making the air, water, or land dirty and toxic.','Pollution is the introduction of substances or forms of energy into the environment that cause harm or unwanted changes.','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_004','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'Which of these is an example of ''air pollution''?','["Plastic floating in a river.","Smoke, dust, and harmful gases from cars and factories.","Loud music playing at night.","Dropping a banana peel on the ground."]',1,'It''s the pollution you breathe in!','Air pollution: Smoke, dust and harmful gases from vehicles, industries, fires...','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_005','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What does ''noise pollution'' do?','["It makes the water dirty.","It causes trees to fall down.","Excessive sound can disturb people, wildlife, sleep, and communication.","It makes the air smell bad."]',2,'Too much loud noise can actually hurt animals that rely on hearing!','Noise pollution: Excessive or unwanted sound can disturb people, wildlife, sleep and communication.','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_006','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'In the ''5 Rs'' of waste management, what does ''Reuse'' mean?','["Throwing something in the bin.","Using an item again instead of throwing it away.","Burning garbage.","Buying a brand new item."]',1,'Instead of throwing away a plastic bottle, refill it with water!','3. Reuse: Use an item again instead of throwing it away, when it is safe and practical.','2026-11-01 09:18:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_007','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What does ''Recycle'' mean?','["Processing materials like paper and glass into materials that can be used again.","Putting food scraps in the garden.","Saying no to plastic bags.","Burying trash underground."]',0,'It turns old paper into new paper!','4. Recycle: Process suitable materials, such as paper, glass and some plastics, into materials that can be used again.','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_008','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What is a ''renewable resource''?','["A resource that forms so slowly we will run out of it.","A natural resource that can be replenished (replaced) naturally on a short timescale, like sunlight or wind.","A resource that can never be used by humans.","A resource made of plastic."]',1,'Nature can quickly make more of it!','Renewable resources: Can be replenished naturally on a relatively short timescale when managed appropriately. Sunlight, wind...','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_009','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'Which of these is a ''non-renewable'' resource?','["Sunlight","Wind","Coal, petroleum (oil), and natural gas","Bamboo"]',2,'Once we dig it all up and burn it, it''s gone for millions of years!','Non-renewable resources... Coal, petroleum, natural gas and many mineral deposits','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_010','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What is the ''greenhouse effect''?','["A natural process where gases in the atmosphere trap some heat, keeping Earth warm enough for life.","A process that makes the Earth freezing cold.","When people build houses out of green glass.","When pollution turns the sky green."]',0,'It acts like a giant, warm blanket wrapped around the Earth!','The greenhouse effect is a natural process in which gases in Earth''s atmosphere trap some heat. It helps keep Earth warm enough for life.','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_011','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What is causing ''global warming'' and climate change today?','["Planting too many trees.","Human activities, especially burning coal/oil and clearing forests, which increases greenhouse gases.","Animals breathing too fast.","Drinking too much water."]',1,'We are making the ''blanket'' around the Earth too thick!','Human activities, especially burning coal, oil and natural gas and clearing forests, have increased the amount of greenhouse gases... This strengthens the greenhouse effect and causes global warming...','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_012','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What does ''sustainability'' mean?','["Using up all the resources today so there is nothing left.","Meeting people''s needs today while protecting nature and resources so future generations can also use them.","Never using any natural resources.","Destroying habitats to build cities."]',1,'It means leaving enough for your grandchildren!','Sustainability means meeting people''s needs while protecting the natural systems and resources that future generations will also depend on.','2026-11-01 09:18:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_013','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'Which of these is a sustainable choice you can make at home?','["Leaving the lights on all day.","Throwing perfectly good food in the trash.","Switching off lights and devices when they are not needed.","Leaving the tap running."]',2,'Save energy by turning things off!','Sustainable choices... Lights and devices use electricity -> Switch off when not needed','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_014','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What should you do if you see a wild animal in its natural habitat?','["Try to catch it and take it home.","Observe the wildlife peacefully without disturbing them or damaging their habitat.","Throw rocks at it.","Feed it human junk food."]',1,'Look, but don''t touch!','Sustainable choices... Wildlife habitats are disturbed -> Observe wildlife without damaging its habitat','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_015','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',1,'What does ''Rot'' mean in the 5 Rs of waste?','["Letting your house fall down.","Composting suitable food scraps and garden waste so they break down into useful organic soil.","Leaving trash on the street.","Putting plastic in the ocean."]',1,'Nature recycles food scraps into rich dirt!','5. Rot: Compost suitable food scraps and garden waste so they break down into useful organic material.','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_016','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why are human-made surroundings (like roads and cities) considered part of the ''environment''?','["Because animals build them.","Because the environment includes the living, non-living, AND the conditions/surroundings in which we live, including what humans build.","They are not part of the environment.","Because they are completely natural."]',1,'Your city is your habitat; it is part of your environment!','The environment includes the living and non-living things around us... Human-made surroundings: homes, roads, farms, schools and factories.','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_017','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'How can ''land and soil pollution'' eventually cause ''water pollution''?','["Soil pollution cannot reach the water.","Rain can carry litter, chemicals, and improperly disposed waste from the land into drains, streams, and larger bodies of water.","The soil turns into water.","Fish eat the polluted soil."]',1,'Everything is connected; if you poison the dirt, rain will wash that poison into the river.','Pollution can travel beyond its original source. For example, rain can carry litter and chemicals from roads into streams and eventually into larger bodies of water.','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_018','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'What is the difference between ''Refusing'' and ''Reducing'' waste?','["Refusing means throwing it away; reducing means burning it.","Refusing is avoiding unnecessary items entirely (like saying no to a plastic straw); Reducing is just using fewer resources and buying less.","They are the exact same thing.","Refusing is for plastic, reducing is for glass."]',1,'Saying ''No thank you'' is Refusing. Only taking one instead of two is Reducing.','1. Refuse: Avoid unnecessary items... 2. Reduce: Use fewer resources and avoid buying things that are not needed.','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_019','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why is it important to follow local rules when trying to compost (''Rot'') waste?','["Because all waste turns into compost instantly.","Because not every material belongs in a compost bin (like batteries or electronics), and they need special, safe treatment.","Because composting is illegal.","Because compost only works in the winter."]',1,'If you put a battery in a compost bin, you will poison the soil!','Not every material belongs in a home compost bin or ordinary recycling collection. Follow local waste-management guidance, especially for batteries...','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_020','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Does the term ''renewable resource'' mean it is completely unlimited and can never be harmed?','["Yes, renewable means we can never run out of it.","No, even renewable resources like forests can be damaged if they are used or cut down faster than they can naturally regrow.","Yes, renewable means it is magic.","No, renewable resources actually run out faster than non-renewable ones."]',1,'If you cut down a 100-year-old tree, it takes another 100 years to replace it!','Renewable does not mean unlimited or impact-free. For example, forests can be damaged if trees are cut down faster than they regrow.','2026-11-01 09:18:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_021','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'How does the burning of ''non-renewable'' resources like coal and oil affect the planet''s climate?','["It makes the planet much colder.","It releases stored greenhouse gases into the atmosphere, which strengthens the greenhouse effect and causes global warming.","It creates new ozone layers.","It has absolutely no effect on the climate."]',1,'Burning fossil fuels is like pumping extra heat-trapping gas into the sky!','Human activities, especially burning coal, oil and natural gas... have increased the amount of greenhouse gases... This strengthens the greenhouse effect and causes global warming...','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_022','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'What might happen to an ecosystem if the climate changes too quickly (global warming)?','["All animals will instantly turn into plants.","Changes in temperature, rainfall, and sea levels can stress plants and animals, making their habitats unsuitable for survival.","The habitats will become perfect for every single species.","It will cause the greenhouse effect to disappear."]',1,'If a polar bear''s ice melts, it loses its home and its hunting ground!','Possible effects include: ... Stress on plants, animals and their habitats. Changes to food production and water availability.','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_023','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why is true ''sustainability'' described as balancing environmental, social, and economic effects?','["Because it only cares about making money.","Because sustainable choices must protect nature, but also ensure people have fair access to resources (social) and can afford to live (economic).","Because humans don''t matter in sustainability.","Because sustainability only applies to animals."]',1,'We have to save the trees, but we also have to make sure humans have enough food and jobs!','A sustainable choice considers environmental, social and economic effects. Examples include: ... Ensuring that people have fair access to essential resources.','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_024','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why shouldn''t you release a pet fish from an aquarium into a local wild pond?','["Because the fish will drown.","Because an organism that is harmless in a tank can become a dangerous ''invasive species'' that harms native wildlife in the pond.","Because the fish will turn into a frog.","Because the pond water is too clean."]',1,'Your pet goldfish could eat all the food that the native pond fish need to survive!','Important: Do not release pets, aquarium animals or non-native plants into the wild. An organism that is harmless in one setting can become invasive in another.','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_025','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'How can ''noise pollution'' harm a wild bird population?','["It makes the birds sing better.","Excessive noise can disrupt their ability to communicate with each other, affecting mating calls or warnings about predators.","It turns their feathers grey.","It makes them fly backwards."]',1,'If a bird can''t hear a predator coming because of a loud highway, it might get eaten!','Noise pollution: Excessive or unwanted sound can disturb people, wildlife, sleep and communication.','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_026','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'How do healthy wetlands benefit humans directly?','["They create plastic.","They act as natural filters to trap pollutants and maintain clean water quality.","They produce coal for fuel.","They stop the sun from shining."]',1,'Nature has built-in water purification systems!','Healthy ecosystems: Wetlands can help filter water, vegetation can reduce erosion...','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_027','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'What does it mean to ''repair'' a product for sustainability?','["Throwing it away immediately.","Fixing a broken item (like sewing a hole in a shirt) so it lasts longer, which conserves non-renewable resources by avoiding buying a new one.","Burning it for energy.","Buying two of the exact same item."]',1,'Fixing a broken toy means the factory doesn''t have to use more oil and plastic to make you a new one!','Non-renewable resources can be conserved by using materials efficiently, repairing products and recycling suitable materials. ... Designing products that last longer and can be repaired.','2026-11-01 09:18:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_028','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why is it important to protect *large, connected* habitats for wildlife?','["Small habitats are too quiet.","Some species need plenty of space to hunt, forage, and survive, which small, disconnected natural areas cannot provide.","Because large habitats are easier to pave over.","Because animals like to get lost."]',1,'A lion or an elephant needs miles of connected land to find enough food!','Even small natural areas can provide shelter and food for organisms. However, protecting larger connected habitats is often essential for species that need plenty of space to survive.','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_029','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'What is a simple way a school can support biodiversity in its own yard?','["By paving the entire yard with concrete.","By planting suitable native plants that provide food for local pollinators like bees and butterflies.","By spraying heavy chemicals everywhere.","By keeping all animals out with a giant net."]',1,'Planting local flowers gives the local bugs and birds exactly what they need to eat!','A school garden can provide food for pollinators... Plant suitable native plants that provide food and shelter for local wildlife.','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_030','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',5,'Why is just relying on ''individual choices'' (like one person recycling) not enough to achieve global sustainability?','["Because recycling is actually bad.","Because governments, communities, businesses, and scientists must also play major roles to make large systems cleaner and more efficient.","Because individuals cannot recycle plastic.","Because the planet is already completely sustainable."]',1,'One person using a reusable bag is great, but we also need factories to stop polluting!','Sustainability is not only about individual choices. Governments, communities, businesses and scientists also have important roles in making systems cleaner and more efficient.','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_031','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Critique the assertion that ''The greenhouse effect is an unnatural, human-made phenomenon that is entirely destructive.''','["The assertion is scientifically perfect.","The assertion is biologically false. The greenhouse effect is a vital, natural atmospheric process that traps solar radiation, keeping Earth''s surface warm enough to sustain liquid water and life. The current crisis is the *anthropogenic enhancement* of this effect via excessive fossil fuel combustion, trapping lethal amounts of heat.","The assertion is true because greenhouse gases are artificial.","The assertion is false because the greenhouse effect cools the Earth."]',1,'Without the natural greenhouse effect, Earth would be a frozen ball of ice! Humans are just making the blanket too thick.','The greenhouse effect is a natural process... It helps keep Earth warm enough for life. Human activities... have increased the amount of greenhouse gases... This strengthens the greenhouse effect and causes global warming...','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_032','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Analyze the cascading ecological impact of ''Clearing forests without allowing them to recover'' (Deforestation).','["Deforestation improves the environment by creating more open space.","Deforestation initiates a severe ecological cascade: it directly destroys terrestrial habitats (causing biodiversity loss), eliminates massive root systems (accelerating soil erosion and water pollution), and destroys critical carbon sinks, leaving excess CO2 in the atmosphere to accelerate global climate change.","Deforestation only affects the birds living in the trees.","Deforestation makes the soil much richer in nutrients."]',1,'Cutting down a forest doesn''t just kill trees; it destroys homes, ruins the dirt, and makes the whole planet hotter!','Examples of activities that can cause harm include: Clearing forests without allowing them to recover... Habitat loss... Climate regulation: Forests, oceans and other ecosystems store and cycle carbon. (Synthesis of multiple concepts).','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_033','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Synthesize the socio-economic dimension of ''Sustainability'' with environmental conservation.','["Sustainability means prioritizing animals over human survival.","True sustainability requires a tripartite balance: Environmental protection must be coupled with Social equity and Economic viability. Conservation efforts (like restricting fishing or logging) must include economic transitions for local communities who rely on those resources, ensuring fair access to food and livelihoods while preserving the ecosystem.","Sustainability means maximizing factory production at all costs.","Sustainability is strictly a biological term with no human factors."]',1,'You can''t just ban fishing to save the fish if it causes the local village to starve to death; sustainability finds a way to feed the village AND save the fish!','A sustainable choice considers environmental, social and economic effects. Examples include: ... Ensuring that people have fair access to essential resources. (Synthesis: It''s about balance).','2026-11-01 09:18:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_034','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Evaluate the environmental limitations of ''Recycling'' as the primary solution to human waste.','["Recycling is a flawless system with zero environmental impact.","While better than landfills, recycling is an energy-intensive industrial process. Transporting, melting, and reforming materials (like plastic or glass) requires massive energy inputs (often from non-renewable fossil fuels) and produces some pollution. Therefore, ''Refusing'' and ''Reducing'' source consumption are ecologically superior to ''Recycling''.","Recycling actually creates more raw waste than it saves.","Recycling is only possible for organic food waste."]',1,'Recycling a plastic bottle takes factory energy; saying ''no'' to the plastic bottle takes zero energy!','The 5 Rs... Refuse... Reduce... Recycle: Process suitable materials... (Synthesis: Recycling requires ''processing'', which requires energy. Refusing prevents the need entirely).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_035','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Analyze how the introduction of a ''Non-native Invasive Species'' disrupts an established food web.','["Invasive species always increase the biodiversity of a food web.","Invasive species bypass the natural evolutionary checks (predators, diseases) of the new ecosystem. They reproduce exponentially and aggressively outcompete native species for limited resources (food/space), or act as unchecked apex predators. This competitive exclusion cascades through the food web, causing massive native population declines or extinctions.","Invasive species only eat non-living abiotic factors.","Invasive species instantly die because they don''t know the environment."]',1,'If you drop a predator onto an island where the animals have never seen a predator, it will eat everything and destroy the food chain!','Introducing non-native organisms that become invasive... Invasive species: Some organisms introduced outside their natural range spread rapidly and harm native species or change habitats.','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_036','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Synthesize the relationship between ''Land/Soil Pollution'' and the health of ''Marine Ecosystems''.','["Soil pollution stays on land and never reaches the ocean.","Because the Earth''s hydrological cycle connects all biomes, land and ocean ecosystems are heavily interdependent. Improper chemical disposal or agricultural runoff on land leaches into the soil, percolates into groundwater, or is carried by surface runoff directly into river networks, eventually discharging massive toxic loads into marine estuaries and coral reefs.","Soil pollution actually cleans the ocean water.","Marine ecosystems are completely immune to land chemicals."]',1,'If you dump motor oil on your driveway, the rain will eventually wash it straight into the ocean!','Land and soil pollution: Improper waste disposal... contaminate water. Pollution can travel beyond its original source. For example, rain can carry litter and chemicals from roads into streams and eventually into larger bodies of water. (Synthesis across biomes).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_037','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Critique the student statement: ''We should transition entirely to solar and wind energy because they have absolutely zero impact on the environment.''','["The statement is 100% accurate.","The statement represents a vast oversimplification. While renewable energy sources do not emit greenhouse gases during generation, the infrastructure (solar panels, wind turbines, massive batteries) requires extensive extraction of non-renewable minerals (lithium, rare earth metals), industrial manufacturing, and large land footprints, all of which carry significant environmental impacts.","The statement is true because wind and solar are infinite.","The statement is false because solar energy causes global warming."]',1,'The wind is free and clean, but building a giant steel and fiberglass wind turbine requires mining, factories, and fossil fuels!','Renewable does not mean unlimited or impact-free... Solar and wind energy also require equipment and materials. (Synthesis: The *source* is renewable, the *equipment* is not).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_038','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Evaluate the biological necessity of ''Composting'' (Rot) over sending organic waste to a landfill.','["Composting is just a slower way to make a landfill.","When organic waste is trapped in anaerobic (oxygen-starved) landfills, it decomposes improperly, releasing massive amounts of methane (a highly potent greenhouse gas). Aerobic composting utilizes decomposers to break down organic matter efficiently, recycling critical inorganic nutrients (nitrogen, phosphorus) back into bioavailable humus to support new producer growth.","Composting kills all the bacteria in the soil.","Composting only works for non-renewable resources."]',1,'In a landfill, an apple core rots without oxygen and makes dangerous methane gas. In a compost bin, worms turn it into super-dirt for new plants!','5. Rot: Compost suitable food scraps and garden waste so they break down into useful organic material. (Synthesis with greenhouse gas and decomposer concepts).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_039','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Analyze how ''Climate Change'' acts as a threat multiplier for species already suffering from ''Habitat Loss''.','["Climate change actually reverses the effects of habitat loss.","Species experiencing habitat fragmentation are confined to isolated geographic pockets. If climate change rapidly alters the abiotic conditions (temperature/precipitation) of that pocket, the species must migrate to survive. However, because their habitat is fragmented by human infrastructure, migration routes are severed, trapping them in an unlivable environment and ensuring localized extinction.","Habitat loss prevents climate change from affecting animals.","Climate change only affects animals in the ocean."]',1,'If a forest gets too hot, the animals need to move north. But if we built a giant city to the north, they are trapped and will die!','These threats may act together. For example, a species already affected by habitat loss may find it harder to survive when the climate also changes. (Synthesis of combined threats).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_040','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Synthesize the ecological role of ''Pollinators'' in maintaining both environmental biodiversity and human economic food systems.','["Pollinators only help wild plants, not human crops.","Pollinators (bees, bats, birds) are keystone mutualists. Environmentally, they facilitate the sexual reproduction of diverse angiosperms (flowering plants), sustaining the producer base of the food web. Economically, human agriculture is massively reliant on these wild pollinators to produce a huge percentage of global crop yields; their decline threatens both ecosystem collapse and global human famine.","Pollinators destroy human crops by eating the flowers.","Pollinators are only needed to produce honey."]',1,'Without bees moving pollen around, thousands of wild plant species would die out, and humans wouldn''t have apples, almonds, or tomatoes!','Food: Crops... provide food. Healthy soil, water and pollinators help many food systems function. Pollination: Insects... help many flowering plants reproduce. (Synthesis: They are essential for nature AND human survival).','2026-11-01 09:18:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('bio_sustain_global_041','Biology','Humans, the Environment and Sustainability','Topic 15: Humans, the Environment and Sustainability','Primary',10,'Critique the concept of a ''Disposable Product'' from a sustainability perspective.','["Disposable products are highly sustainable because they save time.","The ''disposable'' model violates core sustainability principles. It follows a linear ''take-make-dispose'' economy. It requires constant, unsustainable extraction of non-renewable raw materials, energy-intensive manufacturing for brief single use, and results in permanent environmental pollution (landfills/microplastics), completely failing to protect resources for future generations.","Disposable products are good because they disappear instantly.","Disposable products are only a problem if they are made of wood."]',1,'Using Earth''s ancient, non-renewable oil to make a plastic spoon that you use for five minutes and throw in the ocean forever is the exact opposite of sustainability!','1. Refuse: Avoid unnecessary items, such as disposable products when a suitable reusable option is available... Sustainability means meeting people''s needs while protecting the natural systems and resources... (Synthesis: Disposables break the cycle).','2026-11-01 09:18:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_001','History','Basic History','Topic 1: Introduction to History','Primary',1,'What is history?','["The study of rocks and soil","The study of the human past using evidence","The study of the future","The study of outer space"]',1,'It looks at how people lived long ago.','History is the study of the human past using evidence.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_002','History','Basic History','Topic 1: Introduction to History','Primary',1,'What word describes events that have already happened?','["Present","Future","Past","Science"]',2,'Yesterday is an example of this.','Past: Events that have already happened.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_003','History','Basic History','Topic 1: Introduction to History','Primary',1,'What word describes the time we are living in right now?','["Past","Present","Future","History"]',1,'You are reading this in the ______.','Present: The time we are living in now.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_004','History','Basic History','Topic 1: Introduction to History','Primary',1,'What word describes the time that has not yet happened?','["Past","Present","Future","Yesterday"]',2,'Tomorrow is an example of this.','Future: The time that has not yet happened.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_005','History','Basic History','Topic 1: Introduction to History','Primary',1,'What do we call a person who studies and explains the past?','["A doctor","A pilot","A historian","A farmer"]',2,'This person looks at evidence to understand old events.','A historian is a person who researches, studies, and explains the past.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_006','History','Basic History','Topic 1: Introduction to History','Primary',1,'What does historical evidence do?','["Helps us predict the future","Helps us investigate and explain the past","Changes the present","Creates new rocks"]',1,'It provides proof of what happened.','Historical evidence is information that helps us investigate and explain the past.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_007','History','Basic History','Topic 1: Introduction to History','Primary',1,'Which of these is an example of the past?','["A birthday celebration last year","Reading this lesson right now","A school trip next month","Eating dinner tonight"]',0,'It already happened.','For example, a birthday celebration last year belongs to the past.','2026-11-01 09:39:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_008','History','Basic History','Topic 1: Introduction to History','Primary',1,'Which of these is an example of the present?','["A war from 100 years ago","Reading this lesson right now","Your next birthday","Building a pyramid"]',1,'It is happening right now.','Reading this lesson is happening in the present.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_009','History','Basic History','Topic 1: Introduction to History','Primary',1,'Which of these is an example of the future?','["The clothes your grandparents wore","A school trip planned for next month","Finding an old coin","A letter written yesterday"]',1,'It hasn''t happened yet.','A school trip planned for next month belongs to the future until it takes place.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_010','History','Basic History','Topic 1: Introduction to History','Primary',1,'What is one reason we study history?','["To learn how to fly a plane","To learn how people lived in earlier times","To learn how to build computers","To predict the weather"]',1,'It tells us about life before we were born.','History helps us: Understand how people lived in earlier times.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_011','History','Basic History','Topic 1: Introduction to History','Primary',1,'Can an old family photograph be a piece of historical evidence?','["Yes","No","Only if it is in color","Only if it is from today"]',0,'Pictures from long ago show us the past.','An old family photograph can show how clothing or houses have changed.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_012','History','Basic History','Topic 1: Introduction to History','Primary',1,'What can an old coin provide clues about?','["The weather next week","Money, rulers, and trade","How to cook","How to drive"]',1,'It shows who was in charge and how people bought things.','An ancient coin can provide information about money, rulers, and trade.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_013','History','Basic History','Topic 1: Introduction to History','Primary',1,'Who studies past human life through material remains like buildings and tools?','["A palaeontologist","An archaeologist","An archivist","A pilot"]',1,'They dig up old objects to learn about people.','Archaeologists study past human life through material remains, including buildings, tools...','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_014','History','Basic History','Topic 1: Introduction to History','Primary',1,'Who studies fossils of ancient life, like extinct animals?','["An archaeologist","A palaeontologist","An archivist","A historian"]',1,'They study things like dinosaur bones.','Palaeontologists study fossils of ancient life, including extinct plants and animals.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_015','History','Basic History','Topic 1: Introduction to History','Primary',1,'Who preserves and organizes historical documents and records?','["An archivist","A palaeontologist","An anthropologist","A doctor"]',0,'They keep old papers safe in a library or museum.','Archivists preserve and organize historical documents and records.','2026-11-01 09:39:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_016','History','Basic History','Topic 1: Introduction to History','Primary',1,'Is a written letter a type of historical evidence?','["Yes","No","Only if it is typed","Only if it is new"]',0,'People used to write to each other before emails.','Historical evidence... can be a physical object, a written record... Examples include: ... Old letters...','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_017','History','Basic History','Topic 1: Introduction to History','Primary',1,'What is an ''observation''?','["A guess about the future","Something that can be directly noticed","A type of rock","A story someone made up"]',1,'It is what you can see or feel with your own eyes and hands.','Observation: Something that can be directly noticed.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_018','History','Basic History','Topic 1: Introduction to History','Primary',1,'If you see a pot is made of clay and has a broken handle, is that an observation or an inference?','["An observation","An inference","A guess","A timeline"]',0,'You can look right at it and see the clay and the break.','Observation: The pot is made of clay and has a broken handle.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_019','History','Basic History','Topic 1: Introduction to History','Primary',1,'If you guess that a broken clay pot was used to store water, is that an observation or an inference?','["An observation","An inference","A fact","A lie"]',1,'You are making a smart guess based on what you saw.','Inference: It may have been used to store or carry something.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_020','History','Basic History','Topic 1: Introduction to History','Primary',1,'Should you handle historical objects carefully?','["No, you can throw them","Yes, they should be handled carefully","Only if they are heavy","Only if they are new"]',1,'They are old and might break easily.','Objects should be handled carefully.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_021','History','Basic History','Topic 1: Introduction to History','Primary',1,'Does history only study big events, or can it study families and everyday life?','["Only big events","It includes the study of families, communities... and everyday life","Only kings","Only wars"]',1,'Everyday people are a big part of history.','History includes the study of families, communities... History helps us: Understand how people lived in earlier times.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_022','History','Basic History','Topic 1: Introduction to History','Primary',1,'Can an old railway station be historical evidence?','["Yes, it shows how transport developed","No, buildings are not evidence","Only if trains still use it","Only if it is made of wood"]',0,'It shows how people used to travel.','An old railway station can show how transport developed.','2026-11-01 09:39:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_023','History','Basic History','Topic 1: Introduction to History','Primary',1,'What do historians do with evidence?','["They hide it","They examine it to develop explanations","They throw it away","They use it to predict the future"]',1,'They use clues to tell the story of what happened.','Examine evidence... Develop explanations: Use the available evidence to explain events.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_024','History','Basic History','Topic 1: Introduction to History','Primary',1,'Is history just a list of dates and names?','["Yes, that is all it is","No, it also helps us understand why events happened and what changed","Yes, you only need to memorize numbers","Yes, it never asks ''why''"]',1,'It''s about the ''how'' and ''why'', not just the ''when''.','History is not simply a list of dates and names. It also helps us understand why events happened...','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_025','History','Basic History','Topic 1: Introduction to History','Primary',1,'Are all written stories from the past 100% correct?','["Yes, they never have mistakes","No, a story may contain mistakes or describe events from one person''s point of view","Yes, people in the past never lied","Yes, if it is written down, it is true"]',1,'Historians have to double-check the facts!','A story may contain mistakes... A written account may describe events from one person''s point of view.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_026','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why is it important for historians to compare different sources of evidence?','["Because one source is always enough to know the whole truth.","Because different sources might describe the same event differently or from a single point of view, so comparing them helps find the most reliable explanation.","Because historians like reading a lot.","Because they want to combine the sources into a new fictional story."]',1,'If two people tell a different story about a fight, you have to look for more clues!','A written account may describe events from one person''s point of view. Historians therefore... compare their accounts with photographs... or other available evidence.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_027','History','Basic History','Topic 1: Introduction to History','Primary',5,'If a historian finds a new piece of evidence that contradicts an old explanation, what should they do?','["Ignore the new evidence.","Revise their explanations based on the new evidence.","Destroy the old evidence.","Stop studying history."]',1,'Science and history both change when we learn new facts!','Historians may revise their explanations when new evidence becomes available.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_028','History','Basic History','Topic 1: Introduction to History','Primary',5,'How does the study of history help us understand modern languages and traditions?','["It teaches us how to speak future languages.","It helps us understand the origins of traditions, languages, and cultural practices by showing how they developed over time.","It proves that languages never change.","It forces everyone to speak ancient languages."]',1,'Your language and holidays came from the people who lived long before you!','History helps us: ...Understand the origins of traditions, languages, and cultural practices.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_029','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why might an old, broken tool still be considered valuable historical evidence?','["Because it can be used to fix modern cars.","Its shape and material may help researchers infer its likely purpose and tell us about the technology and daily life of the people who made it.","Because it is worth a lot of money.","Because broken things are better than new things."]',1,'Even a broken hammer tells us that the people who owned it knew how to build things!','A tool''s shape and material may help researchers infer its likely purpose.','2026-11-01 09:39:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_030','History','Basic History','Topic 1: Introduction to History','Primary',5,'What is the main difference between the work of a historian and an archaeologist?','["Historians only dig in the dirt; archaeologists only read books.","Archaeologists study past human life specifically through physical material remains (ruins, objects), while historians primarily investigate and interpret broad evidence (like documents) to explain the past.","Historians study animals; archaeologists study humans.","There is no difference; they are the exact same job."]',1,'Archaeologists find the objects; historians help tell the story of the objects.','Archaeologists study past human life through material remains... Historians investigate and interpret evidence about the past. These roles can overlap, but they are not identical.','2026-11-01 09:39:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_031','History','Basic History','Topic 1: Introduction to History','Primary',5,'A student looks at a 200-year-old letter and says, ''This person was sad.'' Is this an observation or an inference?','["Observation, because the words are on the page.","Inference, because the student is drawing a conclusion about the person''s feelings based on the words, rather than directly observing a physical fact like ink on paper.","Observation, because letters cannot lie.","Inference, because letters are not evidence."]',1,'You can''t directly ''see'' the emotion; you have to guess it from the clues in the writing.','Inference: An explanation or conclusion drawn from observations and other evidence.','2026-11-01 09:39:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_032','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why is the exact location where an archaeological object was found important?','["Because the finder gets to keep the land.","Because the location provides crucial context (like what other objects were nearby or what layer of dirt it was in); if it is moved without recording, that information is lost forever.","Because objects change shape if moved.","Because the location proves who made it."]',1,'Finding a coin near a market tells a different story than finding a coin near a battlefield!','Archaeological objects can lose important information if they are removed from their original location without proper recording.','2026-11-01 09:39:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_033','History','Basic History','Topic 1: Introduction to History','Primary',5,'Does the study of history guarantee simple answers to modern problems?','["Yes, history repeats itself exactly.","No, while history helps us ask better questions about the present, the past does not always provide simple answers to modern problems.","Yes, modern problems are identical to ancient ones.","No, because modern problems do not exist."]',1,'The past can guide us, but the modern world is very different!','History can also help us ask better questions about the present. However, the past does not always provide simple answers to modern problems.','2026-11-01 09:39:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_034','History','Basic History','Topic 1: Introduction to History','Primary',5,'What kind of questions do historians ask when they begin an investigation?','["What will happen tomorrow?","What happened? Where did it happen? Why might it have happened?","How can I invent a new tool?","What is the weather like right now?"]',1,'They act like detectives trying to solve a mystery from the past.','Ask questions: What happened? Where did it happen? Why might it have happened?','2026-11-01 09:39:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_035','History','Basic History','Topic 1: Introduction to History','Primary',5,'If a historian is examining a source, why do they consider ''why it was created''?','["Because the creator might want money.","Because knowing the creator''s purpose helps the historian understand if the source might be biased, exaggerated, or telling only one side of a story.","Because the source might be magical.","Because they want to build one themselves."]',1,'A poster made by a king to make himself look good might not tell the whole truth!','Historians therefore consider who created a source, when it was created, why it was created...','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_036','History','Basic History','Topic 1: Introduction to History','Primary',5,'How can a single photograph act as historical evidence, but also have limitations?','["It can show exactly how a building looked on one day, but it only shows one moment in time and doesn''t tell you what happened before or after the picture was taken.","It is a perfect record of the entire year.","Photographs are never considered historical evidence.","It proves everything in the picture is alive today."]',0,'A picture is just a snapshot; it doesn''t tell the whole story!','A photograph may show only one moment... Historians therefore consider... whether other evidence supports it.','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_037','History','Basic History','Topic 1: Introduction to History','Primary',5,'What is the study of humans, societies, cultures, and human development called?','["Palaeontology","Anthropology","Archiving","Biology"]',1,'They study how groups of people live and behave.','Anthropologists study humans, societies, cultures, and human development.','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_038','History','Basic History','Topic 1: Introduction to History','Primary',5,'If you want to know how people communicated before the internet, what historical evidence would be most useful?','["A dinosaur fossil","An ancient coin","An old letter or diary","A new computer"]',2,'People used ink and paper to talk across long distances!','An old letter can reveal how people communicated before modern messaging services.','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_039','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why is ''conflict'' considered a part of history?','["Because history is only about peace.","Because exploring how people lived involves understanding wars, battles, and disagreements, which are major events that change how societies develop over time.","Because historians like to argue.","Because conflict only happens in the future."]',1,'Wars have changed borders, rulers, and lives throughout time.','History includes the study of... culture, and conflicts... [and] social change.','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_040','History','Basic History','Topic 1: Introduction to History','Primary',5,'What does a palaeontologist study that a historian generally does not?','["Written letters","Fossils of ancient life, including extinct plants and animals","Old buildings","Ancient coins"]',1,'Historians study the *human* past; palaeontologists study things like dinosaurs that lived before humans!','Palaeontologists study fossils of ancient life, including extinct plants and animals.','2026-11-01 09:39:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_041','History','Basic History','Topic 1: Introduction to History','Primary',5,'Can an oral account (a spoken story or recorded memory) be considered historical evidence?','["Yes, because it provides relevant information and memories from people who experienced the past.","No, only written words are evidence.","No, only physical objects are evidence.","Yes, but only if it is a song."]',0,'Hearing your grandfather tell a story about his childhood is historical evidence!','Historical evidence... can be a physical object, a written record, an image, an oral account...','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_042','History','Basic History','Topic 1: Introduction to History','Primary',5,'When examining a historical object, what is one of the key questions a researcher should ask?','["What is my favorite color?","What shape and size is it?","How much can I sell this for?","Does it match my clothes?"]',1,'The physical details of the object hold the clues to its use.','How to examine a historical object. Ask these questions: ... What shape and size is it?','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_043','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why do we study the ''development of communities'' in history?','["To learn how to build houses faster.","To learn how groups of people came together, built cities, created rules, and changed from small families into large civilizations over time.","To prove that communities are a bad idea.","To find hidden treasure."]',1,'It explains how we went from living in small caves to giant modern cities!','History helps us: ...Learn about the development of communities and civilizations.','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_044','History','Basic History','Topic 1: Introduction to History','Primary',5,'If a historian finds a diary describing a terrible storm, why might they want to find other sources (like newspapers) to compare it to?','["To make the diary longer.","Because a single written account may be exaggerated or only describe one person''s point of view; comparing it to official records helps verify the facts.","Because the diary is definitely fake.","Because they want to throw the diary away."]',1,'One person might think the storm was the worst ever, while the newspaper shows it only hit one town.','A written account may describe events from one person''s point of view. Historians therefore... compare their accounts with photographs, official records...','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_045','History','Basic History','Topic 1: Introduction to History','Primary',5,'How does learning about historical ''migration'' help us understand the present world?','["It teaches us how to fly.","It explains how different groups of people moved across the world in the past, which helps us understand why certain cultures, languages, or populations exist in specific countries today.","It proves that no one ever moved.","It stops people from traveling."]',1,'It explains why your ancestors might have moved from one country to another!','History helps us: ...Learn about cooperation, conflict, migration... explain how it connects to the present.','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_046','History','Basic History','Topic 1: Introduction to History','Primary',5,'What is a ''civilization'' in the context of history?','["A single family living in a house.","A complex human society with cities, social organization, and cultural development that historians study to see how life changed over time.","A type of ancient tool.","A modern computer system."]',1,'Ancient Egypt and Rome were massive civilizations with millions of people!','History includes the study of families, communities, cities, countries, civilizations...','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_047','History','Basic History','Topic 1: Introduction to History','Primary',5,'If an object is described as a ''material remain'', what does that mean?','["It is a thought or an idea.","It is a physical thing left behind from the past, like a building, a tool, or a piece of pottery.","It is a story told by a grandfather.","It is a date on a calendar."]',1,'It is something you can touch that survived the years.','Archaeologists study past human life through material remains, including buildings, tools, and pottery.','2026-11-01 09:40:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_048','History','Basic History','Topic 1: Introduction to History','Primary',5,'Why is ''technology'' a subject studied in history?','["Because historians want to build robots.","Because discovering how inventions (like the wheel or the steam engine) were created helps us understand how daily life drastically changed for people in the past.","Because technology never changes.","Because historians hate modern technology."]',1,'Before cars, people rode horses. That invention changed the whole world!','History helps us: ...Discover how inventions and technologies changed daily life.','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_049','History','Basic History','Topic 1: Introduction to History','Primary',5,'What does it mean that ''people in different places may have experienced the same period differently''?','["It means everyone experienced it exactly the same.","It means that during a specific time in history, one country might have been rich and peaceful, while another country was poor and at war, leading to very different historical accounts.","It means time moved faster in some places.","It means the past didn''t happen in some places."]',1,'In the year 1500, a king in Europe lived a very different life than a farmer in Asia!','History helps us: ...Understand that people in different places may have experienced the same period differently.','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_050','History','Basic History','Topic 1: Introduction to History','Primary',5,'How does the work of an ''archivist'' directly help the work of a ''historian''?','["The archivist makes the objects; the historian breaks them.","The archivist preserves and organizes historical documents and records, ensuring they are safe and accessible so the historian can examine them for evidence.","The archivist writes the history books; the historian sells them.","They do not help each other."]',1,'The archivist runs the library; the historian uses the library to solve the mystery!','Archivists preserve and organize historical documents and records. Historians investigate and interpret evidence...','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_051','History','Basic History','Topic 1: Introduction to History','Primary',10,'Analyze the inherent epistemological problem with a historical narrative derived exclusively from a single ''written account''.','["Written accounts are always physically indestructible.","A single written account is inherently subjective; it reflects only the author''s limited perspective, biases, and cultural context at the time, ignoring the experiences and contradictory evidence of other participants or marginalized groups.","A single written account is always mathematically perfect.","It requires the historian to read multiple languages simultaneously."]',1,'If you only read the King''s diary, you will never know how the peasants felt about the kingdom!','A written account may describe events from one person''s point of view. Historians therefore consider who created a source... and whether other evidence supports it.','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_052','History','Basic History','Topic 1: Introduction to History','Primary',10,'How does the concept of ''inference'' bridge the gap between archaeological ''material remains'' and historical ''explanations''?','["Inferences destroy the material remains physically.","Material remains (like a sharpened stone) are silent observations; inference is the logical, evidence-based reasoning process a historian uses to assign meaning and function (like concluding it was a hunting tool) to construct the narrative.","Inference proves the material remain is a fake.","Inference turns the material remain into a written document."]',1,'You can observe a piece of sharp metal, but you have to infer that it was used as a sword in a battle!','Observation: The pot... has a broken handle. Inference: It may have been used to store or carry something. The inference is plausible...','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_053','History','Basic History','Topic 1: Introduction to History','Primary',10,'Evaluate the rationale for the statement: ''The past does not always provide simple answers to modern problems.''','["Because modern problems are simple, and the past was complicated.","Historical contexts (societal structures, technology, global connectivity) are vastly different from the modern era; while historical patterns offer insights, directly applying a past solution to a novel modern crisis is often reductive and ineffective.","Because historians refuse to answer modern questions.","Because the past has been completely erased from existence."]',1,'You can''t solve a modern internet hacking problem using the laws of ancient Rome!','History can also help us ask better questions about the present. However, the past does not always provide simple answers to modern problems.','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_054','History','Basic History','Topic 1: Introduction to History','Primary',10,'In historical methodology, why is ''determining when a source was created'' critical to establishing its reliability?','["Because sources created on Tuesdays are invalid.","A source created simultaneously with an event (a primary source) often holds higher evidentiary weight for immediate factual details than an account written centuries later (a secondary source), which may rely on hearsay or distorted memory.","Because it determines how much the source costs to buy.","Because older sources are always 100% false."]',1,'A diary written by a soldier *during* a battle is usually more accurate than a story written by a king 50 years later!','Historians therefore consider who created a source, when it was created, why it was created...','2026-11-01 09:40:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_055','History','Basic History','Topic 1: Introduction to History','Primary',10,'Synthesize: How does studying ''everyday objects'' (like a cooking pot) challenge the traditional historical focus on ''kings and conflicts''?','["It proves that kings used cooking pots as weapons.","Studying everyday objects democratizes history by shifting focus from elite political figures to the social history, economic struggles, and daily realities of common people whose lives were rarely recorded in official state documents.","It shows that conflicts were only fought over food.","It proves that ordinary people did not exist."]',1,'The king''s crown tells us who ruled, but the peasant''s pot tells us how 99% of the population actually lived!','An old cooking pot may tell us about the materials available to a community and how food was prepared... History includes the study of families, communities...','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_056','History','Basic History','Topic 1: Introduction to History','Primary',10,'Why is the distinction between a ''palaeontologist'' and an ''archaeologist'' fundamentally a distinction of chronology and subject matter rather than just methodology?','["Because palaeontologists only work indoors.","Palaeontologists focus on a much older geological chronology (deep time) studying non-human biological evolution (fossils); archaeologists focus on the comparatively recent Holocene epoch, studying exclusively *human* cultural evolution (material remains).","Because archaeologists study dinosaurs and palaeontologists study humans.","Because they both study the exact same things at the same time."]',1,'Archaeologists dig up Roman coins; Palaeontologists dig up T-Rex bones!','Archaeologists study past human life... Palaeontologists study fossils of ancient life, including extinct plants and animals.','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_057','History','Basic History','Topic 1: Introduction to History','Primary',10,'How does the removal of an archaeological object ''without proper recording'' act as an irreversible destruction of historical context?','["It changes the chemical composition of the object.","The object''s spatial relationship to soil strata, surrounding artifacts, and geographical features (its provenance) provides critical data for dating and inference; once moved unrecorded, this contextual web is permanently severed, isolating the object.","It causes the object to instantly turn to dust.","It makes the object heavier to carry."]',1,'If you take a puzzle piece out of the box and lose it in the grass, you don''t know where it fits in the picture anymore!','Archaeological objects can lose important information if they are removed from their original location without proper recording.','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_058','History','Basic History','Topic 1: Introduction to History','Primary',10,'Critique the assertion that ''History is simply a list of dates and names.''','["It is correct; history requires no other analysis.","It severely mischaracterizes the discipline. History is an analytical science that investigates causality (why events happened), tracks societal evolution (what changed), and interprets the diverse human experience, rather than rote memorization.","It is incorrect because history has no dates or names.","It is correct, but only for ancient history."]',1,'Knowing that a war started in 1914 is useless if you don''t understand *why* it started or *how* it changed the world!','History is not simply a list of dates and names. It also helps us understand why events happened, what changed afterward, and how different people experienced those changes.','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_059','History','Basic History','Topic 1: Introduction to History','Primary',10,'How can an ''old coin'' provide multi-disciplinary historical evidence (economic, political, and metallurgical)?','["It cannot; it only shows how much it was worth.","Economically, it indicates trade systems; politically, its stamped imagery (a ruler''s face) reveals centralized authority; metallurgically, its material composition reveals the society''s technological capability in mining and smelting.","It only provides evidence for palaeontologists.","It proves that the society had no leaders."]',1,'A Roman coin tells you they had an economy, it shows you the face of the Emperor (politics), and proves they knew how to melt silver (technology)!','An ancient coin can provide information about money, rulers, and trade.','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_intro_060','History','Basic History','Topic 1: Introduction to History','Primary',10,'Explain the iterative nature of historical explanation as indicated by the statement: ''Historians may revise their explanations when new evidence becomes available.''','["It means historians are always wrong.","It demonstrates that history is not a static dogma but a rigorous, evidence-based discipline. As new archives are uncovered or archaeological sites excavated, previous hypotheses must be challenged, refined, or discarded to fit the updated evidentiary record.","It means evidence is constantly being faked.","It proves that the past changes physically."]',1,'Just like a detective changes his suspect when he finds a new fingerprint, a historian changes the story when he finds a new document!','Historians may revise their explanations when new evidence becomes available.','2026-11-01 09:40:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_001','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What word describes time that has already happened?','["Present","Future","Past","Today"]',2,'Yesterday is an example of this.','The past includes everything that has already happened.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_002','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What word describes time that is happening right now?','["Past","Present","Future","History"]',1,'You are reading this in the ______.','The present is the time happening now.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_003','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What word describes time that has not yet happened?','["Past","Present","Future","Yesterday"]',2,'Tomorrow is an example of this.','The future refers to time that has not yet happened.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_004','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What do we call a visual representation of events arranged in order?','["A map","A timeline","A painting","A photograph"]',1,'It often looks like a line with dates on it.','A timeline is a visual representation of events arranged according to when they happened.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_005','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Which event comes first on a timeline?','["The latest event","The earliest event","The most important event","The event happening now"]',1,'Timelines start with the oldest thing.','The earliest event comes first, and the latest event comes last.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_006','History','Basic History','Topic 2: Time and Chronology','Primary',1,'How many years are in a decade?','["1","10","100","1000"]',1,'The 1980s is an example of this.','A decade is a period of ten years.','2026-11-01 09:40:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_007','History','Basic History','Topic 2: Time and Chronology','Primary',1,'How many years are in a century?','["10","50","100","1000"]',2,'A person who lives to be 100 has lived for a ______.','A century is a period of one hundred years.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_008','History','Basic History','Topic 2: Time and Chronology','Primary',1,'How many years are in a millennium?','["10","100","500","1000"]',3,'This is the longest period of these options.','A millennium is a period of one thousand years.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_009','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What does BCE stand for?','["Before Christ Existed","Before Common Era","Beyond Current Events","Begin Century Early"]',1,'It is often used instead of BC.','BCE: Before Common Era.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_010','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What does CE stand for?','["Common Era","Current Events","Century Ending","Christ Era"]',0,'It is often used instead of AD.','CE: Common Era.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_011','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What is a system used to organize days, months, and years?','["A clock","A timeline","A calendar","A map"]',2,'You use this to find out what day your birthday is on.','A calendar is a system for organizing days, months, and years.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_012','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What device uses the Sun to estimate time during the day?','["A water clock","A sundial","A sand timer","A digital watch"]',1,'It uses a shadow to tell time.','Using sundials to estimate time during daylight.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_013','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Which of these events is in the past?','["Building a new house tomorrow","The construction of an old bridge","Your next birthday","Graduating from school next year"]',1,'It already happened.','The past includes everything that has already happened. Examples include: ... The construction of an old bridge.','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_014','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Which of these events is in the future?','["A family celebration last year","Reading this lesson right now","Tomorrow''s school activities","When you were born"]',2,'It hasn''t happened yet.','The future refers to time that has not yet happened. Examples include tomorrow''s school activities...','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_015','History','Basic History','Topic 2: Time and Chronology','Primary',1,'If you arrange events from earliest to latest, what order are they in?','["Alphabetical order","Random order","Chronological order","Reverse order"]',2,'Chrono- means time.','Events arranged according to when they happened [is chronological order].','2026-11-01 09:40:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_016','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Which of these is used to measure short amounts of time?','["Years","Centuries","Seconds","Decades"]',2,'It is the shortest unit listed here.','We use seconds, minutes, hours... to measure time.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_017','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What does a timeline help us identify?','["Where an event happened","Which event happened first","Why an event happened","Who was at the event"]',1,'It shows the order of time.','Timelines help us: Identify which event happened first.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_018','History','Basic History','Topic 2: Time and Chronology','Primary',1,'If a town builds a road in 1930 and an airport in 1960, which goes first on a timeline?','["The airport","The road","Both at the same time","Neither"]',1,'1930 is earlier than 1960.','The earliest event comes first... New road built — 1935. Airport opened — 1960.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_019','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What is an event?','["A place","A person","Something that happens","A type of calendar"]',2,'Like a birthday or a battle.','Event: Something that happens','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_020','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Which calendar is widely used for civil dates around the world today?','["Islamic calendar","Hebrew calendar","Gregorian calendar","Hindu calendar"]',2,'It is the standard international calendar.','Gregorian calendar: Widely used for civil dates around the world.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_021','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Is a plan made today considered history yet?','["Yes, immediately.","No, it is in the future.","Yes, if it is written down.","No, it is in the past."]',1,'History is about the past.','The future is not history yet. However, plans made today may become historical evidence in the future.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_022','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What does ''approximate date'' mean?','["A date that is exactly known.","A date that is not known exactly.","A date in the future.","A date from a lunar calendar."]',1,'Historians use this when they are guessing the year.','Approximate date: A date that is not known exactly','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_023','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What do historians use years for?','["To measure distance.","To identify when events happened.","To weigh objects.","To find directions."]',1,'It tells them ''when''.','Historians use years to identify when events happened.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_024','History','Basic History','Topic 2: Time and Chronology','Primary',1,'Does a simple timeline always have to be drawn exactly to scale?','["Yes, always.","No, a timeline may show important events without representing the exact amount of time between them.","Yes, or it is wrong.","No, they never have dates."]',1,'Sometimes they just show the order.','A timeline may show important events without representing the exact amount of time between them.','2026-11-01 09:40:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_025','History','Basic History','Topic 2: Time and Chronology','Primary',1,'What is a ''century'' equal to?','["Ten decades","One decade","Ten years","One thousand years"]',0,'Decade = 10. Century = 100.','A century contains ten decades... (10 x 10 = 100 years).','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_026','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why is understanding chronological order so important for historians?','["Because it tells them where an event happened.","Because it explains the exact weather of the past.","Because it helps them explain how people and societies changed over time.","Because it proves all calendars are the same."]',2,'You need to know what happened first to understand *why* the next thing happened.','Historians arrange past events in chronological order to explain how people and societies changed.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_027','History','Basic History','Topic 2: Time and Chronology','Primary',5,'If a timeline is drawn ''to scale'', what does that mean?','["It is drawn very small.","It is drawn using a ruler.","The spacing on the line corresponds exactly to the actual time intervals between events.","It only shows centuries, not years."]',2,'If ten years is 1 inch, then 20 years must be 2 inches.','A timeline drawn to scale uses spacing that corresponds to the time intervals.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_028','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Which century includes the year 1950?','["The 18th century","The 19th century","The 20th century","The 21st century"]',2,'The century number is usually one higher than the first two digits of the year.','The 20th century includes 1901–2000.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_029','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why did the 20th century officially begin in 1901 and not 1900?','["Because people forgot to count 1900.","Because the traditional BCE/CE calendar has no year zero, meaning the first century was years 1-100.","Because 1900 was a leap year.","Because calendars were different then."]',1,'Count 1 to 100. The next hundred starts at 101, not 100!','The 20th century did not begin in 1900. It began in 1901 because the traditional BCE/CE calendar has no year zero.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_030','History','Basic History','Topic 2: Time and Chronology','Primary',5,'How does BCE counting differ from CE counting?','["BCE dates count forward, CE counts backward.","BCE dates count backward as they approach the Common Era, while CE dates count forward.","They both count backward.","They both count forward."]',1,'500 BCE is older than 100 BCE!','BCE dates count backward as they approach the beginning of the Common Era. CE dates count forward.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_031','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Which of these BCE dates happened EARLIEST in history?','["100 BCE","50 BCE","500 BCE","1 BCE"]',2,'In BCE, the bigger the number, the older it is.','The larger BCE number represents the earlier date. (500 BCE happened earlier than 300 BCE).','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_032','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Place these dates in correct chronological order: 100 CE, 500 BCE, 100 BCE, 1000 CE.','["100 CE, 100 BCE, 500 BCE, 1000 CE","1000 CE, 100 CE, 100 BCE, 500 BCE","500 BCE, 100 BCE, 100 CE, 1000 CE","100 BCE, 500 BCE, 100 CE, 1000 CE"]',2,'BCE goes first, counting backwards. Then CE goes forwards.','Correct order: 500 BCE, 100 BCE, 200 CE, 1000 CE. (BCE counts down to 1, then CE counts up).','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_033','History','Basic History','Topic 2: Time and Chronology','Primary',5,'What is the main difference between a solar calendar and a lunar calendar?','["Solar uses the moon; lunar uses the stars.","Solar is based on Earth''s orbit around the Sun; lunar is based on the phases of the Moon.","Solar is used in winter; lunar is used in summer.","Solar has 10 months; lunar has 12."]',1,'Sol = Sun, Lunar = Moon.','A solar calendar is based mainly on the cycle of Earth''s orbit around the Sun. A lunar calendar is based on the phases of the Moon.','2026-11-01 09:40:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_034','History','Basic History','Topic 2: Time and Chronology','Primary',5,'If an event happened 2 centuries and 4 decades ago, how many years ago was it?','["24 years","60 years","240 years","2040 years"]',2,'100+100+10+10+10+10','Two centuries (200 years) + four decades (40 years) = 240 years.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_035','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why might dates from an old document not match our modern calendar?','["Because people in the past didn''t care about time.","Because the document might have been written using a different calendar system (like the Islamic, Hebrew, or traditional Chinese calendar).","Because time moved slower in the past.","Because sundials were always wrong."]',1,'Different cultures start counting their years from different events!','A date recorded under one calendar system may not match the same written date in another.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_036','History','Basic History','Topic 2: Time and Chronology','Primary',5,'What does it mean for a calendar to be ''lunisolar''?','["It ignores both the sun and the moon.","It combines lunar months with adjustments that keep the calendar aligned with the solar year.","It is only used at night.","It only has months, not years."]',1,'It tries to match the moon phases but stay in the right sun season.','A lunisolar calendar combines lunar months with adjustments that keep the calendar aligned with the solar year.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_037','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why is the label ''BCE'' (Before Common Era) often used in international education instead of ''BC'' (Before Christ)?','["Because BCE is older.","BCE and CE are neutral terms widely used for international and secular civil purposes, while BC/AD have specific religious meanings.","Because BC is too hard to spell.","Because calendars changed recently."]',1,'It allows people of all religions to use the same historical timeline labels.','BCE and CE are often used in international educational materials.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_038','History','Basic History','Topic 2: Time and Chronology','Primary',5,'What happens between 1 BCE and 1 CE on the timeline?','["Year Zero happens.","Nothing, the timeline moves directly from 1 BCE to 1 CE.","100 years pass.","The calendar restarts at 100."]',1,'It jumps straight from -1 to +1!','The conventional system moves directly from 1 BCE to 1 CE. There is no year zero in this historical calendar numbering.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_039','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Before modern clocks, how did a ''water clock'' likely measure time?','["By boiling water.","By freezing water into ice.","By observing the steady flow or dripping of water from one container to another.","By throwing water at a sundial."]',2,'They measured how long it took for the water to drain out.','Before modern clocks... people used methods such as: ... Using water clocks.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_040','History','Basic History','Topic 2: Time and Chronology','Primary',5,'If a historian finds an ancient vase, why might they only give it an ''approximate date''?','["Because it is broken.","Because there may be no exact written record or archaeological proof of the exact year it was made.","Because it was made in the future.","Because they lost their calendar."]',1,'Sometimes scientists have to make an educated guess!','Some ancient events have exact dates, while others have approximate dates based on archaeological or written evidence.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_041','History','Basic History','Topic 2: Time and Chronology','Primary',5,'In what millennium are we currently living (assuming the year is 2026)?','["The 1st millennium CE","The 2nd millennium CE","The 3rd millennium CE","The 20th millennium CE"]',2,'Years 1-1000 = 1st. Years 1001-2000 = 2nd. Years 2001-3000 = 3rd.','The 3rd millennium CE began in 2001 and ends in 3000.','2026-11-01 09:40:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_042','History','Basic History','Topic 2: Time and Chronology','Primary',5,'How many centuries are in one millennium?','["1","10","100","1000"]',1,'One century = 100 years. One millennium = 1000 years.','...a millennium contains ten centuries. (10 x 100 = 1,000).','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_043','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why do certain traditional or religious festivals move to different dates on the Gregorian calendar each year?','["Because they are celebrated randomly.","Because they are based on lunar or lunisolar calendars, whose cycles do not perfectly match the 365-day Gregorian solar calendar.","Because the Gregorian calendar changes every year.","Because leap years cancel them out."]',1,'A lunar year is shorter than a solar year, so the dates slide backwards!','These differences [between solar and lunar] help explain why certain festivals move from one date to another in the Gregorian calendar.','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_044','History','Basic History','Topic 2: Time and Chronology','Primary',5,'What defines an ''ordinary year'' in the Gregorian calendar?','["It has 366 days.","It has 365 days, based on one complete orbit of Earth around the Sun.","It has exactly 10 months.","It only has winter and summer."]',1,'It takes Earth 365 days to travel around the Sun.','In the commonly used Gregorian calendar, an ordinary year has 365 days...','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_045','History','Basic History','Topic 2: Time and Chronology','Primary',5,'If someone says ''the 1980s'', what specific years are they talking about?','["1980 through 1989","1900 through 1980","1800 through 1890","1980 through 2000"]',0,'It means the decade starting with 198.','These labels usually refer to years ending in the same digit range, such as 1980–1989...','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_046','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Which event happened LATEST in history?','["100 BCE","10 CE","500 BCE","50 CE"]',3,'Look for the biggest CE number.','CE dates count forward. (50 CE is later than 10 CE, and both are later than BCE dates).','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_047','History','Basic History','Topic 2: Time and Chronology','Primary',5,'Why is ''the present'' important to historians if they study ''the past''?','["It isn''t important to them at all.","Historians study the past, but they also examine how past events have shaped the present.","Because they only want to know what happens tomorrow.","Because the present is older than the past."]',1,'To understand today, you have to understand yesterday!','Historians study the past, but they also examine how past events have shaped the present.','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_048','History','Basic History','Topic 2: Time and Chronology','Primary',5,'If you see a timeline that is NOT drawn to scale, what must you be careful NOT to assume?','["That the events are in order.","That the physical distance between two events on the line represents the exact amount of time passed between them.","That the dates are BCE.","That the events actually happened."]',1,'A one-inch gap could mean 1 year or 1000 years!','Learners should check dates and spacing rather than assuming that all timelines are proportional.','2026-11-01 09:40:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_049','History','Basic History','Topic 2: Time and Chronology','Primary',5,'What is a leap year?','["A year with 365 days.","A year with 366 days.","A year with no summer.","A year in a lunar calendar."]',1,'February gets an extra day!','...while a leap year has 366 days.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_050','History','Basic History','Topic 2: Time and Chronology','Primary',5,'How does establishing a timeline help compare events from different regions (like a kingdom in Africa and an empire in Asia)?','["It makes them fight.","By organizing both regions'' events onto the same chronological timeline, historians can see if two events happened at the same time and might be connected.","It deletes the older events.","It proves one region is better."]',1,'It helps scientists see the ''big picture'' of world history all at once!','Timelines help us: ...Compare events from different periods... Recognize events that happened around the same time.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_051','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Analyze the mathematical implications of the absence of ''Year Zero'' in the Gregorian/historical calendar system.','["It means we cannot do math on dates.","Because it jumps from 1 BCE directly to 1 CE, calculating the exact time span across the BCE/CE divide requires subtracting 1 from the absolute sum of the years (e.g., from 5 BCE to 5 CE is 9 years, not 10).","It means centuries only have 99 years.","It proves the calendar is lunisolar."]',1,'If you are born in 1 BCE, how old are you in 1 CE? You are 1 year old, not 2!','The conventional system moves directly from 1 BCE to 1 CE. There is no year zero in this historical calendar numbering.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_052','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Evaluate the cultural significance of adopting the Gregorian calendar as the ''international civil standard''.','["It destroyed all other calendars.","It facilitated global synchronization for trade, aviation, and diplomacy, but it also imposed a European/Christian-derived timekeeping system onto diverse global cultures, often relegating indigenous/traditional calendars to secondary, ceremonial roles.","It proved the Sun orbits the Earth.","It stopped time from moving."]',1,'It made global business easier, but it means a western calendar is the default worldwide.','The Gregorian calendar is widely used for international civil purposes. However, many communities also use other calendars for religious, cultural...','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_053','History','Basic History','Topic 2: Time and Chronology','Primary',10,'How does a ''lunisolar'' calendar specifically resolve the seasonal drift inherent in a strict lunar calendar?','["It stops tracking the moon entirely.","A strict lunar year is ~354 days, causing it to drift through the solar seasons. A lunisolar calendar periodically inserts an ''intercalary'' (leap) month to realign the lunar months with the solar year and agricultural seasons.","It uses sand timers instead.","It makes the Earth orbit faster."]',1,'If they didn''t adjust it, a ''Spring'' festival would eventually happen in the middle of Winter!','A lunisolar calendar combines lunar months with adjustments that keep the calendar aligned with the solar year.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_054','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Explain the conceptual relationship between ''chronology'' and ''causality'' in historical study.','["Chronology prevents causality.","Chronology (the sequence of events) is the prerequisite for establishing causality (cause and effect); historians must prove Event A happened before Event B to argue that Event A *caused* Event B.","Chronology means cause; causality means time.","They are entirely unrelated concepts."]',1,'You can''t prove a king''s death caused a war unless you prove the king died *before* the war started!','Historians arrange past events in chronological order to explain how people and societies changed.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_055','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Why is identifying the specific ''calendar system'' of a primary source document critical for accurate historical dating?','["Because calendars dictate the language used.","An event recorded as occurring in the ''Year 1400'' in the Islamic calendar corresponds to a radically different Gregorian year (late 20th century) than ''Year 1400'' in the Gregorian calendar; failing to convert creates massive chronological errors.","Because it tells you the author''s name.","Because old calendars only had 5 months."]',1,'If a document from the Middle East says ''Year 500'', you must ask: 500 in *which* calendar?','A date recorded under one calendar system may not match the same written date in another. Researchers may also need to account for changes in calendar rules...','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_056','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Synthesize: How does the scale of a timeline affect the historical narrative it presents?','["Scale has no effect on narrative.","A timeline spanning millennia highlights broad evolutionary or civilizational shifts, minimizing individual human lives; a timeline spanning a decade emphasizes rapid political or personal changes, magnifying the agency of specific individuals.","Timelines can only be drawn at one specific scale.","Scale only changes the colors used."]',1,'Zoom out, and you see the rise and fall of empires. Zoom in, and you see the daily life of a king.','A timeline may cover a few days, several years, or thousands of years... A timeline drawn to scale uses spacing that corresponds to the time intervals.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_057','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Analyze the specific astronomical cycles that dictate the ''year'' versus the ''month'' in most traditional calendars.','["The year is based on stars; the month is based on planets.","The ''year'' is derived from Earth''s orbital period around the Sun (affecting seasons), while the traditional ''month'' was originally derived from the synodic period of the Moon''s phases (approx. 29.5 days).","Both are based purely on the Sun.","Both are based purely on the Moon."]',1,'Year = Earth goes around Sun. Month = Moon goes around Earth.','A solar calendar is based mainly on the cycle of Earth''s orbit around the Sun. A lunar calendar is based on the phases of the Moon.','2026-11-01 09:40:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_058','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Why is the exact dating of ancient events often reliant on cross-referencing multiple calendar systems?','["Because ancient people couldn''t count.","If an event (like an eclipse) is recorded in Chinese, Egyptian, and Babylonian records, historians can synchronize these different calendar dates with astronomical models to pinpoint the exact absolute Gregorian year.","Because calendars break easily.","Because all ancient calendars were identical."]',1,'It''s like finding a matching fingerprint in three different police databases to prove exactly when something happened!','Some ancient events have exact dates, while others have approximate dates based on archaeological or written evidence... Historians must consider the calendar used...','2026-11-01 09:40:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_059','History','Basic History','Topic 2: Time and Chronology','Primary',10,'What is the inherent limitation of using a ''sundial'' as a primary method of measuring time?','["It measures time backwards.","It is entirely dependent on direct sunlight, rendering it useless at night, indoors, or during heavily overcast weather, and it requires adjustment based on seasonal changes in the sun''s path.","It uses too much water.","It can only be used by kings."]',1,'No sun, no shadow, no time!','Using sundials to estimate time during daylight.','2026-11-01 09:40:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_time_060','History','Basic History','Topic 2: Time and Chronology','Primary',10,'Critique the division of history into rigid ''centuries'' (e.g., defining ''19th-century history'').','["Centuries are mathematically incorrect.","While mathematically convenient, historical trends do not obey strict 100-year boundaries. A major shift defining the ''19th century'' might have actually begun in 1789 and ended in 1914.","Centuries only apply to Europe.","Centuries are too short to measure history."]',1,'The ''20th Century'' technically started in 1901, but historians often say the ''Short 20th Century'' started with WWI in 1914!','A century is a period of one hundred years. (But history is fluid!).','2026-11-01 09:40:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_001','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What is an ancient civilization?','["A group of people who only hunt and gather","A complex human society with organized communities, government, and trade","A modern city with electricity","A type of dinosaur"]',1,'It involves cities, specialized jobs, and governments.','A civilization is a complex human society with organized communities and institutions.','2026-11-01 09:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_002','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Why did many ancient civilizations develop near rivers?','["Because rivers provided water, fertile soil, food, and transport","Because rivers were good for hiding from enemies","Because rivers had no fish","Because rivers made farming impossible"]',0,'Rivers are a great source of freshwater and mud for farming.','Many ancient civilizations developed near rivers because rivers supplied water, fertile soil, food, and transport.','2026-11-01 09:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_003','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What does ''agriculture'' mean?','["Building large stone pyramids","Growing crops and raising animals","Writing on clay tablets","Making bronze tools"]',1,'Another word for farming.','Agriculture: Growing crops and raising animals.','2026-11-01 09:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_004','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What does it mean to have a ''food surplus''?','["Having no food left","Producing more food than is immediately needed","Burning food in a fire","Eating all your food in one day"]',1,'Having extra food saved up.','Food surplus: In productive years, communities could produce more food than they immediately needed.','2026-11-01 09:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_005','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Where was ancient Mesopotamia located?','["In modern-day China","In modern-day Iraq and surrounding lands in West Asia","In South America","In Europe"]',1,'It means ''between rivers'' in Greek.','Mesopotamia was an ancient region in West Asia, mainly in the area of modern-day Iraq...','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_006','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which two major rivers were central to ancient Mesopotamia?','["Nile and Amazon","Indus and Ganges","Tigris and Euphrates","Yellow and Yangtze"]',2,'These rivers gave the region its name.','The two major rivers were: The Tigris River, The Euphrates River.','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_007','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What was cuneiform?','["A type of farming tool","A Roman road","An early writing system using wedge-shaped marks","An Egyptian king"]',2,'Scribes wrote it on clay tablets.','One of Mesopotamia''s most important contributions was cuneiform, an early writing system.','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_008','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Who was Hammurabi?','["An Egyptian Pharaoh","A famous ruler of Babylon known for a collection of laws","A Greek philosopher","An Indus Valley trader"]',1,'He wrote the Code of Hammurabi.','One famous ruler was Hammurabi of Babylon, associated with a collection of laws...','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_009','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which river was especially important to ancient Egypt?','["The Tigris","The Yellow River","The Nile","The Amazon"]',2,'It runs through northeastern Africa.','Ancient Egyptian civilization developed along the Nile River...','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_010','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What was a ruler of ancient Egypt called?','["Emperor","President","Pharaoh","Senator"]',2,'They held great political and religious importance.','Ancient Egypt was ruled for long periods by kings known as pharaohs.','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_011','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What writing system did the ancient Egyptians use?','["Cuneiform","Hieroglyphs","Latin alphabet","Indus script"]',1,'They used symbols representing words, sounds, or ideas.','The ancient Egyptians developed a writing system that included hieroglyphs...','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_012','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What was papyrus?','["A type of pyramid","A writing material made from a plant that grew near the Nile","An ancient Egyptian sword","A type of boat"]',1,'It was an early form of paper.','Papyrus was a writing material made from a plant that grew near the Nile.','2026-11-01 09:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_013','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What were the Egyptian pyramids primarily built as?','["Shopping markets","Royal tombs","Schools","Military forts"]',1,'They were giant monuments for dead pharaohs.','The pyramids are among the most famous structures of ancient Egypt. Some were built as royal tombs.','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_014','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Where did the Indus Valley Civilization develop?','["South America","Parts of present-day Pakistan and northwestern India","Southern Africa","Northern Europe"]',1,'It was a major early civilization of South Asia.','The Indus Valley Civilization developed in parts of present-day Pakistan and northwestern India.','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_015','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Name two important cities of the Indus Valley Civilization.','["Athens and Sparta","Rome and Pompeii","Harappa and Mohenjo-daro","Uruk and Babylon"]',2,'These cities had excellent town planning.','Important sites include Harappa and Mohenjo-daro.','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_016','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which river is closely associated with early Chinese civilization?','["The Nile","The Amazon","The Yellow River","The Tigris"]',2,'It had fertile soil but also caused severe floods.','Early Chinese societies developed in parts of East Asia, especially around the Yellow River...','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_017','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What is a dynasty?','["A type of river boat","A line of rulers from the same family or ruling group","A farming tool","An ancient written language"]',1,'The Shang and Zhou are examples.','A dynasty is a series of rulers from the same family or ruling line.','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_018','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What geographic features separated ancient Greek communities?','["Massive deserts","Mountains and islands","Thick jungles","Ice and glaciers"]',1,'This made it hard for them to unite into one country.','Mountains and islands separated many communities, so ancient Greece consisted of numerous independent city-states...','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_019','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which ancient Greek city-state developed an early form of democracy?','["Sparta","Troy","Athens","Rome"]',2,'It was a system where citizens could vote.','Athens developed an early form of democracy in which eligible male citizens could participate...','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_020','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What were the ancient Olympic Games?','["A war between city-states","Athletic festivals held at Olympia in honor of Zeus","A math competition","A type of Greek food"]',1,'They inspired the modern Olympics.','The ancient Olympic Games were athletic festivals held at Olympia in honor of Zeus.','2026-11-01 09:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_021','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Where did ancient Rome begin?','["In the Egyptian desert","In the Italian Peninsula","In the Indus Valley","In the Himalayan mountains"]',1,'It looks like a boot kicking a ball into the sea.','Rome began as a settlement in the Italian Peninsula and grew into a powerful state.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_022','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What did Roman aqueducts do?','["Carried armies across rivers","Carried water to towns and cities","Recorded laws","Made silk"]',1,'They looked like big stone bridges for water.','They also constructed... aqueducts, structures that carried water to towns and cities.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_023','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What language was spoken in ancient Rome?','["Greek","Egyptian","Latin","Chinese"]',2,'It influenced many modern languages like Spanish and French.','Latin was the language of ancient Rome.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_024','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What does an archaeologist study?','["The stars and planets","Past human life through material remains","Modern laws","Weather forecasting"]',1,'They dig up old cities and artifacts.','Archaeology: The study of past human life through material remains.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_025','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What is a ''city-state''?','["A city that is completely underwater","A city and its surrounding territory governed as a political unit","A state with no cities","A modern country"]',1,'Athens, Sparta, and Uruk are examples.','A city-state was a city and the surrounding territory governed as a political unit.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_026','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How did producing a ''food surplus'' change early societies?','["It made everyone sick.","It allowed some people to stop farming and become specialized workers like potters, builders, or traders.","It caused the rivers to dry up.","It forced everyone to move away."]',1,'If one farmer grows enough food for three people, the other two can do different jobs!','In productive years, communities could produce more food than they immediately needed. Specialized jobs: Some people became potters, builders, traders...','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_027','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why did communities in Mesopotamia develop ''irrigation'' systems?','["To drown their enemies.","Because rainfall was limited in many areas, they needed canals to carry river water to their farmland to grow crops.","To wash their stone roads.","Because they had too much rain."]',1,'It''s a way of moving water to where the plants need it.','Because rainfall was limited in many areas, communities developed irrigation systems. Canals helped carry river water to farmland.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_028','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What makes the ''Indus script'' different from Egyptian hieroglyphs or Mesopotamian cuneiform?','["It was written on paper.","It has not yet been deciphered with certainty, so historians cannot read it.","It was only used by kings.","It is fully understood by modern scientists."]',1,'We can see their writing, but we still don''t know what the words mean!','The Indus people used symbols on seals... This writing system has not yet been deciphered with certainty.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_029','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What is a key difference between ancient Athenian democracy and modern democracy?','["Ancient Athens let everyone vote, but modern democracy does not.","Ancient Athenian democracy excluded women, enslaved people, and non-citizens from participating, whereas modern democracy gives adult citizens much broader rights.","Ancient Athens only let women vote.","There is no difference at all."]',1,'It was a democracy, but only for a small group of men.','Athens developed an early form of democracy... However, women, enslaved people, and many residents who were not citizens were excluded.','2026-11-01 09:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_030','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What physical evidence shows that Indus Valley cities like Harappa were highly organized?','["They had giant pyramids.","Archaeologists found carefully planned streets, brick buildings, wells, and advanced drains that carried wastewater away.","They left behind millions of books.","They had cars and trains."]',1,'They had a sewage system thousands of years before many modern cities!','Archaeologists have found evidence of: Carefully planned streets. Brick buildings. Wells and water systems. Drains...','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_031','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why was the seasonal flooding of the Nile River actually a good thing for ancient Egyptians?','["It washed away their enemies.","It historically deposited fertile soil on the riverbanks, which was perfect for growing crops in the middle of a desert.","It made the pyramids shiny.","It filled their swimming pools."]',1,'The flood brought rich, dark mud that plants love to grow in.','Much of Egypt is desert... Seasonal flooding historically deposited fertile soil in many areas beside the river.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_032','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How did early writing develop in civilizations like Mesopotamia?','["It was invented instantly to write poetry.","It started as a practical way to keep records of goods, taxes, and trade, before expanding into stories and laws.","It was taught to them by the Greeks.","It was only used to write letters to other countries."]',1,'They needed a way to remember who paid their taxes and how much wheat they had!','Early writing was often used for practical record-keeping before it expanded into many other forms.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_033','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why is ''mummification'' significant when studying ancient Egypt?','["It proves they didn''t care about the dead.","It shows that religion was important, specifically their strong beliefs about life after death, as they wanted to preserve bodies for burial.","It shows they had advanced freezing technology.","It proves everyone in Egypt was wealthy."]',1,'They believed you needed your body in the afterlife!','Mummification was practiced... to preserve bodies for burial. Many Egyptians... held beliefs about life after death.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_034','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How did the geography of ancient Greece affect its political organization?','["The flat plains made it easy to unite under one king.","Mountains and islands separated communities, causing them to develop into numerous independent, self-governing city-states instead of one large empire.","The thick jungles made them build treehouses.","The rivers forced them to build pyramids."]',1,'It''s hard to rule a country when there are giant mountains and oceans between every city!','Mountains and islands separated many communities, so ancient Greece consisted of numerous independent city-states...','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_035','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What was the purpose of the extensive road networks built by the Romans?','["To host chariot races.","To connect settlements and help quickly move people, goods, and armies across their vast empire.","To block rivers from flooding.","To stop people from traveling."]',1,'They needed smooth roads so their soldiers could march quickly to anywhere in the empire!','The Romans built extensive road networks to connect settlements and help move people, goods, and armies.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_036','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Who were Socrates, Plato, and Aristotle?','["Famous Roman emperors.","Ancient Greek thinkers and philosophers who asked questions about nature, knowledge, and government.","Egyptian pharaohs who built pyramids.","Indus Valley traders."]',1,'They were some of the most famous teachers in history.','Greek thinkers asked questions about nature, knowledge, government... Important figures included: Socrates... Plato... Aristotle...','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_037','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why do historians believe that the decline of the Indus Valley Civilization was NOT just caused by an invasion?','["Because aliens took them away.","Because evidence points to multiple contributing factors, including changes in river systems, shifts in climate/rainfall, and changes in trade patterns.","Because they moved to Rome.","Because they are still living there exactly the same way."]',1,'Civilizations usually fall because of many complex reasons, not just one battle!','Possible contributing factors include changes in river systems, shifts in rainfall... The evidence does not support simply claiming that one invasion caused the entire civilization to disappear.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_038','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What did the ancient Chinese civilizations primarily cultivate in the north vs. the south?','["They grew apples in the north and oranges in the south.","Millet was important in northern China, while rice became important in southern China.","They only grew wheat everywhere.","They didn''t grow crops; they only hunted."]',1,'Different climates are good for growing different crops!','Millet was important in parts of northern China, while rice became important in southern China.','2026-11-01 09:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_039','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What was the ''Code of Hammurabi''?','["A secret password to enter Babylon.","An important collection of recorded laws and punishments from an ancient Mesopotamian ruler.","A medical textbook from Egypt.","A Greek philosophy book."]',1,'It is one of the oldest sets of written laws ever found!','One famous ruler was Hammurabi of Babylon, associated with a collection of laws known as the Code of Hammurabi.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_040','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why shouldn''t we assume that all ancient civilizations developed in the exact same sequence?','["Because none of them ever developed.","Because historical evidence shows that different regions solved problems in different ways, and changes happened at different times based on local environments.","Because the Romans stopped them.","Because they all copied from each other perfectly."]',1,'People in a desert solve problems differently than people in a jungle!','Ancient civilizations did not all develop at the same time or in the same way... These changes happened gradually. Not every civilization followed the same sequence.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_041','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Analyze how the concept of ''civilization'' can be a misleading term if interpreted too narrowly.','["It implies that only humans exist on Earth.","The word ''civilization'' often focuses on cities, but it does not mean every person lived in one; farmers, herders, and smaller settlements were equally crucial components of these complex societies.","It implies that all ancient people were uncivilized and aggressive.","It suggests that civilization only existed in the year 2000."]',1,'A city can''t survive without the farmers outside the city growing the food!','The word civilization does not mean that every person lived in a city. Farmers, herders, craftspeople... and people in smaller settlements were also important parts of these societies.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_042','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Evaluate the relationship between ''specialization of labor'' and ''record-keeping'' in early civilizations.','["Specialization made record-keeping illegal.","As populations grew and people took on specialized jobs (like crafting or trading), the economy became complex, requiring a formal system of writing (like cuneiform) to track surplus goods, taxes, and trade exchanges.","Record-keeping caused people to stop doing specialized jobs.","They are completely unrelated concepts."]',1,'When you trade 100 pots for 500 bags of wheat, you need a way to write that down so you don''t forget!','Specialized jobs... Trade and cultural exchange... Writing and record-keeping: Some societies developed writing to record goods, taxes, laws, and events.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_043','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'How does the inability to decipher the Indus script affect modern historiography of the Indus Valley Civilization?','["It forces historians to completely ignore the Indus Valley.","Historians cannot read their laws, myths, or political records, forcing them to rely almost entirely on physical archaeological evidence (like city layouts and tools) to infer how the society functioned.","It proves that the Indus people had no language.","It means historians must guess their history randomly."]',1,'Without a written voice, the buildings and objects have to tell the whole story.','This writing system has not yet been deciphered... As a result, historians depend heavily on archaeological evidence to understand the civilization.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_044','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Critique the historical narrative that the Roman Empire simply ''fell'' in the 5th century CE.','["The Roman Empire fell in the 1st century, not the 5th.","While the Western Roman Empire collapsed in the fifth century CE, the Eastern Roman Empire (with its capital at Constantinople) continued to thrive and preserve Roman traditions for many more centuries.","The entire Roman Empire still exists exactly as it did today.","The Roman Empire never actually existed."]',1,'Half of the empire fell, but the other half lived on for another 1000 years!','The Roman Empire in the West ended in the fifth century CE. The eastern Roman Empire continued for many centuries, with its capital at Constantinople.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_045','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Synthesize how the geography of ancient Egypt dictated its monumental architecture and administrative organization.','["The freezing temperatures required them to build ice castles.","The harsh desert confined the population to the narrow, fertile Nile valley. This linear geography made central administrative control by Pharaohs easier and provided the vast, coordinated labor force necessary to construct massive stone pyramids.","The endless forests allowed them to build giant wooden treehouses.","The geography had no effect on their architecture."]',1,'Everyone had to live near the river, making it easier for the Pharaoh to rule them all!','Much of Egypt is desert, so the Nile was especially important... Organizing agriculture, collecting taxes... and building large structures required coordination.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_046','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Explain the engineering significance of Roman ''aqueducts'' and how they catalyzed urban growth.','["They were used to transport soldiers over mountains.","Aqueducts were highly engineered structures utilizing a precise gradient and gravity to transport fresh water over massive distances, solving the sanitation and drinking needs of dense, growing urban populations like Rome.","They were giant walls built to keep out floods.","They were early forms of Roman internet cables."]',1,'You can''t have a giant city with millions of people if you don''t have enough clean water to drink and bathe in!','...aqueducts, structures that carried water to towns and cities. Some aqueducts used gravity to move water over long distances. Roman engineering helped support urban life...','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_047','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Analyze the ideological contrast between the Greek city-states of Athens and Sparta.','["Athens was an empire, while Sparta was a small village.","Athens prioritized civic participation, developing an early (though exclusionary) form of democracy, philosophy, and art. In stark contrast, Sparta engineered a rigidly disciplined society with a primary focus on military strength and different political controls.","Athens focused only on war, while Sparta focused on art.","They had the exact same political system."]',1,'They were neighbors, but they had completely opposite ideas of what a perfect society looked like.','Athens developed an early form of democracy... Sparta, by contrast, developed a society with a strong military focus and a different political system.','2026-11-01 09:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_048','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Why is it historically inaccurate to attribute the invention of paper, printing, and gunpowder strictly to the ''early river civilizations'' of China?','["Because those were invented by the Romans.","While ancient Chinese river societies laid foundational technologies (like bronze and silk), inventions like paper, printing, and gunpowder were developed by later Chinese dynasties over many subsequent centuries.","Because those inventions do not actually exist.","Because they were invented before the Yellow River existed."]',1,'History is a long process; the people who started the civilization didn''t invent everything on day one!','Paper, printing, the compass, and gunpowder became important Chinese inventions in later periods; they should not all be attributed to the earliest river civilizations.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_049','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'How did the ''Code of Hammurabi'' represent a shift in the conceptualization of government and justice in Mesopotamia?','["It proved that kings did not care about justice.","By physically recording a standardized collection of laws and punishments, it represented a shift from arbitrary, unwritten royal decrees to a formal, accessible legal framework that governed the city-state.","It outlawed all forms of government.","It was a book of poems, not laws."]',1,'Writing down the laws meant the King couldn''t just change his mind every day; the rules were set in stone!','One famous ruler was Hammurabi... associated with a collection of laws... This code is important evidence of how one ancient kingdom recorded laws and punishments.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_050','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Evaluate the cultural legacy of the ''Latin'' language after the decline of the Western Roman Empire.','["It disappeared completely and is never spoken today.","Latin did not vanish; it fragmented and evolved organically over centuries into the modern Romance languages (Italian, Spanish, French, Portuguese, Romanian), profoundly influencing global linguistics.","It remained exactly the same and is the official language of every country.","It was only used for writing, never speaking."]',1,'Even if Rome fell, their language evolved and is still spoken by billions of people today in different forms!','Latin was the language of ancient Rome. It influenced several modern languages, including Italian, Spanish, French, Portuguese, and Romanian.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_051','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What was the main purpose of Egyptian mummification?','["To make people look younger","To preserve bodies for burial and the afterlife","To turn people into statues","To cure diseases"]',1,'They wanted the body to last forever.','Mummification was practiced... to preserve bodies for burial.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_052','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What does ''Mesopotamia'' mean in Greek?','["Land of the sun","Between rivers","Great mountain","Desert sand"]',1,'It refers to the Tigris and Euphrates.','Its name comes from Greek words meaning ''between rivers.''','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_053','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which civilization is known for early bronze casting and silk production?','["Ancient Greece","Ancient China","Ancient Rome","Indus Valley"]',1,'Silk comes from silkworms native to this region.','Ancient Chinese societies made important contributions to: ...Bronze casting. Silk production.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_054','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What shape were the marks in cuneiform writing?','["Circles","Squares","Wedge-shaped","Stars"]',2,'A wedge is thick at one end and thin at the other.','Scribes pressed a cut reed into soft clay tablets to create wedge-shaped marks.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_055','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Who is known for a theorem about right-angled triangles?','["Plato","Socrates","Pythagoras","Hammurabi"]',2,'A squared + B squared = C squared.','Pythagoras: Associated with a mathematical tradition and a theorem about right-angled triangles.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_056','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why did ancient Greek communities exchange goods and ideas with neighboring peoples via the sea?','["Because they couldn''t walk on land.","Because their mountainous geography made land travel difficult, making the Mediterranean and Aegean seas vital highways for trade and communication.","Because they were afraid of mountains.","Because the sea was completely dry."]',1,'If mountains block your path, you build a boat!','Mountains and islands separated many communities... The sea supported fishing, travel, and trade.','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_057','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How does the structure of Roman government during its ''republic'' phase compare to its ''empire'' phase?','["They were exactly the same.","During the republic, elected officials and the Senate had power; during the empire, central authority shifted to powerful emperors.","During the republic, there was an emperor; during the empire, there was a king.","Rome was always ruled by a Queen."]',1,'A republic has voting; an empire has one ultimate ruler.','During the republic, elected officials and the Senate played important roles. During the empire, emperors held central authority...','2026-11-01 09:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_058','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why are ''standardized weights and measures'' in the Indus Valley a sign of an advanced civilization?','["Because it means they liked math.","It proves they had an organized central authority that regulated trade, ensuring fairness and consistency across their vast cities.","Because it means they had heavy rocks.","It doesn''t mean anything."]',1,'If a merchant in one city sells a ''pound'' of grain, it has to weigh the same as a ''pound'' in another city!','Archaeologists have found evidence of... Standardized weights and measures. These discoveries show that some Indus cities had sophisticated systems for managing urban life.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_059','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Critique the traditional view of a ''civilization'' utilizing the existence of marginalized groups like enslaved people in Athens and Rome.','["Civilizations were perfect utopias for everyone.","While civilizations represent complex organization and monumental achievements, they were also highly stratified and unequal. The ''golden ages'' of Athenian democracy and Roman engineering were fundamentally subsidized by the widespread exploitation and exclusion of enslaved peoples and non-citizens.","Civilizations did not have enslaved people.","Only modern societies have inequality."]',1,'The beautiful temples and roads were often built by people who had no freedom.','However, women, enslaved people, and many residents who were not citizens were excluded [in Athens]... Roman society was unequal, and slavery was widespread.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_060','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which ancient river is associated with early Chinese civilization alongside the Yellow River?','["The Nile","The Yangtze (and other river regions)","The Amazon","The Thames"]',1,'It''s another major river in China.','Early Chinese societies developed in parts of East Asia, especially around the Yellow River and later other river regions.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_061','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What natural event helped deposit fertile soil along the Nile River?','["Earthquakes","Tornadoes","Seasonal flooding","Snowstorms"]',2,'When the river overflowed, it left good mud behind.','Seasonal flooding historically deposited fertile soil in many areas beside the river.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_062','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why did early Chinese communities need methods to manage water and land around the Yellow River?','["Because the river was made of lava.","Because while the river carried fertile soil, it could also cause severe and destructive floods.","Because they wanted to drain the river completely.","Because the river had no water."]',1,'You need water to farm, but too much water destroys the farm!','The Yellow River carried fertile soil but could also cause severe floods. Communities developed farming practices and methods of managing water...','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_063','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How did the invention of papyrus help the ancient Egyptian government?','["It was used as a weapon.","It provided a lightweight, durable writing material for scribes to easily record taxes, laws, and official information.","It was used to build the pyramids.","It was a type of food for the Pharaoh."]',1,'Before paper, carrying heavy clay tablets or carving stone was very slow!','Papyrus was a writing material made from a plant... Scribes recorded religious texts, government information, business activities...','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_064','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Analyze the function of ''philosophy'' in ancient Greece as a tool for societal development.','["It was just a way to waste time.","Greek philosophy (led by figures like Socrates and Plato) represented a critical shift towards using rational inquiry, logic, and systematic questioning to understand nature, ethics, and government, laying the intellectual foundations for Western scientific and political thought.","It was used exclusively to train soldiers.","It prevented any new inventions from being made."]',1,'Instead of just accepting that ''the gods did it'', they started asking ''why'' and ''how''!','Greek thinkers asked questions about nature, knowledge, government, and human behavior... Socrates: Known for questioning...','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_065','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which continent is ancient Egypt located on?','["Asia","Europe","Africa","South America"]',2,'It''s in the northeast corner of this continent.','Ancient Egyptian civilization developed along the Nile River in northeastern Africa.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_066','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What did scribes in Mesopotamia use to write on clay tablets?','["A modern pen","A cut reed","A feather","A piece of chalk"]',1,'They used plants growing near the river.','Scribes pressed a cut reed into soft clay tablets to create wedge-shaped marks.','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_067','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which Chinese dynasty ruled during the second millennium BCE?','["The Ming dynasty","The Shang dynasty","The Han dynasty","The Qing dynasty"]',1,'It is one of the earliest with written evidence.','The Shang dynasty, which ruled during the second millennium BCE, is one of the earliest...','2026-11-01 09:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_068','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What is a major river in ancient Egypt?','["The Nile","The Tigris","The Yellow River","The Euphrates"]',0,'It''s the longest river in Africa.','Ancient Egyptian civilization developed along the Nile River...','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_069','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What type of society did Sparta develop?','["A society focused on art","A society with a strong military focus","A society run by scientists","A peaceful farming village"]',1,'They were famous warriors.','Sparta, by contrast, developed a society with a strong military focus...','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_070','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'Which Greek thinker studied subjects including nature, logic, and politics?','["Socrates","Plato","Aristotle","Archimedes"]',2,'He was a famous student of Plato.','Aristotle: A thinker who studied subjects including nature, logic, and politics.','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_071','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'At its greatest extent, what major sea did the Roman Empire control lands around?','["The Caribbean Sea","The Mediterranean Sea","The Bering Sea","The Dead Sea"]',1,'It''s the sea between Europe and Africa.','At its greatest extent, the Roman Empire controlled lands around much of the Mediterranean Sea...','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_072','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',1,'What city was the capital of the eastern Roman Empire?','["Rome","Athens","Constantinople","Babylon"]',2,'It was named after an emperor.','The eastern Roman Empire continued for many centuries, with its capital at Constantinople.','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_073','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why is the Epic of Gilgamesh important to historians studying Mesopotamia?','["It proves they had spaceships.","It is a piece of literature that provides insight into their culture, beliefs, and early forms of storytelling.","It is a mathematical formula.","It is a recipe for bread."]',1,'Stories tell us what people cared about.','Mesopotamian societies contributed to: ...Literature, including the Epic of Gilgamesh.','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_074','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'How did ancient Egyptian farmers benefit from the work of government officials?','["The officials did all the farming for them.","Officials helped organize agriculture, collect taxes, and maintain the complex irrigation works that farmers needed to water their crops.","The officials paid the farmers to do nothing.","There were no officials in Egypt."]',1,'Big projects need leaders to organize everyone.','Organizing agriculture, collecting taxes, maintaining irrigation, and building large structures required coordination.','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_075','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'Why are the ancient Olympic Games historically significant?','["Because they gave out gold medals.","They were major athletic festivals held in honor of Zeus that helped unite Greek city-states culturally and inspired the modern Olympic Games.","Because they invented football.","Because they were fought with real swords."]',1,'It was a massive religious and sports festival.','The ancient Olympic Games were athletic festivals held at Olympia in honor of Zeus. They were different from the modern Olympic Games...','2026-11-01 09:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_076','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',5,'What did the later Zhou dynasty contribute to Chinese civilization?','["They invented the first airplane.","They influenced Chinese political ideas and culture, building upon the earlier Shang dynasty.","They destroyed the Yellow River.","They moved the civilization to Europe."]',1,'They changed how the government was run.','The later Zhou dynasty influenced Chinese political ideas and culture.','2026-11-01 09:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_civ_077','History','Ancient Civilizations','Topic 5: Ancient Civilizations','Primary',10,'Analyze the architectural differences between Egyptian Pyramids and Roman Aqueducts in terms of their societal function.','["Pyramids were for water; aqueducts were for dead kings.","Pyramids served an ideological, religious, and elite function as monumental royal tombs. Aqueducts served a utilitarian, public infrastructure function, enabling mass urbanization and sanitation for the general populace.","Both were used strictly for military defense.","Neither structure required any advanced engineering."]',1,'One was built to glorify a dead king; the other was built to give living people water to drink.','The pyramids... were built as royal tombs. ...aqueducts, structures that carried water to towns and cities. Roman engineering helped support urban life...','2026-11-01 09:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_001','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is an invention?','["Finding an unknown animal","A new device, process, or method created to solve a problem","Studying natural rocks","Observing the stars"]',1,'It is something built or created by humans.','An invention is a new device, process, or method created to solve a problem or perform a task.','2026-11-01 10:00:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_002','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is a discovery?','["Building a new machine","Inventing the wheel","The identification of something that already exists but was previously unknown","Writing a new book"]',2,'Finding a new planet is an example.','A discovery is the identification or recognition of something that already exists...','2026-11-01 10:00:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_003','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Which of the following is an example of an invention?','["Discovering a new planet","Finding a new species of bird","The telephone","Finding an archaeological site"]',2,'Someone had to build and design it.','The telephone, which made it possible to transmit speech over a distance.','2026-11-01 10:00:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_004','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Which of the following is an example of a discovery?','["The printing press","The electric light bulb","Identifying a microorganism using a microscope","The computer"]',2,'The microorganism was already there; someone just found it.','Identifying a microorganism using scientific instruments [is a discovery].','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_005','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Why do people invent things?','["To solve problems and make tasks easier","Only to waste time","To hide things from others","Because nature tells them to"]',0,'Inventions help us do things faster and safer.','People invent things for many reasons: To solve problems... To save time... To improve safety...','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_006','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is an early model used to test an idea called?','["A fossil","A prototype","A discovery","An ancient tool"]',1,'Inventors build these before making the final version.','Prototype: An early model used to test an idea.','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_007','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How does an invention usually differ from a discovery in terms of its purpose?','["Inventions are always found in nature, while discoveries are built in factories.","An invention often solves a practical problem, while a discovery often expands our knowledge of the natural world.","Inventions are only for scientists, while discoveries are for ordinary people.","There is no difference between them."]',1,'You invent a hammer to build a house; you discover a star to understand space.','Invention: Often solves a practical problem. Discovery: Often expands knowledge.','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_008','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why are many inventions NOT created in a single moment by one person?','["Because it is illegal to invent alone.","Because they develop gradually through a series of improvements, testing, correcting mistakes, and using the work of earlier inventors.","Because they are actually discoveries.","Because people in the past were not smart enough."]',1,'Modern airplanes rely on decades of tests and improvements!','Many inventions are not created in a single moment. They develop through a series of improvements... testing, correcting mistakes...','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_009','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How can an invention and a discovery work together? Give an example from the text.','["They cannot work together.","Developing a telescope (an invention) allowed people to find new objects in space (a discovery).","Discovering a wheel allowed people to invent the planet Jupiter.","Inventions destroy discoveries."]',1,'You invent a tool to discover a fact!','Developing a telescope required inventing an instrument, while using telescopes has helped people discover objects in space.','2026-11-01 10:00:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_010','History','Basic History','Topic 6: Inventions and Discoveries','Primary',10,'Critique the ''lone genius'' myth of historical inventions (e.g., ''Thomas Edison invented the light bulb by himself'').','["The lone genius myth is entirely accurate for all historical inventions.","Most breakthrough technologies are highly iterative and collective; the practical light bulb, for instance, relied on preceding electrical discoveries and the combined engineering of multiple inventors to become viable.","It means inventors must work in complete isolation to be successful.","It proves that inventions only happen by accident."]',1,'No one invents something out of thin air; they build on the work of those before them!','The practical electric light bulb, developed through contributions by several inventors and engineers... Many inventions are not created in a single moment.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_011','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'How were the earliest stone tools made?','["By melting stone in a fire","By striking one stone against another to remove flakes and create a sharp edge","By carving them with metal tools","By finding them naturally shaped"]',1,'Hitting rocks together makes them sharp!','Stone tools were made by striking stones together to produce sharp edges... a method known as stone knapping.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_012','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Why don''t we find many early prehistoric tools made of wood or plant fibers?','["Because they decay and rot more quickly than stone","Because early humans hated wood","Because wood is too heavy","Because animals ate all the wooden tools"]',0,'Wood rots in the dirt, but stone lasts forever.','Many early tools made from these materials have not survived because they decay more easily than stone.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_013','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What was one major benefit of early humans learning to use fire?','["It allowed them to breathe underwater","It helped them cook food and keep warm","It instantly built their houses","It provided a way to fly"]',1,'It made survival in cold climates possible.','Fire helped people: Keep warm in cold conditions. Cook food. Provide light...','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_014','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is the wheel considered in human history?','["A natural discovery","One of the most important inventions","A type of farming tool","A dangerous weapon"]',1,'It changed how we travel and work.','The wheel is one of the most important inventions in human history.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_015','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What did the invention of the plough help farmers do?','["Harvest wheat","Turn and prepare the soil for planting crops","Water the crops","Cut down trees"]',1,'It mixes the dirt so seeds can grow.','The plough helped turn and prepare soil in many farming systems.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_016','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is an alloy?','["A wooden tool","A material made by combining a metal with one or more other elements","A type of wild animal","A prehistoric fire"]',1,'Bronze is an alloy of copper and tin.','Alloy: A material made by combining a metal with one or more other elements.','2026-11-01 10:00:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_017','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is bronze made from?','["Iron and gold","Mainly copper and tin","Stone and wood","Silver and lead"]',1,'Mixing these two soft metals makes a hard one!','Bronze: An alloy usually made mainly from copper and tin.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_018','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Besides transportation, what other important early technology did the wheel support?','["It helped people make fire.","It supported pottery-making, where a rotating wheel helped shape clay.","It was used as a weapon in hunting.","It was used to track the stars."]',1,'Potters spin clay on a wheel to make perfectly round bowls.','Wheel technology also supported pottery-making, where a rotating wheel helped shape clay.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_019','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why was the wheel NOT a useful invention in every single ancient environment?','["Because the wheel was banned by early kings.","Wheels require suitable terrain and roads; in thick jungles, deep sand, or steep mountains, people relied on boats, sledges, or pack animals instead.","Because wheels were too small to see.","Because wheels would always catch on fire."]',1,'A cart is useless if you live in the middle of a rocky mountain!','However, wheels were not useful in every environment. People also used boats, sledges, pack animals...','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_020','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why was the development of ''irrigation'' crucial for the survival of some farming communities?','["It stopped crops from growing too fast.","It provided a system of water channels to move water to fields in areas where natural rainfall was insufficient or unreliable.","It kept wild animals away from the farms.","It was a way to travel across the ocean."]',1,'If it doesn''t rain, you have to bring the river to your farm!','Irrigation channels moved water to fields, particularly where rainfall was insufficient or unreliable.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_021','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why did early humans need specialized knowledge and skills to develop metalworking (like making bronze or iron tools)?','["Because metals are very light and easy to cut.","Because metalworking requires advanced techniques like mining ores, reaching extremely high temperatures for heating, and combining elements to shape them.","Because metal is found perfectly shaped in nature.","Because only certain people were allowed to touch metal."]',1,'You can''t just hit a rock to make an iron sword; you need a hot forge and chemistry!','Metalworking required specialized knowledge and skills, including heating, shaping, and sometimes combining metals.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_022','History','Basic History','Topic 6: Inventions and Discoveries','Primary',10,'Analyze the environmental and geographic determinism involved in the adoption of wheeled transport in early civilizations.','["Every civilization on Earth adopted the wheel immediately.","The adoption of the wheel was heavily dependent on geography. Civilizations in flat, dry river valleys (like Mesopotamia) adopted it rapidly for carts, while societies in dense rainforests or mountainous regions (like the Andes) optimized alternative transport networks (pack animals/footpaths) due to terrain constraints.","Wheels were only used in areas with heavy snowfall.","Geography had absolutely no impact on technological adoption."]',1,'Technology must fit the landscape!','Wheeled carts made it easier to move heavy loads where terrain and road conditions allowed... However, wheels were not useful in every environment.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_023','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What did the domestication of animals like horses and camels help people do?','["Build taller buildings","Transport goods and travel over longer distances","Cook their food faster","Read books"]',1,'They could ride them or use them to pull carts.','The domestication of animals... helped people transport goods and travel over longer distances...','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_024','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What powered the sailing ships used for ocean travel?','["Electricity","Steam engines","Wind","Solar power"]',2,'They used giant fabric sails to catch the breeze.','Sailing ships used wind to travel across seas and oceans.','2026-11-01 10:00:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_025','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What machine became incredibly important during the Industrial Revolution for pulling railway trains?','["The electric car engine","The steam locomotive","The airplane engine","The computer"]',1,'They used coal and boiling water to move.','During the Industrial Revolution... Steam locomotives powered railway trains...','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_026','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Who is widely recognized for making the first controlled, powered, heavier-than-air flight in 1903?','["Johannes Gutenberg","Alexander Graham Bell","The Wright brothers","Galileo Galilei"]',2,'They invented the first successful airplane.','In 1903, the Wright brothers achieved a widely recognized milestone by making a controlled, sustained flight... at Kitty Hawk.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_027','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is a ''motor vehicle''?','["A bicycle","A road vehicle powered by an engine or electric motor","A train pulled by horses","A sailing ship"]',1,'Cars, buses, and trucks are examples.','Motor vehicle: A road vehicle powered by an engine or electric motor.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_028','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How did the invention of railways change where and how people lived and worked?','["It forced everyone to live in the forest.","Railways connected distant towns, ports, mines, and factories, allowing people and goods to move quickly, which completely changed settlement patterns and trade.","It stopped people from trading with each other.","It caused people to only travel by boat."]',1,'You could live in the country and take the train to work in the city!','Railways helped connect towns, cities, ports, mines, farms, and factories. They also changed work, settlement patterns, and trade.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_029','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'What were some of the negative challenges introduced by the expansion of the railway?','["It made travel too slow.","It could involve environmental damage, dangerous working conditions for builders, and the forced displacement of local communities.","It caused the invention of the car.","It made the oceans dry up."]',1,'Building tracks meant destroying nature and sometimes forcing people off their land.','However, railway expansion could involve environmental damage, dangerous working conditions, and displacement of communities.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_030','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'While motor vehicles made individual travel highly flexible, what new problems did they create for modern societies?','["They made roads completely empty.","They caused severe traffic congestion, road accidents, air pollution, and a heavy reliance on fossil fuels.","They forced people to walk more.","They made travel too expensive for everyone."]',1,'Cars are great, but traffic jams and smog are terrible side effects!','Motor vehicles also created challenges, including traffic congestion, road accidents, air pollution, and dependence on fuel.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_031','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why was the development of better navigation methods and maps crucial for ancient sailing ships?','["Because sailors wanted to read books on the ship.","Without landmarks in the open ocean, advanced instruments and maps were required to safely guide ships on long voyages for trade or exploration.","Because the boats were too small.","Because the wind would always blow them backward."]',1,'You can easily get lost in the middle of the ocean!','Better navigation methods, maps, and instruments helped sailors undertake longer voyages.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_032','History','Basic History','Topic 6: Inventions and Discoveries','Primary',10,'Synthesize the dualistic impact of maritime technological advancements (advanced sailing ships) on global history.','["Sailing ships were only used to trade spices and had no negative impacts.","While maritime advancements facilitated unprecedented global trade, cultural exchange, and scientific exploration, they simultaneously enabled devastating warfare, imperial colonization, and the forced transatlantic movement of enslaved peoples.","Sailing ships completely destroyed global trade.","Sailing ships prevented any contact between different continents."]',1,'Ships connected the world, but they also brought cannons and conquerors to new shores.','Sea travel supported trade and cultural exchange, but it also contributed to warfare, colonization, and the forced movement of people.','2026-11-01 10:00:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_033','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What was a major benefit of developing a writing system?','["It allowed people to run faster.","It allowed people to record information beyond what could be remembered or passed on by speech alone.","It stopped people from talking.","It helped build brick walls."]',1,'You don''t have to memorize a book if you can read it!','Writing was a major development because it allowed people to record information beyond what could be remembered...','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_034','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Which ancient society invented paper-making?','["Ancient Egypt","Ancient Greece","Ancient China","Mesopotamia"]',2,'It eventually spread to the rest of the world.','Paper-making developed in China in ancient times...','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_035','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Who is strongly associated with the development of the movable-type printing press in Europe in the mid-15th century?','["Alexander Fleming","Galileo Galilei","Johannes Gutenberg","Edward Jenner"]',2,'He printed famous Bibles.','The printing press with movable metal type developed in Europe by Johannes Gutenberg...','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_036','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What did the electric telegraph do?','["It transmitted speech wirelessly to space.","It enabled coded messages to be transmitted over long distances using electrical signals.","It printed books automatically.","It took photographs."]',1,'It sent Morse code over wires.','The electric telegraph enabled messages to be transmitted over long distances using electrical signals.','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_037','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Who received a famous US patent for the telephone in 1876?','["The Wright brothers","Alexander Graham Bell","Louis Pasteur","Robert Koch"]',1,'He made the first famous phone call.','Its development involved several inventors... with Alexander Graham Bell receiving a well-known US patent in 1876.','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_038','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What is the internet?','["A type of radio","A single large computer in a building","A worldwide system of interconnected computer networks","A printing press"]',2,'It connects billions of devices globally.','Internet: A worldwide system of interconnected computer networks.','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_039','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What device combines communication, computing, photography, and navigation into one portable item?','["A telegraph","A telescope","A smartphone","A steam engine"]',2,'You probably have one in your pocket right now!','Smartphones combine communication, computing, photography, navigation, and other functions in portable devices.','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_040','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How did the invention of the printing press change education and science in Europe?','["It made books so expensive that no one could buy them.","It allowed books, pamphlets, and scientific ideas to be produced quickly and efficiently, helping knowledge circulate much more widely to the public.","It caused people to stop writing completely.","It only printed maps."]',1,'Before the press, a monk had to copy a book by hand for an entire year!','Gutenberg''s press helped make the production of books... more efficient... Printed books... helped ideas circulate more widely. Printing contributed to changes in education, science...','2026-11-01 10:00:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_041','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How did the transition from the telegraph to the telephone alter human communication?','["The telephone was much slower than the telegraph.","While the telegraph required sending coded electrical clicks (Morse code), the telephone revolutionized contact by allowing the direct, electronic transmission of actual human speech over a distance.","The telephone required people to travel to speak.","The telegraph sent videos, while the telephone only sent sound."]',1,'Hearing a voice is much better than reading a series of clicks!','The telegraph enabled messages... using electrical signals. The telephone made it possible to transmit speech electronically.','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_042','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why is it historically inaccurate to say Johannes Gutenberg ''invented printing'' entirely on his own?','["Because printing is a natural phenomenon.","Because printing technologies, such as woodblock printing, already existed in East Asia long before Gutenberg developed his movable-type press in Europe.","Because he actually invented the computer.","Because Gutenberg lived in ancient Egypt."]',1,'The Chinese were printing centuries before Europe!','Printing technologies existed in East Asia before the development of the European movable-type printing system associated with Johannes Gutenberg... Printing was not invented by one person in a single place...','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_043','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'While the internet allows for amazing global communication, what are some of the serious challenges it introduces?','["It makes computers run too fast.","It introduces risks such as widespread misinformation, cybercrime, severe privacy violations, and unequal access to reliable services.","It completely stops people from reading books.","It forces people to use telegraphs."]',1,'Not everything you read online is true, and hackers are a real threat.','Digital technologies also introduce challenges, including misinformation, privacy risks, cybercrime, and unequal access...','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_044','History','Basic History','Topic 6: Inventions and Discoveries','Primary',10,'Analyze how the invention of the radio and television fundamentally transformed the mechanics of political power and ''public opinion'' in the 20th century.','["They had no impact on politics.","By allowing leaders and media to broadcast moving images and spoken speeches directly into millions of homes simultaneously, they created unprecedented mass-media platforms that could unify culture or distribute propaganda, making political influence heavily dependent on broadcast appeal.","They forced politicians to write more letters.","They caused the immediate collapse of all governments."]',1,'A politician on TV could suddenly speak directly to an entire country at once!','Television added moving images to sound. It allowed people to watch news... Both technologies influenced public opinion and culture. Their value depends partly on the accuracy and quality of the information...','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_045','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What instrument did Galileo Galilei use to observe the Moon and Jupiter''s moons?','["A microscope","A telegraph","A telescope","A camera"]',2,'It makes far away things look close.','Galileo Galilei used an improved telescope to make important observations of the Moon, Jupiter''s moons...','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_046','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What instrument allows scientists to view very small objects like cells and bacteria?','["A telescope","A microscope","A compass","An electric light bulb"]',1,'It makes tiny things look huge.','Microscopes allow people to observe objects too small to see clearly with the unaided eye.','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_047','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What are microorganisms?','["Giant space rocks","Tiny living things like bacteria, fungi, and protozoa that can only be seen with a microscope","A type of ancient wheel","A new computer part"]',1,'They are everywhere, but you need a microscope to see them.','Microorganisms include bacteria, many fungi, protozoa, and microscopic algae.','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_048','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Who contributed to the development of the first vaccination against smallpox in the late 18th century?','["Louis Pasteur","Robert Koch","Edward Jenner","Alexander Fleming"]',2,'His work saved millions of lives.','Edward Jenner''s work in the late eighteenth century contributed to the development of vaccination against smallpox.','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_049','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What does a vaccine do?','["It causes bacterial infections.","It trains the immune system to recognize a particular disease target and protect the body.","It acts as a painkiller.","It cures the common cold."]',1,'It''s like a practice drill for your body''s defenders.','Vaccines train the immune system to recognize particular disease-causing organisms or their components.','2026-11-01 10:00:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_050','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'Who observed a mould killing bacteria in 1928, leading to the discovery of penicillin?','["Alexander Fleming","Galileo Galilei","The Wright brothers","Louis Pasteur"]',0,'It was a happy accident in his lab!','In 1928, Alexander Fleming observed the antibacterial effect of a substance produced by a mould. This discovery contributed to the development of penicillin...','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_051','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What do antibiotics treat?','["Viral illnesses like the common cold","Certain bacterial infections","Broken bones","Allergies"]',1,'They kill bad bacteria.','Antibiotics treat bacterial infections, not viral illnesses such as the common cold.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_052','History','Basic History','Topic 6: Inventions and Discoveries','Primary',1,'What theory states that microorganisms can cause particular diseases?','["Gravity theory","Germ theory","Evolution theory","Relativity theory"]',1,'Scientists like Pasteur and Koch helped prove this.','Germ theory: The scientific understanding that microorganisms can cause particular diseases.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_053','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How did the telescope change humanity''s understanding of the universe?','["It proved that the Earth was flat.","By observing the phases of planets and moons orbiting Jupiter, it provided hard evidence that challenged long-held ideas and proved the Earth was not the center of the universe.","It showed that the stars were actually painted on a ceiling.","It proved that there are no other planets."]',1,'It completely changed our place in the universe!','These observations helped strengthen scientific understanding of the Solar System and challenged some long-held ideas about the heavens.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_054','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why is ''using antibiotics unnecessarily'' a dangerous practice?','["Because they taste bad.","Because overusing them can cause bacteria to adapt and survive, contributing to dangerous ''antimicrobial resistance'' where the medicine no longer works.","Because it turns bacteria into viruses.","Because antibiotics are too expensive to make."]',1,'If you use them too much, the bacteria learn how to fight back!','Using antibiotics unnecessarily can contribute to antimicrobial resistance.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_055','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'How do scientific explanations differ from ordinary guesses?','["They are always right the first time.","A good scientific explanation must be strictly supported by empirical observations, collected evidence, and rigorous testing, and it changes when new evidence is found.","They are made by people in lab coats.","They are never allowed to change."]',1,'Science requires proof, not just opinions!','Scientific knowledge changes as evidence improves. A good scientific explanation must be supported by observations and testing.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_056','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'What role do microorganisms play in the world besides causing diseases?','["They cause all earthquakes.","Many are highly beneficial, helping with human digestion, food production (like bread and yogurt), and the decomposition of dead matter.","They build microscopic cities.","They do nothing at all."]',1,'Without the good microbes, humans couldn''t digest food!','Some cause disease, while others help with digestion, food production, decomposition, and other useful processes.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_057','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'What was the significance of the global smallpox eradication programme?','["It proved vaccines do not work.","It showed that through coordinated public health efforts, surveillance, and widespread vaccination, humans could permanently eliminate a deadly infectious disease from the planet.","It taught people how to catch smallpox.","It replaced smallpox with another disease."]',1,'It is one of the greatest medical victories in history!','The global smallpox eradication programme later showed how vaccination... and coordinated public health efforts could eliminate a human infectious disease.','2026-11-01 10:00:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_058','History','Basic History','Topic 6: Inventions and Discoveries','Primary',5,'Why was the development of the electric light bulb dependent on more than just the bulb itself?','["Because bulbs need to be watered.","Practical electric lighting also required simultaneous improvements in electrical generation power plants, distribution wire systems, and safe lamp materials to actually work in homes.","Because electricity is a natural gas.","Because the bulb needed a computer to turn on."]',1,'A light bulb is useless without a power grid to supply the electricity!','Practical electric lighting also depended on improvements in electrical generation, distribution systems, materials, and lamp design.','2026-11-01 10:00:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_inv_059','History','Basic History','Topic 6: Inventions and Discoveries','Primary',10,'Critique the societal paradox introduced by modern technological inventions (e.g., assessing the balance between improved efficiency and ethical/environmental harm).','["Technology only provides absolute benefits with zero negative consequences.","While modern technology exponentially improves medical care, education, and transport efficiency, it concurrently generates severe systemic challenges such as environmental pollution, cyber-security threats, widening wealth inequality, and the mechanization of warfare.","Technology is entirely destructive and should be abandoned immediately.","Technology only affects the weather, not human society."]',1,'Every great invention is a double-edged sword; cars give us freedom but cause pollution!','They can also create challenges: Pollution... Unequal access... Privacy and security problems. Weapons and technologies used to harm people... Therefore, people must consider how technologies are designed... and how they affect society and the environment.','2026-11-01 10:00:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_001','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is a ruler?','["A person who builds houses","A person who holds authority over a country, kingdom, or territory","A type of ancient tool","A person who studies the stars"]',1,'They are the person in charge.','A ruler is a person who holds authority over a country, kingdom, empire, or territory.','2026-11-01 10:01:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_002','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is a monarchy?','["A country with no leaders","A system of government in which the head of state is a monarch, such as a king or queen","A system where everyone is a king","A group of farmers"]',1,'It is ruled by royalty.','A monarchy is a system of government in which the head of state is a monarch, such as a king or queen.','2026-11-01 10:01:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_003','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'How does someone usually become a king or queen in a monarchy?','["They win a race","The position is inherited within a royal family","They are chosen by random lottery","They buy the crown at a market"]',1,'It is passed down from parents to children.','In many monarchies, the position is inherited within a royal family.','2026-11-01 10:01:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_004','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What title was given to the rulers of ancient Egypt?','["President","Emperor","Pharaoh","Sultan"]',2,'They ruled the land of the pyramids.','A pharaoh who ruled ancient Egypt.','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_005','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Did every ruler in history have the exact same amount of power?','["Yes, they all had absolute power.","No, some had absolute authority, while others were restricted by laws or councils.","Yes, they all had no power at all.","Only queens had power."]',1,'Some could do whatever they wanted; others had to follow the rules.','Not every ruler had the same powers. Some had nearly absolute authority, while others were restricted...','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_006','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'What is the primary difference between an ''absolute monarchy'' and a ''constitutional monarchy''?','["An absolute monarch lives in a castle; a constitutional monarch does not.","An absolute monarch holds extensive governing power, while a constitutional monarch''s powers are limited by laws and institutions.","An absolute monarchy only has a queen.","A constitutional monarchy has no laws."]',1,'One has total control; the other is controlled by a rulebook.','Absolute monarchy: The monarch holds extensive governing power... Constitutional monarchy: The monarch''s powers are limited by a constitution...','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_007','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why do rulers depend on officials, soldiers, and farmers?','["Because rulers do not know how to speak.","Because a ruler cannot manage an entire society alone; they need officials to carry out decisions, soldiers for defense, and farmers for food.","Because rulers are not allowed to leave their castles.","Because rulers are usually children."]',1,'A king can''t fight a war and grow wheat all by himself!','Rulers often depended on officials, advisers, soldiers, farmers... to carry out decisions.','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_008','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'What does it mean if a ruler uses their power for ''public works''?','["They force the public to work for free.","They support the building of roads, bridges, irrigation systems, and public buildings that benefit the community.","They only build things for themselves.","They destroy public buildings."]',1,'They use their power to build things that help everyone.','Responsibilities of rulers: ... Support roads, bridges, irrigation, and public buildings.','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_009','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Analyze the concept of ''succession'' and why establishing clear succession rules is critical for the stability of a monarchy.','["Succession prevents anyone from being king.","Succession dictates the legal transfer of power upon a monarch''s death; without clear rules, multiple claimants often ignite devastating civil wars to seize the throne, destroying the state''s stability.","Succession means the monarch lives forever.","Succession rules are only used in democracies."]',1,'If the King dies and three princes all think they should be next, a war usually starts!','Succession: The process by which someone takes over a position of authority. However, succession rules differ...','2026-11-01 10:01:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_010','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is an empire?','["A small village","A large political system governing multiple territories or peoples","A single building","A type of council"]',1,'Rome and China had these.','Empire: A large political system governing multiple territories or peoples.','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_011','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What title is usually given to the ruler of an empire?','["Mayor","President","Emperor or Empress","Pharaoh"]',2,'They rule over many different lands.','An emperor or empress traditionally rules an empire...','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_012','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What title was used by rulers in various Muslim states and empires?','["President","Pharaoh","Sultan","Dictator"]',2,'It is a specific historical title.','A sultan was a title used by rulers in various Muslim states and empires.','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_013','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'How is a president usually different from a king?','["A president wears a crown.","A president is usually elected by citizens or selected through a constitutional process, rather than inheriting the role.","A president is always a dictator.","A president rules an empire."]',1,'They don''t get the job just because their parent had it.','Presidents may be elected directly by citizens or selected through another constitutional process.','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_014','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is a dictator?','["A ruler who exercises concentrated power without effective democratic accountability","A leader chosen by a fair election","A member of a council","A ceremonial king"]',0,'They take power and don''t let the people vote them out.','A dictator is a ruler who exercises concentrated power without effective democratic accountability.','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_015','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why is ruling an empire often more complex than ruling a single city-state?','["Because empires are always located underwater.","Empires often contain diverse languages, religions, and customs across vast territories, requiring complex systems to manage, govern, and collect resources from different communities.","Because empires do not have armies.","Because empires are always ruled by councils."]',1,'You have to keep millions of very different people happy and peaceful!','Empires often contained diverse languages, religions, and customs. Their rulers needed ways to manage large territories...','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_016','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How does a ''council-based system'' make decisions differently than an ''absolute monarchy''?','["A council flips a coin.","In a council-based system, decisions are discussed and made collectively by a group of people (like elders or an assembly), rather than dictated by a single individual.","A council forces the youngest person to decide.","There is no difference."]',1,'Ten heads are better than one!','In a council-based system, decisions may be discussed and made by several people rather than a single monarch.','2026-11-01 10:01:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_017','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Can a country be both a republic and a democracy?','["No, they are opposites.","Yes, a republic simply means there is no monarch, and a democracy means the people participate in choosing the government; many modern countries are both.","Yes, but only if they have a king.","No, republics are always dictatorships."]',1,'The USA and France are examples of both!','These categories can overlap. For example, a country can be both a republic and a democracy...','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_018','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Evaluate the distinction between a ''dictator'' and a highly powerful ''monarch'' in historical analysis.','["They are exactly the same thing.","While both may wield absolute power, a monarch''s authority is traditionally legitimized by established hereditary succession, cultural, or religious frameworks; a dictator typically acquires and maintains concentrated power outside of traditional or democratic accountability.","A dictator inherits power; a monarch steals it.","Dictators only existed in the ancient world."]',1,'A King''s power is usually based on centuries of tradition; a Dictator usually takes power by force.','A dictator is a ruler who exercises concentrated power without effective democratic accountability. Dictatorships often restrict political opposition... The key issue is how power is acquired...','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_019','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Who was Ramses II?','["A British Queen","An ancient Egyptian Pharaoh remembered for major building projects","A modern President","A Roman Emperor"]',1,'He built giant statues of himself in Egypt.','Ramses II, also called Ramesses the Great, ruled Egypt... He is remembered for major building projects...','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_020','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Which ancient Indian ruler supported ''dhamma'' (ethical principles) after the Kalinga War?','["Akbar","Nelson Mandela","Ashoka","Ramses II"]',2,'He decided peace was better than war.','Ashoka... After the Kalinga War, Ashoka''s inscriptions describe his concern about the suffering caused by war and his support for dhamma...','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_021','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Who ruled the Mughal Empire in South Asia from 1556 to 1605?','["Ashoka","Queen Victoria","Akbar","Socrates"]',2,'He is known for his policies of accommodation.','Akbar ruled the Mughal Empire in South Asia from 1556 to 1605.','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_022','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Which Queen ruled England during a time of overseas exploration and the growth of theatre (1558-1603)?','["Queen Victoria","Queen Elizabeth I","Queen Cleopatra","Queen Mary"]',1,'Shakespeare wrote plays during her reign.','Elizabeth I ruled England from 1558 to 1603. Her reign included important developments in literature and theatre, overseas exploration...','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_023','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'During whose reign did the British Empire and industrialization expand significantly (1837-1901)?','["Queen Elizabeth I","Queen Victoria","Nelson Mandela","Ashoka"]',1,'Trains and factories grew huge during her era.','Queen Victoria ruled from 1837 to 1901, a period when industrialization and the British Empire expanded significantly.','2026-11-01 10:01:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_024','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Who was Nelson Mandela?','["A king of South Africa","An anti-apartheid leader who became South Africa''s first democratically elected president","An ancient Egyptian pharaoh","An emperor of the Mughal Empire"]',1,'He fought for equality.','Nelson Mandela was not a king or monarch. He was an anti-apartheid leader who became South Africa''s first democratically elected president...','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_025','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How does the legacy of Queen Victoria''s reign demonstrate that leadership effects can be ''mixed''?','["Her reign only brought bad things.","Her reign brought massive technological progress (railways, factories) and global opportunities, but it concurrently caused harsh working conditions, social inequality, and the exploitation of colonized peoples.","Her reign had no effects on anyone.","She abolished the British Empire entirely."]',1,'Factories made cheap goods, but the workers suffered in dangerous conditions.','These developments brought new opportunities but also difficult working conditions, social inequality, and colonial exploitation.','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_026','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How did Ashoka use ''inscriptions'' to govern his empire?','["He threw them at his enemies.","He promoted moral conduct by carving messages (dhamma) on rocks and pillars across his empire so the public could read his ethical principles.","He used them to build pyramids.","He hid them in caves."]',1,'It was like an ancient billboard promoting peace!','He promoted moral conduct and issued messages carved on rocks and pillars across parts of his empire.','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_027','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why is Nelson Mandela''s leadership historically significant even though he was not a monarch?','["Because he lived in a castle.","His life demonstrates how leadership, perseverance (spending 27 years in prison), and moral authority can contribute to massive political change, democratic transition, and national reconciliation without royal power.","Because he conquered other countries.","Because he ruled for 100 years."]',1,'He changed a country through democracy, not by wearing a crown.','Historical significance: Mandela''s life demonstrates how leadership can contribute to political change, equality, and reconciliation.','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_028','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Critique the historical methodology of judging a ruler solely by their military conquests or monumental architecture.','["It is the only correct way to study history.","It creates a biased, elite-focused narrative that ignores the socioeconomic reality of the broader population; true historical analysis must also examine whether laws protected marginalized groups and how resources were extracted to fund those monuments.","It proves that ordinary people loved the ruler.","It forces historians to ignore written records."]',1,'A giant pyramid looks amazing today, but it was built with the sweat of exhausted workers!','A ruler''s legacy is not measured only by monuments or victories. Historians also consider: How people lived... Whether laws protected or harmed different groups...','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_029','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Why do governments and rulers create laws?','["To cause arguments","To organize society, settle disputes, and maintain order","To make everyone angry","To stop trade"]',1,'Without rules, society would be chaotic.','Rulers and governments have created rules to organize society, settle disputes, and maintain order.','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_030','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is the ''Code of Hammurabi'' an example of?','["An ancient collection of laws","A type of ancient food","A river in Egypt","A musical instrument"]',0,'It is one of the oldest law books.','For example, the Code of Hammurabi is an important collection of laws from ancient Babylon.','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_031','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Did ancient laws always treat everyone equally?','["Yes, absolutely everyone.","No, punishments and rights often depended on social status, wealth, or gender.","Yes, but only in Rome.","No, they only punished the rich."]',1,'A rich person and a poor person might get different punishments for the same crime.','However, historical legal systems did not always treat people equally. Punishments and rights could depend on social status...','2026-11-01 10:01:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_032','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Which of these is an example of a public work organized by a ruler?','["A private diary","Irrigation channels and roads","A personal toy","A family dinner"]',1,'These projects help the whole society.','Some rulers organized large construction projects, including: Roads... Irrigation channels.','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_033','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'How can war negatively affect the daily life of ordinary people?','["It gives them free money.","It can cause deaths, displacement, destruction of farms, and loss of homes.","It always makes the weather better.","It makes them immortal."]',1,'The kings get the glory, but the farmers lose their crops.','Wars could expand territory... but they could also cause deaths, displacement, destruction of farms, and loss of homes.','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_034','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How can a government positively influence trade and the economy?','["By burning all the money.","By maintaining safe roads, protecting ports, issuing standard coins, and setting fair trade rules to help merchants exchange products.","By stopping people from traveling.","By stealing from farmers."]',1,'Merchants need safe roads to transport their goods!','Governments could influence trade by maintaining roads, protecting ports, collecting taxes, issuing coins, and setting trade rules.','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_035','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why is ''diplomacy'' an important skill for a ruler?','["It helps them start more wars.","Diplomacy involves making agreements and cooperating with other countries, which can prevent devastating conflicts and restore peace.","It helps them build pyramids faster.","It teaches them how to farm."]',1,'Talking out a problem is usually better than fighting a war over it!','Diplomacy, agreements, and cooperation sometimes prevented conflict or restored peace.','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_036','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'If a ruler builds a massive, beautiful palace, why might historians still judge their legacy negatively?','["Because palaces are ugly.","Because historians must consider *how* the resources were used; if the palace was built using harsh, forced labor while the common people starved, the legacy is harmful.","Because historians hate architecture.","Because palaces disappear quickly."]',1,'A shiny palace means nothing if the people are suffering!','They also required resources and labour, sometimes under harsh conditions... Historians also consider: How people lived during the ruler''s time. How resources were used.','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_037','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Name a historical kingdom or empire from Africa.','["Rome","Mali, Ethiopia, or Great Zimbabwe","The Aztec Empire","Japan"]',1,'Africa had many powerful empires.','Africa: Kingdoms and empires such as Mali, Ethiopia, and Great Zimbabwe played important roles...','2026-11-01 10:01:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_038','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is a ''ceremonial role'' for a modern monarch?','["A role with absolute dictatorial power","A role mainly concerned with formal events and representation, rather than actual political power","A role as a frontline soldier","A role as a farmer"]',1,'They cut ribbons and host dinners, but don''t make the laws.','Ceremonial role: A role mainly concerned with formal events and representation.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_039','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is a constitution?','["A type of ancient weapon","A country''s fundamental legal framework and set of rules","A large stone pyramid","A type of election"]',1,'It is the rulebook that even the leaders have to follow.','Constitution: A country''s fundamental legal framework.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_040','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What does ''accountability'' mean for a leader?','["They can do whatever they want in secret.","The responsibility to explain their actions and answer to the public for their decisions.","They never have to pay taxes.","They must live in a castle."]',1,'If they make a mistake, they have to admit it and fix it.','Accountability: The responsibility to explain actions and answer for decisions.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_041','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How do modern republics differ from absolute monarchies in terms of how leaders get their jobs?','["In both, the leader is born into the job.","In a republic, leaders (like presidents) are elected or appointed based on a constitution, whereas in an absolute monarchy, the position is inherited by birth.","In a republic, leaders are chosen by a king.","There is no difference."]',1,'Republics let the citizens (or their representatives) pick the boss!','Many modern countries are republics with presidents and other elected or appointed officials... A country''s political system determines how leaders are selected...','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_042','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why is ''listening to different viewpoints'' considered a quality of responsible leadership?','["Because leaders have bad hearing.","Because a responsible leader must consider the fairness and public welfare of all groups in society, not just their own opinions or the elite class.","Because it is a law in every country.","Because it makes them look wealthy."]',1,'A good leader knows they don''t have all the answers!','Responsible leaders should aim to: ... Listen to different viewpoints. Respect laws and human rights.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_043','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How can a society limit the ''abuses of power'' by a leader?','["By giving the leader all the money.","By relying on public institutions, strong laws (constitutions), free discussion, and citizen participation (voting).","By letting the leader do whatever they want.","By ignoring the government entirely."]',1,'If a leader breaks the rules, the citizens and the courts can stop them!','No leader is perfect. Public institutions, laws, free discussion, and citizen participation can help limit abuses of power.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_044','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Synthesize why the historical study of ''human rights'' is essential when evaluating the legacy of ancient empires.','["Human rights did not exist, so they shouldn''t be studied.","Ancient empires (like Rome or Egypt) achieved monumental feats, but often through systemic human rights violations like widespread slavery, violent conquest, and exclusion of women. Evaluating legacy requires confronting this moral dichotomy rather than just praising the architecture.","Human rights only apply to emperors.","Empires always protected human rights perfectly."]',1,'You can admire the Roman roads while still condemning the slavery that built them.','Historical figures should be studied in context, recognizing both their achievements and the limitations or harms associated with their actions... Roman society was unequal, and slavery was widespread.','2026-11-01 10:01:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_045','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What did the Maya, Aztec, and Inca civilizations have in common?','["They were all in Europe.","They were indigenous societies in the Americas with diverse systems of leadership.","They all spoke English.","They had no leaders."]',1,'They were powerful empires in the Americas before European contact.','The Americas: Indigenous societies developed diverse systems of leadership, including those of the Maya, Aztec, and Inca civilizations.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_046','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Which of these is a quality of a responsible leader?','["Acting fairly and honestly","Stealing public resources","Ignoring human rights","Starting wars for fun"]',0,'Good leaders are trustworthy.','Responsible leaders should aim to: Act fairly and honestly.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_047','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why does studying history help us understand modern politics?','["It tells us who will win the next election.","It helps us understand how power works, how political systems change over time, and how decisions affect ordinary people''s lives.","It teaches us how to be absolute monarchs.","It proves that politics is useless."]',1,'History shows us the results of good and bad leadership!','Studying rulers helps learners understand how power works, how political systems change, and how decisions affect people''s lives.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_048','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Analyze the function of a ''Constitution'' as a mechanism for ''Accountability''.','["A constitution gives the leader absolute power.","A constitution establishes the definitive legal boundaries of executive power. By outlining specific rights and procedures, it creates an objective standard against which a leader''s actions can be legally judged and checked by other branches of government or the public.","A constitution is just a list of suggestions.","A constitution prevents any decisions from being made."]',1,'The constitution is the ultimate boss of the president!','Constitution: A country''s fundamental legal framework. Accountability: The responsibility to explain actions and answer for decisions... laws... can help limit abuses of power.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_049','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'What is an empire?','["A small farm","A political system governing multiple territories or peoples","A single city","A type of book"]',1,'Rome and the Mughals were empires.','Empire: A political system governing multiple territories or peoples.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_050','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',1,'Who is the head of state in a Republic?','["A hereditary monarch","A president or elected official (not a monarch)","An Emperor","A Pharaoh"]',1,'The USA is a republic.','Republic: The state does not have a hereditary monarch as its sovereign head.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_051','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'Why did ancient rulers often support religious institutions and temples?','["To destroy the buildings.","Rulers often used religion to legitimize their power and authority, while temples also served as centers of community, education, and culture.","Because the rulers wanted to be farmers.","They were forced to by neighboring countries."]',1,'Pharaohs were even considered partly divine themselves!','Support roads... Support religious institutions, arts, or education.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_052','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',5,'How can the collection of taxes be both helpful and harmful in a society?','["Taxes are always entirely bad.","Fair taxes fund necessary public works (roads, defense), but excessively high or unfair taxes can ruin the livelihoods of farmers and merchants, causing suffering.","Taxes are only used to buy food.","Taxes only help the poor."]',1,'You need taxes to build a road, but if you take all the farmer''s money, he starves!','Governments could influence trade by... collecting taxes... However, high taxes... could disrupt livelihoods.','2026-11-01 10:01:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_rulers_053','History','Basic History','Topic 7: Kings, Queens, and Rulers','Primary',10,'Critique the historical assumption that ''Democracy'' is a strictly modern invention.','["Democracy was invented in the year 2000.","While modern universal suffrage is recent, foundational democratic concepts (public participation and political accountability) were actively practiced in ancient city-states like Athens, albeit restricted to a narrow demographic of eligible male citizens.","Democracy has never existed.","Athens had a perfect modern democracy."]',1,'The ancient Greeks planted the seed of democracy, even if they didn''t let everyone vote!','Athens developed an early form of democracy... However, women, enslaved people, and many residents who were not citizens were excluded. This system was very different from modern democracy...','2026-11-01 10:01:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_001','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What does ''everyday life'' mean in history?','["Only the lives of kings and queens","The ordinary activities people do as part of their daily lives","The study of alien life","Only major wars and battles"]',1,'It focuses on ordinary people, not just rulers.','Everyday life means the ordinary activities people do as part of their daily lives.','2026-11-01 10:01:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_002','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What is a ''settlement''?','["A type of farming tool","A place where people live","A piece of clothing","A written book"]',1,'It is a community''s home base.','A settlement is a place where people live. Settlements range from small villages to large cities.','2026-11-01 10:01:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_003','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'Which of these is an example of an early human shelter?','["A skyscraper","A brick mansion","A cave or simple hut","A glass building"]',2,'They used what nature provided.','Early humans used caves, natural shelters, tents, and simple huts.','2026-11-01 10:01:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_004','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What activity involves collecting wild fruits, nuts, and seeds?','["Hunting","Farming","Gathering","Weaving"]',2,'You don''t plant these; you find them in the wild.','Gathering: Collecting fruits, nuts, seeds, roots, and other edible plants.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_005','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What activity involves growing crops like rice and wheat?','["Hunting","Farming","Fishing","Metalworking"]',1,'It involves preparing soil and planting seeds.','Farming: Growing crops such as rice, wheat, millet, and maize.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_006','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'Which clothing material is obtained from animals like sheep?','["Cotton","Silk","Linen","Wool"]',3,'It keeps you very warm in winter.','Wool: A fibre obtained from animals such as sheep.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_007','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'Which clothing material is produced by small insects?','["Cotton","Silk","Leather","Linen"]',1,'It is very soft and smooth.','Silk: A fibre produced by silkworms.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_008','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What does a blacksmith do?','["Makes pots out of clay","Weaves cloth","Shapes metal to make tools","Works with wood"]',2,'They work with hot fire and iron.','Craftspeople: ...blacksmiths shaped metal.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_009','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What does a carpenter do?','["Makes pots out of clay","Works with wood","Grows crops","Sells spices"]',1,'They build furniture and houses.','Craftspeople: ...carpenters worked with wood.','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_010','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What is the job of a merchant or trader?','["To build houses","To exchange or buy and sell goods between people","To catch fish","To shape metal"]',1,'They move goods from one place to another to sell.','Traders and merchants: Exchanged goods such as grain, cloth, pottery, spices, and tools...','2026-11-01 10:01:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_011','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'What is ''agriculture''?','["Growing crops and raising animals","Building wooden boats","Studying the stars","Making clothing"]',0,'It is another word for farming and animal rearing.','Agriculture: Growing crops and raising animals.','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_012','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'How did children mostly learn practical skills in the past?','["By watching television","Through observation, practice, and family instruction","By searching the internet","By reading modern textbooks"]',1,'They learned by watching adults work.','Skills were learned through observation, practice, family instruction, apprenticeships...','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_013','History','Basic History','Topic 8: Everyday Life in the Past','Primary',1,'Which of these is an example of a leisure activity?','["Playing board games","Harvesting wheat","Building a stone wall","Repairing a roof"]',0,'It is something done for fun and relaxation.','People in the past enjoyed activities such as: ... Playing board games and outdoor games.','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_014','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What does a potter make?','["Metal swords","Wooden chairs","Pots out of clay","Cotton clothing"]',2,'They use wet clay and ovens to make dishes.','Craftspeople: Potters made pots...','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_015','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What material is made from flax fibres?','["Leather","Linen","Wool","Silk"]',1,'It is a light, breathable fabric from a plant.','Linen: A fabric made from flax fibres.','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_016','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What is an ''occupation''?','["A person''s job or type of work","A type of house","A religious festival","A board game"]',0,'It is how someone earns a living or helps the community.','Occupation: A person''s job or type of work.','2026-11-01 10:01:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_017','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'Which communities often depend heavily on seafood?','["Desert communities","Mountain communities","Fishing and coastal communities","Forest communities"]',2,'They eat what is in the water near their homes.','Fishing communities often depend on fish and other seafood.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_018','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What does a weaver make?','["Metal tools","Cloth","Wooden boats","Clay pots"]',1,'They use threads of cotton or wool to make fabric.','Craftspeople: ...weavers made cloth...','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_019','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What does ''tradition'' mean?','["A new invention","A custom or practice passed between generations","A modern computer","A type of wild animal"]',1,'It is something your grandparents taught your parents, and your parents taught you.','Tradition: A custom or practice passed between generations.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_020','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'Why did early humans need shelter?','["To watch television","To protect themselves from weather and wild animals","To store their cars","To hide from other planets"]',1,'Nature can be dangerous without a home!','These helped protect them from weather and wild animals.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_021','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'Why is studying ''everyday life'' just as important as studying famous kings and battles?','["Because kings never existed.","Because it helps us understand the full picture of how ordinary people actually lived, worked, learned, and survived.","Because everyday life is completely made up.","Because kings only lived in modern times."]',1,'History isn''t just about leaders; it''s about everyone!','Studying everyday life helps us understand how ordinary people—not only kings and famous leaders—lived, worked, learned, and cared for their families.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_022','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'How did the local environment dictate the materials used to build homes?','["People imported all their building materials from other continents.","People used whatever local materials were abundant; for example, wood in forested areas, or mud and stone in dry areas.","The environment did not affect homes at all.","Everyone used plastic to build homes."]',1,'You build with what you can find nearby!','Houses could be made from mud, wood, stone, grass, or other local materials... In forested areas, wood could be an important building material.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_023','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'Why would a house in a very hot region be built differently than a house in a very cold region?','["Because people in hot regions don''t sleep.","Hot region homes include features for shade and ventilation to keep cool, while cold region homes are built to retain warmth.","Cold region homes need ventilation to let snow inside.","There is no difference in how they are built."]',1,'The house has to protect you from the local weather!','In hot regions, houses often included features to provide shade and ventilation. In cold regions, homes needed to retain warmth.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_024','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'How did the development of farming change how communities handled their food supply?','["It forced them to eat all their food in one day.","Farming allowed communities to produce food more regularly and store surplus supplies for later use during the year.","It made them stop eating entirely.","It meant they only ate wild animals."]',1,'A successful harvest means you can save food for the winter!','Farming allowed many communities to produce food more regularly and store some supplies for later.','2026-11-01 10:01:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_025','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'Why did people in the past wear different types of clothing?','["Everyone wore the exact same uniform.","Clothing choices depended on the local climate, available raw materials, a person''s occupation, and their cultural customs.","Because they only had one type of fabric.","Because clothing was only used for decoration, not weather."]',1,'A blacksmith working near a hot fire wears different clothes than a herder in the snowy mountains!','People used different clothing according to climate, available materials, work, customs, and personal circumstances.','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_026','History','Basic History','Topic 8: Everyday Life in the Past','Primary',5,'What is an ''apprenticeship''?','["A type of boat.","A way of learning a skill where a young person works with and learns directly from an experienced craftsperson.","A type of ancient food.","A school for kings only."]',1,'It''s on-the-job training in the past!','Skills were learned through observation, practice, family instruction, apprenticeships...','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_027','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'How did a trader or merchant help connect different communities?','["By building large walls between them.","By exchanging goods (like spices, tools, and cloth) across distances, allowing people to access items not made in their own village.","By fighting wars with everyone.","By keeping all goods for themselves."]',1,'If your village didn''t have iron, a merchant would bring it to you from a village that did!','Traders and merchants: Exchanged goods such as grain, cloth, pottery, spices, and tools between people and places.','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_028','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Why did many early villages and cities develop near rivers?','["Because they liked swimming.","Rivers provided a reliable source of drinking water, supported farming and irrigation, and offered waterways for transport and trade.","Because rivers prevented all floods.","Because rivers are quiet."]',1,'Water is essential for life, crops, and moving heavy boats!','Near rivers, people could obtain water and use waterways for transport. Many villages developed around farming, rivers, or other sources of water.','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_029','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Did access to formal education exist equally for everyone in ancient societies?','["Yes, every child went to school.","No, access to formal education varied greatly and was often unequal, depending heavily on wealth, social status, and gender.","Yes, but only for learning to fish.","No, schools did not exist at all until the 1900s."]',1,'In the past, usually only wealthy children had formal teachers.','Access to education was not equal in all societies. Work opportunities were also affected by wealth, gender, social status...','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_030','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'How did community members typically help each other during emergencies or big projects?','["They refused to help anyone else.","Neighbours and community members often cooperated, working together to farm, build homes, or recover from disasters.","They forced the king to do all the work.","They moved to different cities."]',1,'Before modern machines, building a barn required the whole village to pitch in!','Neighbours and community members sometimes cooperated during farming, building, celebrations, or emergencies.','2026-11-01 10:01:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_031','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'What does ''pastoralism'' or ''animal rearing'' involve?','["Catching wild fish in the ocean.","Keeping and managing domesticated animals for resources like milk, meat, eggs, wool, or transport.","Growing large fields of wheat.","Hunting wild deer in the forest."]',1,'Instead of hunting, you raise the animals yourself.','Animal rearing: Keeping animals for milk, meat, eggs, wool, or transport. Pastoral communities may rely on milk and animal products.','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_032','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Why might a city in the past have required a ''drainage system''?','["To bring wild animals into the city.","To safely carry wastewater and rain away from busy streets and crowded houses, keeping the city clean and preventing disease.","To hide treasure.","To make the streets slippery."]',1,'When thousands of people live close together, you have to manage the dirty water!','Some ancient cities also developed drainage systems, roads, and water supplies.','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_033','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Analyze how ''geographical determinism'' shaped the architectural design and material composition of early settlements.','["Geography only determined what color houses were painted.","The physical environment strictly dictated survival architecture; lacking modern transport, communities synthesized local raw materials (e.g., mud-brick in arid river valleys, timber in dense forests) and engineered structural adaptations (ventilation vs. insulation) solely based on regional climate constraints.","Geography had absolutely no impact on how people built homes.","All ancient homes were built exactly the same way to defy geography."]',1,'You can''t build a wooden cabin in the desert if there are no trees!','The types of shelters varied with the environment and available materials... In hot regions, houses often included features to provide shade... In cold regions, homes needed to retain warmth. In forested areas, wood...','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_034','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Critique the historical methodology that focuses exclusively on ''great leaders and wars'' (Great Man Theory) by explaining the historiographical value of studying ''everyday life'' (social history).','["Studying everyday life is a waste of time.","Focusing only on elite rulers creates a biased, incomplete narrative of humanity. Social history democratizes the past, revealing the socioeconomic realities, technological adaptations, and cultural labor of the 99% of ordinary people whose daily work actually built and sustained civilizations.","Only kings left behind any evidence of the past.","Social history proves that kings did not actually exist."]',1,'The King may declare a war, but the blacksmith makes the swords and the farmers feed the army!','Studying everyday life helps us understand how ordinary people—not only kings and famous leaders—lived, worked, learned, and cared for their families.','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_035','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Synthesize the relationship between the ''agricultural revolution'' (farming) and the emergence of ''specialized occupations'' (like blacksmiths and potters).','["Farming made people forget how to do other jobs.","Agriculture generated a reliable caloric surplus, freeing a portion of the population from constant food procurement. This surplus subsidized individuals to dedicate their time entirely to mastering specialized crafts (pottery, metallurgy), thereby driving technological and economic complexity.","Specialized occupations existed long before farming was invented.","Farming required every single person to work in the fields constantly."]',1,'If one farmer can feed three people, the other two people can spend all day inventing new tools!','Farming allowed many communities to produce food more regularly and store some supplies... Craftspeople: Potters made pots, weavers made cloth...','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_036','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Evaluate how the concept of ''leisure and entertainment'' in a historical community serves as an indicator of its economic stability.','["Leisure means the community was lazy and failing.","The presence of structured leisure (board games, festivals, theatre) indicates that a society has moved beyond pure subsistence survival; it demonstrates they possess the surplus time, resources, and social organization necessary to pursue cultural enrichment.","Leisure was only allowed during times of famine.","There was no leisure in the past; everyone worked 24 hours a day."]',1,'You can''t spend three hours playing a board game if you are desperately starving and hunting for your next meal!','People in the past enjoyed activities such as: Singing... Playing board games... Attending fairs, festivals...','2026-11-01 10:01:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_life_037','History','Basic History','Topic 8: Everyday Life in the Past','Primary',10,'Analyze the intersection of ''social hierarchy'' and ''education'' in ancient civilizations.','["Education was universally free and mandatory for everyone.","In most ancient societies, formal education was a highly exclusive privilege restricted to the wealthy or elite classes (nobility, scribes, priests), perpetuating social stratification by ensuring that specialized knowledge and administrative power remained concentrated.","The poorest people always received the best education.","Education was illegal in all ancient societies."]',1,'If you had to work in the fields from age 6 to survive, you didn''t have time to sit in a classroom and learn to read!','Access to education was not equal in all societies. Work opportunities were also affected by wealth, gender, social status, and local customs.','2026-11-01 10:01:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_001','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What are three basic human needs necessary for survival?','["Cars, phones, and computers","Food, clothing, and shelter","Gold, silver, and money","Books, toys, and games"]',1,'Humans need these every day to live and stay healthy.','Food, clothing, and shelter are three basic human needs.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_002','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What does ''gathering'' mean in the context of early food collection?','["Hunting large wild animals","Collecting fruits, nuts, seeds, roots, and edible plants from nature","Planting seeds in a large farm","Catching fish in a river"]',1,'It involves finding wild plant foods in the environment.','Gathering: Collecting fruits, nuts, seeds, roots, and edible plants.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_003','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is ''animal rearing''?','["Hunting wild animals for sport","Keeping and raising domesticated animals for milk, meat, eggs, and other products","Painting animals on cave walls","Releasing farm animals into the wild"]',1,'It means taking care of farm animals for food.','Animal rearing: Keeping animals for milk, meat, eggs, and other products.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_004','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is farming or agriculture?','["Only gathering wild berries","Growing crops such as rice, wheat, and maize, and raising animals","Building houses and cities","Moving from place to place every day"]',1,'It involves planting seeds and harvesting crops.','Farming: Growing crops such as rice, wheat, millet, and maize.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_005','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'How did people preserve food before modern refrigerators were invented?','["By melting it in the sun","By using methods such as drying, salting, smoking, and pickling","By keeping it in plastic boxes","By washing it in the river"]',1,'Smoke and salt help keep food from spoiling.','Before refrigerators became common, people used methods such as drying, salting, smoking, and pickling to help preserve food.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_006','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What does ''preservation'' of food mean?','["Eating all the food immediately","Protecting food from spoilage so it lasts longer","Cooking food on a modern gas stove","Throwing old food away"]',1,'Making sure it doesn''t go bad over time.','Preservation: Protecting food from spoilage for longer.','2026-11-01 10:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_007','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How did the development of farming change how human communities handled their food supply?','["It forced them to eat all their food in one day.","Farming allowed communities to produce a regular food supply and store surplus grain for later use.","It made them forget how to hunt entirely.","It caused all food to spoil quickly."]',1,'A successful harvest means you can save food for winter or dry seasons!','Farming allowed many communities to produce food more regularly and store some supplies for later.','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_008','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How does traditional agriculture generally differ from modern agriculture?','["Traditional agriculture relies on robots; modern uses horses.","Traditional agriculture uses hand tools, animal power, and natural seasons, while modern agriculture uses tractors, scientific methods, and advanced irrigation.","Traditional agriculture doesn''t use water; modern does.","There is no difference in the equipment used."]',1,'Modern farms use machines and science to grow more food.','Traditional agriculture: Farmers used tools, animal power... Modern agriculture: Tractors, improved irrigation, scientific farming methods...','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_009','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why was a thorough understanding of the local environment crucial for ancient ''hunter-gatherer'' societies?','["Because they bought their food from local shops.","Because their entire food supply depended directly on knowing what wild plants and animals were naturally and seasonally available in their specific area.","Because they had to build large stone farms.","Because the environment changed the color of their clothing."]',1,'You can''t gather winter berries in the summer!','Early food collection: People hunted, gathered, and fished. Their food supply depended heavily on the local environment and seasonal availability.','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_010','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',10,'Analyze the socioeconomic impact of transitioning from ''hunting and gathering'' to ''agriculture'' in early human history.','["Agriculture made it impossible to store food.","Agriculture enabled the production of a reliable caloric surplus, which necessitated physical storage systems and allowed parts of the population to specialize in non-farming labor.","Hunting and gathering was the only way to establish permanent cities.","Agriculture meant people only ate once a year."]',1,'Farming creates extra food that needs to be stored, managed, and traded!','Farming allowed many communities to produce food more regularly and store some supplies for later... Many communities stored grain for later use.','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_011','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is the primary purpose of clothing?','["Only to look wealthy","To protect the body from weather and injury, and to express culture or occupation","To make it harder to move","To become invisible in the forest"]',1,'It keeps you warm, safe, and dry.','Clothing protects the body from weather, injury, and other environmental conditions. It can also express culture...','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_012','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'Which of these materials is an animal fibre commonly used for warm clothing?','["Cotton","Linen","Polyester","Wool"]',3,'It comes from the fleece of sheep.','Wool: An animal fibre useful for warm clothing.','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_013','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is linen made from?','["Animal fur","Flax fibres","Silkworms","Cotton plants"]',1,'It is a light, breathable material from a plant.','Linen: A fabric made from flax fibres.','2026-11-01 10:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_014','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What natural fibre is produced by small insects?','["Linen","Wool","Silk","Polyester"]',2,'These insects spin very fine, smooth threads.','Silk: A natural fibre produced by silkworms.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_015','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is a ''synthetic fibre''?','["A material made directly from animal skin","A material like polyester that is developed through modern chemical industries","A type of ancient stone tool","A fabric made by early hunter-gatherers"]',1,'It is man-made in a factory, not grown in nature.','Synthetic fibres: Materials such as polyester developed through modern chemical industries.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_016','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is a ''textile''?','["A wooden boat","Cloth or fabric made from fibres","A type of clay pot","A wild plant used for food"]',1,'It is the material your clothes are made of.','Textile: Cloth or fabric made from fibres.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_017','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is a ''fibre''?','["A type of modern metal","A thin strand used to make materials such as fabric","A stone building block","A type of ancient writing"]',1,'It is spun together to make thread.','Fibre: A thin strand used to make materials such as fabric.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_018','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why did early human clothing designs strongly reflect the local environment?','["Because people bought clothes from global markets.","Because people had to use whatever natural resources were locally available (like animal skins or plant fibres) to create protection suited exactly to their local climate.","Because early humans only wore one type of fabric everywhere.","Because clothing didn''t actually exist back then."]',1,'If you live in the Arctic, you need thick furs, not thin cotton!','In some environments, people used animal skins and plant materials. Clothing designs reflected available resources and the need for protection.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_019','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How did the skills of ''spinning and weaving'' change how clothing was made in traditional societies?','["It stopped people from wearing clothes.","It allowed people to take raw plant or animal fibres and manufacture them into continuous pieces of fabric and garments using handlooms.","It turned cloth into heavy metal.","It was only used to build houses."]',1,'You can''t wear a pile of loose cotton; you have to weave it into a fabric!','Spinning, weaving, and sewing helped people make fabrics and garments. Handlooms and skilled textile workers supported local industries...','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_020','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why do people in hot regions generally choose different clothing than people in cold regions?','["Because clothing color changes automatically.","Hot climates require lightweight clothing that allows ventilation, while cold climates require thick clothing that retains body heat.","Because people in cold regions do not like clothing.","There is no difference in global clothing choices."]',1,'You dress to survive your local weather!','In cold places, people need clothing that helps retain body heat. In hot places, many people prefer lightweight clothing that allows ventilation.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_021','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',10,'Synthesize how the shift from ''handmade textiles'' to ''modern clothing production'' transformed global economics.','["It meant everyone had to weave their own clothes again.","The shift from local artisanal handlooms to mechanized industrial factories enabled mass production using synthetic fibres, creating a massive global trade network and drastically lowering the cost of clothing.","It completely stopped the trade of clothing worldwide.","It meant clothing was only made from animal skins."]',1,'Machines can make a thousand shirts in the time it takes a human to weave one!','Modern clothing production: Industrial machines and global trade made it possible to produce large quantities of clothing from many different fibres and fabrics.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_022','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is the main purpose of shelter?','["To watch television","To protect people from weather, provide a place to rest, and store belongings","To grow indoor crops","To run a business"]',1,'It keeps you safe and dry.','Shelter protects people from weather and provides a place to rest, store belongings, and live with family.','2026-11-01 10:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_023','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What were some natural shelters used by early humans?','["Skyscrapers","Caves and rock overhangs","Glass houses","Brick and steel buildings"]',1,'They found places in nature to hide from the weather.','Natural shelters: Some early humans used caves and rock overhangs.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_024','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What materials are traditional houses often built with?','["Plastic and rubber","Locally available materials like mud, stone, timber, bamboo, and thatch","Steel and concrete","Only glass"]',1,'People built with what they could find around their village.','Traditional houses: Houses were often built using locally available materials, including mud, stone, timber, bamboo, thatch...','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_025','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What materials are widely used in modern buildings?','["Only leaves and mud","Bricks, concrete, steel, and glass","Animal skins","Only timber"]',1,'These materials make buildings very tall and strong.','Modern buildings: Bricks, concrete, steel, glass, and engineered materials are widely used.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_026','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How do environmental conditions like heavy rain influence traditional shelter design globally?','["Rainy regions require flat roofs with no drainage.","Rainy regions require sloping roofs and effective drainage to manage rainwater and prevent leaks.","Rainy regions require houses to be built completely underground.","Rain does not influence shelter design."]',1,'A flat roof will cave in from heavy water weight!','Rainy regions: Sloping roofs and effective drainage help manage rainwater.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_027','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How do builders globally adapt shelters in earthquake-prone regions?','["They build them entirely out of rigid glass.","They use appropriate structural designs and reinforcements to improve safety and flexibility during seismic shaking.","They build them on top of tall, unstable trees.","They refuse to build shelters in those regions."]',1,'The building needs to sway slightly without collapsing.','Earthquake-prone regions: Appropriate structural design can improve safety.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_028','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'What specific shelter adaptations are used globally in flood-prone areas?','["Building underground bunkers.","Using raised floors (like stilts) and careful site selection to reduce the risk of water damage.","Building houses out of mud that dissolves in water.","Putting wheels on the house."]',1,'If the river rises, you want your floor to be higher than the water!','Flood-prone areas: Raised floors and careful site selection can reduce certain flood risks.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_029','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why is ''insulation'' important for houses in cold climates?','["It makes the house slide on ice.","Insulation and protection from wind help retain body heat and fire heat inside the house, keeping the people warm.","It lets all the cold air inside.","It makes the house invisible in the snow."]',1,'It acts like a thick winter coat for the building!','Cold climates: Insulation and protection from wind help retain warmth.','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_030','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',10,'Critique the assumption that modern engineered buildings (steel/concrete) are universally superior to traditional homes.','["Modern buildings are always perfect and traditional homes always collapse.","While modern materials accommodate urban density, traditional homes often utilize sustainable, locally sourced materials and passive architectural designs (like specific roof slopes or natural ventilation) that are perfectly environmentally adapted to their specific regional microclimate.","Traditional homes were actually made of modern steel.","Modern buildings are only used in deserts."]',1,'Traditional designs were perfected over hundreds of years to beat the local weather naturally!','Houses were often built using locally available materials... Hot climates: Shade, airflow... Cold climates: Insulation... Rainy regions: Sloping roofs...','2026-11-01 10:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_031','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'Before gas and electricity, what fuels did traditional households commonly use for cooking?','["Microwaves","Firewood, charcoal, or clay ovens","Solar panels","Plastic"]',1,'They had to build a real fire to cook.','Traditional cooking: Many households used firewood, charcoal, clay ovens, or other locally available fuels.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_032','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'Which of these is a traditional, manual household tool?','["A microwave","A washing machine","A grinding stone","A refrigerator"]',2,'It requires physical human energy to work.','Traditional tools: Grinding stones, hand-operated tools, clay pots...','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_033','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is an ''appliance''?','["A wild animal","A device used to perform a household task","A type of ancient boat","A traditional clay pot"]',1,'A washing machine or refrigerator is an example.','Appliance: A device used to perform a household task.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_034','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is a major benefit of modern household appliances like washing machines and electric mixers?','["They use no electricity at all.","They can significantly reduce the physical time and effort needed for household tasks.","They make food taste worse.","They require you to gather firewood."]',1,'They do the hard, repetitive work for you.','Modern appliances... can reduce the time and effort needed for some household activities.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_035','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why do some households globally today still depend on traditional cooking or washing methods instead of modern appliances?','["Because modern appliances are illegal everywhere.","Due to cost, geographic location, personal choice, or a lack of access to reliable electricity and modern plumbing services.","Because traditional methods are always much faster.","Because modern appliances don''t actually work."]',1,'You can''t use an electric washing machine if your village doesn''t have power lines!','Some households still depend on traditional methods because of cost, location, personal choice, or access to electricity and other services.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_036','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'In the past, how did people mostly travel and transport goods?','["Walking, using animals, boats, and carts","Cars and airplanes","High-speed trains and buses","Helicopters"]',0,'They relied on muscle power and wind.','Transport in many past societies: Walking, animals, boats, and carts.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_037','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'How do people mostly communicate over long distances today compared to the past?','["Using smoke signals","Using phones, email, video calls, and the internet","Only through face-to-face talking","By sending messengers on horses"]',1,'Digital technology changed how we talk globally.','Communication in many places today: Phones, email, video calls, and the internet.','2026-11-01 10:02:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_038','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What does ''technology'' mean in a historical context?','["Knowledge, tools, and methods used to solve problems","Only modern digital computers","The study of old rocks","A type of farming"]',0,'Even a stone axe is a type of technology!','Technology: Knowledge, tools, and methods used to solve problems.','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_039','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How does global ''trade'' act as a catalyst for changes in everyday life?','["It stops people from sharing.","It allows communities to gain access to new goods, materials, foods, and ideas from other regions that they couldn''t produce themselves.","It forces everyone to eat the exact same food.","Trade never changes everyday life."]',1,'Trading brings new tools and fabrics to villages that never had them before!','Trade: Communities gained access to goods and ideas from other regions.','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_040','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How did population growth and urbanization (growing cities) force changes in how food and shelter were managed globally?','["It forced everyone to become hunter-gatherers again.","Growing cities meant fewer people were farming, requiring massive agricultural supply chains, food preservation, and engineered buildings to safely house and feed dense populations.","It caused people to stop eating entirely.","It meant houses were no longer necessary."]',1,'When millions of people live in one city, you need supermarkets and high-rise apartments!','Population growth and urbanization: Growing towns and cities changed housing and food needs.','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_041','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'How did the development of new ''energy and infrastructure'' (like electricity grids and paved roads) transform households?','["It made households completely dark.","It allowed for the use of modern appliances, electric lighting, plumbing, and fast transport, fundamentally changing how daily chores and travel were done.","It forced people to use only firewood.","It had no effect on households."]',1,'Plumbing and power lines changed how we clean, cook, and live.','Energy and infrastructure: Electricity, roads, and water systems transformed many households.','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_042','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why do traditional methods like fishing, gathering, and pastoralism still continue today alongside modern mechanized farming?','["Because modern farming is illegal globally.","Because farming did not develop everywhere, and some environments (like coasts, deserts, or harsh mountains) are better suited to these traditional methods.","Because people forgot how to farm.","Because animals refuse to be farmed."]',1,'You can''t farm wheat on the open ocean or in the frozen tundra!','However, farming did not develop everywhere at the same time, and hunting, gathering, fishing, and pastoralism continued in many societies.','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_043','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',10,'Analyze the socio-economic inequality highlighted by the historical and modern adoption of household technology.','["Everyone on Earth has immediate access to new technology.","Technological advancements (like refrigeration and electric grids) drastically improve living standards, but capitalistic distribution and infrastructural gaps mean marginalized or rural populations globally are often left relying on labor-intensive traditional methods, exacerbating inequality.","Technology makes everyone perfectly equal immediately.","Traditional methods are actually much more expensive than modern ones."]',1,'A refrigerator is great, but only if you can afford to buy it and pay for the power to run it!','Technology has made many tasks faster, but benefits are not equally available to everyone. Some households still depend on traditional methods because of cost, location... or access to electricity...','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_044','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is a major advantage of modern clothing production using machines?','["It produces very few clothes.","It makes it possible to produce large quantities of clothing quickly from many different fabrics.","It only uses animal skins.","It requires everyone to weave their own clothes."]',1,'Factories can make thousands of shirts a day.','Modern clothing production: Industrial machines and global trade made it possible to produce large quantities of clothing...','2026-11-01 10:02:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_045','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',1,'What is an example of a modern cooking appliance?','["A clay oven","A microwave","A wood fire","A stone grill"]',1,'It uses electricity instead of fire.','Modern cooking: Gas stoves, electric cookers, induction cooktops, and microwaves are used in many homes.','2026-11-01 10:02:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_046','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',5,'Why might a society choose to build houses with thick stone walls and small windows?','["To make the house look invisible.","To retain warmth in a cold climate, or to keep heat out in a very hot desert climate.","Because they don''t like sunlight.","Because glass was outlawed."]',1,'Thick walls act as strong insulation.','Houses were often built using locally available materials... In cold regions, homes needed to retain warmth.','2026-11-01 10:02:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_needs_global_047','History','Basic History','Topic 9: Food, Clothing, and Shelter','Primary',10,'Evaluate the assertion that ''no single clothing style represents everyone in a region.''','["Everyone in a region always wears the exact same uniform by law.","Clothing is a highly intersectional cultural artifact; even within the identical climate, an individual''s clothing is heavily modulated by their specific occupation, wealth, social customs, and personal preference.","Clothing styles are strictly determined by the global climate only.","Clothing is identical across the entire world."]',1,'A wealthy merchant and a poor farmer in the same city will dress very differently!','No single style represents everyone in a region. Clothing changes with time, culture, occupation, and individual preference.','2026-11-01 10:02:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_001','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What does ''transport'' mean?','["Growing crops on a farm","Moving people and goods from one place to another","Building large stone houses","Making clothes from wool"]',1,'It is how we travel.','Transport means moving people and goods from one place to another.','2026-11-01 10:02:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_002','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What was one of the earliest ways humans travelled?','["By train","By riding horses","Walking","By sailing ship"]',2,'Before animals were tamed, humans used their own legs.','Walking was one of the earliest ways humans travelled.','2026-11-01 10:02:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_003','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'Which animal is particularly useful for transport across many dry, desert regions?','["Donkey","Horse","Oxen","Camel"]',3,'They can survive long periods without water.','Camels: Particularly useful for travel across many dry regions.','2026-11-01 10:02:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_004','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What were oxen primarily used for in early transport?','["Carrying messages quickly","Pulling carts and assisting with agricultural work","Riding in battles","Traveling across oceans"]',1,'They are very strong animals good for pulling heavy loads.','Oxen: Used to pull carts and assist with agricultural work.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_005','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What is a major advantage and a major limitation of walking as a form of transport?','["It requires no fuel, but journeys over long distances can take considerable time and physical effort.","It is the fastest way to travel, but requires buying fuel.","It requires a lot of fuel, but it is very fast.","It cannot be used to cross land, but it is free."]',0,'Your legs don''t need petrol, but they get tired!','Walking required no vehicle or fuel, but journeys over long distances could take considerable time and effort.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_006','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'Why did early communities need to develop new ways to carry loads?','["Because walking became illegal.","As communities grew and trade increased, human hands and baskets were no longer enough to transport the heavier loads required for farming and building.","Because animals refused to carry goods.","Because they invented the airplane first."]',1,'You can''t carry enough bricks to build a city in your bare hands!','As communities grew, they developed better ways to transport heavier loads.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_007','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What invention made it much easier to move agricultural products and building materials using animals?','["The sailing boat","Wheeled carts and wagons","The steam engine","The hot air balloon"]',1,'It rolls instead of drags.','Wheeled vehicles pulled by animals made it easier to move agricultural products, building materials, and other heavy goods.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_008','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What powered the railways that expanded rapidly during the 19th century?','["Electricity","Horses","Steam locomotives","Solar panels"]',2,'They boiled water using coal to create power.','Steam-powered railways expanded during the 19th century.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_009','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What is a ''motor vehicle''?','["A cart pulled by an ox","A road vehicle like a car or bus powered by an engine or electric motor","A train moving on tracks","A boat powered by wind"]',1,'It uses a motor, not an animal, to move.','Motor vehicles: Cars, buses, and trucks became increasingly important with the development of engines...','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_010','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'How did the expansion of steam-powered railways change the transport of goods?','["It restricted goods to local areas only.","Trains could carry many passengers and massive quantities of heavy goods over long distances much faster than animal carts.","It stopped people from trading completely.","It made land transport much slower."]',1,'A train can carry what a hundred horses could, but much faster!','Trains could carry many passengers and large quantities of goods over long distances.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_011','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'Why was the invention of the wheel not universally useful in every ancient environment?','["Because wheels required gasoline.","Wheels require relatively flat terrain or roads; they are not practical in thick jungles, steep mountains, or deep snow, where pack animals or sledges are better.","Because wheels were outlawed by early kings.","Because all wheels were made of stone and were too heavy to move."]',1,'Try pushing a wheeled cart up a rocky mountain!','However, wheels were not the only important transport development... wheels were not useful in every environment.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_012','History','Basic History','Topic 10: Transport and Travel Through History','Primary',5,'What did early sailing boats use to move across rivers and seas?','["Steam engines","Electric motors","Wind","Solar power"]',2,'They used large sails to catch the breeze.','Sailing boats: Used wind to move across rivers and seas.','2026-11-01 10:02:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_013','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What is a ''port''?','["A train station","A place where ships load or unload passengers and goods","An airport terminal","A place to park a car"]',1,'It''s a parking lot for ships.','Port: A place where ships load or unload passengers and goods.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_014','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What did rowboats use to move through the water?','["Sails","Engines","Oars","Magnets"]',2,'You have to use your arm muscles.','Rowboats: Moved through water using oars.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_015','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'How did the Industrial Revolution change water transport?','["It caused all ships to sink.","It introduced steam-powered ships, which reduced dependence on unpredictable winds and allowed for faster, more reliable ocean travel.","It forced sailors to row their ships.","It replaced all ships with airplanes."]',1,'A steamship can travel even when there is no wind blowing!','During the Industrial Revolution, steam-powered ships reduced dependence on wind.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_016','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'Why are ships still used today for global trade despite the existence of fast airplanes?','["Because airplanes cannot cross oceans.","Ships are vastly more efficient and cost-effective for carrying extremely heavy and bulky cargo across oceans.","Because ships are faster than airplanes.","Because the oceans are drying up."]',1,'You can''t fit a thousand cars or tons of grain inside an airplane easily!','Why water transport matters: Ships can carry heavy and bulky cargo.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_017','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What allowed people to rise into the sky before airplanes were invented?','["Helicopters","Hot-air balloons","Space rockets","Kites"]',1,'They float up using hot air.','Balloons: Hot-air balloons and other lighter-than-air craft allowed people to rise into the sky.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_018','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'Who achieved a pioneering powered, controlled, sustained flight in 1903?','["Alexander Graham Bell","Thomas Edison","The Wright brothers","Galileo Galilei"]',2,'They built the first successful airplane.','Powered aircraft: Orville and Wilbur Wright achieved a pioneering powered, controlled, sustained flight in 1903...','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_019','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What is ''aviation''?','["The study of birds","The operation and development of aircraft","The building of ships","The driving of trains"]',1,'It covers anything related to flying planes.','Aviation: The operation and development of aircraft.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_020','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'What is the main advantage of air transport over land or water transport?','["It is the cheapest way to travel.","It uses the least amount of energy.","It is generally the fastest way to travel long distances, connecting countries and continents quickly.","It can carry the heaviest bulk cargo, like iron ore."]',2,'A journey that takes weeks by ship takes hours by plane!','Advantages of air transport: It is generally the fastest way to travel long distances.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_021','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'What are the major limitations of air transport?','["It is too slow.","It can be very expensive, requires specialized infrastructure like massive airports, and is highly energy-intensive.","It cannot fly over oceans.","It requires a railway track."]',1,'You can''t just land an airplane anywhere; you need a long runway!','Limitations: Air travel can be expensive, requires airports and specialised infrastructure, and uses substantial energy.','2026-11-01 10:02:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_022','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What is ''cargo''?','["A type of vehicle","A person driving a train","Goods carried by a vehicle or ship","A type of road"]',2,'It is the stuff being transported, like food or electronics.','Cargo: Goods carried by a vehicle or ship.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_023','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What does ''infrastructure'' mean when talking about transport?','["Basic systems such as roads, bridges, railways, and airports","The weather on a given day","The people riding the bus","The fuel used in a car"]',0,'It is the physical network that allows vehicles to move.','Infrastructure: Basic systems such as roads, bridges, railways, and airports.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_024','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'How does transport help with emergency services?','["It stops ambulances from driving.","Ambulances, rescue helicopters, and boats help deliver assistance quickly during emergencies.","It causes more emergencies.","It has no effect on emergencies."]',1,'Fast transport saves lives.','Emergency services: Ambulances, rescue vehicles, aircraft, and boats help deliver assistance during emergencies.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_025','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'How does reliable transport support a region''s economy?','["It forces everyone to stay home.","It allows farmers and manufacturers to send goods to distant markets, expanding their business and supplying essential products to other areas.","It prevents people from buying food.","It destroys all factories."]',1,'If you can''t transport your goods, you can''t sell them!','Trade and the economy: Farmers, manufacturers, and businesses can send goods to distant markets. Reliable transport helps supply food...','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_026','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'What are some of the negative environmental effects caused by modern motorized vehicles?','["They create new forests.","They can cause severe air pollution, noise, traffic congestion, and greenhouse-gas emissions.","They make the air completely clean.","They reduce all travel times to zero."]',1,'Cars are useful, but their exhaust is bad for the planet.','Environmental effects: Vehicles can cause air pollution, noise, traffic congestion, and greenhouse-gas emissions.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_027','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'Why is there no ''single best transport method'' for every journey?','["Because all methods cost the exact same amount.","The most suitable choice depends on a combination of distance, cost, time constraints, cargo size, accessibility, and environmental impact.","Because walking is always the best choice.","Because airplanes can go underwater."]',1,'You wouldn''t take an airplane to go to the grocery store, and you wouldn''t walk to another continent!','No single transport method is best for every journey. The most suitable choice depends on distance, cost, time, cargo...','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_028','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'Analyze the paradox of modern urbanization and road transport infrastructure.','["Building more roads completely eliminates all traffic instantly.","While motor vehicles and expanded road networks allow for immense flexibility and suburban growth, they inherently induce demand, leading to chronic traffic congestion, significant environmental degradation (emissions), and the displacement of pedestrian-friendly civic spaces.","Road transport has no effect on cities.","Cars are entirely beneficial with zero negative externalities."]',1,'Building more lanes often just encourages more people to drive, leading to the same traffic jam!','Motor vehicles... transformed personal travel... [but] also created challenges, including traffic congestion... air pollution... Infrastructure: Basic systems such as roads...','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_029','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'Synthesize how the evolution of transport technology (from sail to steam to aviation) compressed ''global space and time''.','["It made the world physically larger.","Technological shifts drastically reduced the time required to traverse the globe. This ''time-space compression'' accelerated globalized trade, cultural homogenization, and the rapid spread of both ideas and diseases, effectively shrinking the experiential size of the world.","It isolated continents from each other completely.","It slowed down all human communication."]',1,'A voyage that took Christopher Columbus months takes us hours today; the world feels much smaller!','Air transport: ...fastest way to travel long distances. It connects countries and continents... Ships connected ports... and distant societies.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_030','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'Evaluate the socio-economic implications of ''infrastructure'' development in a growing nation.','["Infrastructure only benefits the wealthy.","Developing robust infrastructure (railways, ports, airports) requires massive capital investment and labor, but it acts as an economic multiplier by lowering logistical costs, integrating remote regions into national markets, and increasing access to education and employment.","Infrastructure prevents trade and education.","Infrastructure naturally builds itself without human intervention."]',1,'A city without roads is like a body without veins; goods and people can''t circulate!','Infrastructure: Basic systems... Transport supports trade, education, employment... Reliable transport helps supply food... Railways helped connect towns, cities, ports...','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_031','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What is a ''vehicle''?','["A type of horse","A means of carrying people or goods","A road built for walking","A type of fuel"]',1,'A car, boat, and airplane are all vehicles.','Vehicle: A means of carrying people or goods.','2026-11-01 10:02:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_032','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What does ''navigation'' mean?','["Building a road","Planning and directing a journey","Fueling an engine","Carrying a heavy load"]',1,'It means figuring out how to get from point A to point B without getting lost.','Navigation: Planning and directing a journey.','2026-11-01 10:02:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_033','History','Basic History','Topic 10: Transport and Travel Through History','Primary',1,'What does an ''engine'' do?','["It grows food.","It converts energy into mechanical power to make a vehicle move.","It builds roads automatically.","It steers a sailing ship."]',1,'It''s the heart of a car or train.','Engine: A machine that converts energy into mechanical power.','2026-11-01 10:02:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_034','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'How can individuals help reduce transport-related environmental emissions?','["By keeping engines running while parked.","By walking, cycling, using public transport, or adopting suitable electric vehicles instead of relying solely on petrol cars.","By taking a separate car for every single passenger.","By avoiding all railway systems."]',1,'Sharing a bus with 40 people is much cleaner than 40 separate cars!','Walking, cycling, public transport, and suitable electric transport can help reduce some environmental impacts.','2026-11-01 10:02:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_transport_global_035','History','Basic History','Topic 10: Transport and Travel Through History','Primary',10,'How does modern transport support ''tourism and culture''?','["It prevents people from leaving their homes.","It enables people to easily visit distant historical places, meet different cultures, and experience new environments.","It destroys all historical places.","It makes everyone speak the same language."]',1,'Airplanes make it possible to vacation on the other side of the world!','Tourism and culture: Transport enables people to visit historical places, meet people from different cultures, and experience new environments.','2026-11-01 10:02:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_001','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What does ''trade'' mean?','["Only building roads","Buying, selling, or exchanging goods and services","Fighting in a war","Only growing crops for yourself"]',1,'It''s how people get things they don''t make themselves.','Trade is the buying, selling, or exchanging of goods and services.','2026-11-01 10:02:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_002','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What does ''barter'' mean?','["Using modern bank cards to buy things","Exchanging goods or services directly without using money","Traveling by ship to find new lands","Making a map of a trade route"]',1,'If you trade a chicken for a bag of wheat, you are bartering.','Barter means exchanging goods or services directly without using money.','2026-11-01 10:02:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_003','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What happens during ''cultural exchange''?','["People stop talking to each other completely.","People share aspects of their culture, such as language, food, music, art, and knowledge.","People only trade physical gold.","People build large walls between cities."]',1,'It''s how you learn a new song or recipe from a traveler.','Cultural exchange occurs when people or communities share aspects of their culture, such as language, food, music, art...','2026-11-01 10:02:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_004','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Why did early communities start trading with each other?','["To obtain goods and resources that were unavailable in their own region.","Because they had too much money.","To cause arguments.","Because walking was illegal."]',0,'If you live in a desert, you might need to trade to get timber from a forest.','People have traded because different regions produce different goods... To obtain goods unavailable in their own region.','2026-11-01 10:02:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_005','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What does a ''merchant'' do?','["Builds houses","Fights in an army","Buys and sells goods","Grows crops"]',2,'They travel to sell their products.','Merchant: A person who buys and sells goods.','2026-11-01 10:02:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_006','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What was the purpose of using coins in early trade?','["To make bags heavier","To measure value and buy or sell goods more easily than bartering","To skip stones on the water","To build metal houses"]',1,'It is easier to carry coins than to carry cows for trading.','Coins and later other forms of money made it easier to measure value and buy or sell different goods.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_007','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Did the invention of money immediately stop people from bartering?','["Yes, barter became illegal instantly.","No, money did not eliminate barter, which continued in some settings.","Yes, everyone burned their trade goods.","No, because money wasn''t real."]',1,'People in small villages might still trade eggs for milk without using coins.','Money did not eliminate barter, which continued in some settings.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_008','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What is a ''trade route''?','["A path or network used to transport goods between places","A secret underground tunnel","A modern airplane","A type of ancient currency"]',0,'It''s the highway for merchants.','A trade route is a path or network used to transport goods between places.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_009','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What were the ''Silk Roads''?','["A single paved road in modern Europe","A network of routes connecting East Asia, Central Asia, the Middle East, and Europe","A river in South America","A type of clothing factory"]',1,'It was a massive land network for trading.','The Silk Roads were networks of routes connecting parts of East Asia, Central Asia, the Middle East, and Europe.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_010','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Which natural weather pattern helped sailors travel and trade across the Indian Ocean?','["Tornadoes","Snowstorms","Seasonal monsoon winds","Earthquakes"]',2,'Sailors used the predictable winds to blow their ships across the ocean.','Sailors connected East Africa, Arabia, India... often using seasonal monsoon winds.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_011','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What agricultural products were historically famous for being traded from South Asia?','["Arctic ice and snow","Spices such as pepper and cardamom","Plastic and rubber","Only heavy machinery"]',1,'People traveled from across the world to buy these flavors.','Goods traded from India: Spices such as pepper and cardamom.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_012','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What is a ''port''?','["A mountain top","A place where ships load or unload goods and passengers","A desert oasis","A type of ancient coin"]',1,'It is a parking lot for ships.','Port: A place where ships load or unload goods and passengers.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_013','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Which major sea did coastal communities use to connect ports in Africa, Asia, and Europe?','["The Caribbean Sea","The Mediterranean Sea","The Bering Sea","The Dead Sea"]',1,'It was a massive trade hub connecting three continents.','Coastal communities and merchants traded goods around the Mediterranean Sea. Ships connected ports in Africa, Asia, and Europe.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_014','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'How did trade help spread religious and scientific ideas in the past?','["Through contact among merchants, travellers, and teachers moving along trade routes","By preventing people from traveling","By keeping all ideas a secret","Only through television broadcasts"]',0,'Merchants carried their beliefs and knowledge with their cargo.','Religious ideas spread through merchants, teachers, travellers, migration... Science and technology... circulated through translations, travel, and learning.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_015','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'If a new spice is introduced to a community through trade, what usually happens?','["The community ignores it.","The community adapts it to their local cooking tastes and creates new dishes.","The community throws it in the river.","The spice disappears."]',1,'Cultures blend new ingredients into their own recipes.','Food: Ingredients, spices, crops, and cooking techniques travelled between regions. Over time, communities adapted them to local tastes.','2026-11-01 10:02:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_016','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What did people trade on the Silk Roads besides physical goods like silk?','["They traded nothing else.","They exchanged religions, technologies, and ideas.","They traded only ocean fish.","They traded modern cars."]',1,'Merchants talked and shared ideas while traveling.','Silk and many other goods travelled along these routes. People also exchanged religions, technologies, and ideas.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_017','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What is an ''import''?','["A good or service brought into a country","A good or service sold to another country","A type of ancient coin","A trade route"]',0,'It is coming IN to the country.','Import: A good or service brought into a country.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_018','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What is an ''export''?','["A good or service brought into a country","A good or service sold to another country","A person who buys things","A type of ship"]',1,'It is exiting the country.','Export: A good or service sold to another country.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_019','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'What is colonialism?','["Fair trade between equal neighbors","Control of one country or people by another, often involving exploitation of resources and labor","A type of ancient religion","A cultural festival"]',1,'It involves one powerful country taking over another.','Colonialism: Control of one country or people by another, often involving exploitation.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_020','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Which of these is a major benefit of trade?','["Greater availability of different goods","The spread of infectious diseases","Exploitation of workers","Environmental damage"]',0,'It gives you access to things you can''t make yourself.','Benefits: Greater availability of goods. More occupations and income.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_021','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',1,'Which of these is a challenge or negative effect of trade?','["Greater availability of goods","Growth of towns","Exploitation of workers and spread of infectious diseases","Stronger links between communities"]',2,'Trade is not always fair or safe.','Challenges: Unfair trading practices... Exploitation of workers... Spread of some infectious diseases...','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_022','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did the invention of ''money'' change how people traded compared to ''barter''?','["Money made trade completely illegal.","Money made it much easier to measure the exact value of items and buy or sell goods, rather than trying to figure out how many chickens equal one cow.","Money forced everyone to only use barter.","Money made trade much slower and harder."]',1,'It''s easier to carry coins than to carry a flock of chickens to trade!','Coins and later other forms of money made it easier to measure value and buy or sell different goods.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_023','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'Why is cultural exchange rarely a ''one-way process''?','["Because it is impossible to learn new things.","Because when two communities interact, they both select, adapt, and combine new ideas, foods, and words from each other into their own traditions.","Because kings banned cultural exchange.","Because trade only involves giving, not taking."]',1,'When cultures meet, both cultures usually change a little bit!','Cultural exchange was rarely a one-way process. Communities selected, adapted, and combined ideas according to their own needs and traditions.','2026-11-01 10:02:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_024','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did ''ports'' contribute to the growth of ancient coastal civilizations?','["Ports prevented anyone from entering the city.","Ports served as hubs where ships loaded/unloaded goods, creating massive opportunities for trade, employment, and cultural exchange with foreigners.","Ports were only used for fishing, not trade.","Ports made the oceans dry up."]',1,'A busy port city gets rich by trading with the world.','Coastal trade supported markets, shipping, and craft production... Trade brought people with different languages, religions, and customs into contact.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_025','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'Why did ancient trade routes carry risks as well as benefits?','["Because trade was completely safe.","While routes connected societies, they also exposed merchants to piracy, storms, political wars, and the rapid spread of infectious diseases.","Because merchants never made any money.","Because trade routes only existed for one year."]',1,'Traveling the world was dangerous but profitable!','However, trade routes also carried diseases and could be affected by wars, political changes, storms, and piracy.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_026','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did trade routes impact the development of ancient ''languages''?','["They caused everyone to forget how to speak.","Constant contact between diverse merchants and local communities introduced new vocabulary, spreading words and influencing how people communicated.","They made everyone speak only one global language.","Language was never affected by trade."]',1,'When you trade with someone, you often learn a few of their words!','Language: Contact between communities introduced new words and influenced communication.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_027','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'Why is it historically important to distinguish between ''ordinary trade'' and ''colonialism''?','["Because they are exactly the same thing.","Ordinary trade involves mutual exchange, while colonialism involves unequal political/military control, coercion, and the exploitation of a local population''s land and labor for the benefit of a foreign power.","Because colonialism only happened in the ocean.","Because ordinary trade is illegal."]',1,'One is a fair swap; the other is a forced takeover.','Colonial rule often involved unequal control over land, resources, labour, and trade. It is important to distinguish ordinary trade... from trade conducted under coercion, exploitation, or colonial control.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_028','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How does modern global trade differ drastically from ancient trade routes like the Silk Road?','["Modern trade is much slower.","Modern trade uses digital communication, online marketplaces, and massive cargo ships, meaning a single product might contain materials and parts manufactured in dozens of different countries.","Modern trade only uses barter.","There is no difference; modern trade still only uses camels."]',1,'An ancient merchant carried his own goods; a modern product is built by the whole world!','Modern trade uses ships, aircraft... digital communication... Goods may be designed in one country, manufactured in another, and sold worldwide.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_029','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did the ''Mediterranean trade'' routes help connect different continents?','["They only connected one single country.","Coastal communities and merchants used ships on the Mediterranean Sea to connect ports in Africa, Asia, and Europe, allowing goods and ideas to flow between three continents.","They forced people to walk across the ocean.","They were only used to trade ice."]',1,'The sea was like a giant highway connecting three continents!','Coastal communities and merchants traded goods around the Mediterranean Sea. Ships connected ports in Africa, Asia, and Europe.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_030','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did trade allow ancient societies to overcome geographical limitations?','["It allowed them to stop eating food.","By establishing trade routes, a society living in a desert could exchange their unique goods for timber, food, or metals grown in entirely different environments.","It allowed them to move mountains.","It forced everyone to live in the exact same environment."]',1,'You use trade to get what your own land cannot grow!','People have traded because different regions produce different goods. One region might grow spices, another might produce textiles... To obtain goods unavailable in their own region.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_031','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'Why would a farmer in the ancient world want to produce a ''surplus'' crop?','["To throw it away.","Because a surplus (extra crop) could be traded or sold at markets to earn income, support their family, or obtain raw materials they couldn''t produce themselves.","To make the soil angry.","Because surplus crops were illegal."]',1,'Extra food means extra money!','Why did people trade? ... To sell surplus crops or manufactured products. To earn income and support families.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_032','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How could ''environmental damage'' be considered a modern and historical challenge of trade?','["Trade fixes all environmental problems.","The massive production of goods and the fuel required to transport them across the world (via ships or trucks) can cause severe pollution and deplete natural resources.","Environmental damage only happens when people stop trading.","Trade only damages the ocean, not land."]',1,'Moving millions of goods across the world uses a lot of fuel and creates pollution!','Challenges: ... Environmental damage from production and transport.','2026-11-01 10:02:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_033','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'What role did ''translators'' or shared languages likely play along the Silk Roads?','["They were useless because everyone spoke the exact same language.","Because the Silk Roads connected vastly different cultures (East Asia to Europe), translators or a shared trade language were essential for merchants to successfully negotiate and exchange ideas.","They only fought in wars.","They only built the physical roads."]',1,'You can''t buy or sell if you can''t understand the person!','The Silk Roads were networks of routes connecting parts of East Asia, Central Asia, the Middle East, and Europe... Language: Contact between communities introduced new words...','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_034','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How does the phrase ''goods may be designed in one country, manufactured in another, and sold worldwide'' describe the modern economy?','["It means every country is completely isolated.","It highlights deep global interconnectedness; modern trade relies on massive, complex supply chains where multiple countries contribute to building a single product before it reaches the consumer.","It means trade is slower now than in ancient times.","It proves that barter is still the only way to trade."]',1,'Your phone was likely designed in one country, built in another, and shipped to you!','For example, a product sold online might contain raw materials from several countries and components manufactured in different places. This shows how economies and communities are connected today.','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_035','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'Why might a country heavily restrict imports from other nations?','["To encourage cultural exchange.","To protect their own local farmers or craftspeople from being put out of business by cheaper foreign goods.","Because they want to give away all their money.","To increase the spread of diseases."]',1,'If a foreign country sells very cheap cloth, the local weavers might lose their jobs!','Colonial rule often involved unequal control over land, resources, labour, and trade... (Note: Trade involves competition).','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_036','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',5,'How did trade routes contribute to the growth of massive ''towns and ports''?','["They caused towns to shrink.","As merchants traveled, they needed places to rest, repair ships, and sell goods; these rest stops and trading hubs naturally grew into wealthy, diverse, and heavily populated cities.","They forced everyone to move to the countryside.","Towns and ports only grew when trade was banned."]',1,'A crossroads of trade brings in money and jobs!','Benefits: ... Growth of towns and ports. Trade routes helped cities grow, created occupations for merchants and craftspeople...','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_037','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Analyze the paradox of ''cultural exchange'' along trade routes in terms of societal advancement versus vulnerability.','["Trade routes only offered benefits and had no vulnerabilities.","While trade routes catalyzed rapid societal advancement through the diffusion of critical technologies (like mathematics and navigation), they simultaneously acted as vectors for catastrophic vulnerabilities, such as the rapid transmission of devastating pandemics.","Trade routes prevented any cultural exchange from happening.","Trade routes only spread languages, not technology."]',1,'The same road that brings the cure can also bring the plague.','Trade routes helped cities grow... and connected societies... However, trade routes also carried diseases and could be affected by wars...','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_038','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Synthesize how the concept of ''comparative advantage'' (different regions producing different goods) drove the expansion of ancient global networks.','["It prevented global networks from forming.","Because localized geography and climate dictated specific resource abundance (e.g., spices in South Asia, silk in East Asia), regions were compelled to establish expansive, perilous networks (like the Indian Ocean trade) to acquire vital resources unavailable domestically, driving geopolitical interconnectedness.","It meant every region produced the exact same goods.","It forced everyone to rely entirely on barter."]',1,'You travel the world to get what your own land cannot grow!','People have traded because different regions produce different goods. One region might grow spices, another might produce textiles... To obtain goods unavailable in their own region.','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_039','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Evaluate the assertion that ''cultural exchange is rarely a one-way process'' using historical architecture as an example.','["Architecture was only invented by one country and copied perfectly.","When trade introduced new building techniques or decorative patterns to a region, local builders did not simply copy them; they actively adapted and hybridized those foreign concepts with indigenous styles and environmental constraints to create entirely novel architectural traditions.","Cultural exchange means one culture always destroys another.","Architecture is never influenced by trade."]',1,'A Roman pillar built in Asia will look a bit different because the local artists add their own style!','Art and architecture: Designs, building techniques... spread and were adapted locally. Cultural exchange was rarely a one-way process. Communities selected, adapted, and combined ideas...','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_040','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Critique the traditional narrative that colonialism was simply an advanced form of ''trade and cultural exchange''.','["Colonialism was a perfectly fair trade system.","While colonialism did involve the massive transfer of goods and culture, framing it simply as ''trade'' ignores the fundamental coercion, military dominance, and systemic exploitation of indigenous land and labor that defined colonial rule, which enriched the colonizer at the severe detriment of the colonized.","Colonialism only happened through peaceful bartering.","Colonialism was actually invented by merchants."]',1,'Trade is a mutual handshake; colonialism is a forced takeover.','Colonial rule often involved unequal control over land, resources, labour, and trade. It could benefit colonial powers while causing serious harm to local communities. It is important to distinguish ordinary trade... from trade conducted under coercion...','2026-11-01 10:02:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_041','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Analyze how the transition from a ''barter economy'' to a ''monetary (coin) economy'' catalyzed the scale of global trade.','["It made trade impossible.","Barter relies on a ''double coincidence of wants'' (both parties must want exactly what the other has). The introduction of a standardized currency (money) provided a universal medium of exchange and a metric of value, drastically reducing transaction friction and allowing merchants to trade complex, high-volume goods over vast distances.","It forced merchants to carry heavy rocks.","It meant goods lost all their value."]',1,'Money is much easier to carry across a desert than a herd of cows!','Coins and later other forms of money made it easier to measure value and buy or sell different goods.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_042','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'How did the geographic layout of the ''Indian Ocean trade'' network inherently dictate the technological development of regional ships?','["It meant ships didn''t need sails.","Because merchants relied on the cyclical nature of the seasonal monsoon winds to cross the vast open ocean, shipbuilders were forced to engineer advanced, deep-water vessels with specific sail designs capable of safely navigating these powerful, predictable wind currents.","It forced them to only use rowboats.","It proved that the ocean was actually dry land."]',1,'You have to build a ship that can survive the winds you depend on!','Sailors connected East Africa, Arabia, India... often using seasonal monsoon winds.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_043','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Evaluate the socioeconomic impact of a port city losing its access to a major trade route due to political war or piracy.','["The city would become much wealthier.","Losing access to the trade network would devastate the city''s economy; merchants would lose income, specialized craftspeople would lose their markets, and the city would likely suffer rapid depopulation and urban decay as the flow of wealth and raw materials halted.","The city would simply invent a new ocean.","It would have no effect on the city''s population."]',1,'If the ships stop coming, the money stops flowing, and the city dies.','Why were trade routes important? Trade routes helped cities grow, created occupations... However, trade routes... could be affected by wars, political changes, storms, and piracy.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_044','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Synthesize how ''digital communication and online marketplaces'' have functionally erased geographic borders in modern trade.','["Digital communication made shipping physical goods impossible.","The internet allows consumers to instantly purchase products from any continent, coordinating manufacturing, banking, and global supply chains in real-time, effectively rendering physical distance irrelevant to the *transaction* phase of modern commerce.","It forces everyone to travel in person to buy things.","It proved that ancient trade routes were actually faster."]',1,'You can buy a shirt from across the world with a single click!','Modern trade uses ships, aircraft... digital communication, banks, and online marketplaces. Goods may be designed in one country, manufactured in another, and sold worldwide.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_045','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Analyze the ideological implications of ''religious ideas spreading through merchants'' on the Silk Roads.','["It proved merchants were actually priests in disguise.","As merchants established diaspora communities in foreign trading hubs, their religious practices (like Buddhism or Islam) inevitably intersected with local beliefs, leading to the peaceful, organic diffusion and syncretization of major world religions far beyond their geographic origins.","It meant religion was only used to buy goods.","It stopped people from trading entirely."]',1,'When people trade goods, they also talk about their beliefs and gods!','Religion and philosophy: Religious ideas spread through merchants, teachers, travellers, migration, and other forms of contact.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_046','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Critique the assertion that the ''Silk Roads'' were a single, paved highway connecting Europe and Asia.','["They were a single modern highway built of concrete.","The ''Silk Roads'' is a modern historiographical term for a vast, decentralized, and constantly shifting network of harsh overland and maritime routes, mountain passes, and oasis towns; it was not a single, continuous physical road.","They were actually a series of rivers.","They were built entirely by the Romans."]',1,'It was a web of trails, not a single paved street!','The Silk Roads were networks of routes connecting parts of East Asia, Central Asia, the Middle East, and Europe.','2026-11-01 10:02:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_047','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Evaluate how ''science and technology'' circulated through translations and learning along trade routes.','["Science was only spread through warfare.","Trading hubs often evolved into centers of learning where scholars from diverse cultures met. Key mathematical, astronomical, and medical texts were translated across languages (e.g., Greek to Arabic to Latin), accelerating collective human technological progress.","Science was kept strictly secret and never traded.","Traders only cared about gold, not science."]',1,'A book of medicine from one empire could save lives in another!','Science and technology: Knowledge of mathematics, astronomy, navigation, medicine... circulated through translations, travel, and learning.','2026-11-01 10:02:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_048','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'How does the reliance on ''raw materials from several countries and components manufactured in different places'' create fragility in the modern global economy?','["It makes the economy completely indestructible.","While highly efficient and cost-effective, hyper-connected global supply chains are extremely fragile; a political disruption, natural disaster, or pandemic in just one manufacturing country can halt the production and distribution of goods worldwide.","It ensures that every country produces everything it needs independently.","It means goods never have to be shipped."]',1,'If the factory making the computer chips shuts down, no one in the world can build a new car!','For example, a product sold online might contain raw materials from several countries and components manufactured in different places. This shows how economies and communities are connected today.','2026-11-01 10:02:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_049','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Analyze the role of a ''merchant'' as a cultural ambassador in ancient history.','["Merchants only cared about money and refused to speak.","Because merchants were often the only individuals traversing vast geographical and cultural divides, they inadvertently acted as the primary conduits for cross-cultural diplomacy, linguistic exchange, and the dissemination of foreign artistic and philosophical concepts.","Merchants were officially appointed as government spies.","Merchants were forbidden from learning foreign languages."]',1,'The merchant brings the silk, but he also brings the stories of the land the silk came from!','Trade was not only about buying and selling goods. Traders, travellers, teachers... also carried ideas from one place to another.','2026-11-01 10:02:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_050','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Synthesize the relationship between ''surplus crops'' and the development of ''specialized occupations'' in early trading civilizations.','["Surplus crops prevented anyone from working.","Agriculture that yielded a reliable caloric surplus allowed a society to feed individuals who did not farm. This freed labor allowed for the rise of specialized craftspeople (blacksmiths, weavers) whose manufactured goods were then traded by merchants, driving economic complexity.","Surplus crops were always destroyed by kings.","Specialized occupations existed long before surplus crops."]',1,'If you have extra wheat, you can trade it to a blacksmith for a new plow!','Why did people trade? ... To sell surplus crops or manufactured products... To obtain raw materials for making tools and other goods.','2026-11-01 10:02:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_trade_global_051','History','Basic History','Topic 11: Trade and Cultural Exchange','Primary',10,'Evaluate the ethical implications of the ''exploitation of workers'' as a historical and modern challenge of global trade.','["Trade always ensures perfect equality for all workers.","The relentless pursuit of profit maximization and cheaper goods in global trade has frequently incentivized the exploitation of vulnerable labor forces (from historical slavery to modern sweatshops), highlighting the severe ethical costs of unregulated globalized commerce.","Exploitation only happened before the invention of money.","Workers prefer to be exploited in trade networks."]',1,'Cheap goods often come at a very high human cost.','Challenges: Unfair trading practices. Exploitation of workers... Trade has brought many benefits, but its effects have not always been positive.','2026-11-01 10:02:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_001','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What is a ''historical event''?','["A story that is entirely fictional","A happening from the past that helps explain change in societies or the world","A prediction about the future","A type of ancient tool"]',1,'It is an important moment that altered how people lived.','Historical event: A happening from the past that helps explain change.','2026-11-01 10:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_002','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What did the development of agriculture help early communities do?','["It forced them to move every day.","It helped them establish more permanent settlements.","It made them forget how to build houses.","It caused them to stop trading."]',1,'Growing crops means you have to stay in one place to harvest them.','Farming helped many communities establish more permanent settlements.','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_003','History','Basic History','Topic 12: Important Historical Events','Primary',1,'In which regions did some of the world''s earliest ancient cities rise?','["Only in Europe","Mesopotamia, the Indus Valley, Egypt, and China","Only in North America","Antarctica and the Arctic"]',1,'These were major centers of early civilization.','Cities developed in regions such as Mesopotamia, the Indus Valley, Egypt, and China.','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_004','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What was a major benefit of the invention of writing?','["It stopped people from speaking.","It helped people record trade, laws, stories, and religious beliefs across generations.","It was only used for drawing pictures of animals.","It made memory entirely unnecessary."]',1,'It allowed people to save their thoughts forever.','They helped people record trade, laws, stories, religious beliefs, and government activities. Writing helped preserve information across generations.','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_005','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What is a ''revolution''?','["A type of ancient wheel","A major change in a political, social, or economic system","A completely peaceful transition of a king","A small disagreement between two people"]',1,'It completely changes how a society operates.','Revolution: A major change in a political, social, or economic system.','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_006','History','Basic History','Topic 12: Important Historical Events','Primary',1,'When did the French Revolution begin?','["1492","1776","1789","1914"]',2,'It challenged the monarchy and social order in France.','The French Revolution (1789).','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_007','History','Basic History','Topic 12: Important Historical Events','Primary',1,'Where did the Industrial Revolution begin in the 18th century?','["China","Britain","The United States","Egypt"]',1,'It started with factories and machinery in Europe.','Beginning in Britain in the 18th century and spreading to other regions, industrialization changed production...','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_008','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What year was the American Declaration of Independence signed?','["1492","1776","1789","1945"]',1,'Thirteen British colonies declared their independence.','The American Declaration of Independence (1776).','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_009','History','Basic History','Topic 12: Important Historical Events','Primary',1,'When did the First World War take place?','["1900–1905","1914–1918","1939–1945","1961–1969"]',1,'It started after the assassination of Archduke Franz Ferdinand.','First World War (1914–1918).','2026-11-01 10:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_010','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What event marked the beginning of the Second World War in Europe in 1939?','["The invention of the atomic bomb","Nazi Germany invaded Poland","The signing of the Declaration of Independence","The start of the French Revolution"]',1,'This aggressive invasion sparked the global conflict.','The Second World War began in Europe when Nazi Germany invaded Poland in 1939.','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_011','History','Basic History','Topic 12: Important Historical Events','Primary',1,'When did India become independent from British rule?','["1914","1939","1947","1957"]',2,'It led to the creation of India and Pakistan.','India became independent from British rule on 15 August 1947.','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_012','History','Basic History','Topic 12: Important Historical Events','Primary',1,'Which country became the first sub-Saharan African nation to gain independence from European colonial rule in 1957?','["South Africa","Egypt","Ghana","Mali"]',2,'It inspired many other independence movements in Africa.','Ghana became independent from British colonial rule on 6 March 1957.','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_013','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What was ''apartheid'' in South Africa?','["A type of farming","A system of racial segregation and discrimination enforced by law","A peaceful democratic election","A technological invention"]',1,'It was finally dismantled in the 1990s.','Apartheid: A system of racial segregation and discrimination formerly enforced by law in South Africa.','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_014','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What year was the Universal Declaration of Human Rights adopted by the United Nations?','["1776","1914","1945","1948"]',3,'It set out fundamental rights for all people.','The Universal Declaration of Human Rights (1948). The United Nations General Assembly adopted this declaration on 10 December 1948.','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_015','History','Basic History','Topic 12: Important Historical Events','Primary',1,'Who was the first human to travel into space in 1961?','["Neil Armstrong","Buzz Aldrin","Yuri Gagarin","Tim Berners-Lee"]',2,'He was a Soviet cosmonaut.','First human in space: Yuri Gagarin (1961).','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_016','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What important medical discovery was made by Alexander Fleming in 1928?','["The smallpox vaccine","Penicillin","The structure of DNA","The X-ray"]',1,'It became one of the most important antibiotic treatments.','Discovery of penicillin by Alexander Fleming (1928).','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_017','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What did the Wright brothers achieve in 1903?','["They invented the automobile.","They made the first successful powered, controlled, sustained aeroplane flight.","They traveled to the Moon.","They built the first steam train."]',1,'It marked a major milestone in aviation.','First successful powered, controlled, sustained aeroplane flight by the Wright brothers (1903).','2026-11-01 10:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_018','History','Basic History','Topic 12: Important Historical Events','Primary',1,'Who proposed the World Wide Web in 1989?','["Alexander Fleming","Yuri Gagarin","Tim Berners-Lee","Johannes Gutenberg"]',2,'It transformed online communication.','World Wide Web proposed by Tim Berners-Lee (1989).','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_019','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What does ''chronology'' mean?','["The study of old rocks","The arrangement of events in time order","A type of ancient writing","The science of space travel"]',1,'It helps historians know what happened first, next, and last.','Chronology: The arrangement of events in time order.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_020','History','Basic History','Topic 12: Important Historical Events','Primary',1,'What is ''colonialism''?','["A type of democratic voting","Control of a territory or people by an outside power","A peaceful cultural exchange","The growth of machine-based industry"]',1,'It often involves one country taking over another''s land and resources.','Colonialism: Control of a territory or people by an outside power.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_021','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the development of agriculture fundamentally change human society?','["It made humans travel constantly to find food.","It provided a reliable food source, allowing people to establish permanent settlements instead of living as nomadic hunter-gatherers.","It completely eliminated the need for tools.","It caused humans to forget how to hunt."]',1,'If you plant a field, you must stay there to harvest it.','Farming helped many communities establish more permanent settlements... Farming changed how many people obtained food.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_022','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why did early cities become centers of learning and craft production?','["Because people in cities did not need to eat.","Because cities gathered many people together, encouraging specialized occupations and organized public life.","Because cities were always peaceful and quiet.","Because kings banned learning outside of cities."]',1,'When thousands of people live together, they can share skills and build complex systems.','Cities... became centres of trade, government, craft production, and learning... Cities encouraged specialized occupations and organized public life.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_023','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why is the development of writing considered a critical milestone for modern historians?','["It is the only way to know what the weather was like.","Written records became important sources for historians, helping preserve information, laws, and stories across generations.","Writing proved that ancient people had computers.","Historians can only study societies that spoke English."]',1,'Without writing, historians have to guess based only on artifacts.','Written records also became important sources for historians... Writing helped preserve information across generations.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_024','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the French Revolution spread new ideas despite being a period of violence and instability?','["It forced everyone to speak French.","It challenged the existing social order and spread powerful ideas about citizenship, equality before the law, and political rights.","It completely banned all forms of government.","It created the first internet network."]',1,'The ideas of equality survived even when the government collapsed.','It spread ideas about citizenship, equality before the law, and political rights, although the revolution also involved violence and political instability.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_025','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What were some of the negative consequences of the Industrial Revolution?','["It made travel impossible.","While it transformed production and transport, it also led to highly dangerous working conditions in factories and severe environmental pollution.","It caused everyone to move to farms.","It stopped the production of all clothes."]',1,'Factories were efficient but often unsafe and dirty.','It transformed transport, employment, and cities but also led to dangerous working conditions and pollution.','2026-11-01 10:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_026','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What was a major contradiction in the American Declaration of Independence regarding human rights?','["It declared independence from France, not Britain.","It influenced debates about equal political rights, but completely excluded many people from these rights, as slavery legally continued.","It declared that all people must be ruled by a king.","It banned all forms of freedom."]',1,'They demanded freedom for themselves, while denying it to enslaved people.','The event influenced later debates about government and political rights, although slavery continued and many people were excluded from equal rights.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_027','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What were the major underlying causes that led to the outbreak of the First World War?','["The invention of the printing press and steam engine.","Militarism, complex alliances, imperial competition, extreme nationalism, and the assassination of Archduke Franz Ferdinand.","A dispute over the discovery of penicillin.","The signing of the Universal Declaration of Human Rights."]',1,'It was a powder keg of competing empires.','It was influenced by militarism, alliances, imperial competition, nationalism, and the assassination of Archduke Franz Ferdinand in 1914.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_028','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What was an immediate global political consequence of the end of the Second World War in 1945?','["The immediate end of all global conflicts.","Major changes in global power, the growth of anti-colonial independence movements, and the formation of the United Nations.","The collapse of the Roman Empire.","The start of the Industrial Revolution."]',1,'The world order was completely reshaped after the war.','Consequences included: ... The formation of the United Nations in 1945. Major changes in global power and the growth of independence movements...','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_029','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why is learning about the World Wars important for modern society?','["To memorize dates and names of generals.","To understand the devastating consequences of racism, extreme nationalism, and the vital importance of peacebuilding and international cooperation.","To learn how to build better weapons.","To prove that wars are always beneficial."]',1,'Those who do not learn history are doomed to repeat it.','Studying the World Wars helps learners understand the consequences of aggression, racism, extreme nationalism, and failures of international cooperation.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_030','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the 1947 independence of India affect its population?','["It caused everyone to immediately become wealthy.","While it ended British rule, the subsequent Partition created India and Pakistan, causing massive displacement, loss of homes, and widespread violence.","It merged India and China into one country.","It had absolutely no effect on the daily lives of citizens."]',1,'Freedom came with a heavy, traumatic cost for millions of ordinary people.','Partition created India and Pakistan and caused widespread displacement and violence.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_031','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why was Ghana''s independence in 1957 globally significant?','["It was the first country in the world to ever become independent.","It was the first sub-Saharan African country to gain independence from European colonial rule post-WWII, inspiring other nations to fight for freedom.","It marked the start of the First World War.","It was the year they invented the airplane."]',1,'It proved that colonial rule in Africa could be successfully dismantled.','It was the first sub-Saharan African country to gain independence from European colonial rule in the post-Second World War era, inspiring other independence movements.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_032','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did international pressure contribute to the end of apartheid in South Africa?','["It forced South Africa to start a war.","Combined with internal resistance movements and negotiations, global pressure helped force the government to dismantle the racist system and hold democratic elections in 1994.","It caused South Africa to colonize other countries.","International pressure supported apartheid."]',1,'The whole world pushing against an unjust system can force it to change.','Resistance movements, international pressure, and negotiations helped bring the system to an end. In 1994, South Africa held its first fully representative national democratic election.','2026-11-01 10:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_033','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What was the primary goal of the Universal Declaration of Human Rights?','["To force all countries to share the exact same culture.","To set out fundamental rights and freedoms that all people globally should enjoy, regardless of nationality, background, or status.","To declare that only certain people deserve rights.","To end all trade between countries."]',1,'It created a global standard for how human beings must be treated.','It set out fundamental rights and freedoms that all people should enjoy, regardless of nationality, background, or status.','2026-11-01 10:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_034','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why is it important for historians to note that printing developed in East Asia before Gutenberg''s system in Europe?','["To prove that Gutenberg didn''t exist.","To provide a globally accurate timeline of technological innovation, recognizing that major inventions often build upon or parallel discoveries from multiple cultures.","To show that printing was only useful in Europe.","Because European printing used digital screens."]',1,'History is a shared global achievement, not just a European one.','Helped increase the production of printed books in Europe; printing had developed earlier in East Asia.','2026-11-01 10:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_035','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the discovery of penicillin change global medicine?','["It cured all viral infections like the common cold.","It provided the foundation for powerful antibiotic treatments, making previously deadly bacterial infections highly treatable and saving millions of lives.","It was used to create vaccines for smallpox.","It proved that medicine was no longer needed."]',1,'Before this, a simple scratch could be a deadly infection.','Began the development of one of the most important antibiotic treatments... Antibiotics made many bacterial infections treatable...','2026-11-01 10:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_036','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why do historians say that monumental scientific breakthroughs are rarely the work of just one famous individual?','["Because scientists refuse to work together.","Because most achievements (like powered flight or space travel) rely on the accumulated research, engineering, and institutional support of many people over time.","Because individuals are incapable of inventing anything.","Because all discoveries happen by accident."]',1,'Even famous inventors stand on the shoulders of giants!','These achievements usually relied on the contributions of many researchers, engineers, workers, and institutions—not just one famous individual.','2026-11-01 10:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_037','History','Basic History','Topic 12: Important Historical Events','Primary',5,'What does understanding the ''cause and consequence'' of an event help historians do?','["It helps them predict the exact date of future events.","It helps them explain *why* an event happened and *what effects* it had on society, giving deep meaning to history rather than just memorizing facts.","It helps them forget about the past.","It proves that everything happens randomly."]',1,'History is a chain reaction; one event triggers the next.','By examining the causes and consequences of these events... learners can better understand the modern world. Cause: A reason something happened. Consequence: A result or effect...','2026-11-01 10:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_038','History','Basic History','Topic 12: Important Historical Events','Primary',5,'Why must historical events be studied from the perspectives of different groups of people?','["Because everyone experiences events exactly the same way.","Because the same event can have drastically different consequences for different people (e.g., a victory for an empire might mean exploitation for a colony).","Because historians like to argue.","To ensure all history books are confusing."]',1,'A revolution that frees one group might ignore or harm another!','Recognize that the same event can affect different groups in different ways... To understand different experiences and consequences.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_039','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the World Wide Web transform everyday modern society?','["It completely stopped people from communicating.","It radically changed education, business, communication, and global access to information, making data sharing nearly instantaneous.","It caused people to read more physical books.","It only changed how scientists talked to each other."]',1,'It connected the entire globe''s knowledge base.','The World Wide Web changed education, business, communication, and access to information.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_040','History','Basic History','Topic 12: Important Historical Events','Primary',5,'How did the space race achievements (like Gagarin and Apollo 11) impact human understanding?','["They proved the Earth is flat.","They marked monumental milestones in engineering and expanded scientific understanding of the universe beyond Earth''s atmosphere.","They showed that space travel is incredibly easy and cheap.","They prevented any further scientific research on Earth."]',1,'Leaving the planet changed how we see our place in the universe.','Marked a major milestone in space exploration... Space exploration expanded scientific understanding.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_041','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Analyze the paradox between the political ideals of the American Declaration of Independence and the socio-political reality of 1776.','["The document instantly eradicated all social inequality in America.","While championing universal equality and unalienable political rights, the emerging nation concurrently sustained the systemic institution of slavery and explicitly excluded women and indigenous peoples from these fundamental rights.","The document was written by British royalty to enslave the colonists.","The document banned all forms of democratic government."]',1,'They wrote ''all men are created equal'' while actively owning enslaved people.','The event influenced later debates about government and political rights, although slavery continued and many people were excluded from equal rights.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_042','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Evaluate the dualistic nature of the Industrial Revolution regarding human progress and societal degradation.','["It only provided benefits with zero negative consequences for workers.","It catalyzed unprecedented technological advancement, mass production, and urbanization, but simultaneously generated severe environmental pollution, child labor, and highly dangerous, unregulated working conditions for the urban poor.","It resulted in a total return to agricultural hunter-gatherer lifestyles.","It completely eliminated pollution across the globe."]',1,'Factories made cheap goods, but the smoke choked the cities and the workers suffered.','It transformed transport, employment, and cities but also led to dangerous working conditions and pollution.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_043','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Synthesize how the collapse of major empires after the First World War acted as a catalyst for future geopolitical instability.','["The collapse resulted in immediate, permanent global peace.","The dismantling of vast empires created a volatile vacuum; drawing new, often arbitrary political borders inflamed intense nationalist tensions and territorial disputes that directly contributed to the outbreak of the Second World War.","The collapse meant that all countries merged into one single global government.","It caused all European nations to abandon their militaries."]',1,'When an empire falls, the fight over who controls the leftover land often causes new wars.','Consequences included: ... Several empires collapsed. Political borders changed... Studying the World Wars helps learners understand the consequences of aggression, racism, extreme nationalism, and failures of international cooperation.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_044','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Critique the historiographical assertion that monumental historical shifts, such as the ''development of agriculture'', were instantaneous ''events''.','["Agriculture was invented globally on exactly the same day.","This is fundamentally inaccurate; ''events'' like the agricultural transition were actually slow, evolutionary processes spanning thousands of years, developing independently across different global regions based on local environmental pressures.","Agriculture never actually developed; people still strictly hunt and gather.","Agriculture was an instantaneous event caused by a single inventor."]',1,'You don''t go to sleep as a hunter and wake up as a farmer; it takes generations of slow changes!','Some of the most important events in human history happened gradually over hundreds or thousands of years. They were not single-day events but long-term changes... It developed independently in different parts of the world.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_045','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Analyze how the unprecedented devastation of the Second World War acted as a direct catalyst for the institutionalization of global human rights.','["The war proved that human rights were unnecessary.","The sheer scale of state-sponsored atrocities, specifically the Holocaust, exposed the catastrophic dangers of unchecked nationalism, compelling the global community to establish the UN and formalize the Universal Declaration of Human Rights in 1948 to prevent future genocides.","The war ended the concept of international cooperation entirely.","The war only affected military soldiers, leaving civilians completely unharmed."]',1,'The horror of the war made the world realize they needed strict rules to protect human life.','The Holocaust... The formation of the United Nations in 1945... The Universal Declaration of Human Rights (1948)... set out fundamental rights... Studying the World Wars helps learners understand the consequences of aggression... and why peacebuilding and international institutions became important...','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_046','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Evaluate the inherent limitations of rapid political revolutions (like the French Revolution) in establishing immediate social stability.','["Revolutions always result in immediate, peaceful utopias.","While revolutions successfully dismantle oppressive regimes and introduce radical ideals (like equality), the rapid power vacuum frequently leads to intense political factionalism, violence, and prolonged instability before democratic institutions can solidify.","Revolutions are completely ineffective and never change laws.","Revolutions only happen when the monarch requests them."]',1,'Tearing down a bad government is fast; building a good one takes time and often causes chaos.','It spread ideas about citizenship, equality before the law, and political rights, although the revolution also involved violence and political instability.','2026-11-01 10:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_047','History','Basic History','Topic 12: Important Historical Events','Primary',10,'How did the transition from colonial rule to independence in countries like India highlight the traumatic consequences of externally imposed political borders?','["The borders were drawn perfectly and everyone was happy.","The hasty, externally mandated Partition of the subcontinent artificially divided deeply integrated communities along religious lines, triggering one of the largest, most violent mass displacements in human history as millions fled across the newly drawn borders.","The borders prevented any migration from happening.","The independence was cancelled and colonial rule remained."]',1,'Drawing lines on a map can tear apart real communities living on the ground.','Partition created India and Pakistan and caused widespread displacement and violence.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_048','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Analyze the epistemological shift caused by the independent invention of writing systems in ancient civilizations.','["It caused humans to lose their ability to speak.","Writing fundamentally altered human cognition and societal organization by allowing complex information, legal codes, and historical narratives to be externalized, preserved accurately across generations, and transmitted beyond the limits of biological memory.","It was only used as a form of artistic decoration.","It prevented governments from making any laws."]',1,'Information could finally outlive the person who thought of it!','They helped people record trade, laws, stories... Writing helped preserve information across generations. Written records also became important sources...','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_049','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Evaluate how advancements in the human genome and the discovery of penicillin demonstrate the collective, iterative nature of scientific progress.','["They were both discovered accidentally by kings.","Neither breakthrough occurred in a vacuum; they required the foundational biology of previous generations, immense technological infrastructure, and the collaborative research of diverse international teams, debunking the myth of isolated scientific genius.","They prove that science only requires one smart person.","They were both completed in a single afternoon."]',1,'Science is a massive group project spanning decades!','Discovery of penicillin... Human genome reference research advanced greatly... These achievements usually relied on the contributions of many researchers, engineers, workers, and institutions—not just one famous individual.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_050','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Synthesize the relationship between the conclusion of the Second World War and the rapid acceleration of anti-colonial independence movements globally.','["The war strengthened European empires permanently.","The war devastated European economies, shattered the myth of imperial invincibility, and popularized rhetoric regarding self-determination (e.g., the UN charter), emboldening colonized nations in Africa and Asia to fiercely demand and successfully achieve independence.","The war caused all colonized nations to surrender their claims to freedom.","The war had absolutely no impact on colonial empires."]',1,'The empires were too weak after fighting WWII to hold onto their colonies, and the colonized people demanded the freedom they fought for!','Consequences included: ... Major changes in global power and the growth of independence movements in colonized countries. ...Ghana became independent... inspiring other independence movements.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_051','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Analyze the significance of the United Nations (1945) as an institutional response to early 20th-century militarism.','["It was created to start a Third World War.","Designed as a corrective to the failed League of Nations, the UN institutionalized international diplomacy, collective security, and human rights frameworks to proactively mediate disputes and prevent the catastrophic escalation of aggressive militarism seen in WWI and WWII.","It was established strictly to control global trade networks.","It banned all countries from having governments."]',1,'It is a global forum designed to make countries talk out their problems instead of shooting at each other.','Created an international organization for peace, security, and cooperation... helps explain why peacebuilding and international institutions became important after 1945.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_052','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Critique the historiographical tendency to attribute monumental technological shifts (like the printing press or powered flight) to a single ''lone genius''.','["The lone genius theory is completely factually accurate.","Attributing complex innovations to single individuals (like Gutenberg or the Wright Brothers) obscures the vast, iterative web of prior knowledge, concurrent parallel inventions (e.g., East Asian printing), and the crucial labor of uncredited engineers and mechanics who made the final breakthrough viable.","It means we should only study kings, not inventors.","It proves that inventions appear magically."]',1,'No one invents anything entirely by themselves from scratch!','Printing had developed earlier in East Asia... These achievements usually relied on the contributions of many researchers, engineers, workers, and institutions—not just one famous individual.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_053','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Evaluate the systemic mechanisms that sustained apartheid in South Africa and the multifaceted approach required to dismantle it.','["Apartheid was sustained by voluntary agreement and dismantled by a single speech.","Apartheid was sustained through brutal, legally codified racial segregation and state violence; dismantling it required a synthesis of prolonged internal grassroots resistance, severe international economic pressure (sanctions), and eventual high-level political negotiations.","Apartheid was a democratic system that ended naturally.","Apartheid was only enforced by foreign countries."]',1,'It took pressure from inside the country AND outside the country to break the racist laws.','Apartheid enforced racial segregation and discrimination. Resistance movements, international pressure, and negotiations helped bring the system to an end.','2026-11-01 10:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_054','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Synthesize how the invention of the World Wide Web structurally altered the global distribution of information compared to earlier communication eras.','["It centralized all information into a single physical library.","Unlike broadcast media (radio/TV) which was centralized and top-down, the Web decentralized information, allowing unprecedented, instantaneous peer-to-peer sharing, democratizing access to knowledge but simultaneously complicating the verification of factual accuracy.","It made communication much slower than the telegraph.","It restricted information access to only the wealthiest monarchs."]',1,'Anyone, anywhere could suddenly access the sum of human knowledge instantly.','Led to a system that transformed information sharing and online communication... The World Wide Web changed education, business, communication, and access to information.','2026-11-01 10:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_055','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Analyze the long-term geopolitical impact of the atomic bombings of Hiroshima and Nagasaki in 1945.','["They resulted in the immediate elimination of all global militaries.","While forcing the end of WWII, the deployment of nuclear weapons fundamentally altered global military strategy, initiating the Cold War nuclear arms race and embedding the permanent, existential threat of mutually assured destruction into international relations.","They proved that nuclear weapons were completely harmless.","They had no impact on international relations after 1945."]',1,'The invention of the atomic bomb changed the stakes of war forever; a new world war could mean the end of the world.','The atomic bombings of Hiroshima and Nagasaki in August 1945... Major changes in global power...','2026-11-01 10:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_056','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Evaluate why ''chronology'' is not merely a list of dates, but a necessary epistemological framework for historical analysis.','["Chronology is just a math test for students.","Establishing a precise sequence of events is the absolute prerequisite for identifying causality; without chronology, historians cannot scientifically prove that one specific event (a cause) directly triggered a subsequent socio-political shift (a consequence).","Chronology proves that time travels backward.","Chronology prevents historians from understanding why things happen."]',1,'You have to know that Event A happened *before* Event B to prove that A *caused* B!','Chronology: The arrangement of events in time order. By examining the causes and consequences of these events... learners can better understand the modern world.','2026-11-01 10:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_events_global_057','History','Basic History','Topic 12: Important Historical Events','Primary',10,'Critique the concept of a ''universal'' human right in the context of historically entrenched social inequalities.','["Universal rights are automatically enforced by nature.","While the 1948 Universal Declaration established an aspirational global moral baseline, the term ''universal'' masks the ongoing, systemic reality that marginalized communities globally still face severe structural violence, discrimination, and unequal access to those declared rights.","Universal rights mean everyone has always been treated perfectly.","Human rights are only applicable to citizens of European countries."]',1,'Saying everyone *should* have rights doesn''t mean everyone magically *does* have them; it''s an ongoing fight.','It set out fundamental rights and freedoms that all people should enjoy... However, progress has been uneven, and many communities continue to work for equal rights and opportunities.','2026-11-01 10:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_001','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Why do historians study famous historical people?','["Only to memorize their names and birthdays","To understand how their actions affected societies and influenced the world","To prove that one country is better than others","To ignore the daily lives of ordinary people"]',1,'We study them to see their impact on the world.','Studying historical people helps us understand their achievements, the challenges they faced, and how their actions affected others.','2026-11-01 10:02:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_002','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who was Ashoka?','["A ruler of the Mali Empire","A ruler of the Maurya Empire in the Indian subcontinent who promoted moral conduct","A famous Egyptian pharaoh","An explorer who sailed around the world"]',1,'He is famous for his rock inscriptions.','Ashoka ruled much of the Indian subcontinent during the 3rd century BCE... he promoted Dhamma, moral conduct...','2026-11-01 10:02:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_003','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Which ruler of ancient Egypt worked to preserve her kingdom''s independence from Roman power?','["Marie Curie","Elizabeth I","Cleopatra VII","Harriet Tubman"]',2,'She was known for her political and diplomatic skills.','Cleopatra VII (Egypt)... She worked to preserve her kingdom''s independence during a period of growing Roman power.','2026-11-01 10:02:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_004','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Which 14th-century ruler of the Mali Empire was famous for his wealth and pilgrimage to Mecca?','["Zheng He","Mansa Musa","Ashoka","Ibn Battuta"]',1,'He ruled a wealthy empire in West Africa.','Mansa Musa ruled the Mali Empire in the 14th century. His famous pilgrimage to Mecca demonstrated the wealth...','2026-11-01 10:02:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_005','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who ruled England from 1558 to 1603 during a period of overseas exploration and literary development?','["Queen Victoria","Emmeline Pankhurst","Elizabeth I","Cleopatra VII"]',2,'Shakespeare wrote plays during her reign.','Elizabeth I ruled England from 1558 to 1603. Her reign saw developments in literature, overseas exploration...','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_006','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What was the ''Underground Railroad'' associated with Harriet Tubman?','["A literal train that ran underground","A network of people and safe places used to help enslaved people escape to freedom","A new type of subway system in London","A trade route for spices"]',1,'It was a secret network, not a real train.','Harriet Tubman escaped slavery and repeatedly helped other enslaved people reach freedom through the Underground Railroad, a network of people and safe places.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_007','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who became a prominent leader in India''s independence movement by advocating non-violent resistance?','["Nelson Mandela","Rabindranath Tagore","Mahatma Gandhi","Ashoka"]',2,'He inspired peaceful protests around the world.','Gandhi became a prominent leader in India''s independence movement. He advocated non-violent resistance and civil disobedience.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_008','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What is ''apartheid''?','["A system of racial segregation and discrimination formerly enforced in South Africa","A type of ancient Egyptian writing","A scientific theory about space","An ancient trade route"]',0,'It was a system that treated people unfairly based on race.','Mandela opposed apartheid, a system of racial segregation and discrimination.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_009','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who became South Africa''s first democratically elected president in 1994?','["Mansa Musa","Nelson Mandela","Mahatma Gandhi","Ibn Battuta"]',1,'He spent 27 years in prison before leading the country.','In 1994, he [Nelson Mandela] became South Africa''s first president elected in a fully representative national democratic election.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_010','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What does ''suffrage'' mean?','["Suffering from a disease","The right to vote in political elections","Being forced to work without pay","Exploring the ocean"]',1,'Emmeline Pankhurst fought for this right for women.','Suffrage: The right to vote in political elections.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_011','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who made important contributions to optics (the study of light and vision) in the 10th and 11th centuries?','["Albert Einstein","Ibn al-Haytham","Confucius","Zheng He"]',1,'His work emphasized observation and experiments.','Ibn al-Haytham... made important contributions to optics—the study of light and vision.','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_012','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who was the first woman to receive a Nobel Prize?','["Marie Curie","Emmeline Pankhurst","Tu Youyou","Sacagawea"]',0,'She conducted pioneering research on radioactivity.','Marie Curie... became the first woman to receive a Nobel Prize...','2026-11-01 10:02:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_013','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Which scientist developed the theory of relativity?','["Ibn al-Haytham","Marie Curie","Albert Einstein","Alexander Fleming"]',2,'His work changed how we understand space and time.','Einstein developed the theory of relativity, which transformed modern physics.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_014','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What is Tu Youyou known for?','["Writing The Tale of Genji","Leading research that helped identify a medicine to treat malaria","Sailing around the world","Discovering radioactivity"]',1,'She won the Nobel Prize in 2015.','Tu Youyou led research that helped identify artemisinin, a medicine used to treat malaria.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_015','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who led large Chinese maritime expeditions across the Indian Ocean in the early 15th century?','["Zheng He","Confucius","Ibn Battuta","Ferdinand Magellan"]',0,'He connected China with ports in Africa and Asia.','Zheng He led large Chinese maritime expeditions across the Indian Ocean during the early 15th century.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_016','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who was Ibn Battuta?','["A 14th-century traveller whose accounts provide information about societies and trade networks","A Roman emperor","An ancient Greek philosopher","The inventor of the printing press"]',0,'He traveled further than almost anyone else in his era.','Ibn Battuta was a 14th-century traveller who journeyed through parts of Africa, Asia, and Europe.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_017','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What does ''circumnavigation'' mean?','["Building a large city","Travelling all the way around the Earth","Writing a long book","Discovering a new star"]',1,'Ferdinand Magellan''s expedition is famous for this.','Circumnavigation: Travelling all the way around the Earth.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_018','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who wrote ''The Tale of Genji''?','["William Shakespeare","Murasaki Shikibu","Rabindranath Tagore","Confucius"]',1,'She was a writer in Japan''s Heian period.','Murasaki Shikibu... is known for The Tale of Genji, a major work of Japanese literature...','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_019','History','Basic History','Topic 13: Famous Historical People','Primary',1,'Who became the first Asian Nobel laureate in Literature in 1913?','["Confucius","Rabindranath Tagore","Murasaki Shikibu","Zheng He"]',1,'He contributed greatly to Bengali literature and music.','Tagore was a poet, writer, composer, and educator. In 1913, he became the first Asian Nobel laureate in Literature.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_020','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What did the teachings of Confucius emphasize?','["How to build the best sailing ships","Learning, ethical conduct, respect in relationships, and responsibility","The study of light and vision","How to conquer other countries"]',1,'His ideas strongly influenced East Asian societies.','His teachings emphasized learning, ethical conduct, respect in relationships, and responsibility.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_021','History','Basic History','Topic 13: Famous Historical People','Primary',1,'What is a ''reform''?','["A type of ancient weapon","A change intended to improve a system or practice","The complete destruction of a city","A story about the past"]',1,'It means to make something better.','Reform: A change intended to improve a system or practice.','2026-11-01 10:02:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_022','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why are Ashoka''s rock and pillar inscriptions important to historians?','["They are the only stones left in India.","They recorded his messages promoting Dhamma (moral conduct), providing direct evidence of his policies and values.","They were used to build his palaces.","They prove that he never fought in any wars."]',1,'They act like ancient billboards for his rules.','His messages were recorded in inscriptions on rocks and pillars... providing evidence of government, ethics, and public communication.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_023','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why is Cleopatra''s reign considered historically significant?','["She conquered Rome and became its empress.","She utilized highly effective political skills and diplomatic relationships to preserve Egypt''s independence against the expanding Roman Empire.","She built the very first pyramid in Egypt.","She isolated Egypt and refused to trade with anyone."]',1,'She used diplomacy to protect her country from a stronger power.','She worked to preserve her kingdom''s independence during a period of growing Roman power. She was known for her political skills and diplomatic relationships.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_024','History','Basic History','Topic 13: Famous Historical People','Primary',5,'How did Mansa Musa''s pilgrimage to Mecca affect the Mali Empire''s global reputation?','["It made everyone think Mali was very poor.","It demonstrated the immense wealth and expansive international trade connections of his West African empire to the rest of the world.","It caused the Mali Empire to instantly collapse.","It proved that the empire had no religious beliefs."]',1,'He brought so much gold with him that the world noticed!','His famous pilgrimage to Mecca demonstrated the wealth and international connections of his empire.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_025','History','Basic History','Topic 13: Famous Historical People','Primary',5,'What can be learned about social change from leaders like Emmeline Pankhurst and Harriet Tubman?','["That social change is always given freely by rulers.","That social change usually requires the dedicated efforts, organizations, and resistance of many individuals to challenge unfair treatment and laws.","That social change only happens when scientists invent new things.","That social change is impossible to achieve."]',1,'Change requires people to stand up and fight for it.','Individuals and movements have challenged slavery, discrimination... Social change usually involves the efforts of many people... communities, organizers, workers, and ordinary citizens...','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_026','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why was Nelson Mandela''s transition to the presidency in 1994 a major historical milestone?','["He was the first person to ever vote in Africa.","It marked the end of the racist apartheid system and the beginning of a fully representative, democratic South Africa after years of struggle and his long imprisonment.","It was the start of the Second World War.","He conquered South Africa using a foreign army."]',1,'It was a peaceful transition from an unjust system to a democracy.','After spending 27 years in prison, he was released in 1990 and helped negotiate a transition to democracy. In 1994, he became South Africa''s first president elected in a fully representative... election.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_027','History','Basic History','Topic 13: Famous Historical People','Primary',5,'How did Ibn al-Haytham''s work influence the future of science?','["He proved that science is only about guessing.","By emphasizing observation, experiments, and careful reasoning, he helped establish the foundational methods used in modern scientific inquiry.","He invented the first electric light bulb.","He discovered how to turn lead into gold."]',1,'He relied on testing and proof rather than just guessing.','His work emphasized observation, experiments, and careful reasoning.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_028','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why is Marie Curie''s legacy unique in the history of the Nobel Prize?','["She was the only person to ever refuse the prize.","She became the first woman to receive a Nobel Prize and the first person to receive it in two different scientific fields (Physics and Chemistry).","She bought the Nobel Prize with her own money.","She won the prize for writing poetry."]',1,'Her achievements in radioactivity broke major barriers.','She became the first woman to receive a Nobel Prize and the first person to receive Nobel Prizes in two different scientific fields: Physics and Chemistry.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_029','History','Basic History','Topic 13: Famous Historical People','Primary',5,'How does Tu Youyou''s discovery of artemisinin highlight the value of historical knowledge?','["It proves that modern science is useless.","Her work illustrates the importance of combining modern scientific research with knowledge derived from earlier, traditional medical practices to find new cures.","It showed that traditional medicine is the only way to cure diseases.","It was discovered completely by accident with no prior research."]',1,'She looked to ancient texts for clues to solve a modern medical problem.','Her work illustrates the importance of combining scientific research with knowledge from earlier medical traditions.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_030','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why is it important to remember that many places ''discovered'' by explorers were already inhabited?','["Because the explorers were actually aliens.","It corrects the historical bias that a place only matters once outsiders arrive, acknowledging the presence and prior knowledge of Indigenous peoples and local communities.","Because it proves that explorers never traveled anywhere.","Because the indigenous people had invited the explorers."]',1,'You can''t ''discover'' a place where people already live!','It is important to remember that many places described as “discovered” by outsiders were already inhabited and well known to Indigenous peoples and local communities.','2026-11-01 10:02:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_031','History','Basic History','Topic 13: Famous Historical People','Primary',5,'How did Sacagawea''s role in the Lewis and Clark expedition demonstrate the value of Indigenous knowledge?','["She carried all their supplies on her back.","Her deep knowledge of regional languages, environments, and diplomacy was crucial to the expedition''s survival and success.","She built a large wooden ship for them to use.","She convinced them to turn back and go home."]',1,'Explorers often relied entirely on locals to survive foreign lands.','Her knowledge of languages and regional environments contributed to the journey. Her role is an important reminder that Indigenous knowledge helped explorers and travellers.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_032','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why must historians be careful when using travel accounts (like those of Ibn Battuta) as historical evidence?','["Because travelers were never allowed to write anything down.","Because travellers viewed the world from their own cultural perspectives and biases, meaning their descriptions must be compared with other evidence for accuracy.","Because travel accounts are always 100% fictional.","Because travel accounts disappear after 100 years."]',1,'A traveler might misunderstand a foreign custom and write about it incorrectly.','Travellers viewed the world from their own perspectives, so their descriptions must be compared with other evidence.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_033','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why are literary works like ''The Tale of Genji'' by Murasaki Shikibu valuable to historians?','["They contain the exact dates of every war in history.","They offer deep insights into the court life, human relationships, and cultural values of the society in which they were written.","They prove that Japan invented the printing press.","They are the only books that survived from the 11th century."]',1,'Fiction can tell us a lot about what people valued and how they lived.','It is a major work of Japanese literature that offers insights into court life and human relationships.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_034','History','Basic History','Topic 13: Famous Historical People','Primary',5,'Why do the plays of William Shakespeare continue to be performed worldwide centuries later?','["Because it is illegal to write new plays.","Because his works explore universal human themes such as friendship, ambition, love, jealousy, and power that are still relevant to people today.","Because he paid people to perform them forever.","Because they are written in a secret code."]',1,'Human emotions don''t change, even if the world does.','His works explore themes such as friendship, ambition, love, jealousy, and power and are still performed around the world.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_035','History','Basic History','Topic 13: Famous Historical People','Primary',5,'How do philosophical ideas, like those of Confucius, survive for thousands of years?','["They are magically preserved in stone.","Books, schools, oral traditions, and continuous cultural reinterpretation help pass these foundational ideas from one generation to the next.","They only survive if the philosopher was a king.","They don''t survive; historians just invent them."]',1,'Ideas live on through the people who teach and learn them.','Books, performances, artworks, schools, and oral traditions help pass ideas from one generation to another. People continue to reinterpret famous works...','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_036','History','Basic History','Topic 13: Famous Historical People','Primary',5,'What does it mean to study a historical figure''s ''legacy''?','["To find out where they are buried.","To examine the lasting effects, both positive and negative, that their actions or ideas had on the world after they were gone.","To only study the mistakes they made.","To ignore everything they did while they were alive."]',1,'A legacy is what you leave behind for the future.','Legacy: The lasting effects of a person''s actions or ideas... Their lives show that history is shaped by many kinds of contributions.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_037','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Analyze how Ashoka''s shift to ''Dhamma'' served as a tool for imperial administration and stability.','["It proved he was terrified of war.","By promoting ethical conduct, non-violence, and welfare, Ashoka utilized moral ideology (rather than just military force) to unify and stabilize a vast, diverse empire, reducing the likelihood of internal rebellions after the brutal Kalinga War.","It caused his empire to instantly shatter into small villages.","It was a strategy to trick neighboring empires into disarming."]',1,'Ideology can be a stronger tool for holding an empire together than a sword.','After the Kalinga War, he promoted Dhamma, moral conduct, and concern for people and animals... providing evidence of government, ethics, and public communication.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_038','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Evaluate the diplomatic complexity of Cleopatra''s reign in the context of Mediterranean geopolitics.','["She had no diplomatic strategy and surrendered immediately.","She navigated a precarious geopolitical landscape by forming strategic personal and political alliances with powerful Roman leaders (like Julius Caesar and Mark Antony) to maintain Egyptian autonomy against the overwhelming expansionist pressure of the Roman Empire.","She completely isolated Egypt and banned all Romans from entering.","She conquered Rome using a massive naval fleet."]',1,'She used her intellect and alliances to hold off the greatest superpower of her time.','She worked to preserve her kingdom''s independence during a period of growing Roman power. She was known for her political skills and diplomatic relationships.','2026-11-01 10:02:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_039','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Critique the ''Great Man'' theory of history using the examples of Harriet Tubman and Emmeline Pankhurst.','["The theory is correct because only single individuals ever change history.","Their successes demonstrate that monumental historical change is rarely achieved by a single elite leader; it relies heavily on decentralized networks (like the Underground Railroad) and mass grassroots organizations (like the suffrage movement) comprising countless ordinary, uncredited citizens.","The theory proves that women could not be leaders.","The theory is only applicable to scientists, not social reformers."]',1,'No leader can change the world without a movement of people backing them up.','Social change usually involves the efforts of many people, including individuals whose names are less well known. Famous leaders can inspire movements, but communities, organizers, workers... play important roles.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_040','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Synthesize the global impact of Mahatma Gandhi''s philosophy of ''civil disobedience''.','["It was only effective in India and had no global influence.","His formalized approach to non-violent resistance demonstrated that systemic political oppression could be dismantled without armed conflict, providing a powerful ideological framework subsequently adopted by global civil rights movements.","It proved that violence was the only way to achieve political freedom.","It was a philosophy focused entirely on economic trade."]',1,'His ideas crossed borders and influenced leaders like MLK Jr. and Mandela.','He advocated non-violent resistance and civil disobedience. His methods influenced later campaigns for political and social change...','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_041','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Evaluate the transition of Nelson Mandela from a political prisoner to a democratic head of state in terms of national reconciliation.','["He refused to govern and dismantled the state.","Mandela''s transition was pivotal; rather than seeking retribution after 27 years of unjust imprisonment, he leveraged his profound moral authority to negotiate a peaceful democratic transition, preventing a racial civil war and establishing a framework for national reconciliation.","He became an absolute monarch and banned elections.","He only governed for one week before resigning."]',1,'He chose unity over revenge, which saved the nation.','After spending 27 years in prison, he was released... and helped negotiate a transition to democracy... Mandela''s life demonstrates how leadership can contribute to political change, equality, and reconciliation.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_042','History','Basic History','Topic 13: Famous Historical People','Primary',10,'How did Marie Curie''s achievements challenge the deeply entrenched social paradigms of the early 20th century?','["Her work proved that only men could be scientists.","By winning two Nobel Prizes in distinct scientific fields, she shattered the systemic gender barriers of a male-dominated scientific community, proving that intellectual capacity and scientific rigor are not determined by gender.","She challenged the paradigm by refusing to use scientific equipment.","She proved that science was actually a form of art."]',1,'She proved her genius in a world that tried to exclude women from science.','She became the first woman to receive a Nobel Prize and the first person to receive Nobel Prizes in two different scientific fields... Scientific progress is often collaborative...','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_043','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Synthesize how Albert Einstein''s theory of relativity revolutionized the foundational paradigms of physics.','["It proved that gravity does not exist.","It fundamentally dismantled classical Newtonian physics by demonstrating that space and time are not absolute, but are interwoven and relative to the observer, radically transforming human understanding of energy, gravity, and the universe.","It showed that the Earth was the center of the universe.","It only applied to microscopic bacteria, not space."]',1,'He rewrote the fundamental rules of how the universe operates.','Einstein developed the theory of relativity, which transformed modern physics. His work helped scientists develop a deeper understanding of space, time, gravity, and energy.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_044','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Critique the Eurocentric narrative of ''The Age of Discovery'' by incorporating the maritime achievements of Zheng He.','["Zheng He proved that only Europe had ships.","Zheng He''s massive, state-sponsored expeditions across the Indian Ocean in the early 15th century demonstrate that advanced maritime exploration, diplomacy, and trans-oceanic trade networks were pioneered by non-European powers long before European voyages of the late 15th century.","Zheng He''s voyages were entirely fictional and never happened.","Zheng He only sailed in small rivers, not oceans."]',1,'The Chinese had massive treasure fleets decades before Columbus sailed!','Zheng He led large Chinese maritime expeditions across the Indian Ocean during the early 15th century. His voyages connected China with ports in Southeast Asia, South Asia, Arabia, and East Africa.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_045','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Evaluate the epistemological bias inherent in relying solely on foreign travel accounts (like those of Ibn Battuta or European explorers) to reconstruct local histories.','["Foreign accounts are always 100% objective and flawless.","Foreign travelers inherently interpret local customs through the lens of their own cultural norms, biases, and misunderstandings; relying solely on their accounts risks perpetuating a distorted, ''outsider'' narrative of the society being observed.","Foreign accounts are the only valid form of historical evidence.","Local peoples never had any history before foreigners wrote it down."]',1,'An outsider might completely misunderstand the reason behind a local tradition.','Travellers viewed the world from their own perspectives, so their descriptions must be compared with other evidence.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_046','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Analyze the significance of Ferdinand Magellan''s expedition in permanently altering global navigational paradigms.','["The expedition proved the Earth was flat and impassable.","By completing the first recorded circumnavigation, the expedition definitively proved the interconnectedness of the world''s oceans and the true, vast circumference of the globe, fundamentally altering cartography and global trade routes.","The expedition only sailed around a single island.","The expedition proved that the oceans were drying up."]',1,'It proved you could sail west and eventually end up back where you started.','Magellan led the Spanish expedition that began the first recorded circumnavigation of Earth... before the expedition returned to Spain in 1522...','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_047','History','Basic History','Topic 13: Famous Historical People','Primary',10,'How does the historical presence of figures like Sacagawea complicate the traditional, localized narrative of European ''exploration'' in the Americas?','["It proves Europeans didn''t need any help.","It highlights the indispensable reality that European ''explorers'' were heavily dependent on the diplomatic, linguistic, and geographical expertise of Indigenous peoples to survive and navigate lands that were already fully known to local populations.","It shows that indigenous people had no knowledge of their own land.","It proves that explorers always traveled completely alone."]',1,'Lewis and Clark would have likely died without her help!','Her knowledge of languages and regional environments contributed to the journey. Her role is an important reminder that Indigenous knowledge helped explorers and travellers.','2026-11-01 10:02:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_048','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Synthesize the role of literature (e.g., Murasaki Shikibu or Tagore) in preserving and defining national cultural identity over centuries.','["Literature destroys cultural identity.","Literary works encapsulate the philosophical values, linguistic nuances, and social mores of their era. Over centuries, they become foundational cultural touchstones that subsequent generations use to understand their heritage and define their national identity.","Literature is only useful for learning how to read.","Literature is completely ignored by future generations."]',1,'Great books capture the soul of a civilization.','Writers, artists, philosophers... influence societies through stories... Their work can preserve cultural traditions... His work [Tagore] contributed to Bengali literature, music... The Tale of Genji... offers insights into court life...','2026-11-01 10:02:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_049','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Analyze how Confucian philosophy served as a foundational social and ethical framework for East Asian statecraft.','["It encouraged chaos and violent rebellion.","By emphasizing strict ethical conduct, reciprocal respect in relationships, and civic responsibility, Confucianism provided a rigid, harmonious moral architecture that became deeply embedded in the legal and educational systems of East Asian governments for millennia.","It focused entirely on building advanced military weapons.","It taught that humans should not interact with each other."]',1,'It created a blueprint for how a peaceful, orderly society should operate.','His teachings emphasized learning, ethical conduct, respect in relationships, and responsibility. His ideas strongly influenced Chinese and other East Asian societies.','2026-11-01 10:02:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_050','History','Basic History','Topic 13: Famous Historical People','Primary',10,'Evaluate the ethical necessity for modern historians to examine both the achievements and the limitations/harms of historical figures.','["Historians should only praise historical figures and hide their flaws.","Engaging in uncritical hero-worship obscures historical reality; evaluating a figure comprehensively requires acknowledging their progressive achievements while critically confronting their complicity in systemic injustices (like slavery or exploitation) inherent to their context.","Historians should entirely erase figures who made mistakes.","Historians should assume all historical figures were perfectly evil."]',1,'History is complex; heroes have flaws, and progress often comes with a cost.','To understand their historical importance, we should consider their achievements, their policies, the people affected by their decisions... Historical figures should be studied in context, recognizing both their achievements and the limitations or harms...','2026-11-01 10:02:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_people_global_051','History','Basic History','Topic 13: Famous Historical People','Primary',10,'How does the concept of a historical ''legacy'' inherently change as subsequent generations reinterpret past actions through modern ethical lenses?','["A legacy is locked in stone and never changes.","A legacy is dynamic; as societal values evolve (e.g., regarding human rights or colonialism), modern generations continuously re-evaluate historical figures, often condemning actions that were widely accepted in the figure''s own time, thereby altering their legacy.","Legacies disappear completely after 100 years.","Only the ruler can decide their own legacy."]',1,'A king praised as a ''great conqueror'' 500 years ago might be viewed as a cruel invader today.','People continue to reinterpret famous works, and their meaning may change as societies change. Legacy: The lasting effects of a person''s actions or ideas.','2026-11-01 10:02:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_001','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What does ''heritage'' mean?','["Only things built in the last ten years","Things inherited from the past that people value and pass on to future generations","A type of modern technology","A written school examination"]',1,'It is what we receive from our ancestors.','Heritage refers to things inherited from the past that people value and pass on to future generations.','2026-11-01 10:03:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_002','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is ''culture''?','["A type of building material","The shared ways of life of a community, including language, beliefs, customs, and art","A type of ancient weapon","Only the music of a society"]',1,'It is how a group of people lives and expresses themselves.','Culture includes the shared ways of life of a community, such as its language, beliefs, customs, food, music, art...','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_003','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Which of these is an example of ''tangible'' cultural heritage?','["A traditional song","A spoken language","A historic building or monument","A traditional dance"]',2,'Tangible means you can physically touch it.','Tangible cultural heritage: These are physical objects and places that people can see or touch. Examples: Historic buildings and monuments.','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_004','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Which of these is an example of ''intangible'' cultural heritage?','["A stone sculpture","A traditional dance or language","An old coin","A brick wall"]',1,'Intangible means you cannot physically hold it in your hand.','Intangible cultural heritage: These are living traditions... Examples: Traditional songs, dances... Languages...','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_005','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is ''natural heritage''?','["A modern skyscraper","Natural features like mountains, forests, and coral reefs valued for their beauty or ecosystems","An ancient clay pot","A traditional recipe"]',1,'It is made by nature, not by humans.','Natural heritage: These are natural features and places valued for their beauty, geology, ecosystems...','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_006','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Where is the Great Pyramid of Giza located?','["Peru","China","Egypt","Jordan"]',2,'It was built during ancient Egypt''s Old Kingdom.','Great Pyramid of Giza — Egypt.','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_007','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is the Great Wall of China?','["A single large building","A system of walls and fortifications built to defend territories along China''s northern frontier","An ancient river","A natural mountain range"]',1,'It is thousands of miles long.','The Great Wall is a system of walls and fortifications built, rebuilt, and extended over many centuries. It helped defend territories...','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_008','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is Petra?','["A modern city in Europe","An ancient city in Jordan famous for its rock-cut buildings","A temple in Cambodia","A mountain in Peru"]',1,'The buildings are carved directly into the red rock cliffs.','Petra — Jordan. Petra was an important city of the Nabataeans. Its rock-cut buildings...','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_009','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Which ancient civilization is associated with Machu Picchu?','["The Romans","The Egyptians","The Inca","The Greeks"]',2,'It is a famous stone city high in the mountains.','Machu Picchu — Peru. Located in the Andes Mountains, Machu Picchu is associated with the Inca civilization.','2026-11-01 10:03:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_010','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is the Taj Mahal?','["An ancient Roman market","A mausoleum made largely of white marble built in the 17th century in India","A natural forest","A type of ancient ship"]',1,'It is famous for its beautiful white marble and gardens.','Taj Mahal — India. Built in the 17th century under Mughal emperor Shah Jahan, the Taj Mahal is a mausoleum...','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_011','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Where is Great Zimbabwe located?','["In the Andes Mountains","In southern Africa","In East Asia","In the Mediterranean"]',1,'It was the center of a powerful African society.','Great Zimbabwe — Zimbabwe. Great Zimbabwe was a major stone-built settlement... in southern Africa.','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_012','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is Angkor Wat?','["A natural coral reef","A major temple complex built during the Khmer Empire in Cambodia","A rock-cut tomb in Jordan","A Roman aqueduct"]',1,'It is one of the largest religious monuments in the world.','Angkor Wat — Cambodia. Angkor Wat is a major temple complex built during the Khmer Empire.','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_013','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What can pollution do to heritage sites?','["It cleans the stones","It can harm stone, metal, paintings, and ecosystems","It protects the buildings from weather","It has no effect"]',1,'Dirty air and acid rain can eat away at old stone.','Pollution: Air and water pollution can harm stone, metal, paintings, and ecosystems.','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_014','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What does UNESCO stand for?','["United Nations Educational, Scientific and Cultural Organization","United National Entertainment and Sports Committee","Universal Network for Economic and Social Commerce","Unified Nations for Engineering and Space Observation"]',0,'It is a global group that helps protect heritage.','The United Nations Educational, Scientific and Cultural Organization (UNESCO)...','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_015','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Does UNESCO own all World Heritage Sites?','["Yes, they own the land.","No, the country where the site is located has primary responsibility for its protection.","Yes, they buy the sites.","No, the sites belong to no one."]',1,'The local country is still in charge.','Being listed as a World Heritage Site does not mean that UNESCO owns the place. The country where the site is located has primary responsibility...','2026-11-01 10:03:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_016','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is an ''artifact''?','["A type of weather","An object made or modified by people","A naturally occurring rock","A type of song"]',1,'An ancient coin or tool is an artifact.','Artifact: An object made or modified by people.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_017','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What does ''conservation'' mean?','["Destroying old buildings","Protecting and caring for something so it can survive into the future","Selling historical artifacts","Building new skyscrapers"]',1,'It means keeping old things safe.','Conservation: Protecting and caring for something so it can survive into the future.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_018','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'Which of these is a good way to respect a historic place?','["Writing your name on the wall","Taking small stones home as souvenirs","Following site rules and avoiding touching fragile objects","Leaving litter behind"]',2,'Leave the site exactly as you found it.','Respect historic places: Follow site rules, avoid touching fragile objects, do not write on walls, and never remove artifacts.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_019','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is ''archaeology''?','["The study of stars and planets","The study of past people through material remains","The study of modern languages","The study of future technology"]',1,'They dig up artifacts to learn about the past.','Archaeology: The study of past people through material remains.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_020','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',1,'What is one way ''weathering'' damages heritage?','["It paints the buildings new colors.","Wind, rain, heat, and moisture gradually wear away and damage buildings and objects.","It protects the buildings with a shield.","It moves the buildings to a new city."]',1,'Nature slowly breaks down stone and wood over time.','Weathering: Wind, rain, heat, and moisture gradually damage buildings and objects.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_021','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is ''language'' considered an important part of intangible cultural heritage?','["Because words are written in stone.","Because languages carry unique stories, knowledge, humor, and specific ways of understanding the world that are lost if the language disappears.","Because everyone in the world speaks the exact same language.","Because language is a physical object you can touch."]',1,'When a language dies, a unique way of looking at the world dies with it.','Languages carry stories, knowledge, humour, and ways of understanding the world.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_022','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'How can a single location possess BOTH ''cultural'' and ''natural'' heritage significance?','["It is impossible; a place must be one or the other.","A place might feature a stunning natural landscape (like a mountain) that also holds deep historical or spiritual importance to local Indigenous peoples.","Because the government changes the name every year.","Because animals build cities there."]',1,'A sacred forest is important for its trees (natural) AND its religious meaning (cultural).','Remember: A place can have both cultural and natural significance. Some landscapes are also deeply important to Indigenous peoples... because of their histories... and spiritual traditions.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_023','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'What do the construction techniques of the Great Pyramid of Giza reveal about ancient Egyptian society?','["That they had no leaders.","It demonstrates that they possessed highly advanced planning, engineering skills, and the complex administrative ability to organize a massive labor force.","That they were built randomly by accident.","That they only used wood to build."]',1,'You can''t build a giant pyramid without thousands of workers and brilliant engineers!','...the Great Pyramid demonstrates advanced planning, construction skills, and the organization of labour.','2026-11-01 10:03:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_024','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is Machu Picchu considered an impressive feat of engineering?','["Because it was built completely underwater.","Because its stone buildings and agricultural terraces were successfully adapted to a steep, difficult mountainous environment in the Andes.","Because it is entirely made of plastic.","Because it moves from place to place."]',1,'Building a city on top of a mountain requires extreme skill.','Located in the Andes Mountains... Its stone buildings and terraces reveal impressive engineering and adaptation to a mountainous environment.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_025','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'How does ''urban development'' pose a threat to historical heritage?','["It cleans historical sites.","The construction of new roads, modern buildings, and infrastructure can physically destroy or bury old historic places and archaeological sites.","It turns new buildings into ancient monuments.","It only threatens natural forests, not buildings."]',1,'If a city needs a new highway, they might bulldoze an ancient ruin to make space.','Urban development: Roads, buildings, and other construction may destroy historic places.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_026','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is ''irresponsible tourism'' a danger to heritage sites?','["Tourists often bring too much money.","Crowding, leaving litter, touching fragile objects, and building too many hotels can cause physical damage and ruin the site''s environment.","Tourists usually fix the monuments.","Tourism makes the sites invisible."]',1,'Millions of hands touching an old stone carving will wear it away completely!','Irresponsible tourism: Crowding, litter, touching fragile objects, and uncontrolled development can cause harm.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_027','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why must ''climate change'' be considered a major modern threat to heritage?','["It makes the monuments too clean.","Rising sea levels, severe floods, droughts, and extreme weather can permanently submerge or erode ancient coastal sites and fragile structures.","It causes monuments to grow larger.","Climate change only affects modern cities."]',1,'An ancient coastal fort cannot survive if the ocean rises and swallows it.','Climate change: Rising seas, floods, droughts, and extreme weather threaten many heritage sites.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_028','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'What was the purpose of the ''World Heritage Convention of 1972''?','["To sell ancient artifacts to the highest bidder.","To establish a framework for international cooperation to identify, protect, and preserve cultural and natural heritage of outstanding universal value.","To destroy old buildings to make room for new ones.","To force everyone to speak one language."]',1,'It was a global agreement to protect the most important places on Earth.','The World Heritage Convention of 1972 established a framework for international cooperation to identify and protect cultural and natural heritage...','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_029','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is it important to ask permission before recording or sharing culturally sensitive knowledge?','["Because cameras are illegal.","Because some cultural objects, stories, and traditions are sacred or restricted, and preservation must respect the rights and wishes of the communities they belong to.","Because recording makes the stories disappear.","Because you must pay a fine to the government."]',1,'You must respect that some traditions are private or holy to a specific group of people.','Ask permission before recording or sharing culturally sensitive knowledge... Important: Some cultural objects and traditions are sacred or restricted. Preservation should respect the wishes, rights...','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_030','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'How does ''looting and illegal trade'' harm archaeological research?','["It helps archaeologists find things faster.","When artifacts are stolen, they are removed from their original location (their context), which permanently destroys the historical information about how and where they were used.","It makes the artifacts shiny.","It has no effect on research."]',1,'A stolen coin in a private collection tells us nothing about the ancient market where it was dropped!','Looting and illegal trade: Artifacts may be stolen, removing them from their original context.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_031','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is it said that preserving heritage does NOT mean cultures must remain unchanged?','["Because cultures are forced to change every day.","Living heritage (like music and festivals) is dynamic; traditions naturally evolve and adapt to new circumstances while still maintaining their community identity.","Because all traditions must be exactly the same as 1000 years ago.","Because heritage only applies to dead cultures."]',1,'A traditional dance might be performed to new music, but it is still part of the culture!','Traditions may also change over time as people adapt them to new circumstances. Preserving heritage does not mean that cultures must remain unchanged.','2026-11-01 10:03:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_032','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'What can historians learn from studying a site like Great Zimbabwe?','["That stone buildings cannot survive in Africa.","It provides physical evidence of a highly organized, powerful African society with skilled construction, vast trade networks, and complex political organization.","That the site was built entirely by Europeans.","That they had no government."]',1,'The massive stone walls prove they had brilliant engineers and strong leaders.','Great Zimbabwe was a major stone-built settlement associated with a powerful African society... It provides evidence of skilled construction, trade, and political organization in southern Africa.','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_033','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'How do traditional crafts (like pottery or weaving) act as a form of ''intangible'' heritage?','["The clay pot itself is intangible.","While the finished pot is a tangible object, the actual *knowledge, skill, and technique* used to make it are intangible and must be passed down through practice and teaching.","Crafts are entirely natural heritage.","Crafts are not considered heritage at all."]',1,'The skill in the potter''s hands is intangible; the pot is tangible!','Intangible cultural heritage: These are living traditions, knowledge, and skills passed from one generation to another... Traditional crafts, food preparation, and skills.','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_034','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'Why is the preservation of Aboriginal Australian cultural heritage (like rock art) specifically important?','["It is the only art in the world.","These landscapes and art forms preserve ancient knowledge, spiritual connections, and deep historical continuity for Indigenous communities over many thousands of years.","Because it was painted yesterday.","Because it is used to build modern houses."]',1,'It is one of the oldest continuous living cultures on Earth.','Aboriginal peoples have maintained diverse cultures... Rock art and culturally significant landscapes can preserve knowledge and connections between generations.','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_035','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',5,'How can ''war and conflict'' devastate a nation''s cultural heritage?','["It makes monuments stronger.","During wars, monuments, museums, and cultural sites are often severely damaged by bombs or deliberately destroyed to erase a community''s historical identity.","It only damages modern buildings.","It turns monuments into natural heritage."]',1,'Destroying a culture''s history is sometimes used as a weapon in war.','War and conflict: Monuments, museums, and cultural sites can be damaged or deliberately destroyed.','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_036','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Critique the conceptual division between ''tangible'' and ''intangible'' heritage.','["They are completely unrelated and never interact.","The division is a useful classification, but in reality, they are inextricably linked; a tangible monument (like a temple) loses its profound cultural meaning without the intangible heritage (rituals, beliefs, language) that animates it.","Tangible heritage is always more important than intangible heritage.","Intangible heritage cannot exist without tangible heritage."]',1,'A beautiful violin (tangible) is useless without the skill to play it (intangible)!','Intangible cultural heritage: These are living traditions, knowledge, and skills... Tangible cultural heritage: These are physical objects and places... (Synthesis: The building houses the tradition).','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_037','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Evaluate the complex role of UNESCO''s ''World Heritage'' designation in relation to national sovereignty.','["UNESCO assumes absolute dictatorial ownership of all designated sites.","While UNESCO confers international recognition and provides conservation frameworks, it does not abrogate national sovereignty; the host nation retains absolute legal ownership and the primary financial/administrative burden of protecting the site.","UNESCO designation means the site must be destroyed.","UNESCO forces countries to sell the sites to private buyers."]',1,'UNESCO gives the badge of honor, but the country has to do the hard work of protecting it.','Being listed as a World Heritage Site does not mean that UNESCO owns the place. The country where the site is located has primary responsibility for its protection...','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_038','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Analyze how the architectural design of ''Petra'' reflects its historical geopolitical function.','["It was built randomly with no function.","Carved directly into protective rock gorges, Petra''s architecture reflects its function as a highly defensible, wealthy nexus for vital desert trade routes, showcasing the Nabataeans'' commercial power and hydraulic engineering.","It was built entirely out of wood in a dense forest.","It was a floating city on the ocean."]',1,'It was a fortress and a wealthy market built right into the cliffs!','Petra was an important city of the Nabataeans. Its rock-cut buildings and location along trade routes show the architectural skills and commercial connections...','2026-11-01 10:03:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_039','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Synthesize how ''irresponsible tourism'' creates a paradox for heritage conservation.','["Tourism always completely destroys the site immediately.","Tourism generates essential revenue needed to fund conservation efforts, but the physical mass of visitors concurrently accelerates the degradation of the site (erosion, moisture, infrastructure strain), forcing a delicate balance between public access and preservation.","Tourism has no effect on heritage sites.","Conservation does not require any funding."]',1,'The money from selling tickets pays to fix the stairs that get worn down by the people buying the tickets!','Irresponsible tourism: Crowding, litter, touching fragile objects, and uncontrolled development can cause harm. (Synthesis: Tourism brings money to fix the site, but causes the damage that needs fixing).','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_040','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Evaluate the historiographical significance of ''Great Zimbabwe'' in countering colonial narratives.','["It proved that colonial narratives were entirely correct.","The monumental stone architecture and complex urban organization of Great Zimbabwe provided undeniable archaeological proof that highly sophisticated, centralized, indigenous civilizations flourished in sub-Saharan Africa, directly refuting racist colonial assertions to the contrary.","It proved that stone could not be used in Africa.","It showed that trade did not exist before the 20th century."]',1,'For a long time, colonialists refused to believe Africans built it, but archaeology proved them wrong!','Great Zimbabwe was a major stone-built settlement associated with a powerful African society... It provides evidence of skilled construction, trade, and political organization in southern Africa.','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_041','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Analyze the threat of ''loss of traditions'' (intangible heritage) in the context of globalized modernization.','["Modernization instantly preserves all traditions perfectly.","As globalization and modern media homogenize cultures, younger generations may abandon indigenous languages, oral histories, and traditional skills for globalized economic opportunities, leading to the irreversible extinction of unique cultural worldviews.","Traditions can never be lost.","Modernization forces people to only speak ancient languages."]',1,'If the grandparents die and the children never learned the language, it is gone forever.','Loss of traditions: Languages and skills may disappear when fewer people learn or use them.','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_042','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'How does the ''looting'' of an archaeological site destroy its epistemological value?','["Looting makes the artifact easier to study.","An artifact''s historical value is primarily derived from its spatial ''context'' (its stratigraphic layer and proximity to other objects); looting violently extracts the object, permanently destroying the contextual data required for scientific historical reconstruction.","Looting ensures the artifact is kept safe in a museum.","Looting only damages natural heritage, not cultural."]',1,'A sword found next to a king tells a story; a stolen sword sold on the internet tells us nothing.','Looting and illegal trade: Artifacts may be stolen, removing them from their original context.','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_043','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Synthesize the relationship between ''living heritage'' and ''community identity''.','["Living heritage destroys community identity.","Intangible practices (festivals, dialects, culinary traditions) serve as the social glue that binds a community together across time. They provide a shared historical narrative and a distinct, collective identity in an increasingly homogenized world.","Living heritage prevents communities from evolving.","Community identity is only based on modern technology."]',1,'Celebrating the same festival your ancestors did connects you to your past and your neighbors.','Living heritage can strengthen community identity and preserve valuable knowledge. Traditions may also change over time as people adapt them...','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_044','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Evaluate the ethical complexities of ''conservation'' regarding culturally sensitive or sacred Indigenous sites.','["Conservation should always prioritize tourism over Indigenous wishes.","Conservation cannot be a purely objective scientific process; it must navigate the ethical imperative of respecting Indigenous sovereignty, acknowledging that some sacred sites or knowledge may require restricted access rather than public exhibition.","Conservation means destroying the site to build a museum.","Indigenous people have no say in conservation."]',1,'Just because a site is historically important doesn''t mean everyone has the right to walk all over it if it is sacred ground.','Important: Some cultural objects and traditions are sacred or restricted. Preservation should respect the wishes, rights, and knowledge of the communities to which they belong.','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_045','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Critique the notion that ''natural heritage'' (like a forest) and ''cultural heritage'' (like a temple) are entirely separate concepts.','["They are completely unrelated and governed by different laws of physics.","This is a false dichotomy; humans have co-evolved with their environments. Many ''natural'' landscapes are actually culturally managed ecosystems (e.g., Indigenous burning practices), and natural features are deeply imbued with cultural and spiritual significance.","Natural heritage only exists in space.","Cultural heritage can only exist in modern cities."]',1,'A mountain isn''t just a rock; to the people living below it, it might be a sacred god or the center of their culture!','Remember: A place can have both cultural and natural significance. Some landscapes are also deeply important to Indigenous peoples and local communities because of their histories...','2026-11-01 10:03:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_046','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Analyze how the construction of ''Angkor Wat'' reflects the intersection of political power and religious ideology.','["It was built purely as a modern shopping center.","The massive scale, intricate cosmology mapped into its architecture, and vast resources required to build Angkor Wat served to simultaneously legitimize the Khmer Emperor''s absolute political power by visually intertwining it with divine religious authority.","It proved that the Khmer Empire had no religion.","It was built entirely by accident."]',1,'Kings built massive temples to show both how rich they were and how close to the gods they were!','Angkor Wat is a major temple complex built during the Khmer Empire. Its architecture and carvings provide insights into religious beliefs... and the achievements of Khmer society... How religious beliefs and political power shaped buildings.','2026-11-01 10:03:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_047','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Evaluate the impact of ''climate change'' on the preservation of tangible cultural heritage.','["Climate change improves the structural integrity of ancient stones.","Rising sea levels, increased soil salinity, and extreme weather events physically erode and destabilize coastal and fragile archaeological sites at an accelerated, unprecedented rate, outpacing traditional conservation methods.","Climate change only affects intangible heritage like songs.","Climate change has no physical impact on stone or wood."]',1,'A 2,000-year-old coastal ruin might survive a war, but it can''t survive being permanently underwater.','Climate change: Rising seas, floods, droughts, and extreme weather threaten many heritage sites.','2026-11-01 10:03:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_048','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Synthesize how the concept of ''heritage'' acts as a mechanism for intergenerational transmission of values.','["Heritage is only used to make money from tourists.","Heritage (both tangible and intangible) functions as an educational conduit; by preserving languages, monuments, and rituals, a society physically and culturally transmits its core values, historical memory, and survival knowledge to subsequent generations.","Heritage prevents young people from learning.","Heritage is strictly about studying dead languages."]',1,'It is the bridge of knowledge between the ancestors and the grandchildren.','Heritage refers to things inherited from the past that people value and pass on to future generations... Languages carry stories, knowledge, humour, and ways of understanding the world.','2026-11-01 10:03:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_049','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Analyze the tension between ''urban development'' and ''archaeological preservation'' in rapidly growing modern cities.','["Cities always build around archaeological sites perfectly.","As modern populations expand, the economic imperative to build new infrastructure (subways, high-rises) frequently collides with the historical imperative to preserve the buried archaeological strata beneath the city, requiring complex legal and ethical compromises.","Urban development never threatens heritage.","Archaeological preservation is illegal in modern cities."]',1,'When building a new subway in an ancient city like Rome, engineers constantly have to stop digging because they keep hitting ancient temples!','Urban development: Roads, buildings, and other construction may destroy historic places.','2026-11-01 10:03:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_heritage_global_050','History','Basic History','Topic 14: Heritage, Culture, and Monuments','Primary',10,'Critique the idea that ''heritage'' must remain entirely static and unchanged to be authentic.','["Authentic heritage must be frozen in time forever.","This is a fallacy; ''living heritage'' (like traditional music or cuisine) is inherently dynamic. Authenticity involves continuous, organic adaptation by the community to new materials and contexts, proving the culture is alive rather than a static museum piece.","Heritage only counts if it is exactly 1,000 years old.","Cultures must change completely every year to survive."]',1,'Playing a traditional folk song on a modern electric guitar is still cultural heritage!','Living heritage can strengthen community identity... Traditions may also change over time as people adapt them to new circumstances. Preserving heritage does not mean that cultures must remain unchanged.','2026-11-01 10:03:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_001','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''local history'' study?','["The history of the entire planet at once","The past of a particular place, such as a village, town, or neighborhood","Only the history of kings and queens","The history of outer space"]',1,'It focuses on the area right around where you live.','Local history is the study of the past of a particular place, such as a village, town, city, neighbourhood...','2026-11-01 10:03:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_002','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''national history'' examine?','["The history of a single small village","The development of a country over time","The history of the solar system","Only the history of trade routes"]',1,'It looks at how a whole nation grew and changed.','National history examines the development of a country over time.','2026-11-01 10:03:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_003','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''world history'' study?','["Only the history of one country","Events, societies, and connections across different parts of the world","Only the history of the ocean","The history of a single family"]',1,'It looks at the big picture of how the whole world interacts.','World history studies events, societies, and connections across different parts of the world.','2026-11-01 10:03:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_004','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'Which of these is a good source for studying local history?','["A science fiction movie","Old photographs, letters, maps, and public records","A modern comic book","A weather forecast for tomorrow"]',1,'These are primary sources from the past.','Historians can study: Old photographs, letters, maps, newspapers, and public records.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_005','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''independence'' mean for a country?','["Being controlled by a foreign king","Freedom from another country''s political control","When a country stops trading with everyone","When a country builds a new capital city"]',1,'It means the country rules itself.','Independence: Freedom from another country''s political control.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_006','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'When did the United States declare independence from Britain?','["1492","1776","1947","1994"]',1,'This created a new country in North America.','Thirteen British colonies declared independence in 1776.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_007','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'When did India become independent from British rule?','["1776","1914","1947","1957"]',2,'This event also led to the creation of Pakistan.','India became independent from British rule on 15 August 1947.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_008','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'Which country became the first sub-Saharan African nation to gain independence from European colonial rule in 1957?','["South Africa","Egypt","Ghana","Kenya"]',2,'It inspired many other African nations to seek freedom.','Ghana became independent from British colonial rule on 6 March 1957.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_009','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What major event happened in South Africa in 1994?','["The start of the First World War","The country held its first fully representative national democratic election","The invention of the internet","The first moon landing"]',1,'This marked the end of the apartheid system.','In 1994, South Africa held its first fully representative national democratic election.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_010','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What were the ''Silk Roads''?','["A modern highway in Europe","Trade routes that connected parts of Asia, Europe, and Africa","A river in South America","A type of clothing factory"]',1,'Merchants used them to travel and trade across continents.','The Silk Roads connected parts of Asia, Europe, and Africa through networks of trade.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_011','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What is ''citizenship''?','["A type of boat","Membership in a political community, with associated rights and responsibilities","A historical monument","The study of old rocks"]',1,'It means being an official part of a country.','Citizenship: Membership in a political community, with associated rights and responsibilities.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_012','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''migration'' mean?','["Staying in one house forever","The movement of people from one place to another to live","Building a new road","Studying the stars"]',1,'People migrate to find new homes, jobs, or safety.','Migration: The movement of people from one place to another to live.','2026-11-01 10:03:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_013','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What is ''cultural exchange''?','["Refusing to talk to foreigners","The sharing of ideas, customs, knowledge, and practices between communities","A type of modern bank","Destroying old monuments"]',1,'It''s how people learn new things from each other.','Cultural exchange: The sharing of ideas, customs, knowledge, and practices between communities.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_014','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does the United Nations do?','["It prints money for all countries.","It brings countries together to discuss peace, human rights, and global challenges.","It forces all countries to have the same laws.","It is a museum for ancient history."]',1,'It is a place for global cooperation.','Organizations such as the United Nations bring countries together to discuss peace, human rights, development, health, and environmental challenges.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_015','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'How did ''industrialization'' change the world?','["It made everyone go back to farming.","It changed manufacturing, employment, transport, and urban life using machines.","It stopped all trade between countries.","It made travel much slower."]',1,'Factories and machines replaced hand-tools.','Industrialization: Changed manufacturing, employment, transport, and urban life.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_016','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What is ''historical evidence''?','["A fictional story","Information used to investigate and understand the past","A guess about the future","A modern video game"]',1,'It is the proof historians use to write history.','Historical evidence: Information used to investigate and understand the past.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_017','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What does ''colonialism'' mean?','["Free trade between equal countries","Control of a territory or people by an outside power","A peaceful democratic election","A type of local festival"]',1,'It usually involves one country taking over another''s land and resources.','Colonialism: Control of a territory or people by an outside power.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_018','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'Which of these is a way you can protect your local heritage?','["Writing on historic walls","Following conservation rules and respecting historic buildings","Taking artifacts home with you","Ignoring older community members"]',1,'You should leave historic places exactly as you found them.','Protect historic buildings, natural places, and cultural traditions... Respect historic places.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_019','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What did the development of agriculture help people do?','["It forced them to move every day.","It supported settled communities and food production systems.","It caused them to stop trading.","It made them forget how to build houses."]',1,'Growing crops means you have to stay in one place to harvest them.','Development of agriculture: Supported settled communities and food production systems.','2026-11-01 10:03:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_020','History','Basic History','Topic 15: Local History and the Modern World','Primary',1,'What is ''globalization''?','["Isolating a country from the rest of the world","The increasing connections among countries through trade, communication, and travel","A type of ancient government","A local farming technique"]',1,'It means the world is becoming more connected.','Globalization: The increasing connections among countries and communities through trade, communication, travel, and other processes.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_021','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why is ''local history'' important even if the events aren''t famous worldwide?','["Because it is the only history that is true.","Because it helps us understand the specific, everyday details of how our own communities, schools, and neighborhoods developed and changed over time.","Because local history is always older than world history.","Because it prevents us from learning about other countries."]',1,'The history of your own street is just as real as the history of a king!','Local history helps us understand how people lived in the past... It explores how people lived, worked, travelled, celebrated, and interacted with their environment.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_022','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How are ''local'', ''national'', and ''world'' history connected?','["They are completely separate and never interact.","Local events shape national history, and a nation''s development is heavily influenced by world history (like global trade or migration), meaning all three shape the modern world together.","World history only happens in the ocean, while local history happens on land.","They all study the exact same events in the exact same way."]',1,'Your town is part of a country, and your country is part of the world!','National history explains how a country developed, while world history shows how countries and communities influenced one another. By studying all three, we can understand how the past has shaped the modern world.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_023','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why must historians be careful when using ''oral histories'' (spoken memories) to study local history?','["Because people in the past could not speak.","Because human memories can differ or fade over time, so historians must compare several oral accounts with other evidence to build a reliable understanding.","Because oral histories are always 100% false.","Because it is illegal to record someone talking."]',1,'Two people might remember the exact same event very differently!','Oral accounts are valuable, but memories can differ. Comparing several sources helps historians build a more reliable understanding.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_024','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How can the opening of a ''railway station'' drastically change a local village''s history?','["It causes the village to physically move.","It connects the village to distant markets, changing local employment, bringing in new goods, and transforming it from an isolated farming community into a busy trade hub.","It forces everyone to stop farming immediately.","It has no effect on the local village at all."]',1,'A train brings the outside world right to the village''s doorstep.','The opening of a railway station may have helped people travel farther, transport goods, find employment, and connect with other towns.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_025','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why is it important to recognize that ''people within the same country may have different historical experiences''?','["Because some people do not live in the country.","Because national events (like a war or a new law) can affect different social, racial, or economic groups in drastically different—sometimes harmful—ways.","Because everyone experiences history exactly the same.","Because countries change their names every year."]',1,'A new law might help a rich factory owner but hurt a poor worker.','National history is different in every country, and people within the same country may have different historical experiences... A country''s history should include the experiences of different communities, not only those of rulers...','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_026','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How did the 1957 independence of Ghana influence world history?','["It caused the United Nations to collapse.","As the first sub-Saharan African country to gain independence post-WWII, it served as a powerful inspiration and catalyst for anti-colonial movements across the rest of the continent.","It proved that colonialism was the best system of government.","It was the event that started the Industrial Revolution."]',1,'When one nation breaks free, it inspires others to fight for their freedom too.','Its independence became an important inspiration for anti-colonial movements across Africa.','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_027','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'What was the significance of the 1994 election in South Africa?','["It was the year South Africa was colonized.","It marked the official end of the racist apartheid system, establishing the country''s first fully representative democracy where all citizens, regardless of race, could vote.","It was the year they invented the internet.","It was a local election for a small village mayor."]',1,'It was the victory of equality over segregation.','In 1994, South Africa held its first fully representative national democratic election. This marked a major turning point after decades of apartheid...','2026-11-01 10:03:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_028','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why is the statement ''No country developed entirely in isolation'' central to world history?','["Because all countries are actually the same country.","Because for thousands of years, societies have been deeply connected and transformed by global trade, migration, scientific exchange, and conflict.","Because countries are physically attached to each other.","Because every country was created at the exact same time."]',1,'Even ancient empires relied on ideas and goods from far away!','No country developed entirely in isolation. Trade, migration, exploration, scientific exchange, conflict, and cooperation have connected societies for thousands of years.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_029','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How did ''ocean travel'' in places like the Indian Ocean drive cultural exchange?','["It made people afraid of the water.","Ports became massive centers of commerce where merchants from Africa, the Middle East, and Asia met, traded goods, and shared their distinct languages, religions, and technologies.","It stopped all trade completely.","It was only used for fishing."]',1,'A busy port is a melting pot of different cultures!','Indian Ocean trade linked East Africa, the Middle East, South Asia... Ports became centres of commerce and cultural interaction.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_030','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How does ''scientific cooperation'' across borders benefit the modern world?','["It ensures that no new medicines are ever discovered.","Advances in medicine, astronomy, and technology happen much faster when researchers globally share their discoveries and build upon each other''s knowledge.","It forces scientists to compete in physical battles.","It only helps countries that are already rich."]',1,'A cure for a disease found in one country can save lives all over the world.','Scientists and researchers exchange discoveries across borders. Advances in medicine... often build on knowledge developed by people from many countries and cultures.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_031','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'What does it mean to be a ''responsible citizen'' when learning history?','["It means never questioning what you read.","It means respecting cultural diversity, protecting local heritage, comparing different sources for the truth, and participating positively in your community.","It means only caring about the history of your own town.","It means hiding historical evidence."]',1,'Good citizens use history to make the future better.','How can learners contribute? Respect people from different cultural and linguistic backgrounds... Compare historical sources... Participate in community activities...','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_032','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why is it necessary to ask ''who benefited, who was harmed, and why'' when studying major historical changes like Industrialization?','["Because all historical changes are 100% positive.","Because major developments (like factories) often bring incredible progress and wealth for some, while simultaneously causing severe exploitation, pollution, or suffering for others.","Because historians like to be negative.","Because historical changes never affect real people."]',1,'A new factory might make the owner rich, but the workers might suffer in dangerous conditions.','For example, industrialization increased the production of many goods... It also contributed to pollution, difficult working conditions... Understanding history requires asking not only what changed, but also who benefited, who was harmed, and why.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_033','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'How did ''digital communication'' change the modern world?','["It made it impossible to talk to people in other countries.","It made it incredibly easy to share information, communicate worldwide instantly, and connect global economies, fundamentally changing education and business.","It forced people to only write physical letters.","It stopped all scientific research."]',1,'You can now video call someone on the other side of the planet instantly!','Digital communication: Made it easier to share information and communicate worldwide.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_034','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'Why do human rights movements matter in national history?','["They ensure that kings keep all their power.","They actively challenge systemic discrimination, pushing governments to enact legal and social reforms that secure freedom and equality for marginalized citizens.","They prevent countries from trading with each other.","They only focus on building monuments."]',1,'These movements fight to make sure everyone is treated fairly under the law.','Human rights movements: Challenged discrimination and encouraged legal and social reforms.','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_035','History','Basic History','Topic 15: Local History and the Modern World','Primary',5,'What should you do before recording an interview with a community elder for a local history project?','["Secretly hide a microphone.","Ask for their explicit permission and ensure they are comfortable sharing their memories.","Tell them what to say.","Pay them a large amount of money."]',1,'You must always respect the privacy and wishes of the people you are interviewing.','Use reliable sources, ask permission before recording interviews or taking photographs where required...','2026-11-01 10:03:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_036','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Critique the historiographical tendency to study ''national history'' in isolation from ''world history''.','["National history is the only history that exists.","Studying a nation in a vacuum creates a distorted, exceptionalist narrative; a nation''s internal development (its borders, economy, and culture) is inextricably linked to global forces like transnational migration, imperialism, and macroeconomic trade networks.","World history has no impact on national laws.","National history always contradicts world history."]',1,'A country''s history is just one chapter in the book of world history!','No country developed entirely in isolation. Trade, migration, exploration, scientific exchange, conflict, and cooperation have connected societies for thousands of years... world history shows how countries and communities influenced one another.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_037','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Analyze the inherent contradiction within the American Declaration of Independence regarding the concept of ''citizenship''.','["It granted immediate citizenship to every person on Earth.","While the document championed revolutionary Enlightenment ideals of universal political rights and representation, it was hypocritically authored by a society that concurrently institutionalized chattel slavery and explicitly excluded women and indigenous peoples from the social contract.","It was a perfect document with no historical contradictions.","It banned the concept of citizenship entirely."]',1,'They wrote ''all men are created equal'' while legally denying equality to millions.','The new country developed institutions influenced by ideas about representation and political rights, although slavery and unequal rights persisted for many people.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_038','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Evaluate the dualistic impact of ''Global Trade'' and ''Colonialism'' on the modern world.','["They both resulted in perfect global equality and peace.","While global trade interconnected markets and facilitated rapid technological exchange, it was historically weaponized through colonialism, leading to the systemic exploitation of indigenous resources, coercive labor practices, and deep-seated structural inequalities that persist today.","Colonialism was completely peaceful and trade was completely violent.","Neither had any lasting impact beyond the 19th century."]',1,'The same trade routes that brought new medicines also brought colonial armies.','Global trade has made products and ideas more widely available, but trade and empire-building have also involved exploitation and unequal relationships.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_039','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Synthesize how the concept of ''Historical Evidence'' is complicated when relying on ''Oral Histories'' for local history projects.','["Oral histories are always factually perfect.","While oral histories democratize history by capturing marginalized, lived experiences omitted from official records, human memory is reconstructive and subjective; historians must rigorously cross-reference these accounts with tangible primary sources to mitigate bias and establish objective veracity.","Oral histories should never be used by serious historians.","Historical evidence is entirely fictional anyway."]',1,'A grandfather''s memory of a flood is a great story, but you need the old newspaper to confirm the exact date!','Oral histories from older residents... Oral accounts are valuable, but memories can differ. Comparing several sources helps historians build a more reliable understanding... distinguish confirmed facts from personal memories.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_040','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Analyze the function of the United Nations (UN) as an institutional manifestation of ''World History''.','["The UN is a single world government that controls all laws.","The UN represents a post-WWII structural attempt to institutionalize global interconnectedness, providing a diplomatic forum to mediate the inevitable conflicts arising from a deeply integrated world, focusing on collective security, human rights, and transnational environmental challenges.","The UN was created to start global conflicts.","The UN only focuses on local village history."]',1,'It''s the world''s attempt to solve global problems together instead of fighting over them.','Organizations such as the United Nations bring countries together to discuss peace, human rights, development, health, and environmental challenges.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_041','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Evaluate how ''Industrialization'' catalyzed urbanization and fundamentally restructured local community dynamics.','["It caused people to abandon cities and return to farming.","Industrialization centralized manufacturing into urban factories, sparking massive rural-to-urban migration. This dissolved traditional, agrarian kinship networks and created dense, diverse, but often highly stratified and polluted urban centers, permanently altering local daily life.","It had no effect on where people lived.","It meant that everyone worked from their own homes."]',1,'Factories needed thousands of workers, so small villages emptied out as people moved to the big, dirty cities for jobs.','Industrialization: Changed manufacturing, employment, transport, and urban life... It also contributed to pollution, difficult working conditions, and rapid urban growth.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_042','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Synthesize the relationship between ''anti-colonial independence movements'' (like in India or Ghana) and the broader trajectory of 20th-century ''human rights''.','["Independence movements opposed human rights.","Anti-colonial movements were not just political rebellions; they were foundational human rights struggles that dismantled racist imperial hierarchies, popularized the concept of national self-determination, and pressured the global community into formalizing universal equality frameworks.","Human rights were only invented in the 21st century.","Independence movements only happened in Europe."]',1,'Fighting for a country''s freedom was also a fight for the basic human dignity of its people!','India became independent... Ghana became independent... inspiring anti-colonial movements... Human rights movements: Challenged discrimination and encouraged legal and social reforms.','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_043','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Analyze the epistemological value of studying ''local history'' (e.g., an old market or railway station) in combating historical macro-narratives.','["Local history proves that global events never happen.","Macro-narratives (national/world history) often flatten the past into abstract trends. Local history grounds historical inquiry in tangible, micro-level human experiences, demonstrating exactly *how* massive phenomena (like the Industrial Revolution) physically altered the spatial and economic reality of ordinary citizens.","Local history is only useful for finding buried treasure.","Macro-narratives are the only valid way to study history."]',1,'Reading about the invention of trains is good; reading about how the first train changed *your* town makes history real!','Local history... explores how people lived, worked... How an old market became a busy commercial centre. How a railway station changed transport...','2026-11-01 10:03:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_044','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Critique the concept of ''citizenship'' as merely a legal status within a nation-state.','["Citizenship is only a piece of paper and has no real meaning.","While legally defining national membership, robust citizenship is actively performative; it demands critical engagement with the state''s history, respectful participation in a diverse civic sphere, and the ethical responsibility to hold institutions accountable for public welfare.","Citizenship means you are never allowed to question the government.","Citizenship is only applicable to people who study history."]',1,'Being a citizen isn''t just about having a passport; it''s about actively working to make your community better.','Citizenship involves membership in a political community and may include rights, responsibilities, and participation in public life... Learning history can help people become thoughtful, responsible members of society.','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_045','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'How does the study of ''migration'' across world history dismantle the concept of ''pure'' national identities?','["Migration proves that people never move.","Millennia of continuous transnational migration, forced displacement, and subsequent cultural exchange prove that all modern national identities are highly hybridized constructs, synthesized from the constant blending of diverse immigrant languages, technologies, and traditions.","Migration shows that countries only develop in complete isolation.","National identities are completely biological and never change."]',1,'Every culture is a mix of ideas and people who moved there from somewhere else!','National history helps people understand... How migration and cultural exchange shaped society. No country developed entirely in isolation. Trade, migration... have connected societies...','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_046','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Evaluate the ethical imperative of ''comparing historical sources'' when conducting a local history project.','["It is unethical because it insults the first person you interview.","Historical sources are inherently biased by the creator''s perspective, memory, or political agenda. Rigorously cross-referencing multiple primary sources is an ethical imperative to prevent the propagation of historical myths or the erasure of marginalized community voices.","Historians should only ever look at one single source to save time.","Comparing sources is illegal in most countries."]',1,'If you only read the Mayor''s diary, you will never know how the poor people in the town felt!','Oral accounts are valuable, but memories can differ. Comparing several sources helps historians build a more reliable understanding... Compare historical sources instead of accepting every claim without question.','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_047','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Synthesize how ''Advances in medicine'' function as both a product of and a catalyst for ''Globalization''.','["Medicine is only developed in isolated caves.","Medical breakthroughs (product) rely on the rapid, globalized exchange of scientific data and diverse biological research. Once deployed, these advances (catalyst) drastically increase global life expectancies and population density, further accelerating international economic and cultural integration.","Advances in medicine have no impact on the global economy.","Globalization prevents any new medicines from being discovered."]',1,'A global network of scientists working together can cure a disease that threatens the whole world!','Scientific cooperation: Scientists and researchers exchange discoveries across borders. Advances in medicine... often build on knowledge developed by people from many countries... Advances in medicine: Improved the prevention and treatment of many diseases.','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_048','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Analyze the statement ''A country''s history should include the experiences of different communities, not only those of rulers or political leaders'' through a historiographical lens.','["History is defined exclusively by the actions of monarchs.","This statement champions ''history from below'' (social history). It argues that a holistic, accurate historical narrative must integrate the socio-economic struggles, cultural contributions, and systemic subjugation of marginalized groups, rejecting the elitist focus on statecraft and warfare.","It means rulers should be completely erased from all history books.","It proves that different communities do not actually exist within a country."]',1,'A history book that only talks about Presidents is missing 99% of the real story!','A country''s history should include the experiences of different communities, not only those of rulers or political leaders.','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_049','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Evaluate the complex role of ''Trade Routes'' (like the Indian Ocean network) in shaping the political power dynamics of the modern world.','["Trade routes were purely economic and had no political impact.","While initiating as commercial ventures, control over lucrative maritime trade routes rapidly translated into immense geopolitical power, catalyzing the rise of naval empires, mercantilism, and ultimately, the violent European colonial domination of the Global South.","Trade routes forced all countries to become democracies.","The Indian Ocean network was entirely controlled by ancient Rome."]',1,'Whoever controls the trade routes controls the wealth, and wealth buys armies!','Indian Ocean trade linked East Africa, the Middle East, South Asia... These connections also changed over time and were sometimes shaped by unequal power and colonialism.','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_modern_global_050','History','Basic History','Topic 15: Local History and the Modern World','Primary',10,'Critique the assumption that ''digital communication'' universally empowers all global citizens equally.','["Digital communication is perfectly accessible to every human on Earth.","While it theoretically democratizes information access and accelerates global social movements, the ''digital divide'' (disparities in infrastructure, wealth, and censorship) means that digital communication often exacerbates existing socio-economic inequalities and amplifies coordinated misinformation.","Digital communication has completely eliminated all inequality.","Digital communication is only used for sending emails."]',1,'The internet is a powerful tool, but it''s useless if you live in a village with no electricity or money for a computer!','Digital communication: Made it easier to share information and communicate worldwide... (Synthesis: However, historical change has both benefits and challenges... asking not only what changed, but also who benefited, who was harmed...)','2026-11-01 10:03:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_001','History','Basic History','Topic 3: Sources of History','Primary',1,'What is a historical source?','["A place to buy food","An object or record that helps us learn about the past","A type of modern car","A prediction about the future"]',1,'It provides clues for historians.','A historical source is an object, record, image... that helps us learn about the past.','2026-11-01 10:38:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_002','History','Basic History','Topic 3: Sources of History','Primary',1,'Which of these is an example of a written source?','["A bone","A clay pot","A letter","A song"]',2,'It contains words or symbols on paper.','Written records: Letters, diaries, books...','2026-11-01 10:38:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_003','History','Basic History','Topic 3: Sources of History','Primary',1,'Which of these is an example of a material source (artefact)?','["A diary","An old coin","A song","A newspaper"]',1,'You can hold it in your hand.','Material sources are physical objects... They include: ... Coins and jewellery.','2026-11-01 10:38:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_004','History','Basic History','Topic 3: Sources of History','Primary',1,'Which of these is an example of a visual source?','["A spoken story","A photograph","A bone","A written law"]',1,'You look at it to see what things looked like.','Visual sources are images... They include: Photographs.','2026-11-01 10:38:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_005','History','Basic History','Topic 3: Sources of History','Primary',1,'Which of these is an example of an oral source?','["A map","An interview with an older person","A stone building","A clay pot"]',1,'It involves speaking and listening.','Oral sources include: Interviews with people who experienced an event.','2026-11-01 10:38:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_006','History','Basic History','Topic 3: Sources of History','Primary',1,'What is a diary?','["A record of personal experiences","A public building","An ancient tool","A map of the world"]',0,'People write their private thoughts in it.','Diary: A record of personal experiences and observations.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_007','History','Basic History','Topic 3: Sources of History','Primary',1,'What is a manuscript?','["A printed book","A handwritten document","A type of pottery","An old photograph"]',1,'Before computers and printers, people wrote whole books by hand!','A manuscript is a handwritten document or text.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_008','History','Basic History','Topic 3: Sources of History','Primary',1,'What do we call writing carved on a stone pillar or monument?','["A newspaper","A diary","An inscription","A map"]',2,'You often see these on statues or old graves.','An inscription is writing carved, engraved... on a durable surface... like stone pillars.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_009','History','Basic History','Topic 3: Sources of History','Primary',1,'What is an artefact?','["An object made or used by humans","A natural rock","A rain cloud","An animal in the wild"]',0,'A plain stick is just a stick, but a stick carved into a spear is an artefact!','An artefact is an object made, modified, or used by humans.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_010','History','Basic History','Topic 3: Sources of History','Primary',1,'What does an archaeologist study?','["The future","The stars","The past using material remains","Ocean currents"]',2,'They dig in the dirt to find clues!','Archaeology is the study of past human life through material remains...','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_011','History','Basic History','Topic 3: Sources of History','Primary',1,'Why are old photographs useful?','["They show the future.","They can record what buildings and clothing looked like.","They tell you what people were thinking.","They are always perfectly accurate."]',1,'It''s like looking through a window into the past.','An old photograph of a town may show: The types of buildings... The clothing people wore.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_012','History','Basic History','Topic 3: Sources of History','Primary',1,'Can an old song be a historical source?','["No, songs are just for fun.","Yes, if it describes historical events.","Only if it is written down.","No, music is not history."]',1,'People used to sing stories to remember them before writing was invented!','Oral sources include: ... Songs that describe historical events.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_013','History','Basic History','Topic 3: Sources of History','Primary',1,'Do historical sources tell us about people''s daily lives?','["Yes, they can reveal how people lived.","No, they only tell us about kings.","No, they only tell us about wars.","Only if they are from last year."]',0,'A cooking pot tells us what a normal person ate for dinner.','Historical sources help us: Learn about people''s daily lives.','2026-11-01 10:38:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_014','History','Basic History','Topic 3: Sources of History','Primary',1,'Should an archaeologist record exactly where an object was found?','["No, it doesn''t matter.","Yes, because the location provides important information.","Only if it is made of gold.","Only if it is very large."]',1,'Finding a tool in a kitchen means something different than finding it in a grave!','Removing an object without recording its location can destroy valuable historical information.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_015','History','Basic History','Topic 3: Sources of History','Primary',1,'What is one way to collect oral history?','["By digging in the ground.","By reading a newspaper.","By interviewing a community member.","By drawing a map."]',2,'You have to ask people questions and listen to their answers!','Oral history involves collecting and studying people''s spoken memories... often through recorded interviews.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_016','History','Basic History','Topic 3: Sources of History','Primary',1,'Does a single historical source always tell the whole story?','["Yes, always.","No, a single source may not tell the whole story.","Yes, if it is a photograph.","Yes, if it is a book."]',1,'A diary only tells one person''s side of the story!','Recognize that a single source may not tell the whole story.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_017','History','Basic History','Topic 3: Sources of History','Primary',1,'What is a historical map?','["A map drawn by a computer yesterday.","A map showing how people represented places at a particular time in the past.","A map that shows the future.","A photograph of the sky."]',1,'An old map might show countries that don''t exist anymore!','Historical maps show how people represented places at a particular time.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_018','History','Basic History','Topic 3: Sources of History','Primary',1,'What do we call the careful removal of soil to find artefacts?','["Farming","Excavation","Gardening","Painting"]',1,'Archaeologists do this very slowly with small tools.','Excavation: The careful removal and recording of soil or deposits at a site.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_019','History','Basic History','Topic 3: Sources of History','Primary',1,'Can a building be a historical source?','["No, it is too big.","Yes, it can reveal construction methods and how people lived.","Only if it is a castle.","No, buildings are not evidence."]',1,'The pyramids are giant historical sources!','Material sources... include: ... Buildings and walls. An ancient building may reveal information about construction methods.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_020','History','Basic History','Topic 3: Sources of History','Primary',1,'Why might historians study an old newspaper?','["To find out tomorrow''s weather.","To see what events were reported at the time.","To learn how to take a photograph.","To find an ancient coin."]',1,'It shows what was considered ''breaking news'' 100 years ago.','Old newspapers can reveal which events were reported and how journalists described them at the time.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_021','History','Basic History','Topic 3: Sources of History','Primary',1,'What should you do before recording an oral history interview with someone?','["Pay them money.","Ask for their permission.","Tell them the answers.","Write the story for them."]',1,'It is important to be polite and respectful.','Ask permission before recording someone.','2026-11-01 10:38:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_022','History','Basic History','Topic 3: Sources of History','Primary',1,'Can animal bones be a material source for historians?','["Yes","No","Only dinosaur bones","Only if they are alive"]',0,'Bones can tell scientists what people used to eat!','Material sources... include: ... Human and animal remains.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_023','History','Basic History','Topic 3: Sources of History','Primary',1,'What does it mean if a written record has ''bias''?','["It is written in a foreign language.","It presents information from a particular viewpoint, which might not be completely fair.","It is written very neatly.","It is very old."]',1,'If a king writes a book about himself, he might leave out the bad things he did!','Bias: A tendency to present information from a particular viewpoint.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_024','History','Basic History','Topic 3: Sources of History','Primary',1,'Which source would best tell you what a town looked like 100 years ago?','["An oral interview with a 10-year-old.","An old photograph of the town.","A modern map.","An ancient stone tool."]',1,'A picture is worth a thousand words!','An old photograph of a town may show: The types of buildings that existed...','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_025','History','Basic History','Topic 3: Sources of History','Primary',1,'Are historical sources only used to study ancient times thousands of years ago?','["Yes, only ancient times.","No, they can be used to study more recent periods too.","Only the time of the dinosaurs.","Yes, if it happened recently it isn''t history."]',1,'A video from 1990 is a historical source!','Some ancient written sources were created thousands of years ago, while others are relatively recent.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_026','History','Basic History','Topic 3: Sources of History','Primary',5,'Why must historians be careful when relying on a diary as a historical source?','["Because diaries are always written in secret code.","Because a diary only records one person''s perspective and personal feelings, and may not accurately describe what everyone else experienced.","Because diaries cannot survive for more than a year.","Because it is illegal to read old diaries."]',1,'If someone was angry when they wrote it, their story might be exaggerated!','However, a diary records one person''s perspective. It may not describe what everyone else experienced.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_027','History','Basic History','Topic 3: Sources of History','Primary',5,'How does ''stratigraphy'' help archaeologists?','["It helps them read old handwriting.","It is the study of layers of soil; deeper layers are usually older, helping archaeologists determine the sequence of when objects were buried.","It helps them take better photographs.","It allows them to interview dead people."]',1,'Think of the dirt like a layered cake; the bottom layer was baked (or buried) first!','Stratigraphy: The study of layers of soil and deposits.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_028','History','Basic History','Topic 3: Sources of History','Primary',5,'Why might two people give different oral history accounts of the exact same event?','["Because one is definitely lying.","Because human memory can be incomplete, and people naturally remember different details or interpret events differently based on their own perspective.","Because oral history is not allowed to be accurate.","Because they read different newspapers."]',1,'Ten people can watch a car crash and all tell the police a slightly different story!','Two people may remember the same event differently... Differences between accounts do not automatically mean that someone is deliberately lying.','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_029','History','Basic History','Topic 3: Sources of History','Primary',5,'What is a primary limitation of using a photograph as historical evidence?','["It always shows things in color.","It only captures what was within the frame at one specific moment in time; it cannot show what happened before or after the picture was taken.","It is always fake.","It can only be used by scientists."]',1,'A picture of someone smiling doesn''t tell you if they were crying five minutes earlier!','However, a photograph shows only what was captured within its frame. It may not reveal what happened before or after...','2026-11-01 10:38:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_030','History','Basic History','Topic 3: Sources of History','Primary',5,'Why is an ''official record'' (like a tax document) often considered a strong written source?','["Because it is always written in poetry.","It documents factual data required by a government or institution, providing concrete numbers about populations, laws, or land ownership.","Because it is always accompanied by a painting.","Because it only records people''s feelings."]',1,'It provides the hard facts and numbers that a personal diary might leave out.','Official records may document laws, taxes, population counts, land ownership...','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_031','History','Basic History','Topic 3: Sources of History','Primary',5,'What can archaeologists learn by finding seeds or plant remains in an ancient cooking pot?','["What kind of clothing the people wore.","They can learn what crops the community grew, traded, or ate, giving clues about their agriculture and diet.","Who the king was.","How the people built their houses."]',1,'If they find wheat seeds in the pot, they know the people knew how to farm wheat!','Material sources... include: ... Seeds, plant remains, and other traces of food.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_032','History','Basic History','Topic 3: Sources of History','Primary',5,'Why is it important to ask ''Why might it have been created?'' when looking at a historical painting?','["Because paintings are always cheap.","Because paintings are not photographs; artists may emphasize details, leave things out, or create the image to flatter a king, meaning it shouldn''t be treated as perfectly accurate.","Because the painter might still be alive.","Because paintings cannot survive for long."]',1,'A painting of a battle ordered by the winning king will probably make the king look much braver than he actually was!','Artists may emphasize certain details or leave others out. A painting should not automatically be treated as a perfectly accurate record.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_033','History','Basic History','Topic 3: Sources of History','Primary',5,'How does ''radiocarbon dating'' assist historians?','["It helps them predict the weather.","It is a scientific method used to estimate the age of suitable materials that were once alive (like wood, bones, or seeds).","It helps them find gold.","It translates ancient languages."]',1,'It is like a scientific clock hidden inside anything that used to be a living plant or animal!','Radiocarbon dating to estimate the age of suitable materials that were once alive.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_034','History','Basic History','Topic 3: Sources of History','Primary',5,'Why are oral traditions particularly valuable for studying certain communities?','["Because oral traditions are easier to write down.","They preserve the knowledge, memories, and experiences of people whose lives may not have been fully recorded in official written documents.","Because oral traditions never change.","Because they only include songs."]',1,'Not everyone in history knew how to read or write, so their history was spoken, not written!','Oral sources are especially important for understanding experiences that may not have been fully recorded in written documents.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_035','History','Basic History','Topic 3: Sources of History','Primary',5,'What might a historical map reveal besides geographic locations?','["What the mapmaker ate for lunch.","It can reveal political viewpoints, boundaries claimed by the mapmaker, and what areas of the world were known or unknown to that society at the time.","How to build a stone tool.","The exact words spoken in a battle."]',1,'If an old map leaves out an entire continent, it tells us the mapmaker didn''t know it existed!','Maps can contain mistakes, outdated information, or political viewpoints... [They show] Areas known or claimed by the mapmaker.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_036','History','Basic History','Topic 3: Sources of History','Primary',5,'If an archaeologist removes a tool from the ground without recording its exact location, what is lost?','["The tool itself.","The vital context; they lose the information about what soil layer it was in and what other objects were nearby, destroying part of its historical meaning.","The ability to photograph it.","Nothing is lost."]',1,'Finding a sword next to a skeleton tells a story. Finding a sword in a box in a museum tells you nothing about where it came from!','The location, surrounding objects, and soil layers help researchers understand how an object was used... Removing an object without recording its location can destroy valuable historical information.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_037','History','Basic History','Topic 3: Sources of History','Primary',5,'Why must historians combine different types of sources (like an object, a document, and a map) to understand an event?','["Because one source is usually too heavy to lift.","Because different sources reveal different aspects of the past; combining them helps cross-check the facts and build a more complete and reliable explanation.","Because it takes too much time to read just one source.","Because they have to fill up a museum."]',1,'A diary tells you how a soldier felt, a map tells you where he marched, and a found sword shows you what he fought with!','By combining evidence, they may develop a more complete explanation of the market''s history.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_038','History','Basic History','Topic 3: Sources of History','Primary',5,'What is a ''manuscript'' and why do historians have to be careful when reading copies of them?','["A manuscript is a metal coin; copies are often fake.","A manuscript is a handwritten document; because they were copied by hand before printing presses, historians must check if later scribes made mistakes or changed the original text.","A manuscript is a photograph; copies lose color.","A manuscript is a song; copies change the tune."]',1,'Imagine playing the game ''Telephone'' by copying a whole book by hand—mistakes will happen!','A manuscript is a handwritten document... Researchers must consider... whether later copies changed the original text.','2026-11-01 10:38:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_039','History','Basic History','Topic 3: Sources of History','Primary',5,'How can ''inscriptions'' help historians date an ancient monument?','["They hold the monument together.","Inscriptions (writing carved into the stone) often provide official names of rulers, dates of construction, or religious dedications that identify exactly when it was built.","They make the monument look nicer.","They hide the monument from enemies."]',1,'It''s like finding a giant stone nametag on a building!','Inscriptions... can provide names, dates, official announcements... or information about rulers...','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_040','History','Basic History','Topic 3: Sources of History','Primary',5,'If an old film shows a historical event, what limitation must the viewer keep in mind?','["Films cannot show people moving.","Editing, the camera''s specific position, narration, and any missing footage can manipulate what the viewer understands about the whole event.","Films do not exist from history.","Films only show fictional events."]',1,'A camera only records what it is pointed at; it misses everything happening behind the cameraman!','However, editing, camera position, narration, and missing footage can affect what viewers understand.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_041','History','Basic History','Topic 3: Sources of History','Primary',10,'Analyze the inherent tension between ''official records'' and ''oral history'' when studying marginalized communities.','["Official records are always spoken.","Official records often reflect the biases, interests, and administrative goals of the ruling authority, potentially ignoring or misrepresenting marginalized groups whose authentic experiences are only preserved through oral history.","Oral history is always written down by the government.","There is no tension; they always agree completely."]',1,'The government writes the tax records, but the people sing the songs about how hard the taxes were to pay.','Official records may document laws... [but] Some groups may have left fewer written records than others. Oral history... can preserve the voices of people whose experiences were not widely documented.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_042','History','Basic History','Topic 3: Sources of History','Primary',10,'How does the principle of ''stratigraphy'' provide a relative chronological framework for unwritten archaeological sources?','["It uses radiation to find exact years.","By analyzing the undisturbed layers of soil (strata), archaeologists can establish a relative timeline based on the Law of Superposition: deeper layers and the objects within them are older than the layers deposited above them.","It relies entirely on finding coins with dates on them.","It proves that all objects are the exact same age."]',1,'If you drop a coin in the mud in 1900, and someone drops a key in the mud above it in 2000, the coin must be older because it is buried deeper!','Stratigraphy: The study of layers of soil and deposits.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_043','History','Basic History','Topic 3: Sources of History','Primary',10,'Evaluate the epistemological difference between an ''observation'' of a material source and an ''interpretation/inference'' drawn from it.','["Observations are false; interpretations are true.","An observation is an undeniable empirical fact (e.g., ''the metal is rusted''); an interpretation is a reasoned but subjective hypothesis attempting to explain that fact (e.g., ''the tool was abandoned in water'').","They are identical processes.","Interpretations are physical objects; observations are thoughts."]',1,'Observation: The skull has a hole in it. Inference: The person was killed in battle. (The inference could be wrong; maybe they had surgery!).','Observation: Something that can be directly noticed. Inference: An explanation or conclusion drawn from observations... The inference is plausible, but further evidence would be needed...','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_044','History','Basic History','Topic 3: Sources of History','Primary',10,'Why is ''radiocarbon dating'' useless for estimating the age of an ancient bronze sword?','["Bronze is too heavy for the machine.","Radiocarbon dating measures the decay of carbon-14 isotopes, which are only present in organic materials that were once alive (like wood, bone, or cloth); bronze is an inorganic metal and contains no carbon-14.","Bronze is always too young to date.","Radiocarbon dating only works on written documents."]',1,'You can date the wooden handle of the sword, but you cannot date the metal blade!','Radiocarbon dating to estimate the age of suitable materials that were once alive.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_045','History','Basic History','Topic 3: Sources of History','Primary',10,'How might a historian use the concept of ''bias'' to evaluate a propaganda poster from a past war?','["By assuming the poster is perfectly accurate.","A historian would recognize the poster''s explicit purpose was to manipulate public opinion (bias), making it unreliable for factual details of the war, but highly valuable as evidence of how the government wanted citizens to feel.","By throwing the poster away.","By proving the poster was painted by accident."]',1,'The poster doesn''t tell you the truth about the enemy; it tells you the truth about what the government *wanted* you to think about the enemy!','Bias: A tendency to present information from a particular viewpoint... Visual sources... are most useful when their date, origin, purpose, and limitations are considered.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_046','History','Basic History','Topic 3: Sources of History','Primary',10,'Explain the ''crisis of memory'' inherent in utilizing oral history after a long passage of time.','["People speak different languages over time.","Human memory is highly malleable and reconstructive; over time, individuals may unintentionally alter details, conflate events, or adopt collective narratives as their own personal memories, requiring historians to corroborate their accounts.","Memories turn into physical objects.","Oral history is only valid if recorded on video."]',1,'Every time you tell a story, your brain slightly rewrites the memory!','Human memory can be incomplete... a story may change as it passes between generations. Historians consider... whether other evidence supports it.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_047','History','Basic History','Topic 3: Sources of History','Primary',10,'How do historical maps serve as tools of political power rather than just objective geographical records?','["Maps only show where treasure is buried.","Mapmakers often drew boundaries, claimed territories, or altered place names to legitimize an empire''s political control, intentionally erasing indigenous claims or exaggerating their own nation''s size and importance.","Maps were only used for sailing, not politics.","Maps are completely objective and never contain mistakes."]',1,'If an empire wants to claim a new land, they just draw a map showing that land belongs to them!','Maps can contain mistakes, outdated information, or political viewpoints. [They show] Areas known or claimed by the mapmaker.','2026-11-01 10:38:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_048','History','Basic History','Topic 3: Sources of History','Primary',10,'Synthesize: Why is the ''context'' of an archaeological find (its exact location and surrounding artifacts) often more scientifically valuable than the artifact itself?','["Because context can be sold for more money.","An isolated artifact is merely a curiosity; its context (association with hearths, burials, or other specific tools) provides the crucial behavioral and chronological data required to reconstruct the actual lives of the people who used it.","Because the artifact is usually fake.","Context is not valuable; only gold artifacts matter."]',1,'A gold ring in a jewelry box is just a ring. A gold ring found in the stomach of a fossilized fish is a historical mystery solved by context!','The location, surrounding objects, and soil layers help researchers understand how an object was used and when it was deposited.','2026-11-01 10:38:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_049','History','Basic History','Topic 3: Sources of History','Primary',10,'Critique the reliability of ''manuscripts'' as historical sources before the invention of the printing press.','["Manuscripts were printed by machines.","Because they were copied manually by scribes over centuries, they are highly susceptible to translation errors, accidental omissions, and deliberate ideological alterations, making it difficult to ascertain the ''original'' text.","They were always perfectly identical.","They were written in invisible ink."]',1,'If a monk didn''t like a paragraph in a book he was copying, he might just leave it out, changing history forever!','Before printing became widespread, many books were copied by hand... Researchers must consider... whether later copies changed the original text.','2026-11-01 10:38:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_src_050','History','Basic History','Topic 3: Sources of History','Primary',10,'How does ''chemical analysis'' of a clay pot complement the traditional visual ''observation'' of the pot?','["It makes the pot look nicer.","Observation identifies the pot''s shape and manufacturing style (typology); chemical analysis (like examining residues absorbed into the clay) reveals microscopic data about exactly what foods or liquids the pot originally contained.","It breaks the pot into smaller pieces.","It replaces the need for archaeologists."]',1,'You can look at the pot to see how it was made, but you need chemistry to prove they used it to cook ancient stew!','Chemical analysis to investigate the composition of objects or residues.','2026-11-01 10:38:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_001','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is the scientific name for modern humans?','["Homo habilis","Homo sapiens","Homo erectus","Neanderthal"]',1,'It means ''wise man''.','Modern humans, known scientifically as Homo sapiens...','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_002','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What does ''prehistory'' mean?','["The time after the invention of the internet","The human past before written records were used","The future of human history","The study of dinosaurs only"]',1,'It is the time before people wrote things down.','Prehistory is the period of the human past before written records were used in a particular society.','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_003','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'How did hunter-gatherers get their food?','["By shopping at markets","By hunting animals and gathering wild plants","By planting large farms of wheat","By eating only rocks and dirt"]',1,'The name tells you exactly what they did!','Hunter-gatherer: A person whose community obtains much of its food through hunting, fishing, and gathering.','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_004','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is a fossil?','["A new computer part","Preserved remains or traces of ancient life","A type of modern tool","A written book from the past"]',1,'Dinosaur bones are a famous example.','Fossil: Preserved remains or traces of ancient life.','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_005','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is a prehistoric tool?','["A modern electric drill","An object made or adapted to help people complete tasks in the past","A type of ancient food","A wild animal"]',1,'They were used to make life easier.','Early tools were objects made or adapted to help people complete tasks.','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_006','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Which of these materials was commonly used to make early tools?','["Plastic","Stone","Glass","Rubber"]',1,'It is hard and can be chipped to make a sharp edge.','Early humans... used materials available in their surroundings, including stone, wood, bone...','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_007','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is ''stone knapping''?','["Throwing stones in a river","Painting pictures on stones","Shaping stone by striking it to remove flakes","Building houses out of stone"]',2,'It''s how you make a sharp stone knife.','Stone knapping: Shaping stone by striking it to remove pieces.','2026-11-01 10:38:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_008','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Why was fire important for food?','["It froze the food","It allowed people to cook food, making it softer","It turned the food into stone","It made the food invisible"]',1,'It makes meat easier to chew!','Cooking food: Fire allowed people to cook many foods, making them softer and changing their flavour...','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_009','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'How did fire help early humans at night?','["It made them sleep instantly","It provided light so they could see","It turned night into day permanently","It made the stars disappear"]',1,'Before flashlights, this was the only way to see at night.','Light: Fire helped people see after dark.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_010','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is a ''hearth''?','["A type of tool","A type of wild animal","A place where a fire is maintained","A written record"]',2,'It is the fireplace in an ancient camp or home.','Hearth: A place where a fire is maintained.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_011','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Why did some hunter-gatherer communities move from place to place?','["Because they liked walking","To follow migrating animals and find fresh plant resources as seasons changed","Because their houses were on wheels","To run away from farmers"]',1,'If all the food in the forest is eaten, you have to move to a new forest!','Moving could allow people to reach different resources as plants grew, animals migrated, or weather changed.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_012','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What does ''gathering'' mean for early humans?','["Collecting naturally growing foods like fruits and nuts","Collecting rocks to build a wall","Hunting large animals with spears","Planting seeds in a farm"]',0,'It means picking things that grow wild in nature.','Gathering involves collecting naturally growing foods and useful materials, such as fruits, seeds, nuts...','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_013','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is ''farming''?','["Only hunting wild animals","Growing crops and raising animals for food","Moving constantly from place to place","Making tools out of stone"]',1,'It means you grow your own food instead of just finding it.','Farming involves growing crops and raising animals for food and other useful products.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_014','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is a ''crop''?','["A type of hunting spear","A plant grown for food or another useful purpose","A wild animal","A stone tool"]',1,'Wheat, corn, and rice are examples.','Crop: A plant grown for food or another useful purpose.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_015','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What does ''domestication'' mean?','["Hunting wild animals","Managing and selectively breeding plants or animals over generations","Making a fire","Moving to a new settlement"]',1,'It turns a wild wolf into a tame dog, or wild grass into farm wheat!','Domestication is a gradual process in which people manage and selectively breed plants over many generations.','2026-11-01 10:38:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_016','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Did farming allow people to establish permanent settlements?','["No, farming forced people to move more often.","Yes, farming could encourage people to remain near fields and stored food.","Farming had no effect on where people lived.","Only in the winter."]',1,'If you plant a field, you have to stay there to harvest it!','Farming could encourage people to remain near fields, stored food, and domesticated animals.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_017','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is a ''settlement''?','["A hunting trip","A place where people live","A type of fire","A stone tool"]',1,'A village is an example of a settlement.','Settlement: A place where people live.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_018','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Did farming start everywhere in the world at the exact same time?','["Yes, on the exact same day.","No, it developed independently in different parts of the world at different times.","Yes, everyone learned it in the same year.","Farming only started in one country."]',1,'Different people figured it out at different times.','These developments happened at different times and were not part of one single worldwide event.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_019','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Did early humans have cars or electricity?','["Yes, they had both.","No, they relied on nature and their physical skills.","They had electricity but no cars.","They had cars but no electricity."]',1,'Life was very different back then!','People did not have modern electricity, cars, computers, or factories. They relied on their knowledge of nature...','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_020','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What did early humans use to make tools when they couldn''t find stone?','["Plastic and metal","Wood, bone, and plant fibres","Glass and rubber","Only dirt"]',1,'They used whatever they could find in nature.','Early humans... used materials available in their surroundings, including stone, wood, bone, and plant fibres.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_021','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Can fire cause danger to early humans?','["No, fire is completely safe.","Yes, it can cause burns and uncontrolled wildfires.","Only if it is daytime.","Only to animals, not humans."]',1,'Fire is useful, but very dangerous!','Fire safety: Fire can cause burns, smoke inhalation, and uncontrolled wildfires.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_022','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'How did early humans first learn about fire?','["They invented it in a laboratory.","From natural events, like lightning strikes.","They bought it at a market.","They dug it out of the ground."]',1,'Before they learned to make it, they had to wait for lightning!','Natural events, including lightning strikes, can start fires.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_023','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Did all early human communities live exactly the same way?','["Yes, they all did the exact same things.","No, their ways of life depended on their environment.","Yes, they all lived in forests.","Yes, they all ate the same food."]',1,'People near the ocean fished, people in the plains hunted!','Not all early human communities lived in exactly the same way. Their lifestyles varied according to their environment...','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_024','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'Which of these is a benefit of farming?','["People could produce some of their own food and store it.","People had to move every single day.","People forgot how to make tools.","People stopped cooperating with each other."]',0,'It gave them a reliable supply of food for the winter.','Farming brought several important changes: People could produce some of their own food. Food storage became increasingly important.','2026-11-01 10:38:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_025','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',1,'What is the ''Neolithic'' period often associated with?','["The invention of computers.","The later Stone Age period associated with the start of farming.","The time before humans existed.","The period when people forgot how to use fire."]',1,'Neo = New, Lithic = Stone. It''s the ''New Stone Age''!','Neolithic: A term commonly used for the later Stone Age period associated in many regions with farming...','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_026','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why doesn''t ''prehistory'' end at the exact same time everywhere in the world?','["Because time moved slower in some places.","Because prehistory ends when written records begin, and writing was invented at different times in different regions.","Because some places never had a prehistoric period.","Because archaeologists haven''t finished digging everywhere."]',1,'If a society doesn''t invent writing until the year 1800, their ''prehistory'' lasts until 1800!','Prehistory is the period of the human past before written records... Writing developed at different times in different regions. Therefore, prehistory did not end everywhere at the same time.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_027','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why is the archaeological record of early tools mostly made of stone, even though they probably used wood?','["Because they hated using wood.","Wood and plant fibers decay quickly over time, while stone is durable and survives for millions of years in the earth.","Because animals ate all the stone tools.","Because wood turns into stone over time."]',1,'If you bury a stick and a rock for a thousand years, only the rock will still be there!','Wooden tools may have been important, too, but wood often decays more quickly than stone. As a result, the archaeological record may preserve stone tools more readily.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_028','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'How did ''friction'' help early humans?','["It helped them slide down hills faster.","Creating friction between pieces of wood was a method they developed to generate enough heat to start a fire.","It stopped their tools from breaking.","It made their food taste better."]',1,'Rubbing two sticks together really fast creates heat!','Methods used... included friction between pieces of wood and striking suitable stones to produce sparks.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_029','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why was ''cooperation'' essential for the survival of early hunter-gatherer communities?','["Because it was the law.","It allowed them to share crucial knowledge, hunt larger animals safely, care for children, and protect one another from predators.","It wasn''t essential; they preferred to live alone.","Because they needed someone to invent writing."]',1,'One person cannot hunt a mammoth alone, but ten people working together can!','Cooperation could help people obtain food, care for children, share knowledge, and manage difficult tasks.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_030','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'If a community lived in a coastal region, how would their gathering habits differ from a grassland community?','["Coastal communities would only hunt buffalo.","Coastal communities would rely heavily on fishing, collecting shellfish, and marine resources, whereas grassland communities would rely on herds and seeds.","Coastal communities would not gather anything.","There would be no difference."]',1,'You eat what you can find around you!','Coastal regions could provide fish, shellfish, and other marine resources. Grasslands could support herds of animals and offer seeds...','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_031','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'What does it mean that ''domestication'' is a ''gradual process''?','["It happens in one day.","It takes many generations of selectively breeding plants or animals to slowly change their traits to be more useful to humans.","It only happens when lightning strikes.","It means humans instantly control wild animals with magic."]',1,'You don''t turn a wild wolf into a pet dog in one day; it takes hundreds of years of breeding the friendliest wolves!','Domestication is a gradual process in which people manage and selectively breed plants over many generations.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_032','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why did farming encourage some communities to stop moving and build permanent settlements?','["Because walking became illegal.","Farming required people to remain near their planted fields to tend crops, harvest them, and build structures to safely store the food for the rest of the year.","Because farms were too heavy to carry.","Because domestic animals refuse to walk."]',1,'You can''t plant a field of wheat and then walk away for six months; you have to stay and protect it!','Farming could encourage people to remain near fields, stored food, and domesticated animals.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_033','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'How did early farming lead to ''specialized occupations''?','["Because everyone wanted to be a farmer.","Since farming produced enough surplus food to feed the community, not everyone had to spend all day hunting; some people could spend their time becoming specialized toolmakers, builders, or traders.","Because farming was too easy.","Because people forgot how to hunt entirely."]',1,'If the farmer grows enough food for three people, the other two people can spend their time inventing things or building houses!','Farming brought several important changes: ...Some people developed specialized occupations.','2026-11-01 10:38:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_034','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'What was a major challenge or risk introduced by early agriculture?','["Having too much free time.","Communities became highly dependent on specific crops; if a drought or disease caused a ''crop failure'', the entire settlement could face starvation.","Animals became too friendly.","The weather stopped changing."]',1,'If you only eat wheat, and the wheat dies, you have no food!','Agriculture also introduced challenges, including crop failure, dependence on particular crops, disputes over land and water...','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_035','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why do archaeologists study the ''wear marks'' on a prehistoric stone tool?','["To see if the tool was pretty.","Wear marks (scratches or chips) provide physical evidence showing exactly how the tool was used, whether for cutting meat, scraping hides, or chopping wood.","To find out who owned it.","To make the tool sharper."]',1,'If the edge is scratched in a specific way, they know it was used to cut hard bone, not soft meat!','Researchers examine a tool''s shape, material, wear marks... to investigate how it might have been made and used.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_036','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'How did the control of fire change the social life of early humans?','["It made everyone live alone.","A maintained hearth provided a shared space after dark where people could gather to prepare food, exchange vital information, and pass on skills to the next generation.","It stopped people from talking to each other.","It forced them to sleep all day."]',1,'The campfire was the ancient version of the family dinner table!','Fire and social life: A maintained fire could bring people together in a shared space. People could prepare food, exchange information, and teach skills.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_037','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Why is it incorrect to say that farming was a ''single worldwide event''?','["Because it happened in space.","Because farming was developed completely independently by different communities in different regions (like Mesoamerica, Asia, and the Middle East) at very different times in history.","Because farming never actually happened.","Because it only happened in Europe."]',1,'A farmer in Asia growing rice had no idea that a farmer in Mesoamerica was growing corn!','These developments happened at different times and were not part of one single worldwide event.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_038','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'What specific role did ''observation'' play in early human survival?','["It helped them invent writing instantly.","By observing nature, they learned which plants were poisonous, how animals migrated, and how weather patterns changed, allowing them to adapt and survive.","It was only used for painting.","It prevented them from starting fires."]',1,'If you watch a bear eat a berry and die, you learn not to eat that berry!','People learned from observation and experience. Knowledge about useful plants, animal behaviour, weather... could be passed from one generation to another.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_039','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'How did cooking meat with fire benefit early humans biologically?','["It turned the meat into vegetables.","Cooking softened the food (making it easier to chew and digest) and reduced biological risks by killing dangerous bacteria and parasites.","It made the meat taste worse.","It brought the animal back to life."]',1,'Cooked food gives your body more energy and stops you from getting sick from raw meat!','Cooking food: ...making them softer... Cooking can also reduce certain biological risks in food when done properly.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_040','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',5,'Did the invention of farming mean that hunting and gathering ended immediately?','["Yes, the very next day.","No, the transition was gradual; communities followed different paths, and farming did not immediately replace hunting and gathering everywhere.","Yes, hunting became illegal.","No, because farming was a failure."]',1,'Many early farmers still hunted deer and gathered berries to add to their farm food!','However, communities followed different paths, and farming did not immediately replace hunting and gathering everywhere.','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_041','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Analyze the complex relationship between ''climate/environment'' and the ''diversity of early human lifestyles''.','["Climate forced all humans to live exactly the same way.","Different biomes provided radically different abiotic and biotic resources. Humans had to culturally and technologically adapt to these specific parameters, leading to immense diversity in diet, shelter, and toolmaking across different global populations.","Environment had no effect on human lifestyle.","Early humans controlled the climate entirely."]',1,'You can''t build an igloo in the desert, and you can''t hunt a camel in the Arctic!','Their ways of life depended on their environment... Not all early human communities lived in exactly the same way. Their lifestyles varied according to their environment...','2026-11-01 10:38:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_042','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'How does the biological concept of ''selective breeding'' manifest in the historical ''domestication of plants''?','["Humans planted weeds to destroy farms.","Early farmers intentionally saved and planted seeds only from individual wild plants that exhibited desirable traits (e.g., larger grains, non-shattering stalks). Over generations, this artificial selection genetically altered the species into domesticated crops.","Plants domesticated themselves magically.","Humans watered the plants with fire."]',1,'If you only plant the biggest seeds, eventually, all your crops will grow big seeds!','Domestication is a gradual process... People collected seeds from useful plants, grew them, and saved seeds for later planting. Over time, these practices changed some plants...','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_043','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Evaluate the ecological trade-offs a hunter-gatherer community faced when transitioning to a sedentary agricultural lifestyle.','["Farming required less work and guaranteed perfect health.","Agriculture provided a concentrated, storable caloric surplus, enabling larger populations and specialization. However, it drastically reduced dietary diversity, increased susceptibility to localized crop failures (famines), and led to health issues associated with crowded, sedentary living.","Hunting was always safer and provided more food.","There were no trade-offs; farming was a negative mistake."]',1,'Farming meant more food overall, but if the rain didn''t come, the whole village starved!','Farming brought several important changes: ...Food storage... specialized occupations. Agriculture also introduced challenges, including crop failure, dependence on particular crops... and some health problems...','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_044','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Explain how the control of fire functioned as a catalyst for early human ''technological and metallurgical advancement''.','["Fire was only used for dancing.","Beyond basic survival (heat/cooking), the mastery of high-temperature controlled fires eventually allowed later societies to chemically alter clay into durable pottery and smelt ores into metal tools, launching the Bronze and Iron ages.","Fire burned all the early technology.","Fire prevented the invention of metal."]',1,'You can''t melt iron ore into a sword without a really, really hot fire!','Working with materials: Fire was eventually used in processes such as pottery production and metalworking.','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_045','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Critique the traditional narrative that depicts hunter-gatherer societies as ''primitive'' compared to agricultural societies.','["Hunter-gatherers were primitive because they had no language.","This narrative is flawed. Hunter-gatherers possessed vast, complex empirical knowledge of local ecology, botany, and animal behavior, and they engineered highly sophisticated, specialized tools and social structures perfectly adapted to their environments.","Agricultural societies were actually the primitive ones.","Both societies were equally primitive until the modern era."]',1,'Surviving in the wild requires an incredible amount of intelligence and specialized knowledge!','They relied on their knowledge of nature, their physical skills, tools, and cooperation... Knowledge about useful plants, animal behaviour, weather... was passed down.','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_046','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'How does the phrase ''the archaeological record may preserve stone tools more readily'' highlight an inherent ''survival bias'' in historical evidence?','["It proves early humans only ever used stone.","It highlights that durable materials (stone/bone) survive millennia, while organic materials (wood/hide/fiber) decay. This biases our understanding, potentially making early humans seem more reliant on stone than they actually were.","It proves that wood is stronger than stone.","It means archaeologists only like looking for stone."]',1,'Just because we only find stone spearheads doesn''t mean they didn''t have amazing wooden bows that rotted away!','Wooden tools may have been important, too, but wood often decays more quickly than stone. As a result, the archaeological record may preserve stone tools more readily.','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_047','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Analyze how the ''storage of food'' fundamentally altered the social structure of early human settlements.','["It made everyone exactly equal.","A storable caloric surplus allowed populations to grow denser and remain sedentary. It necessitated new social structures to manage, protect, and distribute the surplus, eventually leading to specialized non-farming classes, wealth accumulation, and social hierarchies.","It forced people to move more often.","It caused humans to stop eating meat."]',1,'When you have a giant barn full of grain, you need guards to protect it, builders to fix it, and a leader to manage it!','Food storage became increasingly important. Settlements could become more permanent. Some people developed specialized occupations.','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_048','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'Why is the term ''Neolithic Revolution'' sometimes considered misleading by modern historians describing the advent of farming?','["Because it happened during the Paleolithic.","The term ''revolution'' implies a sudden, rapid event. In reality, the transition to agriculture and domestication was a slow, gradual, millennia-long evolutionary process that occurred independently in multiple regions.","Because it wasn''t a real historical period.","Because ''Neolithic'' means ''Old Stone Age''."]',1,'It didn''t happen overnight; it took thousands of years of slow changes to figure out how to farm!','Farming began independently in several parts of the world... Domestication is a gradual process... The development of farming was a long process involving many communities, not a single invention...','2026-11-01 10:38:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_049','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'What is the epistemological challenge of interpreting prehistoric ''cave paintings and engravings''?','["They are always written in modern English.","Without written records to explain their cultural, religious, or symbolic context, modern researchers can only infer their purpose (e.g., hunting magic, storytelling, or art) based on visual observation, which is inherently speculative.","They dissolve when looked at.","They perfectly explain exactly what happened every day."]',1,'We can see the painting of a bull, but we don''t know if it''s a religious prayer, a hunting guide, or just a cool drawing!','Cave paintings and engravings provide clues about artistic expression. [But] Because written records are absent for prehistoric periods, researchers use other kinds of evidence... A tool''s [or art''s] purpose is sometimes uncertain, so explanations must be based on evidence rather than assumptions.','2026-11-01 10:38:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hist_prehist_050','History','Basic History','Topic 4: Early Humans and Prehistoric Life','Primary',10,'How did the independent domestication of vastly different crops (like maize in Mesoamerica vs. rice in East Asia) influence the cultural trajectories of those distinct regions?','["It made their cultures exactly identical.","The specific biological requirements of the local staple crops (e.g., water-intensive rice paddies vs. dry-farmed maize) dictated different agricultural techniques, labor organizations, and environmental modifications, which in turn profoundly shaped the divergent social and cultural structures of those civilizations.","It prevented them from building any settlements.","It caused them all to abandon farming entirely."]',1,'Farming rice requires massive community cooperation to flood fields; farming other crops requires different social organization!','Different regions domesticated different crops... These developments happened at different times... Agriculture introduced challenges, including... disputes over land and water...','2026-11-01 10:38:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0001','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',1,'What is an ''unknown number'' in mathematics?','["A number whose value we do not know yet.","A number that does not exist.","A number larger than 100.","A negative number."]',0,'We don''t know it yet.','It is a placeholder for a value we need to find.','2026-11-01 17:43:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0002','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',1,'In the sentence 6 + [] = 10, what does the box [] represent?','["The unknown number.","The equals sign.","The answer 16.","A mistake."]',0,'It''s holding a place.','The box is holding the place of the missing number.','2026-11-01 17:43:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0003','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',1,'Charlie has 3 books outside a box. There are 10 books altogether. How do you find how many are inside the box?','["Subtract 3 from 10.","Add 10 and 3.","Multiply 10 by 3.","Guess."]',0,'Work backwards.','Total minus the part you know gives the unknown part.','2026-11-01 17:43:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0004','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',1,'Which symbol can be used to represent an unknown number?','["All of these (a box, a question mark, a letter).","Only a box.","Only a question mark.","Only a letter."]',0,'Multiple things work.','Any symbol can hold the place of a missing value.','2026-11-01 17:43:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0005','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',1,'If 7 + ? = 12, what is the unknown number?','["5","19","6","4"]',0,'Count up from 7.','12 - 7 = 5.','2026-11-01 17:43:07',NULL,NULL);
