INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0025','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Analyze: Why does the method to find an unknown in a subtraction sentence change depending on its position?','["If the starting number is missing, you must add the parts. If the subtracted part is missing, you subtract the difference from the start.","It doesn''t change, always add.","Subtraction is broken.","It doesn''t change, always subtract."]',0,'Part-Whole model.','Whole - Part = Part. If Whole is missing, add Parts. If Part is missing, subtract known Part from Whole.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0026','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Critique: ''Bob says that to find [] in 42 ÷ [] = 6, you should multiply 42 by 6.''','["False, because the starting amount (42) is being split into groups; you divide 42 by 6 to find the group size.","True, multiplication is the inverse of division.","False, you should add them.","False, the answer is 48."]',0,'Don''t just blindly multiply.','Dividend / Quotient = Divisor.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0027','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Synthesize a real-life situation for the equation: [] - 15 = 45.','["You had some money, spent 15, and now have 45 left.","You had 15 books and got 45 more.","You had 45 books and gave away 15.","You had 45 books and lost some, leaving 15."]',0,'Read the equation as a story.','Starting amount is unknown, 15 is removed, 45 remains.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0028','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Evaluate: Why is checking your answer by plugging the found number back into the original equation important?','["It verifies that the inverse operation was performed correctly and the logic holds true.","It wastes time.","It makes the number bigger.","It turns it into a fraction."]',0,'Verify.','Sanity check.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0029','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Synthesize the unknown number: [] x 8 = 96.','["12","11","10","14"]',0,'Inverse operation.','96 / 8 = 12.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0030','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Analyze: What is the inverse operation used to solve [] + x = y?','["Subtraction: y - x","Addition: y + x","Multiplication: y * x","Division: y / x"]',0,'Opposite of addition.','Subtract the known part from the total.','2026-11-01 17:43:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0031','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Analyze: Why does the method to find an unknown in a subtraction sentence change depending on its position?','["If the starting number is missing, you must add the parts. If the subtracted part is missing, you subtract the difference from the start.","It doesn''t change, always add.","Subtraction is broken.","It doesn''t change, always subtract."]',0,'Part-Whole model.','Whole - Part = Part. If Whole is missing, add Parts. If Part is missing, subtract known Part from Whole.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0032','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Critique: ''Hannah says that to find [] in 42 ÷ [] = 6, you should multiply 42 by 6.''','["False, because the starting amount (42) is being split into groups; you divide 42 by 6 to find the group size.","True, multiplication is the inverse of division.","False, you should add them.","False, the answer is 48."]',0,'Don''t just blindly multiply.','Dividend / Quotient = Divisor.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0033','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Synthesize a real-life situation for the equation: [] - 15 = 45.','["You had some money, spent 15, and now have 45 left.","You had 15 leaves and got 45 more.","You had 45 leaves and gave away 15.","You had 45 leaves and lost some, leaving 15."]',0,'Read the equation as a story.','Starting amount is unknown, 15 is removed, 45 remains.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0034','Maths','Introduction to Algebra','Subtopic 1: Understanding Unknown Numbers','Primary',10,'Evaluate: Why is checking your answer by plugging the found number back into the original equation important?','["It verifies that the inverse operation was performed correctly and the logic holds true.","It wastes time.","It makes the number bigger.","It turns it into a fraction."]',0,'Verify.','Sanity check.','2026-11-01 17:43:10',NULL,NULL);
