INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0037','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'What is a ''variable'' in algebra?','["A letter or symbol used to represent an unknown or changing number.","A number that is very large.","An equals sign.","A spelling mistake."]',0,'Usually a letter like x.','It takes the place of a number.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0038','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'Which of these is commonly used as a variable?','["x","5","+","="]',0,'Look for a letter.','Letters are variables.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0039','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'If you have 3 apples and get some more, how could you write ''some more'' as a variable?','["x","3","+","-"]',0,'Use a letter.','A variable represents an unknown amount.','2026-11-01 17:43:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0040','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'In the expression x + 4, what is the variable?','["x","4","+","There isn''t one"]',0,'The letter.','x is the letter standing in for a number.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0041','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'What does the symbol ''<'' mean?','["Is less than","Is greater than","Is equal to","Add"]',0,'L-shape slightly closed.','Points to the smaller number.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0042','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'What does the symbol ''>'' mean?','["Is greater than","Is less than","Is equal to","Subtract"]',0,'Eats the big number.','Open mouth to the bigger number.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0043','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'What is a ''variable'' in algebra?','["A letter or symbol used to represent an unknown or changing number.","A number that is very large.","An equals sign.","A spelling mistake."]',0,'Usually a letter like x.','It takes the place of a number.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0044','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'Which of these is commonly used as a variable?','["x","5","+","="]',0,'Look for a letter.','Letters are variables.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0045','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'If you have 3 apples and get some more, how could you write ''some more'' as a variable?','["x","3","+","-"]',0,'Use a letter.','A variable represents an unknown amount.','2026-11-01 17:43:11',NULL,NULL);
