INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0048','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',1,'What does the symbol ''>'' mean?','["Is greater than","Is less than","Is equal to","Subtract"]',0,'Eats the big number.','Open mouth to the bigger number.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0049','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'If an expression is a + 4, and a = 1, what is the value of the expression?','["5","4","6","4"]',0,'Substitute the number for the letter.','1 + 4 = 5.','2026-11-01 17:43:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0050','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'What does ''3x'' mean in algebra?','["3 times x","3 plus x","3 minus x","3 divided by x"]',0,'Hidden multiplication sign.','A number next to a letter means multiply.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0051','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'Find the value of 2x when x = 5.','["10","7","5","15"]',0,'Multiply.','2 x 5 = 10.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0052','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'Find the value of 4n when n = 5.','["20","9","5","25"]',0,'Multiply.','4 x 5 = 20.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0053','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'What is the difference between an expression and an equation?','["An equation has an equals sign stating two things are equal; an expression is just a mathematical phrase.","They are exactly the same.","An expression has letters, an equation doesn''t.","An equation is only addition."]',0,'Look for the = sign.','Equations equate things.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0054','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'If you have ''b'' stickers and buy 5 more, what expression represents the total?','["b + 5","b - 5","5b","b / 5"]',0,'Add them.','Buying more means addition.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0055','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'If an expression is a + 4, and a = 2, what is the value of the expression?','["6","5","7","4"]',0,'Substitute the number for the letter.','2 + 4 = 6.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0056','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'What does ''3x'' mean in algebra?','["3 times x","3 plus x","3 minus x","3 divided by x"]',0,'Hidden multiplication sign.','A number next to a letter means multiply.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0057','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'Find the value of 2x when x = 6.','["12","8","6","18"]',0,'Multiply.','2 x 6 = 12.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0058','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'Find the value of 4n when n = 6.','["24","10","6","30"]',0,'Multiply.','4 x 6 = 24.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0059','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'What is the difference between an expression and an equation?','["An equation has an equals sign stating two things are equal; an expression is just a mathematical phrase.","They are exactly the same.","An expression has letters, an equation doesn''t.","An equation is only addition."]',0,'Look for the = sign.','Equations equate things.','2026-11-01 17:43:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0060','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',5,'If you have ''b'' cookies and buy 5 more, what expression represents the total?','["b + 5","b - 5","5b","b / 5"]',0,'Add them.','Buying more means addition.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0061','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Analyze: Why is it crucial to understand that 3x means 3 multiplied by x, rather than reading it as a two-digit number where x is the ones place?','["Because variables represent separate quantities being operated on, not literal digits in a place value system.","Because x is always zero.","It actually is a two-digit number.","Because 3x means 3 + x."]',0,'Number next to letter.','Algebra uses implicit multiplication.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0062','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Critique: ''Bob says that in the equation x + x = 10, the first x can be 4 and the second x can be 6.''','["False, within a single mathematical statement, a specific variable must represent the exact same value every time it appears.","True, as long as it adds to 10.","True, variables can be anything.","False, they both must be 10."]',0,'x is always x.','Variables are consistent within an equation.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0063','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Evaluate the term ''coefficient''. In the expression 5y, what is the coefficient and what does it do?','["5 is the coefficient; it tells you how many times to multiply the variable y.","y is the coefficient; it is the unknown.","5 is the coefficient; it tells you what to add to y.","There is no coefficient."]',0,'Number before the letter.','The number in front is the multiplier.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0064','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Synthesize an expression: ''Diana has some money. They spend $4 on shipping, and the remaining money buys 3 identical items.'' Let m be the starting money. Expression for one item''s cost?','["(m - 4) / 3","3m - 4","m / 3 - 4","m - 4 * 3"]',0,'Order of operations.','Subtract shipping first, then divide what''s left.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0065','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Analyze: How does using variables allow us to create formulas?','["Variables act as universal placeholders, allowing a single mathematical relationship (like Area = length x width) to be applied to any specific numbers.","Variables make math look harder.","Variables prevent us from finding an answer.","Variables only work for shapes."]',0,'Universal rules.','Formulas describe relationships, not just specific calculations.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0066','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Critique: ''An expression like x + 5 can be solved to find out what x is.''','["False, an expression cannot be solved because it does not state an equality; it can only be evaluated if x is given.","True, x is always 5.","True, you just subtract 5.","False, x must be 0."]',0,'You need an equation to solve for x.','Expressions don''t have an equals sign.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0067','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Analyze: Why is it crucial to understand that 3x means 3 multiplied by x, rather than reading it as a two-digit number where x is the ones place?','["Because variables represent separate quantities being operated on, not literal digits in a place value system.","Because x is always zero.","It actually is a two-digit number.","Because 3x means 3 + x."]',0,'Number next to letter.','Algebra uses implicit multiplication.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0068','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Critique: ''Hannah says that in the equation x + x = 10, the first x can be 4 and the second x can be 6.''','["False, within a single mathematical statement, a specific variable must represent the exact same value every time it appears.","True, as long as it adds to 10.","True, variables can be anything.","False, they both must be 10."]',0,'x is always x.','Variables are consistent within an equation.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0069','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Evaluate the term ''coefficient''. In the expression 5y, what is the coefficient and what does it do?','["5 is the coefficient; it tells you how many times to multiply the variable y.","y is the coefficient; it is the unknown.","5 is the coefficient; it tells you what to add to y.","There is no coefficient."]',0,'Number before the letter.','The number in front is the multiplier.','2026-11-01 17:43:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0070','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Synthesize an expression: ''Julia has some money. They spend $4 on shipping, and the remaining money buys 3 identical items.'' Let m be the starting money. Expression for one item''s cost?','["(m - 4) / 3","3m - 4","m / 3 - 4","m - 4 * 3"]',0,'Order of operations.','Subtract shipping first, then divide what''s left.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0071','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Analyze: How does using variables allow us to create formulas?','["Variables act as universal placeholders, allowing a single mathematical relationship (like Area = length x width) to be applied to any specific numbers.","Variables make math look harder.","Variables prevent us from finding an answer.","Variables only work for shapes."]',0,'Universal rules.','Formulas describe relationships, not just specific calculations.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0072','Maths','Introduction to Algebra','Subtopic 2: Variables and Algebraic Symbols','Primary',10,'Critique: ''An expression like x + 5 can be solved to find out what x is.''','["False, an expression cannot be solved because it does not state an equality; it can only be evaluated if x is given.","True, x is always 5.","True, you just subtract 5.","False, x must be 0."]',0,'You need an equation to solve for x.','Expressions don''t have an equals sign.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0073','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What is an ''algebraic expression''?','["A mathematical phrase made using numbers, variables, and operations, but NO equals sign.","An equation with an answer.","A word problem.","A type of fraction."]',0,'No equals sign.','It''s a phrase, not a sentence.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0074','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'How do you write ''a number plus 5'' as an algebraic expression? (Let the number be x)','["x + 5","5x","x - 5","x / 5"]',0,'Add 5.','''Plus'' means addition.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0075','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'How do you write ''a number minus 3''? (Let the number be x)','["x - 3","3 - x","3x","x + 3"]',0,'Take away 3.','''Minus'' means subtraction.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0076','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What does ''twice a number'' look like in algebra? (Let the number be x)','["2x","x + 2","x / 2","x^2"]',0,'Double it.','''Twice'' means multiply by 2.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0077','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'How do you write ''a number divided by 4''? (Let the number be x)','["x / 4","4 / x","4x","x - 4"]',0,'Fraction bar.','The number is being split.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0078','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What word often indicates addition in a word problem?','["Sum (or plus, increased by)","Difference","Product","Quotient"]',0,'Adding up.','Sum means total.','2026-11-01 17:43:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0079','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What is an ''algebraic expression''?','["A mathematical phrase made using numbers, variables, and operations, but NO equals sign.","An equation with an answer.","A word problem.","A type of fraction."]',0,'No equals sign.','It''s a phrase, not a sentence.','2026-11-01 17:43:14',NULL,NULL);
