INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0082','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What does ''twice a number'' look like in algebra? (Let the number be x)','["2x","x + 2","x / 2","x^2"]',0,'Double it.','''Twice'' means multiply by 2.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0083','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'How do you write ''a number divided by 4''? (Let the number be x)','["x / 4","4 / x","4x","x - 4"]',0,'Fraction bar.','The number is being split.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0084','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',1,'What word often indicates addition in a word problem?','["Sum (or plus, increased by)","Difference","Product","Quotient"]',0,'Adding up.','Sum means total.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0085','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''3 less than a number''. (Let the number be x)','["x - 3","3 - x","x + 3","3x"]',0,'Order matters in subtraction!','You start with x, and take away the amount.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0086','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The product of 6 and a number''. (Let the number be a)','["6a","a / 6","a + 6","a - 6"]',0,'Smush them together.','''Product'' means multiply.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0087','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The quotient of n and 6''.','["n / 6","6 / n","6n","n - 6"]',0,'Fraction.','''Quotient'' means division. The first mentioned goes on top.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0088','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''Twice a number plus 5''. (Let the number be x)','["2x + 5","2(x + 5)","x + 5","5x + 2"]',0,'Step by step.','Multiply by 2, then add.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0089','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''Three times a number minus 5''. (Let the number be x)','["3x - 5","3(x - 5)","x - 3","5x - 3"]',0,'Step by step.','Multiply by 3, then subtract.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0090','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The sum of a number and 5, divided by 2''. (Let number be x)','["(x + 5) / 2","x / 2 + 5","x + 5 / 2","2(x + 5)"]',0,'Group the addition first.','The whole sum is divided, so use brackets or a long fraction bar.','2026-11-01 17:43:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0091','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''4 less than a number''. (Let the number be x)','["x - 4","4 - x","x + 4","4x"]',0,'Order matters in subtraction!','You start with x, and take away the amount.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0092','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The product of 7 and a number''. (Let the number be a)','["7a","a / 7","a + 7","a - 7"]',0,'Smush them together.','''Product'' means multiply.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0093','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The quotient of n and 7''.','["n / 7","7 / n","7n","n - 7"]',0,'Fraction.','''Quotient'' means division. The first mentioned goes on top.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0094','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''Twice a number plus 6''. (Let the number be x)','["2x + 6","2(x + 6)","x + 6","6x + 2"]',0,'Step by step.','Multiply by 2, then add.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0095','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''Three times a number minus 1''. (Let the number be x)','["3x - 1","3(x - 1)","x - 3","1x - 3"]',0,'Step by step.','Multiply by 3, then subtract.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0096','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',5,'Write an expression for: ''The sum of a number and 5, divided by 2''. (Let number be x)','["(x + 5) / 2","x / 2 + 5","x + 5 / 2","2(x + 5)"]',0,'Group the addition first.','The whole sum is divided, so use brackets or a long fraction bar.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0097','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Analyze the subtle difference in phrasing: Write expressions for ''7 less than a number'' and ''A number less than 7''.','["x - 7 AND 7 - x","7 - x AND x - 7","They are both x - 7","They are both 7 - x"]',0,'Read carefully.','Order is critical in subtraction. ''Less than'' flips the spoken order.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0098','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Synthesize an expression: ''Bob has b books and receives 4 more. Then they share all their books equally among 3 friends. How many does each friend get?''','["(b + 4) / 3","b + 4 / 3","3(b + 4)","b / 3 + 4"]',0,'Use brackets.','The total (b+n) must be grouped before dividing.','2026-11-01 17:43:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0099','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Critique: ''The phrase ''five more than twice a number'' is written as 2(x + 5).''','["False, that represents ''twice the sum of a number and five''. The correct expression is 2x + 5.","True, they mean the same thing.","False, it should be 5x + 2.","False, it should be x + 10."]',0,'Do the multiplication first.','Order of operations dictates that 2x + 5 happens sequentially without brackets.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0100','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Evaluate: Why is 3x the standard algebraic notation rather than 3 * x or 3 x x?','["The multiplication sign ''x'' looks too much like the variable ''x'', causing confusion. Juxtaposition (placing them together) implies multiplication cleanly.","Because it saves ink.","Because ''x'' means addition in algebra.","It is just a stylistic choice with no logic."]',0,'Don''t confuse the letter with the symbol.','Avoid ambiguous symbols.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0101','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Synthesize an expression for the total cost: ''A delivery fee is fixed at 8 dollars, and each item costs 10 dollars. What is the cost of n items?''','["10n + 8","8n + 10","(8 + 10)n","n / 10 + 8"]',0,'Fixed cost vs variable cost.','Cost per item multiplied by number of items, plus flat fee.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0102','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Analyze: What is the fundamental difference between translating words into an expression vs an equation?','["An equation requires phrases like ''is'', ''equals'', or ''gives a total of'' to define a relationship between two expressions.","There is no difference.","An equation only uses addition.","An expression requires an answer."]',0,'Look for the ''is''.','Expressions are phrases; equations are complete sentences.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0103','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Analyze the subtle difference in phrasing: Write expressions for ''7 less than a number'' and ''A number less than 7''.','["x - 7 AND 7 - x","7 - x AND x - 7","They are both x - 7","They are both 7 - x"]',0,'Read carefully.','Order is critical in subtraction. ''Less than'' flips the spoken order.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0104','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Synthesize an expression: ''Hannah has b books and receives 5 more. Then they share all their books equally among 3 friends. How many does each friend get?''','["(b + 5) / 3","b + 5 / 3","3(b + 5)","b / 3 + 5"]',0,'Use brackets.','The total (b+n) must be grouped before dividing.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0105','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Critique: ''The phrase ''five more than twice a number'' is written as 2(x + 5).''','["False, that represents ''twice the sum of a number and five''. The correct expression is 2x + 5.","True, they mean the same thing.","False, it should be 5x + 2.","False, it should be x + 10."]',0,'Do the multiplication first.','Order of operations dictates that 2x + 5 happens sequentially without brackets.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0106','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Evaluate: Why is 3x the standard algebraic notation rather than 3 * x or 3 x x?','["The multiplication sign ''x'' looks too much like the variable ''x'', causing confusion. Juxtaposition (placing them together) implies multiplication cleanly.","Because it saves ink.","Because ''x'' means addition in algebra.","It is just a stylistic choice with no logic."]',0,'Don''t confuse the letter with the symbol.','Avoid ambiguous symbols.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0107','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Synthesize an expression for the total cost: ''A delivery fee is fixed at 4 dollars, and each item costs 6 dollars. What is the cost of n items?''','["6n + 4","4n + 6","(4 + 6)n","n / 6 + 4"]',0,'Fixed cost vs variable cost.','Cost per item multiplied by number of items, plus flat fee.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0108','Maths','Introduction to Algebra','Subtopic 3: Writing Simple Algebraic Expressions','Primary',10,'Analyze: What is the fundamental difference between translating words into an expression vs an equation?','["An equation requires phrases like ''is'', ''equals'', or ''gives a total of'' to define a relationship between two expressions.","There is no difference.","An equation only uses addition.","An expression requires an answer."]',0,'Look for the ''is''.','Expressions are phrases; equations are complete sentences.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0109','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'What is a ''number sentence''?','["A mathematical statement that uses numbers, operations, and sometimes symbols to express a relationship.","A sentence with words spelled out.","A line of numbers.","A random guess."]',0,'Like an equation.','It tells a math story.','2026-11-01 17:43:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0110','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'Which of these is a complete number sentence?','["7 + 2 = 9","7 + 2","The number 7","Plus 2"]',0,'It needs a verb (like =).','It has an operation and an equality/inequality symbol.','2026-11-01 17:43:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0111','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'True or False: 8 + 4 = 12 is a TRUE number sentence.','["True","False","Only on Mondays","Cannot tell"]',0,'Check the addition.','The math is correct.','2026-11-01 17:43:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0112','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'True or False: 8 + 4 = 13 is a TRUE number sentence.','["False","True","Only on Tuesdays","Cannot tell"]',0,'Check the addition.','The math is incorrect.','2026-11-01 17:43:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0113','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'Can a number sentence use the ''<'' or ''>'' symbols instead of ''=''?','["Yes","No","Only for negative numbers","Only in high school"]',0,'Yes, inequalities work.','Comparison sentences are valid number sentences.','2026-11-01 17:43:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0114','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',1,'What does the ''='' sign actually mean?','["Both sides have the exact same value.","Write the answer next.","Calculate the left side.","It marks the end of a problem."]',0,'Balance scale.','It shows balance.','2026-11-01 17:43:18',NULL,NULL);
