INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0121','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Determine if this is true or false: 4 + 6 = 7 + 3.','["True (Both sides equal 10)","False","Cannot be determined","Only true sometimes"]',0,'10 = 10.','Calculate both sides.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0122','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Determine if this is true or false: 10 + 2 = 9 + 4.','["False (12 does not equal 13)","True","Cannot be determined","Only true sometimes"]',0,'12 vs 13.','Calculate both sides.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0123','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'What makes a number sentence an ''open'' number sentence?','["It contains an unknown value (like a box or a variable) so it cannot be judged true or false yet.","It has no equals sign.","It is very long.","It has fractions."]',0,'Missing pieces.','It is waiting for a value.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0124','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Translate into a number sentence: ''Ten minus four equals six.''','["10 - 4 = 6","10 + 4 = 6","10 / 4 = 6","4 - 10 = 6"]',0,'Word for word.','Direct translation.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0125','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Translate into a number sentence: ''Twice three equals six.''','["2 x 3 = 6","2 + 3 = 6","3 / 2 = 6","3 - 2 = 6"]',0,'Double.','''Twice'' means multiply by 2.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0126','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Write a number sentence for: ''A box contains 6 pencils. 4 are added. There are now 10.''','["6 + 4 = 10","6 - 4 = 10","6 x 4 = 10","10 - 6 = 4"]',0,'Translate the action.','Adding items gives a total.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0127','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Determine if this is true or false: 4 + 6 = 7 + 3.','["True (Both sides equal 10)","False","Cannot be determined","Only true sometimes"]',0,'10 = 10.','Calculate both sides.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0128','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Determine if this is true or false: 10 + 2 = 9 + 4.','["False (12 does not equal 13)","True","Cannot be determined","Only true sometimes"]',0,'12 vs 13.','Calculate both sides.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0129','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'What makes a number sentence an ''open'' number sentence?','["It contains an unknown value (like a box or a variable) so it cannot be judged true or false yet.","It has no equals sign.","It is very long.","It has fractions."]',0,'Missing pieces.','It is waiting for a value.','2026-11-01 17:43:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0130','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Translate into a number sentence: ''Ten minus four equals six.''','["10 - 4 = 6","10 + 4 = 6","10 / 4 = 6","4 - 10 = 6"]',0,'Word for word.','Direct translation.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0131','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Translate into a number sentence: ''Twice three equals six.''','["2 x 3 = 6","2 + 3 = 6","3 / 2 = 6","3 - 2 = 6"]',0,'Double.','''Twice'' means multiply by 2.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0132','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',5,'Write a number sentence for: ''A box contains 6 pencils. 4 are added. There are now 10.''','["6 + 4 = 10","6 - 4 = 10","6 x 4 = 10","10 - 6 = 4"]',0,'Translate the action.','Adding items gives a total.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0133','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Critique: ''Alice thinks the ''='' sign just means ''here is the answer to the calculation on the left''.''','["False, it indicates a strict mathematical equivalence (balance) between the expression on the left and the expression on the right.","True, that is its only purpose.","False, it means subtract.","True for addition only."]',0,'Balance scale, not an arrow.','It is a statement of equality, not an action verb.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0134','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Analyze: Why is ''5 + 3'' an expression, but ''5 + 3 = 8'' a number sentence?','["An expression represents a quantity; a number sentence makes a complete relational claim (true or false) about quantities.","They are the same thing.","An expression has letters.","A number sentence has no numbers."]',0,'Phrase vs Sentence.','A sentence needs a relational ''verb'' like equals.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0135','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Evaluate the open number sentence: [] + 4 = 10. Why is it called ''open''?','["Its truth value is unresolved; it becomes a TRUE sentence if 6 is substituted, and a FALSE sentence for any other number.","It is missing a plus sign.","It is open to interpretation and has many answers.","It doesn''t have an equals sign."]',0,'Waiting for input.','It depends on the input.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0136','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Synthesize a number sentence representing this inequality: ''A journey of 30 minutes followed by a 15-minute delay takes less than an hour.'' (Use minutes).','["30 + 15 < 60","30 + 15 = 45","30 + 15 > 60","30 - 15 < 60"]',0,'Convert hour to minutes.','Translate quantities and compare to 60 mins.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0137','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Analyze: Can a number sentence be both false and mathematically valid in its structure?','["Yes, ''2 + 2 = 5'' is a perfectly validly structured number sentence, it just happens to evaluate to False.","No, false sentences are not math.","Only if variables are used.","Only inequalities can be false."]',0,'Grammatically correct but factually wrong.','Structure vs Truth value.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0138','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Evaluate: How does understanding open number sentences prepare students for algebra?','["It introduces the concept of a variable (the open box) acting as a placeholder that must be solved for to balance the equation.","It doesn''t.","It teaches spelling.","It only helps with addition."]',0,'Box = x.','The box is just a proto-variable.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0139','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Critique: ''George thinks the ''='' sign just means ''here is the answer to the calculation on the left''.''','["False, it indicates a strict mathematical equivalence (balance) between the expression on the left and the expression on the right.","True, that is its only purpose.","False, it means subtract.","True for addition only."]',0,'Balance scale, not an arrow.','It is a statement of equality, not an action verb.','2026-11-01 17:43:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0140','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Analyze: Why is ''5 + 3'' an expression, but ''5 + 3 = 8'' a number sentence?','["An expression represents a quantity; a number sentence makes a complete relational claim (true or false) about quantities.","They are the same thing.","An expression has letters.","A number sentence has no numbers."]',0,'Phrase vs Sentence.','A sentence needs a relational ''verb'' like equals.','2026-11-01 17:43:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0141','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Evaluate the open number sentence: [] + 4 = 10. Why is it called ''open''?','["Its truth value is unresolved; it becomes a TRUE sentence if 6 is substituted, and a FALSE sentence for any other number.","It is missing a plus sign.","It is open to interpretation and has many answers.","It doesn''t have an equals sign."]',0,'Waiting for input.','It depends on the input.','2026-11-01 17:43:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0142','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Synthesize a number sentence representing this inequality: ''A journey of 30 minutes followed by a 15-minute delay takes less than an hour.'' (Use minutes).','["30 + 15 < 60","30 + 15 = 45","30 + 15 > 60","30 - 15 < 60"]',0,'Convert hour to minutes.','Translate quantities and compare to 60 mins.','2026-11-01 17:43:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0143','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Analyze: Can a number sentence be both false and mathematically valid in its structure?','["Yes, ''2 + 2 = 5'' is a perfectly validly structured number sentence, it just happens to evaluate to False.","No, false sentences are not math.","Only if variables are used.","Only inequalities can be false."]',0,'Grammatically correct but factually wrong.','Structure vs Truth value.','2026-11-01 17:43:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0144','Maths','Introduction to Algebra','Subtopic 4: Understanding Number Sentences','Primary',10,'Evaluate: How does understanding open number sentences prepare students for algebra?','["It introduces the concept of a variable (the open box) acting as a placeholder that must be solved for to balance the equation.","It doesn''t.","It teaches spelling.","It only helps with addition."]',0,'Box = x.','The box is just a proto-variable.','2026-11-01 17:43:21',NULL,NULL);
