INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0169','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Analyze: Why do ''[] - 4 = 9'' and ''15 - [] = 8'' require different operations to solve?','["In the first, the total (minuend) is missing, so you add the parts. In the second, a part (subtrahend) is missing, so you subtract the known part from the total.","They both require addition.","They both require subtraction.","Subtraction is broken."]',0,'Total vs Part.','Position of the unknown changes the logic.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0170','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Synthesize the solution: 18 - 5 = [] + 4','["9","13","17","27"]',0,'Solve the left side first.','18-5=13. 13-4=9.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0171','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Evaluate: Why is it important to substitute your answer back into the original number sentence?','["To verify that the calculated value actually maintains the equality of the statement, catching any arithmetic or logic errors.","To make the problem longer.","It isn''t important.","To change the equation."]',0,'Check your work.','Sanity check.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0172','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Synthesize the solution: 6 x [] + 4 = 40','["6","36","7","5"]',0,'Work backwards step-by-step.','40-4=36. 36/6=6.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0173','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Analyze the word problem: ''You had some money, saved 15 more, and now have 40.'' What is the equation and solution?','["x + 15 = 40; x = 25","x - 15 = 40; x = 55","15 + 40 = x; x = 55","40 - x = 15; x = 35"]',0,'Translate directly.','Original unknown + 15 = 40.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0174','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Critique: ''Fiona solved 48 ÷ [] = 6 by doing 48 x 6 = 288.''','["False, the divisor is missing, so you must divide the dividend by the quotient (48 ÷ 6 = 8).","True.","False, they should add.","False, they should subtract."]',0,'Check your answer: 48 / 288 is not 6.','Inverse of division isn''t always multiplication, depending on what is missing.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0175','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Analyze: Why do ''[] - 4 = 9'' and ''15 - [] = 8'' require different operations to solve?','["In the first, the total (minuend) is missing, so you add the parts. In the second, a part (subtrahend) is missing, so you subtract the known part from the total.","They both require addition.","They both require subtraction.","Subtraction is broken."]',0,'Total vs Part.','Position of the unknown changes the logic.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0176','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Synthesize the solution: 18 - 5 = [] + 4','["9","13","17","27"]',0,'Solve the left side first.','18-5=13. 13-4=9.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0177','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Evaluate: Why is it important to substitute your answer back into the original number sentence?','["To verify that the calculated value actually maintains the equality of the statement, catching any arithmetic or logic errors.","To make the problem longer.","It isn''t important.","To change the equation."]',0,'Check your work.','Sanity check.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0178','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Synthesize the solution: 6 x [] + 4 = 40','["6","36","7","5"]',0,'Work backwards step-by-step.','40-4=36. 36/6=6.','2026-11-01 17:43:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0179','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Analyze the word problem: ''You had some money, saved 15 more, and now have 40.'' What is the equation and solution?','["x + 15 = 40; x = 25","x - 15 = 40; x = 55","15 + 40 = x; x = 55","40 - x = 15; x = 35"]',0,'Translate directly.','Original unknown + 15 = 40.','2026-11-01 17:43:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0180','Maths','Introduction to Algebra','Subtopic 5: Finding Missing Values in Number Sentences','Primary',10,'Critique: ''Liam solved 48 ÷ [] = 6 by doing 48 x 6 = 288.''','["False, the divisor is missing, so you must divide the dividend by the quotient (48 ÷ 6 = 8).","True.","False, they should add.","False, they should subtract."]',0,'Check your answer: 48 / 288 is not 6.','Inverse of division isn''t always multiplication, depending on what is missing.','2026-11-01 17:43:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0181','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',1,'What does ''equality'' mean in math?','["Two quantities have the exact same value.","One quantity is bigger.","One quantity is smaller.","The numbers look the same."]',0,'Like a scale.','Balanced.','2026-11-01 17:43:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0182','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',1,'What does ''inequality'' mean?','["Two quantities are NOT equal (one is greater or smaller).","Two quantities are equal.","A math mistake.","A negative number."]',0,'Unbalanced.','Not equal.','2026-11-01 17:43:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0183','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',1,'What does the symbol ''<'' mean?','["Less than","Greater than","Equal to","Add"]',0,'Points left.','Pointy end first means small first.','2026-11-01 17:43:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0184','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',1,'What does the symbol ''>'' mean?','["Greater than","Less than","Equal to","Subtract"]',0,'Points right.','Open mouth first means big first.','2026-11-01 17:43:25',NULL,NULL);
