INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0195','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',5,'What does ''x > 5'' mean?','["x is any number strictly greater than 5.","x is exactly 5.","x is less than 5.","x is 5 or more."]',0,'Strictly bigger.','Greater than.','2026-11-01 17:43:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0196','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',5,'If x < 10, could x be 24?','["No","Yes","Only if it''s negative","Maybe"]',0,'Check the condition.','24 is not less than 10.','2026-11-01 17:43:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0197','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',5,'What does the symbol ''≤'' mean?','["Less than or equal to","Greater than or equal to","Not equal to","Approximately equal to"]',0,'Less or equal.','Combines < and =.','2026-11-01 17:43:26',NULL,NULL);
