INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0205','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Analyze: Why does an inequality like x < 10 have multiple solutions, while a linear equation like x + 2 = 10 has only one?','["An inequality defines a range of acceptable values (a condition), whereas an equation demands exact mathematical balance.","Equations are harder.","Inequalities are just guesses.","They both have one solution."]',0,'Many numbers are smaller than 10.','Range vs Point.','2026-11-01 17:43:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0206','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Critique: ''Bob says that if x ≥ 5, then x cannot be 5.''','["False, the ''or equal to'' line under the inequality symbol explicitly includes 5 as a valid solution.","True, it must be bigger than 5.","False, x MUST be 5.","True, 5 is excluded."]',0,'Look at the line under the >.','Greater than OR EQUAL TO.','2026-11-01 17:43:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0207','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Evaluate the expression comparison: 5 + 4 __ 6 + 3.','["=",">","<","≠"]',0,'Calculate first.','Both sides evaluate to 9.','2026-11-01 17:43:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0208','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Synthesize a real-world inequality: ''The speed limit is 50 mph, and you must not exceed it.'' Let s be your speed.','["s ≤ 50","s < 50","s = 50","s > 50"]',0,'Not exceeding means less than or equal to.','You can go 50, or less.','2026-11-01 17:43:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0209','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Analyze the logical inversion: If it is FALSE that A > B, what MUST be true?','["A ≤ B","A < B","A = B","A ≥ B"]',0,'Opposite of >.','If it''s not greater, it must be less than or exactly equal to.','2026-11-01 17:43:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0210','Maths','Introduction to Algebra','Subtopic 6: Understanding Equality and Inequality','Primary',10,'Evaluate: Why is it crucial to calculate the value of both expressions fully before placing a comparison symbol?','["Because complex expressions can be deceptive; surface-level numbers don''t dictate the final magnitude.","It isn''t crucial.","To waste time.","Because symbols are hard to draw."]',0,'Calculate first.','Don''t judge a book by its cover.','2026-11-01 17:43:28',NULL,NULL);
