INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0217','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',1,'What is an ''equation''?','["A mathematical statement containing an equals sign, showing two expressions are equal.","A phrase with no equals sign.","A word problem.","A fraction."]',0,'Has an ''=''.','It equates two things.','2026-11-01 17:43:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0218','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',1,'What does it mean to ''solve'' an equation?','["Find the unknown value (like x) that makes the equation true.","Write it down neatly.","Add all the numbers.","Erase the x."]',0,'Crack the code.','Find the missing piece.','2026-11-01 17:43:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0219','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',1,'Think of an equation like a balanced scale. What is the golden rule?','["Whatever operation you perform on one side, you must perform on the other side.","Always add.","Keep the x on the right.","Always multiply by 0."]',0,'What you do to one side...','Keep it balanced.','2026-11-01 17:43:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0220','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',1,'Solve: x + 7 = 15','["8","22","7","9"]',0,'Inverse operation.','Subtract 7 from both sides.','2026-11-01 17:43:29',NULL,NULL);
