INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0232','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Identify the correct inverse operation to solve: 6x = 60.','["Divide both sides by 6.","Multiply by 6.","Subtract 6.","Add 60."]',0,'Opposite of multiply.','Undo multiplication with division.','2026-11-01 17:43:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0233','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Check if x = 7 is the solution to x + 9 = 16.','["Yes, because 7 + 9 = 16.","No, it equals 15.","No, it equals 17.","Yes, because 16 - 7 = 8."]',0,'Plug it in.','Substitute and evaluate.','2026-11-01 17:43:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0234','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Translate and solve: ''Five identical packs contain 40 pencils altogether. How many in one pack (x)?''','["5x = 40, so x = 8.","x / 5 = 40, so x = 200.","x + 5 = 40, so x = 35.","5 - x = 40, so x = 35."]',0,'5 groups of x.','Equal groups implies multiplication.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0235','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Solve: 5x = 35','["7","30","40","175"]',0,'Inverse operation.','Divide both sides by 5.','2026-11-01 17:43:31',NULL,NULL);
