INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0238','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Identify the correct inverse operation to solve: 7x = 70.','["Divide both sides by 7.","Multiply by 7.","Subtract 7.","Add 70."]',0,'Opposite of multiply.','Undo multiplication with division.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0239','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Check if x = 7 is the solution to x + 9 = 16.','["Yes, because 7 + 9 = 16.","No, it equals 15.","No, it equals 17.","Yes, because 16 - 7 = 8."]',0,'Plug it in.','Substitute and evaluate.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0240','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',5,'Translate and solve: ''Five identical packs contain 40 pencils altogether. How many in one pack (x)?''','["5x = 40, so x = 8.","x / 5 = 40, so x = 200.","x + 5 = 40, so x = 35.","5 - x = 40, so x = 35."]',0,'5 groups of x.','Equal groups implies multiplication.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0241','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Analyze the ''balance scale'' metaphor: Why must an inverse operation be applied to BOTH sides of the equation?','["To isolate the variable while maintaining the fundamental equality of the statement; doing it to one side destroys the balance.","It doesn''t have to be applied to both sides.","To make the numbers bigger.","To turn an equation into an expression."]',0,'Keep it balanced.','Equality requires symmetry of action.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0242','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Critique: ''Bob solved x - 4 = 10 by subtracting 4 from 10 to get x = 6.''','["False, to isolate x you must apply the INVERSE operation (addition). x = 10 + 4 = 14.","True, subtraction is used for subtraction.","False, they should multiply.","True, 6 is the answer."]',0,'Do the opposite.','Undo -4 with +4.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0243','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Evaluate: Why is checking your solution by substituting it back into the original equation highly recommended?','["It acts as a self-correcting mechanism to catch arithmetic or logical errors made during the isolation steps.","It isn''t recommended.","It changes the answer.","It is required by law."]',0,'Verify your work.','Sanity check.','2026-11-01 17:43:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0244','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Synthesize the solution to this real-world problem: ''Diana had 24 marbles, gave some (x) away, and has 18 left.''','["24 - x = 18. Subtract 18 from 24 to find x = 6.","x - 24 = 18, x = 42.","24 + x = 18, x = -6.","24 / x = 18, x = 1.33."]',0,'Translate carefully.','Start with 24, subtract the unknown.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0245','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Analyze: If ax = b (where a is not 0), what is the general formula to solve for x?','["x = b / a","x = b * a","x = b - a","x = a / b"]',0,'Isolate x.','Divide both sides by the coefficient ''a''.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0246','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Critique: ''The equation 5x = 10 means 5 + x = 10.''','["False, juxtaposition of a number and a variable (5x) always denotes multiplication in algebra.","True, x represents 5.","False, it means 5 - x.","True, plus is invisible."]',0,'Number next to letter.','Implicit multiplication.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0247','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Analyze the ''balance scale'' metaphor: Why must an inverse operation be applied to BOTH sides of the equation?','["To isolate the variable while maintaining the fundamental equality of the statement; doing it to one side destroys the balance.","It doesn''t have to be applied to both sides.","To make the numbers bigger.","To turn an equation into an expression."]',0,'Keep it balanced.','Equality requires symmetry of action.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0248','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Critique: ''Hannah solved x - 4 = 10 by subtracting 4 from 10 to get x = 6.''','["False, to isolate x you must apply the INVERSE operation (addition). x = 10 + 4 = 14.","True, subtraction is used for subtraction.","False, they should multiply.","True, 6 is the answer."]',0,'Do the opposite.','Undo -4 with +4.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0249','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Evaluate: Why is checking your solution by substituting it back into the original equation highly recommended?','["It acts as a self-correcting mechanism to catch arithmetic or logical errors made during the isolation steps.","It isn''t recommended.","It changes the answer.","It is required by law."]',0,'Verify your work.','Sanity check.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0250','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Synthesize the solution to this real-world problem: ''Julia had 24 blocks, gave some (x) away, and has 18 left.''','["24 - x = 18. Subtract 18 from 24 to find x = 6.","x - 24 = 18, x = 42.","24 + x = 18, x = -6.","24 / x = 18, x = 1.33."]',0,'Translate carefully.','Start with 24, subtract the unknown.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0251','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Analyze: If ax = b (where a is not 0), what is the general formula to solve for x?','["x = b / a","x = b * a","x = b - a","x = a / b"]',0,'Isolate x.','Divide both sides by the coefficient ''a''.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0252','Maths','Introduction to Algebra','Subtopic 7: Solving Simple One-Step Equations','Primary',10,'Critique: ''The equation 5x = 10 means 5 + x = 10.''','["False, juxtaposition of a number and a variable (5x) always denotes multiplication in algebra.","True, x represents 5.","False, it means 5 - x.","True, plus is invisible."]',0,'Number next to letter.','Implicit multiplication.','2026-11-01 17:43:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0253','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'What does ''substitution'' mean in algebra?','["Replacing a variable (letter) with a given number so you can calculate the result.","Writing long words.","Guessing the answer.","Making expressions longer."]',0,'Like a substitute teacher taking a place.','Swapping a letter for a number.','2026-11-01 17:43:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0254','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'If the expression is x + 5, and you are told x = 3, what do you do?','["Replace x with 3, and calculate 3 + 5 = 8.","Solve for x.","Add 3 + 5 + x.","Change the 5 to a 3."]',0,'Plug it in.','Swap and calculate.','2026-11-01 17:43:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0255','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Find the value of a + 7 when a = 4.','["11","10","12","9"]',0,'Substitute and add.','4 + 7 = 11.','2026-11-01 17:43:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0256','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Find the value of b - 4 when b = 14.','["10","14","18","8"]',0,'Substitute and subtract.','14 - 4 = 10.','2026-11-01 17:43:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0257','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Does the order matter in subtraction? (e.g., if b=10, is b-4 the same as 4-b?)','["Yes, order matters. b - 4 is 10 - 4 = 6. (4 - 10 is not 6).","No, they are the same.","Only if b is negative.","Subtraction doesn''t exist."]',0,'Don''t flip subtraction.','You must keep the order written.','2026-11-01 17:43:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0258','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Find the value of 3x when x = 3.','["9","6","6","3"]',0,'Multiply.','3 * 3 = 9.','2026-11-01 17:43:33',NULL,NULL);
