INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0262','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Find the value of b - 4 when b = 15.','["11","15","19","9"]',0,'Substitute and subtract.','15 - 4 = 11.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0263','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Does the order matter in subtraction? (e.g., if b=10, is b-4 the same as 4-b?)','["Yes, order matters. b - 4 is 10 - 4 = 6. (4 - 10 is not 6).","No, they are the same.","Only if b is negative.","Subtraction doesn''t exist."]',0,'Don''t flip subtraction.','You must keep the order written.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0264','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',1,'Find the value of 3x when x = 4.','["12","7","8","3"]',0,'Multiply.','3 * 4 = 12.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0265','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2a + 5 when a = 4.','["13","8","9","18"]',0,'Order of operations: multiply before add.','Multiply first: 2*4=8, then add 5.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0266','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of x ÷ 2 when x = 14.','["7","14","12","28"]',0,'Divide by 2.','Replace x with 14, then halve it.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0267','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of b/4 + 3 when b = 20.','["8","5","23","20"]',0,'Divide before add.','20/4 = 5. 5 + 3 = 8.','2026-11-01 17:43:34',NULL,NULL);
