INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0269','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2a + b when a = 3 and b = 8.','["14","22","11","17"]',0,'Multiply, then add.','(2 * 3) + 8 = 6 + 8 = 14.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0270','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2(x + 3) when x = 4.','["14","11","24","10"]',0,'Brackets first!','Brackets first: 4+3=7. 2 * 7 = 14.','2026-11-01 17:43:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0271','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2a + 5 when a = 5.','["15","10","10","20"]',0,'Order of operations: multiply before add.','Multiply first: 2*5=10, then add 5.','2026-11-01 17:43:34',NULL,NULL);
