INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0273','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of b/4 + 3 when b = 20.','["8","5","23","20"]',0,'Divide before add.','20/4 = 5. 5 + 3 = 8.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0274','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of x + y when x = 10 and y = 7.','["17","70","3","12"]',0,'Substitute both.','Replace both variables with their specific values and add.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0275','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2a + b when a = 3 and b = 8.','["14","22","11","17"]',0,'Multiply, then add.','(2 * 3) + 8 = 6 + 8 = 14.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0276','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',5,'Find the value of 2(x + 3) when x = 4.','["14","11","24","10"]',0,'Brackets first!','Brackets first: 4+3=7. 2 * 7 = 14.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0277','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Analyze the difference between ''Evaluating an expression'' and ''Solving an equation''.','["Evaluating applies a given value to find a result; solving finds the unknown value that balances an equation.","They are exactly the same process.","Evaluating uses letters, solving uses numbers.","You evaluate equations and solve expressions."]',0,'Calculate vs Isolate.','Evaluation is calculation; solving is isolation.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0278','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Critique: ''{name} evaluated 2x + 3 for x=4 and got 14 by adding 4+3=7 then multiplying by 2.''','["False, order of operations dictates multiplication (2*4=8) must occur before addition (+3=11). The answer is 11.","True, left to right.","False, answer is 24.","True, addition is always first."]',0,'BODMAS/PEMDAS.','Multiply before add.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0279','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Evaluate the impact of brackets: Compare 2x + 3 and 2(x + 3) when x = 4.','["2x + 3 = 11, but 2(x + 3) = 14. Brackets force the addition to happen first.","They both equal 11.","They both equal 14.","Brackets mean subtract."]',0,'Check the grouping.','Brackets override normal order of operations.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0280','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Synthesize the evaluation of a real-world formula: Cost = 6n + 5, where n is number of items. Find cost for 4 items.','["29","24","15","44"]',0,'Multiply then add fixed cost.','Substitute n=4: (6 * 4) + 5.','2026-11-01 17:43:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0281','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Analyze: If you substitute x = 0 into ANY expression composed purely of variables multiplied together (e.g. 5xyz), what is the result?','["0","5","xyz","Undefined"]',0,'Multiply by zero.','Zero property of multiplication.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0282','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Synthesize: Evaluate 3a - 2b when a=5 and b=2.','["11","15","4","19"]',0,'Do both multiplications, then subtract.','(3*5) - (2*2) = 15 - 4 = 11.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0283','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Analyze the difference between ''Evaluating an expression'' and ''Solving an equation''.','["Evaluating applies a given value to find a result; solving finds the unknown value that balances an equation.","They are exactly the same process.","Evaluating uses letters, solving uses numbers.","You evaluate equations and solve expressions."]',0,'Calculate vs Isolate.','Evaluation is calculation; solving is isolation.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0284','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Critique: ''{name} evaluated 2x + 3 for x=4 and got 14 by adding 4+3=7 then multiplying by 2.''','["False, order of operations dictates multiplication (2*4=8) must occur before addition (+3=11). The answer is 11.","True, left to right.","False, answer is 24.","True, addition is always first."]',0,'BODMAS/PEMDAS.','Multiply before add.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0285','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Evaluate the impact of brackets: Compare 2x + 3 and 2(x + 3) when x = 4.','["2x + 3 = 11, but 2(x + 3) = 14. Brackets force the addition to happen first.","They both equal 11.","They both equal 14.","Brackets mean subtract."]',0,'Check the grouping.','Brackets override normal order of operations.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0286','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Synthesize the evaluation of a real-world formula: Cost = 7n + 5, where n is number of items. Find cost for 4 items.','["33","28","16","48"]',0,'Multiply then add fixed cost.','Substitute n=4: (7 * 4) + 5.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0287','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Analyze: If you substitute x = 0 into ANY expression composed purely of variables multiplied together (e.g. 5xyz), what is the result?','["0","5","xyz","Undefined"]',0,'Multiply by zero.','Zero property of multiplication.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0288','Maths','Introduction to Algebra','Subtopic 8: Substituting Values into Simple Expressions','Primary',10,'Synthesize: Evaluate 3a - 2b when a=5 and b=2.','["11","15","4","19"]',0,'Do both multiplications, then subtract.','(3*5) - (2*2) = 15 - 4 = 11.','2026-11-01 17:43:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0289','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'How can algebra help us describe a number pattern?','["We can use a variable (like ''n'') to represent the position of a number, making a formula to find ANY number in the pattern without counting.","It can''t.","By writing it in Roman numerals.","By erasing the numbers."]',0,'Using ''n'' for position.','Formulas predict the future.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0290','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'Look at the sequence: 6, 9, 12, 15... What is the simple rule?','["Add 3 each time.","Multiply by 3.","Add 6.","Subtract 3."]',0,'Check the gap.','The difference is +3.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0291','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'If ''n'' stands for the position in a sequence (1st, 2nd, 3rd), what does ''3n'' mean?','["Multiply the position number by 3.","Add 3 to the position number.","The 3rd number.","Thirty-something."]',0,'Implicit multiplication.','3 times n.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0292','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'Look at the pattern: 3, 6, 9, 12. If the rule is 3n, what is the 5th number (n=5)?','["15","18","12","5"]',0,'Substitute n=5.','3 x 5 = 15.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0293','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'Look at the sequence: 30, 25, 20, 15... What is the rule?','["Subtract 5.","Add 5.","Divide by 5.","Subtract 10."]',0,'Check the gap.','Going down by 5.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0294','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'If the rule for a pattern is 2n, what are the first three numbers (for n=1, n=2, n=3)?','["2, 4, 6","1, 2, 3","2, 22, 222","3, 4, 5"]',0,'Double the positions.','2x1, 2x2, 2x3.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0295','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'How can algebra help us describe a number pattern?','["We can use a variable (like ''n'') to represent the position of a number, making a formula to find ANY number in the pattern without counting.","It can''t.","By writing it in Roman numerals.","By erasing the numbers."]',0,'Using ''n'' for position.','Formulas predict the future.','2026-11-01 17:43:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0296','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'Look at the sequence: 9, 12, 15, 18... What is the simple rule?','["Add 3 each time.","Multiply by 3.","Add 6.","Subtract 3."]',0,'Check the gap.','The difference is +3.','2026-11-01 17:43:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0297','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',1,'If ''n'' stands for the position in a sequence (1st, 2nd, 3rd), what does ''3n'' mean?','["Multiply the position number by 3.","Add 3 to the position number.","The 3rd number.","Thirty-something."]',0,'Implicit multiplication.','3 times n.','2026-11-01 17:43:38',NULL,NULL);
