INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0301','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',5,'If a sequence has the algebraic rule 3n + 2, what is the 4th term (n=4)?','["14","12","16","24"]',0,'Substitute 4 for n.','3(4) + 2 = 12 + 2 = 14.','2026-11-01 17:43:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0302','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',5,'Look at the pattern: 5, 8, 11, 14, 17. The rule is 3n + 2. Check it for the 1st term (n=1).','["3(1) + 2 = 5.","1 + 2 = 3.","5 x 3 = 15.","3 + 5 = 8."]',0,'n=1.','Substitute 1 into the formula.','2026-11-01 17:43:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0303','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',5,'If a decreasing sequence has the rule 35 - 5n, what is the 1st term (n=1)?','["30","35","25","40"]',0,'Substitute n=1.','35 - 5(1) = 30.','2026-11-01 17:43:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0304','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',5,'Look at this shape pattern: Figure 1 has 1 square, Fig 2 has 2, Fig 3 has 3. What is the algebraic rule for the number of squares in figure ''n''?','["n","n + 1","2n","n^2"]',0,'They are identical.','The number of squares exactly matches the figure number.','2026-11-01 17:43:38',NULL,NULL);
