INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0320','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',10,'Synthesize the algebraic rule for the sequence: 6, 10, 14, 18, 22...','["4n + 2","n + 4","6n","4n - 2"]',0,'Find the multiplier, then the adjustment.','It goes up by 4, so it involves 4n. For n=1, 4(1)=4. We need 6, so add 2: 4n+2.','2026-11-01 17:43:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0321','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',10,'Evaluate the sequence: 3, 5, 7, 9, 11. Which algebraic rule fits?','["2n + 1","n + 2","3n","2n - 1"]',0,'Find multiplier and adjustment.','Goes up by 2 (2n). For n=1, 2(1)+1 = 3.','2026-11-01 17:43:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0322','Maths','Introduction to Algebra','Subtopic 9: Recognising Simple Algebraic Patterns','Primary',10,'Critique: ''{name} says that a short sequence can sometimes fit more than one mathematical rule.''','["True, e.g., 2, 4 could be 2n (multiples of 2) or 2^n (powers of 2). You must test the rule against ALL given terms.","False, there is only one true rule.","False, math is perfect.","True, but only if you subtract."]',0,'Verify with more data.','Limited data can lead to multiple hypotheses.','2026-11-01 17:43:40',NULL,NULL);
