INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0325','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',1,'What is a ''word problem''?','["A problem that describes a real-life situation using words and asks us to find a mathematical answer.","A spelling test.","A problem with no numbers.","A reading book."]',0,'Math story.','Math in a real-world story.','2026-11-01 17:43:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0326','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',1,'Read: ''Bob has some cookies. A friend gives them 5 more. They now have 12.'' What is the unknown?','["The number of {item} {name} had at first.","The 5 more.","The 12 total.","The friend."]',0,'What don''t you know?','Identify what you are trying to find.','2026-11-01 17:43:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0327','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',1,'If ''Charlie had x books, got 5 more, and now has 12'', which equation represents this?','["x + 5 = 12","x - 5 = 12","5x = 12","x / 5 = 12"]',0,'Translate to math.','''Got more'' means addition.','2026-11-01 17:43:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0328','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',1,'What is the first step in solving a word problem?','["Identify the unknown (decide what you need to find and use a variable like x).","Guess the answer.","Add all the numbers.","Give up."]',0,'Find the x.','Figure out what you are looking for.','2026-11-01 17:43:41',NULL,NULL);
