INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0339','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Write and solve: 6 identical packs have 42 pencils total. How many in one pack (x)?','["6x = 42; x = 7.","x / 6 = 42; x = 252.","x + 6 = 42; x = 36.","x - 6 = 42; x = 48."]',0,'6 times x.','Equal groups means multiply.','2026-11-01 17:43:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0340','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Write and solve: 56 stickers shared equally among x friends, each gets 8. How many friends?','["8x = 56; x = 7.","x / 8 = 56; x = 448.","x + 8 = 56; x = 48.","x - 8 = 56; x = 64."]',0,'8 times x.','Number of friends times 8 equals 56.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0341','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Solve this two-step problem: A notebook costs 4. Ethan buys x notebooks, plus a bag for 3. Total is 23. Equation: 4x + 3 = 23. What is x?','["5","6","20","26"]',0,'Undo addition, then multiply.','23 - 3 = 20. 20 / 4 = 5.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0342','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'What does ''7 less than a number (x)'' look like as an expression?','["x - 7","7 - x","x + 7","7x"]',0,'Order matters.','You start with x, and take away 7.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0343','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Solve: George has x books. Buys 8 more, now has 23. x + 8 = 23. What is x?','["15","31","16","14"]',0,'Subtract 8.','23 - 8 = 15.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0344','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Solve: Hannah has x money, spends 12, has 18 left. x - 12 = 18. What is x?','["30","6","20","28"]',0,'Add 12.','18 + 12 = 30.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0345','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Write and solve: 6 identical packs have 42 pencils total. How many in one pack (x)?','["6x = 42; x = 7.","x / 6 = 42; x = 252.","x + 6 = 42; x = 36.","x - 6 = 42; x = 48."]',0,'6 times x.','Equal groups means multiply.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0346','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Write and solve: 56 stickers shared equally among x friends, each gets 8. How many friends?','["8x = 56; x = 7.","x / 8 = 56; x = 448.","x + 8 = 56; x = 48.","x - 8 = 56; x = 64."]',0,'8 times x.','Number of friends times 8 equals 56.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0347','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'Solve this two-step problem: A notebook costs 4. Kevin buys x notebooks, plus a bag for 3. Total is 23. Equation: 4x + 3 = 23. What is x?','["5","6","20","26"]',0,'Undo addition, then multiply.','23 - 3 = 20. 20 / 4 = 5.','2026-11-01 17:43:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0348','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',5,'What does ''7 less than a number (x)'' look like as an expression?','["x - 7","7 - x","x + 7","7x"]',0,'Order matters.','You start with x, and take away 7.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0349','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Analyze the multi-step solution: 4x + 3 = 23. Why must you subtract 3 before dividing by 4?','["Key principle: Undo operations in reverse order of operations (reverse PEMDAS) to isolate the variable.","It''s just a random rule.","You should divide by 4 first.","Addition is always first."]',0,'Reverse order.','Untie the knot backwards.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0350','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Critique the mistake: ''A problem asks for the ORIGINAL amount of money. Bob calculates the final amount and stops.''','["False logic; you must clearly define the variable as the original amount (x) and ensure your final solved value answers the specific question asked.","True, final amount is always the answer.","False, they should have added.","True, original amounts don''t matter."]',0,'Check definitions.','Answer the question that was asked.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0351','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Synthesize the word problem: A cyclist travels at 12 km/h. Total distance is 60 km. How many hours (x)?','["12x = 60; x = 5 hours.","12 + x = 60; x = 48 hours.","x / 12 = 60; x = 720 hours.","60x = 12; x = 0.2 hours."]',0,'Multiply.','Speed x Time = Distance.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0352','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Synthesize: A child is 4 years younger than a sibling who is 13. How old is the child (x)?','["x + 4 = 13; x = 9.","x - 4 = 13; x = 17.","13 + 4 = x; x = 17.","4x = 13; x = 3.25."]',0,'Translate carefully.','Child''s age plus 4 equals 13.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0353','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Evaluate the risk of relying purely on ''keywords'' (like ''total'' or ''less'') to translate word problems.','["Keywords can be deceptive depending on sentence structure; translating requires holistic comprehension of the mathematical situation.","Keywords are flawless.","Keywords only work for addition.","You shouldn''t read the words at all."]',0,'Context is key.','Understand the story, don''t just hunt for words.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0354','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Analyze: Why is checking your answer by substituting it back into the word problem''s context important?','["It ensures the numerical answer is logically sound in reality (e.g., you can''t have negative apples or 1.5 people).","It isn''t important.","It changes the answer.","It wastes time."]',0,'Does it make sense?','Sanity check.','2026-11-01 17:43:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t7_global_0355','Maths','Introduction to Algebra','Subtopic 10: Solving Simple Word Problems Using Equations','Primary',10,'Analyze the multi-step solution: 4x + 3 = 23. Why must you subtract 3 before dividing by 4?','["Key principle: Undo operations in reverse order of operations (reverse PEMDAS) to isolate the variable.","It''s just a random rule.","You should divide by 4 first.","Addition is always first."]',0,'Reverse order.','Untie the knot backwards.','2026-11-01 17:43:44',NULL,NULL);
