INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0001','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'What exactly is a ''pattern''?','["An arrangement of numbers, shapes, or colours that follows a rule.","A random pile of items.","Only numbers counting up.","Something that never repeats."]',0,'It follows a rule.','A pattern follows a specific, predictable rule.','2026-11-01 17:45:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0002','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'If you have red, blue, red, blue... what color comes next?','["Red","Blue","Green","Yellow"]',0,'Follow the repeating colors.','The pattern alternates red then blue.','2026-11-01 17:45:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0003','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'What do we call the individual numbers or items in a sequence?','["Terms","Rules","Steps","Sums"]',0,'Vocabulary word.','The items in the list are called terms.','2026-11-01 17:45:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0004','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'If a pattern is: 1 block, 2 blocks, 3 blocks... what is the next term?','["4 blocks","5 blocks","1 block","3 blocks"]',0,'Count up by one.','Each step adds one block.','2026-11-01 17:45:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0005','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'Look at the pattern: Circle, Square, Circle, Square. What is the rule?','["The shapes alternate between Circle and Square.","Add one shape each time.","It is a growing pattern.","There is no rule."]',0,'What is repeating?','It''s a repeating pattern of two shapes.','2026-11-01 17:45:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0006','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',1,'What is a ''sequence''?','["An ordered list of items or numbers arranged according to a rule.","A shape.","A random color.","A single number."]',0,'An ordered list.','A sequence is a list that follows a rule.','2026-11-01 17:45:44',NULL,NULL);
