INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0013','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'What are the three important parts of a sequence?','["Terms, Rule, Next term","Numbers, Letters, Shapes","Addition, Subtraction, Multiplication","Start, Middle, End"]',0,'The parts that make it work.','A sequence consists of the terms themselves, the rule governing them, and predicting the next term.','2026-11-01 17:45:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0014','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'Find the next term: 4, 6, 8, 10, __','["12","11","14","9"]',0,'Add 2.','The rule is add 2.','2026-11-01 17:45:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0015','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'Find the next term: 23, 18, 13, 8, __','["3","7","-2","4"]',0,'Go down by 5.','The rule is subtract 5.','2026-11-01 17:45:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0016','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'What type of pattern is: 4, 14, 24, 34?','["Increasing pattern","Decreasing pattern","Repeating pattern","Shape pattern"]',0,'Going up.','The numbers are getting larger.','2026-11-01 17:45:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0017','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'What type of pattern is: Sun, Moon, Star, Sun, Moon, Star?','["Repeating pattern","Increasing pattern","Decreasing pattern","Number pattern"]',0,'It repeats.','The same group of items repeats over and over.','2026-11-01 17:45:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0018','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'Identify the rule: 5, 9, 13, 17.','["Add 4 each time.","Add 2 each time.","Subtract 4 each time.","Multiply by 4."]',0,'Find the difference.','The difference between terms is +4.','2026-11-01 17:45:45',NULL,NULL);
