INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0023','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'What type of pattern is: Sun, Moon, Star, Sun, Moon, Star?','["Repeating pattern","Increasing pattern","Decreasing pattern","Number pattern"]',0,'It repeats.','The same group of items repeats over and over.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0024','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',5,'Identify the rule: 6, 10, 14, 18.','["Add 4 each time.","Add 2 each time.","Subtract 4 each time.","Multiply by 4."]',0,'Find the difference.','The difference between terms is +4.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0025','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Analyze: Why is it dangerous to guess a pattern''s rule from just the first two terms (e.g. 2, 4...)?','["Because the rule could be ''add 2'' (2, 4, 6, 8) OR ''multiply by 2'' (2, 4, 8, 16). You need more terms to confirm.","It isn''t dangerous, it''s always ''add 2''.","Because numbers are unpredictable.","Because patterns only exist in shapes."]',0,'Add or multiply?','Multiple rules can fit the first two numbers.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0026','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Critique: ''Bob says that a decreasing pattern always ends in zero.''','["False, a decreasing pattern can go into negative numbers or fractions, and doesn''t stop unless specified.","True, numbers stop at zero.","True, if you subtract enough.","False, they go up."]',0,'Negative numbers exist.','Numbers continue past zero.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0027','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Synthesize the rule for this alternating pattern: 3, 10, 5, 12, 7, 14...','["The first sequence starts at 3 and adds 2; the second starts at 10 and adds 2.","Add 10.","Subtract 2.","Multiply by 2."]',0,'Look at every other number.','It interleaves two different sequences.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0028','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Evaluate: How does finding the ''difference'' between consecutive terms help identify a rule?','["If the difference is constant, it confirms an addition or subtraction rule. If not, it points toward multiplication/division or a multi-step rule.","It proves the pattern is wrong.","It only works for even numbers.","It finds the total sum."]',0,'Check the gap.','The difference is the first check for linear patterns.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0029','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Analyze: What is the defining characteristic of a ''growing pattern'' (e.g., 1 block, 3 blocks, 6 blocks)?','["The number of items increases at each step according to a mathematical rule, rather than just repeating a fixed group.","It just repeats the same thing.","It uses plants.","It gets smaller."]',0,'It gets bigger.','The physical arrangement expands mathematically.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0030','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Synthesize the next two terms: 1, 2, 4, 8, __, __','["16, 32","10, 12","12, 16","32, 64"]',0,'Double the numbers.','The rule is multiply by 2 (doubling).','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0031','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Analyze: Why is it dangerous to guess a pattern''s rule from just the first two terms (e.g. 2, 4...)?','["Because the rule could be ''add 2'' (2, 4, 6, 8) OR ''multiply by 2'' (2, 4, 8, 16). You need more terms to confirm.","It isn''t dangerous, it''s always ''add 2''.","Because numbers are unpredictable.","Because patterns only exist in shapes."]',0,'Add or multiply?','Multiple rules can fit the first two numbers.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0032','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Critique: ''Hannah says that a decreasing pattern always ends in zero.''','["False, a decreasing pattern can go into negative numbers or fractions, and doesn''t stop unless specified.","True, numbers stop at zero.","True, if you subtract enough.","False, they go up."]',0,'Negative numbers exist.','Numbers continue past zero.','2026-11-01 17:45:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0033','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Synthesize the rule for this alternating pattern: 4, 10, 6, 12, 8, 14...','["The first sequence starts at 4 and adds 2; the second starts at 10 and adds 2.","Add 10.","Subtract 2.","Multiply by 2."]',0,'Look at every other number.','It interleaves two different sequences.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0034','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Evaluate: How does finding the ''difference'' between consecutive terms help identify a rule?','["If the difference is constant, it confirms an addition or subtraction rule. If not, it points toward multiplication/division or a multi-step rule.","It proves the pattern is wrong.","It only works for even numbers.","It finds the total sum."]',0,'Check the gap.','The difference is the first check for linear patterns.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0035','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Analyze: What is the defining characteristic of a ''growing pattern'' (e.g., 1 block, 3 blocks, 6 blocks)?','["The number of items increases at each step according to a mathematical rule, rather than just repeating a fixed group.","It just repeats the same thing.","It uses plants.","It gets smaller."]',0,'It gets bigger.','The physical arrangement expands mathematically.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0036','Maths','Patterns and Sequences','Subtopic 1: Understanding Patterns and Sequences','Primary',10,'Synthesize the next two terms: 2, 4, 8, 16, __, __','["32, 64","20, 24","24, 32","64, 128"]',0,'Double the numbers.','The rule is multiply by 2 (doubling).','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0037','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'What is a ''repeating pattern''?','["A pattern where a group of items repeats in the exact same order over and over.","A pattern that gets bigger.","A pattern of just numbers.","A pattern that stops."]',0,'Loops over and over.','The same sequence loops repeatedly.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0038','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'What is the ''repeating unit''?','["The smallest group of items that repeats to form the pattern.","The last item in the pattern.","The first item only.","A type of shape."]',0,'The block that repeats.','It''s the core group that gets copied.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0039','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'Identify the repeating unit in: Red, Blue, Green, Red, Blue, Green.','["Red, Blue, Green","Red, Blue","Green, Red","Red, Green, Blue"]',0,'Find the chunk that loops.','This three-color group repeats.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0040','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'If a pattern is Clap, Tap, Clap, Tap... what comes next?','["Clap","Tap","Jump","Nothing"]',0,'Follow the loop.','The sequence alternates.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0041','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'Find the next shape: Circle, Square, Circle, Square, ___','["Circle","Square","Triangle","Star"]',0,'Back to the start of the unit.','It alternates back to Circle.','2026-11-01 17:45:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0042','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'If the repeating unit is 1, 2... what comes after 1?','["2","3","1","0"]',0,'Follow the unit.','The pattern is 1, 2, 1, 2.','2026-11-01 17:45:48',NULL,NULL);
