INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0048','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',1,'If the repeating unit is 2, 3... what comes after 2?','["3","4","2","0"]',0,'Follow the unit.','The pattern is 2, 3, 2, 3.','2026-11-01 17:45:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0049','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Identify the repeating unit: Triangle, Triangle, Circle, Triangle, Triangle, Circle.','["Triangle, Triangle, Circle","Triangle, Circle","Triangle","Circle, Triangle"]',0,'Look for where it restarts.','The group of three repeats.','2026-11-01 17:45:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0050','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Find the next two numbers: 2, 7, 2, 7, 2, __, __','["7, 2","2, 7","7, 7","2, 2"]',0,'Follow the cycle.','The pattern alternates between 2 and 7.','2026-11-01 17:45:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0051','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'What is missing? Red, ___, Red, Blue, Red, Blue.','["Blue","Red","Green","Yellow"]',0,'Look at the rest of the pattern.','The repeating unit is Red, Blue.','2026-11-01 17:45:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0052','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Find the missing item: Star, Star, Circle, ___, Star, Circle.','["Star","Circle","Square","Moon"]',0,'Look at the beginning.','The repeating unit is Star, Star, Circle.','2026-11-01 17:45:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0053','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'If the repeating unit is A, B, C, what is the 5th item?','["B","A","C","D"]',0,'Count it out.','A(1), B(2), C(3), A(4), B(5).','2026-11-01 17:45:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0054','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Fiona makes a pattern: 1, 2, 3, 1, 2, 3. What is the 7th number?','["1","2","3","4"]',0,'Restart the loop.','The cycle restarts at the 7th position.','2026-11-01 17:45:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0055','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Identify the repeating unit: Triangle, Triangle, Circle, Triangle, Triangle, Circle.','["Triangle, Triangle, Circle","Triangle, Circle","Triangle","Circle, Triangle"]',0,'Look for where it restarts.','The group of three repeats.','2026-11-01 17:45:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0056','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Find the next two numbers: 3, 8, 3, 8, 3, __, __','["8, 3","3, 8","8, 8","3, 3"]',0,'Follow the cycle.','The pattern alternates between 3 and 8.','2026-11-01 17:45:49',NULL,NULL);
