INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0059','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'If the repeating unit is A, B, C, what is the 5th item?','["B","A","C","D"]',0,'Count it out.','A(1), B(2), C(3), A(4), B(5).','2026-11-01 17:45:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0060','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',5,'Liam makes a pattern: 2, 3, 4, 2, 3, 4. What is the 7th number?','["2","3","4","5"]',0,'Restart the loop.','The cycle restarts at the 7th position.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0061','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Analyze: How do you find the 20th item in a repeating pattern with a unit of 3 items (A, B, C)?','["Divide 20 by 3 (6 R 2). The remainder is 2, so it is the 2nd item in the unit (B).","Count on your fingers up to 20.","It will always be A.","Multiply 20 by 3."]',0,'Division shortcut.','Use division and remainders to jump forward in repeating patterns.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0062','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Critique: ''Bob looked at Red, Red, Blue and said the repeating unit is just Red.''','["False, the repeating unit is the ENTIRE sequence that repeats (Red, Red, Blue).","True.","False, it is Blue.","True, because Red is first."]',0,'Find the full chunk.','The repeating unit must encompass the full cycle.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0063','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Synthesize the missing numbers: 3, 4, 3, __, 3, 4, __, 4.','["4, 3","3, 4","3, 3","4, 4"]',0,'Fill in the gaps.','The pattern is 3, 4, 3, 4.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0064','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Evaluate: Why is it important to check where the pattern currently ends before continuing it?','["To ensure you resume the repeating unit at the correct position, rather than blindly starting from the beginning again.","It doesn''t matter.","To make the pattern longer.","To change the rule."]',0,'Don''t just restart blindly.','You must pick up exactly where you left off.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0065','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Analyze: If a pattern is X, Y, Z, X, Y, Z... what will the 9th item be?','["Z (because 9 is perfectly divisible by 3, so it lands on the last item of the unit).","X","Y","W"]',0,'Think of multiples of 3.','Multiples of the unit size land on the last item.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0066','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Critique: ''Fiona thinks 1, 2, 3, 4, 5... is a repeating pattern because you count them every time.''','["False, it is an increasing sequence, not a repeating group of items.","True.","False, it is a decreasing pattern.","True, numbers repeat."]',0,'Does it loop?','The group itself does not loop back to the start.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0067','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Analyze: How do you find the 20th item in a repeating pattern with a unit of 3 items (A, B, C)?','["Divide 20 by 3 (6 R 2). The remainder is 2, so it is the 2nd item in the unit (B).","Count on your fingers up to 20.","It will always be A.","Multiply 20 by 3."]',0,'Division shortcut.','Use division and remainders to jump forward in repeating patterns.','2026-11-01 17:45:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0068','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Critique: ''Hannah looked at Red, Red, Blue and said the repeating unit is just Red.''','["False, the repeating unit is the ENTIRE sequence that repeats (Red, Red, Blue).","True.","False, it is Blue.","True, because Red is first."]',0,'Find the full chunk.','The repeating unit must encompass the full cycle.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0069','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Synthesize the missing numbers: 4, 5, 4, __, 4, 5, __, 5.','["5, 4","4, 5","4, 4","5, 5"]',0,'Fill in the gaps.','The pattern is 4, 5, 4, 5.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0070','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Evaluate: Why is it important to check where the pattern currently ends before continuing it?','["To ensure you resume the repeating unit at the correct position, rather than blindly starting from the beginning again.","It doesn''t matter.","To make the pattern longer.","To change the rule."]',0,'Don''t just restart blindly.','You must pick up exactly where you left off.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0071','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Analyze: If a pattern is X, Y, Z, X, Y, Z... what will the 9th item be?','["Z (because 9 is perfectly divisible by 3, so it lands on the last item of the unit).","X","Y","W"]',0,'Think of multiples of 3.','Multiples of the unit size land on the last item.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0072','Maths','Patterns and Sequences','Subtopic 2: Repeating Patterns','Primary',10,'Critique: ''Liam thinks 1, 2, 3, 4, 5... is a repeating pattern because you count them every time.''','["False, it is an increasing sequence, not a repeating group of items.","True.","False, it is a decreasing pattern.","True, numbers repeat."]',0,'Does it loop?','The group itself does not loop back to the start.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0073','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'What is an ''increasing'' number sequence?','["A sequence that moves towards larger numbers.","A sequence that moves towards smaller numbers.","A sequence that stays the same.","A sequence of only even numbers."]',0,'Going up.','Increasing means getting bigger.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0074','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'What is a ''decreasing'' number sequence?','["A sequence that moves towards smaller numbers.","A sequence that moves towards larger numbers.","A repeating pattern.","A sequence of shapes."]',0,'Going down.','Decreasing means getting smaller.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0075','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'Find the next number in this increasing sequence: 3, 5, 7, 9, __','["11","10","13","8"]',0,'Add 2.','Add 2.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0076','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'Find the next number in this decreasing sequence: 24, 19, 14, __','["9","12","16","4"]',0,'Subtract 5.','Subtract 5.','2026-11-01 17:45:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0077','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'What is the rule for this sequence: 10, 20, 30, 40?','["Add 10 each time.","Add 5 each time.","Subtract 10 each time.","Multiply by 2."]',0,'Count by 10s.','Going up by 10s.','2026-11-01 17:45:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0078','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',1,'If the rule is ''add 2'', and you start at 5, what is the next number?','["7","6","8","5"]',0,'Add the rule to 5.','5 + 2 = 7.','2026-11-01 17:45:52',NULL,NULL);
