INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0097','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Analyze the alternating pattern: 1, 10, 3, 20, 5, 30, __, __','["7, 40","9, 50","5, 40","7, 30"]',0,'Look at odd and even positions separately.','First group adds 2, second group adds 10.','2026-11-01 17:45:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0098','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Evaluate: Why must you check the rule against ALL given terms in a sequence before predicting the next one?','["A short sequence might deceptively fit an addition rule (e.g. 2, 4 -> +2) when it actually follows a multiplication rule (2, 4, 8 -> x2).","It isn''t necessary.","To practice math.","Because numbers change."]',0,'Don''t jump to conclusions.','Verify the rule works for the whole list.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0099','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Synthesize: Find the rule and next term for 3, 6, 11, 18, 27, __','["Add consecutive odd numbers (+3, +5, +7, +9). Next is add 11: 38.","Add 5: 32","Multiply by 2: 51","Add 9: 36"]',0,'Look at the differences between the differences!','The differences are increasing odd numbers.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0100','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Critique: ''Diana says the sequence 54, 49, 44... is an increasing pattern because 50 is a big number.''','["False, it is a decreasing pattern because the terms are getting smaller (subtracting 5), regardless of the starting size.","True.","False, it is repeating.","False, it is multiplying."]',0,'Are they going up or down?','Direction matters, not starting magnitude.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0101','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Analyze: What kind of pattern is 5, 50, 500, 5000?','["An increasing pattern using multiplication (x10).","An increasing pattern using addition (+10).","A repeating pattern.","A shape pattern."]',0,'Powers of 10.','Multiplying by 10 each step.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0102','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Evaluate: If a sequence decreases by a constant division rule, will it ever reach negative numbers?','["No, dividing a positive number repeatedly only produces smaller and smaller positive fractions/decimals, never crossing zero.","Yes.","Only if you divide by an even number.","Yes, very quickly."]',0,'Think about halving.','Division approaches zero but doesn''t cross it.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0103','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Analyze the alternating pattern: 2, 10, 4, 20, 6, 30, __, __','["8, 40","10, 50","6, 40","8, 30"]',0,'Look at odd and even positions separately.','First group adds 2, second group adds 10.','2026-11-01 17:45:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0104','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Evaluate: Why must you check the rule against ALL given terms in a sequence before predicting the next one?','["A short sequence might deceptively fit an addition rule (e.g. 2, 4 -> +2) when it actually follows a multiplication rule (2, 4, 8 -> x2).","It isn''t necessary.","To practice math.","Because numbers change."]',0,'Don''t jump to conclusions.','Verify the rule works for the whole list.','2026-11-01 17:45:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0105','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Synthesize: Find the rule and next term for 4, 7, 12, 19, 28, __','["Add consecutive odd numbers (+3, +5, +7, +9). Next is add 11: 39.","Add 5: 33","Multiply by 2: 52","Add 9: 37"]',0,'Look at the differences between the differences!','The differences are increasing odd numbers.','2026-11-01 17:45:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0106','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Critique: ''Julia says the sequence 55, 50, 45... is an increasing pattern because 50 is a big number.''','["False, it is a decreasing pattern because the terms are getting smaller (subtracting 5), regardless of the starting size.","True.","False, it is repeating.","False, it is multiplying."]',0,'Are they going up or down?','Direction matters, not starting magnitude.','2026-11-01 17:45:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0107','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Analyze: What kind of pattern is 1, 10, 100, 1000?','["An increasing pattern using multiplication (x10).","An increasing pattern using addition (+10).","A repeating pattern.","A shape pattern."]',0,'Powers of 10.','Multiplying by 10 each step.','2026-11-01 17:45:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0108','Maths','Patterns and Sequences','Subtopic 3: Number Patterns and Sequences','Primary',10,'Evaluate: If a sequence decreases by a constant division rule, will it ever reach negative numbers?','["No, dividing a positive number repeatedly only produces smaller and smaller positive fractions/decimals, never crossing zero.","Yes.","Only if you divide by an even number.","Yes, very quickly."]',0,'Think about halving.','Division approaches zero but doesn''t cross it.','2026-11-01 17:45:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0109','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',1,'What does ''skip counting'' mean?','["Counting forwards or backwards by a fixed number (like 2s or 5s) instead of counting one at a time.","Only odd numbers.","Skipping randomly.","Counting backwards only."]',0,'Giant steps.','Taking equal steps.','2026-11-01 17:45:56',NULL,NULL);
