INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0130','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',5,'What is the next number: 120, 100, 80, 60, __?','["40","50","70","20"]',0,'Count backwards by 20s.','Decreases by 20.','2026-11-01 17:45:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0131','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',5,'Kevin skip counts by 3s: 3, 6, 9, 12. What is the 6th number they say?','["18","15","21","24"]',0,'Keep going.','5th is 15. 6th is 18.','2026-11-01 17:45:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0132','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',5,'Find the missing number: 15, 30, 45, __, 75.','["60","50","55","70"]',0,'Add 15.','Counting by 15s.','2026-11-01 17:45:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0133','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Analyze how skip counting is mathematically linked to multiplication.','["Skip counting forwards by a number generates the sequence of positive multiples for that number (e.g., counting by 4s gives 1x4, 2x4, etc).","No relation.","Only used for division.","Only for odd numbers."]',0,'3 times 5 is counting by 5 three times.','It''s a way to construct multiplication tables.','2026-11-01 17:45:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0134','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Evaluate: If Bob starts at 19 and counts backwards by 5s, what are the next three numbers?','["14, 9, 4","14, 10, 6","24, 29, 34","17, 12, 7"]',0,'Subtract.','Subtract 5 continuously.','2026-11-01 17:45:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0135','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Critique: ''Charlie says skip counting by 3s starting from 4 (4, 7, 10...) gives the multiples of 3.''','["False, it gives a sequence that adds 3, but these are NOT the multiples of 3 (which must start at 3: 3, 6, 9).","True.","False, they are multiples of 4.","True, because the interval is 3."]',0,'Multiples start at the number.','Multiples must be exact products (starting from 0 or the number itself).','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0136','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Synthesize the practical application: If Diana counts 9 boxes containing 10 pencils each, how does skip counting find the total?','["Skip counting by 10s 9 times reaches 90, which is much faster than counting 1 by 1.","It doesn''t help.","Count backwards.","Multiply by 5."]',0,'Group counting.','Efficient grouping.','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0137','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Analyze: What is the 10th term when skip counting by 11s starting from 11?','["110","99","121","100"]',0,'Multiplication.','The nth term is the number times n.','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0138','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Evaluate: Why is skip counting backwards by 20s from 100 useful in real life?','["It perfectly models giving change or tracking remaining inventory in bulk.","It is only a game.","It builds rockets.","It doesn''t work."]',0,'Giving change.','Practical subtraction model.','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0139','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Analyze how skip counting is mathematically linked to multiplication.','["Skip counting forwards by a number generates the sequence of positive multiples for that number (e.g., counting by 4s gives 1x4, 2x4, etc).","No relation.","Only used for division.","Only for odd numbers."]',0,'3 times 5 is counting by 5 three times.','It''s a way to construct multiplication tables.','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0140','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Evaluate: If Hannah starts at 20 and counts backwards by 5s, what are the next three numbers?','["15, 10, 5","15, 11, 7","25, 30, 35","18, 13, 8"]',0,'Subtract.','Subtract 5 continuously.','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0141','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Critique: ''Ian says skip counting by 3s starting from 4 (4, 7, 10...) gives the multiples of 3.''','["False, it gives a sequence that adds 3, but these are NOT the multiples of 3 (which must start at 3: 3, 6, 9).","True.","False, they are multiples of 4.","True, because the interval is 3."]',0,'Multiples start at the number.','Multiples must be exact products (starting from 0 or the number itself).','2026-11-01 17:46:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0142','Maths','Patterns and Sequences','Subtopic 4: Skip Counting Patterns','Primary',10,'Synthesize the practical application: If Julia counts 10 boxes containing 10 bananas each, how does skip counting find the total?','["Skip counting by 10s 10 times reaches 100, which is much faster than counting 1 by 1.","It doesn''t help.","Count backwards.","Multiply by 5."]',0,'Group counting.','Efficient grouping.','2026-11-01 17:46:00',NULL,NULL);
