INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0145','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',1,'What does an ''increasing'' pattern do?','["It moves towards larger numbers.","It moves towards smaller numbers.","It stays exactly the same.","It only uses odd numbers."]',0,'Going up.','Increasing means getting bigger.','2026-11-01 17:46:01',NULL,NULL);
