INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0164','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',5,'Find the rule and next number: 80, 70, 60, __','["Subtract 10; next is 50","Subtract 5; next is 55","Add 10; next is 70","Divide by 2; next is 45"]',0,'Going down by tens.','The difference is -10.','2026-11-01 17:46:03',NULL,NULL);
