INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0169','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Analyze: How do you differentiate between an increasing pattern that adds vs one that multiplies?','["Addition patterns have constant differences (+2, +2, +2), while multiplication patterns grow exponentially and the differences get larger (+2, +4, +8).","You can''t tell.","Multiplication is always even.","Addition is faster."]',0,'Constant gap vs Growing gap.','Look at the gap between the gaps.','2026-11-01 17:46:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0170','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Synthesize the rule and next term for 2, 5, 10, 17, 26, __','["Add consecutive odd numbers (+3, +5, +7, +9). Next is add 11: 37.","Add 5: 31","Multiply by 2: 50","Add 9: 35"]',0,'Look at the differences between the differences!','The differences are increasing odd numbers.','2026-11-01 17:46:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0171','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Critique: ''Charlie says the sequence 53, 48, 43... is an increasing pattern because 50 is a big number.''','["False, it is a decreasing pattern because the terms are getting smaller (subtracting 5), regardless of the starting size.","True.","False, it is repeating.","False, it is multiplying."]',0,'Are they going up or down?','Direction matters, not starting magnitude.','2026-11-01 17:46:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0172','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Evaluate: If a sequence decreases by a constant division rule (e.g. dividing by 2), will it ever reach negative numbers?','["No, dividing a positive number repeatedly only produces smaller and smaller positive fractions/decimals, never crossing zero.","Yes.","Only if you divide by an even number.","Yes, very quickly."]',0,'Think about halving.','Division approaches zero but doesn''t cross it.','2026-11-01 17:46:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0173','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Analyze the alternating pattern: 5, 50, 7, 60, 9, 70, __, __','["11, 80","13, 90","9, 90","11, 70"]',0,'Look at odd and even positions separately.','First group adds 2, second group adds 10.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0174','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Synthesize a real-world scenario for a decreasing division pattern.','["Sharing a quantity in half repeatedly (e.g., a tournament bracket starting with 64 teams, then 32, 16, 8, 4, 2).","Saving $5 a week.","A repeating flashing light.","None exist."]',0,'Halving.','Exponential decay or bracket structures.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0175','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Analyze: How do you differentiate between an increasing pattern that adds vs one that multiplies?','["Addition patterns have constant differences (+2, +2, +2), while multiplication patterns grow exponentially and the differences get larger (+2, +4, +8).","You can''t tell.","Multiplication is always even.","Addition is faster."]',0,'Constant gap vs Growing gap.','Look at the gap between the gaps.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0176','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Synthesize the rule and next term for 3, 6, 11, 18, 27, __','["Add consecutive odd numbers (+3, +5, +7, +9). Next is add 11: 38.","Add 5: 32","Multiply by 2: 51","Add 9: 36"]',0,'Look at the differences between the differences!','The differences are increasing odd numbers.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0177','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Critique: ''Ian says the sequence 54, 49, 44... is an increasing pattern because 50 is a big number.''','["False, it is a decreasing pattern because the terms are getting smaller (subtracting 5), regardless of the starting size.","True.","False, it is repeating.","False, it is multiplying."]',0,'Are they going up or down?','Direction matters, not starting magnitude.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0178','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Evaluate: If a sequence decreases by a constant division rule (e.g. dividing by 2), will it ever reach negative numbers?','["No, dividing a positive number repeatedly only produces smaller and smaller positive fractions/decimals, never crossing zero.","Yes.","Only if you divide by an even number.","Yes, very quickly."]',0,'Think about halving.','Division approaches zero but doesn''t cross it.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0179','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Analyze the alternating pattern: 1, 10, 3, 20, 5, 30, __, __','["7, 40","9, 50","5, 50","7, 30"]',0,'Look at odd and even positions separately.','First group adds 2, second group adds 10.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0180','Maths','Patterns and Sequences','Subtopic 5: Increasing and Decreasing Patterns','Primary',10,'Synthesize a real-world scenario for a decreasing division pattern.','["Sharing a quantity in half repeatedly (e.g., a tournament bracket starting with 64 teams, then 32, 16, 8, 4, 2).","Saving $5 a week.","A repeating flashing light.","None exist."]',0,'Halving.','Exponential decay or bracket structures.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0181','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',1,'What is an ''arithmetic operation''?','["A calculation using addition, subtraction, multiplication, or division.","A shape.","A color pattern.","A roman numeral."]',0,'Math symbols.','It''s the basic math actions.','2026-11-01 17:46:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0182','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',1,'Identify the rule for this sequence: 3, 7, 11, 15, 19.','["Add 4","Subtract 4","Multiply 2","Add 3"]',0,'Check the gap.','It goes up by 4 each time.','2026-11-01 17:46:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0183','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',1,'Identify the rule for this sequence: 40, 35, 30, 25, 20.','["Subtract 5","Add 5","Divide 2","Subtract 10"]',0,'Check the gap.','It goes down by 5 each time.','2026-11-01 17:46:05',NULL,NULL);
