INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0195','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',5,'Identify the alternating rule: 1, 3, 7, 9, 13, 15...','["Add 2, then add 4.","Add 2, then subtract 1.","Multiply by 3.","Add 2 only."]',0,'Look at the gaps.','+2, +4, +2, +4.','2026-11-01 17:46:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0196','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',5,'Find the next number for this alternating rule (Multiply by 2, then add 1): 2, 5, 10, 21, 42, __','["85","84","43","44"]',0,'Careful with the alternating steps.','Next step is add 1, wait, 21x2=42, so next is 42x2+1? No, the rule is (x2+1) applied as ONE step? Ah, notes say: 2x2+1=5, 5x2=10, 10x2+1=21, 21x2=42. Next is 42x2+1=85.','2026-11-01 17:46:06',NULL,NULL);
