INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0205','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Analyze the sequence: 4, 12, 36, 108... What is the rule and the next term?','["Multiply by 3; next is 324.","Add 8; next is 116.","Multiply by 4; next is 432.","Add 24; next is 132."]',0,'Check multiplication.','108 x 3 = 324.','2026-11-01 17:46:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0206','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Evaluate: Why must you check the rule against EVERY given term in a sequence?','["A short sequence can sometimes fit more than one possible rule (e.g. 2, 4 could be +2 or x2); checking all terms isolates the consistent rule.","It isn''t necessary.","To practice math.","Because numbers change."]',0,'Don''t jump to conclusions.','Verify the rule works for the whole list.','2026-11-01 17:46:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0207','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Synthesize the alternating sequence: 1, 10, 2, 20, 3, 30, __, __','["4, 40","4, 31","31, 4","40, 4"]',0,'Look at odd/even positions.','Interleaved sequences: 1,2,3,4 and 10,20,30,40.','2026-11-01 17:46:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0208','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Critique: ''Diana says that any sequence that adds 5 will always end in a 0 or 5.''','["False, it only ends in 0 or 5 if it started on a number ending in 0 or 5 (e.g., starting at 2 gives 2, 7, 12, 17).","True, that is the rule for 5.","False, it always ends in 5.","True, because 5 is odd."]',0,'What if you start at 2?','The starting number matters!','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0209','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Analyze the real-world application: If a machine produces 62 items every hour, what arithmetic pattern does cumulative production follow?','["An increasing pattern using addition (+62).","Multiplication by 62.","A repeating pattern.","Decreasing subtraction."]',0,'Cumulative means adding up.','Adding the same amount each hour.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0210','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Synthesize: Find the rule and next term for 1, 2, 4, 7, 11, __','["Add consecutive integers (+1, +2, +3, +4). Next is +5: 16.","Add 3: 14","Multiply by 2: 21","Add 4: 15"]',0,'Look at the differences between the differences!','The differences are increasing by 1.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0211','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Analyze the sequence: 4, 12, 36, 108... What is the rule and the next term?','["Multiply by 3; next is 324.","Add 8; next is 116.","Multiply by 4; next is 432.","Add 24; next is 132."]',0,'Check multiplication.','108 x 3 = 324.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0212','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Evaluate: Why must you check the rule against EVERY given term in a sequence?','["A short sequence can sometimes fit more than one possible rule (e.g. 2, 4 could be +2 or x2); checking all terms isolates the consistent rule.","It isn''t necessary.","To practice math.","Because numbers change."]',0,'Don''t jump to conclusions.','Verify the rule works for the whole list.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0213','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Synthesize the alternating sequence: 1, 10, 2, 20, 3, 30, __, __','["4, 40","4, 31","31, 4","40, 4"]',0,'Look at odd/even positions.','Interleaved sequences: 1,2,3,4 and 10,20,30,40.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0214','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Critique: ''Julia says that any sequence that adds 5 will always end in a 0 or 5.''','["False, it only ends in 0 or 5 if it started on a number ending in 0 or 5 (e.g., starting at 2 gives 2, 7, 12, 17).","True, that is the rule for 5.","False, it always ends in 5.","True, because 5 is odd."]',0,'What if you start at 2?','The starting number matters!','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0215','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Analyze the real-world application: If a machine produces 22 items every hour, what arithmetic pattern does cumulative production follow?','["An increasing pattern using addition (+22).","Multiplication by 22.","A repeating pattern.","Decreasing subtraction."]',0,'Cumulative means adding up.','Adding the same amount each hour.','2026-11-01 17:46:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0216','Maths','Patterns and Sequences','Subtopic 6: Patterns Using Arithmetic Operations','Primary',10,'Synthesize: Find the rule and next term for 2, 3, 5, 8, 12, __','["Add consecutive integers (+1, +2, +3, +4). Next is +5: 17.","Add 3: 15","Multiply by 2: 22","Add 4: 16"]',0,'Look at the differences between the differences!','The differences are increasing by 1.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0217','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'What is a ''shape pattern''?','["An arrangement of shapes that follows a rule.","A random pile of shapes.","Only squares.","Shapes that never repeat."]',0,'It has a rule.','It follows a specific, predictable rule.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0218','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'If a pattern is Circle, Square, Circle, Square... what comes next?','["Circle","Square","Triangle","Star"]',0,'Follow the loop.','It alternates.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0219','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'Look at this color pattern: Red, Yellow, Green, Red, Yellow, Green... What comes after Red?','["Yellow","Green","Red","Blue"]',0,'Find the sequence.','The unit is Red, Yellow, Green.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0220','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'What is a ''growing pattern''?','["A pattern that adds shapes or objects at each step.","A pattern that repeats the same thing.","A pattern that shrinks.","A pattern of only colors."]',0,'Grows.','It gets bigger.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0221','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'If a growing pattern starts with 1 dot, then 2 dots, then 3 dots, what is the rule?','["Add one dot each time.","Repeat 1 dot.","Subtract one dot.","Multiply by 2."]',0,'Count them.','It goes 1, 2, 3.','2026-11-01 17:46:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0222','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'Which of these is a repeating pattern?','["Star, Moon, Star, Moon","1 dot, 2 dots, 3 dots","Big, bigger, biggest","Small square, large square, huge square"]',0,'Loops.','The same group loops.','2026-11-01 17:46:09',NULL,NULL);
