INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0227','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'If a growing pattern starts with 1 dot, then 2 dots, then 3 dots, what is the rule?','["Add one dot each time.","Repeat 1 dot.","Subtract one dot.","Multiply by 2."]',0,'Count them.','It goes 1, 2, 3.','2026-11-01 17:46:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0228','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',1,'Which of these is a repeating pattern?','["Star, Moon, Star, Moon","1 dot, 2 dots, 3 dots","Big, bigger, biggest","Small square, large square, huge square"]',0,'Loops.','The same group loops.','2026-11-01 17:46:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0229','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',5,'Identify the repeating unit: Triangle, Circle, Square, Triangle, Circle, Square.','["Triangle, Circle, Square","Triangle, Circle","Triangle","Circle, Square"]',0,'Look for where it restarts.','The group of three repeats.','2026-11-01 17:46:10',NULL,NULL);
