INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0232','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',5,'What kind of pattern is: Large square, Medium square, Small square?','["A pattern using size (decreasing).","A repeating color pattern.","A growing shape pattern.","Symmetry."]',0,'Check the sizes.','The shapes are getting smaller.','2026-11-01 17:46:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0233','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',5,'If an arrow pattern goes ↑, →, ↓, ←, what is the rule?','["The arrow rotates a quarter-turn clockwise each time.","It repeats ↑.","It is random.","It flips upside down."]',0,'Watch the direction.','It''s spinning.','2026-11-01 17:46:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0234','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',5,'In the pattern: ■, ■■, ■■■, ■■■■. What is the rule?','["Add one square each time.","Add two squares.","Multiply by 2.","Repeat."]',0,'Count them.','1, 2, 3, 4.','2026-11-01 17:46:11',NULL,NULL);
