INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0240','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',5,'In the pattern: ■, ■■, ■■■, ■■■■. What is the rule?','["Add one square each time.","Add two squares.","Multiply by 2.","Repeat."]',0,'Count them.','1, 2, 3, 4.','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0241','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Analyze: How is a ''symmetrical'' picture pattern structured (e.g. Circle, Square, Triangle, Square, Circle)?','["The sequence mirrors itself around a central point or line.","It repeats the same shape forever.","It only uses primary colors.","It grows exponentially."]',0,'Like a mirror.','It looks the same forwards and backwards.','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0242','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Critique the mistake: ''Bob looked at Red Triangle, Blue Square, Green Circle, and said the rule is just Red, Blue, Green.''','["False, they looked only at color and ignored the changing shapes.","True, color is all that matters.","False, the rule is only about shapes.","True, patterns only have one rule."]',0,'Don''t ignore details.','Visual patterns often combine multiple attributes (color AND shape).','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0243','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Evaluate: Why is it important to observe *several* steps of a growing pattern before deciding the rule?','["Because adding shapes doesn''t always mean adding a constant amount; it could be growing exponentially or geometrically (e.g. 1, 2, 6).","It isn''t important.","To practice drawing.","Because shapes change color."]',0,'Verify the growth rate.','Don''t assume it''s just ''+1''.','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0244','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Synthesize the next item in this rotational pattern: 🕛, 🕒, 🕕, 🕘, ___','["🕛 (12 o''clock, quarter-turn clockwise).","🕐","🕕","🕒"]',0,'Follow the clock hand.','Rotating 90 degrees clockwise each step.','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0245','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Analyze the real-world application of repeating visual patterns.','["They are used in floor tiles, clothing stripes, and architectural designs to create organized, predictable aesthetics.","They are used for secret codes.","They only exist in math books.","They prevent earthquakes."]',0,'Look at a brick wall.','Design and art heavily rely on visual patterns.','2026-11-01 17:46:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0246','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Synthesize: If a pattern rule is ''Add a row of dots equal to the new step number'' (Step 1: 1 dot, Step 2: 3 dots, Step 3: 6 dots). What are these numbers called?','["Triangular numbers.","Square numbers.","Prime numbers.","Even numbers."]',0,'Look up triangular numbers.','They form a triangle shape (1, 1+2, 1+2+3).','2026-11-01 17:46:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0247','Maths','Patterns and Sequences','Subtopic 7: Shape and Picture Patterns','Primary',10,'Analyze: How is a ''symmetrical'' picture pattern structured (e.g. Circle, Square, Triangle, Square, Circle)?','["The sequence mirrors itself around a central point or line.","It repeats the same shape forever.","It only uses primary colors.","It grows exponentially."]',0,'Like a mirror.','It looks the same forwards and backwards.','2026-11-01 17:46:13',NULL,NULL);
