INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0279','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Analyze this sequence with two interleaved rules: 1, 10, 2, 20, 3, 30, __, 40.','["4","400","5","31"]',0,'Look at every other number.','Odd-positioned terms are 1, 2, 3, 4. Even-positioned are 10, 20, 30, 40.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0280','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Critique the mistake: ''Guessing the missing number without finding the rule first.''','["It leads to errors because you assume a simple addition rule when it might be multiplication, division, or alternating.","It is the fastest and best method.","It only works for odd numbers.","It is required in math."]',0,'Don''t guess.','Always define the rule mathematically first.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0281','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Synthesize the missing term: 5, 8, 13, __, 29, 40','["20","19","21","17"]',0,'Increasing odd differences.','Differences are +3, +5, +7, +9, +11. So {n+8} + 7 = {n+15}.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0282','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Evaluate the real-world scenario: ''A timer shows 30, 25, ___, 15.'' What is the missing number and rule?','["20; The rule is a decreasing pattern subtracting 5.","20; The rule is adding 5.","24; The rule is subtracting 6.","10; The rule is dividing by 2."]',0,'Subtract 5.','Countdowns are decreasing patterns.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0283','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Evaluate: Why is it crucial to check the numbers on BOTH sides of a missing number in the middle of a sequence?','["To verify that your hypothesized rule actually connects perfectly to the rest of the established sequence.","It isn''t crucial.","To make the math harder.","Because numbers change."]',0,'Does the puzzle piece fit?','You must check your work.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0284','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Synthesize the missing numbers in this alternating pattern: 2, 5, 7, 10, 12, __, __','["15, 17","14, 16","15, 18","14, 17"]',0,'Alternating rule.','The changes are +3, +2, +3, +2.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0285','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Analyze this sequence with two interleaved rules: 1, 10, 2, 20, 3, 30, __, 40.','["4","400","5","31"]',0,'Look at every other number.','Odd-positioned terms are 1, 2, 3, 4. Even-positioned are 10, 20, 30, 40.','2026-11-01 17:46:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0286','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Critique the mistake: ''Guessing the missing number without finding the rule first.''','["It leads to errors because you assume a simple addition rule when it might be multiplication, division, or alternating.","It is the fastest and best method.","It only works for odd numbers.","It is required in math."]',0,'Don''t guess.','Always define the rule mathematically first.','2026-11-01 17:46:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0287','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Synthesize the missing term: 1, 4, 9, __, 25, 36','["16","15","17","13"]',0,'Increasing odd differences.','Differences are +3, +5, +7, +9, +11. So {n+8} + 7 = {n+15}.','2026-11-01 17:46:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0288','Maths','Patterns and Sequences','Subtopic 8: Finding Missing Numbers in Patterns','Primary',10,'Evaluate the real-world scenario: ''A timer shows 30, 25, ___, 15.'' What is the missing number and rule?','["20; The rule is a decreasing pattern subtracting 5.","20; The rule is adding 5.","24; The rule is subtracting 6.","10; The rule is dividing by 2."]',0,'Subtract 5.','Countdowns are decreasing patterns.','2026-11-01 17:46:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0289','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',1,'What is an ''input-output number machine''?','["A machine that takes a number in, follows a rule, and gives a new number out.","A calculator that prints money.","A machine that breaks numbers.","A random number generator."]',0,'In -> Rule -> Out.','It applies a mathematical rule to an input.','2026-11-01 17:46:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0290','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',1,'If the rule is ''Add 3'', and the input is 5, what is the output?','["8","2","15","53"]',0,'Apply the rule.','5 + 3 = 8.','2026-11-01 17:46:18',NULL,NULL);
