INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0303','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',5,'If you know the rule and the output, how do you find the missing input?','["Work backwards using the opposite (inverse) operation.","Guess.","Multiply them.","Add them."]',0,'Go in reverse.','Inverse operations reverse the machine.','2026-11-01 17:46:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0304','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',5,'Rule: Multiply by 4. Output is 28. What was the input?','["7","32","24","112"]',0,'Inverse of multiply.','Work backwards: 28 / 4 = 7.','2026-11-01 17:46:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0305','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',5,'Rule: Add 5. Output is 20. What was the input?','["15","25","10","20"]',0,'Inverse of add.','Work backwards: 20 - 5 = 15.','2026-11-01 17:46:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0306','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',5,'Two-step rule: Multiply by 2, then add 3. Input is 4. Output?','["11","14","20","5"]',0,'Do step 1, then step 2.','(4x2)+3 = 8+3 = 11.','2026-11-01 17:46:20',NULL,NULL);
