INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0312','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',5,'Two-step rule: Multiply by 2, then add 3. Input is 4. Output?','["11","14","20","5"]',0,'Do step 1, then step 2.','(4x2)+3 = 8+3 = 11.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0313','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Evaluate: Why must you NOT add before multiplying in a two-step machine (e.g. ''Multiply by 2, then add 3'')?','["You must follow the machine''s rules in the specific order given, otherwise you alter the mathematical function.","Because addition is bad.","Because multiplication is easier.","You should add first."]',0,'Follow the flow.','The machine processes sequentially.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0314','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Synthesize working backwards through two steps: Rule is ''Multiply by 2, then add 3''. Output is 15. Input?','["6","9","24","12"]',0,'Undo the last step first.','Reverse order and operations: 15 - 3 = 12. 12 / 2 = 6.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0315','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Analyze the real-world application: If one ticket costs 8 units, the rule is ''Multiply by 8''. What is the input?','["The number of tickets being purchased.","The total cost.","The number 8.","The change given."]',0,'What are you putting into the equation?','Input (tickets) -> Rule (x8) -> Output (Total Cost).','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0316','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Synthesize the rule: Inputs: 2, 4, 6. Outputs: 5, 9, 13. What is the two-step rule?','["Multiply by 2, then add 1.","Add 3.","Multiply by 3, subtract 1.","Add 5."]',0,'Try combinations of x and +.','2x2+1=5. 4x2+1=9. 6x2+1=13.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0317','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Evaluate: A machine has Rule 1: ''Add 5'' and Rule 2: ''Multiply by 2''. Input is 5. Output?','["20","15","35","15"]',0,'Sequential logic.','(5 + 5) x 2.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0318','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Critique: ''Fiona says to work backwards through ''Add 5, then Multiply by 2'', you should Divide by 2, then Add 5.''','["False, you must Divide by 2, then SUBTRACT 5.","True.","False, Subtract 5 then Divide by 2.","False, Multiply by 2 then Add 5."]',0,'Opposite operation.','Use the inverse operation for every step.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0319','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Evaluate: Why must you NOT add before multiplying in a two-step machine (e.g. ''Multiply by 2, then add 3'')?','["You must follow the machine''s rules in the specific order given, otherwise you alter the mathematical function.","Because addition is bad.","Because multiplication is easier.","You should add first."]',0,'Follow the flow.','The machine processes sequentially.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0320','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Synthesize working backwards through two steps: Rule is ''Multiply by 2, then add 3''. Output is 15. Input?','["6","9","24","12"]',0,'Undo the last step first.','Reverse order and operations: 15 - 3 = 12. 12 / 2 = 6.','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0321','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Analyze the real-world application: If one ticket costs 8 units, the rule is ''Multiply by 8''. What is the input?','["The number of tickets being purchased.","The total cost.","The number 8.","The change given."]',0,'What are you putting into the equation?','Input (tickets) -> Rule (x8) -> Output (Total Cost).','2026-11-01 17:46:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0322','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Synthesize the rule: Inputs: 2, 4, 6. Outputs: 5, 9, 13. What is the two-step rule?','["Multiply by 2, then add 1.","Add 3.","Multiply by 3, subtract 1.","Add 5."]',0,'Try combinations of x and +.','2x2+1=5. 4x2+1=9. 6x2+1=13.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0323','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Evaluate: A machine has Rule 1: ''Add 5'' and Rule 2: ''Multiply by 2''. Input is 1. Output?','["12","7","15","11"]',0,'Sequential logic.','(1 + 5) x 2.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0324','Maths','Patterns and Sequences','Subtopic 9: Input–Output Rules and Number Machines','Primary',10,'Critique: ''Liam says to work backwards through ''Add 5, then Multiply by 2'', you should Divide by 2, then Add 5.''','["False, you must Divide by 2, then SUBTRACT 5.","True.","False, Subtract 5 then Divide by 2.","False, Multiply by 2 then Add 5."]',0,'Opposite operation.','Use the inverse operation for every step.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0325','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'What is a ''pattern problem''?','["A problem where numbers or shapes follow a rule, and you must discover it to find the answer.","A problem with no solution.","A spelling test.","A random guess."]',0,'Find the rule.','You have to crack the code.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0326','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'What is the first step in solving a pattern problem?','["Observe carefully: look at the numbers, shapes, or objects.","Guess the answer.","Add everything.","Give up."]',0,'Look before you leap.','You must look closely first.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0327','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'If a pattern starts at 3 and the rule is ''add 5'', what are the next numbers?','["3, 8, 13, 18, 23...","3, 5, 8, 11...","3, 15, 75...","3, -2, -7..."]',0,'3+5.','Keep adding 5.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0328','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'If a pattern starts at 30 and the rule is ''subtract 4'', what are the next numbers?','["30, 26, 22, 18, 14...","30, 34, 38...","30, 25, 20...","30, 20, 10..."]',0,'30-4.','Keep taking away 4.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0329','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'If Ethan wants to create their own pattern, what two things do they need to choose first?','["A starting number/shape and a rule.","An ending number and a letter.","A color and a sound.","Two rules."]',0,'Start and Rule.','You need a beginning and a direction.','2026-11-01 17:46:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0330','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',1,'What does ''predict'' mean in a pattern problem?','["To use the rule to determine what is likely to come next.","To guess randomly.","To stop counting.","To change the rule."]',0,'Look ahead.','Make an educated calculation for the future.','2026-11-01 17:46:22',NULL,NULL);
