INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0337','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',5,'A gardener plants flowers: Row 1 has 4, Row 2 has 7, Row 3 has 10. How many in Row 5?','["16","13","19","20"]',0,'Keep adding 3.','Rule is add 3. Row 4=13, Row 5=16.','2026-11-01 17:46:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0338','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',5,'A craft design uses: Circle, Square, Triangle, repeat. What is the 5th shape?','["Square","Circle","Triangle","Star"]',0,'Count it out.','C(1), S(2), T(3), C(4), S(5).','2026-11-01 17:46:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0339','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',5,'Charlie saves 5 coins day 1, 10 coins day 2, 15 day 3. How many on day 6?','["30","25","35","20"]',0,'6 x 5.','Rule is add 5. Day 6 is 5x6=30.','2026-11-01 17:46:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0340','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',5,'A library has 12 books on shelf 1. Each shelf below has 4 more books. Books on shelf 4?','["24","20","28","16"]',0,'Add 4 three times.','12, 16, 20, 24.','2026-11-01 17:46:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0341','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',5,'Find the missing numbers in this alternating pattern: 2, 10, 3, 11, 4, 12, __, __','["5, 13","6, 14","5, 14","4, 13"]',0,'Look at odd/even positions.','Odd pos: +1. Even pos: +1.','2026-11-01 17:46:24',NULL,NULL);
