INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0349','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Evaluate the 5-step method (Observe, Find Rule, Apply, Check, Explain). Why is ''Check'' important?','["To verify that your hypothesized rule consistently applies to EVERY given term, preventing errors from deceptive short sequences.","It wastes time.","To make the answer larger.","Because teachers say so."]',0,'Check your work.','Ensure the rule fits perfectly everywhere.','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0350','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Synthesize the rule and the 5th term: 2, 6, 18, 54, __','["Multiply by 3; 162","Add 4; 70","Multiply by 4; 216","Add 12; 66"]',0,'Check the multiplier.','54 x 3 = 162.','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0351','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Analyze the real-life problem: A bacteria population doubles every hour. If it starts at 10, what is the population after 4 hours?','["160 (10->20->40->80->160)","40","80","100"]',0,'Double it 4 times.','Hour 1: 20, H2: 40, H3: 80, H4: 160.','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0352','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Critique: ''Diana says that if one rule does not explain every consecutive pair, the pattern is broken and impossible.''','["False, it could be an alternating pattern that interleaves two separate sequences or rules.","True.","False, it just means you should add 1.","True, patterns must be simple."]',0,'Alternating patterns.','Look for two overlapping patterns.','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0353','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Synthesize: Start at 1. Rule: Multiply by 2. What is the 8th term?','["128","64","256","16"]',0,'Powers of 2.','1, 2, 4, 8, 16, 32, 64, 128 (which is 2^7).','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0354','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Evaluate: How does understanding patterns in primary math build a foundation for later mathematics?','["It is the fundamental basis for algebraic thinking, functions, and predicting mathematical behavior.","It only helps with art.","It doesn''t help later on.","It is only for spelling."]',0,'Algebraic foundation.','Patterns lead directly to algebra.','2026-11-01 17:46:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t6_global_0355','Maths','Patterns and Sequences','Subtopic 10: Creating and Solving Pattern Problems','Primary',10,'Evaluate the 5-step method (Observe, Find Rule, Apply, Check, Explain). Why is ''Check'' important?','["To verify that your hypothesized rule consistently applies to EVERY given term, preventing errors from deceptive short sequences.","It wastes time.","To make the answer larger.","Because teachers say so."]',0,'Check your work.','Ensure the rule fits perfectly everywhere.','2026-11-01 17:46:25',NULL,NULL);
