INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0001','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'What symbol separates the whole-number part from the fractional part in a decimal?','["Decimal point","Comma","Dash","Slash"]',0,'It looks like a dot.','The decimal point separates the wholes from the parts.','2026-11-01 17:47:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0002','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'In the number 2.5, which digit represents the whole-number part?','["2","5","0","None"]',0,'Left side of the dot.','The number to the left of the decimal point is the whole number.','2026-11-01 17:47:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0003','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'What does the ''.5'' mean in 3.5?','["Five tenths (half of one whole)","Five wholes","Fifty","Five hundred"]',0,'It''s half of a whole.','0.5 means 5/10, or one half.','2026-11-01 17:47:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0004','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'Which of these numbers is a decimal?','["4.4","40","4/4","400"]',0,'Look for the dot.','A decimal number has a decimal point.','2026-11-01 17:47:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0005','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'If Ethan eats 5 out of 10 pieces of a chocolate bar, what decimal represents the part eaten?','["0.5","5.10","10.5","5.0"]',0,'Five tenths.','5 out of 10 is 5/10, which is written as 0.5.','2026-11-01 17:47:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0006','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',1,'In 11.8, which digit represents the fractional part (tenths)?','["8","11","0","1"]',0,'Right side.','The digit to the right of the decimal point.','2026-11-01 17:47:45',NULL,NULL);
