INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0013','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'How do you write the fraction 1/10 as a decimal?','["0.1","1.10","0.01","1.0"]',0,'Tenths place.','1/10 means 1 tenths, written as 0.1.','2026-11-01 17:47:45',NULL,NULL);
