INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0015','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'Convert 3 and 7 tenths into a decimal number.','["3.7","3.07","0.37","37.0"]',0,'Whole point part.','3 is the whole, 7 is in the tenths place.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0016','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'What is true about the number 0.7?','["It is less than one whole.","It is a whole number.","It is greater than 8.","It has no fractional part."]',0,'Look at the whole number part (0).','Decimals starting with 0. are less than 1.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0017','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'If a pencil is 15.5 cm long, what does the .5 mean?','["5 tenths of a centimeter (half a cm)","5 whole centimeters","50 centimeters","5 meters"]',0,'Part of a cm.','It represents the fractional part.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0018','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'Why are decimals useful in everyday life?','["They help describe quantities that are between whole numbers (like prices or measurements).","They make numbers bigger.","They remove the need for zero.","They are only used in science."]',0,'Between wholes.','Decimals give us precision between integers.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0019','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'How do you write the fraction 2/10 as a decimal?','["0.2","2.10","0.02","2.0"]',0,'Tenths place.','2/10 means 2 tenths, written as 0.2.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0020','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'Which part of 15.45 represents the whole units?','["15","4","5","45"]',0,'Left of the point.','Everything to the left of the decimal is whole units.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0021','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'Convert 4 and 7 tenths into a decimal number.','["4.7","4.07","0.47","47.0"]',0,'Whole point part.','4 is the whole, 7 is in the tenths place.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0022','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'What is true about the number 0.8?','["It is less than one whole.","It is a whole number.","It is greater than 9.","It has no fractional part."]',0,'Look at the whole number part (0).','Decimals starting with 0. are less than 1.','2026-11-01 17:47:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0023','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'If a pencil is 11.5 cm long, what does the .5 mean?','["5 tenths of a centimeter (half a cm)","5 whole centimeters","50 centimeters","5 meters"]',0,'Part of a cm.','It represents the fractional part.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0024','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',5,'Why are decimals useful in everyday life?','["They help describe quantities that are between whole numbers (like prices or measurements).","They make numbers bigger.","They remove the need for zero.","They are only used in science."]',0,'Between wholes.','Decimals give us precision between integers.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0025','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Critique: ''Alice says that 0.1 is not a real decimal because it doesn''t have a whole number.''','["False, a decimal can have a whole-number part of zero.","True, decimals must start with 1 or more.","False, 0 is a whole number so it is a whole number, not a decimal.","True, it is just a fraction."]',0,'Zero is a valid whole-number part.','0.x is a valid decimal representing a value less than 1.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0026','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Analyze: How does the decimal point function conceptually?','["It acts as a separator indicating where whole units end and fractional sub-units (base-10 fractions) begin.","It is just punctuation to pause reading.","It multiplies the number by 10.","It turns the number negative."]',0,'Divider.','It separates wholes from parts.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0027','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Synthesize the meaning of 23.75.','["It represents 23 whole units and 75 hundredths (or 3 quarters) of another unit.","It represents 23 plus 75.","It represents 23 tenths and 75 wholes.","It is a code."]',0,'Wholes and parts.','Whole part and fractional part.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0028','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Evaluate: Why do we use base-10 denominators (10, 100, 1000) for decimals?','["Because the decimal system is an extension of our base-10 place value system for whole numbers.","Because 10 is an even number.","Because fractions are too hard.","We don''t use base-10."]',0,'Place value extension.','Decimals extend the place value chart to the right.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0029','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Critique: ''Ethan wrote 5 wholes and 8 tenths as 58.''','["False, without the decimal point (5.8), the 5 is shifted to the tens place and the 8 to the ones.","True, the dot doesn''t matter.","False, it should be 0.58.","False, it should be 8.5."]',0,'Where are the ones?','The decimal point anchors the place values.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0030','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Analyze: On a number line, where does 1.8 fall?','["Between 1 and 2, but closer to 2.","Between 1 and 2, closer to 1.","Exactly on 1.","Past 3."]',0,'0.8 is almost a whole.','1.8 is 1 and 8/10, so it''s close to the next whole.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0031','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Critique: ''George says that 0.2 is not a real decimal because it doesn''t have a whole number.''','["False, a decimal can have a whole-number part of zero.","True, decimals must start with 1 or more.","False, 0 is a whole number so it is a whole number, not a decimal.","True, it is just a fraction."]',0,'Zero is a valid whole-number part.','0.x is a valid decimal representing a value less than 1.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0032','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Analyze: How does the decimal point function conceptually?','["It acts as a separator indicating where whole units end and fractional sub-units (base-10 fractions) begin.","It is just punctuation to pause reading.","It multiplies the number by 10.","It turns the number negative."]',0,'Divider.','It separates wholes from parts.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0033','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Synthesize the meaning of 24.75.','["It represents 24 whole units and 75 hundredths (or 3 quarters) of another unit.","It represents 24 plus 75.","It represents 24 tenths and 75 wholes.","It is a code."]',0,'Wholes and parts.','Whole part and fractional part.','2026-11-01 17:47:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0034','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Evaluate: Why do we use base-10 denominators (10, 100, 1000) for decimals?','["Because the decimal system is an extension of our base-10 place value system for whole numbers.","Because 10 is an even number.","Because fractions are too hard.","We don''t use base-10."]',0,'Place value extension.','Decimals extend the place value chart to the right.','2026-11-01 17:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0035','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Critique: ''Kevin wrote 5 wholes and 8 tenths as 58.''','["False, without the decimal point (5.8), the 5 is shifted to the tens place and the 8 to the ones.","True, the dot doesn''t matter.","False, it should be 0.58.","False, it should be 8.5."]',0,'Where are the ones?','The decimal point anchors the place values.','2026-11-01 17:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0036','Maths','Decimals','Subtopic 1: Understanding Decimal Numbers','Primary',10,'Analyze: On a number line, where does 2.8 fall?','["Between 2 and 3, but closer to 3.","Between 2 and 3, closer to 2.","Exactly on 2.","Past 4."]',0,'0.8 is almost a whole.','2.8 is 2 and 8/10, so it''s close to the next whole.','2026-11-01 17:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0037','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',1,'What place value is the first digit after the decimal point?','["Tenths","Ones","Hundredths","Tens"]',0,'Right next to the dot.','The first place to the right is tenths.','2026-11-01 17:47:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0038','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',1,'What place value is the second digit after the decimal point?','["Hundredths","Tenths","Thousandths","Hundreds"]',0,'Two steps right.','The second place is hundredths.','2026-11-01 17:47:48',NULL,NULL);
