INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0050','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'In 3.472, what is the value of the 7?','["7 hundredths (0.07)","7 tenths (0.7)","7 thousandths (0.007)","7 ones"]',0,'Hundredths.','It is in the second decimal place.','2026-11-01 17:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0051','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Write 8/100 as a decimal.','["0.08","0.8","0.008","8.0"]',0,'Needs a placeholder zero.','8 must be in the second place.','2026-11-01 17:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0052','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Which is greater: 0.4 or 0.04?','["0.4 (tenths are larger than hundredths)","0.04","They are equal","Cannot tell"]',0,'First spot vs Second spot.','Tenths > Hundredths.','2026-11-01 17:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0053','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Convert 130/1000 to a decimal.','["0.130","0.0130","1.30","0.17"]',0,'Three spots.','Thousandths means 3 decimal places.','2026-11-01 17:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0054','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'In 5.012, what place is the 1 in?','["Hundredths","Tenths","Thousandths","Ones"]',0,'Second spot.','Second place is hundredths.','2026-11-01 17:47:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0055','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Write 12/100 as a decimal.','["0.12","0.012","12.0","0.3"]',0,'Two decimal places.','Numerator goes into hundredths.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0056','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'In 3.472, what is the value of the 7?','["7 hundredths (0.07)","7 tenths (0.7)","7 thousandths (0.007)","7 ones"]',0,'Hundredths.','It is in the second decimal place.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0057','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Write 8/100 as a decimal.','["0.08","0.8","0.008","8.0"]',0,'Needs a placeholder zero.','8 must be in the second place.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0058','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Which is greater: 0.5 or 0.05?','["0.5 (tenths are larger than hundredths)","0.05","They are equal","Cannot tell"]',0,'First spot vs Second spot.','Tenths > Hundredths.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0059','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'Convert 126/1000 to a decimal.','["0.126","0.0126","1.26","0.13"]',0,'Three spots.','Thousandths means 3 decimal places.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0060','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',5,'In 5.022, what place is the 2 in?','["Hundredths","Tenths","Thousandths","Ones"]',0,'Second spot.','Second place is hundredths.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0061','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Critique: ''Alice says that 0.5 is equal to 0.05 because zeros don''t matter.''','["False, the zero in 0.05 is a placeholder that shifts the 5 from tenths to the much smaller hundredths place.","True, zeros after the decimal don''t matter.","False, 0.05 is larger.","True for fractions."]',0,'Tenths vs Hundredths.','Placeholders between the decimal and a digit change the value.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0062','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Analyze: Why is 0.5 equal to 0.50 but NOT equal to 0.05?','["Trailing zeros on the far right (0.50) don''t change the column the 5 is in, but a zero before the 5 (0.05) shifts its place value.","They are all equal.","0.50 is larger.","0.05 is the largest."]',0,'Trailing vs Leading (fractional).','Position of the digit matters, not just the number of digits.','2026-11-01 17:47:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0063','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Synthesize the conversion of 3/1000 into a decimal.','["0.003","0.03","0.3","3.000"]',0,'Three decimal places total.','Requires two placeholder zeros to push the digit to the thousandths place.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0064','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Evaluate: Compare 0.125 and 0.120.','["0.125 > 0.120","0.125 < 0.120","They are equal","Cannot compare"]',0,'Compare place by place.','125 thousandths is greater than 120 thousandths.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0065','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Analyze: In 7.567, what is the sum of the digit in the tenths place and the digit in the thousandths place?','["12","11","13","14"]',0,'Identify the correct columns.','Tenths is 5, thousandths is 7.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0066','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Critique: ''Thousandths are larger than tenths because 1000 is larger than 10.''','["False; fractional parts work in reverse. A whole divided into 1000 parts results in much smaller pieces than a whole divided into 10 parts.","True.","False, they are equal.","True, for decimals."]',0,'Fractions of a whole.','More pieces means smaller pieces.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0067','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Critique: ''George says that 0.5 is equal to 0.05 because zeros don''t matter.''','["False, the zero in 0.05 is a placeholder that shifts the 5 from tenths to the much smaller hundredths place.","True, zeros after the decimal don''t matter.","False, 0.05 is larger.","True for fractions."]',0,'Tenths vs Hundredths.','Placeholders between the decimal and a digit change the value.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0068','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Analyze: Why is 0.5 equal to 0.50 but NOT equal to 0.05?','["Trailing zeros on the far right (0.50) don''t change the column the 5 is in, but a zero before the 5 (0.05) shifts its place value.","They are all equal.","0.50 is larger.","0.05 is the largest."]',0,'Trailing vs Leading (fractional).','Position of the digit matters, not just the number of digits.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0069','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Synthesize the conversion of 4/1000 into a decimal.','["0.004","0.04","0.4","4.000"]',0,'Three decimal places total.','Requires two placeholder zeros to push the digit to the thousandths place.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0070','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Evaluate: Compare 0.125 and 0.120.','["0.125 > 0.120","0.125 < 0.120","They are equal","Cannot compare"]',0,'Compare place by place.','125 thousandths is greater than 120 thousandths.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0071','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Analyze: In 3.123, what is the sum of the digit in the tenths place and the digit in the thousandths place?','["4","3","5","6"]',0,'Identify the correct columns.','Tenths is 1, thousandths is 3.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0072','Maths','Decimals','Subtopic 2: Tenths, Hundredths and Thousandths','Primary',10,'Critique: ''Thousandths are larger than tenths because 1000 is larger than 10.''','["False; fractional parts work in reverse. A whole divided into 1000 parts results in much smaller pieces than a whole divided into 10 parts.","True.","False, they are equal.","True, for decimals."]',0,'Fractions of a whole.','More pieces means smaller pieces.','2026-11-01 17:47:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0073','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'In the decimal 4.582, what is the ''face value'' of the digit 5?','["5","0.5","50","Tenths"]',0,'The symbol itself.','Face value is always just the digit itself.','2026-11-01 17:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0074','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'In 4.582, what is the ''place value'' of the digit 5?','["0.5 (or 5 tenths)","5","0.05","50"]',0,'Position matters.','It is in the tenths place.','2026-11-01 17:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0075','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'What place is immediately to the left of the decimal point?','["Ones","Tenths","Tens","Hundredths"]',0,'Left side.','The whole numbers start with the ones place.','2026-11-01 17:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0076','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'In 26.347, which digit is in the ones place?','["6","2","3","7"]',0,'Left of dot.','The digit just left of the decimal is the ones.','2026-11-01 17:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0077','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'In 7.35, what is the place value of the 3?','["3 tenths","3 ones","3 hundredths","3 tens"]',0,'Tenths.','First digit right of the dot.','2026-11-01 17:47:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0078','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'What is the place value of 2 in 0.02?','["2 hundredths","2 tenths","2 thousandths","2 ones"]',0,'Hundredths.','Second digit right of the dot.','2026-11-01 17:47:52',NULL,NULL);
