INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0084','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',1,'What is the place value of 2 in 0.02?','["2 hundredths","2 tenths","2 thousandths","2 ones"]',0,'Hundredths.','Second digit right of the dot.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0085','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'Write 5.26 in expanded form.','["5 + 0.2 + 0.06","5 + 2 + 6","500 + 20 + 6","5.2 + 0.6"]',0,'Wholes + Tenths + Hundredths.','Break it into place values.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0086','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'In 8.407, why do we not write the zero in expanded form (8 + 0.4 + 0.007)?','["A digit with a value of zero contributes nothing to the sum.","Because zero is negative.","Zero makes it wrong.","You MUST write the zero."]',0,'0 = nothing.','Adding zero doesn''t change the sum.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0087','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'If the digit 4 moves one place to the right (from 0.4 to 0.04), what happens to its value?','["It becomes ten times smaller.","It becomes ten times larger.","It stays the same.","It becomes negative."]',0,'Right is smaller.','Moving right on the chart divides value by 10.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0088','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'Find the place value of 4 in 12.045.','["4 hundredths (0.04)","4 tenths (0.4)","4 thousandths","4 ones"]',0,'Hundredths.','Second place after decimal.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0089','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'What is 30 + 2 + 0.1 + 0.05 + 0.008 in standard form?','["32.158","302.158","32.1508","3.2158"]',0,'Line up the dots.','Combine the place values.','2026-11-01 17:47:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0090','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'In 4.205, why is the zero important?','["Without it, the 5 would move to the hundredths place, making it 4.25 (a completely different number).","It isn''t important.","It makes the number even.","It makes the 4 bigger."]',0,'Placeholder.','It''s a placeholder holding the thousandths in place.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0091','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'Write 5.26 in expanded form.','["5 + 0.2 + 0.06","5 + 2 + 6","500 + 20 + 6","5.2 + 0.6"]',0,'Wholes + Tenths + Hundredths.','Break it into place values.','2026-11-01 17:47:54',NULL,NULL);
