INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0094','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'Find the place value of 5 in 12.055.','["5 hundredths (0.05)","5 tenths (0.5)","5 thousandths","5 ones"]',0,'Hundredths.','Second place after decimal.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0095','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'What is 30 + 2 + 0.1 + 0.05 + 0.008 in standard form?','["32.158","302.158","32.1508","3.2158"]',0,'Line up the dots.','Combine the place values.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0096','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',5,'In 4.205, why is the zero important?','["Without it, the 5 would move to the hundredths place, making it 4.25 (a completely different number).","It isn''t important.","It makes the number even.","It makes the 4 bigger."]',0,'Placeholder.','It''s a placeholder holding the thousandths in place.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0097','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Analyze the base-ten system: How does a digit''s value change if it moves one place to the left across the decimal point (e.g., from 0.5 to 5)?','["It becomes exactly 10 times greater.","It becomes 10 times smaller.","It becomes 1 greater.","It becomes a whole number randomly."]',0,'x10.','The base-10 rule applies across the decimal boundary too.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0098','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Synthesize the expanded form of 20.003.','["20 + 0.003","20 + 0.3","20 + 0.03","20 + 3"]',0,'Watch the zeros.','Omit the empty tenths and hundredths.','2026-11-01 17:47:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0099','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Critique: ''Charlie says that in 4.582, the 5 is worth more than the 4 because 5 is a larger face value.''','["False, the 4 is in the ones place (worth 4 wholes), while the 5 is only in the tenths place (worth half a whole).","True, face value is all that matters.","True for decimals.","False, they are equal."]',0,'Position is key.','Place value overrides face value.','2026-11-01 17:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0100','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Evaluate: Reconstruct the standard form from 8 + 0.03 + 0.007.','["8.037","8.37","8.307","8.0037"]',0,'Placeholder needed.','The tenths place is empty, so it needs a 0.','2026-11-01 17:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0101','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Analyze: How many times larger is the 2 in 0.2 than the 2 in 0.002?','["100 times larger.","10 times larger.","1000 times larger.","They are equal."]',0,'Count the jumps.','It is two columns to the left (10 x 10 = 100).','2026-11-01 17:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0102','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Synthesize: What is the sum of the place value of the 3 and the face value of the 7 in 5.37?','["7.3","7.07","10","3.7"]',0,'Read carefully!','Place value of 3 is 0.3. Face value of 7 is 7. 0.3 + 7 = 7.3.','2026-11-01 17:47:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0103','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Analyze the base-ten system: How does a digit''s value change if it moves one place to the left across the decimal point (e.g., from 0.5 to 5)?','["It becomes exactly 10 times greater.","It becomes 10 times smaller.","It becomes 1 greater.","It becomes a whole number randomly."]',0,'x10.','The base-10 rule applies across the decimal boundary too.','2026-11-01 17:47:55',NULL,NULL);
