INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0106','Maths','Decimals','Subtopic 3: Place Value in Decimals','Primary',10,'Evaluate: Reconstruct the standard form from 8 + 0.03 + 0.007.','["8.037","8.37","8.307","8.0037"]',0,'Placeholder needed.','The tenths place is empty, so it needs a 0.','2026-11-01 17:47:55',NULL,NULL);
