INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0109','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'How do you read the decimal 0.1 using place value names?','["1 tenths","1 hundredths","Zero point 1","1 ones"]',0,'Look at the column.','One decimal place means tenths.','2026-11-01 17:47:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0110','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'How do you read 2.7?','["Two and seven tenths","Two point seventy","Twenty-seven","Two and seven hundredths"]',0,'Read the whole, then the part.','The decimal is ''and'', the 7 is in the tenths.','2026-11-01 17:47:56',NULL,NULL);
