INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0115','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'How do you read the decimal 0.2 using place value names?','["2 tenths","2 hundredths","Zero point 2","2 ones"]',0,'Look at the column.','One decimal place means tenths.','2026-11-01 17:47:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0116','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'How do you read 2.7?','["Two and seven tenths","Two point seventy","Twenty-seven","Two and seven hundredths"]',0,'Read the whole, then the part.','The decimal is ''and'', the 7 is in the tenths.','2026-11-01 17:47:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0117','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'Write ''four tenths'' as a decimal.','["0.4","0.04","4.0","0.004"]',0,'First spot.','4 in the tenths place.','2026-11-01 17:47:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0118','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'How is 3.25 read digit by digit?','["Three point two five","Three point twenty-five","Three two five","Thirty-two point five"]',0,'Say each number.','Read each digit individually after the dot.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0119','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'Write ''zero point zero six'' as a numeral.','["0.06","0.6","0.60","6.0"]',0,'Just write what you hear.','Follow the words exactly.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0120','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',1,'Which is correct for 0.08?','["Eight hundredths","Eight tenths","Eighty","Eight thousandths"]',0,'Second spot.','Two decimal places is hundredths.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0121','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Write ''11 and 6 hundredths'' as a decimal numeral.','["11.06","11.60","11.006","0.116"]',0,'Watch the columns.','Wholes before the dot, hundredths after.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0122','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Convert 406/1000 into a decimal.','["0.406","4.06","0.0406","40.6"]',0,'Three digits.','Four hundred six thousandths means 3 decimal places.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0123','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'How do you write 5.24 in words?','["Five and twenty-four hundredths","Five and twenty-four tenths","Five point twenty-four","Fifty-two and four"]',0,'Read the fraction part fully.','Two decimal places means hundredths.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0124','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Write ''eight hundredths'' as a decimal.','["0.08","0.8","8.00","0.008"]',0,'Placeholder needed.','The 8 must be in the second decimal place.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0125','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'What is the word form of 0.235?','["Two hundred thirty-five thousandths","Two hundred thirty-five hundredths","Two point thirty-five","Two and thirty-five"]',0,'Read all three digits.','Three decimal places is thousandths.','2026-11-01 17:47:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0126','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Critique: ''Fiona read 2.305 as ''two point three hundred five''.''','["Incorrect, it should be ''two point three zero five'' or ''two and three hundred five thousandths''.","Correct.","Incorrect, should be two point thirty-five.","Incorrect, should be two point three five."]',0,'Digit by digit OR place value.','Don''t mix the two reading styles.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0127','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Write ''12 and 7 hundredths'' as a decimal numeral.','["12.07","12.70","12.007","0.127"]',0,'Watch the columns.','Wholes before the dot, hundredths after.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0128','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Convert 406/1000 into a decimal.','["0.406","4.06","0.0406","40.6"]',0,'Three digits.','Four hundred six thousandths means 3 decimal places.','2026-11-01 17:47:58',NULL,NULL);
