INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0130','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Write ''eight hundredths'' as a decimal.','["0.08","0.8","8.00","0.008"]',0,'Placeholder needed.','The 8 must be in the second decimal place.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0131','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'What is the word form of 0.235?','["Two hundred thirty-five thousandths","Two hundred thirty-five hundredths","Two point thirty-five","Two and thirty-five"]',0,'Read all three digits.','Three decimal places is thousandths.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0132','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',5,'Critique: ''Liam read 2.305 as ''two point three hundred five''.''','["Incorrect, it should be ''two point three zero five'' or ''two and three hundred five thousandths''.","Correct.","Incorrect, should be two point thirty-five.","Incorrect, should be two point three five."]',0,'Digit by digit OR place value.','Don''t mix the two reading styles.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0133','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Analyze the use of ''and'' in decimal number names.','["The word ''and'' is specifically used to denote the location of the decimal point, separating the whole numbers from the fractional parts.","It is just a filler word.","It means addition.","It goes between the tenths and hundredths."]',0,'Separator.','E.g., Two AND five tenths.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0134','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Synthesize the numerical form of: ''One hundred twenty and five thousandths''.','["120.005","120.500","120.05","100.25"]',0,'Placeholders.','Thousandths require three decimal places; the 5 must be in the third spot.','2026-11-01 17:47:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0135','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Evaluate the difference between 0.6 and 0.06 in word form.','["0.6 is six tenths, 0.06 is six hundredths. They are vastly different values.","They are exactly the same.","0.6 is six hundredths.","0.06 is six tenths."]',0,'Tenths vs Hundredths.','Place value determines the name.','2026-11-01 17:47:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0136','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Critique: ''Diana wrote 40.012 as ''forty and twelve hundredths''.''','["False, it has three decimal places, so it must be ''twelve thousandths''.","True.","False, it is forty point twelve.","False, it is forty twelve."]',0,'Three spots = thousandths.','Count the decimal places to determine the denominator word.','2026-11-01 17:47:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0137','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Synthesize the word form for 3,004.05.','["Three thousand four and five hundredths","Three thousand and four and five tenths","Three thousand four point five","Three thousand forty-five"]',0,'Combine the rules.','Read the whole, say ''and'', read the fraction.','2026-11-01 17:47:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0138','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Analyze: Why is it wrong to say ''three point twenty-five'' for 3.25?','["Because ''twenty-five'' implies tens and ones, but these digits represent tenths and hundredths. Digit-by-digit reading (''two five'') is mathematically clearer.","It is actually correct.","Because there is no twenty.","Because it should be a fraction."]',0,'Digit by digit.','Don''t use whole number place values for decimal digits.','2026-11-01 17:47:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0139','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Analyze the use of ''and'' in decimal number names.','["The word ''and'' is specifically used to denote the location of the decimal point, separating the whole numbers from the fractional parts.","It is just a filler word.","It means addition.","It goes between the tenths and hundredths."]',0,'Separator.','E.g., Two AND five tenths.','2026-11-01 17:47:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0140','Maths','Decimals','Subtopic 4: Reading and Writing Decimals','Primary',10,'Synthesize the numerical form of: ''One hundred twenty and five thousandths''.','["120.005","120.500","120.05","100.25"]',0,'Placeholders.','Thousandths require three decimal places; the 5 must be in the third spot.','2026-11-01 17:47:59',NULL,NULL);
