INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0145','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',1,'Compare using symbols: 0.8 __ 0.5','[">","<","=","+"]',0,'Open mouth to bigger number.','8 tenths is greater than 5 tenths.','2026-11-01 17:48:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0146','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',1,'Which is smaller: 0.3 or 0.7?','["0.3","0.7","Equal","Cannot tell"]',0,'Look at the digit.','3 tenths < 7 tenths.','2026-11-01 17:48:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0147','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',1,'Compare: 4.7 __ 3.9','[">","<","=","-"]',0,'Look at the wholes first.','Compare the whole numbers first: 4 > 3.','2026-11-01 17:48:00',NULL,NULL);
