INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0149','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',1,'Compare: 0.4 __ 0.40','["=",">","<","+"]',0,'Zeros at the end.','Trailing zeros do not change the value.','2026-11-01 17:48:00',NULL,NULL);
