INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0157','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Compare 0.34 and 0.39.','["0.34 < 0.39","0.34 > 0.39","0.34 = 0.39","None"]',0,'Check the second digit.','Tenths are the same, 4 hundredths < 9 hundredths.','2026-11-01 17:48:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0158','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Which is greater: 0.7 or 0.65?','["0.7 (because 0.70 > 0.65)","0.65","Equal","Cannot tell"]',0,'Add a trailing zero.','Add a zero to make them both have two decimal places.','2026-11-01 17:48:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0159','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Compare 3.08 and 3.8.','["3.08 < 3.8","3.08 > 3.8","3.08 = 3.8","None"]',0,'Add a zero.','3.8 is 3.80. 08 < 80.','2026-11-01 17:48:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0160','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Arrange in ascending order: 0.4, 0.7, 0.2, 0.5.','["0.2, 0.4, 0.5, 0.7","0.7, 0.5, 0.4, 0.2","0.2, 0.5, 0.4, 0.7","0.4, 0.2, 0.5, 0.7"]',0,'Go up.','Smallest to largest.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0161','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Arrange in descending order: 2.4, 2.08, 2.75, 2.3.','["2.75, 2.4, 2.3, 2.08","2.08, 2.3, 2.4, 2.75","2.75, 2.08, 2.4, 2.3","2.4, 2.75, 2.3, 2.08"]',0,'Add zeros to compare.','Largest to smallest (2.40, 2.08, 2.75, 2.30).','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0162','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Critique: ''Fiona says 0.125 > 0.2 because 125 is greater than 2.''','["False, 0.2 is 0.200, so 200 thousandths > 125 thousandths.","True.","False, they are equal.","True, more digits means bigger."]',0,'Add zeros.','Compare place by place, not digit count.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0163','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Compare 0.34 and 0.39.','["0.34 < 0.39","0.34 > 0.39","0.34 = 0.39","None"]',0,'Check the second digit.','Tenths are the same, 4 hundredths < 9 hundredths.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0164','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Which is greater: 0.7 or 0.65?','["0.7 (because 0.70 > 0.65)","0.65","Equal","Cannot tell"]',0,'Add a trailing zero.','Add a zero to make them both have two decimal places.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0165','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Compare 3.08 and 3.8.','["3.08 < 3.8","3.08 > 3.8","3.08 = 3.8","None"]',0,'Add a zero.','3.8 is 3.80. 08 < 80.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0166','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Arrange in ascending order: 0.4, 0.7, 0.2, 0.5.','["0.2, 0.4, 0.5, 0.7","0.7, 0.5, 0.4, 0.2","0.2, 0.5, 0.4, 0.7","0.4, 0.2, 0.5, 0.7"]',0,'Go up.','Smallest to largest.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0167','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Arrange in descending order: 2.4, 2.08, 2.75, 2.3.','["2.75, 2.4, 2.3, 2.08","2.08, 2.3, 2.4, 2.75","2.75, 2.08, 2.4, 2.3","2.4, 2.75, 2.3, 2.08"]',0,'Add zeros to compare.','Largest to smallest (2.40, 2.08, 2.75, 2.30).','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0168','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',5,'Critique: ''Liam says 0.125 > 0.2 because 125 is greater than 2.''','["False, 0.2 is 0.200, so 200 thousandths > 125 thousandths.","True.","False, they are equal.","True, more digits means bigger."]',0,'Add zeros.','Compare place by place, not digit count.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0169','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Analyze the logic: Why does adding a ''trailing zero'' (e.g. 0.5 to 0.50) NOT change the value of a decimal?','["Because 5 tenths and 0 hundredths is exactly the same mathematical amount as 5 tenths.","It does change the value.","Because zeros are invisible.","Because it is an error."]',0,'Equivalent fractions (5/10 = 50/100).','You are adding nothing (zero) to the smaller columns.','2026-11-01 17:48:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0170','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Synthesize the ascending order for: 1.08, 1.008, 1.8, 1.088.','["1.008, 1.08, 1.088, 1.8","1.8, 1.088, 1.08, 1.008","1.008, 1.8, 1.08, 1.088","1.08, 1.008, 1.088, 1.8"]',0,'Line up the decimal points and pad zeros.','Pad with zeros: 1.080, 1.008, 1.800, 1.088. Then compare.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0171','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Evaluate the comparison: 4.306 and 4.36.','["4.306 < 4.36 (4.360)","4.306 > 4.36","4.306 = 4.36","None"]',0,'Compare digit by digit.','Hundredths place: 0 < 6.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0172','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Critique: ''Diana says that negative decimals work exactly the same way, so -0.5 is greater than -0.2.''','["False, for negative numbers, the value closer to zero is greater. -0.2 > -0.5.","True, 5 is greater than 2.","True, decimals are always positive.","False, they are equal."]',0,'Think of a number line going left.','Negative numbers reverse the comparison logic.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0173','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Synthesize the descending order of: 5.6, 5.65, 5.06, 5.7.','["5.7, 5.65, 5.6, 5.06","5.06, 5.6, 5.65, 5.7","5.7, 5.6, 5.65, 5.06","Cannot sort."]',0,'Add trailing zeros.','Pad with zeros to compare easily.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0174','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Analyze: What is the most efficient mental strategy to compare 0.45 and 0.405?','["Pad 0.45 to 0.450, then compare 450 thousandths to 405 thousandths.","Add them.","Ignore the decimal.","Multiply by 10."]',0,'Padding.','Making the lengths the same makes comparison trivial.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0175','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Analyze the logic: Why does adding a ''trailing zero'' (e.g. 0.5 to 0.50) NOT change the value of a decimal?','["Because 5 tenths and 0 hundredths is exactly the same mathematical amount as 5 tenths.","It does change the value.","Because zeros are invisible.","Because it is an error."]',0,'Equivalent fractions (5/10 = 50/100).','You are adding nothing (zero) to the smaller columns.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0176','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Synthesize the ascending order for: 1.08, 1.008, 1.8, 1.088.','["1.008, 1.08, 1.088, 1.8","1.8, 1.088, 1.08, 1.008","1.008, 1.8, 1.08, 1.088","1.08, 1.008, 1.088, 1.8"]',0,'Line up the decimal points and pad zeros.','Pad with zeros: 1.080, 1.008, 1.800, 1.088. Then compare.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0177','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Evaluate the comparison: 4.306 and 4.36.','["4.306 < 4.36 (4.360)","4.306 > 4.36","4.306 = 4.36","None"]',0,'Compare digit by digit.','Hundredths place: 0 < 6.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0178','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Critique: ''Julia says that negative decimals work exactly the same way, so -0.5 is greater than -0.2.''','["False, for negative numbers, the value closer to zero is greater. -0.2 > -0.5.","True, 5 is greater than 2.","True, decimals are always positive.","False, they are equal."]',0,'Think of a number line going left.','Negative numbers reverse the comparison logic.','2026-11-01 17:48:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0179','Maths','Decimals','Subtopic 5: Comparing and Ordering Decimals','Primary',10,'Synthesize the descending order of: 1.2, 1.25, 1.02, 1.3.','["1.3, 1.25, 1.2, 1.02","1.02, 1.2, 1.25, 1.3","1.3, 1.2, 1.25, 1.02","Cannot sort."]',0,'Add trailing zeros.','Pad with zeros to compare easily.','2026-11-01 17:48:04',NULL,NULL);
