INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0181','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',1,'Convert the fraction 3/10 into a decimal.','["0.3","3.10","0.03","3.0"]',0,'Tenths place.','Three tenths is 0.3.','2026-11-01 17:48:04',NULL,NULL);
