INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0195','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',5,'Convert 1/2 into a decimal by making an equivalent fraction first.','["0.5 (1/2 = 5/10)","0.12","0.2","0.05"]',0,'Make the denominator 10.','Multiply top and bottom by 5.','2026-11-01 17:48:06',NULL,NULL);
