INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0197','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',5,'Convert 7/20 into a decimal.','["0.35 (multiply by 5/5 to get 35/100)","0.72","0.20","0.07"]',0,'Multiply by 5.','Multiply to get 100 on bottom.','2026-11-01 17:48:06',NULL,NULL);
