INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0205','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Analyze the division method: Convert 3/8 into a decimal.','["0.375","0.38","0.83","0.4"]',0,'Long division.','Divide 3.000 by 8 using long division.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0206','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Critique: ''Bob converted 1/3 to 0.3.''','["False, 1/3 is a repeating decimal (0.333...); 0.3 is exactly 3/10.","True, they are the same.","False, it is 0.13.","False, it is 0.34."]',0,'Repeating decimal.','1 ÷ 3 never ends.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0207','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Synthesize the conversion of 5 3/4 into a decimal.','["5.75","5.34","5.43","3.45"]',0,'Whole stays the same.','3/4 = 0.75, so 5.75.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0208','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Evaluate: Why must we convert fractions like 2/5 to have a denominator of 10 or 100 before writing them directly as a decimal?','["Because the decimal place value system is strictly base-10.","We don''t have to.","Because 5 is an odd number.","Because decimals can only have two digits."]',0,'Base-10.','Decimals are just fractions with base-10 denominators.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0209','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Analyze: Convert 5/25 into a decimal.','["0.20 (multiply by 4/4)","0.525","0.255","0.25"]',0,'x 4.','Make denominator 100 by multiplying by 4.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0210','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Synthesize: Convert the improper fraction 17/5 into a decimal.','["3.4","1.75","17.5","3.2"]',0,'Multiply by 2/2.','17/5 = 34/10 = 3.4 (or 17 ÷ 5).','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0211','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Analyze the division method: Convert 3/8 into a decimal.','["0.375","0.38","0.83","0.4"]',0,'Long division.','Divide 3.000 by 8 using long division.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0212','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Critique: ''Hannah converted 1/3 to 0.3.''','["False, 1/3 is a repeating decimal (0.333...); 0.3 is exactly 3/10.","True, they are the same.","False, it is 0.13.","False, it is 0.34."]',0,'Repeating decimal.','1 ÷ 3 never ends.','2026-11-01 17:48:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0213','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Synthesize the conversion of 5 3/4 into a decimal.','["5.75","5.34","5.43","3.45"]',0,'Whole stays the same.','3/4 = 0.75, so 5.75.','2026-11-01 17:48:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0214','Maths','Decimals','Subtopic 6: Converting Fractions to Decimals','Primary',10,'Evaluate: Why must we convert fractions like 2/5 to have a denominator of 10 or 100 before writing them directly as a decimal?','["Because the decimal place value system is strictly base-10.","We don''t have to.","Because 5 is an odd number.","Because decimals can only have two digits."]',0,'Base-10.','Decimals are just fractions with base-10 denominators.','2026-11-01 17:48:08',NULL,NULL);
