INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0244','Maths','Decimals','Subtopic 7: Converting Decimals to Fractions','Primary',10,'Evaluate: Why does a trailing zero (like 0.40) result in the same simplified fraction as 0.4?','["Because 40/100 and 4/10 are equivalent fractions that both simplify to 2/5.","Because 0 is magic.","It doesn''t.","Because 40 is 4."]',0,'40/100 vs 4/10.','Trailing zeros just create unsimplified equivalent fractions.','2026-11-01 17:48:11',NULL,NULL);
