INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0269','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',5,'Subtract 5.02 - 2.78.','["2.24","3.24","2.76","3.76"]',0,'Borrow from the 5.','Borrow across the zero.','2026-11-01 17:48:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0270','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',5,'Calculate 10 - 3.75.','["6.25","7.25","6.75","13.75"]',0,'10.00','Write 10 as 10.00 and borrow.','2026-11-01 17:48:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0271','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',5,'Add 3.5 + 2.36.','["5.86 (write 3.5 as 3.50)","5.41","2.71","5.80"]',0,'Line up the dots, add a zero.','Add a placeholder zero to 3.5.','2026-11-01 17:48:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0272','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',5,'Calculate 0.7 + 0.08.','["0.78","0.15","0.87","0.078"]',0,'Use a placeholder zero.','0.70 + 0.08 = 0.78. Don''t just add 7+8.','2026-11-01 17:48:14',NULL,NULL);
