INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0276','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',5,'Calculate 10 - 3.75.','["6.25","7.25","6.75","13.75"]',0,'10.00','Write 10 as 10.00 and borrow.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0277','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Analyze: Why do we add placeholder zeros to the right of decimals when subtracting (e.g., 6.20 - 1.45)?','["To provide a digit in every place value column so borrowing and subtraction can be performed correctly.","To make the number larger.","It''s just for decoration.","To change the value of the decimal."]',0,'You can''t subtract from nothing.','You need a ''0'' to borrow against when subtracting ''5''.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0278','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Critique the mistake: ''Bob added 2.5 + 1.25 and got 3.30 by aligning the 5s.''','["False, they misaligned the place values. 2.50 + 1.25 = 3.75.","True, you align the last digits.","False, they should have subtracted.","True, the answer is 3.30."]',0,'Align the dots!','Decimals must be aligned by the decimal point, not the last digit.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0279','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Synthesize the multi-step calculation: 1.25 + 0.8 + 2.06.','["4.11","3.39","4.01","3.11"]',0,'Pad with zeros and add all three.','1.25 + 0.80 + 2.06 = 4.11.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0280','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Evaluate the real-life application: You have a 10 unit note. You buy items for 2.75 and 3.40. How much change?','["3.85","4.85","6.15","4.15"]',0,'Add costs, subtract from 10.','2.75+3.40=6.15. 10.00-6.15=3.85.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0281','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Analyze the subtraction: 100.1 - 99.99.','["0.11","1.11","0.21","1.01"]',0,'Line up dots, borrow carefully.','100.10 - 99.99 = 0.11.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0282','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Synthesize: If X + 1.5 = 5.25, what is X?','["5.25 - 1.50 = 3.75","3.25","4.25","3.50"]',0,'Subtract to find X.','Use inverse operation (subtraction) with padded zeros.','2026-11-01 17:48:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0283','Maths','Decimals','Subtopic 8: Addition and Subtraction of Decimals','Primary',10,'Analyze: Why do we add placeholder zeros to the right of decimals when subtracting (e.g., 6.20 - 1.45)?','["To provide a digit in every place value column so borrowing and subtraction can be performed correctly.","To make the number larger.","It''s just for decoration.","To change the value of the decimal."]',0,'You can''t subtract from nothing.','You need a ''0'' to borrow against when subtracting ''5''.','2026-11-01 17:48:15',NULL,NULL);
