INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0289','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',1,'What does 0.3 x 3 mean using repeated addition?','["0.3 + 0.3 + 0.3","0.3 + 3","3 + 3 + 3","0.3 x 0.3 x 0.3"]',0,'Repeated addition.','Three groups of 0.3.','2026-11-01 17:48:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0290','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',1,'Calculate 1.2 x 3.','["3.6","3.2","4.6","36"]',0,'Add it 3 times.','1.2 + 1.2 + 1.2 = 3.6.','2026-11-01 17:48:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0291','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',1,'What happens to the digits when you multiply a decimal by 10 (e.g., 2.4 x 10)?','["The digits shift one place to the left, making the number 10 times larger (24).","The digits shift right.","You add a zero to the end (2.40).","Nothing happens."]',0,'The dot ''moves'' right.','Place value shift.','2026-11-01 17:48:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0292','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',1,'Calculate 0.7 x 10.','["7","0.07","70","0.70"]',0,'x10.','Shifts one place left.','2026-11-01 17:48:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0293','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',1,'What happens when you divide a decimal by 10 (e.g., 5.6 ÷ 10)?','["The digits shift one place to the right, making it 10 times smaller (0.56).","It gets 10 times bigger.","Nothing.","You add a zero."]',0,'The dot ''moves'' left.','Place value shift right.','2026-11-01 17:48:17',NULL,NULL);
