INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0302','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'Calculate 0.4 x 5.','["2.0 (or 2)","0.20","20","0.02"]',0,'Ignore dot, then put it back.','4 x 5 = 20, one decimal place gives 2.0.','2026-11-01 17:48:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0303','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'Calculate 3.56 x 100.','["356","35.6","3560","0.0356"]',0,'x100.','Shift digits two places left.','2026-11-01 17:48:18',NULL,NULL);
