INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0305','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'A simple way to calculate 1.2 x 4 is to do 12 x 4 = 48, and then what?','["Put the decimal point back in to match the one decimal place of the question, giving 4.8.","Add a zero.","Leave it as 48.","Divide by 100."]',0,'Count the decimal places.','Restore the place value.','2026-11-01 17:48:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0306','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'Calculate 6.3 ÷ 3.','["2.1","2.3","3.1","21"]',0,'Divide each part.','6/3=2, 3/3=1.','2026-11-01 17:48:18',NULL,NULL);
