INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0311','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'A simple way to calculate 1.2 x 4 is to do 12 x 4 = 48, and then what?','["Put the decimal point back in to match the one decimal place of the question, giving 4.8.","Add a zero.","Leave it as 48.","Divide by 100."]',0,'Count the decimal places.','Restore the place value.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0312','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',5,'Calculate 6.3 ÷ 3.','["2.1","2.3","3.1","21"]',0,'Divide each part.','6/3=2, 3/3=1.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0313','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Analyze: Why is it risky to just teach ''moving the decimal point'' when multiplying by 10?','["Because it obscures the fundamental mathematical concept that the *digits themselves* are shifting to higher place value columns.","It''s the best way to teach it.","Because the point disappears.","It isn''t risky."]',0,'Place value.','Focus on the value of the digits changing, not the dot moving.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0314','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Critique: ''Bob calculated 0.25 x 2 by doing 25x2=50, and since 0.25 has two decimal places, they wrote 0.50, which is 0.5.''','["This method (temporarily ignoring the decimal, calculating, then restoring place values) is perfectly valid and correct.","False, they must keep all zeros.","False, the answer is 5.","False, you cannot ignore the decimal."]',0,'It works!','This is the standard algorithm for decimal multiplication.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0315','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Synthesize: Calculate 0.08 ÷ 10.','["0.008","0.8","0.080","8"]',0,'Divide by 10.','Shifts one more place to the right.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0316','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Evaluate: If 3 bottles hold 0.5 L each, what is the total volume?','["1.5 L (0.5 x 3)","15 L","0.15 L","1.0 L"]',0,'Multiply.','5x3=15, one decimal place.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0317','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Analyze: How can estimation catch the error if someone writes 19 x 0.6 = 114?','["Rounding 19 to 20, and 0.6 to 0.5 (half). Half of 20 is 10. The answer 114 is 10x too big. It should be 11.4.","Estimation can''t catch this.","114 is correct.","Round both to 10."]',0,'Estimate!','Sanity check the decimal placement.','2026-11-01 17:48:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0318','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Synthesize: A 4.8m rope is cut into 4 equal pieces. Length of each?','["1.2m","1.4m","0.12m","12m"]',0,'Divide.','4.8 / 4 = 1.2.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0319','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Analyze: Why is it risky to just teach ''moving the decimal point'' when multiplying by 10?','["Because it obscures the fundamental mathematical concept that the *digits themselves* are shifting to higher place value columns.","It''s the best way to teach it.","Because the point disappears.","It isn''t risky."]',0,'Place value.','Focus on the value of the digits changing, not the dot moving.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0320','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Critique: ''Hannah calculated 0.25 x 2 by doing 25x2=50, and since 0.25 has two decimal places, they wrote 0.50, which is 0.5.''','["This method (temporarily ignoring the decimal, calculating, then restoring place values) is perfectly valid and correct.","False, they must keep all zeros.","False, the answer is 5.","False, you cannot ignore the decimal."]',0,'It works!','This is the standard algorithm for decimal multiplication.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0321','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Synthesize: Calculate 0.08 ÷ 10.','["0.008","0.8","0.080","8"]',0,'Divide by 10.','Shifts one more place to the right.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0322','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Evaluate: If 3 bottles hold 0.5 L each, what is the total volume?','["1.5 L (0.5 x 3)","15 L","0.15 L","1.0 L"]',0,'Multiply.','5x3=15, one decimal place.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0323','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Analyze: How can estimation catch the error if someone writes 19 x 0.6 = 114?','["Rounding 19 to 20, and 0.6 to 0.5 (half). Half of 20 is 10. The answer 114 is 10x too big. It should be 11.4.","Estimation can''t catch this.","114 is correct.","Round both to 10."]',0,'Estimate!','Sanity check the decimal placement.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0324','Maths','Decimals','Subtopic 9: Multiplication and Division of Decimals — Introductory','Primary',10,'Synthesize: A 4.8m rope is cut into 4 equal pieces. Length of each?','["1.2m","1.4m","0.12m","12m"]',0,'Divide.','4.8 / 4 = 1.2.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0325','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'What does ''rounding a decimal'' mean?','["Replacing it with a nearby, simpler number (like rounding 4.8 to 5).","Removing the decimal point.","Adding zeros to it.","Making it negative."]',0,'Friendly numbers.','It makes the number easier to work with.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0326','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'If the digit you are checking is 0, 1, 2, 3, or 4, what do you do to the target digit?','["Keep the target digit the same (round down).","Increase it by 1.","Add 5 to it.","Delete it."]',0,'Stay the same.','0-4 means stay on the floor.','2026-11-01 17:48:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0327','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'If the digit you are checking is 5, 6, 7, 8, or 9, what do you do?','["Increase the target digit by 1 (round up).","Keep it the same.","Subtract 1.","Delete it."]',0,'Go up 1.','5-9 means climb the vine (round up).','2026-11-01 17:48:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0328','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'Round 6.3 to the nearest whole number.','["6","7","6.5","6.03"]',0,'Closer to 6 or 7?','Tenths digit is 3 (keep it the same).','2026-11-01 17:48:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0329','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'Round 6.8 to the nearest whole number.','["7","6","6.5","6.9"]',0,'Closer to 6 or 7?','Tenths digit is 8 (round up).','2026-11-01 17:48:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0330','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',1,'Round 9.5 to the nearest whole number.','["10","9","9.0","9.6"]',0,'5 rounds up.','Tenths digit is 5 (round up).','2026-11-01 17:48:21',NULL,NULL);
