INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0337','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'To round to the nearest tenth, which digit do you look at?','["The hundredths digit (the second digit after the dot).","The tenths digit.","The ones digit.","The thousandths digit."]',0,'Look right.','Always look one place to the right of your target.','2026-11-01 17:48:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0338','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'Round 3.42 to the nearest tenth.','["3.4","3.5","3.40","3.0"]',0,'Look at the 2.','Hundredths digit is 2, so keep the 4.','2026-11-01 17:48:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0339','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'Round 3.47 to the nearest tenth.','["3.5","3.4","3.50","3.0"]',0,'Look at the 7.','Hundredths digit is 7, so increase the 4 to 5.','2026-11-01 17:48:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0340','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'Round 8.234 to the nearest hundredth.','["8.23","8.24","8.20","8.230"]',0,'Look at the 4.','Thousandths digit is 4, keep the 3.','2026-11-01 17:48:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0341','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'Round 8.237 to the nearest hundredth.','["8.24","8.23","8.20","8.240"]',0,'Look at the 7.','Thousandths digit is 7, increase 3 to 4.','2026-11-01 17:48:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0342','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'A table is 1.87 m long. Round to the nearest tenth.','["1.9 m","1.8 m","2.0 m","1.80 m"]',0,'Look at the 7.','Hundredths is 7, round up.','2026-11-01 17:48:22',NULL,NULL);
