INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0348','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',5,'A table is 1.87 m long. Round to the nearest tenth.','["1.9 m","1.8 m","2.0 m","1.80 m"]',0,'Look at the 7.','Hundredths is 7, round up.','2026-11-01 17:48:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0349','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Analyze the cascade effect: Round 2.96 to the nearest tenth.','["3.0 (The 6 rounds the 9 up to 10, which carries over to make the 2 a 3).","2.9","3.1","2.10"]',0,'Carry the 1.','The 9 becomes a 10, pushing a 1 to the whole numbers.','2026-11-01 17:48:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0350','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Critique: ''Bob rounded 4.998 to the nearest hundredth and wrote 5. Is this perfectly correct?''','["No, they must write 5.00 to indicate the precision of the rounding to the hundredths place.","Yes, 5 and 5.00 are exactly the same.","No, it should be 4.99.","No, it should be 4.100."]',0,'Significant figures.','The zeros indicate the level of precision requested.','2026-11-01 17:48:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0351','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Synthesize: Round 7.4628 to the nearest thousandth.','["7.463","7.462","7.460","7.464"]',0,'Look at the 8.','Ten-thousandths digit is 8, so the 2 rounds up to 3.','2026-11-01 17:48:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0352','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Evaluate the mistake: ''Rounding 7.86 to the nearest whole number and getting 7.''','["They simply deleted the decimal digits without checking the tenths digit (8) to round up.","It is correct.","They should have gotten 9.","They forgot to carry."]',0,'Don''t just chop it off.','Truncating is not rounding.','2026-11-01 17:48:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0353','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Analyze: When dealing with medicine doses or money payments, why is rounding sometimes dangerous?','["These situations require exact precision; an approximation could result in an underpayment or a dangerous overdose.","It isn''t dangerous.","Because numbers are too small.","Because calculators break."]',0,'Exact vs Approx.','Rounding sacrifices accuracy for simplicity.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0354','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Critique: ''Fiona rounded 5.268 to the nearest tenth by checking the 8, rounding the 6 to 7, and then the 7 rounded the 2 to 3, getting 5.3.''','["False, you NEVER chain-round. You only check the single digit immediately to the right (the 6) to round the 2 to 3.","True, cascade rounding is how it works.","False, answer is 5.2.","False, answer is 5.0."]',0,'Don''t cause a domino effect.','Check exactly ONE digit to the right.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0355','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Analyze the cascade effect: Round 2.96 to the nearest tenth.','["3.0 (The 6 rounds the 9 up to 10, which carries over to make the 2 a 3).","2.9","3.1","2.10"]',0,'Carry the 1.','The 9 becomes a 10, pushing a 1 to the whole numbers.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0356','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Critique: ''Hannah rounded 4.998 to the nearest hundredth and wrote 5. Is this perfectly correct?''','["No, they must write 5.00 to indicate the precision of the rounding to the hundredths place.","Yes, 5 and 5.00 are exactly the same.","No, it should be 4.99.","No, it should be 4.100."]',0,'Significant figures.','The zeros indicate the level of precision requested.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0357','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Synthesize: Round 7.4628 to the nearest thousandth.','["7.463","7.462","7.460","7.464"]',0,'Look at the 8.','Ten-thousandths digit is 8, so the 2 rounds up to 3.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0358','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Evaluate the mistake: ''Rounding 7.86 to the nearest whole number and getting 7.''','["They simply deleted the decimal digits without checking the tenths digit (8) to round up.","It is correct.","They should have gotten 9.","They forgot to carry."]',0,'Don''t just chop it off.','Truncating is not rounding.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0359','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Analyze: When dealing with medicine doses or money payments, why is rounding sometimes dangerous?','["These situations require exact precision; an approximation could result in an underpayment or a dangerous overdose.","It isn''t dangerous.","Because numbers are too small.","Because calculators break."]',0,'Exact vs Approx.','Rounding sacrifices accuracy for simplicity.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0360','Maths','Decimals','Subtopic 10: Rounding Decimals','Primary',10,'Critique: ''Liam rounded 5.268 to the nearest tenth by checking the 8, rounding the 6 to 7, and then the 7 rounded the 2 to 3, getting 5.3.''','["False, you NEVER chain-round. You only check the single digit immediately to the right (the 6) to round the 2 to 3.","True, cascade rounding is how it works.","False, answer is 5.2.","False, answer is 5.0."]',0,'Don''t cause a domino effect.','Check exactly ONE digit to the right.','2026-11-01 17:48:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0361','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'Read: ''Alice buys a notebook for $3.75 and a pen for $1.50. Total cost?'' Which operation?','["Addition","Subtraction","Multiplication","Division"]',0,'Total.','Combining costs is addition.','2026-11-01 17:48:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0362','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'Read: ''A container has 5.0 L of water. 2 L are used. How much remains?'' Which operation?','["Subtraction","Addition","Multiplication","Division"]',0,'Remains.','Finding what is left over.','2026-11-01 17:48:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0363','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'Read: ''One book costs $2.45. Cost of 4 books?'' Which operation?','["Multiplication","Addition","Subtraction","Division"]',0,'Groups of.','Repeated quantities.','2026-11-01 17:48:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0364','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'Read: ''2.4 L of juice is shared equally among 6 people.'' Which operation?','["Division","Multiplication","Addition","Subtraction"]',0,'Share.','Sharing equally.','2026-11-01 17:48:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0365','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'What is the first step in solving a decimal word problem?','["Read the problem carefully and identify what is known and what you need to find.","Guess the answer.","Add all the numbers you see.","Ignore the decimals."]',0,'Read.','Understand the problem first.','2026-11-01 17:48:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0366','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',1,'A rope is 8.6 m long. Another is 5.85 m. Which operation finds ''how much longer''?','["Subtraction","Addition","Multiplication","Division"]',0,'Difference.','Comparing amounts.','2026-11-01 17:48:25',NULL,NULL);
