INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0373','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Solve: A notebook costs $3.75, pen $1.50. Total?','["$5.25","$4.25","$5.00","$4.80"]',0,'Line up decimals.','3.75 + 1.50 = 5.25.','2026-11-01 17:48:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0374','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Solve: Walk 1.35 km morning, 2.4 km evening. Total?','["3.75 km","3.39 km","3.79 km","1.59 km"]',0,'Add a zero to 2.4.','1.35 + 2.40 = 3.75.','2026-11-01 17:48:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0375','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Solve: 5.0 L container, 1.75 L used. Remaining?','["3.25 L","4.25 L","3.75 L","4.75 L"]',0,'Borrow across zeros.','5.00 - 1.75 = 3.25.','2026-11-01 17:48:26',NULL,NULL);
