INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0377','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Solve: 7.5 m ribbon cut into 5 equal pieces. Length of each?','["1.5 m","1.0 m","2.5 m","1.2 m"]',0,'Divide.','7.5 / 5 = 1.5.','2026-11-01 17:48:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0378','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Estimate to check: $4.80 toy + $3.20 game.','["8","7","9","10"]',0,'Round then add.','5 + 3 = 8.','2026-11-01 17:48:26',NULL,NULL);
