INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0384','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',5,'Estimate to check: $4.80 toy + $3.20 game.','["8","7","9","10"]',0,'Round then add.','5 + 3 = 8.','2026-11-01 17:48:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0385','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize the multi-step problem: Alice buys a bag ($12.75) and bottle ($3.60). Pays with a $20 bill. Change?','["$3.65","$4.65","$3.35","$16.35"]',0,'Add costs, subtract from 20.','12.75+3.60 = 16.35. 20.00 - 16.35 = 3.65.','2026-11-01 17:48:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0386','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize the multi-step problem: Cyclist goes 4.65 km day 1, 5.8 km day 2. Goal is 15 km. How much further?','["4.55 km","5.55 km","10.45 km","4.45 km"]',0,'Add parts, subtract from total.','4.65+5.80 = 10.45. 15.00 - 10.45 = 4.55.','2026-11-01 17:48:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0387','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Critique the mistake: ''A problem asks how much heavier bag A (5.2kg) is than bag B (3.15kg). Charlie did 5.2 + 3.15.''','["False, asking ''how much heavier'' is a comparison requiring subtraction, not addition.","True, heavier means add.","False, they should multiply.","False, they should divide."]',0,'Difference = subtract.','Comparing amounts means finding the difference.','2026-11-01 17:48:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0388','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Analyze the mistake: ''Diana added 2.40 + 1.35 but misaligned the decimal points, adding the 4 to the 5.''','["Decimals must always be aligned by the decimal point to ensure tenths are added to tenths, and hundredths to hundredths.","It''s fine as long as they add a zero.","Decimals should align on the right.","They should ignore the decimal."]',0,'Align the dots.','Place value alignment is strictly required.','2026-11-01 17:48:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0389','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Evaluate: Why is it crucial to keep track of units (like kg, $, km) in word problems?','["To ensure you aren''t adding or subtracting incompatible quantities, and to give meaning to the final number.","To make the problem longer.","Units are just for science.","It doesn''t matter."]',0,'Apples vs oranges.','Context prevents logical errors.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0390','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize: Fiona buys 3 items at $2.40 each and pays with a $10 bill. Estimate the change.','["Around $3 (3x$2=$6, $10-$6=$4; or 3x$2.50=$7.50, $10-$7.50=$2.50).","Around $1","Around $5","Around $0"]',0,'Round and calculate.','3 x 2.40 = 7.20. 10 - 7.20 = 2.80. Estimate is ~3.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0391','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize the multi-step problem: George buys a bag ($12.75) and bottle ($3.60). Pays with a $20 bill. Change?','["$3.65","$4.65","$3.35","$16.35"]',0,'Add costs, subtract from 20.','12.75+3.60 = 16.35. 20.00 - 16.35 = 3.65.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0392','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize the multi-step problem: Cyclist goes 4.65 km day 1, 5.8 km day 2. Goal is 15 km. How much further?','["4.55 km","5.55 km","10.45 km","4.45 km"]',0,'Add parts, subtract from total.','4.65+5.80 = 10.45. 15.00 - 10.45 = 4.55.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0393','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Critique the mistake: ''A problem asks how much heavier bag A (5.2kg) is than bag B (3.15kg). Ian did 5.2 + 3.15.''','["False, asking ''how much heavier'' is a comparison requiring subtraction, not addition.","True, heavier means add.","False, they should multiply.","False, they should divide."]',0,'Difference = subtract.','Comparing amounts means finding the difference.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0394','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Analyze the mistake: ''Julia added 2.40 + 1.35 but misaligned the decimal points, adding the 4 to the 5.''','["Decimals must always be aligned by the decimal point to ensure tenths are added to tenths, and hundredths to hundredths.","It''s fine as long as they add a zero.","Decimals should align on the right.","They should ignore the decimal."]',0,'Align the dots.','Place value alignment is strictly required.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0395','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Evaluate: Why is it crucial to keep track of units (like kg, $, km) in word problems?','["To ensure you aren''t adding or subtracting incompatible quantities, and to give meaning to the final number.","To make the problem longer.","Units are just for science.","It doesn''t matter."]',0,'Apples vs oranges.','Context prevents logical errors.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t5_global_0396','Maths','Decimals','Subtopic 11: Decimal Word Problems','Primary',10,'Synthesize: Liam buys 3 items at $2.40 each and pays with a $10 bill. Estimate the change.','["Around $3 (3x$2=$6, $10-$6=$4; or 3x$2.50=$7.50, $10-$7.50=$2.50).","Around $1","Around $5","Around $0"]',0,'Round and calculate.','3 x 2.40 = 7.20. 10 - 7.20 = 2.80. Estimate is ~3.','2026-11-01 17:48:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0001','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'What does it mean to ''compare'' quantities?','["To examine two or more amounts and describe how they are related (e.g. which is bigger).","To add them all together into one big pile.","To ignore the smaller amount.","To multiply them."]',0,'Looking at differences.','Comparing is looking at the relationship.','2026-11-01 17:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0002','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'Bob has 10 cookies and Charlie has 6. How many MORE cookies does Bob have?','["4","16","60","2"]',0,'Find the difference.','10 - 6 = 4. This is an additive comparison.','2026-11-01 17:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0003','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'Charlie scores 20 points and Diana scores 15. How many FEWER points did Diana score?','["5","35","10","15"]',0,'Find the difference.','20 - 15 = 5.','2026-11-01 17:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0004','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'When a question asks ''How many more?'' or ''How many fewer?'', what math operation should you usually use?','["Subtraction","Addition","Multiplication","Division"]',0,'Difference.','Finding the difference requires subtraction.','2026-11-01 17:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0005','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'A big box has 12 crayons and a small box has 4 crayons. How many TIMES as many crayons are in the big box?','["3 times as many.","8 times as many.","16 times as many.","4 times as many."]',0,'Divide the big by the small.','12 / 4 = 3. This is a multiplicative comparison.','2026-11-01 17:49:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0006','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'What is an ''additive comparison''?','["Finding the difference between amounts (using subtraction).","Finding how many times one amount is another (using division).","Adding zero.","Comparing letters."]',0,'Uses subtraction.','Additive compares the gap.','2026-11-01 17:49:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0007','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',1,'What does it mean to ''compare'' quantities?','["To examine two or more amounts and describe how they are related (e.g. which is bigger).","To add them all together into one big pile.","To ignore the smaller amount.","To multiply them."]',0,'Looking at differences.','Comparing is looking at the relationship.','2026-11-01 17:49:36',NULL,NULL);
