INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0013','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'A plant is 20 cm tall and another is 5 cm tall. How many times as tall is the first plant?','["4 times","15 times","5 times","3 times"]',0,'Multiplicative comparison.','20 / 5 = 4.','2026-11-01 17:49:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0014','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'A library has 50 fiction books and 30 science books. What is the difference?','["20","80","10","30"]',0,'Subtract.','(50) - (30) = 20.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0015','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'What is the difference between ''How much more?'' and ''How many times as much?''','["''How much more'' asks for a difference (subtraction), while ''How many times as much'' asks for a quotient (division).","They mean the exact same thing.","''How much more'' is multiplication.","They are both addition."]',0,'Difference vs Quotient.','Different questions need different math.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0016','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'If Container A has 15 liters, B has 10, and C has 5. How much greater is the largest amount than the smallest?','["10 liters","5 liters","20 liters","15 liters"]',0,'Largest minus smallest.','15 (largest) - 5 (smallest) = 10.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0017','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'If Container A has 15 liters, B has 10, and C has 5. How many TIMES greater is the largest than the smallest?','["3 times","2 times","10 times","5 times"]',0,'Multiplicative comparison.','15 / 5 = 3.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0018','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'Fiona reads 14 books, George reads 7. Fiona says they read 2 times as many. Is this correct?','["Yes, 14 / 7 = 2.","No, they read 7 times as many.","No, they read 21 times as many.","Cannot tell."]',0,'Check the division.','Multiplicative comparison is correct.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0019','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'A plant is 25 cm tall and another is 5 cm tall. How many times as tall is the first plant?','["5 times","20 times","6 times","4 times"]',0,'Multiplicative comparison.','25 / 5 = 5.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0020','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'A library has 60 fiction books and 40 science books. What is the difference?','["20","100","10","30"]',0,'Subtract.','(60) - (40) = 20.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0021','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'What is the difference between ''How much more?'' and ''How many times as much?''','["''How much more'' asks for a difference (subtraction), while ''How many times as much'' asks for a quotient (division).","They mean the exact same thing.","''How much more'' is multiplication.","They are both addition."]',0,'Difference vs Quotient.','Different questions need different math.','2026-11-01 17:49:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0022','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'If Container A has 15 liters, B has 10, and C has 5. How much greater is the largest amount than the smallest?','["10 liters","5 liters","20 liters","15 liters"]',0,'Largest minus smallest.','15 (largest) - 5 (smallest) = 10.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0023','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'If Container A has 15 liters, B has 10, and C has 5. How many TIMES greater is the largest than the smallest?','["3 times","2 times","10 times","5 times"]',0,'Multiplicative comparison.','15 / 5 = 3.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0024','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',5,'Liam reads 14 books, Alice reads 7. Liam says they read 2 times as many. Is this correct?','["Yes, 14 / 7 = 2.","No, they read 7 times as many.","No, they read 21 times as many.","Cannot tell."]',0,'Check the division.','Multiplicative comparison is correct.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0025','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Analyze the table: Reading=14 books, Science=6 books. Is it accurate to say Reading has ''2 and 1/3 times'' as many books as Science?','["Yes, because 14 / 6 = 2 2/6, which simplifies to 2 1/3.","No, multiplicative comparisons must always result in whole numbers.","No, it is 8 times as many.","No, it is exactly 2 times as many."]',0,'Fractional multipliers.','Multiplicative comparisons can result in fractions.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0026','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Critique: ''Bob has 20 cookies. Charlie has 5. Bob says they have 4 more cookies than Charlie.''','["False, they have 15 more (additive), but they have 4 TIMES as many (multiplicative).","True.","False, they have 5 more.","False, they have 25 more."]',0,'More vs Times.','Mixing up additive and multiplicative language.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0027','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Synthesize: If quantity A is 3 times as large as quantity B, and B is 4, what is the difference between A and B?','["8 (Because A is 12, and 12 - 4 = 8).","12","7","3"]',0,'Multi-step comparison.','Find A first, then subtract.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0028','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Evaluate: When comparing three quantities (A, B, C), can A be multiplicatively compared to B, while B is additively compared to C?','["Yes, you can describe different relationships between different pairs in the same dataset.","No, you must pick one method.","Only if they are all even.","Only if A is the biggest."]',0,'Mix and match.','Different comparisons for different contexts.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0029','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Analyze: Ethan grows a plant from 10cm to 30cm. Did it grow by 20cm, or did it grow 3 times as tall?','["Both statements are mathematically correct descriptions of the same growth using different comparison methods.","Only ''grew by 20cm'' is correct.","Only ''3 times as tall'' is correct.","Neither is correct."]',0,'Look at both perspectives.','Additive (30-10) and Multiplicative (30/10).','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0030','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Critique: ''If I have 10 apples and you have 0, I have 10 times as many apples as you.''','["False, multiplicative comparison involving zero is undefined (10 / 0). You just have 10 MORE apples.","True.","False, you have 0 times as many.","True, 10 x 0 = 10."]',0,'Cannot divide by 0.','Division by zero.','2026-11-01 17:49:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0031','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Analyze the table: Reading=14 books, Science=6 books. Is it accurate to say Reading has ''2 and 1/3 times'' as many books as Science?','["Yes, because 14 / 6 = 2 2/6, which simplifies to 2 1/3.","No, multiplicative comparisons must always result in whole numbers.","No, it is 8 times as many.","No, it is exactly 2 times as many."]',0,'Fractional multipliers.','Multiplicative comparisons can result in fractions.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0032','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Critique: ''Hannah has 20 shells. Ian has 5. Hannah says they have 4 more shells than Ian.''','["False, they have 15 more (additive), but they have 4 TIMES as many (multiplicative).","True.","False, they have 5 more.","False, they have 25 more."]',0,'More vs Times.','Mixing up additive and multiplicative language.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0033','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Synthesize: If quantity A is 3 times as large as quantity B, and B is 4, what is the difference between A and B?','["8 (Because A is 12, and 12 - 4 = 8).","12","7","3"]',0,'Multi-step comparison.','Find A first, then subtract.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0034','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Evaluate: When comparing three quantities (A, B, C), can A be multiplicatively compared to B, while B is additively compared to C?','["Yes, you can describe different relationships between different pairs in the same dataset.","No, you must pick one method.","Only if they are all even.","Only if A is the biggest."]',0,'Mix and match.','Different comparisons for different contexts.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0035','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Analyze: Kevin grows a plant from 10cm to 30cm. Did it grow by 20cm, or did it grow 3 times as tall?','["Both statements are mathematically correct descriptions of the same growth using different comparison methods.","Only ''grew by 20cm'' is correct.","Only ''3 times as tall'' is correct.","Neither is correct."]',0,'Look at both perspectives.','Additive (30-10) and Multiplicative (30/10).','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0036','Maths','Ratio, Proportion and Percentages','Subtopic 1: Comparing Quantities','Primary',10,'Critique: ''If I have 10 apples and you have 0, I have 10 times as many apples as you.''','["False, multiplicative comparison involving zero is undefined (10 / 0). You just have 10 MORE apples.","True.","False, you have 0 times as many.","True, 10 x 0 = 10."]',0,'Cannot divide by 0.','Division by zero.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0037','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'What does a ''ratio'' do in math?','["It compares two or more quantities by showing how much of one quantity there is in relation to another.","It adds numbers together.","It finds the exact difference.","It measures length."]',0,'Comparison.','Ratios compare parts.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0038','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'What symbol is normally used to write a ratio?','["A colon (:)","A plus (+)","A dash (-)","A slash (/)"]',0,'Two dots.','We use a colon, like 3:2.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0039','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'If a basket has 3 books and 2 oranges, what is the ratio of books to oranges?','["3:2","2:3","5:3","3:5"]',0,'Read the words in order.','The order matters. The first word is the first number.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0040','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'How do you read the ratio ''4:7'' out loud?','["Four to seven.","Four plus seven.","Four point seven.","Seven to four."]',0,'Read left to right.','The colon is read as ''to''.','2026-11-01 17:49:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0041','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'If there are 4 blue crayons and 7 yellow crayons, what is the ratio of YELLOW to BLUE?','["7:4","4:7","11:7","7:11"]',0,'Look at the order in the question.','Order matters! Yellow is asked for first.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0042','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'Is a ratio the same thing as a difference (subtraction)?','["No, a ratio compares relative sizes, while difference finds the exact gap.","Yes.","Only for even numbers.","Only if they are equal."]',0,'Relative vs Absolute.','3:2 means for every 3, there are 2. Not that there is 1 more.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0043','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'What does a ''ratio'' do in math?','["It compares two or more quantities by showing how much of one quantity there is in relation to another.","It adds numbers together.","It finds the exact difference.","It measures length."]',0,'Comparison.','Ratios compare parts.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0044','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'What symbol is normally used to write a ratio?','["A colon (:)","A plus (+)","A dash (-)","A slash (/)"]',0,'Two dots.','We use a colon, like 3:2.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0045','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'If a basket has 3 leaves and 2 oranges, what is the ratio of leaves to oranges?','["3:2","2:3","5:3","3:5"]',0,'Read the words in order.','The order matters. The first word is the first number.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0046','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'How do you read the ratio ''4:7'' out loud?','["Four to seven.","Four plus seven.","Four point seven.","Seven to four."]',0,'Read left to right.','The colon is read as ''to''.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0047','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'If there are 4 blue apples and 7 yellow apples, what is the ratio of YELLOW to BLUE?','["7:4","4:7","11:7","7:11"]',0,'Look at the order in the question.','Order matters! Yellow is asked for first.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0048','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',1,'Is a ratio the same thing as a difference (subtraction)?','["No, a ratio compares relative sizes, while difference finds the exact gap.","Yes.","Only for even numbers.","Only if they are equal."]',0,'Relative vs Absolute.','3:2 means for every 3, there are 2. Not that there is 1 more.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0049','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'What is a ''part-to-part'' ratio?','["A ratio that compares one specific group with another specific group (e.g. boys to girls).","A ratio that compares a group to the total.","A fraction.","A mistake."]',0,'Comparing groups.','Part vs Part.','2026-11-01 17:49:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0050','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'What is a ''part-to-whole'' ratio?','["A ratio that compares one specific part with the entire combined group (e.g. boys to all students).","A ratio that compares two small groups.","An addition problem.","An improper fraction."]',0,'Comparing to everything.','Part vs Total.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0051','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'A bag has 3 green books and 5 yellow books. What is the part-to-whole ratio of green books to ALL books?','["3:8","3:5","5:8","8:3"]',0,'Find the total first.','Total is 3+5=8. Green to total is 3:8.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0052','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'A box has 2 red, 3 blue, and 4 green marbles. What is the ratio of red to blue to green?','["2:3:4","2:4:3","9:2:3","4:3:2"]',0,'Keep the order.','Ratios can compare three quantities in order.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0053','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'In the box (2 red, 3 blue, 4 green crayons), what is the ratio of blue crayons to ALL crayons?','["3:9","3:7","2:9","4:9"]',0,'Find the total.','Total is 2+3+4=9. Blue is 3.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0054','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'Compare 2 meters to 50 centimeters as a ratio. What must you do first?','["Convert 2 meters to 200 centimeters, so the ratio is 200:50.","Write 2:50.","Write 50:2.","Add them."]',0,'Make the units match.','Units MUST be the same before comparing.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0055','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'What is a ''part-to-part'' ratio?','["A ratio that compares one specific group with another specific group (e.g. boys to girls).","A ratio that compares a group to the total.","A fraction.","A mistake."]',0,'Comparing groups.','Part vs Part.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0056','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'What is a ''part-to-whole'' ratio?','["A ratio that compares one specific part with the entire combined group (e.g. boys to all students).","A ratio that compares two small groups.","An addition problem.","An improper fraction."]',0,'Comparing to everything.','Part vs Total.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0057','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'A bag has 3 green leaves and 5 yellow leaves. What is the part-to-whole ratio of green leaves to ALL leaves?','["3:8","3:5","5:8","8:3"]',0,'Find the total first.','Total is 3+5=8. Green to total is 3:8.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0058','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'A box has 2 red, 3 blue, and 4 green blocks. What is the ratio of red to blue to green?','["2:3:4","2:4:3","9:2:3","4:3:2"]',0,'Keep the order.','Ratios can compare three quantities in order.','2026-11-01 17:49:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0059','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'In the box (2 red, 3 blue, 4 green apples), what is the ratio of blue apples to ALL apples?','["3:9","3:7","2:9","4:9"]',0,'Find the total.','Total is 2+3+4=9. Blue is 3.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0060','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',5,'Compare 2 meters to 50 centimeters as a ratio. What must you do first?','["Convert 2 meters to 200 centimeters, so the ratio is 200:50.","Write 2:50.","Write 50:2.","Add them."]',0,'Make the units match.','Units MUST be the same before comparing.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0061','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Critique: ''Alice says that if the ratio of cats to dogs is 2:3, then 2/5 of the animals are cats.''','["True, because the total parts are 2+3=5, making cats 2 out of the whole 5.","False, 2/3 of the animals are cats.","False, cats are 3/5.","True, because 2+3=5."]',0,'Part / (Part + Part).','Part-to-whole can be expressed as a fraction.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0062','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Analyze the unit conversion: Write the ratio of 1 Litre to 250 millilitres.','["1000:250","1:250","250:1","100:250"]',0,'Convert to mL.','1 L = 1000 mL. They must be in the same unit.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0063','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Evaluate: Why is it mathematically invalid to write a ratio like 2 cm : 5 kg?','["Because ratios compare quantities of the same kind; you cannot logically compare a length to a mass directly in this way.","It is valid.","Because 5 is bigger than 2.","Because cm is metric."]',0,'Apples to oranges.','Ratios compare ''like'' things.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0064','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Synthesize: If the ratio of adults to children is 4:6, and there are 40 adults, how many children are there?','["60","40","12","16"]',0,'Multiply both sides of the ratio by the same amount.','The ratio is scaled by x10.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0065','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Analyze: If a part-to-part ratio is 1:1, what does that mean about the quantities?','["They are exactly equal in amount.","One is bigger.","They are both 1.","They are zero."]',0,'Equal parts.','For every 1 of A, there is 1 of B.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0066','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Critique: ''A part-to-whole ratio can never have the first number larger than the second number.''','["True, because a part cannot be physically larger than the whole it belongs to (unless dealing with theoretical percentages > 100%).","False, it happens all the time.","True, but only for even numbers.","False, wholes are small."]',0,'Part is inside the whole.','The whole encompasses all parts.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0067','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Critique: ''George says that if the ratio of cats to dogs is 2:3, then 2/5 of the animals are cats.''','["True, because the total parts are 2+3=5, making cats 2 out of the whole 5.","False, 2/3 of the animals are cats.","False, cats are 3/5.","True, because 2+3=5."]',0,'Part / (Part + Part).','Part-to-whole can be expressed as a fraction.','2026-11-01 17:49:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0068','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Analyze the unit conversion: Write the ratio of 1 Litre to 250 millilitres.','["1000:250","1:250","250:1","100:250"]',0,'Convert to mL.','1 L = 1000 mL. They must be in the same unit.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0069','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Evaluate: Why is it mathematically invalid to write a ratio like 2 cm : 5 kg?','["Because ratios compare quantities of the same kind; you cannot logically compare a length to a mass directly in this way.","It is valid.","Because 5 is bigger than 2.","Because cm is metric."]',0,'Apples to oranges.','Ratios compare ''like'' things.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0070','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Synthesize: If the ratio of adults to children is 5:7, and there are 50 adults, how many children are there?','["70","50","14","17"]',0,'Multiply both sides of the ratio by the same amount.','The ratio is scaled by x10.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0071','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Analyze: If a part-to-part ratio is 1:1, what does that mean about the quantities?','["They are exactly equal in amount.","One is bigger.","They are both 1.","They are zero."]',0,'Equal parts.','For every 1 of A, there is 1 of B.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0072','Maths','Ratio, Proportion and Percentages','Subtopic 2: Understanding Ratios','Primary',10,'Critique: ''A part-to-whole ratio can never have the first number larger than the second number.''','["True, because a part cannot be physically larger than the whole it belongs to (unless dealing with theoretical percentages > 100%).","False, it happens all the time.","True, but only for even numbers.","False, wholes are small."]',0,'Part is inside the whole.','The whole encompasses all parts.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0073','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'What are three different ways to write a ratio?','["With a colon (4:6), in words (4 to 6), or as a fraction (4/6).","Only with a colon.","With decimals.","With a plus sign."]',0,'Colon, words, fraction.','Ratios are flexible in notation.','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0074','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'If you write the ratio of 4 red pencils to 6 blue pencils as a fraction, what is it?','["4/6","6/4","10/4","4/10"]',0,'First thing goes on top.','The first quantity goes on top (numerator).','2026-11-01 17:49:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0075','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'Does the order matter when writing a ratio?','["Yes, it must clearly state which quantity comes first based on the question.","No.","Only for fractions.","Only for big numbers."]',0,'Order is critical.','Red to Blue is different from Blue to Red.','2026-11-01 17:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0076','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'A class has 7 boys and 9 girls. Write the ratio of boys to girls in words.','["7 to 9","9 to 7","7 and 9","16 to 7"]',0,'Follow the prompt.','Boys first, then girls.','2026-11-01 17:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0077','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'If you see ''3 to 5'', how do you write it with a colon?','["3:5","5:3","3.5","3/5"]',0,'Colon replacement.','Just swap ''to'' with '':''.','2026-11-01 17:49:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0078','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',1,'If a group has 2 green balls and 3 yellow balls, what is the part-to-part ratio of green to yellow?','["2:3","3:2","2:5","5:2"]',0,'Green first.','Part (green) to Part (yellow).','2026-11-01 17:49:44',NULL,NULL);
