INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0085','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'A group has 2 green apples and 3 yellow apples. Write the part-to-WHOLE ratio of green to total as a fraction.','["2/5","2/3","3/5","5/2"]',0,'Find the total.','Total is 5. Green is 2. 2/5.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0086','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'If a basket has 3 apples, 4 oranges, and 2 pears. Write the ratio of apples to oranges to pears.','["3:4:2","2:3:4","4:3:2","3:2:4"]',0,'Apples, Oranges, Pears.','Keep the exact order requested.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0087','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'In the same basket (3 apples, 4 oranges, 2 pears), what is the ratio of Pears to Apples to Oranges?','["2:3:4","3:4:2","4:2:3","2:4:3"]',0,'Pears, Apples, Oranges.','Change the numbers to match the new order.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0088','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Why is it wrong to say that 2 green and 3 yellow balls means green makes up 2/3 of the whole?','["Because the whole is 5 balls. Green makes up 2/5 of the whole, not 2/3. (2/3 is a part-to-part comparison).","It isn''t wrong.","Because green is 3/5.","Because fractions can''t be colors."]',0,'What is the total?','Don''t confuse part-to-part ratios with fractions of a whole.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0089','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Convert to write a ratio: 1 Litre to 250 millilitres.','["1000:250","1:250","250:1000","100:25"]',0,'Same units.','1 L = 1000 mL.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0090','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Convert to write a ratio: 2 meters to 50 centimeters.','["200:50","2:50","50:200","20:50"]',0,'Same units.','2 m = 200 cm.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0091','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'A group has 2 green toys and 3 yellow toys. Write the part-to-WHOLE ratio of green to total as a fraction.','["2/5","2/3","3/5","5/2"]',0,'Find the total.','Total is 5. Green is 2. 2/5.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0092','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'If a basket has 3 apples, 4 oranges, and 2 pears. Write the ratio of apples to oranges to pears.','["3:4:2","2:3:4","4:3:2","3:2:4"]',0,'Apples, Oranges, Pears.','Keep the exact order requested.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0093','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'In the same basket (3 apples, 4 oranges, 2 pears), what is the ratio of Pears to Apples to Oranges?','["2:3:4","3:4:2","4:2:3","2:4:3"]',0,'Pears, Apples, Oranges.','Change the numbers to match the new order.','2026-11-01 17:49:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0094','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Why is it wrong to say that 2 green and 3 yellow balls means green makes up 2/3 of the whole?','["Because the whole is 5 balls. Green makes up 2/5 of the whole, not 2/3. (2/3 is a part-to-part comparison).","It isn''t wrong.","Because green is 3/5.","Because fractions can''t be colors."]',0,'What is the total?','Don''t confuse part-to-part ratios with fractions of a whole.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0095','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Convert to write a ratio: 1 Litre to 250 millilitres.','["1000:250","1:250","250:1000","100:25"]',0,'Same units.','1 L = 1000 mL.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0096','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',5,'Convert to write a ratio: 2 meters to 50 centimeters.','["200:50","2:50","50:200","20:50"]',0,'Same units.','2 m = 200 cm.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0097','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Analyze: Why does fraction notation (like 4/6) for a part-to-part ratio sometimes confuse students?','["Because fractions are almost exclusively taught as part-to-WHOLE relationships; using them for part-to-part breaks that mental model.","Because fractions are hard to read.","It doesn''t confuse anyone.","Because they should be decimals."]',0,'Part/Whole vs Part/Part.','4/6 as a ratio doesn''t mean ''4 out of 6 total'', it means ''4 of this for every 6 of that''.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0098','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Synthesize: If Bob mixes 2 cups of syrup to 3 cups of water, what fraction of the ENTIRE drink is syrup?','["2/5","2/3","3/5","1/5"]',0,'Find the total parts.','Total parts = 5. Syrup = 2.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0099','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Evaluate the mistake: ''Writing the ratio of 5 cm to 2 km as 5:2.''','["False, they completely ignored the units. It should be converted to 5 : 200,000 (since 2 km = 200,000 cm).","True, 5 and 2 are the numbers.","False, it should be 2:5.","False, it should be 5:20."]',0,'Check the metric conversion.','Units MUST match before numbers are compared.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0100','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Critique: ''Diana says that the ratio 3:4:2 cannot be written as a fraction.''','["True, standard fraction notation (a/b) only accommodates two quantities.","False, it can be written as 3/4/2.","False, it is 9.","True, because they are odd."]',0,'How many parts in a fraction?','Fractions only have a top and bottom.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0101','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Synthesize: Write the ratio of hours in a day to days in a week.','["24:7","7:24","1:7","24:1"]',0,'Think about time.','24 hours in a day, 7 days in a week.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0102','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Analyze: If a recipe ratio is 1:2:3 for ingredients A, B, C, what fraction of the whole recipe is ingredient B?','["2/6 (or 1/3)","1/2","2/3","1/6"]',0,'Find the sum of all parts.','Total parts = 1+2+3 = 6. B is 2 parts.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0103','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Analyze: Why does fraction notation (like 4/6) for a part-to-part ratio sometimes confuse students?','["Because fractions are almost exclusively taught as part-to-WHOLE relationships; using them for part-to-part breaks that mental model.","Because fractions are hard to read.","It doesn''t confuse anyone.","Because they should be decimals."]',0,'Part/Whole vs Part/Part.','4/6 as a ratio doesn''t mean ''4 out of 6 total'', it means ''4 of this for every 6 of that''.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0104','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Synthesize: If Hannah mixes 2 cups of syrup to 3 cups of water, what fraction of the ENTIRE drink is syrup?','["2/5","2/3","3/5","1/5"]',0,'Find the total parts.','Total parts = 5. Syrup = 2.','2026-11-01 17:49:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0105','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Evaluate the mistake: ''Writing the ratio of 5 cm to 2 km as 5:2.''','["False, they completely ignored the units. It should be converted to 5 : 200,000 (since 2 km = 200,000 cm).","True, 5 and 2 are the numbers.","False, it should be 2:5.","False, it should be 5:20."]',0,'Check the metric conversion.','Units MUST match before numbers are compared.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0106','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Critique: ''Julia says that the ratio 3:4:2 cannot be written as a fraction.''','["True, standard fraction notation (a/b) only accommodates two quantities.","False, it can be written as 3/4/2.","False, it is 9.","True, because they are odd."]',0,'How many parts in a fraction?','Fractions only have a top and bottom.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0107','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Synthesize: Write the ratio of hours in a day to days in a week.','["24:7","7:24","1:7","24:1"]',0,'Think about time.','24 hours in a day, 7 days in a week.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0108','Maths','Ratio, Proportion and Percentages','Subtopic 3: Writing Ratios in Different Forms','Primary',10,'Analyze: If a recipe ratio is 1:2:3 for ingredients A, B, C, what fraction of the whole recipe is ingredient B?','["2/6 (or 1/3)","1/2","2/3","1/6"]',0,'Find the sum of all parts.','Total parts = 1+2+3 = 6. B is 2 parts.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0109','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'What are ''equivalent ratios''?','["Two ratios that represent the same comparison, even though their numbers are different (like 2:2 and 4:4).","Ratios that equal zero.","Ratios that have the same first number.","Ratios that are very long."]',0,'Same proportion.','They mean the same thing, just scaled up or down.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0110','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'If you have 1:2, how can you make an equivalent ratio?','["Multiply both numbers by the same non-zero number (e.g., x2 makes 2:4).","Add 1 to both numbers.","Subtract 1 from both numbers.","Multiply only the first number."]',0,'Do the same to both sides.','Scale it up evenly.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0111','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Find a ratio equivalent to 3:5 by multiplying by 2.','["6:10","5:7","3:10","6:5"]',0,'Double both.','3x2 = 6. 5x2 = 10.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0112','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Find a ratio equivalent to 3:5 by multiplying by 3.','["9:15","6:15","9:5","15:9"]',0,'Triple both.','3x3 = 9. 5x3 = 15.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0113','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'What does ''simplifying a ratio'' mean?','["Expressing it using the smallest whole numbers possible by dividing both terms by a common factor.","Making the numbers as big as possible.","Removing the colon.","Adding them."]',0,'Smallest numbers.','Breaking it down to lowest terms.','2026-11-01 17:49:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0114','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Simplify the ratio 12:18 by dividing both by 2.','["6:9","6:9","12:9","6:18"]',0,'Division.','Divide both sides.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0115','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'What are ''equivalent ratios''?','["Two ratios that represent the same comparison, even though their numbers are different (like 2:2 and 4:4).","Ratios that equal zero.","Ratios that have the same first number.","Ratios that are very long."]',0,'Same proportion.','They mean the same thing, just scaled up or down.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0116','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'If you have 1:2, how can you make an equivalent ratio?','["Multiply both numbers by the same non-zero number (e.g., x2 makes 2:4).","Add 1 to both numbers.","Subtract 1 from both numbers.","Multiply only the first number."]',0,'Do the same to both sides.','Scale it up evenly.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0117','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Find a ratio equivalent to 3:5 by multiplying by 2.','["6:10","5:7","3:10","6:5"]',0,'Double both.','3x2 = 6. 5x2 = 10.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0118','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Find a ratio equivalent to 3:5 by multiplying by 3.','["9:15","6:15","9:5","15:9"]',0,'Triple both.','3x3 = 9. 5x3 = 15.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0119','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'What does ''simplifying a ratio'' mean?','["Expressing it using the smallest whole numbers possible by dividing both terms by a common factor.","Making the numbers as big as possible.","Removing the colon.","Adding them."]',0,'Smallest numbers.','Breaking it down to lowest terms.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0120','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',1,'Simplify the ratio 12:18 by dividing both by 2.','["6:9","6:9","12:9","6:18"]',0,'Division.','Divide both sides.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0121','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Simplify 20:30 to its simplest form.','["2:3","4:6","10:15","2:5"]',0,'Drop the zeros.','Divide both by 10 (the GCF).','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0122','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'What is the Greatest Common Factor (GCF) you would use to completely simplify 24:36 in one step?','["12","6","4","2"]',0,'Biggest shared factor.','12 goes into 24 twice, and 36 three times.','2026-11-01 17:49:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0123','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Simplify a three-term ratio: 12:18:24.','["2:3:4","6:9:12","4:6:8","1:2:3"]',0,'Find a factor for ALL three.','Divide all three by 6.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0124','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Find the missing value: 3:4 = 12:x','["16","12","8","20"]',0,'Find the multiplier.','3 x 4 = 12, so 4 x 4 = 16.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0125','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'A drink recipe is 2 parts concentrate to 5 parts water (2:5). To make a bigger batch using 6 parts concentrate, how much water is needed?','["15 parts","10 parts","12 parts","20 parts"]',0,'Scale up the recipe.','2 x 3 = 6. So 5 x 3 = 15.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0126','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Critique the mistake: ''Simplifying 12:18 to 6:9 and stopping.''','["It is not in simplest form; 6 and 9 still share a common factor of 3, so it simplifies further to 2:3.","It is fully simplified.","It should be 4:6.","You can''t simplify ratios."]',0,'Are 6 and 9 divisible by anything?','Keep going until no factors remain.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0127','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Simplify 20:30 to its simplest form.','["2:3","4:6","10:15","2:5"]',0,'Drop the zeros.','Divide both by 10 (the GCF).','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0128','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'What is the Greatest Common Factor (GCF) you would use to completely simplify 24:36 in one step?','["12","6","4","2"]',0,'Biggest shared factor.','12 goes into 24 twice, and 36 three times.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0129','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Simplify a three-term ratio: 12:18:24.','["2:3:4","6:9:12","4:6:8","1:2:3"]',0,'Find a factor for ALL three.','Divide all three by 6.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0130','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Find the missing value: 3:4 = 12:x','["16","12","8","20"]',0,'Find the multiplier.','3 x 4 = 12, so 4 x 4 = 16.','2026-11-01 17:49:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0131','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'A drink recipe is 2 parts concentrate to 5 parts water (2:5). To make a bigger batch using 6 parts concentrate, how much water is needed?','["15 parts","10 parts","12 parts","20 parts"]',0,'Scale up the recipe.','2 x 3 = 6. So 5 x 3 = 15.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0132','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',5,'Critique the mistake: ''Simplifying 12:18 to 6:9 and stopping.''','["It is not in simplest form; 6 and 9 still share a common factor of 3, so it simplifies further to 2:3.","It is fully simplified.","It should be 4:6.","You can''t simplify ratios."]',0,'Are 6 and 9 divisible by anything?','Keep going until no factors remain.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0133','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Analyze the mistake: ''Alice tried to find an equivalent ratio for 3:5 by adding 2 to both sides, getting 5:7.''','["False logic; adding the same amount distorts the proportional relationship. You MUST multiply or divide.","True, adding works.","False, they should have subtracted.","True for odd numbers."]',0,'Adding breaks the scale.','Ratios are multiplicative, not additive.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0134','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Evaluate: Why does finding the GCF allow you to simplify a ratio in exactly one step?','["Because the GCF is the largest possible block that fits into both numbers, removing all common factors at once.","It doesn''t.","Because it makes the numbers zero.","Because it is magic."]',0,'One-shot simplification.','It removes all the ''fluff'' immediately.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0135','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Synthesize a missing value across three terms: 2:5:7 = 6:x:y. What are x and y?','["x=15, y=21","x=10, y=14","x=12, y=18","x=20, y=28"]',0,'Find the multiplier for the first term.','The multiplier is 3 (2x3=6). 5x3=15. 7x3=21.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0136','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Critique: ''Diana simplified the ratio of 1 meter to 50 cm as 1:50.''','["False, units must match first (100 cm to 50 cm), so the true simplified ratio is 2:1.","True.","False, it is 50:1.","False, it is 1:500."]',0,'Convert first!','Never ignore units in a ratio.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0137','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Analyze: If you double a recipe that calls for a 3:4 ratio, does the ratio itself double to 6:8?','["The AMOUNTS double to 6 and 8, but the underlying RATIO remains 3:4 (since 6:8 simplifies back to 3:4). The proportion is constant.","Yes, the ratio changes.","No, it becomes 1.5:2.","Yes, it becomes 9:16."]',0,'The taste doesn''t change.','Equivalent ratios represent the exact same relationship.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0138','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Synthesize: Simplify the ratio 144 : 120.','["6 : 5","12 : 10","14 : 12","72 : 60"]',0,'Find a big common factor.','Divide by 24 (or divide by 12, then 2).','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0139','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Analyze the mistake: ''George tried to find an equivalent ratio for 3:5 by adding 2 to both sides, getting 5:7.''','["False logic; adding the same amount distorts the proportional relationship. You MUST multiply or divide.","True, adding works.","False, they should have subtracted.","True for odd numbers."]',0,'Adding breaks the scale.','Ratios are multiplicative, not additive.','2026-11-01 17:49:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0140','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Evaluate: Why does finding the GCF allow you to simplify a ratio in exactly one step?','["Because the GCF is the largest possible block that fits into both numbers, removing all common factors at once.","It doesn''t.","Because it makes the numbers zero.","Because it is magic."]',0,'One-shot simplification.','It removes all the ''fluff'' immediately.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0141','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Synthesize a missing value across three terms: 2:5:7 = 6:x:y. What are x and y?','["x=15, y=21","x=10, y=14","x=12, y=18","x=20, y=28"]',0,'Find the multiplier for the first term.','The multiplier is 3 (2x3=6). 5x3=15. 7x3=21.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0142','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Critique: ''Julia simplified the ratio of 1 meter to 50 cm as 1:50.''','["False, units must match first (100 cm to 50 cm), so the true simplified ratio is 2:1.","True.","False, it is 50:1.","False, it is 1:500."]',0,'Convert first!','Never ignore units in a ratio.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0143','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Analyze: If you double a recipe that calls for a 3:4 ratio, does the ratio itself double to 6:8?','["The AMOUNTS double to 6 and 8, but the underlying RATIO remains 3:4 (since 6:8 simplifies back to 3:4). The proportion is constant.","Yes, the ratio changes.","No, it becomes 1.5:2.","Yes, it becomes 9:16."]',0,'The taste doesn''t change.','Equivalent ratios represent the exact same relationship.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0144','Maths','Ratio, Proportion and Percentages','Subtopic 4: Equivalent Ratios and Simplifying Ratios','Primary',10,'Synthesize: Simplify the ratio 144 : 120.','["6 : 5","12 : 10","14 : 12","72 : 60"]',0,'Find a big common factor.','Divide by 24 (or divide by 12, then 2).','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0145','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'What is a ''proportion''?','["A mathematical statement that two ratios are exactly equal (like 2:3 = 4:6).","A type of fraction.","A really big number.","A shape."]',0,'Equals sign between ratios.','It links two equivalent ratios.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0146','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'What is the difference between a ratio and a proportion?','["A ratio compares quantities (2:3); a proportion states two ratios are equal (2:3 = 4:6).","They are the same.","A proportion is for fractions.","A ratio is for addition."]',0,'Relationship vs Equation.','Phrase vs Sentence.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0147','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'If a recipe uses 2 cups flour to 1 cup water (2:1). A double batch uses 4 cups flour to 2 cups water (4:2). Is this a proportion?','["Yes, 2:1 = 4:2.","No.","Only for baking.","Cannot tell."]',0,'Scaled up equally.','They are equivalent ratios.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0148','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'How can you check if 4:6 and 6:9 form a proportion using simplification?','["Simplify both. 4:6 = 2:3. 6:9 = 2:3. Since they match, they form a proportion.","Add them.","Subtract them.","It''s impossible."]',0,'Simplify.','Bring them both to lowest terms.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0149','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'Check if 2:5 and 6:15 form a proportion using multiplication.','["Yes, multiplying both terms of 2:5 by 3 gives 6:15.","No.","Only if you divide.","Only if you add."]',0,'Is there a multiplier?','Find a common multiplier.','2026-11-01 17:49:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0150','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'Find the missing number x: 3:4 = 9:x','["12","16","8","24"]',0,'Find the multiplier.','3 x 3 = 9. 4 x 3 = 12.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0151','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'What is a ''proportion''?','["A mathematical statement that two ratios are exactly equal (like 2:3 = 4:6).","A type of fraction.","A really big number.","A shape."]',0,'Equals sign between ratios.','It links two equivalent ratios.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0152','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'What is the difference between a ratio and a proportion?','["A ratio compares quantities (2:3); a proportion states two ratios are equal (2:3 = 4:6).","They are the same.","A proportion is for fractions.","A ratio is for addition."]',0,'Relationship vs Equation.','Phrase vs Sentence.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0153','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'If a recipe uses 2 cups flour to 1 cup water (2:1). A double batch uses 4 cups flour to 2 cups water (4:2). Is this a proportion?','["Yes, 2:1 = 4:2.","No.","Only for baking.","Cannot tell."]',0,'Scaled up equally.','They are equivalent ratios.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0154','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'How can you check if 4:6 and 6:9 form a proportion using simplification?','["Simplify both. 4:6 = 2:3. 6:9 = 2:3. Since they match, they form a proportion.","Add them.","Subtract them.","It''s impossible."]',0,'Simplify.','Bring them both to lowest terms.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0155','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'Check if 2:5 and 6:15 form a proportion using multiplication.','["Yes, multiplying both terms of 2:5 by 3 gives 6:15.","No.","Only if you divide.","Only if you add."]',0,'Is there a multiplier?','Find a common multiplier.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0156','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',1,'Find the missing number x: 3:4 = 9:x','["12","16","8","24"]',0,'Find the multiplier.','3 x 3 = 9. 4 x 3 = 12.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0157','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Find the missing number x: 2:7 = x:21','["6","14","9","4"]',0,'Look at the second terms.','7 x 3 = 21. 2 x 3 = 6.','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0158','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Three identical cookies cost 6 coins. How much for six cookies?','["12 coins","18 coins","9 coins","24 coins"]',0,'Double it.','Number of items doubles (3->6), so cost doubles (6->12).','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0159','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'A painter mixes 2 cups blue to 3 cups white. If they use 6 cups blue, how much white is needed for the same proportion?','["9 cups","6 cups","12 cups","15 cups"]',0,'Find the multiplier.','Blue is x3 (2->6). White must be x3 (3x3=9).','2026-11-01 17:49:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0160','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Four boxes hold 20 marbles. How many marbles will 8 identical boxes hold?','["40","30","60","80"]',0,'Double it.','Boxes double (4->8), items double (20->40).','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0161','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'A quick rule for simple proportions: If a:b = c:d, and ''a'' is multiplied by a number to get ''c''...','["You must apply that exact same multiplier to ''b'' to get ''d''.","You add the number to ''b''.","You subtract it.","You ignore it."]',0,'Same multiplier.','Keep the scale the same.','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0162','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Critique the mistake: ''If 2:3 becomes 4:x, x must be 5 because 2+2=4 and 3+2=5.''','["False, proportions are multiplicative, not additive. You multiplied 2 by 2, so you must multiply 3 by 2 to get x=6.","True.","False, x is 7.","True for small numbers."]',0,'Multiply!','Never add across a proportion.','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0163','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Find the missing number x: 2:7 = x:21','["6","14","9","4"]',0,'Look at the second terms.','7 x 3 = 21. 2 x 3 = 6.','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0164','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Three identical shells cost 6 coins. How much for six shells?','["12 coins","18 coins","9 coins","24 coins"]',0,'Double it.','Number of items doubles (3->6), so cost doubles (6->12).','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0165','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'A painter mixes 2 cups blue to 3 cups white. If they use 6 cups blue, how much white is needed for the same proportion?','["9 cups","6 cups","12 cups","15 cups"]',0,'Find the multiplier.','Blue is x3 (2->6). White must be x3 (3x3=9).','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0166','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Four boxes hold 20 blocks. How many blocks will 8 identical boxes hold?','["40","30","60","80"]',0,'Double it.','Boxes double (4->8), items double (20->40).','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0167','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'A quick rule for simple proportions: If a:b = c:d, and ''a'' is multiplied by a number to get ''c''...','["You must apply that exact same multiplier to ''b'' to get ''d''.","You add the number to ''b''.","You subtract it.","You ignore it."]',0,'Same multiplier.','Keep the scale the same.','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0168','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',5,'Critique the mistake: ''If 2:3 becomes 4:x, x must be 5 because 2+2=4 and 3+2=5.''','["False, proportions are multiplicative, not additive. You multiplied 2 by 2, so you must multiply 3 by 2 to get x=6.","True.","False, x is 7.","True for small numbers."]',0,'Multiply!','Never add across a proportion.','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0169','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Analyze the limitation: ''Alice says if 1 person paints a fence in 4 hours, 2 people paint it in 8 hours (1:4 = 2:8).''','["False, this is an inversely proportional relationship (more people = LESS time). 2 people would take 2 hours. Simple direct proportions don''t apply.","True, that''s how proportions work.","False, they would take 12 hours.","True, math proves it."]',0,'Think about real life logic.','Does doubling the workers double the time?','2026-11-01 17:49:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0170','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Evaluate the order requirement: Why must a proportion compare corresponding terms in the exact same order?','["Because swapping the order changes the mathematical relationship (e.g. boys:girls is not equal to girls:boys).","It doesn''t matter.","Because it looks nicer.","To confuse students."]',0,'A:B is not B:A.','Order defines the ratio.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0171','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Synthesize a missing value involving decimals: 1.5 : 3 = x : 12.','["6","4.5","9","24"]',0,'Find the multiplier.','Multiplier is 4 (3x4=12). 1.5 x 4 = 6.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0172','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Critique: ''Any two ratios can be made into a proportion if you add the right numbers.''','["False, proportions STRICTLY deal with multiplicative relationships (scaling), not additive ones.","True.","False, they must be subtracted.","True if they are even."]',0,'Multiplication only.','Proportions are scaled copies.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0173','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Analyze: If Ethan mixes paint in a 3:5 ratio, and uses 15 liters of the first color, how much of the second?','["25","15","75","35"]',0,'Scale it up.','Multiplier is 5.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0174','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Synthesize a check for a proportion using cross-multiplication: Does 5:7 = 15:21?','["Yes, because 5 x 21 (105) equals 7 x 15 (105).","No.","Yes, because they are odd.","No, 21 is too big."]',0,'Cross multiply.','The cross products of a true proportion are always equal.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0175','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Analyze the limitation: ''George says if 1 person paints a fence in 4 hours, 2 people paint it in 8 hours (1:4 = 2:8).''','["False, this is an inversely proportional relationship (more people = LESS time). 2 people would take 2 hours. Simple direct proportions don''t apply.","True, that''s how proportions work.","False, they would take 12 hours.","True, math proves it."]',0,'Think about real life logic.','Does doubling the workers double the time?','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0176','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Evaluate the order requirement: Why must a proportion compare corresponding terms in the exact same order?','["Because swapping the order changes the mathematical relationship (e.g. boys:girls is not equal to girls:boys).","It doesn''t matter.","Because it looks nicer.","To confuse students."]',0,'A:B is not B:A.','Order defines the ratio.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0177','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Synthesize a missing value involving decimals: 1.5 : 3 = x : 12.','["6","4.5","9","24"]',0,'Find the multiplier.','Multiplier is 4 (3x4=12). 1.5 x 4 = 6.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0178','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Critique: ''Any two ratios can be made into a proportion if you add the right numbers.''','["False, proportions STRICTLY deal with multiplicative relationships (scaling), not additive ones.","True.","False, they must be subtracted.","True if they are even."]',0,'Multiplication only.','Proportions are scaled copies.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0179','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Analyze: If Kevin mixes paint in a 3:5 ratio, and uses 3 liters of the first color, how much of the second?','["5","3","15","15"]',0,'Scale it up.','Multiplier is 1.','2026-11-01 17:49:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0180','Maths','Ratio, Proportion and Percentages','Subtopic 5: Simple Proportions','Primary',10,'Synthesize a check for a proportion using cross-multiplication: Does 5:7 = 15:21?','["Yes, because 5 x 21 (105) equals 7 x 15 (105).","No.","Yes, because they are odd.","No, 21 is too big."]',0,'Cross multiply.','The cross products of a true proportion are always equal.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0181','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'What is the ''unitary method''?','["A way of solving problems by first finding the value of ONE unit, and then using that to calculate any other number of units.","A method that only uses the number 1.","A way to unite numbers.","A type of fraction."]',0,'Go down to one, then up to many.','Find the cost of one first.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0182','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 5 identical cookies cost 20 coins, how do you find the cost of ONE?','["Divide the total cost by the number of items (20 ÷ 5).","Add them.","Multiply them.","Subtract them."]',0,'Divide.','Total cost divided by quantity gives unit cost.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0183','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 5 books cost 20 coins, what is the cost of ONE?','["4 coins","15 coins","25 coins","100 coins"]',0,'Math.','20 / 5 = 4.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0184','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'Once you know the cost of ONE item (e.g. 4 coins), how do you find the cost of 7 items?','["Multiply the cost of one by the number of items needed (4 x 7).","Add 7.","Divide by 7.","Guess."]',0,'Multiply up.','Unit cost times quantity.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0185','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 1 item costs 4 coins, what is the cost of 7 items?','["28 coins","11 coins","3 coins","24 coins"]',0,'Math.','4 x 7 = 28.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0186','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'What are the two main steps of the unitary method?','["Step 1: Divide to find one. Step 2: Multiply to find the required amount.","Add then Subtract.","Multiply then Add.","Just guess."]',0,'Divide then multiply.','Divide down to one, multiply up to many.','2026-11-01 17:49:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0187','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'What is the ''unitary method''?','["A way of solving problems by first finding the value of ONE unit, and then using that to calculate any other number of units.","A method that only uses the number 1.","A way to unite numbers.","A type of fraction."]',0,'Go down to one, then up to many.','Find the cost of one first.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0188','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 5 identical shells cost 20 coins, how do you find the cost of ONE?','["Divide the total cost by the number of items (20 ÷ 5).","Add them.","Multiply them.","Subtract them."]',0,'Divide.','Total cost divided by quantity gives unit cost.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0189','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 5 leaves cost 20 coins, what is the cost of ONE?','["4 coins","15 coins","25 coins","100 coins"]',0,'Math.','20 / 5 = 4.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0190','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'Once you know the cost of ONE item (e.g. 4 coins), how do you find the cost of 7 items?','["Multiply the cost of one by the number of items needed (4 x 7).","Add 7.","Divide by 7.","Guess."]',0,'Multiply up.','Unit cost times quantity.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0191','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'If 1 item costs 4 coins, what is the cost of 7 items?','["28 coins","11 coins","3 coins","24 coins"]',0,'Math.','4 x 7 = 28.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0192','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',1,'What are the two main steps of the unitary method?','["Step 1: Divide to find one. Step 2: Multiply to find the required amount.","Add then Subtract.","Multiply then Add.","Just guess."]',0,'Divide then multiply.','Divide down to one, multiply up to many.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0193','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Six identical apples cost 24 coins. How much will 9 cost?','["36 coins","40 coins","45 coins","30 coins"]',0,'Divide then multiply.','24/6=4 (cost of 1). 4x9=36.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0194','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'A cyclist travels 30 km in 2 hours at a constant speed. How far in 5 hours?','["75 km","60 km","90 km","100 km"]',0,'Find the speed for 1 hour first.','30/2=15 km/hr. 15x5=75.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0195','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Four identical bottles contain 8 liters total. How much in 7 bottles?','["14 liters","12 liters","16 liters","20 liters"]',0,'Find 1 bottle first.','8/4=2L per bottle. 2x7=14L.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0196','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Critique the mistake: ''If 5 pens cost 25, then 1 pen costs 25 x 5 = 125.''','["False, to find the unit cost you must DIVIDE the total cost by the quantity (25 ÷ 5 = 5).","True.","False, you subtract.","True, pens are expensive."]',0,'Division, not multiplication.','You divide to find the cost of one.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0197','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Analyze: Does the unitary method only work for money?','["No, it works for any proportional quantities like distance/time, weight/volume, or item/capacity.","Yes, only money.","Yes, and time.","No, it only works for fractions."]',0,'Rates and ratios.','It works for any constant rate.','2026-11-01 17:49:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0198','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'If 3 workers can build a wall in some amount of time... wait, can we use unitary method for workers and time?','["No, workers and time are INVERSELY proportional (more workers = less time). Unitary method works best for direct proportions.","Yes, it always works.","Yes, but you have to add.","Only if they are fast."]',0,'Think about real life.','The notes say ''check the conditions'' – standard unitary assumes constant direct rates.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0199','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Six identical toys cost 24 coins. How much will 9 cost?','["36 coins","40 coins","45 coins","30 coins"]',0,'Divide then multiply.','24/6=4 (cost of 1). 4x9=36.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0200','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'A cyclist travels 30 km in 2 hours at a constant speed. How far in 5 hours?','["75 km","60 km","90 km","100 km"]',0,'Find the speed for 1 hour first.','30/2=15 km/hr. 15x5=75.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0201','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Four identical bottles contain 8 liters total. How much in 7 bottles?','["14 liters","12 liters","16 liters","20 liters"]',0,'Find 1 bottle first.','8/4=2L per bottle. 2x7=14L.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0202','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Critique the mistake: ''If 5 pens cost 25, then 1 pen costs 25 x 5 = 125.''','["False, to find the unit cost you must DIVIDE the total cost by the quantity (25 ÷ 5 = 5).","True.","False, you subtract.","True, pens are expensive."]',0,'Division, not multiplication.','You divide to find the cost of one.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0203','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'Analyze: Does the unitary method only work for money?','["No, it works for any proportional quantities like distance/time, weight/volume, or item/capacity.","Yes, only money.","Yes, and time.","No, it only works for fractions."]',0,'Rates and ratios.','It works for any constant rate.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0204','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',5,'If 4 workers can build a wall in some amount of time... wait, can we use unitary method for workers and time?','["No, workers and time are INVERSELY proportional (more workers = less time). Unitary method works best for direct proportions.","Yes, it always works.","Yes, but you have to add.","Only if they are fast."]',0,'Think about real life.','The notes say ''check the conditions'' – standard unitary assumes constant direct rates.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0205','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Analyze the assumption: When using the unitary method to say ''3 apples cost 15, so 5 cost 25'', what real-world condition MUST be met?','["The price per apple must remain constant (no bulk discounts, fixed pricing).","Apples must be red.","The store must be open.","It doesn''t matter."]',0,'Bulk discounts break the math.','The math assumes a constant rate.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0206','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Synthesize: A taxi charges a fixed $5 starting fee, plus $2 per mile. Can you use the simple unitary method to find the cost of 10 miles if you know the cost of 2 miles is $9?','["No, the fixed fee breaks the direct proportion. (10 miles is NOT 5 x $9).","Yes, just multiply by 5.","Yes, subtract 5.","No, taxis are too fast."]',0,'Fixed fees ruin it.','Linear equations with a y-intercept are not simple direct proportions.','2026-11-01 17:49:57',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0207','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Evaluate the two steps mathematically: Finding the cost of y items if x items cost c.','["Step 1: c / x (unit cost). Step 2: (c / x) * y.","x / c * y","c * x * y","y / x"]',0,'Formula.','Divide total cost by quantity, then multiply by new quantity.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0208','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Synthesize: Diana can run 400m in 1 minute. Assuming constant speed, how many seconds does it take to run 100m?','["15 seconds","25 seconds","10 seconds","20 seconds"]',0,'Convert to seconds, then divide.','1 min = 60s. 60/4 = 15s.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0209','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Critique: ''Ethan found the unit cost but forgot the second step.'' What did they actually find?','["They found the ''rate'' or value of a single item, but failed to answer the question about the multiple items requested.","They finished the problem.","They found the total.","They made an error in step 1."]',0,'Half finished.','Step 1 is only halfway there.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0210','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Analyze: How does the unitary method relate to finding equivalent fractions?','["Finding the ''unit'' is like simplifying the fraction to a denominator of 1 (e.g., 20/5 = 4/1), then scaling it up to the new denominator (4/1 * 7/7 = 28/7).","They are unrelated.","They are opposites.","Fractions don''t use division."]',0,'Scale down, scale up.','It''s exactly the same mathematical process disguised as a word problem.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0211','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Analyze the assumption: When using the unitary method to say ''6 apples cost 15, so 10 cost 25'', what real-world condition MUST be met?','["The price per apple must remain constant (no bulk discounts, fixed pricing).","Apples must be red.","The store must be open.","It doesn''t matter."]',0,'Bulk discounts break the math.','The math assumes a constant rate.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0212','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Synthesize: A taxi charges a fixed $5 starting fee, plus $2 per mile. Can you use the simple unitary method to find the cost of 10 miles if you know the cost of 2 miles is $9?','["No, the fixed fee breaks the direct proportion. (10 miles is NOT 5 x $9).","Yes, just multiply by 5.","Yes, subtract 5.","No, taxis are too fast."]',0,'Fixed fees ruin it.','Linear equations with a y-intercept are not simple direct proportions.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0213','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Evaluate the two steps mathematically: Finding the cost of y items if x items cost c.','["Step 1: c / x (unit cost). Step 2: (c / x) * y.","x / c * y","c * x * y","y / x"]',0,'Formula.','Divide total cost by quantity, then multiply by new quantity.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0214','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Synthesize: Julia can run 400m in 1 minute. Assuming constant speed, how many seconds does it take to run 100m?','["15 seconds","25 seconds","10 seconds","20 seconds"]',0,'Convert to seconds, then divide.','1 min = 60s. 60/4 = 15s.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0215','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Critique: ''Kevin found the unit cost but forgot the second step.'' What did they actually find?','["They found the ''rate'' or value of a single item, but failed to answer the question about the multiple items requested.","They finished the problem.","They found the total.","They made an error in step 1."]',0,'Half finished.','Step 1 is only halfway there.','2026-11-01 17:49:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0216','Maths','Ratio, Proportion and Percentages','Subtopic 6: Unitary Method — Introductory','Primary',10,'Analyze: How does the unitary method relate to finding equivalent fractions?','["Finding the ''unit'' is like simplifying the fraction to a denominator of 1 (e.g., 20/5 = 4/1), then scaling it up to the new denominator (4/1 * 7/7 = 28/7).","They are unrelated.","They are opposites.","Fractions don''t use division."]',0,'Scale down, scale up.','It''s exactly the same mathematical process disguised as a word problem.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0217','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'What does the word ''percent'' literally mean?','["Per hundred (parts out of 100).","Per ten.","Per thousand.","Per one."]',0,'Century.','Cent = 100.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0218','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'What is the mathematical symbol for percentage?','["%","$","&","@"]',0,'Two circles and a slash.','The percent sign.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0219','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'If you have 10%, what does that mean as a fraction?','["10 out of 100 (10/100).","10 out of 10.","1 out of 100.","100 out of 10."]',0,'Over 100.','Percent is always out of 100.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0220','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'What does 100% mean?','["The entire whole amount (100 out of 100).","Half of it.","Nothing.","Double the amount."]',0,'Everything.','100/100 is 1.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0221','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'If a grid has 100 equal squares and 25 are coloured green, what percentage is green?','["25%","75%","50%","100%"]',0,'Direct mapping.','25 out of 100 is 25%.','2026-11-01 17:49:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0222','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',1,'What is 50% as a common fraction?','["One-half (1/2)","One-quarter (1/4)","Three-quarters (3/4)","One whole"]',0,'Halfway to 100.','50 out of 100 is half.','2026-11-01 17:49:59',NULL,NULL);
