INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0230','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'What is 75% as a common fraction?','["Three-quarters (3/4)","One-half (1/2)","One-quarter (1/4)","Four-thirds (4/3)"]',0,'Three quarters of a dollar.','75/100 simplifies to 3/4.','2026-11-01 17:50:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0231','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'Write 35% as an unsimplified fraction.','["35/100","35/10","3.5/100","100/35"]',0,'Over 100.','Percent means per hundred.','2026-11-01 17:50:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0232','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'If a fraction is 45/100, what is it as a percentage?','["45%","0.45%","450%","4.5%"]',0,'Look at the top.','The numerator is the percentage when the denominator is 100.','2026-11-01 17:50:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0233','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'Convert 1/2 to a percentage.','["50% (because 1/2 = 50/100)","20%","12%","2%"]',0,'Half.','Equivalent fraction over 100.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0234','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'Convert 1/4 to a percentage.','["25% (because 1/4 = 25/100)","40%","14%","4%"]',0,'Quarter.','Equivalent fraction over 100.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0235','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'What is 25% as a common fraction?','["One-quarter (1/4)","One-half (1/2)","Three-quarters (3/4)","One-fifth (1/5)"]',0,'Think of coins/quarters.','25/100 simplifies to 1/4.','2026-11-01 17:50:01',NULL,NULL);
