INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0238','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'If a fraction is 45/100, what is it as a percentage?','["45%","0.45%","450%","4.5%"]',0,'Look at the top.','The numerator is the percentage when the denominator is 100.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0239','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'Convert 1/2 to a percentage.','["50% (because 1/2 = 50/100)","20%","12%","2%"]',0,'Half.','Equivalent fraction over 100.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0240','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',5,'Convert 1/4 to a percentage.','["25% (because 1/4 = 25/100)","40%","14%","4%"]',0,'Quarter.','Equivalent fraction over 100.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0241','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Analyze: Why can a percentage be greater than 100% (e.g. 150%)?','["Because it represents an amount larger than the original reference whole (e.g., one and a half times the amount).","It cannot be; 100% is the maximum in all math.","Because 150 is a big number.","Because of inflation."]',0,'More than a whole.','150/100 is 1.5 wholes.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0242','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Critique: ''Bob says that 100% always means exactly 100 objects.''','["False, 100% means the ENTIRE reference amount. If there are 40 objects, 100% is 40 objects.","True.","False, it means 1 object.","True, percent means 100."]',0,'100% of a pizza is 1 pizza.','100% scales to whatever the ''whole'' is.','2026-11-01 17:50:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0243','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Evaluate: How does knowing that 10% is 1/10 help you calculate 10% of 60 mentally?','["You just divide the total quantity by 10 (60 / 10 = 6).","It doesn''t help.","You multiply by 10.","You subtract 10."]',0,'Divide by 10.','Fractions as division.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0244','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Synthesize: If 60 out of 100 people choose an option, what percentage DID NOT choose it?','["40% (since 100% - 60% = 40%).","60%","100%","0%"]',0,'Subtract from 100.','The whole is 100%.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0245','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Analyze the conversion: Why is 7/10 equal to 70%, not 7%?','["Because 7/10 must be converted to an equivalent fraction over 100 (70/100) to find the percentage.","Because you add a zero to everything.","It is actually 7%.","Because 7 is lucky."]',0,'Scale up to 100.','The denominator MUST be 100.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0246','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Evaluate the real-world application: If a shop advertises ''25% off'', what fraction of the original price is the discount?','["1/4 of the price is taken off.","1/2","3/4","1/25"]',0,'Simplify the percent.','25% = 25/100 = 1/4.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0247','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Analyze: Why can a percentage be greater than 100% (e.g. 150%)?','["Because it represents an amount larger than the original reference whole (e.g., one and a half times the amount).","It cannot be; 100% is the maximum in all math.","Because 150 is a big number.","Because of inflation."]',0,'More than a whole.','150/100 is 1.5 wholes.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0248','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Critique: ''Hannah says that 100% always means exactly 100 objects.''','["False, 100% means the ENTIRE reference amount. If there are 40 objects, 100% is 40 objects.","True.","False, it means 1 object.","True, percent means 100."]',0,'100% of a pizza is 1 pizza.','100% scales to whatever the ''whole'' is.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0249','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Evaluate: How does knowing that 10% is 1/10 help you calculate 10% of 60 mentally?','["You just divide the total quantity by 10 (60 / 10 = 6).","It doesn''t help.","You multiply by 10.","You subtract 10."]',0,'Divide by 10.','Fractions as division.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0250','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Synthesize: If 60 out of 100 people choose an option, what percentage DID NOT choose it?','["40% (since 100% - 60% = 40%).","60%","100%","0%"]',0,'Subtract from 100.','The whole is 100%.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0251','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Analyze the conversion: Why is 7/10 equal to 70%, not 7%?','["Because 7/10 must be converted to an equivalent fraction over 100 (70/100) to find the percentage.","Because you add a zero to everything.","It is actually 7%.","Because 7 is lucky."]',0,'Scale up to 100.','The denominator MUST be 100.','2026-11-01 17:50:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0252','Maths','Ratio, Proportion and Percentages','Subtopic 7: Understanding Percentages','Primary',10,'Evaluate the real-world application: If a shop advertises ''25% off'', what fraction of the original price is the discount?','["1/4 of the price is taken off.","1/2","3/4","1/25"]',0,'Simplify the percent.','25% = 25/100 = 1/4.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0253','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'What do fractions, decimals, and percentages all have in common?','["They are just three different ways to describe the exact same quantity or part of a whole.","They all use a decimal point.","They all use a colon.","Nothing."]',0,'Translations.','They are different languages for the same idea.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0254','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'If you have 1/4 of a pizza, what is that as a decimal and a percentage?','["0.25 and 25%","0.4 and 40%","0.14 and 14%","0.5 and 50%"]',0,'Think of a quarter.','1/4 = 25/100.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0255','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'How do you convert a fraction into a decimal using division?','["Divide the top number (numerator) by the bottom number (denominator).","Add them.","Multiply them.","Subtract them."]',0,'Top divided by bottom.','The fraction bar means division.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0256','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'Convert 1/2 into a decimal.','["0.5 (1 ÷ 2)","1.2","0.2","0.12"]',0,'1 divided by 2.','Half.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0257','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'Convert 0.6 into a fraction based on its place value.','["6/10","6/100","1/6","6/1"]',0,'Tenths.','One decimal place is tenths.','2026-11-01 17:50:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0258','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',1,'Convert 0.25 into a fraction based on its place value.','["25/100","25/10","1/25","2.5/10"]',0,'Hundredths.','Two decimal places is hundredths.','2026-11-01 17:50:03',NULL,NULL);
