INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0265','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 40% into an unsimplified fraction.','["40/100","40/10","4/100","100/40"]',0,'Over 100.','Percent means out of 100.','2026-11-01 17:50:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0266','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Simplify the fraction 40/100.','["2/5","4/10","1/2","1/4"]',0,'Divide by 20.','Divide both by 20.','2026-11-01 17:50:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0267','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'How do you convert a decimal into a percentage (e.g., 0.4)?','["Multiply it by 100 and add the % symbol (0.4 x 100 = 40%).","Divide by 100.","Just add a % sign (0.4%).","Multiply by 10."]',0,'x 100.','Shift the decimal two places right.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0268','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 0.65 into a percentage.','["65%","6.5%","0.65%","650%"]',0,'Shift dot two places right.','0.65 x 100.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0269','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'How do you convert a percentage into a decimal (e.g., 35%)?','["Divide the number by 100 (35 ÷ 100 = 0.35).","Multiply by 100.","Remove the % sign (35).","Divide by 10."]',0,'/ 100.','Shift the decimal two places left.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0270','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 8% into a decimal.','["0.08","0.8","8.0","0.008"]',0,'Needs a placeholder zero.','8 ÷ 100.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0271','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 40% into an unsimplified fraction.','["40/100","40/10","4/100","100/40"]',0,'Over 100.','Percent means out of 100.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0272','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Simplify the fraction 40/100.','["2/5","4/10","1/2","1/4"]',0,'Divide by 20.','Divide both by 20.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0273','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'How do you convert a decimal into a percentage (e.g., 0.4)?','["Multiply it by 100 and add the % symbol (0.4 x 100 = 40%).","Divide by 100.","Just add a % sign (0.4%).","Multiply by 10."]',0,'x 100.','Shift the decimal two places right.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0274','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 0.65 into a percentage.','["65%","6.5%","0.65%","650%"]',0,'Shift dot two places right.','0.65 x 100.','2026-11-01 17:50:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0275','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'How do you convert a percentage into a decimal (e.g., 35%)?','["Divide the number by 100 (35 ÷ 100 = 0.35).","Multiply by 100.","Remove the % sign (35).","Divide by 10."]',0,'/ 100.','Shift the decimal two places left.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0276','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',5,'Convert 8% into a decimal.','["0.08","0.8","8.0","0.008"]',0,'Needs a placeholder zero.','8 ÷ 100.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0277','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Analyze: Why does 125% equal the decimal 1.25?','["Dividing 125 by 100 gives 1.25, showing that it represents one whole unit plus 25 hundredths.","Because 125 is a big number.","It doesn''t, it equals 0.125.","It equals 12.5."]',0,'Shift two places left.','Percentages over 100 become decimals greater than 1.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0278','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Synthesize the conversion from a fraction to a percentage: What is 4/5 as a percentage?','["80%","45%","40%","50%"]',0,'Make the denominator 100.','4/5 = 80/100 = 80%. (Or 4 ÷ 5 = 0.8 -> 80%).','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0279','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Critique the mistake: ''0.5 and 50% are different because 50 is much larger than 0.5.''','["False, 50% explicitly means 50 divided by 100, which mathematically equals 0.5. They represent the exact same quantity.","True, 50 is bigger.","False, 0.5 is bigger.","True for whole numbers."]',0,'Read the symbol.','The % symbol implies division by 100.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0280','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Evaluate the real-world application: If a learner scores 75 out of 100 marks, how is this expressed in all three formats?','["75/100 (or 3/4), 0.75, and 75%.","75, 0.75, 3/4","7.5, 75%, 75/10","3/4, 0.34, 34%"]',0,'The holy trinity.','Fraction, Decimal, Percent.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0281','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Analyze: Convert 0.08 into a percentage. Why is it 8% and not 80%?','["0.08 represents 8 hundredths (8/100). Multiplying by 100 yields 8. 0.8 would be 80%.","Because 8 is smaller.","It is 80%.","Because of the decimal."]',0,'Shift two places.','Place value matters.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0282','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Synthesize the conversion loop: Convert 1/8 to a decimal, then to a percentage.','["1 ÷ 8 = 0.125. 0.125 x 100 = 12.5%.","0.18, 18%","0.8, 80%","0.12, 12%"]',0,'1 divided by 8.','Requires long division.','2026-11-01 17:50:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0283','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Analyze: Why does 125% equal the decimal 1.25?','["Dividing 125 by 100 gives 1.25, showing that it represents one whole unit plus 25 hundredths.","Because 125 is a big number.","It doesn''t, it equals 0.125.","It equals 12.5."]',0,'Shift two places left.','Percentages over 100 become decimals greater than 1.','2026-11-01 17:50:06',NULL,NULL);
