INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0285','Maths','Ratio, Proportion and Percentages','Subtopic 8: Converting Fractions, Decimals and Percentages','Primary',10,'Critique the mistake: ''0.5 and 50% are different because 50 is much larger than 0.5.''','["False, 50% explicitly means 50 divided by 100, which mathematically equals 0.5. They represent the exact same quantity.","True, 50 is bigger.","False, 0.5 is bigger.","True for whole numbers."]',0,'Read the symbol.','The % symbol implies division by 100.','2026-11-01 17:50:07',NULL,NULL);
