INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0289','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'What does it mean to find ''a percentage of a quantity''?','["Calculating a specific part (based on the percentage) out of the whole quantity.","Adding 100 to the number.","Dividing the number by 100.","Guessing."]',0,'Part of the whole.','Finding a part of the whole.','2026-11-01 17:50:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0290','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'If a class has 40 learners and 50% participate, what does 50% mean here?','["Half of the learners.","All 40 learners.","50 learners.","100 learners."]',0,'Half.','50% is always one half.','2026-11-01 17:50:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0291','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'What is a quick way to find 10% of a number?','["Divide the number by 10.","Divide by 100.","Multiply by 10.","Take half."]',0,'Move decimal one place left.','10% is 1/10th.','2026-11-01 17:50:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0292','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'Find 10% of 90.','["9","90","900","10"]',0,'Drop the zero.','Divide by 10.','2026-11-01 17:50:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0293','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'What is a quick way to find 50% of a number?','["Find half (divide by 2).","Divide by 50.","Multiply by 2.","Divide by 5."]',0,'Split in two.','50% is half.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0294','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'Find 50% of 36.','["18","36","72","9"]',0,'Half of 36.','36 ÷ 2 = 18.','2026-11-01 17:50:08',NULL,NULL);
