INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0297','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'What is a quick way to find 10% of a number?','["Divide the number by 10.","Divide by 100.","Multiply by 10.","Take half."]',0,'Move decimal one place left.','10% is 1/10th.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0298','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'Find 10% of 100.','["10","100","1000","10"]',0,'Drop the zero.','Divide by 10.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0299','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'What is a quick way to find 50% of a number?','["Find half (divide by 2).","Divide by 50.","Multiply by 2.","Divide by 5."]',0,'Split in two.','50% is half.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0300','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',1,'Find 50% of 36.','["18","36","72","9"]',0,'Half of 36.','36 ÷ 2 = 18.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0301','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is a quick way to find 25% of a number?','["Divide the number by 4.","Divide by 25.","Multiply by 4.","Divide by 2."]',0,'Half it, then half it again.','25% is one-quarter.','2026-11-01 17:50:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0302','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'Find 25% of 80.','["20","40","10","25"]',0,'Quarter of 80.','80 ÷ 4 = 20.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0303','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is a quick way to find 75% of a number?','["Find one-quarter (divide by 4) and multiply by 3.","Divide by 75.","Subtract 25.","Multiply by 75."]',0,'Find 25%, times 3.','75% is three-quarters.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0304','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'Find 75% of 40.','["30","10","20","35"]',0,'Three-quarters.','40 ÷ 4 = 10. 10 x 3 = 30.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0305','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is the general mathematical formula to find p% of N?','["(p / 100) x N","p x N","p + N","100 / p x N"]',0,'Fraction x Whole.','Turn percent into fraction, multiply by quantity.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0306','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'Use the formula to find 20% of 50.','["10","50","5","20"]',0,'Divide by 5.','(20/100) x 50.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0307','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is a quick way to find 25% of a number?','["Divide the number by 4.","Divide by 25.","Multiply by 4.","Divide by 2."]',0,'Half it, then half it again.','25% is one-quarter.','2026-11-01 17:50:09',NULL,NULL);
