INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0309','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is a quick way to find 75% of a number?','["Find one-quarter (divide by 4) and multiply by 3.","Divide by 75.","Subtract 25.","Multiply by 75."]',0,'Find 25%, times 3.','75% is three-quarters.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0310','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'Find 75% of 40.','["30","10","20","35"]',0,'Three-quarters.','40 ÷ 4 = 10. 10 x 3 = 30.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0311','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'What is the general mathematical formula to find p% of N?','["(p / 100) x N","p x N","p + N","100 / p x N"]',0,'Fraction x Whole.','Turn percent into fraction, multiply by quantity.','2026-11-01 17:50:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0312','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',5,'Use the formula to find 20% of 60.','["12","60","6","20"]',0,'Divide by 5.','(20/100) x 60.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0313','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Analyze the strategy of finding a percentage using simpler parts: How would you find 15% of 200 mentally?','["Find 10% (20), then find 5% which is half of 10% (10). Add them together (20 + 10 = 30).","Multiply 15 by 200.","Divide 200 by 15.","It cannot be done mentally."]',0,'Split it up.','Break 15% into 10% + 5%.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0314','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Synthesize: Find 35% of 80 using mental math strategies.','["28 (10% is 8, 30% is 24, 5% is 4. 24 + 4 = 28).","35","24","40"]',0,'Use 10% chunks.','Break into 30% + 5%.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0315','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Critique the mistake: ''Finding the percentage amount incorrectly: 20% of 60 is 20.''','["False, they just copied the percentage number. 20% of 60 requires calculation (60 / 5 = 12).","True, 20 is the percent.","False, it is 60.","False, it is 10."]',0,'20% is 1/5th.','The percentage is a RATIO, not an absolute amount.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0316','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Evaluate the real-world application: If a library has 120 books and 20% are science books, how many science books are there?','["24","30","120","20"]',0,'Calculate carefully.','(20/100) x 120.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0317','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Analyze: If you know 10% of a number is 14, what is the whole number (100%)?','["140","14","1.4","1400"]',0,'Scale up.','Multiply by 10 to get back to 100%.','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0318','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Synthesize: What is 12.5% of 80?','["10 (Since 12.5% is 1/8, 80 / 8 = 10).","12.5","8","20"]',0,'Half of 25%.','12.5% is a very useful fraction to know (1/8).','2026-11-01 17:50:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0319','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Analyze the strategy of finding a percentage using simpler parts: How would you find 15% of 200 mentally?','["Find 10% (20), then find 5% which is half of 10% (10). Add them together (20 + 10 = 30).","Multiply 15 by 200.","Divide 200 by 15.","It cannot be done mentally."]',0,'Split it up.','Break 15% into 10% + 5%.','2026-11-01 17:50:10',NULL,NULL);
