INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0324','Maths','Ratio, Proportion and Percentages','Subtopic 9: Finding a Percentage of a Quantity','Primary',10,'Synthesize: What is 12.5% of 80?','["10 (Since 12.5% is 1/8, 80 / 8 = 10).","12.5","8","20"]',0,'Half of 25%.','12.5% is a very useful fraction to know (1/8).','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0325','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'What is a ''discount'' in shopping?','["An amount taken off the original price, making it cheaper.","An extra tax.","The final price.","A type of credit card."]',0,'Taking money off.','A reduction in price.','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0326','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'If a bag costs 800 units and the shop offers a 10% discount, how much is the discount AMOUNT?','["80 units (10% of 800)","800 units","10 units","720 units"]',0,'Divide by 10.','Find 10% of 800.','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0327','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'Once you know the discount amount (80 units) for the 800 unit bag, how do you find the FINAL price?','["Subtract the discount from the original price (800 - 80 = 720).","Add them together.","Multiply them.","It is 80."]',0,'Take it off.','Original - Discount = Final.','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0328','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'If a learner scores 42 marks out of 60, what fraction represents their score?','["42/60","60/42","42/100","60/100"]',0,'Part over whole.','Marks obtained over total marks.','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0329','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'If 100 learners are surveyed and 50% choose sports, how many chose sports?','["50","100","50","10"]',0,'Out of 100 is easy.','50% of 100 is 50.','2026-11-01 17:50:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0330','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'If a plant grows from 40 cm to 50 cm, how much did its height INCREASE in cm?','["10 cm","50 cm","40 cm","90 cm"]',0,'Find the difference.','50 - 40 = 10.','2026-11-01 17:50:12',NULL,NULL);
