INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0336','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',1,'If a plant grows from 40 cm to 50 cm, how much did its height INCREASE in cm?','["10 cm","50 cm","40 cm","90 cm"]',0,'Find the difference.','50 - 40 = 10.','2026-11-01 17:50:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0337','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'To calculate a percentage score (e.g. 42 out of 60), what is the formula?','["(Marks obtained / Total marks) x 100","Total marks / Marks obtained","Marks obtained + 100","Total marks - Marks obtained"]',0,'Make it out of 100.','Fraction x 100 gives percentage.','2026-11-01 17:50:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0338','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'Calculate the percentage for 42 out of 60.','["70%","80%","42%","60%"]',0,'Simplify 42/60 first (7/10).','(42/60) x 100 = 0.7 x 100 = 70%.','2026-11-01 17:50:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0339','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'A test has 80 marks. A learner scores 75%. How many marks did they earn?','["60 marks","75 marks","80 marks","20 marks"]',0,'Three-quarters of 80.','75% is 3/4. 3/4 of 80 is 60.','2026-11-01 17:50:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0340','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'In a survey of 200 learners, 35% choose sports. How many chose sports?','["70","35","100","135"]',0,'35 x 2.','(35/100) x 200 = 70.','2026-11-01 17:50:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0341','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'If 35% of 200 learners choose sports, what percentage choose something else?','["65%","165%","35%","100%"]',0,'The rest of the whole.','100% - 35% = 65%.','2026-11-01 17:50:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0342','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'What does ''percentage increase'' tell us?','["How much a quantity has grown compared with its ORIGINAL value.","How big it is now.","The final number.","How much it shrank."]',0,'Compared to the beginning.','Growth relative to the start.','2026-11-01 17:50:13',NULL,NULL);
