INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0347','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'If 35% of 200 learners choose sports, what percentage choose something else?','["65%","165%","35%","100%"]',0,'The rest of the whole.','100% - 35% = 65%.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0348','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',5,'What does ''percentage increase'' tell us?','["How much a quantity has grown compared with its ORIGINAL value.","How big it is now.","The final number.","How much it shrank."]',0,'Compared to the beginning.','Growth relative to the start.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0349','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Analyze the formula for Percentage Increase: A plant grows from 40cm to 50cm. Why do you divide the increase (10cm) by the ORIGINAL height (40cm) and not the new height (50cm)?','["Because growth is always measured relative to the starting point (10/40 = 25% increase).","Because 40 is smaller.","You should divide by 50.","It doesn''t matter."]',0,'Always use the starting value.','Change / Original x 100.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0350','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Synthesize a Percentage Decrease: A box has 100 sheets. 20 are used. What is the percentage decrease?','["20%","80%","100%","0%"]',0,'Change / Original.','Decrease is 20. (20/100) x 100 = 20%.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0351','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Evaluate: A club had 50 members last year and 60 this year. What is the percentage increase?','["20% (Increase of 10. 10 / 50 = 1/5 = 20%).","10%","60%","16%"]',0,'Don''t just use the difference!','Change (10) / Original (50) = 0.2.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0352','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Critique the mistake: ''Diana saw a 20% discount on a 500 unit item and said the final price is 20 units.''','["False, they confused the percentage number with the final price. The discount is 100 (20% of 500), so the final price is 400.","True.","False, the final price is 500.","False, the final price is 20%."]',0,'Don''t skip steps.','Calculate the amount, THEN subtract.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0353','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Synthesize: If a price is increased by 10%, then immediately decreased by 10%, is it back to the original price?','["No, it will be slightly less than the original because the 10% decrease is calculated on a LARGER number.","Yes, they cancel out.","No, it will be more.","Only for $100."]',0,'Do the math with a real number.','Try it with 100. -> 110. -> 10% of 110 is 11. 110 - 11 = 99.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0354','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Analyze: Why is it a common mistake to add percentages from different wholes? (e.g. 50% of boys + 50% of girls = 100% of students?)','["Because percentages are relative to their specific base (whole); they cannot be directly added unless the bases are identical.","It isn''t a mistake.","Because 50+50 is 100.","Because boys and girls are different."]',0,'You can''t add apples to oranges.','Percentages are ratios, not absolute counts.','2026-11-01 17:50:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0355','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Analyze the formula for Percentage Increase: A plant grows from 40cm to 50cm. Why do you divide the increase (10cm) by the ORIGINAL height (40cm) and not the new height (50cm)?','["Because growth is always measured relative to the starting point (10/40 = 25% increase).","Because 40 is smaller.","You should divide by 50.","It doesn''t matter."]',0,'Always use the starting value.','Change / Original x 100.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0356','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Synthesize a Percentage Decrease: A box has 100 sheets. 30 are used. What is the percentage decrease?','["30%","70%","100%","0%"]',0,'Change / Original.','Decrease is 30. (30/100) x 100 = 30%.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0357','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Evaluate: A club had 50 members last year and 60 this year. What is the percentage increase?','["20% (Increase of 10. 10 / 50 = 1/5 = 20%).","10%","60%","16%"]',0,'Don''t just use the difference!','Change (10) / Original (50) = 0.2.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0358','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Critique the mistake: ''Julia saw a 20% discount on a 500 unit item and said the final price is 20 units.''','["False, they confused the percentage number with the final price. The discount is 100 (20% of 500), so the final price is 400.","True.","False, the final price is 500.","False, the final price is 20%."]',0,'Don''t skip steps.','Calculate the amount, THEN subtract.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0359','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Synthesize: If a price is increased by 10%, then immediately decreased by 10%, is it back to the original price?','["No, it will be slightly less than the original because the 10% decrease is calculated on a LARGER number.","Yes, they cancel out.","No, it will be more.","Only for $100."]',0,'Do the math with a real number.','Try it with 100. -> 110. -> 10% of 110 is 11. 110 - 11 = 99.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t8_global_0360','Maths','Ratio, Proportion and Percentages','Subtopic 10: Real-Life Percentage Problems','Primary',10,'Analyze: Why is it a common mistake to add percentages from different wholes? (e.g. 50% of boys + 50% of girls = 100% of students?)','["Because percentages are relative to their specific base (whole); they cannot be directly added unless the bases are identical.","It isn''t a mistake.","Because 50+50 is 100.","Because boys and girls are different."]',0,'You can''t add apples to oranges.','Percentages are ratios, not absolute counts.','2026-11-01 17:50:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0001','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'What does the short hand on an analogue clock show?','["The hour","The minutes","The seconds","The day"]',0,'It points to the big numbers.','The short hand is the hour hand.','2026-11-01 17:58:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0002','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'What does the long hand on an analogue clock show?','["The minutes","The hour","The month","The year"]',0,'It sweeps around faster.','The long hand is the minute hand.','2026-11-01 17:58:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0003','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'If the long minute hand is pointing exactly at 12, what does it mean?','["It is exactly on the hour (00 minutes).","It is half past.","It is 12 minutes past.","It is midnight."]',0,'O''clock.','Top of the clock means the start of a new hour.','2026-11-01 17:58:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0004','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'Look at a clock. The short hand is pointing exactly at 6, and the long hand is at 12. What time is it?','["6:00","12:06","6:30","12:00"]',0,'O''clock.','Short hand at 6, long hand at 12 means 6 o''clock.','2026-11-01 17:58:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0005','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'When the minute hand (long hand) points to the 6, how many minutes past the hour is it?','["30 minutes (half past)","6 minutes","15 minutes","45 minutes"]',0,'Halfway around the circle.','6 x 5 = 30 minutes. It has traveled halfway around.','2026-11-01 17:58:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0006','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',1,'If the long hand points to the 3, how many minutes past the hour is it?','["15 minutes (quarter past)","3 minutes","30 minutes","45 minutes"]',0,'15 mins.','3 x 5 = 15 minutes. A quarter of the way around.','2026-11-01 17:58:10',NULL,NULL);
