INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0013','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The hour hand is halfway between 5 and 6. The minute hand is on the 6. What time is it?','["5:30","6:30","5:06","6:5"]',0,'Look at the hour it just passed.','It has passed 5 but hasn''t reached 6 yet.','2026-11-01 17:58:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0014','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The minute hand points to the 9. How many minutes is this?','["45 minutes (quarter to)","9 minutes","15 minutes","30 minutes"]',0,'Multiply by 5.','9 x 5 = 45 minutes.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0015','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The hour hand is almost at 11, but the minute hand is on the 9. What time is it?','["10:45","11:45","10:09","11:09"]',0,'Look at the hour before the one it''s approaching.','It hasn''t reached 11 yet. The time is 10:45.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0016','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'If the minute hand points to the 5, how many minutes past the hour is it?','["25 minutes","5 minutes","15 minutes","30 minutes"]',0,'Count by fives.','5 x 5 = 25.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0017','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'What time is ''quarter past 11''?','["11:15","11:45","11:30","15:11"]',0,'15 mins.','Quarter past means 15 minutes past.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0018','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'What time is ''quarter to 4''?','["3:45","4:45","4:15","3:15"]',0,'Not quite the hour yet.','15 minutes BEFORE 4 is 3:45.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0019','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The hour hand is halfway between 6 and 7. The minute hand is on the 6. What time is it?','["6:30","7:30","6:06","6:6"]',0,'Look at the hour it just passed.','It has passed 6 but hasn''t reached 7 yet.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0020','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The minute hand points to the 9. How many minutes is this?','["45 minutes (quarter to)","9 minutes","15 minutes","30 minutes"]',0,'Multiply by 5.','9 x 5 = 45 minutes.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0021','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'The hour hand is almost at 12, but the minute hand is on the 9. What time is it?','["11:45","12:45","11:09","12:09"]',0,'Look at the hour before the one it''s approaching.','It hasn''t reached 12 yet. The time is 11:45.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0022','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'If the minute hand points to the 6, how many minutes past the hour is it?','["30 minutes","6 minutes","15 minutes","30 minutes"]',0,'Count by fives.','6 x 5 = 30.','2026-11-01 17:58:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0023','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'What time is ''quarter past 7''?','["7:15","7:45","7:30","15:7"]',0,'15 mins.','Quarter past means 15 minutes past.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0024','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',5,'What time is ''quarter to 5''?','["4:45","5:45","5:15","4:15"]',0,'Not quite the hour yet.','15 minutes BEFORE 5 is 4:45.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0025','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Analyze: Why does the hour hand move continuously between numbers, rather than jumping from one to the next exactly on the hour?','["Because time is continuous; as minutes pass, the hour hand proportionally moves toward the next hour.","Because the clock is broken.","To confuse people.","It actually jumps."]',0,'Continuous motion.','It slowly creeps forward.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0026','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Critique the mistake: ''The long hand is on the 4, so it is 4 minutes past the hour.''','["False, each number represents a 5-minute interval. It is 4 x 5 = 20 minutes past the hour.","True.","False, it is 40 minutes.","False, it is 15 minutes."]',0,'Groups of 5.','Multiply the number by 5.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0027','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Synthesize: If the hour hand is exactly on the 5 and the minute hand is exactly on the 12, what time will it be in 30 minutes?','["The time will be 5:30, and the hour hand will be halfway between 5 and 6.","5:30, hour hand on 5.","6:30","12:5"]',0,'Think about the hour hand''s movement.','The hour hand must move halfway.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0028','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Evaluate: At 3:15, do the hour hand and minute hand overlap exactly?','["No. The minute hand is exactly on the 3, but the hour hand has moved 1/4 of the way toward the 4.","Yes.","No, they point opposite.","Only on digital clocks."]',0,'Slight offset.','The hour hand doesn''t stay perfectly on the 3.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0029','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Analyze: How many small tick marks are there between the 12 and the 1 on a standard clock face?','["4 marks (creating 5 intervals, representing 5 minutes).","5 marks","1 mark","0 marks"]',0,'Think of a ruler.','Count the gaps.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0030','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Synthesize: Fiona sees the long hand on the 11 and the short hand just before the 8. What time is it?','["7:55","8:55","11:40","11:08"]',0,'Almost 8.','It is 5 minutes to 8.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0031','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Analyze: Why does the hour hand move continuously between numbers, rather than jumping from one to the next exactly on the hour?','["Because time is continuous; as minutes pass, the hour hand proportionally moves toward the next hour.","Because the clock is broken.","To confuse people.","It actually jumps."]',0,'Continuous motion.','It slowly creeps forward.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0032','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Critique the mistake: ''The long hand is on the 4, so it is 4 minutes past the hour.''','["False, each number represents a 5-minute interval. It is 4 x 5 = 20 minutes past the hour.","True.","False, it is 40 minutes.","False, it is 15 minutes."]',0,'Groups of 5.','Multiply the number by 5.','2026-11-01 17:58:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0033','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Synthesize: If the hour hand is exactly on the 6 and the minute hand is exactly on the 12, what time will it be in 30 minutes?','["The time will be 6:30, and the hour hand will be halfway between 6 and 7.","6:30, hour hand on 6.","7:30","12:6"]',0,'Think about the hour hand''s movement.','The hour hand must move halfway.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0034','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Evaluate: At 3:15, do the hour hand and minute hand overlap exactly?','["No. The minute hand is exactly on the 3, but the hour hand has moved 1/4 of the way toward the 4.","Yes.","No, they point opposite.","Only on digital clocks."]',0,'Slight offset.','The hour hand doesn''t stay perfectly on the 3.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0035','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Analyze: How many small tick marks are there between the 12 and the 1 on a standard clock face?','["4 marks (creating 5 intervals, representing 5 minutes).","5 marks","1 mark","0 marks"]',0,'Think of a ruler.','Count the gaps.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0036','Maths','Time and Calendar','Subtopic 1: Reading Analogue Clocks','Primary',10,'Synthesize: Liam sees the long hand on the 11 and the short hand just before the 8. What time is it?','["7:55","8:55","11:40","11:08"]',0,'Almost 8.','It is 5 minutes to 8.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0037','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'On a digital clock, what does the colon (:) do?','["It separates the hours (on the left) from the minutes (on the right).","It means add.","It separates days and months.","It is just a decoration."]',0,'Separator.','Hours on left, minutes on right.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0038','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'Look at this digital time: 05:00. What time does it show?','["5 o''clock","Zero point 5","5 minutes","Midnight"]',0,'O''clock.','00 minutes means exactly on the hour.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0039','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'Read this digital time: 04:30. How do you say it?','["Half past 4","Quarter past 4","Quarter to 4","Thirty to 4"]',0,'Half past.','30 minutes is half an hour.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0040','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'Read this digital time: 10:15. How do you say it?','["Quarter past ten","Half past ten","Quarter to eleven","Ten to fifteen"]',0,'Quarter past.','15 minutes is a quarter past.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0041','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'What does the leading zero mean in ''09:15''?','["It is just a placeholder to keep the format consistent; it still means 9 hours.","It means midnight.","It means 90.","It means it''s a mistake."]',0,'Placeholder.','Just a formatting style.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0042','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'Look at 04:45. What is another way to say this time?','["Quarter to five.","Quarter past four.","Half past four.","Forty-five past five."]',0,'Quarter to.','15 minutes until 5:00.','2026-11-01 17:58:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0043','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'On a digital clock, what does the colon (:) do?','["It separates the hours (on the left) from the minutes (on the right).","It means add.","It separates days and months.","It is just a decoration."]',0,'Separator.','Hours on left, minutes on right.','2026-11-01 17:58:13',NULL,NULL);
