INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0047','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'What does the leading zero mean in ''09:15''?','["It is just a placeholder to keep the format consistent; it still means 9 hours.","It means midnight.","It means 90.","It means it''s a mistake."]',0,'Placeholder.','Just a formatting style.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0048','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',1,'Look at 04:45. What is another way to say this time?','["Quarter to five.","Quarter past four.","Half past four.","Forty-five past five."]',0,'Quarter to.','15 minutes until 5:00.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0049','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'Why is 07:05 different from 07:50?','["07:05 is five minutes past seven, while 07:50 is fifty minutes past seven. The zero changes the place value.","They are the same.","07:50 is wrong.","07:05 is morning, 07:50 is night."]',0,'Five vs Fifty.','Place value applies to digital clocks too.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0050','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'If a digital clock says 11:45, how many minutes until 12:00?','["15 minutes","45 minutes","5 minutes","60 minutes"]',0,'Quarter to.','60 - 45 = 15.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0051','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'A timer displays 00:10. What does this usually mean?','["Zero hours/minutes and 10 seconds (or minutes/seconds depending on context). Always check the labels.","Ten hours.","10 o''clock.","Midnight."]',0,'Look at the context.','Timers often show M:S.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0052','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'What time is it 20 minutes after 10:10?','["10:30","10:20","10:40","10:15"]',0,'Add the minutes.','10 + 20 = 30.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0053','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'Which of these shows ''half past eight''?','["08:30","08:15","08:45","08:00"]',0,'30 mins.','Half an hour is 30 minutes.','2026-11-01 17:58:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0054','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'If a clock shows 12:00, what time is it?','["Noon or Midnight","One o''clock","Morning","Evening"]',0,'O''clock.','12:00 can be midday or night.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0055','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'Why is 07:05 different from 07:50?','["07:05 is five minutes past seven, while 07:50 is fifty minutes past seven. The zero changes the place value.","They are the same.","07:50 is wrong.","07:05 is morning, 07:50 is night."]',0,'Five vs Fifty.','Place value applies to digital clocks too.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0056','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'If a digital clock says 11:45, how many minutes until 12:00?','["15 minutes","45 minutes","5 minutes","60 minutes"]',0,'Quarter to.','60 - 45 = 15.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0057','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'A timer displays 00:10. What does this usually mean?','["Zero hours/minutes and 10 seconds (or minutes/seconds depending on context). Always check the labels.","Ten hours.","10 o''clock.","Midnight."]',0,'Look at the context.','Timers often show M:S.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0058','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'What time is it 20 minutes after 10:10?','["10:30","10:20","10:40","10:15"]',0,'Add the minutes.','10 + 20 = 30.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0059','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'Which of these shows ''half past eight''?','["08:30","08:15","08:45","08:00"]',0,'30 mins.','Half an hour is 30 minutes.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0060','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',5,'If a clock shows 12:00, what time is it?','["Noon or Midnight","One o''clock","Morning","Evening"]',0,'O''clock.','12:00 can be midday or night.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0061','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Critique the mistake: ''A digital clock shows 06:20, which means 6 hours and 20 hours.''','["False, the digits after the colon represent minutes, not hours.","True.","False, it means 620 minutes.","False, it means 6 divided by 20."]',0,'Read the parts.','Colon separates hours and minutes.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0062','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Analyze: Why do some digital clocks display ''00:00''?','["It represents midnight, the exact start of a new 24-hour day (zero hours and zero minutes have passed).","It means the clock is broken.","It means noon.","It is a glitch."]',0,'Start line.','The very beginning of the day.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0063','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Evaluate the context: If you set an oven timer to ''02:30'', what does it most likely mean?','["2 hours and 30 minutes (or 2 minutes and 30 seconds). Context dictates the units for timers.","Half past two in the morning.","230 degrees.","2 days and 30 hours."]',0,'Duration vs Time of day.','Timers show duration, not the time of day.','2026-11-01 17:58:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0064','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Synthesize: What digital time is exactly 1 hour and 15 minutes after 09:45?','["11:00","10:60","10:45","11:15"]',0,'Roll over the hour.','45 + 15 = 60 mins (which rolls over to the next hour). 9 + 1 + 1 = 11.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0065','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Analyze: Why is digital time considered ''easier'' to read than analogue time for young children?','["It directly provides the numeric values for hours and minutes without requiring the interpretation of hands and spatial angles.","Because it is brighter.","Because it uses Roman numerals.","It isn''t easier."]',0,'Direct reading.','No decoding required.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0066','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Critique: ''Fiona sees 10:55 and says it is 55 minutes to 11.''','["False, it is 5 minutes to 11 (or 55 minutes PAST 10).","True.","False, it is 5 minutes to 10.","False, it is 11:55."]',0,'How many minutes until the next hour?','60 - 55 = 5.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0067','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Critique the mistake: ''A digital clock shows 06:20, which means 6 hours and 20 hours.''','["False, the digits after the colon represent minutes, not hours.","True.","False, it means 620 minutes.","False, it means 6 divided by 20."]',0,'Read the parts.','Colon separates hours and minutes.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0068','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Analyze: Why do some digital clocks display ''00:00''?','["It represents midnight, the exact start of a new 24-hour day (zero hours and zero minutes have passed).","It means the clock is broken.","It means noon.","It is a glitch."]',0,'Start line.','The very beginning of the day.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0069','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Evaluate the context: If you set an oven timer to ''02:30'', what does it most likely mean?','["2 hours and 30 minutes (or 2 minutes and 30 seconds). Context dictates the units for timers.","Half past two in the morning.","230 degrees.","2 days and 30 hours."]',0,'Duration vs Time of day.','Timers show duration, not the time of day.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0070','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Synthesize: What digital time is exactly 1 hour and 15 minutes after 09:45?','["11:00","10:60","10:45","11:15"]',0,'Roll over the hour.','45 + 15 = 60 mins (which rolls over to the next hour). 9 + 1 + 1 = 11.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0071','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Analyze: Why is digital time considered ''easier'' to read than analogue time for young children?','["It directly provides the numeric values for hours and minutes without requiring the interpretation of hands and spatial angles.","Because it is brighter.","Because it uses Roman numerals.","It isn''t easier."]',0,'Direct reading.','No decoding required.','2026-11-01 17:58:16',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0072','Maths','Time and Calendar','Subtopic 2: Reading Digital Clocks','Primary',10,'Critique: ''Liam sees 10:55 and says it is 55 minutes to 11.''','["False, it is 5 minutes to 11 (or 55 minutes PAST 10).","True.","False, it is 5 minutes to 10.","False, it is 11:55."]',0,'How many minutes until the next hour?','60 - 55 = 5.','2026-11-01 17:58:16',NULL,NULL);
