INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0090','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',5,'Convert 2 minute and 10 seconds entirely into seconds.','["130 seconds","70 seconds","11 seconds","100 seconds"]',0,'Convert minutes, then add.','2 x 60 = 120. Then add 10.','2026-11-01 17:58:18',NULL,NULL);
