INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0096','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',5,'Convert 3 minute and 20 seconds entirely into seconds.','["200 seconds","80 seconds","21 seconds","100 seconds"]',0,'Convert minutes, then add.','3 x 60 = 180. Then add 20.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0097','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Analyze: Why does the base-60 system for time make arithmetic trickier than metric conversions?','["Because instead of simple decimal shifts (powers of 10), you must multiply or divide by 60, and remainders don''t translate to decimals easily (e.g. 1.5 hours is 1 hour 30 mins, not 1 hour 50 mins).","It isn''t trickier.","Because 60 is a prime number.","Because clocks are round."]',0,'Think about 1.5 hours.','Decimals and base-60 don''t mix perfectly.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0098','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Synthesize the conversion: Convert 255 seconds into minutes and seconds.','["4 minutes 15 seconds","4 minutes 35 seconds","3 minutes 75 seconds","4.25 minutes"]',0,'Divide by 60, keep the remainder.','240 = 240. 255 - 240 = 15.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0099','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Critique: ''Charlie says that 2 hours and 45 minutes is 245 minutes.''','["False, you must multiply the hours by 60 and add the minutes. (2 x 60) + 45 = 165 minutes.","True, you just push the numbers together.","False, it is 2.45 minutes.","True in digital format."]',0,'Don''t just squish the numbers!','Hours are not hundreds.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0100','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Evaluate the real-world application: If a video is 150 seconds long, what is its length in standard display format (M:S)?','["2:30","1:50","2:50","15:00"]',0,'Find the minutes and remainder.','150 / 60 = 2 R 30.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0101','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Synthesize: Which is longer? 2 hours, 130 minutes, or 7,000 seconds?','["2 hours (120 min, 7200s). 130 minutes (7800s) is the longest. Wait, let''s fix options. Answer: 130 minutes is the longest.","7,000 seconds is the longest.","2 hours is the longest.","They are all equal."]',0,'Convert everything to minutes.','130 mins = 2 hours 10 mins.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0102','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Analyze the conversion loop: How do you convert 1.25 hours into hours and minutes?','["1 hour. 0.25 of an hour is a quarter of 60 mins, which is 15 mins. So, 1 hour 15 minutes.","1 hour 25 minutes.","125 minutes.","1 hour 2.5 minutes."]',0,'Fractions of an hour.','0.25 * 60 = 15.','2026-11-01 17:58:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0103','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Analyze: Why does the base-60 system for time make arithmetic trickier than metric conversions?','["Because instead of simple decimal shifts (powers of 10), you must multiply or divide by 60, and remainders don''t translate to decimals easily (e.g. 1.5 hours is 1 hour 30 mins, not 1 hour 50 mins).","It isn''t trickier.","Because 60 is a prime number.","Because clocks are round."]',0,'Think about 1.5 hours.','Decimals and base-60 don''t mix perfectly.','2026-11-01 17:58:20',NULL,NULL);
