INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0105','Maths','Time and Calendar','Subtopic 3: Hours, Minutes and Seconds','Primary',10,'Critique: ''Ian says that 2 hours and 45 minutes is 245 minutes.''','["False, you must multiply the hours by 60 and add the minutes. (2 x 60) + 45 = 165 minutes.","True, you just push the numbers together.","False, it is 2.45 minutes.","True in digital format."]',0,'Don''t just squish the numbers!','Hours are not hundreds.','2026-11-01 17:58:20',NULL,NULL);
