INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0109','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',1,'What does ''a.m.'' mean?','["Morning (before noon).","Afternoon.","Night time only.","All day."]',0,'Ante meridiem.','From midnight to noon.','2026-11-01 17:58:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0110','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',1,'What does ''p.m.'' mean?','["Afternoon and evening (after midday).","Morning.","Midnight.","Past morning."]',0,'Post meridiem.','From noon to midnight.','2026-11-01 17:58:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0111','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',1,'What time is ''Noon''?','["12:00 p.m. (midday).","12:00 a.m.","Midnight.","6:00 p.m."]',0,'Lunchtime.','The middle of the day when you eat lunch.','2026-11-01 17:58:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0112','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',1,'What time is ''Midnight''?','["12:00 a.m. (the very start of a new day).","12:00 p.m.","Noon.","10:00 p.m."]',0,'Spooky time.','The middle of the night.','2026-11-01 17:58:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0113','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',1,'If Ethan eats breakfast, what letters should be after the time?','["a.m.","p.m.","m.m.","o''clock"]',0,'Morning meal.','Breakfast is in the morning.','2026-11-01 17:58:20',NULL,NULL);
