INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0124','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',5,'Is 12:15 a.m. in the middle of the day or the middle of the night?','["Middle of the night (just past midnight).","Middle of the day.","Afternoon.","Morning."]',0,'Dark outside.','12 a.m. is midnight.','2026-11-01 17:58:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0125','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',5,'Is 11:59 a.m. right before lunch or right before midnight?','["Right before lunch (noon).","Right before midnight.","Breakfast time.","Dinner time."]',0,'Almost midday.','11:59 a.m. is the minute before 12:00 p.m. (noon).','2026-11-01 17:58:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0126','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',5,'If Fiona eats dinner at 6:30, is that a.m. or p.m.?','["p.m.","a.m.","Neither","Both"]',0,'Evening.','Dinner is an evening meal.','2026-11-01 17:58:22',NULL,NULL);
