INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0131','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',5,'Is 11:59 a.m. right before lunch or right before midnight?','["Right before lunch (noon).","Right before midnight.","Breakfast time.","Dinner time."]',0,'Almost midday.','11:59 a.m. is the minute before 12:00 p.m. (noon).','2026-11-01 17:58:22',NULL,NULL);
