INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0133','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Analyze the confusing convention: Why is 12:00 p.m. followed by 1:00 p.m. instead of 13:00 p.m.?','["The 12-hour clock restarts its numbering at 1, but the a.m./p.m. period doesn''t switch until the 12 o''clock hour is completed.","Because 13 is unlucky.","It isn''t, it is 13:00.","Because p.m. means 1."]',0,'It resets to 1.','The 12 is acting like a 0 for the hour count.','2026-11-01 17:58:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0134','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Critique the statement: ''12:00 a.m. is the end of the day.''','["False, standard convention dictates that midnight (12:00 a.m.) is the precise start of a NEW calendar day.","True, it is the last minute.","False, 11:59 p.m. is the start.","True, time stops."]',0,'New day starts.','The date rolls over at exactly midnight.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0135','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Synthesize: If an event starts at 11:45 p.m. and lasts 30 minutes, what time and period does it end in?','["12:15 a.m. (the next day).","12:15 p.m.","11:15 a.m.","1:15 p.m."]',0,'Roll over the midnight barrier.','It crosses the midnight boundary into the next day (a.m.).','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0136','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Evaluate: Why do transportation schedules often use the 24-hour clock instead of a.m./p.m.?','["To eliminate the risk of a.m./p.m. confusion, which could cause someone to miss a flight by 12 hours.","Because it looks cooler.","Because 24 is bigger than 12.","They don''t use it."]',0,'No confusion.','Clarity and error prevention.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0137','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Analyze: What does ''ante meridiem'' literally translate to?','["Before midday.","After midday.","At night.","In the morning."]',0,'Latin root.','Meridiem means midday.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0138','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Critique: ''If it is 12:01 p.m., the sun has already set.''','["False, 12:01 p.m. is exactly one minute past noon (midday).","True.","False, it is midnight.","False, the sun never sets."]',0,'Just past lunch.','p.m. starts at lunch.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0139','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Analyze the confusing convention: Why is 12:00 p.m. followed by 1:00 p.m. instead of 13:00 p.m.?','["The 12-hour clock restarts its numbering at 1, but the a.m./p.m. period doesn''t switch until the 12 o''clock hour is completed.","Because 13 is unlucky.","It isn''t, it is 13:00.","Because p.m. means 1."]',0,'It resets to 1.','The 12 is acting like a 0 for the hour count.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0140','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Critique the statement: ''12:00 a.m. is the end of the day.''','["False, standard convention dictates that midnight (12:00 a.m.) is the precise start of a NEW calendar day.","True, it is the last minute.","False, 11:59 p.m. is the start.","True, time stops."]',0,'New day starts.','The date rolls over at exactly midnight.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0141','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Synthesize: If an event starts at 11:45 p.m. and lasts 30 minutes, what time and period does it end in?','["12:15 a.m. (the next day).","12:15 p.m.","11:15 a.m.","1:15 p.m."]',0,'Roll over the midnight barrier.','It crosses the midnight boundary into the next day (a.m.).','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0142','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Evaluate: Why do transportation schedules often use the 24-hour clock instead of a.m./p.m.?','["To eliminate the risk of a.m./p.m. confusion, which could cause someone to miss a flight by 12 hours.","Because it looks cooler.","Because 24 is bigger than 12.","They don''t use it."]',0,'No confusion.','Clarity and error prevention.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0143','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Analyze: What does ''ante meridiem'' literally translate to?','["Before midday.","After midday.","At night.","In the morning."]',0,'Latin root.','Meridiem means midday.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0144','Maths','Time and Calendar','Subtopic 4: A.M. and P.M.','Primary',10,'Critique: ''If it is 12:01 p.m., the sun has already set.''','["False, 12:01 p.m. is exactly one minute past noon (midday).","True.","False, it is midnight.","False, the sun never sets."]',0,'Just past lunch.','p.m. starts at lunch.','2026-11-01 17:58:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0145','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',1,'What is the ''24-hour clock''?','["A clock that counts the hours from 00 to 23, so a.m. and p.m. are not needed.","A clock with 24 hands.","A clock that only works for 24 days.","A clock that repeats 1-12 twice."]',0,'00 to 23.','It numbers every hour of the day uniquely.','2026-11-01 17:58:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0146','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',1,'In 24-hour time, what does 06:00 mean?','["6:00 a.m. (morning)","6:00 p.m. (evening)","12:00 p.m.","Midnight"]',0,'Early.','Numbers less than 12 are morning times.','2026-11-01 17:58:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0147','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',1,'In 24-hour time, what does 12:00 mean?','["Noon (midday)","Midnight","1:00 p.m.","12:00 a.m."]',0,'Lunchtime.','12:00 is midday.','2026-11-01 17:58:24',NULL,NULL);
