INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0149','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',1,'Convert 6:00 p.m. (afternoon) to 24-hour time.','["18:00","06:00","6:00","18:30"]',0,'Add 12.','Add 12 to p.m. hours: 6 + 12.','2026-11-01 17:58:24',NULL,NULL);
