INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0159','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',5,'Convert 00:15 to 12-hour time.','["12:15 a.m.","12:15 p.m.","0:15 a.m.","1:15 a.m."]',0,'Midnight hour.','00 hours is the midnight hour.','2026-11-01 17:58:25',NULL,NULL);
