INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0162','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',5,'Why do we put a zero in front of early morning times like 07:25?','["A leading zero keeps the digital format consistently 4 digits wide.","Because it is negative.","To confuse people.","It means midnight."]',0,'Placeholder.','Formatting consistency.','2026-11-01 17:58:25',NULL,NULL);
