INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0169','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Analyze the conversion rule: Why do we ADD 12 to afternoon times to get 24-hour time?','["Because 12 hours of the morning have already passed. The 24-hour clock continues counting up instead of restarting at 1.","Because 12 is a lucky number.","It''s just a random rule.","We subtract 12."]',0,'Don''t restart the clock.','Continuing the count past noon.','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0170','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Evaluate the edge case: Convert 12:15 a.m. to 24-hour time.','["00:15","12:15","24:15","1:15"]',0,'Reset to zero.','12 a.m. is the start of the day (zero hours).','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0171','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Synthesize: Charlie''s flight departs at 23:45. They must be at the gate 1 hour early. What time (in 12-hour format) should they be there?','["10:45 p.m.","11:45 p.m.","9:45 p.m.","10:45 a.m."]',0,'Convert then subtract.','23:45 - 1 hr = 22:45. 22 - 12 = 10 p.m.','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0172','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Critique: ''The time 24:00 is exactly the same as 00:00.''','["True in concept (they represent midnight), but standard convention usually uses 00:00 for the START of a day and 24:00 for the END of a day.","False, 24:00 doesn''t exist.","False, 00:00 is noon.","True, there is no difference."]',0,'Midnight.','Start of day vs End of day.','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0173','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Analyze: If a train schedule says ''Departs 18:05'', what time is this?','["6:05 p.m.","8:05 p.m.","6:05 a.m.","18:05 a.m."]',0,'Subtract 12.','18 - 12 = 6.','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0174','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Synthesize: Convert ''quarter to midnight'' into 24-hour format.','["23:45","11:45","00:45","24:45"]',0,'15 mins before midnight.','11:45 p.m. -> 23:45.','2026-11-01 17:58:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0175','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Analyze the conversion rule: Why do we ADD 12 to afternoon times to get 24-hour time?','["Because 12 hours of the morning have already passed. The 24-hour clock continues counting up instead of restarting at 1.","Because 12 is a lucky number.","It''s just a random rule.","We subtract 12."]',0,'Don''t restart the clock.','Continuing the count past noon.','2026-11-01 17:58:26',NULL,NULL);
