INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0177','Maths','Time and Calendar','Subtopic 5: 12-hour and 24-hour time','Primary',10,'Synthesize: Ian''s flight departs at 23:45. They must be at the gate 1 hour early. What time (in 12-hour format) should they be there?','["10:45 p.m.","11:45 p.m.","9:45 p.m.","10:45 a.m."]',0,'Convert then subtract.','23:45 - 1 hr = 22:45. 22 - 12 = 10 p.m.','2026-11-01 17:58:27',NULL,NULL);
