INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0204','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',5,'How many days are in a leap year?','["366","365","360","367"]',0,'Extra day.','One extra day in February.','2026-11-01 17:58:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0205','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Analyze the calendar: Why do we have leap years with 366 days?','["Because Earth takes approximately 365.25 days to orbit the sun. The extra 0.25 days accumulate, requiring an extra day every 4 years to keep the calendar aligned with seasons.","Because February was too short.","To give everyone an extra day off.","It''s just a tradition."]',0,'Fractional days.','Orbit mechanics.','2026-11-01 17:58:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0206','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Synthesize a multi-step conversion: How many hours are in 2 complete weeks?','["336 (2 x 7 = 14 days. 14 x 24 = 336 hours).","168","48","672"]',0,'Multiply twice.','Weeks -> Days -> Hours.','2026-11-01 17:58:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0207','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Evaluate the mistake: ''Charlie says that exactly 4 weeks is one month.''','["False, 4 weeks is exactly 28 days. Only February in a common year is exactly 28 days; other months have 30 or 31 days.","True, 4 weeks = 1 month.","False, a month is 5 weeks.","True for business."]',0,'Count the days.','Months are slightly longer than 4 weeks.','2026-11-01 17:58:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0208','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Synthesize: How many days are there in one leap year AND one common year combined?','["731","730","732","700"]',0,'Add them up.','366 + 365 = 731.','2026-11-01 17:58:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0209','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Critique: ''Every year divisible by 4 is a leap year.''','["False, century years (ending in 00) must ALSO be divisible by 400 to be a leap year (e.g., 2000 was a leap year, but 1900 was not).","True.","False, they must be divisible by 2.","False, they must be odd."]',0,'Year 1900.','The 100-year exception rule.','2026-11-01 17:58:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0210','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Analyze: If Fiona is exactly 3 years and 4 months old, how many months old are they?','["40","36","44","30"]',0,'Convert years to months.','(3 x 12) + 4 = 36 + 4 = 40.','2026-11-01 17:58:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0211','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Analyze the calendar: Why do we have leap years with 366 days?','["Because Earth takes approximately 365.25 days to orbit the sun. The extra 0.25 days accumulate, requiring an extra day every 4 years to keep the calendar aligned with seasons.","Because February was too short.","To give everyone an extra day off.","It''s just a tradition."]',0,'Fractional days.','Orbit mechanics.','2026-11-01 17:58:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0212','Maths','Time and Calendar','Subtopic 6: Converting Units of Time','Primary',10,'Synthesize a multi-step conversion: How many hours are in 2 complete weeks?','["336 (2 x 7 = 14 days. 14 x 24 = 336 hours).","168","48","672"]',0,'Multiply twice.','Weeks -> Days -> Hours.','2026-11-01 17:58:30',NULL,NULL);
