INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0217','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'What does ''elapsed time'' mean?','["The amount of time that passes between a starting time and an ending time.","What time it is right now.","The time you wake up.","A broken clock."]',0,'How long it took.','The duration.','2026-11-01 17:58:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0218','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'If a lesson starts at 9:00 a.m. and finishes at 11:00 a.m., how long is the elapsed time?','["2 hour(s)","11 hours","9 hours","3 hours"]',0,'Count the hours.','11 - 9 = 2.','2026-11-01 17:58:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0219','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'If Charlie plays a game from 3:00 p.m. to 3:45 p.m., how long did they play?','["45 minutes","30 minutes","15 minutes","3 hours"]',0,'Look at the minutes.','The hours are the same, just subtract the minutes.','2026-11-01 17:58:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0220','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'If you know the start time and the duration (how long it took), how do you find the finish time?','["Add the duration to the start time.","Subtract the duration.","Multiply them.","Divide them."]',0,'Push the clock forward.','Move forward in time.','2026-11-01 17:58:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0221','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'If you know the finish time and the duration, how do you find the start time?','["Subtract the duration from the finish time.","Add the duration.","Guess.","Look at a calendar."]',0,'Rewind the clock.','Move backward in time.','2026-11-01 17:58:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0222','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',1,'A show starts at 4:15 p.m. and lasts 10 minutes. When does it finish?','["4:25 p.m.","4:05 p.m.","5:15 p.m.","4:15 p.m."]',0,'Add minutes.','15 + 10 = 25.','2026-11-01 17:58:31',NULL,NULL);
