INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0229','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A library visit begins at 10:15 a.m. and ends at 11:45 a.m. How long is the visit?','["1 hour 30 minutes","1 hour 45 minutes","1 hour 15 minutes","30 minutes"]',0,'Break it into parts.','10:15 to 11:15 is 1 hr. 11:15 to 11:45 is 30 mins.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0230','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A movie starts at 2:40 p.m. and finishes at 4:10 p.m. Find the elapsed time.','["1 hour 30 minutes (90 minutes)","2 hours 30 minutes","1 hour 50 minutes","1 hour 10 minutes"]',0,'Jump to the next whole hour.','2:40 to 3:00 is 20m. 3:00 to 4:00 is 1h. 4:00 to 4:10 is 10m.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0231','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A lesson starts at 9:25 a.m. and lasts 1 hour 40 minutes. When does it finish?','["11:05 a.m.","10:65 a.m.","11:25 a.m.","10:05 a.m."]',0,'Watch the 60-minute rollover.','9:25 + 1hr = 10:25. 10:25 + 40 mins = 11:05 (carry over 60 mins).','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0232','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A bus arrives at 4:20 p.m. after a 35-minute journey. When did it leave?','["3:45 p.m.","3:55 p.m.","4:55 p.m.","3:20 p.m."]',0,'Count backward through the hour.','4:20 minus 20 mins is 4:00. Minus another 15 is 3:45.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0233','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A trip lasts 2 hours 30 minutes. How many total minutes is that?','["150 minutes","120 minutes","130 minutes","230 minutes"]',0,'Convert hours to minutes.','2 x 60 = 120. 120 + 30 = 150.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0234','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'Fiona studies for 95 minutes. Express this in hours and minutes.','["1 hour 35 minutes","1 hour 95 minutes","1 hour 45 minutes","9 hours 5 minutes"]',0,'Pull out 60 minutes.','95 - 60 = 35.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0235','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A library visit begins at 10:15 a.m. and ends at 11:45 a.m. How long is the visit?','["1 hour 30 minutes","1 hour 45 minutes","1 hour 15 minutes","30 minutes"]',0,'Break it into parts.','10:15 to 11:15 is 1 hr. 11:15 to 11:45 is 30 mins.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0236','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A movie starts at 2:40 p.m. and finishes at 4:10 p.m. Find the elapsed time.','["1 hour 30 minutes (90 minutes)","2 hours 30 minutes","1 hour 50 minutes","1 hour 10 minutes"]',0,'Jump to the next whole hour.','2:40 to 3:00 is 20m. 3:00 to 4:00 is 1h. 4:00 to 4:10 is 10m.','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0237','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A lesson starts at 9:25 a.m. and lasts 1 hour 40 minutes. When does it finish?','["11:05 a.m.","10:65 a.m.","11:25 a.m.","10:05 a.m."]',0,'Watch the 60-minute rollover.','9:25 + 1hr = 10:25. 10:25 + 40 mins = 11:05 (carry over 60 mins).','2026-11-01 17:58:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0238','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A bus arrives at 4:20 p.m. after a 35-minute journey. When did it leave?','["3:45 p.m.","3:55 p.m.","4:55 p.m.","3:20 p.m."]',0,'Count backward through the hour.','4:20 minus 20 mins is 4:00. Minus another 15 is 3:45.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0239','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'A trip lasts 2 hours 30 minutes. How many total minutes is that?','["150 minutes","120 minutes","130 minutes","230 minutes"]',0,'Convert hours to minutes.','2 x 60 = 120. 120 + 30 = 150.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0240','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',5,'Liam studies for 95 minutes. Express this in hours and minutes.','["1 hour 35 minutes","1 hour 95 minutes","1 hour 45 minutes","9 hours 5 minutes"]',0,'Pull out 60 minutes.','95 - 60 = 35.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0241','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Analyze the difficulty of crossing the ''hour boundary'': Why does 11:45 + 30 minutes equal 12:15, not 11:75?','["Because time is base-60, not base-100. Once the minutes reach 60, they roll over into 1 new hour.","Because time is base-10.","Because 12 comes after 11.","It should be 11:75."]',0,'Roll over at 60.','60 minutes = 1 hour.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0242','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Synthesize: A night journey begins at 10:30 p.m. and ends at 1:15 a.m. the next day. What is the elapsed time?','["2 hours 45 minutes.","3 hours 45 minutes.","2 hours 15 minutes.","1 hour 45 minutes."]',0,'Count to midnight, then past it.','10:30 to 12:00 = 1.5 hrs. 12:00 to 1:15 = 1.25 hrs.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0243','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Critique: ''Charlie calculated the time from 9:40 a.m. to 10:20 a.m. by doing 1020 - 940 = 80 minutes.''','["False, standard base-10 subtraction does not work on time formats because hours roll over at 60, not 100. The true elapsed time is 40 minutes.","True.","False, it is 120 minutes.","True for digital clocks."]',0,'Base-60 ruins normal subtraction.','Don''t treat time like a regular decimal number.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0244','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Evaluate: If a train departs at 22:45 and arrives at 02:15, how long was the journey?','["3 hours 30 minutes.","4 hours.","2 hours 30 minutes.","4 hours 30 minutes."]',0,'Crossing midnight on a 24-hour clock.','22:45 to 24:00 is 1h 15m. Plus 2h 15m is 3h 30m.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0245','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Synthesize: Ethan started a project at 1:55 p.m., took a 45-minute break, and worked for 2 hours and 10 minutes total. When did they finish?','["4:50 p.m.","4:05 p.m.","3:50 p.m.","5:00 p.m."]',0,'Add all the time durations together.','Total elapsed = 45m + 2h 10m = 2h 55m. 1:55 + 2h 55m = 3:55 + 55m = 4:50.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0246','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Analyze: Why is it helpful to draw a ''number line'' for time calculations?','["It visually separates the jumps to the next whole hour from the remaining minutes, preventing base-10 subtraction errors.","It isn''t helpful.","To practice drawing.","To make the clock straight."]',0,'Visualizing chunks.','Breaking it into chunks (to the hour, past the hour).','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0247','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Analyze the difficulty of crossing the ''hour boundary'': Why does 11:45 + 30 minutes equal 12:15, not 11:75?','["Because time is base-60, not base-100. Once the minutes reach 60, they roll over into 1 new hour.","Because time is base-10.","Because 12 comes after 11.","It should be 11:75."]',0,'Roll over at 60.','60 minutes = 1 hour.','2026-11-01 17:58:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0248','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Synthesize: A night journey begins at 10:30 p.m. and ends at 1:15 a.m. the next day. What is the elapsed time?','["2 hours 45 minutes.","3 hours 45 minutes.","2 hours 15 minutes.","1 hour 45 minutes."]',0,'Count to midnight, then past it.','10:30 to 12:00 = 1.5 hrs. 12:00 to 1:15 = 1.25 hrs.','2026-11-01 17:58:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0249','Maths','Time and Calendar','Subtopic 7: Calculating Elapsed Time','Primary',10,'Critique: ''Ian calculated the time from 9:40 a.m. to 10:20 a.m. by doing 1020 - 940 = 80 minutes.''','["False, standard base-10 subtraction does not work on time formats because hours roll over at 60, not 100. The true elapsed time is 40 minutes.","True.","False, it is 120 minutes.","True for digital clocks."]',0,'Base-60 ruins normal subtraction.','Don''t treat time like a regular decimal number.','2026-11-01 17:58:34',NULL,NULL);
