INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0266','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',5,'Convert 24 days into weeks and days.','["3 weeks and 3 days","3 weeks and 4 days","4 weeks","2 weeks and 10 days"]',0,'Divide by 7 and find remainder.','24 / 7 = 3 R 3.','2026-11-01 17:58:35',NULL,NULL);
