INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0276','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',5,'How many days are in two common (non-leap) years?','["730","732","700","720"]',0,'Double 365.','365 + 365 = 730.','2026-11-01 17:58:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0277','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Analyze the calendar system: Why is a month ''about 4 weeks'', but not exactly?','["Because 4 weeks is exactly 28 days. Most months have 30 or 31 days, leaving 2 or 3 extra days, which shifts the weekdays each month.","Because weeks change length.","Because months are exactly 4 weeks.","It''s just a saying."]',0,'Look at the extra days.','28 is smaller than 30 or 31.','2026-11-01 17:58:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0278','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Evaluate: ''Bob says that because a leap year happens every 4 years, the year 1900 was a leap year.''','["False, century years (ending in 00) must ALSO be divisible by 400 to be a leap year (2000 was, 1900 was not).","True, 1900 is divisible by 4.","False, 1900 is odd.","True, all 00 years are leap years."]',0,'The 400 year rule.','The 100-year exception rule corrects slight over-counting.','2026-11-01 17:58:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0279','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Synthesize: If a holiday begins on Friday and lasts exactly 3 days (inclusive counting), which day is the last day?','["Sunday","Monday","Saturday","Thursday"]',0,'Count the starting day.','Friday (1), Saturday (2), Sunday (3).','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0280','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Analyze: If a library book is borrowed on the 6th and returned on the 13th, how many ELAPSED days passed?','["7 days (13 - 6 = 7).","8 days","6 days","14 days"]',0,'Subtraction.','Elapsed time subtracts the start from the end (excluding one endpoint).','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0281','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Critique: ''Ethan says there are 52 weeks in a year, so a year is exactly 52 x 7 = 364 days long.''','["False, a common year is 365 days. It consists of 52 full weeks PLUS 1 extra day (or 2 in a leap year).","True.","False, it is 50 weeks.","False, it is 360 days."]',0,'Check the multiplication.','That extra day shifts the calendar every year.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0282','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Synthesize: If Fiona is exactly 2 years and 5 months old, how many total months old are they?','["29","24","30","17"]',0,'Convert years to months.','(2 x 12) + 5 = 24 + 5 = 29.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0283','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Analyze the calendar system: Why is a month ''about 4 weeks'', but not exactly?','["Because 4 weeks is exactly 28 days. Most months have 30 or 31 days, leaving 2 or 3 extra days, which shifts the weekdays each month.","Because weeks change length.","Because months are exactly 4 weeks.","It''s just a saying."]',0,'Look at the extra days.','28 is smaller than 30 or 31.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0284','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Evaluate: ''Hannah says that because a leap year happens every 4 years, the year 1900 was a leap year.''','["False, century years (ending in 00) must ALSO be divisible by 400 to be a leap year (2000 was, 1900 was not).","True, 1900 is divisible by 4.","False, 1900 is odd.","True, all 00 years are leap years."]',0,'The 400 year rule.','The 100-year exception rule corrects slight over-counting.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0285','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Synthesize: If a holiday begins on Friday and lasts exactly 3 days (inclusive counting), which day is the last day?','["Sunday","Monday","Saturday","Thursday"]',0,'Count the starting day.','Friday (1), Saturday (2), Sunday (3).','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0286','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Analyze: If a library book is borrowed on the 6th and returned on the 13th, how many ELAPSED days passed?','["7 days (13 - 6 = 7).","8 days","6 days","14 days"]',0,'Subtraction.','Elapsed time subtracts the start from the end (excluding one endpoint).','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0287','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Critique: ''Kevin says there are 52 weeks in a year, so a year is exactly 52 x 7 = 364 days long.''','["False, a common year is 365 days. It consists of 52 full weeks PLUS 1 extra day (or 2 in a leap year).","True.","False, it is 50 weeks.","False, it is 360 days."]',0,'Check the multiplication.','That extra day shifts the calendar every year.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0288','Maths','Time and Calendar','Subtopic 8: Days, Weeks, Months and Years','Primary',10,'Synthesize: If Liam is exactly 2 years and 5 months old, how many total months old are they?','["29","24","30","17"]',0,'Convert years to months.','(2 x 12) + 5 = 24 + 5 = 29.','2026-11-01 17:58:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0289','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',1,'What does a calendar help us do?','["Organise days, weeks, months, and years to plan events.","Tell the exact time of day.","Measure temperature.","Weigh objects."]',0,'Plan ahead.','It organizes dates.','2026-11-01 17:58:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0290','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',1,'On a monthly calendar, what do the columns (up and down) usually represent?','["The days of the week (Monday, Tuesday, etc.).","The months.","The years.","The hours."]',0,'M T W T F S S.','The top headers.','2026-11-01 17:58:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0291','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',1,'If you look down one specific column on a calendar, how many days apart is each date?','["7 days (exactly one week).","1 day","30 days","10 days"]',0,'One row down.','The same weekday repeats every 7 days.','2026-11-01 17:58:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0292','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',1,'If the 1st of the month is a Monday, what day is the 8th?','["Monday","Tuesday","Sunday","Cannot tell"]',0,'Add 7.','1 + 7 = 8. It falls in the same column.','2026-11-01 17:58:38',NULL,NULL);
