INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0301','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',5,'If the 8th is a Monday, what date is three days AFTER the 8th?','["11th (Thursday)","10th","12th","5th"]',0,'Move 3 boxes forward.','8 + 3 = 11.','2026-11-01 17:58:39',NULL,NULL);
