INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0303','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',5,'How many ELAPSED days are there from the 22nd to the 27th?','["5 days","6 days","4 days","7 days"]',0,'Subtract.','27 - 22 = 5.','2026-11-01 17:58:39',NULL,NULL);
