INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0305','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',5,'If the 5th is a Friday, what is the date of the NEXT Friday?','["12th","10th","13th","15th"]',0,'Add one week.','5 + 7 = 12.','2026-11-01 17:58:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0306','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',5,'Why is it clearer to write ''4 May'' instead of ''04/05''?','["Because ''04/05'' can mean May 4th (UK) or April 5th (US), depending on the regional format.","It isn''t clearer.","Because numbers are hard.","Because May has 3 letters."]',0,'Month first or Day first?','Avoid regional confusion.','2026-11-01 17:58:39',NULL,NULL);
