INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0312','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',5,'Why is it clearer to write ''4 May'' instead of ''04/05''?','["Because ''04/05'' can mean May 4th (UK) or April 5th (US), depending on the regional format.","It isn''t clearer.","Because numbers are hard.","Because May has 3 letters."]',0,'Month first or Day first?','Avoid regional confusion.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0313','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Analyze the layout: If you move one box down on a standard calendar, what mathematical operation have you performed on the date?','["You have added 7 (one full week).","You have added 1.","You have multiplied by 7.","You have added 10."]',0,'+7.','Rows are weeks.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0314','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Evaluate the boundary crossing: If today is January 30th, what is the date 3 days from now?','["February 2nd","January 33rd","February 3rd","February 1st"]',0,'January has 31 days.','Jan 30 + 1 = 31. +1 = Feb 1. +1 = Feb 2.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0315','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Synthesize: If the 1st of a month is a Sunday, how many Sundays will there be in that 31-day month?','["5 (1st, 8th, 15th, 22nd, 29th).","4","6","3"]',0,'Count them up.','Add 7s until you pass 31.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0316','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Critique: ''Diana says that because a month has 4 weeks, the 1st and the 28th are always on the same day of the week.''','["False, 1 + 28 = 29. The 1st and the 29th fall on the same weekday. The 28th is one day before.","True.","False, they are 2 days apart.","True, if it is February."]',0,'1 + 28 = 29.','Add multiples of 7.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0317','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Evaluate: Why do different calendars start the week on different days (Sunday vs Monday)?','["It is a cultural/regional convention; mathematically, the 7-day cycle remains identical regardless of the visual layout.","It changes the length of the week.","It makes the math harder.","It depends on the moon."]',0,'Cultural differences.','The cycle doesn''t break.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0318','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Synthesize: A project starts on the 10th and takes exactly 2 weeks and 3 days. What date does it finish (assuming a 31-day month)?','["27th","24th","30th","31st"]',0,'Convert to days first.','2 weeks is 14 days. 14 + 3 = 17 elapsed days. 10 + 17 = 27.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0319','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Analyze the layout: If you move one box down on a standard calendar, what mathematical operation have you performed on the date?','["You have added 7 (one full week).","You have added 1.","You have multiplied by 7.","You have added 10."]',0,'+7.','Rows are weeks.','2026-11-01 17:58:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0320','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Evaluate the boundary crossing: If today is January 30th, what is the date 3 days from now?','["February 2nd","January 33rd","February 3rd","February 1st"]',0,'January has 31 days.','Jan 30 + 1 = 31. +1 = Feb 1. +1 = Feb 2.','2026-11-01 17:58:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0321','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Synthesize: If the 1st of a month is a Sunday, how many Sundays will there be in that 31-day month?','["5 (1st, 8th, 15th, 22nd, 29th).","4","6","3"]',0,'Count them up.','Add 7s until you pass 31.','2026-11-01 17:58:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0322','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Critique: ''Julia says that because a month has 4 weeks, the 1st and the 28th are always on the same day of the week.''','["False, 1 + 28 = 29. The 1st and the 29th fall on the same weekday. The 28th is one day before.","True.","False, they are 2 days apart.","True, if it is February."]',0,'1 + 28 = 29.','Add multiples of 7.','2026-11-01 17:58:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0323','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Evaluate: Why do different calendars start the week on different days (Sunday vs Monday)?','["It is a cultural/regional convention; mathematically, the 7-day cycle remains identical regardless of the visual layout.","It changes the length of the week.","It makes the math harder.","It depends on the moon."]',0,'Cultural differences.','The cycle doesn''t break.','2026-11-01 17:58:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0324','Maths','Time and Calendar','Subtopic 9: Reading Calendars','Primary',10,'Synthesize: A project starts on the 10th and takes exactly 2 weeks and 3 days. What date does it finish (assuming a 31-day month)?','["27th","24th","30th","31st"]',0,'Convert to days first.','2 weeks is 14 days. 14 + 3 = 17 elapsed days. 10 + 17 = 27.','2026-11-01 17:58:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0325','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',1,'What is a ''timetable''?','["A table that shows when activities or journeys are planned to happen.","A table for eating dinner.","A math chart.","A clock."]',0,'Schedule.','It schedules things.','2026-11-01 17:58:41',NULL,NULL);
