INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0340','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',5,'If a bus leaves at 8:45 a.m. and takes 35 minutes, when does it arrive?','["9:20 a.m.","9:15 a.m.","8:80 a.m.","9:10 a.m."]',0,'Rollover the hour.','45+35=80. 80-60=20. 9:20.','2026-11-01 17:58:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0341','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',5,'Why is it important to check a.m./p.m. on a timetable?','["To avoid confusing morning and evening times (a 12-hour difference).","It isn''t.","To check the date.","To see if it is broken."]',0,'Huge difference.','Morning vs Evening.','2026-11-01 17:58:43',NULL,NULL);
