INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0349','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Analyze: Why do timetables often use the 24-hour clock?','["To eliminate any ambiguity between a.m. and p.m. (e.g., distinguishing 06:00 from 18:00 clearly).","Because 24 is better.","It saves space.","It is a secret code."]',0,'No confusion.','Clarity prevents missed trains.','2026-11-01 17:58:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0350','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Evaluate the calculation: A train departs at 17:50 and arrives at 19:15. Duration?','["1 hour 25 minutes","2 hours 35 minutes","1 hour 35 minutes","2 hours 25 minutes"]',0,'Cross the hour carefully.','17:50 to 18:00 (10m). 18:00 to 19:15 (1h 15m). Total 1h 25m.','2026-11-01 17:58:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0351','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Synthesize: You have a 45-minute meeting, a 15-minute break, and a 30-minute meeting. Total duration?','["1 hour 30 minutes","90 minutes","1 hour","2 hours"]',0,'Add them up.','45+15+30 = 90 mins.','2026-11-01 17:58:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0352','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Critique: ''If I read across a row on a bus timetable, it shows the times different buses arrive at one stop.''','["False, reading across a row usually shows the journey of ONE specific bus arriving at DIFFERENT stops sequentially.","True.","False, it shows the driver''s name.","True, buses are fast."]',0,'Follow the bus.','Rows are usually individual journeys.','2026-11-01 17:58:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0353','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Evaluate: Why must you convert units when subtracting times like 10:15 - 9:45?','["Because time uses base-60. You cannot do simple base-10 borrowing (15 - 45 requires borrowing 60 minutes from the hour, not 10).","You don''t have to.","Because 10 is bigger.","Because it''s a timetable."]',0,'Base-60 borrowing.','Borrow 60, not 10.','2026-11-01 17:58:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0354','Maths','Time and Calendar','Subtopic 10: Timetables and Schedules','Primary',10,'Synthesize: A flight leaves at 23:30 and takes 4 hours 45 mins. Arrival time?','["04:15","03:45","04:45","05:15"]',0,'Rollover midnight.','23:30 + 30m = 00:00. 4h 15m left. 04:15.','2026-11-01 17:58:44',NULL,NULL);
