INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0385','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Evaluate: Why must you check if an answer is ''reasonable'' in time word problems?','["Because it is easy to make a base-10 error (like 11:45 + 30m = 11:75). Checking ensures the answer is a valid base-60 time.","It isn''t necessary.","To practice.","To make it longer."]',0,'Is 11:75 a real time?','Sanity check.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0386','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Critique: ''To find elapsed time, just subtract the numbers like normal decimals.''','["False, time is base-60. You must borrow 60 minutes, not 10 or 100, when subtracting.","True.","False, you add.","True for digital."]',0,'Base-60.','Borrowing 1 hour = 60 minutes.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0387','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Synthesize a multi-step problem: Starts at 9:15, 45m work, 15m break, 30m work. Finish?','["10:45","10:15","11:00","9:45"]',0,'Add durations first.','Total duration = 90m (1h 30m). 9:15 + 1h 30m = 10:45.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0388','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Analyze: If a train schedule crosses from 23:45 to 00:15, what happened?','["It crossed midnight into a new calendar day.","It went backwards in time.","The train broke.","It is afternoon."]',0,'Midnight.','00:xx is the start of a new day.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0389','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Evaluate the ''inclusive counting'' problem: A festival runs from the 1st through the 5th. How many days?','["5 days (1, 2, 3, 4, 5).","4 days (5-1).","6 days.","3 days."]',0,'Count on fingers.','You must count the start and end day.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0390','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Synthesize: Flight A leaves at 13:00 and takes 2h. Flight B leaves at 14:00 and takes 1h. Which lands first?','["They land at the exact same time (15:00).","Flight A.","Flight B.","Cannot tell."]',0,'Compare.','Calculate both finish times.','2026-11-01 17:58:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t11_global_0391','Maths','Time and Calendar','Subtopic 11: Time Word Problems','Primary',10,'Evaluate: Why must you check if an answer is ''reasonable'' in time word problems?','["Because it is easy to make a base-10 error (like 11:45 + 30m = 11:75). Checking ensures the answer is a valid base-60 time.","It isn''t necessary.","To practice.","To make it longer."]',0,'Is 11:75 a real time?','Sanity check.','2026-11-01 17:58:48',NULL,NULL);
