INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0001','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',1,'What geometric term describes an exact position with no size?','["Line","Segment","Point","Ray"]',2,'Review geometric properties to find the answer.','A point marks an exact location.','2026-11-03 14:27:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0002','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',5,'Morgan draws a line segment 3 cm long. What does this length represent?','["The thickness of the line.","The fixed distance between two endpoints.","The location of a point.","The infinite path of the line."]',1,'Review geometric properties to find the answer.','A segment has a fixed, measurable length.','2026-11-03 14:27:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0003','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',10,'You are given two distinct points. How many unique straight lines can pass through BOTH points?','["0","Exactly 2","Infinite","Exactly 1"]',3,'Review geometric properties to find the answer.','Only one unique straight line can connect two specific points.','2026-11-03 14:27:44',NULL,NULL);
