INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0005','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',5,'If Alex looks at the straight edge of a book, which concept does it best model?','["Line segment","Ray","Line","Point"]',0,'Review geometric properties to find the answer.','Real-world straight edges have fixed lengths, modelling line segments.','2026-11-03 14:27:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0006','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',10,'Alex draws a line segment and extends it infinitely in both directions. What has it become?','["A line","A point","A vertex","A ray"]',0,'Review geometric properties to find the answer.','Extending a segment infinitely in both directions forms a line.','2026-11-03 14:27:45',NULL,NULL);
