INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0008','Maths','Geometry: Shapes and Properties','Subtopic 1: Points, Lines and Line Segments','Primary',5,'Spot the error: Alex says a mathematical point is a tiny circle with a radius of 16 mm. Why is this wrong?','["A point is infinitely large.","A point has no size, length, or width.","A point has infinite length.","A point must be a square."]',1,'Review geometric properties to find the answer.','A true point has zero dimensions.','2026-11-03 14:27:45',NULL,NULL);
