INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0074','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',5,'Alex looks at train tracks. What type of lines do they best represent?','["Perpendicular lines","Circles","Intersecting lines","Parallel lines"]',3,'Review geometric properties to find the answer.','These objects have straight lines that stay equally far apart.','2026-11-03 14:27:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0075','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',10,'If Line A is parallel to Line B, and Line B is parallel to Line C, what is the relationship between A and C?','["They are the exact same line.","They intersect at an acute angle.","Line A is parallel to Line C.","Line A is perpendicular to Line C."]',2,'Review geometric properties to find the answer.','Lines parallel to the same line are parallel to each other.','2026-11-03 14:27:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0076','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',1,'What type of lines meet at exactly a 90° right angle?','["Parallel lines","Curved lines","Perpendicular lines","Zigzag lines"]',2,'Review geometric properties to find the answer.','Perpendicular lines form perfect square corners (90°).','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0077','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',5,'Spot the error: Morgan says parallel lines will eventually meet if you draw them long enough. Is this true?','["True, all lines meet eventually.","True, because Earth is round.","False, they only meet at 90 degrees.","False, parallel lines never meet no matter how long they are drawn."]',3,'Review geometric properties to find the answer.','By definition, parallel lines in the same plane never intersect.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0078','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',10,'If a line crosses two parallel lines at exactly 90°, what is its relationship to the parallel lines?','["It is perpendicular to both.","It is parallel to both.","It is a ray.","It is a curve."]',0,'Review geometric properties to find the answer.','A line intersecting parallel lines at 90° is perpendicular to both.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0079','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',1,'What is the symbol for parallel lines?','["+","⊥","||","="]',2,'Review geometric properties to find the answer.','The symbol || means ''is parallel to''.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0080','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',5,'What geometric feature is formed at the corner of a rectangular window?','["An acute angle","Parallel lines","Perpendicular lines","An obtuse angle"]',2,'Review geometric properties to find the answer.','The corners of rectangles form 90° angles, making the edges perpendicular.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0081','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',10,'Which capital letter is made of exactly two perpendicular line segments?','["X","T","V","Z"]',1,'Review geometric properties to find the answer.','The letter T has a horizontal and vertical line meeting at 90°.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0082','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',1,'What do we call ANY lines that cross or meet at a point?','["Parallel lines","Straight lines","Independent lines","Intersecting lines"]',3,'Review geometric properties to find the answer.','Intersecting lines cross each other.','2026-11-03 14:27:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0083','Maths','Geometry: Shapes and Properties','Subtopic 3: Parallel and Perpendicular Lines','Primary',5,'Are all intersecting lines perpendicular?','["Yes, if they are drawn with a ruler.","Yes, they always form 90°.","No, they only need to cross, not necessarily at 90°.","No, they never cross."]',2,'Review geometric properties to find the answer.','Perpendicular lines are a special type of intersecting lines that meet exactly at 90°.','2026-11-03 14:27:52',NULL,NULL);
