INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0139','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',1,'An angle measures 126°. What type of angle is it?','["Full turn","Acute angle","Right angle","Obtuse angle"]',3,'Review geometric properties to find the answer.','Angles between 90° and 180° are obtuse.','2026-11-03 14:27:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0140','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',5,'Spot the error: Morgan says an angle of 293° is a straight angle. What is it really?','["A reflex angle","An obtuse angle","A right angle","An acute angle"]',0,'Review geometric properties to find the answer.','Angles between 180° and 360° are reflex angles.','2026-11-03 14:27:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0141','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',10,'If Morgan adds a 40° angle to a 90° angle, what type of angle is formed?','["Right angle","Obtuse angle","Straight angle","Acute angle"]',1,'Review geometric properties to find the answer.','Adding an acute angle to 90° creates an angle between 90° and 180°.','2026-11-03 14:27:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0142','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',1,'What type of angle measures exactly 180°?','["Acute angle","Straight angle","Right angle","Reflex angle"]',1,'Review geometric properties to find the answer.','A straight angle forms a straight line.','2026-11-03 14:27:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0143','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',5,'How many degrees are in a full turn (a complete circle)?','["100°","90°","180°","360°"]',3,'Review geometric properties to find the answer.','A full turn is 360°.','2026-11-03 14:27:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0144','Maths','Geometry: Shapes and Properties','Subtopic 4: Types of Angles','Primary',10,'If the hands of a clock are perfectly opposite each other (like at 6:00), what angle do they form?','["180° (Straight angle)","90° (Right angle)","45° (Acute angle)","360° (Full turn)"]',0,'Review geometric properties to find the answer.','Perfectly opposite hands form a straight line (180°).','2026-11-03 14:27:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0145','Maths','Geometry: Shapes and Properties','Subtopic 5: 2D Shapes and Their Properties','Primary',1,'What do we call a flat shape that has two dimensions (length and width)?','["2D shape","Line segment","Point","3D shape"]',0,'Review geometric properties to find the answer.','A 2D shape is flat with no thickness.','2026-11-03 14:27:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0146','Maths','Geometry: Shapes and Properties','Subtopic 5: 2D Shapes and Their Properties','Primary',5,'Riley is holding a coin. Why is this shape NOT a polygon?','["It has straight lines.","It is a 3D shape.","It has too many sides.","It has a curved boundary."]',3,'Review geometric properties to find the answer.','Polygons must have only straight sides; circles are curved.','2026-11-03 14:27:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0147','Maths','Geometry: Shapes and Properties','Subtopic 5: 2D Shapes and Their Properties','Primary',10,'If a regular polygon has 12 sides, how many vertices does it have?','["24","11","13","12"]',3,'Review geometric properties to find the answer.','In any 2D polygon, the number of sides equals the number of vertices.','2026-11-03 14:27:59',NULL,NULL);
