INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0150','Maths','Geometry: Shapes and Properties','Subtopic 5: 2D Shapes and Their Properties','Primary',10,'Spot the error: Riley says a square is a regular polygon, but a rectangle is always a regular polygon too. Why is this wrong?','["A rectangle''s sides are not all equal.","A square is not a regular polygon.","A rectangle does not have equal angles.","A rectangle is a 3D shape."]',0,'Review geometric properties to find the answer.','A regular polygon must have ALL sides equal. Most rectangles do not.','2026-11-03 14:27:59',NULL,NULL);
