INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0152','Maths','Geometry: Shapes and Properties','Subtopic 5: 2D Shapes and Their Properties','Primary',5,'Quinn draws a shape where all sides are equal and all interior angles are equal. What is this called?','["Irregular polygon","Regular polygon","Circle","Open shape"]',1,'Review geometric properties to find the answer.','A regular polygon has equal sides and equal angles.','2026-11-03 14:27:59',NULL,NULL);
