INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0186','Maths','Geometry: Shapes and Properties','Subtopic 6: Triangles and Their Types','Primary',10,'True or False: Riley can draw a triangle that is both equilateral AND right-angled.','["False, equilateral triangles only have 60° angles.","True, if the sides are long enough.","False, right triangles must have 3 unequal sides.","True, a square cut in half is an example."]',0,'Review geometric properties to find the answer.','Equilateral triangles must have 60° angles, so they cannot have a 90° angle.','2026-11-03 14:28:03',NULL,NULL);
