INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0188','Maths','Geometry: Shapes and Properties','Subtopic 6: Triangles and Their Types','Primary',5,'What do we call a triangle that has exactly one 90° angle?','["Equilateral triangle","Obtuse-angled triangle","Right-angled triangle","Acute-angled triangle"]',2,'Review geometric properties to find the answer.','A triangle with a 90° angle is right-angled.','2026-11-03 14:28:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0189','Maths','Geometry: Shapes and Properties','Subtopic 6: Triangles and Their Types','Primary',10,'If a right-angled triangle has one angle of 35°, what are its other two angles?','["90° and 45°","90° and 65°","90° and 55°","35° and 110°"]',2,'Review geometric properties to find the answer.','180 - 90 - 35 = 55°.','2026-11-03 14:28:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0190','Maths','Geometry: Shapes and Properties','Subtopic 6: Triangles and Their Types','Primary',1,'What is the sum of all three interior angles in ANY triangle?','["180°","360°","90°","100°"]',0,'Review geometric properties to find the answer.','The angles of a triangle always sum to 180°.','2026-11-03 14:28:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0191','Maths','Geometry: Shapes and Properties','Subtopic 6: Triangles and Their Types','Primary',5,'Spot the error: Jordan draws a triangle with angles of 90°, 90°, and 0°. Why is this impossible?','["It is an isosceles triangle.","The angles sum to 360°.","The third angle must be 90°.","A triangle cannot have two right angles."]',3,'Review geometric properties to find the answer.','Two 90° angles equal 180°, leaving 0° for the third angle, so the sides would never meet.','2026-11-03 14:28:03',NULL,NULL);
