INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0219','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',10,'True or False: Every square is a rectangle, but not every rectangle is a square.','["False, a square is not a rectangle.","False, they are completely unrelated.","True, a square is a special rectangle with equal sides.","True, every rectangle is a square too."]',2,'Review geometric properties to find the answer.','A square has all rectangle properties, plus equal sides.','2026-11-03 14:28:06',NULL,NULL);
