INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0236','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',5,'Which quadrilateral has EXACTLY one pair of parallel opposite sides?','["Trapezoid","Square","Rhombus","Parallelogram"]',0,'Review geometric properties to find the answer.','A trapezoid (or trapezium) has exactly one pair of parallel sides.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0237','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',10,'If Avery draws a parallelogram, what must be true about its opposite angles?','["They are exactly equal.","They add up to 90°.","They add up to 180°.","They are all 90°."]',0,'Review geometric properties to find the answer.','In a parallelogram, opposite angles are always equal.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0238','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',1,'What is the sum of all four interior angles in any quadrilateral?','["90°","360°","400°","180°"]',1,'Review geometric properties to find the answer.','The angles of a quadrilateral sum to 360°.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0239','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',5,'Spot the error: Jamie says a rhombus is exactly the same as a square. What is missing?','["A square is a 3D shape.","A rhombus has 5 sides.","A rhombus does not always have four right angles.","A rhombus has unequal sides."]',2,'Review geometric properties to find the answer.','A rhombus has equal sides but not necessarily 90° angles.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0240','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',10,'If a rhombus has four 90° angles, what other shape is it automatically?','["A square","A trapezoid","A kite","A pentagon"]',0,'Review geometric properties to find the answer.','A rhombus with 90° angles has equal sides and right angles, making it a square.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0241','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',1,'How many sides does a quadrilateral have?','["5","3","4","6"]',2,'Review geometric properties to find the answer.','Quadrilaterals are 4-sided polygons.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0242','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',5,'Alex measures three angles of a quadrilateral as 88°, 89°, and 107°. What is the fourth angle?','["76°","92°","86°","272°"]',0,'Review geometric properties to find the answer.','The sum is 360°. 360 - A - B - C = D.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0243','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',10,'True or False: Every square is a rectangle, but not every rectangle is a square.','["True, a square is a special rectangle with equal sides.","True, every rectangle is a square too.","False, a square is not a rectangle.","False, they are completely unrelated."]',0,'Review geometric properties to find the answer.','A square has all rectangle properties, plus equal sides.','2026-11-03 14:28:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0244','Maths','Geometry: Shapes and Properties','Subtopic 7: Quadrilaterals and Their Properties','Primary',1,'What do we call a quadrilateral with four equal sides and four right angles?','["Rhombus","Square","Kite","Rectangle"]',1,'Review geometric properties to find the answer.','A square has 4 equal sides and 4 right angles.','2026-11-03 14:28:08',NULL,NULL);
