INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0253','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',1,'What do we call the fixed point exactly in the middle of a circle?','["Chord","Radius","Vertex","Centre"]',3,'Review geometric properties to find the answer.','The centre is the exact middle point.','2026-11-03 14:28:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0254','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',5,'If Avery draws a circle with a radius of 4 cm, what is its diameter?','["10 cm","8 cm","16 cm","4 cm"]',1,'Review geometric properties to find the answer.','Diameter is twice the radius (d = 2r).','2026-11-03 14:28:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0255','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',10,'Which chord is the longest straight line segment that can fit inside a circle?','["The radius","The circumference","The diameter","An arc"]',2,'Review geometric properties to find the answer.','The diameter is a special chord that passes through the centre, making it the longest.','2026-11-03 14:28:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0256','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',1,'What is the distance from the centre of a circle to any point on its boundary?','["Diameter","Arc","Radius","Circumference"]',2,'Review geometric properties to find the answer.','The radius connects the centre to the edge.','2026-11-03 14:28:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0257','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',5,'A pizza has a diameter of 24 cm. What is its radius?','["6 cm","24 cm","12 cm","48 cm"]',2,'Review geometric properties to find the answer.','Radius is half the diameter (r = d/2).','2026-11-03 14:28:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0258','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',10,'Spot the error: Jamie says the circumference is exactly 2 times the diameter. What is it really?','["It is approximately 3.14 (pi) times the diameter.","It is equal to the diameter.","It is exactly half the diameter.","It is exactly 3 times the radius."]',0,'Review geometric properties to find the answer.','C = pi * d, which is roughly 3.14 times the diameter.','2026-11-03 14:28:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0259','Maths','Geometry: Shapes and Properties','Subtopic 8: Circles and Their Parts','Primary',1,'What is the distance all the way around the outside boundary of a circle?','["Diameter","Circumference","Area","Chord"]',1,'Review geometric properties to find the answer.','The circumference is the boundary length.','2026-11-03 14:28:10',NULL,NULL);
