INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0300','Maths','Geometry: Shapes and Properties','Subtopic 9: 3D Shapes and Their Properties','Primary',10,'True or False: A book is a model of a 3D shape, but a drawing of a rectangle is a 2D shape.','["True, because a book is a cylinder.","False, both are 3D.","False, both are 2D.","True, the book has thickness (height) but the drawing does not."]',3,'Review geometric properties to find the answer.','3D objects have depth/thickness; 2D shapes are purely flat.','2026-11-03 14:28:14',NULL,NULL);
