INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0327','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',10,'According to Euler''s formula (F + V = E + 2), if a shape has 6 faces and 8 vertices, how many edges does it have?','["12","10","14","16"]',0,'Review geometric properties to find the answer.','6 + 8 = 14. E + 2 = 14, so E = 12.','2026-11-03 14:28:17',NULL,NULL);
