INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0329','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',5,'How many vertices (corners) does a square-based pyramid have?','["4","8","5","6"]',2,'Review geometric properties to find the answer.','4 corners on the base + 1 apex = 5 vertices.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0330','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',10,'A mystery polyhedron has 8 faces and 6 vertices. Using Euler''s formula, how many edges does it have?','["14","10","24","12"]',3,'Review geometric properties to find the answer.','F + V = E + 2, so E = F + V - 2.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0331','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',1,'What is the geometric name for a ''corner'' where edges meet on a 3D shape?','["Face","Line","Vertex","Edge"]',2,'Review geometric properties to find the answer.','A corner is called a vertex.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0332','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',5,'A triangular prism (like a tent) has how many faces in total?','["6","5 (2 triangles, 3 rectangles)","8","4"]',1,'Review geometric properties to find the answer.','It has 2 triangular ends and 3 rectangular sides.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0333','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',10,'Spot the error: Maya says a cylinder has 2 vertices because it has a top and bottom. Why is this wrong?','["A cylinder has 0 vertices; it has no sharp corners.","A cylinder is a 2D shape.","A cylinder has 4 vertices.","Vertices are only on the bottom."]',0,'Review geometric properties to find the answer.','Vertices are sharp corners where straight edges meet. A cylinder has none.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0334','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',1,'How many faces does a cube have?','["4","6","8","12"]',1,'Review geometric properties to find the answer.','A cube has 6 square faces.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0335','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',5,'What do we call a 3D solid whose faces are ALL flat polygons?','["Cylinder","Circle","Polyhedron","Sphere"]',2,'Review geometric properties to find the answer.','A polyhedron is made entirely of flat polygon faces.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0336','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',10,'Does Euler''s formula (F + V = E + 2) work for a sphere?','["No, because a sphere has 10 vertices.","Yes, F=0, V=0, E=0.","No, because a sphere is not a polyhedron (it has curved surfaces).","Yes, it works for all 3D shapes."]',2,'Review geometric properties to find the answer.','Euler''s formula applies to convex polyhedra with flat faces and straight edges.','2026-11-03 14:28:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0337','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',1,'What is a flat surface of a solid 3D shape called?','["Edge","Face","Apex","Vertex"]',1,'Review geometric properties to find the answer.','A face is a flat surface.','2026-11-03 14:28:18',NULL,NULL);
