INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0339','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',10,'According to Euler''s formula (F + V = E + 2), if a shape has 6 faces and 8 vertices, how many edges does it have?','["14","16","12","10"]',2,'Review geometric properties to find the answer.','6 + 8 = 14. E + 2 = 14, so E = 12.','2026-11-03 14:28:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0340','Maths','Geometry: Shapes and Properties','Subtopic 10: Faces, Edges and Vertices','Primary',1,'What do we call the line segment where two faces meet on a 3D shape?','["Corner","Edge","Vertex","Face"]',1,'Review geometric properties to find the answer.','An edge is the line where faces connect.','2026-11-03 14:28:18',NULL,NULL);
