INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0361','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'What do we call a line that divides a shape into two perfectly matching mirror-image halves?','["Radius","Line of symmetry","Diagonal","Edge"]',1,'Review geometric properties to find the answer.','A line of symmetry creates mirror halves.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0362','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Rowan folds a piece of paper shaped like an equilateral triangle. How many lines of symmetry will they find?','["0","1","3","4"]',2,'Review geometric properties to find the answer.','An equilateral triangle has 3 lines of symmetry.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0363','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'If a regular polygon has 8 sides (an octagon), how many lines of symmetry does it have?','["8","0","16","4"]',0,'Review geometric properties to find the answer.','A regular polygon with n sides has n lines of symmetry.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0364','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'How many lines of symmetry does a perfect square have?','["1","0","2","4"]',3,'Review geometric properties to find the answer.','A square has 4 (vertical, horizontal, 2 diagonals).','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0365','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Look at the capital letter ''V''. What type of line symmetry does it have?','["Vertical symmetry","No symmetry","Diagonal symmetry","Horizontal symmetry"]',0,'Review geometric properties to find the answer.','These specific letters can be split down the middle vertically.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0366','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'Which of these triangles is always ASYMMETRICAL (0 lines of symmetry)?','["Right-angled isosceles triangle","Equilateral triangle","Isosceles triangle","Scalene triangle"]',3,'Review geometric properties to find the answer.','A scalene triangle has no equal sides, so it has no lines of symmetry.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0367','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'If a shape has NO lines of symmetry, what do we call it?','["Equilateral","Asymmetrical","Regular","Symmetrical"]',1,'Review geometric properties to find the answer.','Asymmetrical means no symmetry.','2026-11-03 14:28:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0368','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'How many lines of symmetry does a standard rectangle (that is NOT a square) have?','["4","0","1","2"]',3,'Review geometric properties to find the answer.','A rectangle has 2 (vertical and horizontal), but the diagonals don''t fold perfectly.','2026-11-03 14:28:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0369','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'What is ''rotational symmetry''?','["When a shape looks unchanged after being rotated less than a full turn.","When a shape has no sides.","When a shape is flipped like a mirror.","When a shape is folded in half."]',0,'Review geometric properties to find the answer.','Rotational symmetry happens when turning a shape matches its original outline.','2026-11-03 14:28:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0370','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'How many lines of symmetry does a circle have?','["1","0","Infinitely many","4"]',2,'Review geometric properties to find the answer.','Any line through the center of a circle is a line of symmetry.','2026-11-03 14:28:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0371','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Spot the error: Quinn says every straight line drawn through a shape is a line of symmetry. Why is this false?','["A line of symmetry must be curved.","Lines of symmetry must be horizontal.","The line must divide the shape into exact mirror-image halves.","Symmetry only works on circles."]',2,'Review geometric properties to find the answer.','Only lines that create perfect matching folds are lines of symmetry.','2026-11-03 14:28:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0372','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'If you fold a standard non-square rectangle along its diagonal, will the two halves match perfectly?','["No, because a rectangle has 4 lines of symmetry.","No, the corners will stick out.","Yes, but only if you fold it twice.","Yes, it is a line of symmetry."]',1,'Review geometric properties to find the answer.','The diagonal of a standard rectangle is NOT a line of symmetry.','2026-11-03 14:28:21',NULL,NULL);
