INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0381','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'What is ''rotational symmetry''?','["When a shape is folded in half.","When a shape looks unchanged after being rotated less than a full turn.","When a shape has no sides.","When a shape is flipped like a mirror."]',1,'Review geometric properties to find the answer.','Rotational symmetry happens when turning a shape matches its original outline.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0382','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'How many lines of symmetry does a circle have?','["Infinitely many","4","1","0"]',0,'Review geometric properties to find the answer.','Any line through the center of a circle is a line of symmetry.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0383','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Spot the error: Jamie says every straight line drawn through a shape is a line of symmetry. Why is this false?','["Symmetry only works on circles.","Lines of symmetry must be horizontal.","The line must divide the shape into exact mirror-image halves.","A line of symmetry must be curved."]',2,'Review geometric properties to find the answer.','Only lines that create perfect matching folds are lines of symmetry.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0384','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'If you fold a standard non-square rectangle along its diagonal, will the two halves match perfectly?','["Yes, but only if you fold it twice.","No, because a rectangle has 4 lines of symmetry.","Yes, it is a line of symmetry.","No, the corners will stick out."]',3,'Review geometric properties to find the answer.','The diagonal of a standard rectangle is NOT a line of symmetry.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0385','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'What do we call a line that divides a shape into two perfectly matching mirror-image halves?','["Radius","Diagonal","Edge","Line of symmetry"]',3,'Review geometric properties to find the answer.','A line of symmetry creates mirror halves.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0386','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Avery folds a piece of paper shaped like an equilateral triangle. How many lines of symmetry will they find?','["1","3","0","4"]',1,'Review geometric properties to find the answer.','An equilateral triangle has 3 lines of symmetry.','2026-11-03 14:28:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0387','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'If a regular polygon has 8 sides (an octagon), how many lines of symmetry does it have?','["8","0","4","16"]',0,'Review geometric properties to find the answer.','A regular polygon with n sides has n lines of symmetry.','2026-11-03 14:28:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0388','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',1,'How many lines of symmetry does a perfect square have?','["2","4","0","1"]',1,'Review geometric properties to find the answer.','A square has 4 (vertical, horizontal, 2 diagonals).','2026-11-03 14:28:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0389','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',5,'Look at the capital letter ''W''. What type of line symmetry does it have?','["Diagonal symmetry","Horizontal symmetry","Vertical symmetry","No symmetry"]',2,'Review geometric properties to find the answer.','These specific letters can be split down the middle vertically.','2026-11-03 14:28:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0390','Maths','Geometry: Shapes and Properties','Subtopic 11: Symmetry and Lines of Symmetry','Primary',10,'Which of these triangles is always ASYMMETRICAL (0 lines of symmetry)?','["Right-angled isosceles triangle","Isosceles triangle","Equilateral triangle","Scalene triangle"]',3,'Review geometric properties to find the answer.','A scalene triangle has no equal sides, so it has no lines of symmetry.','2026-11-03 14:28:23',NULL,NULL);
