INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0429','Maths','Geometry: Shapes and Properties','Subtopic 12: Tessellations and Shape Patterns','Primary',10,'Why can''t regular pentagons tessellate? (Their interior angles are 108°)','["They add up to exactly 360°.","108° does not divide evenly into 360°, so they leave a gap.","They are not polygons.","They have too many sides."]',1,'Review geometric properties to find the answer.','Three pentagons = 324° (leaves a gap). Four = 432° (overlap).','2026-11-03 14:28:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0430','Maths','Geometry: Shapes and Properties','Subtopic 12: Tessellations and Shape Patterns','Primary',1,'Which of these shapes CANNOT tessellate a flat surface by itself because it leaves gaps?','["Regular Hexagon","Rectangle","Square","Circle"]',3,'Review geometric properties to find the answer.','Circles leave curved gaps between them.','2026-11-03 14:28:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0431','Maths','Geometry: Shapes and Properties','Subtopic 12: Tessellations and Shape Patterns','Primary',5,'If a shape pattern goes: Triangle, Square, Triangle, Square... what is the repeating unit?','["Triangle, Square","Just Square","Just Triangle","Square, Triangle"]',0,'Review geometric properties to find the answer.','The smallest repeating block is Triangle then Square.','2026-11-03 14:28:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t9_global_0432','Maths','Geometry: Shapes and Properties','Subtopic 12: Tessellations and Shape Patterns','Primary',10,'If a pattern involves ''reflection'', what happens to the shape?','["It gets larger.","It is flipped like a mirror image.","It just slides over.","It is spun around a point."]',1,'Review geometric properties to find the answer.','Reflection creates a mirrored copy of the shape.','2026-11-03 14:28:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0001','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',1,'What does length tell us about an object?','["How much liquid it holds.","How long it is from one end to the other.","How heavy it is.","How hot it is."]',1,'Review measurement and unit properties to find the answer.','Length measures size from end to end.','2026-11-03 15:23:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0002','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',5,'Sam is measuring a desk. Which unit is the most reasonable?','["Grams","Metres","Millimetres","Kilometres"]',1,'Review measurement and unit properties to find the answer.','Metres are suitable for furniture-sized objects.','2026-11-03 15:23:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0003','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',10,'Sam walks 680 m to the park, and then 340 m to the store. What is the total distance in metres?','["680 m","3400 m","340 m","1020 m"]',3,'Review measurement and unit properties to find the answer.','680 + 340 = 1020 m.','2026-11-03 15:23:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0004','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',1,'Which unit is best for measuring the length of a pencil?','["Litre (L)","Kilogram (kg)","Kilometre (km)","Centimetre (cm)"]',3,'Review measurement and unit properties to find the answer.','Centimetres are best for small objects.','2026-11-03 15:23:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0005','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',5,'If a book is 51 cm long and a pen is 15 cm long, how much longer is the book?','["765 cm","66 cm","51 cm","36 cm"]',3,'Review measurement and unit properties to find the answer.','51 - 15 = 36.','2026-11-03 15:23:39',NULL,NULL);
