INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0007','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',1,'How many centimetres (cm) are in 1 metre (m)?','["50","100","1,000","10"]',1,'Review measurement and unit properties to find the answer.','1 metre equals 100 centimetres.','2026-11-03 15:23:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0008','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',5,'Spot the error: Casey starts measuring a pencil at the 2 cm mark and it ends at 10 cm. Casey says it is 10 cm long.','["Rulers only measure from 0.","It is actually 12 cm long.","The pencil is too short.","It is actually 8 cm long (10 - 2)."]',3,'Review measurement and unit properties to find the answer.','You must subtract the starting point (10 - 2 = 8).','2026-11-03 15:23:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0009','Maths','Measurement and Units','Subtopic 1: Length and Distance','Primary',10,'True or False: We should write ''67 cms'' for plural centimetres.','["False, unit symbols do not take an ''s''.","True, grammar rules apply.","True, if it is more than 1 cm.","False, it should be ''cmeters''."]',0,'Review measurement and unit properties to find the answer.','Unit symbols are never pluralized with an ''s''.','2026-11-03 15:23:40',NULL,NULL);
