INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0039','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'Rowan has two bags of beans. One is 7000 g and the other is 7 kg. Which is heavier?','["Cannot be determined.","The 7000 g bag.","The 7 kg bag.","They are exactly the same."]',3,'Review measurement and unit properties to find the answer.','7 kg = 7000 g.','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0040','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'Which unit is best for measuring the mass of an apple?','["Gram (g)","Litre (L)","Kilogram (kg)","Metre (m)"]',0,'Review measurement and unit properties to find the answer.','Grams are best for small, light objects.','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0041','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',5,'If Skyler travels to the Moon, what happens to their mass?','["It decreases because of gravity.","It becomes zero.","It doubles.","It remains exactly the same."]',3,'Review measurement and unit properties to find the answer.','Mass is the amount of matter, which doesn''t change with location. (Weight changes).','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0042','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'Spot the error: A scientist says ''My suitcase weighs 20 kg.'' Why is this technically incorrect in physics?','["Kilograms measure mass, not weight.","Suitcases are measured in tonnes.","20 kg is too light.","The correct unit is grams."]',0,'Review measurement and unit properties to find the answer.','Weight is a force (Newtons), while kilograms measure mass.','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0043','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'How many grams (g) are in 1 kilogram (kg)?','["10","1,000","10,000","100"]',1,'Review measurement and unit properties to find the answer.','1 kilogram equals 1,000 grams.','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0044','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',5,'What scientific unit is used to measure ''weight'' (the force of gravity)?','["Tonnes (t)","Grams (g)","Kilograms (kg)","Newtons (N)"]',3,'Review measurement and unit properties to find the answer.','Weight is a force measured in newtons.','2026-11-03 15:23:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0045','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'If a medicine pill contains 500 mg of a vitamin, what does ''mg'' stand for?','["Microgram","Metre-gram","Megagram","Milligram"]',3,'Review measurement and unit properties to find the answer.','mg stands for milligram, which is 1/1,000 of a gram.','2026-11-03 15:23:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0046','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'Which tool is commonly used to measure the mass of cooking ingredients?','["Stopwatch","Thermometer","Ruler","Digital kitchen scale"]',3,'Review measurement and unit properties to find the answer.','A scale measures mass.','2026-11-03 15:23:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0047','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',5,'Which unit would you use to measure the mass of a heavy truck?','["Kilogram (kg)","Tonne (t)","Milligram (mg)","Gram (g)"]',1,'Review measurement and unit properties to find the answer.','Tonnes are used for massive objects (1 t = 1,000 kg).','2026-11-03 15:23:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0048','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'If Quinn combines a 3 kg block and a 4 kg block on a balance scale against a 7 kg block, what will happen?','["The left side will go down.","The scale will balance perfectly.","The right side will go down.","The scale will break."]',1,'Review measurement and unit properties to find the answer.','3 + 4 = 7, so they are equal.','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0049','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'What does ''mass'' measure?','["How much liquid it holds.","How much matter an object contains.","How hot an object is.","How long an object is."]',1,'Review measurement and unit properties to find the answer.','Mass is the amount of matter in an object.','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0050','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',5,'Rowan has a bag of sand with a mass of 7 kg. Another bag is 10 kg. What is the difference in mass?','["17 kg","1 kg","7 kg","3 kg"]',3,'Review measurement and unit properties to find the answer.','(10) - 7 = 3 kg.','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0051','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'Rowan has two bags of sand. One is 7000 g and the other is 7 kg. Which is heavier?','["They are exactly the same.","Cannot be determined.","The 7 kg bag.","The 7000 g bag."]',0,'Review measurement and unit properties to find the answer.','7 kg = 7000 g.','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0052','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'Which unit is best for measuring the mass of an apple?','["Gram (g)","Litre (L)","Metre (m)","Kilogram (kg)"]',0,'Review measurement and unit properties to find the answer.','Grams are best for small, light objects.','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0053','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',5,'If Sam travels to the Moon, what happens to their mass?','["It remains exactly the same.","It becomes zero.","It doubles.","It decreases because of gravity."]',0,'Review measurement and unit properties to find the answer.','Mass is the amount of matter, which doesn''t change with location. (Weight changes).','2026-11-03 15:23:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0054','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',10,'Spot the error: A scientist says ''My suitcase weighs 20 kg.'' Why is this technically incorrect in physics?','["Suitcases are measured in tonnes.","20 kg is too light.","Kilograms measure mass, not weight.","The correct unit is grams."]',2,'Review measurement and unit properties to find the answer.','Weight is a force (Newtons), while kilograms measure mass.','2026-11-03 15:23:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0055','Maths','Measurement and Units','Subtopic 2: Mass and Weight in Everyday Contexts','Primary',1,'How many grams (g) are in 1 kilogram (kg)?','["10","10,000","100","1,000"]',3,'Review measurement and unit properties to find the answer.','1 kilogram equals 1,000 grams.','2026-11-03 15:23:49',NULL,NULL);
