INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0073','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',1,'To change a larger metric unit (like metres) into a smaller one (like centimetres), what math operation do you use?','["Divide","Add","Subtract","Multiply"]',3,'Review measurement and unit properties to find the answer.','Larger to smaller requires multiplication (e.g., 2m * 100 = 200cm).','2026-11-03 15:23:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0074','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',5,'To convert 8000 millilitres (mL) back into Litres (L), what should you do?','["Multiply by 100","Multiply by 1,000","Divide by 100","Divide by 1,000"]',3,'Review measurement and unit properties to find the answer.','Smaller to larger unit means divide by 1,000.','2026-11-03 15:23:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0075','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'Convert 8 kilometres into centimetres (Hint: two steps!).','["800000 cm","8000 cm","80000 cm","800 cm"]',0,'Review measurement and unit properties to find the answer.','8 km * 1000 = 8000 m. 8000 m * 100 = 800000 cm.','2026-11-03 15:23:54',NULL,NULL);
