INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0078','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'A journey takes 2 hours and 30 minutes. How many total minutes is this?','["150 minutes","90 minutes","130 minutes","230 minutes"]',0,'Review measurement and unit properties to find the answer.','2 * 60 = 120. 120 + 30 = 150.','2026-11-03 15:23:56',NULL,NULL);
