INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0097','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',1,'To change a larger metric unit (like metres) into a smaller one (like centimetres), what math operation do you use?','["Multiply","Subtract","Divide","Add"]',0,'Review measurement and unit properties to find the answer.','Larger to smaller requires multiplication (e.g., 2m * 100 = 200cm).','2026-11-03 15:24:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0098','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',5,'To convert 5000 millilitres (mL) back into Litres (L), what should you do?','["Multiply by 1,000","Multiply by 100","Divide by 1,000","Divide by 100"]',2,'Review measurement and unit properties to find the answer.','Smaller to larger unit means divide by 1,000.','2026-11-03 15:24:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0099','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'Convert 5 kilometres into centimetres (Hint: two steps!).','["5000 cm","500000 cm","50000 cm","500 cm"]',1,'Review measurement and unit properties to find the answer.','5 km * 1000 = 5000 m. 5000 m * 100 = 500000 cm.','2026-11-03 15:24:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0100','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',1,'How many centimetres are in 8 metres?','["8000 cm","80 cm","800 cm","80 cm"]',2,'Review measurement and unit properties to find the answer.','8 * 100 = 800 cm.','2026-11-03 15:24:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0101','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',5,'Convert 8 minutes into seconds.','["480 s","800 s","28800 s","192 s"]',0,'Review measurement and unit properties to find the answer.','8 * 60 = 480 seconds.','2026-11-03 15:24:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0102','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'A journey takes 2 hours and 40 minutes. How many total minutes is this?','["240 minutes","140 minutes","160 minutes","100 minutes"]',2,'Review measurement and unit properties to find the answer.','2 * 60 = 120. 120 + 40 = 160.','2026-11-03 15:24:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0103','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',1,'How many grams are in 2 kilograms?','["2000 g","2 g","20 g","200 g"]',0,'Review measurement and unit properties to find the answer.','2 * 1000 = 2000 g.','2026-11-03 15:24:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0104','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',5,'Convert 200 centimetres into metres.','["2000 m","0.2 m","20 m","2 m"]',1,'Review measurement and unit properties to find the answer.','200 / 100 = 2 m.','2026-11-03 15:24:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0105','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'Which of these is exactly equal to 1.75 Litres?','["1,750 mL","175 mL","17.5 mL","17,500 mL"]',0,'Review measurement and unit properties to find the answer.','1.75 * 1000 = 1750 mL.','2026-11-03 15:24:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0106','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',1,'How many minutes are in 1 hour?','["24","60","3600","100"]',1,'Review measurement and unit properties to find the answer.','There are 60 minutes in an hour.','2026-11-03 15:24:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0107','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',5,'Spot the error: A student converts 3 hours into minutes by calculating 3 × 100. What did they do wrong?','["They should multiply by 24.","They should divide by 60.","They should multiply by 60.","They should divide by 100."]',2,'Review measurement and unit properties to find the answer.','Time doesn''t use base-100; there are 60 mins in an hour.','2026-11-03 15:24:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0108','Maths','Measurement and Units','Subtopic 5: Converting Measurement Units','Primary',10,'Convert 3 days into hours.','["21 hours","36 hours","72 hours","180 hours"]',2,'Review measurement and unit properties to find the answer.','3 * 24 = 72 hours.','2026-11-03 15:24:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0109','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',1,'What does ''perimeter'' measure?','["The flat surface inside a shape.","The total distance around the outside of a shape.","The weight of a shape.","How much liquid fits inside."]',1,'Review measurement and unit properties to find the answer.','Perimeter is the outside boundary length.','2026-11-03 15:24:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0110','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',5,'A rectangular garden is 14 m long and 4 m wide. What is its perimeter?','["36 m","18 m","72 m","56 m"]',0,'Review measurement and unit properties to find the answer.','P = 2 * (14 + 4) = 36 m.','2026-11-03 15:24:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0111','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',10,'A rectangle has a perimeter of 36 cm. If its length is 14 cm, what is its width?','["4 cm","14 cm","8 cm","18 cm"]',0,'Review measurement and unit properties to find the answer.','36 / 2 = 18. 18 - 14 = 4.','2026-11-03 15:24:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0112','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',1,'If a square has a side length of 8 cm, what is its perimeter?','["64 cm","16 cm","32 cm","12 cm"]',2,'Review measurement and unit properties to find the answer.','A square has 4 equal sides: 4 * 8 = 32.','2026-11-03 15:24:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0113','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',5,'A triangle has sides of 8 cm, 9 cm, and 10 cm. What is its perimeter?','["11 cm","64 cm","27 cm","24 cm"]',2,'Review measurement and unit properties to find the answer.','8 + 9 + 10 = 27.','2026-11-03 15:24:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0114','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',10,'Spot the error: A student writes the perimeter of a 5m by 3m rug as 15 m². What is wrong?','["The math is correct but the unit is wrong.","Perimeter should be measured in m, not m², and the math is wrong (it''s 16 m).","Perimeter is in m³, not m².","They forgot to divide by 2."]',1,'Review measurement and unit properties to find the answer.','They calculated area (5*3=15) and used area units (m²). Perimeter is 16 m.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0115','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',1,'How do you find the perimeter of ANY flat polygon?','["Add the lengths of all its sides together.","Multiply the length by the width.","Divide the area by 2.","Count the number of corners."]',0,'Review measurement and unit properties to find the answer.','Perimeter is the sum of all side lengths.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0116','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',5,'If a square has a total perimeter of 20 m, how long is ONE of its sides?','["10 m","5 m","25 m","20 m"]',1,'Review measurement and unit properties to find the answer.','20 / 4 = 5.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0117','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',10,'A regular pentagon has a perimeter of 60 cm. What is the length of one side?','["12 cm","72 cm","60 cm","48 cm"]',0,'Review measurement and unit properties to find the answer.','A regular pentagon has 5 equal sides. Divide perimeter by 5.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0118','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',1,'Which unit is suitable for measuring perimeter?','["Litres (L)","Square metres (m²)","Centimetres (cm)","Grams (g)"]',2,'Review measurement and unit properties to find the answer.','Perimeter is a length, measured in standard linear units.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0119','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',5,'True or False: The formula P = 2 × (Length + Width) works for all rectangles.','["False, it only works for squares.","True, but only if the sides are odd numbers.","False, you must multiply all 4 sides.","True, because opposite sides of a rectangle are equal."]',3,'Review measurement and unit properties to find the answer.','A rectangle has 2 equal lengths and 2 equal widths.','2026-11-03 15:24:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0120','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',10,'If you combine two identical squares (each with 5cm sides) side-by-side to make a rectangle, what is the new perimeter?','["30 cm","25 cm","20 cm","40 cm"]',0,'Review measurement and unit properties to find the answer.','The new shape is 10cm by 5cm. P = 2*(10+5) = 30cm. (Two internal sides disappear).','2026-11-03 15:24:06',NULL,NULL);
