INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0144','Maths','Measurement and Units','Subtopic 6: Perimeter','Primary',10,'If you combine two identical squares (each with 5cm sides) side-by-side to make a rectangle, what is the new perimeter?','["40 cm","25 cm","30 cm","20 cm"]',2,'Review measurement and unit properties to find the answer.','The new shape is 10cm by 5cm. P = 2*(10+5) = 30cm. (Two internal sides disappear).','2026-11-03 15:24:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0145','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',1,'What does ''area'' measure?','["The distance around the boundary.","The volume of a 3D box.","How heavy the shape is.","The amount of flat surface covered inside a shape."]',3,'Review measurement and unit properties to find the answer.','Area measures 2D interior space.','2026-11-03 15:24:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0146','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',5,'A classroom floor is 8 m long and 2 m wide. What is its area?','["20 m²","16 m²","10 m²","16 m"]',1,'Review measurement and unit properties to find the answer.','A = 8 * 2 = 16 m².','2026-11-03 15:24:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0147','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',10,'A square has an area of 64 m². What is its perimeter?','["64 m","32 m","16 m","64 m"]',1,'Review measurement and unit properties to find the answer.','Side = 8 (since 8*8=64). Perimeter = 4 * 8 = 32.','2026-11-03 15:24:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0148','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',1,'What kind of units are used to measure area?','["Linear units (like cm or m)","Square units (like cm² or m²)","Cubic units (like cm³)","Volume units (like Litres)"]',1,'Review measurement and unit properties to find the answer.','Area is strictly 2D, measured in square units.','2026-11-03 15:24:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0149','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',5,'A rectangle has an area of 28 cm² and a width of 4 cm. What is its length?','["14 cm","7 cm","11 cm","28 cm"]',1,'Review measurement and unit properties to find the answer.','Length = Area / Width. 28 / 4 = 7.','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0150','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',10,'If you double the length and double the width of a rectangle, what happens to its area?','["It becomes 8 times larger.","It becomes 4 times larger.","It doubles.","It stays the same."]',1,'Review measurement and unit properties to find the answer.','(2L) * (2W) = 4 * (L*W).','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0151','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',1,'What is the formula for the area of a rectangle?','["Area = Length ÷ Width","Area = Length × Width","Area = 2 × (Length + Width)","Area = Length + Width"]',1,'Review measurement and unit properties to find the answer.','Multiply the two dimensions to find the area.','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0152','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',5,'Spot the error: A student says a 4m by 5m garden has an area of 18 m². What did they do?','["They multiplied incorrectly.","They added an extra zero.","They calculated perimeter instead of area.","They divided instead of multiplying."]',2,'Review measurement and unit properties to find the answer.','They calculated P = 2*(4+5) = 18. Area should be 4*5 = 20.','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0153','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',10,'Which of these is NOT a correct unit for area?','["Square millimetres (mm²)","Centimetres (cm)","Square kilometres (km²)","Square metres (m²)"]',1,'Review measurement and unit properties to find the answer.','Plain centimetres measure length, not area.','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0154','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',1,'If a square has a side length of 5 m, what is its area?','["20 m²","25 m²","10 m²","10 m²"]',1,'Review measurement and unit properties to find the answer.','Area of a square = side × side. 5 * 5 = 25.','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0155','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',5,'If a square picture has sides of 10 cm, what is its area?','["100 cm²","40 cm²","100 cm","20 cm²"]',0,'Review measurement and unit properties to find the answer.','10 * 10 = 100 cm².','2026-11-03 15:24:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0156','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',10,'A wall is 8 m wide and 5 m high. A can of paint covers 10 m². How many full cans are needed to paint it completely?','["5 cans","6 cans","1 can","4 cans"]',0,'Review measurement and unit properties to find the answer.','Area = 40. Divide by 10 and round up for full cans.','2026-11-03 15:24:14',NULL,NULL);
