INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0163','Maths','Measurement and Units','Subtopic 7: Area of Squares and Rectangles','Primary',1,'What is the formula for the area of a rectangle?','["Area = 2 × (Length + Width)","Area = Length × Width","Area = Length ÷ Width","Area = Length + Width"]',1,'Review measurement and unit properties to find the answer.','Multiply the two dimensions to find the area.','2026-11-03 15:24:15',NULL,NULL);
