INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0181','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What does ''volume'' measure?','["How heavy an object is.","The flat surface of a shape.","The amount of 3D space an object occupies.","The distance around a shape."]',2,'Review measurement and unit properties to find the answer.','Volume is the 3D space inside an object.','2026-11-03 15:24:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0182','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'A box is 5 cm long, 4 cm wide, and 4 cm high. What is its volume?','["160 cm³","20 cm³","13 cm³","80 cm³"]',3,'Review measurement and unit properties to find the answer.','V = 5 * 4 * 4 = 80 cm³.','2026-11-03 15:24:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0183','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'A cuboid has a volume of 80 cm³. If its length is 5 cm and width is 4 cm, what is its height?','["9 cm","20 cm","4 cm","8 cm"]',2,'Review measurement and unit properties to find the answer.','V = L*W*H. 80 / (5*4) = 4.','2026-11-03 15:24:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0184','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What units are used to measure volume of a solid object?','["Square units (like cm²)","Linear units (like cm)","Cubic units (like cm³ or m³)","Grams (g)"]',2,'Review measurement and unit properties to find the answer.','Volume uses 3 dimensions, so it uses cubic units.','2026-11-03 15:24:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0185','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'What is the difference between ''Volume'' and ''Capacity''?','["Volume is measured in Litres, capacity in cm³.","Volume is for liquids, capacity is for solids.","Volume is space occupied; Capacity is how much liquid a container holds.","They are exactly the same thing."]',2,'Review measurement and unit properties to find the answer.','Capacity specifically refers to holding potential (often liquids).','2026-11-03 15:24:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0186','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'If 1 cubic centimetre (cm³) is exactly equal to 1 millilitre (mL), what is the capacity of a 500 cm³ container?','["50 mL","0.5 mL","500 mL","5 Litres"]',2,'Review measurement and unit properties to find the answer.','Since 1 cm³ = 1 mL, 500 cm³ = 500 mL.','2026-11-03 15:24:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0187','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What is the formula for the volume of a cuboid (a rectangular box)?','["Length + Width + Height","2 × (Length + Width)","Length × Width","Length × Width × Height"]',2,'Review measurement and unit properties to find the answer.','Multiply all three dimensions to find volume.','2026-11-03 15:24:20',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0188','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'If Reese fills a box with 45 identical 1 cm cubes, what is the volume of the box?','["15 cm³","1 cm³","45 cm³","11 cm³"]',2,'Review measurement and unit properties to find the answer.','Counting 1cm cubes directly gives the volume in cm³.','2026-11-03 15:24:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0189','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'If you double the height of a box but keep the length and width the same, what happens to its volume?','["It doubles.","It stays the same.","It halves.","It becomes 4 times larger."]',0,'Review measurement and unit properties to find the answer.','V = L*W*(2H) = 2*(L*W*H).','2026-11-03 15:24:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0190','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What is a ''unit cube''?','["A 2D shape.","A box that holds water.","A flat square on paper.","A cube with sides of 1 unit, used to measure volume."]',3,'Review measurement and unit properties to find the answer.','Unit cubes represent 1 cubic unit of volume.','2026-11-03 15:24:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0191','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'Spot the error: A student writes the volume of a block as ''24 cm²''. What is wrong?','["They forgot to add the sides.","They should have used Litres.","Volume must be in cubic units (cm³), not square units (cm²).","The number is wrong."]',2,'Review measurement and unit properties to find the answer.','cm² is for area; cm³ is for volume.','2026-11-03 15:24:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0192','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'How many Litres are in 1 cubic metre (1 m³)?','["1,000 L","10 L","100 L","10,000 L"]',0,'Review measurement and unit properties to find the answer.','A cube 1m x 1m x 1m holds exactly 1,000 Litres of water.','2026-11-03 15:24:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0193','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What does ''volume'' measure?','["The flat surface of a shape.","The amount of 3D space an object occupies.","How heavy an object is.","The distance around a shape."]',1,'Review measurement and unit properties to find the answer.','Volume is the 3D space inside an object.','2026-11-03 15:24:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0194','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'A box is 3 cm long, 5 cm wide, and 4 cm high. What is its volume?','["12 cm³","15 cm³","60 cm³","120 cm³"]',2,'Review measurement and unit properties to find the answer.','V = 3 * 5 * 4 = 60 cm³.','2026-11-03 15:24:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0195','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'A cuboid has a volume of 60 cm³. If its length is 3 cm and width is 5 cm, what is its height?','["15 cm","4 cm","8 cm","8 cm"]',1,'Review measurement and unit properties to find the answer.','V = L*W*H. 60 / (3*5) = 4.','2026-11-03 15:24:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0196','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What units are used to measure volume of a solid object?','["Grams (g)","Linear units (like cm)","Square units (like cm²)","Cubic units (like cm³ or m³)"]',3,'Review measurement and unit properties to find the answer.','Volume uses 3 dimensions, so it uses cubic units.','2026-11-03 15:24:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0197','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'What is the difference between ''Volume'' and ''Capacity''?','["They are exactly the same thing.","Volume is measured in Litres, capacity in cm³.","Volume is space occupied; Capacity is how much liquid a container holds.","Volume is for liquids, capacity is for solids."]',2,'Review measurement and unit properties to find the answer.','Capacity specifically refers to holding potential (often liquids).','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0198','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'If 1 cubic centimetre (cm³) is exactly equal to 1 millilitre (mL), what is the capacity of a 500 cm³ container?','["5 Litres","50 mL","500 mL","0.5 mL"]',2,'Review measurement and unit properties to find the answer.','Since 1 cm³ = 1 mL, 500 cm³ = 500 mL.','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0199','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What is the formula for the volume of a cuboid (a rectangular box)?','["Length + Width + Height","2 × (Length + Width)","Length × Width","Length × Width × Height"]',2,'Review measurement and unit properties to find the answer.','Multiply all three dimensions to find volume.','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0200','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'If Reese fills a box with 48 identical 1 cm cubes, what is the volume of the box?','["11 cm³","48 cm³","12 cm³","1 cm³"]',1,'Review measurement and unit properties to find the answer.','Counting 1cm cubes directly gives the volume in cm³.','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0201','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'If you double the height of a box but keep the length and width the same, what happens to its volume?','["It halves.","It becomes 4 times larger.","It stays the same.","It doubles."]',3,'Review measurement and unit properties to find the answer.','V = L*W*(2H) = 2*(L*W*H).','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0202','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What is a ''unit cube''?','["A cube with sides of 1 unit, used to measure volume.","A box that holds water.","A 2D shape.","A flat square on paper."]',0,'Review measurement and unit properties to find the answer.','Unit cubes represent 1 cubic unit of volume.','2026-11-03 15:24:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0203','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'Spot the error: A student writes the volume of a block as ''24 cm²''. What is wrong?','["The number is wrong.","They should have used Litres.","They forgot to add the sides.","Volume must be in cubic units (cm³), not square units (cm²)."]',3,'Review measurement and unit properties to find the answer.','cm² is for area; cm³ is for volume.','2026-11-03 15:24:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0204','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'How many Litres are in 1 cubic metre (1 m³)?','["10,000 L","100 L","1,000 L","10 L"]',2,'Review measurement and unit properties to find the answer.','A cube 1m x 1m x 1m holds exactly 1,000 Litres of water.','2026-11-03 15:24:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0205','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',1,'What does ''volume'' measure?','["The distance around a shape.","How heavy an object is.","The flat surface of a shape.","The amount of 3D space an object occupies."]',3,'Review measurement and unit properties to find the answer.','Volume is the 3D space inside an object.','2026-11-03 15:24:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0206','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',5,'A box is 6 cm long, 4 cm wide, and 2 cm high. What is its volume?','["48 cm³","96 cm³","24 cm³","12 cm³"]',0,'Review measurement and unit properties to find the answer.','V = 6 * 4 * 2 = 48 cm³.','2026-11-03 15:24:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0207','Maths','Measurement and Units','Subtopic 8: Volume — Introductory','Primary',10,'A cuboid has a volume of 48 cm³. If its length is 6 cm and width is 4 cm, what is its height?','["24 cm","10 cm","4 cm","2 cm"]',3,'Review measurement and unit properties to find the answer.','V = L*W*H. 48 / (6*4) = 2.','2026-11-03 15:24:24',NULL,NULL);
