INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0217','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',1,'What does it mean to ''estimate'' a measurement?','["Make a sensible, educated guess before measuring.","Ask someone else.","Use a calculator.","Use a ruler to get the exact number."]',0,'Review measurement and unit properties to find the answer.','Estimation is a reasonable guess based on known references.','2026-11-03 15:24:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0218','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',5,'Sam wants to measure the width of a large classroom. Which tool is best?','["Thermometer","15 cm Ruler","Measuring wheel","Measuring tape"]',3,'Review measurement and unit properties to find the answer.','A measuring tape is flexible and long enough for rooms.','2026-11-03 15:24:27',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0219','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',10,'Which tool would be best to measure the exact volume of 25 mL of a chemical in a science lab?','["Kitchen scale","Measuring cylinder","Ruler","Measuring jug"]',1,'Review measurement and unit properties to find the answer.','A measuring cylinder offers precise liquid volume readings.','2026-11-03 15:24:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0220','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',1,'Which tool is best for measuring a short, straight line?','["Thermometer","Weighing scale","Measuring tape","Ruler"]',3,'Review measurement and unit properties to find the answer.','A ruler is ideal for short, straight lengths on paper.','2026-11-03 15:24:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0221','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',5,'What do you call the curved surface of a liquid when reading a measuring jug?','["The capacity curve","The meniscus","The apex","The volume line"]',1,'Review measurement and unit properties to find the answer.','You read the bottom of the meniscus for clear liquids.','2026-11-03 15:24:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0222','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',10,'If you want to measure the distance of a curved running track, which tool is most practical?','["Ruler","Stopwatch","Measuring wheel","Set square"]',2,'Review measurement and unit properties to find the answer.','A measuring wheel rolls along the ground to measure long/curved distances.','2026-11-03 15:24:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0223','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',1,'Which tool would you use to measure the mass of a bag of apples?','["Weighing scale","Ruler","Measuring jug","Stopwatch"]',0,'Review measurement and unit properties to find the answer.','Scales measure mass/weight.','2026-11-03 15:24:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0224','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',5,'Skyler estimates a book is 20 cm long. It actually measures 23 cm. What is the difference?','["20 cm","23 cm","3 cm","43 cm"]',1,'Review measurement and unit properties to find the answer.','23 - 20 = 3 cm.','2026-11-03 15:24:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0225','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',10,'Spot the error: Skyler uses a thermometer to see how much a pot of water weighs. What''s wrong?','["A thermometer measures temperature, not mass.","Water has no mass.","They should use a stopwatch.","A thermometer measures capacity."]',0,'Review measurement and unit properties to find the answer.','Thermometers track heat (°C), scales track mass (kg/g).','2026-11-03 15:24:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0226','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',1,'What does a stopwatch measure?','["Temperature","Elapsed time (seconds/minutes)","Liquid volume","Distance"]',1,'Review measurement and unit properties to find the answer.','Stopwatches track time durations.','2026-11-03 15:24:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0227','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',5,'When using a ruler, where should you align the start of the object?','["At the zero (0) mark.","In the middle.","At the physical edge of the plastic.","At the 1 cm mark."]',0,'Review measurement and unit properties to find the answer.','Always start at the 0 line, not the physical edge of the tool.','2026-11-03 15:24:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0228','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',10,'Why is it important to estimate before taking an exact measurement?','["It means you don''t have to use a tool.","It gives you the exact answer faster.","It makes the ruler more accurate.","It helps you check if your final measurement is reasonable and avoids big mistakes."]',3,'Review measurement and unit properties to find the answer.','Estimates act as a reality check for your final math/reading.','2026-11-03 15:24:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0229','Maths','Measurement and Units','Subtopic 9: Estimation and Measurement Tools','Primary',1,'What does it mean to ''estimate'' a measurement?','["Use a calculator.","Ask someone else.","Make a sensible, educated guess before measuring.","Use a ruler to get the exact number."]',2,'Review measurement and unit properties to find the answer.','Estimation is a reasonable guess based on known references.','2026-11-03 15:24:30',NULL,NULL);
