INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0288','Maths','Measurement and Units','Subtopic 10: Choosing Suitable Units','Primary',10,'Which two units represent the exact same amount of liquid?','["10,000 mL and 1 L","10 mL and 1 L","100 mL and 1 L","1,000 mL and 1 L"]',3,'Review measurement and unit properties to find the answer.','1 Litre is defined as 1,000 millilitres.','2026-11-03 15:24:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0289','Maths','Measurement and Units','Subtopic 11: Measurement Word Problems','Primary',1,'A rope is 40 cm long. Quinn cuts off 5 cm. How long is the rope now?','["5 cm","45 cm","35 cm","200 cm"]',0,'Review measurement and unit properties to find the answer.','40 - 5 = 35.','2026-11-03 15:24:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0290','Maths','Measurement and Units','Subtopic 11: Measurement Word Problems','Primary',5,'A plank is 2 m long. Quinn saws off 40 cm. What must Quinn do FIRST before subtracting?','["Change cm into Litres.","Convert 2 m into 200 cm.","Add the numbers together.","Nothing, just subtract 2 - 50."]',1,'Review measurement and unit properties to find the answer.','You must convert to matching units before adding or subtracting.','2026-11-03 15:24:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t10_global_0291','Maths','Measurement and Units','Subtopic 11: Measurement Word Problems','Primary',10,'A lesson starts at 10:45 a.m. and lasts 40 minutes. What time does it finish?','["It ends at 10:95 a.m.","Multiply the minutes.","Subtract the minutes.","Calculate by counting forward over the hour boundary."]',3,'Review measurement and unit properties to find the answer.','You must roll over the hour if minutes exceed 60.','2026-11-03 15:24:44',NULL,NULL);
