INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0038','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Convert 1615 cents into a decimal dollar amount.','["$31.00","$1615.00","$0.1615","$16.15"]',3,'Review Money and Financial Mathematics to find the answer.','Divide by 100: 1615 cents = $16.15.','2026-11-03 15:29:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0039','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'If Jordan has £16.15 and their friend has £15.65, what is the exact difference in pence?','["15 pence","0 pence","50 pence","1600 pence"]',1,'Review Money and Financial Mathematics to find the answer.','£16.15 is 1615p. The friend has 1565p. Difference is 50 = 50p.','2026-11-03 15:29:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0040','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'How many cents make up 1 Euro?','["1000","10","50","100"]',0,'Review Money and Financial Mathematics to find the answer.','1 Euro = 100 cents.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0041','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Spot the error: Jordan writes 19 dollars and 5 cents as $19.5. Why is this confusing?','["It should be written as 5 dollars.","It is missing a comma.","It looks like 19 dollars and 50 cents. It should be written as $19.05.","The decimal is in the wrong place for euros."]',2,'Review Money and Financial Mathematics to find the answer.','In decimal money notation, a single digit after the decimal usually implies tens of cents.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0042','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Why is it incorrect to compare $19.50 directly to €19.50 by just saying ''they are equal''?','["They are actually mathematically identical in purchasing power.","Because they are different currencies and their exchange rates (actual values) differ.","Because 50 cents in Euros is larger than 50 cents in Dollars.","Because the symbols are written on different sides."]',1,'Review Money and Financial Mathematics to find the answer.','Different currencies cannot be compared solely by their numerical face value.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0043','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'How would you write 9 dollars and 50 cents using a decimal point?','["$950","$9.05","$0.95","$9.50"]',3,'Review Money and Financial Mathematics to find the answer.','The decimal separates the major unit (dollars) from the minor unit (cents).','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0044','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Which amount is strictly greater: $9.87 or $9.08?','["$9.08","Cannot be determined","They are equal","$9.87"]',3,'Review Money and Financial Mathematics to find the answer.','87 cents is greater than 8 cents.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0045','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'A shop sells a toy for 987 paise. Write this price correctly in Rupees using decimal notation.','["₹9.87","₹96","₹0.987","₹987.00"]',0,'Review Money and Financial Mathematics to find the answer.','987 divided by 100 is 9.87.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0046','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'Convert 7 dollars entirely into cents.','["70 cents","7 cents","700 cents","7000 cents"]',2,'Review Money and Financial Mathematics to find the answer.','Multiply by 100: 7 * 100 = 700 cents.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0047','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Riley has ₹7.48 (Rupees). What does this mean in words?','["7 rupees and 48 paise","7 rupees","7 paise and 48 rupees","748 rupees"]',0,'Review Money and Financial Mathematics to find the answer.','The digits before the decimal are Rupees, the digits after are Paise.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0048','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Convert a total of 7 dollars, 48 dimes (10 cents each), and 5 pennies (1 cent each) into decimal format.','["$11.85","$7.485","$55.05","$7.53"]',0,'Review Money and Financial Mathematics to find the answer.','Total cents = 485. Adding 7 dollars gives the total.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0049','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'What does the decimal point do in monetary notation (like $4.50)?','["It multiplies the number by 10.","It means the money is a coin.","It shows the end of the number.","It separates the major units from the minor units."]',3,'Review Money and Financial Mathematics to find the answer.','The decimal separates dollars and cents.','2026-11-03 15:29:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0050','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Convert 430 pence into British Pounds (£).','["£0.043","£4.30","£430","£43"]',1,'Review Money and Financial Mathematics to find the answer.','430 divided by 100 is 4.30.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0051','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Which set of values is arranged in DESCENDING (largest to smallest) order?','["$0.45, $4.05, $4.50","$4.05, $4.50, $0.45","$4.50, $0.45, $4.05","$4.50, $4.05, $0.45"]',3,'Review Money and Financial Mathematics to find the answer.','4.50 is largest, then 4.05, then 0.45.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0052','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'If Mia has 200 pence, how many British Pounds (£) is that?','["£20","£0.20","£2","£200"]',0,'Review Money and Financial Mathematics to find the answer.','200 divided by 100 equals 2 pounds.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0053','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'What is the total minor unit value of €4.09?','["409 cents","13 cents","4009 cents","49 cents"]',0,'Review Money and Financial Mathematics to find the answer.','4 euros = 400 cents, plus 9 cents.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0054','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'If a digital payment system asks for an amount strictly in minor units, how would you input £4.09?','["49","409","49","4.09"]',1,'Review Money and Financial Mathematics to find the answer.','£4 is 400p. Plus 9p = 409.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0055','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'In the US Dollar currency system, what is the minor unit called?','["Rupee","Pound","Cent","Penny"]',2,'Review Money and Financial Mathematics to find the answer.','A cent is the minor unit of a dollar.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0056','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Convert 2088 cents into a decimal dollar amount.','["$2088.00","$0.2088","$20.88","$108.00"]',2,'Review Money and Financial Mathematics to find the answer.','Divide by 100: 2088 cents = $20.88.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0057','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'If Casey has £20.88 and their friend has £19.138, what is the exact difference in pence?','["0 pence","2000 pence","88 pence","50 pence"]',0,'Review Money and Financial Mathematics to find the answer.','£20.88 is 2088p. The friend has 2038p. Difference is 50 = 50p.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0058','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'How many cents make up 1 Euro?','["10","100","50","1000"]',0,'Review Money and Financial Mathematics to find the answer.','1 Euro = 100 cents.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0059','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Spot the error: Ava writes 15 dollars and 5 cents as $15.5. Why is this confusing?','["It is missing a comma.","It should be written as 5 dollars.","The decimal is in the wrong place for euros.","It looks like 15 dollars and 50 cents. It should be written as $15.05."]',3,'Review Money and Financial Mathematics to find the answer.','In decimal money notation, a single digit after the decimal usually implies tens of cents.','2026-11-03 15:29:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0060','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Why is it incorrect to compare $15.50 directly to €15.50 by just saying ''they are equal''?','["Because 50 cents in Euros is larger than 50 cents in Dollars.","They are actually mathematically identical in purchasing power.","Because they are different currencies and their exchange rates (actual values) differ.","Because the symbols are written on different sides."]',2,'Review Money and Financial Mathematics to find the answer.','Different currencies cannot be compared solely by their numerical face value.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0061','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'How would you write 8 dollars and 50 cents using a decimal point?','["$850","$8.05","$8.50","$0.85"]',2,'Review Money and Financial Mathematics to find the answer.','The decimal separates the major unit (dollars) from the minor unit (cents).','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0062','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Which amount is strictly greater: $8.83 or $8.08?','["$8.83","They are equal","Cannot be determined","$8.08"]',0,'Review Money and Financial Mathematics to find the answer.','83 cents is greater than 8 cents.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0063','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'A shop sells a toy for 883 paise. Write this price correctly in Rupees using decimal notation.','["₹0.883","₹91","₹8.83","₹883.00"]',2,'Review Money and Financial Mathematics to find the answer.','883 divided by 100 is 8.83.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0064','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'Convert 5 dollars entirely into cents.','["50 cents","5 cents","5000 cents","500 cents"]',3,'Review Money and Financial Mathematics to find the answer.','Multiply by 100: 5 * 100 = 500 cents.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0065','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Riley has ₹5.21 (Rupees). What does this mean in words?','["5 rupees and 21 paise","521 rupees","5 rupees","5 paise and 21 rupees"]',0,'Review Money and Financial Mathematics to find the answer.','The digits before the decimal are Rupees, the digits after are Paise.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0066','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Convert a total of 5 dollars, 21 dimes (10 cents each), and 5 pennies (1 cent each) into decimal format.','["$26.05","$5.215","$7.15","$5.26"]',2,'Review Money and Financial Mathematics to find the answer.','Total cents = 215. Adding 5 dollars gives the total.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0067','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'What does the decimal point do in monetary notation (like $4.50)?','["It means the money is a coin.","It multiplies the number by 10.","It shows the end of the number.","It separates the major units from the minor units."]',3,'Review Money and Financial Mathematics to find the answer.','The decimal separates dollars and cents.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0068','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'Convert 630 pence into British Pounds (£).','["£6.30","£630","£63","£0.063"]',0,'Review Money and Financial Mathematics to find the answer.','630 divided by 100 is 6.30.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0069','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'Which set of values is arranged in DESCENDING (largest to smallest) order?','["$0.45, $4.05, $4.50","$4.05, $4.50, $0.45","$4.50, $4.05, $0.45","$4.50, $0.45, $4.05"]',2,'Review Money and Financial Mathematics to find the answer.','4.50 is largest, then 4.05, then 0.45.','2026-11-03 15:29:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0070','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',1,'If Noah has 200 pence, how many British Pounds (£) is that?','["£0.20","£20","£200","£2"]',1,'Review Money and Financial Mathematics to find the answer.','200 divided by 100 equals 2 pounds.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0071','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',5,'What is the total minor unit value of €8.02?','["82 cents","10 cents","8002 cents","802 cents"]',3,'Review Money and Financial Mathematics to find the answer.','8 euros = 800 cents, plus 2 cents.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0072','Maths','Money and Financial Mathematics','Subtopic 2: Understanding Monetary Values','Primary',10,'If a digital payment system asks for an amount strictly in minor units, how would you input £8.02?','["82","82","802","8.02"]',2,'Review Money and Financial Mathematics to find the answer.','£8 is 800p. Plus 2p = 802.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0073','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Jordan has 3 coins, and each is worth 10 units. What is their total value?','["10 units","30 units","3 units","13 units"]',1,'Review Money and Financial Mathematics to find the answer.','Multiply the number of coins by their value: 3 x 10 = 30.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0074','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'A collection contains 3 notes of 10 units and 2 notes of 5 units. What is the total value?','["75 units","40 units","10 units","30 units"]',1,'Review Money and Financial Mathematics to find the answer.','(3 x 10) + (2 x 5) = 40.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0075','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Jordan empties a piggy bank containing 3 quarters (25 cents), 2 dimes (10 cents), and 5 nickels (5 cents). What is the total value in dollars?','["$1.00","$0.85","$10.00","$1.20"]',3,'Review Money and Financial Mathematics to find the answer.','(3*25) + (2*10) + (5*5) = 120 cents. Convert to dollars.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0076','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'If you have 7 banknotes worth 20 units each, how do you find the total quickly?','["Multiply the number of notes by their value.","Subtract the value from the number of notes.","Count the physical notes only.","Add the number of notes to the value."]',0,'Review Money and Financial Mathematics to find the answer.','Multiplication is faster than repeated addition.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0077','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Noah has 4 $2 coins and 7 50-cent coins. What is the total value in dollars?','["$11.50","$8.50","$27.50","$15"]',0,'Review Money and Financial Mathematics to find the answer.','Dollars: 4 x 2 = 8. Cents: 7 x 50 = 350 cents. Total = 11.5.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0078','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'You need exactly $120. Which combination of bills gives exactly this amount?','["10 five-dollar bills.","10 ten-dollar bills and 1 20-dollar bill/coin.","11 ten-dollar bills.","1 ten-dollar bill and 20 one-dollar coins."]',1,'Review Money and Financial Mathematics to find the answer.','10x10 = 100. Plus 20 = 120.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0079','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Count the total: Two 10-unit coins and one 1-unit coin.','["11 units","3 units","20 units","21 units"]',3,'Review Money and Financial Mathematics to find the answer.','(2 x 10) + 1 = 21.','2026-11-03 15:29:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0080','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Spot the error: A child has 6 coins worth 5 units each and says ''I have 6 units of money.'' What did they do wrong?','["They are perfectly correct.","They forgot to divide by 5.","They counted the number of physical coins instead of their monetary value.","They should have subtracted the coins."]',2,'Review Money and Financial Mathematics to find the answer.','The value is Quantity x Denomination, not just the physical count of objects.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0081','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'A cash register holds 6 twenty-euro notes and 6 fifty-euro notes. What is the total amount?','["€420","€12","€4200","€420"]',0,'Review Money and Financial Mathematics to find the answer.','(6 * 20) + (6 * 50) = 420.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0082','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'What is the total value of 4 notes worth 10 units each?','["14 units","40 units","4 units","10 units"]',1,'Review Money and Financial Mathematics to find the answer.','4 x 10 = 40.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0083','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'If Noah needs exactly 25 units and only has 5-unit coins, how many coins do they need?','["10 coins","5 coins","2 coins","5 coins"]',1,'Review Money and Financial Mathematics to find the answer.','25 divided by 5 equals 5.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0084','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Which collection of money has the HIGHEST total value?','["Fourteen $10 notes","Three $50 notes","One-hundred $1 coins","Seven $20 notes"]',1,'Review Money and Financial Mathematics to find the answer.','3*50=150. 7*20=140. 14*10=140. 100*1=100. 150 is the highest.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0085','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'When counting mixed money, what is a good strategy to avoid mistakes?','["Count the biggest physical coins first, regardless of value.","Group matching denominations together before counting.","Only count the notes.","Mix them all up in a bag."]',1,'Review Money and Financial Mathematics to find the answer.','Grouping similar coins/notes makes counting easier and more accurate.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0086','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Count the money: 8 ten-dollar notes, 3 five-dollar notes, and 3 one-dollar coins.','["$113","$14","$98","$95"]',2,'Review Money and Financial Mathematics to find the answer.','(8x10) + (3x5) + 3 = 98.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0087','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Sam has £8.50 in 50p coins. How many 50p coins does Sam have?','["58 coins","17 coins","8 coins","16 coins"]',1,'Review Money and Financial Mathematics to find the answer.','There are two 50p coins in every £1. So 8 * 2 = 16, plus 1 for the extra 50p.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0088','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Sam has a 50-unit note and a 20-unit note. What is the total?','["100 units","520 units","30 units","70 units"]',3,'Review Money and Financial Mathematics to find the answer.','50 + 20 = 70.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0089','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Which is the QUICKEST way to count 16 identical coins worth 1 units each?','["Subtract the value from the total.","Add 2 to the coins.","Multiply 16 by 1.","Count them one by one."]',2,'Review Money and Financial Mathematics to find the answer.','Multiplication is much faster than repeated addition.','2026-11-03 15:29:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0090','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'A vending machine only accepts exact change. An item costs $5.75. Which coin combination works?','["One $5 coin and three 20-cent coins.","One $5 coin, one 50-cent coin, one 20-cent coin, and one 5-cent coin.","Two $5 coins and one 50-cent coin.","One $5 coin, one 50-cent coin, and one 10-cent coin."]',1,'Review Money and Financial Mathematics to find the answer.','50 + 20 + 5 = 75 cents. Plus the $5 coin equals $5.75.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0091','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Sam has 3 coins, and each is worth 10 units. What is their total value?','["10 units","3 units","13 units","30 units"]',3,'Review Money and Financial Mathematics to find the answer.','Multiply the number of coins by their value: 3 x 10 = 30.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0092','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'A collection contains 3 notes of 10 units and 3 notes of 5 units. What is the total value?','["30 units","15 units","45 units","90 units"]',2,'Review Money and Financial Mathematics to find the answer.','(3 x 10) + (3 x 5) = 45.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0093','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Sam empties a piggy bank containing 3 quarters (25 cents), 3 dimes (10 cents), and 5 nickels (5 cents). What is the total value in dollars?','["$1.10","$1.30","$11.00","$1.10"]',1,'Review Money and Financial Mathematics to find the answer.','(3*25) + (3*10) + (5*5) = 130 cents. Convert to dollars.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0094','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'If you have 3 banknotes worth 50 units each, how do you find the total quickly?','["Count the physical notes only.","Subtract the value from the number of notes.","Add the number of notes to the value.","Multiply the number of notes by their value."]',3,'Review Money and Financial Mathematics to find the answer.','Multiplication is faster than repeated addition.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0095','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Ava has 4 $2 coins and 3 50-cent coins. What is the total value in dollars?','["$8.50","$17.50","$9.50","$11"]',2,'Review Money and Financial Mathematics to find the answer.','Dollars: 4 x 2 = 8. Cents: 3 x 50 = 150 cents. Total = 9.5.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0096','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'You need exactly $150. Which combination of bills gives exactly this amount?','["10 five-dollar bills.","10 ten-dollar bills and 1 50-dollar bill/coin.","1 ten-dollar bill and 50 one-dollar coins.","11 ten-dollar bills."]',1,'Review Money and Financial Mathematics to find the answer.','10x10 = 100. Plus 50 = 150.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0097','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Count the total: Two 5-unit coins and one 50-unit coin.','["500 units","60 units","3 units","55 units"]',1,'Review Money and Financial Mathematics to find the answer.','(2 x 5) + 50 = 60.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0098','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Spot the error: A child has 8 coins worth 5 units each and says ''I have 8 units of money.'' What did they do wrong?','["They should have subtracted the coins.","They are perfectly correct.","They forgot to divide by 5.","They counted the number of physical coins instead of their monetary value."]',3,'Review Money and Financial Mathematics to find the answer.','The value is Quantity x Denomination, not just the physical count of objects.','2026-11-03 15:29:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0099','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'A cash register holds 8 twenty-euro notes and 5 fifty-euro notes. What is the total amount?','["€13","€500","€410","€4100"]',2,'Review Money and Financial Mathematics to find the answer.','(8 * 20) + (5 * 50) = 410.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0100','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'What is the total value of 5 notes worth 10 units each?','["15 units","5 units","10 units","50 units"]',3,'Review Money and Financial Mathematics to find the answer.','5 x 10 = 50.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0101','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'If Chen needs exactly 25 units and only has 5-unit coins, how many coins do they need?','["5 coins","5 coins","10 coins","2 coins"]',0,'Review Money and Financial Mathematics to find the answer.','25 divided by 5 equals 5.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0102','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Which collection of money has the HIGHEST total value?','["One-hundred $1 coins","Fourteen $10 notes","Seven $20 notes","Three $50 notes"]',3,'Review Money and Financial Mathematics to find the answer.','3*50=150. 7*20=140. 14*10=140. 100*1=100. 150 is the highest.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0103','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'When counting mixed money, what is a good strategy to avoid mistakes?','["Count the biggest physical coins first, regardless of value.","Only count the notes.","Group matching denominations together before counting.","Mix them all up in a bag."]',2,'Review Money and Financial Mathematics to find the answer.','Grouping similar coins/notes makes counting easier and more accurate.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0104','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Count the money: 7 ten-dollar notes, 7 five-dollar notes, and 3 one-dollar coins.','["$143","$17","$108","$105"]',2,'Review Money and Financial Mathematics to find the answer.','(7x10) + (7x5) + 3 = 108.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0105','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'Charlie has £7.50 in 50p coins. How many 50p coins does Charlie have?','["57 coins","7 coins","14 coins","15 coins"]',3,'Review Money and Financial Mathematics to find the answer.','There are two 50p coins in every £1. So 7 * 2 = 14, plus 1 for the extra 50p.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0106','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',1,'Ava has a 50-unit note and a 20-unit note. What is the total?','["100 units","520 units","30 units","70 units"]',3,'Review Money and Financial Mathematics to find the answer.','50 + 20 = 70.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0107','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',5,'Which is the QUICKEST way to count 16 identical coins worth 50 units each?','["Subtract the value from the total.","Add 2 to the coins.","Multiply 16 by 50.","Count them one by one."]',2,'Review Money and Financial Mathematics to find the answer.','Multiplication is much faster than repeated addition.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0108','Maths','Money and Financial Mathematics','Subtopic 3: Counting Money','Primary',10,'A vending machine only accepts exact change. An item costs $5.75. Which coin combination works?','["One $5 coin and three 20-cent coins.","One $5 coin, one 50-cent coin, and one 10-cent coin.","Two $5 coins and one 50-cent coin.","One $5 coin, one 50-cent coin, one 20-cent coin, and one 5-cent coin."]',3,'Review Money and Financial Mathematics to find the answer.','50 + 20 + 5 = 75 cents. Plus the $5 coin equals $5.75.','2026-11-03 15:29:54',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0109','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'Ava has 33 units and a friend has 6 units. Who has MORE money?','["Ava","The friend","Cannot be determined","They have the same amount"]',0,'Review Money and Financial Mathematics to find the answer.','Since 33 is greater than 6, Ava has more.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0110','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',5,'Ava has 33 units and Sam has 6 units. How much MORE money does Ava have?','["6 units","39 units","33 units","27 units"]',3,'Review Money and Financial Mathematics to find the answer.','Difference = 33 - 6 = 27.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0111','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',10,'Child A has two $20 notes and one $5 note. Child B has four $10 notes and two $2 coins. Who has more?','["Child A ($45) has more than Child B ($44).","Child B has more.","Child A has $25.","They have the exact same amount."]',0,'Review Money and Financial Mathematics to find the answer.','A = 40+5=45. B = 40+4=44. 45 > 44.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0112','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'What does the mathematical symbol ''>'' mean?','["Less than","Greater than","Minus","Equal to"]',1,'Review Money and Financial Mathematics to find the answer.','The open side of ''>'' faces the larger number.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0113','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',5,'Group A has three 10-unit coins. Group B has one 32-unit note. Which group has a higher total value?','["Group A (30 units) vs Group B (32 units). Group A is greater if 32 < 30.","They are always equal.","Coins are always worth less.","Group B is always greater because it''s a note."]',0,'Review Money and Financial Mathematics to find the answer.','You must calculate Group A (3*10=30) and compare it to Group B.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0114','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',10,'Why is it mathematically incorrect to say that 10 US Dollars > 10 Indian Rupees based strictly on the number 10?','["The numbers are equal (10=10), but the currencies have totally different exchange values and purchasing power.","Because Rupees are only coins.","Because Dollars don''t use decimals.","Because 10 Rupees is a larger number."]',0,'Review Money and Financial Mathematics to find the answer.','You cannot compare different currencies without an exchange rate.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0115','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'What does the mathematical symbol ''<'' mean?','["Plus","Equal to","Greater than","Less than"]',3,'Review Money and Financial Mathematics to find the answer.','The pointy end of ''<'' points to the smaller number.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0116','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',5,'Compare these amounts in the same currency: $4.37 ___ $4.18','[">","=","+","<"]',0,'Review Money and Financial Mathematics to find the answer.','Since 37 > 18, the correct symbol is >.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0117','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',10,'Fill in the correct inequality: £37.18 ___ £36.99','[">","=","<","+"]',0,'Review Money and Financial Mathematics to find the answer.','£37 is a whole pound greater than £36, regardless of the pence.','2026-11-03 15:29:55',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0118','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'Which amount is greater: 26 units or 13 units?','["13 units","26 units","They are equal","Neither"]',1,'Review Money and Financial Mathematics to find the answer.','26 is a larger number than 13.','2026-11-03 15:29:55',NULL,NULL);
