INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0120','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',10,'Charlie has ₹26.50. They want to buy a snack that costs ₹26.85. How much are they short?','["85 paise (₹0.85)","50 paise (₹0.50)","15 paise (₹0.15)","35 paise (₹0.35)"]',3,'Review Money and Financial Mathematics to find the answer.','85 - 50 = 35 paise.','2026-11-03 15:29:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0121','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'If a book costs 45 units and a toy costs 45 units, which symbol compares their prices?','["+","<","=",">"]',2,'Review Money and Financial Mathematics to find the answer.','They are exactly the same, so use ''=''.','2026-11-03 15:29:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0122','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',5,'Spot the error: A student compares $2.5 and $2.05 and says they are equal. Why is this wrong?','["They are different currencies.","$2.5 means 50 cents, which is greater than 5 cents ($2.05).","$2.5 is not a real number.","$2.05 is actually 50 cents."]',1,'Review Money and Financial Mathematics to find the answer.','In money, $2.5 is read as $2.50.','2026-11-03 15:29:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0123','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',10,'Which set of monetary values is ordered from LEAST to GREATEST?','["$0.50, $0.05, $5.00, $5.05","$0.05, $0.50, $5.00, $5.05","$5.05, $5.00, $0.50, $0.05","$5.00, $5.05, $0.05, $0.50"]',1,'Review Money and Financial Mathematics to find the answer.','0.05 < 0.50 < 5.00 < 5.05.','2026-11-03 15:29:56',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0124','Maths','Money and Financial Mathematics','Subtopic 4: Comparing Amounts','Primary',1,'To find out how much MORE money Casey has than their friend (42 vs 11), what math operation should you use?','["Multiplication","Subtraction","Addition","Division"]',1,'Review Money and Financial Mathematics to find the answer.','Subtract the smaller amount from the larger amount to find the difference.','2026-11-03 15:29:56',NULL,NULL);
