INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0150','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',10,'An item costs $30.75. Sam pays with a $50.00 note. What is the change?','["$20.25","$20.75","$19.25","$30.25"]',2,'Review Money and Financial Mathematics to find the answer.','50.00 - 30.75 = 19.25.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0151','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',1,'Ava has 20 units and buys a toy for 8 units. What operation finds the money left over?','["Subtraction","Division","Addition","Multiplication"]',0,'Review Money and Financial Mathematics to find the answer.','Spending money requires subtracting it from your total.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0152','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',5,'You have $5.00 and spend $8.50. How much is left?','["$8.50","$-3.00","$-3.50","$-4.50"]',3,'Review Money and Financial Mathematics to find the answer.','5.00 - 8.50 = -4.50.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0153','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',10,'Spot the error: A student adds $3.50 and $1.60 and gets $4.10. What did they do wrong?','["They added too many cents.","The total is $4.00.","They should have subtracted.","They forgot to carry over the extra dollar. 50c + 60c = $1.10. The total is $5.10."]',3,'Review Money and Financial Mathematics to find the answer.','3.50 + 1.60 = 5.10.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0154','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',1,'Charlie has 12 units and buys a toy for 2 units. How much money remains?','["14 units","12 units","2 units","10 units"]',3,'Review Money and Financial Mathematics to find the answer.','12 - 2 = 10.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0155','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',5,'When adding amounts like $4.35 and $2.10, what must you line up perfectly?','["The last digits, ignoring the decimal.","The largest numbers.","The dollar signs.","The decimal points."]',3,'Review Money and Financial Mathematics to find the answer.','Aligning the decimal point ensures dollars add to dollars and cents to cents.','2026-11-03 15:29:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0156','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',10,'Charlie saves $1.25 a week. How much will they have saved after 8 weeks?','["$9.25","$20.00","$10.00","$8.25"]',2,'Review Money and Financial Mathematics to find the answer.','1.25 * 8 = 10.0.','2026-11-03 15:30:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0157','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',1,'If Charlie starts with 5 units and receives 13 more units, how much do they have in total?','["18 units","8 units","13 units","5 units"]',0,'Review Money and Financial Mathematics to find the answer.','Receiving money adds to the total.','2026-11-03 15:30:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0158','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',5,'Spot the error: Charlie subtracts $2.50 from $10.00 and says the answer is $8.50. What went wrong?','["They should have added the numbers.","The answer is actually $8.00.","They subtracted the dollars correctly (10-2=8) but forgot to subtract the 50 cents from the whole dollar. The answer is $7.50.","They forgot the dollar sign."]',2,'Review Money and Financial Mathematics to find the answer.','10.00 - 2.50 = 7.50.','2026-11-03 15:30:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0159','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',10,'A group of 5 friends order a meal for $65.00. They want to split the cost equally. How much does each pay?','["$5.00","$13.00","$18.00","$65.00"]',1,'Review Money and Financial Mathematics to find the answer.','65 / 5 = 13.','2026-11-03 15:30:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0160','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',1,'What does it mean to find the ''difference'' between two prices?','["Multiply the prices.","Subtract the smaller price from the larger price.","Add the two prices together.","Divide the prices."]',1,'Review Money and Financial Mathematics to find the answer.','Difference always implies subtraction.','2026-11-03 15:30:00',NULL,NULL);
