INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0162','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',10,'Taylor starts with $10.00, spends $6.25, and then finds a $5 note. What is the final total?','["$9.25","$4.75","$15.25","$8.75"]',3,'Review Money and Financial Mathematics to find the answer.','10.00 - 6.25 + 5.00 = 3.75 + 5.00.','2026-11-03 15:30:00',NULL,NULL);
