INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0164','Maths','Money and Financial Mathematics','Subtopic 5: Adding and Subtracting Money','Primary',5,'Charlie has 42 units. They spend 29 units on food and 3 units on a drink. How much remains?','["13 units","32 units","10 units","39 units"]',2,'Review Money and Financial Mathematics to find the answer.','Total spent = 32. Remaining = 42 - 32 = 10.','2026-11-03 15:30:00',NULL,NULL);
