INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0181','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'What is ''change'' in shopping?','["The money returned to you when you pay more than the item costs.","The money you owe the shop.","The tax added to the item.","The exact price of the item."]',0,'Review Money and Financial Mathematics to find the answer.','Change is the difference returned to the customer.','2026-11-03 15:30:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0182','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'Ben buys a sandwich for $4.50 and pays with a $10.00 note. How much change is due?','["$5.50","$5.00","$6.50","$4.50"]',0,'Review Money and Financial Mathematics to find the answer.','10.00 - 4.50 = 5.50.','2026-11-03 15:30:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0183','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Ben buys 3 items that cost $32.00 each. They pay with a $100.00 note. How much change do they receive?','["$14.00","$96.00","$4.00","$68.00"]',2,'Review Money and Financial Mathematics to find the answer.','Total cost = 3 * 32 = 96. Change = 100 - 96.','2026-11-03 15:30:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0184','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'An item costs 18 units. You hand the cashier 28 units. What math operation finds the change?','["Multiplication","Division","Subtraction","Addition"]',2,'Review Money and Financial Mathematics to find the answer.','Amount Paid - Cost = Change.','2026-11-03 15:30:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0185','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'The change due is 18 units. Which combination of coins/notes could make this exact amount?','["Notes/coins that add up to exactly 18.","Notes/coins that add up to 23.","Notes/coins that add up to 36.","Notes/coins that add up to 16."]',0,'Review Money and Financial Mathematics to find the answer.','The combination must sum to 18.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0186','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'A customer''s bill is $13.75. They hand the cashier a $20 note. The cashier gives them back a $5 note, a $1 coin, and a 25-cent coin. Is this correct?','["No, they gave too much change.","No, they are short 50 cents.","Yes, but they should have used all coins.","Yes, $5 + $1 + $0.25 = $6.25, which is the exact change."]',3,'Review Money and Financial Mathematics to find the answer.','20.00 - 13.75 = 6.25.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0187','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'An item costs 26 units. You hand the cashier a 36-unit note. How much change do you get?','["26 units","36 units","10 units","62 units"]',2,'Review Money and Financial Mathematics to find the answer.','36 - 26 = 10.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0188','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'What is the ''counting up'' method for finding change?','["Counting all the coins in your wallet.","Counting backwards from 100.","Counting forward from the item''s price up to the amount paid.","Adding the prices of everything in the shop."]',2,'Review Money and Financial Mathematics to find the answer.','Counting up bridges the gap between cost and amount paid.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0189','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Spot the error: A book costs $26. The customer gives $31. The cashier gives $2 change. How do you mathematically prove it''s wrong?','["The cashier should have added the numbers.","$26 (cost) + $2 (change) = $28. This does not equal the $31 paid.","The customer paid too much.","The change should be in coins."]',1,'Review Money and Financial Mathematics to find the answer.','Cost + Change must equal Amount Paid.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0190','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'How can you easily check if the cashier gave you the correct change?','["Multiply the change by 2.","Subtract the change from the cost.","Count the change twice.","Add the cost of the item and the change together; it should equal what you paid."]',3,'Review Money and Financial Mathematics to find the answer.','Cost + Change = Amount Paid.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0191','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'An item costs 30 units. Charlie receives 5 units in change. How much did Charlie originally hand to the cashier?','["35 units","5 units","30 units","65 units"]',0,'Review Money and Financial Mathematics to find the answer.','Cost + Change = Amount Paid. 30 + 5 = 35.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0192','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Charlie buys a toy for $8.40. They want to get exactly one $2 coin back in change. How much money should they hand the cashier?','["$10.00","$6.40","$10.40","$8.40"]',2,'Review Money and Financial Mathematics to find the answer.','Cost + Desired Change = 8.40 + 2.00 = 10.40.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0193','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'If a book costs 10 units and Noah gives the cashier a 20-unit note, what is the change?','["5 units","30 units","20 units","10 units"]',3,'Review Money and Financial Mathematics to find the answer.','20 - 10 = 10.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0194','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'If Noah buys a toy for $30.25 and pays with a $20.00 bill, what is the change?','["$-10.75","$30.75","$-10.25","$-11.75"]',3,'Review Money and Financial Mathematics to find the answer.','20.00 - 30.25 = -11.75.','2026-11-03 15:30:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0195','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'The total cost is $21.30. The customer hands the cashier a $50 note AND a 50-cent coin, saying ''This will make the change easier.'' What change will the cashier give back?','["$30.20","$29.50","$29.20","$28.70"]',2,'Review Money and Financial Mathematics to find the answer.','Amount paid = 50.50. Cost = 21.30. Change = 50.50 - 21.30 = 29.20.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0196','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'If you pay the EXACT amount an item costs, how much change do you receive?','["1 unit","0 units","The full amount","Half the amount"]',1,'Review Money and Financial Mathematics to find the answer.','Exact payment means no change is due.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0197','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'Spot the error: The cost is $3.40. Sam pays $5.00. The cashier counts up: ''3.40 plus 60 cents is 4.00, plus $1 is 5.00. Here is $1.40.'' What is wrong?','["Nothing is wrong; the counting up method is perfectly correct and gives $1.60.","The cashier should have added the totals.","The cashier gave 20 cents too little.","The cashier gave $2.60."]',0,'Review Money and Financial Mathematics to find the answer.','3.40 + 0.60 = 4.00; + 1.00 = 5.00. Change is $1.60. (Wait, the prompt said ''Here is $1.40''. So the error is math: 60c + $1 = $1.60).','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0198','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'If Sam buys a uniform for $22.15 and pays with $27.00, what is the most efficient combination of change (fewest coins/notes)?','["Give back only notes.","Depends on the exact change of $4.85, using the largest denominations first.","Always use only 1-cent coins.","Rounding the change to the nearest dollar."]',1,'Review Money and Financial Mathematics to find the answer.','The fewest coins/notes rule uses the largest possible denominations first.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0199','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'What is ''change'' in shopping?','["The exact price of the item.","The money returned to you when you pay more than the item costs.","The tax added to the item.","The money you owe the shop."]',1,'Review Money and Financial Mathematics to find the answer.','Change is the difference returned to the customer.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0200','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'Taylor buys a sandwich for $4.50 and pays with a $10.00 note. How much change is due?','["$5.00","$4.50","$5.50","$6.50"]',2,'Review Money and Financial Mathematics to find the answer.','10.00 - 4.50 = 5.50.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0201','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Taylor buys 3 items that cost $18.00 each. They pay with a $100.00 note. How much change do they receive?','["$82.00","$54.00","$56.00","$46.00"]',3,'Review Money and Financial Mathematics to find the answer.','Total cost = 3 * 18 = 54. Change = 100 - 54.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0202','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'An item costs 29 units. You hand the cashier 49 units. What math operation finds the change?','["Addition","Division","Subtraction","Multiplication"]',2,'Review Money and Financial Mathematics to find the answer.','Amount Paid - Cost = Change.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0203','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'The change due is 29 units. Which combination of coins/notes could make this exact amount?','["Notes/coins that add up to exactly 29.","Notes/coins that add up to 34.","Notes/coins that add up to 58.","Notes/coins that add up to 27."]',0,'Review Money and Financial Mathematics to find the answer.','The combination must sum to 29.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0204','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'A customer''s bill is $13.75. They hand the cashier a $20 note. The cashier gives them back a $5 note, a $1 coin, and a 25-cent coin. Is this correct?','["No, they are short 50 cents.","No, they gave too much change.","Yes, $5 + $1 + $0.25 = $6.25, which is the exact change.","Yes, but they should have used all coins."]',2,'Review Money and Financial Mathematics to find the answer.','20.00 - 13.75 = 6.25.','2026-11-03 15:30:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0205','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'An item costs 35 units. You hand the cashier a 45-unit note. How much change do you get?','["35 units","80 units","10 units","45 units"]',2,'Review Money and Financial Mathematics to find the answer.','45 - 35 = 10.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0206','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'What is the ''counting up'' method for finding change?','["Adding the prices of everything in the shop.","Counting forward from the item''s price up to the amount paid.","Counting backwards from 100.","Counting all the coins in your wallet."]',1,'Review Money and Financial Mathematics to find the answer.','Counting up bridges the gap between cost and amount paid.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0207','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Spot the error: A book costs $35. The customer gives $40. The cashier gives $2 change. How do you mathematically prove it''s wrong?','["The cashier should have added the numbers.","The change should be in coins.","The customer paid too much.","$35 (cost) + $2 (change) = $37. This does not equal the $40 paid."]',3,'Review Money and Financial Mathematics to find the answer.','Cost + Change must equal Amount Paid.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0208','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'How can you easily check if the cashier gave you the correct change?','["Count the change twice.","Subtract the change from the cost.","Add the cost of the item and the change together; it should equal what you paid.","Multiply the change by 2."]',2,'Review Money and Financial Mathematics to find the answer.','Cost + Change = Amount Paid.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0209','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'An item costs 34 units. Noah receives 15 units in change. How much did Noah originally hand to the cashier?','["49 units","34 units","83 units","15 units"]',0,'Review Money and Financial Mathematics to find the answer.','Cost + Change = Amount Paid. 34 + 15 = 49.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0210','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'Noah buys a toy for $8.40. They want to get exactly one $2 coin back in change. How much money should they hand the cashier?','["$10.40","$10.00","$6.40","$8.40"]',0,'Review Money and Financial Mathematics to find the answer.','Cost + Desired Change = 8.40 + 2.00 = 10.40.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0211','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'If a book costs 10 units and Chen gives the cashier a 20-unit note, what is the change?','["10 units","20 units","30 units","5 units"]',0,'Review Money and Financial Mathematics to find the answer.','20 - 10 = 10.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0212','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'If Chen buys a toy for $17.25 and pays with a $20.00 bill, what is the change?','["$3.75","$17.75","$2.75","$3.25"]',2,'Review Money and Financial Mathematics to find the answer.','20.00 - 17.25 = 2.75.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0213','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'The total cost is $21.30. The customer hands the cashier a $50 note AND a 50-cent coin, saying ''This will make the change easier.'' What change will the cashier give back?','["$29.50","$29.20","$30.20","$28.70"]',1,'Review Money and Financial Mathematics to find the answer.','Amount paid = 50.50. Cost = 21.30. Change = 50.50 - 21.30 = 29.20.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0214','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',1,'If you pay the EXACT amount an item costs, how much change do you receive?','["0 units","The full amount","Half the amount","1 unit"]',0,'Review Money and Financial Mathematics to find the answer.','Exact payment means no change is due.','2026-11-03 15:30:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0215','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',5,'Spot the error: The cost is $3.40. Charlie pays $5.00. The cashier counts up: ''3.40 plus 60 cents is 4.00, plus $1 is 5.00. Here is $1.40.'' What is wrong?','["The cashier gave $2.60.","The cashier gave 20 cents too little.","Nothing is wrong; the counting up method is perfectly correct and gives $1.60.","The cashier should have added the totals."]',2,'Review Money and Financial Mathematics to find the answer.','3.40 + 0.60 = 4.00; + 1.00 = 5.00. Change is $1.60. (Wait, the prompt said ''Here is $1.40''. So the error is math: 60c + $1 = $1.60).','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0216','Maths','Money and Financial Mathematics','Subtopic 6: Making Change','Primary',10,'If Charlie buys a fruit for $23.15 and pays with $28.00, what is the most efficient combination of change (fewest coins/notes)?','["Rounding the change to the nearest dollar.","Give back only notes.","Always use only 1-cent coins.","Depends on the exact change of $4.85, using the largest denominations first."]',3,'Review Money and Financial Mathematics to find the answer.','The fewest coins/notes rule uses the largest possible denominations first.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0217','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''budget''?','["The money you get back as change.","A list of everything in a shop.","A type of bank account.","A plan for how to use a limited amount of money."]',3,'Review Money and Financial Mathematics to find the answer.','A budget is a spending plan.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0218','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Ben has a budget of 51 units. Their shopping list totals 56 units. What is the financial reality?','["They are 5 units over budget and cannot afford everything.","They have 5 units left over.","They should buy more things.","They calculated wrong."]',0,'Review Money and Financial Mathematics to find the answer.','Total (56) > Budget (51).','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0219','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Ben has a budget of $100. They buy a Need for $51 and a Want for $35. How much of their budget is left?','["$14","$49","$0","$86"]',0,'Review Money and Financial Mathematics to find the answer.','100 - (51 + 35) = 14.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0220','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''Need'' in financial terms?','["Extra candy.","A toy you saw on TV.","Something fun to have, like a video game.","Something essential for health, safety, or everyday life."]',3,'Review Money and Financial Mathematics to find the answer.','Needs are absolute essentials.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0221','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If you are strictly following a limited budget, which items should you buy FIRST?','["The shiniest items.","The Wants (fun items).","The Needs (essentials).","The most expensive items."]',2,'Review Money and Financial Mathematics to find the answer.','Needs take priority in a limited budget.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0222','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Spot the error: A student has a $20 budget. They buy 3 items that cost $6 each and say they have $4 left. What''s wrong?','["They have $0 left.","They went over budget.","They should have multiplied by 4.","3 x $6 = $18. $20 - $18 = $2 left, not $4."]',3,'Review Money and Financial Mathematics to find the answer.','Math error in subtraction: 20 - 18 = 2.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0223','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''Want'' in financial terms?','["Something desirable but not essential.","Basic clothing for winter.","Medicine.","Healthy food."]',0,'Review Money and Financial Mathematics to find the answer.','Wants are optional desires.','2026-11-03 15:30:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0224','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Your budget is 33 units. A book is 18 units and a toy is 23 units. Can you buy both?','["Yes, always.","No, never.","Compare 41 to 33 to decide.","Only if you pay with coins."]',2,'Review Money and Financial Mathematics to find the answer.','Calculate the sum of both items and compare to the budget.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0225','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'If your planned purchases total $38 but your budget is $33, what is the most sensible financial decision?','["Buy it anyway and owe money.","Remove a ''Want'' from your list until the total is within budget.","Demand a $5 discount.","Remove a ''Need'' like food."]',1,'Review Money and Financial Mathematics to find the answer.','Adjust spending by cutting non-essentials (wants).','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0226','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'If Noah has a budget of 58 units and spends 46 units, how do they find the money left over?','["Add the budget and spending.","Multiply the budget by spending.","Divide the budget.","Subtract the spending from the budget."]',3,'Review Money and Financial Mathematics to find the answer.','Remaining = Budget - Spent.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0227','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If Noah has 58 units, buys school bag for 46 units, and wants a comic book for 14 units, what happens?','["They can buy both perfectly.","They will have 2 units left over.","They are 2 units short and cannot afford the toy.","They should buy the want first."]',2,'Review Money and Financial Mathematics to find the answer.','Remaining is 12. The want costs 14, which is 2 units too much.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0228','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Noah has a monthly budget. They spend 50% on Needs, 30% on Wants, and 20% on Savings. If their income is $580, how much goes to Savings?','["$174","$580","$290","$116"]',3,'Review Money and Financial Mathematics to find the answer.','20% of 580 = 116.0.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0229','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'Why is writing a shopping list a good idea?','["It records what you plan to buy so you can estimate the total cost.","It guarantees the shop will have the items.","It means you don''t have to pay.","It gives you a discount at the register."]',0,'Review Money and Financial Mathematics to find the answer.','Lists help you estimate totals and stay on budget.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0230','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Is a winter coat a ''Need'' or a ''Want''?','["It depends on the context: it is a Need if you don''t have one and it is freezing, but a Want if you already have three good ones.","It is never a Need.","It is always a Want.","It is only a Need in summer."]',0,'Review Money and Financial Mathematics to find the answer.','Context determines if an item is an essential need or a superfluous want.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0231','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'A family''s budget for groceries is $195. They spend $78 in week 1 and $78 in week 2. How much is left for the rest of the month?','["$156","$39","$78","$39"]',1,'Review Money and Financial Mathematics to find the answer.','195 - (78 + 78) = 39.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0232','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'Which of the following is considered a ''Need''?','["school bag","A luxury vacation","video game","A massive television"]',0,'Review Money and Financial Mathematics to find the answer.','Needs are essential for basic living.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0233','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If your estimated shopping total is exactly equal to your budget limit, what is the best strategy?','["Throw away your list.","Just buy it without checking.","Calculate the exact prices to make absolutely sure you aren''t slightly over budget.","Assume you have plenty of money."]',2,'Review Money and Financial Mathematics to find the answer.','Estimates can be slightly lower than reality; check exactly on a tight budget.','2026-11-03 15:30:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0234','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Why is ''paying yourself first'' (saving money immediately when you get it) a recommended budgeting strategy?','["It ensures your savings goal is met before you have a chance to spend the money on ''Wants''.","It means you keep all your money and never pay for Needs.","It forces you to spend more.","It is illegal in most countries."]',0,'Review Money and Financial Mathematics to find the answer.','Prioritizing savings guarantees you don''t spend it accidentally.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0235','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''budget''?','["A plan for how to use a limited amount of money.","The money you get back as change.","A list of everything in a shop.","A type of bank account."]',0,'Review Money and Financial Mathematics to find the answer.','A budget is a spending plan.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0236','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Jordan has a budget of 58 units. Their shopping list totals 63 units. What is the financial reality?','["They are 5 units over budget and cannot afford everything.","They should buy more things.","They have 5 units left over.","They calculated wrong."]',0,'Review Money and Financial Mathematics to find the answer.','Total (63) > Budget (58).','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0237','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Jordan has a budget of $100. They buy a Need for $58 and a Want for $49. How much of their budget is left?','["$0","$-7","$107","$42"]',1,'Review Money and Financial Mathematics to find the answer.','100 - (58 + 49) = -7.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0238','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''Need'' in financial terms?','["A toy you saw on TV.","Something fun to have, like a video game.","Something essential for health, safety, or everyday life.","Extra candy."]',2,'Review Money and Financial Mathematics to find the answer.','Needs are absolute essentials.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0239','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If you are strictly following a limited budget, which items should you buy FIRST?','["The Needs (essentials).","The Wants (fun items).","The most expensive items.","The shiniest items."]',0,'Review Money and Financial Mathematics to find the answer.','Needs take priority in a limited budget.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0240','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Spot the error: A student has a $20 budget. They buy 3 items that cost $6 each and say they have $4 left. What''s wrong?','["They went over budget.","3 x $6 = $18. $20 - $18 = $2 left, not $4.","They should have multiplied by 4.","They have $0 left."]',1,'Review Money and Financial Mathematics to find the answer.','Math error in subtraction: 20 - 18 = 2.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0241','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'What is a ''Want'' in financial terms?','["Medicine.","Basic clothing for winter.","Something desirable but not essential.","Healthy food."]',2,'Review Money and Financial Mathematics to find the answer.','Wants are optional desires.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0242','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Your budget is 32 units. A book is 17 units and a toy is 22 units. Can you buy both?','["Only if you pay with coins.","Yes, always.","No, never.","Compare 39 to 32 to decide."]',3,'Review Money and Financial Mathematics to find the answer.','Calculate the sum of both items and compare to the budget.','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0243','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'If your planned purchases total $37 but your budget is $32, what is the most sensible financial decision?','["Buy it anyway and owe money.","Demand a $5 discount.","Remove a ''Need'' like food.","Remove a ''Want'' from your list until the total is within budget."]',3,'Review Money and Financial Mathematics to find the answer.','Adjust spending by cutting non-essentials (wants).','2026-11-03 15:30:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0244','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'If Ben has a budget of 71 units and spends 24 units, how do they find the money left over?','["Divide the budget.","Multiply the budget by spending.","Add the budget and spending.","Subtract the spending from the budget."]',3,'Review Money and Financial Mathematics to find the answer.','Remaining = Budget - Spent.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0245','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If Ben has 71 units, buys medicine for 24 units, and wants a movie ticket for 49 units, what happens?','["They are 2 units short and cannot afford the video game.","They can buy both perfectly.","They should buy the want first.","They will have 2 units left over."]',0,'Review Money and Financial Mathematics to find the answer.','Remaining is 47. The want costs 49, which is 2 units too much.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0246','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Ben has a monthly budget. They spend 50% on Needs, 30% on Wants, and 20% on Savings. If their income is $710, how much goes to Savings?','["$142","$355","$710","$213"]',0,'Review Money and Financial Mathematics to find the answer.','20% of 710 = 142.0.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0247','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'Why is writing a shopping list a good idea?','["It gives you a discount at the register.","It guarantees the shop will have the items.","It means you don''t have to pay.","It records what you plan to buy so you can estimate the total cost."]',3,'Review Money and Financial Mathematics to find the answer.','Lists help you estimate totals and stay on budget.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0248','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'Is a winter coat a ''Need'' or a ''Want''?','["It is only a Need in summer.","It depends on the context: it is a Need if you don''t have one and it is freezing, but a Want if you already have three good ones.","It is never a Need.","It is always a Want."]',1,'Review Money and Financial Mathematics to find the answer.','Context determines if an item is an essential need or a superfluous want.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0249','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'A family''s budget for groceries is $160. They spend $64 in week 1 and $64 in week 2. How much is left for the rest of the month?','["$32","$128","$32","$64"]',0,'Review Money and Financial Mathematics to find the answer.','160 - (64 + 64) = 32.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0250','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',1,'Which of the following is considered a ''Need''?','["A luxury vacation","toy","bread","A massive television"]',2,'Review Money and Financial Mathematics to find the answer.','Needs are essential for basic living.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0251','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',5,'If your estimated shopping total is exactly equal to your budget limit, what is the best strategy?','["Calculate the exact prices to make absolutely sure you aren''t slightly over budget.","Throw away your list.","Just buy it without checking.","Assume you have plenty of money."]',0,'Review Money and Financial Mathematics to find the answer.','Estimates can be slightly lower than reality; check exactly on a tight budget.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0252','Maths','Money and Financial Mathematics','Subtopic 7: Shopping and Budgeting','Primary',10,'Why is ''paying yourself first'' (saving money immediately when you get it) a recommended budgeting strategy?','["It is illegal in most countries.","It forces you to spend more.","It ensures your savings goal is met before you have a chance to spend the money on ''Wants''.","It means you keep all your money and never pay for Needs."]',2,'Review Money and Financial Mathematics to find the answer.','Prioritizing savings guarantees you don''t spend it accidentally.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0253','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'What does it mean to ''estimate'' a cost?','["To pay the cashier.","To guess a random number.","To find an approximate, easy-to-calculate amount.","To find the exact penny amount."]',2,'Review Money and Financial Mathematics to find the answer.','Estimating is finding a sensible approximation.','2026-11-03 15:30:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0254','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'A toy costs $44.90. What is a sensible estimate to the nearest whole dollar?','["$44","$45","$46","$43"]',1,'Review Money and Financial Mathematics to find the answer.','90 cents is very close to the next whole dollar, so round up.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0255','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'A book is $14.50 and a game is $24.75. Estimate the total to the nearest ten dollars.','["$50","$30 (10 + 20) or $40 (10 + 30)","$20","$60"]',1,'Review Money and Financial Mathematics to find the answer.','14.50 rounds to 10 (or 15). 24.75 rounds to 20 (or 25).','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0256','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'If a price ends in 1, 2, 3, or 4, how do we usually round it to the nearest ten?','["Round down to the previous ten.","Add 5.","Round up to the next ten.","Leave it exactly the same."]',0,'Review Money and Financial Mathematics to find the answer.','1-4 rounds down.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0257','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'Mia wants to buy items costing 12, 9, and 18 units. Estimate the total by rounding each to the nearest ten.','["20 units","50 units","30 units","40 units (10 + 10 + 20)"]',3,'Review Money and Financial Mathematics to find the answer.','12->10, 9->10, 18->20. Total = 40.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0258','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'Spot the error: A student estimates $9.95 + $9.95 by saying ''10 + 10 = 20''. They have a $20 bill. Are they guaranteed to have enough money?','["Yes, but they need a calculator.","No, estimates are always wrong.","Yes, because the actual total ($19.90) is strictly less than their over-estimate ($20).","No, they will be short."]',2,'Review Money and Financial Mathematics to find the answer.','If you round UP and still have enough, you are guaranteed to afford it.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0259','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'If a price ends in 5, 6, 7, 8, or 9, how do we usually round it to the nearest ten?','["Round up to the next ten.","Round down.","Keep it the same.","Subtract 5."]',0,'Review Money and Financial Mathematics to find the answer.','5-9 rounds up.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0260','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'Why might you purposely ''round up'' every price when estimating a shopping trip?','["Because rounding down is against the rules.","To make absolutely sure you bring enough money to cover the total.","To make the cashier happy.","To make the math harder."]',1,'Review Money and Financial Mathematics to find the answer.','Rounding up gives a safe over-estimate for a budget.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0261','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'If an item costs $4.10, $4.20, and $4.30, and you round them all DOWN to $4, what is the risk?','["You will bring too much change.","Your estimate ($12) will be too low, and you might not bring enough money ($12.60 actual).","Your estimate will be too high.","There is no risk."]',1,'Review Money and Financial Mathematics to find the answer.','Rounding down consistently leads to under-estimating the true cost.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0262','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'Round 69 units to the nearest ten.','["70 units","79 units","59 units","69 units"]',0,'Review Money and Financial Mathematics to find the answer.','Apply standard rounding rules to the nearest 10.','2026-11-03 15:30:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0263','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'An item costs $69.40. What is a convenient estimate to the nearest whole dollar?','["$68","$70","$69","$71"]',2,'Review Money and Financial Mathematics to find the answer.','40 cents is less than 50, so round down.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0264','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'Estimate the total cost of 4 items that each cost $69.85.','["About $276","About $272","About $280 (4 x $70)","About $284"]',2,'Review Money and Financial Mathematics to find the answer.','$69.85 is close to $70. 4 x 70 = 280.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0265','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'A toy costs 19 units. What is a sensible estimate?','["25 units","10 units","20 units","15 units"]',2,'Review Money and Financial Mathematics to find the answer.','19 rounds up to 20.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0266','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'If your estimated shopping total is exactly equal to your budget limit, what should you do?','["Throw away your list.","Calculate the exact prices to make sure you aren''t slightly over budget.","Assume you have plenty of money.","Just buy it without checking."]',1,'Review Money and Financial Mathematics to find the answer.','Estimates can be slightly lower than reality; check exactly if it''s a tight budget.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0267','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'Taylor has $840. They want to buy items that cost $19, $22, and $38. By rounding to the nearest ten, estimate the total. Can they afford it?','["Estimated total = $70.","Estimated total = 20 + 20 + 40 = $80. Check against budget.","Estimated total = $90.","Estimated total = $100."]',1,'Review Money and Financial Mathematics to find the answer.','19->20, 22->20, 38->40. Sum = 80.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0268','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',1,'Why do we estimate costs while shopping?','["To make the items cheaper.","Because exact math is illegal.","To trick the cashier.","To quickly check if we have enough money."]',3,'Review Money and Financial Mathematics to find the answer.','Estimation allows fast mental math to check budget limits.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0269','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',5,'Estimate the total: $33.80 + $1.10.','["$36","$34","$33","$35"]',3,'Review Money and Financial Mathematics to find the answer.','33.80 -> 34. 1.10 -> 1. Total = 35.','2026-11-03 15:30:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0270','Maths','Money and Financial Mathematics','Subtopic 8: Estimating Costs','Primary',10,'Why is an estimate useful, but not a replacement for an exact calculation?','["An estimate is only used for taxes.","Exact calculations are illegal.","An estimate gives a quick idea of affordability, but exact calculations are needed to ensure exact payment.","An estimate is more accurate than an exact calculation."]',2,'Review Money and Financial Mathematics to find the answer.','Estimates are for planning; exact calculations are for execution.','2026-11-03 15:30:11',NULL,NULL);
