INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0325','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What does ''saving'' money mean?','["Paying the cashier.","Buying everything you want immediately.","Keeping some money to use later instead of spending it now.","Losing your coins."]',2,'Review Money and Financial Mathematics to find the answer.','Saving is delaying spending for the future.','2026-11-03 15:30:17',NULL,NULL);
