INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0327','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'Ben wants a bike that costs $100. They have $40. If they save $5 a week, how many weeks until they can buy it?','["20 weeks","8 weeks","28 weeks","12 weeks"]',3,'Review Money and Financial Mathematics to find the answer.','Need = 100 - 40 = 60. 60 / 5 = 12.','2026-11-03 15:30:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0328','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What does ''spending'' money mean?','["Working for a salary.","Putting money in a bank.","Hiding money in a jar.","Using money to pay for goods or services."]',3,'Review Money and Financial Mathematics to find the answer.','Spending is exchanging money for items.','2026-11-03 15:30:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0329','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'A toy costs 30 units. Jordan already has 12 units saved. How much MORE does Jordan need to save?','["18 units","12 units","42 units","30 units"]',0,'Review Money and Financial Mathematics to find the answer.','30 - 12 = 18.','2026-11-03 15:30:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0330','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'Spot the error: A student says ''I get $10 a week, so if I spend $10 a week on candy, I will have $50 saved in 5 weeks.''','["They should buy more candy.","They are spending all their money, so their savings will be $0.","They will actually have $100.","Their math is perfect."]',1,'Review Money and Financial Mathematics to find the answer.','Savings = Income - Spending. 10 - 10 = 0 saved.','2026-11-03 15:30:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0331','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What is a ''savings goal''?','["A type of shopping list.","A goal in a soccer match.","A specific item or amount of money you are planning and saving up to get.","A budget deficit."]',2,'Review Money and Financial Mathematics to find the answer.','A target you want to reach with saved money.','2026-11-03 15:30:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0332','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'You have $10. You want a game ($8) and candy ($4). You can''t afford both. Which decision process is best?','["Compare choices, decide which is a higher priority, and save the rest or buy only one.","Buy the game and steal the candy.","Borrow money from a stranger.","Throw the $10 away."]',0,'Review Money and Financial Mathematics to find the answer.','Evaluate priorities when funds are limited.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0333','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'If you put your money in a savings account at a bank instead of a jar at home, what might the bank give you as a reward over time?','["A discount on groceries.","Free toys.","A receipt.","Interest (extra money added to your balance)."]',3,'Review Money and Financial Mathematics to find the answer.','Banks pay interest on saved deposits.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0334','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'If Taylor receives 30 units and decides to SAVE 4 units, how much is left to SPEND?','["4 units","26 units","30 units","34 units"]',1,'Review Money and Financial Mathematics to find the answer.','30 - 4 = 26.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0335','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'Why is saving a set amount (like $3) EVERY week a good strategy?','["It makes it easy to predict exactly when you will reach your savings goal.","It stops you from ever buying things.","The bank forces you to do it.","It makes the items cheaper."]',0,'Review Money and Financial Mathematics to find the answer.','Consistent saving creates a predictable timeline.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0336','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'A child receives $30 for their birthday. They want to save 20% of it, spend 50% on a game, and keep the rest for snacks. How much is kept for snacks?','["$6.00","$21.00","$9.00","$15.00"]',2,'Review Money and Financial Mathematics to find the answer.','100% - 20% - 50% = 30%. 30% of the total goes to snacks.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0337','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What is a simple way to calculate money saved?','["Money received multiplied by money spent.","There is no way to calculate it.","Money received minus money spent.","Money spent plus money received."]',2,'Review Money and Financial Mathematics to find the answer.','Saved = Received - Spent.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0338','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'Chen has 80 units. They spend 10 on school supplies and 5 on a snack. How much is remaining?','["65 units","15 units","75 units","70 units"]',0,'Review Money and Financial Mathematics to find the answer.','Total spent = 15. Remaining = 80 - 15.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0339','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'Chen creates a savings plan: save $5 in Week 1, $10 in Week 2, $15 in Week 3. What is the total saved?','["$25","$20","$15","$30"]',3,'Review Money and Financial Mathematics to find the answer.','5 + 10 + 15 = 30.','2026-11-03 15:30:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0340','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'If you want to buy a bicycle in the future, what is the best financial habit?','["Borrow money from everyone.","Wait and hope you find the money on the street.","Spend all your money on candy now.","Set a savings goal and save a little bit of money each week."]',3,'Review Money and Financial Mathematics to find the answer.','Consistent saving helps reach goals.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0341','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'If you have a limited amount of money, which should you usually plan for first?','["Important needs (like healthy food or school supplies).","Optional wants (like a new video game).","Extra candy.","The most expensive item in the shop."]',0,'Review Money and Financial Mathematics to find the answer.','Needs must be prioritized over wants.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0342','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'Why is ''paying yourself first'' (saving money immediately when you get it) a recommended budgeting strategy?','["It forces you to spend more.","It means you keep all your money and never pay for Needs.","It ensures your savings goal is met before you have a chance to spend the money on ''Wants''.","It is illegal in most countries."]',2,'Review Money and Financial Mathematics to find the answer.','Prioritizing savings guarantees you don''t spend it accidentally.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0343','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What does ''saving'' money mean?','["Keeping some money to use later instead of spending it now.","Buying everything you want immediately.","Losing your coins.","Paying the cashier."]',0,'Review Money and Financial Mathematics to find the answer.','Saving is delaying spending for the future.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0344','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',5,'Alex saves 3 units every week. How much will Alex have saved after 5 weeks?','["5 units","3 units","8 units","15 units"]',0,'Review Money and Financial Mathematics to find the answer.','3 * 5 = 15.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0345','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',10,'Alex wants a bike that costs $100. They have $40. If they save $3 a week, how many weeks until they can buy it?','["20 weeks","13 weeks","46 weeks","33 weeks"]',0,'Review Money and Financial Mathematics to find the answer.','Need = 100 - 40 = 60. 60 / 3 = 20.','2026-11-03 15:30:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0346','Maths','Money and Financial Mathematics','Subtopic 10: Saving and Spending Decisions','Primary',1,'What does ''spending'' money mean?','["Using money to pay for goods or services.","Hiding money in a jar.","Working for a salary.","Putting money in a bank."]',0,'Review Money and Financial Mathematics to find the answer.','Spending is exchanging money for items.','2026-11-03 15:30:19',NULL,NULL);
