INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0363','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'Chen buys 2 shirts for $66 each. They have a coupon for $10 off the TOTAL. If they pay with a $100 bill, how much change is returned?','["$122","$34","$-32","$-22"]',3,'Review Money and Financial Mathematics to find the answer.','Cost = 2*66 = 132. Discount = 132-10 = 122. Change = 100 - 122.','2026-11-03 15:30:21',NULL,NULL);
