INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0367','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'Ben buys 3 apples that cost 2 units EACH. What operation finds the total cost?','["Fractions","Subtraction","Division","Multiplication (or repeated addition)"]',3,'Review Money and Financial Mathematics to find the answer.','Cost = Quantity × Unit Price.','2026-11-03 15:30:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0368','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Ben wants a game for $40. They have $56. They earn $5 for chores. Do they have enough?','["No, never.","They need to multiply.","Yes, always.","Calculate if their starting money plus $5 is greater than or equal to $40."]',3,'Review Money and Financial Mathematics to find the answer.','Check if 56 + 5 >= 40.','2026-11-03 15:30:21',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0369','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'A shop sells 3 pens for $6. How much would 5 pens cost?','["$10","$12","$15","$5"]',0,'Review Money and Financial Mathematics to find the answer.','Unit price = 6/3 = $2. 5 pens = 5 * 2 = $10.','2026-11-03 15:30:21',NULL,NULL);
