INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0375','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'A family''s budget for groceries is $325. They spend $130 in week 1 and $130 in week 2. How much is left for the rest of the month?','["$130","$260","$65","$65"]',2,'Review Money and Financial Mathematics to find the answer.','325 - (130 + 130) = 65.','2026-11-03 15:30:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0376','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'In a word problem, what does the word ''difference'' usually tell you to do?','["Add everything up.","Multiply by 2.","Subtract the smaller amount from the larger amount.","Share it equally."]',2,'Review Money and Financial Mathematics to find the answer.','Difference implies subtraction.','2026-11-03 15:30:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0377','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Mina wants a book costing 35 units. She has saved 17 units and saves another 20 units. How much more does she need?','["20 units","37 units","-2 units","18 units"]',2,'Review Money and Financial Mathematics to find the answer.','Total saved = 17 + 20. Need = 35 - (17 + 20).','2026-11-03 15:30:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0378','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'If Jordan buys a uniform for $20.15 and pays with $43.00, what is the most efficient combination of change (fewest coins/notes)?','["Always use only 1-cent coins.","Rounding the change to the nearest dollar.","Give back only notes.","Depends on the exact change of $22.85, using the largest denominations first."]',3,'Review Money and Financial Mathematics to find the answer.','The fewest coins/notes rule uses the largest possible denominations first.','2026-11-03 15:30:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0379','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'Charlie has 51 units. They buy a snack for 18 units. What operation do you use to find the remaining money?','["Addition","Multiplication","Subtraction","Division"]',2,'Review Money and Financial Mathematics to find the answer.','Spending money means subtracting from the total.','2026-11-03 15:30:22',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0380','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Charlie has 51 units and buys a book for 18 units. How much money remains?','["51 units","33 units","18 units","69 units"]',1,'Review Money and Financial Mathematics to find the answer.','51 - 18 = 33.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0381','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'Charlie buys 2 shirts for $51 each. They have a coupon for $10 off the TOTAL. If they pay with a $100 bill, how much change is returned?','["$92","$-2","$8","$49"]',2,'Review Money and Financial Mathematics to find the answer.','Cost = 2*51 = 102. Discount = 102-10 = 92. Change = 100 - 92.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0382','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'If 4 friends want to share 292 dollars equally, what math operation should they use?','["Division","Multiplication","Subtraction","Addition"]',0,'Review Money and Financial Mathematics to find the answer.','Sharing equally requires division.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0383','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Ava buys 4 toys at $5 each. They hand the cashier a $50 bill. How much change do they get?','["$20","$45","$30","$10"]',2,'Review Money and Financial Mathematics to find the answer.','4 * 5 = 20. 50 - 20 = 30.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0384','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'Spot the error: ''I had $20, spent $8, then found $5. So I have $20 - $8 - $5 = $7 left.''','["Math is correct.","Finding money means ADDING it. It should be 20 - 8 + 5 = $17.","They forgot to multiply by 5.","They should have added $8."]',1,'Review Money and Financial Mathematics to find the answer.','Finding money increases the total (+).','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0385','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'Ava buys 3 apples that cost 2 units EACH. What operation finds the total cost?','["Multiplication (or repeated addition)","Division","Subtraction","Fractions"]',0,'Review Money and Financial Mathematics to find the answer.','Cost = Quantity × Unit Price.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0386','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Ava wants a game for $40. They have $73. They earn $5 for chores. Do they have enough?','["Calculate if their starting money plus $5 is greater than or equal to $40.","Yes, always.","No, never.","They need to multiply."]',0,'Review Money and Financial Mathematics to find the answer.','Check if 73 + 5 >= 40.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0387','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'A shop sells 3 pens for $6. How much would 5 pens cost?','["$5","$12","$10","$15"]',2,'Review Money and Financial Mathematics to find the answer.','Unit price = 6/3 = $2. 5 pens = 5 * 2 = $10.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0388','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'In a word problem, what does the word ''altogether'' usually tell you to do?','["Divide the amounts.","Add the amounts.","Subtract the amounts.","Ignore the amounts."]',1,'Review Money and Financial Mathematics to find the answer.','''Altogether'' implies a total sum.','2026-11-03 15:30:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0389','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Four friends share a $24 pizza equally. How much does each friend pay?','["$4","$12","$8","$6"]',3,'Review Money and Financial Mathematics to find the answer.','24 / 4 = 6.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0390','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'Noah saves $1.50 a day. How many days until they have exactly $15.00?','["10 days","5 days","20 days","15 days"]',0,'Review Money and Financial Mathematics to find the answer.','15.00 / 1.50 = 10.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0391','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'If Riley has 39 units and receives a gift of 23 units, what operation finds the new total?','["Division","Subtraction","Multiplication","Addition"]',3,'Review Money and Financial Mathematics to find the answer.','Receiving money means adding it to your total.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0392','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'A learner buys 3 notebooks at 4 units each and 2 pencils at 23 units each. What is the total cost?','["5 units","35 units","58 units","27 units"]',2,'Review Money and Financial Mathematics to find the answer.','(3*4) + (2*23) = 12 + 46.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0393','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'A family''s budget for groceries is $195. They spend $78 in week 1 and $78 in week 2. How much is left for the rest of the month?','["$78","$156","$39","$39"]',2,'Review Money and Financial Mathematics to find the answer.','195 - (78 + 78) = 39.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0394','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',1,'In a word problem, what does the word ''difference'' usually tell you to do?','["Add everything up.","Share it equally.","Subtract the smaller amount from the larger amount.","Multiply by 2."]',2,'Review Money and Financial Mathematics to find the answer.','Difference implies subtraction.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0395','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',5,'Mina wants a book costing 35 units. She has saved 17 units and saves another 15 units. How much more does she need?','["15 units","18 units","3 units","32 units"]',2,'Review Money and Financial Mathematics to find the answer.','Total saved = 17 + 15. Need = 35 - (17 + 15).','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t12_global_0396','Maths','Money and Financial Mathematics','Subtopic 11: Money Word Problems','Primary',10,'If Mia buys a school bag for $15.15 and pays with $54.00, what is the most efficient combination of change (fewest coins/notes)?','["Give back only notes.","Rounding the change to the nearest dollar.","Depends on the exact change of $38.85, using the largest denominations first.","Always use only 1-cent coins."]',2,'Review Money and Financial Mathematics to find the answer.','The fewest coins/notes rule uses the largest possible denominations first.','2026-11-03 15:30:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0001','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'What does the word ''data'' mean in mathematics?','["A collection of facts, observations or information.","A geometric shape.","A secret code.","A type of ruler."]',0,'Review Data Handling and Statistics to find the answer.','Data is information collected to be studied.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0002','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'Skyler wants to find out which running is most popular in class. What is the best way to collect this data?','["Ask each student in the class and record their answers.","Look at a book about sports.","Guess what everyone likes.","Ask the teacher only."]',0,'Review Data Handling and Statistics to find the answer.','Surveying the actual group provides the most accurate data.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0003','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'Why might collecting data by ''observation'' be more reliable than ''asking questions'' for a topic like ''How many cars stop at the stop sign?''','["People might forget or lie if asked, but observing records exactly what happens.","Observation always uses a ruler.","You can''t ask a car a question.","Observation is faster than talking."]',0,'Review Data Handling and Statistics to find the answer.','Observation removes human memory bias from the data.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0004','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'Which of these is a method of collecting data?','["Adding two numbers.","Sleeping.","Drawing a circle.","Asking people a question."]',3,'Review Data Handling and Statistics to find the answer.','Asking questions (surveying) gathers data.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0005','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'Spot the error: A student collects data on favorite pets but only asks people who own dogs. Why is this a problem?','["The data will be biased and won''t represent everyone fairly.","Dogs can''t talk.","They didn''t use a ruler.","They should have asked cats."]',0,'Review Data Handling and Statistics to find the answer.','Fair data collection requires a balanced, unbiased group of participants.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0006','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'Class A has 30 students. 6 are absent. The teacher asks the rest a survey question. How many data points (responses) will the teacher collect?','["6","36","30","24"]',3,'Review Data Handling and Statistics to find the answer.','30 total - 6 absent = 24 present to answer.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0007','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'If you sit in a garden and count how many birds you see, what method of data collection are you using?','["Observation and counting","Guessing","Ignoring","Measuring"]',0,'Review Data Handling and Statistics to find the answer.','Watching and counting is observation.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0008','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'In a survey, 4 people choose mango and 3 people choose orange. How many responses were recorded altogether?','["12","7","3","4"]',1,'Review Data Handling and Statistics to find the answer.','Total responses = 4 + 3 = 7.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0009','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'Spot the error: A scientist measures the temperature of water every hour, but decides to leave out the lowest temperature because ''it looked weird.''','["They should have changed it to a fraction.","They should have added 10 degrees to it.","That is the correct way to do science.","You must record ALL observations accurately without changing or hiding data."]',3,'Review Data Handling and Statistics to find the answer.','Removing valid data points ruins the integrity of the data collection.','2026-11-03 15:37:52',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0010','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'Why do we collect data?','["To make our notebooks heavier.","To avoid doing math.","Because numbers are colorful.","To understand what is happening and answer questions using evidence."]',3,'Review Data Handling and Statistics to find the answer.','Data provides evidence to answer questions.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0011','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'Why is it important to record every answer exactly once during a survey?','["So you can pick the winner you want.","To practice writing.","So that the total count accurately matches the number of participants.","So that you finish faster."]',2,'Review Data Handling and Statistics to find the answer.','Double-counting or skipping ruins data accuracy.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0012','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'If Rowan surveys 50 people, and exactly half refuse to answer, how many valid data responses does Rowan actually collect?','["25","0","100","50"]',0,'Review Data Handling and Statistics to find the answer.','Half of 50 is 25.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0013','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'If Jordan asks 7 friends their favorite fruit, and 4 friends their favorite color, how many people did Jordan ask in total (assuming they are different friends)?','["7","11","4","28"]',1,'Review Data Handling and Statistics to find the answer.','7 + 4 = 11.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0014','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'If you want to collect data on how tall plants grow in a week, which method should you use?','["Counting their leaves.","Asking the plants a question.","Guessing their height.","Measurement using a ruler."]',3,'Review Data Handling and Statistics to find the answer.','Height requires the measurement method.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0015','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'What is a ''leading question'' in data collection, and why is it bad?','["A question that is too hard.","A question that pushes people to a specific answer (e.g. ''Don''t you love pizza?''); it makes data unfair.","A question at the start of a page.","A question asked by the leader."]',1,'Review Data Handling and Statistics to find the answer.','Leading questions create biased, inaccurate data.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0016','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'Which of these is an example of ''data''?','["A single random number.","The daily temperature of a town for a week.","A fictional story.","A blank piece of paper."]',1,'Review Data Handling and Statistics to find the answer.','A collection of related facts/measurements is data.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0017','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',5,'A survey has 13 total participants. If 7 choose option A, how many choose option B (assuming everyone chose one of the two)?','["6","13","7","42"]',0,'Review Data Handling and Statistics to find the answer.','Total (13) - Option A (7) = Option B (6).','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0018','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',10,'If you want to know the most popular book in the whole school, but you only survey your 5 best friends, what is the problem with your data?','["Books are not data.","You didn''t use a tally chart.","You should have observed them reading.","Your small group (sample size) does not accurately represent the entire school population."]',3,'Review Data Handling and Statistics to find the answer.','A sample must represent the population to make broad conclusions.','2026-11-03 15:37:53',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0019','Maths','Data Handling and Statistics','Subtopic 1: Collecting Data','Primary',1,'What does the word ''data'' mean in mathematics?','["A secret code.","A collection of facts, observations or information.","A type of ruler.","A geometric shape."]',1,'Review Data Handling and Statistics to find the answer.','Data is information collected to be studied.','2026-11-03 15:37:53',NULL,NULL);
