INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0065','Maths','Data Handling and Statistics','Subtopic 2: Sorting and Classifying Information','Primary',5,'You have a bag of different coloured toy cars. If you sort them by ''Type of Vehicle'', what happens?','["They get sorted into rainbow order.","They get sorted by size.","You cannot sort them.","They all go into one category (''Cars'')."]',3,'Review Data Handling and Statistics to find the answer.','Since they are all cars, sorting by vehicle type yields only one group.','2026-11-03 15:37:58',NULL,NULL);
