INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0068','Maths','Data Handling and Statistics','Subtopic 2: Sorting and Classifying Information','Primary',5,'If a set of 12 items is sorted, and 7 items go into Category A, how many go into Category B (assuming only 2 categories)?','["7","0","12","5"]',3,'Review Data Handling and Statistics to find the answer.','Total (12) - Category A (7) = 5.','2026-11-03 15:37:58',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0069','Maths','Data Handling and Statistics','Subtopic 2: Sorting and Classifying Information','Primary',10,'Spot the error: Sorting a class of students by ''Tall'' and ''Short'' without any other instruction.','["You must use colors.","There is no error.","The rule is subjective and not clear; you need a specific measurement (e.g. ''Over 140cm'').","Students can''t be sorted."]',2,'Review Data Handling and Statistics to find the answer.','Classification rules must be objective and measurable.','2026-11-03 15:37:59',NULL,NULL);
