INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0071','Maths','Data Handling and Statistics','Subtopic 2: Sorting and Classifying Information','Primary',5,'Why is it important to check the total count after classifying data into groups?','["To make the numbers look bigger.","To practice addition.","To change the rule.","To ensure no item was missed or counted twice."]',3,'Review Data Handling and Statistics to find the answer.','The sum of the groups must equal the original total count.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0072','Maths','Data Handling and Statistics','Subtopic 2: Sorting and Classifying Information','Primary',10,'If you sort the numbers 1, 2, 3, 4, 5, 6 by ''Even'' and ''Odd'', what are the frequencies of the two categories?','["Even: 4, Odd: 2","Even: 2, Odd: 4","Even: 3, Odd: 3","Even: 6, Odd: 0"]',2,'Review Data Handling and Statistics to find the answer.','Evens (2,4,6) = 3. Odds (1,3,5) = 3.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0073','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'What does a single vertical tally mark (|) represent?','["0 items","5 items","10 items","1 item"]',3,'Review Data Handling and Statistics to find the answer.','One vertical line equals one count.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0074','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'A tally chart shows 7 complete groups of five. What is the frequency?','["70","12","35","7"]',2,'Review Data Handling and Statistics to find the answer.','7 groups of 5 = 35.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0075','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'Category A has 7 tally groups of 5. Category B has 8 tally groups of 5. What is the difference in frequency between them?','["40","5","35","1"]',1,'Review Data Handling and Statistics to find the answer.','(8 * 5) - (7 * 5) = 5.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0076','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'How many items does a complete ''group'' of tally marks (four vertical lines crossed by one diagonal line) represent?','["6","10","5","4"]',2,'Review Data Handling and Statistics to find the answer.','A completed tally group represents 5.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0077','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'A tally chart shows 7 complete groups of five, plus 3 extra lines. What is the total frequency?','["10","3","35","38"]',1,'Review Data Handling and Statistics to find the answer.','(7 * 5) + 3 = 38.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0078','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'A surveyor counts 70 cars. How many COMPLETE tally groups of 5 will be drawn in the chart?','["35","7","70","14"]',3,'Review Data Handling and Statistics to find the answer.','70 / 5 = 14.','2026-11-03 15:37:59',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0079','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'Why do we group tally marks in fives?','["It saves ink.","Because 5 is a lucky number.","It makes it much faster and easier to count large numbers.","Because it looks like a box."]',2,'Review Data Handling and Statistics to find the answer.','Counting by 5s is faster than counting individual lines.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0080','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'Rowan wants to record a frequency of 17 using tally marks. How many diagonal ''crossing'' lines will they draw?','["15","3","2","5"]',1,'Review Data Handling and Statistics to find the answer.','The number is 17, which means 3 complete groups of five. So 3 diagonal lines.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0081','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'Spot the error: A frequency table shows ''Apples: 14'' but the tally column shows two groups of 5 and three single lines.','["There is no error.","Apples shouldn''t be in a tally chart.","The frequency should be 12.","The tally marks only add up to 13. There is a mismatch."]',3,'Review Data Handling and Statistics to find the answer.','5 + 5 + 3 = 13. The frequency says 14. Data is mismatched.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0082','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'What does ''frequency'' mean in a tally table?','["A type of radio wave.","The title of the table.","The final number count of how many times something occurred.","The name of the category."]',2,'Review Data Handling and Statistics to find the answer.','Frequency is the total numerical count.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0083','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'Spot the error: A student records a count of 7 by drawing 7 straight vertical lines |||||||.','["They forgot to cross the 5th line to make a group of 5.","Nothing is wrong.","They should have stopped at 5.","They should have used numbers."]',0,'Review Data Handling and Statistics to find the answer.','Tally marks must be bundled in 5s (4 vertical, 1 diagonal).','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0084','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'If a total of 75 items are distributed EQUALLY across 3 categories, how many tally marks will be in the first category?','["50","15","25","75"]',2,'Review Data Handling and Statistics to find the answer.','75 / 3 = 25.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0085','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'If a category has 4 tally marks, what is its frequency?','["9","4","5","1"]',1,'Review Data Handling and Statistics to find the answer.','The number of lines equals the frequency: 4.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0086','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'If Category A has a frequency of 25 and Category B has a frequency of 20, how many complete tally groups are in Category B?','["5","4","19","20"]',1,'Review Data Handling and Statistics to find the answer.','20 divided by 5 is 4 groups.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0087','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'Why might a scientist use a tally chart in the field instead of just writing the final number?','["A tally chart allows you to continuously add data one by one as events happen in real-time.","Tally charts take up less paper.","Numbers are too hard to write.","Tally charts are required by law."]',0,'Review Data Handling and Statistics to find the answer.','Tallying is ideal for running counts of live events.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0088','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',1,'What do we do with the FIFTH tally mark?','["Draw it diagonally across the first four lines.","Write the number 5.","Draw a circle.","Draw it taller than the others."]',0,'Review Data Handling and Statistics to find the answer.','The fifth mark slashes across the previous four to bundle them.','2026-11-03 15:38:00',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0089','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',5,'When turning tally marks into a frequency table, what is the final step to ensure accuracy?','["Change the title.","Add up all the frequencies and check it matches the total number of items recorded.","Erase the tally marks.","Color the table."]',1,'Review Data Handling and Statistics to find the answer.','Verification against the total ensures no data was lost.','2026-11-03 15:38:01',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0090','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'Sam is making a tally chart. They draw 7 vertical lines, cross them with 1 diagonal line, and then draw 1 more vertical lines. What is the frequency?','["It is impossible to know.","36","This is an improper tally. They should cross on the 5th line, not the (t+1)th line.","9"]',2,'Review Data Handling and Statistics to find the answer.','Tally marks MUST be crossed exactly on the 5th line.','2026-11-03 15:38:01',NULL,NULL);
