INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0108','Maths','Data Handling and Statistics','Subtopic 3: Tally Marks','Primary',10,'Reese is making a tally chart. They draw 5 vertical lines, cross them with 1 diagonal line, and then draw 2 more vertical lines. What is the frequency?','["This is an improper tally. They should cross on the 5th line, not the (t+1)th line.","27","8","It is impossible to know."]',0,'Review Data Handling and Statistics to find the answer.','Tally marks MUST be crossed exactly on the 5th line.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0109','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What is a ''pictograph''?','["A table with only numbers.","A graph with only lines.","A chart that uses pictures or symbols to display data.","A photograph of a graph."]',2,'Review Data Handling and Statistics to find the answer.','Pictographs use visual symbols to represent data.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0110','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'A pictograph key says ''1 book symbol = 3 books''. If Taylor''s row has 5 book symbols, how many books did Taylor read?','["15 books","8 books","3 books","5 books"]',0,'Review Data Handling and Statistics to find the answer.','5 symbols x 3 books/symbol = 15.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0111','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'A pictograph shows 3 rows. Row 1 has 5 symbols. Row 2 has 6 symbols. Row 3 has 4 symbols. The key is ''1 symbol = 3''. What is the TOTAL sum of all rows?','["15","15","18","45"]',3,'Review Data Handling and Statistics to find the answer.','Total symbols = 15. 15 * 3 = 45.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0112','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What does the ''key'' on a pictograph do?','["It shows the alphabet.","It tells you what number each picture/symbol represents.","It tells you the title of the graph.","It unlocks the paper."]',1,'Review Data Handling and Statistics to find the answer.','The key explains the value of the symbols.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0113','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If a category needs to show 28 items, and the key says ''1 symbol = 7 items'', how many symbols should you draw?','["4 symbols","10 symbols","7 symbols","28 symbols"]',0,'Review Data Handling and Statistics to find the answer.','28 / 7 = 4.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0114','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'You need to represent 38 items. The key is ''1 symbol = 7''. How do you draw this?','["5 whole symbols and 1 half symbol.","5 whole symbols.","It is impossible.","6 whole symbols."]',0,'Review Data Handling and Statistics to find the answer.','(7*5) = 5 symbols. 3.5 is exactly half a symbol.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0115','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'If a pictograph key says ''1 star = 1 learner'', how many learners do 5 stars represent?','["10","10","1","5"]',3,'Review Data Handling and Statistics to find the answer.','If 1 star = 1, then 5 stars = 5.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0116','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'Category A has 5 symbols. Category B has 3 symbols. The key is ''1 symbol = 2 items''. What is the exact difference between A and B?','["2 items","1 item","4 items","6 items"]',2,'Review Data Handling and Statistics to find the answer.','Difference is 2 symbols. 2 symbols x 2 = 4 items.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0117','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Why might a scientist choose to use ''1 symbol = 100'' instead of ''1 symbol = 1'' for a very large dataset?','["To make the data look smaller.","To hide the real numbers.","Because they don''t know how to draw.","To prevent the graph from becoming too massive and unreadable with thousands of tiny symbols."]',3,'Review Data Handling and Statistics to find the answer.','Scaling the key makes large datasets visually manageable.','2026-11-03 15:38:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0118','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'In a pictograph, if the ''Apples'' row has the most symbols, what does that mean?','["Apples are the least popular.","The graph is broken.","Apples are red.","Apples is the most popular/highest category."]',3,'Review Data Handling and Statistics to find the answer.','More symbols mean a higher frequency/value.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0119','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'Spot the error: A student counts 5 symbols in a pictograph and writes the total as ''5'', completely ignoring the key that says ''1 symbol = 10''.','["They should have added 10.","Nothing is wrong.","The total is actually 15.","They should have multiplied the symbols by the key (5 x 10 = 50)."]',3,'Review Data Handling and Statistics to find the answer.','The value is always (Number of Symbols) x (Key Value).','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0120','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Row A has 6 symbols. Row B has 3 symbols. Key: ''1 symbol = 5''. What is the ratio of Row A to Row B?','["1 : 2","6 : 1","2 : 1","5 : 1"]',2,'Review Data Handling and Statistics to find the answer.','Row A has exactly twice as many symbols as Row B, so the ratio of values is 2:1.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0121','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'If a row in a pictograph has 7 symbols, and another has 5 symbols, which category is smaller?','["The one with fewer symbols.","Cannot be determined.","The one with more symbols.","They are equal."]',0,'Review Data Handling and Statistics to find the answer.','Fewer symbols represent a smaller value.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0122','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If a key says ''1 smiling face = 6 students'', what does HALF a smiling face represent?','["0 students","3 students","1 student","6 students"]',1,'Review Data Handling and Statistics to find the answer.','Half a symbol represents half of the key''s value.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0123','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Spot the error: Riley makes a pictograph about favorite pets. The key says ''1 dog picture = 5 votes''. But Riley uses dog pictures for the cat row too.','["There is no error.","They should have used a cat picture with a different key value.","Dog pictures are only for dogs.","The symbols should ideally match the category, or a neutral symbol (like a star or smiley) should be used for the whole graph."]',3,'Review Data Handling and Statistics to find the answer.','Using a specific category''s icon for all rows can be highly confusing.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0124','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What do you MUST check before counting the pictures on a pictograph?','["The date.","The back of the page.","The Key.","The colour of the pictures."]',2,'Review Data Handling and Statistics to find the answer.','The key dictates the value of the pictures.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0125','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If the total for a category is 48 and the key is ''1 symbol = 8'', how many symbols are drawn?','["48","8","14","6"]',3,'Review Data Handling and Statistics to find the answer.','Divide total by key: 48 / 8 = 6.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0126','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'If a graph''s total value is 80 and there are 8 symbols drawn across the whole graph, what MUST the key value be?','["10","1","5","8"]',0,'Review Data Handling and Statistics to find the answer.','Total (80) / Symbols (8) = Key (10).','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0127','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What is a ''pictograph''?','["A graph with only lines.","A photograph of a graph.","A chart that uses pictures or symbols to display data.","A table with only numbers."]',2,'Review Data Handling and Statistics to find the answer.','Pictographs use visual symbols to represent data.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0128','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'A pictograph key says ''1 book symbol = 7 books''. If Skyler''s row has 5 book symbols, how many books did Skyler read?','["7 books","12 books","5 books","35 books"]',2,'Review Data Handling and Statistics to find the answer.','5 symbols x 7 books/symbol = 35.','2026-11-03 15:38:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0129','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'A pictograph shows 3 rows. Row 1 has 5 symbols. Row 2 has 6 symbols. Row 3 has 4 symbols. The key is ''1 symbol = 7''. What is the TOTAL sum of all rows?','["42","105","15","35"]',1,'Review Data Handling and Statistics to find the answer.','Total symbols = 15. 15 * 7 = 105.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0130','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What does the ''key'' on a pictograph do?','["It tells you what number each picture/symbol represents.","It shows the alphabet.","It tells you the title of the graph.","It unlocks the paper."]',0,'Review Data Handling and Statistics to find the answer.','The key explains the value of the symbols.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0131','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If a category needs to show 24 items, and the key says ''1 symbol = 6 items'', how many symbols should you draw?','["6 symbols","24 symbols","4 symbols","10 symbols"]',1,'Review Data Handling and Statistics to find the answer.','24 / 6 = 4.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0132','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'You need to represent 33 items. The key is ''1 symbol = 6''. How do you draw this?','["5 whole symbols.","6 whole symbols.","It is impossible.","5 whole symbols and 1 half symbol."]',3,'Review Data Handling and Statistics to find the answer.','(6*5) = 5 symbols. 3 is exactly half a symbol.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0133','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'If a pictograph key says ''1 star = 1 learner'', how many learners do 7 stars represent?','["7","14","1","10"]',0,'Review Data Handling and Statistics to find the answer.','If 1 star = 1, then 7 stars = 7.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0134','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'Category A has 7 symbols. Category B has 5 symbols. The key is ''1 symbol = 2 items''. What is the exact difference between A and B?','["6 items","4 items","1 item","2 items"]',1,'Review Data Handling and Statistics to find the answer.','Difference is 2 symbols. 2 symbols x 2 = 4 items.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0135','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Why might a scientist choose to use ''1 symbol = 100'' instead of ''1 symbol = 1'' for a very large dataset?','["To prevent the graph from becoming too massive and unreadable with thousands of tiny symbols.","To make the data look smaller.","To hide the real numbers.","Because they don''t know how to draw."]',0,'Review Data Handling and Statistics to find the answer.','Scaling the key makes large datasets visually manageable.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0136','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'In a pictograph, if the ''Apples'' row has the most symbols, what does that mean?','["Apples are red.","Apples are the least popular.","The graph is broken.","Apples is the most popular/highest category."]',3,'Review Data Handling and Statistics to find the answer.','More symbols mean a higher frequency/value.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0137','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'Spot the error: A student counts 5 symbols in a pictograph and writes the total as ''5'', completely ignoring the key that says ''1 symbol = 10''.','["They should have multiplied the symbols by the key (5 x 10 = 50).","The total is actually 15.","Nothing is wrong.","They should have added 10."]',0,'Review Data Handling and Statistics to find the answer.','The value is always (Number of Symbols) x (Key Value).','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0138','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Row A has 14 symbols. Row B has 7 symbols. Key: ''1 symbol = 10''. What is the ratio of Row A to Row B?','["14 : 1","2 : 1","1 : 2","10 : 1"]',1,'Review Data Handling and Statistics to find the answer.','Row A has exactly twice as many symbols as Row B, so the ratio of values is 2:1.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0139','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'If a row in a pictograph has 5 symbols, and another has 3 symbols, which category is smaller?','["The one with fewer symbols.","The one with more symbols.","They are equal.","Cannot be determined."]',0,'Review Data Handling and Statistics to find the answer.','Fewer symbols represent a smaller value.','2026-11-03 15:38:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0140','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If a key says ''1 smiling face = 10 students'', what does HALF a smiling face represent?','["0 students","5 students","1 student","10 students"]',1,'Review Data Handling and Statistics to find the answer.','Half a symbol represents half of the key''s value.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0141','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'Spot the error: Avery makes a pictograph about favorite pets. The key says ''1 dog picture = 5 votes''. But Avery uses dog pictures for the cat row too.','["Dog pictures are only for dogs.","The symbols should ideally match the category, or a neutral symbol (like a star or smiley) should be used for the whole graph.","There is no error.","They should have used a cat picture with a different key value."]',1,'Review Data Handling and Statistics to find the answer.','Using a specific category''s icon for all rows can be highly confusing.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0142','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',1,'What do you MUST check before counting the pictures on a pictograph?','["The back of the page.","The colour of the pictures.","The date.","The Key."]',3,'Review Data Handling and Statistics to find the answer.','The key dictates the value of the pictures.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0143','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',5,'If the total for a category is 40 and the key is ''1 symbol = 8'', how many symbols are drawn?','["5","8","13","40"]',0,'Review Data Handling and Statistics to find the answer.','Divide total by key: 40 / 8 = 5.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0144','Maths','Data Handling and Statistics','Subtopic 4: Pictographs','Primary',10,'If a graph''s total value is 80 and there are 8 symbols drawn across the whole graph, what MUST the key value be?','["10","5","1","8"]',0,'Review Data Handling and Statistics to find the answer.','Total (80) / Symbols (8) = Key (10).','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0145','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What is a ''bar graph''?','["A table with no pictures.","A chart that uses rectangular bars to compare values across categories.","A graph with only wavy lines.","A circular pie chart."]',1,'Review Data Handling and Statistics to find the answer.','Bar graphs use vertical or horizontal rectangular bars.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0146','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'If a bar graph''s scale counts by 2s (0, 2, 4, 6...), and a bar stops exactly halfway between 20 and 22, what is its value?','["20","20.5","22","21"]',3,'Review Data Handling and Statistics to find the answer.','Halfway between an interval of 2 represents an addition of 1.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0147','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'A bar graph''s Y-axis is labeled ''Population (in thousands)''. The bar for City A reaches 10. What is the actual population of City A?','["0.01","10000","1000","10"]',1,'Review Data Handling and Statistics to find the answer.','The axis label acts as a multiplier. v1 * 1,000 = actual value.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0148','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What does the HEIGHT (or length) of a bar represent in a bar graph?','["The color of the category.","The value or frequency of that category.","The title of the graph.","The width of the bar."]',1,'Review Data Handling and Statistics to find the answer.','The bar extends to match the numerical value on the scale.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0149','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Bar A is 13 units tall. Bar B is 8 units tall. How much TALLER is Bar A than Bar B?','["21 units","13 units","8 units","5 units"]',3,'Review Data Handling and Statistics to find the answer.','13 - 8 = 5.','2026-11-03 15:38:06',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0150','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'What is a ''Horizontal Bar Graph''?','["A graph where all bars are the same height.","A graph where the categories are on the Y-axis and the bars stretch left-to-right along the X-axis.","A graph with no axes.","A graph that is lying down on a table."]',1,'Review Data Handling and Statistics to find the answer.','Horizontal bar graphs swap the axis roles compared to vertical ones.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0151','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What does the ''Title'' of a bar graph do?','["It shows the numbers.","It is just for decoration.","It tells you the date.","It explains exactly what the whole graph is about."]',3,'Review Data Handling and Statistics to find the answer.','The title describes the data being presented.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0152','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Spot the error: A student draws a bar graph but makes the ''Cats'' bar very wide and the ''Dogs'' bar very skinny, even though they have the same value.','["The ''Cats'' bar should be taller.","All bars in a bar graph should be the same width; only the height should change to show value.","Nothing is wrong.","The ''Dogs'' bar is wrong."]',1,'Review Data Handling and Statistics to find the answer.','Consistent bar width ensures fair visual comparison.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0153','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'Spot the error: A student''s Y-axis scale goes 0, 2, 5, 10, 20. Why is this graph mathematically invalid?','["The intervals on the scale are not equal (jumps of 2, 3, 5, 10). Scales must increase by a constant amount.","The numbers don''t go high enough.","They forgot the number 1.","They should have used a pictograph."]',0,'Review Data Handling and Statistics to find the answer.','A valid scale must have uniform, equal intervals.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0154','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'Where do you usually find the numbers you need to read the value of a bar?','["On the back of the page.","In the title.","On the vertical (or horizontal) axis scale.","Hidden behind the bars."]',2,'Review Data Handling and Statistics to find the answer.','The axis scale provides the numerical framework.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0155','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'A graph shows 3 categories: 13, 9, and 22. What is the TOTAL of all categories combined?','["22","27","44","117"]',2,'Review Data Handling and Statistics to find the answer.','13 + 9 + 22 = 44.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0156','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'If a total of 130 items are divided EQUALLY among 5 categories on a bar graph, how tall will each bar be?','["13","130","65","26"]',3,'Review Data Handling and Statistics to find the answer.','130 / 5 = 26.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0157','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'If the ''Red'' bar goes up to 9 and the ''Blue'' bar goes up to 3 (where 9 > 3), which category has a larger value?','["Cannot be determined","They are equal","Red","Blue"]',2,'Review Data Handling and Statistics to find the answer.','A taller bar indicates a larger value.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0158','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Why is it important for the axis scale to start at zero?','["So you can add the numbers faster.","Because zero is a round number.","If it doesn''t, the visual height of the bars will be misleading and exaggerate differences.","It isn''t important."]',2,'Review Data Handling and Statistics to find the answer.','A non-zero baseline distorts the visual proportion of the bars.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0159','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'Can a bar graph show fractions or decimals?','["Yes, the scale can accommodate any numerical value, and the bar can stop between whole numbers.","No, bar graphs are only for whole numbers.","No, rulers can''t measure fractions.","Yes, but only if it''s a pictograph."]',0,'Review Data Handling and Statistics to find the answer.','The Y-axis is a continuous number line.','2026-11-03 15:38:07',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0160','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'In a vertical bar graph, which direction do the bars point?','["Straight up.","Diagonal.","Left to right.","Downward."]',0,'Review Data Handling and Statistics to find the answer.','Vertical means pointing up/down.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0161','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'If a bar graph''s scale counts by 5s (0, 5, 10, 15...), where would a value of 10 line up?','["On the 2nd line.","Above the 15.","Halfway between 5 and 10.","Exactly on the line marked ''10''."]',3,'Review Data Handling and Statistics to find the answer.','10 is an exact interval mark.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0162','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'If Bar A is twice as tall as Bar B, and the scale starts at zero, what is the mathematical relationship between their values?','["The value of Category A is exactly double the value of Category B.","Category A is 2 units larger.","Category A is half of B.","They are equal."]',0,'Review Data Handling and Statistics to find the answer.','With a zero baseline, visual proportions match mathematical proportions (2:1).','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0163','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What is a ''bar graph''?','["A circular pie chart.","A graph with only wavy lines.","A table with no pictures.","A chart that uses rectangular bars to compare values across categories."]',3,'Review Data Handling and Statistics to find the answer.','Bar graphs use vertical or horizontal rectangular bars.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0164','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'If a bar graph''s scale counts by 2s (0, 2, 4, 6...), and a bar stops exactly halfway between 18 and 20, what is its value?','["19","20","18.5","18"]',0,'Review Data Handling and Statistics to find the answer.','Halfway between an interval of 2 represents an addition of 1.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0165','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'A bar graph''s Y-axis is labeled ''Population (in thousands)''. The bar for City A reaches 9. What is the actual population of City A?','["900","9000","9","0.009"]',0,'Review Data Handling and Statistics to find the answer.','The axis label acts as a multiplier. v1 * 1,000 = actual value.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0166','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What does the HEIGHT (or length) of a bar represent in a bar graph?','["The value or frequency of that category.","The width of the bar.","The title of the graph.","The color of the category."]',0,'Review Data Handling and Statistics to find the answer.','The bar extends to match the numerical value on the scale.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0167','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Bar A is 9 units tall. Bar B is 9 units tall. How much TALLER is Bar A than Bar B?','["9 units","18 units","0 units","9 units"]',2,'Review Data Handling and Statistics to find the answer.','9 - 9 = 0.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0168','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'What is a ''Horizontal Bar Graph''?','["A graph with no axes.","A graph that is lying down on a table.","A graph where the categories are on the Y-axis and the bars stretch left-to-right along the X-axis.","A graph where all bars are the same height."]',2,'Review Data Handling and Statistics to find the answer.','Horizontal bar graphs swap the axis roles compared to vertical ones.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0169','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'What does the ''Title'' of a bar graph do?','["It tells you the date.","It explains exactly what the whole graph is about.","It shows the numbers.","It is just for decoration."]',1,'Review Data Handling and Statistics to find the answer.','The title describes the data being presented.','2026-11-03 15:38:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0170','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Spot the error: A student draws a bar graph but makes the ''Cats'' bar very wide and the ''Dogs'' bar very skinny, even though they have the same value.','["Nothing is wrong.","All bars in a bar graph should be the same width; only the height should change to show value.","The ''Cats'' bar should be taller.","The ''Dogs'' bar is wrong."]',1,'Review Data Handling and Statistics to find the answer.','Consistent bar width ensures fair visual comparison.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0171','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'Spot the error: A student''s Y-axis scale goes 0, 2, 5, 10, 20. Why is this graph mathematically invalid?','["They forgot the number 1.","The numbers don''t go high enough.","The intervals on the scale are not equal (jumps of 2, 3, 5, 10). Scales must increase by a constant amount.","They should have used a pictograph."]',2,'Review Data Handling and Statistics to find the answer.','A valid scale must have uniform, equal intervals.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0172','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'Where do you usually find the numbers you need to read the value of a bar?','["On the back of the page.","On the vertical (or horizontal) axis scale.","In the title.","Hidden behind the bars."]',1,'Review Data Handling and Statistics to find the answer.','The axis scale provides the numerical framework.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0173','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'A graph shows 3 categories: 13, 2, and 15. What is the TOTAL of all categories combined?','["30","15","20","26"]',0,'Review Data Handling and Statistics to find the answer.','13 + 2 + 15 = 30.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0174','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'If a total of 130 items are divided EQUALLY among 5 categories on a bar graph, how tall will each bar be?','["130","13","26","65"]',2,'Review Data Handling and Statistics to find the answer.','130 / 5 = 26.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0175','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'If the ''Red'' bar goes up to 8 and the ''Blue'' bar goes up to 7 (where 8 > 7), which category has a larger value?','["Blue","Cannot be determined","Red","They are equal"]',2,'Review Data Handling and Statistics to find the answer.','A taller bar indicates a larger value.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0176','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'Why is it important for the axis scale to start at zero?','["If it doesn''t, the visual height of the bars will be misleading and exaggerate differences.","It isn''t important.","So you can add the numbers faster.","Because zero is a round number."]',0,'Review Data Handling and Statistics to find the answer.','A non-zero baseline distorts the visual proportion of the bars.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0177','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'Can a bar graph show fractions or decimals?','["No, bar graphs are only for whole numbers.","Yes, the scale can accommodate any numerical value, and the bar can stop between whole numbers.","Yes, but only if it''s a pictograph.","No, rulers can''t measure fractions."]',1,'Review Data Handling and Statistics to find the answer.','The Y-axis is a continuous number line.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0178','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',1,'In a vertical bar graph, which direction do the bars point?','["Left to right.","Downward.","Straight up.","Diagonal."]',2,'Review Data Handling and Statistics to find the answer.','Vertical means pointing up/down.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0179','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',5,'If a bar graph''s scale counts by 5s (0, 5, 10, 15...), where would a value of 10 line up?','["Above the 15.","Halfway between 5 and 10.","Exactly on the line marked ''10''.","On the 2nd line."]',2,'Review Data Handling and Statistics to find the answer.','10 is an exact interval mark.','2026-11-03 15:38:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0180','Maths','Data Handling and Statistics','Subtopic 5: Bar Graphs','Primary',10,'If Bar A is twice as tall as Bar B, and the scale starts at zero, what is the mathematical relationship between their values?','["Category A is half of B.","Category A is 2 units larger.","They are equal.","The value of Category A is exactly double the value of Category B."]',3,'Review Data Handling and Statistics to find the answer.','With a zero baseline, visual proportions match mathematical proportions (2:1).','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0181','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'What does a ''table'' do in mathematics?','["Draws a picture.","Calculates the final answer automatically.","Organizes information into neat rows and columns.","Makes a mess of the numbers."]',2,'Review Data Handling and Statistics to find the answer.','Tables structure data into a grid format.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0182','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'A frequency table lists 8 apples, 8 bananas, and 16 oranges. What is the TOTAL frequency?','["16","64","32","24"]',2,'Review Data Handling and Statistics to find the answer.','8 + 8 + 16 = 32.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0183','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'A two-way table shows Boys and Girls who like Math or Science. If 8 boys like Math and 8 boys like Science, what is the ''Row Total'' for Boys?','["8","8","16","64"]',2,'Review Data Handling and Statistics to find the answer.','Row Total = Sum of all cells in that row.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0184','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'In a table, which way do ''rows'' run?','["Horizontally (side to side).","In circles.","Diagonally.","Vertically (up and down)."]',0,'Review Data Handling and Statistics to find the answer.','Rows go left-to-right.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0185','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'If Skyler makes a frequency table from a list of 50 items, what must the sum of the frequency column be?','["100","10","50","0"]',2,'Review Data Handling and Statistics to find the answer.','The sum of frequencies MUST equal the total number of items collected.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0186','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'In a frequency table of test scores grouped into intervals (e.g., 80-89, 90-99), why is it impossible to know exactly who scored an 85?','["Because 85 is not a real score.","Because the table is wrong.","Because an 85 is in the 90-99 interval.","The table only shows how many scores fell into the 80-89 interval, losing individual data details."]',3,'Review Data Handling and Statistics to find the answer.','Grouped frequency tables summarize data but lose individual granularity.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0187','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'In a table, which way do ''columns'' run?','["Vertically (up and down).","In circles.","Horizontally (side to side).","Diagonally."]',0,'Review Data Handling and Statistics to find the answer.','Columns go top-to-bottom.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0188','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Spot the error: A student records 5 tally marks for ''Red'' but writes ''4'' in the frequency column.','["They forgot the heading.","The frequency number MUST exactly match the tally count.","They should have written 6.","Nothing is wrong."]',1,'Review Data Handling and Statistics to find the answer.','Tally count = Frequency integer.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0189','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'If a frequency table shows relative frequencies (percentages) that add up to 90%, what is the most likely error?','["A category was missed or the math is wrong, because percentages in a complete table must sum to 100%.","The data is perfect.","Percentages always sum to 90%.","10% evaporated."]',0,'Review Data Handling and Statistics to find the answer.','Complete relative frequency tables sum to 100% (or 1.0).','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0190','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'What is a ''frequency table''?','["A table with no numbers.","A table of random shapes.","A table of radio stations.","A table showing categories and a number count (frequency) of how often each occurred."]',3,'Review Data Handling and Statistics to find the answer.','Frequency tables log occurrences of data categories.','2026-11-03 15:38:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0191','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Category A has 11 votes. Category B has 6 votes. How many MORE votes does A have than B?','["5","17","11","6"]',0,'Review Data Handling and Statistics to find the answer.','11 - 6 = 5.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0192','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'You roll a 6-sided die 66 times and record the results in a frequency table. What should the sum of the frequency column be?','["11","66","6","36"]',1,'Review Data Handling and Statistics to find the answer.','The sum of frequencies equals the total number of trials.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0193','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'What do ''headings'' in a table do?','["They tell us exactly what information is in each row or column.","They hide the data.","They are just decorations.","They tell us the time."]',0,'Review Data Handling and Statistics to find the answer.','Headings label the data structure.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0194','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Why is converting raw data into a frequency table helpful?','["It is required by law.","It changes the data completely.","It makes the data invisible.","It makes it much easier to read, compare, and summarize the data quickly."]',3,'Review Data Handling and Statistics to find the answer.','Tables structure chaotic raw data into readable summaries.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0195','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'Spot the error: A student makes a frequency table of eye colors: Blue, Brown, Hazel, and ''Brown''.','["They forgot ''Green''.","They should use numbers instead of colors.","They have duplicate categories (''Brown''). Each category must be unique.","There is no error."]',2,'Review Data Handling and Statistics to find the answer.','Categories must be mutually exclusive and unique.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0196','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'If a table says ''Dogs: 6'', what is the frequency of dogs?','["6","Dogs","Cannot be determined","0"]',0,'Review Data Handling and Statistics to find the answer.','The number next to the category is its frequency.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0197','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'If you see a column labeled ''Tally'' in a frequency table, what will it contain?','["Only final numbers.","Lines or marks grouped in fives.","Only words.","A graph."]',1,'Review Data Handling and Statistics to find the answer.','The tally column holds the running count marks.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0198','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'What is a ''Cumulative Frequency'' column?','["A column for tally marks.","A running total that adds the frequencies of the current row to all previous rows.","A column that subtracts frequencies.","A column that only shows the highest frequency."]',1,'Review Data Handling and Statistics to find the answer.','Cumulative means adding up as you go down the table.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0199','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'What does a ''table'' do in mathematics?','["Calculates the final answer automatically.","Draws a picture.","Makes a mess of the numbers.","Organizes information into neat rows and columns."]',3,'Review Data Handling and Statistics to find the answer.','Tables structure data into a grid format.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0200','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'A frequency table lists 12 apples, 3 bananas, and 15 oranges. What is the TOTAL frequency?','["36","36","15","30"]',3,'Review Data Handling and Statistics to find the answer.','12 + 3 + 15 = 30.','2026-11-03 15:38:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0201','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'A two-way table shows Boys and Girls who like Math or Science. If 12 boys like Math and 3 boys like Science, what is the ''Row Total'' for Boys?','["15","36","3","12"]',0,'Review Data Handling and Statistics to find the answer.','Row Total = Sum of all cells in that row.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0202','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'In a table, which way do ''rows'' run?','["Vertically (up and down).","Horizontally (side to side).","Diagonally.","In circles."]',1,'Review Data Handling and Statistics to find the answer.','Rows go left-to-right.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0203','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'If Rowan makes a frequency table from a list of 45 items, what must the sum of the frequency column be?','["0","45","100","9"]',1,'Review Data Handling and Statistics to find the answer.','The sum of frequencies MUST equal the total number of items collected.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0204','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'In a frequency table of test scores grouped into intervals (e.g., 80-89, 90-99), why is it impossible to know exactly who scored an 85?','["The table only shows how many scores fell into the 80-89 interval, losing individual data details.","Because an 85 is in the 90-99 interval.","Because 85 is not a real score.","Because the table is wrong."]',0,'Review Data Handling and Statistics to find the answer.','Grouped frequency tables summarize data but lose individual granularity.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0205','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'In a table, which way do ''columns'' run?','["Diagonally.","Horizontally (side to side).","Vertically (up and down).","In circles."]',2,'Review Data Handling and Statistics to find the answer.','Columns go top-to-bottom.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0206','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Spot the error: A student records 5 tally marks for ''Red'' but writes ''4'' in the frequency column.','["The frequency number MUST exactly match the tally count.","They should have written 6.","Nothing is wrong.","They forgot the heading."]',0,'Review Data Handling and Statistics to find the answer.','Tally count = Frequency integer.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0207','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'If a frequency table shows relative frequencies (percentages) that add up to 90%, what is the most likely error?','["A category was missed or the math is wrong, because percentages in a complete table must sum to 100%.","Percentages always sum to 90%.","The data is perfect.","10% evaporated."]',0,'Review Data Handling and Statistics to find the answer.','Complete relative frequency tables sum to 100% (or 1.0).','2026-11-03 15:38:12',NULL,NULL);
