INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0209','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Category A has 6 votes. Category B has 7 votes. How many MORE votes does A have than B?','["13","7","6","-1"]',3,'Review Data Handling and Statistics to find the answer.','6 - 7 = -1.','2026-11-03 15:38:12',NULL,NULL);
