INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0211','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'What do ''headings'' in a table do?','["They are just decorations.","They hide the data.","They tell us the time.","They tell us exactly what information is in each row or column."]',3,'Review Data Handling and Statistics to find the answer.','Headings label the data structure.','2026-11-03 15:38:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0212','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'Why is converting raw data into a frequency table helpful?','["It changes the data completely.","It makes it much easier to read, compare, and summarize the data quickly.","It is required by law.","It makes the data invisible."]',1,'Review Data Handling and Statistics to find the answer.','Tables structure chaotic raw data into readable summaries.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0213','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'Spot the error: A student makes a frequency table of eye colors: Blue, Brown, Hazel, and ''Brown''.','["They forgot ''Green''.","They should use numbers instead of colors.","They have duplicate categories (''Brown''). Each category must be unique.","There is no error."]',2,'Review Data Handling and Statistics to find the answer.','Categories must be mutually exclusive and unique.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0214','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',1,'If a table says ''Dogs: 8'', what is the frequency of dogs?','["8","0","Cannot be determined","Dogs"]',0,'Review Data Handling and Statistics to find the answer.','The number next to the category is its frequency.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0215','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',5,'If you see a column labeled ''Tally'' in a frequency table, what will it contain?','["A graph.","Only words.","Lines or marks grouped in fives.","Only final numbers."]',2,'Review Data Handling and Statistics to find the answer.','The tally column holds the running count marks.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0216','Maths','Data Handling and Statistics','Subtopic 6: Tables and Frequency Tables','Primary',10,'What is a ''Cumulative Frequency'' column?','["A column that subtracts frequencies.","A column for tally marks.","A running total that adds the frequencies of the current row to all previous rows.","A column that only shows the highest frequency."]',2,'Review Data Handling and Statistics to find the answer.','Cumulative means adding up as you go down the table.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0217','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'What does it mean to ''interpret'' a graph?','["Just looking at the colors.","Drawing a new graph.","Throwing the graph away.","Using the information in the graph to answer questions or draw conclusions."]',3,'Review Data Handling and Statistics to find the answer.','Interpreting is extracting meaning from the visual data.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0218','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'A bar graph shows Casey read 28 books and Sam read 12 books. How many MORE books did Casey read?','["12","40","28","16"]',3,'Review Data Handling and Statistics to find the answer.','28 - 12 = 16.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0219','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'A graph shows Ice Cream sales by month. Sales peak in July and drop in December. What is a logical interpretation based on external knowledge?','["Ice cream sells better in hotter summer months than in cold winter months.","People hate ice cream.","July is the only month stores are open.","Ice cream is illegal in December."]',0,'Review Data Handling and Statistics to find the answer.','Data often correlates with real-world seasonal logic.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0220','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'If a question asks ''Which category is the greatest?'', what do you look for on a bar graph?','["The shortest bar.","The red bar.","The tallest (or longest) bar.","The widest bar."]',2,'Review Data Handling and Statistics to find the answer.','Tallest bar = greatest value.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0221','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'Why is it important to check the ''Scale'' before reading a bar graph?','["It tells you the colors.","The numbers might count by 2s, 5s, or 10s, not just 1s.","It isn''t important.","It tells you the title."]',1,'Review Data Handling and Statistics to find the answer.','Scales dictate the value of the bar''s height.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0222','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'A bar graph''s scale skips numbers: 0, 10, 20, 30. A bar stops exactly at the 3/4 mark between 10 and 20. What is its value?','["15","17.5","18","12.5"]',1,'Review Data Handling and Statistics to find the answer.','The gap is 10. 3/4 of 10 is 7.5. 10 + 7.5 = 17.5.','2026-11-03 15:38:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0223','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'If a question asks ''Which category is the least?'', what do you look for on a bar graph?','["The tallest bar.","The key.","The shortest (or smallest) bar.","The title."]',2,'Review Data Handling and Statistics to find the answer.','Shortest bar = lowest value.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0224','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'Spot the error: A student sees a graph where the ''Apples'' bar is taller than the ''Oranges'' bar. They conclude ''Everyone in the world hates oranges.''','["The conclusion is perfectly correct.","They did not add the numbers.","The conclusion is too broad; the graph only represents the small group surveyed, not the whole world.","They should have subtracted."]',2,'Review Data Handling and Statistics to find the answer.','Data conclusions must be limited to the sample population.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0225','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'Spot the error: Two graphs show the same data. Graph A''s Y-axis goes from 0 to 100. Graph B''s Y-axis goes from 50 to 60. A student says Graph B shows much bigger differences.','["Graph B''s truncated Y-axis visually exaggerates the differences, making small changes look massive.","The student is correct; Graph B has different data.","Graph B is a lie.","Graph A is broken."]',0,'Review Data Handling and Statistics to find the answer.','Truncating the Y-axis (not starting at zero) distorts visual proportions.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0226','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'A graph shows 15 dogs and 6 cats. How many pets are there ''altogether''?','["6","15","21","9"]',2,'Review Data Handling and Statistics to find the answer.','''Altogether'' means add them up.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0227','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'A pictograph key says 1 symbol = 5 items. If there are 15 symbols, what is the value?','["20","75","3","15"]',1,'Review Data Handling and Statistics to find the answer.','15 * 5 = 75.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0228','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'If Category X is 15% of a pie chart, Category Y is 6%, and Category Z is the rest, what percentage is Category Z?','["94%","79%","21%","85%"]',1,'Review Data Handling and Statistics to find the answer.','A full pie chart is 100%. 100 - (15 + 6) = 79.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0229','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'Which part of the graph tells you what the whole chart is about?','["The Key","The Title","The Y-axis","The X-axis"]',1,'Review Data Handling and Statistics to find the answer.','The Title summarizes the graph''s subject.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0230','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'If a graph shows temperatures over a week, what conclusion can you draw if the line goes down from Monday to Friday?','["The thermometer broke.","The temperature decreased over the week.","The temperature increased.","It was raining."]',1,'Review Data Handling and Statistics to find the answer.','A downward trend indicates a decrease in value.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0231','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'Why is reading the labels on the X and Y axes critical to interpreting a scatter plot?','["To know what color to use.","It isn''t; just look at the dots.","It tells you the author''s name.","Without labels, you wouldn''t know what the relationship or correlation being measured actually is."]',3,'Review Data Handling and Statistics to find the answer.','Axes define the variables being compared.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0232','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'If a graph asks ''How many more?'', what math operation should you use?','["Subtraction","Multiplication","Addition","Division"]',0,'Review Data Handling and Statistics to find the answer.','''How many more'' asks for the difference.','2026-11-03 15:38:14',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0233','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'Three bars have values of 5, 7, and 9. What is the total sum?','["5","11","15","21"]',3,'Review Data Handling and Statistics to find the answer.','5 + 7 + 9 = 21.','2026-11-03 15:38:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0234','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',10,'A graph shows Avery''s heart rate over 10 minutes of running. It starts at 80 bpm, peaks at 150 bpm at 8 minutes, and drops to 120 bpm at 10 minutes. What likely happened at 8 minutes?','["Avery fell asleep.","Avery ran faster.","The heart stopped.","Avery slowed down, stopped running, or entered a cool-down phase."]',3,'Review Data Handling and Statistics to find the answer.','A dropping heart rate indicates decreased physical exertion.','2026-11-03 15:38:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0235','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',1,'What does it mean to ''interpret'' a graph?','["Just looking at the colors.","Using the information in the graph to answer questions or draw conclusions.","Drawing a new graph.","Throwing the graph away."]',1,'Review Data Handling and Statistics to find the answer.','Interpreting is extracting meaning from the visual data.','2026-11-03 15:38:15',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0236','Maths','Data Handling and Statistics','Subtopic 7: Reading and Interpreting Graphs','Primary',5,'A bar graph shows Reese read 29 books and Sam read 9 books. How many MORE books did Reese read?','["38","29","20","9"]',2,'Review Data Handling and Statistics to find the answer.','29 - 9 = 20.','2026-11-03 15:38:15',NULL,NULL);
