INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0253','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'What does it mean to ''compare'' two data sets?','["To change the numbers.","To look at two groups of information to find similarities and differences.","To throw one data set away.","To add them both into a giant pile."]',1,'Review Data Handling and Statistics to find the answer.','Comparing means analyzing relationships between two sets.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0254','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Group A scored 49 points. Group B scored 28 points. What is the DIFFERENCE between their scores?','["21 points","28 points","49 points","77 points"]',0,'Review Data Handling and Statistics to find the answer.','49 - 28 = 21.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0255','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'School A (100 students) reads 490 books. School B (50 students) reads 280 books. Which school reads more books PER STUDENT?','["School A reads 4.9 per student; School B reads 5.6 per student. Compare those numbers.","School B always reads more.","They read the same.","School A always reads more."]',0,'Review Data Handling and Statistics to find the answer.','A average = 4.9. B average = 5.6.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0256','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'Data Set A has 39 items. Data Set B has 18 items. Which set has MORE items?','["Cannot be determined","Data Set B","Data Set A","They are equal"]',2,'Review Data Handling and Statistics to find the answer.','39 > 18.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0257','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Spot the error: A student compares ''Books read in 1 week'' for Class A to ''Books read in 1 YEAR'' for Class B, and says Class B reads faster.','["Class A actually reads faster.","The comparison is unfair because the time periods are completely different.","Class B definitely reads faster.","Nothing is wrong."]',1,'Review Data Handling and Statistics to find the answer.','Data sets must measure comparable metrics/timeframes to be valid.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0258','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'What does it mean if two data sets have the exact same ''mean'' (average) but a very different ''range'' (spread)?','["One set has zero in it.","It is impossible.","One set of numbers is tightly clustered together, while the other is spread out with extreme highs and lows.","They are exactly the same data set."]',2,'Review Data Handling and Statistics to find the answer.','Average measures center; range measures spread.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0259','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'When comparing the ''highest value'' in two different tables, what are you looking for?','["The title.","The single largest number in each table.","The middle number.","The smallest number."]',1,'Review Data Handling and Statistics to find the answer.','Highest value = largest number.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0260','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Table A has a highest value of 42 and lowest of 19. Table B has a highest of 52 and lowest of 14. Which table has a wider ''range'' (difference between high and low)?','["They are equal","Table B","Cannot be determined","Table A"]',1,'Review Data Handling and Statistics to find the answer.','A''s range = 23. B''s range = 38. B''s is much wider.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0261','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'Spot the error: A TV ad says ''Our brand sold 1,000 units! The competitor only sold 100!'' but fails to mention their brand is sold globally and the competitor is in one town.','["1,000 is always better.","The competitor is terrible.","This is a misleading comparison due to mismatched population sizes (market availability).","There is no error."]',2,'Review Data Handling and Statistics to find the answer.','Comparing totals across vastly different population sizes is statistically misleading.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0262','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'Class A reads 44 books. Class B reads 44 books. How do the data sets compare in total books?','["Class B is greater.","They are exactly equal.","They cannot be compared.","Class A is greater."]',1,'Review Data Handling and Statistics to find the answer.','Equal totals mean they are the same.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0263','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'If Category ''Red'' is the highest in Data Set 1, but Category ''Blue'' is the highest in Data Set 2, what can we conclude?','["Blue is the best color globally.","Red is the best color globally.","The data is broken.","The most popular choice is different between the two groups."]',3,'Review Data Handling and Statistics to find the answer.','Different groups can have different preferences or trends.','2026-11-03 15:38:17',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0264','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'Set A has 44 items that average $10 each. Set B has 25 items that average $20 each. Which set has a higher TOTAL value?','["Set A total = $440. Set B total = $500. Compare the two.","Set A ($440) is always higher.","They are equal.","Set B ($500) is always higher."]',0,'Review Data Handling and Statistics to find the answer.','Total = count x average. A=440, B=500.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0265','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'What is a ''Data Set''?','["A collection of related information or numbers.","A blank piece of paper.","A math symbol.","A type of television."]',0,'Review Data Handling and Statistics to find the answer.','A set of data is a collected group of facts/numbers.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0266','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Group A has 38 kids who like dogs and 18 who like cats. Group B has 18 who like dogs and 38 who like cats. Do they have the same TOTAL number of kids?','["Yes, the sum is the same.","Cannot be calculated.","No, Group B has more.","No, Group A has more."]',0,'Review Data Handling and Statistics to find the answer.','38+18 is equal to 18+38.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0267','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'If a scatter plot for Data Set 1 goes UP and a scatter plot for Data Set 2 goes DOWN, what is the difference in their ''correlation''?','["Set 1 has a positive correlation; Set 2 has a negative correlation.","They both have positive correlations.","Set 1 is broken.","They have no correlation."]',0,'Review Data Handling and Statistics to find the answer.','Upward slope = positive. Downward slope = negative.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0268','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'If you want to know how many MORE points Team A scored than Team B, what operation do you use?','["Subtraction","Division","Addition","Multiplication"]',0,'Review Data Handling and Statistics to find the answer.','Finding ''how many more'' requires finding the difference (subtraction).','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0269','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Why might it be unfair to compare the total number of goals scored by a team with 20 players to a team with only 5 players?','["Goals don''t count in data.","It is perfectly fair.","The smaller team always wins.","The larger team has an unfair advantage in total volume; an average per player would be a fairer comparison."]',3,'Review Data Handling and Statistics to find the answer.','Different sample sizes warp ''total'' comparisons. Rates or averages are better.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0270','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'Why is taking a ''Random Sample'' important when trying to compare two large populations?','["It prevents bias and ensures the data accurately represents the whole population.","It makes the math harder.","It guarantees everyone gives the same answer.","It means you only ask your friends."]',0,'Review Data Handling and Statistics to find the answer.','Random sampling removes selection bias for fair comparisons.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0271','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'What does it mean to ''compare'' two data sets?','["To change the numbers.","To look at two groups of information to find similarities and differences.","To add them both into a giant pile.","To throw one data set away."]',1,'Review Data Handling and Statistics to find the answer.','Comparing means analyzing relationships between two sets.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0272','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Group A scored 49 points. Group B scored 24 points. What is the DIFFERENCE between their scores?','["73 points","49 points","25 points","24 points"]',2,'Review Data Handling and Statistics to find the answer.','49 - 24 = 25.','2026-11-03 15:38:18',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0273','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'School A (100 students) reads 490 books. School B (50 students) reads 240 books. Which school reads more books PER STUDENT?','["School A always reads more.","They read the same.","School B always reads more.","School A reads 4.9 per student; School B reads 4.8 per student. Compare those numbers."]',3,'Review Data Handling and Statistics to find the answer.','A average = 4.9. B average = 4.8.','2026-11-03 15:38:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0274','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'Data Set A has 37 items. Data Set B has 20 items. Which set has MORE items?','["Data Set A","Cannot be determined","Data Set B","They are equal"]',0,'Review Data Handling and Statistics to find the answer.','37 > 20.','2026-11-03 15:38:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0275','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Spot the error: A student compares ''Books read in 1 week'' for Class A to ''Books read in 1 YEAR'' for Class B, and says Class B reads faster.','["Nothing is wrong.","The comparison is unfair because the time periods are completely different.","Class A actually reads faster.","Class B definitely reads faster."]',1,'Review Data Handling and Statistics to find the answer.','Data sets must measure comparable metrics/timeframes to be valid.','2026-11-03 15:38:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0276','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',10,'What does it mean if two data sets have the exact same ''mean'' (average) but a very different ''range'' (spread)?','["It is impossible.","They are exactly the same data set.","One set of numbers is tightly clustered together, while the other is spread out with extreme highs and lows.","One set has zero in it."]',2,'Review Data Handling and Statistics to find the answer.','Average measures center; range measures spread.','2026-11-03 15:38:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0277','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',1,'When comparing the ''highest value'' in two different tables, what are you looking for?','["The title.","The smallest number.","The single largest number in each table.","The middle number."]',2,'Review Data Handling and Statistics to find the answer.','Highest value = largest number.','2026-11-03 15:38:19',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t13_global_0278','Maths','Data Handling and Statistics','Subtopic 8: Comparing Data Sets','Primary',5,'Table A has a highest value of 41 and lowest of 19. Table B has a highest of 51 and lowest of 14. Which table has a wider ''range'' (difference between high and low)?','["Cannot be determined","They are equal","Table B","Table A"]',2,'Review Data Handling and Statistics to find the answer.','A''s range = 22. B''s range = 37. B''s is much wider.','2026-11-03 15:38:19',NULL,NULL);
