INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0026','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',5,'Jordan places a apple ''behind'' a chair. What does ''behind'' mean in this context?','["At the back of the chair.","In front of the chair.","At the side of the chair.","Inside the chair."]',0,'Review Position, Direction and Coordinates to find the answer.','Behind indicates the rear or back position.','2026-11-03 15:41:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0027','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',10,'A cup is inside a box. The box is inside a bag. The bag is on a desk. Which of the following is logically TRUE?','["The cup is inside the bag.","The cup is on the desk, not in the box.","The bag is inside the cup.","The desk is in the box."]',0,'Review Position, Direction and Coordinates to find the answer.','Nested containment applies transitively (cup is in box, box is in bag -> cup is in bag).','2026-11-03 15:41:23',NULL,NULL);
