INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0029','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',5,'True or False: The same object can be ''near'' one thing and ''far'' from another thing at the exact same time.','["False, an object can only be far from things.","False, an object can only be near things.","True, but only if the object is moving.","True, position words describe relative relationships to different reference points."]',3,'Review Position, Direction and Coordinates to find the answer.','Position is always relative to the chosen reference point.','2026-11-03 15:41:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0030','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',10,'If Jordan is standing facing North, and the school is directly ''in front of'' them, and the library is directly ''behind'' them, what is the relationship between the school and the library?','["The library is inside the school.","The school is South of the library.","They are beside each other.","The school is North of the library."]',3,'Review Position, Direction and Coordinates to find the answer.','Facing North: Front is North, Behind is South. The school is North relative to the person and the library.','2026-11-03 15:41:23',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0031','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',1,'If a toy is ''near'' a desk, what does that mean?','["It is floating.","It is the exact same thing as the desk.","It is a long distance away.","It is a short distance away."]',3,'Review Position, Direction and Coordinates to find the answer.','Near means close by or a short distance away.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0032','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',5,'If object A is in front of object B, where is object B compared to object A?','["Object B is inside.","Object B is also in front.","Object B is behind object A.","Object B is far away."]',2,'Review Position, Direction and Coordinates to find the answer.','Front and behind are opposite relative positions.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0033','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',10,'How can the word ''outside'' be used to describe two very different positional distances?','["It only applies to weather.","It just means ''not within'', so the object could be right next to the container or miles away.","It only means exactly 1 meter away.","It means the object is broken."]',1,'Review Position, Direction and Coordinates to find the answer.','''Outside'' just defines non-containment, giving no specific distance.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0034','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',1,'What is a ''reference point''?','["A sharp point on a pencil.","A dot on a piece of paper.","Something we use to help describe the position of another object.","A scoring system in a game."]',2,'Review Position, Direction and Coordinates to find the answer.','Reference points give context to positional descriptions.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0035','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',5,'If a car moves from being beside a tree to being in front of the tree, what has changed?','["The tree''s position.","Its position relative to the tree.","The car''s size.","The car''s color."]',1,'Review Position, Direction and Coordinates to find the answer.','Moving changes an object''s relative location.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0036','Maths','Position, Direction and Coordinates','Subtopic 1: Position and Location','Primary',10,'If Object X is between Y and Z, and you are standing directly in front of X looking at it, where might Y and Z be relative to your vision?','["Both are above you.","Both are inside X.","Both are behind you.","One is to your left and one is to your right."]',3,'Review Position, Direction and Coordinates to find the answer.','If X is between them and you face X, they flank X laterally.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0037','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'Which side of your body is the ''left'' side?','["The side where your left hand is.","The side where your right hand is.","The top of your head.","Your feet."]',0,'Review Position, Direction and Coordinates to find the answer.','Left is relative to your own left hand/side.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0038','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'If a picture is above a desk, where is the desk compared to the picture?','["Below the picture.","To the right.","To the left.","Above the picture."]',0,'Review Position, Direction and Coordinates to find the answer.','Above and below are opposite vertical positions.','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0039','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'A grid has shapes: A is above B, and B is to the left of C. What is the spatial relationship between A and C?','["A is exactly between B and C.","A is above and to the left of C.","A is below and to the right of C.","A is below C."]',1,'Review Position, Direction and Coordinates to find the answer.','Combine the vertical (above B, so above C''s row) and horizontal (B is left of C, so A is left of C''s column).','2026-11-03 15:41:24',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0040','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'What does the word ''above'' mean?','["At a lower position.","At a higher position.","Inside.","To the side."]',1,'Review Position, Direction and Coordinates to find the answer.','Above indicates higher vertical placement.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0041','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'You and a friend are standing face-to-face. Your left hand is opposite which of your friend''s hands?','["Their right hand.","Both hands.","Neither hand.","Their left hand."]',0,'Review Position, Direction and Coordinates to find the answer.','When facing opposite directions, left and right are mirrored.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0042','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'Spot the error: A map app tells you to ''Turn right''. Your friend says ''But East is that way!'' Why is your friend confused?','["They don''t know left from right.","Right is always East.","They are confusing geographic directions (East) with relative body directions (Right).","Maps only use North."]',2,'Review Position, Direction and Coordinates to find the answer.','''Right'' depends on current facing direction, not a compass.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0043','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'What does the word ''below'' mean?','["Outside.","In the middle.","At a higher position.","At a lower position."]',3,'Review Position, Direction and Coordinates to find the answer.','Below indicates lower vertical placement.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0044','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'Avery is facing the teacher''s board. The door is on Avery''s left. If Avery turns completely around (half-turn), where is the door now?','["On their right.","Above them.","Still on their left.","Below them."]',0,'Review Position, Direction and Coordinates to find the answer.','Turning 180 degrees swaps your relative left and right.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0045','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'If Shape X is below Shape Y, and Shape Y is below Shape Z, what must be true?','["Shape Y is above Shape Z.","Shape Z is below Shape X.","They are all side-by-side.","Shape X is below Shape Z."]',3,'Review Position, Direction and Coordinates to find the answer.','Transitive property of vertical placement.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0046','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'On a standard grid or piece of paper, where is ''above'' usually considered to be?','["Towards the left side.","Towards the top of the page.","Towards the right side.","Towards the bottom of the page."]',1,'Review Position, Direction and Coordinates to find the answer.','Standard 2D convention makes ''up/above'' the top of the page.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0047','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'In a grid with 3 columns, a star is in the left column and a moon is in the middle column. Where is the moon compared to the star?','["Below the star.","To the left of the star.","To the right of the star.","Above the star."]',2,'Review Position, Direction and Coordinates to find the answer.','Middle is to the right of the left column.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0048','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'If Jamie looks in a mirror and raises their right hand, which hand does the mirror image appear to raise?','["Both hands.","Neither hand.","Its right hand.","Its left hand."]',3,'Review Position, Direction and Coordinates to find the answer.','Mirrors reflect front-to-back, which reverses the perceived left/right of the reflection.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0049','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'On a standard grid or piece of paper, where is ''left'' usually considered to be?','["Towards the left side of the page.","Towards the bottom.","Towards the top of the page.","Towards the right side."]',0,'Review Position, Direction and Coordinates to find the answer.','Standard convention matches the reader''s left.','2026-11-03 15:41:25',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0050','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'Why does a person''s ''viewpoint'' matter when describing left and right?','["Because left and right change depending on the time of day.","Because it changes their height.","It doesn''t matter; left is always North.","Because left and right change depending on which way a person is facing."]',3,'Review Position, Direction and Coordinates to find the answer.','Left and right are egocentric (body-relative) directions.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0051','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'Imagine a 2x2 grid (4 squares). If Square 1 is top-left, and Square 4 is bottom-right. How do you move from 1 to 4?','["Move one space below.","Move right, then move below (or below, then right).","Move exactly one space right.","Move left, then above."]',1,'Review Position, Direction and Coordinates to find the answer.','Top-left to bottom-right requires one horizontal right step and one vertical down/below step.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0052','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'If Jordan draws a bird higher than a tree, where is the bird compared to the tree?','["Inside the tree","Above the tree","Behind the tree","Below the tree"]',1,'Review Position, Direction and Coordinates to find the answer.','Higher up means above.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0053','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'If you are instructed to ''Draw a square to the right of a circle'', how should the paper look?','["Circle above the Square.","Square on the left, Circle on the right.","Square above the Circle.","Circle on the left, Square on the right."]',3,'Review Position, Direction and Coordinates to find the answer.','Right means further toward the right side of the page.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0054','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'Why is ''above'' and ''below'' generally absolute on a 2D piece of paper, while ''left'' and ''right'' can be confusing in real life?','["Left and right don''t exist on paper.","Gravity doesn''t work on paper.","Paper is heavier.","Paper has a fixed top/bottom orientation, but people can face any direction in real life."]',3,'Review Position, Direction and Coordinates to find the answer.','The page creates a fixed 2D coordinate system, unlike 3D body orientation.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0055','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',1,'Which side of your body is the ''left'' side?','["The side where your left hand is.","The top of your head.","Your feet.","The side where your right hand is."]',0,'Review Position, Direction and Coordinates to find the answer.','Left is relative to your own left hand/side.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0056','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'If a picture is above a desk, where is the desk compared to the picture?','["To the left.","Above the picture.","Below the picture.","To the right."]',2,'Review Position, Direction and Coordinates to find the answer.','Above and below are opposite vertical positions.','2026-11-03 15:41:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0057','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'A grid has shapes: A is above B, and B is to the left of C. What is the spatial relationship between A and C?','["A is above and to the left of C.","A is exactly between B and C.","A is below and to the right of C.","A is below C."]',0,'Review Position, Direction and Coordinates to find the answer.','Combine the vertical (above B, so above C''s row) and horizontal (B is left of C, so A is left of C''s column).','2026-11-03 15:41:26',NULL,NULL);
