INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0071','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',5,'If you are instructed to ''Draw a square to the right of a circle'', how should the paper look?','["Circle on the left, Square on the right.","Circle above the Square.","Square on the left, Circle on the right.","Square above the Circle."]',0,'Review Position, Direction and Coordinates to find the answer.','Right means further toward the right side of the page.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0072','Maths','Position, Direction and Coordinates','Subtopic 2: Left, Right, Above and Below','Primary',10,'Why is ''above'' and ''below'' generally absolute on a 2D piece of paper, while ''left'' and ''right'' can be confusing in real life?','["Paper has a fixed top/bottom orientation, but people can face any direction in real life.","Gravity doesn''t work on paper.","Left and right don''t exist on paper.","Paper is heavier."]',0,'Review Position, Direction and Coordinates to find the answer.','The page creates a fixed 2D coordinate system, unlike 3D body orientation.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0073','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What are the four main geographic directions?','["Up, Down, Left, Right","Red, Blue, Green, Yellow","North, South, East, West","Forward, Backward, Sideways, Stop"]',2,'Review Position, Direction and Coordinates to find the answer.','N, S, E, W are the cardinal directions.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0074','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'A robot faces North. It moves forward 7 steps. Which geographic direction did it travel?','["East","South","West","North"]',3,'Review Position, Direction and Coordinates to find the answer.','Forward while facing North means traveling North.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0075','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'A robot faces North. It turns 90° clockwise, moves 7 steps forward, turns 90° clockwise again, and moves 3 steps forward. What is its final position relative to the start?','["7 steps North and 3 steps East","7 steps East and 3 steps South","3 steps West","Exactly where it started"]',1,'Review Position, Direction and Coordinates to find the answer.','Turn 1 = facing East (moves East). Turn 2 = facing South (moves South).','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0076','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'On a standard map, if North is at the top, which direction is at the BOTTOM?','["East","South","West","North"]',1,'Review Position, Direction and Coordinates to find the answer.','South is opposite North.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0077','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'If you are facing North and make a ''half-turn'' (180°), which direction are you facing now?','["North","South","East","West"]',1,'Review Position, Direction and Coordinates to find the answer.','A half-turn flips you to the exact opposite direction.','2026-11-03 15:41:28',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0078','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'Spot the error: A student says ''I moved 5 steps North, then 5 steps Left, so I am 5 steps North and 5 steps East of where I started.''','["The math is perfect.","Left is South.","They are exactly where they started.","Facing North, ''Left'' is West, not East. They are 5 steps West."]',3,'Review Position, Direction and Coordinates to find the answer.','North''s left is West.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0079','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'On a standard map, if North is at the top, which direction is to the RIGHT?','["East","West","North","South"]',0,'Review Position, Direction and Coordinates to find the answer.','East is to the right of North.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0080','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'A counter moves 7 spaces East, and then 1 spaces West. Where is it relative to its starting point?','["Exactly where it started","6 spaces East","1 spaces West","8 spaces East"]',1,'Review Position, Direction and Coordinates to find the answer.','East and West cancel out. 7 - 1 = 6 East.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0081','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'If a compass needle points North, and you rotate the compass casing a quarter-turn clockwise, where does the needle point in the real world?','["It points South.","It still points North; the magnetic field hasn''t changed, only the casing moved.","It points East.","It points West."]',1,'Review Position, Direction and Coordinates to find the answer.','A compass needle aligns with magnetic North regardless of casing orientation.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0082','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What does it mean to move ''Forward''?','["To move backwards.","To spin in a circle.","To move left.","To move towards the direction you are currently facing."]',3,'Review Position, Direction and Coordinates to find the answer.','Forward is movement along your line of sight.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0083','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'What does ''Clockwise'' mean?','["Turning in the opposite direction of clock hands.","Turning in the same direction as the hands of a clock.","Walking forward.","Standing perfectly still."]',1,'Review Position, Direction and Coordinates to find the answer.','Clockwise follows the 12, 1, 2, 3... pattern.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0084','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'Quinn makes three quarter-turns (270°) clockwise. What is a faster way to achieve the exact same facing direction?','["Make a full turn (360°).","Walk backwards.","Make one quarter-turn (90°) anticlockwise.","Make a half-turn (180°)."]',2,'Review Position, Direction and Coordinates to find the answer.','3/4 clockwise = 1/4 anticlockwise.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0085','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What is a ''route''?','["The path followed from one place to another.","A stopped car.","A type of tree root.","A dead end."]',0,'Review Position, Direction and Coordinates to find the answer.','A route is a path of travel.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0086','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'If Jamie faces East and makes a quarter-turn (90°) anticlockwise, which way is Jamie facing?','["West","North","East","South"]',1,'Review Position, Direction and Coordinates to find the answer.','Anticlockwise from East goes ''up'' to North.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0087','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'If a character on a grid moves 4 spaces East, 4 spaces North, 4 spaces West, and 4 spaces South, where do they end up?','["At the origin (0,0).","16 spaces North.","4 spaces East.","Exactly at their starting point."]',3,'Review Position, Direction and Coordinates to find the answer.','The equal and opposite movements form a closed square loop.','2026-11-03 15:41:29',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0088','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What is a ''quarter-turn''?','["A turn of 90 degrees.","Walking backwards.","A turn of 360 degrees.","Looking up."]',0,'Review Position, Direction and Coordinates to find the answer.','A quarter turn is 1/4 of a full circle (90°).','2026-11-03 15:41:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0089','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'Why does the ORDER of movement instructions on a grid matter?','["Because it changes the colors of the grid.","It doesn''t matter; you always end up in the same spot.","Because you must always move North first.","Because changing the order of turns and steps will usually result in a completely different final position."]',3,'Review Position, Direction and Coordinates to find the answer.','Path dependence: turning then stepping is different from stepping then turning.','2026-11-03 15:41:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0090','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'How many degrees are in a ''three-quarter turn''?','["270°","180°","90°","360°"]',0,'Review Position, Direction and Coordinates to find the answer.','90° * 3 = 270°.','2026-11-03 15:41:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0091','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What are the four main geographic directions?','["Red, Blue, Green, Yellow","Forward, Backward, Sideways, Stop","North, South, East, West","Up, Down, Left, Right"]',2,'Review Position, Direction and Coordinates to find the answer.','N, S, E, W are the cardinal directions.','2026-11-03 15:41:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0092','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'A robot faces North. It moves forward 6 steps. Which geographic direction did it travel?','["South","East","West","North"]',3,'Review Position, Direction and Coordinates to find the answer.','Forward while facing North means traveling North.','2026-11-03 15:41:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0093','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'A robot faces North. It turns 90° clockwise, moves 6 steps forward, turns 90° clockwise again, and moves 2 steps forward. What is its final position relative to the start?','["2 steps West","Exactly where it started","6 steps North and 2 steps East","6 steps East and 2 steps South"]',3,'Review Position, Direction and Coordinates to find the answer.','Turn 1 = facing East (moves East). Turn 2 = facing South (moves South).','2026-11-03 15:41:31',NULL,NULL);
