INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0102','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'Jamie makes three quarter-turns (270°) clockwise. What is a faster way to achieve the exact same facing direction?','["Make a full turn (360°).","Walk backwards.","Make a half-turn (180°).","Make one quarter-turn (90°) anticlockwise."]',3,'Review Position, Direction and Coordinates to find the answer.','3/4 clockwise = 1/4 anticlockwise.','2026-11-03 15:41:32',NULL,NULL);
