INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0105','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'If a character on a grid moves 8 spaces East, 8 spaces North, 8 spaces West, and 8 spaces South, where do they end up?','["Exactly at their starting point.","8 spaces East.","32 spaces North.","At the origin (0,0)."]',0,'Review Position, Direction and Coordinates to find the answer.','The equal and opposite movements form a closed square loop.','2026-11-03 15:41:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0106','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',1,'What is a ''quarter-turn''?','["A turn of 360 degrees.","Walking backwards.","A turn of 90 degrees.","Looking up."]',2,'Review Position, Direction and Coordinates to find the answer.','A quarter turn is 1/4 of a full circle (90°).','2026-11-03 15:41:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0107','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',5,'Why does the ORDER of movement instructions on a grid matter?','["Because you must always move North first.","It doesn''t matter; you always end up in the same spot.","Because it changes the colors of the grid.","Because changing the order of turns and steps will usually result in a completely different final position."]',3,'Review Position, Direction and Coordinates to find the answer.','Path dependence: turning then stepping is different from stepping then turning.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0108','Maths','Position, Direction and Coordinates','Subtopic 3: Direction and Movement','Primary',10,'How many degrees are in a ''three-quarter turn''?','["180°","360°","90°","270°"]',3,'Review Position, Direction and Coordinates to find the answer.','90° * 3 = 270°.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0109','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What is a ''map''?','["A type of calculator.","A drawing that represents an area or place to help us locate things.","A random pattern.","A storybook."]',1,'Review Position, Direction and Coordinates to find the answer.','Maps are visual representations of geography/spaces.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0110','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'In a grid with columns A,B,C and rows 1,2,3, where exactly is cell D2?','["In column 2 and row D.","In the exact center.","Off the map.","In column D and row 2."]',3,'Review Position, Direction and Coordinates to find the answer.','The letter dictates the column, the number dictates the row.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0111','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'A grid starts at A1 in the top-left. Quinn starts at C3. They move 2 cells Left, and 1 cell Up. What is their new cell reference?','["E4","D4","A2","B2"]',2,'Review Position, Direction and Coordinates to find the answer.','Left from C is A (C->B->A). Up from 3 is 2 (assuming 1 is top row).','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0112','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What is a ''grid''?','["A single straight line.","A completely blank circle.","A pattern of horizontal rows and vertical columns.","A triangle."]',2,'Review Position, Direction and Coordinates to find the answer.','Grids divide space into coordinate boxes.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0113','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If Taylor starts at A1 on a map grid and moves 2 columns to the right, what column are they in now?','["Column B","Column A","Column D","Column C"]',3,'Review Position, Direction and Coordinates to find the answer.','A -> B -> C (2 moves).','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0114','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'Why must you ALWAYS check a map''s ''orientation'' (like a compass rose) before following a route?','["To see what colors were used.","Because maps change shape.","Because the map might be upside down.","Because ''Up'' on the paper might not be North, and ''Right'' might not be East."]',3,'Review Position, Direction and Coordinates to find the answer.','Orientation defines how page-directions map to geographic-directions.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0115','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'In a grid, what is a horizontal line of boxes called?','["A column","A cell","A row","A key"]',2,'Review Position, Direction and Coordinates to find the answer.','Rows go left-to-right (horizontally).','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0116','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'Why do maps use symbols instead of drawing highly detailed pictures of real buildings?','["Symbols save space, make the map less cluttered, and are easier to read.","Symbols are required by law.","To make the map a secret code.","Because mapmakers can''t draw."]',0,'Review Position, Direction and Coordinates to find the answer.','Symbols abstract complex realities into readable icons.','2026-11-03 15:41:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0117','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'If two entirely different routes on a grid start at A1 and end at D4, what must be true about the total number of East/West and North/South steps?','["It is impossible to have two routes.","They must use different vehicles.","The NET horizontal and vertical steps must be identical, even if taken in a different order.","One route must be much longer."]',2,'Review Position, Direction and Coordinates to find the answer.','Displacement is independent of the path taken.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0118','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'In a grid, what is a vertical line of boxes called?','["A row","A key","A column","A cell"]',2,'Review Position, Direction and Coordinates to find the answer.','Columns go up-and-down (vertically).','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0119','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If Sam is at B2 on a grid, and the treasure is at B4, how should Sam move to get there?','["Move 2 cells right.","Move 1 cell down.","Move 2 cells left.","Move 2 cells down (or up, depending on row numbering)."]',3,'Review Position, Direction and Coordinates to find the answer.','The column (B) stays the same, only the row changes by 2.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0120','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'A map has a scale of 1 cell = 10 meters. If a route takes 4 steps East and 3 steps North, what is the total distance walked?','["50 meters","7 meters","10 meters","70 meters"]',3,'Review Position, Direction and Coordinates to find the answer.','Total steps = 7. 7 * 10m = 70m walked.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0121','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What does a ''map key'' (or legend) do?','["It draws the map for you.","It unlocks a real door.","It tells you the date.","It explains the meaning of the symbols used on the map."]',3,'Review Position, Direction and Coordinates to find the answer.','A key translates symbols to real-world meanings.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0122','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If a park map has the ''Pond'' to the right of the ''Garden'', and the ''Cafe'' to the right of the ''Pond'', where is the Cafe compared to the Garden?','["To the right of the Garden.","To the left of the Garden.","Above the Garden.","Inside the Garden."]',0,'Review Position, Direction and Coordinates to find the answer.','Relative positions are transitive along a straight line.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0123','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'Spot the error: ''The treasure is at C4, so I will walk diagonally across the grid lines to get there faster.'' What is wrong with this in standard grid-movement?','["You can''t walk on maps.","Standard grid movement usually restricts you to orthogonal (horizontal/vertical) moves between cells, not diagonal cutting.","Diagonals are slower.","C4 is a trap."]',1,'Review Position, Direction and Coordinates to find the answer.','Manhattan distance (grid movement) forbids diagonal shortcuts.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0124','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What do we call one individual box in a grid?','["A cell","A legend","A row","A column"]',0,'Review Position, Direction and Coordinates to find the answer.','A cell is a single grid unit.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0125','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'Spot the error: A student says ''Cell 3C'' when asked for a location. Why is this technically wrong on a standard alphanumeric grid?','["There is no letter C.","Grids only use colors.","There is no number 3.","The convention is usually Column Letter first, then Row Number (C3)."]',3,'Review Position, Direction and Coordinates to find the answer.','Alphanumeric grid references traditionally put the letter first (like Battleship).','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0126','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'If a map legend shows a green triangle for ''Mountain'' and a blue wavy line for ''River'', how do you interpret a cell with a green triangle next to a blue line?','["It means it''s raining.","The mountain is floating on water.","There is a mountain located next to a river.","It''s a mistake."]',2,'Review Position, Direction and Coordinates to find the answer.','Combining symbols visually indicates geographic proximity.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0127','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What is a ''map''?','["A random pattern.","A drawing that represents an area or place to help us locate things.","A storybook.","A type of calculator."]',1,'Review Position, Direction and Coordinates to find the answer.','Maps are visual representations of geography/spaces.','2026-11-03 15:41:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0128','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'In a grid with columns A,B,C and rows 1,2,3, where exactly is cell E2?','["In the exact center.","In column E and row 2.","Off the map.","In column 2 and row E."]',1,'Review Position, Direction and Coordinates to find the answer.','The letter dictates the column, the number dictates the row.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0129','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'A grid starts at A1 in the top-left. Reese starts at C3. They move 2 cells Left, and 1 cell Up. What is their new cell reference?','["B2","D4","A2","E4"]',2,'Review Position, Direction and Coordinates to find the answer.','Left from C is A (C->B->A). Up from 3 is 2 (assuming 1 is top row).','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0130','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'What is a ''grid''?','["A single straight line.","A pattern of horizontal rows and vertical columns.","A triangle.","A completely blank circle."]',1,'Review Position, Direction and Coordinates to find the answer.','Grids divide space into coordinate boxes.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0131','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If Quinn starts at A1 on a map grid and moves 2 columns to the right, what column are they in now?','["Column B","Column C","Column D","Column A"]',1,'Review Position, Direction and Coordinates to find the answer.','A -> B -> C (2 moves).','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0132','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'Why must you ALWAYS check a map''s ''orientation'' (like a compass rose) before following a route?','["To see what colors were used.","Because maps change shape.","Because ''Up'' on the paper might not be North, and ''Right'' might not be East.","Because the map might be upside down."]',2,'Review Position, Direction and Coordinates to find the answer.','Orientation defines how page-directions map to geographic-directions.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0133','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'In a grid, what is a horizontal line of boxes called?','["A cell","A key","A column","A row"]',3,'Review Position, Direction and Coordinates to find the answer.','Rows go left-to-right (horizontally).','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0134','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'Why do maps use symbols instead of drawing highly detailed pictures of real buildings?','["Symbols are required by law.","To make the map a secret code.","Because mapmakers can''t draw.","Symbols save space, make the map less cluttered, and are easier to read."]',3,'Review Position, Direction and Coordinates to find the answer.','Symbols abstract complex realities into readable icons.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0135','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'If two entirely different routes on a grid start at A1 and end at D4, what must be true about the total number of East/West and North/South steps?','["It is impossible to have two routes.","The NET horizontal and vertical steps must be identical, even if taken in a different order.","One route must be much longer.","They must use different vehicles."]',1,'Review Position, Direction and Coordinates to find the answer.','Displacement is independent of the path taken.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0136','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',1,'In a grid, what is a vertical line of boxes called?','["A row","A column","A key","A cell"]',1,'Review Position, Direction and Coordinates to find the answer.','Columns go up-and-down (vertically).','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0137','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If Sam is at B2 on a grid, and the treasure is at B4, how should Sam move to get there?','["Move 1 cell down.","Move 2 cells left.","Move 2 cells right.","Move 2 cells down (or up, depending on row numbering)."]',3,'Review Position, Direction and Coordinates to find the answer.','The column (B) stays the same, only the row changes by 2.','2026-11-03 15:41:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0138','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'A map has a scale of 1 cell = 10 meters. If a route takes 4 steps East and 3 steps North, what is the total distance walked?','["10 meters","70 meters","7 meters","50 meters"]',1,'Review Position, Direction and Coordinates to find the answer.','Total steps = 7. 7 * 10m = 70m walked.','2026-11-03 15:41:36',NULL,NULL);
