INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0140','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',5,'If a park map has the ''Pond'' to the right of the ''Garden'', and the ''Cafe'' to the right of the ''Pond'', where is the Cafe compared to the Garden?','["To the left of the Garden.","To the right of the Garden.","Inside the Garden.","Above the Garden."]',1,'Review Position, Direction and Coordinates to find the answer.','Relative positions are transitive along a straight line.','2026-11-03 15:41:36',NULL,NULL);
