INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0144','Maths','Position, Direction and Coordinates','Subtopic 4: Using Simple Maps and Grids','Primary',10,'If a map legend shows a green triangle for ''Mountain'' and a blue wavy line for ''River'', how do you interpret a cell with a green triangle next to a blue line?','["It''s a mistake.","The mountain is floating on water.","There is a mountain located next to a river.","It means it''s raining."]',2,'Review Position, Direction and Coordinates to find the answer.','Combining symbols visually indicates geographic proximity.','2026-11-03 15:41:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0145','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'What is an ''ordered pair''?','["A fraction.","A pair of shoes.","Any two random letters.","Two numbers written in a specific order inside brackets, like (x, y)."]',3,'Review Position, Direction and Coordinates to find the answer.','Ordered pairs designate specific coordinate points.','2026-11-03 15:41:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0146','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'What does the ordered pair (2, 1) mean on a standard grid?','["Move 1 units right, and 2 units up.","Move 2 units to the right, and 1 units up from the origin.","Just draw a dot anywhere.","Move 2 left and 1 down."]',1,'Review Position, Direction and Coordinates to find the answer.','Always right (x) then up (y) on a positive grid.','2026-11-03 15:41:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0147','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Sam starts at (2, 1) and moves 2 units to the RIGHT, what is the new ordered pair?','["(4, 1)","(0, 1)","(4, 3)","(2, 3)"]',0,'Review Position, Direction and Coordinates to find the answer.','Moving right adds to the x-coordinate.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0148','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (x, y), what does the FIRST number (x) tell you?','["The vertical position (up/down).","The color of the point.","The size of the point.","The horizontal position (left/right)."]',3,'Review Position, Direction and Coordinates to find the answer.','The x-coordinate is horizontal.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0149','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Are the points (9, 6) and (6, 9) in the exact same location?','["No, one is a circle and one is a square.","No, changing the order usually changes the location (unless x and y are the same number).","Yes, they are always the same.","Yes, because the numbers are the same."]',1,'Review Position, Direction and Coordinates to find the answer.','Order matters! (x,y) != (y,x).','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0150','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Skyler starts at (9, 6) and moves 3 units UP, what is the new ordered pair?','["(9, 3)","(12, 6)","(9, 9)","(12, 9)"]',2,'Review Position, Direction and Coordinates to find the answer.','Moving up adds to the y-coordinate.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0151','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (x, y), what does the SECOND number (y) tell you?','["The color of the point.","The size of the point.","The vertical position (up/down).","The horizontal position (left/right)."]',2,'Review Position, Direction and Coordinates to find the answer.','The y-coordinate is vertical.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0152','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'If a point is exactly 7 units to the right of the origin, and sits flat on the x-axis, what are its coordinates?','["(7, 7)","(0, 0)","(7, 0)","(0, 7)"]',2,'Review Position, Direction and Coordinates to find the answer.','Sitting on the x-axis means vertical movement (y) is 0.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0153','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'Spot the error: A treasure map says the gold is at (7, 2). A pirate says ''We need to walk 7 meters North and 2 meters East!''','["Standard grids define x as East (horizontal) and y as North (vertical). The pirate reversed them.","The gold is actually at (0,0).","You can''t use meters on a grid.","The pirate is correct."]',0,'Review Position, Direction and Coordinates to find the answer.','x is horizontal (East/West), y is vertical (North/South).','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0154','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (9, 6), what is the x-coordinate?','["6","15","0","9"]',3,'Review Position, Direction and Coordinates to find the answer.','The first number is x.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0155','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'If a point is exactly 6 units straight up from the origin, sitting on the y-axis, what are its coordinates?','["(6, 6)","(6, 0)","(0, 6)","(0, 0)"]',2,'Review Position, Direction and Coordinates to find the answer.','Sitting on the y-axis means horizontal movement (x) is 0.','2026-11-03 15:41:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0156','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'What is the mathematical difference between a ''cell reference'' (like A1 in a spreadsheet) and an ''ordered pair'' (like (1, 1))?','["There is no difference.","Cell references use numbers only.","Ordered pairs only use letters.","Cell references label an entire box/area; ordered pairs label an exact, infinitely small point on an intersection."]',3,'Review Position, Direction and Coordinates to find the answer.','Cells are areas; coordinates are exact points.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0157','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (9, 2), what is the y-coordinate?','["0","11","9","2"]',3,'Review Position, Direction and Coordinates to find the answer.','The second number is y.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0158','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Spot the error: A student is told to find (3, 5). They go UP 3 units, and RIGHT 5 units.','["They started at the wrong corner.","They mixed up x and y. You must go RIGHT 3, and UP 5.","They should have subtracted.","They are perfectly correct."]',1,'Review Position, Direction and Coordinates to find the answer.','Always run before you jump (x then y).','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0159','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Point A is at (0, 0) and Point B is at (9, 9), what type of geometric line connects them?','["A horizontal line.","A perfectly diagonal straight line.","A vertical line.","A curved line."]',1,'Review Position, Direction and Coordinates to find the answer.','When x and y change equally, it creates a 45-degree diagonal.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0160','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'What do we call the point (0, 0) where the x-axis and y-axis meet?','["The Zero Point","The Origin","The Center","The Apex"]',1,'Review Position, Direction and Coordinates to find the answer.','The origin is the starting point of the grid.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0161','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Why are brackets ( ) used when writing ordered pairs?','["To group the two numbers together as a single mathematical location.","Because they are negative.","To make them look pretty.","To show they are a fraction."]',0,'Review Position, Direction and Coordinates to find the answer.','Brackets denote a single coordinate entity.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0162','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'Why is the point (0,0) called the ''Origin''?','["It is the starting point from which all other coordinate distances are measured.","It is the end of the grid.","Because it was discovered first.","Because zero is a circle."]',0,'Review Position, Direction and Coordinates to find the answer.','Origin means ''the point where something begins''.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0163','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'What is an ''ordered pair''?','["A pair of shoes.","Any two random letters.","A fraction.","Two numbers written in a specific order inside brackets, like (x, y)."]',3,'Review Position, Direction and Coordinates to find the answer.','Ordered pairs designate specific coordinate points.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0164','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'What does the ordered pair (9, 9) mean on a standard grid?','["Move 9 left and 9 down.","Just draw a dot anywhere.","Move 9 units right, and 9 units up.","Move 9 units to the right, and 9 units up from the origin."]',3,'Review Position, Direction and Coordinates to find the answer.','Always right (x) then up (y) on a positive grid.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0165','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Taylor starts at (9, 9) and moves 2 units to the RIGHT, what is the new ordered pair?','["(7, 9)","(9, 11)","(11, 9)","(11, 11)"]',2,'Review Position, Direction and Coordinates to find the answer.','Moving right adds to the x-coordinate.','2026-11-03 15:41:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0166','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (x, y), what does the FIRST number (x) tell you?','["The horizontal position (left/right).","The vertical position (up/down).","The color of the point.","The size of the point."]',0,'Review Position, Direction and Coordinates to find the answer.','The x-coordinate is horizontal.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0167','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Are the points (8, 6) and (6, 8) in the exact same location?','["No, one is a circle and one is a square.","Yes, because the numbers are the same.","No, changing the order usually changes the location (unless x and y are the same number).","Yes, they are always the same."]',2,'Review Position, Direction and Coordinates to find the answer.','Order matters! (x,y) != (y,x).','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0168','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Sam starts at (8, 6) and moves 3 units UP, what is the new ordered pair?','["(11, 6)","(11, 9)","(8, 9)","(8, 3)"]',2,'Review Position, Direction and Coordinates to find the answer.','Moving up adds to the y-coordinate.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0169','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (x, y), what does the SECOND number (y) tell you?','["The color of the point.","The size of the point.","The vertical position (up/down).","The horizontal position (left/right)."]',2,'Review Position, Direction and Coordinates to find the answer.','The y-coordinate is vertical.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0170','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'If a point is exactly 6 units to the right of the origin, and sits flat on the x-axis, what are its coordinates?','["(6, 0)","(0, 0)","(6, 6)","(0, 6)"]',0,'Review Position, Direction and Coordinates to find the answer.','Sitting on the x-axis means vertical movement (y) is 0.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0171','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'Spot the error: A treasure map says the gold is at (6, 7). A pirate says ''We need to walk 6 meters North and 7 meters East!''','["You can''t use meters on a grid.","Standard grids define x as East (horizontal) and y as North (vertical). The pirate reversed them.","The gold is actually at (0,0).","The pirate is correct."]',1,'Review Position, Direction and Coordinates to find the answer.','x is horizontal (East/West), y is vertical (North/South).','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0172','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (9, 4), what is the x-coordinate?','["9","13","4","0"]',0,'Review Position, Direction and Coordinates to find the answer.','The first number is x.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0173','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'If a point is exactly 4 units straight up from the origin, sitting on the y-axis, what are its coordinates?','["(0, 4)","(4, 0)","(4, 4)","(0, 0)"]',0,'Review Position, Direction and Coordinates to find the answer.','Sitting on the y-axis means horizontal movement (x) is 0.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0174','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'What is the mathematical difference between a ''cell reference'' (like A1 in a spreadsheet) and an ''ordered pair'' (like (1, 1))?','["Cell references label an entire box/area; ordered pairs label an exact, infinitely small point on an intersection.","There is no difference.","Ordered pairs only use letters.","Cell references use numbers only."]',0,'Review Position, Direction and Coordinates to find the answer.','Cells are areas; coordinates are exact points.','2026-11-03 15:41:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0175','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'In the ordered pair (4, 2), what is the y-coordinate?','["4","0","6","2"]',3,'Review Position, Direction and Coordinates to find the answer.','The second number is y.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0176','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Spot the error: A student is told to find (3, 5). They go UP 3 units, and RIGHT 5 units.','["They should have subtracted.","They are perfectly correct.","They mixed up x and y. You must go RIGHT 3, and UP 5.","They started at the wrong corner."]',2,'Review Position, Direction and Coordinates to find the answer.','Always run before you jump (x then y).','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0177','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'If Point A is at (0, 0) and Point B is at (4, 4), what type of geometric line connects them?','["A curved line.","A perfectly diagonal straight line.","A horizontal line.","A vertical line."]',1,'Review Position, Direction and Coordinates to find the answer.','When x and y change equally, it creates a 45-degree diagonal.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0178','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',1,'What do we call the point (0, 0) where the x-axis and y-axis meet?','["The Zero Point","The Origin","The Center","The Apex"]',1,'Review Position, Direction and Coordinates to find the answer.','The origin is the starting point of the grid.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0179','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',5,'Why are brackets ( ) used when writing ordered pairs?','["To make them look pretty.","To group the two numbers together as a single mathematical location.","To show they are a fraction.","Because they are negative."]',1,'Review Position, Direction and Coordinates to find the answer.','Brackets denote a single coordinate entity.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0180','Maths','Position, Direction and Coordinates','Subtopic 7: Ordered Pairs — Introductory','Primary',10,'Why is the point (0,0) called the ''Origin''?','["Because zero is a circle.","Because it was discovered first.","It is the starting point from which all other coordinate distances are measured.","It is the end of the grid."]',2,'Review Position, Direction and Coordinates to find the answer.','Origin means ''the point where something begins''.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0181','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'What does ''plotting a point'' mean?','["Drawing a random circle.","Coloring the whole grid.","Marking an exact position on a coordinate grid using an ordered pair.","Erasing a line."]',2,'Review Position, Direction and Coordinates to find the answer.','Plotting is precisely placing a point based on coordinates.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0182','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'Spot the error: A student is told to plot (4, 0). They start at (0,0) and move 4 units UP the y-axis.','["They moved vertically instead of horizontally. (4, 0) should be 4 units RIGHT along the x-axis.","They should have moved 4 units left.","The point is correct.","They forgot to draw a square."]',0,'Review Position, Direction and Coordinates to find the answer.','The first number (4) is x (horizontal). y is 0 (no vertical movement).','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0183','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'You plot Point A at (2, 2) and Point B at (6, 2). If you connect them, what kind of line segment do you draw, and how long is it?','["A diagonal line that is 8 units long.","A horizontal line segment that is 4 units long.","A vertical line that is 4 units long.","A horizontal line that is 8 units long."]',1,'Review Position, Direction and Coordinates to find the answer.','y is constant (2), so it''s horizontal. 6 - 2 = 4 units.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0184','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Which axis is the horizontal (left-to-right) line on a grid?','["The y-axis","The x-axis","The z-axis","The origin"]',1,'Review Position, Direction and Coordinates to find the answer.','The x-axis is horizontal.','2026-11-03 15:41:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0185','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'If Rowan plots a point exactly on the y-axis, what MUST the x-coordinate be?','["0","10","1","It could be anything."]',0,'Review Position, Direction and Coordinates to find the answer.','To stay on the y-axis, there can be zero horizontal movement.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0186','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'You plot three points: (5, 1), (5, 5), and (5, 9). If you connect them in order, what do you get?','["A perfectly straight horizontal line.","A triangle.","A curved line.","A perfectly straight vertical line."]',3,'Review Position, Direction and Coordinates to find the answer.','Since x is constant, all points align vertically.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0187','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Which axis is the vertical (up-and-down) line on a grid?','["The origin","The x-axis","The y-axis","The z-axis"]',2,'Review Position, Direction and Coordinates to find the answer.','The y-axis is vertical.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0188','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'When you plot a point on a coordinate grid, where exactly do you draw the dot?','["In the middle of the empty white square.","Exactly where the grid lines cross (at the intersection).","Off the page.","On the x-axis only."]',1,'Review Position, Direction and Coordinates to find the answer.','Coordinates refer to grid line intersections, not cell spaces.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0189','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'Spot the error: A student counts the empty white boxes instead of the grid lines to plot (4, 4).','["Counting boxes is the correct way.","They should count backwards.","They should use a ruler.","Counting boxes (cells) instead of line intersections leads to inaccurate point placement on standard coordinate grids."]',3,'Review Position, Direction and Coordinates to find the answer.','Coordinates denote intersections (0, 1, 2 lines) not areas (boxes).','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0190','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Where must you ALWAYS start when plotting a point on a coordinate grid?','["At (1,1).","At the origin (0,0).","At the top right corner.","Anywhere you like."]',1,'Review Position, Direction and Coordinates to find the answer.','All movements begin at the (0,0) origin.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0191','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'What should you always write next to a point after you plot it?','["Your name.","Its label or ordered pair (e.g., ({x}, {y})).","The date.","A smiley face."]',1,'Review Position, Direction and Coordinates to find the answer.','Labeling points prevents confusion when multiple points are plotted.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0192','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'If you plot (0, 0), (0, 4), (4, 4), and (4, 0), and connect them with straight lines, what shape do you create?','["A square with a side length of 4 units.","A circle.","A rectangle.","A triangle."]',0,'Review Position, Direction and Coordinates to find the answer.','The points form 4 right angles and 4 equal sides of length 4.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0193','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'To plot (2, 4), which direction do you move FIRST?','["Move left.","Move diagonally.","Move 2 units to the right along the x-axis.","Move 4 units up along the y-axis."]',2,'Review Position, Direction and Coordinates to find the answer.','Always perform horizontal (x) movement first.','2026-11-03 15:41:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0194','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'If Rowan wants to plot (2, 4) but accidentally plots (4, 2), how will the dot''s position look compared to the correct one?','["It will be off the page.","It will be in a completely different spot, reflected across a diagonal line.","It will be invisible.","It will be exactly the same."]',1,'Review Position, Direction and Coordinates to find the answer.','Swapping x and y drastically changes the location.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0195','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'A point is plotted at (2, 4). You are told to ''translate'' (slide) it 3 units left. What is the new coordinate?','["(-1, 4)","(2, 1)","(5, 4)","(-1, 1)"]',0,'Review Position, Direction and Coordinates to find the answer.','Moving left reduces the x-coordinate by 3.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0196','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'To plot (7, 5), which direction do you move SECOND?','["Move 7 units right.","Move diagonally.","Move left.","Move 5 units up, parallel to the y-axis."]',3,'Review Position, Direction and Coordinates to find the answer.','Vertical (y) movement happens after horizontal.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0197','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'Why is ''run before you jump'' a good trick for plotting points?','["It means y comes before x.","It reminds you to exercise.","It reminds you to move horizontally (x) before moving vertically (y).","It means you should plot fast."]',2,'Review Position, Direction and Coordinates to find the answer.','It''s a mnemonic for x (run horizontal) then y (jump vertical).','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0198','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'Why is the intersection of the x-axis and y-axis always labeled (0,0)?','["Because it represents zero distance moved in both the horizontal and vertical directions.","Because circles look like zeros.","Because you start with zero points.","It was a random choice."]',0,'Review Position, Direction and Coordinates to find the answer.','The origin is the geometric zero-point for all measurements.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0199','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'What does ''plotting a point'' mean?','["Marking an exact position on a coordinate grid using an ordered pair.","Drawing a random circle.","Erasing a line.","Coloring the whole grid."]',0,'Review Position, Direction and Coordinates to find the answer.','Plotting is precisely placing a point based on coordinates.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0200','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'Spot the error: A student is told to plot (4, 0). They start at (0,0) and move 4 units UP the y-axis.','["The point is correct.","They should have moved 4 units left.","They forgot to draw a square.","They moved vertically instead of horizontally. (4, 0) should be 4 units RIGHT along the x-axis."]',3,'Review Position, Direction and Coordinates to find the answer.','The first number (4) is x (horizontal). y is 0 (no vertical movement).','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0201','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'You plot Point A at (2, 2) and Point B at (6, 2). If you connect them, what kind of line segment do you draw, and how long is it?','["A vertical line that is 4 units long.","A horizontal line that is 8 units long.","A diagonal line that is 8 units long.","A horizontal line segment that is 4 units long."]',3,'Review Position, Direction and Coordinates to find the answer.','y is constant (2), so it''s horizontal. 6 - 2 = 4 units.','2026-11-03 15:41:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0202','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Which axis is the horizontal (left-to-right) line on a grid?','["The z-axis","The y-axis","The origin","The x-axis"]',3,'Review Position, Direction and Coordinates to find the answer.','The x-axis is horizontal.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0203','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'If Morgan plots a point exactly on the y-axis, what MUST the x-coordinate be?','["0","1","It could be anything.","10"]',0,'Review Position, Direction and Coordinates to find the answer.','To stay on the y-axis, there can be zero horizontal movement.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0204','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'You plot three points: (3, 1), (3, 5), and (3, 9). If you connect them in order, what do you get?','["A perfectly straight horizontal line.","A perfectly straight vertical line.","A triangle.","A curved line."]',1,'Review Position, Direction and Coordinates to find the answer.','Since x is constant, all points align vertically.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0205','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Which axis is the vertical (up-and-down) line on a grid?','["The y-axis","The x-axis","The origin","The z-axis"]',0,'Review Position, Direction and Coordinates to find the answer.','The y-axis is vertical.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0206','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'When you plot a point on a coordinate grid, where exactly do you draw the dot?','["Exactly where the grid lines cross (at the intersection).","In the middle of the empty white square.","On the x-axis only.","Off the page."]',0,'Review Position, Direction and Coordinates to find the answer.','Coordinates refer to grid line intersections, not cell spaces.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0207','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'Spot the error: A student counts the empty white boxes instead of the grid lines to plot (2, 2).','["They should use a ruler.","Counting boxes (cells) instead of line intersections leads to inaccurate point placement on standard coordinate grids.","Counting boxes is the correct way.","They should count backwards."]',1,'Review Position, Direction and Coordinates to find the answer.','Coordinates denote intersections (0, 1, 2 lines) not areas (boxes).','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0208','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'Where must you ALWAYS start when plotting a point on a coordinate grid?','["At (1,1).","At the top right corner.","Anywhere you like.","At the origin (0,0)."]',3,'Review Position, Direction and Coordinates to find the answer.','All movements begin at the (0,0) origin.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0209','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'What should you always write next to a point after you plot it?','["Its label or ordered pair (e.g., ({x}, {y})).","Your name.","A smiley face.","The date."]',0,'Review Position, Direction and Coordinates to find the answer.','Labeling points prevents confusion when multiple points are plotted.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0210','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'If you plot (0, 0), (0, 4), (4, 4), and (4, 0), and connect them with straight lines, what shape do you create?','["A triangle.","A rectangle.","A circle.","A square with a side length of 4 units."]',3,'Review Position, Direction and Coordinates to find the answer.','The points form 4 right angles and 4 equal sides of length 4.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0211','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'To plot (7, 4), which direction do you move FIRST?','["Move 7 units to the right along the x-axis.","Move diagonally.","Move left.","Move 4 units up along the y-axis."]',0,'Review Position, Direction and Coordinates to find the answer.','Always perform horizontal (x) movement first.','2026-11-03 15:41:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0212','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'If Morgan wants to plot (7, 4) but accidentally plots (4, 7), how will the dot''s position look compared to the correct one?','["It will be exactly the same.","It will be off the page.","It will be in a completely different spot, reflected across a diagonal line.","It will be invisible."]',2,'Review Position, Direction and Coordinates to find the answer.','Swapping x and y drastically changes the location.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0213','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'A point is plotted at (7, 4). You are told to ''translate'' (slide) it 3 units left. What is the new coordinate?','["(7, 1)","(10, 4)","(4, 4)","(4, 1)"]',2,'Review Position, Direction and Coordinates to find the answer.','Moving left reduces the x-coordinate by 3.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0214','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',1,'To plot (3, 7), which direction do you move SECOND?','["Move 3 units right.","Move 7 units up, parallel to the y-axis.","Move diagonally.","Move left."]',1,'Review Position, Direction and Coordinates to find the answer.','Vertical (y) movement happens after horizontal.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0215','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',5,'Why is ''run before you jump'' a good trick for plotting points?','["It reminds you to exercise.","It means y comes before x.","It reminds you to move horizontally (x) before moving vertically (y).","It means you should plot fast."]',2,'Review Position, Direction and Coordinates to find the answer.','It''s a mnemonic for x (run horizontal) then y (jump vertical).','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0216','Maths','Position, Direction and Coordinates','Subtopic 8: Plotting Points on a Grid','Primary',10,'Why is the intersection of the x-axis and y-axis always labeled (0,0)?','["Because it represents zero distance moved in both the horizontal and vertical directions.","Because you start with zero points.","Because circles look like zeros.","It was a random choice."]',0,'Review Position, Direction and Coordinates to find the answer.','The origin is the geometric zero-point for all measurements.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0217','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'What does the word ''quadrant'' mean in a coordinate grid?','["One of the four regions formed by the crossing of the x and y axes.","A quarter of a circle.","A type of square.","A 4-sided shape."]',0,'Review Position, Direction and Coordinates to find the answer.','Quad means 4; axes divide the grid into 4 regions.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0218','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Compare Point A at (2, 8) and Point B at (6, 8). Which point is farther to the RIGHT?','["Neither.","Point A, because 2 is smaller.","They are in the exact same spot.","Point B, because its x-coordinate (6) is larger."]',3,'Review Position, Direction and Coordinates to find the answer.','Larger x means further right.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0219','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'If you are in the First Quadrant and you move left until your x-coordinate drops below zero, what happens?','["You enter the Third Quadrant.","You fall off the grid.","You cross the y-axis and enter the Second Quadrant (where x is negative, y is positive).","You enter the Fourth Quadrant."]',2,'Review Position, Direction and Coordinates to find the answer.','Top-left is Quadrant II.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0220','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'Where is the ''First Quadrant'' located on a standard math grid?','["In the dead center.","In the upper-left region.","In the upper-right region.","In the lower-left region."]',2,'Review Position, Direction and Coordinates to find the answer.','Quadrant I is top-right.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0221','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Compare Point C at (9, 3) and Point D at (9, 8). Which point is HIGHER?','["Point D, because its y-coordinate (8) is larger.","Point C, because 3 is smaller.","They are at the same height.","Cannot be determined."]',0,'Review Position, Direction and Coordinates to find the answer.','Larger y means higher up.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0222','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'Point P is at (9, 3). You reflect (flip) Point P exactly across the y-axis. Is the new point still in the First Quadrant?','["Yes, it just moves higher.","No, reflecting across the y-axis makes the x-coordinate negative, moving it out of the First Quadrant.","No, it moves to the Fourth Quadrant.","Yes, it moves to (0,0)."]',1,'Review Position, Direction and Coordinates to find the answer.','Reflection across y negates x.','2026-11-03 15:41:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0223','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'In the First Quadrant, what is true about BOTH the x and y coordinates?','["They are both positive numbers.","They are both zero.","One is positive, one is negative.","They are both negative numbers."]',0,'Review Position, Direction and Coordinates to find the answer.','Right is positive x, Up is positive y.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0224','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Spot the error: A student says the point (0, 0) is in the very middle of the First Quadrant.','["Nothing is wrong.","It should be (1,1).","The origin is in the Second Quadrant.","(0,0) is the Origin. It is the bottom-left corner boundary of the First Quadrant, not the middle."]',3,'Review Position, Direction and Coordinates to find the answer.','The origin anchors the corner, it isn''t the center of the quadrant area.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0225','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'A rectangle is drawn entirely inside the First Quadrant. Its bottom-left corner is at (2,2). Its top-right corner is at (6,5). What are the coordinates of the other two corners?','["(4,3) and (4,3).","(0,0) and (8,7).","(2,6) and (5,2).","(6,2) and (2,5)."]',3,'Review Position, Direction and Coordinates to find the answer.','Corners share x and y coordinates: (x2, y1) and (x1, y2).','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0226','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'Is the point (3, 3) located inside the First Quadrant?','["No, it is in the second quadrant.","Yes, because both numbers are positive.","Cannot be determined.","No, it is on the axis."]',1,'Review Position, Direction and Coordinates to find the answer.','Positive x and positive y put it in Quadrant I.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0227','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'If Reese plots (3, 3) and wants to move it strictly to the left but stay inside the First Quadrant, what must happen?','["The x-coordinate must decrease, but must stay greater than 0.","The x-coordinate must become negative.","The y-coordinate must become zero.","The y-coordinate must increase."]',0,'Review Position, Direction and Coordinates to find the answer.','Moving left reduces x. Quadrant I requires x > 0.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0228','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'Spot the error: Reese says that any point with a zero in it, like (3, 0), is in the First Quadrant because 3 is positive.','["0 is not a number.","It is in the Fourth Quadrant.","Points with a zero lie ON the boundary axes, so they are not strictly INSIDE any quadrant.","They should be negative."]',2,'Review Position, Direction and Coordinates to find the answer.','Axes form the borders between quadrants.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0229','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'If a point has a ''0'' for its x-coordinate, like (0, 5), is it INSIDE the First Quadrant?','["Yes, 0 is a positive number.","Yes, it is in the middle.","No, it is sitting exactly on the y-axis, not inside the quadrant.","No, it is in the second quadrant."]',2,'Review Position, Direction and Coordinates to find the answer.','Points on the boundary lines (axes) are not strictly inside the quadrants.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0230','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Why do primary school math problems usually only use the First Quadrant?','["Because paper isn''t big enough.","Because the other quadrants are illegal.","Because it only uses positive numbers, which are easier to learn first.","Because negative numbers don''t exist."]',2,'Review Position, Direction and Coordinates to find the answer.','It avoids the complexity of negative integer coordinates.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0231','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'If you draw a line from (1,1) to (10,10) in the First Quadrant, what is the mathematical relationship between x and y for every single point on that line?','["x is always greater than y.","x plus y equals 10.","x times y equals 1.","x is always exactly equal to y (x = y)."]',3,'Review Position, Direction and Coordinates to find the answer.','A 45-degree diagonal from the origin implies x=y.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0232','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'If you want to move HIGHER in the First Quadrant, which coordinate must get larger?','["The x-coordinate.","Both coordinates.","Neither.","The y-coordinate."]',3,'Review Position, Direction and Coordinates to find the answer.','y controls vertical height.','2026-11-03 15:41:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0233','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'What Roman Numeral is used to identify the First Quadrant?','["II","IV","V","I"]',0,'Review Position, Direction and Coordinates to find the answer.','Quadrants are labeled I, II, III, IV.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0234','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'How are the four quadrants numbered?','["Left to right, top to bottom.","Clockwise, starting from the upper-right.","Randomly.","Anticlockwise, starting from the upper-right (I, II, III, IV)."]',3,'Review Position, Direction and Coordinates to find the answer.','Mathematical convention numbers them counter-clockwise.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0235','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'What does the word ''quadrant'' mean in a coordinate grid?','["A type of square.","A quarter of a circle.","A 4-sided shape.","One of the four regions formed by the crossing of the x and y axes."]',3,'Review Position, Direction and Coordinates to find the answer.','Quad means 4; axes divide the grid into 4 regions.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0236','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Compare Point A at (2, 2) and Point B at (6, 2). Which point is farther to the RIGHT?','["They are in the exact same spot.","Neither.","Point A, because 2 is smaller.","Point B, because its x-coordinate (6) is larger."]',3,'Review Position, Direction and Coordinates to find the answer.','Larger x means further right.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0237','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'If you are in the First Quadrant and you move left until your x-coordinate drops below zero, what happens?','["You cross the y-axis and enter the Second Quadrant (where x is negative, y is positive).","You enter the Fourth Quadrant.","You enter the Third Quadrant.","You fall off the grid."]',0,'Review Position, Direction and Coordinates to find the answer.','Top-left is Quadrant II.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0238','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'Where is the ''First Quadrant'' located on a standard math grid?','["In the upper-right region.","In the lower-left region.","In the dead center.","In the upper-left region."]',0,'Review Position, Direction and Coordinates to find the answer.','Quadrant I is top-right.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0239','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Compare Point C at (8, 3) and Point D at (8, 8). Which point is HIGHER?','["Cannot be determined.","Point C, because 3 is smaller.","They are at the same height.","Point D, because its y-coordinate (8) is larger."]',3,'Review Position, Direction and Coordinates to find the answer.','Larger y means higher up.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0240','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'Point P is at (8, 3). You reflect (flip) Point P exactly across the y-axis. Is the new point still in the First Quadrant?','["No, reflecting across the y-axis makes the x-coordinate negative, moving it out of the First Quadrant.","No, it moves to the Fourth Quadrant.","Yes, it just moves higher.","Yes, it moves to (0,0)."]',0,'Review Position, Direction and Coordinates to find the answer.','Reflection across y negates x.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0241','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'In the First Quadrant, what is true about BOTH the x and y coordinates?','["One is positive, one is negative.","They are both zero.","They are both positive numbers.","They are both negative numbers."]',2,'Review Position, Direction and Coordinates to find the answer.','Right is positive x, Up is positive y.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0242','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Spot the error: A student says the point (0, 0) is in the very middle of the First Quadrant.','["It should be (1,1).","(0,0) is the Origin. It is the bottom-left corner boundary of the First Quadrant, not the middle.","The origin is in the Second Quadrant.","Nothing is wrong."]',1,'Review Position, Direction and Coordinates to find the answer.','The origin anchors the corner, it isn''t the center of the quadrant area.','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0243','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'A rectangle is drawn entirely inside the First Quadrant. Its bottom-left corner is at (2,2). Its top-right corner is at (6,5). What are the coordinates of the other two corners?','["(4,3) and (4,3).","(0,0) and (8,7).","(6,2) and (2,5).","(2,6) and (5,2)."]',2,'Review Position, Direction and Coordinates to find the answer.','Corners share x and y coordinates: (x2, y1) and (x1, y2).','2026-11-03 15:41:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0244','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'Is the point (8, 2) located inside the First Quadrant?','["No, it is on the axis.","Cannot be determined.","No, it is in the second quadrant.","Yes, because both numbers are positive."]',3,'Review Position, Direction and Coordinates to find the answer.','Positive x and positive y put it in Quadrant I.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0245','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'If Riley plots (8, 2) and wants to move it strictly to the left but stay inside the First Quadrant, what must happen?','["The y-coordinate must become zero.","The x-coordinate must become negative.","The y-coordinate must increase.","The x-coordinate must decrease, but must stay greater than 0."]',3,'Review Position, Direction and Coordinates to find the answer.','Moving left reduces x. Quadrant I requires x > 0.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0246','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'Spot the error: Riley says that any point with a zero in it, like (8, 0), is in the First Quadrant because 8 is positive.','["It is in the Fourth Quadrant.","Points with a zero lie ON the boundary axes, so they are not strictly INSIDE any quadrant.","0 is not a number.","They should be negative."]',1,'Review Position, Direction and Coordinates to find the answer.','Axes form the borders between quadrants.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0247','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'If a point has a ''0'' for its x-coordinate, like (0, 5), is it INSIDE the First Quadrant?','["No, it is sitting exactly on the y-axis, not inside the quadrant.","Yes, it is in the middle.","Yes, 0 is a positive number.","No, it is in the second quadrant."]',0,'Review Position, Direction and Coordinates to find the answer.','Points on the boundary lines (axes) are not strictly inside the quadrants.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0248','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'Why do primary school math problems usually only use the First Quadrant?','["Because the other quadrants are illegal.","Because paper isn''t big enough.","Because it only uses positive numbers, which are easier to learn first.","Because negative numbers don''t exist."]',2,'Review Position, Direction and Coordinates to find the answer.','It avoids the complexity of negative integer coordinates.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0249','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'If you draw a line from (1,1) to (10,10) in the First Quadrant, what is the mathematical relationship between x and y for every single point on that line?','["x times y equals 1.","x plus y equals 10.","x is always exactly equal to y (x = y).","x is always greater than y."]',2,'Review Position, Direction and Coordinates to find the answer.','A 45-degree diagonal from the origin implies x=y.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0250','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',1,'If you want to move HIGHER in the First Quadrant, which coordinate must get larger?','["Neither.","The y-coordinate.","The x-coordinate.","Both coordinates."]',1,'Review Position, Direction and Coordinates to find the answer.','y controls vertical height.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0251','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',5,'What Roman Numeral is used to identify the First Quadrant?','["I","II","IV","V"]',0,'Review Position, Direction and Coordinates to find the answer.','Quadrants are labeled I, II, III, IV.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0252','Maths','Position, Direction and Coordinates','Subtopic 9: First-Quadrant Coordinates','Primary',10,'How are the four quadrants numbered?','["Randomly.","Left to right, top to bottom.","Clockwise, starting from the upper-right.","Anticlockwise, starting from the upper-right (I, II, III, IV)."]',3,'Review Position, Direction and Coordinates to find the answer.','Mathematical convention numbers them counter-clockwise.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0253','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'What is a ''coordinate pattern''?','["A single dot on a page.","A random scattering of dots.","A picture of a dog.","A sequence of points on a grid that follow a specific, repeating mathematical rule."]',3,'Review Position, Direction and Coordinates to find the answer.','Patterns are rule-based sequences.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0254','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'What is the rule for this pattern: (2, 1), (5, 1), (8, 1)?','["Multiply by 2.","Increase the y-coordinate by 3.","Increase the x-coordinate by 3, keep y constant.","Add 3 to both coordinates."]',2,'Review Position, Direction and Coordinates to find the answer.','x changes by the step value, y stays 1.','2026-11-03 15:41:47',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0255','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A pattern follows the rule: y is always exactly double x (y = 2x). If the pattern starts at x=1, what are the first three points?','["(2, 1), (4, 2), (6, 3)","(1, 2), (2, 4), (3, 6)","(1, 1), (2, 2), (3, 3)","(1, 3), (2, 5), (3, 7)"]',1,'Review Position, Direction and Coordinates to find the answer.','If x=1, y=2. If x=2, y=4. If x=3, y=6.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0256','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'Look at this pattern: (1, 1), (2, 1), (3, 1). Which coordinate is changing?','["Neither coordinate.","The first coordinate (x-coordinate).","The second coordinate (y-coordinate).","Both coordinates."]',1,'Review Position, Direction and Coordinates to find the answer.','The x values are 1, 2, 3.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0257','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'What comes next in this vertical pattern? (5, 2), (5, 4), (5, 6), ...','["(5, 8)","(5, 10)","(10, 2)","(6, 6)"]',0,'Review Position, Direction and Coordinates to find the answer.','y increases by 2. Next is 6 + 2.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0258','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'You plot a pattern: (1, 10), (2, 8), (3, 6). If you continue this rule, at what x-coordinate will the y-coordinate hit exactly 0?','["x = 5","x = 6. (The pattern is (4,4), (5,2), (6,0)).","It will never hit zero.","x = 7"]',1,'Review Position, Direction and Coordinates to find the answer.','y decreases by 2 each time. 6->4->2->0. x increases by 1: 3->4->5->6.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0259','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'Look at this pattern: (2, 1), (2, 2), (2, 3). Which coordinate is changing?','["The second coordinate (y-coordinate).","Neither coordinate.","The first coordinate (x-coordinate).","Both coordinates."]',0,'Review Position, Direction and Coordinates to find the answer.','The y values are 1, 2, 3.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0260','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Look at this diagonal pattern: (1, 1), (2, 2), (3, 3)... What will the 4th point be?','["(1, 4)","(4, 4)","(4, 1)","(5, 5)"]',1,'Review Position, Direction and Coordinates to find the answer.','x and y both equal the step number.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0261','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A sequence of points is (1, 1), (1, 3), (3, 3), (3, 1), (1, 1). If you connect these dots in order on a grid, what do you draw?','["A circle.","A triangle.","A square.","A straight line."]',2,'Review Position, Direction and Coordinates to find the answer.','The points map the 4 corners of a 2x2 square and close the loop.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0262','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'If a pattern is (1, 5), (2, 5), (3, 5)... what direction are the dots moving on the grid?','["Horizontally to the right.","In a circle.","Diagonally.","Vertically upwards."]',0,'Review Position, Direction and Coordinates to find the answer.','x increases while y is constant = moving right.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0263','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Find the missing point: (2, 4), (4, 4), (___, 4), (8, 4).','["(8, 6)","(6, 4)","(6, 6)","(5, 4)"]',1,'Review Position, Direction and Coordinates to find the answer.','x increases by 2. 4 + 2 = 6.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0264','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'Spot the error: The rule is ''Increase x by 1, decrease y by 1''. The student writes: (5, 5), (6, 6), (7, 7).','["They INCREASED both. It should be (5, 5), (6, 4), (7, 3).","They started at the wrong number.","They should have subtracted 2.","There is no error."]',0,'Review Position, Direction and Coordinates to find the answer.','Decreasing y means the second number must go down.','2026-11-03 15:41:48',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0265','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'If a pattern is (4, 1), (4, 2), (4, 3)... what direction are the dots moving on the grid?','["Vertically upwards.","Downwards.","Horizontally to the right.","Diagonally."]',0,'Review Position, Direction and Coordinates to find the answer.','y increases while x is constant = moving up.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0266','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Spot the error: A student claims the pattern (1, 5), (2, 4), (3, 3) is a horizontal pattern.','["It is a vertical pattern.","The math is correct.","It is a circle.","It is actually a diagonal pattern because BOTH x and y coordinates are changing."]',3,'Review Position, Direction and Coordinates to find the answer.','Horizontal patterns only change x. Here, x goes up, y goes down.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0267','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A pattern starts at (0, 0). The rule alternates: Move 3 right, then Move 3 up. What is the 4th point?','["(6, 6)","(3, 0)","(3, 3)","(0, 3)"]',2,'Review Position, Direction and Coordinates to find the answer.','P1: (0,0). P2 (Right): (3,0). P3 (Up): (3,3). P4 (Right): (6,3). Wait, if 4th is right, it''s (2s, s). Let''s re-verify. P1(0,0). P2(3,0). P3(3,3). P4(6,3).','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0268','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'What comes next in this pattern? (1, 2), (2, 2), (3, 2), ...','["(4, 2)","(3, 3)","(4, 3)","(2, 4)"]',0,'Review Position, Direction and Coordinates to find the answer.','x is increasing by 1. 3+1 = 4.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0269','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'If a pattern starts at (0, 0) and the rule is ''add 2 to x, add 2 to y'', what is the 3rd point? (Hint: 1st point is (0,0))','["(0, 4)","(6, 6)","(2, 2)","(4, 4)"]',3,'Review Position, Direction and Coordinates to find the answer.','Point 1: (0,0). Point 2: (2,2). Point 3: (4,4).','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0270','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'If a coordinate pattern forms a perfectly straight diagonal line that does NOT pass through the origin (0,0), what must be true about its rule?','["It only uses negative numbers.","It involves adding/subtracting a constant offset, not just multiplying. (e.g. y = x + 2).","It must be a horizontal line.","It is impossible."]',1,'Review Position, Direction and Coordinates to find the answer.','Lines passing through origin are proportional (y=kx). Lines not passing through have an offset (y=kx+c).','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0271','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'What is a ''coordinate pattern''?','["A single dot on a page.","A sequence of points on a grid that follow a specific, repeating mathematical rule.","A picture of a dog.","A random scattering of dots."]',1,'Review Position, Direction and Coordinates to find the answer.','Patterns are rule-based sequences.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0272','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'What is the rule for this pattern: (1, 1), (3, 1), (5, 1)?','["Increase the y-coordinate by 2.","Add 2 to both coordinates.","Increase the x-coordinate by 2, keep y constant.","Multiply by 2."]',2,'Review Position, Direction and Coordinates to find the answer.','x changes by the step value, y stays 1.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0273','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A pattern follows the rule: y is always exactly double x (y = 2x). If the pattern starts at x=1, what are the first three points?','["(1, 3), (2, 5), (3, 7)","(1, 2), (2, 4), (3, 6)","(2, 1), (4, 2), (6, 3)","(1, 1), (2, 2), (3, 3)"]',1,'Review Position, Direction and Coordinates to find the answer.','If x=1, y=2. If x=2, y=4. If x=3, y=6.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0274','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'Look at this pattern: (1, 1), (2, 1), (3, 1). Which coordinate is changing?','["The first coordinate (x-coordinate).","The second coordinate (y-coordinate).","Both coordinates.","Neither coordinate."]',0,'Review Position, Direction and Coordinates to find the answer.','The x values are 1, 2, 3.','2026-11-03 15:41:49',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0275','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'What comes next in this vertical pattern? (5, 3), (5, 5), (5, 7), ...','["(10, 3)","(5, 11)","(6, 7)","(5, 9)"]',3,'Review Position, Direction and Coordinates to find the answer.','y increases by 2. Next is 7 + 2.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0276','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'You plot a pattern: (1, 10), (2, 8), (3, 6). If you continue this rule, at what x-coordinate will the y-coordinate hit exactly 0?','["x = 6. (The pattern is (4,4), (5,2), (6,0)).","x = 5","It will never hit zero.","x = 7"]',0,'Review Position, Direction and Coordinates to find the answer.','y decreases by 2 each time. 6->4->2->0. x increases by 1: 3->4->5->6.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0277','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'Look at this pattern: (2, 1), (2, 2), (2, 3). Which coordinate is changing?','["The second coordinate (y-coordinate).","The first coordinate (x-coordinate).","Both coordinates.","Neither coordinate."]',0,'Review Position, Direction and Coordinates to find the answer.','The y values are 1, 2, 3.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0278','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Look at this diagonal pattern: (1, 1), (2, 2), (3, 3)... What will the 4th point be?','["(1, 4)","(5, 5)","(4, 1)","(4, 4)"]',3,'Review Position, Direction and Coordinates to find the answer.','x and y both equal the step number.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0279','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A sequence of points is (1, 1), (1, 3), (3, 3), (3, 1), (1, 1). If you connect these dots in order on a grid, what do you draw?','["A square.","A triangle.","A straight line.","A circle."]',0,'Review Position, Direction and Coordinates to find the answer.','The points map the 4 corners of a 2x2 square and close the loop.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0280','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'If a pattern is (1, 5), (2, 5), (3, 5)... what direction are the dots moving on the grid?','["Vertically upwards.","Diagonally.","In a circle.","Horizontally to the right."]',3,'Review Position, Direction and Coordinates to find the answer.','x increases while y is constant = moving right.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0281','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Find the missing point: (2, 4), (4, 4), (___, 4), (8, 4).','["(6, 4)","(6, 6)","(8, 6)","(5, 4)"]',0,'Review Position, Direction and Coordinates to find the answer.','x increases by 2. 4 + 2 = 6.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0282','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'Spot the error: The rule is ''Increase x by 1, decrease y by 1''. The student writes: (5, 5), (6, 6), (7, 7).','["They started at the wrong number.","There is no error.","They INCREASED both. It should be (5, 5), (6, 4), (7, 3).","They should have subtracted 2."]',2,'Review Position, Direction and Coordinates to find the answer.','Decreasing y means the second number must go down.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0283','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'If a pattern is (4, 1), (4, 2), (4, 3)... what direction are the dots moving on the grid?','["Horizontally to the right.","Downwards.","Vertically upwards.","Diagonally."]',2,'Review Position, Direction and Coordinates to find the answer.','y increases while x is constant = moving up.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0284','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'Spot the error: A student claims the pattern (1, 5), (2, 4), (3, 3) is a horizontal pattern.','["The math is correct.","It is a circle.","It is actually a diagonal pattern because BOTH x and y coordinates are changing.","It is a vertical pattern."]',2,'Review Position, Direction and Coordinates to find the answer.','Horizontal patterns only change x. Here, x goes up, y goes down.','2026-11-03 15:41:50',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0285','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'A pattern starts at (0, 0). The rule alternates: Move 3 right, then Move 3 up. What is the 4th point?','["(0, 3)","(6, 6)","(3, 0)","(3, 3)"]',3,'Review Position, Direction and Coordinates to find the answer.','P1: (0,0). P2 (Right): (3,0). P3 (Up): (3,3). P4 (Right): (6,3). Wait, if 4th is right, it''s (2s, s). Let''s re-verify. P1(0,0). P2(3,0). P3(3,3). P4(6,3).','2026-11-03 15:41:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0286','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',1,'What comes next in this pattern? (1, 2), (2, 2), (3, 2), ...','["(3, 3)","(4, 2)","(2, 4)","(4, 3)"]',1,'Review Position, Direction and Coordinates to find the answer.','x is increasing by 1. 3+1 = 4.','2026-11-03 15:41:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0287','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',5,'If a pattern starts at (0, 0) and the rule is ''add 2 to x, add 2 to y'', what is the 3rd point? (Hint: 1st point is (0,0))','["(0, 4)","(4, 4)","(6, 6)","(2, 2)"]',1,'Review Position, Direction and Coordinates to find the answer.','Point 1: (0,0). Point 2: (2,2). Point 3: (4,4).','2026-11-03 15:41:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t14_global_0288','Maths','Position, Direction and Coordinates','Subtopic 10: Patterns on Coordinate Grids','Primary',10,'If a coordinate pattern forms a perfectly straight diagonal line that does NOT pass through the origin (0,0), what must be true about its rule?','["It only uses negative numbers.","It is impossible.","It involves adding/subtracting a constant offset, not just multiplying. (e.g. y = x + 2).","It must be a horizontal line."]',2,'Review Position, Direction and Coordinates to find the answer.','Lines passing through origin are proportional (y=kx). Lines not passing through have an offset (y=kx+c).','2026-11-03 15:41:51',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0001','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'What is a ''missing-number problem''?','["A completely blank page.","A pattern or calculation with one or more unknown numbers to find.","A game of hide and seek.","A number that was erased by mistake."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Missing number problems require finding an unknown value in a sequence or equation.','2026-11-03 16:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0002','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'What is the rule for this sequence? 2, 14, 28, 42','["Add 7.","Multiply the previous term by 7.","Multiply by 2.","Subtract 2."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Wait, 2 * 7 = 14. But 28 doesn''t follow a simple multiplication if it''s just *2. Let me fix the sequence: 2, 14, 98. Ah, the rule is multiply by 7.','2026-11-03 16:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0003','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'A sequence follows the rule ''Multiply by 2, then add 1''. If it starts at 2, what are the next two numbers?','["3, 6","5, 9","5, 11","4, 8"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','2*2+1 = 5. Then (5)*2+1 = 11.','2026-11-03 16:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0004','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'Find the missing number: 2, 10, 18, __','["10","26","19","34"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern adds 8. 18 + 8 = 26.','2026-11-03 16:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0005','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'Find the missing number: 1024, 128, 16, __','["0.25","32","2","0"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern divides by 8 each time.','2026-11-03 16:02:02',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0006','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'Find the missing number in the middle: 2, 10, __, 26, 34','["19","25","26","18"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern adds 8. 10 + 8 = 18.','2026-11-03 16:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0007','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'If a pattern goes 10, 8, 6, 4, what is the rule?','["Divide by 2.","Add 2 each time.","Multiply by 2.","Subtract 2 each time."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The numbers decrease by 2.','2026-11-03 16:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0008','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'Find the missing number in this equation: 50 - __ = 46','["8","54","4","50"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','50 - 4 = 46.','2026-11-03 16:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0009','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'Solve this double-blank equation: __ + __ = 8 (assuming both blanks are the SAME number)','["8","2","4","0"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','4 + 4 = 8.','2026-11-03 16:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0010','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'Find the missing number in the calculation: __ + 8 = 10','["2","8","-6","18"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Since 2 + 8 = 10, the answer is 2.','2026-11-03 16:02:03',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0011','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'Riley is trying to solve: 8 × __ = 16. What is the missing number?','["16","10","2","8"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','16 / 8 = 2.','2026-11-03 16:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0012','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'Spot the error: The sequence is 1, 4, 9, 16. Riley says the next number is 20 because 16+4=20.','["The sequence should be adding 5.","The next number is 24.","These are square numbers (1x1, 2x2, 3x3, 4x4). The next is 5x5 = 25.","There is no error."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The sequence represents squares, not a constant addition.','2026-11-03 16:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0013','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'What is the very first step you should take when solving a missing number sequence?','["Erase the blank.","Add the first and last number.","Look at the known numbers and find the rule.","Guess randomly."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Identifying the pattern rule is the key to solving the sequence.','2026-11-03 16:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0014','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'Spot the error: A student sees the sequence 2, 4, 8, 16. They say the rule is ''Add 2''.','["The sequence is broken.","The student is correct.","The rule is actually ''Multiply by 2''. (2+2=4, but 4+2 is not 8).","The rule is ''Add 4''."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Always check the rule against all numbers in the sequence.','2026-11-03 16:02:04',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0015','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'What is the missing number in this sequence of differences? The numbers are: 2, 3, 5, 8, 12, __','["15","14","17","16"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Differences are +1, +2, +3, +4. Next is +5. 12+5=17.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0016','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'Find the missing number: 6, 12, 18, __','["19","30","13","24"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern is multiples of 6.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0017','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'Complete the alternating pattern: 1, 10, 2, 9, 3, 8, __','["5","10","7","4"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Odd positions go 1, 2, 3, 4. Even positions go 10, 9, 8, 7.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0018','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'If a sequence starts at 100, and the rule is ''Subtract 6'', what is the 5th number in the sequence?','["94","82","70","76"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','1st=100. 2nd=100-6. 3rd=100-12. 4th=100-18. 5th=100-24.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0019','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',1,'What is a ''missing-number problem''?','["A number that was erased by mistake.","A game of hide and seek.","A completely blank page.","A pattern or calculation with one or more unknown numbers to find."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Missing number problems require finding an unknown value in a sequence or equation.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0020','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',5,'What is the rule for this sequence? 4, 24, 48, 72','["Subtract 4.","Add 6.","Multiply by 2.","Multiply the previous term by 6."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Wait, 4 * 6 = 24. But 48 doesn''t follow a simple multiplication if it''s just *2. Let me fix the sequence: 4, 24, 144. Ah, the rule is multiply by 6.','2026-11-03 16:02:05',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0021','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'A sequence follows the rule ''Multiply by 2, then add 1''. If it starts at 4, what are the next two numbers?','["8, 16","9, 17","5, 10","9, 19"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','4*2+1 = 9. Then (9)*2+1 = 19.','2026-11-03 16:02:06',NULL,NULL);
