INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0036','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 1: Finding Missing Numbers','Primary',10,'If a sequence starts at 100, and the rule is ''Subtract 6'', what is the 5th number in the sequence?','["76","94","70","82"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','1st=100. 2nd=100-6. 3rd=100-12. 4th=100-18. 5th=100-24.','2026-11-03 16:02:08',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0037','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'What is an ''odd-one-out'' problem?','["A puzzle about odd numbers only.","A game of tag.","A puzzle with no answer.","A puzzle where you find the one item that does not fit the rule shared by the others."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','You must find the item that breaks the group''s pattern/property.','2026-11-03 16:02:09',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0038','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Which number is the odd one out? 11, 13, 17, 20, 23','["13","11","23","20 (it is even, the rest are odd/prime)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','20 is the only even number.','2026-11-03 16:02:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0039','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Which is the odd one out? 2, 3, 5, 9, 11','["9 (it is not a prime number, it is divisible by 3).","2","11","3"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','2,3,5,11 are prime. 9 is composite (3x3).','2026-11-03 16:02:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0040','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'Which of these numbers is the odd one out? 2, 4, 6, 9','["4 (it is in the middle).","2 (it is too small).","9 (it is odd, the others are even).","6 (it is too big)."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','9 is the only odd number in the set of evens.','2026-11-03 16:02:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0041','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Which shape is the odd one out? Pentagon, Hexagon, Octagon, Square','["Octagon","Square (it has 4 sides, the rest have 5 or more).","Hexagon","Pentagon"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Square is a quadrilateral, others are larger polygons.','2026-11-03 16:02:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0042','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Look at these fractions: 1/2, 2/4, 3/6, 4/9, 5/10. Which is the odd one out?','["5/10","1/2","4/9 (it does not equal one half).","3/6"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','All others simplify to 1/2.','2026-11-03 16:02:10',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0043','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'Which of these shapes is the odd one out? Square, Rectangle, Circle, Triangle','["Square","Circle (it has no straight sides).","Rectangle","Triangle"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Circle is the only shape without straight sides/corners.','2026-11-03 16:02:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0044','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Jordan looks at the numbers 9, 16, 25, 30. Which is the odd one out?','["30 (it is not a square number like 3x3, 4x4, 5x5).","16","25","9"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','30 is not a perfect square.','2026-11-03 16:02:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0045','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Which shape is the odd one out? Equilateral Triangle, Square, Regular Pentagon, Scalene Triangle','["Scalene Triangle (it is irregular, the rest are regular polygons with equal sides/angles).","Regular Pentagon","Equilateral Triangle","Square"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Regular vs Irregular polygons is the rule.','2026-11-03 16:02:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0046','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'Which of these numbers is the odd one out? 5, 10, 15, 17, 20','["10","20","17 (it is not a multiple of 5).","5"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','All others are multiples of 5.','2026-11-03 16:02:11',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0047','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Which of these is the odd one out? 12, 14, 16, 21, 24','["12","14","21 (it is the only odd number).","24"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','21 breaks the even number pattern.','2026-11-03 16:02:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0048','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Consider the numbers: 27, 64, 125, 100. Which is the odd one out?','["100 (it is a square number, the others are cube numbers: 3³, 4³, 5³).","27","64","125"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','100 is 10², the rest are cubes.','2026-11-03 16:02:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0049','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'If the rule is ''things you wear on your feet'', which is the odd one out? Shoes, Socks, Boots, Hat','["Shoes","Socks","Boots","Hat"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','A hat is worn on the head.','2026-11-03 16:02:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0050','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Spot the error: A student says ''In the group Apple, Banana, Orange, Carrot, the odd one out is Apple because it is red.''','["Carrot is the odd one out because it is a vegetable, not a fruit. (Color is too specific and ignores the main category).","Banana is the odd one out because it is long.","Orange is the odd one out.","They are correct."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Finding the broadest categorical rule (fruit vs veg) is the primary goal.','2026-11-03 16:02:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0051','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Spot the error: The group is 10, 20, 30, 40, 45. A student says 10 is the odd one out because it''s the smallest.','["20 is the odd one.","30 is the odd one.","They are correct.","45 is the odd one out because it does not end in zero (it''s not a multiple of 10). Being the smallest isn''t a grouping rule."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Relative size (smallest/largest) is usually not the intended rule; look for mathematical properties (multiples).','2026-11-03 16:02:12',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0052','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',1,'What must you do to solve an odd-one-out problem?','["Guess randomly.","Pick the last item.","Pick the first item.","Find the shared rule or property that most items have, and spot the one that doesn''t fit."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','You must establish the rule before finding the exception.','2026-11-03 16:02:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0053','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',5,'Why might an odd-one-out puzzle have more than one correct answer?','["Because the teacher made a mistake.","Because different people might find different valid mathematical rules to group the items.","They never have more than one answer.","Because math is always wrong."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Multiple valid rules can create different ''odd ones out''.','2026-11-03 16:02:13',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0054','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 2: Odd-One-Out Problems','Primary',10,'Which of these angles is the odd one out? 45°, 89°, 60°, 95°','["45°","89°","60°","95° (it is obtuse, all the others are acute)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Acute (<90) vs Obtuse (>90) is the rule.','2026-11-03 16:02:13',NULL,NULL);
