INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0144','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 8: Trial-and-Error Problem-Solving','Primary',10,'A test has 10 questions. +5 points for correct, -2 points for wrong. A student answered all questions and got 29 points. How many did they get right?','["5 right, 5 wrong.","7 right, 3 wrong (7*5 = 35. 3*2 = 6. 35-6 = 29).","8 right, 2 wrong.","6 right, 4 wrong."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Trial: (10,0)=50. (9,1)=43. (8,2)=36. (7,3)=29.','2026-11-03 16:02:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0145','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'What makes a word problem ''multi-step''?','["You have to walk up steps to solve it.","It requires two or more different calculations to find the final answer.","It uses very big words.","It is written in multiple languages."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Multi-step requires sequential math operations.','2026-11-03 16:02:30',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0146','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A library has 23 books. It receives 17 new books and lends out 6 books. How many books remain?','["12","0","34","46"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','23 + 17 - 6 = 34.','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0147','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Morgan earns $17 an hour. They work for 4 hours, then spend half of all their money on a game. How much is left?','["$34","$34","$68","$63"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Earned = 17 * 4 = 68. Spent half, so 68 / 2 is left.','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0148','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'What is a good FIRST step when reading a multi-step word problem?','["Skip it.","Add all the numbers together.","Guess the answer immediately.","Identify what information is known and what you need to find out."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Comprehension of variables and goals is step 1.','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0149','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Rowan buys 3 notebooks costing 8 units each, and a pen for 5 units. What is the total cost?','["16","29","24","55"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(3 * 8) + 5 = 29.','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0150','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'A baker makes 34 cookies. They pack them into bags of 8. If they sell each bag for $5, how much money do they make?','["$4","$1360","$170","$20"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Bags = 34 / 8. Money = Bags * 5 (ignore remainder cookies).','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0151','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'If a problem asks you to find the ''total'' and then find ''what remains'', what operations will you likely use?','["Only Subtraction.","Addition, followed by Subtraction.","Division, followed by Multiplication.","Only Addition."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Total = add. Remains = subtract.','2026-11-03 16:02:31',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0152','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A cyclist wants to travel 117 km. They travel 39 km in the morning and 14 km in the afternoon. How many km remain?','["117","53","92","64"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','117 - (39 + 14) = 64.','2026-11-03 16:02:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0153','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Spot the error: ''A shirt is $20. It is on sale for half off. I bought 3 shirts and gave a $50 bill. 50 - 20/2 * 3 = 20.''','["There is no error.","They should have added 50.","They subtracted the $50 before finding the total cost of the shirts. It should be 50 - ( (20/2) * 3 ).","Order of operations/logic error. Half off is $10. 3 shirts = $30. Change = 50 - 30 = $20. Wait, the student got $20. Let''s fix the error: Student says 50 - 20 = 30 / 2 = 15 * 3 = 45."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Word problems require structuring the equation with proper parenthesis based on the narrative.','2026-11-03 16:02:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0154','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'Jamie has 47 apples, gets 13 more, and then eats 2. How many are left?','["36","60","45","58"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(47 + 13) - 2 = 58.','2026-11-03 16:02:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0155','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Spot the error: A student reads ''I had 10, got 5, lost 2'' and calculates 10 - 5 + 2 = 7.','["The math is correct.","They should have multiplied.","They forgot the 10.","They swapped the operations. It should be 10 + 5 - 2 = 13."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Got = add (+). Lost = subtract (-).','2026-11-03 16:02:32',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0156','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'A tank holds 470 Liters of water. It leaks at a rate of 7 Liters per hour. How many Liters remain after 5 hours?','["2315","435","465","463"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Leaked = 7 * 5. Remaining = 470 - 35.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0157','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'Why is calculating in the ''correct order'' important for multi-step problems?','["Because teachers like order.","So it looks neat on the page.","Doing the wrong step first will give you the wrong intermediate number, ruining the final answer.","It isn''t important."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Order of operations dictates the logical flow of the word problem.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0158','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A school arranges 8 tables with 4 students at each table. Then 5 more students arrive. How many students are there altogether?','["17","27","52","37"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(8 * 4) + 5 = 37.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0159','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Taylor buys 4 tickets for $15 each. They have a $10 discount coupon for the whole purchase. They pay with a $100 bill. How much change do they get?','["$50","$40","$50","$50"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Cost = (4 * 15) - 10. Change = 100 - Cost.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0160','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'If a problem involves ''sharing equally'', what math operation will you probably use?','["Division","Addition","Multiplication","Subtraction"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Sharing equally implies division.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0161','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Why should you write down ''intermediate results'' (the answer to step 1) in a multi-step problem?','["So you don''t forget the number before you start step 2, preventing silly mistakes.","Because it is the final answer.","You shouldn''t write them down.","To waste paper."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Tracking partial progress prevents cognitive overload and errors.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0162','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'If a problem says ''John has 3 times as many apples as Mary. Mary has 5 fewer apples than Steve. Steve has 12 apples.'' How do you solve this?','["It is impossible to solve.","Multiply 3, 5, and 12.","Work backwards from the known variable (Steve). Steve=12 -> Mary=7 -> John=21.","Add 3, 5, and 12 together."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Chained relative variables require working backwards from the absolute known.','2026-11-03 16:02:33',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0163','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'What makes a word problem ''multi-step''?','["It is written in multiple languages.","You have to walk up steps to solve it.","It uses very big words.","It requires two or more different calculations to find the final answer."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Multi-step requires sequential math operations.','2026-11-03 16:02:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0164','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A library has 21 books. It receives 14 new books and lends out 6 books. How many books remain?','["41","13","1","29"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','21 + 14 - 6 = 29.','2026-11-03 16:02:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0165','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Sam earns $14 an hour. They work for 4 hours, then spend half of all their money on a game. How much is left?','["$56","$51","$28","$28"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Earned = 14 * 4 = 56. Spent half, so 56 / 2 is left.','2026-11-03 16:02:34',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0166','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'What is a good FIRST step when reading a multi-step word problem?','["Add all the numbers together.","Skip it.","Guess the answer immediately.","Identify what information is known and what you need to find out."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Comprehension of variables and goals is step 1.','2026-11-03 16:02:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0167','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Quinn buys 3 notebooks costing 9 units each, and a pen for 5 units. What is the total cost?','["32","60","17","27"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(3 * 9) + 5 = 32.','2026-11-03 16:02:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0168','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'A baker makes 29 cookies. They pack them into bags of 9. If they sell each bag for $5, how much money do they make?','["$145","$15","$3","$1305"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Bags = 29 / 9. Money = Bags * 5 (ignore remainder cookies).','2026-11-03 16:02:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0169','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'If a problem asks you to find the ''total'' and then find ''what remains'', what operations will you likely use?','["Only Addition.","Only Subtraction.","Division, followed by Multiplication.","Addition, followed by Subtraction."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Total = add. Remains = subtract.','2026-11-03 16:02:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0170','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A cyclist wants to travel 105 km. They travel 35 km in the morning and 16 km in the afternoon. How many km remain?','["105","54","86","51"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','105 - (35 + 16) = 54.','2026-11-03 16:02:35',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0171','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Spot the error: ''A shirt is $20. It is on sale for half off. I bought 3 shirts and gave a $50 bill. 50 - 20/2 * 3 = 20.''','["They subtracted the $50 before finding the total cost of the shirts. It should be 50 - ( (20/2) * 3 ).","They should have added 50.","Order of operations/logic error. Half off is $10. 3 shirts = $30. Change = 50 - 30 = $20. Wait, the student got $20. Let''s fix the error: Student says 50 - 20 = 30 / 2 = 15 * 3 = 45.","There is no error."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Word problems require structuring the equation with proper parenthesis based on the narrative.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0172','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'Casey has 22 apples, gets 14 more, and then eats 2. How many are left?','["10","20","34","36"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(22 + 14) - 2 = 34.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0173','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Spot the error: A student reads ''I had 10, got 5, lost 2'' and calculates 10 - 5 + 2 = 7.','["The math is correct.","They should have multiplied.","They forgot the 10.","They swapped the operations. It should be 10 + 5 - 2 = 13."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Got = add (+). Lost = subtract (-).','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0174','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'A tank holds 220 Liters of water. It leaks at a rate of 6 Liters per hour. How many Liters remain after 5 hours?','["214","1070","215","190"]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Leaked = 6 * 5. Remaining = 220 - 30.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0175','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'Why is calculating in the ''correct order'' important for multi-step problems?','["So it looks neat on the page.","Because teachers like order.","It isn''t important.","Doing the wrong step first will give you the wrong intermediate number, ruining the final answer."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Order of operations dictates the logical flow of the word problem.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0176','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'A school arranges 4 tables with 4 students at each table. Then 5 more students arrive. How many students are there altogether?','["11","21","36","13"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','(4 * 4) + 5 = 21.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0177','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'Sam buys 4 tickets for $17 each. They have a $10 discount coupon for the whole purchase. They pay with a $100 bill. How much change do they get?','["$42","$42","$32","$58"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Cost = (4 * 17) - 10. Change = 100 - Cost.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0178','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',1,'If a problem involves ''sharing equally'', what math operation will you probably use?','["Subtraction","Addition","Division","Multiplication"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Sharing equally implies division.','2026-11-03 16:02:36',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0179','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',5,'Why should you write down ''intermediate results'' (the answer to step 1) in a multi-step problem?','["So you don''t forget the number before you start step 2, preventing silly mistakes.","To waste paper.","You shouldn''t write them down.","Because it is the final answer."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Tracking partial progress prevents cognitive overload and errors.','2026-11-03 16:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0180','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 9: Multi-Step Word Problems','Primary',10,'If a problem says ''John has 3 times as many apples as Mary. Mary has 5 fewer apples than Steve. Steve has 12 apples.'' How do you solve this?','["Add 3, 5, and 12 together.","Multiply 3, 5, and 12.","It is impossible to solve.","Work backwards from the known variable (Steve). Steve=12 -> Mary=7 -> John=21."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Chained relative variables require working backwards from the absolute known.','2026-11-03 16:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0181','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'What does ''mathematical reasoning'' mean?','["Guessing the answer.","Using facts, patterns, rules, and logical steps to reach a conclusion.","Using a calculator for everything.","Drawing a picture of math."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Reasoning is the logical application of math rules.','2026-11-03 16:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0182','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'A secret number is greater than 20, less than 30, and is a multiple of 5. What could it be?','["It is 30.","Check multiples of 5 (e.g., 10, 15...) and find the one(s) between 20 and 30.","It must be 25.","It is 20."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','You must cross-reference the range with the multiple rule.','2026-11-03 16:02:37',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0183','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'A lock has a 3-digit code. The digits add up to 6. The first digit is twice the second digit. The third digit is 0. What is the code?','["600","420","210","330"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Third is 0. First + Second = 6. First = 2 * Second. 4 + 2 = 6.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0184','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'If all multiples of 10 end in zero, and 50 is a multiple of 10, what can you logically conclude?','["50 is a prime number.","50 ends in 5.","10 is a multiple of 50.","50 ends in zero."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','This is a basic deductive reasoning syllogism.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0185','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Spot the error: ''A number is even and ends in 5.''','["The number is 15.","The number is 25.","Even numbers must end in 0, 2, 4, 6, or 8. It cannot end in 5. The clues contradict each other.","The math is correct."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The constraints are logically impossible to satisfy simultaneously.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0186','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'You need exactly 5 coins worth 8 units total. Available coins are 1-unit and 2-unit. How many of each?','["Three 2-unit coins and two 1-unit coins (3*2 + 2*1 = 8, and 3+2=5 coins).","Five 1-unit coins.","Four 1-unit and two 2-unit.","Four 2-unit coins."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','System of equations logic. (3x2) + (2x1) = 8. Count = 5.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0187','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'Find the pattern: 2, 4, 6, 8, __','["12","10","9","0"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern adds 2.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0188','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'If Sam has 3 coins that total exactly 12 units, and the only coins available are 1, 2, 5, and 10 units, what are the coins?','["One 10-unit and one 2-unit.","Three 4-units.","Two 5-units and one 2-unit.","One 10-unit and two 1-unit coins (10+1+1=12)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','10 + 1 + 1 = 12, using exactly 3 coins.','2026-11-03 16:02:38',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0189','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'Spot the error in this logic: ''All birds lay eggs. A turtle lays eggs. Therefore, a turtle is a bird.''','["The logic is flawed. Just because turtles share one trait (laying eggs) with birds doesn''t mean they are birds.","Turtles don''t lay eggs.","Birds don''t lay eggs.","The logic is perfect."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Affirming the consequent is a logical fallacy.','2026-11-03 16:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0190','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'Jordan is taller than Leo. Leo is taller than Sam. Who is the shortest?','["Jordan","Cannot be determined","Sam","Leo"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Transitive property of inequalities.','2026-11-03 16:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0191','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Why is ''trying a simpler example'' a good strategy for difficult problems?','["It means you can skip the hard problem.","It gives you the exact answer.","A smaller example with easier numbers can help you discover the hidden rule or pattern needed for the hard problem.","It wastes time."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Simplifying reduces cognitive load to reveal mechanics.','2026-11-03 16:02:39',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0192','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'I am a 2-digit number. I am a square number. The sum of my digits is 13. Who am I?','["49 (7x7=49, 4+9=13).","36","64","25"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Squares: 16, 25, 36, 49, 64, 81. Sums: 7, 7, 9, 13, 10, 9. 49 fits.','2026-11-03 16:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0193','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'If a problem gives you a list of ''clues'' about a secret number, what should you do?','["Add the clues together.","Only use the first clue.","Ignore the clues and guess.","Test numbers to see if they satisfy ALL the clues."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','All constraints must be met to find the solution.','2026-11-03 16:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0194','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'A number is multiplied by 3, then 5 is added to get 26. What was the number?','["8","6","7","21"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Work backwards: (26 - 5) / 3 = 7.','2026-11-03 16:02:40',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0195','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'If Skyler can paint a fence in 2 hours, and Sam can paint it in 2 hours, how long will it take if they work together?','["2 hours","45 minutes","4 hours","1 hour (They work twice as fast together)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Combined rate = 1/2 + 1/2 = 1 fence per hour.','2026-11-03 16:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0196','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'What is a ''constraint'' in a math problem?','["A type of fraction.","A mistake in the math.","A specific rule or condition that your final answer MUST follow (like ''the number must be even'').","A geometric shape."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Constraints limit the possible valid solutions.','2026-11-03 16:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0197','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Can a mathematical reasoning problem have MORE THAN ONE correct answer?','["No, that means the problem is broken.","Yes, but only if you guess.","No, math problems only ever have one answer.","Yes, if the clues given do not narrow it down to a single unique solution."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Under-constrained problems yield multiple valid solutions.','2026-11-03 16:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0198','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'A farmer has 10 sheep. All but 9 run away. How many are left?','["10","1","9. (''All but 9'' means 9 did NOT run away).","0"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','This tests careful reading comprehension and logical syntax parsing.','2026-11-03 16:02:41',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0199','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'What does ''mathematical reasoning'' mean?','["Drawing a picture of math.","Using a calculator for everything.","Using facts, patterns, rules, and logical steps to reach a conclusion.","Guessing the answer."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Reasoning is the logical application of math rules.','2026-11-03 16:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0200','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'A secret number is greater than 20, less than 30, and is a multiple of 3. What could it be?','["Check multiples of 3 (e.g., 6, 9...) and find the one(s) between 20 and 30.","It is 30.","It must be 25.","It is 20."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','You must cross-reference the range with the multiple rule.','2026-11-03 16:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0201','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'A lock has a 3-digit code. The digits add up to 6. The first digit is twice the second digit. The third digit is 0. What is the code?','["420","210","330","600"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Third is 0. First + Second = 6. First = 2 * Second. 4 + 2 = 6.','2026-11-03 16:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0202','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'If all multiples of 10 end in zero, and 50 is a multiple of 10, what can you logically conclude?','["10 is a multiple of 50.","50 ends in zero.","50 ends in 5.","50 is a prime number."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','This is a basic deductive reasoning syllogism.','2026-11-03 16:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0203','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Spot the error: ''A number is even and ends in 5.''','["Even numbers must end in 0, 2, 4, 6, or 8. It cannot end in 5. The clues contradict each other.","The number is 15.","The number is 25.","The math is correct."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The constraints are logically impossible to satisfy simultaneously.','2026-11-03 16:02:42',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0204','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'You need exactly 5 coins worth 8 units total. Available coins are 1-unit and 2-unit. How many of each?','["Four 2-unit coins.","Four 1-unit and two 2-unit.","Five 1-unit coins.","Three 2-unit coins and two 1-unit coins (3*2 + 2*1 = 8, and 3+2=5 coins)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','System of equations logic. (3x2) + (2x1) = 8. Count = 5.','2026-11-03 16:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0205','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'Find the pattern: 2, 4, 6, 8, __','["0","12","10","9"]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','The pattern adds 2.','2026-11-03 16:02:43',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0206','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'If Skyler has 3 coins that total exactly 12 units, and the only coins available are 1, 2, 5, and 10 units, what are the coins?','["Three 4-units.","One 10-unit and two 1-unit coins (10+1+1=12).","Two 5-units and one 2-unit.","One 10-unit and one 2-unit."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','10 + 1 + 1 = 12, using exactly 3 coins.','2026-11-03 16:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0207','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'Spot the error in this logic: ''All birds lay eggs. A turtle lays eggs. Therefore, a turtle is a bird.''','["Turtles don''t lay eggs.","Birds don''t lay eggs.","The logic is flawed. Just because turtles share one trait (laying eggs) with birds doesn''t mean they are birds.","The logic is perfect."]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Affirming the consequent is a logical fallacy.','2026-11-03 16:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0208','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'Quinn is taller than Leo. Leo is taller than Sam. Who is the shortest?','["Cannot be determined","Sam","Leo","Quinn"]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Transitive property of inequalities.','2026-11-03 16:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0209','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Why is ''trying a simpler example'' a good strategy for difficult problems?','["It gives you the exact answer.","A smaller example with easier numbers can help you discover the hidden rule or pattern needed for the hard problem.","It wastes time.","It means you can skip the hard problem."]',1,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Simplifying reduces cognitive load to reveal mechanics.','2026-11-03 16:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0210','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'I am a 2-digit number. I am a square number. The sum of my digits is 13. Who am I?','["36","25","64","49 (7x7=49, 4+9=13)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Squares: 16, 25, 36, 49, 64, 81. Sums: 7, 7, 9, 13, 10, 9. 49 fits.','2026-11-03 16:02:44',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0211','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'If a problem gives you a list of ''clues'' about a secret number, what should you do?','["Ignore the clues and guess.","Only use the first clue.","Add the clues together.","Test numbers to see if they satisfy ALL the clues."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','All constraints must be met to find the solution.','2026-11-03 16:02:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0212','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'A number is multiplied by 3, then 5 is added to get 26. What was the number?','["21","8","7","6"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Work backwards: (26 - 5) / 3 = 7.','2026-11-03 16:02:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0213','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'If Morgan can paint a fence in 2 hours, and Sam can paint it in 2 hours, how long will it take if they work together?','["45 minutes","4 hours","1 hour (They work twice as fast together).","2 hours"]',2,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Combined rate = 1/2 + 1/2 = 1 fence per hour.','2026-11-03 16:02:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0214','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',1,'What is a ''constraint'' in a math problem?','["A mistake in the math.","A type of fraction.","A geometric shape.","A specific rule or condition that your final answer MUST follow (like ''the number must be even'')."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Constraints limit the possible valid solutions.','2026-11-03 16:02:45',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0215','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',5,'Can a mathematical reasoning problem have MORE THAN ONE correct answer?','["Yes, if the clues given do not narrow it down to a single unique solution.","Yes, but only if you guess.","No, that means the problem is broken.","No, math problems only ever have one answer."]',0,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','Under-constrained problems yield multiple valid solutions.','2026-11-03 16:02:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('math_t15_global_0216','Maths','Logical Reasoning and Mathematical Problem-Solving','Subtopic 11: Mathematical Reasoning Challenges','Primary',10,'A farmer has 10 sheep. All but 9 run away. How many are left?','["10","0","1","9. (''All but 9'' means 9 did NOT run away)."]',3,'Review Logical Reasoning and Mathematical Problem-Solving to find the answer.','This tests careful reading comprehension and logical syntax parsing.','2026-11-03 16:02:46',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('test_primary_math_addition_d1_9001','Maths','Addition','Adding two-digit numbers','Primary',1,'What is 24 + 15?','["39","38","40","41"]',0,'Add the tens first, then the ones.','24 + 15 = 24 + 10 + 5 = 39.','2026-11-04 16:00:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('test_primary_math_addition_d1_9002','Maths','Addition','Adding two-digit numbers','Primary',1,'What is 32 + 16?','["46","48","49","47"]',1,'Add 30 + 10 and 2 + 6.','32 + 16 = 48.','2026-11-04 16:00:26',NULL,NULL);
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hs_math_t01_st01_d1_9001','math','Number Systems and Real Numbers','Natural numbers, integers and rational numbers','hs',1,'Which of the following is an integer?','["3/4","-5","√2","π"]',1,'Integers do not include fractions or irrational numbers.','-5 is an integer because integers include negative whole numbers, zero and positive whole numbers.','2026-11-04 16:01:38','hs_math_t01','hs_math_t01_st01');
INSERT INTO "questions" ("id","subject","category","topic","level","difficulty","question","options","correct","hint","explanation","created_at","topic_id","subtopic_id") VALUES('hs_math_t01_st01_d1_9002','math','Number Systems and Real Numbers','Natural numbers, integers and rational numbers','hs',1,'Which number is rational?','["√3","π","0.75","√5"]',2,'A terminating decimal can be written as a fraction.','0.75 = 3/4, so it can be expressed as a ratio of two integers.','2026-11-04 16:01:38','hs_math_t01','hs_math_t01_st01');
